QuestTraduttoreData = QuestTraduttoreData or {}
QuestTraduttoreGossip = QuestTraduttoreGossip or {}
local T, G = QuestTraduttoreData, QuestTraduttoreGossip

T[2] = {
  title = "Sharptalon's Claw",
  desc = "Il possente ippogrifo Sharptalon è stato ucciso, e l'artiglio della bestia abbattuta è la testimonianza della tua vittoria. Senani Thunderheart, a Splintertree Post, sarà senza dubbio interessata a vedere questo trofeo come prova delle tue imprese.",
  obj = "Porta Sharptalon's Claw a Senani Thunderheart a Splintertree Post, in Ashenvale.",
  progress = "Sì, possente $C, ho percepito il tuo arrivo. Immagino che tu abbia altre notizie da riferirmi sulla tua caccia?",
  reward = "Davvero notevole, $N... l'artiglio di Sharptalon non dev'essere stato facile da ottenere! La caccia di Ashenvale procede bene per te!$B$BSharptalon terrorizzava da tempo i peon dei campi di legname lungo il suo cammino, mentre cercavano di arrivare fin qui a Splintertree Post. Non appena si saprà che sei $Gstato:stata; tu ad abbattere la bestia, di sicuro si leveranno molti canti al tuo coraggio attorno ai fuochi e nelle segherie di tutta Ashenvale!",
  en_title = "Sharptalon's Claw",
  en_obj = "Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[5] = {
  title = "Il brontolio di Jitters",
  desc = "Sono bloccato in questa città fantasma da settimane e non mangio altro che larve ed erbacce!  Mi serve del cibo decente, e sono disposto a pagare bene.$B$BPortami un banchetto e ti ricompenserò generosamente.$B$BHo sentito che Chef Grual, alla Scarlet Raven Tavern di Darkshire, prepara degli ottimi Dusky Crab Cakes...",
  obj = "Parla con Chef Grual.",
  reward = "Ti servono dei Crab Cakes, eh? Beh, forse posso cucinartene qualcuno...",
  en_title = "Jitters' Growling Gut",
  en_obj = "Speak with Chef Grual.",
}
T[6] = {
  title = "Taglia su Garrick Padfoot",
  desc = "Garrick Padfoot, un tagliagole che da settimane tormenta i nostri contadini e mercanti, è stato avvistato in una baracca vicino ai vigneti, a est dell'Abbazia, oltre il ponte.  Portami la testa di quel furfante e riscuoterai la sua taglia!$B$BMa sta in guardia, $N.  Garrick si è circondato di una banda di furfanti.  Non sarà facile raggiungerlo.",
  obj = "Uccidi Garrick Padfoot e porta la sua testa a Deputy Willem all'Abbazia di Northshire.",
  progress = "Hai trovato la baracca di Garrick? Siamo finalmente liberi da quel furfante?",
  reward = "Ah! Lo hai preso! Hai reso un grande servizio a Elwynn e ti sei guadagnat$Go:a; una bella taglia!",
  en_title = "Bounty on Garrick Padfoot",
  en_obj = "Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.",
}
T[7] = {
  title = "Pulizia dell'accampamento dei coboldi",
  desc = "Il tuo primo compito è una purificazione, $N.  Un clan di coboldi ha infestato i boschi a nord.  Recati là e combatti i parassiti coboldi che troverai.  Riduci il loro numero, così che un giorno possiamo scacciarli da Northshire.",
  obj = "Uccidi 10 Kobold Vermin, poi torna da Marshal McBride.",
  progress = "Come procede la caccia, $N? Hai trovato e sconfitto quei parassiti?",
  reward = "Ben fatto, cittadino. Quei coboldi sono ladri e codardi, ma in gran numero rappresentano una minaccia per noi. E gli umani di Stormwind non hanno bisogno di un'altra minaccia.$B$BPer averli sconfitti, hai la mia gratitudine.",
  en_title = "Kobold Camp Cleanup",
  en_obj = "Kill 10 Kobold Vermin, then return to Marshal McBride.",
}
T[8] = {
  title = "L'affare di un furfante",
  desc = "Ehi, amico! Fai un favore a un giovanotto che ha combattuto più del dovuto contro zombi e ragni senza cervello?$B$BHo questa lettera che deve arrivare a Brill... a una locandiera di nome Renee qualcosa. Non importa un accidente quale sia il suo cognome.$B$BInsomma, è un posticino accogliente, pieno di vittime della piaga che cercano di farsi strada nel mondo. E sarebbe un ottimo posto anche per riposarti, se ne avrai bisogno. Dagli un'occhiata... fallo e ti pagherò bene.",
  obj = "Consegna la Nondescript Letter a Innkeeper Renee a Tirisfal Glades.",
  progress = "Sì? Sì? Che c'è?$B$BI Reietti... che appetito enorme hanno! Fa' come se fossi a casa tua... sì, riposa quelle stanche ossa. Mi chiamo Renee, se ti serve qualsiasi cosa.",
  reward = "Oh? Una lettera? Splendide notizie! Aspettavo notizie dalla mia cara vecchia madre a Deathknell. Una santa donna, lei. Chissà come se la passa.$B$BCosa? Troppo allegra? Non ci credi, vero?$B$BBene, allora sparisci... non sono affari tuoi da chi sia la lettera, comunque. Via! Sparisci!$B$BTorna quando avrai qualche moneta da spendere... fannullone.$B$BE un giorno o l'altro tornerai a riposarti dopo una lunga giornata d'avventura o qualche altra sciocchezza simile.",
  en_title = "A Rogue's Deal",
  en_obj = "Deliver the Nondescript Letter to Innkeeper Renee in Tirisfal Glades.",
}
T[9] = {
  title = "I campi della morte",
  desc = "Guarda cos'è successo a questo posto!  Queste terre un tempo erano abitate da brava gente di campagna.  Ma quei maledetti ladri li hanno cacciati tutti.  Me no, però!  Ma pare che alcuni Harvest Watcher si siano impossessati dei campi.$B$BSe te la senti, vorrei che tu ne uccidessi venti.  Torna quando hai finito per ricevere la tua paga.  Se finisci con quelli nel mio campo, ripulisci anche i campi vicini.",
  obj = "Farmer Saldean vuole che tu uccida 20 Harvest Watcher.",
  progress = "Ah, vedo che sei tornat$Go:a;! Spero tu abbia lavorato sodo per ripulire quei campi dagli Harvest Watcher. Ne hai uccisi venti?",
  reward = "Bel lavoro, amic$Go:a;. Ti sei guadagnat$Go:a; la paga. Chissà, forse Westfall tornerà a prosperare.",
  en_title = "The Killing Fields",
  en_obj = "Farmer Saldean wants you to kill 20 Harvest Watchers.",
}
T[11] = {
  title = "Taglia sui Riverpaw Gnoll",
  desc = "Gli gnoll, creature brutali che non hanno niente da fare in queste terre, sono stati avvistati lungo i confini di Elwynn Forest.  Un grosso branco, molti più di quanti possiamo affrontare da soli, ha infestato i boschi a sud della torre di guardia laggiù.  Un altro gruppo ha infestato le zone vicino a Stone Cairn Lake, a est.$B$BLo Stormwind Army elogerà chiunque aiuti a ucciderli.  Portami le loro fasce da braccio dipinte come prova della tua impresa.",
  obj = "Porta 8 Painted Gnoll Armband a Deputy Rainer alla Caserma.",
  progress = "Salute, $N. Hai ucciso degli Gnoll...?",
  reward = "Vedo che sei stat$Go:a; occupat$Go:a;! Hai i nostri ringraziamenti, $N.",
  en_title = "Riverpaw Gnoll Bounty",
  en_obj = "Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks.",
}
T[12] = {
  title = "La Milizia del Popolo",
  desc = "La People's Militia ha un solo scopo:  difendere le terre di Westfall e riportare la pace nei nostri dintorni.  Purtroppo, il prezzo della pace è spesso il sangue.$B$BUno dei miei esploratori mi ha riferito di una banda di Defias Trapper che semina il caos nei paraggi.  Ho notizie di avvistamenti di Defias Trapper vicino alla Jangolode Mine a nordovest, così come alla Molsen Farm e alla Furlbrow's Pumpkin Farm. Se desideri unirti ai nostri ranghi, uccidi 15 Defias Trapper e 15 Defias Smuggler, poi torna da me.",
  obj = "Gryan Stoutmantle vuole che tu uccida 15 Defias Trapper e 15 Defias Smuggler, poi torni da lui a Sentinel Hill.",
  progress = "Forse non mi sono spiegato bene, recluta. Per dimostrare il tuo valore come servitore della People's Militia e della Luce devi uccidere 15 Defias Trapper e 15 Defias Smuggler, poi tornare da me a impresa compiuta.",
  reward = "Ben fatto, $N. Il mio esploratore ha visto le tue gesta valorose. Finora ti stai dimostrando davvero all'altezza.",
  en_title = "The People's Militia",
  en_obj = "Gryan Stoutmantle wants you to kill 15 Defias Trappers and 15 Defias Smugglers then return to him on Sentinel Hill.",
}
T[13] = {
  title = "La Milizia del Popolo",
  desc = "Una banda di spietati Defias Pillager è stata vista saccheggiare la Gold Coast Quarry, Moonbrook e la Alexston Farmstead.  La People's Militia non tollererà simili comportamenti.  Parti subito, $N, e fa' sentire la presenza della Luce a Westfall.$B$BLa Gold Coast Quarry si trova vicino alla costa, a ovest della torre.  Come prossimo passo del tuo addestramento, voglio che tu uccida 15 di quei luridi Defias Pillager e 15 Defias Looter.",
  obj = "Gryan Stoutmantle vuole che tu uccida 15 Defias Pillager e 15 Defias Looter e torni da lui a Sentinel Hill.",
  progress = "Non c'è tempo per chiacchierare, $N. I Defias Pillager stanno negando alla gente di Westfall la pace e la prosperità che merita. Assicurati che almeno 15 Defias Pillager e 15 Defias Looter siano stati uccisi. Sarà un chiaro messaggio che la corruzione non è la benvenuta qui.",
  reward = "Il tuo valore per la People's Militia è stato confermato dalle tue azioni coraggiose finora.",
  en_title = "The People's Militia",
  en_obj = "Gryan Stoutmantle wants you to kill 15 Defias Pillagers and 15 Defias Looters and return to him on Sentinel Hill.",
}
T[14] = {
  title = "La Milizia del Popolo",
  desc = "Alcuni Defias ci sono sfuggiti.  Il mio esploratore più fidato riferisce che questi Defias hanno saccheggiato e razziato la campagna, fino a Southern Westfall.  Crediamo che si nascondano nelle Dagger Hills, a tramare la prossima mossa.   Stermina quei miserabili in nome della People's Militia.",
  obj = "Gryan Stoutmantle vuole che tu uccida 15 Defias Highwayman, 5 Defias Pathstalker e 5 Defias Knuckleduster, poi torni da lui a Sentinel Hill.",
  progress = "$N, non è il momento per le chiacchiere. Se vuoi ancora dimostrare il tuo valore alla People's Militia, devi eliminare i Defias di cui ti ho parlato prima. Torna da me quando avrai compiuto il tuo dovere.",
  reward = "Quando ho lasciato le terre contaminate di Lordaeron, sono tornato a una situazione cupa qui nella mia patria. Ma c'è ancora speranza per Westfall. Come dimostrato dal tuo valore in battaglia, è evidente che servi la nostra causa con onore. È con grande orgoglio che ti accolgo nella People's Militia. Che la Luce risplenda su di te.",
  en_title = "The People's Militia",
  en_obj = "Gryan Stoutmantle wants you to kill 15 Defias Highwaymen, 5 Defias Pathstalkers and 5 Defias Knuckledusters then return to him on Sentinel Hill.",
}
T[15] = {
  title = "Indagine a Echo Ridge",
  desc = "$N, i miei esploratori dicono che l'infestazione di kobold è più estesa di quanto pensassimo.  Un gruppo di kobold lavoratori si è accampato vicino alla Echo Ridge Mine, a nord.$B$BVai alla miniera e eliminali.  Sappiamo che ce ne sono almeno 10.  Uccidili, controlla se ce ne sono altri, poi torna a riferirmi.",
  obj = "Uccidi 10 Kobold Worker, poi torna a riferire a Marshal McBride.",
  progress = "Sei stat$Go:a; alle miniere? Sei pront$Go:a; a riferire?",
  reward = "Non mi piace sentire di tutti questi kobold nella nostra miniera. Non ne verrà nulla di buono. Tieni, prendi questo come pagamento, e quando sei pront$Go:a;, parlami di nuovo. Vorrei che tornassi alle miniere ancora una volta...",
  en_title = "Investigate Echo Ridge",
  en_obj = "Kill 10 Kobold Workers, then report back to Marshal McBride.",
}
T[16] = {
  title = "Un goccio per Gerard",
  progress = "Lavorare i campi mette sete, e cerco sempre acqua di sorgente fresca.$B$BSe ne hai, sono disposto a fare uno scambio.",
  reward = "Grazie, $N! E torna se vuoi fare un altro scambio.",
  en_title = "Give Gerard a Drink",
}
T[17] = {
  title = "Reagenti da Uldaman",
  desc = "Ho sentito parlare di una pianta scoperta da poco, i Magenta Fungus Cap. Crescono a grappoli, nel profondo del sito di scavo di Uldaman; forse si trovano anche altrove, ma per ora è l'unico posto che conosco. Voglio studiarne il possibile uso in alchimia, ed è qui che entri in gioco tu.$B$BTrova i Magenta Cap Clusters e portami una dozzina di cappelli. Sta' $Gattento:attenta;: se li urti, i grappoli potrebbero sputare spore velenose.$B$BFallo per me, e ti preparerò una partita di uno dei miei famosi elisir ristoratori!",
  obj = "Porta 12 Magenta Fungus Cap a Ghak Healtouch, a Thelsamar.",
  progress = "Ti sei $Gprocurato:procurata; i Magenta Fungus Cap che mi servono per il mio lavoro alchemico? Niente cappelli, niente ricompensa!",
  reward = "Ben fatto, $N: hai dimostrato ancora una volta quanto vali! I cappelli saranno uno studio interessante, puoi giurarci!$B$BE ora, come promesso, gusta un assaggio di uno dei miei intrugli ristoratori più potenti, dalla mia scorta personale...$B$BSe sei $Gun alchimista esperto:un'alchimista esperta;, forse potremmo fare altri affari. In ogni caso, ti ringrazio per il tuo aiuto!",
  en_title = "Uldaman Reagent Run",
  en_obj = "Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar.",
}
T[18] = {
  title = "Fratellanza di ladri",
  desc = "Di recente un nuovo gruppo di ladri si aggira per Northshire.  Si fanno chiamare Defias Brotherhood, e sono stati visti oltre il fiume, a est.$B$BNon so cosa stiano tramando, ma di sicuro nulla di buono!  Portami le bandane che indossano e ti ricompenserò con un'arma.",
  obj = "Porta 12 Red Burlap Bandana a Deputy Willem fuori dalla Northshire Abbey.",
  progress = "Hai già raccolto quelle bandane per me?",
  reward = "Sei tornat$Go:a; con delle bandane, vedo. Lo Stormwind Army apprezza il tuo aiuto.",
  en_title = "Brotherhood of Thieves",
  en_obj = "Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.",
}
T[19] = {
  title = "Tharil'zun",
  desc = "I Blackrock Outrunner e i Blackrock Renegade tendono imboscate tra qui e lo Stonewatch Keep. Il capo degli Outrunner è un orco di nome Tharil'zun: quell'orco lo vogliamo. Portami la testa di Tharil'zun!",
  obj = "Porta Tharil'zun's Head a Marshal Marris, a Redridge.",
  progress = "La pressione degli orchi di Blackrock è sempre alta. Ma almeno ci hai liberati di Tharil'zun?",
  reward = "Tharil'zun era un orco feroce e astuto. Ben fatto — di sicuro non è caduto facilmente. Ecco la tua ricompensa, $N.",
  en_title = "Tharil'zun",
  en_obj = "Bring Tharil'zun's Head to Marshal Marris in Redridge.",
}
T[20] = {
  title = "La minaccia Blackrock",
  desc = "Gli orchi Blackrock sono arrivati dalle Burning Steppes e hanno occupato lo Stonewatch Keep, a nord. Da lì saccheggiano le zone a nord di Lakeshire e costringono i cittadini a restare in paese, chiusi come bestie in un recinto.$B$BAiutaci a liberare Lakeshire da questa minaccia. Uccidi questi orchi Blackrock e portami dieci delle loro Battleworn Axe come prova.$B$BI Blackrock ci minacciano da nord, ma ci sono arrivate segnalazioni di altri orchi nell'angolo sud-orientale di Redridge. Se ne trovi laggiù, da' la caccia anche a loro.",
  obj = "Porta 10 Battleworn Axe a Marshal Marris, a Lakeshire.",
  progress = "Hai ucciso degli orchi, $N? Se è così, fammi vedere...",
  reward = "Sono un bel po' di orchi in meno di cui preoccuparsi, grazie.",
  en_title = "Blackrock Menace",
  en_obj = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.",
}
T[21] = {
  title = "Scontro a Echo Ridge",
  desc = "Le tue precedenti indagini sono la prova che la Echo Ridge Mine va ripulita.  Torna alla miniera e aiuta a liberarla dai kobold.$B$BNon perdere tempo, $N.  Più a lungo i kobold restano indisturbati nella miniera, più si radicano a Northshire.",
  obj = "Uccidi 12 Kobold Laborer, poi torna dal Marshal McBride alla Northshire Abbey.",
  progress = "So che è un lavoro sanguinoso, $N, ma è vitale per la sicurezza di Northshire. Sei pront$Go:a; a riferire?",
  reward = "Ancora una volta ti sei guadagnat$Go:a; il mio rispetto e la gratitudine dello Stormwind Army. Forse ci sono ancora kobold nella miniera, ma schiererò altri contro di loro. Abbiamo altri compiti per te.",
  en_title = "Skirmish at Echo Ridge",
  en_obj = "Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.",
}
T[22] = {
  title = "Torta al fegato di Goretusk",
  desc = "Le cipolle sono sbucciate.  L'aglio è tritato.  Il rosmarino è pestato.  La crosta è cotta.  L'aneto è tagliato.  Il sugo sobbolle.  Ora per la mia famosa torta di carne mi servono solo 8 Goretusk Liver!",
  obj = "Salma Saldean ha bisogno di 8 Goretusk Liver per preparare una Goretusk Liver Pie.",
  progress = "Per la mia famosa torta di carne mi servono solo 8 Goretusk Liver!",
  reward = "Sono perfetti, $N! Grazie mille. Farmer Saldean e io faremo un banchetto stasera. Ed ecco una piccola cosa per te, per la fatica. Non penserai mica che lasci a digiuno un $C come te, vero?",
  en_title = "Goretusk Liver Pie",
  en_obj = "Salma Saldean needs 8 Goretusk livers to make a Goretusk Liver Pie.",
}
T[23] = {
  title = "Ursangous's Paw",
  desc = "La zampa del possente orso Ursangous è il tuo trofeo per questa parte della caccia di Ashenvale. Sulla zampa c'è un piccolo emblema a quarto di luna; il significato dell'emblema resta un mistero.$B$BLa zampa va portata a Senani Thunderheart a Splintertree Post, per dimostrare che hai battuto la possente creatura e completato questa parte della caccia.",
  obj = "Porta Ursangous's Paw a Senani Thunderheart a Splintertree Post, in Ashenvale.",
  progress = "Ah — $N — stavo giusto pensando a te! Come va la caccia?",
  reward = "Ah, la zampa di Ursangous! La tua abilità è notevole, $C; gli sono attribuite numerose uccisioni. La mezzaluna sulla sua zampa è senza dubbio il segno che era stato addestrato dagli elfi della notte che si aggirano per Ashenvale. Ursangous è... era uno degli orsi più possenti che si potessero trovare da queste parti. Aver battuto una creatura simile è la prova della tua volontà e della tua determinazione.$B$BI tuoi antenati ne sarebbero fieri!",
  en_title = "Ursangous's Paw",
  en_obj = "Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[24] = {
  title = "Shadumbra's Head",
  desc = "Shadumbra, un tempo veloce, ora giace immobile mentre reclami la vittoria su di esso. La testa del nightsaber ucciso è un trofeo adatto a questo scontro della caccia di Ashenvale. Senani Thunderheart, a Splintertree Post, vorrà vedere un trofeo simile per riconoscerti il merito di questa parte della caccia di Ashenvale.",
  obj = "Porta Shadumbra's Head a Senani Thunderheart a Splintertree Post, in Ashenvale.",
  progress = "Salve di nuovo, $N! Sei $Gvenuto:venuta; a mostrarmi le prove della tua caccia?",
  reward = "Una vittoria per $N nella caccia di Ashenvale! Ben fatto — la testa di Shadumbra è senza dubbio un trofeo adatto a uno scontro così notevole.$B$BLa ferocia di Shadumbra era nota in tutto l'avamposto. Ogni viaggio verso ovest, soprattutto a piedi per raggiungere lo Zoram Strand, era pieno di pericoli a causa di quella tigre. Grazie a te, il pericolo è diminuito.",
  en_title = "Shadumbra's Head",
  en_obj = "Bring Shadumbra's Head to Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[25] = {
  title = "Stallo a Stonetalon",
  desc = "Se vuoi renderti utile, perché non fai qualcosa per la situazione vicino al Talondeep Path?$B$BI trasporti tra Ashenvale e Stonetalon sono fermi perché il lago si è animato e attacca tutto ciò che gli si avvicina... cioè chiunque passi sul sentiero. Ancora più utile che menare le mani sugli elementali dell'acqua sarebbe qualcuno che vada a dare un'occhiata al gazebo sul Mystral Lake — quello da cui si vede bene l'avamposto dell'Alleanza.$B$BTe la senti di renderti utile?",
  obj = "Elimina 12 Befouled Water Elemental al Mystral Lake, dritto a est del Talondeep Path e a sud-ovest di Splintertree Post.$B$BVa' a dare un'occhiata al gazebo sul Mystral Lake, quello che domina l'avamposto dell'Alleanza lì vicino.$B$BTorna da Mastok Wrilehiss a Splintertree Post, in Ashenvale.",
  progress = "Già di ritorno? Com'è la situazione là fuori — tutto sistemato, grazie a te?",
  reward = "Già, ho sentito che qualcuno ha messo a soqquadro quel lago come un turbine di polvere attraverso le Barrens. E da quel che si dice, forse potremmo allestire là fuori un punto d'osservazione per tenere d'occhio i nostri amici dell'Alleanza. Sempre che riusciamo a farlo senza dare nell'occhio...$B$BSembra che alla fine ti sia $Greso:resa; parecchio utile; i trasporti tra qui e Stonetalon dovrebbero avere vita più facile. Prendi questo — te lo sei $Gguadagnato:guadagnata;.",
  en_title = "Stonetalon Standstill",
  en_obj = "Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post.$B$BScout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost.$B$BReturn to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
}
T[26] = {
  title = "Una lezione da imparare",
  desc = "$N, seguo i tuoi progressi con grande piacere. Stai davvero diventando $Gun prezioso protettore:una preziosa protettrice; della natura.$B$BÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci — un aspetto che ti dona il controllo e la padronanza dell'acqua. Per questo devi recarti nel villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Sarà lui a guidarti oltre.",
  obj = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.",
  reward = "Salute a te, giovane $Gdruido:druida;. È giunto il momento che tu conosca la nostra Aquatic Form. È una forma che ti permette di muoverti liberamente nell'acqua, senza limiti di tempo. Scoprirai che questo aspetto è uno strumento utile e una benedizione... ma prima di padroneggiarlo bisogna guadagnarselo.$B$BDovrai superare due prove. La prima verificherà la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione a comprendere gli aspetti della forma stessa.$B$BTieniti $Gpronto:pronta;, perché il momento delle prove è arrivato.",
  en_title = "A Lesson to Learn",
  en_obj = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[27] = {
  title = "Una lezione da imparare",
  desc = "$N, seguo i tuoi progressi con grande piacere. Stai davvero diventando $Gun prezioso protettore:una preziosa protettrice; della natura.$B$BÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci — un aspetto che ti dona il controllo e la padronanza dell'acqua. Per questo devi recarti nel villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Sarà lui a guidarti oltre.",
  obj = "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.",
  reward = "Salute a te, giovane $Gdruido:druida;. È giunto il momento che tu conosca la nostra Aquatic Form. È una forma che ti permette di muoverti liberamente nell'acqua, senza limiti di tempo. Scoprirai che questo aspetto è uno strumento utile e una benedizione... ma prima di padroneggiarlo bisogna guadagnarselo.$B$BDovrai superare due prove. La prima verificherà la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione a comprendere gli aspetti della forma stessa.$B$BTieniti $Gpronto:pronta;, perché il momento delle prove è arrivato.",
  en_title = "A Lesson to Learn",
  en_obj = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[28] = {
  title = "Prova del lago",
  desc = "Per la tua prima prova, cerca nelle profondità del Lake Elune'ara uno Shrine Bauble. Si deteriora in fretta, quindi portalo subito allo Shrine of Remulos. Usa il ninnolo al santuario, poi parla con Tajarri, che si trova lì; è una delle guardiane più fidate di Moonglade.$B$BHai solo un tempo limitato per completare il compito, e potresti trovarti in competizione con altri druidi che cercano anche loro dei ninnoli. L'agilità mentale e fisica sarà fondamentale per la tua riuscita.$B$BBuona fortuna, $N.",
  obj = "Trova uno Shrine Bauble nel Lake Elune'ara e portalo allo Shrine of Remulos, nella parte nord-occidentale di Moonglade. Una volta lì, usa lo Shrine Bauble.$B$BPoi, per completare la prova, devi parlare con Tajarri al santuario.",
  progress = "Per completare la Prova del Lago devi usare lo Shrine Bauble entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.",
  reward = "Bene, bene, sembra che $Gun altro druido:un'altra druida; abbia superato la Prova del Lago! Ben fatto, $Gmio giovane amico:mia giovane amica; — ben fatto.$B$BCome ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio fare da guardiana a Moonglade, e in particolare a questo santuario. Keeper Remulos guida il Cenarion Circle nella salvaguardia della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare il ninnolo qui è un modo di riconoscere l'importanza di questo luogo per il Circle.",
  en_title = "Trial of the Lake",
  en_obj = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.$B$BYou must speak with Tajarri at the shrine afterwards in order to complete the trial.",
}
T[29] = {
  title = "Prova del lago",
  desc = "Per la tua prima prova, cerca nelle profondità del Lake Elune'ara uno Shrine Bauble. Si deteriora in fretta, quindi portalo subito allo Shrine of Remulos. Usa il ninnolo al santuario, poi parla con Tajarri, che si trova lì; è una delle guardiane più fidate di Moonglade.$B$BHai solo un tempo limitato per completare il compito, e potresti trovarti in competizione con altri druidi che cercano anche loro dei ninnoli. L'agilità mentale e fisica sarà fondamentale per la tua riuscita.$B$BBuona fortuna, $N.",
  obj = "Trova uno Shrine Bauble nel Lake Elune'ara e portalo allo Shrine of Remulos, nella parte nord-occidentale di Moonglade. Una volta lì, usa lo Shrine Bauble.$B$BPoi, per completare la prova, devi parlare con Tajarri al santuario.",
  progress = "Per completare la Prova del Lago devi usare lo Shrine Bauble entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.",
  reward = "Bene, bene, sembra che $Gun altro druido:un'altra druida; abbia superato la Prova del Lago! Ben fatto, $Gmio giovane amico:mia giovane amica; — ben fatto.$B$BCome ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio fare da guardiana a Moonglade, e in particolare a questo santuario. Keeper Remulos guida il Cenarion Circle nella salvaguardia della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare il ninnolo qui è un modo di riconoscere l'importanza di questo luogo per il Circle.",
  en_title = "Trial of the Lake",
  en_obj = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.$B$BYou must speak with Tajarri at the shrine afterwards in order to complete the trial.",
}
T[30] = {
  title = "Prova del leone marino",
  desc = "Per la seconda prova ti serviranno le due metà che formano il Pendant of the Sea Lion. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dall'incredibile resistenza dell'aspetto del leone marino. I druidi attingono in egual misura a entrambe queste qualità per incarnare l'aspetto della loro Aquatic Form.$B$BParla con gli abitanti di Moonglade per scoprire dove potrebbero trovarsi le due parti, e portale entrambe qui per unirle. Una volta formato il pendente, portalo a Dendrite Starblaze.",
  obj = "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per avere indizi su dove possano trovarsi questi oggetti.$B$BForma il Pendant of the Sea Lion unendo le due metà del pendente. Per farlo devi trovarti vicino allo Shrine of Remulos.$B$BPorta il pendente completo a Dendrite Starblaze, nel villaggio di Nighthaven, a Moonglade.",
  progress = "Hai formato il pendente da farmi esaminare, $N? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni alla gente del posto. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.",
  reward = "Hai completato la Prova del Leone Marino, $N — congratulazioni.$B$BOgni passo per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua disponibilità a fare tuo l'aspetto del leone marino.$B$BRicorda bene queste lezioni: ti serviranno quando avrai ottenuto la tua Aquatic Form.",
  en_title = "Trial of the Sea Lion",
  en_obj = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.$B$BForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.$B$BBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[31] = {
  title = "Aquatic Form",
  desc = "Hai completato le lezioni che tutti i giovani druidi devono imparare prima di poter assumere un aspetto acquatico. Ora torna dal tuo istruttore, Turak Runetotem, a Thunder Bluff. Mostragli il tuo pendente e dimostragli che sei $Gpronto:pronta; a imparare ciò che ha da insegnarti. Completerà il tuo addestramento, permettendoti di diventare una cosa sola con l'acqua.$B$BArrivederci, giovane $Gdruido:druida;. Parleremo ancora.",
  obj = "Torna a Thunder Bluff e mostra il Pendant of the Sea Lion a Turak Runetotem.",
  progress = "La notizia del tuo ritorno a Thunder Bluff ti ha preceduto, ma mi servirà una prova delle lezioni che hai imparato a Moonglade prima di insegnarti la tua Aquatic Form.$B$BHai il Pendant of the Sea Lion?",
  reward = "Davvero notevole, $N. I tuoi antenati sarebbero fieri dei tuoi progressi! Sei $Gpronto:pronta; a imparare la tua Aquatic Form, ed è un piacere per me insegnartela.$B$BInoltre, in riconoscimento di quanto hai fatto nelle due prove, ti do questo oggetto. Spero che sia un'aggiunta gradita al tuo equipaggiamento di $Gprotettore:protettrice; della natura e custode dell'equilibrio.",
  en_title = "Aquatic Form",
  en_obj = "Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion.",
}
T[33] = {
  title = "Lupi oltre il confine",
  desc = "Odio quei fastidiosi lupi grigi!  Ma mi piacciono parecchio le bistecche di lupo...  Portami della carne di lupo coriacea e te la scambierò con qualcosa di utile.$B$BLa carne di lupo coriacea si ottiene cacciando i lupi grigi e i giovani lupi che vagano per la campagna di Northshire.",
  obj = "Porta 8 pezzi di Tough Wolf Meat a Eagan Peltskinner fuori dalla Northshire Abbey.",
  progress = "Ehi $N. Comincia a venirmi fame... hai preso quella carne di lupo coriacea?",
  reward = "Ti sei dat$Go:a; da fare! Non vedo l'ora di cucinare quella carne di lupo...$B$BHo qui alcune cose che fanno per te - scegli pure!",
  en_title = "Wolves Across the Border",
  en_obj = "Bring 8 pieces of Tough Wolf Meat to Eagan Peltskinner outside Northshire Abbey.",
}
T[34] = {
  title = "Un ospite sgradito",
  desc = "Un'altra volta il mio giardino è stato calpestato e saccheggiato. E so bene chi è il bruto che lo fa. È quel maledetto cinghiale, quello che Marshal Marris ha preso a chiamare Bellygrub.$B$BAdesso non potrò ripiantare i narcisi fino alla prossima stagione. Rovinati! Tutti rovinati da quell'unico cinghiale molesto. Metti fine a quella peste! Mostrami la sua zanna e sarò felice di ricompensarti. Sembra che passi il tempo a razzolare nel campo a sud-ovest di Lakeshire, ma ogni tanto se ne viene fin qui e mi entra in giardino.",
  obj = "Martie Jainrose di Lakeshire vuole che tu uccida Bellygrub. Portale la sua zanna come prova.",
  progress = "Bellygrub sta ancora facendo dei suoi, o sei $Griuscito:riuscita; a liberare Lakeshire da quella peste una volta per tutte?",
  reward = "Finalmente la minaccia è sepolta! Grazie, $N, mi hai reso un gran servizio. Questa stagione il giardino sarà in piena fioritura!",
  en_title = "An Unwelcome Guest",
  en_obj = "Martie Jainrose of Lakeshire wants you to kill Bellygrub.  Bring her his tusk as proof.",
}
T[35] = {
  title = "Altre preoccupazioni",
  desc = "Se temi che le voci sui murloc siano vere, fa' così: raggiungi il ponte a est di Elwynn e parla con Guard Thomas.  È di stanza al ponte da una settimana e conoscerà la situazione della zona.$B$BPortami il suo rapporto.",
  obj = "Marshal Dughan vuole che tu parli con Guard Thomas.",
  reward = "Sì, i murloc si sono insediati dentro e intorno ai ruscelli di Elwynn orientale. Non sappiamo perché siano qui, ma sono aggressivi e almeno in parte intelligenti.",
  en_title = "Further Concerns",
  en_obj = "Marshal Dughan wants you to speak with Guard Thomas.",
}
T[36] = {
  title = "Stufato di Westfall",
  desc = "Non avrei mai pensato che sarebbe arrivato il giorno in cui avrei lasciato la fattoria.  Ma i campi sono invasi dai ladri ed è troppo pericoloso per noi restare qui.  Appena Farmer Furlbrow avrà riparato il carro, partiremo.$B$BForse potresti farmi un favore?  Lasciami scrivere la mia ricetta dello stufato di Westfall.  Per favore, portala a Salma Saldean nella fattoria laggiù.  La fattoria dei Saldean è subito dopo il bivio sulla strada.",
  obj = "Verna Furlbrow vuole che tu consegni la sua ricetta dello Westfall Stew a Salma Saldean.",
  progress = "Mi mancherà tanto quella Verna Furlbrow. Non è che l'hai vista, per caso, venendo qui?",
  reward = "Quella Verna è sempre stata una ragazza così dolce. Ci mancherà qui a Westfall, ma detto tra noi, è una ragazza di città nel cuore e Stormwind le starà benissimo. Ma basta pettegolezzi! Ora possiamo preparare lo Westfall Stew!",
  en_title = "Westfall Stew",
  en_obj = "Verna Furlbrow wants you to deliver her recipe for Westfall Stew to Salma Saldean.",
}
T[37] = {
  title = "Trova le guardie scomparse",
  desc = "Qualche giorno fa abbiamo mandato due guardie, Rolf e Malakai, a indagare lungo il fiume, e non sono ancora tornate. Per completare il mio rapporto devo sapere che cosa è successo a quegli uomini.$B$BViaggia verso nord lungo il fiume e trova le guardie... o i loro resti.",
  obj = "Guard Thomas vuole che tu viaggi verso nord lungo il fiume e cerchi le due guardie scomparse, Rolf e Malakai.",
  reward = "Anche se al cadavere è stato strappato via quasi tutto, lì accanto giace un medaglione con incise le parole: \"Footman Malakai Stone\".",
  en_title = "Find the Lost Guards",
  en_obj = "Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai.",
}
T[38] = {
  title = "Stufato di Westfall",
  desc = "Aiutami a preparare un po' di Westfall Stew! Torna con i seguenti ingredienti: $B $B 3 Stringy Vulture Meat $B 3 Goretusk Snouts $B 3 Murloc Eyes $B 3 Okra",
  obj = "Salma Saldean vuole 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 Okra.",
  progress = "Torna con i seguenti ingredienti: $B $B 3 Stringy Vulture Meat $B 3 Goretusk Snouts $B 3 Murloc Eyes $B 3 Okra",
  reward = "Questa Okra renderà il brodo bello denso! Ora basta aggiungere la Stringy Vulture Meat, qualche Murloc Eye e quei deliziosi Goretusk Snouts. E il piatto è pronto! Per tutto il tuo aiuto, $N, voglio che tu prenda la prima porzione di Westfall Stew di oggi!",
  en_title = "Westfall Stew",
  en_obj = "Salma Saldean wants 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 Okra.",
}
T[39] = {
  title = "Consegna il rapporto di Thomas",
  desc = "Riferisci a Marshal Dughan della morte di Malakai e Rolf, e informalo che i Murloc nell'Elwynn orientale non possono essere contenuti con la nostra attuale presenza di truppe.$B$BSo che non abbiamo molti soldati da risparmiare, ma spero che Dughan riesca a trovare qualcuno.",
  obj = "Riferisci a Marshal Dughan a Goldshire.",
  reward = "Hmm, queste notizie sono preoccupanti. Le nostre difese sono già ridotte all'osso, e aver perso Rolf e Malakai a causa di quei murloc ci mette in una posizione ancora peggiore.$B$BSe le cose non migliorano, entro la fine della settimana si combatterà a Goldshire!",
  en_title = "Deliver Thomas' Report",
  en_obj = "Report to Marshal Dughan in Goldshire.",
}
T[40] = {
  title = "Un pericolo che sa di pesce",
  desc = "$N, c'è una nuova minaccia nella Elwynn Forest! I Murloc risalgono i ruscelli dell'Elwynn orientale, spaventando i pesci e attaccando la brava gente!$B$BHo avvertito Marshal Dughan, ma lui è più preoccupato per i gnoll e i banditi. Non è convinto che i murloc siano un pericolo.$B$BTi prego, $N, parla con Dughan e convincilo a mandare più truppe a est!",
  obj = "Remy \"Two Times\" vuole che tu parli con Marshal Dughan a Goldshire.",
  reward = "Sì, ho parlato con Remy. Lo rispetto come mercante, ma tutti i rapporti sui Murloc a est sono stati nel migliore dei casi vaghi.$B$BLe tue preoccupazioni sono state annotate, ma finché non riceverò un rapporto militare su una minaccia murloc, non possiamo permetterci di mandare altre truppe a est.",
  en_title = "A Fishy Peril",
  en_obj = "Remy \"Two Times\" wants you to speak with Marshal Dughan in Goldshire.",
}
T[45] = {
  title = "Scopri il destino di Rolf",
  desc = "Continuando a cercare nella zona, trovi delle impronte palmate che conducono a est lungo la riva dello Stone Cairn Lake. In lontananza, a est, riesci appena a scorgere un villaggio di Murloc.$B$BForse il destino di Rolf si è compiuto laggiù...",
  obj = "Cerca Rolf nel villaggio dei murloc, o i segni della sua morte.",
  reward = "Intorno al collo del cadavere trovi un medaglione di metallo con incise le parole \"Footman Rolf Hartford\".",
  en_title = "Discover Rolf's Fate",
  en_obj = "Search the murloc village for Rolf, or signs of his death.",
}
T[46] = {
  title = "Taglia sui Murloc",
  desc = "Lo Stormwind Army ha posto una taglia sui murloc lurker e forager dell'Elwynn. Massacrali e portami le loro Torn Murloc Fins, e lo Stormwind Army ti ricompenserà bene.$B$BI murloc hanno costruito un villaggio allo Stone Cairn Lake, a nord di qui, e un altro a sud, dove il ruscello si biforca.",
  obj = "Porta 8 Torn Murloc Fins a Guard Thomas al ponte dell'Elwynn orientale.",
  progress = "Come procede la caccia, $N?",
  reward = "Hai le pinne? Ottimo! Marshal Dughan è in ansia per la situazione dei Murloc nell'Elwynn orientale, e vorrei dirgli che sta tornando sotto controllo.$B$BLe tue azioni hanno aiutato a renderlo possibile.",
  en_title = "Bounty on Murlocs",
  en_obj = "Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge.",
}
T[47] = {
  title = "Scambio di Gold Dust",
  desc = "I Kobold da queste parti a volte portano con sé della Gold Dust. Mi farebbe proprio comodo: portamene un carico e ti darò il miglior prezzo della città... il miglior prezzo della città!$B$BPuoi trovare kobold nella Fargodeep Mine a sud, e intorno alla Jasperlode Mine a nordest.",
  obj = "Porta 10 Gold Dust a Remy \"Two Times\" a Goldshire. La Gold Dust si ottiene dai Kobold della Elwynn Forest.",
  progress = "Psst! Hai quella Gold Dust per me... per me?",
  reward = "Grazie per la polvere, $N. Ecco i tuoi soldi, e... ecco un pegno da parte di alcuni miei soci. Potresti trovarlo utile... utile.",
  en_title = "Gold Dust Exchange",
  en_obj = "Bring 10 Gold Dust to Remy \"Two Times\" in Goldshire.  Gold Dust is gathered from Kobolds in Elwynn Forest.",
}
T[48] = {
  title = "Dolce ambra",
  desc = "Nella terra a sud, dove i tralci si torcono e strisciano,$Bc'è un pozzo nascosto, dove acque profonde scorrono.$BPura come la sacra Figlia della Luce,$Bportami ora un po' di Holy Spring Water.",
  obj = "Porta dell'Holy Spring Water a Grimbooze Thunderbrew.",
  progress = "Hic! Oh oh! Vuoi il bis?$B$BNella terra a sud, dove i tralci si torcono e strisciano,$Bc'è un pozzo nascosto, dove acque profonde scorrono.$BPura come la sacra Figlia della Luce,$Bportami ora un po' di Holy Spring Water.",
  reward = "Hic! Oh oh!",
  en_title = "Sweet Amber",
  en_obj = "Bring Holy Spring Water to Grimbooze Thunderbrew.",
}
T[49] = {
  title = "Dolce ambra",
  desc = "L'ambra è il colore del più lungo amore della mia vita,$Bcome le ultime braci del tramonto nel cielo lassù.$BProcurami, perché il mio amore possa nascere,$Bun sacco per tipo: orzo, segale e mais.",
  obj = "Grimbooze Thunderbrew vuole un Sack of Barley, un Sack of Rye e un Sack of Corn.",
  progress = "Il bis? Ma certo!$B$BL'ambra è il colore del più lungo amore della mia vita,$Bcome le ultime braci del tramonto nel cielo lassù.$BProcurami, perché il mio amore possa nascere,$Bun sacco per tipo: orzo, segale e mais.",
  reward = "Hic! Oh oh!",
  en_title = "Sweet Amber",
  en_obj = "Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.",
}
T[50] = {
  title = "Dolce ambra",
  desc = "Mescolerò e mescolerò finché avremo il mosto,$Be sarà la nostra scorta privata, ben nascosta.$BUn alambicco va forgiato con un metallo forte:$Bportami del Truesilver per finire questa canzone.",
  obj = "Grimbooze Thunderbrew vuole del Truesilver.",
  progress = "Un bis per te? Ma certo, $Gamico:amica;!$B$BMescolerò e mescolerò finché avremo il mosto,$Be sarà la nostra scorta privata, ben nascosta.$BUn alambicco va forgiato con un metallo forte:$Bportami del Truesilver per finire questa canzone.",
  reward = "Hic! Oh oh!",
  en_title = "Sweet Amber",
  en_obj = "Grimbooze Thunderbrew wants Truesilver.",
}
T[51] = {
  title = "Dolce ambra",
  desc = "Non ancora filtrato, ma appena distillato,$Bcome terra non seminata che attende, già arata.$BOra preparerò il nostro mucchio di carbone:$Bportami un ramo di sicomoro, è la tua prossima missione.",
  obj = "Porta un Sycamore Branch a Grimbooze Thunderbrew.",
  progress = "Un bis? Per te, questo e altro!$B$BNon ancora filtrato, ma appena distillato,$Bcome terra non seminata che attende, già arata.$BOra preparerò il nostro mucchio di carbone:$Bportami un ramo di sicomoro, è la tua prossima missione.",
  reward = "Hic! Oh oh!",
  en_title = "Sweet Amber",
  en_obj = "Bring a Sycamore Branch to Grimbooze Thunderbrew.",
}
T[52] = {
  title = "Proteggi la frontiera",
  desc = "Salute, $N. Gli animali selvatici diventano sempre più aggressivi man mano che ci allontaniamo da Goldshire, e l'Eastvale Logging Camp subisce attacchi quasi continui da parte di lupi e orsi!$B$BUn aiuto qui ci farebbe comodo.",
  obj = "Uccidi 8 Prowler e 5 Young Forest Bear, poi torna da Guard Thomas al ponte dell'Elwynn orientale.",
  progress = "Hai ucciso quei lupi e quegli orsi?",
  reward = "Grazie mille per l'aiuto, $N. Qualcosa nella foresta deve rendere questi animali così audaci.$B$BQualunque cosa sia, spero che resti là.",
  en_title = "Protect the Frontier",
  en_obj = "Kill 8 Prowlers and 5 Young Forest Bears, and then return to Guard Thomas at the east Elwynn bridge.",
}
T[53] = {
  title = "Dolce ambra",
  desc = "Un liquido dolce, limpido come le lacrime di un bambino,$Bcol passare degli anni si fa di un bell'ambra profondo.$BMa prima di ubriacarci fino in fondo,$Bva costruita una botte di quercia carbonizzata.",
  obj = "Porta a Grimbooze Thunderbrew un fascio di Charred Oak.",
  progress = "Certo che te la ricanto, $Gamico:amica;!$B$BUn liquido dolce, limpido come le lacrime di un bambino,$Bcol passare degli anni si fa di un bell'ambra profondo.$BMa prima di ubriacarci fino in fondo,$Bva costruita una botte di quercia carbonizzata.",
  reward = "Invecchiato nella botte, filtrato nel carbone,$Bti passa sulle labbra e dritto nell'anima scende.$BAllora beviamo, facciamo un brindisi a te,$Be già che ci siamo a me, Grimbooze Thunderbrew!",
  en_title = "Sweet Amber",
  en_obj = "Bring Grimbooze Thunderbrew a bundle of Charred Oak.",
}
T[54] = {
  title = "Presentati a Goldshire",
  desc = "$N, sei $Gun:una; $c con un provato interesse per la sicurezza di Northshire. Ora ti è affidata la protezione della vicina Elwynn Forest.$B$BSe accetti questo incarico, ho preparato dei documenti che devono essere consegnati a Marshal Dughan a Goldshire. Goldshire si trova lungo la strada meridionale, oltre i cancelli di confine.",
  obj = "Porta i Marshal McBride's Documents a Marshal Dughan a Goldshire.",
  progress = "Hai notizie da McBride? Northshire è un giardino in confronto alla Elwynn Forest, ma mi chiedo che cosa abbia da riferire Marshal McBride.$B$BQui, lascia che veda i suoi documenti...",
  reward = "Dunque, qui dice che ti è stato conferito lo status di Acting Deputy presso gli Stormwind Marshal. Congratulazioni.$B$BE buona fortuna: mantenere al sicuro Elwynn non è una passeggiata... visto che la maggior parte dell'esercito è impegnata a fare chissà che cosa per chissà quale nobile!$B$BÈ difficile tenere il passo con la politica in questi giorni bui...",
  en_title = "Report to Goldshire",
  en_obj = "Take Marshal McBride's Documents to Marshal Dughan in Goldshire.",
}
T[55] = {
  title = "Morbent Fel",
  desc = "Morbent Fel si nasconde nella sua tana, la casa appollaiata in cima alla collina a est, che domina il cimitero di Raven Hill. Il suo tempo in questa terra sta per finire...$B$BUsa Morbent's Bane contro di lui. Renderà impotenti le sue magie protettive.$B$BUccidilo. Uccidilo, e salvaci dalla sua malvagità. Sii lo strumento della mia vendetta, e $Gun eroe:un'eroina; di Duskwood!",
  obj = "Usa Morbent's Bane su Morbent Fel, uccidi Morbent Fel, poi riporta Morbent's Bane a Sven, al suo accampamento.",
  progress = "Morbent Fel è stato sconfitto?!",
  reward = "Morbent Fel è stato sconfitto. I Dark Rider sono ancora in libertà, ma una piccola parte di quel che speravo oltre ogni speranza si è avverata.$B$BHai fatto l'impossibile, e le tue imprese vivranno per sempre nelle leggende di Duskwood.$B$BVa', $N. E forse, un giorno, il destino ti riporterà da me...",
  en_title = "Morbent Fel",
  en_obj = "Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.",
}
T[56] = {
  title = "La Guardia Notturna",
  desc = "Come comandante della Guardia Notturna, ho giurato di proteggere i cittadini di Darkshire. Stormwind ha ritirato le guardie che aveva di stanza qui, lasciandoci a cavarcela da soli.$B$BSe ti senti all'altezza del compito, ci serve il tuo aiuto! Aiuta la Guardia Notturna spingendoti nei Tranquil Gardens, appena a sud di Darkshire, e uccidendo 8 Skeletal Warrior e 6 Skeletal Mage. La minaccia dei non morti va fermata!",
  obj = "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 8 Skeletal Warrior e 6 Skeletal Mage.",
  progress = "Vedo che sei $Gtornato:tornata;, $N. Se vuoi dimostrare di essere utile alla Guardia Notturna, torna da me quando avrai ucciso 8 Skeletal Warrior e 6 Skeletal Mage.",
  reward = "Ottimo, $N. Per il servizio reso alla gente di Darkshire sarai $Gricompensato:ricompensata;.",
  en_title = "The Night Watch",
  en_obj = "Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages.",
}
T[57] = {
  title = "La Guardia Notturna",
  desc = "$N, mi arrivano segnalazioni di un'infestazione di non morti nella foresta! Se te la senti, va' al cimitero di Raven Hill e uccidi 15 di quegli immondi Skeletal Fiend e 15 Skeletal Horror. Ci sono segnalazioni di scheletri anche appena a sud di Darkshire, dentro e intorno al Tranquil Gardens Cemetery. I non morti vanno cacciati da Duskwood!",
  obj = "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 15 Skeletal Fiend e 15 Skeletal Horror.",
  progress = "Torna da me quando avrai ucciso 15 Skeletal Fiend e 15 Skeletal Horror, $N.",
  reward = "La gente di Darkshire ti ringrazia, $N. Hai dimostrato di essere $Gun grande alleato:una grande alleata; della Guardia Notturna.",
  en_title = "The Night Watch",
  en_obj = "Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors.",
}
T[58] = {
  title = "La Guardia Notturna",
  desc = "La situazione a Raven Hill è ancora grave. La sicurezza di Darkshire è nelle tue mani, $N. Non ho abbastanza Watcher per tenere il paese al sicuro. Devi partire ancora una volta per Raven Hill e liberare il mausoleo orientale da 20 Plague Spreader!",
  obj = "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 20 Plague Spreader nel mausoleo orientale di Raven Hill.",
  progress = "Mi serve il tuo aiuto, $N. Va' al cimitero a nord-ovest e libera il mausoleo orientale da 20 Plague Spreader.$B$BTorna da me quando avrai finito.",
  reward = "A nome della gente di Darkshire e come capo della Guardia Notturna, ti ringrazio, $N, per il tuo coraggio e la tua dedizione. Che la Luce illumini il tuo cammino.",
  en_title = "The Night Watch",
  en_obj = "Commander Althea Ebonlocke of Darkshire wants you to kill 20 Plague Spreaders in the eastern Raven Hill mausoleum.",
}
T[59] = {
  title = "Armatura di stoffa e di cuoio",
  desc = "Per la tua astuzia e il tuo valore, ho qui un buono valido per un pezzo di armatura. Voglio che lo porti a Sara Timberlain all'Eastvale Logging Camp. Consegnale il buono e lei forgerà l'armatura per te. E dopo averla ricevuta, $N, usala per difendere Elwynn.$B$BL'Eastvale Logging Camp si trova a est, oltre il posto di guardia di Guard Thomas.",
  obj = "Consegna lo Stormwind Armor Marker a Sara Timberlain.",
  progress = "Lo Stormwind Army mi ha incaricata di rifornire i suoi uomini di armature di stoffa e di cuoio.$B$BSe hai un buono per me, sarò lieta di realizzarti qualcosa.",
  reward = "Ah, grazie per il buono. Scegli pure l'armatura che preferisci.$B$BBuona fortuna, coraggios$Go:a; $C. E che questa armatura ti serva bene.",
  en_title = "Cloth and Leather Armor",
  en_obj = "Give Sara Timberlain the Stormwind Armor Marker.",
}
T[60] = {
  title = "Candele dei Kobold",
  desc = "Salve, $gbuon signore:mia signora;! Avete un momento?$B$BMio fratello e io gestiamo un'erboristeria a Stormwind, e sono qui per raccogliere grosse candele per la loro cera. Potete aiutarmi?$B$BLe grosse candele si ottengono dai kobold, e corre voce che i kobold stiano infestando le miniere dell'Elwynn... la Fargodeep Mine a sud e la Jasperlode Mine a est. Vi consiglio di cercare le candele in uno di quei posti.",
  obj = "Porta 8 Large Candles a William Pestle a Goldshire.",
  progress = "Hai già raccolto quelle candele?",
  reward = "Sei stat$Go:a; occupat$Go:a; a dare la caccia ai kobold, vero? Grazie per le candele, $N, ed ecco la tua ricompensa...",
  en_title = "Kobold Candles",
  en_obj = "Bring 8 Large Candles to William Pestle in Goldshire.",
}
T[61] = {
  title = "Carico per Stormwind",
  desc = "Mio fratello Morgan sta aspettando a Stormwind il mio carico di candele. Non ho abbastanza tempo per fare il viaggio di persona, ma se vuoi portargli il carico, ti pagherà bene.$B$BHo imballato le candele, e puoi trovare Morgan nel nostro negozio, Pestle's Apothecary, nello Stormwind Trade District.",
  obj = "Porta il William's Shipment a Morgan Pestle nello Stormwind Trade District.",
  progress = "Oh, un carico da parte di mio fratello? Splendido! La fortuna mi sorride davvero oggi!",
  reward = "Ecco il tuo pagamento... e già che ci sei, dai un'occhiata in giro! Sono certo che abbiamo una pozione o qualche altra cianfrusaglia che ti potrebbe tornare utile.",
  en_title = "Shipment to Stormwind",
  en_obj = "Bring William's Shipment to Morgan Pestle in the Stormwind Trade District.",
}
T[62] = {
  title = "La Fargodeep Mine",
  desc = "La miniera di Northshire non è l'unica ad avere problemi! Mi hanno riferito che anche la Fargodeep Mine, a Elwynn, è diventata un rifugio per i Kobold.$B$BEsplora la miniera e conferma queste voci, poi torna da me. La miniera si trova quasi esattamente a sud di Goldshire, tra le fattorie Stonefield e Maclure.",
  obj = "Esplora la Fargodeep Mine, poi torna da Marshal Dughan a Goldshire.",
  progress = "Che cosa hai da riferire, $N? Sei stat$Go:a; alla Fargodeep Mine?",
  reward = "Sono cattive notizie. Cosa sarà il prossimo, i draghi?!? Dovremo aumentare le pattuglie vicino a quella miniera. Grazie per il tuo impegno, $N. E aspetta un momento... potrei avere un altro incarico per te.",
  en_title = "The Fargodeep Mine",
  en_obj = "Explore the Fargodeep Mine, then return to Marshal Dughan in Goldshire.",
}
T[63] = {
  title = "Il richiamo dell'acqua",
  desc = "Lungo la costa di Silverpine, a ovest del Sepulcher, troverai un santuario che la piaga ha corrotto. Gli spiriti che ci sono non parlano più al nostro popolo, e toccherà a te sconfiggere la manifestazione e purificare la pozza.$B$BPrendi i bracciali dell'elementale, insieme alle gocce rimaste della pozione di Brine, e mettili sul braciere. Il rituale dovrebbe bastare a evocare uno spirito puro con cui potrai comunicare.$B$BPortami la prova che il compito è stato svolto, e ti ricompenserò con il tuo totem.",
  obj = "Sconfiggi la Corrupt Manifestation of Water e metti i Corrupted Manifestation's Bracers insieme alle Remaining Drops of Purest Water sul Brazier of Everfount, nella Silverpine Forest.",
  progress = "Il braciere riflette ancora la luce dei dintorni, e la fiamma si sposta leggermente mentre ti avvicini.$B$BLa corruzione sulle colline sembra essersi tenuta a distanza, e a parte i componenti mancanti il braciere sembra pronto per il rituale che evocherà una manifestazione purificata dell'acqua.",
  reward = "Metti i bracciali sul braciere, poi versi nella fiamma le gocce rimaste della pozione di Brine. Le gocce crepitano quando toccano la fiamma, e cominci a recitare le semplici parole che ti ha insegnato Islen...",
  en_title = "Call of Water",
  en_obj = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.",
}
T[64] = {
  title = "Il cimelio dimenticato",
  desc = "È stato orribile! Verna mi ha svegliato quando ha sentito un baccano nei campi. I campi erano pieni di teppisti. Siamo scappati di corsa e ho dimenticato di prendere il mio orologio da tasca. Il padre di Verna me lo diede il giorno delle nostre nozze e mi sento male al pensiero che quei ladri ce l'abbiano. Ho lasciato l'orologio da tasca nell'armadio della fattoria. Cerca il campo di zucche a ovest: non puoi sbagliarti. Se me lo riporti, te ne sarò davvero grato!",
  obj = "Farmer Furlbrow vuole che tu recuperi il suo orologio da tasca dall'armadio della sua fattoria, nella fattoria delle zucche a ovest.",
  progress = "Non è che per caso sei riuscit$Go:a; a prendere il mio orologio?",
  reward = "Il mio orologio! Grazie mille, gentile $Gsignore:signora;! $B$BSiamo solo poveri contadini e abbiamo perso la nostra terra, ma ti prego di accettare questa ricompensa come segno della nostra gratitudine.",
  en_title = "The Forgotten Heirloom",
  en_obj = "Farmer Furlbrow wants you to retrieve his pocket watch from the wardrobe in his farmhouse at the pumpkin farm to the West.",
}
T[65] = {
  title = "La Defias Brotherhood",
  desc = "La banda di miserabili responsabile di aver cacciato dalla loro terra la brava gente di Westfall si fa chiamare The Defias Brotherhood. Ho bisogno che tu infiltri questo clan di furfanti. Dobbiamo sapere chi guida il cartello e dove si nascondono. A Lakeshire, nella locanda, c'è un ladro di nome Wiley che mi deve un favore.$B$BViaggia fino a Lakeshire, nelle Redridge Mountains, a est di Elwynn, e scopri quello che puoi.",
  obj = "Gryan Stoutmantle vuole che tu parli con Wiley a Lakeshire.",
  reward = "Dunque, ti ha mandato Stoutmantle? Be', gli devo un favore.",
  en_title = "The Defias Brotherhood",
  en_obj = "Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.",
}
T[66] = {
  title = "La leggenda di Stalvan",
  desc = "Ieri notte un disturbo orribile mi ha percorso le vene. Ho sentito che mia nipote, Alyssa, era in grave pericolo. Ho consultato le carte e la Morte mi ha fissata dal tavolo.$B$BDopo un lungo viaggio attraverso una trance oscura sono riuscita a scoprire un indizio su questo mistero terrificante. Mi è venuto un nome, il nome di Stalvan.$B$BCerca il cancelliere al Town Hall e vedi se riesci a scoprire di più su questo tizio. Temo per tutti noi.",
  obj = "Cerca Clerk Daltry al Darkshire Town Hall.",
  reward = "Ah, quindi ti manda Madame Eva. . . .",
  en_title = "The Legend of Stalvan",
  en_obj = "Seek out the Clerk Daltry in the Darkshire Town Hall.",
}
T[67] = {
  title = "La leggenda di Stalvan",
  desc = "Stalvan, eh? Fammi controllare il registro del paese.$B$BStalvan. . .Stalvan. . .vediamo. Ah, eccolo! Ho la scheda di un certo Stalvan Mistmantle. L'ultimo indirizzo registrato è la Moonbrook Schoolhouse. Roba vecchia, altroché!$B$BMi fai un favore? Se ti capita di andare a Moonbrook, fammi sapere se trovi qualcosa di nuovo su questo tizio. Mi piace tenere le schede in ordine.",
  obj = "Va' alla Moonbrook Schoolhouse e riporta a Clerk Daltry ogni informazione aggiornata su Stalvan.",
  reward = "Il vecchio baule cigola mentre si apre. . . .",
  en_title = "The Legend of Stalvan",
  en_obj = "Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.",
}
T[68] = {
  title = "La leggenda di Stalvan",
  desc = "Nel vecchio baule trovi una Dusty Unsent Letter.",
  obj = "Porta la Dusty Unsent Letter a Clerk Daltry.",
  progress = "Ah, mi ricordo di te. Sei $Gquello:quella; che chiedeva di quel tale Stalvan. L'hai poi trovato quel che cercavi?",
  reward = "Interessante. Quindi quel tipo a Moonbrook ci ha passato davvero un po' di tempo. È piuttosto strano che la lettera non sia mai stata consegnata. In ogni caso, aggiorno il registro.",
  en_title = "The Legend of Stalvan",
  en_obj = "Take the Dusty Unsent Letter to Clerk Daltry.",
}
T[69] = {
  title = "La leggenda di Stalvan",
  desc = "Oh cielo! Devo essermelo perso la prima volta. Nel registro, proprio sotto il primo indirizzo di Stalvan, ce n'è un altro, cancellato solo a metà. Sembra che fosse diretto alla Lion's Pride Inn, a Goldshire. Faresti bene a controllare là, $N.",
  obj = "Va' alla Lion's Pride Inn e vedi se qualcuno lì ha sentito il nome Stalvan.",
  reward = "Stalvan? Di sicuro mi dice qualcosa.",
  en_title = "The Legend of Stalvan",
  en_obj = "Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.",
}
T[70] = {
  title = "La leggenda di Stalvan",
  desc = "Il nome Stalvan mi dice qualcosa. Ora ricordo.$B$BMolti anni fa, in una notte di tempesta, arrivò un messaggero in cerca di un riparo per la notte. Verso la mezzanotte l'uomo scese di corsa le scale urlando, il volto pallido di paura. Ancora in camicia da notte, sparì nel diluvio.$B$BNella fretta dimenticò le sue lettere nella cassa al piano di sopra. Non tornò mai a riprenderle. Ne resta una di quel tale Stalvan, indirizzata al Canal District di Stormwind. Serviti pure.",
  obj = "Recupera Stalvan's Undelivered Letter dalla cassa e consegnala al Canal District di Stormwind.",
  progress = "Cos'hai lì? Fammi dare un'occhiata. . .",
  reward = "Hai un bel coraggio a portare questa roba qui.",
  en_title = "The Legend of Stalvan",
  en_obj = "Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.",
}
T[71] = {
  title = "Rapporto a Thomas",
  desc = "Ora che hai entrambi i medaglioni, portali a Guard Thomas al ponte, così che possa conoscere la sorte delle sue guardie assassinate.",
  obj = "Consegna i Medaglioni di Rolf e Malakai a Guard Thomas al ponte orientale di Elwynn.",
  progress = "Salute, $N. Hai scoperto che fine hanno fatto Rolf e Malakai?",
  reward = "Hai confermato i miei timori, $N. I murloc sono una minaccia che non possiamo ignorare.",
  en_title = "Report to Thomas",
  en_obj = "Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge.",
}
T[72] = {
  title = "La leggenda di Stalvan",
  desc = "Mio padre è stato il custode della tenuta molto prima di me. Fu lui a dover asciugare il sangue dopo il massacro. Ma questo non c'entra.$B$BGli ultimi fondi dei Flintridge si sono esauriti. Ora anche le ultime cose di famiglia finiscono all'asta. Colpa degli avvoltoi del fisco. Immagino che, se proprio muori dalla voglia di saperne di più, sei $Glibero:libera; di frugare in questa roba. Chissà cosa puoi trovare.",
  obj = "Fruga tra le cose imballate in cerca di un indizio.",
  reward = "Fai scivolare piano il coperchio della cassa. . . .",
  en_title = "The Legend of Stalvan",
  en_obj = "Search through the packed up possessions for a clue.",
}
T[74] = {
  title = "La leggenda di Stalvan",
  desc = "Dentro la cassa trovi oggetti di ogni tipo: cimeli ammuffiti, un ritratto di famiglia, qualche trofeo di caccia e alcuni libri vecchi. Quasi in fondo, sotto un vaso di ceramica, scopri A Torn Journal Page.",
  obj = "La Torn Journal Page che hai scoperto ti dà il prossimo indizio.",
  progress = "Cos'hai lì? Non riesco a vedere. Ho la vista molto debole. Mettimelo tra le mani.",
  reward = "Riesco a malapena a distinguere quelle lettere. Ma quella calligrafia mi ricorda qualcosa che ho visto una volta, prima che la mia vista si facesse così debole.",
  en_title = "The Legend of Stalvan",
  en_obj = "The Torn Journal page you discovered provides your next clue.",
}
T[75] = {
  title = "La leggenda di Stalvan",
  desc = "Quando sono venuto a stare qui, nella cassa al piano di sopra c'era un fascio di pergamene. Le ho guardate una volta appena arrivato, ma ho rinunciato quando la nebbia mi ha annebbiato gli occhi.$B$BFa' un favore a un vecchio quasi cieco e controlla la cassa di sopra: magari c'è qualcosa che ti aiuta nella tua ricerca su questo Stalvan. Sono quasi sicuro che ci sia una pagina di diario sbiadita che potrebbe interessarti. Portamela e ti aiuterò come posso.",
  obj = "Marshal Haggard vuole che tu controlli la cassa di sopra per trovare la Faded Journal Page.",
  progress = "L'hai trovata quella pagina di cui ti ho detto, $N?",
  reward = "L'hai trovata!",
  en_title = "The Legend of Stalvan",
  en_obj = "Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.",
}
T[76] = {
  title = "La miniera di Jasperlode",
  desc = "Grazie a te sappiamo che la Fargodeep Mine è infestata dai kobold. Ora ci serve un esploratore che indaghi sulla più lontana Jasperlode Mine.$B$BEsplora Jasperlode e conferma la presenza dei kobold. Per raggiungere la miniera, viaggia verso est lungo la strada fino alla Tower of Azora. Dalla torre dirigiti a nord e troverai la miniera ai piedi delle colline.",
  obj = "Esplora la Jasperlode Mine, poi riferisci al Marshal Dughan a Goldshire.",
  progress = "Salute, $N. Che cos'hai da riferire? Hai esplorato la Jasperlode Mine?",
  reward = "Kobold alla Jasperlode Mine, dici? Maledizione! La situazione peggiora di minuto in minuto!$B$BGrazie del rapporto, $N. Ma vorrei che le notizie che hai portato fossero buone.",
  en_title = "The Jasperlode Mine",
  en_obj = "Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire.",
}
T[78] = {
  title = "La leggenda di Stalvan",
  desc = "Conosco qualcuno che potrebbe darti una mano. Ai tempi in cui guidavo la Stormwind Guard, andavamo a bere alla Scarlet Raven Tavern di Darkshire. Il locandiere di lì, Smitts, era un bell'esperto di storie locali. Mostragli questa pagina e senti cos'ha da dire.",
  obj = "Porta la Faded Journal Page a Tavernkeep Smitts.",
  progress = "Ti manda Marshal Haggard? E dirlo subito, no?$B$BAh, il buon vecchio Haggard. Povero diavolo, fra non molto sarà cieco del tutto. Comunque, fammi vedere cos'hai lì.",
  reward = "Per la Luce! Certo che la riconosco quella calligrafia.",
  en_title = "The Legend of Stalvan",
  en_obj = "Take the Faded Journal Page to Tavernkeep Smitts.",
}
T[79] = {
  title = "La leggenda di Stalvan",
  desc = "Ho seguito per anni la leggenda di quel tale Stalvan. Quando qualche anno fa massacrarono quei nobili in visita, andai a indagare insieme a Haggard. Trovai queste pagine infangate, ma non riuscimmo mai a collegare la calligrafia a quel pazzo nel bosco. Le prove che hai raccolto dimostrano la sua colpa. Porta questa a Commander Ebonlocke subito e raccontale quel che hai scoperto!",
  obj = "Porta la pagina infangata a Commander Ebonlocke.",
  progress = "Sarà meglio che sia importante, $C. Fammi vedere cos'hai e raccontami la tua storia. Ma per la Luce, fa' in fretta. La difesa di Darkshire è la mia priorità numero uno. Non ho tempo da sprecare in piste che non portano a niente.",
  reward = "Però, hai dimostrato di essere $Gun bel detective:una bella detective;, $C.",
  en_title = "The Legend of Stalvan",
  en_obj = "Take the muddy page to Commander Ebonlocke.",
}
T[80] = {
  title = "La leggenda di Stalvan",
  desc = "Quel viscido di Stalvan lo tengo d'occhio da parecchio. Ma se questa pagina è stata scritta dalla stessa mano, la sua colpa è provata al di là di ogni dubbio.$B$BIn tutti i suoi anni a tenere il Town Registry, Clerk Daltry è diventato un esperto nel riconoscere le calligrafie. Mostragli questa pagina e vedi se la scrittura corrisponde a quella della firma sul registro.",
  obj = "Mostra la Bloodstained Journal Page a Clerk Daltry.",
  progress = "Di nuovo qui, $N? Cos'hai questa volta?",
  reward = "Ma certo! La scrittura di questa pagina corrisponde davvero a quella delle firme sul registro.",
  en_title = "The Legend of Stalvan",
  en_obj = "Show Clerk Daltry the Bloodstained Journal Page.",
}
T[83] = {
  title = "Merci di lino rosso",
  desc = "I Defias di Northshire portano maschere di tela di sacco, ma quelli di Elwynn indossano del lino che posso usare per confezionare ottime merci.$B$BPortami delle bandane di lino rosso e le userò per creare qualcosa per te.$B$BI Defias hanno accampamenti sparsi per tutta Elwynn.",
  obj = "Porta 6 Red Linen Bandanas a Sara Timberlain all'Eastvale Logging Camp.",
  progress = "Sto finendo il lino, $N. Ne hai un po' per me?",
  reward = "Ah, belle bandane, anche se un po' grezze...$B$BEcco a te!",
  en_title = "Red Linen Goods",
  en_obj = "Bring 6 Red Linen Bandanas to Sara Timberlain at the Eastvale Logging Camp.",
}
T[84] = {
  title = "Di nuovo da Billy",
  desc = "Tieni. E quando darai questa torta a quel Billy, digli che spero gli vada di traverso!",
  obj = "Porta la Pork Belly Pie a Billy Maclure ai Maclure Vineyards.",
  progress = "Uff... Sto morendo di fame! Hai quella torta per me, $N?",
  reward = "Mmm, che bontà! Questa torta è la migliore!$B$BCredo che la memoria mi stia tornando...",
  en_title = "Back to Billy",
  en_obj = "Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards.",
}
T[85] = {
  title = "La collana perduta",
  desc = "Ho perso la mia collana e credo che quel monello di Billy Maclure l'abbia presa! Di solito se ne va in giro come un topo per i vigneti Maclure, a est di qui.$B$BRiportami la collana e scalderai il cuore di una vecchia vedova.",
  obj = "Parla con Billy Maclure.",
  reward = "Hai perso cosa? Be', io nessuna collana non l'ho presa, perché non sono mica un ladro!$B$BForse so chi è stato, però... <sorride>... ho troppa fame per ricordare.",
  en_title = "Lost Necklace",
  en_obj = "Speak with Billy Maclure.",
}
T[86] = {
  title = "Una torta per Billy",
  desc = "Forse se avessi una torta potrei dirti chi ha quella collana. E sai, credo che quella vecchia signora, Bernice, all'altra fattoria faccia delle ottime Pork Belly Pie... $B$BForse se le portassi dei pezzi di carne di cinghiale, presi dai cinghiali che bazzicano le nostre fattorie, e le dicessi a cosa servono, ti cucinerebbe una torta.",
  obj = "Porta 4 Chunks of Boar Meat ad Auntie Bernice Stonefield alla Stonefield's Farm.",
  progress = "Non mi pare giusto dare da mangiare al ragazzo che mi ha rubato la collana, ma se serve a riavere ciò che è mio, e sia!$B$BHai quella carne di cinghiale?",
  reward = "La carne di cinghiale selvatico è dura, ma se la fai sobbollire a lungo ne viene fuori una torta saporitissima!",
  en_title = "Pie for Billy",
  en_obj = "Bring 4 Chunks of Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm.",
}
T[87] = {
  title = "Goldtooth",
  desc = "Stavo giocando vicino alla Fargodeep Mine e credo di aver lasciato cadere, ehm... cioè, di aver visto, la collana della vecchietta. Non chiedermi come c'è finita... non sono stato io!$B$BComunque, ho visto un grosso kobold dal dente d'oro raccogliere la collana e scappare dentro la miniera. Trova quel kobold e troverai la collana, lo giuro!",
  obj = "Porta la Bernice's Necklace ad \"Auntie\" Bernice Stonefield alla Stonefield Farm.",
  progress = "Salute, $N. Hai trovato la mia collana?",
  reward = "Oh, l'hai trovata! Grazie, grazie, caro!$B$BTieni, prendi questo. Era di mio marito e diceva sempre che portava fortuna. Peccato che se lo sia dimenticato durante la sua ultima campagna! *sniff*",
  en_title = "Goldtooth",
  en_obj = "Bring Bernice's Necklace to \"Auntie\" Bernice Stonefield at the Stonefield Farm.",
}
T[88] = {
  title = "La principessa deve morire!",
  desc = "I Brackwell hanno un maiale da premio, Princess. La scrofa è ENORME, e lo è diventata sgattaiolando qui a mangiarsi le mie verdure!$B$BQuindi, prima che arrivi nei nostri campi... Princess deve morire! Portami il suo collare come prova dell'impresa e ti darò qualcosa per il disturbo!$B$BPrincess di solito sta al Brackwell Pumpkin Patch, a est, oltre la fattoria dei Maclure. Prendila prima che le torni fame e venga qui!",
  obj = "Uccidi Princess, prendi il suo collare, poi riportalo a Ma Stonefield alla Stonefield Farm.",
  progress = "L'hai già vista? L'hai presa?",
  reward = "Grazie al cielo! Quel maiale stava diventando così grosso che si sarebbe mangiato tutto il raccolto! Grazie, $N.$B$BOra, qualcuna di queste cose fa al caso tuo?",
  en_title = "Princess Must Die!",
  en_obj = "Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm.",
}
T[89] = {
  title = "L'Everstill Bridge",
  desc = "Durante l'ultima invasione orchesca siamo stati costretti a fondere il nostro ferro per farne proiettili, spade e armature. Abbiamo mandato a chiedere a Stormwind un nuovo carico di materiali, ma una banda di gnoll di Redridge ha dirottato la carovana ed è fuggita sulle colline dietro Lakeshire.$B$BOra ci mancano le scorte per ricostruire questo ponte. Se mi porti 5 Iron Pikes e 5 Iron Rivets, $N, farò in modo che tu sia ricompensat$Go:a;. $B$BE ora mettiamoci al lavoro!",
  obj = "Porta 5 Iron Pikes e 5 Iron Rivets a Foreman Oslow a Lakeshire.",
  progress = "Questo ponte non si costruirà da solo! Allora, dove sono quelle Iron Pikes e quei Iron Rivets?",
  reward = "Ottimo lavoro, $N. Queste scorte aiuteranno enormemente i lavori al ponte. Rimetteremo in piedi questa meraviglia in un battibaleno.",
  en_title = "The Everstill Bridge",
  en_obj = "Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire.",
}
T[90] = {
  title = "Seasoned Wolf Kabobs",
  desc = "I Seasoned Wolf Kabob sono il piatto forte della casa! Certo che posso fartene un po'. Ma prima mi servono gli ingredienti. Portami 10 Lean Wolf Flank e delle Stormwind Seasoning Herbs. Di lupi qui nella foresta ce ne sono tanti, di sicuro trovare i Flank non sarà un problema. Per le erbe, cerca Felicia Gump nel suo negozio di fiori nel quartiere dei canali di Stormwind.",
  obj = "Raccogli 10 Lean Wolf Flank e le Stormwind Seasoning Herbs, poi torna da Chef Grual, a Darkshire.",
  progress = "Sei già $Griuscito:riuscita; a trovare 10 Lean Wolf Flank? E le erbe da Felicia, a Stormwind?",
  reward = "Ottimo lavoro, $N! Goditi la prelibatezza chiamata Seasoned Wolf Kabob!",
  en_title = "Seasoned Wolf Kabobs",
  en_obj = "Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire.",
}
T[91] = {
  title = "La legge di Solomon",
  desc = "Un nemico di Stormwind si è stabilito nelle colline orientali di Redridge. Questo malvagio criminale usa l'Arcano per diffondere terrore e miseria sul nostro paese e sulla nostra gente. Conduce i suoi affari immondi sotto il nome di Morganth.$B$BMorganth ora controlla lo Shadowhide Gnoll Clan e lo usa per i suoi voleri. Come stabilito dalla legge di Lakeshire, aiutare un criminale del Regno è punibile con la morte.$B$BQuesti gnoll ignobili vanno uccisi!$B$BConsegnami 10 Shadowhide Pendant e sarai $Gricompensato:ricompensata;.",
  obj = "Porta 10 Shadowhide Pendant a Bailiff Conacher, nel Lakeshire Town Hall.",
  progress = "Consegnami 10 Shadowhide Pendant e sarai $Gricompensato:ricompensata;.",
  reward = "La Corte di Lakeshire riconosce il tuo impegno per la giustizia, $N. Facendo rispettare le leggi del Regno hai contribuito a difendere la giustizia di questa terra.",
  en_title = "Solomon's Law",
  en_obj = "Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.",
}
T[92] = {
  title = "Goulash di Redridge",
  desc = "Niente mi farebbe più piacere che prepararti un Redridge Goulash. Ma c'è un piccolo problema. Durante la recente rivolta degli orchi ho sfamato un'intera brigata di truppe di Stormwind. Ora la mia dispensa è vuota. Ma se mi procuri gli ingredienti, sarò lieto di accontentarti.$B$BPortami cinque pezzi di Tough Condor Meat, cinque Great Goretusk Snouts e cinque porzioni di Crisp Spider Meat.",
  obj = "Chef Breanna di Lakeshire vuole cinque pezzi di Tough Condor Meat, cinque Great Goretusk Snouts e cinque porzioni di Crisp Spider Meat.",
  progress = "Mi servono ancora cinque pezzi di Tough Condor Meat, cinque Great Goretusk Snouts e cinque porzioni di Crisp Spider Meat.",
  reward = "Ben fatto, $N. E che splendidi esemplari! Ed ecco la deliziosa prelibatezza nota come Redridge Goulash!",
  en_title = "Redridge Goulash",
  en_obj = "Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.",
}
T[93] = {
  title = "Dusky Crab Cakes",
  desc = "Ti svelo un piccolo segreto: le Dusky \"Crab\" Cakes sono fatte in realtà con zampe di ragno! So che è un po' disgustoso, ma le frittelle hanno un sapore piccante e sono ottimi spuntini! Portami delle Gooey Spider Legs e te ne preparo qualcuna.$B$BSento dire che i Venom Web Spiders siano una buona fonte: nidificano a nord, tra le colline e il fiume. ",
  obj = "Raccogli 6 Gooey Spider Legs e portale a Chef Grual a Darkshire.",
  progress = "Salute, $N. Hai già preso quelle Gooey Spider Legs?",
  reward = "Ah sì, una bella nidiata di zampe, la tua! Fammele condire con le mie spezie segrete (non guardare!) e farle sfrigolare un po' in padella...$B$BE, anche se le Dusky Crab Cakes sono la mia specialità e non svelerò la ricetta, ecco la ricetta di un piatto che è quasi altrettanto buono.",
  en_title = "Dusky Crab Cakes",
  en_obj = "Gather 6 Gooey Spider Legs and bring them to Chef Grual in Darkshire.",
}
T[94] = {
  title = "Un occhio vigile",
  desc = "Il mio rivale, Morganth, è un mago malvagio di grande potere che vive nella Tower of Ilgalar, a Redridge. Ho messo a punto un modo per spiarlo, l'Eye of Azora, e ora posso osservarlo da lontano.$B$BMa per studiare i suoi pensieri... mi serve altro aiuto.$B$BSe te la senti, porta il mio Glyph of Azora alla Tower of Ilgalar. Posalo sulla Lion Statue vicino alla torre.$B$BQuando sarà fatto, il potere di Azora concederà visioni dei piani futuri di Morganth.",
  obj = "Porta il Glyph of Azora alla Lion Statue vicino alla Tower of Ilgalar, a Redridge.",
  progress = "Questa Lion Statue sta qui da decenni, e fa la guardia solitaria alla famigerata Tower of Ilgalar.$B$BAlla base della statua c'è un incavo, dove si potrebbe incastonare una gemma o un glifo...",
  reward = "Posi il Glyph of Azora sulla pietra. Aderisce da solo... e da esso senti la voce incorporea di Theocritus:$B$BTi sono grato, giovane $N. Ora puoi parlarmi attraverso questo glifo, e potrei avere altri incarichi per te... dopo aver sondato i pensieri del mio rivale.",
  en_title = "A Watchful Eye",
  en_obj = "Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge.",
}
T[95] = {
  title = "La vendetta di Sven",
  desc = "Un tempo lavoravo una delle fattorie a sud-est... finché i Dark Rider del Deadwind Pass non piombarono sulla mia fattoria e massacrarono la mia famiglia mentre ero via!$B$BAl mio ritorno vidi una figura in ombra aggirarsi furtiva vicino al fienile, mentre seppelliva qualcosa. Fuggì prima che potessi prenderlo, e non potevo attardarmi perché ero alle calcagna dei Dark Rider. Così non ho mai scoperto cosa fosse nascosto.$B$BSe riesci a trovare quel che quella figura ha seppellito, te ne sarei grato. Il nascondiglio è dietro il vecchio ceppo vicino al fienile.",
  obj = "Va' a Sven's Farm e trova cosa è stato sepolto dietro il vecchio ceppo.",
  reward = "Qui c'è un cumulo di terra, ammucchiato in fretta come se qualcuno avesse avuto bisogno di nascondere qualcosa... senza molto tempo per farlo.",
  en_title = "Sven's Revenge",
  en_obj = "Go to Sven's Farm and find what was buried behind the old stump.",
}
T[96] = {
  title = "Il richiamo dell'acqua",
  desc = "Prendi frammento. Prendi frammento e dai vita.$B$BDai vita e capisci. Capisci che acqua è vita... corruzione ferma vita.$B$BTu proteggi e dai vita con potere di acqua.",
  obj = "Porta lo Shard of Water a Islen Waterseer, nelle Barrens.",
  progress = "Sei $Gtornato:tornata;. Splendido!$B$BCom'è andato il tuo viaggio a Silverpine? Ci hai messo molto?$B$BÈ difficile per me capire se laggiù hai avuto successo, perché gran parte di quella terra è ormai corrotta. Il suo fetore soffoca qualunque bene tu possa aver fatto. Ma i piccoli successi a volte sono importanti quanto quelli grandi. Purificare l'acqua laggiù è stato fondamentale per te, e per tutti gli sciamani.",
  reward = "Questa è la prova che ti avevo chiesto. Hai fatto bene, $N.$B$BSono lieta di essere la prima a congratularmi con te e a darti questo... il tuo Water Totem.$B$BUsalo bene, e buona fortuna.$B$BLa tua prossima prova non arriverà prima di un po' di tempo, quindi impara bene le tue lezioni. L'acqua pura non solo ridà la vita a chi è ferito, ma può avere molti altri effetti. Ti consiglio di cercare un istruttore di sciamani quando hai tempo. Potrebbe avere altri incantesimi da insegnarti.",
  en_title = "Call of Water",
  en_obj = "Bring the Shard of Water to Islen Waterseer in the Barrens.",
}
T[97] = {
  title = "La leggenda di Stalvan",
  desc = "Fa' sapere subito a Commander Ebonlocke che la calligrafia corrisponde, $N! I suoi sospetti erano giusti!",
  obj = "Riporta la notizia a Commander Ebonlocke.",
  progress = "Sì, $N?",
  reward = "Lo sapevo! Ottimo lavoro, $N.",
  en_title = "The Legend of Stalvan",
  en_obj = "Report the news to Commander Ebonlocke.",
}
T[98] = {
  title = "La leggenda di Stalvan",
  desc = "Stalvan Mistmantle ha condotto una vita di depravazione. Vittime innocenti sono morte per mano sua. È senza dubbio colpevole di innumerevoli delitti. Ora quel folle minaccia Darkshire. Solo la Luce sa che atti sordidi stia tramando. Va' al suo cottage appena a nord del paese, $C, e giustizia Stalvan, una volta per tutte.$B$BQuando sarà fatto, va' da Madame Eva e mostrale il suo anello di famiglia. In fondo è stata la sua premonizione a portare a questa scoperta raccapricciante. Ma grazie a lei Darkshire è più sicura.",
  obj = "Uccidi Stalvan Mistmantle e mostra a Madame Eva il suo anello di famiglia.",
  progress = "Sì, $N?",
  reward = "Lo so, $N: Stalvan è morto. Ho sentito un'onda di speranza attraversare la foresta corrotta. Una volta per tutte, Duskwood è libera dalla sua sete di sangue. La mia gioia è offuscata dal pensiero di chi è caduto preda di quella bestia orribile. Ciò nonostante, sei $Gun:una; $C $Gcoraggioso:coraggiosa; e $Gastuto:astuta;.",
  en_title = "The Legend of Stalvan",
  en_obj = "Kill Stalvan Mistmantle and show Madame Eva his family ring.",
}
T[99] = {
  title = "La follia di Arugal",
  desc = "Più cresce la mia comprensione della magia di Arugal, più cresce il mio disprezzo per quello sciagurato. Sono vicino a completare la mia ricerca sul suo cosiddetto rimedio.$B$BLa mia conoscenza sarà completa quando scoprirò quale incantesimo causa lo strano fenomeno di Pyrewood Village. Di giorno i contadini sembrano Umani. Ma quando il sole tramonta gli abitanti si trasformano in Moonrage Worgen.$B$BDevo trarre energia dalle catene incantate che Arugal ha lanciato su di loro. Portami sei Pyrewood Shackles incantate, $N.",
  obj = "Porta 6 Pyrewood Shackles a Dalar Dawnweaver al Sepulcher.",
  progress = "Hai già recuperato le Pyrewood Shackles, $N?",
  reward = "La tua perseveranza è lodevole. Con la conoscenza che mi hai aiutato a raccogliere, Arugal cadrà e la sua magia sconsiderata sarà disfatta. Salute a te, $N.",
  en_title = "Arugal's Folly",
  en_obj = "Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher.",
}
T[100] = {
  title = "Il richiamo dell'acqua",
  desc = "Mentre pronunci le ultime parole della formula, esplode un lampo di luce. Il suono delle gocce d'acqua che colpiscono la fiamma si è spento, e i tuoi sensi vengono sopraffatti mentre gli spiriti corrotti intorno a te vengono distrutti.",
  obj = "Parla con la Minor Manifestation of Water, nella Silverpine Forest.",
  reward = "Grazie a te. Grazie agli sciamani.$B$BLa corruzione si ritira, ma la vita continua a spegnersi. Tocca a sciamani proteggere vita.",
  en_title = "Call of Water",
  en_obj = "Speak to the Minor Manifestation of Water in Silverpine Forest.",
}
T[101] = {
  title = "Il Totem of Infliction",
  desc = "Mentre la corruzione mistica si insinua nella foresta, il bisogno di proteggersi è innegabile, $N. I venti mi sussurrano e parlano di un grande pericolo che ti attende paziente nel prossimo futuro.$B$BSe vuoi proteggerti, nobile $C, portami 10 Ghoul Fang, 10 Skeleton Finger e 5 Vial of Spider Venom. Per te incanterò un Totem of Infliction che ferirà chi tenta di farti violenza.",
  obj = "Porta 10 Ghoul Fang, 10 Skeleton Finger e 5 Vial of Spider Venom a Madame Eva, a Darkshire.",
  progress = "Portami 10 Ghoul Fang, 10 Skeleton Finger e 5 Vial of Spider Venom. Per te incanterò un Totem of Infliction che ferirà chi tenta di farti violenza.",
  reward = "Molto saggio da parte tua, $N. Questo Totem of Infliction ti aiuterà a proteggerti dal male che si annida per tutta Azeroth e oltre. Quando ti senti $Gminacciato:minacciata;, stringi questo totem e trova conforto nella sua aura magica. Sii $Gcoraggioso:coraggiosa;, gentile $C. Ti servirà tutto il coraggio che riesci a raccogliere, perché vedo molto sangue nel tuo futuro.",
  en_title = "The Totem of Infliction",
  en_obj = "Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire.",
}
T[102] = {
  title = "Pattugliare Westfall",
  desc = "Stormwind ci ha abbandonati. Un vento fetido di depravazione soffia sulle pianure di Westfall. Questa era la mia terra natale e non volterò le spalle ai cittadini che hanno scelto di restare. Noi, gli ex contadini, faremo la nostra resistenza.$B$BIl tuo compito, se vorrai accettarlo, è pattugliare le praterie di Westfall. Rintraccia e uccidi i vili Gnoll che sembrano collaborare con i ladri delle Deadmines. Portami otto Gnoll Paws e ricompenserò il tuo coraggio.",
  obj = "Porta 8 Gnoll Paws a Captain Danuvin a Sentinel Hill.",
  progress = "Hai già raccolto 8 zampe da quei Gnoll traditori?",
  reward = "Ben fatto, $N. Con valorosi avventurieri come te che combattono al fianco della People's Militia, Westfall potrebbe tornare a essere il prospero granaio che era un tempo. Accetta questo in riconoscimento dei tuoi instancabili sforzi.",
  en_title = "Patrolling Westfall",
  en_obj = "Bring 8 Gnoll Paws to Captain Danuvin on Sentinel Hill.",
}
T[103] = {
  title = "Custode della fiamma",
  desc = "La notte in cui la famiglia del Guardiano del Faro morì fu orribile. Guardai, impotente, Old Murk-Eye guidare l'attacco. Ma quel che è fatto è fatto, e ora la mia preoccupazione va alle vite dei marinai del Great Sea le cui navi si avvicinano alle pericolose rocce della costa. Poiché nessuno veglia sulla fiamma, la responsabilità è ricaduta su di me.$B$BAiutami a mantenere accesa la torcia portandomi 5 fiaschi d'olio dagli Harvest Monsters.",
  obj = "Porta 5 Flasks of Oil a Captain Grayson al Westfall Lighthouse.",
  progress = "La fiamma non brucerà a lungo senza olio, $N.",
  reward = "Sia lode a te, valoroso $C. Le rocce della Westfall Coast saranno illuminate grazie al tuo duro lavoro. Molte vite saranno risparmiate finché la torcia resterà accesa.$B$BIo sono morto inutilmente su questa stessa riva. La pena della mia vita ultraterrena è fare in modo che nessun altro segua il mio destino.",
  en_title = "Keeper of the Flame",
  en_obj = "Bring 5 Flasks of Oil to Captain Grayson at the Westfall Lighthouse.",
}
T[104] = {
  title = "La minaccia costiera",
  desc = "Quando la mia vita si spezzò sugli scogli, non avevo idea di cosa mi attendesse nell'aldilà. Quella notte il Faro era buio perché Old Murk-Eye aveva messo in fuga la famiglia del guardiano. Tornarono e riaccesero la fiamma, ma Old Murk-Eye costrinse i murloc più deboli di mente ad assaltare di nuovo il Faro con lui. La seconda volta la famiglia non ebbe la stessa fortuna e sotto i miei occhi perì, impotente.$B$BUccidi Old Murk-Eye se lo vedi lungo la riva e portami una delle sue squame: ti ricompenserò.",
  obj = "Porta una squama di Old Murk-Eye a Captain Grayson al Westfall Lighthouse.",
  progress = "Hai già annientato la minaccia nota come Old Murk-Eye? È stato avvistato aggirarsi lungo la costa di Westfall.$B$BTorna da me quando la sozza bestia sarà morta.",
  reward = "Dunque il sozzo miscredente, Murk-Eye, è morto. Ben fatto, $N. Per mano tua una vita ha trovato riposo, ma forse molte altre sono state salvate. Il Great Sea, colmo di pericoli com'è, sarà un po' più sicuro questa notte grazie alle tue gesta.",
  en_title = "The Coastal Menace",
  en_obj = "Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.",
}
T[106] = {
  title = "Giovani amanti",
  desc = "Oh, sono maledetta! Il mio cuore appartiene a Tommy Joe Stonefield, ma le nostre famiglie sono nemiche giurate. Così non posso vederlo, anche se i miei occhi bramano quel bel volto!$B$BTi prego, prendi questa lettera e consegnala a Tommy Joe. Di solito si trova al fiume, a ovest della Stonefield Farm, che è proprio a ovest di qui.",
  obj = "Consegna la Maybell's Love Letter a Tommy Joe Stonefield.",
  progress = "Hai cosa?? Maybell è la luce della mia grigia esistenza. Presto, fammi vedere la sua lettera!",
  reward = "Ah! Non sopporto di starle lontano. Devo vederla!!",
  en_title = "Young Lovers",
  en_obj = "Give Maybell's Love Letter to Tommy Joe Stonefield.",
}
T[107] = {
  title = "Un messaggio per William",
  desc = "Scommetto che William Pestle ha una pozione per riunire i nostri due giovani amanti!$B$BEcco, porta questo messaggio a William. Alloggia alla Lion's Pride Inn a Goldshire.",
  obj = "Porta il messaggio di Gramma Stonefield a William Pestle.",
  progress = "Hai un messaggio della \"nonna\" Stonefield, eh? Non vedo Mildred da anni! Chissà cosa avrà da dirmi...",
  reward = "Il mio cuore è con quei due poveretti, Maybell e Tommy Joe. Ricordo di essere stato giovane e innamorato, un tempo.$B$BDeve esserci qualcosa che posso fare per aiutarli! Fammi pensare...",
  en_title = "Note to William",
  en_obj = "Take Gramma Stonefield's Note to William Pestle.",
}
T[109] = {
  title = "Presentati a Gryan Stoutmantle",
  desc = "A quanto vedo, $c, hai affrontato parecchi combattimenti nella tua vita. Se non l'hai ancora fatto, dovresti presentarti a Gryan Stoutmantle. Guida la People's Militia, che difende le terre coltivate di Westfall. Scommetto che il tuo aiuto gli farebbe comodo. Di solito lo trovi nella torre di pietra a Sentinel Hill, poco fuori dalla strada, nel cuore di Westfall.",
  obj = "Parla con Gryan Stoutmantle. Di solito si trova nella torre di pietra a Sentinel Hill, poco fuori dalla strada, nel cuore di Westfall.",
  reward = "Ah, quindi un mio amico ti ha mandato qui? Che gentile.$B$BLa monarchia di Stormwind ha abbandonato la nostra causa. Ora spetta alla People's Militia mantenere questa terra libera dalla corruzione. Se la nostra causa ti interessa, posso mettere le tue abilità in battaglia al servizio della libertà.",
  en_title = "Report to Gryan Stoutmantle",
  en_obj = "Talk to Gryan Stoutmantle.  He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall.",
}
T[111] = {
  title = "Parla con la nonna",
  desc = "Ti prego, $N, parla con mia nonna. Se qualcuno può trovare un modo per farmi stare con Maybell, è lei.$B$BÈ nella nostra casa, a est di qui.",
  obj = "Parla con Gramma Stonefield.",
  progress = "Non vedo l'ora di sentire come reagiranno i miei amici!$B$BNon se lo aspetteranno mai.",
  reward = "Finché le nostre famiglie sono in lite, Tommy Joe e Maybell non hanno molto futuro, ma... forse possiamo farli incontrare almeno per un po'.$B$BMh, cosa possiamo fare...",
  en_title = "Speak with Gramma",
  en_obj = "Speak with Gramma Stonefield.",
}
T[112] = {
  title = "Raccolta di alghe",
  desc = "Posso preparare un liquore dell'invisibilità per Maybell, così potrà sgattaiolare via dai Maclure Vineyards e raggiungere Tommy Joe. Ma per prepararlo mi servono delle alghe di cristallo.$B$BDi solito crescono nell'oceano... ma a volte i murloc le raccolgono. Vedi se quelli vicino a Crystal Lake ne hanno. Crystal Lake si trova subito a est di Goldshire.",
  obj = "Porta 4 Crystal Kelp Fronds a William Pestle a Goldshire.",
  progress = "Hai le alghe di cristallo? Sono certo che Maybell non vede l'ora di rivedere il suo bello...",
  reward = "Le hai trovate. Ottimo lavoro! Ora, un attimo soltanto mentre preparo la pozione...",
  en_title = "Collecting Kelp",
  en_obj = "Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire.",
}
T[114] = {
  title = "La fuga",
  desc = "Porta questo liquore dell'invisibilità alla giovane Maybell. Dovrebbe durare abbastanza da permetterle di far visita a Tommy Joe.",
  obj = "Porta l'Invisibility Liquor a Maybell Maclure.",
  progress = "Hai consegnato la mia lettera a Tommy Joe? Cos'ha detto??",
  reward = "Oh... cielo! Mi sento in colpa a ingannare la mia famiglia, ma i miei sentimenti per Tommy Joe sono troppo forti per essere ignorati.$B$BGrazie, $N. Berrò questo liquore appena ne avrò l'occasione e fuggirò dal mio amore.$B$BE per te... ti prego, accetta questo.",
  en_title = "The Escape",
  en_obj = "Take the Invisibility Liquor to Maybell Maclure.",
}
T[115] = {
  title = "Magia delle ombre",
  desc = "Gli orchi Blackrock hanno arruolato degli shadowcaster per sostenere i loro attacchi a Redridge, e si sono portati dietro strumenti di potere oscuro: i Midnight Orb. Questi orbi hanno inferto colpi pesanti ai difensori di Redridge, ed è indispensabile togliere dal conflitto questi oggetti corrotti dai demoni.$B$BTrova e portami i Midnight Orb degli shadowcaster Blackrock che avrai ucciso. Li farò distruggere: questo mondo sarebbe un posto migliore senza di loro!",
  obj = "Porta 3 Midnight Orb a Marshal Marris, a Lakeshire.",
  progress = "Come va lo scontro con gli shadowcaster? Li hai trovati i Midnight Orb?",
  reward = "Grazie, $N. Li manderò subito a distruggere.",
  en_title = "Shadow Magic",
  en_obj = "Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.",
}
T[116] = {
  title = "Tempi di siccità",
  desc = "Mi trovo in un bel guaio, $N. Le bottiglie stanno per finire. La spedizione di alcolici è in ritardo da tempo. L'invasione degli orchi è stata un inferno.$B$BForse puoi lavorare per me?$B$BDevi ritirare un barile di Thunderbrew Lager da Grimbooze Thunderbrew sulle colline di Westfall, una botte di Merlot a Stormwind, una bottiglia di Moonshine a Darkshire e un otre di Sweet Rum a Goldshire. Portameli e farò in modo che tu sia ricompensat$Go:a;.",
  obj = "Barkeep Daniels di Lakeshire ha bisogno di un barile di Thunderbrew Lager, una botte di Merlot, una bottiglia di Moonshine e un otre di Sweet Rum.",
  progress = "Devi ritirare un barile di Thunderbrew Lager da Grimbooze Thunderbrew sulle colline di Westfall, una botte di Merlot a Stormwind, una bottiglia di Moonshine a Darkshire e un otre di Sweet Rum a Goldshire. Portameli e farò in modo che tu sia ricompensat$Go:a;.",
  reward = "Un lavoro ben fatto, $N! So bene quali strade hai dovuto percorrere per procurare questa splendida scorta di liquori. Ma i miei clienti saranno di nuovo felici! $B$BMia moglie è una brava sarta. Ti prego di accettare questo mantello che ha cucito, in cambio dei tuoi servigi.",
  en_title = "Dry Times",
  en_obj = "Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum.",
}
T[117] = {
  title = "Thunderbrew Lager",
  desc = "Presto, amico mio, muoviti in fretta $BPerché la nostra ricca birra abbia il gusto $BPiù di birra e meno di stufato, $BServe il luppolo per prepararla.",
  obj = "Porta 5 luppoli a Grimbooze Thunderbrew per completare la sua birra speciale.",
  progress = "Presto, amico mio, muoviti in fretta $BPerché la nostra ricca birra abbia il gusto $BPiù di birra e meno di stufato, $BServe il luppolo per prepararla.",
  reward = "Luppolo e orzo, lievito e malto $BLe papille assaporano un vero assalto, $BNon serve implorare, non serve pregare $BLa Thunderbrew Lager arriva in barile!",
  en_title = "Thunderbrew Lager",
  en_obj = "Bring Grimbooze Thunderbrew 5 hops to complete his special brew.",
}
T[118] = {
  title = "Il prezzo dei ferri",
  desc = "Ho usato così tanto ferro per equipaggiare le guardie di Stormwind che non me ne resta abbastanza per ferrare i cavalli della stalla!$B$BPorta questo messaggio a Blacksmith Argus a Goldshire. Gli spiega il mio problema e richiede una fornitura di ferri di cavallo.",
  obj = "Porta il messaggio di Verner a Smith Argus a Goldshire.",
  progress = "Come? Ti manda Verner, dici? Allora dammi il suo messaggio. E PARLA PIÙ FORTE!",
  reward = "Eh, quindi il vecchio Verner ha bisogno di ferri, eh!?!",
  en_title = "The Price of Shoes",
  en_obj = "Take Verner's Note to Smith Argus in Goldshire.",
}
T[119] = {
  title = "Ritorno da Verner",
  desc = "Va bene, gli darò i suoi 50 ferri di cavallo...$B$BEcco qui, tutti imballati e pronti a partire! Digli che è stato un piacere fare affari, e assicurati che legga il messaggio attaccato a questa cassa!",
  obj = "Torna da Verner Osgood a Redridge. Consegnagli la Crate of Horseshoes.",
  progress = "Ottimo, sei tornat$Go:a;! Hai preso i ferri?",
  reward = "Grazie, mi sei di grande aiuto.$B$BMa cos'è questo? Argus ha mandato un messaggio con la cassa... Cosa?? Argus vuole che lo PAGHI? Bah!$B$BBene, $N, grazie per il tuo aiuto.",
  en_title = "Return to Verner",
  en_obj = "Return to Verner Osgood in Redridge.  Give him the Crate of Horseshoes.",
}
T[120] = {
  title = "Messaggero per Stormwind",
  desc = "Sono tempi duri, $c. Il villaggio è sotto assedio costante. Senza rinforzi, subiremo di certo la sconfitta. Il messaggio che sto per affidarti è della massima importanza. Porta questo rapporto al General Marcus Jonathan a Stormwind, immediatamente. Una volta consegnato, torna subito da me con le notizie, buone o cattive che siano. $B$BOra sbrigati!",
  obj = "Magistrate Solomon ti ha affidato un rapporto che deve essere consegnato al General Marcus Jonathan a Stormwind. Il giudice vuole che tu torni da lui non appena la consegna sarà completata.",
  progress = "Cos'hai lì?",
  reward = "Riposo, $C.$B$BMagistrate Solomon è un nobile condottiero. Le sue parole hanno grande peso per me. Chiederò consiglio al Re e gli esporrò chiaramente la situazione. Assicura al buon giudice che ha il sostegno dell'esercito di Stormwind. I rinforzi saranno inviati non appena Sua Maestà darà l'ordine.",
  en_title = "Messenger to Stormwind",
  en_obj = "Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind.  The judge wants you to return to him as soon as the delivery has been made.",
}
T[121] = {
  title = "Messaggero per Stormwind",
  desc = "Mentre attendo la risposta del Re, voglio che tu porti questa lettera al Magistrate Solomon. $B$BPuoi andare, $c!",
  obj = "Porta la lettera di risposta del General Marcus Jonathan al Magistrate Solomon a Lakeshire.",
  progress = "Il Generale ha mandato notizie? I rinforzi sono in arrivo?",
  reward = "Grazie per il tuo tempo, $C. Per il tuo servizio a Lakeshire e a Stormwind ti ricompenso con queste monete.$B$BOra, se vuoi scusarmi, trovo questa corrispondenza piuttosto misteriosa. C'è qualcosa che non va nel nostro Regno. Temo che questo sia l'inizio del conflitto, non la fine.",
  en_title = "Messenger to Stormwind",
  en_obj = "Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire.",
}
T[122] = {
  title = "Scaglie del ventre",
  desc = "Mi servono delle scaglie del ventre dei draghetti neri per pagare i ferri che Argus mi ha mandato da Goldshire. Se me ne porti 6, potrò pagare Argus con alcune... e me ne resteranno abbastanza per forgiare qualcosa anche per te.$B$BI draghetti neri volano spesso a sud di Lakeshire, ma amano vagare. Forse dovrai tenere gli occhi aperti e cacciarli quando li vedi.",
  obj = "Raccogli 6 Underbelly Whelp Scales dai Black Dragon Whelps e portale a Verner Osgood a Redridge.",
  progress = "So che quell'avido di Argus manderà qualcuno a riscuotere le sue scaglie se non gliele do presto. Hai trovato quelle scaglie?",
  reward = "Grazie! Con queste uscirò dai debiti con Argus...",
  en_title = "Underbelly Scales",
  en_obj = "Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.",
}
T[123] = {
  title = "Il Collettore",
  desc = "Questa nota è un calendario con un elenco di giorni e orari in cui una persona, descritta soltanto come \"il Collettore\", riceverà una spedizione d'oro dalle miniere di Elwynn Forest.$B$BDal calendario sembra che il Collettore risieda vicino al Brackwell Pumpkin Patch, nell'Elwynn orientale.$B$BSembra importante. Dovresti riferirlo a Marshal Dughan a Goldshire.",
  obj = "Vai da Marshal Dughan a Goldshire e consegnagli The Collector's Schedule.",
  progress = "Cosa?!? Non abbiamo gente che lavora nelle miniere di Elwynn da mesi!$B$BFammi vedere quella nota che hai...",
  reward = "Hm... ho sentito parlare di questo \"Collettore\", ma non so per chi lavori. Grazie per il calendario. Ci aiuterà a risolvere questo mistero.",
  en_title = "The Collector",
  en_obj = "Go to Marshal Dughan in Goldshire and give him The Collector's Schedule.",
}
T[124] = {
  title = "Un ululato di Gnoll",
  desc = "Come se gli orchi all'attacco non bastassero! Ora ho brutali gnoll e mistici che si aggirano lungo il crinale a nord della mia stalla, portandosi via i miei cavalli quando si allontanano...$B$BSe riesci a sbarazzarti di quegli gnoll, io e i miei cavalli te ne saremo molto grati.",
  obj = "Uccidi 10 Redridge Brutes e 8 Redridge Mystics, poi torna da Verner Osgood.",
  progress = "Sì? C'è qualcosa che posso fare per te?",
  reward = "Grazie per tutto il tuo aiuto, $N.",
  en_title = "A Baying of Gnolls",
  en_obj = "Kill 10 Redridge Brutes and 8 Redridge Mystics, then return to Verner Osgood.",
}
T[125] = {
  title = "Gli attrezzi perduti",
  desc = "Mi servirebbe proprio una mano, $N. Con la città sotto assedio, trovare rifornimenti è difficile. I miei attrezzi stavano arrivando da Goldshire in carro, ma il ponte è stato fatto saltare. Li abbiamo caricati su una barca, ma gli orchi l'hanno colpita con una catapulta. Che sfortuna: la mia cassetta è affondata dritta sul fondo del lago.$B$BRecupera la mia cassetta degli attrezzi, $N, e farò in modo che ne valga la pena.",
  obj = "Foreman Oslow di Lakeshire vuole che tu recuperi la sua cassetta degli attrezzi dal fondo di Lake Everstill.",
  progress = "Sei riuscit$Go:a; a trovare i miei attrezzi?",
  reward = "Un recupero eccellente, $N! Non pensavo che avrei rivisto questi attrezzi.",
  en_title = "The Lost Tools",
  en_obj = "Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill.",
}
T[126] = {
  title = "Ululati sulle colline",
  desc = "$N, gli gnoll sono ancora là fuori. Sento i loro latrati mentre cacciano sulle colline sopra Lakeshire. E un ululato è più forte degli altri: Yowler, il loro capo.$B$BUccidi Yowler e disperdi il suo branco! Portami la sua zampa come prova.$B$BE sta' $Gattento:attenta;: questo gnoll non è il loro capo per caso. Non è un Mongrel qualsiasi...",
  obj = "Porta Yowler's Paw a Verner Osgood, a Lakeshire.",
  progress = "Yowler è una creatura pericolosa, $N. Se non sei $Gpronto:pronta; ad affrontarlo, capisco.",
  reward = "Ancora una volta, grazie dell'aiuto. L'esercito di Stormwind è così impegnato con gli orchi che non ha truppe per proteggere Redridge dalle minacce locali come gli gnoll.",
  en_title = "Howling in the Hills",
  en_obj = "Bring Yowler's Paw to Verner Osgood in Lakeshire.",
}
T[127] = {
  title = "Vendere pesce",
  desc = "Il Lake Everstill è famoso per i suoi Spotted Sunfish. C'è sempre richiesta... e io sono a corto!$B$BPortamene una partita di 10 e te li pagherò bene. Se non sai pescare, allora... magari puoi prenderli dai murloc!",
  obj = "Porta 10 Spotted Sunfish a Dockmaster Baren, a Lakeshire.",
  progress = "Hai un po' di Spotted Sunfish per me, eh?",
  reward = "È un piacere fare affari con te, $Gcompagno:compagna;!",
  en_title = "Selling Fish",
  en_obj = "Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire.",
}
T[128] = {
  title = "Taglia sui Blackrock",
  desc = "Il Blackrock Clan va distrutto. Il Nemico ha invaso le nostre terre. Queste montagne ricadono sotto il diritto sovrano del Re di Stormwind. Le nostre fonti ci dicono che i capi di ogni unità del Clan sono chiamati Champion. Li trovi nel loro accampamento a nord, appena a ovest della strada per le Burning Steppes.$B$BMagistrate Solomon vuole morti questi bruti immondi. Uccidi 15 Blackrock Champion e torna da me.",
  obj = "Uccidi 15 Blackrock Champion e Guard Howe, a Lakeshire, ti ricompenserà.",
  progress = "Torna quando avrai ucciso 15 Blackrock Champion.",
  reward = "Vedo che hai combattuto valorosamente contro il Blackrock Clan, $C. Il tuo servizio alla nostra cittadina è davvero grande.",
  en_title = "Blackrock Bounty",
  en_obj = "Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.",
}
T[129] = {
  title = "Un pranzo gratis",
  desc = "Puoi farmi un favore? Ho preparato il pranzo per Guard Parker, ma è fuori in pattuglia... è una grossa e forte guardia di Stormwind, sa difendersi da solo, ma là fuori è troppo pericoloso per una semplice cittadina come me.$B$BSe gli consegni il pranzo e poi torni qui, ti darò un pranzo gratis! Parker pattuglia il tratto di strada che porta a Duskwood.",
  obj = "Porta il pranzo di Parker a Guard Parker. Pattuglia la strada che porta a Darkshire.",
  progress = "Darcy mi ha mandato il pranzo, dici? Che cuore gentile ha. Bene... vediamo che c'è!",
  reward = "Grazie, avevo proprio bisogno di un pasto. Difendere Lakeshire dagli orchi e dai gnoll è un lavoro duro!",
  en_title = "A Free Lunch",
  en_obj = "Bring Parker's lunch to Guard Parker.  He patrols the road leading to Darkshire.",
}
T[130] = {
  title = "Visita all'erborista",
  desc = "Prima di tornare da Darcy, puoi portarle dei fiori da parte mia? Li trovi alla bottega dell'erborista, a Lakeshire, all'estremità ovest della città.$B$BMa quando prendi i fiori... non dire all'erborista, Martie, da parte di chi sono, né per chi sono...",
  obj = "Parla con l'erborista di Redridge, Martie Jainrose.",
  reward = "Ti serve un mazzo di fiori? Non sei in città da molto... hai già trovato qui qualcuno da corteggiare?$B$BSo che non dovrei impicciarmi, ma è bello vedere che l'amore è nell'aria... soprattutto in tempi pericolosi come questi.",
  en_title = "Visit the Herbalist",
  en_obj = "Speak with the Redridge Herbalist, Martie Jainrose.",
}
T[131] = {
  title = "Consegna di asfodeli",
  desc = "Ecco il tuo mazzo. Ho scelto dei Daffodil per te. Sono i miei preferiti!",
  obj = "Dai a Darcy il Daffodil Bouquet.",
  progress = "Ciao di nuovo, $N. A Parker è piaciuto il pranzo che gli ho mandato?",
  reward = "Oh, sono splendidi! Non vedo l'ora di metterli in acqua!$B$BMa... questi sono i fiori preferiti di Martie. Parker non ti ha mandato da quell'invidiosa per questo mazzo, vero? Non le hai detto per chi erano, vero? Se l'hai fatto, non mi stupirei se li avesse avvelenati.$B$BOh, ma non è colpa tua. Grazie, ed ecco il tuo pasto.",
  en_title = "Delivering Daffodils",
  en_obj = "Give Darcy the Daffodil Bouquet.",
}
T[132] = {
  title = "La Fratellanza Defias",
  desc = "Quello che sto per dirti potrebbe costarmi la vita. La banda dei Defias sta tramando qualcosa di grosso. Da quanto ho sentito, lavorano insieme a gnoll, kobold e perfino goblin.$B$BPorta questa nota a Stoutmantle. Spiega tutto ciò che so sull'argomento.",
  obj = "Porta la Wiley's Note a Gryan Stoutmantle a Westfall.",
  progress = "Bentornat$Go:a;, $N. Che cos'aveva da dire Wiley?",
  reward = "Bah! Avrei dovuto lasciare quel furfante a marcire quando ne ho avuto l'occasione. Ma queste informazioni sono fondamentali. Ottimo lavoro.",
  en_title = "The Defias Brotherhood",
  en_obj = "Take Wiley's Note to Gryan Stoutmantle in Westfall.",
}
T[133] = {
  title = "Effigie per i ghoul",
  desc = "Vivo così lontano dalla protezione del paese che è un miracolo se i ghoul e i morti che camminano non mi hanno ancora mangiato! Anzi, proprio ieri un branco di Bone Chewer martellava sui muri di casa mia!$B$BVoglio fare un'effigie — una specie di \"spaventapasseri\" per i ghoul. Per farla mi servono delle Ghoul Rib. Puoi prenderle da Flesh Eater, Bone Chewer, Brain Eater, Rotted One e Plague Spreader.$B$BPortami le costole e ti ripagherò con qualche moneta.",
  obj = "Raccogli 7 Ghoul Rib e portale ad Abercrombie, alla sua baracca.",
  progress = "Mi sembra di sentire un branco di ghoul che sgattaiola dietro casa — meglio che tiri su in fretta quell'effigie! Me le hai prese quelle Ghoul Rib?",
  reward = "Ah, grazie. Faranno proprio al caso mio!",
  en_title = "Ghoulish Effigy",
  en_obj = "Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.",
}
T[134] = {
  title = "Ogre ladri",
  desc = "Qualche settimana fa stavo raccogliendo erbe lontano da casa, e una banda di ogre mi ha assalito! Sono scappato, e ho dovuto lasciare indietro una cassa di attrezzi e di erbe preziose.$B$BDopo avermi cacciato, gli ogre sono tornati impettiti al tumulo degli ogre nel sud di Duskwood. Sono sicuro che la mia cassa è da qualche parte vicino al tumulo.$B$BTi prego, $N, recuperamela, perché mi manca tantissimo.",
  obj = "Riporta Abercrombie's Crate ad Abercrombie.",
  progress = "Ce l'hai la mia cassa? Se sì, allora ti prego... dammela subito!",
  reward = "Grazie al Negrom-... be', grazie a TE, $N! Ti sei $Gguadagnato:guadagnata; la ricompensa e anche di più.$B$BAha! Felice! Notti felici in arrivo!!",
  en_title = "Ogre Thieves",
  en_obj = "Return Abercrombie's Crate to Abercrombie.",
}
T[135] = {
  title = "La Fratellanza Defias",
  desc = "Mi chiedo cosa intendesse Wiley quando ha parlato degli Stonemasons. Forse è stato un lapsus. Che la banda dei Defias abbia a che fare con gli Stonemasons? Solo un uomo potrebbe saperlo con certezza: Mathias Shaw, capo dell'SI:7. Mostragli la Wiley's Note e vedi se ha qualcosa da aggiungere a questo mistero sempre più fitto. Se hai difficoltà a trovare Shaw, controlla nelle caserme di Old Town.",
  obj = "Porta la Wiley's Note a Mathias Shaw a Stormwind.",
  progress = "Che affari hai con me? Sono un uomo molto occupato...",
  reward = "Questa faccenda potrebbe essere più complessa di quanto Stoutmantle immagini.",
  en_title = "The Defias Brotherhood",
  en_obj = "Take Wiley's Note to Mathias Shaw in Stormwind.",
}
T[136] = {
  title = "Il tesoro nascosto del Capitano Sander",
  desc = "Se state leggendo questo, vuol dire che il vecchio Capitano Sanders giace in una tomba d'acqua. Il mio tesoro ora è vostro, basta che seguiate gli indizi.$B$BPer prima cosa dovete trovare il mio baule. Ormai sarà mezzo sepolto nella sabbia, lungo la costa occidentale di Westfall, vicino al relitto. Ci sono tanti relitti, ma sulla costa c'è una sola àncora arrugginita. Trovate quell'àncora e troverete il mio baule! Guardate là dentro per il prossimo indizio.",
  obj = "Trova il baule del Capitano Sanders e cercaci dentro il prossimo indizio.",
  reward = "Il baule si apre lentamente con uno scricchiolio. Dentro sembrano esserci solo sabbia e acqua. Ma aspetta! Un piccolo granchio schizza fuori con un indizio per il tesoro tra le chele!",
  en_title = "Captain Sander's Hidden Treasure",
  en_obj = "Find Captain Sanders' footlocker and search it for the next clue.",
}
T[138] = {
  title = "Il tesoro nascosto del Capitano Sander",
  desc = "L'indizio per il tesoro dice: Bel lavoro, amico! Ora dovete dirigervi dritti a est. A est su per le scogliere, a est fino alla strada. Cercate le vecchie rovine di un camino sul ciglio della strada. Là troverete una vecchia botte con il vostro prossimo indizio.",
  obj = "Trova la vecchia botte vicino al camino in rovina e cercaci dentro il prossimo indizio.",
  reward = "Bel lavoro, cercatore di tesori!",
  en_title = "Captain Sander's Hidden Treasure",
  en_obj = "Find the old barrel near the ruined chimney and search it for your next clue.",
}
T[139] = {
  title = "Il tesoro nascosto del Capitano Sander",
  desc = "Frugando nella botte scopri un altro pezzo di pergamena. Dice: Ora, da questa botte, voltatevi a nord. Dritti come vola il corvo, continuate a camminare finché non vedrete la brocca vuota accanto al mulino a vento solitario sulle scogliere. Se frugate attorno a quella brocca, potreste trovare ciò che cercate.",
  obj = "Cerca nella brocca vuota accanto al mulino a vento il prossimo indizio.",
  reward = "Sei sulla strada del bottino, cercatore di tesori!",
  en_title = "Captain Sander's Hidden Treasure",
  en_obj = "Search the empty jug next to the windmill for the next clue.",
}
T[140] = {
  title = "Il tesoro nascosto del Capitano Sander",
  desc = "Proprio come previsto, in fondo alla Old Jug c'è un altro indizio sul tesoro di Sander. L'inchiostro è sbavato in alcuni punti e la carta sa di whisky, ma riesci a leggere parte del testo: Ora che avete trovato la mia vecchia brocca di whisky, siete quasi al tesoro! Voltatevi a ovest rispetto alla bottiglia e scendete fino alla riva. Una volta arrivati all'acqua, continuate! Nuotate dritti a ovest finché non trovate l'isola con il mio forziere!",
  obj = "Trova il forziere del Capitano Sanders e aprilo per ottenere la tua ricompensa.",
  reward = "I cardini del vecchio forziere sono arrugginiti, ma funzionano ancora. Lo forzi e ti prendi il bottino.$B$BCongratulazioni!",
  en_title = "Captain Sander's Hidden Treasure",
  en_obj = "Locate Captain Sanders' chest and open it for your reward.",
}
T[141] = {
  title = "La Fratellanza Defias",
  desc = "La gilda degli Stonemasons era guidata da un uomo di nome Edwin VanCleef. VanCleef fu responsabile della ricostruzione di Stormwind dopo che gli orchi la rasero al suolo nella Prima Guerra. A quanto pare, VanCleef e i suoi uomini rimasero scontenti del trattamento ricevuto dal Re a ricostruzione ultimata. Questo potrebbe spiegare più di una cosa.$B$BHo scritto un resoconto più dettagliato per il tuo Master a Westfall. Portaglielo subito!",
  obj = "Porta il rapporto di Shaw a Gryan Stoutmantle a Westfall.",
  progress = "Master Shaw ha fatto luce sulla faccenda?",
  reward = "Edwin VanCleef... conosco bene quel nome. Pensare che un uomo così laborioso e talentuoso possa essere diventato un simile furfante mi turba. Mi serviranno ulteriori prove prima di crederci.",
  en_title = "The Defias Brotherhood",
  en_obj = "Take Shaw's report to Gryan Stoutmantle in Westfall.",
}
T[142] = {
  title = "La Fratellanza Defias",
  desc = "Dobbiamo scoprire dove si trova il nascondiglio dei Defias. $N, il mio esploratore riferisce che un Defias Messenger è stato visto sulle strade tra Moonbrook, la Gold Coast Quarry e la Jangolode Mine. Voglio che lo catturi. Se resiste, uccidilo e portami qualunque cosa abbia con sé.",
  obj = "Rintraccia il Defias Messenger a Westfall e porta il suo messaggio a Stoutmantle.",
  progress = "$N, sei riuscit$Go:a; a raccogliere qualche informazione? Hai trovato il messaggero?",
  reward = "Questa è davvero la prova certa che VanCleef è al comando. Ora ci manca solo sapere dove si nasconde la banda dei Defias.$B$BMentre eri via abbiamo avuto un colpo di fortuna. Abbiamo catturato un ladro che cercava di rubare il carro di Saldean. Ha promesso di condurci al nascondiglio in cambio della vita. Voglio che tu difenda il traditore, così che possa rivelarci il nascondiglio. Torna da me quando avrai scoperto dove si trova.",
  en_title = "The Defias Brotherhood",
  en_obj = "Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.",
}
T[143] = {
  title = "Messaggero per Westfall",
  desc = "Qualcosa di strano sta accadendo con l'Esercito di Stormwind. Dovrebbero essere già qui in forze. Il tempo però è un lusso che non abbiamo. Non resterò a guardare la gente di Lakeshire dare la vita senza tentare di ottenere altro aiuto. Ho sentito che a Westfall si sta formando una milizia popolare.$B$BPorta questa supplica al loro capo, Gryan Stoutmantle. Forse gli uomini di Stoutmantle potranno darci una mano qui finché il Re non invierà le riserve.",
  obj = "Magistrate Solomon vuole che tu porti la sua supplica scritta a Gryan Stoutmantle a Westfall.",
  progress = "Salute, $C. Che affari hai con la People's Militia?",
  reward = "Buon messaggero, hai servito bene il tuo signore.",
  en_title = "Messenger to Westfall",
  en_obj = "Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall.",
}
T[144] = {
  title = "Messaggero per Westfall",
  desc = "La nota di Magistrate Solomon mi addolora. Ma è evidente che non conosce la guerra che si combatte a Westfall, altrimenti saprebbe di non poter aspettarsi aiuto dalla Militia. Se Stormwind non ci avesse abbandonati, non avremmo bisogno della Militia.$B$BPorta questa risposta al tuo signore a Redridge, $C. E digli che il mio cuore è pesante per la perdita di tanti uomini valorosi.",
  obj = "Torna da Magistrate Solomon con la risposta di Gryan Stoutmantle.",
  progress = "Dobbiamo aspettarci presto la People's Militia? Le notizie di Lord Stoutmantle sono buone?",
  reward = "Devo dire che non è affatto una buona notizia. Non mi ero reso conto che la situazione di Stoutmantle non fosse dissimile dalla nostra qui a Lakeshire. Quale impresa è così importante da richiamare l'Esercito di Stormwind lontano dalla sua gente? Bah, non dovrei ragionare ad alta voce.$B$BTieni, messaggero. Accetta queste monete in cambio del tuo servizio al Township. Potrei chiamarti ancora.",
  en_title = "Messenger to Westfall",
  en_obj = "Return to Magistrate Solomon with Gryan Stoutmantle's response.",
}
T[145] = {
  title = "Messaggero per Darkshire",
  desc = "Ho ancora bisogno del tuo aiuto. Ho scritto a Lord Ebonlocke, chiedendogli di inviare le sue guardie addestrate, la Night Watch, in difesa di Lakeshire. È fondamentale che questo messaggio gli arrivi in fretta. Devi procedere con estrema cautela. Ebonlocke è il sindaco di Darkshire, nel cuore di Duskwood. Non abbandonare le strade.",
  obj = "Magistrate Solomon vuole che tu porti una lettera a Lord Ebonlocke a Darkshire.",
  progress = "Sembri giunt$Go:a; da lontano, $C. Che affari hai qui a Darkshire?",
  reward = "Grazie per aver affrontato il lungo viaggio fin qui. Queste sono davvero informazioni importanti.",
  en_title = "Messenger to Darkshire",
  en_obj = "Magistrate Solomon wants you to take a letter to Lord Ebonlocke in Darkshire.",
}
T[146] = {
  title = "Messaggero per Darkshire",
  desc = "Se non conoscessi Magistrate Solomon di persona, direi che quell'uomo è impazzito. Mandare la Night Watch a Lakeshire perché Stormwind rifiuta di aiutare? La Night Watch è nata proprio perché Stormwind ci ha abbandonati quando questa magia immonda si è infiltrata nella terra. Se mandassi i miei uomini, questa città verrebbe sopraffatta dal male prima ancora che le guardie raggiungano il limitare della foresta.$B$BPorta questa lettera di risposta al tuo Master a Lakeshire.",
  obj = "Torna da Magistrate Solomon con la lettera di risposta di Lord Ebonlocke.",
  progress = "Ah, bentornato, messaggero. Devo informare il Marshal che la Night Watch sta per partire da Darkshire?",
  reward = "Per la Luce! L'esercito di Stormwind si è ritirato da Westfall. E la Guardia non protegge più Darkshire? C'è del tradimento sotto tutto questo. Come può essere? $B$BOh, stavo dimenticando di ricompensare il tuo servizio, $C. Ecco qualche moneta. Ora scusami: qualcosa non va a Stormwind e devo andare a fondo della faccenda.",
  en_title = "Messenger to Darkshire",
  en_obj = "Return to Magistrate Solomon with Lord Ebonlocke's letter of response.",
}
T[147] = {
  title = "Caccia all'uomo",
  desc = "Se il \"Collector\" sta portando via oro dalle nostre miniere, allora sta derubando il regno! Porta il Collector davanti alla giustizia e portami l'anello menzionato nel programma dei ritiri che mi hai consegnato. Potrebbe rivelarci per chi lavora...$B$BQuel programma dei ritiri dice che il Collector si nasconde al Brackwell Pumpkin Patch. Dovresti cercarlo laggiù.",
  obj = "Trova e uccidi \"the Collector\", poi torna da Marshal Dughan con The Collector's Ring.",
  progress = "Hai trovato il Collector? Hai scoperto per chi lavora?",
  reward = "Lo hai trovato? Ben fatto, $N. Non \"riscuoterà\" mai più dalle Elwynn Mines!$B$BE questo anello che hai trovato è interessante... è l'anello di appartenenza della vecchia Stonemason's Guild di Stormwind. Perché un misero ladro porterebbe l'anello di una gilda di artigiani, e perché i Defias Thieves raccolgono denaro dalle nostre miniere?$B$BDomande difficili. Spero che un giorno avremo delle risposte.",
  en_title = "Manhunt",
  en_obj = "Find and kill \"the Collector\"  then return to Marshal Dughan with The Collector's Ring.",
}
T[148] = {
  title = "Rifornimenti da Darkshire",
  desc = "Oh, cosa può fare un povero vecchio? Mi servono dei rifornimenti da Darkshire, ma il villaggio è così lontano e io sono così vecchio e malandato... non ce la farei mai a fare il viaggio.$B$BPuoi andare a Darkshire e portarmi del Ghost Hair Thread? Puoi averlo da Madame Eva, a casa sua, sulla piazza di Darkshire.",
  obj = "Parla con Madame Eva.",
  reward = "Ah, ti serve del Ghost Hair Thread, vero? Temo di non averne, ma posso fartene un po'... se mi procuri tu i capelli di fantasma.",
  en_title = "Supplies from Darkshire",
  en_obj = "Speak with Madame Eva.",
}
T[149] = {
  title = "Ghost Hair Thread",
  desc = "C'è un povero spirito triste, Blind Mary, che infesta una vecchia fattoria sulle colline a sud di Darkshire.$B$BTieni, prendi questo Spectral Comb e chiedi a Blind Mary di pettinarsi. Poi riportami il pettine e ne ricaverò i Ghost Hair che mi servono per il filo.$B$BE sta' $Gattento:attenta;, perché adesso vicino a quella casa si annidano cose oscure...",
  obj = "Porta lo Spectral Comb a Blind Mary.",
  progress = "<Singhiozzo> Oh, ti prego, non guardarmi! Mi sono strappata questi occhi con le mie mani, eppure sento ancora il tuo sguardo!$B$BSono orrenda! Orrenda! Ti prego, gira lo sguardo!!",
  reward = "Cos'è questo? Un pettine? È bellissimo! E scivola tra i miei capelli come se non fossero l'orrore rigido e stopposo che sono.$B$BOh, se solo avessi uno specchio...",
  en_title = "Ghost Hair Thread",
  en_obj = "Bring the Spectral Comb to Blind Mary.",
}
T[150] = {
  title = "Murloc bracconieri",
  desc = "I murloc stanno diventando un problema. Gruppi sempre più numerosi di questi uomini-pesce stanno gettando l'ancora lungo le rive di Lake Everstill e pescano a più non posso! Dobbiamo cacciarli via prima che si mangino tutti i pesci del lago!$B$BDai la caccia ai murloc! Portami otto delle loro pinne e forse avrò qualcosa per te...",
  obj = "Porta 8 Murloc Fin a Dockmaster Baren a Lakeshire.",
  progress = "Hai quelle pinne? Sbrigati, dobbiamo scacciare i murloc dal lago!",
  reward = "Ben fatto, $N. Spero che quei murloc non ti abbiano dato troppi problemi.$B$BÈ strano vederli così lontani dal mare. Mi chiedo se siano qui perché stanno fuggendo da qualcosa...",
  en_title = "Murloc Poachers",
  en_obj = "Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire.",
}
T[151] = {
  title = "La povera vecchia Blanchy",
  desc = "Povera vecchia Blanchy! Che bestia stanca, dopo tutto il lavoro che le abbiamo fatto fare. Le ho dato da mangiare prima di lasciare la fattoria, ma non ci aspettavamo che il carro si rompesse. Se potessi portarle qualche manciata di avena dai campi, te ne sarei grato.$B$BScommetto che ne troverai attorno a tutte le fattorie di Westfall, se riuscirai a evitare quelle orribili macchine che hanno preso il sopravvento. Ci sono diverse fattorie a sudovest di qui.",
  obj = "Verna Furlbrow a Westfall vuole che tu le porti 8 Handful of Oats.",
  progress = "La vecchia Blanchy è allo stremo. Hai trovato per caso un po' di avena per lei?",
  reward = "Grazie mille, $N! La povera vecchia Blanchy sarà così felice!",
  en_title = "Poor Old Blanchy",
  en_obj = "Verna Furlbrow in Westfall wants you to bring her 8 Handfuls of Oats.",
}
T[152] = {
  title = "La costa non è sicura",
  desc = "Avrai di certo notato tutti i relitti lungo la costa. Il Great Sea è davvero insidioso. La costa di Westfall deve restare libera, in modo che i marinai che approdano sulle nostre spiagge siano al sicuro. I Murloc però sono un problema.$B$BUccidi 7 Tidehunter, 7 Warrior, 7 Oracle e 7 Coastrunner e mi assicurerò che tu sia ricompensat$Go:a;.",
  obj = "Uccidi 7 Tidehunter, 7 Warrior, 7 Oracle e 7 Coastrunner, poi torna da Captain Grayson al Westfall Lighthouse.",
  progress = "Uccidi 7 Tidehunter, 7 Warrior, 7 Oracle e 7 Coastrunner e mi assicurerò che tu sia ricompensat$Go:a;.",
  reward = "Ben fatto, $N. Hai davvero un talento per il combattimento. Grazie a te la costa di Westfall è un posto più sicuro.",
  en_title = "The Coast Isn't Clear",
  en_obj = "Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and return to Captain Grayson at the Westfall Lighthouse.",
}
T[153] = {
  title = "Bandane di cuoio rosso",
  desc = "Il Defias Front è in continuo movimento. Seguo i loro spostamenti da parecchio tempo ormai. Per inciso, ho scoperto che molti membri della banda si possono riconoscere dalle Red Leather Bandana che indossano.$B$BPortami 15 di queste bandane e farò in modo che tu sia ricompensat$Go:a;.",
  obj = "Porta 15 Red Leather Bandana a Scout Galiaan a Sentinel Hill.",
  progress = "Portami 15 Red Leather Bandana e ti pagherò bene.",
  reward = "Bel lavoro, $R. Accetta uno di questi oggetti come paga per tutta la tua fatica.",
  en_title = "Red Leather Bandanas",
  en_obj = "Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill.",
}
T[154] = {
  title = "Restituisci il pettine",
  desc = "NO!!!!!$B$BPrendilo, portami via questo pettine!$B$BSono un mostro, e nessuno mi troverà mai più bella!",
  obj = "Riporta il Ghost Hair Comb a Madame Eva, a Darkshire.",
  progress = "Sento che hai visto Blind Mary. Hai il mio pettine...?",
  reward = "Con questo posso fare una matassa di Ghost Hair Thread, e mi avanzeranno anche alcuni capelli. Ecco qualche moneta per quelli che avanzano.",
  en_title = "Return the Comb",
  en_obj = "Return the Ghost Hair Comb to Madame Eva in Darkshire.",
}
T[155] = {
  title = "La Defias Brotherhood",
  desc = "Quindi Stoutmantle manda un $r mingherlino come te a proteggermi? Immagino dovrai andare bene. Meglio se porti anche qualche amico.$B$BConosci l'accordo, vero? Tu mi guardi le spalle e io ti porto al covo dei Defias. Ma devi stare ben vicino a me. La banda dei Defias ora vuole la mia testa. Se mi vedono con te, cercheranno di uccidermi.$B$BDimmi quando tu e gli amici che riuscirai a radunare siete pronti a partire.",
  obj = "Scorta il Defias Traitor fino al nascondiglio segreto della Defias Brotherhood. Quando il Defias Traitor ti avrà mostrato dove si nascondono VanCleef e i suoi uomini, torna da Gryan Stoutmantle con le informazioni.",
  progress = "Che affari hai con me? Sono un uomo molto impegnato...",
  reward = "Eccellente, $N! Ora che sappiamo dove si nasconde, VanCleef è praticamente nostro.",
  en_title = "The Defias Brotherhood",
  en_obj = "Escort the Defias Traitor to the secret hideout of the Defias Brotherhood.  Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.",
}
T[156] = {
  title = "Raccogli i Rot Blossom",
  desc = "Se mi porti dei Rot Blossom posso prepararti una dose di Zombie Juice.$B$BI Rot Blossom crescono in posti strani. In particolare, mi dicono che si trovano dentro i teschi degli Skeletal Horror e degli Skeletal Fiend... non che io abbia mai guardato da così vicino!$B$BIl Raven Hill Cemetery e i Tranquil Gardens pullulano di quegli scheletri. Tanto vale farli fuori mentre cerchi i Rot Blossom. La città di Darkshire te ne sarebbe grata.",
  obj = "Raccogli 8 Rot Blossom e portali a Tavernkeep Smitts, a Darkshire.",
  progress = "Ciao, $N. Hai già quei Rot Blossom per me?",
  reward = "Bene, hai preso i Rot Blossom. E dirò ad Althea Ebonlocke della Guardia Notturna che stavi uccidendo scheletri.$B$BTenere al sicuro la gente di Darkshire è un compito gravoso per la Guardia Notturna, e sapere che anche altri aiutano ad arginare la marea di mostri a Duskwood è davvero una buona notizia.",
  en_title = "Gather Rot Blossoms",
  en_obj = "Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.",
}
T[157] = {
  title = "Consegna il filo",
  desc = "Ecco il tuo filo, $N. Ha mille usi, dal legare gli spiriti maligni al cucire la vita dentro oggetti inanimati.",
  obj = "Porta il Ghost Hair Thread ad Abercrombie, nella sua baracca a nord del Raven Hill Cemetery.",
  progress = "Devo tendere il Ghost Hair Thread lungo la porta e le finestre per tenere fuori gli spiriti indesiderati. Me l'hai preso?",
  reward = "Splendido! Andrà benissimo...$B$BTieni, $Gcaro:cara; $N, prendi questo come pagamento per la tua nobile azione.",
  en_title = "Deliver the Thread",
  en_obj = "Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.",
}
T[158] = {
  title = "Zombie Juice",
  desc = "Mi serve una bottiglia di un certo liquore — Zombie Juice. Tavernkeep Smitts, alla Scarlet Raven Tavern di Darkshire, dovrebbe averne.$B$BE fa' in fretta, ti prego, $N. Queste notti si fanno fredde, e mi serve quella bevanda per rimettermi il fuoco nelle vene!",
  obj = "Parla con Tavernkeep Smitts.",
  reward = "Ti serve dello Zombie Juice, eh? Hmm... è roba forte — non me lo chiede quasi nessuno.",
  en_title = "Zombie Juice",
  en_obj = "Speak with Tavernkeep Smitts.",
}
T[159] = {
  title = "Consegna dello Zombie Juice",
  desc = "Ecco il tuo Zombie Juice...$B$B...e sta' $Gattento:attenta; con questa roba. È abbastanza forte da resuscitare i morti!",
  obj = "Porta lo Zombie Juice ad Abercrombie, alla sua baracca.",
  progress = "Mi serve quello Zombie Juice per scaldarmi in queste notti fredde e buie. Me l'hai preso?",
  reward = "Mille grazie, $N. Scaldi il cuore di un vecchio con la tua stupid-... voglio dire... con la tua gentilezza!$B$BEccoti qua, $Gamico:amica;. Prendi questo come segno della mia gratitudine.",
  en_title = "Juice Delivery",
  en_obj = "Bring the Zombie Juice to Abercrombie at his shack.",
}
T[160] = {
  title = "Un biglietto per il sindaco",
  desc = "Porta questo biglietto a Ello Ebonlocke, il sindaco di Darkshire.$B$BLui e io siamo vecchi amici... e quando lo leggerà e scoprirà quel che hai fatto per me... sono sicuro che sarà felice quanto me! Ahahaha!",
  obj = "Porta la Letter to Ello di Abercrombie a Ello Ebonlocke, sindaco di Darkshire.",
  progress = "Abercrombie...? Non conosco nessuno con questo nome. Dici di avere una lettera per me da parte di questo tale Abercrombie?$B$BBe', allora diamole un'occhiata...",
  reward = "<Ello guarda la lettera...>$B$BChe lingua è questa? Sembra antica... non riesco a leggerla.",
  en_title = "Note to the Mayor",
  en_obj = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.",
}
T[161] = {
  title = "Un'oscura minaccia incombe",
  desc = "Se i miei sospetti sono fondati, questa è una specie di polvere esplosiva. Va analizzata da un esperto di esplosivi, così sapremo con cosa abbiamo a che fare. Ashlan Stonesmirk è stato assegnato al reggimento che sorveglia Dun Modr e il Thandol Span. Devo chiederti di intraprendere un viaggio lungo e pericoloso, $N.$B$BAttraversa l'Algaz Gate, segui la strada attraverso le Wetlands e cerca Stonesmirk a Dun Modr. Dai retta a me: resta sulle strade e non fermarti per nessun motivo!",
  obj = "Chief Engineer Hinderweir vuole che tu porti la polvere dall'odore strano ad Ashlan Stonesmirk, l'esperto di esplosivi di Dun Modr.",
  progress = "Hai detto qualcosa, $Gragazzo:ragazza;? Non sento un accidente, a parte il fischio nelle orecchie. Ehi, cos'è quella roba che hai lì?",
  reward = "Ah, beh, il vecchio Hinderweir fa bene a preoccuparsi.",
  en_title = "A Dark Threat Looms",
  en_obj = "Chief Engineer Hinderweir wants you to take the strange smelling powder to Ashlan Stonesmirk, the explosives expert in Dun Modr.",
}
T[163] = {
  title = "Raven Hill",
  desc = "Qualcosa non va a Raven Hill, $n. Calor giura che qualcuno, o qualcosa, infesti gli edifici laggiù. Per due notti di fila ha visto muoversi delle ombre, e tre notti fa dice di aver visto una luce a una delle finestre.$B$BSe, come dici, ti sta a cuore la sicurezza di Duskwood, scopri quale mostro infesta Raven Hill.",
  obj = "Scopri cosa infesta Raven Hill.",
  reward = "No! Ti prego, non uccidermi! Sono solo io... Jitters!! Sono ovunque... non riesco a scappare! Mostri a Raven Hill? N-n-no... impossibile. Solo l'innocuo Jitters.",
  en_title = "Raven Hill",
  en_obj = "Find out what is haunting Raven Hill.",
}
T[164] = {
  title = "Consegne per Sven",
  desc = "Conosci Sven? Ecco un uomo che fa l'opera della Luce! Lui e i suoi seguaci hanno un accampamento all'estremità nord-occidentale di Duskwood.$B$BPurtroppo sono così pochi che non possono permettersi di staccare un uomo per andare a prendere i rifornimenti in città. Glieli porteresti tu, questi rifornimenti?",
  obj = "Consegna i rifornimenti a Sven.",
  progress = "Hai l'aria robusta, $C. Sei $Gvenuto:venuta; a unirti alla nostra battaglia?",
  reward = "Questi rifornimenti saranno utilissimi. L'aiuto della famiglia Carevin è sempre gradito. Ecco qualcosina per il disturbo.",
  en_title = "Deliveries to Sven",
  en_obj = "Deliver the supplies to Sven.",
}
T[165] = {
  title = "L'eremita",
  desc = "C'era un vecchio che veniva in paese piuttosto spesso a comprare rifornimenti, ma è da parecchio che non lo vedo. Se ricordo bene, vive in una baracca che domina il cimitero di Raven Hill. Forse dovresti andare a vedere se è successo qualcosa.",
  obj = "Va' a vedere come sta il vecchio nella baracca vicino al cimitero di Raven Hill.",
  reward = "Elaine Carevin? Eheh, oh sì... i Carevin, certo.$B$BNo, non c'è niente che non va, ma adesso per me è dura andare in paese. Le strade sono pericolose e non ringiovanisco di certo. Magari puoi fare qualche favore a un vecchio?",
  en_title = "The Hermit",
  en_obj = "Check on the old man in the shack near Raven Hill cemetery.",
}
T[166] = {
  title = "La Defias Brotherhood",
  desc = "Ti resta un solo compito da portare a termine. Edwin VanCleef deve essere assassinato. Per quanto mi rattristi condannare a morte un uomo, è per il bene supremo della gente di Westfall che VanCleef sia sepolto una volta per tutte. Portami la testa del criminale, una volta compiuta l'impresa.",
  obj = "Uccidi Edwin VanCleef e porta la sua testa a Gryan Stoutmantle.",
  progress = "Come va la caccia a Edwin VanCleef?",
  reward = "$N, il tuo coraggio è notevole. La People's Militia ti ringrazia per il servizio reso alla gente di Westfall. Con VanCleef morto, questo segna l'inizio della fine per la Defias Brotherhood. Speriamo che presto la pace torni a benedire le pianure di questa bella terra.$B$BTi saluto, $Gsignore:signora;!",
  en_title = "The Defias Brotherhood",
  en_obj = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.",
}
T[167] = {
  title = "Oh, fratello...",
  desc = "Eravamo in fondo a una miniera enorme a Westfall, nascosta sotto un fienile a Moonbrook. Non ho idea di dove siano sbucati quei ladri puzzolenti. Comunque, la galleria ci è crollata addosso. Io ne sono uscito, ma gli altri... be'... degli altri non si è più saputo nulla.$B$BSembra che tu là dentro possa avere più fortuna. Se potessi cercare mio fratello, te ne sarei grato. Portava sempre con sé il suo Explorers' League Badge. Se non riesci a trovarlo, quel distintivo mi darebbe almeno un po' di pace.",
  obj = "Porta Foreman Thistlenettle's Explorers' League Badge a Wilder Thistlenettle, a Stormwind.",
  progress = "Hai trovato qualche traccia di mio fratello? C'è ancora speranza dopo tutto questo tempo?",
  reward = "I miei sospetti erano fondati. Povero fratello mio... Be', grazie per aver dato una conclusione a questo mistero, anche se la conclusione era cupa.",
  en_title = "Oh Brother. . .",
  en_obj = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.",
}
T[168] = {
  title = "Raccogliere ricordi",
  desc = "Molti dei miei amici sono morti in quel giorno orribile in cui la galleria della miniera è crollata. Se le tue avventure dovessero portarti in quell'ala della miniera a Moonbrook, ti prego, tieni gli occhi aperti per qualsiasi segno che possa identificarli. Se ti capita di trovare qualcuna delle loro Miners' Union Card, riportamele e farò in modo che le loro famiglie trovino una risposta a questo terribile incidente.",
  obj = "Recupera 4 Miners' Union Card e riportale a Wilder Thistlenettle, a Stormwind.",
  progress = "Sei $Griuscito:riuscita; a recuperare qualche Miners' Union Card dei miei vecchi compagni di lavoro?",
  reward = "Grazie di averle raccolte, $N. Il tuo impegno aiuterà a dare pace ai morti dopo questa tragedia. Mi occuperò io di avvisare le famiglie.",
  en_title = "Collecting Memories",
  en_obj = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.",
}
T[169] = {
  title = "Wanted: Gath'Ilzogg",
  desc = "Wanted! Gath'Ilzogg, capo degli attacchi Blackrock allo Stonewatch Keep e delle incursioni contro la cittadina di Lakeshire.$B$BGath'Ilzogg è estremamente pericoloso. Si dice sia rintanato nel forte appena conquistato, a tramare altri crimini del Blackrock Clan contro l'umanità. L'infestazione degli orchi va soffocata a ogni costo. Sarà data una generosa ricompensa a qualunque anima coraggiosa consegni la testa di Gath'Ilzogg a Magistrate Solomon.",
  obj = "Uccidi Gath'Ilzogg e porta la sua testa a Magistrate Solomon, a Lakeshire, per la ricompensa.",
  progress = "Che cos'hai lì, $R?",
  reward = "Lavoro fantastico, $N! Gath'Ilzogg ha guidato quei bruti in battaglia, uccidendo molti umani innocenti. La rivincita è nostra. È il primo passo per riconquistare il forte per il regno di Stormwind!",
  en_title = "Wanted: Gath'Ilzogg",
  en_obj = "Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.",
}
T[170] = {
  title = "Una nuova minaccia",
  desc = "Spero che tu sia qui per darci una mano, $C. Dopo l'ultimo attacco dei trogg, ci serve tutto l'aiuto possibile.$B$BHo sentito che quelle canaglie spuntano ovunque nelle nostre terre, e a quanto pare Coldridge Valley non fa eccezione. Sono stati avvistati su tutte le colline a sud-est e vicino al lago ghiacciato.$B$BE non è tutto: poche notti fa hanno attaccato e travolto il nostro accampamento a ovest!$B$BQui siamo a corto di uomini, $Gragazzo:ragazza;, e ci servono braccia forti per ricacciare indietro i trogg.",
  obj = "Balir Frosthammer vuole che tu uccida 6 Rockjaw Troggs e 6 Burly Rockjaw Troggs.",
  progress = "Tenaci, quelle piccole canaglie, eh?",
  reward = "Se i problemi che abbiamo avuto qui riflettono quello che succede nel resto delle nostre terre, per la barba di Magni, ci aspettano tempi duri! Posso solo sperare che il re e il Senato stiano prendendo provvedimenti contro la minaccia dei trogg.",
  en_title = "A New Threat",
  en_obj = "Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.",
}
T[171] = {
  title = "$GUn tutore:Una tutrice; dell'Alleanza",
  desc = "Sei $Gstato:stata; così gentile con me, $N. Non avrei mai sognato di divertirmi così tanto durante la Settimana dei Bambini. Grazie. Non voglio essere triste per quello che mi è successo e tutto il resto: i miei mi hanno sempre detto di superare qualunque cosa brutta succeda. Sai, da grande voglio essere un eroe... proprio come te.$B$BMi dispiace dirlo, ma è ora che torni a casa. Torniamo indietro, e dirò alla matrona che persona fantastica sei!",
  obj = "Riporta il tuo protetto all'orfanotrofio di Stormwind consegnando lo Human Orphan Whistle a Orphan Matron Nightingale, nel Cathedral District.",
  progress = "È un piacere rivederti, $N. Hai portato a termine i compiti di cui ti sei $Gfatto:fatta; carico durante la Settimana dei Bambini?",
  reward = "Che il cielo ti benedica, $N. Hai fatto per Randis più di quanto la maggior parte della gente penserebbe mai di fare per lui. Grazie: sei una stella splendente nei cieli dell'Alleanza.$B$BTi prego, se riesci a trovare un po' di tempo, torna a trovarci. So che a Randis farebbe piacere, e anche a me.$B$BRandis si è divertito tantissimo con te, $N. Voleva darti uno dei suoi animaletti preferiti, perché ti ricordi di lui.",
  en_title = "A Warden of the Alliance",
  en_obj = "Return your ward to the Stormwind orphanage by handing in the Human Orphan Whistle to Orphan Matron Nightingale in the Cathedral District.",
}
T[172] = {
  title = "Settimana dei Bambini",
  desc = "Vuoi aiutarci qui all'orfanotrofio? Che il cielo ti benedica, $Gamico:amica;: il tuo aiuto durante la Settimana dei Bambini sarà prezioso.$B$BPrendi questo fischietto. Potrai usarlo solo per poco tempo, di solito non più a lungo della Settimana dei Bambini stessa. Quando lo usi, potrai parlare con il bambino di cui hai accettato di occuparti. Se lo usi di nuovo, il bambino se ne andrà.$B$BForza, $N, usa il fischietto e conosci il tuo protetto! Sono $Gsicuro:sicura; che il bambino non vedrà l'ora di conoscerti.",
  obj = "Usa l'Orcish Orphan Whistle per parlare con il bambino di cui ti occuperai durante la Settimana dei Bambini.",
  reward = "Zug zug! Mi chiamo Grunth, e immagino che sarai tu a occuparti di me? Sei $Gun avventuriero:un'avventuriera;, come lo erano la mia mamma e il mio papà. La mia matrona dice che sono morti con onore in battaglia. Sono contento di conoscerti.$B$BSpero che faremo un sacco di cose insieme. Ho alcune cose che vorrei fare, e la matrona dice che durante questa settimana sarai come $Gun fratello maggiore:una sorella maggiore; per me. Mi piacerebbe un sacco.",
  en_title = "Children's Week",
  en_obj = "Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week.",
}
T[173] = {
  title = "Worgen nei boschi",
  desc = "L'oscurità sembra attirata inesorabilmente da Duskwood. La missione di Master Carevin è scacciare il male e l'eresia. È grazie ai nostri sforzi che la gente di Darkshire resta al sicuro.$B$BTi credi $Gdegno:degna; di unirti a noi?$B$BUna volta la pensavo come te. Deluso dall'inerzia della Guardia, mi sono unito a Master Carevin. Se vuoi dimostrare il tuo valore, non sarà con le parole.$B$BMetti alla prova le tue capacità contro i worgen Nightbane Shadow Weaver a Brightwood Grove — luminoso, ah! — e al Rotting Orchard.",
  obj = "Uccidi 6 worgen Nightbane Shadow Weaver per Calor, a Darkshire.",
  progress = "$N, come va la caccia?",
  reward = "Notevole, $N. Sembra che tu sia capace di cavartela da $Gsolo:sola;. Forse per $Guno:una; con le tue capacità si può trovare una sfida più adatta.$B$BÈ curioso, però... I worgen sembravano comparire dal nulla. Ma poi, con tutte le altre creature strane che hanno passato i nostri confini, immagino sia solo una preoccupazione fra tante.",
  en_title = "Worgen in the Woods",
  en_obj = "Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire.",
}
T[174] = {
  title = "Guarda le stelle",
  desc = "Il mio amico gnomo, Cog, ha promesso di aiutarmi a costruire un congegno che mi permetta di scrutare verso le stelle. Esiste una verità, oltre la magia, che può spiegare la strana trasformazione della foresta.$B$BPortami un tubo di bronzo fatto da un ingegnere esperto. È il primo passo, secondo il progetto di Cog.",
  obj = "Viktori Prism'Antras di Darkshire vuole che tu gli porti un tubo di bronzo.",
  progress = "Hai già trovato un ingegnere esperto che faccia un tubo di bronzo?",
  reward = "È perfetto, $N. Il primo passo è compiuto!",
  en_title = "Look To The Stars",
  en_obj = "Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube.",
}
T[175] = {
  title = "Guarda le stelle",
  desc = "Secondo il progetto di Cog, ora mi serve un modo per riflettere la luce. Ricordo una donna di nome Mary che da queste parti era conosciuta perché portava sempre con sé uno specchio. Magari puoi rintracciare Mary e vedere se può prestarci una superficie riflettente per questo progetto. Credo che un tempo vivesse nella parte meridionale di Duskwood. . .",
  obj = "Trova Mary e convincila a cedere una superficie riflettente per il progetto di Viktori.",
  reward = "Ma sì, un tempo avevo uno specchio.",
  en_title = "Look To The Stars",
  en_obj = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.",
}
T[176] = {
  title = "Ricercato: \"Hogger\"",
  desc = "Ricercato: Hogger$B$BUn enorme gnoll, Hogger, si aggira per i boschi del sudovest di Elwynn. Ha sopraffatto ogni tentativo di cattura.$B$BLo Stormwind Army ha posto una generosa taglia sullo Gnoll. Per ottenere la ricompensa, i cacciatori di taglie devono portare la prova della morte di Hogger a Marshal Dughan a Goldshire.",
  obj = "Uccidi lo gnoll Hogger e porta il suo Huge Gnoll Claw a Marshal Dughan.",
  progress = "Sì, Hogger è stato un vero tormento per me e i miei uomini. Hai qualcosa da riferire sulla bestia?",
  reward = "Ah! Ben fatto! Cominciavo a pensare che nessuno avrebbe abbattuto quel mostro!$B$BEcco a te, $N. E grazie: quello Gnoll mi dava un mal di testa grande quanto Blackrock Spire!",
  en_title = "Wanted:  \"Hogger\"",
  en_obj = "Slay the gnoll Hogger and bring his Huge Gnoll Claw to Marshal Dughan.",
}
T[177] = {
  title = "Guarda le stelle",
  desc = "Lo specchio era uno dei miei tesori più belli, fino a. . .l'incidente. Dopo quel che è successo l'ho buttato dietro il fienile. Là dietro si aggirava un Insane Ghoul. Forse l'ha raccolto lui. Si dice che quella bestia diabolica stia nel Tranquil Gardens Cemetery.",
  obj = "Recupera Blind Mary's Looking Glass dall'Insane Ghoul e portalo a Viktori, a Darkshire.",
  progress = "Ho mostrato a Cog l'inizio della nostra macchina per guardare le stelle. È rimasto colpito. Ti è capitato di trovare un congegno riflettente?",
  reward = "Magnifico! Andrà a meraviglia. Mille grazie!",
  en_title = "Look To The Stars",
  en_obj = "Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire.",
}
T[178] = {
  title = "Il recupero di Theocritus",
  desc = "<Senti una voce incorporea...>$B$BNon ti allarmare. Sono Theocritus, High Mage della Tower of Azora, nell'Elwynn Forest. Il pendaglio che hai in mano è un mezzo di comunicazione tra gli Shadowhide Gnoll e il loro padrone, Morganth.$B$BDopo mesi di ricerche, credo di poter comunicare anch'io attraverso questi pendagli. Se senti questo messaggio, allora il mio incantesimo ha funzionato.$B$BPortami questo pendaglio e ti ricompenserò per il servizio.",
  obj = "Porta il Faded Shadowhide Pendant a Theocritus the Mage.",
  progress = "Ti ho parlato attraverso un pendaglio, dici? Hmm... dallo a me, così posso studiarlo.",
  reward = "Ti sono grato, $N. Quel messaggio l'ho mandato agli Shadowhide Pendant settimane fa e lo credevo un fallimento. Ma pare che l'incantesimo abbia raggiunto almeno qualche pendaglio, dopo un notevole ritardo.$B$BCol tempo spero di imparare a mandare un attacco attraverso i pendagli, per immobilizzare gli Shadowhide Gnoll che li portano.$B$BMa prima che sia possibile, temo che serva ancora molta ricerca.",
  en_title = "Theocritus' Retrieval",
  en_obj = "Bring the Faded Shadowhide Pendant to Theocritus the Mage.",
}
T[179] = {
  title = "Equipaggiamento nanico",
  desc = "Cosa abbiamo qui? Sembri proprio avere bisogno di qualcosa per tenerti le mani al caldo, eh?$B$BTi dico io cosa ci vorrebbe: un bel paio di guanti caldi. E, anima gentile quale sono, sarei più che felice di procurartene un paio adatto. Ho però una condizione.$B$BDevi portarmi un po' di carne di lupo. Bell'accordo, eh? Tu mi porti la carne di lupo e io mi assicuro che il gelo non ti porti via nessun dito. Allora, che ne dici?",
  obj = "Sten Stoutarm vuole 8 pezzi di Tough Wolf Meat.",
  progress = "I lupi ti danno un po' di filo da torcere? Faresti bene a stare alla larga da zanne, artigli e altre parti appuntite, sì?",
  reward = "Ah! Magnifico. La carne di lupo andrà benissimo. Oh, non preoccuparti, $N, non dimentico la mia parte dell'accordo. Ecco, uno di questi dovrebbe andarti bene.",
  en_title = "Dwarven Outfitters",
  en_obj = "Sten Stoutarm would like 8 pieces of Tough Wolf Meat.",
}
T[180] = {
  title = "Wanted: Lieutenant Fangore",
  desc = "Wanted: Lieutenant Fangore$B$BCapo riconosciuto dello Shadowhide Gnoll Clan, al servizio del nemico della cittadina e del Regno, Morganth. Per mandato di Magistrate Solomon, questo ignobile traditore di Stormwind è ricercato morto. Mostra la sua zampa al magistrato come prova della sua morte.",
  obj = "Uccidi Lieutenant Fangore e torna da Magistrate Solomon, a Lakeshire, con la sua zampa.",
  progress = "Che notizie porti davanti alla Corte?",
  reward = "Dunque il malvagio Lieutenant Fangore è morto? Finalmente ci siamo liberati di quella creatura immonda. Sei molto $Gcoraggioso:coraggiosa;, $C. La cittadina di Lakeshire ti ringrazia per il tuo aiuto.",
  en_title = "Wanted: Lieutenant Fangore",
  en_obj = "Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.",
}
T[181] = {
  title = "Guarda le stelle",
  desc = "Ora manca solo un pezzo per completare questo congegno. Il progetto di Cog richiede una lente di qualche tipo. L'unica lente che conosco abbastanza grande sarà molto difficile da procurarsi.$B$BC'è un ogre di nome Zzarc'Vul che sta nel tumulo nel sud di Duskwood. Se ci riesci, portami il suo monocolo e lo userò come lente!",
  obj = "Trova Zzarc'Vul nel tumulo degli ogre a sud, a Duskwood, e porta il suo monocolo a Viktori, a Darkshire.",
  progress = "Sei $Griuscito:riuscita; a convincere Zzarc'Vul a prestarci il suo monocolo per il nostro esperimento?",
  reward = "Finalmente! Il congegno per osservare le stelle è completo! Grazie, $N. Ora posso continuare le mie ricerche. . .",
  en_title = "Look To The Stars",
  en_obj = "Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire.",
}
T[182] = {
  title = "La caverna dei troll",
  desc = "Mio fratello Senir e io siamo stati mandati in diverse parti di Dun Morogh a indagare sulla minaccia dei troll. Il Senato ha già il suo daffare con i trogg, quindi non ha bisogno di altri fastidi.$B$BDa quello che ho visto, i troll non sono ben insediati qui a Coldridge Valley: stanno soprattutto nella caverna a sud. Direi che non serve l'esercito. Qualche braccio forte dovrebbe bastare e avanzare.$B$BForse ti andrebbe di dare una mano in questa impresa? Sono autorizzato a offrire un compenso per il tuo aiuto.",
  obj = "Grelin Whitebeard vuole che tu uccida 14 Frostmane Troll Whelps.",
  progress = "Da quello che ho scoperto, questi troll appartengono al clan Frostmane. Temo di non sapere molto altro su di loro che possa esserti utile, $N.",
  reward = "Argh! Quei maledetti troll!$B<Fa qualche respiro e sembra calmarsi... un po'.>$BUn gruppo di loro è venuto di notte e mi ha rubato il diario! Lo sapevo che non dovevo fidarmi di quel buono a nulla dell'appr...",
  en_title = "The Troll Cave",
  en_obj = "Grelin Whitebeard would like you to kill 14 Frostmane Troll Whelps.",
}
T[183] = {
  title = "Il cacciatore di cinghiali",
  desc = "Niente di meglio di una giornata di caccia al cinghiale, eh?$B$BAnche se qui a Coldridge Valley ce ne sono così tanti che quasi toglie il gusto. Non serve nemmeno provocarli: sono già tutti arrabbiati e pronti a caricare. Anzi, di recente ce ne sono così tanti in zona che è diventato pericoloso fare la mia caccia quotidiana.$B$BPer farla breve, se mi aiutassi ad abbatterne qualcuno te ne sarei grato.",
  obj = "Talin Keeneye vuole che tu uccida 12 Small Crag Boars.",
  progress = "Come va la caccia?",
  reward = "Eccellente! Ora posso tornare alla mia... tranquilla... caccia. Grazie, $N.",
  en_title = "The Boar Hunter",
  en_obj = "Talin Keeneye would like you to kill 12 Small Crag Boars.",
}
T[184] = {
  title = "L'atto di proprietà di Furlbrow",
  desc = "Questo è l'atto di proprietà di un'estensione di terreni agricoli a Westfall. È firmato da un certo Theodore Furlbrow e controfirmato dalla moglie, Verna. Sul retro dell'atto ci sono parole scarabocchiate in fretta:$B$B\"Abbiamo messo sotto pressione Furlbrow e ci siamo presi il suo atto. Pensavamo che ti sarebbe stato utile se volevi falsificarne uno per il tuo podere.$B$BI Furlbrow non ci daranno fastidi. L'ultima volta che li ho visti stavano lasciando Westfall, bloccati con un carro rotto.\"$B$BTi viene da pensare che i Furlbrow vorrebbero riavere il loro atto...",
  obj = "Porta Furlbrow's Deed a Farmer Furlbrow.",
  progress = "Hai l'atto della mia fattoria?? Che buona notizia! Dei furfanti me l'hanno rubato giorni fa... pensavo fosse perso per sempre!$B$BTi prego, dammelo. Stiamo lasciando Westfall e non torneremo tanto presto, ma se mai dovessimo tornare ci serviranno quei documenti...",
  reward = "Mille grazie, $N! Come dicevo, da queste parti non è più posto per la gente onesta, ma se le cose miglioreranno, questo atto ci permetterà di riprenderci la nostra terra.$B$BNon ho molto da offrirti, ma ecco, prendi questo.",
  en_title = "Furlbrow's Deed",
  en_obj = "Bring Furlbrow's Deed to Farmer Furlbrow.",
}
T[185] = {
  title = "Maestria nella caccia alla tigre",
  desc = "Quando ero solo una ragazzina, mio padre mi insegnò l'arte della caccia alla tigre.$B$BI felini giovani sono molto più facili da seguire e da uccidere. Per questo cominceremo con qualcosa di semplice. Spesso si trovano giovani tigri vicino all'accampamento della spedizione.$B$BMetti alla prova la tua abilità nel seguire le tracce e vedi se riesci a cacciare qualcuna di queste bestie.",
  obj = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida 10 Young Stranglethorn Tiger.",
  progress = "Non me la sento di addestrarti oltre, $N, finché non avrai dimostrato di saper uccidere prima le tigri più giovani.",
  reward = "Ben fatto, $N. Sei $Gpronto:pronta; per il passo successivo.",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers.",
}
T[186] = {
  title = "Maestria nella caccia alla tigre",
  desc = "Stai imparando, $C. Ora mettiamo alla prova la tua abilità con i felini adulti. Stavolta uccidi 10 Stranglethorn Tiger.",
  obj = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida 10 Stranglethorn Tiger.",
  progress = "Se aspiri a sfide più grandi, devi prima dimostrare quanto vali con il compito che hai davanti. Torna da me dopo aver ucciso 10 Stranglethorn Tiger.",
  reward = "Sono colpita, $C. Stai facendo davvero buoni progressi.",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers.",
}
T[187] = {
  title = "Maestria nella caccia alla tigre",
  desc = "Ora alzerò la posta e metterò davvero alla prova la tua abilità. Dimostrami che sai uccidere 10 Elder Stranglethorn Tiger. Se ci riesci, sarai $Gpronto:pronta; per la tua sfida finale, prima che io ti proclami $Gmaestro cacciatore:maestra cacciatrice; di tigri alla presenza di Master Nesingwary.$B$BLe Elder Stranglethorn Tiger non solo sono le più difficili da trovare, ma sono anche le più feroci da sconfiggere.",
  obj = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida 10 Elder Stranglethorn Tiger.",
  progress = "Devi uccidere 10 Elder Stranglethorn Tiger prima che io ti affidi la sfida finale, quella che stabilirà se sei $Gun vero maestro:una vera maestra; nella caccia alla tigre.",
  reward = "Davvero notevole. Credo che tu sia quasi $Gpronto:pronta;.",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers.",
}
T[188] = {
  title = "Maestria nella caccia alla tigre",
  desc = "Ecco la sfida finale che ti propongo. Da settimane seguiamo le tracce di una tigre sfuggente. Chiamiamo la bestia Sin'Dall. Vediamo se riesci a fare ciò che $Gnessun altro:nessun'altra; $R ha mai fatto prima: stanare e uccidere Sin'Dall. Portami la sua zampa come prova della tua impresa.$B$BRintracciarla non sarà un compito facile.",
  obj = "Ajeck Rouack, della Nesingwary's Expedition, vuole che tu uccida Sin'Dall e torni con la sua zampa.",
  progress = "Come procede la caccia a Sin'Dall?",
  reward = "Davvero notevole, non c'è che dire! Sei $Gun vero maestro:una vera maestra; della caccia alla tigre, $N!",
  en_title = "Tiger Mastery",
  en_obj = "Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw.",
}
T[189] = {
  title = "Bloodscalp Ears",
  desc = "Maledetti troll! Stanno facendo fuori i nostri agenti nella giungla! Ho già perso un bel po' delle mie guardie migliori negli scontri con loro. I costi si accumulano! Come lo spiego a Baron Revilgaz?$B$BUn'azione decisa... Pensa, Kebok... non ti hanno messo al posto che occupi oggi per startene con le mani in mano... Ci sono! Tu... $N, giusto? Mi aiuterai, vero? C'è da guadagnarci!$B$BEcco l'accordo... tu mi porti le orecchie di quindici troll Bloodscalp, e io ti ricompenso bene.",
  obj = "Procurati 15 Bloodscalp Ear e riportale a Kebok, a Booty Bay.",
  progress = "Hai avuto successo, spero? Sono dappertutto, quei troll. Sudici diavoli.$B$BOh sì, questo mi ricorda una cosa! Dillo anche ai tuoi amici, eh? Ci farebbe comodo parecchio aiuto!",
  reward = "Oh, eccellente, eccellente. Questo aiuterà un po', per il momento...$B$B<La sua voce si spegne mentre borbotta di margini di profitto e di costi...>$B$BCosa? Sei ancora qui? Una ricompensa? Ah, giusto... certo, ecco, prendi questo... dovrebbe bastare e avanzare.",
  en_title = "Bloodscalp Ears",
  en_obj = "Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.",
}
T[190] = {
  title = "Maestria nella caccia alla pantera",
  desc = "Se vuoi partecipare alla caccia con questo gruppo di assi che Hemet ha radunato, dovrai dimostrare di essere $Gun abile cacciatore:un'abile cacciatrice; di pantere. Cominceremo con qualcosa di semplice, non preoccuparti. Vediamo se riesci a uccidere 10 Young Panther, per cominciare.$B$BRintracciarle è solo metà della sfida...",
  obj = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu uccida 10 Young Panther.",
  progress = "Un vero cacciatore di pantere sarebbe in giro per i campi, a braccare la sua preda. Mostra un po' di impegno per il tuo obiettivo, $C, e torna là fuori.",
  reward = "Un buon inizio, $N!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers.",
}
T[191] = {
  title = "Maestria nella caccia alla pantera",
  desc = "Ora sei $Gpronto:pronta; ad alzare il livello. Se vuoi dimostrarti $Gdegno:degna; di frequentare gente del calibro di questi esperti di caccia grossa, dovrai dimostrare di saper uccidere 10 Panther.$B$BQuei bestioni sono più resistenti. Non sono facili come quelle giovani che uccidevi prima.",
  obj = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu uccida 10 Panther.",
  progress = "Va' a uccidere 10 Panther! Facci vedere cosa sai fare!",
  reward = "Esecuzione perfetta, $N!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers.",
}
T[192] = {
  title = "Maestria nella caccia alla pantera",
  desc = "Ora viene la parte difficile. Un vero cacciatore di pantere può dimostrare la sua abilità abbattendo le Shadowmaw Panther, le più letali di Stranglethorn. Dimostraci che sai uccidere 10 di queste bestie.$B$BSe pensi che sia difficile seguirne le tracce, aspetta di provare a ucciderne una...",
  obj = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu uccida 10 Shadowmaw Panther.",
  progress = "Che ci fai qui, $N! Dovresti strisciare nella boscaglia, cercando di uccidere 10 Shadowmaw Panther. Credevo che ti considerassi $Gun cacciatore:una cacciatrice; di grossa selvaggina?",
  reward = "Hai fatto un ottimo lavoro, $N!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers.",
}
T[193] = {
  title = "Maestria nella caccia alla pantera",
  desc = "Hai quasi dimostrato di essere $Gun maestro:una maestra; nella caccia alla pantera. Una pantera di nome Bhag'thera si aggira per la giungla. Finora ha eluso il nostro gruppo. Vediamo se riesci a usare la tua abilità per uccidere il grande Bhag'thera.$B$BPortami la Fang of Bhag'thera e ti sarai $Gguadagnato:guadagnata; il mio rispetto!",
  obj = "Sir S. J. Erlgadin, della Nesingwary's Expedition, vuole che tu gli porti la Fang of Bhag'thera.",
  progress = "Bhag'thera può rivelarsi una bestia sfuggente. Come procede la caccia?",
  reward = "Dunque il grande Bhag'thera è morto! Alla tua salute, $N. Sei davvero $Gun:una; $C possente!",
  en_title = "Panther Mastery",
  en_obj = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.",
}
T[194] = {
  title = "Maestria nella caccia al raptor",
  desc = "Quindi credi che le tue abilità di caccia siano in forma smagliante? Posso metterle alla prova in un attimo. Addentrati in quella giungla e uccidi 10 Stranglethorn Raptor. Vedremo quanto sei $Gbravo:brava; nella caccia grossa.$B$BE no, non ti dirò dove trovarli! Scovare le bestie è metà della sfida.",
  obj = "Hemet Nesingwary vuole che tu uccida 10 Stranglethorn Raptor.",
  progress = "Non ho mai conosciuto un cacciatore che abbia abbattuto qualcosa standosene intorno al fuoco del campo. Avevi intenzione di uccidere quegli Stranglethorn Raptor o speravi che morissero di vecchiaia?",
  reward = "Ben fatto, $Gvecchio mio:mia signora;!",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors.",
}
T[195] = {
  title = "Maestria nella caccia al raptor",
  desc = "Ora alziamo il livello della sfida e vediamo se sei all'altezza. Avventurati nella giungla e abbatti 10 di quei dannati Lashtail Raptor. Vediamo cosa sai fare!",
  obj = "Hemet Nesingwary vuole che tu uccida 10 Lashtail Raptor.",
  progress = "Un vero cacciatore si concentra sulla sua preda. Tu, $Gamico mio:amica mia;, sembri più $Ginteressato:interessata; a chiacchierare intorno al fuoco del campo. Ora vai là fuori e uccidi 10 Lashtail, prima che io ripulisca da loro l'intera dannata giungla in una sola battuta di caccia.",
  reward = "Ecco come ci si guadagna un trofeo o due sopra il vecchio camino! Bella caccia, $N!",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill 10 Lashtail Raptors.",
}
T[196] = {
  title = "Maestria nella caccia al raptor",
  desc = "Vediamo come te la cavi con la prossima sfida. Là fuori c'è una razza di raptor molto astuta. Li chiamiamo Jungle Stalker. Sono molto più difficili da scovare e da uccidere delle altre razze con cui hai tentato la fortuna finora. Uccidi 10 Jungle Stalker e ti darò una soffiata sulla caccia migliore di tutte.",
  obj = "Hemet Nesingwary vuole che tu uccida 10 Jungle Stalker.",
  progress = "Bah! Che ci fai lì senza far niente, $N! Un vero cacciatore di grossa selvaggina non si arrende mai quando ha la preda nel mirino. Quei Jungle Stalker non verranno di corsa a questo fuoco per buttarcisi dentro. $GChe ragazzo sciocco:Che ragazza sciocca;.",
  reward = "Oh oh! Abbiamo $Gun vero sterminatore:una vera sterminatrice; di raptor! Ben fatto, $Gvecchio mio:bella signora;!",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill 10 Jungle Stalkers.",
}
T[197] = {
  title = "Maestria nella caccia al raptor",
  desc = "Visto che nella giungla ti sei $Gdimostrato:dimostrata; così intraprendente, lascia che ti parli di un raptor feroce che nemmeno io sono riuscito a uccidere. Ajeck, qui, chiama questo astuto raptor Tethis.$B$BSe vuoi dimostrare di essere $Gun vero maestro:una vera maestra;, uccidi Tethis e portami il suo artiglio. Sarebbe un'impresa che nessun altro cacciatore di grossa selvaggina ha mai compiuto.",
  obj = "Hemet Nesingwary vuole che tu uccida Tethis, un raptor sfuggente e pericoloso di Stranglethorn.",
  progress = "Come procede la caccia a Tethis? Hai seguito le sue tracce fin qui all'accampamento, eh?",
  reward = "Master $N, $Glo sterminatore:la sterminatrice; di raptor!$B$BSuona bene, eh?",
  en_title = "Raptor Mastery",
  en_obj = "Hemet Nesingwary wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.",
}
T[198] = {
  title = "Provviste per Private Thorsen",
  desc = "Mmh. Sì, in effetti avrei qualcosa da farti fare. Lieutenant Doren e i suoi seguaci, su a nord, hanno bisogno delle solite provviste da parte nostra.$B$BNon sono state consegnate, e con i troll all'attacco mi serve qualcuno che se ne occupi. L'accampamento di Doren si trova a nord-ovest della strada, all'ingresso di Stranglethorn da Duskwood. Consegna le provviste a Private Thorsen; se non è nell'accampamento, starà pattugliando la zona a sud. Se ne occuperà lui.$B$BBada, se fallisci, dovrai risarcirmi.",
  obj = "Consegna le Miscellaneous Goblin Supplies a Private Thorsen.",
  progress = "Sì? Cosa vuoi? Oh, le provviste dei goblin. Strano vedere $Gun:una; $R che le consegna, di solito mandano uno dei loro. Non importa... non le hai toccate, vero? Bene, bene... non vorremmo che succedesse qualcosa alle nostre mine, oh no.",
  reward = "Queste mine ci aiuteranno a difenderci da quell'animale di Kurzen e dai suoi uomini. Grazie per averle portate. Se cerchi altro lavoro, probabilmente posso trovarti qualcosa da fare. E non dovrai avere a che fare con quei goblin, eh?",
  en_title = "Supplies to Private Thorsen",
  en_obj = "Deliver the Miscellaneous Goblin Supplies to Private Thorsen.",
}
T[199] = {
  title = "Un'oscura minaccia incombe",
  desc = "Prendi un campione della polvere dall'odore strano.",
  obj = "Torna da Chief Engineer Hinderweir e mostragli l'indizio che hai scoperto.",
  progress = "Hai per caso scoperto qualche indizio, $N?",
  reward = "Questa è una scoperta allarmante, a dir poco!",
  en_title = "A Dark Threat Looms",
  en_obj = "Return to Chief Engineer Hinderweir and show him the clue that you discovered.",
}
T[200] = {
  title = "Bookie Herod",
  desc = "Se Kurzen conosce il segreto di Thorsen, allora abbiamo una spia tra noi. Dobbiamo scoprire come è trapelato il segreto!$B$BIl contatto di Thorsen nell'accampamento di Kurzen era Bookie Herod. Herod è l'ufficiale della logistica di Kurzen e sa tutto su come funziona il Kurzen's Compound. Se riesci a prendere gli appunti o i registri di Herod, forse potremo scoprire come è stato smascherato Thorsen.$B$BQuando eravamo ancora con Kurzen, l'ufficio di Bookie era all'ultimo piano dell'unica casa a due piani dell'accampamento. I suoi registri sono probabilmente ancora lì.",
  obj = "Trova i Bookie Herod's Records.",
  reward = "Questi sono gli appunti e i registri di Bookie Herod.$B$BTra questi ci sono: un elenco delle provviste dell'accampamento, richieste di materiali da parte di Colonel Kurzen e varie lettere e corrispondenze.",
  en_title = "Bookie Herod",
  en_obj = "Find Bookie Herod's Records.",
}
T[201] = {
  title = "Indaga sull'accampamento",
  desc = "Mi è giunta voce di un gruppo di cacciatori che si è accampato a monte del campo minerario della Venture Company sul Lake Nazferiti. Ora, di solito non me ne importerebbe, ma, per quanto sembri improbabile, ho sentito che tra quei cacciatori c'è Hemet Nesingwary. Ha di certo le conoscenze giuste, se capisci cosa intendo, e la prudenza non è mai troppa.$B$BPerché non vai a dare un'occhiata all'accampamento, $N, a vedere cosa stanno combinando?",
  obj = "Trova l'accampamento dei cacciatori e riferisci la sua posizione a Krazek, a Booty Bay.",
  progress = "Allora? Hai avuto fortuna nel trovare l'accampamento?",
  reward = "Mmm, quindi le mie informazioni erano corrette, come al solito. Interessante. Be', non credo che rischino di interferire con i nostri affari, ma forse hanno bisogno di qualcuno dei nostri eccellenti prodotti. Mmm...",
  en_title = "Investigate the Camp",
  en_obj = "Find the hunters' camp and report its location to Krazek in Booty Bay.",
}
T[202] = {
  title = "Colonel Kurzen",
  desc = "Hai dato prova di te più e più volte, e la tua intraprendenza sembra rivaleggiare perfino con quella di Kurzen in persona. Potresti essere la salvezza della nostra banda di ribelli... se riesci a misurarti con Kurzen e a prevalere!$B$BComanda i suoi uomini dal fondo dello Stockpile. Devi entrare in quella caverna, farti strada tra i suoi difensori e affrontare Kurzen e i suoi capi.$B$BAddio, $N. La mia speranza, e il destino dei miei uomini, vengono con te.",
  obj = "Uccidi 6 Kurzen Elite e 4 Kurzen Subchief, e porta Kurzen's Head a Lieutenant Doren, al Rebel Camp.",
  progress = "Oso sperare che Kurzen e i suoi difensori siano morti, $N?",
  reward = "Non osavo credere ai rapporti, ma ci porti la prova che... Kurzen e i suoi capi sono stati sconfitti. Ci hai salvato!$B$BQueste giungle sono piene di minacce di ogni tipo, ma nessuna aveva l'intelletto crudele di Kurzen. Ora che non c'è più, possiamo tutti respirare più tranquilli.",
  en_title = "Colonel Kurzen",
  en_obj = "Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.",
}
T[203] = {
  title = "La seconda ribellione",
  desc = "Contro Colonel Kurzen stiamo combattendo una battaglia persa. Non solo è un tattico brillante, ma ci supera di numero almeno 10 a 1! Per sopravvivere dobbiamo usare contro di lui le sue stesse tattiche clandestine.$B$BEntra nel suo accampamento a est e uccidi i suoi uomini. Tanti. E vattene prima che i rinforzi riescano a chiuderti in trappola.",
  obj = "Uccidi 15 Kurzen Jungle Fighter.$B$BTorna da Sergeant Yohwa, al Rebel Camp.",
  progress = "Spero che la tua caccia sia andata a buon fine, $N. Senza il tuo aiuto non resisteremo a lungo contro di lui.",
  reward = "Ben fatto. La perdita di quei Jungle Fighter allenterà un po' la pressione sul nostro accampamento.$B$BMa ora che hai avuto un assaggio delle forze che affrontiamo, vuoi ancora schierarti dalla nostra parte?",
  en_title = "The Second Rebellion",
  en_obj = "Kill 15 Kurzen Jungle Fighters.$B$BReturn to Sergeant Yohwa at the Rebel Camp.",
}
T[204] = {
  title = "Cattiva medicina",
  desc = "Per avere una possibilità contro Kurzen, dobbiamo privarlo dei suoi guaritori. Si è circondato di un gran numero di Medicine Man che curano le sue truppe con i Jungle Remedy e avvelenano i nostri combattenti con i Venom Fern Extract.$B$BCi servono quei rimedi per curare la nostra gente, e ci serve un campione di quegli estratti da studiare, per poter preparare rimedi nostri. Cerca entrambi nel Kurzen's Compound — i suoi Medicine Man avranno i rimedi, e gli estratti sono probabilmente riposti in qualche cassa di provviste dell'accampamento.",
  obj = "Porta 7 Jungle Remedy e 1 Venom Fern Extract a Sergeant Yohwa, al Rebel Camp.",
  progress = "Aspetto quei rimedi e quell'estratto, $N.",
  reward = "Ben fatto, $N. Grazie a questi rimedi più di noi resteranno in vita e in grado di combattere. E gli estratti ci aiuteranno a creare rimedi nostri.",
  en_title = "Bad Medicine",
  en_obj = "Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.",
}
T[205] = {
  title = "Stregoneria troll",
  desc = "Mentre studio le leggende che hai recuperato, raccogli per me gli strumenti della malvagia magia troll. Entra nel territorio dei troll Skullsplitter, un'altra tribù, lontano a sud, e procurati degli Skullsplitter Fetish dai loro Witch Doctor e Mystic.",
  obj = "Porta 4 Skullsplitter Fetish a Brother Nimetz, al Rebel Camp.",
  progress = "Hai quei feticci, $N? Potrebbero custodire il segreto della degradazione di Kurzen... devo saperlo!",
  reward = "Grazie. Studierò questi feticci e vedrò se custodiscono il segreto della caduta di Kurzen nel male.",
  en_title = "Troll Witchery",
  en_obj = "Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.",
}
T[206] = {
  title = "Mai'Zoth",
  desc = "Kurzen sarà anche morto, ma... ciò che lo ha spinto al male vive ancora! Con i miei studi ho scoperto questo: un Ogre Mage — Mai'Zoth — vive in un Ogre Mound tra le montagne orientali di Stranglethorn. Si dice che usi una magia capace di controllare la mente, e non ho dubbi che sia stato lui a corrompere Kurzen.$B$BSe Mai'Zoth resterà in vita, il suo male potrebbe influenzare altri, e perfino far emergere un altro Kurzen.$B$BUccidilo, e portami il suo Mind's Eye, l'artefatto che usa per corrompere gli altri.",
  obj = "Porta il Mind's Eye a Brother Nimetz, al Rebel Camp.",
  progress = "Ti do la mia benedizione. La forza di Mai'Zoth è pari solo alla sua malvagità.",
  reward = "Aha! Ce l'hai fatta! Sei una grande forza del bene, $N, e che la tua forza non si affievolisca mai!$B$BStudierò questo Mind's Eye e stabilirò se può essere usato per il bene. Altrimenti... dovrà essere distrutto.",
  en_title = "Mai'Zoth",
  en_obj = "Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.",
}
T[207] = {
  title = "Il mistero di Kurzen",
  desc = "Un tempo Colonel Kurzen era un uomo grande e nobile — devo scoprire cosa lo ha fatto sprofondare nella depravazione! Forse è sotto l'influsso della magia troll. Per averne conferma, devo studiare alcune delle loro leggende.$B$BCi sono 4 tavolette nascoste tra le rovine troll di Stranglethorn. Devo vedere cosa c'è scritto su queste tavolette! Trascrivi i loro segni e riportami le trascrizioni.$B$BLa prima tavoletta è nelle Bal'lal Ruins, la seconda nella Vile Reef, e la terza e la quarta nelle Ruins of Zul'Kunda.",
  obj = "Trova le 4 tavolette e riporta le loro leggende a Brother Nimetz.",
  progress = "$N! Hai le leggende troll? Devo conoscere i loro segreti!",
  reward = "Grazie, $N. Studierò queste leggende per vedere se c'è qualche legame tra i troll e il male che si è impadronito di Colonel Kurzen.",
  en_title = "Kurzen's Mystery",
  en_obj = "Find the 4 tablets and bring their legends back to Brother Nimetz.",
}
T[208] = {
  title = "Cacciatore di grossa selvaggina",
  desc = "$N, sei $Gun cacciatore degno:una cacciatrice degna; della nostra compagnia. Dai campi di battaglia di Lordaeron alla giungla più profonda, raramente ho visto un'abilità con le armi pari a quella che hai dimostrato.$B$BHai ucciso la feroce Sin'Dall, lo sfuggente Bag'thera e l'infido Tethis. Ma il vero premio è la testa di King Bangalash. Quella tigre bianca è il motivo per cui sono qui. È da un bel po' di tempo che ho messo gli occhi su di lui. Uccidi King Bangalash e la tua abilità di caccia si dimostrerà seconda a nessuno.",
  obj = "Hemet Nesingwary vuole che tu gli porti la testa di King Bangalash, la grande tigre bianca.",
  progress = "Vedo che sei $Gtornato:tornata;, $Gvecchio mio:ragazza mia;. King Bangalash mi ha fatto tornare all'accampamento strisciando molte volte. Tieni duro.",
  reward = "Dannatamente ben fatto! Benissimo! Congratulazioni, $N, per essere $Griuscito:riuscita; dove altri hanno fallito.$B$BSono onorato di annoverarti tra i compagni della nostra grande squadra di caccia. Nessuno dubiterà mai della tua abilità nella caccia e nel seguire le tracce!$B$BAlla tua salute, dico io! Alla salute!",
  en_title = "Big Game Hunter",
  en_obj = "Hemet Nesingwary wants you to bring him the head of King Bangalash, the great white tiger.",
}
T[209] = {
  title = "Skullsplitter Tusks",
  desc = "Uccidere abbastanza tigri da sostenere l'esportazione di zanne di tigre verso le isole dei South Seas è costoso e difficile. Per fortuna abbiamo messo a punto una tecnica che ci permette di prendere dei comuni oggetti simili a corna e trasformarli in falsi impossibili da scoprire.$B$BLa cosa più somigliante che abbiamo trovato, incredibilmente, sono le zanne dei troll Skullsplitter.$B$BEhi, prima che tu dica qualcosa: occhio non vede, cuore non duole, giusto? Portamene un bel po', così possiamo metterci al lavoro sulla spedizione del mese!",
  obj = "Procura 18 Skullsplitter Tusk e riportali a Kebok.",
  progress = "Tipi tosti, eh? Allora, hai avuto fortuna? Scusa se sembro impaziente, ma questa faccenda è stata una grossa spina nel fianco! Allora?",
  reward = "Ah, ottimo lavoro, ottimo lavoro! Uff, anche se avresti potuto pulire meglio il... Be', non importa, non importa! Grazie, $N: grazie al tuo aiuto la nostra attività vedrà di sicuro aumentare produzione e rendimento! Bene, bene, e ora passiamo ad altro...",
  en_title = "Skullsplitter Tusks",
  en_obj = "Acquire 18 Skullsplitter Tusks and return them to Kebok.",
}
T[210] = {
  title = "La cucina di Krazek",
  desc = "All'accampamento cucino quasi sempre io. Ed era un gran lavoro, finché non ho comprato una pentola da cucina meccanica da un mercante goblin di Booty Bay. La pentola è una meraviglia! Mi ha fatto risparmiare ore e ore... finché non si è rotta!$B$BPuoi riportare la pentola al goblin per me, così la aggiusta? Si chiama Krazek.",
  obj = "Porta Krazek's Crock Pot al goblin Krazek.",
  progress = "Salve! Mi hai portato qualcosa?",
  reward = "Oh, vedo, è una Krazek's Crock Pot! Un lavoro geniale, ma ogni tanto può rompersi una molla o saltare un ingranaggio. Vediamo cosa c'è che non va in questa...$B$BAha! Il caricatore a vapore è arrugginito, ha una guarnizione a snodo incrinata e al fobulatore mancano dei denti. Mi sorprende che la pentola riuscisse anche solo a far bollire una rapa in questo stato!$B$BSe posso aggiustarla? Certo che posso aggiustarla!$B$BMa c'è un prezzo. Oh sì, c'è sempre un prezzo...",
  en_title = "Krazek's Cookery",
  en_obj = "Bring Krazek's Crock Pot to Krazek the goblin.",
}
T[212] = {
  title = "Un piatto da servire freddo",
  desc = "Uno dei miei piatti più famosi è il basilisco freddo in vinaigrette al lime. Ma il problema è che... la carne è impossibile da tenere fresca, e stasera devo servire il piatto per il compleanno di un nobile!$B$BQuindi, se riesci a portarmi in fretta un Chilled Basilisk Haunch da un Cold Eye Basilisk appena ucciso, ti dovrò un banchetto da re!$B$BSi sa che i Cold Eye Basilisk si aggirano lungo le dune della spiaggia nel nord-ovest di Stranglethorn, quindi hai molta strada da fare. E sii $Grapido:rapida;!",
  obj = "Uccidi un Cold Eye Basilisk, prendi un Chilled Basilisk Haunch e riportalo ad Angus Stern, al Blue Recluse.$B$B<Per riuscire in questa missione non devi liberare il tuo spirito.>",
  progress = "$N! Hai quel cosciotto? Devo cominciare presto a prepararlo, o il banchetto sarà rovinato!",
  reward = "Ah, questo andrà benissimo! Mille, mille grazie!$B$BOra, se vuoi scusarmi, devo tagliare, marinare e guarnire il cosciotto per il banchetto.",
  en_title = "A Meal Served Cold",
  en_obj = "Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse.",
}
T[213] = {
  title = "Acquisizione ostile",
  desc = "Stavolta l'ha fatta grossa! Già era abbastanza grave che Gelriz facesse fuori a spintoni i magnati nominati dai principi del commercio, ora cerca pure di mettersi in mezzo agli affari del pirata più famigerato!$B$BRevilgaz non lo tollererà, e mi ha detto di occuparmi del problema a modo mio.$B$BA modo mio? Furto. I geologi della Venture Co. vicino al Lake Nazferiti sono molto interessati a quegli strani cristalli blu che trovano nelle miniere. Portami dei campioni della pietra presi dai loro geologi; non m'importa cosa dovrai fare per procurarteli.",
  obj = "Recupera 8 Tumbled Crystal e riportali a Kebok, a Booty Bay.",
  progress = "Mi servono quelle pietre, $N. Con qualunque mezzo necessario! Fallo e basta, non darmi i dettagli!$B$BContano i risultati, $N, niente di più, niente di meno.",
  reward = "Affascinante. Che i cristalli siano stati levigati con questo procedimento può solo significare che intendono usarli come una specie di combustibile o come qualche altro catalizzatore. Di più non so. Bisognerà spedire dei campioni a Head Chemist Gigglefont.",
  en_title = "Hostile Takeover",
  en_obj = "Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.",
}
T[214] = {
  title = "Red Silk Bandanas",
  desc = "Non è un segreto che il marchio della Defias Gang siano le loro bandane rosse. Ma abbiamo scoperto che il materiale di cui sono fatte indica il grado del membro.$B$BDetto questo, voglio che tu elimini più Defias di alto grado che puoi. I membri di grado più alto si troveranno senz'altro nel nascondiglio segreto di VanCleef. Quando hai finito, portami 10 Red Silk Bandana come prova della loro morte e ti ricompenserò. Buona fortuna, $N.",
  obj = "Scout Riell, alla Sentinel Hill Tower, vuole che le porti 10 Red Silk Bandana.",
  progress = "Stai riprendendo la nostra terra alla banda dei Defias? Se è così, mostrami 10 Red Silk Bandana come prova.",
  reward = "Ben fatto, $N! A nome della People's Militia ti saluto per il tuo impegno. Presto restituiremo questa terra alla gente, con l'aiuto di anime coraggiose come te.",
  en_title = "Red Silk Bandanas",
  en_obj = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.",
}
T[215] = {
  title = "Segreti della giungla",
  desc = "Grazie per avermi salvato, $N. So cosa sembra, ma... lasciami spiegare.$B$BLieutenant Doren mi aveva incaricato di arruolarmi di nuovo tra gli uomini di Kurzen, per spiarli e portare ai ribelli informazioni di cui hanno un disperato bisogno. Quello che hai visto qui era, credevo, la mia occasione per infiltrarmi nel Kurzen's Compound. Mi sbagliavo, e grazie ancora per avermi salvato.$B$BEra una missione segretissima, quindi non devi dirlo a nessuno. Ma se parli con Doren, te lo spiegherà lui.",
  obj = "Parla con Lieutenant Doren, al Rebel Camp.",
  reward = "Sì, quello che ti ha detto Thorsen è vero. Devi essere $Gdiscreto:discreta; su questa faccenda. Un tempo noi ribelli eravamo ferocemente leali a Colonel Kurzen. Ma la corruzione di Kurzen era tale che la nostra passione si è trasformata in rabbia. Se si venisse a sapere che di recente Private Thorsen ha avuto a che fare con gli uomini di Kurzen, una notte si ritroverebbe con la gola tagliata.$B$BPer quanto ne so, solo Sergeant Yohwa, Thorsen e io eravamo al corrente della missione di Thorsen. Ma dev'esserci qualcun altro. Un traditore.",
  en_title = "Jungle Secrets",
  en_obj = "Speak with Lieutenant Doren at the Rebel Camp.",
}
T[216] = {
  title = "Tra l'incudine e i Thistlefur",
  desc = "I furbolg Thistlefur minacciano la nostra espansione! Thistlefur Village, a est di qui, blocca la via tra noi e Splintertree Post. È un percorso che aggirerebbe il villaggio di Astranaar; senza di esso, diamo all'Alleanza una via di espansione in più.$B$B$N, non possiamo permettere... un divario nelle vie di espansione!$B$BVa' a Thistlefur Village e dirada i furbolg. Riceverai un compenso per questo incarico, ma soprattutto farai il tuo dovere per l'Orda!",
  obj = "Abbatti 12 Thistlefur Avenger e 12 Thistlefur Shaman; la maggior parte si trova a est dello Zoram Strand, a Thistlefur Village. Fatto questo, torna da Karang Amakkar allo Zoram'gar Outpost, in Ashenvale.",
  progress = "Hai portato la battaglia ai Thistlefur? Con una via libera tra le nostre basi, le nostre possibilità di prenderci tutta Ashenvale aumentano moltissimo.",
  reward = "Ben fatto, $C, ben fatto! Continuerò a mandare forze a diradare i furbolg, ma almeno posso contare su un'altra via, libera dagli impicci dell'Alleanza. La conquista di Ashenvale da parte dell'Orda è ormai in pieno svolgimento!$B$BOggi ti sei $Gguadagnato:guadagnata; la paga, $Geroe:eroina;. Ti saluto!",
  en_title = "Between a Rock and a Thistlefur",
  en_obj = "Take down 8 Thistlefur Avengers and 8 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village.  Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale.",
}
T[217] = {
  title = "In difesa delle terre del re",
  desc = "$N, i nostri esploratori hanno identificato il capo di questa recente incursione dei trogg. A quanto pare, le bestie di Loch Modan seguono gli ordini di un capotribù di nome Grawmug. Grawmug però è ben protetto: le sue due guardie migliori, Gnasher e Brawler, non si allontanano mai da lui.$B$BSe te la senti, $N, voglio che guidi tu la missione per eliminare Grawmug e i suoi due scagnozzi. Con i capi dei trogg morti, forse avremo una possibilità di ricacciare queste bestie sottoterra.",
  obj = "Uccidi il capo dei trogg, Grawmug, e le sue due guardie, Gnasher e Brawler, poi fai rapporto a Captain Rugelfuss nella torre di guardia meridionale.",
  progress = "Grawmug e le sue due guardie, Gnasher e Brawler, sono ancora vivi. La tua missione non sarà compiuta finché non saranno morti tutti e 3. L'impero dei nani conta su di te, $N.",
  reward = "Eccellente, $N! Hai riportato la speranza a Loch Modan. Con Grawmug morto, abbiamo più possibilità di spazzare via i trogg da queste terre.",
  en_title = "In Defense of the King's Lands",
  en_obj = "Kill the Trogg leader, Grawmug, and his two guards, Gnasher and Brawler then report back to Captain Rugelfuss in the southern guard tower.",
}
T[218] = {
  title = "Il diario rubato",
  desc = "Il mio diario! L'hanno portato nella caverna. Quello che l'aveva... era un bestione con strani segni sulla pelle e sul viso. Di più non sono riuscito a vedere.$B$BCon i troll finora hai avuto fortuna: forse potresti andare a riprendermelo?",
  obj = "Grelin Whitebeard vuole che tu uccida Grik'nir the Cold e recuperi il suo diario.",
  progress = "$N! Novità?",
  reward = "Magnifico, $N! Mille grazie per aver recuperato il mio taccuino. Beh, sembra che la situazione dei troll qui a Coldridge Valley sia sotto controllo e non dia grandi motivi di preoccupazione.$B$BQuando avrò dato gli ultimi ritocchi al mio rapporto, mi servirà qualcuno che lo porti a mio fratello Senir.",
  en_title = "The Stolen Journal",
  en_obj = "Grelin Whitebeard wants you to kill Grik'nir the Cold, and retrieve his journal.",
}
T[219] = {
  title = "Disperso in azione",
  desc = "Finalmente, amici dell'Alleanza!$B$BAiuto... vi prego...$B$BL'ultima cosa che ricordo è che quegli orchi immondi hanno sopraffatto il nostro reggimento. Quasi tutti gli uomini sono stati uccisi. Ho preso un colpo forte alla testa e tutto è diventato nero. Adesso mi tengono prigioniero in questa grotta. Aiutatemi, sono ferito gravemente.$B$BMi servirà aiuto per tornare in paese... vi prego... siete la mia ultima speranza...",
  obj = "Proteggi Corporal Keeshan nel viaggio di ritorno a Redridge.",
  progress = "Sì?",
  reward = "Hai servito bene il Regno, $C. Grazie per aver aiutato Corporal Keeshan a fuggire da quei temuti orchi Blackrock. Sarai $Gricompensato:ricompensata; per le tue azioni coraggiose di oggi.",
  en_title = "Missing In Action",
  en_obj = "Protect Corporal Keeshan on the journey back to Redridge.",
}
T[220] = {
  title = "Il richiamo dell'acqua",
  desc = "Islen avrà un ultimo compito per te prima di ricompensarti con il tuo prossimo totem. La fiala d'acqua che ti ho dato è necessaria per quel compito, qualunque sia.$B$BOra va' e trovala. Ci rivedremo, un giorno.",
  obj = "Porta la Vial of Purest Water a Islen Waterseer, nelle Barrens.",
  progress = "Salve di nuovo, $N. Ti trovo bene.$B$BCosa ti riporta da me così presto?",
  reward = "Ah, una fiala d'acqua creata e benedetta da Brine, e raccolta da te, nientemeno.$B$BIl liquido di questa fiala sarà fondamentale per creare una sapta per te, ma servirà anche per un altro compito.$B$BLa sapta che creerò per te andrà usata per vedere gli spiriti dell'acqua al santuario della Silverpine Forest, a sud dell'Undercity. Le gocce rimaste... be', delle gocce rimaste ti parlerò se ti senti $Gpronto:pronta;.$B$BSei $Gpronto:pronta; per un altro viaggio, $N?",
  en_title = "Call of Water",
  en_obj = "Bring the Vial of Purest Water to Islen Waterseer in the Barrens.",
}
T[221] = {
  title = "Worgen nei boschi",
  desc = "Avrai notato qualche worgen più grosso che si aggira con gli Shadow Weaver nei boschi, no? Da quel che possiamo dire, sono questi Dark Runner a fare il grosso delle file dei worgen.$B$BNelle mie perlustrazioni ho notato anche che hanno invaso il Rotting Orchard, a sud-ovest del paese. Questi worgen sono un po' più duri degli ultimi che hai affrontato.$B$BSta' in guardia.",
  obj = "Uccidi 12 worgen Nightbane Dark Runner per Calor, a Darkshire.",
  progress = "Già di ritorno, $N? Spero che tu non sia $Gvenuto:venuta; a dirmi che hai rinunciato.",
  reward = "Te la sei cavata bene contro i Dark Runner, $N. Ma sembra che il loro numero sia inesauribile. Ogni volta che facciamo progressi, ne spuntano altri a riempire le file.$B$BQual è il potere maligno che li attira qui? Perché sono venuti a turbare il nostro regno infelice...$B$BIo riporrò la mia fiducia in Master Carevin. Di sicuro andrà a fondo della questione.",
  en_title = "Worgen in the Woods",
  en_obj = "Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire.",
}
T[222] = {
  title = "Worgen nei boschi",
  desc = "Quel che hai fatto finora mi ha convinto che sei $Gpronto:pronta; ad affrontare i worgen più duri che infestano i boschi.$B$BFra i worgen che si sono fatti una nuova casa qui, i Vile Fang e i Tainted One si sono rivelati i più pericolosi. Si sono sistemati vicino ad alcune caverne e nella miniera a sud.$B$BDa lontano si vede perfino la luce dei loro falò...",
  obj = "Uccidi 8 worgen Nightbane Vile Fang e 8 Nightbane Tainted One per Calor, a Darkshire.",
  progress = "Bestie che mettono paura, vero? Ma non temere, $N: chi sta dalla parte della Luce non cadrà mai!",
  reward = "$N, a dirti la verità non credevo che saresti $Garrivato:arrivata; fin qui, ma è chiaro che sei $Gun:una; $C con cui fare i conti. Anzi, se vuoi unirti ufficialmente alla lotta di Master Carevin, ti scriverò volentieri una lettera di raccomandazione.",
  en_title = "Worgen in the Woods",
  en_obj = "Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire.",
}
T[223] = {
  title = "Worgen nei boschi",
  desc = "Ecco qua, $N. Porta questo messaggio a Master Carevin.$B$B<Tira fuori in fretta un pezzo di pergamena sbiadita e te lo porge.>$B$BAncora qualcuno come te, e saremo più numerosi della Guardia Notturna! Forse allora potremo portare a termine il lavoro che noi pochi mandiamo avanti oggi.",
  obj = "Porta il biglietto di Calor a Jonathan Carevin.",
  progress = "Sì, che c'è? Fa' in fretta, ho questioni urgenti di cui occuparmi.",
  reward = "Scusa l'accoglienza fredda, $N, ma come avrai capito sono un uomo estremamente occupato. Vedo che hai fatto colpo su Calor — e ti assicuro che non è cosa da poco — e che ti ha dato la sua raccomandazione.$B$BIn giro c'è gente poco raccomandabile, $N, e ci serve l'aiuto di tutti quelli che hanno dimostrato il proprio valore. Combattiamo contro i demoni, i non morti e chi dà loro aiuto. Sii vigile, sta' $Gattento:attenta;, e non fidarti di nessuno che non aiuti la nostra causa.$B$BGloria nella Luce.",
  en_title = "Worgen in the Woods",
  en_obj = "Bring Calor's note to Jonathan Carevin.",
}
T[224] = {
  title = "In difesa delle terre del re",
  desc = "Dobbiamo proteggere il Loch, $N! Con tanti soldati del re che combattono valorosamente su campi di battaglia lontani, qui in patria siamo sopraffatti. I trogg sbucano da ogni fessura! L'infestazione dei trogg è la minaccia più grave per Ironforge. Questi disgustosi mutanti vanno distrutti.$B$BAbbiamo bisogno di te, $Gcoraggioso avventuriero:coraggiosa avventuriera;: parti e annienta la minaccia dei trogg. Uccidi 10 Stonesplinter Troggs e 10 Stonesplinter Scouts e torna a fare rapporto.",
  obj = "Mountaineer Cobbleflint della torre di guardia meridionale vuole che tu uccida 10 Stonesplinter Troggs e 10 Stonesplinter Scouts.",
  progress = "Loch Modan è sotto assedio, $N! Ci serve ogni membro dell'Alleanza in grado di combattere. Hai già ucciso 10 Stonesplinter Troggs e 10 Stonesplinter Scouts?",
  reward = "Ben fatto, $N! Sul campo di battaglia hai dimostrato un coraggio fuori dal comune. Con imprese come la tua vinceremo la guerra contro i trogg. Hai servito bene re Magni.$B$BSe pensi di essere $Gtagliato:tagliata; per questo genere di avventure, ti consiglio di parlare con Mountaineer Gravelgaw. Il capitano gli ha assegnato una pattuglia difficile e sono sicuro che un aiuto gli farebbe comodo. Cerca Gravelgaw appena dentro la torre.",
  en_title = "In Defense of the King's Lands",
  en_obj = "Mountaineer Cobbleflint of the southern guard tower wants you to kill 10 Stonesplinter Troggs and 10 Stonesplinter Scouts.",
}
T[225] = {
  title = "La tomba consunta",
  desc = "Sulla lapide consunta si legge soltanto:$B$BMORGAN LADIMORE$B$B<Guardando meglio, noti che la terra sopra la tomba è stata smossa di recente, e che una buona parte è stata spostata...>",
  obj = "Parla con Sirra Von'Indi, a Darkshire.",
  reward = "Morgan Ladimore?$B$BAhh, sì, certo. La sua è una storia lunga e dolorosa. Lo conoscevo bene, prima che partisse per la guerra, ma è stata l'ultima volta che l'ho visto. Era un uomo nobile e buono, ma ha fatto una brutta fine.$B$BAspetta, qui dovrei avere qualcosa che racconta la storia meglio dei miei ricordi...",
  en_title = "The Weathered Grave",
  en_obj = "Speak with Sirra Von'Indi in Darkshire.",
}
T[226] = {
  title = "Lupi alle calcagna",
  desc = "Io e Sven abbiamo giorni pericolosi davanti, con il negromante a est e tutto il resto. E qui fuori, soli come siamo, il cibo dobbiamo cacciarcelo da noi. Sembra che ogni volta che torno all'accampamento con addosso un po' di carne, dalla foresta sbuchino Starving Dire Wolf o Rabid Dire Wolf in cerca di un boccone. Inutile dirlo: vivere qui fuori è un mestiere pericoloso!$B$BMa se ci liberassi da un po' di quei lupi, per noi sarebbe più facile. Si aggirano soprattutto a nord e a est di qui, vicino al fiume.",
  obj = "Uccidi 12 Starving Dire Wolf e 8 Rabid Dire Wolf, poi torna da Lars a Sven's Camp, al confine occidentale di Duskwood.",
  progress = "Sei ancora a caccia di lupi...?",
  reward = "Oh, bene. Hai diradato parecchio quel branco, e senza quei lupi alle calcagna possiamo concentrarci su Morbent Fel.$B$BTieni, prendi un po' di questi Flash Bundle. Li fanno in città, e molti sono stati donati a Sven per aiutarlo nella sua causa.",
  en_title = "Wolves at Our Heels",
  en_obj = "Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.",
}
T[227] = {
  title = "Morgan Ladimore",
  desc = "<Fruga tra gli scaffali e ne tira fuori un libro rilegato in pelle.>$B$BSe vuoi saperne di più, potresti chiedere ad Althea: è lei che si è occupata dei... guai... con lui, ultimamente.",
  obj = "Parla con Commander Althea Ebonlocke, a Darkshire.",
  reward = "Morgan Ladimore? Mai sentito...$B$BOh, intendi Mor'Ladim! Immagino che tu non conosca la storia.$B$BBe', te la faccio breve. Un non morto errante che si fa chiamare Mor'Ladim si aggira per Duskwood. Da quel che abbiamo raccolto, sembra essere il corpo non morto di Morgan Ladimore, che a quanto pare tu conosci. Ci sta dando problemi di ogni tipo: attacca i Watchman di pattuglia e uccide la gente.$B$B<Ti squadra.>$B$BSembri abbastanza capace: forse potresti dargli pace tu.",
  en_title = "Morgan Ladimore",
  en_obj = "Speak with Commander Althea Ebonlocke in Darkshire.",
}
T[228] = {
  title = "Mor'Ladim",
  desc = "Da quel che mi dicono i miei esploratori, Mor'Ladim vaga per tutta Duskwood, seguendo un percorso strano e tortuoso attraverso il cimitero. L'abbiamo sepolto oltre la casa sulla collina: sai dov'è?$B$BNon c'è niente che io possa fare per aiutarti, ma ti auguro buona fortuna.",
  obj = "Uccidi Mor'Ladim, poi porta il suo teschio a Commander Althea Ebonlocke, a Darkshire.",
  progress = "Non ti biasimo se hai difficoltà con lui, $N. Mor'Ladim ci è già costato alcuni dei nostri Watcher più forti.",
  reward = "L'hai ucciso? Non è cosa da poco, $N! A nome della gente di Darkshire e della Guardia Notturna, ti ringrazio.$B$BAh... c'è però una piccola questione...",
  en_title = "Mor'Ladim",
  en_obj = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.",
}
T[229] = {
  title = "La figlia sopravvissuta",
  desc = "Avrei dovuto dirtelo prima...$B$BCome posso metterla...$B$BMorgan può anche aver creduto che la sua famiglia fosse tutta morta, ma in realtà sua figlia Sarah Ladimore adesso è una Watcher. L'hanno sempre tormentata le... circostanze... della morte del padre. Forse potresti andare tu a darle la notizia.",
  obj = "Parla con Watcher Sarah Ladimore, a Darkshire.",
  reward = "Sì? Mio padre...$B$B<I suoi occhi si abbassano.>$B$BVorrei... che ci fosse stato qualcosa che potevo fare per lui... Se solo gli avessi parlato prima che...",
  en_title = "The Daughter Who Lived",
  en_obj = "Speak with Watcher Sarah Ladimore in Darkshire.",
}
T[230] = {
  title = "Sven's Camp",
  desc = "Scavando nel cumulo, trovi un piccolo libro sporco di terra.$B$BIl libro non ha titolo, ma... contiene informazioni che Sven vorrebbe sapere.",
  obj = "Porta il Book from Sven's Farm a Sven.",
  progress = "Hai trovato cosa?? Ti prego, fammelo vedere...",
  reward = "<Sven legge le pagine del libro, poi lo chiude di colpo.>$B$BQuella figura in ombra che ho visto era un testimone della morte della mia famiglia! Ci sono domande che vorrei fare a quell'uomo... se solo sapessi chi era!",
  en_title = "Sven's Camp",
  en_obj = "Bring the Book from Sven's Farm to Sven.",
}
T[231] = {
  title = "L'amore di una figlia",
  desc = "Tieni, prendi questo e posalo sulla sua tomba. Forse... in qualche modo saprà che sto bene, e che nessuno di noi lo ritiene responsabile di quel che è successo.$B$B<Adesso ha le lacrime agli occhi, mentre si sfila un anello dalla mano destra e te lo preme fra le mani.>$B$BE... grazie, $N.",
  obj = "Porta l'anello di Sarah Ladimore alla tomba di Morgan Ladimore.",
  progress = "Lasciami in pace...",
  reward = "<Una voce spettrale risuona nel vento...>$B$BQuesto è...? Sarah? Può essere che sia ancora viva? Il peso mi si toglie dalle spalle...$B$B$N. Prendi la mia spada, Archeus. Ora che la mia anima trova pace, non me ne faccio più niente. Fu forgiata per fare del bene e, anche se io mi sono dimostrato indegno di impugnarla, forse tu porterai avanti la Luce attraverso di essa.$B$BLys, amore mio...",
  en_title = "A Daughter's Love",
  en_obj = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.",
}
T[233] = {
  title = "Consegna della posta di Coldridge Valley",
  desc = "Mm, non è che ti andrebbe di farmi un favore, $Gragazzo:ragazza;? Oggi dal passo è arrivato un mucchio di lettere, ma non ho il tempo di recapitarle.$B$BSono tutte indirizzate a Talin Keeneye. Lo trovi a ovest, lungo la strada: ha piantato il campo accanto al lago ghiacciato.$B$BChe ne dici?",
  obj = "Consegna il mucchio di lettere a Talin Keeneye.",
  progress = "Sì? Hai qualcosa per me?",
  reward = "Grazie, aspettavo queste lettere da parecchio tempo...$B$BPurtroppo non sono tutte per me. Questa è indirizzata a Grelin Whitebeard. Non è molto lontano, se vuoi portargliela.",
  en_title = "Coldridge Valley Mail Delivery",
  en_obj = "Deliver the stack of letters to Talin Keeneye.",
}
T[234] = {
  title = "Consegna della posta di Coldridge Valley",
  desc = "Se ricordo bene, il campo di Grelin è giù lungo la strada, verso sud-est. Senza dubbio sarà impaziente di ricevere la sua posta.",
  obj = "Consegna la lettera a Grelin Whitebeard.",
  progress = "Posso esserti utile in qualcosa?",
  reward = "Ahh, eccellente. Era un po' che non ricevevo notizie da Ironforge.",
  en_title = "Coldridge Valley Mail Delivery",
  en_obj = "Deliver the letter to Grelin Whitebeard.",
}
T[235] = {
  title = "La caccia di Ashenvale",
  desc = "Attenzione, giovani avventurieri! Le terre selvagge di Ashenvale vi aspettano!$B$BL'Orda ha stabilito una forte presenza nelle terre a nord dei Barrens. I nostri due avamposti, Splintertree Post e Zoram Strand Outpost, si impegnano a portare gloria all'Orda! Chi vuole mettersi alla prova dovrebbe cercare lì una guida. In particolare: Senani Thunderheart, a Splintertree Post, appena a nord dei Barrens, cerca avventurieri disposti a partecipare a una grande caccia di Ashenvale!",
  obj = "Parla con Senani Thunderheart a Splintertree Post, Ashenvale.",
  reward = "Benvenut$Go:a; sulla nuova frontiera, $N. Ashenvale è una terra di opportunità, dove un giovane $C come te può trovare infinite occasioni per dimostrare il proprio valore. Dai un'occhiata all'avamposto qui intorno e assicurati di recarti anche a Zoram Strand, perché l'Orda ha un altro avamposto laggiù.$B$BLa tua presenza qui mi dice che sei venut$Go:a; per saperne di più sulla caccia. Ascolta con attenzione e ti dirò volentieri ciò che ti serve sapere.",
  en_title = "The Ashenvale Hunt",
  en_obj = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[237] = {
  title = "In difesa delle terre del re",
  desc = "Mountaineer Cobbleflint ha detto solo cose buone su di te, $R. Per questo ti affiderò una missione della massima importanza. Dobbiamo tenere sotto pressione le forze dei trogg invasori finché i nostri fratelli nani non torneranno dal fronte dell'Alleanza.$B$BParti per le colline meridionali e uccidi 10 Stonesplinter Skullthumpers e 10 Stonesplinter Seers. I tuoi attacchi ci faranno guadagnare tempo. Torna a fare rapporto quando la missione sarà compiuta.",
  obj = "Mountaineer Gravelgaw nella torre di guardia meridionale vuole che tu uccida 10 Stonesplinter Skullthumpers e 10 Stonesplinter Seers e torni a fare rapporto.",
  progress = "Ci serve più tempo, $R. I tuoi ordini sono di uccidere 10 Stonesplinter Skullthumpers e 10 Stonesplinter Seers. Tieni il nemico sotto pressione finché non ci manderanno rinforzi. Non è il momento di starsene con le mani in mano.",
  reward = "Hai compiuto bene la tua missione, $R. Il re in persona ne sarebbe orgoglioso.$B$BI rinforzi che ci avevano promesso, però, non sono mai arrivati. A quanto pare il fronte dell'Alleanza è un mare cremisi, rosso del sangue dei nostri fratelli caduti. La notizia delle perdite lascia l'amaro in bocca. Ma non dobbiamo lasciare che la loro morte sia vana. In questi tempi cupi dobbiamo stringerci insieme e riportare gloria all'Alleanza.$B$BParla con Mountaineer Wallbang per un nuovo incarico. Ora c'è bisogno di te più che mai.",
  en_title = "In Defense of the King's Lands",
  en_obj = "Mountaineer Gravelgaw in the southern guard tower wants you to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers and report back to him.",
}
T[239] = {
  title = "Il Westbrook Garrison ha bisogno di aiuto!",
  desc = "Il Garrison al nostro confine occidentale ci manda notizia di una crescente attività di gnoll e ladri. Chiedono che inviamo altri soldati di Stormwind... ma non ne abbiamo nessuno da risparmiare!$B$BSe puoi aiutare, ci faresti comodo. Va' a parlare con Deputy Rainer al Westbrook Garrison e scopri di cosa ha bisogno.$B$BIl Garrison è lungo la strada verso ovest. Dopo aver attraversato il ponte sul piccolo ruscello, lo troverai sulla destra.",
  obj = "Recati al Westbrook Garrison e parla con Deputy Rainer.",
  reward = "Ti ha mandato Marshall Dughan, eh? Be', non sei dell'esercito, ma se ti manda Dughan per me va benissimo!$B$BLa nostra situazione è, a dir poco, tesa. Spero che tu possa darci una mano.",
  en_title = "Westbrook Garrison Needs Help!",
  en_obj = "Go to the Westbrook Garrison and speak with Deputy Rainer.",
}
T[240] = {
  title = "Torna da Jitters",
  desc = "Ed eccoci qui: \"Crab\" Cakes ala Grual!",
  obj = "Torna da Jitters con i Dusky Crab Cake.",
  progress = "$N, sei qui! Hai il mio cibo?!?",
  reward = "Aha! Grazie, $N. Ci voleva proprio!$B$BE tieni, lascia che ti paghi per questi!",
  en_title = "Return to Jitters",
  en_obj = "Return to Jitters with the Dusky Crab Cakes.",
}
T[244] = {
  title = "Gnoll in avanzata",
  desc = "Salute, $c. Ho l'incarico di pattugliare questo tratto di strada. Anche se per ora la strada è sicura, ho visto accampamenti di gnoll a nord e a est di qui.$B$BLakeshire deve sapere di questa forza di gnoll che si sta radunando! Presentati a Deputy Feldon a Lakeshire e riferiscigli degli gnoll. Se lo farai, sono certo che Feldon ti offrirà la paga di un esploratore.$B$BFeldon di solito ispeziona la zona a sud del ponte per Lakeshire.",
  obj = "Riferisci a Deputy Feldon.",
  reward = "Ci sono gnoll di Redridge così vicini a Elwynn?? Potrebbero essere pronti ad avanzare nella nostra patria. Presto la gente di Lakeshire potrebbe non essere l'unica popolazione umana sotto assedio!$B$BEcco la tua paga, anche se ci porti notizie funeste. E arrivano in un brutto momento, perché siamo mal equipaggiati per affrontarle.",
  en_title = "Encroaching Gnolls",
  en_obj = "Report to Deputy Feldon.",
}
T[245] = {
  title = "Minacce a otto zampe",
  desc = "Salve, $C. Avrai visto quei ragni che si sono impadroniti del confine occidentale, no? Quelle minacce a otto zampe sono troppo per noi, e la comandante non ha uomini a sufficienza da mandare così lontano da Darkshire.$B$BMi dispiace chiedertelo, ma sembri in grado di occupartene. Non posso prometterti niente di grande valore, ma posso ricompensarti se ci aiuti a stanare quegli insetti immondi.$B$BAh, e un consiglio: se puoi, evita il loro veleno.",
  obj = "Uccidi 15 Pygmy Venom Web Spider, poi torna a riferire a Watcher Dodds, a Duskwood.",
  progress = "Faresti meglio a stare $Gattento:attenta; con quei ragni: ci ho rimesso qualche uomo, e credimi, non è un bello spettacolo un uomo appeso a testa in giù nelle loro ragnatele dopo che il veleno ha cominciato ad ammorbidirlo.$B$BNon vorrei vederti diventare il pranzo di uno di quegli insetti.",
  reward = "Ah! Sei $Gtornato:tornata;. E a quanto pare non troppo $Gmalconcio:malconcia;. Naturalmente, $N, la Guardia Notturna ti è grata per il tuo lavoro, e una ricompensa te l'avevo promessa, quindi eccola.",
  en_title = "Eight-Legged Menaces",
  en_obj = "Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood.",
}
T[246] = {
  title = "Valutare la minaccia",
  desc = "Non abbiamo uomini da risparmiare, ma bisogna fare qualcosa a proposito di quegli gnoll di cui mi hai riferito.$B$BEsplora il sud di Redridge in cerca di gnoll. Molestali, uccidi quelli che puoi e torna da me con il conteggio dei loro numeri e una valutazione della minaccia che rappresentano. Potresti trovare quegli gnoll accampati lungo tutta la strada meridionale di Redridge.$B$BFallo per lo Stormwind Army, $N, e sarai ricompensat$Go:a;.",
  obj = "Uccidi 10 Redridge Mongrel e 6 Redridge Poacher, poi riferisci a Deputy Feldon a Lakeshire.",
  progress = "Scusami, $N, ma qui abbiamo le mani piene di faccende. Se non hai nulla da riferire, devo dedicarmi ad altro.",
  reward = "<Deputy Feldon ascolta il tuo rapporto...>$B$BC'è una nutrita forza di gnoll accampata laggiù e, da quanto mi dici, sono duri a morire. Non deve essere stato facile per te raccogliere queste informazioni.$B$BEcco a te, $N. Ti siamo grati per il tuo aiuto.$B$BE se non l'hai ancora fatto, parla con Marshal Marris e Magistrate Solomon a Lakeshire. La nostra situazione si fa sempre più disperata: quei due avranno di certo bisogno di te.",
  en_title = "Assessing the Threat",
  en_obj = "Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire.",
}
T[247] = {
  title = "La caccia completata",
  reward = "$N, hai ucciso tutte e tre le bestie che compongono la caccia di Ashenvale. Mi hai portato prove sufficienti della loro fine; la tua forza e la tua tenacia sono fuori discussione. Nelle tue vene scorre il sangue di $Gun cacciatore:una cacciatrice;, e meriti ogni elogio!$B$BTi prego, accetta questo ninnolo come congratulazioni per le grandi imprese che hai compiuto oggi ad Ashenvale per l'Orda. Che i tuoi antenati veglino su di te!",
  en_title = "The Hunt Completed",
}
T[248] = {
  title = "Guardare più lontano",
  desc = "Ho tenuto d'occhio la Tower of Ilgalar, e riesco a capire che Morganth è in conflitto con gli orchi dello Stonewatch Keep. Non conosco il motivo della loro contesa, ma tu puoi aiutarmi a sciogliere il mistero.$B$BPrendi un altro Glyph of Azora, poi sali in cima alla torre di guardia ancora intatta accanto allo Stonewatch Keep.$B$BTrova un oggetto adatto su cui posare il glifo. Una cassa o un vaso — un posto dove il glifo non venga notato — farà al caso mio.",
  obj = "Sali sulla torre di guardia intatta accanto allo Stonewatch Keep.$B$BTrova un contenitore adatto dove mettere il Glyph of Azora.",
  progress = "Questo vaso un tempo conteneva un liquore dall'odore disgustoso, ma ora giace vuoto e dimenticato su un paio di barili.",
  reward = "È un recipiente adatto per il Glyph of Azora, e permette a Theocritus di scavare nelle menti dentro lo Stonewatch Keep.",
  en_title = "Looking Further",
  en_obj = "Climb the intact watch tower beside Stonewatch Keep.$B$BFind a suitable container to place the Glyph of Azora.",
}
T[249] = {
  title = "Morganth",
  desc = "Dopo molte osservazioni, ho scoperto i piani di Morganth.$B$BCerca la Scythe of Elune... e forse l'ha trovata! Se è così, presto le Redridge Mountains, e il regno di Stormwind, sentiranno la sua oscura potenza.$B$BNon sono pronto a misurarmi con Morganth, ma temo che vada affrontato ora. Quindi devi entrare tu nella Tower of Ilgalar e affrontare Morganth.$B$BSconfiggilo e portami il suo Pendant of Shadow. Fallo, e il regno ti dovrà molto.",
  obj = "Sconfiggi Morganth.$B$BPorta il suo Pendant of Shadow a Theocritus, alla Tower of Azora, nell'Elwynn Forest.",
  progress = "Sbrigati, $N, prima che i miei timori sul potere di Morganth che si diffonde diventino realtà!",
  reward = "Hai fatto bene, $N. Sconfiggendo lo stregone Morganth hai salvato Stormwind da un grave pericolo.$B$BTi offro questa ricompensa con umiltà. E ti augurerei pace, se questi fossero tempi di pace.$B$BMa invece ti auguro fortuna nelle tue prove, e vittoria negli scontri che verranno.",
  en_title = "Morganth",
  en_obj = "Defeat Morganth.$B$BBring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest.",
}
T[250] = {
  title = "Un'oscura minaccia incombe",
  desc = "Grazie al cielo qualcuno si preoccupa della sicurezza della Diga. Prima la distruzione del Thandol Span, poi il saccheggio di Dun Modr! Non ho dubbi che la Diga sarà il prossimo obiettivo dei Dark Iron. Gran parte della sorveglianza qui è stata trasferita al fronte dell'Alleanza, compreso il mio miglior ispettore.$B$BEcco perché ho bisogno di te, $N. Ho visto alcuni Dark Iron Sappers aggirarsi sulla rampa orientale della Diga. Indaga nella zona e riportami un indizio.",
  obj = "Indaga nella zona vicino alla rampa orientale della Diga e porta a Chief Engineer Hinderweir un indizio che possa rivelare cosa stanno tramando i Dark Iron Dwarves.",
  reward = "Il barile sospetto contiene una polvere dall'odore strano.",
  en_title = "A Dark Threat Looms",
  en_obj = "Investigate the area near the eastern ramp of the Dam and bring Chief Engineer Hinderweir a clue that might reveal what the Dark Iron Dwarves are up to.",
}
T[251] = {
  title = "Traduci il biglietto di Abercrombie",
  desc = "Porta il biglietto che mi hai dato a Sirra Von'Indi. È molto istruito in lingue e arti antiche: se c'è qualcuno qui che può tradurre questo messaggio, è lui.",
  obj = "Porta la Letter to Ello a Sirra Von'Indi.",
  progress = "Un biglietto di Abercrombie l'eremita, eh? Non lo conosco, anche se, se vive laggiù al cimitero, di sicuro so che il cervello gli è marcito!",
  reward = "<Sirra comincia a tradurre il biglietto...>",
  en_title = "Translate Abercrombie's Note",
  en_obj = "Bring the Letter to Ello to Sirra Von'Indi.",
}
T[252] = {
  title = "La traduzione per Ello",
  desc = "Oh cielo! Se quel che c'è scritto su questo biglietto è vero, allora Abercrombie ha fatto qualcosa di... indicibile.$B$BFaresti meglio a riportare il biglietto tradotto a Ello.$B$BE fallo in fretta, perché temo che una sciagura stia già avanzando pesante verso il nostro paese...",
  obj = "Porta la Translated Letter a Lord Ello Ebonlocke.",
  progress = "Ah, il biglietto è tradotto? Ti prego, fammelo vedere...",
  reward = "<Ello legge la lettera... e il suo volto si fa bianco. Poi ti guarda...>$B$BAnche se l'aiuto che hai dato ad Abercrombie può essere nato dalla gentilezza, quel che hai fatto ha condannato il nostro paese.$B$B<Ello si perde nei suoi pensieri...>",
  en_title = "Translation to Ello",
  en_obj = "Bring the Translated Letter to Lord Ello Ebonlocke",
}
T[253] = {
  title = "La sposa dell'Embalmer",
  desc = "L'Embalmer è un nome che ricorre in una delle nostre storie per bambini. Era un alchimista gentile, impazzito per la morte della moglie, Eliza. Per riportarla in vita usò la magia oscura e mise il proprio cuore nel petto della sposa morta.$B$BQuesto fece rivivere Eliza... ma la maledisse con una fame di carne umana, e costrinse l'Embalmer a tenerla sepolta.$B$BIl suo cuore è il suo potere. Trova la tomba della moglie, recupera il cuore e portamelo mentre ancora batte. Fa' questo e il suo potere sarà spezzato.",
  obj = "Trova la tomba di Eliza. Recupera da lei l'Embalmer's Heart, poi torna da Ello Ebonlocke.",
  progress = "L'hai già trovata la tomba di Eliza? Ce l'hai il cuore dell'Embalmer?",
  reward = "Ce l'hai fatta! La magia dentro il suo cuore reggerà contro il male dell'Embalmer, e sarà un'egida potente sul paese di Darkshire.$B$BHai fatto una grande cosa per la nostra gente, $N. Il tuo nome resterà per sempre nei nostri annali.",
  en_title = "Bride of the Embalmer",
  en_obj = "Find Eliza's grave.  Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.",
}
T[254] = {
  title = "Scavando nella terra",
  reward = "Scavi nella terra smossa sopra la tomba... e trovi i resti di una bara.$B$BDentro la bara senti il vibrare di dita adunche che grattano e il digrignare di denti marci...$B$BVuoi aprire la bara e recuperare il cuore dell'Embalmer?",
  en_title = "Digging Through the Dirt",
}
T[255] = {
  title = "Mercenari",
  desc = "Due mesi solo per sentirci dire da Ironforge che ci concederanno una manciata di soldati per la nostra difesa, e altri due mesi prima che arrivino! Già è grave che la nostra città resti senza protezione, ma anche lo scavo e la diga (la diga!) sono esposti agli attacchi.$B$BA quanto pare non ho scelta. Mi servono dei mercenari.$B$BChe ne dici tu? Sembri $Gil tipo giusto:la tipa giusta;, $C. Un gruppo di ogre si è accampato a nord-est del lago. Forse sarai tu a eliminare la minaccia per la nostra città?",
  obj = "Magistrate Bluntnose di Thelsamar ti ha assoldato per uccidere 4 Mo'grosh Ogres, 4 Mo'grosh Brutes e 4 Mo'grosh Enforcers.",
  progress = "Hai avuto fortuna?",
  reward = "Ah, questa è un'ottima notizia! I tuoi sforzi sono molto apprezzati da me e dalla gente di Thelsamar. E ancora meglio: se riusciamo a risolvere il problema degli ogre, potremo concentrarci su quei maledetti trogg.",
  en_title = "Mercenaries",
  en_obj = "Magistrate Bluntnose of Thelsamar has hired you to kill 4 Mo'grosh Ogres, 4 Mo'grosh Brutes and 4 Mo'grosh Enforcers.",
}
T[256] = {
  title = "RICERCATO: Chok'sul",
  desc = "Per ordine del Magistrato di Thelsamar:$B$BChok'sul, l'ogre ritenuto capo e organizzatore degli attacchi contro la città di Thelsamar, la Stonewrought Dam e il sito di scavo, è ricercato morto, con qualsiasi mezzo necessario.$B$BUna ricompensa in denaro sarà corrisposta a chi porterà al Magistrato la prova della morte di Chok'sul.$B$BChok'sul è stato visto l'ultima volta nell'accampamento degli ogre nella parte nord-orientale di Loch Modan.",
  obj = "Uccidi Chok'sul e porta la sua testa a Magistrate Bluntnose di Thelsamar.",
  progress = "Sì? Posso fare qualcosa per te?",
  reward = "Bleah! Cos'è quella cosa? E perché mai l'hai portata...$B$BMaledi--! Ma è...? Beh, che la Luce mi fulmini, è la testa di quel maledetto ogre? Allora questa sì che è una bella preda! Ecco la tua ricompensa, con i ringraziamenti miei e della gente di Thelsamar.",
  en_title = "WANTED: Chok'sul",
  en_obj = "Kill Chok'sul and bring his head to Magistrate Bluntnose of Thelsamar.",
}
T[257] = {
  title = "La sfida di un cacciatore",
  desc = "Pensi di poterti misurare con Daryl the Bold, eh? Direi proprio di no! Ma certo, sei liber$Go:a; di provarci. Ecco una sfida che dovrebbe rivelarsi al di sopra delle tue capacità, quindi non prendertela troppo se non riuscirai ad affrontarla.$B$BUno stormo di avvoltoi ha fatto il nido qui a Loch Modan. Perché non provi ad abbattere qualcuna di quelle bestie? Facciamo così: se superi la mia sfida entro quindici minuti, ti darò il mio arco o il mio fucile.$B$B<Ti squadra con aria sprezzante.>$B$BTanto, a quanto pare, non hai molto da perdere.",
  obj = "Uccidi 6 Mountain Buzzards e torna da Daryl the Youngling alla Farstrider Lodge entro 15 minuti.",
  progress = "Niente da fare? Non prendertela troppo, $N...$B$BNon tutti possono essere come me.",
  reward = "Cosa? Ce l'hai fatta?$B$BDai retta a me, $Nama: non montarti la testa. Voglio dire, qualunque ragazzino imberbe con un arco avrebbe potuto uccidere esemplari così... piccoli. E spero che uccidere avvoltoi non ti piaccia troppo, eh? Non vorremmo che si estinguessero.$B$BBeh, ehm... Che non si dica mai che Daryl the Bold non mantiene la parola data.",
  en_title = "A Hunter's Boast",
  en_obj = "Kill 6 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge within 15 minutes.",
}
T[258] = {
  title = "La prova di un cacciatore",
  desc = "$Nath, giusto? Si vede che scoppi d'orgoglio per aver superato la prima prova, eh? Come ti ho già detto, non è una grande impresa.$B$BDovresti provare con la caccia al cinghiale. Credimi, questa non è una caccia al cinghiale di Coldridge Valley, quindi faresti bene a stare attent$Go:a;. Stavolta ti do solo dodici minuti.$B$BNon prendertela se fallisci. Se ce la fai, ti do la camicia che ho addosso!$B$BTi ho mai raccontato la storia di come mi sono fatto la mia famosa cicatrice? No? Era due anni fa...",
  obj = "Uccidi 5 Elder Mountain Boars e torna da Daryl the Youngling alla Farstrider Lodge entro 12 minuti.",
  progress = "È naturale compatirsi quando si viene superati da qualcuno così nuovo di questo mondo. Non devi sentirti in colpa, $N.$B$BMm? Ho sbagliato il tuo nome?",
  reward = "Sembri un po' malridott$Go:a;. Senza dubbio i cinghiali ti hanno dato del filo da torcere, eh? Non preoccuparti, sarò discreto sulle tue difficoltà: immagino quanto debba essere dura per te anche senza le malelingue.$B$BOh! Sei riuscit$Go:a; a uccidere i cinghiali? Io... beh, cioè... cioè, non sono sorpreso! Qualunque bambino avrebbe potuto... scommessa?$B$BQuale scommessa?",
  en_title = "A Hunter's Challenge",
  en_obj = "Kill 5 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge within 12 minutes.",
}
T[261] = {
  title = "Lungo il sentiero scarlatto",
  desc = "Sarò franco. Siamo in guerra con il Flagello. È un male che corrompe la nostra gente e infetta la nostra terra. Deve essere fermato prima che ci travolga e trascini il nostro mondo nell'ombra. Noi della Crociata Scarlatta abbiamo giurato di combattere il Flagello anima e corpo.$B$BSe sei con noi, allora fatti coraggio e dimostra la tua lealtà — distruggi gli Undead Ravager di Desolace, nella Valley of Bones, a sud.$B$BFallo, e la Crociata ti accoglierà a braccia aperte.",
  obj = "Distruggi 30 Undead Ravager, poi torna da Brother Anton, a Nijel's Point.",
  progress = "Il Flagello diventa più potente a ogni giorno che passa. Se desideri davvero fermarne l'avanzata, allora dimostramelo.",
  reward = "Hai dimostrato la tua determinazione, e la Crociata Scarlatta ti elogia.$B$BSe non ti tiri indietro davanti a un giusto massacro, allora forse il tuo cammino è insieme a noi...",
  en_title = "Down the Scarlet Path",
  en_obj = "Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.",
}
T[262] = {
  title = "La Shadowy Figure",
  desc = "Devo sapere chi era quello che sgattaiolava nell'ombra la notte in cui la mia famiglia è stata uccisa!$B$BTi prego, $N, hai dimostrato di essere $Gpieno:piena; di risorse. Ti prego, trova quella figura in ombra. Devo sapere che segreti nasconde!$B$BNon ho indizi che tu non conosca già, ma tieni — prendi il libro che hai trovato alla mia fattoria. Forse qualcuno in paese può collegare questo libro al suo proprietario.",
  obj = "Prendi il libro che hai trovato alla fattoria di Sven e mostralo alla gente di Darkshire.",
  progress = "Se hai qualcosa che appartiene alla figura in ombra che cerchi, fammela vedere. Forse riesco a indovinare qualcosa sul suo proprietario.",
  reward = "Hmm... Qualcuno ha maneggiato questo libro di recente, qualcuno mosso dalla vendetta. Ma le impressioni rimaste sopra, almeno quelle del proprietario originale, sono deboli.$B$BQuello che posso dirti, però, è che il proprietario originale di questo libro non è di Darkshire.",
  en_title = "The Shadowy Figure",
  en_obj = "Take the book you found at Sven's farm and show it to townsfolk in Darkshire.",
}
T[263] = {
  title = "In difesa delle terre del re",
  desc = "I Mountaineer mi dicono che hai coraggio e capacità da vendere, $N. Qui ci serve $Gun:una; $R come te. Il problema dei trogg non migliora. Le riserve sono state richiamate al fronte e qui siamo rimasti soli. Ma ora che abbiamo $Gun $C esperto:una $C esperta;, vediamo cosa sai fare.$B$BVai e uccidi 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnappers. Vediamo se sei all'altezza della tua fama, $GAmmazzatrogg:Ammazzatrogg;.",
  obj = "Mountaineer Wallbang nella torre di guardia meridionale vuole che tu uccida 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnappers.",
  progress = "Già di ritorno? Se non sono stato chiaro, ci serve che tu uccida 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnappers, $N. Ora vai a prenderli, Ammazzatrogg!",
  reward = "Nel momento stesso in cui ti ho vist$Go:a;, $N, ho capito che avresti reso orgogliosa Ironforge. Hai servito bene re Magni. Ora che hai dimostrato di essere un aiuto così leale per il Regno, forse dovresti parlare con il Capitano: potrebbe affidarti un incarico più importante.$B$BTi saluto, $N.",
  en_title = "In Defense of the King's Lands",
  en_obj = "Mountaineer Wallbang in the southern guard tower wants you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.",
}
T[264] = {
  title = "Finché morte non ci separi",
  desc = "Lurido miserabile! Mi lascia per la sua maledetta crociata. Perché «la Luce è la cosa più importante che abbiamo contro le minacce dei non morti».$B$BEbbene, e i suoi figli?! E io?! Notte dopo notte l'ho aspettato pazientemente... sempre seconda al suo dannato dovere!$B$BEbbene, guarda cosa ti porta la «giustizia», $N! È morto e io porto in grembo proprio ciò che lui cercava di fermare!$B$BPrendi questo ciarpame e mettilo sulla sua tomba al Sepulcher. Non voglio più averci a che fare... né con lui!",
  obj = "Deponi il Clarice's Pendant su Yuriv's Tomb a Silverpine.",
  progress = "La pietra è fredda al tatto, ma è evidente che è stata maltrattata. Rifiuti ricoprono la zona; scheggiature e sfregi decorano il rilievo sopra la bara; e il fogliame intorno alla tomba ha cominciato a coprire il sito.$B$BA nessuno importa di chi sia sepolto qui, men che meno delle vittime della piaga.",
  reward = "Posi il ciondolo senza valore sulla tomba, e la gemma incastonata sembra spegnersi in modo evidente.$B$BMentre ti rialzi per andartene, abbassi lo sguardo sul ciondolo: giace senza vita sulle mani del rilievo scolpito sul coperchio della bara. I tuoi pensieri sono interrotti da una brezza fredda e rigida che attraversa il Sepulcher. Per un momento tutto intorno a te è silenzio.",
  en_title = "Until Death Do Us Part",
  en_obj = "Place Clarice's Pendant on Yuriv's Tomb in Silverpine.",
}
T[265] = {
  title = "La ricerca nell'ombra continua",
  desc = "Ecco il tuo libro, $N, e ti auguro fortuna con la tua ricerca. Se chiedi ad altri in paese, forse possono darti altri indizi.$B$BE te ne do ancora uno: anche se l'autore di questo libro è un forestiero per Darkshire, il libro è stato comprato qui.",
  obj = "Vedi se altri in paese hanno indizi sulla figura in ombra.",
  progress = "Certe volte vendo libri bianchi a studiosi e maghi, o a chiunque voglia tenere un diario.$B$BRicordo bene tutti quelli a cui ho venduto un libro negli ultimi mesi...",
  reward = "Ah, sì. Questo libro l'ho venduto un mese fa a un tipo losco. Non mi ha detto il suo nome, ma era un tipo nervoso e agitato, che si guardava sempre alle spalle.$B$BSpero che ti sia d'aiuto...",
  en_title = "The Shadowy Search Continues",
  en_obj = "See if other townsfolk have clues about the shadowy figure.",
}
T[266] = {
  title = "Chiedi alla locanda",
  desc = "Ecco il tuo libro, e buona fortuna con le tue domande.$B$BPotresti allargare la ricerca alla locanda. Se la persona che cerchi ha passato del tempo in paese, è probabile che qualcuno l'abbia vista lì.",
  obj = "Cerca indizi sulla figura in ombra alla locanda.",
  progress = "La Scarlet Raven non ha più il giro d'affari di una volta, ma qualche viaggiatore di passaggio capita ancora.$B$BSe sai descrivermi la persona che cerchi, magari me la ricordo.",
  reward = "Oh sì, questo libro me lo ricordo. Il suo proprietario ha preso una stanza per qualche giorno, e passava le notti al bancone a scrivere.$B$BHa lasciato il paese in fretta, borbottando di essere braccato da... qualcosa. L'ultima volta che l'ho visto andava a ovest, fuori dal paese, in cerca di un nuovo posto dove nascondersi.$B$BIl primo posto che trova a ovest è Raven Hill...",
  en_title = "Inquire at the Inn",
  en_obj = "Search the inn for clues about the shadowy figure.",
}
T[267] = {
  title = "La minaccia dei trogg",
  desc = "$C, forse sai, o forse no, della minaccia dei trogg che incombe sulle terre dei nani. Con la Riserva di Ironforge richiamata al fronte dell'Alleanza, ci resta solo una frazione delle forze necessarie a tenere al sicuro queste terre. Il mio reggimento è assegnato alla sorveglianza del Cancello e non possiamo lasciare il posto per paura di un'invasione.$B$BMa bisogna mettere sotto pressione quei maledetti trogg nascosti tra le colline. Se te la senti, lancia un attacco contro di loro. Portami 8 Trogg Stone Teeth come prova.",
  obj = "Porta 8 Trogg Stone Teeth a Captain Rugelfuss nella torre di guardia meridionale.",
  progress = "Hai 8 Trogg Stone Teeth da mostrarmi? Se no, c'è ancora del lavoro da fare, $N.",
  reward = "Sono davvero colpito, $N. Difendendo le nostre terre hai reso un grande favore alla razza dei nani. Re Magni Bronzebeard in persona ne sarebbe orgoglioso!",
  en_title = "The Trogg Threat",
  en_obj = "Bring 8 Trogg Stone Teeth to Captain Rugelfuss in the southern guard tower.",
}
T[268] = {
  title = "Torna da Sven",
  desc = "Il libro che hai trovato era solo a metà. Ho dovuto lasciarlo alla fattoria di Sven quando sono fuggito là...$B$BTieni. Porta a Sven il mio diario completo. Racconta molto meglio quel che è successo alla sua fattoria.$B$BAnche se in queste settimane questo diario è stata la mia unica compagnia, se cederlo mi evita di affrontare Sven e la sua ira, lo faccio volentieri!",
  obj = "Torna da Sven con il diario completo di Jitters.",
  progress = "Hai scoperto chi era la Shadowy Figure?",
  reward = "Questo diario mi spiega molte cose, e mi mette sulla strada contro i Dark Rider! Ho visto questi cavalieri a Duskwood, e li ho visti parlare con il mago Morbent Fel, al Forlorn Rowe.",
  en_title = "Return to Sven",
  en_obj = "Return to Sven with Jitters' completed journal.",
}
T[269] = {
  title = "In cerca di saggezza",
  desc = "Va' alla città di Stormwind e parla con Bishop Farthing, alla Cathedral of Light. Dagli il diario di Jitters e digli che intendi affrontare Morbent Fel.$B$BAnche se Stormwind ha abbandonato Darkshire, Farthing è un'anima buona e molto saggia. Può aiutarti nella tua impresa per salvarci.$B$BLa tua missione è pericolosa, ma sbrigati, $N. Con ogni ora che passa, le ombre di Duskwood si fanno più fitte.",
  obj = "Consegna Jitters' Completed Journal a Bishop Farthing, a Stormwind.",
  progress = "Riposati, $Gfratello:sorella;. Vedo che hai viaggiato a lungo, e che porti un peso gravoso. Sai dirmi cos'è che getta quell'ombra scura su di te?",
  reward = "<Dopo aver letto il diario e aver ascoltato le tue intenzioni...>$B$BUna corruzione maligna ha messo radici nella già tormentata Duskwood. Ringrazio la Luce che ad affrontarla ci sia $Gun eroe:un'eroina; come te.$B$BMa prima devi prepararti alla prova che ti aspetta... perché il negromante Morbent Fel è immensamente potente, e si è cinto di incantesimi oscuri che lo proteggono dagli attacchi fisici. Se vuoi sconfiggerlo, ti servirà un'arma che quelle protezioni non possono fermare.",
  en_title = "Seeking Wisdom",
  en_obj = "Give Jitters' Completed Journal to Bishop Farthing in Stormwind.",
}
T[270] = {
  title = "La flotta maledetta",
  desc = "Anni fa la Third Fleet di Kul'Tiras affondò lungo le coste delle Wetlands, una distesa di paludi a nord del regno nanico di Ironforge. Su una delle navi c'era un carico di Lightforge Iron.$B$BQuesto metallo è prezioso per noi, perché gli oggetti forgiati con esso colpiscono con la verità sacra. Se devi affrontare Morbent Fel, ti servirà un'arma così.$B$BVa' a Menethil Harbor e parla con il mio collega nano Glorin Steelbrow. Se quel metallo perduto si può trovare, lui saprà dove cercare.",
  obj = "Va' a Menethil Harbor, nelle Wetlands, e parla con Glorin Steelbrow.",
  reward = "Il Lightforge Iron è un metallo prezioso, ma pare che la tua impresa sia terribile. Hai fatto molta strada, $GFratello:Sorella;. Con un po' di fortuna, potresti trovare proprio quel che cerchi!$B$BE se il metallo lo trovi, so chi può farne un'arma contro questo negromante di cui parli, a Duskwood.",
  en_title = "The Doomed Fleet",
  en_obj = "Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.",
}
T[271] = {
  title = "La vendetta di Vyrin",
  desc = "Non è che ti andrebbe di dare una piccola lezione a Sua Audacia? Daryl qualche abilità ce l'ha, mi costa ammetterlo.$B$BUn anno fa, alla Farstrider Lodge davano la caccia a un grosso orso, ma nessun cacciatore riusciva ad averne ragione. Così Daryl pensò di provarci lui. L'unico risultato fu quella brutta cicatrice sopra l'occhio.$B$BUccidi l'orso, e sono sicuro che per una volta persino Daryl resterà senza parole.$B$BL'orso, Ol' Sooty, si trova vicino alla sua tana, sulle colline sopra Thelsamar.",
  obj = "Uccidi Ol' Sooty, poi mostra il tuo lavoro a Daryl the Youngling alla Farstrider Lodge.",
  progress = "Ah, $N! Già di ritorno? Di sicuro sei stat$Go:a; di nuovo a caccia, eh? Non preoccuparti se hai avuto qualche battuta d'arresto: alla lunga ti renderà migliore!$B$B... Tanto peggio di così non potresti fare...",
  reward = "Ehm... cos'è questo? Una testa d'orso, a quanto pare.$B$B<Si passa un dito sulla cicatrice senza accorgersene.>$B$BBeh, questa sì che è una preda interessante. Non può essere quell'orso di allora...$B$B<Si interrompe e comincia a tremare vistosamente.>$B$BOh, portala via, portala via! Porta fuori di qui quella cosa raccapricciante!",
  en_title = "Vyrin's Revenge",
  en_obj = "Kill Ol' Sooty then show your handiwork to Daryl the Youngling at the Farstrider Lodge.",
}
T[272] = {
  title = "Prova del leone marino",
  desc = "Per la seconda prova ti serviranno le due metà che formano il Pendant of the Sea Lion. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dall'incredibile resistenza dell'aspetto del leone marino. I druidi attingono in egual misura a entrambe queste qualità per incarnare l'aspetto della loro Aquatic Form.$B$BParla con gli abitanti di Moonglade per scoprire dove potrebbero trovarsi le due parti, e portale entrambe qui per unirle. Una volta formato il pendente, portalo a Dendrite Starblaze.",
  obj = "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per avere indizi su dove possano trovarsi questi oggetti.$B$BForma il Pendant of the Sea Lion unendo le due metà del pendente. Per farlo devi trovarti vicino allo Shrine of Remulos.$B$BPorta il pendente completo a Dendrite Starblaze, nel villaggio di Nighthaven, a Moonglade.",
  progress = "Hai formato il pendente da farmi esaminare, $N? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni alla gente del posto. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.",
  reward = "Hai completato la Prova del Leone Marino, $N — congratulazioni.$B$BOgni passo per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua disponibilità a fare tuo l'aspetto del leone marino.$B$BRicorda bene queste lezioni: ti serviranno quando avrai ottenuto la tua Aquatic Form.",
  en_title = "Trial of the Sea Lion",
  en_obj = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.$B$BForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.$B$BBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.",
}
T[273] = {
  title = "Rifornire lo scavo",
  desc = "Però non è troppo tardi: puoi andare a cercare Huldar. Non può essere andato molto lontano; per quanto siano forti, Miran e Saean non possono andare poi così veloci, carichi di quei barili.$B$BStanno facendo la solita strada per il sito: escono dalla città verso sud e seguono la curva del Loch.$B$BNon dovresti avere problemi a trovarli, a meno che non siano già arrivati.",
  obj = "Parla con Huldar.",
  reward = "Mph, ci vuole ben più di un'imboscata dei Dark Iron per fermare le consegne!$B$BMa Saean... non avrei mai sospettato che fosse uno dei loro simpatizzanti. Lavoriamo con lui da quasi un anno... forse non ho colto i segnali.$B$BBeh, ci penserò più tardi.",
  en_title = "Resupplying the Excavation",
  en_obj = "Speak with Huldar.",
}
T[274] = {
  title = "Un'oscura minaccia incombe",
  desc = "Questa non è una normale polvere da mina. Guarda questi minuscoli cristalli d'argento. E quell'odore inconfondibile! È chiaro come il sole: questa è Seaforium Powder. Il seaforium è abbastanza innocuo. Ma una volta bagnato potrebbe far saltare Ironforge fuori dalla montagna.$B$BLa reazione chimica si può neutralizzare mescolando quattro componenti: veleno di lurker, cristallo di Mo'Grosh frantumato, una lacrima di crocolisco e questo colloide disinnescante. Ora avvisa Hinderweir, prima che sia troppo tardi!",
  obj = "Ashlan Stonesmirk vuole che tu torni da Chief Engineer Hinderweir e lo informi della nuova scoperta.",
  progress = "Cosa mi porti da parte di Ashlan?",
  reward = "Un colloide disinnescante? Per il seaforium? Oh, santo cielo!",
  en_title = "A Dark Threat Looms",
  en_obj = "Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir and inform him of the new discovery.",
}
T[275] = {
  title = "Pustole sulla terra",
  desc = "Non so perché, ma nelle Wetlands cresce un'infezione. I Fen Creeper si sono levati. Sono pustole malate e febbricitanti sulla terra, e perché la febbre passi devono essere eliminati e lasciati tornare nelle paludi.$B$BI Fen Creeper si trascinano tra i corsi d'acqua delle Wetlands.",
  obj = "Uccidi 12 Fen Creeper, poi torna da Rethiel the Greenwarden, nelle Wetlands.",
  progress = "Le Wetlands piangono ancora, e i Fen Creeper ancora infuriano. Torna da me quando il tuo compito sarà finito.",
  reward = "Questa terra è placata dai tuoi sforzi, e per questo ti concederò un dono.",
  en_title = "Blisters on The Land",
  en_obj = "Kill 8 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands.",
}
T[276] = {
  title = "Zampe che calpestano",
  desc = "I Mosshide Gnoll hanno vissuto in pace nelle Wetlands per molti anni, ma ora crescono di numero. Le loro zampe calpestano i cespugli e i fiori della palude, e le loro asce immonde tagliano troppo legno per alimentare i fuochi.$B$BNon sono più in equilibrio con la terra. Perché le Wetlands sopravvivano, gli gnoll vanno ridotti.$B$BUccidi 15 Mosshide Gnoll e 10 Mosshide Mongrel. Dai loro la caccia a sud, vicino alla porta nanica di Algaz. Quando l'avrai fatto, torna da me.",
  obj = "Uccidi 15 Mosshide Gnoll e 10 Mosshide Mongrel, poi torna da Rethiel the Greenwarden, nelle Wetlands.",
  progress = "Il tuo compito ti aspetta ancora, giovane $C.",
  reward = "Riducendo il numero degli gnoll, ti sei $Gpreso:presa; cura della salute delle Wetlands. Anche se in passato la mia fiducia nella tua gente è stata messa a dura prova, $R, può ancora essere ristabilita.",
  en_title = "Tramping Paws",
  en_obj = "Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands.",
}
T[277] = {
  title = "Il tabù del fuoco",
  desc = "I Mosshide tagliano gli alberi delle Wetlands, e usano la carne degli alberi per scaldarsi con il fuoco. Non sopporterò più questo dolore!$B$BPriva i Mosshide dei loro rozzi acciarini, gli arnesi con cui accendono il fuoco. Gli acciarini li portano tutti i Mosshide, tranne i Mosshide Gnoll e i Mosshide Mongrel più piccoli.",
  obj = "Porta 9 Crude Flint a Rethiel the Greenwarden.",
  progress = "Hai gli arnesi del fuoco degli gnoll?",
  reward = "... grazie. Frantumerò questi acciarini e li getterò in mare, perché non siano mai più usati per bruciare legno vivo.",
  en_title = "Fire Taboo",
  en_obj = "Bring Rethiel the Greenwarden 9 Crude Flints.",
}
T[278] = {
  title = "Un'oscura minaccia incombe",
  desc = "Comincia subito a raccogliere i materiali per il disinnesco, $N. Il Lurker Venom si trova sui ragni del posto, qui a Loch Modan. Anche le lacrime di crocolisco si trovano qui nel Loch. Ma un cristallo di Mo'Grosh sarà molto difficile da procurare. Gli ogre a nord-est li estraggono, ma quei cristalli sono merce rarissima.$B$BDobbiamo essere pronti a sventare un attacco dei Dark Iron! Torna da me quando avrai raccolto quello che serve e preparerò la miscela.",
  obj = "Chief Engineer Hinderweir vuole che tu raccolga Lurker Venom, un Mo'grosh Crystal e una Crocolisk Tear.",
  progress = "Hai quello che serve? Il tempo stringe!!",
  reward = "Giusto in tempo, $N!",
  en_title = "A Dark Threat Looms",
  en_obj = "Chief Engineer Hinderweir wants you to gather Lurker Venom, a Mo'grosh Crystal, and a Crocolisk Tear.",
}
T[279] = {
  title = "Artigli dal profondo",
  desc = "I murloc stanno strisciando fuori dalle acque profonde e costruiscono i loro villaggi sulla costa. Danno fastidio ai nostri pescatori e ai nostri mercanti, e vanno fermati.$B$BUno di questi murloc, Gobbler, si aggira insieme agli altri Bluegill Murloc e tormenta i mercanti lungo la strada, per poi ritirarsi sempre al sicuro nelle capanne dei murloc qui vicino. I nostri mercanti sono in pericolo, e pagheremo per metterli al sicuro.$B$BGobbler si aggira nell'insenatura del fiume a nord di qui. Trovalo, uccidi i suoi simili e portami la sua testa.",
  obj = "Uccidi 12 Bluegill Murloc.$B$BUccidi Gobbler e prendi la sua testa.$B$BPorta Gobbler's Head a Karl Boran, a Menethil Harbor.",
  progress = "I nostri mercanti non saranno al sicuro finché non ci saremo liberati di Gobbler e di quei murloc.",
  reward = "Ah, ben fatto, $N.$B$BAccetta questo come pagamento per aver adempiuto al tuo contratto con i Merchant Marines.",
  en_title = "Claws from the Deep",
  en_obj = "Kill 12 Bluegill Murlocs.$B$BSlay Gobbler and take his head.$B$BBring Gobbler's Head to Karl Boran in Menethil Harbor.",
}
T[280] = {
  title = "Un'oscura minaccia incombe",
  desc = "Stamattina ho visto alcuni Dark Iron Insurgents nuotare verso la Diga con un grosso barile. Non c'era nessun Mountaineer a fermarli! Temo che abbiano piazzato il seaforium alla base della Diga, e potrebbe esplodere da un momento all'altro! Lasciami combinare tutti questi ingredienti nella miscela disinnescante. Ecco fatto.$B$BOra devi prendere questa miscela e versarla nel barile, prima che sia troppo tardi! Presto!",
  obj = "Chief Engineer Hinderweir vuole che tu nuoti fino alla base della diga, trovi il barile di polvere e ci mescoli la Disarming Mixture per evitare un'esplosione.",
  progress = "Il coperchio del barile si svita lentamente.",
  reward = "Il barile sfrigola leggermente mentre la Disarming Mixture si deposita.",
  en_title = "A Dark Threat Looms",
  en_obj = "Chief Engineer Hinderweir wants you to swim down to the base of the dam, locate the powder keg and stir in the Disarming Mixture to prevent an explosion.",
}
T[281] = {
  title = "Recuperare la merce",
  desc = "Non molto tempo fa un mercantile, la Blind Princess, è stato assalito dai murloc. Anche se la nave se l'è cavata intatta, gran parte del carico è stata trascinata in mare da quelle creature, compresa una statuetta di Terenas Menethil di grande valore. Vogliamo che quella statuetta venga recuperata.$B$BCerca casse, barili e altre tracce del carico perduto nelle capanne dei murloc sulla costa. Trova la Menethil Statuette e riportamela.",
  obj = "Cerca nelle casse e nei barili degli accampamenti murloc sulla costa.",
  reward = "Questa cassa è coperta di graffi di artigli e di segni lasciati dall'acqua. Forzandola si scopre paglia fradicia e marcia, come se dentro fosse stato riposto qualcosa di valore. Frughi tra la paglia...$B$B...e trovi una bracciata di bottiglie rosse.",
  en_title = "Reclaiming Goods",
  en_obj = "Search the crates and barrels at the coastal Murloc camps.",
}
T[282] = {
  title = "Le osservazioni di Senir",
  desc = "Pensavo di mandare il mio apprendista da mio fratello Senir con il rapporto, ma mi sentirei molto più tranquillo se fosse in mani più... affidabili. Sempre che non ti dispiaccia, s'intende.$B$BMm... per arrivare a Kharanos dovrai passare per il tunnel.$B$BParla con Mountaineer Thalos prima di attraversarlo: ormai è completamente infestato dai trogg.$B$BSegui la strada fino ad Anvilmar, poi prosegui verso est fino al tunnel; Thalos è di stanza lì vicino.",
  obj = "Parla con Mountaineer Thalos.",
  progress = "Salve! Fai attenzione, $N: il tunnel per Dun Morogh è infestato dai trogg e non è sicuro attraversarlo.$B$BSe non hai affari urgenti a Dun Morogh, devo chiederti di restare ad Anvilmar finché il tunnel non sarà più sicuro.",
  reward = "Mm, beh, se Whitebeard ti manda a Dun Morogh per affari importanti, non posso certo fermarti, no?$B$BAlmeno lascia che ti dia qualche consiglio e qualche indicazione.",
  en_title = "Senir's Observations",
  en_obj = "Speak with Mountaineer Thalos.",
}
T[283] = {
  title = "Un'oscura minaccia incombe",
  desc = "Il barile sfrigola leggermente.",
  obj = "La Disarming Mixture sembra aver fatto effetto. Torna da Chief Engineer Hinderweir a riferire la buona notizia.",
  reward = "Grazie di cuore, $N!! Hai salvato la Stonewrought Dam! Senza il tuo aiuto, i terroristi Dark Iron avrebbero di sicuro distrutto questo possente monumento. Hai reso orgogliosi il Regno e l'Alleanza, $Gcoraggioso:coraggiosa; $C.$B$BLa Diga è di nuovo al sicuro... almeno per il momento...",
  en_title = "A Dark Threat Looms",
  en_obj = "The Disarming Mixture seemed to take effect.  Return to Chief Engineer Hinderweir to report the good news.",
}
T[284] = {
  title = "La ricerca continua",
  desc = "Perlustri a fondo questo gruppo di capanne murloc e non trovi traccia della Menethil Statuette.$B$BForse una delle due capanne vicine, a nord e a nord-est, avrà altri indizi.",
  obj = "Cerca la Menethil Statuette.",
  reward = "Questo barile è quasi intatto. Lo forzi...$B$B...e ti assale l'odore pungente del formaggio. È un po' bagnato, ma ancora buono!",
  en_title = "The Search Continues",
  en_obj = "Search for the Menethil Statuette.",
}
T[285] = {
  title = "Cerca in altre capanne",
  desc = "Questo gruppo di capanne murloc, dopo un'ispezione accurata, non rivela nulla.$B$B...ma sei $Gcerto:certa; che il prossimo indizio che troverai sarà quello buono.$B$BUna delle capanne a nord deve avere la Menethil Statuette!",
  obj = "Continua a cercare la Menethil Statuette nelle capanne murloc.",
  reward = "Questo barile è mezzo sepolto tra il fango e l'erba...",
  en_title = "Search More Hovels",
  en_obj = "Continue searching the Murloc hovels for the Menethil Statuette.",
}
T[286] = {
  title = "Riporta la statuetta",
  desc = "Dopo aver liberato il barile dalla melma e averlo aperto, si trova una figurina argentea avvolta in paglia fine. Raffigura un giovane paladino dai capelli lunghi con il martello sollevato.$B$BDeve essere la Menethil Statuette! Ora devi riportarla a Karl Boran, a Menethil Harbor.",
  obj = "Porta la Menethil Statuette a Karl Boran.",
  progress = "Hai la statuetta?",
  reward = "Il capitano della Blind Princess sarà sollevato di sapere che questo carico prezioso è stato recuperato. Ti sei $Gguadagnato:guadagnata; in pieno questo compenso per i servizi resi.$B$BFa piacere vedere gente affidabile come te, soprattutto in tempi difficili come questi.",
  en_title = "Return the Statuette",
  en_obj = "Bring Karl Boran the Menethil Statuette.",
}
T[287] = {
  title = "Frostmane Hold",
  desc = "Sono in ritardo con il mio rapporto e mi farebbe comodo il tuo aiuto, $N. Sono appena riuscito a scoprire dove si rintanano i troll, ma ne ho visti così tanti che ho avuto paura di entrare.$B$BEcco cosa mi serve... Scendi alla caverna, dai un'occhiata dentro, uccidi qualche troll e poi torna qui.$B$BPrendi la strada a nord di Kharanos; arrivato al ponte, segui il fiume ghiacciato verso ovest fino a Iceflow Lake. Troverai Brewnall Village sulla riva occidentale. La Hold è a sud-ovest del villaggio.",
  obj = "Esplora Frostmane Hold e uccidi 5 Frostmane Headhunters per Senir Whitebeard a Kharanos.",
  progress = "Non la trovi? Le mie indicazioni erano chiarissime! Non abbiamo molto tempo, devi sbrigarti! Non tornare finché non hai trovato la caverna.",
  reward = "Ah, $N! Non pensavo che avresti avuto difficoltà a trovare il posto, le mie indicazioni sono eccellenti, sai...$B$BAllora lasciami finire il rapporto.$B$B<Tira fuori un foglio e ci scarabocchia sopra per un momento.>$B$BEcco fatto! Beh, ah ah, questa sì che è buffa... Non è che ti dispiacerebbe farmi un ultimo favore, $N?",
  en_title = "Frostmane Hold",
  en_obj = "Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos.",
}
T[288] = {
  title = "La Third Fleet",
  desc = "Un tempo ero Primo Ufficiale sulla Wave Mistress, nave di linea della Third Fleet di Kul Tiras. La Flotta Dannata. Dannata, perché nel suo ultimo viaggio la flotta fu attaccata dai Red Dragon. Draghi controllati dagli orchi!$B$BNon avevamo scampo contro quel fuoco di drago... e la nostra flotta fu bruciata e affondata al largo di questa costa. Sono l'unico sopravvissuto di quelle povere navi...$B$B...Oh, la testa mi martella e mi pulsa! Mi serve una bevuta fresca se devo domare questa sbornia e continuare il racconto.",
  obj = "Compra un Flagon of Mead per First Mate Fitzsimmons.",
  progress = "Oh, ho una sete tremenda! Non offriresti da bere a questo povero, patetico scemo?",
  reward = "Ah! Questo sì che ci voleva, e scioglie la lingua. Grazie, socio!",
  en_title = "The Third Fleet",
  en_obj = "Buy First Mate Fitzsimmons a Flagon of Mead.",
}
T[289] = {
  title = "L'equipaggio maledetto",
  desc = "<Rinfrancato, Fitzsimmons riprende il racconto...>$B$BSono l'unico sopravvissuto della sventurata Third Fleet di Kul Tiras, naufragata al largo della costa a nord. Ma anche se sono l'unico membro della flotta che ancora respira, non sono l'unico che ancora cammina! Perché su una delle nostre navi era nascosto un tesoro grande e terribile, e il suo potere sinistro tiene le anime dei miei fratelli intrappolate negli scafi marcescenti delle navi.$B$BMa se riesci a liberare qualcuno dei miei fratelli, forse potrai spezzare la loro maledizione.",
  obj = "Uccidi 13 Cursed Sailor, 5 Cursed Marine e First Mate Snellig. Porta Snellig's Snuffbox a First Mate Fitzsimmons, a Menethil Harbor.",
  progress = "Nei miei sogni, a volte sento i gemiti dannati dei miei fratelli! Ti prego, $Gbuon signore:buona signora;, liberali dai vincoli e fa' tacere le loro grida.",
  reward = "Ti ringrazio, $N. E anche la gratitudine dei miei fratelli maledetti va a te.",
  en_title = "The Cursed Crew",
  en_obj = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig.  Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.",
}
T[290] = {
  title = "Spezzare la maledizione",
  desc = "Per spezzare la maledizione e liberare tutti i miei fratelli, quella... cosa... stivata sulla mia nave va recuperata e purificata! Non so cosa fosse, ma so che era custodita al sicuro nella cassaforte della nave, su cui vegliava Captain Halyndor.$B$BIl mio vecchio capitano è ancora nei miei sogni. So che cammina sulla mia nave dannata, l'Intrepid. Prendi la chiave da lui e usala per aprire la cassaforte dell'Intrepid.$B$BPoi, quando avrai la cosa maledetta, portala al sacerdote Glorin Steelbrow, in città.",
  obj = "Prendi l'Intrepid Strongbox Key da Captain Halyndor.$B$BUsa la chiave per aprire l'Intrepid's Locked Strongbox.",
  progress = "Questa cassa è chiusa saldamente a chiave.",
  reward = "La chiave è arrugginita, ma entra nella serratura alla perfezione.",
  en_title = "Lifting the Curse",
  en_obj = "Get the Intrepid Strongbox Key from Captain Halyndor.$B$BUse the key to open the Intrepid's Locked Strongbox.",
}
T[291] = {
  title = "I rapporti",
  desc = "Eccellente! Porta il mio rapporto al senatore Barin Redstone. È un tipo scorbutico, quindi non farti scoraggiare dal suo carattere poco solare. Si trova a Ironforge, nella sala dove re Magni tiene udienza.$B$BNon conosci la strada per Ironforge? Prendi la strada a nord di Kharanos, attraversa il ponte, poi segui la strada verso est (ci sono grandi stendardi ai lati) su per il fianco della montagna.$B$BA proposito, potresti evitare di dire che mi hai aiutato? Non posso lasciare che pensino che qui non lavoro sodo, capisci?",
  obj = "Consegna il rapporto di Senir al senatore Barin Redstone a Ironforge.",
  progress = "Mm... a quanto pare le mie guardie stanno diventando meno selettive con i postulanti. Allora, che cosa vuoi? Fai in fretta.",
  reward = "<Scorre rapidamente il rapporto.>$B$BPer autorità del RE!? Magni ha del tutto perso il senno? E quel maledetto Whitebeard... Ha deciso di fare di testa sua, eh? Il Senato non sarà affatto contento di saperlo, per niente.$B$BChe c'è, sei ancora qui? Vattene, prima che chiami le guardie!",
  en_title = "The Reports",
  en_obj = "Deliver Senir's report to Senator Barin Redstone in Ironforge.",
}
T[292] = {
  title = "L'Eye of Paleth",
  desc = "Aprendo la cassa si scopre una sfera annerita che pulsa di una luce sinistra. È il tesoro di cui parlava Fitzsimmons: un Cursed Eye of Paleth.$B$BPorta il Cursed Eye of Paleth al sacerdote nano Glorin Steelbrow, a Menethil Harbor. Chiedigli come togliere la maledizione dall'Eye.",
  obj = "Porta il Cursed Eye of Paleth a Glorin Steelbrow.",
  progress = "Quell'ubriacone di Fitzsimmons ti manda da me? Be', puoi dirgli che non ho birra in più. Dovrà andare a elemosinare da qualcun altro!",
  reward = "Un Eye of Paleth? Incredibile! Mmh... c'è qualcosa che non va in questo. L'hai trovato su uno di quei relitti? Be', questo spiega tutto! Ma... non sapevo che ne avessero uno sulla Third Fleet...$B$BNon c'è da stupirsi che Fitzsimmons fosse così spaventato. Un Cursed Eye of Paleth non è cosa da riderci sopra.",
  en_title = "The Eye of Paleth",
  en_obj = "Bring the Cursed Eye of Paleth to Glorin Steelbrow.",
}
T[293] = {
  title = "Purificare l'Eye",
  desc = "Non riesco a togliere la maledizione dall'Eye of Paleth. Gli Eye furono creati da sacerdoti umani, quindi dovrai andare a Stormwind a cercare qualcuno che possa aiutarti. Parla con Archbishop Benedictus. È a capo della Cathedral of Light di Stormwind. Lui può aiutarti.$B$BLo spero, per il tuo bene.",
  obj = "Porta il Cursed Eye of Paleth ad Archbishop Benedictus. Benedictus si trova nella Cathedral of Light, nella città di Stormwind.",
  progress = "Che sfera è quella che hai? Sembra... lordata.",
  reward = "Un Eye of Paleth. Ma questo ha visto molto dolore... deve essere stato testimone di una tragedia terribile, terribile.$B$BLascia che lo purifichi, perché gli Eye furono creati per splendere, e i loro poteri possono essere molto pericolosi se corrotti come questo.",
  en_title = "Cleansing the Eye",
  en_obj = "Bring Archbishop Benedictus the Cursed Eye of Paleth.  Benedictus is in the Cathedral of Light, in the city of Stormwind.",
}
T[294] = {
  title = "La vendetta di Ormer",
  desc = "La situazione è grave, questo è certo. Quando abbiamo portato alla luce queste ossa abbiamo attirato i raptor. Quelle bestie immonde hanno ucciso i miei compagni e hanno intrappolato quassù me, Merrin e il povero cercatore.$B$BAiuta a ripulire le Wetlands da questi raptor, $N. I Mottled Raptor e i Mottled Screecher sono appena a ovest del promontorio, là. Uccidine 10 di ciascuno, se ci riesci.$B$BSarà un buon inizio per la vendetta che ho in mente per loro.",
  obj = "Ormer Ironbraid, al Whelgar Excavation Site, vuole che tu uccida 10 Mottled Screecher e 10 Mottled Raptor.",
  progress = "Uccidi 10 Mottled Raptor e 10 Mottled Screecher, $N. I miei colleghi non meritavano la sorte che è toccata loro. È ora di pareggiare i conti.",
  reward = "Uccidere è un mestiere sporco, ma hai fatto bene il tuo lavoro, $N. Se non fossi obbligato a restare con il cercatore e Merrin, sarei laggiù a versare sangue al tuo fianco.",
  en_title = "Ormer's Revenge",
  en_obj = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.",
}
T[295] = {
  title = "La vendetta di Ormer",
  desc = "Ora è il momento di far pentire davvero quei maledetti raptor della loro sete di sangue. Proprio là sotto ci sono a bizzeffe Mottled Scytheclaw e Mottled Razormaw. Falla pagare a quelle creature marce uccidendone 10 di ciascuna!",
  obj = "Ormer Ironbraid vuole che tu uccida 10 raptor Mottled Scytheclaw e 10 raptor Mottled Razormaw, poi che torni da lui al Whelgar Excavation Site.",
  progress = "Voglio che quei Mottled Scytheclaw e quei Mottled Razormaw paghino per quello che hanno fatto. Ne hai già uccisi 10 di ciascuna specie?",
  reward = "Hai fatto un lavoro coi fiocchi ripulendo quei raptor, $N!",
  en_title = "Ormer's Revenge",
  en_obj = "Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.",
}
T[296] = {
  title = "La vendetta di Ormer",
  desc = "Mentre eri laggiù ho notato che uno di quei mostri spiccava sugli altri. Era più grosso e più minaccioso. Scommetto che è stato lui a guidare gli altri fin qui, a devastare il sito di scavo.$B$BTi chiedo ora un ultimo compito, $N. Fa' in modo che Sarltooth sia assicurato alla giustizia. E vista la gravità dei suoi crimini, in questo caso giustizia vuol dire morte! Portami uno dei suoi artigli come prova della sua morte.",
  obj = "Ormer Ironbraid, al Whelgar Excavation Site, vuole che tu uccida Sarltooth e torni da lui con uno dei suoi artigli, una volta compiuto il compito.",
  progress = "Sarltooth è morto? Hai riscattato la memoria dei caduti?",
  reward = "Grazie, $N. Quello che hai fatto qui non sarà dimenticato. Molti nani innocenti sono morti in questo sito, mentre facevano solo il loro lavoro. La vendetta che hai portato a quelle creature malvagie dovrebbe farle pensare due volte prima di attaccare ancora i sudditi di King Magni.",
  en_title = "Ormer's Revenge",
  en_obj = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.",
}
T[297] = {
  title = "Raccogliere gli idoli",
  desc = "Poco prima che i trogg sbucassero nel sito, avevamo portato alla luce un gran numero di strani idoli scolpiti. Ma non abbiamo avuto il tempo di studiarli, perché subito dopo la scoperta i trogg ci hanno cacciati dalle rovine! E quegli idoli hanno uno strano effetto sui trogg: li fanno impazzire!$B$BPortami 8 idoli: voglio studiarli, e voglio toglierli dalle mani dei trogg! Li trovi addosso ai trogg che infestano il sito.",
  obj = "Porta a Magmar Fellhew 8 Carved Stone Idols.",
  progress = "Hai quegli idoli? Dobbiamo studiarli e riferire le nostre scoperte a Ironforge!",
  reward = "Ce l'hai fatta! Ottimo lavoro, $N!$B$BE non sembri nemmeno troppo malridott$Go:a;, con quei trogg impazziti in giro. Ti terrò d'occhio... hai del potenziale.",
  en_title = "Gathering Idols",
  en_obj = "Bring Magmar Fellhew 8 Carved Stone Idols.",
}
T[298] = {
  title = "Rapporto sullo stato degli scavi",
  desc = "Devo mandare un rapporto sullo stato dei lavori a Thelsamar: un rapporto, e un nuovo sollecito per avere altra polvere da mina! Ecco il rapporto. Portalo a Jern Hornhelm, il nostro contatto a Thelsamar.$B$BNon è un compito difficile, ma va fatto.",
  obj = "Porta l'Ironband's Progress Report a Jern Hornhelm a Thelsamar.",
  progress = "Oh, un rapporto dal sito di scavo? Molto bene!",
  reward = "Bah! Ironband ha problemi con i trogg. Mi chiedo se voglia quella polvere per aiutarsi a scavare o per combattere quelle bestie...$B$BBeh, in ogni caso è polvere ben spesa!$B$BPerò è strano: gli ho mandato un sacco di polvere da mina settimane fa. Chissà dov'è finita...",
  en_title = "Excavation Progress Report",
  en_obj = "Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar.",
}
T[299] = {
  title = "Riportare alla luce il passato",
  desc = "Poco prima dell'invasione ho portato alla luce una grande tavoletta chiamata Goaz Stone. Il testo tradotto si interrompe in 4 punti. Parla di un \"piano divino\" e di una \"profezia dannata\".$B$BTemo che il tempo stia per scadere. Sono troppo vecchio per scendere ad affrontare quelle bestie. Ma tu sei forte.$B$BSetaccia il sito di scavo e riporta alla luce i 4 frammenti mancanti della tavoletta: Ados, Modr, Golm e Neru. Cercali negli artefatti antichi o dove il terreno è smosso. Portameli, così potrò cominciare a sciogliere il mistero!",
  obj = "Prospector Whelgar vuole che tu setacci il sito di scavo in cerca dei 4 frammenti mancanti della tavoletta: Ados, Modr, Golm e Neru.",
  progress = "Hai già riportato alla luce i quattro frammenti, $N? Ados, Modr, Golm e Neru...",
  reward = "Ah, la Goaz Stone è completa! Ottimo lavoro, $N. Davvero ottimo. Ora posso continuare la delicata traduzione di questa scrittura dei titani. Riesco già a distinguere parole nuove! Mmh... qui dice: \"Antichi Dei... Incatenati Sotto la Terra\". È l'inizio di qualcosa di epico.",
  en_title = "Uncovering the Past",
  en_obj = "Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.",
}
T[301] = {
  title = "Rapporto a Ironforge",
  desc = "Ci serve un'autorizzazione per dare a Ironband altra polvere da mina. Dovrai portare il suo rapporto al quartier generale dell'Explorers' League a Ironforge.$B$BEcco il rapporto. Consegnalo a Prospector Stormpike, e dopo averglielo dato ricordati di abbassare la testa. Stormpike è una testa calda e non sarà contento di sentire dei lenti progressi di Ironband.$B$BTroverai Stormpike nell'Assembly of Explorers.",
  obj = "Porta l'Ironband's Progress Report a Prospector Stormpike.",
  progress = "A noi Stormpike non piace essere disturbati per sciocchezze, $C. Spero che tu abbia portato notizie degne della mia preziosa attenzione.",
  reward = "Maledetto Ironband! Gli ho mandato un carico di polvere da mina settimane fa, ma in questo rapporto non ne fa parola.$B$BE allora... dov'è finita la polvere?!?",
  en_title = "Report to Ironforge",
  en_obj = "Take Ironband's Progress Report to Prospector Stormpike.",
}
T[302] = {
  title = "Polvere per Ironband",
  desc = "Se Ironband ha ancora bisogno di polvere da mina, per Magni, l'avrà! Ho già mandato l'autorizzazione tramite un messaggero a Jern Hornhelm, a Thelsamar. Preparerà la polvere e le altre provviste da portare a Ironband.$B$BE un'altra cosa: voglio che ti assicuri di persona che il carico di polvere arrivi a destinazione. L'ultimo non è arrivato, quindi tieni la mente sveglia e gli occhi aperti.",
  obj = "Parla con Jern Hornhelm a Thelsamar.",
  reward = "Cosa? Stormpike vuole che tu segua di persona il carico per Ironband?$B$BSuppongo... che vada bene. L'unico problema è che ho già mandato Huldar con i portatori, Miran e Saean. Li hai mancati per poco: sono partiti da pochissimo.",
  en_title = "Powder to Ironband",
  en_obj = "Speak with Jern Hornhelm in Thelsamar.",
}
T[303] = {
  title = "La guerra dei Dark Iron",
  desc = "La guerra infuria sia in patria sia all'estero. Mentre possenti soldati nani danno la vita in territori lontani nel nome dell'Alleanza, le nostre terre cadono preda delle malefatte dei Dark Iron Dwarf. Hanno devastato il Thandol Span. Dun Modr è caduta poco dopo.$B$BCi serve che tu raduni le forze e respinga il fronte. Se riesci a uccidere 15 Dark Iron Dwarf, 5 Tunneler, 5 Saboteur e 5 Demolitionist, la riserva potrebbe arrivare in tempo per chiudere la spinta.$B$BOra fa' presto!",
  obj = "Motley Garmason, a Dun Modr, vuole che tu uccida 15 Dark Iron Dwarf, 5 Dark Iron Tunneler, 5 Dark Iron Saboteur e 5 Dark Iron Demolitionist.",
  progress = "Roggo non è riuscito a contattare le forze di riserva. Ci serve pressione offensiva su quell'accampamento Dark Iron, $C. Adesso torna là fuori e fa' il tuo dovere verso King Magni!",
  reward = "Hai rispettato bene i tuoi ordini, $C. Ti sei $Gdimostrato:dimostrata; $Gun soldato valoroso:una soldatessa valorosa; e $Gun leale servitore:una leale servitrice; di King Magni, e per questo ti saluto! Con la pressione che hai messo sull'accampamento Dark Iron, ora abbiamo qualche possibilità di cacciarli dalle nostre terre per sempre... se solo arrivasse quella maledetta riserva...",
  en_title = "The Dark Iron War",
  en_obj = "Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.",
}
T[304] = {
  title = "Un compito tetro",
  desc = "Molti dei miei soldati sono morti nella battaglia di Dun Modr. Mio fratello è perito quando il West Bridge sul Thandol Span è stato distrutto. Sì, i nani Dark Iron sono una razza diabolica. Da quello che Roggo è riuscito a raccogliere, il capo di questa banda di bruti nelle Wetlands è uno stregone di nome Balgaras the Foul. È però un bel codardo. Manda i suoi soldati a fare il lavoro sporco e resta inafferrabile, evitando il pericolo.$B$BSe riesci a trovare quella feccia senza spina dorsale, uccidilo e portami il suo orecchio. Ti ricompenserò, $C.",
  obj = "Uccidi Balgaras the Foul e porta il suo orecchio a Longbraid the Grim, fuori da Dun Modr.",
  progress = "Sei già $Griuscito:riuscita; a trovare Balgaras the Foul, $C? Ci sfugge da parecchio tempo.",
  reward = "Balgaras the Foul è finalmente morto. Anche se la sua morte non riporterà indietro i tanti nani innocenti morti inutilmente per mano sua, aiuterà a ridare pace a chi è sopravvissuto. Con Balgaras morto, la feccia Dark Iron rimasta dovrebbe essere abbastanza facile da gestire. Ora dobbiamo spazzarli via prima che mandino da queste parti un nuovo capo.$B$BHai fatto bene, $C.",
  en_title = "A Grim Task",
  en_obj = "Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.",
}
T[305] = {
  title = "In cerca della squadra di scavo",
  desc = "Oh, tu devi essere $Gl'esploratore:l'esploratrice; che Longbraid ha detto che avrebbe mandato! Non puoi immaginare quanto sono stato in pena.$B$BMia moglie, Merrin, mi manda lettere ogni settimana da un mese. Fa parte della squadra di scavo di Whelgar. Ma sono passate quasi due settimane dall'ultima lettera. Qualcosa non va di sicuro!$B$BLongbraid aveva detto che avrebbe mandato un esploratore a controllare, se non avessimo avuto notizie della squadra. Immagino che $Gquell'esploratore:quell'esploratrice; sia tu, $N. Trova Merrin al sito di scavo, a est!",
  obj = "Tarrel Rockweaver vuole che tu raggiunga l'Excavation Site e contatti Merrin Rockweaver.",
  reward = "Oh, siano ringraziati i cieli, sei qui!",
  en_title = "In Search of The Excavation Team",
  en_obj = "Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.",
}
T[306] = {
  title = "In cerca della squadra di scavo",
  desc = "È stato orribile! Stavamo portando alla luce certi artefatti rari e abbiamo cominciato a trovare queste ossa enormi.$B$BPrima che ci rendessimo conto di cosa stava succedendo, questi Mottled Raptor hanno invaso il sito di scavo. Molte vite sono andate perdute.$B$BOrmer, qui, così coraggioso, ha salvato il cercatore e me. Ci ha difesi mentre correvamo al riparo. Ora siamo intrappolati. E il nostro duro lavoro è in rovina.$B$BEcco, riporta questo biglietto al mio caro Tarrel. Gli spiegherà la situazione.",
  obj = "Torna da Tarrel Rockweaver con Merrin's Note.",
  progress = "Sei $Griuscito:riuscita; a trovare Merrin? Ha mandato sue notizie?",
  reward = "Che notizie orribili! Almeno tre di loro sono sopravvissuti. Ma quando finirà questa mattanza? Aspetto con ansia il giorno in cui i sudditi di re Magni potranno vivere senza paura.",
  en_title = "In Search of The Excavation Team",
  en_obj = "Return to Tarrel Rockweaver with Merrin's note.",
}
T[307] = {
  title = "Zampe sudicie",
  desc = "La Silver Stream Mine, a est, si è esaurita molto tempo fa. La Miners' League l'ha trasformata in un deposito, ma ora ci si sono stabiliti i coboldi, che mettono le loro zampe sudicie su buoni attrezzi nanici!$B$BPresto staneremo quei parassiti, ma la Lega vuole che qualcuno porti fuori la loro attrezzatura prima che noi guerrieri entriamo a spaccare tutto. Sarà una discesa difficile: forse ti conviene avere dei compagni al tuo fianco.$B$BL'attrezzatura è custodita nei Miners' League Crates sparsi per la miniera. Buona fortuna.",
  obj = "Vai alla Silver Stream Mine e raccogli 4 carichi di Miners' Gear.$B$BTorna da Mountaineer Stormpike.",
  progress = "Hai quella Miners' Gear, $N?",
  reward = "Hai visto molti coboldi là dentro? Non vedo l'ora che arrivi l'ordine di ripulire la miniera. Il solo pensiero delle loro mani sudicie che frugano nella nostra miniera mi fa brontolare lo stomaco!",
  en_title = "Filthy Paws",
  en_obj = "Go to the Silver Stream Mine and collect 4 loads of Miners' Gear.$B$BReturn to Mountaineer Stormpike.",
}
T[308] = {
  title = "Distrarre Jarven",
  progress = "Mph! Quaggiù c'è un mucchio di alcol, ma ho ordini severi di non toccarlo. Se solo potessi assaggiare un po' della nostra Thunder Ale... mi schiarirebbe le idee, parola mia!",
  reward = "Per me? Sei $Gun vero eroe:una vera eroina;, $N!",
  en_title = "Distracting Jarven",
}
T[309] = {
  title = "Proteggere il carico",
  desc = "Pront$Go:a; a partire, $N?$B$BPer prima cosa dobbiamo portare questa polvere a Ironband. Per me è un carico pesante, e queste zone possono diventare pericolose... e chissà cos'altro hanno in serbo per me i Dark Iron.$B$BMi sentirò molto più tranquillo se vieni con me.",
  obj = "Assicurati che Miran e il carico arrivino al sito di scavo, poi informa Prospector Ironband.",
  progress = "Dov'è la mia polvere, $N? Ogni giorno che passa ne ho più disperato bisogno.",
  reward = "Oh, sia lodata la Luce, la polvere è arrivata. Ma porti anche notizie preoccupanti. Pensare che i Dark Iron abbiano simpatizzanti capaci di procurare materiale del genere per i loro piani infami.$B$BÈ una questione che dovrà valutare qualcun altro, un'altra volta. Io devo mettere a frutto questa polvere.",
  en_title = "Protecting the Shipment",
  en_obj = "Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband.",
}
T[310] = {
  title = "Rivali acerrimi",
  desc = "Devo ammetterlo, quei Thunderbrew fanno delle buone bevande. Ma devono capire che la loro non è l'unica birra decente! Forse puoi aiutarmi a dar loro una lezione...$B$BEcco, prendi questo barile di Barleybrew Scalder. Intrufolati nella cantina della Thunderbrew Distillery a Kharanos e scambialo con uno dei loro barili di Thunder Ale. Poi vedremo se i loro clienti preferiscono la mia birra alla loro!$B$BE se i barili sono sorvegliati, forse dovrai distrarre la guardia...",
  obj = "Nella cantina della Thunderbrew Distillery a Kharanos, sostituisci un barile di Thunder Ale con un Barrel of Barleybrew Scalder.",
  progress = "La data su questo barile indica che sarà spillato a breve.",
  reward = "Metti rapidamente il barile di Barleybrew Scalder di Marleth tra i barili dei Thunderbrew.",
  en_title = "Bitter Rivals",
  en_obj = "In the basement of the Thunderbrew Distillery in Kharanos, replace a barrel of Thunder Ale with a Barrel of Barleybrew Scalder.",
}
T[311] = {
  title = "Ritorno da Marleth",
  desc = "Dopo aver piazzato un barile di Scalder di Marleth nella cantina della distilleria di Kharanos, afferri un barile di Thunder Ale come prova dell'impresa...",
  obj = "Porta il barile di Thunder Ale a Marleth Barleybrew a Brewnall Village.",
  progress = "Hai fatto lo scambio?",
  reward = "Niente male, $N! Hai avuto difficoltà a superare la loro guardia?$B$BNon importa: mille grazie! E se mai ti servisse una birra scura che dà la carica, non dimenticare i Barleybrew!",
  en_title = "Return to Marleth",
  en_obj = "Bring the barrel of Thunder Ale to Marleth Barleybrew at the Brewnall Village.",
}
T[312] = {
  title = "La scorta rubata di Tundra MacGrann",
  desc = "Avevo un mese di carne secca, salata e chiusa sotto chiave per la stagione fredda. La tenevo sotto chiave perché gli orsi non la prendessero! Ma mentre ero a caccia di cervi, quella bestia di Old Icebeard si è portato via la cassa della carne. Il thorium non riuscirà a sfondarlo, però. Ma io morirò di fame se non riavrò la mia carne.$B$BTu sembri un po' più furtiv$Go:a; di me. Forse puoi recuperare la mia scorta? Con questa gamba malandata non riuscirei mai a entrare e uscire da quella caverna abbastanza in fretta.",
  obj = "Recupera la carne secca di Tundra MacGrann dalla cassa rubata nella caverna di Old Icebeard.",
  progress = "Sei riuscit$Go:a; ad aprire la mia cassa della carne, $N?",
  reward = "Che anima gentile sei, $N! Grazie al tuo coraggio non morirò di fame quando arriveranno le bufere della stagione fredda.",
  en_title = "Tundra MacGrann's Stolen Stash",
  en_obj = "Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave.",
}
T[313] = {
  title = "The Grizzled Den",
  desc = "Guidare una macchina d'assedio non è per tutti. Ci vogliono una presa di ferro e nervi d'acciaio... per fortuna io ho entrambi! E tu? Che tempra hai? Vuoi dimostrarmelo?$B$BBeh... vorrei rendere la mia macchina, Trollplow, un po' più accogliente. Che ne dici di portarmi un bel mucchio di Wendigo Manes dal Grizzled Den, a ovest di Kharanos? Quelle criniere sarebbero un tappeto perfetto per il ponte interno di Trollplow!",
  obj = "Raccogli 8 Wendigo Manes e portale a Pilot Stonegear.",
  progress = "Ehi, $N. Sei già stat$Go:a; al Grizzled Den? Quei wendigo sanno essere feroci.",
  reward = "Ah sì, queste criniere andranno benissimo! Hai davvero del fegato, $C: scommetto che sentiremo parlare di te.",
  en_title = "The Grizzled Den",
  en_obj = "Gather 8 Wendigo Manes and bring them to Pilot Stonegear.",
}
T[314] = {
  title = "Proteggere la mandria",
  desc = "Abbiamo sentito le urla nel cuore della notte. E stamattina, come temevamo, alla mandria mancavano due arieti. Quella bestia infame chiamata Vagash sta distruggendo il nostro sostentamento. Con gran parte dell'esercito di re Magni in terre lontane a combattere al fianco dell'Alleanza, non c'è nessuno a tenere a bada Vagash.$B$BForse tu hai il coraggio di cercare la bestia e ucciderla. Portami una delle sue zanne e ti ricompenserò. Vagash si aggira proprio sopra il ranch, ma sta' attent$Go:a;: è letale.",
  obj = "Rudra Amberstill vuole che tu uccida Vagash e le porti la sua zanna al ranch degli arieti.",
  progress = "Vagash terrorizza ancora la mandria! Ti prego, aiutaci uccidendo quella bestia maledetta.",
  reward = "Ottimo lavoro! Veron sarà felicissimo quando sentirà la buona notizia. Uccidere Vagash non è un'impresa da poco. Immagino che un giorno combatterai al fianco degli uomini di re Magni sul fronte dell'Alleanza.",
  en_title = "Protecting the Herd",
  en_obj = "Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.",
}
T[315] = {
  title = "La birra scura perfetta",
  desc = "Sono in missione: la missione di creare la birra scura perfetta. So di potercela fare, la birra ce l'ho nel sangue. Devo solo trovare la ricetta giusta...$B$BI troll Frostmane coltivano una pianta, lo shimmerweed, in alto sulle colline a est. La usano nei loro strani rituali tribali. Noi nani non ne abbiamo mai trovato un grande uso, ma ha un sapore unico... e voglio sperimentarla nelle mie birre!$B$BProcurami un po' di shimmerweed dai Frostmane Seers, oppure rubalo dai cesti di shimmerweed dei troll.",
  obj = "Porta 6 Shimmerweed a Rejold Barleybrew a Brewnall Village.",
  progress = "Hai lo shimmerweed? Ho quasi pronta una partita di birra scura da fermentare e voglio provare ad aggiungerci l'erba.",
  reward = "Fantastico! Non vedo l'ora di usarlo in qualcuna delle mie ricette. Ce n'è una in particolare in cui credo che funzionerà benissimo...",
  en_title = "The Perfect Stout",
  en_obj = "Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village.",
}
T[317] = {
  title = "Rifornire Jetsteam",
  desc = "Mi sto preparando a partire per una missione della Siege Brigade. Sarà lunga, e devo rifornire Jetsteam con provviste per un mese. Quindi, mentre Steelgrill lavora al mio carro, potresti andare a caccia per me?$B$BMi servono pellicce per il giaciglio e carne di cinghiale da mangiare. La carne la prendi dai cinghiali e le pellicce dagli orsi... li trovi entrambi nelle distese innevate a sud del Grizzled Den.",
  obj = "Raccogli 4 Chunks of Boar Meat e 2 Thick Bear Furs e consegnali a Pilot Bellowfiz a Steelgrill's Depot.",
  progress = "I preparativi procedono bene. Come va la caccia?",
  reward = "Per la barba di Magni, hai cacciato proprio tanto! Grazie, $N.",
  en_title = "Stocking Jetsteam",
  en_obj = "Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot.",
}
T[318] = {
  title = "Evershine",
  desc = "Rejold Barleybrew fa esperimenti con le sue birre. Alcune sono buone, altre cattive, e alcune... beh, alcune stendono tutti i nani tranne i più robusti.$B$BVive a Brewnall Village, a ovest di Kharanos, e una delle sue bevande, l'Evershine, è quella che voglio. Mi aiuterà a scaldarmi lungo la strada gelida.$B$BE... quella roba benedetta brucia così forte che posso buttarla nella caldaia di Jetsteam per una spinta di potenza! Quel trucchetto mi ha tirato fuori dai guai più di una volta.",
  obj = "Procurati una botticella di Evershine da Rejold Barleybrew a Brewnall Village.",
  reward = "Bellowfiz ha bisogno del mio Evershine? Mm... d'accordo.",
  en_title = "Evershine",
  en_obj = "Get a cask of Evershine from Rejold Barleybrew in Brewnall Village.",
}
T[319] = {
  title = "Un favore per l'Evershine",
  desc = "Ho una botticella di Evershine a portata di mano, ma... puoi farmi un favore? A Brewnall Village farebbe comodo un aiuto contro gli animali selvatici che vagano per le nevi qui intorno. A volte si avvicinano troppo.$B$BNon abbiamo paura di questi orsi, felini e cinghiali (nessun nano che si rispetti ne avrebbe), ma se te ne occupassi tu avremmo più tempo per i nostri mestieri e le nostre birre.",
  obj = "Uccidi 6 Ice Claw Bears, 8 Elder Crag Boars e 8 Snow Leopards, poi torna da Rejold Barleybrew a Brewnall Village.",
  progress = "Ti sei occupat$Go:a; di quegli animali selvatici?",
  reward = "Grazie, $N. Sarà bello lavorare senza sentire tanti ringhi e grugniti fuori dal villaggio.",
  en_title = "A Favor for Evershine",
  en_obj = "Kill 6 Ice Claw Bears, 8 Elder Crag Boars, and 8 Snow Leopards, and then return to Rejold Barleybrew in Brewnall Village.",
}
T[320] = {
  title = "Ritorno da Bellowfiz",
  desc = "Ecco la tua botticella di Evershine, $N. E grazie ancora per la caccia di prima.",
  obj = "Consegna la botticella di Evershine a Pilot Bellowfiz a Steelgrill's Depot.",
  progress = "Hai preso quell'Evershine?",
  reward = "Sì, questo andrà benissimo. Credo che ne aprirò subito una bottiglia per assaggiarlo...",
  en_title = "Return to Bellowfiz",
  en_obj = "Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.",
}
T[321] = {
  title = "Lightforge Iron",
  desc = "I relitti al largo di questa costa sono la sventurata Third Fleet di Kul'Tiras, bruciata e affondata dai Red Dragon durante l'ultima Grande Guerra.$B$BLa flotta veniva da Lordaeron, ma con lei c'era una nave, un vascello da guerra elfico: la Flying Osprey. Trasportava un carico di Lightforge Iron e si era unita alla Third Fleet per avere protezione. Ironico che sia affondata per opera degli stessi draghi...$B$BBasta storia. La Flying Osprey è naufragata a sud di Menethil Harbor. Se trovi lì il Lightforge Iron, portamelo.",
  obj = "Cerca tra i relitti della Flying Osprey, nelle Wetlands.",
  reward = "Questa cassa è impregnata d'acqua e le fiancate sono rotte. Molti segni di artigli rovinano l'interno e l'esterno della cassa... come se dei murloc l'avessero frugata e ne avessero rubato il tesoro.$B$BMa in fondo alla cassa, ben infilato, c'è un solo Lightforge Ingot. Purtroppo ne serviranno molti altri per avere metallo a sufficienza da forgiare un'arma.",
  en_title = "Lightforge Iron",
  en_obj = "Search the wreckage of The Flying Osprey in the Wetlands.",
}
T[322] = {
  title = "L'arma benedetta",
  desc = "Nel Dwarven District di Stormwind c'è un armaiolo nano che sa lavorare il Lightforge Iron. Si chiama Grimand Elmore.$B$BHo messo in una cassa il metallo che hai trovato. Portala a Grimand e raccontagli la tua storia. Sono sicuro che darà una mano a chi è impegnato in un'impresa come la tua, e ti forgerà un'arma: un'arma che farà preoccupare perfino Morbent Fel!",
  obj = "Porta la Crate of Lightforge Ingots a Grimand Elmore, a Stormwind.",
  progress = "In cosa posso mettere la mia arte al tuo servizio, $C?",
  reward = "Quella sì che è una bella storia. E Lightforge Iron! Non lavoro un metallo simile da anni. Sarà un onore lavorarlo di nuovo. E dovrai tornare da me più avanti a raccontarmi la tua battaglia contro il negromante.$B$BMa stiamo correndo troppo. Prima, la tua arma contro Morbent Fel...",
  en_title = "Blessed Arm",
  en_obj = "Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.",
}
T[323] = {
  title = "Dimostra il tuo valore",
  desc = "Morbent Fel è un negromante, e un alleato dei Dark Rider. Ti metterei contro il potere di Morbent Fel, ma non ti manderò contro quel mostro immondo senza prima conoscere la tua forza.$B$BIl tuo coraggio me l'hai già dimostrato, ma se vuoi davvero affrontare il negromante, allora devi dimostrare la tua abilità contro i suoi servi.",
  obj = "Uccidi 15 Skeletal Raider, 3 Skeletal Healer e 3 Skeletal Warder, poi torna da Sven.",
  progress = "Combatti con forza, $N. E non disperare, perché la disperazione è l'arma più grande del male.",
  reward = "La tua abilità in combattimento, $N, è fuori discussione. La tua determinazione potrebbe portarci fino alla fine di Morbent Fel!",
  en_title = "Proving Your Worth",
  en_obj = "Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.",
}
T[324] = {
  title = "I lingotti perduti",
  desc = "Preso l'unico Lightforge Ingot dalla cassa impregnata d'acqua, è chiaro che i murloc hanno rubato il resto. Dai la caccia ai murloc predoni vicino al relitto della Flying Osprey per recuperare il Lightforge Iron perduto.",
  obj = "Raccogli 5 Lightforge Ingot, poi torna da Glorin Steelbrow, nelle Wetlands.",
  progress = "L'hai trovato il Lightforge Iron che ti serve?",
  reward = "Ah, li hai trovati! E adesso battiamo questo Lightforge Iron fino a farne qualcosa di utile, eh?",
  en_title = "The Lost Ingots",
  en_obj = "Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.",
}
T[325] = {
  title = "Armi in pugno",
  desc = "Ecco l'arma contro quel mostro di cui parlavi. Sei $Gpronto:pronta;, $N. Buona fortuna, e aspetto con ansia il racconto della tua gloria!",
  obj = "Porta Morbent's Bane a Sven, a Duskwood.",
  progress = "Salve, $N. Non sei $Gstato:stata; via molto, ma vedo nei tuoi occhi un fuoco che prima non c'era.",
  reward = "Ah, questa reggerà contro quel mostro di Morbent Fel! Ben fatto!$B$BSei $Gpronto:pronta;. Morbent Fel cadrà.",
  en_title = "Armed and Ready",
  en_obj = "Bring Morbent's Bane to Sven in Duskwood.",
}
T[328] = {
  title = "La chiave nascosta",
  desc = "Anche se in questi registri non si trova alcun accenno a Private Thorsen, nascosta nella rilegatura di uno dei libri contabili di Herod c'è una Small Brass Key.$B$BE, studiando meglio i suoi appunti, tra le varie carte si trovano alcuni riferimenti a un \"forziere sicuro\". Il forziere si trova da qualche parte nello Stockpile — il complesso di caverne sul retro del Kurzen's Compound.$B$BSe si trova questo forziere sicuro, e se la Small Brass Key riesce ad aprirlo, forse si svelerà il mistero di come è stato scoperto Thorsen.",
  obj = "Usa la Small Brass Key per aprire il Bookie Herod's Strongbox.",
  progress = "Il forziere è rinforzato in bronzo, molto robusto e molto pesante.",
  reward = "Aprendo il forziere, è chiaro che è qui che Herod tiene le monete e gli oggetti di maggior valore.",
  en_title = "The Hidden Key",
  en_obj = "Use the Small Brass Key to open Bookie Herod's Strongbox.",
}
T[329] = {
  title = "La spia smascherata!",
  desc = "Tra gli oggetti di valore del forziere c'è un Muddy Note scarabocchiato. Anche se è a malapena leggibile, sembra un itinerario di Private Thorsen. Descrive nei dettagli i suoi percorsi di pattuglia, con chi parla e come passa il tempo con i ribelli. È firmato con una sola lettera: -M.$B$BMa chiunque abbia scritto questo biglietto deve essere stato molto vicino a Thorsen. Chiunque abbia scritto questo biglietto è il traditore all'interno del Rebel Camp.",
  obj = "Porta il Muddy Note a Lieutenant Doren, al Rebel Camp.",
  progress = "Hai scoperto chi conosceva il segreto di Thorsen? C'è un traditore tra noi?",
  reward = "Grazie, $N. Questo biglietto è l'indizio che ci serve per stanare il traditore!",
  en_title = "The Spy Revealed!",
  en_obj = "Take the Muddy Note to Lieutenant Doren at the Rebel Camp.",
}
T[330] = {
  title = "I turni di pattuglia",
  desc = "Il biglietto che mi hai dato è firmato con una \"-M\"... non so cosa possa significare.$B$BMa... il biglietto dice anche che la settimana scorsa questa persona ha condiviso i percorsi di pattuglia con Thorsen. Quindi chiunque abbia fatto la pattuglia con Thorsen la settimana scorsa dev'essere il traditore!$B$BVa' da Corporal Sethman. Si occupa dei turni di pattuglia e può dirti chi era con Thorsen.",
  obj = "Parla con Corporal Sethman.",
  reward = "Oh, sì, posso controllarlo io per te. Vediamo... la settimana scorsa c'era...$B$B...ma guarda, in turno con Thorsen c'era Private Merle. Hanno avuto gli stessi orari di pattuglia per tutta la settimana scorsa.",
  en_title = "Patrol Schedules",
  en_obj = "Speak with Corporal Sethman.",
}
T[331] = {
  title = "Rapporto a Doren",
  desc = "Lieutenant Doren voleva che tornassi a fargli rapporto con quelle informazioni sulle pattuglie?",
  obj = "Parla con Lieutenant Doren.",
  reward = "Mi addolora scoprire che è stato Merle a tradirci. È sempre stato un soldato coraggioso, e credevo che il suo cuore fosse leale. Ma è un gran sollievo averlo smascherato — con una spia come lui tra noi... non resisteremmo a lungo contro Colonel Kurzen.",
  en_title = "Report to Doren",
  en_obj = "Speak with Lieutenant Doren.",
}
T[332] = {
  title = "Pubblicità per l'enoteca",
  desc = "Se parli di vino con qualcuno, saprai che noi Gallina vendiamo il miglior vino di Stormwind. E non siamo lontani, sempre nel Trade District, lungo i bei canali della città.$B$BEcco, prendi questo opuscolo. Portalo a mia sorella Suzetta nel nostro negozio per una bottiglia in omaggio del nostro famoso pinot noir. Non te ne pentirai!",
  obj = "Vai alla Gallina Winery e porta a Suzetta Gallina il Wine Ticket per una bottiglia di vino gratis.",
  progress = "Salve, $Gsignore:signora;, e benvenut$Go:a;. Avete già assaggiato uno dei nostri vini pregiati?",
  reward = "Ah, dunque avete visto Renato? Ecco a voi, $Gsignore:signora;. Una bottiglia del nostro speciale pinot noir. Non ne troverete uguali in tutta Azeroth!",
  en_title = "Wine Shop Advert",
  en_obj = "Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine.",
}
T[333] = {
  title = "Harlan ha bisogno di rifornimenti",
  desc = "Ultimamente facciamo molti affari. Sembra che tutti comprino armature e abiti robusti. Quasi come se si aspettassero una stagione fredda e dura...$B$BMa queste sono preoccupazioni future. La mia preoccupazione di oggi è che sto finendo gli abiti di maglia da vendere. Mi serve un altro carico dal nostro fornitore.$B$BSe puoi portare questa richiesta a Rema Schneider al Canal Tailor and Fit Shop, ti sarei molto grato.",
  obj = "Vai al Canal Tailor Shop e porta a Rema Schneider la Cloth Request di Harlan Bagley.",
  progress = "Porti notizie dal signor Bagley?",
  reward = "Qui dice che gli affari di Harlan vanno a gonfie vele. È una buona notizia, ma mi chiedo perché la gente abbia bisogno di tutte quelle armature. Non ho sentito parlare di guerra aperta... c'è qualcosa che i nobili non ci dicono?$B$BBene, grazie per aver portato la richiesta. Ecco il tuo compenso, e mi assicurerò che Harlan riceva le sue forniture.",
  en_title = "Harlan Needs a Resupply",
  en_obj = "Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley.",
}
T[334] = {
  title = "Un pacco per Thurman",
  desc = "Mio figlio Thurman è apprendista alla Larson Clothiers, nel Mage's Quarter. Oggi aveva fretta e ha dimenticato forbici e aghi. So che un grande $C come te avrà compiti importanti da svolgere, ma senza i suoi attrezzi Thurman non può fare il suo lavoro di apprendista!$B$BPer favore, $N. Puoi portargli il kit da cucito di mio figlio? La Larson Clothiers è uno dei due negozi di abbigliamento nel Mage's Quarter: è quello più all'interno, vicino alla Mage's Tower.",
  obj = "Vai alla Larson Clothiers nello Stormwind Mage Quarter e consegna a Thurman Schneider il suo Sewing Kit.",
  progress = "Sei qui per comprare dei vestiti?",
  reward = "Oh, accidenti! Pensavo che dimenticare il kit mi avrebbe liberato dal lavoro. Adesso immagino che dovrò aiutare i Larson a cucire...$B$BVa be', il divertimento verrà più tardi, suppongo.",
  en_title = "Package for Thurman",
  en_obj = "Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit.",
}
T[335] = {
  title = "Un intruglio per nobili",
  desc = "Lord Wishock sta facendo parecchio rumore in seno all'House of Nobles. È venuto a sapere del nostro piccolo \"locale\" quaggiù e si sta dando da fare per un'indagine completa. Ho un piano per tenere Wishock \"occupato\", ma mi servirà il tuo aiuto.$B$BC'è un fiore che cresce nel Garden of Stalvan, alle porte di Darkshire. Questo fiorellino bianco si chiama Tear of Tilloa. Mi servirà anche una Musquash Root, che si trova solo proprio ai piedi delle cascate molto più in basso della Stonewrought Dam, nelle Wetlands.",
  obj = "Zardeth the Black Claw vuole che tu gli porti una Tear of Tilloa da Darkshire e una Musquash Root dalle Wetlands.",
  progress = "Presto Wishock avrà abbastanza appoggi da procurarci molti guai. Sei già $Griuscito:riuscita; a procurarti la Tear of Tilloa o la Musquash Root?",
  reward = "Magnifico! Questi sì che sono campioni di qualità!",
  en_title = "A Noble Brew",
  en_obj = "Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands.",
}
T[336] = {
  title = "Un intruglio per nobili",
  desc = "Lord Wishock, come tutti gli uomini, ha le sue debolezze. La sua è la passione per il liquore. L'ipocrisia è sbalorditiva. Quello sciocco banale passa le giornate a cercare di far chiudere la nostra piccola \"taverna\", mentre passa le notti al piano di sopra ad accumulare un conto che non paga mai. Bene, vediamo come gli piace questo intruglio speciale che ho preparato per lui: la Black Claw Stout. Ha una bella botta, $N.$B$BPortagliela e vedi se gli piace. Con ogni probabilità quel vecchio sciocco bighellona per l'Hall of Petitioners.",
  obj = "Porta la Black Claw Stout a Lord Wishock, all'Hall of Petitioners.",
  progress = "Non vedi che sono occupato? Le mie parole devono essere ascoltate! Io sono molto importante per il futuro di questo Regno!$B$BOh... cos'hai lì? Ma sembra una bevanda rinfrescante...",
  reward = "Ah, grazie di avermi portato questa bella stout, servo. Ecco un rame per te. Ora togliti di torno e lasciami gustare la mia bevanda!",
  en_title = "A Noble Brew",
  en_obj = "Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners.",
}
T[337] = {
  title = "Un vecchio libro di storia",
  desc = "Anche se la copertina di questo libro è rovinata dai graffi e incrostata di fango, sul dorso si legge ancora \"The History of Stormwind\". Aprendolo, sulla prima pagina si vede chiaro il sigillo della Stormwind Library.$B$BSembra che qualcuno abbia preso in prestito questo libro e non l'abbia mai restituito...",
  obj = "Restituisci il libro \"The History of Stormwind\" alla Stormwind Library.",
  progress = "Ooh! Cos'è quel vecchio libro che hai lì? Posso vederlo??",
  reward = "Oh cielo! Questo libro non stava su questi scaffali da prima della ricostruzione di Stormwind, anni fa. Andrà restaurato, ovviamente, è messo male, ma sarà un onore metterlo nella nostra raccolta di libri rari.$B$BGrazie, $Gsignore:signora;. Prendi questo come pagamento per aver riportato il libro!",
  en_title = "An Old History Book",
  en_obj = "Return the book: The History of Stormwind, to the Stormwind Library.",
}
T[338] = {
  title = "The Green Hills of Stranglethorn",
  desc = "Master Nesingwary si arrabbierà tantissimo se lo scopre!$B$BMi aveva affidato la correzione delle bozze del suo romanzo, The Green Hills of Stranglethorn. Andava tutto bene, ma una forte raffica di vento ha attraversato l'accampamento e ha sparpagliato le pagine dappertutto!$B$BHo recuperato quasi tutte le pagine, ma molte sono ancora sparse per la giungla. Raccogli le pagine per completare ciascuno dei quattro capitoli.$B$BTi aiuterò a metterle in ordine. Riportami i capitoli quando li avrai tutti e quattro.",
  obj = "Raccogli le pagine mancanti del manoscritto di The Green Hills of Stranglethorn. Quando tutti e quattro i capitoli saranno completi, riportali a Barnil.",
  progress = "Hai già rimesso insieme i capitoli, $N?",
  reward = "Mi hai proprio risparmiato un mucchio di guai, $N! Non so come ringraziarti. Ormai non manca molto prima di vedere il libro di Master Nesingwary nelle biblioteche di tutto il mondo!",
  en_title = "The Green Hills of Stranglethorn",
  en_obj = "Collect the missing pages from The Green Hills of Stranglethorn manuscript.  Once all four chapters are complete, return them to Barnil.",
}
T[339] = {
  title = "Chapter I",
  desc = "Il Chapter I era davvero avvincente! Master Nesingwary delinea lo sfondo della storia e menziona i suoi compagni di caccia, tra cui anche me!$B$BMa non è questo il punto. Vediamo quali pagine mancano ancora. Sembra che le pagine 1, 4, 6 e 8 siano ancora là fuori, da qualche parte nella giungla!",
  obj = "Porta le pagine 1, 4, 6 e 8 di Nesingwary's The Green Hills of Stranglethorn a Barnil Stonepot, per completare il Chapter I.",
  progress = "Non è che per caso sei $Griuscito:riuscita; a trovare le pagine 1, 4, 6 e 8? Ci servono solo quelle quattro per ricomporre il Chapter I.",
  reward = "Finalmente! Il Chapter I è completo!",
  en_title = "Chapter I",
  en_obj = "Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.",
}
T[340] = {
  title = "Chapter II",
  desc = "Il Chapter II era pieno zeppo di storie emozionanti di caccia alla pantera e alla tigre. Mi prenderei a calci per aver lasciato volar via le pagine!$B$BSembra che io abbia recuperato tutte le pagine, tranne le pagine 10, 11, 14 e 16.",
  obj = "Porta le pagine 10, 11, 14 e 16 di Nesingwary's The Green Hills of Stranglethorn a Barnil Stonepot, per completare il Chapter II.",
  progress = "Ci servono ancora le pagine 10, 11, 14 e 16 per completare il Chapter II, $N.",
  reward = "Il Chapter II è finalmente completo! Ben fatto!",
  en_title = "Chapter II",
  en_obj = "Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.",
}
T[341] = {
  title = "Chapter III",
  desc = "Il Chapter III era il mio preferito. Racconta la prima preda di Sir Erlgadin e Lady Rouack con un fucile nanico. E la fine del Chapter III, accidenti, che suspense!$B$BMi sembra che ci servano ancora le pagine 18, 20, 21 e 24 per finire il capitolo. Quelle pagine sono là fuori, da qualche parte...",
  obj = "Porta le pagine 18, 20, 21 e 24 di Nesingwary's The Green Hills of Stranglethorn a Barnil Stonepot, per completare il Chapter III.",
  progress = "Hai avuto fortuna con le pagine 18, 20, 21 o 24? Sono le uniche che ci servono per ricomporre il Chapter III.",
  reward = "Uff! Ottimo lavoro, $N. Il Chapter III è di nuovo tutto intero!",
  en_title = "Chapter III",
  en_obj = "Bring pages 18, 20, 21 and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.",
}
T[342] = {
  title = "Chapter IV",
  desc = "Ah, il Chapter IV: il gran finale! E che finale è stato!$B$BCi mancano solo tre pagine per questo capitolo. Ci servono le pagine 25, 26 e 27 per ricomporre il Chapter IV.",
  obj = "Porta le pagine 25, 26 e 27 di Nesingwary's The Green Hills of Stranglethorn a Barnil Stonepot, per completare il Chapter IV.",
  progress = "Ci servono solo tre pagine per finire il Chapter IV, $N. Hai già le pagine 25, 26 o 27?",
  reward = "Magnifico! Ora il Chapter IV è pronto!",
  en_title = "Chapter IV",
  en_obj = "Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.",
}
T[343] = {
  title = "A proposito di fortezza",
  desc = "Terrò un discorso sulla Fortezza dello Spirito, e vorrei recitare dei passi da un certo libro di metallurgia: \"The Stresses of Iron\". Una copia di questo libro dovrebbe essere nella Royal Library, dentro Stormwind Keep. Puoi recuperarmela? Se lo fai, che le benedizioni della Luce siano con te!$B$BLa Royal Library è molto grande, ma il bibliotecario capo, Milton Sheaf, conosce ogni scaffale come se fosse suo figlio. Parla con lui, il libro te lo troverà.",
  obj = "Va' alla Royal Library, dentro Stormwind Keep, e parla con Milton Sheaf. Può trovarti il libro di metallurgia che serve a Brother Kristoff per il suo discorso.",
  reward = "Metallurgia? Ah sì, abbiamo molti libri sull'argomento, e siamo felici di aiutare Brother Kristoff con il suo discorso! Ora... qual era il libro preciso che serviva al buon fratello?",
  en_title = "Speaking of Fortitude",
  en_obj = "Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf.  He can find for you the book on metallurgy that Brother Kristoff needs for his speech.",
}
T[344] = {
  title = "Brother Paxton",
  desc = "The Stresses of Iron? Sì, il libro lo conosco. Davvero buono, scritto dal minatore nano Margulf Blaggon qualche decennio fa. Ha passato quasi tutto il suo tempo nelle profondità delle montagne di Khaz Modan, a scavare minerale. Tipo sveglio!$B$BMa dov'ero rimasto? Ah sì, The Stresses of Iron! Temo che il libro sia stato spostato alla Northshire Abbey. Il custode della biblioteca dell'abbazia, Brother Paxton, voleva farne una copia per i suoi scaffali.$B$BMa è successo mesi fa. Mi chiedo perché ci stia mettendo tanto...",
  obj = "Parla con Brother Paxton, alla Northshire Abbey.",
  reward = "Il signor Sheaf si chiede dove sia finito il suo libro? Be', è un po' imbarazzante. Il libro ce l'ho io, ma sto ancora facendo la mia copia e non sono proprio pronto a restituire l'originale!",
  en_title = "Brother Paxton",
  en_obj = "Speak with Brother Paxton in the Northshire Abbey.",
}
T[345] = {
  title = "Rifornimenti di inchiostro",
  desc = "Volevo finire la mia copia di The Stresses of Iron, ma...$B$BBe', vedi, l'inchiostro per i libri che copio me lo faccio da solo. È una mia ricetta: non cola e non sbava, e asciuga molto in fretta. Purtroppo asciuga troppo in fretta! L'ultima partita si è seccata prima che finissi la copiatura, e non ho avuto modo di farne dell'altro!$B$BPer farne ancora mi serve del Rethban Iron Ore dalle Redridge Mountains. Il mio fornitore abituale è Foreman Oslow, a Lakeshire.",
  obj = "Parla con Foreman Oslow, a Lakeshire, e chiedigli del Rethban Iron Ore.",
  reward = "Ti serve cosa?? Forse non l'hai notato, ma siamo occupati a rinforzare le difese di Lakeshire e a riparare i danni dei recenti attacchi degli orchi. Se ti serve del Rethban Iron Ore, dovrai procurartelo da $Gsolo:sola;!",
  en_title = "Ink Supplies",
  en_obj = "Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.",
}
T[346] = {
  title = "Torna da Kristoff",
  desc = "Ora che ho finito di copiare il libro, ecco l'originale di The Stresses of Iron. Grazie della pazienza e, se vedi Milton, digli per favore che mi dispiace per il lungo ritardo.",
  obj = "Torna da Brother Kristoff, a Cathedral Square. Dagli il libro The Stresses of Iron.",
  progress = "Sei $Griuscito:riuscita; a trovare il libro?",
  reward = "È proprio quello! Grazie, $N. Che la Luce splenda luminosa sul tuo corpo e sul tuo spirito!",
  en_title = "Return to Kristoff",
  en_obj = "Return to Brother Kristoff in the Cathedral Square.  Give him the book The Stresses of Iron.",
}
T[347] = {
  title = "Rethban Ore",
  desc = "Il Rethban Ore prende il nome dall'uomo che per primo lo trovò, Bart Rethban. Fuso non è resistente come il ferro, ma il minerale ha un colore scuro e opaco che certi scrivani usano nelle loro tinture. Si trova nelle Rethban Caverns, a nord di qui.$B$BDi solito ne abbiamo un po' in magazzino, ma siamo troppo occupati a prepararci agli attacchi degli orchi per raccoglierne. E poi... adesso nelle Rethban Caverns vivono i Redridge Gnoll, e sono i loro Drudger a raccogliere il minerale.$B$BQuindi, se te ne serve, dovrai procurartelo da $Gsolo:sola;.",
  obj = "Raccogli 5 carichi di Rethban Ore e portali a Brother Paxton, alla Northshire Library.",
  progress = "Ce l'hai il Rethban Ore?",
  reward = "Oh, splendido! Posso usare questo minerale per fare la mia tintura, e poi finire di copiare The Stresses of Iron.$B$BGrazie, $N!",
  en_title = "Rethban Ore",
  en_obj = "Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.",
}
T[348] = {
  title = "Febbre di Stranglethorn",
  desc = "Sto male... così... tanto m-m-male...$B$B...ho preso la Febbre di Stranglethorn... virus m-m-mortale...$B$B...l'unica cura... è... è... mangiare il cuore di M-m-m-m-mokk the Savage... sfuggente bestia bianca...$B$B...Witch Doctor Unbagwa... l'unico che può e-e-evocarlo...$B$B...cerca Unbagwa nella grotta nascosta sul capo meridionale...$B$B...fa' presto... sto morendo... morendo...",
  obj = "Trova Witch Doctor Unbagwa e fagli evocare Mokk the Savage. Porta l'Heart of Mokk a Fin Fizracket.",
  progress = "...mamma?$B$B...che freddo...$B$B...sto andando nel Twisting Nether... t-t-t-tienimi, mamma...",
  reward = "...sento tornare le forze...$B$BDove sono? A Booty Bay? Oh, cielo! Ho fatto un sogno stranissimo...$B$B...la debolezza non mi ha ancora lasciato del tutto...",
  en_title = "Stranglethorn Fever",
  en_obj = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.",
}
T[349] = {
  title = "Febbre di Stranglethorn",
  desc = "Testo temporaneo 02 — descrizione.",
  obj = "Testo temporaneo 02 — registro.",
  progress = "Witch Doctor Unbagwa sapere cosa piacere a Mokk the Savage. Sì, sì!$B$BIo parlare con spiriti e fare venire lui, io fare.$B$BMa anche altre bestie-gorilla piacere parlare con spiriti. Tu proteggere Witch Doctor Unbagwa e io fare venire lui da te.$B$BWitch Doctor Unbagwa volere prima qualcosa. Tu portare 10 Gorilla Fang e io cominciare parlare con spiriti!",
  reward = "A Witch Doctor Unbagwa piacere Gorilla Fang! Per te io parlare con spiriti. Fare venire Mokk the Savage.$B$BMa tu proteggere Witch Doctor Unbagwa da altre bestie-gorilla, o niente Mokk per te!",
  en_title = "Stranglethorn Fever",
  en_obj = "Speak with Witch Doctor Unbagwa.",
}
T[350] = {
  title = "Rivolgiti a un vecchio amico",
  desc = "Che Marzon sia in contatto con un membro dei Defias e abbia legami con Lescovar...$B$BAvendo ucciso VanCleef e Thredd, sarà difficile vedere Lescovar portato davvero davanti alla giustizia: le tue prove non valgono niente senza le loro testimonianze. E questo senza nemmeno considerare che Lescovar è un nobile e ha ottimi agganci. Di fatto lo mette al di sopra della legge.$B$BTi servirà altro aiuto. Mi ripugna farlo, ma conosco qualcuno che ci darà una mano. Trias lo trovi nel Trade District della città.",
  obj = "Parla con Elling Trias, a Stormwind.",
  reward = "Stai scherzando? Shaw vuole di nuovo il mio aiuto? Ma che faccia tosta...$B$BLa Defias Brotherhood, dici? Be', sei proprio $Gportatore:portatrice; di notizie meravigliose, eh? Adesso mi dirai che Deathwing è ancora vivo e sta attaccando la città.$B$BVa bene, raccontami tutto dall'inizio. E non tralasciare niente che ti sembri poco importante. Devo sapere tutto.",
  en_title = "Look to an Old Friend",
  en_obj = "Speak to Elling Trias in Stormwind.",
}
T[353] = {
  title = "La consegna per Stormpike",
  desc = "Gli Stormpike sono un rispettato clan di nani, noti per i loro gusti raffinati ed esigenti. Non c'è da stupirsi, quindi, che Gringer Stormpike, un Mountaineer di Ironforge, mi abbia commissionato la fabbricazione di un'arma.$B$BL'arma è finita, ma... il Mountaineer Stormpike è lontano, nella remota Loch Modan. Se hai intenzione di viaggiare verso nord, puoi consegnargli questo pacco?$B$BL'ultimo messaggio del Mountaineer Stormpike diceva che è di stanza alla torre di guardia settentrionale di Loch Modan.",
  obj = "Consegna il Package for Stormpike al Mountaineer Stormpike a Loch Modan.",
  progress = "Vieni da Stormwind fin qui? Sento che laggiù nelle terre degli umani le cose si fanno rischiose, con briganti e orchi in giro. Un posto perfetto perché un $C dimostri il proprio valore!",
  reward = "Aha! Quindi Grimand ha finalmente finito la mia ascia! Non vedo l'ora di provarla contro qualche trogg e qualche kobold!$B$BGrazie mille, $N. C'era molta strada da fare per questa consegna. Ecco qualche moneta per il disturbo.",
  en_title = "Stormpike's Delivery",
  en_obj = "Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan.",
}
T[354] = {
  title = "Lutti in famiglia",
  desc = "La famiglia Agamand era la più prospera di Tirisfal Glades. Io lavoravo nei loro mulini... prima della Piaga.$B$BQuando arrivò per la prima volta la Scourge, gli Agamand fortificarono la loro casa e convinsero i loro dipendenti a restare e aiutarli a difenderla. Fummo degli sciocchi, ma almeno fummo sciocchi leali.$B$BGli Agamand, nel loro orgoglio, ci condannarono alla non morte. E ora sono servitori della Scourge!$B$BServi i Forsaken sconfiggendo gli Agamand caduti preda della Piaga. Servi me portandomi i loro resti.",
  obj = "Porta Gregor's Remains, Nissa's Remains e Thurman's Remains a Coleman Farthing a Brill.",
  progress = "Hai i resti degli Agamand? Quelle bestie maledette sono state finalmente distrutte?",
  reward = "La vendetta ha un sapore dolce, non trovi? Quando hai distrutto gli Agamand, hai notato in loro qualche traccia di volontà? Spero di sì. Spero che abbiano conosciuto la paura prima di essere ridotti al nulla.$B$BÈ una speranza folle, lo so. Ma è una speranza che coltivo comunque.",
  en_title = "Deaths in the Family",
  en_obj = "Bring Gregor's Remains, Nissa's Remains and Thurman's Remains to Coleman Farthing in Brill.",
}
T[355] = {
  title = "Parla con Sevren",
  desc = "Mi hai consegnato i resti degli Agamand e hai saziato la mia sete di vendetta. Ma gli Agamand Mills nascondono una minaccia per tutti i Reietti, non solo per me.$B$BHo parlato al Magistrate Sevren delle tue imprese contro gli Agamand, e desidera parlare con te.",
  obj = "Parla con il Magistrate Sevren a Brill.",
  reward = "Coleman parla bene di te, $N, e racconta delle tue incursioni riuscite negli Agamand Mills.$B$BI Reietti hanno ancora bisogno dei tuoi talenti...",
  en_title = "Speak with Sevren",
  en_obj = "Speak with Magistrate Sevren in Brill.",
}
T[356] = {
  title = "Pattuglia della retroguardia",
  desc = "I difensori di The Bulwark, che protegge Tirisfal dalle Plaguelands, sono in costante allerta. Ma a volte qualche Scourge riesce a sgusciare oltre le loro linee.$B$BIl nostro successo a The Bulwark dipende da una battaglia su un solo fronte: non possiamo permettere un attacco alle spalle, né che la linea di rifornimento dei nostri difensori venga tagliata.$B$BAiuta The Bulwark. Pattuglia verso est e uccidi ogni Scourge che trovi. Impegnati in particolare al Balnir Farmstead, a est: è diventato un rifugio per gli Scourge intrusi.",
  obj = "Uccidi 8 Bleeding Horror e 8 Wandering Spirit, poi riferisci a Linnea al suo accampamento.",
  progress = "Hai un resoconto della tua pattuglia?",
  reward = "Molto bene. I tuoi sforzi aiutano a tenere a bada gli Scourge. Invierò un encomio al mio superiore, l'Executor Zygand.",
  en_title = "Rear Guard Patrol",
  en_obj = "Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp.",
}
T[357] = {
  title = "L'identità del lich",
  desc = "C'è un lich che vive sull'isola nel Brightwater Lake, a nord. Sebbene sia un Rinnegato dotato di libero arbitrio, crede che tutti gli altri non morti siano schiavi della Scourge e fa attaccare dai suoi servitori chiunque si avvicini.$B$BMa poiché è un Rinnegato, la Regina lo vorrà. E se è esperto di Negromanzia, le sue conoscenze ci sarebbero... assai utili.$B$BPer scoprire la sua identità e i suoi talenti devo vedere il suo libro degli incantesimi. Infiltrati nel suo accampamento, procuralo e torna da me.",
  obj = "Porta il Lich's Spellbook a Bethor Iceshard a Undercity.",
  progress = "$N, hai preso il libro?",
  reward = "Molto bene, $N. Studierò questo libro e stabilirò l'identità di quel lich. Hai servito bene la tua Regina.$B$B<Bethor apre il libro e fissa intensamente le sue pagine luminose...>$B$BSorprendente! Il libro che hai recuperato appartiene a nientemeno che Gunther Arcanus!$B$BGunther era un abile Negromante in vita; io e lui eravamo amici e compagni d'armi, prima della Piaga. E a giudicare dal suo libro è diventato ancora più potente nella morte.$B$BLe sue capacità sarebbero un grande vantaggio per noi.",
  en_title = "The Lich's Identity",
  en_obj = "Bring the Lich's Spellbook to Bethor Iceshard in the Undercity.",
}
T[358] = {
  title = "Predatori di tombe",
  desc = "Le Mass Graves, a sudovest di Garren's Haunt, a nord, furono scavate per accogliere l'... impressionante... numero di morti che Tirisfal subì quando arrivò la Piaga.$B$BI corpi in queste fosse sono stati finora risparmiati da una non-morte, ma ora gli Scourge mandano i Rot Hide Gnoll a raccogliere i cadaveri per rinforzare i loro eserciti. Non possiamo permetterlo!$B$BIl tuo compito è duplice: uccidi i Rot Hide alle Mass Graves e a Garren's Haunt, e prendi loro l'Embalming Ichor che li tiene in vita.",
  obj = "Uccidi i Rot Hide Graverobber e i Rot Hide Mongrel.$B$BPorta 8 Embalming Ichor al Magistrate Sevren a Brill.",
  progress = "Hai finito il tuo compito? Hai distrutto quelle bestie e le hai prosciugate del loro ichor?",
  reward = "Ottimo lavoro, $N. Gli Scourge si sbagliano se pensano di poter usare quei cadaveri contro di noi, e il fluido che hai raccolto dagli schiavi Rot Hide sarà studiato dai nostri Apothecary. Potrebbe celare segreti da usare contro di loro.$B$BCome ho detto, ben fatto. Ma la nostra lotta continua, e il conflitto ti offrirà certamente altre occasioni per dimostrare il tuo valore ai Reietti.",
  en_title = "Graverobbers",
  en_obj = "Kill Rot Hide Graverobbers and Rot Hide Mongrels.  $B$BBring 8 Embalming Ichors to Magistrate Sevren in Brill.",
}
T[359] = {
  title = "Doveri dei Reietti",
  desc = "Mi serve un rapporto aggiornato dal nostro avamposto dei Deathguard a est.$B$BDevo sapere se altre forze degli Scourge sono sfuggite a The Bulwark e sono entrate a Tirisfal. La nostra vigilanza sul confine con le Plaguelands deve restare salda: non possiamo permettere agli Scourge di consolidarsi qui!$B$BViaggia verso sud lungo la strada, poi a est al bivio fino all'avamposto. Parla con la Deathguard Linnea. Lei ha le informazioni che mi servono.",
  obj = "Parla con la Deathguard Linnea.",
  reward = "Il Magistrate Sevren vuole un rapporto? Molto bene: i difensori di The Bulwark tengono a bada la maggior parte degli Scourge, ma ogni tanto qualcuno riesce a passare.$B$BAbbiamo visto sporadica attività degli Scourge a est di questo avamposto, con una concentrazione intorno al Balnir Farmstead.",
  en_title = "Forsaken Duties",
  en_obj = "Speak with Deathguard Linnea.",
}
T[360] = {
  title = "Ritorno dal Magistrate",
  desc = "Ora torna dal Magistrate Sevren con le informazioni che ti ho dato. Le vorrà il prima possibile, quindi sii rapido.$B$BE se incontri degli Scourge sulla via del ritorno, abbattili: non possiamo lasciarli vagare indisturbati per le nostre terre.",
  obj = "Torna dal Magistrate Sevren a Brill.",
  reward = "È preoccupante sapere che gli Scourge sfuggono a The Bulwark. Il Lich King e i suoi servitori non danno tregua ai loro assalti.$B$BMa non cederemo. Non ci prenderà di nuovo!",
  en_title = "Return to the Magistrate",
  en_obj = "Return to Magistrate Sevren in Brill.",
}
T[361] = {
  title = "Una lettera non consegnata",
  desc = "Questa è una lettera scritta da Thurman, il figlio maggiore di Gregor Agamand. È indirizzata a una certa Yvette Farthing, ma non sembra essere mai arrivata a destinazione...",
  obj = "Trova Yvette Farthing e consegnale la lettera di Thurman Agamand.",
  progress = "Sì?",
  reward = "Oh... il mio povero Thurman! Lo implorai di lasciare Agamand Mills con me e mio padre, ma la lealtà verso la sua famiglia era troppo forte! E io lo sapevo! Lo sapevo che Brand gli voleva del male!! Oh, maledetta questa Piaga, e maledetti gli Scourge!$B$B<Il volto di Yvette si distende e si fa freddo.>$B$BMa i rimpianti sono per i deboli. Come Reietta, ho nuovi obiettivi e l'amore non è tra questi. Ti ringrazio per aver consegnato questa lettera, perché mi chiedevo che ne fosse stato del mio antico amore.$B$BMa quella vita è finita. Per sempre.",
  en_title = "A Letter Undelivered",
  en_obj = "Find Yvette Farthing, and deliver to her the letter from Thurman Agamand.",
}
T[362] = {
  title = "I Mulini infestati",
  desc = "Devlin Agamand era il più giovane dei due figli della famiglia Agamand, e in vita i due non potevano essere più diversi. Thurman era alto e gentile, mentre il fratello minore era debole e dalla lingua tagliente.$B$BQuando Agamand Mills cadde preda della Piaga, non mi stupii di sentire che Devlin fu tra i primi a cedere. Il suo folle farneticare si sente ancora vicino alla strada che porta agli Agamand Mills.$B$BSto raccogliendo i resti degli Agamand, e voglio il povero Devlin. Trovalo, distruggilo e portami le sue ossa.",
  obj = "Uccidi Devlin Agamand e porta i Devlin's Remains a Coleman Farthing a Brill.",
  progress = "Hai trovato Devlin?",
  reward = "Grazie. Le ossa di Devlin staranno benissimo sul mio camino.$B$BSe il mio cuore gelido riesce a trovare calore, è nel sapere che gli Agamand sono distrutti. Hanno fallito con me e con la mia famiglia quando giunse la Piaga: ora giuro che schiaccerò i loro resti sotto il mio tallone!",
  en_title = "The Haunted Mills",
  en_obj = "Slay Devlin Agamand, and bring Devlin's Remains to Coleman Farthing in Brill.",
}
T[363] = {
  title = "Un brusco risveglio",
  desc = "Era ora che ti svegliassi. Eravamo pronti a gettarti nel fuoco insieme agli altri, ma a quanto pare ce l'hai fatta.$B$BIo sono Mordo, il custode della cripta di Deathknell. E tu non sei più schiav$Go:a; del Lich King.$B$BParla con lo Shadow Priest Sarvis nella cappella ai piedi della collina: ti dirà di più su ciò che devi sapere.",
  obj = "Parla con lo Shadow Priest Sarvis.",
  reward = "Un altro dei morti viventi, eh? Dev'essere stato un bello shock svegliarsi nella cripta con solo il gelo e Mordo ad accoglierti...$B$BVedo la confusione sul tuo volto. Lascia che ti spieghi la nostra... situazione.$B$BSiamo stati liberati dal controllo del Lich King dalla nostra nuova guida, Lady Sylvanas. La Dark Lady ci guida nella nostra guerra contro gli odiati Scourge e contro i superstiti dell'umanità che ci braccano a ogni passo.",
  en_title = "Rude Awakening",
  en_obj = "Speak with Shadow Priest Sarvis.",
}
T[364] = {
  title = "I Senza Mente",
  desc = "Noi Reietti siamo in guerra contro l'esercito degli Scourge del Lich King: armate di non morti risvegliate dalla negromanzia, immonde bestie del nord e spettri tormentati.$B$BLa parte settentrionale del villaggio è stata invasa dai Mindless Ones, e vanno distrutti. Distruggili, non mostrare pietà, per quanto siano stati un tempo nostri fratelli e sorelle. I Caduti non sono altro che schiavi del Lich King.",
  obj = "Lo Shadow Priest Sarvis vuole che tu uccida 8 Mindless Zombie e 8 Wretched Zombie.",
  progress = "In questa nuova vita non andrai lontano se non riesci nemmeno a uccidere il più debole degli zombie, $n. Non tornare finché non avrai successi da riferire.",
  reward = "È un peccato che gli Scourge non possano essere condotti dalla nostra parte: il loro gran numero sarebbe utile nelle battaglie che ci attendono.$B$BMa non si uniranno a noi, quindi non abbiamo altra scelta che distruggerli.",
  en_title = "The Mindless Ones",
  en_obj = "Shadow Priest Sarvis wants you to kill 8 Mindless Zombies and 8 Wretched Zombies.",
}
T[365] = {
  title = "Campi del Dolore",
  desc = "Cosa abbiamo qui? Sembri un$Go:a; giovane $c alle prime armi. Se speri di metterti alla prova davanti alla Dark Lady, devi imparare le vie dei Reietti.$B$BA ovest troverai una fattoria. Gli umani infestano la terra come muffa su un cadavere in putrefazione. E peggio ancora, la Scarlet Crusade pattuglia nei dintorni dalla sua torre. Dai una lezione a quella feccia e ruba 10 delle loro preziose zucche.$B$BQuando ne avrai 10, portale all'Apothecary Johaan a Brill.",
  obj = "Ruba 10 zucche dalla fattoria a ovest, appena a nord di Deathknell, e portale all'Apothecary Johaan a Brill.",
  progress = "La Deathguard Simmer mi ha fatto sapere che mi avresti procurato dei reagenti di cui ho tanto bisogno. Sei riuscit$Go:a; a raccogliere 10 zucche, $N?",
  reward = "Hai eseguito bene il tuo compito, giovane $C. Ti stai dimostrando una vera risorsa per l'esercito della Dark Lady.",
  en_title = "Fields of Grief",
  en_obj = "Steal 10 pumpkins from the farm to the west, just north of Deathknell and take them to Apothecary Johaan in Brill.",
}
T[366] = {
  title = "Restituisci il libro",
  desc = "Tanto tempo fa Gunther ed io, insieme al Necromancer ora al servizio degli Scourge Thule Ravenclaw, eravamo amici e studenti del Kirin Tor, una società di maghi a Dalaran.$B$BGunther ed io cademmo entrambi preda della Piaga, ma pensavo che lui fosse rimasto morto, o fosse stato risvegliato nei ranghi del Lich King. Fa piacere sapere che è libero.$B$BDobbiamo averlo con noi. Ho lanciato un incantesimo sul suo libro che, quando lo vedrà, gli mostrerà che anch'io sono libero dal Lich King. Dopo averlo saputo, spero che si unisca a noi.",
  obj = "Restituisci a Gunther il suo Spellbook, sull'isola di Gunther's Retreat.",
  progress = "I tuoi padroni sono sciocchi a mandarti qui, perché non sarò mai più $Guno schiavo:una schiava; degli Scourge!",
  reward = "Il mio libro?!? Dunque sei tu il ladro che lo ha rubato!$B$BMa... cos'è questo nuovo incantesimo... Bethor? È a Lordaeron?$B$BSe esiste ancora, forse è sfuggito anche lui alla presa del Lich King...",
  en_title = "Return the Book",
  en_obj = "Return Gunther's Spellbook to him, on the island of Gunther's Retreat.",
}
T[367] = {
  title = "Una nuova piaga",
  desc = "Lady Sylvanas ha chiamato a raccolta la Royal Apothecary Society. La Dark Lady crede che le nostre conoscenze, unite alla magia di recente scoperta, offriranno la chiave per la caduta di Arthas. Ci ha sfidati a creare una nuova piaga, più letale di qualsiasi morbo di Azeroth. Questa nuova malattia porterà alla rovina l'esercito degli Scourge di Arthas.$B$BI miei studi indicano che il sangue delle bestie potrebbe essere la chiave. Portami 5 fiale di sangue di darkhound, così potrò verificare la mia teoria.",
  obj = "L'Apothecary Johaan, nella città di Brill, vuole che tu raccolga 5 Vial of Darkhound Blood.",
  progress = "Hai già raccolto 5 fiale di sangue di darkhound, $N? Il tempo stringe!",
  reward = "Hai fatto bene, $N, e ti ringrazio per i tuoi sforzi.",
  en_title = "A New Plague",
  en_obj = "Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood.",
}
T[368] = {
  title = "Una nuova piaga",
  desc = "Mentre raccoglievi i campioni per me, i miei esperimenti mi hanno fatto capire che servono altri reagenti perché questa nuova malattia si diffonda a dovere. Avvelenare una vittima indifesa è un gioco da ragazzi. Appestare un intero mondo si rivela un po' più complicato.$B$BMi serviranno 5 Vile Fin Scale dai Murloc della zona. Troverai queste creature lungo la costa a nord o a ovest.",
  obj = "L'Apothecary Johaan della città di Brill ha bisogno di 5 Vile Fin Scale dai Murloc di Tirisfal Glades.",
  progress = "$N, sei riuscit$Go:a; a ottenere 5 Vile Fin Scale dai Murloc?",
  reward = "Le scaglie sono perfette, $N. Esattamente ciò che mi serviva per questo intruglio.",
  en_title = "A New Plague",
  en_obj = "Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades.",
}
T[369] = {
  title = "Una nuova piaga",
  desc = "Mentre eri via a raccogliere, ho scovato in uno dei miei tomi un vecchio testo che indica come un'antica piaga abbia spazzato via migliaia di vittime innocenti. In seguito si scoprì che l'agente letale della piaga si era conservato nel veleno dei Night Web Spider.$B$BPortami del veleno di un Vicious Night Web Spider per completare questo esperimento. Voglio vedere se l'elemento contagioso del veleno funzionerà con il mio nuovo intruglio. Si dice che i ragni si trovino nella parte orientale di Tirisfal Glades.",
  obj = "L'Apothecary Johaan, nella città di Brill, vuole che tu gli porti 4 campioni di veleno di Vicious Night Web Spider.",
  progress = "Hai già del veleno di un Vicious Night Web Spider, $N? È l'ultimo componente che mi serve per provare il mio esperimento.",
  reward = "Ah, questo veleno andrà alla perfezione, $N. Tutto il resto è già stato aggiunto al mio intruglio e fatto bollire. Finalmente sono pronto a provare questo nuovo agente letale!",
  en_title = "A New Plague",
  en_obj = "Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider.",
}
T[370] = {
  title = "In guerra con la Scarlet Crusade",
  desc = "I documenti strategici dell'Executor Arren contengono tutti i dettagli necessari per ripulire queste terre dall'infestazione umana. Secondo le informazioni, la Scarlet Crusade ha assegnato il Captain Perrine e una brigata alla torre in rovina a sudovest di Brill.$B$BUccidi Perrine insieme a 3 Zealot e 3 Missionary e torna a riferire.",
  obj = "L'Executor Zygand a Brill vuole che tu uccida il Captain Perrine, 3 Scarlet Zealot e 3 Scarlet Missionary.",
  progress = "Giovane $C, non dovresti sprecare tempo qui a Brill quando il tuo popolo ha bisogno di te a combattere per la sua causa. Ora imbraccia le armi e viaggia a sudovest, fino alla torre in rovina, e uccidi il Captain Perrine insieme a 3 Scarlet Zealot e 3 Scarlet Missionary. Condurremo la Scarlet Crusade come bestiame verso la sua rovina.",
  reward = "La morte del Captain Perrine renderà senza dubbio felice la Dark Lady. Hai compiuto bene il tuo dovere, $C.",
  en_title = "At War With The Scarlet Crusade",
  en_obj = "Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries.",
}
T[371] = {
  title = "In guerra con la Scarlet Crusade",
  desc = "Siamo ancora in guerra e la Scarlet Crusade diventa sempre più forte. Il rapporto che mi ha inviato Executor Arren indica che i Crociati Scarlatti hanno compiuto razzie dalla torre in rovina nel sud-est di Tirisfal, vicino a Balnir Farmstead, sotto il comando di Captain Vachon.$B$BUccidi Vachon insieme a 5 Scarlet Friar. Dovrebbe essere un colpo devastante per la Crusade!",
  obj = "Executor Zygand a Brill ti ha incaricato di uccidere Captain Vachon e 5 Scarlet Friar.",
  progress = "Vedo che sei tornato, ma il tuo compito non è concluso. Forse non ti dispiace che dei semplici umani interferiscano con il piano della Dark Lady? Oppure saprai ascoltare il richiamo del dovere e uccidere Captain Vachon e la sua banda di Scarlet Friar!",
  reward = "La morte di Captain Vachon rallenterà parecchio l'avanzata della Scarlet Crusade a Tirisfal. Ma altre minacce incombono.",
  en_title = "At War With The Scarlet Crusade",
  en_obj = "Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars.",
}
T[372] = {
  title = "In guerra con la Scarlet Crusade",
  desc = "I Crociati Scarlatti hanno compiuto razzie dalla torre in rovina nel nord di Tirisfal, oltre Faol's Rest. Secondo le nostre informazioni, uno spietato comandante di nome Captain Melrache guida questa malvagia masnada.$B$BOra ti affido una missione speciale e pericolosa. Uccidi Melrache e le sue due guardie del corpo, in nome della Dark Lady.",
  obj = "Executor Zygand, nella città di Brill, vuole che tu assassini Captain Melrache e le sue due guardie del corpo.",
  progress = "Non hai ancora compiuto il tuo dovere, $c. Non possiamo sperare di portare a termine il piano della Dark Lady con la Scarlet Crusade che tormenta i nostri soldati. Portali alla morte e compi il tuo dovere verso Sylvanas!",
  reward = "Hai fatto un lavoro eccellente, $C. Con combattenti spietati come te che conquistano in nome dei Forsaken, la nostra razza è un passo più vicina a sconfiggere Arthas una volta per tutte. Ho una buona sensazione su di te, compagno.",
  en_title = "At War With The Scarlet Crusade",
  en_obj = "Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.",
}
T[373] = {
  title = "La lettera mai spedita",
  desc = "Frugando addosso a Edwin VanCleef, tra le altre cose scopri una lettera mai spedita. È indirizzata a Baros Alexston, il City Architect di Stormwind, City Hall, Cathedral Square.$B$BSembra scritta e sigillata di recente.",
  obj = "Consegna la Letter to the City Architect a Baros Alexston, a Stormwind.",
  progress = "Sì? C'è qualcosa in cui posso aiutarti?",
  reward = "Edwin VanCleef, dici? Mi sarei aspettato più facilmente una lettera da mia nonna morta... Quindi l'hai ucciso? Perdonami se lo dico, ma sono un po' sorpreso. Da giovane era un combattente senza pari. Vediamo cosa sente il bisogno di scrivermi dopo tutti questi anni.$B$B<Baros scorre la lettera.>$B$BEdwin... Vedo che gli anni non ti hanno cambiato di una virgola, idealista come sempre, e romantico. Non gli importa chi fa soffrire, $N. La vendetta lo ha divorato. Ma poi, non sono sicuro di potergliene fare una colpa.",
  en_title = "The Unsent Letter",
  en_obj = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.",
}
T[374] = {
  title = "Prova della morte",
  desc = "Executor Zygand mi dice che sei andato in giro a uccidere Crociati Scarlatti. Tirisfal Glades ne è infestata.$B$BVarimathras, luogotenente della Dark Lady, si sta occupando personalmente di cancellare dall'esistenza la feccia di Azeroth, la razza umana. Qui a Tirisfal Glades affrontiamo una genia di umani particolarmente fastidiosa: la Scarlet Crusade.$B$BAvventurati e porta l'offensiva alla Scarlet Crusade, $c. Portami 10 Scarlet Insignia Ring come prova della tua lealtà a Varimathras e alla Dark Lady.",
  obj = "Porta 10 Scarlet Insignia Ring a Deathguard Burgess a Brill.",
  progress = "Hai già raccolto 10 Scarlet Insignia Ring, $C?",
  reward = "Varimathras sarebbe orgoglioso. Servi bene i tuoi capi, $C.",
  en_title = "Proof of Demise",
  en_obj = "Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.",
}
T[375] = {
  title = "Il gelo della morte",
  desc = "Fa così freddo, ormai. La Piaga della Non Morte mi striscia nelle vene come un serpente di ghiaccio. Lo Stato Privo di Mente sarà presto su di me. Ma nessun destino maledetto mi impedirà di servire la nostra Dark Lady. Quando giunse la chiamata, cucii sacchi mortuari per i soldati caduti del possente esercito di Sylvanas.$B$BOra le mie mani tremano per il gelo. Se mi portassi cinque Duskbat Pelt e del Coarse Thread potrei cucirmi una coperta. Aiutami, $N, così che io possa continuare a servire la causa.",
  obj = "Porta cinque Duskbat Pelt e del Coarse Thread a Gretchen Dedmar a Brill.",
  progress = "Hai già cinque Duskbat Pelt e del Coarse Thread, $N?",
  reward = "Apprezzo i tuoi sforzi, $N. Possa Sylvanas riconoscere un giorno il tuo coraggio. . . .",
  en_title = "The Chill of Death",
  en_obj = "Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill.",
}
T[376] = {
  title = "I Dannati",
  desc = "I miei compiti comprendono curare i nostri guerrieri feriti, confezionare armature e vesti e assistere Shadow Priest Sarvis in qualsiasi altra cosa gli serva.$B$BDa come stanno le cose, sarai arruolato anche tu al suo servizio... a dare la caccia ai Mindless One, se conosco la sua mente. Beh, se vuoi restare tutto intero - e non ho dubbi che lo voglia - forse posso aiutarti. Sto finendo le zampe e le ali e, se me ne porti un po', troverò un'armatura per te. A sud troverai un buon numero di lupi e pipistrelli.",
  obj = "Novice Elreth ha bisogno di 6 Scavenger Paw e 6 Duskbat Wing.",
  progress = "Cerca di restare illeso finché non ti procuro un'armatura.",
  reward = "Grazie, $N. Questa armatura dovrebbe esserti d'aiuto.$B$BSperiamo ti serva più di quanto sia servita a chi la indossava prima di te...",
  en_title = "The Damned",
  en_obj = "Novice Elreth requires 6 Scavenger Paws and 6 Duskbat Wings.",
}
T[377] = {
  title = "Delitto e castigo",
  desc = "Come se trascurare gli abitanti di Duskwood non bastasse, ora l'House of Nobles sputa in faccia al Darkshire Council con la decisione di imprigionare Dextren Ward a Stormwind invece di decapitare quel criminale, come vuole la sentenza di Lord Ebonlocke.$B$BWard è stato colto a vendere a Morbent Fel i cadaveri del cimitero, un crimine punibile con la morte. Eppure Stormwind lo rivendica come proprio prigioniero.$B$BAssassina Ward nello Stormwind Stockade, portami la sua mano, e ti ricompenserò.",
  obj = "Councilman Millstipe, di Darkshire, vuole che gli porti la mano di Dextren Ward.",
  progress = "Finché a un profanatore di morti come Dextren Ward è concesso vivere, la giustizia resta tradita. Torna da me quando la condanna a morte di Lord Ebonlocke sarà eseguita su quel profanatore di Ward. Daremo alle famiglie dei morti la pace che meritano e, meglio ancora, manderemo un messaggio chiaro all'House of Nobles di Stormwind.",
  reward = "Così Dextren Ward ha finalmente pagato per i suoi crimini contro l'umanità? Ce ne siamo liberati, di quella feccia, dico io. E complimenti a te, $Gamico mio:amica mia;! Non solo hai dato alle famiglie dei morti la serenità che meritano, ma hai mandato un messaggio pungente a quei burocrati corrotti dell'House of Nobles. Stormwind deve farsi carico dei bisogni della gente di Duskwood, o ci libereremo dalla loro tirannia.",
  en_title = "Crime and Punishment",
  en_obj = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.",
}
T[378] = {
  title = "La furia scava a fondo",
  desc = "Hai dimostrato la tua lealtà a King Magni, $C. E il tuo odio per la feccia dei Dark Iron è grande quanto il mio.$B$BC'è un compito che vorrei portare a termine io stesso, ma l'onore mi lega a restare con Longbraid. Roggo però ha raccolto informazioni che provano che Kam Deepfury fu tra i cospiratori dell'attacco al Thandol Span. Fu per i piani di Deepfury che Longbraid perse i suoi cari.$B$BDeepfury è trattenuto per ragioni politiche nello Stormwind Stockade. Lo voglio morto, $N. Per Longbraid! Portami la sua testa!",
  obj = "Motley Garmason vuole che la testa di Kam Deepfury gli sia portata a Dun Modr.",
  progress = "Non lascerò che la sciocca burocrazia umana si intrometta nelle questioni dei nani, $N. Kam Deepfury è un cospiratore accertato dell'attacco al Thandol Span. La brava gente di King Magni ha perso la vita per l'inganno di Deepfury. Gli umani si accontenteranno anche di lasciar marcire Deepfury nello Stockade, ma io non dormirò sonni tranquilli finché Deepfury non sarà ucciso.",
  reward = "Così Kam Deepfury ha finalmente provato cosa vuol dire finire nelle mani della Morte? Bene. Se lo merita, quella feccia codarda dei Dark Iron. Hai fatto bene, $C. Le vittime dell'attacco al Thandol Span erano solo vittime in un mondo lacerato da guerra e disordini. Le loro famiglie avranno la pace di sapere che Deepfury ha avuto la punizione che meritava. La morte del fratello di Longbraid è stata vendicata.",
  en_title = "The Fury Runs Deep",
  en_obj = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.",
}
T[380] = {
  title = "Night Web's Hollow",
  desc = "Una delle nostre più grandi difficoltà è procurarci le risorse naturali di cui abbiamo bisogno per sopravvivere. L'oro scarseggiava anche al culmine del potere dell'Alleanza.$B$BA nordovest c'è una miniera d'oro invasa dai ragni. Ci serve l'oro della miniera, ma non possiamo certo estrarlo finché i ragni ci strisciano dentro. Ho pochi uomini da dedicare al compito, quindi dovremo procedere a poco a poco.$B$BVai lassù e vedi cosa puoi fare per noi, $n.",
  obj = "Executor Arren vuole che tu uccida 10 Young Night Web Spider e 8 Night Web Spider.",
  progress = "Fai attenzione al veleno dei ragni, $N. Se senti un bruciore acuto, fallo controllare.",
  reward = "Hmm, beh, è un inizio. Ci vorranno settimane o mesi per ripulire del tutto l'infestazione. Dopodiché dovremo scendere laggiù con delle torce per bruciare le ragnatele.$B$BHai assolto bene il tuo dovere, $N, sono certo di poter trovare qualcos'altro da farti fare.",
  en_title = "Night Web's Hollow",
  en_obj = "Executor Arren wants you to kill 10 Young Night Web Spiders and 8 Night Web Spiders.",
}
T[381] = {
  title = "La Scarlet Crusade",
  desc = "Sarai felice di sapere che sembra stiamo facendo progressi nella miniera, in non piccola parte grazie ai tuoi sforzi. Ora possiamo rivolgere lo sguardo ad altre preoccupazioni.$B$BI miei esploratori riferiscono che un distaccamento della Scarlet Crusade sta allestendo un campo a sudest di qui. La Scarlet Crusade è un'organizzazione disprezzabile che ci dà la caccia, e non si fermerà finché ogni non morto - Scourge del Lich King o no - non sarà distrutto. Dobbiamo colpire per primi!$B$BStai attento, il loro empio zelo li rende avversari pericolosi.",
  obj = "Porta a Executor Arren 12 Scarlet Armband prese a Scarlet Convert e Scarlet Initiate.",
  progress = "Quegli sciocchi... Si mandano allegramente da soli alla tomba.",
  reward = "Se solo dessero ascolto alla ragione, eh, $N? Forse potremmo farli sedere a un civile confronto... ah!$B$BSciocchi accecati dalla Luce.",
  en_title = "The Scarlet Crusade",
  en_obj = "Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates.",
}
T[382] = {
  title = "Il messaggero rosso",
  desc = "I rapporti dei miei superiori a Brill indicano che un agente della Scarlet Crusade è stato inviato dallo Scarlet Monastery qui a Deathknell. Secondo i rapporti, il messaggero porta con sé informazioni importanti. Non ho altri dettagli, ma qualunque cosa sia, dobbiamo averla!$B$BSei la persona più qualificata che ho da mandare, $n. Trova quel messaggero e portami tutte le informazioni che riesci a trovare.",
  obj = "Uccidi Meven Korgal, il messaggero, al campo dei Crociati, poi porta le informazioni che trovi a Executor Arren.",
  progress = "Come procede la tua missione, $N?",
  reward = "Hmm... Vediamo cos'hai portato...$B$B<Comincia a rovistare tra i documenti che hai recuperato.>$B$BQualche notizia sulle loro imprese contro di noi... Senza valore. Rapporti di ricognizione... Nuovi ordini: \"Continuare a rafforzare un campo vicino alla città in rovina...\" Niente che non sapessimo già... Ah, e questo? Una mappa delle disposizioni di alcuni dei loro comandanti e agenti sul campo! Possiamo usarla.",
  en_title = "The Red Messenger",
  en_obj = "Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.",
}
T[383] = {
  title = "Informazioni vitali",
  desc = "Questi devono essere portati al mio superiore, Executor Zygand, a Brill. Con queste informazioni potremo infliggere un colpo decisivo alla Scarlet Crusade. I tuoi servigi sono stati utili qui a Deathknell, ma mi serve qualcuno che consegni questo a Zygand, e credo che saprà trovarti un lavoro più adatto.$B$BPrendi la strada a nord uscendo da Deathknell. Poco dopo essere entrato a Tirisfal vera e propria, arriverai a un crocevia. Prendi la biforcazione a est e continua verso est. Lungo la strada passerai da Cold Hearth Manor.",
  obj = "Consegna gli Scarlet Crusade Documents a Executor Zygand a Brill.",
  progress = "Sì, cosa vuoi?",
  reward = "Sì, ottimo. Hai fatto bene a procurarti queste informazioni, $N. Hmm... i nomi degli ufficiali di Tirisfal Glades...$B$BImmagina che colpo potremmo infliggere al morale di quei maledetti fanatici se uccidessimo i loro capi in un solo, rapido attacco.",
  en_title = "Vital Intelligence",
  en_obj = "Deliver the Scarlet Crusade Documents to Executor Zygand in Brill.",
}
T[384] = {
  title = "Costine di cinghiale alla birra",
  desc = "Niente piace ai clienti della mia taverna quanto le Beer Basted Boar Ribs! L'unico problema è che il cacciatore di zona che mi portava le provviste si è arruolato nell'esercito del re per combattere sul fronte dell'Alleanza.$B$BForse puoi aiutarmi tu? Se mi porti sei costine di crag boar e una Rhapsody Malt dalla taverna, ti darò la ricetta di famiglia delle mie famose Beer Basted Boar Ribs, e in più un assaggio gratis! Il segreto è nel malto!",
  obj = "Ragnar Thunderbrew a Kharanos vuole 6 Crag Boar Ribs e un boccale di Rhapsody Malt.",
  progress = "Mi servono sei costine di crag boar e un boccale di Rhapsody Malt, $N.",
  reward = "Il malto è pronto, i cinghiali son stesi$Be prima che il resto sia fatto e detto$Bci toccherà lottare per il primo morso$Bdi queste gustose costine alla birra!",
  en_title = "Beer Basted Boar Ribs",
  en_obj = "Ragnar Thunderbrew in Kharanos wants 6 Crag Boar Ribs and a mug of Rhapsody Malt.",
}
T[385] = {
  title = "Caccia al crocolisco",
  desc = "Molti cacciatori vengono a Loch Modan per cacciare i nostri famosi coccodrilli. Ci sono sempre mercanti in cerca di pelli di crocolisco per vestiti o armature, e c'è anche chi apprezza il sapore della loro carne.$B$BNe facciamo un po' di commercio, ma non molto, perché i crocolischi sono feroci e si sono insediati sulle isole del Loch. Ma non lasciarti scoraggiare: lottare con le fauci di quelle bestie è un'esperienza unica.$B$BPensa che una volta...",
  obj = "Procura 5 pezzi di Crocolisk Meat e 6 Crocolisk Skins per Marek Ironheart alla Farstrider Lodge.",
  progress = "Ti ho raccontato di quella volta che per poco un coccodrillo non mi portava via la mano? Una brutta bestia, con denti come coltelli. Ma sono stato fortunato... Gli ho bloccato le fauci con il mio coltello. Dev'essere ancora qui da qualche parte...",
  reward = "Bene bene, questi che hai raccolto sono esemplari eccellenti, $N. Bei soldi per materiali di alta qualità, questo è certo.",
  en_title = "Crocolisk Hunting",
  en_obj = "Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge.",
}
T[386] = {
  title = "Chi la fa l'aspetti...",
  desc = "Targorr the Dread serviva sotto Gath'Ilzogg come boia supremo. I suoi metodi erano spietati, perfino per i sudici standard degli orchi. Uomini che si erano battuti con coraggio per difendere il Regno venivano torturati a suo capriccio. Ora è rinchiuso nello Stormwind Stockade, condannato a morte. Eppure qualcosa non torna. Uno dei nobili burocrati ha bloccato la sua esecuzione. Sono sicuro che sotto c'è un imbroglio.$B$BMetti fine a Targorr the Dread, $N. Va' allo Stockade e decapitalo, prima che l'inganno ci travolga.",
  obj = "Porta la testa di Targorr the Dread a Guard Berton, a Lakeshire.",
  progress = "Sei già $Gstato:stata; a Stormwind, allo Stockade? Temo che l'imbroglio che ha tenuto in vita Targorr the Dread così a lungo finirà per portargli la libertà. È stato condannato a morte, $N, non a fare da pedina politica al capriccio di un nobile.",
  reward = "Targorr the Dread ha finalmente incontrato il suo destino. Da parte mia sono contento di sapere che la bestia ora sa cosa vuol dire finire nella morsa spietata della Morte. Hai fatto bene, $N. A volte la giustizia più vera si trova solo fuori dal tribunale e oltre la vista appannata della politica.",
  en_title = "What Comes Around...",
  en_obj = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire.",
}
T[387] = {
  title = "Sedare la rivolta",
  desc = "La rivolta va sedata! Mi serve il tuo aiuto. Se si sparge la voce che la prigione è in mano ai detenuti, perdo il posto! Questo è un caso di imbroglio come pochi ne ho visti. Ma adesso quello che conta è piegare questi prigionieri, per la sicurezza di Stormwind.$B$BLa pena per l'insurrezione è la morte. Uccidi qualcuno di questi deviati! Dovrebbe bastare a riportare le cose sotto controllo.",
  obj = "Warden Thelwater, di Stormwind, vuole che tu uccida 10 Defias Prisoner, 8 Defias Convict e 8 Defias Insurgent nello Stockade.",
  progress = "Lo Stockade è ancora in mano loro! Bisogna far capire a questi ratti dei Defias che le loro azioni non saranno tollerate. Adesso torna laggiù e usa la forza!",
  reward = "I tuoi sforzi nello Stockade sono stati valorosi, $N. È evidente che il problema è più grande di noi due. Ma tu hai fatto bene, e di questo ti sono grato.",
  en_title = "Quell The Uprising",
  en_obj = "Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.",
}
T[388] = {
  title = "Il colore del sangue",
  desc = "L'amarezza mi scorre nelle vene come un fiume gelido. Mio nipote, Mac, era un bravo ragazzo. Aveva appena 14 anni. Quando l'esercito fu mandato al fronte, Mac prese le armi per difendere la città. Faceva la guardia nello Stockade, dove è rinchiusa la banda dei Defias. Mac rimproverò alcuni prigionieri perché strappavano le coperte di lana per farne sciarpe, il simbolo della loro banda. Per questo Mac fu pugnalato alle spalle.$B$BVoglio vendetta. Portami 10 delle loro preziose Wool Bandana. Sono del colore del sangue.",
  obj = "Nikova Raskol, di Stormwind, vuole che tu raccolga 10 Red Wool Bandana.",
  progress = "Vedo che sei $Gtornato:tornata;, $C. Hai già raccolto 10 Red Wool Bandana da quella feccia dei Defias nello Stockade?",
  reward = "Quindi queste bandane, luridi simboli di corruzione, sono ciò per cui il mio Mac è dovuto morire? Che spreco. Che sacrificio tragico.$B$BMa ahimè, non posso tornare al passato. Sappi solo, $N, che con quello che hai fatto hai reso giustizia alla mia famiglia.",
  en_title = "The Color of Blood",
  en_obj = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.",
}
T[389] = {
  title = "Bazil Thredd",
  desc = "VanCleef e io eravamo membri della Stonemasons Guild. Il nostro progetto principale era ricostruire Stormwind dopo la guerra.$B$BQuando avevamo finito il nostro lavoro, siamo stati truffati. I nobili si sono rifiutati di pagarci per l'opera. Ad alcuni degli Stonemason più anziani sono stati offerti incarichi di governo, ma VanCleef li ha rifiutati per lealtà verso tutti gli Stonemason. Ha guidato una rivolta e ha lasciato la città, giurando vendetta.$B$BIl suo luogotenente, Bazil Thredd, potrebbe sapere di più sui piani di VanCleef. È tenuto prigioniero nello Stockade.",
  obj = "Parla con Warden Thelwater, nello Stockade.",
  reward = "Che diamine vuoi, per la Luce? Non vedi che qui abbiamo una crisi?$B$BBazil Thredd?! Perché mai vorresti parlare con quel bastardo? E come faccio a sapere che non sei $Guno:una; dei suoi compari, $Gvenuto:venuta; quaggiù a dare una mano alla sua maledetta rivolta? Se non fossero aperte tutte quelle dannate celle, ti ci butterei dentro per un po'!",
  en_title = "Bazil Thredd",
  en_obj = "Speak with Warden Thelwater in the Stockade.",
}
T[391] = {
  title = "I tumulti nello Stockade",
  desc = "Mettiamo subito in chiaro una cosa, $N: non mi fido di te. Ma, stando così le cose, probabilmente non farai differenza.$B$BAllora si fa così: scendi laggiù e fatti la tua chiacchierata con Thredd. Se sei davvero dalla nostra parte, uccidilo e portami la sua testa a lavoro finito. E se si scopre che sei dalla sua parte, e non torni su... quando ti troveremo, morirai insieme al resto dei vermi.",
  obj = "Uccidi Bazil Thredd e riporta la sua testa a Warden Thelwater, allo Stockade.",
  progress = "O mi porti la testa di Thredd, o prendo la tua: intesi, $N?",
  reward = "Senza Thredd a guidarli, si spera che i tumulti siano più controllabili. Vedremo.$B$BDevo dire che, dopo mezz'ora, non mi aspettavo proprio che tornassi su, ma a quanto pare ti avevo giudicato male.$B$BImmagino, allora, che da lui non sia uscito molto di utile? Ma io so un paio di cose che potrebbero interessarti sulle attività di Thredd.",
  en_title = "The Stockade Riots",
  en_obj = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.",
}
T[392] = {
  title = "Il visitatore curioso",
  desc = "Nei primi anni di prigionia di Thredd non ha mai avuto visite. Immaginavo che non servisse più alla Brotherhood, e che quindi l'avessero abbandonato.$B$BPoi, qualche mese fa, è cambiato tutto: ha cominciato a ricevere visite regolari... una volta, forse due alla settimana. Era un uomo strano, di quelli silenziosi. Avevo i miei sospetti, ma i suoi documenti erano tutti in regola.$B$BI documenti dicevano che si chiamava Maelik; ecco la sua descrizione. Non credo che verrà più a trovare Thredd.",
  obj = "Porta la Sealed Description of Thredd's Visitor a Baros Alexston, a Stormwind.",
  progress = "Sì, $N? Cos'hai trovato?",
  reward = "Hmm. Maelik? No, il nome non mi dice niente, e nemmeno questa descrizione. Ma potrebbe essere chiunque! Un ex Stonemason, uno della Defias Brotherhood... Però, se ha i buoni agganci che dice Thelwater, forse qualcun altro potrebbe riconoscerlo. Fammi pensare.",
  en_title = "The Curious Visitor",
  en_obj = "Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.",
}
T[393] = {
  title = "L'ombra del passato",
  desc = "Non ne ho davvero idea, $N. C'è qualcun altro che potrebbe aiutarti, e si dà il caso che mi debba un favore per... be', lasciamo perdere. Master Mathias Shaw dello SI:7 lo trovi nella caserma di Old Town. Shaw tiene il dito su quasi tutti i traffici loschi o sottobanco della città.$B$BSe c'è qualcuno che lo sa, è lui.",
  obj = "Porta la Sealed Description of Thredd's Visitor a Master Mathias Shaw, a Stormwind.",
  progress = "Salve. In cosa posso esserti utile, $C?",
  reward = "Cosa? Cos'è questo? Sì, credo di sapere chi è quest'uomo, ma il suo nome non è Maelik. Gli assassini portano molti nomi e molte maschere, e le buttano via quando non servono più. Un altro alias che si sa aver usato è Marzon, anche se di sicuro nemmeno quello è il suo vero nome.$B$BIn ogni caso è un assassino, e io so parecchio di lui.$B$BAl momento Marzon è al soldo di Lord Gregor Lescovar, un nobile di reputazione losca, e questo pur tenendo conto della corruzione della nobiltà di Stormwind.",
  en_title = "Shadow of the Past",
  en_obj = "Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.",
}
T[394] = {
  title = "La testa della bestia",
  desc = "Trova Shaw a Old Town. Fagli sapere che la minaccia di Lescovar è stata risolta e del tuo ruolo nelle trame del nobile contro la città. Sono sicuro che sarà fiero di avere $Gun altro eroe:un'altra eroina; tra i cittadini di Stormwind.$B$BCon ogni probabilità ti manderà a incontrare il principe o qualche altro nobile. Non montarti la testa, $N. I nobili possono credere quanto vogliono di comandare la città, ma certe cose restano fuori dalla loro portata.",
  obj = "Parla con Mathias Shaw, a Stormwind.",
  reward = "È morto, dunque? La tua giustizia è stata rapida, $N. Prego la Luce di non diventare mai la tua preda!$B$B<Ride e ti dà una pacca sulla spalla.>$B$BNon è una critica, $N. Come potrei, io che sono il maestro di tutti gli assassini? Ma in verità hai reso un grande servizio alla gente di Stormwind, e di questo ti ringrazio.",
  en_title = "The Head of the Beast",
  en_obj = "Speak to Mathias Shaw in Stormwind.",
}
T[395] = {
  title = "La fine della Brotherhood",
  desc = "Ah, quasi dimenticavo. Alexston è passato mentre eri via, voleva parlarti. Di sicuro vuole riferire ai nobili quel che è successo con la Defias Brotherhood.$B$BUn consiglio, $N: se qualcuno dovesse chiedere, io riferirei tutti i particolari tranne che è stata la tua mano a uccidere Lescovar. Fidati. Sono... pratico... di come vanno certe cose.$B$BE quanto a Trias, be', non parlarne con nessuno... mai... se puoi evitarlo.",
  obj = "Parla con Baros Alexston, a Stormwind.",
  reward = "È bello vederti, $N. Ho sentito che Lord Gregor Lescovar è stato trovato morto non molto tempo fa.$B$BPare che tu abbia avuto successo nella tua missione. Hai la mia gratitudine per aver salvato me, e molti altri, dalla vendetta di VanCleef.",
  en_title = "Brotherhood's End",
  en_obj = "Speak with Baros Alexston in Stormwind.",
}
T[396] = {
  title = "Udienza dal Re",
  desc = "Ho preparato un rapporto per il Re. Credo che debba essere tu a consegnarglielo, insieme al resoconto di quel che hai scoperto. Non preoccuparti: non c'è dubbio che ti loderà per aver fatto il tuo dovere verso la gente di Stormwind.$B$BLa tua udienza è fissata a breve, quindi faresti meglio a sbrigarti: c'è un bel pezzo di strada fino a Stormwind Keep.",
  obj = "Consegna il rapporto di Baros Alexston sulla Defias Brotherhood a King Varian Wrynn, a Stormwind Keep.",
  progress = "$N, giusto? Baros Alexston mi ha avvisato che saresti $Gvenuto:venuta;. Devo dire che sono molto interessata a quel che hai da raccontare.",
  reward = "Meriti lode per il servizio che hai reso a Stormwind, $N. Se VanCleef avesse avuto successo nelle sue macchinazioni, avrebbe senza dubbio fatto un danno considerevole al regno, cosa che ovviamente dobbiamo evitare.$B$BPrendi questo, $C, come segno della riconoscenza del Re. Mi dispiace solo che non possa consegnartelo di persona, ma è via per una missione diplomatica e non tornerà per un po'.",
  en_title = "An Audience with the King",
  en_obj = "Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.",
}
T[397] = {
  title = "Ci hai servito bene",
  desc = "Mi dicono che Lord Wishock ha gradito la sua bevanda.$B$BCi hai servito bene, $N. Grazie a te gli stregoni di Stormwind potranno praticare le nostre arti senza disturbi. Per quel che hai fatto ho preparato un dono speciale per te. Parla con il mio servo, Zggi, e prenditi la ricompensa.",
  obj = "Parla con Zggi, il servo di Zardeth the Blackclaw, per ritirare la ricompensa.",
  reward = "Padrone dice dare dono a $N. Zggi vuole tenere bel dono ma Zggi sa che non deve tradire Padrone.",
  en_title = "You Have Served Us Well",
  en_obj = "Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.",
}
T[398] = {
  title = "Ricercato: Maggot Eye",
  desc = "Ricercato: Maggot Eye!$B$BUna bestia immonda, persino per gli standard dei Gnoll: Maggot Eye è stato condannato a morte per i suoi crimini contro i Forsaken. Questo spregevole furfante ha rubato cadaveri per l'esercito del Lich King. Maggot Eye è stato visto l'ultima volta mentre saccheggiava le terre vicino a Garren's Haunt, a nord di Brill.$B$BLa città di Brill offre una ricompensa a chiunque abbia la capacità di eseguire la condanna. Mostra la zampa del furfante a Executor Zygand a fatto compiuto.$B$BLa pietà è per i deboli.",
  obj = "Uccidi Maggot Eye e torna da Executor Zygand a Brill con la sua zampa per ottenere la ricompensa.",
  progress = "Sì?",
  reward = "Le azioni scellerate di Maggot Eye sono finalmente vendicate. Forse le tue gesta valorose manderanno un messaggio chiaro a chi vuole fare del male al nostro popolo. A nome della città di Brill ti ringrazio, $N.",
  en_title = "Wanted: Maggot Eye",
  en_obj = "Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.",
}
T[399] = {
  title = "Umili inizi",
  desc = "Mi sembra passata un'eternità da quando ero un ragazzo che lavorava nella fattoria a Westfall. Dicono che non si possa mai tornare indietro, ed è vero. Doppiamente vero nel mio caso: la casa della mia famiglia è stata bruciata e occupata dai ladri.$B$BHo parlato con mio padre della sorte di alcuni miei averi, tra cui la mia prima bussola. Non è riuscito a salvarli. Tuttavia dice anche che dovrebbero essere nascosti nella fattoria.$B$BTroverai l'Alexston Farmstead a ovest di Sentinel Hill. Forse potresti andare a recuperarla per me?",
  obj = "Vai alla casa di Baros Alexston a Westfall, cerca la sua bussola e riportagliela nella Cathedral Square di Stormwind.",
  progress = "$N! Hai avuto fortuna?",
  reward = "Oh, grazie, $N! Non ha alcuna utilità pratica per me, ma il valore affettivo... Inutile dire grazie per avermela portata... a costo del tuo benessere, senza contare il tempo che ci è voluto per scendere fino a Westfall. Hai la mia gratitudine, e prendi questo come segno di ringraziamento.",
  en_title = "Humble Beginnings",
  en_obj = "Go to Baros Alexston's house in Westfall and search for his compass, then return it to him in Cathedral Square of Stormwind.",
}
T[400] = {
  title = "Attrezzi per Steelgrill",
  desc = "Beldin Steelgrill possiede l'officina meccanica della zona ed è il miglior tecnico di macchine d'assedio che ci sia! Ma con i suoi attrezzi non ha pietà. Giuro che rompe più chiavi arclight di quante riusciamo a fornirgliene!$B$BAbbiamo appena preparato il suo ultimo ordine di attrezzi. Se glielo consegni, sono sicuro che ne varrà la pena.$B$BLa sua officina, Steelgrill's Depot, è appena a nord-est di Kharanos. È un ritrovo per piloti veterani di macchine d'assedio, quindi tieni le orecchie aperte: potrebbero esserci delle opportunità.",
  obj = "Consegna gli attrezzi di Steelgrill a Beldin Steelgrill.",
  progress = "Mm? Sembri un po' giovane per pilotare una macchina d'assedio. Ma non importa... devi far riparare qualcosa?$B$BBeh, prendi il numero e mettiti comod$Go:a;. Sto lavorando a un paio di macchine e non avrò tempo per un altro lavoro almeno per qualche giorno.$B$BOppure sei qui per qualcos'altro...?",
  reward = "Hai i miei attrezzi? Ben fatto, ben fatto! Ho rotto il mio ultimo cricchetto a zanna un'ora fa e me ne serve uno per finire le riparazioni della macchina d'assedio di Pilot Stonegear. Hai fatto una buona cosa a trascinare qui questi attrezzi, $N.$B$BEcco, prendi queste monete per il tuo aiuto.",
  en_title = "Tools for Steelgrill",
  en_obj = "Deliver Steelgrill's Tools to Beldin Steelgrill.",
}
T[401] = {
  title = "Aspetta che Sirra finisca",
  desc = "Ho quasi finito di tradurre quel biglietto. Se torni fra qualche momento dovrei aver finito.",
  obj = "Aspetta un momento, poi parla di nuovo con Sirra Von'Indi.",
  reward = "Ecco qua. È tradotto...$B$B<L'aria si fa pesante, come se una cortina nera e spessa calasse sulla terra...>",
  en_title = "Wait for Sirra to Finish",
  en_obj = "Wait a moment, then speak with Sirra Von'Indi again.",
}
T[403] = {
  title = "Barile di Thunderbrew sorvegliato",
  reward = "Questo barile di birra è sorvegliato da Jarven Thunderbrew. Finché lui è in cantina, nessun barile può essere toccato.",
  en_title = "Guarded Thunderbrew Barrel",
}
T[404] = {
  title = "Un compito putrido",
  desc = "Lo Scourge si è infiltrato a Tirisfal Glades e ha infestato la zona a ovest di Brill, vicino al vecchio ponte.$B$BVai là e respingi i morti in putrefazione e i cadaveri straziati che troverai. Disperdi le loro ossa e portami i loro artigli putridi, e le Deathguard ti ricompenseranno.",
  obj = "Porta 7 Putrid Claw a Deathguard Dillinger a Brill.",
  progress = "Hai portato a termine il compito che ti ho affidato? Hai quegli artigli putridi?",
  reward = "Ben fatto. Mi dispiace non essere stato presente a vederti ridurre quei non morti in poltiglia putrescente!",
  en_title = "A Putrid Task",
  en_obj = "Bring 7 Putrid Claws to Deathguard Dillinger in Brill.",
}
T[405] = {
  title = "Il Lich prodigo",
  desc = "Bethor Iceshard, un potente mago di alto rango nella Undercity, a sud, mi ordina di mandargli un agente che abbia dimostrato il suo valore contro lo Scourge. Tu, $N, sarai quell'agente.$B$BPresenta questi ordini a Bethor. Lui ti istruirà sulla tua missione. Non ne conosco i dettagli, ma riguarda il reclutamento di un Lich ribelle. E sarà pericolosa.$B$BQuindi preparati, $C. Non devi fallire.$B$BPuoi trovare Bethor nel Magic Quarter della Undercity.",
  obj = "Presenta gli Sevren's Orders a Bethor Iceshard nella Undercity.",
  progress = "Salute. O non sai chi sono, oppure la tua faccenda con me è urgente.$B$BPerché se nessuna delle due fosse vera, non saresti così sciocco da disturbarmi...",
  reward = "Ah, sei l'agente mandato da Magistrate Sevren. Allora sì, la tua faccenda con me è cruciale.$B$BSpero che Sevren abbia scelto qualcuno adatto al mio compito... ma vedremo.",
  en_title = "The Prodigal Lich",
  en_obj = "Present Sevren's Orders to Bethor Iceshard in the Undercity.",
}
T[407] = {
  title = "Fields of Grief",
  desc = "Zucche innocue, vero? O almeno così sembrerebbe. Se vogliamo sconfiggere l'avanzata di Arthas da nord e l'infestazione umana da sud, dobbiamo iniziare a sfruttare appieno il potenziale del nostro dono della non morte.$B$BCon un po' di ingegno una semplice zucca diventa un agente per la nostra Dark Lady. Questa zucca, intrisa della mia ultima formula, si rivelerà una vera delizia.$B$BUn altro Scarlet Zealot è stato catturato e viene tenuto nella cantina della Gallow's End Tavern. Porta questa zucca a quello sciocco.",
  obj = "Porta la Laced Pumpkin al Captured Scarlet Zealot tenuto prigioniero nella cantina della Gallow's End Tavern.",
  progress = "Stai lontano, creatura immonda ed empia! Che la Luce mi protegga! La Scarlet Crusade libererà Azeroth dalla tua. . .$B$B. . .oh, aspetta. È cibo per me? Ho tanta fame. . .",
  reward = "Per la Luce! Finalmente del cibo! Dolce, dolce zucca. . . .",
  en_title = "Fields of Grief",
  en_obj = "Take the Laced Pumpkin to the Captured Scarlet Zealot who is being held in the cellar of the Gallow's End Tavern.",
}
T[408] = {
  title = "La cripta di famiglia",
  desc = "La zona di Agamand Mills è diventata un punto d'appoggio per lo Scourge. Il loro baluardo è la Agamand Family Crypt, dove ha stabilito il quartier generale il loro capo militare locale, uno scheletro di nome Captain Dargol. Con la negromanzia ha risvegliato gli antenati degli Agamand e intende usarli contro di noi.$B$BQuesto non deve accadere, e tu devi impedirlo. Recati alla Agamand Family Crypt e sconfiggi gli antenati risvegliati degli Agamand.$B$BE portami il teschio di Captain Dargol.",
  obj = "Uccidi 8 Wailing Ancestor e 8 Rotting Ancestor.$B$BUccidi Captain Dargol e porta il suo teschio a Magistrate Sevren a Brill.",
  progress = "Il tempo non è un lusso che possiamo permetterci, $N. A ogni ora che passa, la presa dello Scourge su Tirisfal Glades si fa più salda.",
  reward = "Le tue azioni hanno inferto un colpo decisivo allo Scourge. E la tua vittoria non passerà inosservata, né ai Forsaken né ai nostri nemici.$B$BContinua la lotta come facciamo tutti noi, $N, e un giorno scacceremo da Azeroth il Lich King in persona!",
  en_title = "The Family Crypt",
  en_obj = "Kill 8 Wailing Ancestors and 8 Rotting Ancestors.$B$BKill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.",
}
T[409] = {
  title = "Dimostrare fedeltà",
  desc = "Dici di non essere vincolato dalla volontà del Lich King, e l'incantesimo che Bethor ha posto sul mio libro lo conferma. Ma prima di crederti devo avere la prova che sei nemico dello Scourge.$B$BC'è un vecchio altare insanguinato poco oltre la costa meridionale di quest'isola. Lo usa un potente agente dello Scourge, Lillith Nefara.$B$BPrendi una Candle of Beckoning da questa cassa. Accendila sull'altare e Lillith si risveglierà. Distruggi Lillith e crederò che tu sia nemico del Lich King.",
  obj = "Ottieni una Candle of Beckoning.$B$BEvoca Lillith Nefara e uccidila.$B$BTorna da Gunther sulla sua isola.",
  progress = "Attendo la prova della tua fedeltà, $c.",
  reward = "Hai sconfitto Lillith Nefara, dimostrando di essere un nemico dello Scourge. Incredibile.$B$BCredevo di essere l'unico Non Morto dotato di libero arbitrio, ma tu mi hai mostrato che ce ne sono altri che hanno spezzato il dominio del Lich King.",
  en_title = "Proving Allegiance",
  en_obj = "Obtain a Candle of Beckoning.$B$BSummon Lillith Nefara and kill her.$B$BReturn to Gunther on his island.",
}
T[410] = {
  title = "L'Ombra Dormiente",
  progress = "È un vecchio tavolo, malconcio e insanguinato.",
  reward = "Posi la Candle of Beckoning sul tavolo e la accendi...",
  en_title = "The Dormant Shade",
}
T[411] = {
  title = "Il ritorno del Lich Prodigo",
  desc = "Porta questa Nether Gem al mio vecchio compagno Bethor. Ci permetterà di comunicare... e ho molto da dirgli.",
  obj = "Porta la Nether Gem a Bethor Iceshard a Undercity.",
  progress = "Hai restituito il libro di Gunther? Ha risposto?",
  reward = "L'hai convinto a unirsi a noi! Hai compiuto una grande impresa per i Reietti, $N. La Dama Oscura sarà informata.",
  en_title = "The Prodigal Lich Returns",
  en_obj = "Bring the Nether Gem to Bethor Iceshard in the Undercity.",
}
T[412] = {
  title = "Operazione Ricombobulazione",
  desc = "Da un'ulteriore analisi della situazione di Gnomeregan, sembrerebbe che non solo non siamo riusciti a sterminare i trogg, ma abbiamo anche trasformato gran parte della razza gnomica in orribili gnomi lebbrosi, malvagi e senza cervello.$B$BOzzie e io intendiamo invertire l'orribile effetto lebbroso con la nostra ultima invenzione: il Ricombobulatore. La macchina è quasi completa, ma ci servono urgentemente dei Restabilization Cogs e dei Gyromechanic Gears. Recuperane un po' dagli gnomi lebbrosi davanti a Gnomeregan.",
  obj = "Porta a Razzle Sprysprocket a Kharanos 8 Restabilization Cogs e 8 Gyromechanic Gears.",
  progress = "Il Ricombobulatore sarà operativo non appena avremo abbastanza Restabilization Cogs e Gyromechanic Gears.",
  reward = "Questi Gyromechanic Gears e Restabilization Cogs sono perfettamente conformi agli schemi di Ozzie per il dispositivo di ricombobulazione. Una volta aggiunto un po' di idrolubrificante ai pistoni a combustione interna, regolato il cricco-manovella e aumentata la viscosità del gel elettrogommoso, la razza gnomica sarà come nuova.",
  en_title = "Operation Recombobulation",
  en_obj = "Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.",
}
T[413] = {
  title = "Shimmer Stout",
  desc = "Vorrei che mio fratello Wellart assaggiasse la mia nuova Shimmer Stout. È un Mountaineer di stanza nella torre di guardia meridionale, una delle due torri al confine con Loch Modan.$B$BNon sarà un birraio come il resto di noi Barleybrew, ma adora bere e so che questa gli piacerà.$B$BPuoi portargli questo barile di Shimmer Stout da parte mia?",
  obj = "Porta il Barrel of Shimmer Stout a Mountaineer Barleybrew.",
  progress = "Salve, $C! E quale faccenda ti porta fin quaggiù?$B$BQualcosa di emozionante, spero. Non faccio una bella rissa da giorni, e questo barile di birra è quasi a secco...",
  reward = "<Mountaineer Barleybrew assaggia la Shimmer Stout...>$B$BOh. Accidenti! Questa roba ti fa proprio brillare gli occhi. Mi sembra di vedere al buio!",
  en_title = "Shimmer Stout",
  en_obj = "Take the Barrel of Shimmer Stout to Mountaineer Barleybrew.",
}
T[414] = {
  title = "Birra per Kadrell",
  desc = "Ho bevuto ancora un po' di quella Shimmer Stout di mio fratello: è fantastica! Voglio che la assaggi anche un altro Mountaineer. Si chiama Kadrell e di solito pattuglia la strada che attraversa Thelsamar, a Loch Modan.$B$BPer arrivare a Thelsamar, vai a sud-est attraverso il tunnel, poi gira a nord-est dove il sentiero si biforca in una strada. Segui quella strada dritto fino a Thelsamar.$B$BDai a Mountaineer Kadrell questa botticella di Shimmer Stout e senti cosa ne pensa!",
  obj = "Porta la Cask of Shimmer Stout a Mountaineer Kadrell.",
  progress = "Salute, $C, e benvenut$Go:a; a Thelsamar!",
  reward = "Allora, fammi assaggiare...$B$BPer la barba di Magni! Questa roba ti fa girare la testa! E alleggerisce pure le gambe.$B$BMi sembra di poter volare!",
  en_title = "Stout to Kadrell",
  en_obj = "Take the Cask of Shimmer Stout to Mountaineer Kadrell.",
}
T[415] = {
  title = "La nuova birra di Rejold",
  desc = "Rejold Barleybrew di Brewnall Village ha chiesto di te.$B$BVuole parlarti di una nuova bevanda che sta preparando... ha detto qualcosa sul fatto che l'hai aiutato. Forse ti conviene tornare a Brewnall Village e sentire cosa ha da dire.$B$BPotrebbe scapparci qualche bicchiere gratis...",
  obj = "Parla con Rejold Barleybrew.",
  reward = "$N! Ricordi lo shimmerweed che mi hai portato? Beh, l'ho usato in un paio di ricette a cui stavo lavorando, e una è venuta benissimo!$B$BEcco, assaggiala e dimmi cosa ne pensi...",
  en_title = "Rejold's New Brew",
  en_obj = "Speak with Rejold Barleybrew.",
}
T[416] = {
  title = "Caccia ai ratti",
  desc = "A ovest abbiamo un vero problema di infestazione. I coboldi tunnel rat si sono trasferiti ai piedi delle colline, costruendo tane e sporcando la nostra terra con la loro sporcizia!$B$BVogliamo che vengano eliminati. Dagli la caccia, portami le loro orecchie e incassa la taglia.$B$BTrovi i coboldi tunnel rat e le loro tane a ovest di Thelsamar, sparsi lungo il fianco della montagna.",
  obj = "Porta 12 Tunnel Rat Ears a Mountaineer Kadrell a Thelsamar.",
  progress = "Salve, $N. Come va la caccia ai ratti?",
  reward = "Bleah! Quando ti ho chiesto quelle orecchie non immaginavo che puzzassero così tanto!$B$BEcco la tua ricompensa, $N. Ben fatto.",
  en_title = "Rat Catching",
  en_obj = "Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar.",
}
T[417] = {
  title = "La vendetta di un pilota",
  desc = "Hildelve ha scritto nel suo diario di essere stato attaccato da Mangeclaw, un \"enorme Ice Claw Bear\". Riuscì a scacciare la bestia, ma non prima che lo sbranasse ferocemente.$B$BA giudicare dallo stato del corpo di Hildelve, Mangeclaw dev'essere tornato più tardi a ucciderlo.$B$BTuttavia, Hildelve ha scritto nel diario il suo ultimo desiderio:$B$BVendetta contro Mangeclaw.",
  obj = "Uccidi Mangeclaw.$B$BPorta il suo Mangy Claw e l'Hildelve's Journal a Pilot Hammerfoot.",
  progress = "Salve, $N. Hai notizie del mio amico Hildelve?",
  reward = "Sono notizie tristi: Hildelve era un buon amico. E vorrei essere stato lì con te quando hai trovato quella bestia di Mangeclaw!$B$BGrazie, $N. Il tuo gesto sarà ricordato dai piloti della Ironforge Siege Brigade.",
  en_title = "A Pilot's Revenge",
  en_obj = "Kill Mangeclaw.$B$BBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot.",
}
T[418] = {
  title = "Sanguinacci di Thelsamar",
  desc = "Qui a Thelsamar le pance vuote non mancano mai: bambini che entrano ed escono, operai dello scavo che arrivano dopo una dura giornata di lavoro. Siamo famosi per i nostri sanguinacci. Scommetto che non li hai mai assaggiati.$B$BNo? Beh, da queste parti i pasti bisogna guadagnarseli, e non pensare di fare eccezione solo perché sei $Gun $C tanto elegante:una $C tanto elegante;.$B$BMi servono carne d'orso, budella di cinghiale per l'involucro e icore di ragno per insaporire. Procurami un po' di questa roba e lascia la cucina a Vidra!",
  obj = "Porta 3 pezzi di Bear Meat, 3 Boar Intestines e 3 Spider Ichor a Vidra Hearthstove a Thelsamar.",
  progress = "Sono pronta a cominciare a cucinare. Hai gli ingredienti per me?",
  reward = "Fidati, sembra molto più difficile di quello che è, ma...$B$BOh, non ho mai conosciuto nessuno che si interessasse tanto a come si fanno le salsicce, ma ti do la ricetta, non si sa mai. Ecco qua, e mi raccomando: mangiali freschi!",
  en_title = "Thelsamar Blood Sausages",
  en_obj = "Bring 3 pieces of Bear Meat, 3 Boar Intestines, and 3 Spider Ichor to Vidra Hearthstove in Thelsamar.",
}
T[419] = {
  title = "Il pilota scomparso",
  desc = "Il mio amico e collega pilota di macchine d'assedio, Mori Hildelve, si è perso sulle colline. Cercavamo un minerale raro che serve per una polvere esplosiva di alta qualità e, durante la ricerca, lui ha guidato la sua macchina su per una collina ripida e l'ha distrutta!$B$BAncora convinto che quel minerale fosse su queste montagne, Hildelve mi ha incaricato di sorvegliare le nostre macchine mentre lui proseguiva a piedi a cercarlo.$B$BSono passati giorni, e di notte ho sentito dei ringhi bestiali sulle colline. Mori è duro come la pietra, ma sono preoccupato.$B$BTi prego, $N. Trovalo.",
  obj = "Trova Pilot Hildelve.",
  reward = "Qui giace il cadavere di un nano: sbranato, congelato e ripulito dagli spazzini di montagna. Stretto nella mano c'è un libro con gli appunti scarabocchiati di Mori Hildelve. E addosso, ancora in ottime condizioni, c'è un Brigadier's Vest.$B$BIn questa scena raccapricciante il pilota della macchina d'assedio ha trovato la sua fine.",
  en_title = "The Lost Pilot",
  en_obj = "Find Pilot Hildelve.",
}
T[420] = {
  title = "Le osservazioni di Senir",
  desc = "I trogg nel tunnel sono estremamente ostili e non hanno esitato ad attaccare chi lo attraversa. Però sembri abbastanza robust$Go:a;, quindi dovresti essere al sicuro.$B$BIndicazioni? Se vai a parlare con Senir, lo troverai a Kharanos.$B$BAttraversa il tunnel e, una volta uscit$Go:a; dall'altra parte, continua a seguire la strada: ti porterà dritt$Go:a; a Kharanos.",
  obj = "Consegna il rapporto di Grelin a Senir Whitebeard a Kharanos.",
  progress = "Come stai? Ti va di bere qualcosa con me? Non c'è molto altro da fare con questo freddo.",
  reward = "Cos'è questo? Ah, il rapporto di mio fratello. Mm...$B$BGli avevo detto di andarci piano con il nome del re, ma non mi ha dato retta. Poco male, suppongo, anche se di sicuro farà arruffare qualche piuma al Senato. E di piume da arruffare ce n'erano! Ah!$B$BComunque, immagino che questo significhi che dovrei mandare anch'io il mio rapporto a Ironforge, ma devo ammettere che sono un po' in ritardo. Maledetto freddo.$B$BPiù tardi dovrei avere del lavoro per te, se ti interessa.",
  en_title = "Senir's Observations",
  en_obj = "Deliver Grelin's report to Senir Whitebeard in Kharanos.",
}
T[421] = {
  title = "Dimostra il tuo valore",
  desc = "Lady Sylvanas ha affidato a Varimathras la conquista delle terre umane e naniche a sud.$B$BMa quello sciocco di Arugal, ciarlatano di Dalaran e ora bestia maledetta di Shadowfang Keep, ha lasciato che la sua magia sconsiderata devastasse la roccaforte strategica di Silverpine Forest.$B$BHo bisogno di qualcuno esperto nell'arte del combattimento che mi aiuti a ripulire il disastro di Arugal. Dimostrami il tuo valore uccidendo 5 Moonrage Whitescalps. Quelle bestie miserabili si trovano spesso poco lontano dalla strada, giù per la collina.",
  obj = "Dalar Dawnweaver al Sepulcher vuole che tu uccida 5 Moonrage Whitescalps.",
  progress = "Se vuoi dimostrarmi il tuo valore, devi uccidere 5 Moonrage Whitescalps. Porta a termine il compito e farò in modo che la tua abilità sia impiegata in incarichi più degni.",
  reward = "Mi hai servito bene, $C. È evidente che sarai un aiutante degno di me mentre mi preparo a liberare Silverpine Forest dalla maledizione di Arugal.",
  en_title = "Prove Your Worth",
  en_obj = "Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps.",
}
T[422] = {
  title = "La follia di Arugal",
  desc = "Come Arugal sia stato accettato nel Kirin Tor è al di là della mia comprensione. La sua conoscenza degli incantesimi era trasparente quanto una bolla di vetro soffiato.$B$BCiò che conta ora è scoprire esattamente quale magia abbia usato Arugal, così da rivolgergliela contro e assicurare Silverpine Forest alla Dama Oscura.$B$BArugal soggiornò per primo nella fattoria di grano a nord del ponte. Uno dei Deathstalker ha riferito di aver visto dei libri di incantesimi, ma non è riuscito a recuperarli. Recupera per me da quei libri l'incantesimo chiamato Remedy of Arugal.",
  obj = "Recupera il Remedy of Arugal per Dalar Dawnweaver al Sepulcher.",
  progress = "Prima di sapere con cosa abbiamo a che fare, $C, devo studiare l'incantesimo noto come Remedy of Arugal. Portamelo subito, o sarò costretto a cercarmi un servitore più degno.",
  reward = "È proprio l'incantesimo che cercavo, $C. Se la tua dedizione alla causa della Dama Oscura resterà ferma, scoprirai di avere un grande futuro tra i Reietti.",
  en_title = "Arugal's Folly",
  en_obj = "Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher.",
}
T[423] = {
  title = "La follia di Arugal",
  desc = "Dopo aver esaminato l'opera di Arugal, i miei peggiori sospetti sono stati confermati. Quel vecchio ciarlatano non era qualificato nemmeno per pulire i vasi da notte a Dalaran, figuriamoci per rappresentare il Kirin Tor nella sua ora più buia. Sciocchi!$B$BArugal usava oggetti incantati per rinforzare la sua magia debole. Devo esaminarli di persona. Parti e uccidi Moonrage Gluttons e Moonrage Darksouls finché non avrai raccolto abbastanza delle loro catene incantate per le mie ricerche. Quelle creature immonde sono state avvistate a nord e a est.",
  obj = "Porta 6 Glutton Shackles e 3 Darksoul Shackles a Dalar Dawnweaver al Sepulcher.",
  progress = "Mi servono 6 Glutton Shackles e 3 Darksoul Shackles prima di poter valutare la situazione e ideare una soluzione definitiva per Arugal. Ora obbedisci e uccidi Moonrage Gluttons e Moonrage Darksouls finché non avrai ciò che mi serve.",
  reward = "Spero di riuscire a ricavare abbastanza energia da un campione così limitato. Forse avrei dovuto farti portare più catene.$B$BTuttavia, hai dimostrato grande abilità nel raccoglierle, $C.",
  en_title = "Arugal's Folly",
  en_obj = "Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher.",
}
T[424] = {
  title = "La follia di Arugal",
  desc = "Mi ci vorrà davvero più tempo del previsto per scoprire gli oscuri segreti degli incantesimi usati da Arugal.$B$BNel frattempo, però, devi occuparti di un piccolo problema scoperto dai nostri Darkstalker. Pare che Arugal abbia lasciato diffondere la sua magia fino alla Deep Elem Mine, sulle colline a sudest.$B$BLa miniera sarebbe una risorsa preziosa per l'avanzata di Varimathras.$B$BVoglio che tu decapiti il caposquadra contaminato della miniera, Grimson the Pale. Con la sua morte, la miniera sarà nostra.",
  obj = "Uccidi Grimson the Pale e porta la sua testa a Dalar Dawnweaver al Sepulcher.",
  progress = "Grimson the Pale è stato ucciso? Varimathras non sarà contento se ignoriamo i suoi ordini.",
  reward = "Eccellente. La miniera fornirà risorse superbe alle nostre forze mentre ci espandiamo per Silverpine e fino in Azeroth.",
  en_title = "Arugal's Folly",
  en_obj = "Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher.",
}
T[425] = {
  title = "Ivar the Foul",
  desc = "Io e mio fratello Quinn eravamo stati incaricati di esplorare Silverpine Forest e riferire all'High Executor Hadrec. Ma non siamo andati lontano: mentre attraversavamo questa fattoria siamo stati attaccati dal ghoul Ivar the Foul.$B$BCi siamo salvati da Ivar, ma ha ferito gravemente Quinn. Si sta riprendendo grazie alla pozione che gli hai dato, ma Ivar potrebbe tornare prima che Quinn sia guarito.$B$BUccidi Ivar, così che Quinn abbia il tempo di rimettersi. Ivar di solito sta nel fienile laggiù, in attesa che io abbassi la guardia.",
  obj = "Uccidi Ivar the Foul e porta l'Ivar's Head a Rane Yorick all'Ivar Patch.",
  progress = "Hai ucciso Ivar the Foul? Se non vuoi farlo per me e per mio fratello, fallo per i Reietti.",
  reward = "Ah, grazie. Hai la mia gratitudine, $N.$B$BE ti includerò nel rapporto che farò ai miei superiori.",
  en_title = "Ivar the Foul",
  en_obj = "Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch.",
}
T[426] = {
  title = "I Mulini invasi",
  desc = "Lo Scourge sta cercando di stabilire una base agli Agamand Mills. Se ci riuscirà, potrà lanciare altri attacchi dentro Tirisfal.$B$BGli ordini sono stati dati: lo Scourge nei Mills va distrutto.$B$BVai ai Mills. Raccogli Notched Ribs da Rattlecage e Cracked Skull Soldiers, e Blackened Skulls dai Darkeye Bonecasters.$B$BPer raggiungere i Mills, segui la strada verso ovest. Dopo aver attraversato il ponte, prendi il prossimo bivio a nord e continua verso nord. Quando vedrai dei mulini a vento, la battaglia avrà inizio.",
  obj = "Raccogli 5 Notched Ribs e 3 Blackened Skulls, poi torna da Deathguard Dillinger a Brill.",
  progress = "Le nostre battaglie contro lo Scourge infuriano, $N. Fai la tua parte e ricaccia quei maledetti non morti senza cervello nelle Plaguelands!",
  reward = "I tuoi sforzi in guerra si fanno sentire tra noi, $N. Non ti ringrazierò per aver fatto ciò che è necessario, ma le Deathguard di Tirisfal ricorderanno il tuo nome.",
  en_title = "The Mills Overrun",
  en_obj = "Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill.",
}
T[427] = {
  title = "In guerra con la Scarlet Crusade",
  desc = "I documenti forniti dall'Executor Arren sono proprio la svolta che ci serviva nella battaglia contro la miserabile Scarlet Crusade. Ora conosciamo le loro posizioni esatte in tutta Tirisfal Glades.$B$BMa la Deathguard ha preoccupazioni più grandi. L'esercito del Lich King cresce ogni notte. Ci serve qualcuno con \"iniziativa\" come te per spingere la Scarlet Crusade nella tomba.$B$BDimostrami di poter servire la Dama Oscura: viaggia a ovest fino alla torre oltre la Solliden Farmstead e uccidi 10 Scarlet Warriors.",
  obj = "Executor Zygand di Brill vuole che tu uccida 10 Scarlet Warriors.",
  progress = "Se vuoi dimostrare il tuo valore alla Dama Oscura, uccidi 10 Scarlet Warriors, $C.",
  reward = "Eccellente, $C. La tua abilità nell'arte del combattimento è innegabile.",
  en_title = "At War With The Scarlet Crusade",
  en_obj = "Executor Zygand of Brill wants you to kill 10 Scarlet Warriors.",
}
T[428] = {
  title = "Deathstalker dispersi",
  desc = "Un paio di settimane fa due dei nostri Deathstalker, Rane e Quinn Yorick, sono stati inviati in ricognizione attraverso la parte settentrionale di Silverpine. Non abbiamo più avuto notizie.$B$BPotrebbero essere caduti vittime dello Scourge, ma se è così voglio una conferma. Trova questi Deathstalker.$B$BIl loro primo obiettivo era esplorare le fattorie del nord di Silverpine. Dovresti iniziare la ricerca da lì.",
  obj = "Trova i Deathstalker Quinn e Rane Yorick.",
  reward = "Ci hai trovati! E non un attimo troppo presto...",
  en_title = "Lost Deathstalkers",
  en_obj = "Find the Deathstalkers Quinn and Rane Yorick.",
}
T[429] = {
  title = "Cuori selvaggi",
  desc = "Mio fratello Quinn è stato ferito gravemente dal ghoul Ivar the Foul, e non so se guarirà a dovere senza aiuto magico. Anche se non sono un apothecary, so che i nostri apothecary possono preparare pozioni curative con i cuori scoloriti dei worg.$B$BRaccogli quei cuori e portali ad Apothecary Renferrel al Sepulcher, a sud. Poi torna qui con la pozione.$B$BTroverai molti worg tra qui e il Malden's Orchard, a est.",
  obj = "Raccogli 6 discolored worg hearts e portali ad Apothecary Renferrel al Sepulcher.",
  progress = "Il mio tempo è poco, $c, perché la Dama Oscura mi ha affidato un compito grave.",
  reward = "<Renferrel prende i cuori>$B$BÈ preoccupante sapere che i nostri Deathstalker hanno fallito la missione.$B$BSperiamo che simili fallimenti siano rari.$B$BTra un momento ti darò la pozione, ma ecco la sua ricetta: se quei Deathstalker dovessero avere bisogno di altro aiuto, forse potrai prepararla tu stess$Go:a;.",
  en_title = "Wild Hearts",
  en_obj = "Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher.",
}
T[430] = {
  title = "Ritorno da Quinn",
  desc = "Ecco la pozione per aiutare la guarigione di Quinn Yorick.$B$BOra, se vuoi scusarmi, ho un lavoro molto importante da portare avanti...",
  obj = "Porta la pozione di Quinn a Quinn Yorick all'Ivar Patch, a nord del Sepulcher.",
  progress = "Mia sorella mi ha detto che sei qui per aiutarci. È vero?",
  reward = "<Quinn prende la pozione e la beve>$B$BSì, sento che sta facendo effetto. Presto potrò rimettermi in viaggio.$B$BMi hai fatto un grande favore, $N.",
  en_title = "Return to Quinn",
  en_obj = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.",
}
T[431] = {
  title = "Candles of Beckoning",
  reward = "Prendi una delle candele e la riponi nello zaino.",
  en_title = "Candles of Beckoning",
}
T[432] = {
  title = "Quei maledetti trogg!",
  desc = "Quei maledetti trogg stanno trasformando il mio cantiere in un rottame! Guarda lì, ecco che salta un altro barile di polvere!$B$BOhhh, vorrei scendere laggiù e tirare il collo a ognuno di quei cosi rinsecchiti! Voglio ammazzarli tutti!$B$BTutto questo stress e questa rabbia non possono fare bene alla mia salute... Cosa mi hanno lasciato? Niente!$B$BLi ucciderei io stesso, ma la mia mira non è più quella di una volta! Scendi nella cava e uccidi un po' di quelle luride canaglie! Ti pagherò! Basta che li colpisci, che li uccidi!",
  obj = "Uccidi 6 Rockjaw Skullthumpers per Foreman Stonebrow alla cava di Gol'Bolar.",
  progress = "Mi fa così arrabbiare! Grrr...",
  reward = "Beh, così mi sento un po' meglio...$B$BMa non sarò contento finché non saranno tutti morti! Tutti quanti!",
  en_title = "Those Blasted Troggs!",
  en_obj = "Kill 6 Rockjaw Skullthumpers for Foreman Stonebrow at the Gol'Bolar quarry.",
}
T[433] = {
  title = "Al servizio del popolo",
  desc = "Come membro del Senato e dell'Explorers' League, mi sono fatto carico di questa parte dell'infestazione di trogg che affligge le nostre terre.$B$BHanno fatto un bel disastro alla cava di Gol'Bolar, e senza motivo. Mentre scavavamo in profondità, sono sbucati fuori a frotte, distruggendo le nostre attrezzature e cacciando i minatori. Non ci resta che sterminarli tutti, ricostruire e poi tornare al lavoro.$B$BSe mi aiuti con i trogg, ti ricompenserò volentieri per il tuo tempo.",
  obj = "Uccidi 10 Rockjaw Bonesnappers per il senatore Mehr Stonehallow alla cava di Gol'Bolar.",
  progress = "Liberare la cava di Gol'Bolar dai trogg sarà il primo di molti passi necessari per sbarazzarci di questa piaga.",
  reward = "È un inizio. Speriamo di poterne approfittare per mandare qualche Mountaineer a mettere in sicurezza la zona. Poi potremo cominciare a ripristinare le nostre strutture e rimettere al lavoro i minatori.$B$BGrazie per il tuo aiuto, $N.",
  en_title = "The Public Servant",
  en_obj = "Kill 10 Rockjaw Bonesnappers for Senator Mehr Stonehallow at the Gol'Bolar quarry.",
}
T[434] = {
  title = "L'attacco!",
  desc = "Dopo che avrò messo addosso a Spybot il travestimento, andrà a parlare con Lescovar. Le guardie dovrebbero lasciarlo passare senza problemi.$B$BMentre tu mi procuravi il materiale, io ho pensato a far sapere a Marzon che era ora che lui e Lescovar si rivedessero. Gli ho anche fatto arrivare qualche informazione falsa.$B$BLescovar congederà le guardie e aspetterà Marzon qui fuori in giardino. Quando li senti parlare dei Defias, entra in azione. Devi ucciderli tutti e due prima che le guardie tornino! Quando hai finito, parla con Trias.",
  obj = "Resta nel giardino finché Lord Gregor Lescovar e Marzon the Silent Blade non hanno finito di parlare. Poi uccidili tutti e due e torna da Elling Trias, a Stormwind.",
  progress = "Sì, $N? Le cose vanno bene con Tyrion? Mi ha messo al corrente della situazione e l'ho aiutato a ingannare Marzon perché andasse al castello.$B$BMarzon è stato una spina nel fianco di molte persone a Stormwind, e parecchie di loro sono miei cari amici. Nessuno tocca i miei amici... non se sa cosa gli conviene.$B$BÈ solo un peccato che nel frattempo stia facendo indirettamente un favore a Shaw e allo SI:7. Pazienza, non tutti i piani sono perfetti.",
  reward = "Quindi è fatta? Bene. Grazie mille per la tua discrezione, $N. Hai dimostrato il tuo valore più di una volta. Starò di sicuro a guardare te e i tuoi progressi dentro l'Alleanza.$B$BMi raccomando, tieni la fedina pulita.",
  en_title = "The Attack!",
  en_obj = "Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.",
}
T[435] = {
  title = "Scortare Erland",
  desc = "I lupi là fuori non se ne vanno, e mi guardano con occhi malvagi ogni volta che metto piede fuori da quella porta. Devono avere una fame tremenda per pensare che io valga la pena di essere mangiato.$B$BDevo fare rapporto al mio compagno, il Deathstalker Rane Yorick. E per raggiungere Rane mi serve aiuto contro quei lupi.$B$BTi prego, scortami! Là fuori ci sono molti lupi, quindi avremo più possibilità se hai degli amici che possano aiutarci...",
  obj = "Scorta Erland attraverso i lupi fino a Rane Yorick.",
  progress = "Ti prego di essere breve. Ci sono molti pericoli in giro e non possiamo restare fermi a conversare.",
  reward = "Grazie per l'aiuto, $N. Temevo che Erland fosse stato sopraffatto dai pericoli di Silverpine. Grazie a te, vedo che non è così.",
  en_title = "Escorting Erland",
  en_obj = "Escort Erland through the wolves, to Rane Yorick.",
}
T[436] = {
  title = "Lo scavo di Ironband",
  desc = "Prospector Ironband dirige lo scavo di antiche rovine a est del lago. Ultimamente i suoi progressi sono lenti, soprattutto considerando tutte le provviste che gli abbiamo mandato.$B$BIronband è un nano robusto e onesto che bada ai risultati, e questo mi fa temere che qualcuno stia lavorando contro di lui.$B$BVai all'Ironband's Excavation e parla con Magmar Fellhew. Si occupa dei dettagli del sito e saprà perché i lavori rallentano.$B$BPer arrivare al sito di scavo, aggira la punta meridionale del lago, poi dirigiti a est.",
  obj = "Parla con Explorer Fellhew.",
  reward = "Jern vuole sapere perché i lavori rallentano, eh?$B$BIronband sta preparando il suo ultimo rapporto con tutti i dettagli, ma una cosa posso dirtela:$B$BSono i trogg!!",
  en_title = "Ironband's Excavation",
  en_obj = "Speak with Explorer Fellhew.",
}
T[437] = {
  title = "I Dead Fields",
  desc = "I nostri primi rapporti di ricognizione su Silverpine mostrano che i rot hide hanno una base in una vecchia fattoria a nord, i Dead Fields. Abbiamo inviato piccoli assalti contro di loro, ma ogni volta ricevono rinforzi dalla banshee Nightlash, che usa la sua magia per mettere in rotta le nostre forze.$B$BVogliamo Nightlash distrutta.$B$BVai ai Dead Fields e assalta i rot hide. Se non vedi Nightlash, uccidi i rot hide finché non appare, poi sconfiggila.$B$BLa sua essenza si trasformerà in polvere. Portami quella polvere come prova.",
  obj = "Uccidi i gnoll rot hide ai Dead Fields.$B$BQuando appare Nightlash, uccidila.$B$BPorta l'Essence of Nightlash a High Executor Hadrec al Sepulcher.",
  progress = "Hai sconfitto Nightlash, $N? Il nostro successo contro i rot hide dipende dalla sua distruzione!",
  reward = "Ho saputo della tua incursione riuscita contro i rot hide, $N, e questa essenza è la prova della morte di Nightlash.$B$BOggi lo Scourge ha perso terreno. Il tuo valore per i Reietti cresce.",
  en_title = "The Dead Fields",
  en_obj = "Kill rot hide gnolls at the Dead Fields.$B$BWhen Nightlash appears, kill her.$B$BBring the Essence of Nightlash to High Executor Hadrec at the Sepulcher.",
}
T[438] = {
  title = "Il Decrepit Ferry",
  desc = "$N, abbiamo scoperto un nuovo alveare della Scourge: il Decrepit Ferry. Il traghetto si trova a est del Sepulcher ed è pesantemente pattugliato da rot hide e altri non morti.$B$BDeve esserci un motivo per cui la Scourge occupa la zona. Vai al Decrepit Ferry e scopri perché si trovano là.",
  obj = "Vai al Decrepit Ferry.$B$BCerca il motivo per cui la Scourge si trova là.",
  reward = "Su questa barca è ammassata una pila di cadaveri avvolti. E guardando a est, oltre il Lordamere Lake, si scorge un molo opposto sulla Fenris Isle.$B$BIl destino di questi cadaveri deve essere legato alla Fenris Isle.",
  en_title = "The Decrepit Ferry",
  en_obj = "Go to the Decrepit Ferry.$B$BSearch for the reason the Scourge are there.",
}
T[439] = {
  title = "Indizi sui Rot Hide",
  desc = "Tra i cadaveri sporge una mano, non avvolta. È la mano di una donna, segnata dalla peste ma relativamente fresca.$B$BAl dito porta un anello. Toglierlo e ispezionarlo rivela un'incisione:$B$B\"Per Deliah\"",
  obj = "Porta l'anello di Deliah a High Executor Hadrec al Sepulcher.",
  progress = "$N. Sei tornat$Go:a;, quindi suppongo che le tue indagini abbiano dato frutti?",
  reward = "Dici che questo anello apparteneva a una donna uccisa di recente?$B$BL'unica fonte vicina di un cadavere simile sarebbero le fosse comuni di Tirisfal. I Rot Hide Gnoll devono portare quei corpi a Fenris Isle!",
  en_title = "Rot Hide Clues",
  en_obj = "Bring Deliah's Ring to High Executor Hadrec at the Sepulcher.",
}
T[440] = {
  title = "L'anello inciso",
  desc = "Se vuoi trovare il marito o l'amato che ha donato a Deliah il suo anello... parla con il Magistrate Sevren a Brill. Dovrebbe avere i registri dei decessi recenti e, con un po' di fortuna, potrà scoprire chi fosse Deliah.$B$BMa non farei troppo affidamento. Chiunque le abbia dato l'anello è probabilmente morto. O, se è non morto, probabilmente non si cura più di Deliah.",
  obj = "Porta l'anello di Deliah al Magistrate Sevren a Brill.",
  progress = "Salve, $N. Cosa ti riporta a Brill?",
  reward = "Una Deliah viveva davvero a Brill non molto tempo fa. Fu sepolta nella fossa comune, ma se ciò che dici è vero, i Rot Hide Gnoll devono aver rubato il suo corpo e averlo portato a Silverpine.$B$BI Rot Hide, come tutta la Scourge, devono essere distrutti. Confido che tu stia facendo il necessario perché accada.",
  en_title = "The Engraved Ring",
  en_obj = "Bring Deliah's Ring to Magistrate Sevren in Brill.",
}
T[441] = {
  title = "Raleigh e l'Undercity",
  desc = "Deliah aveva un marito, Raleigh, che ora dimora nell'Undercity. Se la Deliah che viveva a Brill è colei che possedeva questo anello, Raleigh lo saprà.$B$BRaleigh si trova nel Trade Quarter dell'Undercity.",
  obj = "Porta l'anello di Deliah a Raleigh.",
  progress = "Ti conosco?",
  reward = "Sì, questo anello era di mia moglie. Il suo fato è quello di tutti coloro che non resistono a questi tempi duri. Non provo nulla per la sua morte, né per la storia che racconti sul rapimento del suo corpo.$B$BTali sentimenti si sono raffreddati in me da tempo. Ma il desiderio brucia ancora nel mio cuore morto, $N.$B$BIl desiderio di vendetta.",
  en_title = "Raleigh and the Undercity",
  en_obj = "Bring Deliah's Ring to Raleigh.",
}
T[442] = {
  title = "Assalto alla Fenris Isle",
  desc = "È giunto il momento di assaltare la roccaforte del Flagello in Silverpine: la Fenris Isle.$B$BDevi tornare sull'isola e distruggere Thule Ravenclaw. Voglio la sua testa!$B$BQuesta missione è tanto pericolosa quanto vitale, $N. Non devi fallire.",
  obj = "Porta Thule's Head a High Executor Hadrec, al Sepulcher.",
  progress = "Non si può permettere al Flagello di restare in Silverpine, $N. Torna da me quando avrai la prova della morte di Thule.",
  reward = "La morte di Thule Ravenclaw non è stata cosa da poco, $N. Renferrel mi dice che le energie liberate quando hai distrutto Thule si sono sentite fin qui, al Sepulcher.$B$BLe tue azioni risuonano tra le file dei Reietti. Il tuo valore per noi cresce.",
  en_title = "Assault on Fenris Isle",
  en_obj = "Bring Thule's Head to High Executor Hadrec at the Sepulcher.",
}
T[443] = {
  title = "L'icore dei Rot Hide",
  desc = "Prima di lanciare un assalto a Fenris Isle, dobbiamo scoprire chi si nasconde dietro i rot hide gnoll. I nostri apothecary ritengono che la loro origine risieda nello strano fluido che scorre nei loro corpi.$B$BVai a Fenris Isle, a est del Decrepit Ferry, e raccogli l'icore dei rot hide dai gnoll che troverai. Portalo all'Apothecary Renferrel, di stanza fuori dal Sepulcher.",
  obj = "Porta 8 fiale di rot hide ichor all'Apothecary Renferrel al Sepulcher.",
  progress = "Hai l'icore dei rot hide, $N?",
  reward = "Molto bene. Questo icore ci aiuterà a comprendere la natura dei rot hide e forse ci mostrerà il loro punto debole...$B$B...se ne hanno uno.",
  en_title = "Rot Hide Ichor",
  en_obj = "Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher.",
}
T[444] = {
  title = "Le origini dei Rot Hide",
  desc = "Ho ridotto l'icore che mi hai portato e l'ho separato nei suoi componenti di base. I miei risultati non sono conclusivi, ma ho stabilito che nella creazione dell'icore furono usate magie da warlock e negromantiche.$B$BMentre continuo a studiarlo, voglio che porti un campione a Bethor Iceshard nell'Undercity. Bethor non è un apothecary, ma la sua conoscenza della magia potrebbe aiutare a svelare il mistero dei rot hide.$B$BVai. Troverai Bethor nel Magic Quarter dell'Undercity.",
  obj = "Porta il Sample Ichor a Bethor Iceshard nell'Undercity.",
  progress = "I miei studi richiedono grande concentrazione. Spero dunque che la tua visita non sia frivola.",
  reward = "Questa sostanza è intrisa di potenti incantesimi, alcuni dei quali non vedevo da molto, molto tempo...$B$BUn momento: devo invocare un incantesimo di divinazione...",
  en_title = "Rot Hide Origins",
  en_obj = "Bring the Sample Ichor to Bethor Iceshard in the Undercity.",
}
T[445] = {
  title = "Consegna a Silverpine Forest",
  desc = "Il tempo è un lusso che non è concesso a noi al servizio di Lady Sylvanas. Di certo ormai lo sai.$B$BIn quanto membro della Royal Apothecary Society, è mio dovere condividere la mia conoscenza con i colleghi, affinché i nostri sforzi collettivi possano un giorno donare alla Dark Lady la Nuova Piaga che tanto desidera.$B$BPorta questi risultati all'Apothecary Renferrel, di stanza al Sepulcher in Silverpine Forest. Segui le strade a sud di Brill. Dall'Undercity vai a sudovest.",
  obj = "Porta i risultati dell'Apothecary Johaan all'Apothecary Renferrel a Silverpine Forest.",
  progress = "Che affari hai con me, $C?",
  reward = "Ah, che gentile l'Apothecary Johaan a inviare la sua ricerca. Con tante novità qui a Silverpine, avevo quasi dimenticato i risultati che arrivano da Lordaeron e Tirisfal Glades. Il che mi ricorda che devo spedire presto quei campioni alla Necropolis.$B$BMa perdona le mie divagazioni. Trattieniti a Silverpine, $N. Un $C valente come te ci farebbe comodo da queste parti.",
  en_title = "Delivery to Silverpine Forest",
  en_obj = "Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest.",
}
T[446] = {
  title = "Thule Ravenclaw",
  desc = "Questo icore fu creato da un mio vecchio collega: Thule Ravenclaw. Era un giovane e promettente mago prima della grande guerra, ma quando il Lich King salì al potere tradì i suoi fratelli e si alleò con la Scourge.$B$BNon sapevo che fosse ancora vivo, né che guidasse i Rot Hide nelle loro incursioni contro di noi!$B$BConosco molti dei suoi incantesimi e posso aiutare a preparare una pozione per contrastarli. Porta questa pergamena all'Apothecary Renferrel. Contiene le formule necessarie per la pozione.",
  obj = "Porta la Bethor's Scroll all'Apothecary Renferrel al Silverpine Sepulcher.",
  progress = "Salute, $N. Cos'ha detto Bethor?",
  reward = "Questa pergamena è intrisa di potente magia. Non ho mai usato forze simili in una pozione... sarà una miscela potente e ti sarà d'aiuto se attaccherai Thule nella sua roccaforte su Fenris Isle.",
  en_title = "Thule Ravenclaw",
  en_obj = "Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher.",
}
T[447] = {
  title = "Una ricetta per la morte",
  desc = "I numeri di Arthas sono schiaccianti. Ma con una Nuova Piaga potremmo sradicare una volta per tutte sia l'esercito della Scourge sia l'infestazione degli Umani.$B$BI miei studi hanno dimostrato che il sangue di ragno unito a una tossina derivata dal cuore di un orso grizzled produce un elisir mortale. Raccogli campioni dai ragni dello Skittering Dark a nordovest e dagli orsi che vagano per Silverpine Forest. Consegna i reagenti al Master Apothecary Faranell della Royal Apothecary Society nell'Undercity.",
  obj = "Raccogli 6 Grizzled Bear Heart e 6 campioni di Skittering Blood e consegnali al Master Apothecary Faranell nell'Undercity.",
  progress = "Salute, $C. Che affari hai con la Royal Apothecary Society?",
  reward = "Che gentile l'Apothecary Renferrel a mandarti da me, $N. Questi campioni saranno davvero utili alla causa. Inizierò subito a studiarne le proprietà tossiche e contaminanti.",
  en_title = "A Recipe For Death",
  en_obj = "Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.",
}
T[448] = {
  title = "Riferisci a Hadrec",
  desc = "Prima di lanciare un assalto a Fenris Isle, riferisci a High Executor Hadrec. Potrebbe avere altre informazioni o equipaggiamento di cui avrai bisogno.",
  obj = "Riferisci a High Executor Hadrec al Sepulcher.",
  reward = "Se ciò che dice Bethor è vero, Thule Ravenclaw è una forza con cui bisogna fare i conti, e presto.$B$BPer aiutarti in questo compito, puoi prendere qualcosa dal nostro arsenale...",
  en_title = "Report to Hadrec",
  en_obj = "Report to High Executor Hadrec at the Sepulcher.",
}
T[449] = {
  title = "Il rapporto dei Deathstalker",
  desc = "Anche se le ferite di Quinn stanno guarendo, voglio che il nostro rapporto giunga a High Executor Hadrec il più in fretta possibile. Contiene informazioni vitali per l'occupazione di Silverpine da parte dei Forsaken.",
  obj = "Porta il Deathstalker Report a High Executor Hadrec al Sepulcher.",
  progress = "Hai scoperto la sorte dei Deathstalker?",
  reward = "Non avevo messo in conto il livello di presenza della Scourge a Silverpine Forest, né le difficoltà che i nostri Deathstalker hanno incontrato nelle loro ricognizioni.$B$BIl tuo aiuto ai nostri Deathstalker è stato prezioso, $N. E verrai encomiato.",
  en_title = "The Deathstalkers' Report",
  en_obj = "Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher.",
}
T[450] = {
  title = "Una ricetta per la morte",
  desc = "Puoi servire ancora la Royal Apothecary Society, $N.$B$BQuando Arugal lanciò la sua magia nefasta sulla foresta, maledisse uno dei nostri membri più promettenti, l'Apothecary Berard. Ora, servo senza mente di Arugal, Berard è inutile per noi. Ma le sue ricerche potrebbero avere valore. Studiava un'antica piaga che millenni fa sterminò ogni vita acquatica nel Lake Lordamere.$B$BRecupera il Berard's Journal dal suo studio nella Pyrewood Village Inn e portalo all'Apothecary Renferrel.",
  obj = "Recupera il diario dell'Apothecary Berard a Pyrewood Village e portalo all'Apothecary Renferrel al Sepulcher.",
  progress = "Vedo che sei tornat$Go:a;, $N.",
  reward = "Il diario dell'Apothecary Berard! Sei davvero coraggios$Go:a;, $N. Vediamo dunque cosa tramava Berard prima di impazzire...",
  en_title = "A Recipe For Death",
  en_obj = "Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher.",
}
T[451] = {
  title = "Una ricetta per la morte",
  desc = "Secondo il diario di Berard, il muschio dei Lake Skulker e dei Creeper potrebbe rivelarsi utile nella nostra impresa di preparare una nuova piaga. Quelle bestie abitano le isole del Lake Lordamere, a est.$B$BMenziona anche un Hardened Tumor molto raro, scoperto su un murloc Vile Fin. A quanto pare il tumore è così raro che Berard ne ottenne uno solo.$B$BRaccogli campioni del muschio e il raro tumore indurito e portali al Master Apothecary Faranell nell'Undercity.",
  obj = "Porta 6 campioni di Lake Creeper Moss, 6 campioni di Lake Skulker Moss e un Hardened Tumor al Master Apothecary Faranell nell'Undercity.",
  progress = "Cosa ti riporta nell'Undercity, $N?",
  reward = "Che colpo per la Royal Apothecary Society perdere Berard. Ma grazie al tuo duro lavoro e alla diligente ricerca dell'Apothecary Renferrel, gli studi di Berard saranno comunque utili alla causa della Dark Lady.$B$BSiamo sull'orlo di qualcosa di grande, $N. Se non fossi così abile nell'arte del combattimento, cercherei di reclutarti nella Society.",
  en_title = "A Recipe For Death",
  en_obj = "Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.",
}
T[452] = {
  title = "Imboscata a Pyrewood",
  desc = "Sei arrivat$Go:a; appena in tempo, $N!$B$BIl Pyrewood Council tornerà da un momento all'altro. Arugal ha altre faccende da sbrigare nella fortezza. Usa il Council come semplici marionette per tenere sotto controllo i servi senza mente di Pyrewood. Ma credo che, senza la guida del Pyrewood Council, i figli di Arugal si rivolteranno contro il loro padrone.$B$BNon posso occuparmi di tutti da sola. Ho bisogno del tuo aiuto. Insieme possiamo annientare il Council per Lady Sylvanas.",
  obj = "Aiuta Deathstalker Faerleia a uccidere il Pyrewood Council.",
  reward = "Hai combattuto come un vero discepolo della Dark Lady, $N. Con il consiglio morto, forse potremo prendere il controllo di questa città una volta per tutte e scacciare Arugal da Shadowfang Keep. Ti saluto!",
  en_title = "Pyrewood Ambush",
  en_obj = "Help Deathstalker Faerleia kill the Pyrewood Council.",
}
T[453] = {
  title = "Trovare la Shadowy Figure",
  desc = "Buona fortuna, $N. Spero che tu trovi quel tipo, e spero che tu lo trovi vivo.$B$BSe ha lasciato la sicurezza di Darkshire, può essere finito preda delle bestie selvatiche.",
  obj = "Trova la Shadowy Figure. I tuoi indizi:$B$BNon è di Darkshire.$B$BÈ una persona nervosa e agitata.$B$BHa lasciato Darkshire ed è andato a ovest.",
  progress = "Chi sei?? Lasciami in pace!",
  reward = "<Jitters sospira...>$B$BSì, sono io l'autore di quel libro. Alla fine mi hai trovato, eh?$B$BBe', se hai letto quel diario... allora ne sai solo metà!",
  en_title = "Finding the Shadowy Figure",
  en_obj = "Find the Shadowy Figure.  Your clues:$B$BHe is not native to Darkshire.$B$BHe is a nervous, jittery person.$B$BHe left Darkshire and headed west.",
}
T[454] = {
  title = "Dopo l'imboscata",
  desc = "Prima di questa... faccenda, portavamo i barili di polvere avanti e indietro in più viaggi. Ora dobbiamo dividerci il lavoro: Miran porta i barili e io sorveglio gli altri.$B$BNon mi sento tranquillo a lasciare che Miran trasporti da solo il resto del carico. Quando è pronto a partire, potresti scortarlo nel prossimo viaggio?",
  obj = "Parla con Miran.",
  reward = "Salve, $C.$B$BMi scorterai tu fino al sito di scavo? Mi fa piacere sentirlo... Dopo Saean e i suoi compari, chissà cos'altro hanno in serbo i Dark Iron?$B$BComunque, lasciami fare gli ultimi controlli. Parlami di nuovo quando sei pront$Go:a; a partire.",
  en_title = "After the Ambush",
  en_obj = "Speak with Miran.",
}
T[455] = {
  title = "Il varco di Algaz",
  desc = "Gli orchi del clan Dragonmaw hanno un rifugio nelle Wetlands. E adesso si sono estesi dentro Dun Algaz! Non possiamo lasciare che mantengano questo appiglio, o Loch Modan resterà tagliato fuori da Menethil Harbor, il nostro porto e la nostra roccaforte nelle Wetlands.$B$BSfonda attraverso Dun Algaz fino alle Wetlands di là, e già che ci sei uccidi qualche orco! Presentati a Valstag Ironjaw, a Menethil Harbor.$B$BMenethil si raggiunge attraverso Dun Algaz, poi a nord lungo la strada, poi a ovest al bivio.$B$BContiamo su di te, $N. Non fallire.",
  obj = "Attraversa Dun Algaz.$B$BUccidi 8 Dragonmaw Scout e 6 Dragonmaw Grunt.$B$BPresentati a Valstag Ironjaw, a Menethil Harbor.",
  progress = "Vieni da Loch Modan? Com'è la situazione degli orchi all'Algaz Gate?",
  reward = "Il tuo rapporto è pieno di brutte notizie!$B$BVedo che i Dragonmaw stanno facendo una mossa decisa dentro Algaz. Di solito i Dragonmaw se ne stanno nascosti sulle colline. Cosa li abbia spinti a riversarsi su Algaz resta un mistero...$B$BGrazie, $N. E probabilmente vorremo il tuo aiuto per occuparci di questi orchi.",
  en_title = "The Algaz Gauntlet",
  en_obj = "Traverse Dun Algaz.$B$BKill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.$B$BReport to Valstag Ironjaw in Menethil Harbor.",
}
T[456] = {
  title = "L'equilibrio della natura",
  desc = "Salute, $N. Sono Conservator Ilthalaine. Il mio compito a Shadowglen è garantire che l'equilibrio della natura sia preservato.$B$BQuest'anno le piogge primaverili sono state particolarmente abbondanti, facendo prosperare alcune bestie della foresta mentre altre soffrivano.$B$BPurtroppo le popolazioni di nightsaber e thistle boar sono cresciute troppo. Shadowglen può produrre solo una certa quantità di cibo per le bestie. Parti, giovane $c, e riduci le popolazioni di cinghiali e sabre affinché l'armonia della natura sia preservata.",
  obj = "Uccidi 7 Young Nightsaber e 4 Young Thistle Boar e torna da Conservator Ilthalaine.",
  progress = "C'è ancora del lavoro da fare, $N. Torna da me quando avrai ridotto le popolazioni di nightsaber e thistle boar.",
  reward = "Hai svolto bene il tuo dovere, $N.",
  en_title = "The Balance of Nature",
  en_obj = "Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.",
}
T[457] = {
  title = "L'equilibrio della natura",
  desc = "Diradare i giovani esemplari di creature qui a Shadowglen è stato un buon inizio, $N, ma c'è ancora del lavoro da fare.$B$BLe risorse della foresta si esauriranno troppo in fretta se non affrontiamo il problema. Uccidere le bestie della natura è un male necessario, per il bene di tutti coloro che condividono questa terra. Addentrati nella foresta e abbatti i Mangy Nightsaber e i Thistle Boar in nome dell'equilibrio.",
  obj = "Conservator Ilthalaine ha bisogno che tu uccida 7 Mangy Nightsaber e 7 Thistle Boar.",
  progress = "Il tuo compito non è ancora concluso, $N. Torna da me quando avrai ucciso 7 Mangy Nightsaber e 7 Thistle Boar.",
  reward = "Hai dimostrato di essere davvero devot$Go:a; alla natura, $N. Un giovane $C come te ha un futuro promettente.",
  en_title = "The Balance of Nature",
  en_obj = "Conservator Ilthalaine needs you to kill 7 Mangy Nightsabers and 7 Thistle Boars.",
}
T[458] = {
  title = "La protettrice del bosco",
  desc = "Grazie al cielo sei qui, $C. Strane notizie mi sono giunte attraverso i sussurri degli spiriti della foresta.$B$BLa misteriosa protettrice del bosco, Tarindrella, è tornata a Shadowglen. La presenza della driade non si avvertiva nelle foreste di Kalimdor da anni. Dev'esserci certamente qualcosa che non va, se è tornata in queste terre.$B$BCerca Tarindrella e scopri quali affari la portano nel nostro bosco. Una delle Sentinelle dice di averla vista a sudovest di Aldrassil.",
  obj = "Cerca la driade conosciuta come Tarindrella.",
  reward = "Vedo che mi hai trovata, giovane $R. Melithar è un saggio druido ad averti mandat$Go:a;.",
  en_title = "The Woodland Protector",
  en_obj = "Seek out the dryad known as Tarindrella.",
}
T[459] = {
  title = "La protettrice del bosco",
  desc = "Qualcosa di malvagio sta prendendo forma nelle foreste di Teldrassil. Guarda oltre le colline, dove un tempo vivevano i pacifici furbolg. Hanno abbandonato le loro case e si stanno radunando sotto il nome di tribù Gnarlpine.$B$BSolo la corruzione del malvagio Fel Moss può aver causato una simile trasformazione. I grell e i grellkin hanno infestato la zona e minacciano gli abitanti di Shadowglen.$B$BAffronta questi grell e grellkin, $N, e scopri se sono davvero caduti sotto l'incantesimo del malvagio Fel Moss.",
  obj = "Raccogli 8 Fel Moss e portali a Tarindrella.",
  progress = "Dissipa i miei sospetti, $N. Portami 8 Fel Moss.",
  reward = "Il tuo servizio alle creature di Shadowglen merita una ricompensa, $N.$B$BHai confermato i miei timori, però. Se i grell sono stati corrotti dal Fel Moss, si può solo immaginare cosa ne sia stato della tribù Gnarlpine dei furbolg che un tempo viveva qui.$B$BSe ti trovassi a Dolanaar, abile $C, cerca il sapiente druido Athridas Bearmantle. Condivide la nostra preoccupazione per il benessere della foresta.",
  en_title = "The Woodland Protector",
  en_obj = "Collect 8 Fel Moss and bring them to Tarindrella.",
}
T[460] = {
  title = "Riposare in pace",
  desc = "Non sembri un Rot Hide. Bene. Avevo perso la speranza...$B$BMi chiamo Alaric, e un tempo ero il servitore capo e la guardia del corpo di Thule. Usò la sua magia per \"proteggermi\" dalla Piaga della Non Morte, ma il suo incantesimo mi ha dato una non vita da cui non posso fuggire. E dopo aver creato i maledetti gnoll Rot Hide, Thule mi decapitò... e diede la mia testa agli gnoll come giocattolo!$B$BTi prego, portami al mio corpo. Credo che gli gnoll l'abbiano seppellito qui a Fenris Keep, vicino alle stalle, in una tomba senza nome.",
  obj = "Porta la testa di Alaric alla sua tomba.",
  progress = "Questa tomba è stata scavata in fretta.",
  reward = "Grazie, $N. Temevo che gli gnoll avessero distrutto il mio corpo. È bello sapere che non l'hanno fatto.",
  en_title = "Resting in Pieces",
  en_obj = "Bring Alaric's Head to his grave.",
}
T[461] = {
  title = "La nicchia nascosta",
  desc = "So di una nicchia nascosta nella fortezza che custodisce un oggetto caro a Thule e ai suoi vecchi colleghi. Contiene anche qualcosa che potresti trovare utile. Portami là!$B$BL'alcova si trova nella torre sudoccidentale della fortezza, dietro uno scaffale polveroso.$B$BPrendi il mio corpo, ma lascia i miei stivali. Non mi sono mai andati bene, comunque...",
  obj = "Porta Alaric alla nicchia nascosta.",
  progress = "Questo è il posto! Avvicinami ancora...",
  reward = "Ecco fatto, si è aperta. Lasciami qui. Ho trascorso i migliori giorni della mia vita in questa fortezza, e il pensiero di riposare tra le sue mura mi dà conforto.$B$BAssicurati di chiudere bene l'alcova: non voglio che i Rot Hide mi trovino.$B$BOh, e prendi questo. Te lo sei guadagnato.",
  en_title = "The Hidden Niche",
  en_obj = "Take Alaric to the hidden alcove.",
}
T[463] = {
  title = "Il Greenwarden",
  desc = "Hai sentito parlare del Greenwarden? Non è che lo stai cercando, vero? Be', io dico che sei $Gpazzo:pazza; se è così, ma chi sono io per impedire a $Gun folle:una folle; di andare incontro alla sua morte?$B$BSe cerchi quella bestia, ho sentito dire che sta nella palude, a est della strada dove si biforca per Dun Modr. Se ne sta in agguato là in mezzo ai crocolisk... e a cose peggiori!$B$BE lascia qui i tuoi soldi. Dove stai andando non ti serviranno... e non vorrai scheggiare un dente al vecchio Greenie con il tuo oro, quando ti morderà in due, vero?",
  obj = "Trova il Greenwarden.",
  reward = "Le radici e le felci parlano bene di te, $Gpiccolo:piccola;. Ho molti nomi, ma rispondo solo a pochi. Tu però puoi chiamarmi Rethiel.$B$BE devi ascoltare... perché queste terre piangono da ferite infette, e io ti affiderei il compito di risanarle.",
  en_title = "The Greenwarden",
  en_obj = "Find the Greenwarden.",
}
T[464] = {
  title = "Stendardi di guerra",
  desc = "Il clan orchesco Dragonmaw fu quasi distrutto alla fine della Seconda Guerra, dopo che perse il controllo dei suoi draghi rossi addomesticati. I draghi non erano molto contenti dei loro vecchi padroni, e diedero ai Dragonmaw una caccia feroce. I pochi rimasti fuggirono da Grim Batol e si rifugiarono sulle montagne a est della Whelgar's Excavation.$B$BOra hanno ripreso forza e hanno un accampamento a nord-est di Menethil.$B$BVogliamo che tu attacchi quell'accampamento. Raccogli e portami i loro stendardi di guerra come prova.",
  obj = "Porta 8 Dragonmaw War Banner a Captain Stoutfist.",
  progress = "Hai attaccato l'accampamento dei Dragonmaw?",
  reward = "Ben combattuto, $N. I Dragonmaw non sono la minaccia che erano quando avevano i draghi, ma restano avversari feroci.$B$BI Dragonmaw sono guidati da Nek'rosh, figlio di Nekros, che anni fa era a capo dei Dragonmaw. Nekros usò una magia potente per domare i Red Dragon, ma quando quella magia gli venne meno... i draghi non furono contenti.$B$BNekros fu ucciso, e suo figlio ha giurato vendetta contro i draghi che uccisero suo padre.",
  en_title = "War Banners",
  en_obj = "Bring 8 Dragonmaw War Banners to Captain Stoutfist.",
}
T[465] = {
  title = "La mossa di Nek'rosh",
  desc = "Mentre combattevi i Dragonmaw, abbiamo scoperto altri dei loro piani.$B$BNek'rosh ha costruito catapulte e punta ad assediare Menethil! E con i combattimenti a Dun Algaz siamo di fatto tagliati fuori dai rinforzi!$B$BDevi eliminare quelle catapulte. Sono nell'accampamento dei Dragonmaw.$B$BEcco, prendi quest'esca. Apriti la strada fino alle catapulte e dai loro fuoco con l'esca.$B$BE quando l'avrai fatto, trova e uccidi Nek'rosh. Dobbiamo tagliare la testa a questa bestia dei Dragonmaw.",
  obj = "Distruggi le catapulte dei Dragonmaw.",
  progress = "La prima catapulta è davanti a te. Le darai fuoco?",
  reward = "Metti un po' di esca sulla catapulta, poi fai scoccare una scintilla.$B$BLa fiamma divampa e si propaga in fretta!",
  en_title = "Nek'rosh's Gambit",
  en_obj = "Destroy the Dragonmaw catapults.",
}
T[466] = {
  title = "Alla ricerca dell'incendicite",
  desc = "Ho sentito che un minerale raro, l'incendicite, è stato trovato nelle Wetlands, in una caverna a nord-ovest di Algaz Gate. L'incendicite è roba instabile e difficile da usare senza saltare in aria, ma sono sicuro che, fuso nel modo giusto, potrebbe dare proiettili da cannone con una potenza formidabile!$B$BPortami del minerale di incendicite e troverò qualcuno abbastanza coraggioso da sperimentarlo.$B$BAh, e per estrarre il minerale da un filone ti servirà l'abilità di estrazione. Se non ce l'hai... porta in quella caverna un amico che ce l'ha!",
  obj = "Porta 6 carichi di Incendicite Ore a Pilot Stonegear a Dun Morogh.",
  progress = "Dov'è quel minerale, $N?!",
  reward = "Hai il minerale! Ben fatto, $N! Lo farò lavorare subito da qualcuno. Speriamo che non salti in aria!",
  en_title = "Search for Incendicite",
  en_obj = "Bring 6 loads of Incendicite Ore to Pilot Stonegear in Dun Morogh.",
}
T[467] = {
  title = "La ricerca di Stonegear",
  desc = "Pilot Stonegear ama la sua macchina d'assedio, come ogni pilota dovrebbe! Ed è sempre in cerca di nuovi modi per aumentarne la potenza di fuoco!$B$BHa sentito voci su un minerale raro e cerca qualcuno che lo trovi per lui. Se ti prudono i piedi dalla voglia di partire, cerca Stonegear a Steelgrill's Depot, a Dun Morogh, e senti cosa vuole.",
  obj = "Parla con Pilot Stonegear.",
  reward = "Salve, $N. Sei qui per l'incarico che ho, eh? Fa piacere vedere $Gun:una; giovane $R come te a cui ribolle il sangue all'idea dell'avventura!",
  en_title = "Stonegear's Search",
  en_obj = "Speak with Pilot Stonegear.",
}
T[468] = {
  title = "Presentati a Mountaineer Rockgar",
  desc = "Mountaineer Rockgar cerca volontari per una missione attraverso Dun Algaz e dentro le Wetlands.$B$BSe vuoi bagnarti gli stivali in quella contea fradicia a nord, parla con Rockgar a Dun Algaz. Dun Algaz è a nord lungo la strada, oltre la torre di guardia.",
  obj = "Parla con Mountaineer Rockgar.",
  reward = "Salve, $C! Sei qui per la missione di ricognizione, vero? Benissimo!$B$BSpero che il tuo equipaggiamento sia in buone condizioni, perché questa missione \"di ricognizione\" si è trasformata in qualcosa di più sporco...",
  en_title = "Report to Mountaineer Rockgar",
  en_obj = "Speak with Mountaineer Rockgar.",
}
T[469] = {
  title = "Consegna quotidiana",
  desc = "Salve, $Gviaggiatore:viaggiatrice;!$B$BNon è che per caso stai andando verso Menethil? Se non ci vai, ti consiglierei di fermartici: è un buon posto per comprare provviste e anche per farsi una pinta e rilassarsi.$B$BOra, se per caso stai andando proprio da quelle parti, non ti dispiacerebbe portare questo fascio di pelli di crocolisk a James Halloran, il conciatore?$B$BLo farei io, ma mia moglie è di pessimo umore ultimamente, e vorrei rimandare il più possibile il momento di affrontarla.",
  obj = "Consegna il Bundle of Crocolisk Skins a James Halloran, il conciatore, a Menethil Harbor.",
  progress = "Salve, $C. Posso interessarti un paio di stivali? O magari delle pelli conciate di fresco?",
  reward = "Mmh, questo viene da Einar, giusto? È quasi una settimana che non mi porta le pelli di persona. Di sicuro sono screzi con la moglie!$B$BForse prima o poi manderò mia moglie a parlare con Sida...",
  en_title = "Daily Delivery",
  en_obj = "Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.",
}
T[470] = {
  title = "A frugare nella melma",
  desc = "Durante la mia visita settimanale all'Ironbeard's Tomb sono stata attaccata da orribili melme gocciolanti! Naturalmente sono andata nel panico.$B$BHo tirato la mia borsa addosso a una di loro, ma non è servito a niente! La melma se l'è risucchiata... Per fortuna mi ha dato il tempo di scappare.$B$BLa brutta notizia è che mi serve davvero il contenuto della borsa!$B$BNon so a quale melma ho tirato la borsa: erano tutte identiche! L'Ironbeard's Tomb è a nord-est di qui, vicino a Dun Modr. Grazie infinite!",
  obj = "Una delle melme all'Ironbeard's Tomb ha Sida's Bag: recuperala e riportagliela a Menethil Harbor.",
  progress = "Hai trovato la mia borsa?",
  reward = "Oh, grazie, $N! Temevo che fosse persa per sempre!$B$B<Svuota in fretta sul terreno il contenuto della borsa ricoperta di melma, poi lo raccoglie.>$B$BMmh, a me non serve più granché, ma lavalo bene e sono sicura che potrai farne buon uso.",
  en_title = "Digging Through the Ooze",
  en_obj = "One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor.",
}
T[471] = {
  title = "I doveri dell'apprendista",
  desc = "Ho mandato il mio apprendista nelle paludi a scuoiare qualcuno dei nostri famosi crocolisk giganti delle Wetlands. Quando non è tornato, sono andato a cercarlo... Diciamo che non è stato un bello spettacolo.$B$BLa levatrice dice che potrebbe cavarsela, ma intanto a me servono ancora le pelli!$B$B...Se ti va di ucciderne qualcuno in più, di quei bruti, non avrei niente in contrario, dopo quello che hanno fatto. I crocolisk li trovi a nord lungo la costa, oltre le capanne dei murloc.",
  obj = "Raccogli 6 Giant Crocolisk Skin e portale a James Halloran, a Menethil Harbor.",
  progress = "Il mio apprendista è come un figlio per me. Sarà dura per lui vivere con una gamba sola.$B$BAh, $N, come va? Hai le mie pelli?",
  reward = "Mmh... Non è che ti interesserebbe diventare il mio apprendista, vero?$B$BAh! No, sto scherzando. Sei troppo $Gvecchio:vecchia;, tanto per cominciare. E poi, a vederti, sembra che tu abbia altre ambizioni nella vita. Comunque, queste pelli che hai procurato sono ottime, e saprò farne buon uso.",
  en_title = "Apprentice's Duties",
  en_obj = "Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.",
}
T[472] = {
  title = "La caduta di Dun Modr",
  desc = "Dun Modr è caduta in mano ai Dark Iron Dwarf!$B$BLe mie ferite sono gravi, $C. Gran parte del reggimento è stata uccisa! I bruti Dark Iron ci hanno attaccati prima che potessimo riorganizzarci dopo l'imboscata del Thandol Span.$B$BIl nostro comandante, Longbraid, ha suonato il corno della ritirata. Mentre lasciavamo la città sono stato colpito alla schiena da un'ascia vagante. È andato tutto nero.$B$BMi sono svegliato qui a Menethil, ma temo per i miei compagni soldati. Dentro di me arde ancora la speranza. Forse Longbraid è ancora vivo! Vedi se riesci a trovarlo vicino a Dun Modr, $R!",
  obj = "Cerca Longbraid vicino alla città di Dun Modr.",
  reward = "Quale $C $Gcoraggioso:coraggiosa; porta notizie da Menethil? Ah, ti chiamano $N.$B$BPorti speranza in una situazione senza speranza. È davvero una buona notizia che il giovane Harlo sia sopravvissuto. Mentre fuggiva ha ricevuto una ferita grave. Avevamo pochissimo tempo per mandarlo via sulla groppa dell'unico destriero rimasto al reggimento.$B$BMa ora ci troviamo in una situazione pericolosa. Dun Modr è caduta e siamo solo l'ombra del grande reggimento che eravamo.",
  en_title = "Fall of Dun Modr",
  en_obj = "Search for Longbraid near the town of Dun Modr.",
}
T[473] = {
  title = "Presentati a Captain Stoutfist",
  desc = "$N. Il clan orchesco Dragonmaw sta mostrando la sua forza non solo ad Algaz. Captain Stoutfist ha chiesto di parlare con chi è disposto a dare aiuto contro questi orchi. È dentro la fortezza, nella sala di guerra.",
  obj = "Parla con Captain Stoutfist.",
  reward = "$N. Valstag mi ha riferito i tuoi successi passati con gli orchi Dragonmaw a Dun Algaz. Sei $Gun:una; $R di valore.$B$BE ho un compito per te.",
  en_title = "Report to Captain Stoutfist",
  en_obj = "Speak with Captain Stoutfist.",
}
T[474] = {
  title = "Sconfiggi Nek'rosh",
  desc = "Ora che le catapulte sono state bruciate, trova e uccidi Chieftain Nek'rosh.",
  obj = "Uccidi Chieftain Nek'rosh.$B$BPorta Nek'rosh's Head a Captain Stoutfist.",
  progress = "Hai ucciso Nek'rosh?",
  reward = "Fatto con vigore, $N. Hai inferto un colpo decisivo al clan orchesco Dragonmaw. Forse non si riprenderanno mai. E la distruzione di quelle catapulte ha messo Menethil Harbor al sicuro.$B$BSei $Gun:una; $R di merito, e il regno di Ironforge ricompensa chi lo serve bene.",
  en_title = "Defeat Nek'rosh",
  en_obj = "Kill Chieftain Nek'rosh$B$BBring Nek'rosh's Head to Captain Stoutfist.",
}
T[475] = {
  title = "Una brezza inquietante",
  desc = "Una brezza inquietante soffia attraverso la foresta.$B$BGaerolas Talvethren è il Grande Custode dei druidi del Talon in letargo nel Ban'ethil Barrow Den. Il suo dovere di protettore prescelto dei Dormienti è garantire la loro sicurezza, così che il loro patto con Ysera resti rispettato.$B$BMa le notizie di Gaerolas tardano ad arrivare e io comincio a preoccuparmi. Viaggia a est fino a Starbreeze Village e portami un rapporto di Gaerolas, così che possa scacciare le mie ansie, sapendo che i miei fratelli sognanti dormono al sicuro.",
  obj = "Cerca Gaerolas Talvethren a Starbreeze Village.$B",
  reward = "Sia ringraziato lo spirito della foresta, sei qui! Sapevo che Athridas avrebbe percepito il pericolo e mandato aiuto.",
  en_title = "A Troubling Breeze",
  en_obj = "Seek out Gaerolas Talvethren in Starbreeze Village.$B",
}
T[476] = {
  title = "La corruzione dei Gnarlpine",
  desc = "La tribù Gnarlpine è stata corrotta!$B$BI furbolg un tempo pacifici si sono rivoltati contro i protettori della foresta. Mi hanno teso un'imboscata mentre partivo per il Ban'ethil Barrow Den e poi hanno saccheggiato Starbreeze Village. Ursal the Mauler, il loro capo, usa i malvagi poteri del Fel Moss per farli impazzire.$B$BSono troppo ferito per tornare da Athridas e portargli questa grave notizia. Il compito spetta a te, giovane $C. Possiamo solo sperare che i Gnarlpine deliranti non siano già arrivati a Ban'ethil!",
  obj = "Torna da Athridas Bearmantle a Dolanaar.",
  reward = "Per le stelle! Questo è davvero molto inquietante!",
  en_title = "Gnarlpine Corruption",
  en_obj = "Return to Athridas Bearmantle in Dolanaar.",
}
T[477] = {
  title = "Attraversare il confine",
  desc = "Come forse saprai, la città di Ambermill resta un fulcro di opposizione umana, soprattutto grazie al sostegno che riceve dai maghi di Dalaran.$B$BNon so quale sia il loro piano, ma il fatto che si interessino a un villaggio isolato come Ambermill indica che deve avere una qualche importanza maggiore.$B$BHanno spedito casse a carrettate da Hillsbrad. Molte di quelle provviste finiscono in un piccolo accampamento a nord di Pyrewood Village. Recupera il contenuto di una cassa e portamelo.",
  obj = "Recupera il contenuto di una delle casse dei maghi di Dalaran. Pyrewood Village si trova a sud.",
  reward = "<Forzando il coperchio della cassa, trovi un assortimento di oggetti imballati con cura. In cima alla cassa c'è un fascio di mappe ingiallite dal tempo, che sembrano raffigurare Silverpine Forest e altre zone della Lordaeron occidentale.$B$BSotto le mappe c'è un misterioso ciondolo magico.>",
  en_title = "Border Crossings",
  en_obj = "Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south.",
}
T[478] = {
  title = "Mappe e rune",
  desc = "<Estrai in fretta il ciondolo dalla cassa e rimetti a posto il coperchio.>",
  obj = "Porta lo strano ciondolo a Shadow Priest Allister al Sepulcher.",
  progress = "Hai scoperto qualcosa di utile, $N?",
  reward = "Mappe e questo... ciondolo, eh? Interessante.$B$BÈ evidente che i maghi di Dalaran siano interessati ad Ambermill per qualche scopo, ma il loro intento mi è ancora oscuro.$B$BForse Dalar saprà qualcosa sul loro utilizzo.",
  en_title = "Maps and Runes",
  en_obj = "Bring the strange pendant to Shadow Priest Allister at the Sepulcher.",
}
T[479] = {
  title = "Indagini su Ambermill",
  desc = "Dalar sta cercando di individuare la fonte degli incantesimi dei maghi. Per ora dovremo rallentare i loro progressi in ogni modo possibile...$B$BGli evocatori, i maghi e i protettori portano senza dubbio i ciondoli. Toglieteli e recuperali.$B$BPrendi la strada principale verso sud e poi la diramazione orientale per Ambermill.",
  obj = "Ottieni 8 Dalaran Pendant per Shadow Priest Allister al Sepulcher.",
  progress = "Dobbiamo sbrigarci: i loro piani non devono realizzarsi, o rischiamo di perdere la nostra presa su Silverpine Forest.",
  reward = "Dalar ha scoperto che la tessitura è già molto avanzata, nonostante la battuta d'arresto.$B$BUn mago di grande potere sta guidando l'energia magica. Va fermato in fretta.",
  en_title = "Ambermill Investigations",
  en_obj = "Obtain 8 Dalaran Pendants for Shadow Priest Allister at the Sepulcher.",
}
T[480] = {
  title = "Il Tessitore",
  desc = "Un arcimago di grande potere sta sovrintendendo alla riattivazione del nodo di energia ley. Con i progressi che hanno fatto, la nostra unica speranza di fermarli è ucciderlo. Sarà difficile: senza dubbio è protetto da molti altri maghi e guardiani.$B$BDevi andare, e devi eliminarlo in fretta. Quando sarà morto, recupera il suo bastone per me. Va', ora.",
  obj = "Uccidi l'arcimago di Dalaran, poi recupera il suo bastone per Shadow Priest Allister, al Sepulcher.",
  progress = "Presto, il tempo stringe, $N!",
  reward = "La magia dei maghi si dissolve e le energie ley tornano a sopirsi. I tuoi sforzi hanno dato frutto, $N, e abbiamo inferto un duro colpo ai nostri nemici e agli arroganti maghi di Dalaran.$B$BDobbiamo però restare vigili, sapendo che quella fonte di energia è così a portata di mano... Bisognerà fare piani per il futuro.",
  en_title = "The Weaver",
  en_obj = "Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher.",
}
T[481] = {
  title = "L'analisi di Dalar",
  desc = "Porta il ciondolo a Dalar Dawnweaver: forse potrà far luce sui piani dei maghi.",
  obj = "Porta il ciondolo inciso di rune a Dalar Dawnweaver al Sepulcher.",
  progress = "Sì, $C? Di che si tratta?",
  reward = "Interessante, a quanto pare altre macchinazioni del Kirin Tor. Questo è un potente artefatto. Veniva usato spesso dai potenti maghi del Kirin Tor per incanalare le energie magiche.$B$BIl fatto che ne consegnino così tanti ad Ambermill indica che devono star portando avanti un progetto di una certa portata.$B$BVedrò se riesco a penetrare le loro difese e a capire quali siano le loro intenzioni.",
  en_title = "Dalar's Analysis",
  en_obj = "Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher.",
}
T[482] = {
  title = "Le intenzioni di Dalaran",
  desc = "Ma certo! Come ho potuto dimenticarlo?$B$BAmbermill era uno dei siti designati dal Kirin Tor, notato perché ospita un nodo di energia ley dormiente. I maghi devono avere intenzione di riattivare il nodo e usarne le energie per qualche scopo più grande.$B$BNon possiamo permettere che accada...$B$BCi vorrà un'enorme quantità di potere per attivare le energie ley della zona: possiamo ritardarli sottraendo i ciondoli ai maghi.$B$BRiferisci queste informazioni ad Allister, sarà lui a decidere il da farsi.",
  obj = "Parla con Shadow Priest Allister al Sepulcher.",
  reward = "Porti cattive notizie, $N. Se Dalar ha ragione, e non ho motivo di credere il contrario, dobbiamo muoverci in fretta.$B$BDevo consultarmi con lui sul nostro piano d'attacco. Nel frattempo dovremo ritardare i loro progressi.",
  en_title = "Dalaran's Intentions",
  en_obj = "Speak with Shadow Priest Allister at the Sepulcher.",
}
T[483] = {
  title = "Le reliquie del risveglio",
  desc = "Degli invasori Gnarlpine sono stati visti devastare il Ban'ethil Barrow Den a ovest.$B$BI druidi addormentati resteranno intrappolati nell'Emerald Dream per l'eternità, ignari del loro destino, se non li aiutiamo. Il delicato rituale di ibernazione non può essere spezzato senza le Reliquie del Risveglio.$B$BRecati al Den e recupera il Raven Claw Talisman, la Black Feather Quill, lo Sapphire of Sky e la Rune of Nesting. I druidi li custodiscono in forzieri sacri. Portameli e io preparerò il rituale del risveglio.",
  obj = "Recupera le Reliquie del Risveglio e portale ad Athridas Bearmantle a Dolanaar.",
  progress = "$N, i Druids of the Talon rapiti resteranno per sempre intrappolati nell'Emerald Dream se non riusciremo a recuperare le Reliquie del Risveglio dal Ban'ethil Barrow Den, a ovest.$B$BOgni minuto di ritardo avvicina di un passo il loro destino di eterna rovina.",
  reward = "Ce l'hai fatta, giovane $C! Ben fatto. E proprio in tempo, aggiungerei.",
  en_title = "The Relics of Wakening",
  en_obj = "Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar.",
}
T[484] = {
  title = "Young Crocolisk Skins",
  desc = "Sono James Halloran, il conciatore. Le mie pelli di crocolisk conciate sono ricercate ovunque, e le spedizioni partono in nave per i porti di tutto il mondo.$B$BHai conosciuto Einar? È uno dei cacciatori che mi portano le pelli di crocolisk.$B$BSono un po' a corto delle pelli più morbide, quelle che vengono dai crocolisk giovani.$B$BVisto che ne ho poche, ti pago profumatamente per un mazzo di quelle pelli. I crocolisk giovani li trovi nelle paludi appena fuori città.",
  obj = "Procura 4 Young Crocolisk Skin a James Halloran, a Menethil Harbor.",
  progress = "$N, giusto? Hai le mie pelli?",
  reward = "Bel lavoro, $N. La qualità di queste pelli è ottima. Devo metterle in conciatura il prima possibile. Oh, ma prima di arrivare a quello, c'è un altro lavoro che mi serve e che credo tu possa sbrigare.",
  en_title = "Young Crocolisk Skins",
  en_obj = "Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor.",
}
T[486] = {
  title = "Ursal the Mauler",
  desc = "Ora è giunto il momento di salvare i Druids of the Talon. Se falliamo adesso, $N, saranno perduti per sempre nel sonno.$B$BPreparerò le Reliquie del Risveglio ed eseguirò il rituale. Perché la mia opera abbia effetto, la maledetta bestia responsabile di questa terribile situazione deve essere uccisa. Solo allora il rituale sarà completo.$B$BÈ stato Ursal the Mauler a interferire con la vocazione dei nostri fratelli, ed è Ursal the Mauler che ora deve pagare perché possano essere liberati. Recati a Gnarlpine Hold, a sudovest, e uccidilo.",
  obj = "Uccidi Ursal the Mauler e torna da Athridas Bearmantle a Dolanaar.",
  progress = "I nostri fratelli non possono essere risvegliati finché Ursal the Mauler non sarà stato ucciso, $N.",
  reward = "$N, ti sei dimostrat$Go:a; un $C davvero degno e capace. Un elfo della notte che segue la via dell'onore con la tua stessa fermezza troverà di certo grande gloria in questo mondo.$B$BChe gli spiriti della foresta ti proteggano ovunque i tuoi viaggi ti portino.",
  en_title = "Ursal the Mauler",
  en_obj = "Kill Ursal the Mauler and return to Athridas Bearmantle in Dolanaar.",
}
T[487] = {
  title = "La strada per Darnassus",
  desc = "La strada per Darnassus deve restare sicura. I viaggiatori diretti da Dolanaar a Darnassus segnalano spietati attacchi da parte dei furbolg corrotti della tribù Gnarlpine.$B$BNotizie importanti e commerci viaggiano ogni giorno da e per Darnassus lungo questa strada. Non possiamo permettere che una banda di eretici terrorizzi la gente.$B$BImbraccia le armi in nome della foresta sacra, $C. La loro tana si trova da qualche parte sotto questo punto di osservazione. Uccidi 6 di questi Gnarlpine Ambusher e torna da me.",
  obj = "Uccidi 6 Gnarlpine Ambusher e torna da Sentinel Amara Nightwalker fuori da Dolanaar.",
  progress = "La strada non è ancora sicura, $C. Parti e uccidi 6 Gnarlpine Ambusher, poi torna da me.",
  reward = "Hai servito bene la brava gente di Dolanaar e Darnassus, coraggios$Go:a; $C. Come membro delle forze Sentinel di Teldrassil, saluto i tuoi sforzi.",
  en_title = "The Road to Darnassus",
  en_obj = "Slay 6 Gnarlpine Ambushers and return to Sentinel Amara Nightwalker outside of Dolanaar.",
}
T[488] = {
  title = "Gli ordini di Zenn",
  desc = "Voglia di lavorare, vedo. Fortunato te: non passa giorno senza che io desideri avere un giovane $C a eseguire i miei ordini.$B$BVedi, $N, posso renderti molto felice e darti cose che non hai mai sognato di possedere. Ma perché accada, devi portarmi certi oggetti.$B$BI miei affari nella foresta richiedono spesso certi... reagenti. Portami 3 Nightsaber Fangs, 3 Strigid Owl Feathers e 3 swatches of Webwood Spider Silk.$B$BTeniamo questo come il nostro piccolo segreto, $R.",
  obj = "Porta a Zenn Foulhoof, fuori da Dolanaar, 3 Nightsaber Fangs, 3 Strigid Owl Feathers e 3 swatches of Webwood Spider Silk.",
  progress = "Sei stat$Go:a; un'ape molto operosa, $N? Aspettavo che mi portassi ciò di cui ho bisogno.",
  reward = "Ah ah! Davvero ben fatto.$B$BChi avrebbe mai immaginato che io, Zenn Foulhoof, avrei avuto un $R a eseguire i miei ordini? Certo non io! Ma così va... questo nostro amato mondo è pieno di sorprese.$B$BTre urrà per gli ingenui e i creduloni!",
  en_title = "Zenn's Bidding",
  en_obj = "Bring Zenn Foulhoof outside of Dolanaar 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.",
}
T[489] = {
  title = "Cerca la redenzione!",
  desc = "Il Council of the Forest ha saputo che hai aiutato Zenn Foulhoof. Il satiro è un nemico della foresta. Come $R, dovresti saperlo meglio: non si profana la foresta uccidendo le creature della Natura.$B$BDevi riscattarti agli occhi del Council se vuoi restare amic$Go:a; di Teldrassil.$B$BDai una lezione a Foulhoof e sarai redent$Go:a;. I Fel Cones sono semi corrotti che cadono dagli alberi. Sprigionano un fumo verde.$B$BPortane qualcuno a Foulhoof. Penserà che tu gli abbia portato uno spuntino innocuo.",
  obj = "Raccogli 3 Fel Cones e consegnali a Zenn Foulhoof, fuori da Dolanaar.",
  progress = "Cosa hai per me, $N? Un bel bocconcino, suppongo?",
  reward = "Ah, che dolce $R! Sapevo che mi saresti stato utile!",
  en_title = "Seek Redemption!",
  en_obj = "Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar.",
}
T[491] = {
  title = "Una bacchetta per Bethor",
  desc = "Thule una volta mi raccontò che, tanto tempo fa, lui e due colleghi crearono una bacchetta magica, intrecciata con le bacchette da apprendista che ogni mago possedeva. Quella bacchetta era un simbolo della loro amicizia e, sebbene Thule finì per disprezzarla, non riuscì a separarsene, né a lasciarla agli altri. Così la rubò e la nascose a Fenris Keep.$B$BTieni. Porta la bacchetta a Bethor Iceshard, uno degli amici di Thule di molti anni fa. Sono certo che la vorrà.",
  obj = "Porta la Woven Wand a Bethor Iceshard nel Magic Quarter di Undercity.",
  progress = "$N. Hai sconfitto Thule Ravenclaw?",
  reward = "...che cos'è questa? Thule aveva la nostra Woven Wand? Credevo fosse andata perduta quando la nostra amicizia si spezzò e lui si schierò con il Lich King!$B$BNon deve aver invocato il suo potere, altrimenti lo avrei percepito. Ed è un bene che non l'abbia usata...$B$BÈ un ritrovamento meraviglioso. Hai la mia gratitudine, $N, e sarai ricompensat$Go:a;.",
  en_title = "Wand to Bethor",
  en_obj = "Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity.",
}
T[492] = {
  title = "Una nuova piaga",
  desc = "Secondo la Deathguard, un altro di quei folli Dwarven Mountaineers è appena stato catturato. La Deathguard usa la cantina della Gallows End Tavern come cella finché i prigionieri non possono essere trattati \"a dovere\".$B$BPerché non vai a vedere se il Captured Mountaineer gradisce questa bevanda speciale che ho preparato per lui? Contiene un sottile accenno di ciò che la Dark Lady ha in serbo per il resto di Azeroth.",
  obj = "Porta la Johaan's Special Drink al Captured Mountaineer.",
  progress = "Se avessi il mio fidato fucile saresti già morto, $C. Aspetta solo che arrivi la Steam Tank Brigade a salvarmi!",
  reward = "Ah, finalmente da bere. Sono certo che non sarà una Rhapsody Malt, ma a questo punto accetto qualsiasi cosa per bagnarmi la gola.",
  en_title = "A New Plague",
  en_obj = "Bring Johaan's Special Drink to the Captured Mountaineer.",
}
T[493] = {
  title = "Viaggio verso Hillsbrad Foothills",
  desc = "La Royal Apothecary Society è sotto fortissima pressione da parte della Dark Lady per sviluppare una Nuova Piaga. Lavoriamo con impegno e abbiamo fatto grandi progressi. Crediamo che il successo arriverà molto più in fretta se condivideremo le informazioni all'interno della Società.$B$BPer questo voglio che tu consegni le mie ultime scoperte ad Apothecary Lydon a Tarren Mill, un piccolo villaggio nascosto tra le Hillsbrad Foothills.$B$BIl viaggio sarà lungo. Vai verso sud e resta sulle strade. Segui con attenzione i cartelli!",
  obj = "Consegna le scoperte di Apothecary Renferrel ad Apothecary Lydon, nel villaggio di Tarren Mill nelle Hillsbrad Foothills.",
  progress = "Hai qualcosa per me?",
  reward = "Ah, eccellente. Apothecary Renferrel ha tutto il mio rispetto. Non vedo l'ora di studiare il suo lavoro.",
  en_title = "Journey to Hillsbrad Foothills",
  en_obj = "Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills.",
}
T[494] = {
  title = "È ora di colpire",
  desc = "Silenzio e attenzione, $C.$B$BSono stato mandato in questa postazione per tenere d'occhio la città di Hillsbrad. La mia è una missione di ricognizione. È indispensabile che tu porti subito un messaggio a High Executor Darthalia a Tarren Mill. Dille che io, Deathstalker Lesh, invio il seguente messaggio:$B$B\"Il grido del corvo dall'ovest invita a venire.\"$B$BSegui la strada verso est e fai molta attenzione ai cartelli. Ora, in fretta! Via verso Tarren Mill, e con urgenza, aggiungerei!",
  obj = "Recati a Tarren Mill per consegnare il messaggio di Deathstalker Lesh a High Executor Darthalia.",
  reward = "Il grido del corvo dall'ovest invita a venire?$B$BOttime notizie! Hillsbrad è pronta per l'attacco. Ora possiamo mettere in atto il nostro piano di distruzione. Varimathras sarà soddisfatto.",
  en_title = "Time To Strike",
  en_obj = "Travel to Tarren Mill to deliver Deathstalker Lesh's message to High Executor Darthalia.",
}
T[496] = {
  title = "Elixir of Suffering",
  desc = "Ah, un altro giorno miserabile a Tarren Mill. Tutta quest'aria pulita mi mette di pessimo umore, $N.$B$BPrima riusciamo ad appestare gli umani di qui, meglio è. Ho condotto studi accurati sui possibili agenti letali da usare nei miei intrugli, ma non ho il tempo di raccoglierli tutti.$B$BSe vuoi renderti utile, procurami queste cose: 10 Gray Bear Tongue e il rarissimo e introvabile Creeper Ichor. Troverai sia gli orsi sia i creeper appena fuori Tarren Mill.",
  obj = "Apothecary Lydon, a Tarren Mill, vuole 10 Gray Bear Tongue e un po' di Creeper Ichor.",
  progress = "Vedo che sei $Gtornato:tornata;. Spero che tu sia $Griuscito:riuscita; a raccogliere gli agenti che mi servono. Un altro giorno senza morti mi metterà di umore cupo.",
  reward = "Questi esemplari sono perfetti. Be', $N, sei $Griuscito:riuscita; a portarmi un minimo accenno di gioia in un'altra giornata miserabile. I tuoi sforzi sono apprezzati.",
  en_title = "Elixir of Suffering",
  en_obj = "Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.",
}
T[498] = {
  title = "Il salvataggio",
  desc = "Io e altri guerrieri siamo stati mandati dal Capoguerra a recuperare un oggetto a Durnholde e a indagare su questo cosiddetto Syndicate.$B$BSiamo andati a Durnholde a dare un'occhiata, ma siamo stati colti di sorpresa da un gran numero di umani. Abbiamo combattuto con coraggio, ma il loro numero è bastato a sconfiggerci. Alcuni di noi li hanno presi prigionieri, ma io sono riuscito a fuggire.$B$BDurnholde è appena a sud-est di qui, oltre il fiume. Drull e Tog'thar sono tenuti là: devi andare a liberarli.",
  obj = "Krusk, a Tarren Mill, vuole che tu liberi Drull e Tog'thar da Durnholde Keep.",
  progress = "Devi fare in fretta, $C. Rabbrividisco a pensare cosa potrebbero fare gli umani a Drull e Tog'thar.",
  reward = "Quindi gli umani pensavano di trasformare i nostri guerrieri in schiavi, eh? Gliela faremo vedere!$B$BA quanto pare hanno portato Gol'dir, il nostro capo, in un altro posto. Dobbiamo trovarlo e salvarlo. Ma per ora non abbiamo idea di dove sia...$B$BQuando avremo una pista, non mancherò di dirtelo, $N.",
  en_title = "The Rescue",
  en_obj = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.",
}
T[499] = {
  title = "Elixir of Suffering",
  desc = "Mi basterà un momento per mescolare questi componenti in quello che ho battezzato Elixir of Suffering.$B$BEcco fatto! Ah, niente rallegra una giornata cupa in queste miserabili colline come portare un po' di sofferenza nel mondo.$B$BVediamo se la nostra pozioncina ha ottenuto l'effetto voluto.$B$BFa' assaggiare alla mia assistente Umpi quel che la Signora Oscura ha in serbo per gli umani e per il Flagello.",
  obj = "Dai l'Elixir of Suffering a Umpi.",
  progress = "Cra cra!",
  reward = "Craaa!",
  en_title = "Elixir of Suffering",
  en_obj = "Give Umpi the Elixir of Suffering.",
}
T[500] = {
  title = "Taglia sui Crushridge",
  desc = "Gli ogre Crushridge hanno scavato un tumulo di ogre sulle Alterac Mountains, vicino alla città in rovina di Alterac. E i miei esploratori mi dicono che hanno occupato anche quelle rovine.$B$BNon possiamo lasciare che si mettano comodi lassù: se pensano di essere al sicuro dove sono, il loro prossimo passo sarà scendere sulle colline, e questo li porterebbe proprio alla nostra porta!$B$BVa' a nord, nelle Alterac Mountains, e dai la caccia agli ogre. Portami i Dirty Knucklebone che portano con sé e ti guadagnerai una bella taglia.",
  obj = "Raccogli 9 Dirty Knucklebone dagli ogre Crushridge nelle Alterac Mountains. Portali a Marshal Redpath, a Southshore.",
  progress = "$N, stai ancora dando la caccia agli ogre? Hai gli ossicini che ti avevo chiesto di raccogliere?",
  reward = "Molto bene, $N. Devi aver fatto a pezzi un bel mucchio di ogre per raccogliere tutti questi ossicini.$B$BQuesto dovrebbe tenerceli lontani. Almeno per un po'.",
  en_title = "Crushridge Bounty",
  en_obj = "Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains.  Bring them to Marshal Redpath in Southshore.",
}
T[501] = {
  title = "Elixir of Pain",
  desc = "Oh, $N... i fiori sbocciano a Hillsbrad e l'aria è così fresca e frizzante. Non posso far altro che crogiolarmi nella miseria di tutto questo. Guardo fuori dalla mia finestra sporca e aspetto con ansia il giorno in cui la nostra nuova piaga porterà a questo mondo la morte che merita.$B$BPer quanto mi piacerebbe starmene seduto a rimuginare tutto il giorno, il mio dovere verso la Signora Oscura mi chiama. Mi aiuti? Le mie ricerche mi portano a credere di poter preparare il più splendido degli intrugli di morte con il sangue di un Mountain Lion. Portamene un po' e ci divertiremo un pochino.",
  obj = "Porta 10 fiale di Mountain Lion Blood ad Apothecary Lydon, a Tarren Mill.",
  progress = "Mi ricordo di te, $N. Dovevi aiutarmi a preparare il mio ultimo elisir. Mi serve quel sangue prima di poter portare agli abitanti di Hillsbrad la mia personale forma di miseria.",
  reward = "Raccolta superba, $N.",
  en_title = "Elixir of Pain",
  en_obj = "Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.",
}
T[502] = {
  title = "Elixir of Pain",
  desc = "Ah, niente come l'odore del sangue fresco tra le colline!$B$BOra mescoliamo un po' di questo e un pizzico di quello e che il vero divertimento cominci! Quel che ho creato con questo sangue mi piace chiamarlo Elixir of Pain. Se i miei calcoli sono giusti, questo intruglio potrebbe essere l'inizio di qualcosa di molto bello per Lady Sylvanas. Ma quel che ci serve è una prova.$B$BPorta questo elisir alla fattoria più a nord degli Hillsbrad Fields, a sud-ovest. Vediamo come piace questo \"regalino\" a Stanley, il cagnolino di Farmer Ray.",
  obj = "Fa' bere l'Elixir of Pain a Stanley.",
  progress = "Bau?",
  reward = "Versi un po' di elisir nella mano e la porgi davanti al muso di Stanley.",
  en_title = "Elixir of Pain",
  en_obj = "Feed the Elixir of Pain to Stanley.",
}
T[503] = {
  title = "Gol'dir",
  desc = "Da quel che capisco dai documenti che hai procurato, Gol'dir è tenuto prigioniero in una grande base del Syndicate a nord, molto probabilmente nelle Alterac Mountains. È prigioniero da troppo tempo e va liberato.",
  obj = "Libera Gol'dir, poi torna da Krusk, a Tarren Mill.",
  progress = "Dammi la chiave, $C, apro io la serratura.",
  reward = "Grazie, $N. Ho guidato io la spedizione da Durotar agli ordini del Capoguerra, ma come vedi i nostri piani sono andati un po' storti. Mi hanno tenuto prigioniero qui in questa città, costringendomi a lavorare, a trasportare pesi, a scavare...$B$BQuel che ho sofferto però non conta. C'è un'informazione importante che devi consegnare a chi guida il nostro gruppo adesso.",
  en_title = "Gol'dir",
  en_obj = "Free Gol'dir then return to Krusk in Tarren Mill.",
}
T[504] = {
  title = "Crushridge Warmongers",
  desc = "Ora che hai avuto un assaggio degli ogre Crushridge, voglio che tu li faccia sanguinare sul serio...$B$BEntra nelle Ruins of Alterac e cerca i Crushridge Warmonger. Voglio che tu ne abbatta un buon numero: è l'unico modo perché quei bruti imparino a stare lontani dal territorio dell'Alleanza.",
  obj = "Uccidi 15 Crushridge Warmonger, poi torna da Marshal Redpath, a Southshore.",
  progress = "Hai altri Warmonger da uccidere, $N. Dovresti essere su in montagna a svolgere il tuo compito, non quaggiù con l'arma riposta.",
  reward = "Molto bene. Ecco la tua ricompensa.$B$BE mentre davi la caccia a quei Warmonger, com'era la città di Alterac? Sarà in cattive condizioni, immagino. Gli ogre non sono noti per la loro pulizia.$B$BPer fortuna, i tuoi sforzi aiuteranno a tenerli lontani da Southshore.",
  en_title = "Crushridge Warmongers",
  en_obj = "Slay 10 Crushridge Warmongers, then return to Marshal Redpath in Southshore.",
}
T[505] = {
  title = "Gli assassini del Syndicate",
  desc = "Sono il nuovo magistrato di Southshore, nominato di recente dopo l'assassinio del magistrato precedente. Gli assassini non sono mai stati trovati, ma grazie alle nostre indagini siamo quasi certi che siano stati assoldati dal Syndicate, una banda di ladri guidata da nobili malvagi dell'ormai caduto regno di Alterac.$B$BIl Syndicate ha un accampamento a nord di Tarren Mill, in mano all'Orda, e i nostri ultimi indizi portavano a quell'accampamento. Uccidi i membri del Syndicate che trovi laggiù.",
  obj = "Uccidi 12 Syndicate Footpad e 8 Syndicate Thief, poi torna da Magistrate Henry Maleb, a Southshore.",
  progress = "Hai eliminato quei delinquenti del Syndicate, confido?",
  reward = "Grazie, $N. Anche se forse sono ancora in giro, speriamo che alcuni dei ladri e dei tagliaborse che hai ucciso fossero i responsabili della morte dell'ultimo magistrato. Ma anche se non lo fossero, il Syndicate porta corruzione in questa terra ed è una macchia sulla razza umana.$B$BLa loro morte è ben accetta a Southshore.",
  en_title = "Syndicate Assassins",
  en_obj = "Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore.",
}
T[506] = {
  title = "L'eredità di Blackmoore",
  desc = "Un giorno o due fa ho ricevuto la visita del capo di questo Syndicate. Si chiamava Aliden Perenolde e si faceva chiamare signore di queste terre. Mi ha confidato il suo piano: prendere come schiavi gli orchi che gli si oppongono, proprio come avevano progettato suo padre e il suo mentore, il disprezzato Blackmoore.$B$BPiù importante ancora: si è portato dietro la sua amante, una ragazzina esile di nome Elysa. Al collo aveva il pendaglio che il Capoguerra desidera.$B$BOra va', io me la caverò da solo, dopo aver sistemato le mie faccende qui.",
  obj = "Porta a Krusk, a Tarren Mill, le informazioni raccolte da Gol'dir.",
  reward = "Che sfacciataggine, questi umani arroganti! Mostreremo loro che gli orchi non si piegheranno mai al loro volere!$B$BOra questa sarà la nostra missione, oltre a recuperare il ninnolo che il Capoguerra desidera. Sembra che portando a termine l'una porteremo a termine anche l'altra.",
  en_title = "Blackmoore's Legacy",
  en_obj = "Return the information gathered by Gol'dir to Krusk in Tarren Mill.",
}
T[507] = {
  title = "Lord Aliden Perenolde",
  desc = "È chiaro che Perenolde va ucciso, la sua sozzura va tolta dal mondo. Il suo maniero si trova un bel pezzo a nord di qui, sulle rive del Lordamere Lake. Fa' il tuo dovere, $N, poi recupera il pendaglio che il Capoguerra desidera e torna qui.",
  obj = "Uccidi Lord Aliden Perenolde e chiedi alla sua amante, Elysa, del pendaglio di Taretha.",
  progress = "C-cosa vuoi?",
  reward = "No, no, ti prego, non farmi del male! Non ho mai voluto fare del male alla tua gente, mi ha tenuta qui contro la mia volontà! Ti prego... risparmiami!",
  en_title = "Lord Aliden Perenolde",
  en_obj = "Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.",
}
T[508] = {
  title = "Il dono di Taretha",
  desc = "Il pendaglio? Certo che puoi averlo... Prendilo! Non voglio più niente che me lo ricordi... ti prego, ti prego, vattene in pace...",
  obj = "Porta il pendaglio di Taretha a Krusk, a Tarren Mill.",
  progress = "Sei $Gtornato:tornata;, $N. Hai un successo da riferire?",
  reward = "È strano che il Capoguerra si spenda tanto per una cosa così piccola. Non pretendo di capirlo, ma lo seguirò, qualunque cosa ordini. Hai fatto bene, $N, e di sicuro il Capoguerra sarà contento di sapere del tuo successo.",
  en_title = "Taretha's Gift",
  en_obj = "Return Taretha's pendant to Krusk in Tarren Mill.",
}
T[509] = {
  title = "Elixir of Agony",
  desc = "Un altro giorno, un altro elisir da preparare. Se dipendesse da me, lascerei che i patetici umani e il Flagello se la sbrigassero tra loro. Sembrano già decisi ad ammazzarsi a vicenda.$B$BPurtroppo la nostra Signora Oscura vuole accelerare un pochino il processo, e allora perché non passare queste giornate tetre spargendo un po' di morte e di malattia per la terra?$B$BEcco il piano, $N: va' a Nethander Stead, a sud di Tarren Mill e a est del fiume e di Southshore. Raccogli per me 6 Mudsnout Blossom nel campo, per il mio prossimo elisir.",
  obj = "Porta 6 Mudsnout Blossom ad Apothecary Lydon, a Tarren Mill.",
  progress = "Fortuna a Nethander Stead?",
  reward = "Ah, il puzzo orribile dei Mudsnout Blossom. Almeno quei luridi gnoll servono a qualcosa.",
  en_title = "Elixir of Agony",
  en_obj = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.",
}
T[510] = {
  title = "Foreboding Plans",
  desc = "Tra questi documenti c'è una lista di rifornimenti richiesti. Comprende oggetti comuni (cibo, armi, vestiti) e attrezzatura più insolita (maschere, olio, veleno).$B$BMa la cosa più notevole è l'urgenza della richiesta: questi rifornimenti servivano presto per portare a termine quella che nel documento viene descritta come una \"missione importante contro Southshore.\"",
  obj = "Porta i Foreboding Plans a Magistrate Maleb, a Southshore.",
  progress = "$N, sembri in ansia. C'è qualcosa che vuoi dirmi?",
  reward = "<Maleb legge i documenti.>$B$BSono molto preoccupanti, $N. Dalle informazioni di questi documenti, e dalle azioni passate del Syndicate, dobbiamo presumere che quella banda di tagliagole abbia dichiarato guerra a Southshore.",
  en_title = "Foreboding Plans",
  en_obj = "Bring the Foreboding Plans to Magistrate Maleb in Southshore.",
}
T[511] = {
  title = "Encrypted Letter",
  desc = "Una delle lettere su questo tavolo è cifrata e indecifrabile.",
  obj = "Porta l'Encrypted Letter a Loremaster Dibbs, a Southshore.",
  progress = "Sì, $Gsignore:signora;? Hai qualcosa da sbrigare con me?",
  reward = "Che cos'è? Aspetta un momento... fammi dare un'occhiata più da vicino.$B$B...$B$BHm, non ho mai visto questo tipo di cifratura, ma devo ammettere che le mie conoscenze in quel campo non sono affatto complete.",
  en_title = "Encrypted Letter",
  en_obj = "Bring the Encrypted Letter to Loremaster Dibbs in Southshore.",
}
T[512] = {
  title = "Morti nobili",
  desc = "Temo che i capi del Syndicate vogliano la rovina di Southshore. Dobbiamo colpire duramente questi capi prima che i loro piani si realizzino.$B$BEntra nelle rovine di Strahnbrad, nelle Alterac Mountains a nord. Pensiamo che il Syndicate usi la zona come quartier generale.$B$BSappiamo che questa banda di tagliagole è guidata da ex nobili di Alterac. Potrebbero nascondersi fingendosi normali agenti del Syndicate, ma capirai di aver ucciso un nobile dall'anello con sigillo che porta.$B$BPortami quegli anelli con sigillo.",
  obj = "Porta 7 Alterac Signet Ring a Magistrate Maleb, a Southshore.",
  progress = "Hai dato la caccia al Syndicate? Hai quegli anelli?",
  reward = "Privare il Syndicate dei suoi nobili gli toglierà la capacità di agire con decisione, e lo ridurrà a nient'altro che una banda di delinquenti.$B$BServi bene la tua Alleanza, $N.",
  en_title = "Noble Deaths",
  en_obj = "Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore.",
}
T[513] = {
  title = "Elixir of Agony",
  desc = "Proprio quando pensavo che sarebbe passato un altro giorno senza un briciolo di gioia, mi hai portato quei magnifici Mudsnout Blossom.$B$BPrima li ridurrò in un bel composto. Poi ci servirà che Master Apothecary Faranell, nell'Undercity, ci applichi il suo colloide di decomposizione, e allora sì che ci divertiremo davvero!$B$BTieni, prendi questo Mudsnout Composite e portalo subito di corsa a Master Faranell, $N.",
  obj = "Porta il Mudsnout Composite a Master Apothecary Faranell, nell'Undercity.",
  progress = "Non vedi che sono occupato, $C? La Signora Oscura pretende una nuova piaga prima che l'avanzata del Flagello da Northrend ci travolga. E con la minaccia umana che incalza da sud, il tempo diventa la mia merce più preziosa. Spero per te che sia importante!",
  reward = "Ti manda Apothecary Lydon? Ah, potevi dirlo subito!$B$BNonostante il carattere tetro, Apothecary Lydon è uno dei nostri membri più devoti e capaci.$B$BIl bravo compare manda del Mudsnout Composite! Adesso ho capito cosa sta combinando il nostro amico a Hillsbrad. E il suo modo di ragionare mi piace. La Signora Oscura sarebbe assai colpita dai progressi che sta facendo verso la nuova piaga.",
  en_title = "Elixir of Agony",
  en_obj = "Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.",
}
T[514] = {
  title = "Lettera per Stormpike",
  desc = "Ho un collega a Ironforge che forse può aiutare a decifrare questa lettera. Va' alla biblioteca nell'Hall of Explorers, a Ironforge, e parla con Prospector Stormpike. Digli che ti mando io e mostragli la lettera. Se c'è qualcuno a nord della Blackrock Spire che può leggerla, è lui.",
  obj = "Porta la Cleverly Encrypted Letter a Prospector Stormpike, a Ironforge.",
  progress = "Ti ha mandato Dibbs, da Southshore? Come se la passa quel vecchio topo di biblioteca?",
  reward = "Ah, una cifratura! Una mia specialità. Vediamo un po'...",
  en_title = "Letter to Stormpike",
  en_obj = "Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.",
}
T[515] = {
  title = "Elixir of Agony",
  desc = "Un composto di mudsnout? Assolutamente geniale! Come mai non ci ho pensato io?$B$BLascia che aggiunga il mio colloide di decomposizione a questo intruglio diabolico.$B$BPer attivare gli agenti contaminanti in questa miscela di mudsnout, a Lydon serviranno una Strong Troll's Blood Potion, qualche Daggerspine Scale e qualche Torn Fin Eye dalla costa meridionale di Hillsbrad. Saprà lui cosa fare, una volta che gli avrai portato tutti i reagenti. E ah, quanto sono impaziente di sapere come va il suo esperimento!",
  obj = "Porta la Mudsnout Mixture, una Strong Troll's Blood Potion, 5 Daggerspine Scale e 5 Torn Fin Eye ad Apothecary Lydon, a Tarren Mill.",
  progress = "Che piacere vederti di ritorno, $N. Mi stavo annoiando terribilmente. Non una sola cosa divertente da fare, a parte avvelenare e infettare Umpi e poi rianimarla... ancora e ancora e ancora.$B$BCom'è andato il viaggio all'Undercity? Hai avuto la fortuna di massacrare qualche umano lungo la strada?",
  reward = "L'eccitazione per questo esperimento mi mette allegria! Mi sei $Gstato:stata; di grande aiuto, $N. Insieme spargeremo morte e malattia su questa terra!",
  en_title = "Elixir of Agony",
  en_obj = "Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.",
}
T[516] = {
  title = "Beren's Peril",
  desc = "Mi sono arrivati rapporti su un gruppo di non morti che si sta asserragliando per preparare un attacco contro di noi. Con questa informazione possiamo ribaltare la situazione e attaccarli per primi, stroncando sul nascere il loro piccolo piano.$B$BPurtroppo le mie informazioni sono frammentarie, a dir poco. Pare che si nascondano in un luogo noto come Beren's Peril. La posizione esatta non si conosce, ma sembra sia una grotta fra le colline, vicino a una sacca di maghi di Dalaran.$B$BConfido nella tua intraprendenza. Trovali e annientali.",
  obj = "Individua Beren's Peril, poi uccidi 6 Ravenclaw Drudger e 6 Ravenclaw Guardian, e torna da Shadow Priest Allister, al Sepulcher.",
  progress = "Hai già individuato la loro base, $N? Il tempo stringe!",
  reward = "Se i nostri esploratori e i nostri agenti continueranno a procurarci informazioni preziose come questa, toglieremo dalle nostre terre il Flagello del Re dei Lich in men che non si dica.",
  en_title = "Beren's Peril",
  en_obj = "Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.",
}
T[517] = {
  title = "Elixir of Agony",
  desc = "Questo nuovo elisir è finalmente pronto per la prova. Ma perché sprecare una piaga tanto buona e tanto contagiosa su una semplice rana o su un cane? Divertiamoci sul serio, nel nome di Lady Sylvanas.$B$BScendi a Dun Garok. Sai, la caserma dove sgattaiolano quei sudici nanetti. Rubami un barile della loro Shindigger Stout. Quando avrò quel barile, tu e io faremo una gran festa, $N.",
  obj = "Porta un barile di Shindigger Stout ad Apothecary Lydon, a Tarren Mill.",
  progress = "Certe volte mi annoio talmente qui a Tarren Mill che mi metto ad aprire il barattolo di formaldeide e lascio che il delizioso aroma si spanda nell'aria. Anche se Umpi si innervosisce un po'.$B$BAllora, sei $Griuscito:riuscita; a procurarti un barile dai nani? Giuro che se devo fissare questo elisir letale un altro giorno senza usarlo su qualcuno mi metto a urlare.",
  reward = "Finalmente! Ora siamo pronti all'azione!",
  en_title = "Elixir of Agony",
  en_obj = "Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.",
}
T[518] = {
  title = "La Crown of Will",
  desc = "Mug'Thol e i suoi ogre Crushridge hanno invaso le rovine di Alterac. Sarà difficile infliggergli una punizione seria senza prima sfoltire il numero degli ogre.$B$BDopo averli indeboliti, procederemo.$B$BChiaro? Bene. Ora va'.",
  obj = "Uccidi 14 Crushridge Mauler per Melisara, a Tarren Mill.",
  progress = "Noto che il tuo compito non è finito, $N. Devo informare Sharlindra della tua incompetenza?",
  reward = "La neve si tinge di rosso del sangue degli ogre, ma non possiamo fermare i nostri sforzi finché lo spirito e il numero dei Crushridge non saranno schiacciati e ridotti in polvere nella terra e nella neve.",
  en_title = "The Crown of Will",
  en_obj = "Kill 10 Crushridge Maulers for Melisara in Tarren Mill.",
}
T[519] = {
  title = "La Crown of Will",
  desc = "Targ, Muckrake e Glommus sono i luogotenenti di Mug'Thol. Gli sono fedeli, anche se chi può dire cosa spinge un ogre alla fedeltà.$B$BPortami le loro teste, $N, e poi non resterà che prendere la testa di Mug'Thol, corona compresa.",
  obj = "Uccidi Targ, Muckrake e Glommus e porta le loro teste a Melisara, a Tarren Mill.",
  progress = "Voglio le loro teste, $N, non scuse.",
  reward = "...e io che pensavo che gli ogre puzzassero già abbastanza.$B$BQuando mi porterai la testa di Mug'Thol, le farò infilzare tutte e quattro su delle picche sopra Alterac. Un monumento adatto a chi va contro la volontà della Signora Oscura.",
  en_title = "The Crown of Will",
  en_obj = "Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.",
}
T[520] = {
  title = "La Crown of Will",
  desc = "Con i luogotenenti di Mug'Thol morti, non resta che uccidere Mug'Thol e recuperare la Crown of Will. Non ho dubbi che non vorrà separarsene. Probabilmente ti starà anche aspettando, vista la... dipartita... dei suoi compagni.$B$BTrova Mug'Thol, e portami la sua testa e la Crown. La resistenza dei Crushridge sarà finita.",
  obj = "Uccidi Mug'Thol e riporta la sua testa con la Crown of Will a Melisara, a Tarren Mill.",
  progress = "Tre teste le ho, me ne serve una quarta. Sarà quella di Mug'Thol, o sarà la tua, $N. Te lo prometto.",
  reward = "Hai fatto bene il tuo dovere, $N. La testa di Mug'Thol ornerà la vetta più alta delle rovine di Alterac, e la Guardiamorte spazzerà sottoterra quel che resta dei Crushridge.",
  en_title = "The Crown of Will",
  en_obj = "Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.",
}
T[521] = {
  title = "La Crown of Will",
  desc = "Non resta che consegnare la Crown of Will a Sharlindra, nell'Undercity. Farà in modo che venga consegnata a Lady Sylvanas. Ti sconsiglio di pensare di usarla per i tuoi scopi, $N: la sorte di Mug'Thol dovrebbe bastare come esempio.",
  obj = "Consegna la Crown of Will a Sharlindra, nell'Undercity.",
  progress = "Sì? Hai qualcosa da riferire?",
  reward = "Dunque è questa la reliquia che l'ogre usava per sottrarsi alla volontà della Signora Oscura...$B$BStrano che una cosa così semplice possa avere un potere tanto grande. E finire in mani così goffe. Ben fatto, $N: consegnerò la corona a Lady Sylvanas, e farò in modo che venga a sapere della tua impresa.",
  en_title = "The Crown of Will",
  en_obj = "Deliver the Crown of Will to Sharlindra in the Undercity.",
}
T[522] = {
  title = "Assassin's Contract",
  desc = "Questo è un contratto per l'assassinio di Magistrate Henry Maleb. È stato sigillato con ceralacca rossa, usando un anello con sigillo inconfondibile.",
  obj = "Porta l'Assassin's Contract a Magistrate Maleb, a Southshore.",
  progress = "Sei senza fiato! Hai qualcosa da riferire?",
  reward = "<Maleb esamina il contratto.>$B$BQuesto spiega l'ultimo attacco a Southshore. Il Syndicate deve avercela con me, come l'aveva con l'ultimo magistrato!",
  en_title = "Assassin's Contract",
  en_obj = "Bring the Assassin's Contract to Magistrate Maleb in Southshore.",
}
T[523] = {
  title = "La fine del barone",
  desc = "Il contratto che hai recuperato è firmato da Baron Vardus, un nobile dell'ex regno di Alterac, noto per il suo cuore di ghiaccio e i suoi metodi brutali. Non mi sorprende che dietro a tutto questo ci fosse uno come il barone.$B$BTrova quest'uomo. Trovalo, e consegnalo alla giustizia. Deve trovarsi in uno dei covi del Syndicate: forse tra le rovine di Strahnbrad, o forse nella valle a nord di esse.",
  obj = "Porta l'Head of Baron Vardus a Magistrate Maleb, a Southshore.",
  progress = "Baron Vardus non può pensare che Southshore gli permetta di mandarci contro i suoi delinquenti impunemente. Voglio la sua testa!",
  reward = "Grazie, $N. La mia testa riposa un po' più tranquilla, sapendo che quel furfante ha perso la sua.",
  en_title = "Baron's Demise",
  en_obj = "Bring the Head of Baron Vardus to Magistrate Maleb in Southshore.",
}
T[524] = {
  title = "Elixir of Agony",
  desc = "Qui accanto i Guardiamorte tengono prigionieri alcuni contadini catturati. High Executor Darthalia sospettava che tra loro si nascondesse uno degli strateghi militari di Stormwind. A quanto pare il tizio è stato trovato morto nelle Plaguelands ieri notte. Darthalia, che ha sempre un occhio di riguardo per me, ha deciso di lasciare i prigionieri a mia disposizione.$B$BCredo sia ora di offrire una festa a quei contadini. Sembra proprio una bella idea!$B$BPosa questo barile infetto sul tappeto nella loro stanza. Birra appestata per tutti!",
  obj = "Posa il Tainted Keg sul tappeto, per i contadini prigionieri.",
  progress = "Dal tappeto sale un odore di muffa.",
  reward = "Posi il barile infetto sul tappeto polveroso.",
  en_title = "Elixir of Agony",
  en_obj = "Place the Tainted Keg on the rug for the captured farmers.",
}
T[525] = {
  title = "Altri misteri",
  desc = "Ho decifrato la lettera, ma non so cosa pensarne. L'hai trovata tra dei ladri, sulle colline ai piedi delle montagne di Alterac? Molto strano...$B$BDovresti portarla al magistrato di Southshore. Anche se questa lettera è criptica, la sua è la città più vicina ad Alterac; se si sta preparando una minaccia, dovrebbe saperlo.",
  obj = "Porta la Decrypted Letter a Magistrate Maleb, a Southshore.",
  progress = "$N. Hai di nuovo viaggiato tra le colline e le montagne? Che notizie porti?",
  reward = "<Maleb legge la lettera.>$B$BQuesta è la traduzione di una lettera che hai trovato in un accampamento del Syndicate? Non l'ha scritta un ladro, e nemmeno un nobile di Alterac.$B$BSembra che il Syndicate abbia legami con un altro potere, e rabbrividisco al pensiero di quale possa essere.",
  en_title = "Further Mysteries",
  en_obj = "Bring the Decrypted Letter to Magistrate Maleb in Southshore.",
}
T[526] = {
  title = "Lightforge Ingots",
  desc = "In quella cassa avrai anche trovato un Lightforge Ingot, ma non basta per forgiare niente di decente!$B$BDovresti tornare là e cercarne altri. Magari i murloc intorno a quella nave naufragata ne hanno addosso.",
  obj = "Raccogli 5 Lightforge Ingot, poi torna da Glorin Steelbrow, nelle Wetlands.",
  progress = "L'hai trovato il Lightforge Iron che ti serve?",
  reward = "Ah, li hai trovati! E adesso battiamo questo Lightforge Iron fino a farne qualcosa di utile, eh?",
  en_title = "Lightforge Ingots",
  en_obj = "Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands.",
}
T[527] = {
  title = "La battaglia di Hillsbrad",
  desc = "Sull'attenti quando ti rivolgi a me, $C.$B$BSono sotto il comando diretto di Varimathras. Dobbiamo reprimere l'infestazione umana finché i nostri speziali non avranno sviluppato la nuova piaga.$B$BLe nostre informazioni ci portano a credere che la città di Hillsbrad sia vulnerabile a un attacco. Il tuo primo incarico mira a interrompere i loro rifornimenti di cibo e le loro infrastrutture.$B$BVa' a ovest. Saccheggia le fattorie più a nord degli Hillsbrad Fields. Assicurati che anche i proprietari, Farmer Ray e Farmer Getz, vengano giustiziati.",
  obj = "Uccidi 6 Hillsbrad Farmhand, 6 Hillsbrad Farmer, Farmer Ray e Farmer Getz, poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Come High Executor di Tarren Mill, sotto il comando diretto di Varimathras e della Signora Oscura, sei $Gtenuto:tenuta; a obbedire ai miei ordini.$B$BForse prendi questa guerra con l'Alleanza alla leggera? Se è così dovrei decapitarti qui e ora. Altrimenti va' a ovest, alla città di Hillsbrad, e combatti contro gli umani, come ordinato.$B$BPuoi andare.",
  reward = "Riposo, $C. Vedo che sei $Gtornato:tornata; dalla battaglia. Le mie fonti mi dicono che ti sei $Gcomportato:comportata; bene sul fronte di Hillsbrad.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.",
}
T[528] = {
  title = "La battaglia di Hillsbrad",
  desc = "La notizia dell'attacco alle fattorie del nord ha gettato la gente del posto nel panico. Ottimo.$B$BI nostri Inseguitori della Morte riferiscono che i contadini fuggono verso i campi nell'Hillsbrad meridionale. Gli sciocchi credono di potersi nascondere nei frutteti e sfuggire alla loro fine.$B$BDimostra che si sbagliano, $N. Torna agli Hillsbrad Fields e stana i contadini acquattati. Falli a pezzi nel nome della nostra Signora Oscura.$B$BPuoi andare!",
  obj = "Uccidi 15 Hillsbrad Peasant, poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Hai i tuoi ordini, $C. Smettila di gingillarti qui a Tarren Mill quando c'è del lavoro da fare altrove.",
  reward = "La morsa della morte si stringe intorno alla città di Hillsbrad. La battaglia va bene.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.",
}
T[529] = {
  title = "La battaglia di Hillsbrad",
  desc = "Gli umani di Hillsbrad oppongono una resistenza inattesa. Il problema sembra essere che la gente del posto viene armata dal fabbro locale. Dobbiamo interrompere tutte le linee di rifornimento.$B$BLa tua missione sarà giustiziare Blacksmith Verringtan. Uccidi anche i suoi apprendisti. Già che ci sei, riporta un carico di ferro dalla loro scorta. I rifornimenti ci torneranno utili quando avremo finito di conquistare Hillsbrad e cominceremo a radere al suolo Southshore.",
  obj = "Uccidi Blacksmith Verringtan e 4 Hillsbrad Apprentice Blacksmith.$B$BRecupera un carico di ferro e torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Sei $Griuscito:riuscita; a eseguire gli ordini, $C? Ti sei $Gsbarazzato:sbarazzata; di Verringtan e dei suoi aiutanti? E dov'è quel carico di ferro?",
  reward = "Missione compiuta, $C. E svolta anche con una certa abilità, devo dire.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.$B$BRetrieve a shipment of iron and report back to Darthalia in Tarren Mill.",
}
T[530] = {
  title = "La vendetta di un marito",
  desc = "Valdred, un tempo mio caro amico, è stato l'assassino di mia moglie. Anche se sono incapace di provare dolore, desidero ardentemente vendetta. Se uccidi Valdred e mi porti le sue mani maledette, ti ricompenserò.$B$BL'ultima volta ho sentito che era al Greymane Wall, nel sud di Silverpine, nel tentativo di fuggire nel regno di Gilneas.",
  obj = "Uccidi Valdred Moray.$B$BPorta le sue mani a Raleigh Andrean a Undercity.",
  progress = "Hai quelle mani, $N?",
  reward = "Ah, bene. Queste mani hanno ucciso mia moglie, Deliah. La vendetta per il suo assassinio era la mia unica preoccupazione, e tu ne sei stat$Go:a; lo strumento.$B$BTieni, prendi l'anello che hai restituito prima. Deliah è morta per me da così tanto tempo che il suo anello è solo un gingillo che non voglio più conservare. Io terrò queste mani, a ricordo del tradimento del mio amico.",
  en_title = "A Husband's Revenge",
  en_obj = "Kill Valdred Moray.$B$BBring his hands to Raleigh Andrean in the Undercity.",
}
T[531] = {
  title = "La vendetta di Vyrin",
  desc = "Per la Luce! Non portare cose del genere nella Lodge... è antigienico, indicibile, anti... anti... antigienico!$B$BPortala fuori di qui, vuoi? Nessuno vuole vedere il tuo piccolo trofeo insanguinato, davvero!",
  obj = "Porta la testa di Ol' Sooty a Vyrin Swiftwind alla Farstrider Lodge.",
  progress = "Ottimo lavoro, $N! Gliel'abbiamo fatta vedere! Ecco, dammi la testa, ci penso io.",
  reward = "Grazie per avermi aiutato con il mio piccolo piano, $N. Erano mesi che non vedevo l'ora di vendicarmi di quel ragazzino presuntuoso e pieno di sé, e direi che ci siamo riusciti proprio bene! Ecco, prendi questo: te lo sei guadagnato.",
  en_title = "Vyrin's Revenge",
  en_obj = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.",
}
T[532] = {
  title = "La battaglia di Hillsbrad",
  desc = "La città di Hillsbrad è allo sbando e crediamo che cadrà presto. Dobbiamo però continuare a essere spietati finché la feccia umana non sarà spazzata via da queste colline per l'eternità.$B$BNonostante le perdite enormi, gli umani si stringono intorno ai loro capi e continuano a combattere. Dobbiamo eliminare il loro capo, Magistrate Burnside, e anche il consiglio cittadino. Distruggi anche il loro venerato documento politico, l'Hillsbrad Proclamation. E già che ci sei, ruba il registro della città.",
  obj = "Uccidi Magistrate Burnside e 5 Hillsbrad Councilman. Distruggi l'Hillsbrad Proclamation. Ruba l'Hillsbrad Town Registry. Poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Che notizie porti?",
  reward = "La voce delle tue imprese a Hillsbrad ha corso veloce. Hai fatto un buon lavoro, $C.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill Magistrate Burnside and 4 Hillsbrad Councilmen.  Destroy the Hillsbrad Proclamation.  Steal the Hillsbrad Town Registry.  Report back to Darthalia in Tarren Mill afterwards.",
}
T[533] = {
  title = "Infiltrazione",
  desc = "Finalmente cominciano ad arrivare voci e notizie, troviamo prove di dove si trovi Gol'dir. Gli umani lo spostano di continuo, ma stiamo restringendo il campo e ci concentriamo sul grande accampamento del Syndicate appena a nord di qui.$B$BVa' là, $N, e riporta tutte le informazioni su cui riesci a mettere le mani.",
  obj = "Recupera informazioni su dove si trovi Gol'dir per Krusk, a Tarren Mill.",
  progress = "Hai trovato qualcosa? Temo che le speranze per Gol'dir si riducano di giorno in giorno...",
  reward = "Finalmente sappiamo dove tengono Gol'dir. L'accampamento in questione non è lontano da qui, e speriamo che non siano preparati come lo erano quando ci catturarono la prima volta.",
  en_title = "Infiltration",
  en_obj = "Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.",
}
T[535] = {
  title = "Valik",
  desc = "Urrgh... Ferito, morente e davanti al nemico.$B$BSenza dubbio mi ucciderai comunque, ma se mi porti un po' di Southshore Stout (quelli come te bevono, vero?), ti dirò quello che vuoi sapere.",
  obj = "Porta un boccale di Southshore Stout a Valik, nell'accampamento del Syndicate.",
  progress = "Mi hai portato qualcosa da bere o sei solo $Gtornato:tornata; a finire il lavoro?",
  reward = "Vista la mia morte imminente, credo di poter dire tranquillamente che questa è la cosa più dolce che abbia mai assaggiato... Ecco, prendi questo, da morto non mi servirà a niente.$B$BBe', avanti, fallo!",
  en_title = "Valik",
  en_obj = "Bring a mug of Southshore Stout to Valik in the Syndicate camp.",
}
T[536] = {
  title = "Giù lungo la costa",
  desc = "Trasferito dalla guardia cittadina di Stormwind a Southshore, una città che a vederla dovrebbe essere abbandonata... Puzza di porto giorno e notte.$B$BPer non parlare del vecchio Redpath... Vuole che mi occupi dei murloc. Ah!$B$BRiesco a malapena a trovare la forza di andare fino a qualcuna delle sacche di quei pesci sovracresciuti giù lungo il Western Strand. Se ci andassi tu al posto mio e te ne occupassi, te ne sarei riconoscente.",
  obj = "Uccidi 10 Torn Fin Tidehunter e 10 Torn Fin Oracle per Lieutenant Farren Orinelle, a Southshore.",
  progress = "Un'altra birra, per favore, l'ultima sembra essere sparita!$B$BLuce, quanto devo restare ancora bloccato qui?$B$BOh, sei tu, $N. Li hai già uccisi quei murloc?",
  reward = "Spero che basti a convincere Redpath che ho — ah! — eseguito i suoi ordini e liberato Southshore della terribile e orribile minaccia dei temutissimi murloc! Perché non può esserci male peggiore delle devastazioni di un pesce sovracresciuto!",
  en_title = "Down the Coast",
  en_obj = "Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore.",
}
T[537] = {
  title = "Il consiglio oscuro",
  desc = "La lettera che mi hai portato è stata scritta da un essere che si fa chiamare Nagaz, un membro dell'Argus Wake. Non so cosa sia questo Argus Wake, ma se hanno stretto un'alleanza con il Syndicate, devono essere una minaccia.$B$BVoglio che tu trovi Nagaz e gli Argus Shadow Mage nominati in quella lettera. Voglio che tu li trovi, e li uccida.$B$BCerca nelle Uplands, dove il Syndicate è più forte. Si trovano a nord di Strahnbrad.$B$BCon un po' di fortuna, troverai lì questi emissari dell'Argus Wake.",
  obj = "Uccidi 4 Argus Shadow Mage.$B$BPorta l'Head of Nagaz a Magistrate Maleb, a Southshore.",
  progress = "Hai trovato gli emissari dell'Argus Wake?",
  reward = "Ben fatto, $N. L'Argus Wake non sembra un gruppo che vorremmo alla guida del Syndicate.$B$BE anche se qui hai distrutto il loro capo, Nagaz era solo il servitore di qualcun altro. L'Argus Wake potrebbe avere radici profonde in tutto il continente di Azeroth.$B$BO perfino nel mondo intero.",
  en_title = "Dark Council",
  en_obj = "Kill 4 Argus Shadow Mages.$B$BBring the Head of Nagaz to Magistrate Maleb in Southshore.",
}
T[538] = {
  title = "Southshore",
  desc = "$N. Se non ti spaventa un lungo viaggio, allora ho un compito per te, di nuovo per aiutare Stormwind a riempire la sua biblioteca.$B$BIl vecchio regno di Alterac cadde dopo la grande guerra, e aveva una grande raccolta di libri. È una tragedia che la città sia in rovina, ma è ancora più tragico che tutto il loro sapere sia andato perduto! Dobbiamo recuperare quel che possiamo.$B$BSouthshore è la città più vicina alle Ruins of Alterac. Va' là e parla con Loremaster Dibbs. Può indicarti le rovine e dirti quali libri vi si possono trovare.",
  obj = "Parla con Loremaster Dibbs, a Southshore.",
  reward = "Ah sì, mi ricordo di Milton. Un topo di biblioteca, non c'è dubbio. Che sia benedetto.$B$BE ha ragione. Le Ruins of Alterac custodiscono ancora depositi di sapere in pericolo di andare perduti!$B$BOra ad Alterac vivono gli ogre, e a loro del sapere importa ben poco.",
  en_title = "Southshore",
  en_obj = "Speak with Loremaster Dibbs in Southshore.",
}
T[539] = {
  title = "La battaglia di Hillsbrad",
  desc = "L'Hillsbrad Town Registry indica che l'Azureload Mine è sotto il controllo dell'Alleanza. Non solo: la miniera è una delle principali fonti di minerale di ferro per le armerie dell'Alleanza.$B$BAnche se abbiamo inferto un colpo decisivo alla città di Hillsbrad, l'Alleanza continua a sostenere e a proteggere con accanimento l'Azureload Mine.$B$BLa miniera si trova proprio a sud di Hillsbrad. Va' là e uccidi il caposquadra, un umano di nome Bonds. Uccidi anche i suoi minatori. Dovrebbe essere un messaggio chiaro per l'Alleanza.",
  obj = "Uccidi Foreman Bonds e 10 Hillsbrad Miner, poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Ti sono stati dati ordini precisi: attaccare l'Azureload Mine. Spero per te che i motivi per cui bighelloni a Tarren Mill siano buoni, o ti farò decapitare per tradimento.",
  reward = "La Signora Oscura sarà contenta quando saprà di avere una nuova miniera con cui armare i suoi soldati.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.",
}
T[540] = {
  title = "Preservare il sapere",
  desc = "Quegli ogre bestiali ora abitano tra le rovine di Alterac, e rabbrividisco a pensare cosa stiano facendo ai preziosi libri rimasti là. Devi recuperare quel che puoi!$B$BEntra nelle Ruins of Alterac e cerca i tomi saccheggiati dagli ogre. Prendi tutto quel che riesci a trovare e portamelo, ma cerca anche un libro in particolare: The Arm of Gri'lek. Contiene antiche tradizioni dei troll che devo studiare, e le Ruins of Alterac sono l'ultimo posto in cui si sappia ci fosse una copia intatta di questo libro.",
  obj = "Porta 5 Recovered Tome e il Worn Leather Book che contiene The Arm of Gri'lek a Loremaster Dibbs, a Southshore.",
  progress = "Vorrei poter cercare anch'io tra le rovine, ma temo che queste vecchie ossa non mi reggerebbero durante la salita sulle montagne. Comunque, come procede la tua caccia al sapere, $N?",
  reward = "Oh, li hai presi! Splendido! Devo cominciare subito a studiare The Arm of Gri'lek!",
  en_title = "Preserving Knowledge",
  en_obj = "Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore.",
}
T[541] = {
  title = "La battaglia di Hillsbrad",
  desc = "I nani aiutano gli umani? Maledetti quei piccoli esseri immondi.$B$BMetteremo alla prova la forza della cosiddetta Alleanza. Vedremo quanta voglia hanno quegli spacca-caviglie di aiutare gli umani, una volta assaggiata la nostra ira. Sappiamo esattamente dov'è la loro roccaforte in questo territorio.$B$BHanno messo su una caserma nell'Hillsbrad sud-orientale, lungo Thoradin's Wall: si chiama Dun Garok. L'ultima missione di questa battaglia è assediare Dun Garok, $C. Captain Ironhill, il loro capo, deve morire.",
  obj = "Va' a Dun Garok, uccidi 10 Mountaineer, 8 Rifleman, 4 Priest e Captain Ironhill, poi torna a riferire a Darthalia, a Tarren Mill.",
  progress = "Dun Garok è un ostacolo troppo grande per te, $C? E io che pensavo ti fossi $Gdistinto:distinta; valorosamente a Hillsbrad.$B$BSe non sei all'altezza della missione che ti è stata assegnata, ne troverò un altro capace di ottenere risultati migliori. Quanto a te, be', sono certa che alla Signora Oscura servano sempre altri becchini nelle Tirisfal Glades.",
  reward = "Quel che hai fatto sul campo di battaglia merita la lode più alta.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Travel to Dun Garok and kill 8 Mountaineers, 4 Riflemen, 2 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.",
}
T[542] = {
  title = "Ritorno da Milton",
  desc = "Mi serve un po' di tempo per studiare il libro The Arm of Gri'lek che mi hai portato, anche se sono sicuro che Milton non veda l'ora di aggiungere gli altri libri recuperati alla collezione di Stormwind.$B$BEccoti i libri che hai raccolto nelle Ruins of Alterac, impacchettati e catalogati. Riportali a Milton Sheaf, a Stormwind, e sono sicuro che te ne sarà grato.",
  obj = "Porta i Tomes of Alterac a Milton Sheaf, a Stormwind.",
  progress = "$N, sei $Gtornato:tornata;! Com'è andata la tua incursione ad Alterac? Hai riportato qualcosa?",
  reward = "Perbacco! Ma guarda qui! Non posso credere che siano sopravvissuti alla rovina di Alterac. E a tutti quegli ogre!$B$BGrazie, $N. Grazie di cuore! Hai aiutato a preservare il sapere degli umani, e aggiungi lustro alla Royal Library of Stormwind.",
  en_title = "Return to Milton",
  en_obj = "Bring the Tomes of Alterac to Milton Sheaf in Stormwind.",
}
T[543] = {
  title = "La Perenolde Tiara",
  desc = "La Perenolde Tiara è un antico cimelio dei \"nobili\" Perenolde, la famiglia che regnava su Alterac prima che quel regno cadesse in rovina. Si dice sia stata forgiata da mastri gioiellieri a Ironforge e ornata con gli smeraldi più pregiati.$B$BQuando Alterac fu distrutta la Tiara andò perduta, ma corre voce che un Ogre Mage, Grel'borg the Miser, l'abbia trovata e ora vaghi per le Ruins of Alterac in cerca di altri tesori.$B$BVorremmo che la recuperassi per noi.",
  obj = "Porta la Perenolde Tiara a Remington Ridgewell, a Stormwind.",
  progress = "Salve, $N. Cerca di non calpestarmi i risvolti dei pantaloni. Questo completo è appena stato fatto su misura.",
  reward = "Ah, è splendida. Andrà pulita, naturalmente, ma ti sei davvero $Gsuperato:superata;, $N. Farò preparare la tiara e sistemare nella nostra collezione al più presto.$B$BCome sono certo converrai, la nostra gratitudine è grande quanto la nostra collezione.",
  en_title = "The Perenolde Tiara",
  en_obj = "Bring the Perenolde Tiara to Remington Ridgewell in Stormwind.",
}
T[544] = {
  title = "Irruzione in prigione",
  desc = "Sono venuto a Tarren Mill per fare ricerca, ma adesso devo risolvere una crisi. Vedi, quattro Reietti sono fuggiti dall'Undercity qualche mese fa. Hanno voltato le spalle ai loro fratelli, ma la cosa peggiore è che hanno rubato alla Signora Oscura.$B$BQuesti ladri sono entrati in una cripta sorvegliata e hanno rubato quattro manufatti, oggetti che servivano ai nostri speziali per certi studi. Sylvanas vuole indietro quei manufatti.$B$BI ladri sono fuggiti dall'Undercity a Dalaran, e quei maghi li hanno messi in quarantena nel Lordamere Internment Camp.",
  obj = "Trova i traditori e recupera i loro manufatti, poi torna da Magus Voidglare, a Tarren Mill.",
  progress = "Hai trovato i ladri? E, cosa più importante, hai trovato quel che hanno rubato?",
  reward = "Hai reso un grande servizio ai Reietti, $N. Questi manufatti ci sono mancati molto.$B$BEd è un piacere sapere che Kegan e gli altri traditori hanno avuto giustizia.",
  en_title = "Prison Break In",
  en_obj = "Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill.",
}
T[545] = {
  title = "Le pattuglie di Dalaran",
  desc = "I maghi di Dalaran hanno costruito una vasta cupola magica intorno al cuore della loro città. C'è chi crede fosse per proteggersi dalle violenze di questi tempi, e chi dice che volessero solo la solitudine, per studiare e tramare.$B$BA me non importa quale fosse il motivo. Mi importa che le periferie in rovina della loro città, fuori dalla cupola, potrebbero nascondere preziosi tesori magici.$B$BMa la zona è pattugliata dai maghi e dai loro schiavi elementali.$B$BQuindi dagli la caccia, e torna quando il loro numero sarà ridotto a sufficienza.",
  obj = "Uccidi 6 Dalaran Summoner e 12 Elemental Slave, poi torna da Magus Voidglare, a Tarren Mill.",
  progress = "Hai già diradato le pattuglie di Dalaran intorno alle loro rovine?",
  reward = "Molto bene. Quelle rovine adesso dovrebbero essere abbastanza sicure da esplorare, se si sta attenti.$B$BGrazie, $N.",
  en_title = "Dalaran Patrols",
  en_obj = "Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.",
}
T[546] = {
  title = "Souvenir di morte",
  desc = "Ho sentito che Darthalia ti ha arruolato per far guerra agli umani di Hillsbrad. Che invidia...$B$BMentre tu te ne vai in giro a divertirti — ammazzare umani, saccheggiare la città, terrorizzare gente innocente — io resto qui di guardia a Tarren Mill.$B$BMagari avrai pietà di un vecchio Guardiamorte come me? Vedi, io colleziono teschi umani. E tu combatterai contro gli umani ancora per un bel po'. Nel corso della tua lunga battaglia portamene 30, e farò in modo che ne valga la pena.",
  obj = "Deathguard Samsa, a Tarren Mill, vuole 30 Hillsbrad Human Skull.",
  progress = "Allora, torna $Gil fortunato:la fortunata; $N? Quanti umani hai massacrato oggi? Centinaia, spero!$B$BHai qualche teschio per me?",
  reward = "Teschi preziosi! Che meraviglia! Ti devo quel che ho promesso, $N!",
  en_title = "Souvenirs of Death",
  en_obj = "Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls.",
}
T[547] = {
  title = "La spada di Humbert",
  desc = "High Executor Darthalia mi ha mandato a sorvegliare Dun Garok da lontano. Avevo piantato il campo appena fuori vista. Ma quando è arrivato il mattino e ho dovuto far bollire l'acqua, mi sono allontanato a raccogliere legna.$B$BAl ritorno al campo ho scoperto che la mia roba era sparita.$B$BA quanto pare erano passati degli esploratori nani da Dun Garok e se l'erano portata via. Mi serve la mia spada! Se riesci a riprendermela te ne sarei molto riconoscente. Ci sono così tanti nani là... sarà piuttosto difficile trovare lo sporco ladruncolo che l'ha rubata.",
  obj = "Recupera la spada di Deathguard Humbert a Dun Garok e riportagliela a Tarren Mill.",
  progress = "Sei $Griuscito:riuscita; a recuperare la mia spada, $N? High Executor Darthalia mi appenderà alle travi, se scopre la mia sciocchezza.",
  reward = "L'hai trovata!$B$BAh, mi sento di nuovo intero con la mia preziosa spada in mano. Grazie mille!",
  en_title = "Humbert's Sword",
  en_obj = "Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.",
}
T[549] = {
  title = "WANTED: personale del Syndicate",
  desc = "Per autorità di Lady Sylvanas, tutti i membri dell'organizzazione nota come Syndicate sono ricercati morti. Chi verrà preso in custodia o catturato sarà giustiziato sul posto. Al momento si sa che si stanno radunando tra le rovine di Durnholde Keep, a sud-est di Tarren Mill.$B$BUna bella ricompensa è offerta a chiunque porti prova delle proprie imprese a High Executor Darthalia.",
  obj = "Uccidi 10 Syndicate Rogue e 10 Syndicate Watchman. Torna da High Executor Darthalia, a Tarren Mill, per la ricompensa.",
  progress = "Non hai niente di meglio da fare che startene qui davanti a me, $C? Da High Executor ho questioni più urgenti che fissare il tuo muso putrefatto.",
  reward = "Eccellente, $C. Di questo passo la peste del Syndicate sarà spazzata via da questa terra in men che non si dica.",
  en_title = "WANTED: Syndicate Personnel",
  en_obj = "Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward.",
}
T[550] = {
  title = "La battaglia di Hillsbrad",
  desc = "Poiché hai combattuto con tanto valore e tanta tenacia nella battaglia di Hillsbrad, ho scritto questo encomio, in cui esalto le tue prodezze in combattimento perché l'alto comando ne prenda atto.$B$BPorta questo encomio sigillato a Varimathras, nell'Undercity. Va' con orgoglio, $C.",
  obj = "Porta Darthalia's Sealed Commendation a Varimathras, nell'Undercity.",
  progress = "Cosa porta $Gun:una; $C fin nell'Undercity dal campo di battaglia?",
  reward = "Quindi sei tu $Gil famigerato:la famigerata; $C che ha inferto un colpo tanto decisivo alle forze dell'Alleanza nelle Hillsbrad Foothills? La voce delle tue gloriose imprese è arrivata in fretta all'Undercity.$B$BHai un bel futuro nei ranghi della Signora Oscura, se continui a mostrare questa capacità di comando e questa perizia in battaglia.$B$BAnche se la nostra minaccia principale è l'esercito del Flagello del Re dei Lich che scende da nord, il \"problema\" umano continua a intralciare i nostri piani di battaglia. Tu però hai dimostrato che gli umani possono cadere, e cadranno.",
  en_title = "Battle of Hillsbrad",
  en_obj = "Take Darthalia's Sealed Commendation to Varimathras in the Undercity.",
}
T[551] = {
  title = "L'Ensorcelled Parchment",
  desc = "Questa pergamena è incantata con una magia che la rende indecifrabile. Ma una parola in cima al foglio si può leggere:$B$B$B      Nagaz",
  obj = "Porta l'Ensorcelled Parchment a Loremaster Dibbs, a Southshore.",
  progress = "Oh. Hai qualcosa che vorresti farmi vedere? Qualche frammento di sapere raccolto su in montagna, spero...",
  reward = "Altri appunti cifrati?$B$BVorrei avere il talento per decifrare tutti gli strani scritti che arrivano giù da Alterac. Ma temo di non avere le conoscenze necessarie.",
  en_title = "The Ensorcelled Parchment",
  en_obj = "Take the Ensorcelled Parchment to Loremaster Dibbs in Southshore.",
}
T[552] = {
  title = "La vendetta di Helcular",
  desc = "Master Helcular aveva quasi completato la sua trasformazione in Lich quando un gruppo di umani inferociti scoprì la sua tana rituale sulle colline e lo uccise brutalmente. Come se non bastasse, ne seppellirono il cadavere nel cimitero di Southshore.$B$BUna simile mancanza di rispetto per il grande mago è inaccettabile. Come suo apprendista, farò in modo che la pioggia della vendetta si abbatta sulla città di Southshore.$B$BPrima ci servirà Helcular's Rod. Gli Yeti hanno invaso la sua tana rituale. Senza dubbio ce l'ha una di quelle bestie.",
  obj = "Recupera Helcular's Rod dagli Yeti e riportala a Novice Thaivand, a Tarren Mill.",
  progress = "Hai già recuperato Helcular's Rod? Ci sono così tanti Yeti in questa regione che sarà molto difficile trovarla. Ma dobbiamo averla per andare avanti.",
  reward = "L'hai trovata! Ottimo, $N!",
  en_title = "Helcular's Revenge",
  en_obj = "Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.",
}
T[553] = {
  title = "La vendetta di Helcular",
  desc = "Tieni, prendi la Rod of Helcular. Ti servirà.$B$BHelcular preparò 3 pire cerimoniali come parte del suo incantesimo più potente. La Flame of Azel e la Flame of Veraz si trovano nelle Foothill Caverns. La Flame of Uzel si trova in una grotta sopra le caverne, più a nord tra le montagne.$B$BLa Rod of Helcular va caricata con ognuna delle tre fiamme. Una volta completato il rituale, conficca la verga nella tomba di Helcular a Southshore, la città umana a sud, sorvegliatissima. La vendetta sarà nostra!",
  obj = "Carica la Rod of Helcular con i poteri della Flame of Azel, della Flame of Veraz e della Flame of Uzel.$B$BConficca la verga carica nella tomba di Helcular, a Southshore.",
  progress = "La tomba di Helcular brulica di un'energia mistica.",
  reward = "Dal terreno sale un gran rombo.",
  en_title = "Helcular's Revenge",
  en_obj = "Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.$B$BDrive the charged rod into Helcular's grave in Southshore.",
}
T[554] = {
  title = "La decifrazione di Stormpike",
  desc = "Prospector Stormpike è un maestro della decrittazione e della decifrazione. Se gli porti la pergamena che hai trovato, con un po' di fortuna riuscirà a darle un senso. Stormpike al momento sta studiando nel quartier generale dei cercatori, a Ironforge.$B$BE quando lo vedi digli che hai parlato con me: ultimamente gli sto mandando parecchio lavoro.",
  obj = "Porta l'Ensorcelled Parchment a Prospector Stormpike, a Ironforge.",
  progress = "Altre interruzioni?$B$BAh, questa pergamena è coperta da un incantesimo molto intricato, tessuto con finezza. Posso districarlo, naturalmente, ma ci vorrà tempo. E il tempo per me è molto prezioso...$B$BForse te la compro e basta?",
  reward = "Una decisione saggia. Non credo che esista un altro studioso oltre a me con le capacità per tradurre questa pergamena. E se il suo contenuto si rivelerà interessante, non temere. Ti manderò a chiamare.",
  en_title = "Stormpike's Deciphering",
  en_obj = "Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge.",
}
T[555] = {
  title = "Soothing Turtle Bisque",
  desc = "Se c'è una cosa che imparerai su Southshore è che abbiamo una delle cucine migliori a nord di Stormwind!$B$BPrendi la mia ricetta segreta della Turtle Bisque, per esempio. Ho conosciuto gente che veniva da lontano come Darkshire solo per gustarsene una scodella. A proposito, ultimamente non riesco più a prepararla. Prima salivo io stesso oltre Dalaran, fino al Lake Lordamere, a cacciare gli Snapjaw, ma adesso è troppo pericoloso. Se mi porti un po' di Turtle Meat dagli Snapjaw a nord e delle Soothing Spices, te ne preparo un po'!",
  obj = "Porta 10 Turtle Meat e delle Soothing Spices a Chef Jessen, a Southshore.",
  progress = "Fortuna con gli ingredienti? Te lo dico io, questo territorio non è più il posto tranquillo di una volta. Ah, se solo non ci fossero stati questi disordini...",
  reward = "Saranno tutti contenti: la Soothing Turtle Bisque di Chef Jessen torna in tavola!",
  en_title = "Soothing Turtle Bisque",
  en_obj = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Chef Jessen in Southshore.",
}
T[556] = {
  title = "Gettoni di pietra",
  desc = "Un talento notevole dei maghi di Dalaran è la loro dimestichezza con gli elementali: creature potenti che vengono da altre dimensioni. I maghi usano gettoni magici per controllare questi elementali. Magus Voidglare vorrebbe qualcuno di questi gettoni da studiare.$B$BEntra nei territori dei maghi di Dalaran, a ovest di Hillsbrad, e raccogli i gettoni.$B$BPuoi trovarli addosso a qualunque cittadino di Dalaran, ma ti consiglio di andare a caccia al campo di internamento. È più sicuro di Dalaran stessa.",
  obj = "Porta 10 Worn Stone Token a Keeper Bel'varil, a Tarren Mill.",
  progress = "Hai i Worn Stone Token, $N? Il Magus non vede l'ora di svelarne i segreti.",
  reward = "Questi andranno benissimo. Anche se la loro magia sembra svanita, è meglio che i primi esperimenti del Magus siano su esemplari inerti come questi.$B$BGrazie, $N.",
  en_title = "Stone Tokens",
  en_obj = "Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.",
}
T[557] = {
  title = "Bracciali del vincolo",
  desc = "Il Magus sarà impegnato a studiare i gettoni di pietra che hai raccolto, ma so che prima o poi vorrà anche degli esemplari della loro controparte: i bracciali del vincolo. Vengono stretti ai polsi degli elementali veri e propri e li legano al servizio del mago.$B$BDa' la caccia agli elementali tra le rovine di Dalaran e raccogli i loro Bracers of Earth Binding: il Magus ne sarà contento.",
  obj = "Porta 4 Bracers of Earth Binding a Keeper Bel'varil, a Tarren Mill.",
  progress = "Salve, $N. Gli elementali sono una preda dura, ma so che sei all'altezza del compito. Hai quei bracciali del vincolo?",
  reward = "Li hai trovati. Immagino che gli elementali a cui li hai tolti fossero d'accordo?$B$BHm... la morte non mi ha solo fermato il cuore, a quanto pare mi ha anche tolto il senso dei tempi comici.$B$BBe', grazie, $N. Servi bene il Magus, e quindi la Signora Oscura.",
  en_title = "Bracers of Binding",
  en_obj = "Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.",
}
T[558] = {
  title = "Jaina's Autograph",
  desc = "Dicono che Lady Jaina Proudmoore, a Theramore, sia una delle più grandi eroine che l'Alleanza abbia mai avuto. Da grande voglio essere un eroe dell'Alleanza anch'io!$B$BConosci Jaina, $N? Mi faresti un favore, per piacere? Potresti procurarmi il suo autografo? Non so come chiederglielo, e probabilmente sarebbe troppo occupata per uno come me... ma tu! Sei $Gun avventuriero:un'avventuriera; proprio come lei! Scommetto che a te l'autografo lo darebbe subito!$B$BPer piacere?",
  obj = "Raggiungi Theramore e cerca di ottenere l'autografo di Lady Jaina Proudmoore per il tuo protetto.",
  progress = "Un giorno voglio essere un eroe proprio come Jaina... be', un eroe maschio, cioè.",
  reward = "WOW! Mi hai procurato l'autografo di Lady Jaina! Grazie mille! E wow... ci ha scritto sopra un messaggio personale, per me! Lo sapevo che sarebbe stata fantastica, e magari un giorno la ringrazierò di persona... quando diventerò un eroe dell'Alleanza!$B$BSei $Gil migliore:la migliore;, $N. Grazie di essere così gentile con me.",
  en_title = "Jaina's Autograph",
  en_obj = "Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward.",
}
T[559] = {
  title = "La prova di Farren",
  desc = "Ci credi, $N? Redpath non era soddisfatto di tutti i murloc che abbiamo ucciso... oh, adesso non fare $Gil modesto:la modesta;, un po' di mano ce l'hai messa anche tu. Adesso vuole che gli porti le prove dei morti: tagliare teste di murloc fredde e viscide da sottoporre alla sua approvazione.",
  obj = "Raccogli 10 Murloc Head dai murloc del Western Strand per Lieutenant Farren Orinelle, a Southshore.",
  progress = "Le hai prese quelle teste per me, $N?",
  reward = "Oh, per l'amor della Luce... stanno gocciolando per terra.$B$BIo non sopporto di toccare quelle cose. Il pesce va benissimo, ma quando mette le gambe e comincia a camminare... Non mangio pesce da settimane, credimi, e a Southshore questo vuol dire non mangiare granché.",
  en_title = "Farren's Proof",
  en_obj = "Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore.",
}
T[560] = {
  title = "La prova di Farren",
  desc = "Sai, $N, preferirei proprio non prendere queste teste... Visto che ormai le hai in mano tu, ti spiacerebbe consegnarle a Redpath per me?",
  obj = "Consegna il sacco di teste di murloc a Marshall Redpath, a Southshore.",
  progress = "Salve, $Gcittadino:cittadina;. Sei $Gvenuto:venuta; a offrire il tuo braccio per la sicurezza di Southshore?",
  reward = "Sei $Gil galoppino:la galoppina; di Farren, eh?$B$BSe hai aiutato Farren a procurarsi queste teste, allora grazie. Southshore ha bisogno di gente che lavori sodo e si impegni per mantenere la propria protezione.",
  en_title = "Farren's Proof",
  en_obj = "Deliver the sack of murloc heads to Marshall Redpath in Southshore.",
}
T[561] = {
  title = "La prova di Farren",
  desc = "Per favore, informa Lieutenant Orinelle che vorrei che concentrasse i suoi sforzi sui naga che infestano l'Eastern Strand. Quando avrà dei risultati, digli di venire a rapporto di persona.",
  obj = "Parla con Lieutenant Farren Orinelle, a Southshore.",
  reward = "I naga, eh? Redpath deve aver appena ricevuto la mia stessa informazione... Ah! Non sarà lui a prendersi una promozione grazie alla mia fatica. Lascia che ti spieghi.",
  en_title = "Farren's Proof",
  en_obj = "Speak with Lieutenant Farren Orinelle in Southshore.",
}
T[562] = {
  title = "Verso Stormwind!",
  desc = "Il mio vecchio mentore nella guardia cittadina di Stormwind mi ha mandato un messaggio: l'alto comando dell'Alleanza comincia a preoccuparsi per la minaccia dei naga. Da quel che ha sentito, ci sono buone possibilità di promozione — o almeno di trasferimento — per chi si dimostra utile su questo fronte.$B$BC'è solo un piccolo problema... Io i naga non li reggo, $N. Oh, certo, saprei sedare una rissa da taverna o portare via un mendicante molesto, ma i naga sono troppo per me. Devi aiutarmi, $N!",
  obj = "Uccidi 10 Daggerspine Shorehunter e 10 Daggerspine Siren per Lieutenant Farren Orinelle, a Southshore.",
  progress = "Ho una lettera pronta da mandare a Major Samuelson, a Stormwind. Mi servono solo i risultati.",
  reward = "Con i naga messi a tacere a Southshore, il trasferimento è praticamente mio. Rivedrò Stormwind... via da questo porto dimenticato dalla Luce.",
  en_title = "Stormwind Ho!",
  en_obj = "Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore.",
}
T[563] = {
  title = "Trasferimento",
  desc = "Non dovrebbe essere un problema far leggere il mio rapporto. Il nuovo capitano della guardia, Major Samuelson, era il mio mentore quando ero di stanza a Stormwind. Dovrebbe bastargli e avanzare come scusa per farmi trasferire di nuovo in città. Ho bisogno però che gli porti tu il mio rapporto... non vorrei che il vecchio Redpath se ne accorgesse.",
  obj = "Consegna il rapporto di Farren a Major Samuelson, a Stormwind Keep.",
  progress = "Salve, $Gcittadino:cittadina;. La guardia cittadina di Stormwind può esserti utile?",
  reward = "Cos'è questo? Ah... così il mio allievo attento si è dedicato al problema dei naga a Southshore. Grazie di avermelo portato, ne terrò senz'altro conto quando rivedrò le assegnazioni del personale il mese prossimo.",
  en_title = "Reassignment",
  en_obj = "Deliver Farren's report to Major Samuelson in Stormwind Keep.",
}
T[564] = {
  title = "Una minaccia costosa",
  desc = "Non c'è niente che mi dia più fastidio di perdere questi bei cavalli. E credimi, ne abbiamo persi parecchi tra quei fastidiosi non morti, quella maledetta banda del Syndicate e tutti gli altri buoni a nulla che gironzolano da queste parti.$B$BMa giuro sulla tomba del mio vecchio nonno che non c'è minaccia peggiore per i nostri cavalli dei Mountain Lion lassù ad Alterac. Scendono sempre dalle colline a complicarmi la vita!$B$BTi credi $Gun eroe:un'eroina;? E allora va' a fare qualcosa!",
  obj = "Darren Malvew, a Southshore, vuole che tu uccida 8 Mountain Lion e 10 Hulking Mountain Lion.",
  progress = "I Mountain Lion ci ammazzano i cavalli a destra e a manca e tu te ne stai qui a chiacchierare del tempo e di che altro.$B$BDovrei proprio andarmi a cercare $Gun eroe vero:un'eroina vera;. Più ammazzare e meno parlare.",
  reward = "Questa sì che è una bella notizia! Avrei dovuto cercarmi $Gun vero eroe:una vera eroina; di guerra fin dal primo giorno per occuparsi di quelle bestie. Tuo padre sarebbe stato fiero di te, $N.",
  en_title = "Costly Menace",
  en_obj = "Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.",
}
T[565] = {
  title = "Lo Yeti Fur Cloak di Bartolo",
  desc = "Io, il grande Bartolo, ti farò il famosissimo Yeti Fur Cloak, rinomato in tutta l'Alleanza!$B$BGira il mondo e trovati un mantello migliore, ti sfido. Oh, aspetta, cosa dici, $Gpiccolo:piccola; $R? \"Bartolo, non c'è mantello più bello!\" Sì, sì! Questo l'ho già sentito.$B$BA Bartolo servono un Bolt of Wool, un Hillman's Cloak fatto da un abile conciatore, del Fine Thread e Yeti Fur, naturalmente! Portami queste cose e sarai $Gun cliente soddisfatto:una cliente soddisfatta;!",
  obj = "Porta a Bartolo Ginsetti, a Southshore, un Bolt of Wool, un Hillman's Cloak, del Fine Thread e 10 ciuffi di Yeti Fur.",
  progress = "Così sei $Gtornato:tornata; dal grande Bartolo. Forse hai finito di raccogliere i materiali per il tuo Yeti Fur Cloak? O magari ti piace soltanto crogiolarti nella grandezza di me, Bartolo!",
  reward = "Ora è il momento che il grande Bartolo faccia la sua magia! Non mi serve il bastone di un mago né la verga di un incantatore. Perché io, il grande Bartolo, faccio magie con un semplice ago e un filo!",
  en_title = "Bartolo's Yeti Fur Cloak",
  en_obj = "Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur.",
}
T[566] = {
  title = "WANTED: Baron Vardus",
  desc = "Per ordine di High Executor Darthalia, l'umano noto come Baron Vardus è ricercato per crimini contro i Reietti. Vardus è noto come membro di alto rango dell'organizzazione chiamata Syndicate.$B$BÈ stato avvistato l'ultima volta nelle Uplands, nelle Alterac Mountains, a nord di Tarren Mill.$B$BLo si vuole morto. Porta la prova della sua morte a High Executor Darthalia per riscuotere la ricompensa.",
  obj = "Uccidi Baron Vardus e consegna la sua testa a High Executor Darthalia, a Tarren Mill.",
  progress = "Ah, $N. Forse sei $Gvenuto:venuta; a riscuotere la taglia sulla testa di Baron Vardus?",
  reward = "Un lavoro produttivo il tuo, $N. Con Baron Vardus morto, il numero dei capi del Syndicate diminuisce. La loro resistenza e il loro fastidio avranno vita breve.",
  en_title = "WANTED: Baron Vardus",
  en_obj = "Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.",
}
T[567] = {
  title = "Pericolosi!",
  desc = "Pericolosi!$B$BI seguenti umani di Hillsbrad sono stati giudicati pericolosi e su di loro pende una taglia di High Executor Darthalia:$B$BClerk Horrace Whitesteed. Ricercato per l'omicidio di Deathguard Toma.$B$BCitizen Wilkes. Ricercato per l'omicidio di Apothecary Eli.$B$BMiner Hackett. Ricercato per l'omicidio di Deathstalker Fry.$B$BFarmer Kalaba. Ricercato per l'imboscata ai rifornimenti dell'Undercity.$B$BTutti questi nemici sono nascosti e saranno difficili da trovare. Una ricompensa sarà concessa alla notizia della loro morte.",
  obj = "High Executor Darthalia, a Tarren Mill, offre una taglia su Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett e Farmer Kalaba.",
  progress = "Sì?",
  reward = "Sei $Gun bel cacciatore:una bella cacciatrice; di taglie, $C. Ben fatto.",
  en_title = "Dangerous!",
  en_obj = "High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.",
}
T[568] = {
  title = "La difesa di Grom'gol",
  desc = "Throm'ka, $C!$B$BIl tuo arrivo a Grom'gol è davvero tempestivo. Come comandante del campo base del Capoguerra qui nella giungla, l'onore mi impone di garantire la sicurezza di tutti i membri dell'Orda. La nostra missione di assicurare una linea di rifornimento sicura verso Stonard è ostacolata da alcuni degli abitanti del posto.$B$BTi affido il compito di sfoltire la popolazione di raptor fuori da Grom'gol. Quando avrai fatto progressi significativi, torna a riferire da me per un nuovo incarico.",
  obj = "Commander Aggro'gosh, del campo base di Grom'gol, vuole che tu uccida 15 Lashtail Raptor.",
  progress = "I nostri rifornimenti sono ancora ostacolati dai raptor del posto, $C.",
  reward = "Hai compiuto il tuo dovere con onore, $C.",
  en_title = "The Defense of Grom'gol",
  en_obj = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.",
}
T[569] = {
  title = "La difesa di Grom'gol",
  desc = "Quando siamo arrivati in questa giungla non avevamo intenzione di fare guerra alle tribù del posto. La nostra missione di rifornire Stonard ha la massima priorità. Ma sono sorte delle complicazioni. Una banda di ogre del posto ha occupato le Mizjah Ruins, a sud-est di Grom'gol. Nonostante gli avvertimenti, continuano a tendere agguati alle nostre carovane di rifornimenti.$B$BTi affido il compito di occuparti di questi ogre poco collaborativi.$B$BVa' alle rovine e cerca di cacciarli dalla zona. Se non altro, sarà un messaggio chiaro.",
  obj = "Commander Aggro'gosh, del campo base di Grom'gol, vuole che tu uccida 10 Mosh'Ogg Brute e 5 Mosh'Ogg Witch Doctor.",
  progress = "Hai fatto progressi con gli ogre delle Mizjah Ruins, $C?",
  reward = "Ben fatto. Hai servito il Capoguerra con onore.",
  en_title = "The Defense of Grom'gol",
  en_obj = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.",
}
T[570] = {
  title = "L'incantamento di Mok'thardin",
  desc = "Il potere della magia della giungla va compreso e poi imbrigliato dall'Orda. Finora i miei rituali hanno avuto successo. Posso lanciare incantamenti molto potenti. Per te, $Gvaloroso:valorosa; $C, creerò davvero un oggetto speciale.$B$BPortami degli artigli di Shadowmaw Panther e una zanna di tigressa. Non va bene una zanna qualsiasi: deve essere in condizioni perfette.$B$BLe bestie si aggirano in tutta la giungla, ma ne troverai alcune qui vicino, appena oltre il fiume, dalle Mizjah Ruins verso sud-est.",
  obj = "Far Seer Mok'thardin, al campo base di Grom'gol, vuole 8 Shadowmaw Claw e una Pristine Tigress Fang.",
  progress = "Che notizie porti?",
  reward = "La tua conoscenza della giungla è grande, $N. Questi esemplari saranno perfetti. Ringrazierò gli spiriti per aver sacrificato bestie così belle alla causa dell'Orda.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.",
}
T[571] = {
  title = "L'incantamento di Mok'thardin",
  desc = "Quello che mi serve adesso sarà molto difficile da procurare.$B$BPer tenere insieme tutte queste piume, gli artigli e la zanna perfetta, mi serve un legame magico. Funzionerà solo un Aged Gorilla Sinew.$B$BPotrai trovarne uno solo su un Elder Mistvale Gorilla. Si sa che vanno in cerca di cibo a est di Booty Bay.$B$BIl tendine deve essere perfetto. Potresti doverne uccidere parecchi prima di trovare esattamente quello che mi serve, ma la caccia ne varrà la pena.",
  obj = "Porta un Aged Gorilla Sinew a Far Seer Mok'thardin, a Grom'gol.",
  progress = "La fortuna è stata dalla tua parte, $N? Sei $Griuscito:riuscita; a procurarti un Aged Gorilla Sinew?",
  reward = "Un tendine davvero perfetto, $N. I tuoi sforzi saranno presto ripagati.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol.",
}
T[572] = {
  title = "L'incantamento di Mok'thardin",
  desc = "Le cose che hai raccolto dalle bestie feline della Vale sono solo il primo requisito per un potente oggetto incantato. Questi ninnoli della giungla, uniti al mio rituale sciamanico, ti daranno uno strumento molto utile per aiutare l'Orda e il Capoguerra.$B$BMa ora devi raccogliere per me delle Jungle Stalker Feather. Per tradizione, le bestie portano le piume sulle fasce che hanno al braccio. Troverai una tribù di questi raptor proprio a sud di Grom'gol, non lontano dalla grande arena.",
  obj = "Porta 10 Jungle Stalker Feather a Far Seer Mok'thardin, al campo base di Grom'gol.",
  progress = "La tua raccolta ha dato frutti?",
  reward = "Eccellente. Le preparerò subito.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.",
}
T[573] = {
  title = "L'incantamento di Mok'thardin",
  desc = "Manca solo un ultimo reagente per completare l'incantamento.$B$BA sud, verso la costa occidentale, in alto sopra le scogliere, si trova la Holy Spring. Questa sorgente è oggetto di grande contesa tra studiosi di religione e di misticismo. Ogni razza di Azeroth sostiene che le acque della sorgente siano state rese divine per il proprio popolo.$B$BL'ultima cosa che ti chiedo: portami della Holy Spring Water. Ma fa' attenzione. Una spedizione di Naga Explorer è avanzata fino alla sorgente. Dovrai occuparti anche di loro.",
  obj = "Far Seer Mok'thardin, di Grom'gol, ha bisogno di Holy Spring Water. Vuole anche che tu uccida 10 Naga Explorer.",
  progress = "Sono quasi pronto a completare l'incantamento. Hai fatto quanto ti ho chiesto?",
  reward = "Con questa Holy Spring Water il girocollo cerimoniale è pronto per l'incantamento.$B$BPortalo con orgoglio, $N, in nome del Capoguerra e in difesa della possente Orda.",
  en_title = "Mok'thardin's Enchantment",
  en_obj = "Far Seer Mok'thardin of Grom'gol needs Holy Spring Water.  He also wants you to kill 10 Naga Explorers.",
}
T[574] = {
  title = "Forze speciali",
  desc = "Ora che molte delle sue truppe regolari sono state decimate, devi affrontare le sue forze meglio addestrate. Quando non sono nelle terre selvagge a massacrare i nostri soldati ribelli, si trovano in fondo al Kurzen's Compound, in una caverna che chiamano lo Stockpile.$B$BConosco di persona molti soldati di Kurzen, e so che sono abili, leali e crudeli. Non è un compito facile quello che ti affido, $N.$B$BDopo averli sconfitti, fai rapporto a Lieutenant Doren, il mio ufficiale comandante. Vorrà sentire il tuo rapporto di persona.",
  obj = "Uccidi 10 Kurzen Commando e 6 Kurzen Headshrinker.$B$BFai rapporto a Lieutenant Doren, al Rebel Camp.",
  progress = "Sergeant Yohwa mi dice che sei abile e $Gcoraggioso:coraggiosa;, $C. Hai qualcosa da riferire?",
  reward = "$N. Sergeant Yohwa si fidava delle tue capacità, e io mi fido di lei. La sconfitta che hai inflitto alle forze di Kurzen va quasi oltre ogni speranza. Temevo che noi ribelli fossimo soli, e da soli non avremmo mai potuto tenere testa alla genialità del colonnello.$B$BForse c'è ancora speranza di sopravvivere.",
  en_title = "Special Forces",
  en_obj = "Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.$B$BReport to Lieutenant Doren at the Rebel Camp.",
}
T[575] = {
  title = "Domanda e offerta",
  desc = "\"Il miglior conciatore dei South Seas e dei mondi vecchi e nuovi.\" È così che mi chiamano. Io! Drizzlik! Il miglior concia... Ehm. Bene.$B$BI miei articoli in pelle sono noti in lungo e in largo come i più raffinati, la scelta degli intenditori!$B$BHo appena ricevuto un ordine da Director Riddlevox della Tinkers' Union per una dozzina dei suoi stivali preferiti della linea Excelsior. I nostri più venduti, a dire il vero.$B$BPer cominciare con la forma di base, mi servono pelli di crocolisk prese dai coccodrilli lungo il fiume, nella Stranglethorn settentrionale.",
  obj = "Porta 2 Large River Crocolisk Skin a Drizzlik, a Booty Bay.",
  progress = "La mia attrezzatura è pronta, $N, mi servono solo quelle pelli. Non vogliamo far aspettare Riddlevox, questo è certo.$B$BNon è una buona idea, per nessuno, lasciare insoddisfatto il capo inventore della Tinkers' Union.",
  reward = "Queste pelli dovrebbero andare. La loro qualità non conta troppo, visto che formeranno lo strato interno degli stivali, ma è comunque importante che siano comode.$B$BSe sono un po' troppo rigide, userò del sangue di tigre per ammorbidirle. Trucchi del mestiere, sai?",
  en_title = "Supply and Demand",
  en_obj = "Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.",
}
T[576] = {
  title = "Apri l'occhio",
  desc = "Alt! Chi va là?$B$BArgh, senza il mio speciale occhio incantato non servo a niente. Già era abbastanza brutto aver perso gli occhi in battaglia! Ma per un colpo di fortuna abbiamo attraccato a Menethil, e un mago girovago ha incantato uno speciale occhio di vetro che mi ha fatto tornare a vedere.$B$BIeri notte, mentre uscivo, mi sono fatto assalire da un gruppo di Bloodsail Buccaneers. Mi hanno preso l'occhio, sì! Pare che quei tizi siano arrivati fino a Booty Bay.$B$BAiuti un vecchio lupo di mare a riavere il suo occhio?",
  obj = "Dizzy One-Eye, a Booty Bay, vuole che tu recuperi il suo occhio dai Bloodsail Buccaneers.",
  progress = "Ahoy, $Gragazzo mio:ragazza mia;! Forse non ci vedo, ma ti sento l'odore da un capo all'altro del porto.$B$BMi servirebbe proprio il mio occhio. Il capitano mi farà passare sotto la chiglia quando scoprirà che la mia pupilla è nelle mani di quegli sporchi Bloodsail Buccaneers.$B$BA cosa serve una vedetta che non ci vede? La coffa era la mia casa... senza i miei fanali sarei fortunato a poter strofinare la sentina.",
  reward = "Corpo di mille balene e balene di mille corpi! Hai trovato il mio bell'occhio! Vediamo se entra ancora.$B$B$N in vista! Perbacco, ci vedo!!",
  en_title = "Keep An Eye Out",
  en_obj = "Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.",
}
T[577] = {
  title = "Montaggio richiesto",
  desc = "Be', ho messo a punto la forma di base degli stivali, e stanno venendo bene, ma le pelli che mi hai portato non basteranno per gli strati interni.$B$B\"Cosa facciamo, Drizzlik?\" È senz'altro la domanda che hai sulle labbra, e be', che fortuna che tu stia parlando con Drizzlik, perché ora ti dirà lui cosa faremo!$B$BGli strati interni non si vedranno mai davvero, quindi prenderemo delle pelli più spesse ed economiche dai coccodrilli intorno al Lake Nazferiti per imbottire gli stivali.",
  obj = "Porta 5 Snapjaw Crocolisk Skin a Drizzlik, a Booty Bay.",
  progress = "Stivali di cuoio Excelsior di Drizzlik, lavorazione finissima, stivali al cento per cento in pelle di crocolisk d'acqua salata di alta qualità. Non ce n'è di migliori!$B$BDifficile battere una descrizione così entusiasta, vero?$B$BTranne, forse, se hai quelle pelli per me?",
  reward = "I miei stivali... sono come le salsicce, $N. Bell'aspetto, ottimo sapore. Ti dico che sono pieni solo degli ingredienti e delle carni migliori, e tu li mangi, e ti piacciono.$B$BÈ più sicuro, e più piacevole, se ti fidi di me e non chiedi troppo nei dettagli cosa c'è davvero dentro.",
  en_title = "Some Assembly Required",
  en_obj = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.",
}
T[578] = {
  title = "La Stone of the Tides",
  desc = "Se sull'isola ci sono davvero un mago goblin e dei Water Elemental, potrebbe significare che la Stone of the Tides può essere mia!$B$BVoglio che tu trovi quest'isola infestata... e scopra cosa sta succedendo. Ah, e se per caso vuoi saperne di più sulla Stone of the Tides, porta questo biglietto alla Stormwind Library: dovrebbero riuscire a trovarti una copia del libro in cui ho letto per la prima volta la leggenda.$B$BPossibile che Gazban abbia davvero scoperto la pietra...?",
  obj = "Trova l'isola infestata per Baron Revilgaz, a Booty Bay.",
  progress = "I troll possedevano davvero oggetti magici straordinari, $N. E ora, forse, ho l'occasione di aggiungerne uno alla mia vasta collezione. Hai avuto fortuna a trovare l'origine della voce?",
  reward = "Allora le storie erano vere! Incredibile!$B$BPerò dovremo trovare un modo per vincere la maledizione della Stone of the Tides, se vogliamo recuperarla. La maledizione è una faccenda magica: ci servirà uno di quei maghi per aiutarci.",
  en_title = "The Stone of the Tides",
  en_obj = "Find the haunted island for Baron Revilgaz in Booty Bay.",
}
T[579] = {
  title = "La biblioteca di Stormwind",
  progress = "Re Anduin attribuisce grande importanza all'istruzione, e per questo ha stanziato fondi per rendere disponibili al pubblico copie di vari tomi e scritti. È molto semplice. Mi porti un library scrip e posso darti una copia di uno dei libri disponibili.",
  reward = "Qualcuno di questi titoli ti interessa, $N?",
  en_title = "Stormwind Library",
}
T[580] = {
  title = "Il grog perduto di Whiskey Slim",
  desc = "Stavamo brindando a più non posso al largo delle Overlook Cliffs, con le vecchie Hinterlands appena in lontananza. Pensavo che il mare ci avrebbe inghiottiti tutti interi.$B$BIl vecchio Slim sa tutto sul coraggio in bottiglia! Il capitano aveva una cassa di Pupellyverbos Port che avevamo requisito a un corsaro diretto a Stormwind.$B$BCosì, quando è arrivata quella tempesta al largo delle Hinterlands, ho fatto irruzione nel grog. Un'onda grossa ci ha colpiti e ha buttato quelle bottiglie fuori bordo. Il capitano mi farà assaggiare il gatto a nove code, se non mi aiuti a riprenderle!",
  obj = "Whiskey Slim, a Booty Bay, vuole che tu gli porti le bottiglie di Pupellyverbos Port che ha perso.",
  progress = "Che mi venga un colpo! Sto quasi finendo l'alcol! Il capitano leverà l'ancora e il vecchio Slim resterà a secco come il Tanaris Desert. E quando scoprirà che manca il suo Pupellyverbos Port... accidenti!",
  reward = "Corpo di mille balene! Hai trovato il grog del capitano!$B$BTi devo un grosso favore, $Gamico:amica;.$B$BPare che fuori si stia preparando una tempesta. Forse mi terrò al caldo con una di queste bottiglie mentre aspettiamo che passi...",
  en_title = "Whiskey Slim's Lost Grog",
  en_obj = "Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.",
}
T[581] = {
  title = "Alla ricerca di Yenniku",
  desc = "Una sventura incombe. Una sventura sul figlio più giovane del mio capo, Yenniku. Come vuole un'usanza del nostro popolo, fu affidato ai troll Gurubashi di Zul'Gurub, ma dopo che la mia tribù, la tribù Darkspear, se ne andò con l'orco Thrall, il povero Yenniku fu perduto per noi. Sono stato mandato dalla lontana Orgrimmar, di nuovo a Stranglethorn, a cercare il figlio del mio capo.$B$BE credo che sia nelle mani della tribù Bloodscalp.$B$BSe vuoi aiutarmi, dai la caccia ai Bloodscalp. Puoi trovarli a nord. Raccogli le loro zanne e torna da me.",
  obj = "Porta 9 Bloodscalp Tusk a Nimboya, al Grom'gol Base Camp.",
  progress = "$C. Mostrami che hai fatto preda della tribù Bloodscalp.$B$BMostrami i tuoi trofei.",
  reward = "Sono buone zanne, $N. Dimostri di avere la forza per dare la caccia ai Bloodscalp.$B$BE questo è un bene, perché non hai ancora finito di cacciarli.",
  en_title = "Hunt for Yenniku",
  en_obj = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.",
}
T[582] = {
  title = "A caccia di teste",
  desc = "Dobbiamo scoprire se Yenniku è morto.$B$BUccidi i Bloodscalp Headhunter e prendi le loro Shrunken Head. Devi raccogliere molte, molte teste, e io le esaminerò per assicurarmi che tra queste non ci sia quella di Yenniku.$B$BE se Yenniku è stato ucciso dai Bloodscalp, allora che una maledizione di 600 anni si abbatta sullo spirito del loro capo, Gan'zulah!$B$BVa', $N. Troverai molti Headhunter presso le rovine di Zuuldaia e Zul'Kunda, lungo la costa a nord.",
  obj = "Porta 20 Shrunken Head a Nimboya, al Grom'gol Base Camp.",
  progress = "$N. Temo per il figlio del nostro capo. Hai le Shrunken Head, così che io possa esaminarle?",
  reward = "Grazie, $N. Esaminerò queste teste per assicurarmi che il povero Yenniku sia stato risparmiato dall'ascia del cacciatore di teste.",
  en_title = "Headhunting",
  en_obj = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.",
}
T[583] = {
  title = "Benvenuti nella giungla",
  desc = "$GBenvenuto:Benvenuta; a Stranglethorn!$B$BForse non lo sai, ma quel nano laggiù è l'unico e inimitabile Hemet Nesingwary, famoso eroe di guerra dell'Alleanza e maestro della caccia grossa. Non è tipo da accogliere estranei nel suo accampamento, ma dall'aspetto si direbbe che tu ne abbia viste parecchie, $C.$B$BEssendo anche lui un veterano di molte battaglie, Master Nesingwary ha un debole per i compagni eroi.$B$BVa' a parlargli. Forse può darti qualche consiglio di caccia.",
  obj = "Parla con Hemet Nesingwary.",
  reward = "Proprio un piacere fare la tua conoscenza, $N. Era da un po' che non vedevo $Gun:una; $C da queste parti.$B$BMi sono unito a questa spedizione per un solo scopo: cacciare una bestia grande e sfuggente. Visto che sei una specie di $Geroe:eroina;, sono disposto a farti partecipare alla caccia, ma prima devi dimostrare quanto vali.$B$BTi insegnerò l'arte di uccidere i raptor. Ajeck ti addestrerà nella caccia alla tigre. E Sir Erlgadin è un maestro nel seguire le tracce delle pantere.$B$BDimostra la tua abilità e ti farò partecipare alla grande caccia.",
  en_title = "Welcome to the Jungle",
  en_obj = "Speak with Hemet Nesingwary",
}
T[584] = {
  title = "Le teste del clan Bloodscalp",
  desc = "Yenniku non era tra le teste, e ne ringrazio il Grande Serpente. Ma non siamo più vicini a trovarlo.$B$BDobbiamo conoscere la verità, e temo che la conoscano solo il capo dei Bloodscalp e il suo stregone. Sono nemici della tribù Darkspear e non parleranno di loro spontanea volontà, quindi dovremo strappare la verità dalle loro labbra morte!$B$BPortami le teste di Gan'zulah e di Nezzliok the Dire e mettile in questo calderone.$B$BSi trovano nel cuore di Zul'Kunda. Porta le loro teste... poi li faremo parlare.",
  obj = "Porta Gan'zulah's Head e Nezzliok's Head al Bubbling Cauldron, al Grom'gol Base Camp.",
  progress = "Il brodo verdastro nel calderone ribolle.",
  reward = "Metti le teste di Gan'zulah e di Nezzliok nel calderone...",
  en_title = "Bloodscalp Clan Heads",
  en_obj = "Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.",
}
T[585] = {
  title = "A colloquio con Nezzliok",
  desc = "<La testa di Nezzliok parla.>$B$BÈ vero. So dove è stato portato il figlio dei Darkspear. Mi hai sconfitto e hai incatenato il mio spirito, ma non dirò nulla senza un'offerta che mi plachi!$B$BI Bloodscalp sono in guerra con gli Skullsplitter. Per guadagnarti il mio favore, ruba agli Skullsplitter 3 dei loro teschi trofeo e mettili qui con noi, così che il mio spirito abbia degli schiavi nel Nether. Un teschio deve venire dal loro mucchio di trofei a Balia'mah, un altro da Ziata'jai e l'ultimo da Zul'Mamwe.",
  obj = "Porta un Balia'mah Trophy, un Ziata'jai Trophy e un Zul'Mamwe Trophy al Bubbling Cauldron, al Grom'gol Base Camp.",
  progress = "Attendo i teschi...",
  reward = "Sì. Questi mi serviranno bene. Quando il mio spirito sarà liberato, entrerò nel Nether con tre ottimi servitori!$B$BSei $Gun:una; $R che fa onore al suo clan, e hai saputo placarmi.",
  en_title = "Speaking with Nezzliok",
  en_obj = "Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.",
}
T[586] = {
  title = "A colloquio con Gan'zulah",
  desc = "<La testa di Gan'zulah parla.>$B$BTi maledico! E maledico i tuoi antenati!$B$BSolo il sangue e la vendetta possono placare la mia rabbia, quindi se è questo che desideri, allora... fai così:$B$BGettati nel cuore degli Skullsplitter, a est. Uccidi i più feroci tra loro e, se sopravvivi... va' a infrangerti contro il loro capo, Ana'thek the Cruel. Ah! Portami la sua armatura in frantumi, se ci riesci!$B$BChe ti strappi gli arti e ti lasci a marcire, pasto per i necrofagi.",
  obj = "Uccidi 8 Skullsplitter Hunter, 6 Skullsplitter Headhunter e 4 Skullsplitter Berserker.$B$BPorta la Broken Armor of Ana'thek al Bubbling Cauldron, al Grom'gol Base Camp.",
  progress = "Anche se la mia carne si stacca bollendo dal teschio, sento ancora l'odore della tua paura.$B$BAh! Non porterai mai a termine il mio compito...",
  reward = "Non voglio crederci, ma non posso negare ciò che hai fatto. E la mia rabbia si placa, ora che Ana'thek è stato sconfitto.$B$BLa tua potenza ti porterà a grandi imprese, $N. Ma un giorno... ti rivedrò nel Nether, e misureremo di nuovo le nostre forze.$B$BTi aspetterò.",
  en_title = "Speaking with Gan'zulah",
  en_obj = "Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.$B$BBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.",
}
T[587] = {
  title = "Una presa di tabacco",
  desc = "Ah, la vita di mare. Non dirò che è la bella vita, ma è la mia vita.$B$BQuando arrivo in porto mi piace trovarmi una buona bottiglia di grog e del tabacco da fiuto di qualità. Brutte abitudini, ma cos'è un pirata senza i suoi vizi, giusto?$B$BQuindi puoi immaginare quanto ci sono rimasto male quando ho scoperto che l'erborista qui in città l'ha finito. Dice che il suo carico è stato dirottato da quei maledetti Bloodsail Raiders.$B$BScommetto che $Gun:una; $C $Gimpavido:impavida; come te potrebbe convincerli a dividere la merce, eh?",
  obj = "Deeg, a Booty Bay, vuole che tu gli porti 15 porzioni di Snuff.",
  progress = "Hai avuto fortuna con la merce, $Gcompagno:compagna;?",
  reward = "Ottimo lavoro, $N! E proprio prima che io debba salpare! Non so come ringraziarti, $Gvecchio amico mio:vecchia amica mia;.",
  en_title = "Up to Snuff",
  en_obj = "Deeg in Booty Bay wants you to bring him 15 shares of Snuff.",
}
T[588] = {
  title = "Il destino di Yenniku",
  desc = "<Nezzliok parla.>$B$BHai placato me e il mio capo, quindi ti dirò ciò che cerchi di scoprire...$B$BIl giovane Yenniku è perduto per il suo clan.$B$BÈ stato preso dallo stregone Zanzil the Outcast. Ora Zanzil lo controlla, corpo e anima, e solo la magia più potente potrebbe liberarlo.$B$BUna magia che tu non possiedi, $C.$B$BForse i tuoi alleati Darkspear possono offrire una speranza di salvezza per Yenniku. Ma ne dubito.",
  obj = "Parla con Kin'weelay.",
  reward = "Zanzil the Outcast?$B$BSe Yenniku è prigioniero di quel troll, uno stregone vile e potente, allora temo che resti solo una debole speranza. Debole. E minuscola come il più piccolo degli insetti.$B$BMa è pur sempre una speranza.",
  en_title = "The Fate of Yenniku",
  en_obj = "Speak with Kin'weelay.",
}
T[589] = {
  title = "I Singing Crystals",
  desc = "Le leggende parlano di un gioiello nascosto nel profondo del cuore di Stranglethorn. Lo chiamiamo il Mind's Eye, e ha grandi poteri. Se riuscirai a ottenere questo Eye, forse potremo usarlo per riportare il perduto Yenniku fuori dall'oscurità.$B$BConsulterò gli spiriti della giungla per trovare il Mind's Eye. Nel frattempo, tu entra nella Crystalvein Mine, a sud-est di qui, e raccogli dei Pulsing Blue Shard dagli Ironjaw Basilisk. I frammenti sono rari, ma ci servirà la loro magia per piegare il Mind's Eye alla nostra volontà.",
  obj = "Porta 3 Pulsing Blue Shard a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Hai i frammenti, $N? Mi servono per il mio rituale finale, quando avremo il Mind's Eye.",
  reward = "Hai fatto bene, $N. Questi frammenti sono ben formati. Già li sento cantare per me.$B$BE mentre eri via, ho parlato con gli spiriti della giungla. So dove si trova il Mind's Eye...$B$B...E chi lo custodisce.",
  en_title = "The Singing Crystals",
  en_obj = "Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.",
}
T[590] = {
  title = "L'accordo di un furfante",
  desc = "Cosa?$B$BCosa?!$B$BVuoi dei soldi? Non ti devo nessun soldo.$B$BUna lettera? Quale lettera? Oh, vuoi combattere allora? D'accordo, amico... facciamolo! Ti devo dei soldi...",
  obj = "Sconfiggi Calvin Montague a Deathknell.",
  reward = "Incredibile! Che abilità!$B$BPensavo fossi una facile preda, $N. Mi hai fregato per bene, eh.$B$BEcco la moneta che ti avevo promesso... non quanto avevo detto, ma è colpa del fatto che ti ho mentito fin dall'inizio.",
  en_title = "A Rogue's Deal",
  en_obj = "Defeat Calvin Montague in Deathknell.",
}
T[591] = {
  title = "Il Mind's Eye",
  desc = "Il Mind's Eye è nelle mani di un mago ogre, a est di qui, nel profondo del tumulo degli ogre Mosh'Ogg. Si chiama Mai'Zoth. Lo conosco da quando i Darkspear vivevano a Stranglethorn — è crudele, e la sua magia è potente.$B$BE se ha il Mind's Eye, la sua magia sarà ancora più forte.$B$BDevi affrontare Mai'Zoth e strappargli il Mind's Eye. È un compito pericoloso, ma è l'unica speranza che abbiamo di salvare Yenniku.",
  obj = "Porta il Mind's Eye a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Salute, $N. Gli spiriti cantano lodi al tuo coraggio, eppure non mi raccontano nulla della tua impresa contro Mai'Zoth.$B$BHai l'Eye?",
  reward = "Hai recuperato l'occhio! La tua potenza è materia da leggenda, $N!$B$BE per prendere l'Eye devi aver sconfitto Mai'Zoth e averlo mandato nel Nether. Ecco perché prima gli spiriti non volevano nominarlo.$B$BÈ un bene che abbia lasciato il mondo della carne e delle ossa, ma ora che si trova nel regno degli spiriti... temo che darà inizio a un nuovo dominio.$B$BMa questa è una preoccupazione per un'altra volta. Ora devo celebrare un rituale per piegare il Mind's Eye ai nostri bisogni...",
  en_title = "The Mind's Eye",
  en_obj = "Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.",
}
T[592] = {
  title = "Salvare Yenniku",
  desc = "Ho trasformato il Mind's Eye in una Soul Gem. Il suo scopo è duplice: devi usarla per stordire Yenniku e, una volta stordito, posargliela sulla testa per imprigionarne l'anima.$B$BPoi porta la gemma a Nimboya.$B$BYenniku vive con Zanzil the Outcast, nelle Ruins of Aboraz, lungo la Crystal Shore, nel lontano Cape of Stranglethorn.",
  obj = "Porta la Filled Soul Gem a Nimboya.",
  progress = "$N. Kin'weelay mi ha detto che sei $Gpartito:partita; per catturare Yenniku.$B$BÈ vero? L'hai preso?",
  reward = "Ce l'hai fatta! Hai liberato Yenniku dalla volontà di Zanzil e hai portato a termine la missione che credevo così disperata.$B$BLa nostra tribù ricorderà il tuo nome nei canti, $N, e incideremo la tua storia nella pietra perché viva per sempre.",
  en_title = "Saving Yenniku",
  en_obj = "Bring the Filled Soul Gem to Nimboya.",
}
T[593] = {
  title = "Riempire la Soul Gem",
  progress = "Yenniku è in piedi davanti a te, stordito, con la mente altrove...",
  reward = "Posi la Soul Gem sulla sua fronte. Rabbrividisce mentre la sua anima viene risucchiata, lasciandosi dietro il corpo, un guscio vuoto senza mente.",
  en_title = "Filling the Soul Gem",
}
T[594] = {
  title = "Messaggio in bottiglia",
  desc = "Il biglietto dice, con una calligrafia piuttosto buona:$B$BA chiunque possa aiutarmi:$B$Bti prego, ho un disperato bisogno di aiuto. Un grande Skymane mi tiene prigioniera su un'isola dei South Seas.$B$BLe stelle, di notte, mi sono sconosciute e nascoste dagli alberi della giungla, ma nei giorni più limpidi vedo la Wild Shore a nord-ovest, e quelle che sembrano grandi navi a vela a sud-ovest.$B$BTi supplico, $Gmio salvatore:mia salvatrice;, ti prego, aiutami.",
  obj = "Trova chi ha scritto il messaggio in bottiglia.",
  reward = "Sei $Gvenuto:venuta; a liberarmi?",
  en_title = "Message in a Bottle",
  en_obj = "Find the author of the message in a bottle.",
}
T[595] = {
  title = "I Bloodsail Buccaneers",
  desc = "Hai proprio voglia di lavorare, $Gcompagno:compagna;. Non so perché $Gun:una; $C $R di terraferma voglia aiutare i Blackwater Raiders, ma non ti manderò via.$B$BLa nostra nave è appena attraccata qui a Booty Bay, e si dice che i nostri rivali, quei maledetti, sporchi Bloodsail Buccaneers, siano stati avvistati in tutta la Stranglethorn meridionale.$B$BI ragazzi sono tutti troppo presi dal grog e dalle donne! Mi serve un esploratore.$B$BControlla l'insenatura appena a nord di Booty Bay, lungo la Savage Coast, e vedi cosa trovi.",
  obj = "First Mate Crazz vuole che tu controlli l'insenatura a nord di Booty Bay.",
  reward = "Sopra il barile trovi una mappa con un testo scritto in fretta, insieme a qualche moneta.",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "First Mate Crazz wants you to check the cove north of Booty Bay.",
}
T[596] = {
  title = "Bloody Bone Necklaces",
  desc = "Sono stato mandato a Grom'gol per aiutare Nimboya nella sua missione, ma... anch'io ho le mie ragioni per essere qui.$B$BLa tribù Bloodscalp è nemica della nostra tribù. Raccogliere trofei dei nostri nemici ci dà potere su di loro. Puoi aiutare la nostra tribù dando la caccia ai nostri nemici.$B$BVivono a nord. Uccidi i troll Bloodscalp e prendi le loro Bloody Bone Necklace. Raccoglile in gran numero, e la tua ricompensa sarà grande.",
  obj = "Porta 25 Bloody Bone Necklace a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Un giorno i Bloodscalp saranno schiacciati dai Darkspear! Hai le collane del nostro nemico condannato?",
  reward = "Ah, molto bene. Le farò bollire, le prosciugherò, e gli spiriti dei loro proprietari si indeboliranno mentre riduco in poltiglia le loro collane!$B$BEcco, $N. Questo ripagherà il mio debito con te.",
  en_title = "Bloody Bone Necklaces",
  en_obj = "Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.",
}
T[597] = {
  title = "I Bloodsail Buccaneers",
  desc = "La mappa mostra Booty Bay con una \"X\" rossa disegnata esattamente nel punto in cui ti trovi.$B$BIl testo scarabocchiato dice:$B$B\"Voi uomini dovete allestire un accampamento in questo punto e restare in silenzio. Aspettate il segnale dal posto di comando meridionale prima di attaccare. Se qualcuno si avvicina, uccidetelo.\"",
  obj = "Riferisci le tue scoperte a First Mate Crazz, a Booty Bay.",
  reward = "Certo che mi ricordo di te, $C. Di ritorno dalla ricognizione, vedo...",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Report your findings to First Mate Crazz in Booty Bay.",
}
T[598] = {
  title = "Split Bone Necklace",
  desc = "Ora che hai raccolto i trofei dei Bloodscalp, ho un altro compito per te. La tribù di troll Skullsplitter vive a sud-est, e da anni siamo in guerra con loro. Anche se i Darkspear non vivono più a Stranglethorn, siamo ancora legati al nostro conflitto con gli Skullsplitter.$B$BQuindi, dai loro la caccia. Raccogli le loro Split Bone Necklace e torna da me. Aiutaci nella nostra guerra, e ti guadagnerai l'amicizia dei Darkspear.",
  obj = "Porta 25 Split Bone Necklace a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Gli Skullsplitter malediranno il giorno in cui ci hanno portato alla guerra! Hai completato il tuo compito?",
  reward = "Grande è la tua forza, se hai ottenuto queste collane, $N. Gli Skullsplitter cadono davanti a te come giovani alberelli schiacciati a terra da un basilisco!$B$BLe tue imprese sono una benedizione per noi.",
  en_title = "Split Bone Necklace",
  en_obj = "Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.",
}
T[599] = {
  title = "I Bloodsail Buccaneers",
  desc = "Corpo di mille balene! Quindi i Bloodsail Buccaneers stanno preparando una specie di attacco a Booty Bay? Ma che faccia tosta, quelle canaglie. Booty Bay sarà sempre in mano ai Blackwater Raiders!$B$BÈ una faccenda più grossa di quanto pensassi. Riferisci subito quello che hai scoperto a Fleet Master Seahorn! Il vecchio lupo di mare è da qualche parte in città...",
  obj = "Riferisci a Fleet Master Seahorn dell'attacco che i Bloodsail stanno preparando.",
  reward = "I Bloodsail Buccaneers attaccano Booty Bay? Tanto varrebbe che si buttassero giù dalle Overlook Cliffs. Comunque, portandomi questa informazione hai reso un grande servizio alla mia flotta di bucanieri. I Blackwater Raiders ti ringraziano.",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Report the planned Bloodsail attack to Fleet Master Seahorn.",
}
T[600] = {
  title = "L'estrazione mineraria della Venture Company",
  desc = "La Venture Company ha una serie di attività in tutta Stranglethorn che impediscono ai goblin gran lavoratori, come me, di guadagnare oro onestamente! Ti prego, devi aiutarmi!$B$BLa Venture Company sta scavando vicino alla Crystalvein Mine, a nord. Non riescono a entrare nella miniera per via di tutti quei basilischi, ma riescono comunque a estrarre Singing Crystals dalle colline intorno.$B$BPrendi i loro cristalli e fagli vedere che la giungla non è roba loro.$B$BE... ehm... portami quei cristalli come prova!",
  obj = "Porta 10 Singing Blue Crystal a Crank Fizzlebub, a Booty Bay.",
  progress = "Hai quei cristalli? Mi servono!$B$BCioè... ho bisogno di sapere che la malvagia Venture Company sta perdendo terreno a Stranglethorn. Perché, sai, noi gente onesta dobbiamo pur campare!",
  reward = "Ottimo! Magnifico! Posso ricavarci un bel gruzzolo!$B$BQuella Venture Company ha proprio scelto la giungla sbagliata in cui scavare, eh? Staremmo tutti meglio se se ne andassero da qui.$B$BGrazie, $N. Oggi hai compiuto una buona azione.",
  en_title = "Venture Company Mining",
  en_obj = "Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.",
}
T[601] = {
  title = "I Water Elemental",
  desc = "I Water Elemental sono stati senza dubbio evocati da Gazban, il mago goblin che si dice abbia scoperto la Stone of the Tides. Come forse sai, la Stone of the Tides maledice chi la porta, facendolo svanire e ricomparire...$B$BForse possiamo trovare un modo per contrastare la maledizione. Possiamo far analizzare a un mago di Dalaran il residuo magico di uno dei Water Elemental Bracers. Ho bisogno che torni sull'isola e recuperi qualche esemplare.",
  obj = "Procura 6 Water Elemental Bracers per Baron Revilgaz, a Booty Bay.",
  progress = "Hai avuto fortuna, $N?",
  reward = "Mmh, non ho l'occhio per esaminare questi bracciali e capire se qualcuno servirà, ma sono sicuro che almeno uno potrà aiutarci. Portali a Dalaran e falli esaminare da un mago.$B$BDopotutto, non posso certo lasciare Booty Bay solo per chiacchierare con quei noiosi vecchi maghi.$B$BNon che io sia preoccupato che qualcuno provi a farsi largo a gomitate per diventare il nuovo barone. Nessuno si mette contro Revilgaz e vive per raccontarlo.",
  en_title = "Water Elementals",
  en_obj = "Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.",
}
T[602] = {
  title = "Analisi magica",
  desc = "A quanto ho sentito, i maghi di Dalaran sono impegnati a ricostruire la loro città distrutta; sono sicuro che ne troverai uno disposto a dedicare un po' di tempo a esaminare i bracciali. Se c'è una cosa che so dei maghi, è che non resistono a un enigma magico.$B$BPrendi la Bag of Water Elemental Bracers e vedi se riescono a fare luce sulla maledizione della pietra. Cerca in particolare Archmage Ansirem Runeweaver. Ho già avuto a che fare con lui, e la sua conoscenza è vasta.",
  obj = "Porta la Bag of Water Elemental Bracers ad Archmage Ansirem Runeweaver, a Dalaran.",
  progress = "Se non ti dispiace, in questo momento sono piuttosto occupato.",
  reward = "La Stone of the Tides? Molto interessante. Forse ti sorprenderà sapere che, diversi anni fa, ho scritto un tomo sulle leggende del Gurubashi Empire. Della pietra so parecchio.$B$BAlmeno uno di questi bracciali sembra avere un residuo magico che posso analizzare.$B$BVediamo cosa riesco a vedere...",
  en_title = "Magical Analysis",
  en_obj = "Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran.",
}
T[603] = {
  title = "La chiave di Ansirem",
  desc = "Il mago che possiede la pietra ne amplifica il potere attraverso una specie di punto focale... un altare di qualche tipo. Dovresti riuscire a spezzarlo sovraccaricandolo.$B$BGuarda caso, conosco proprio la cosa che fa al caso nostro: un antico pugnale, un'altra reliquia troll. C'è solo un... piccolo problema.$B$BVedi, ho trovato il pugnale durante le mie ricerche a Stranglethorn, ma l'ho dato a mia figlia Catelyn, una testa calda, che è scappata a Booty Bay per fare la pirata.",
  obj = "Parla con Catelyn, a Booty Bay.",
  reward = "Il mio pugnale? Cosa sei, $Gun comico:una comica;?$B$BCosa? Vuoi solo sentirmi ripetere come sono passata dall'essere la miglior combattente di coltello di Booty Bay allo zimbello di tutta la pirateria?$B$BHo perso un duello al coltello con uno dei Bloodsail Buccaneers (una manica di gran bastardi, quelli!) e lui si è preso la mia lama come bottino.$B$BNon è che una combattente di coltello possa tirare avanti solo con gli insulti e la lingua tagliente...",
  en_title = "Ansirem's Key",
  en_obj = "Talk to Catelyn in Booty Bay.",
}
T[604] = {
  title = "I Bloodsail Buccaneers",
  desc = "Crazz parla molto bene della tua dedizione ai Blackwater Raiders. Ti affiderò una missione della massima importanza per la flotta.$B$BInfiltrati nel cosiddetto posto di comando meridionale che i Bloodsail Buccaneers hanno allestito sulla Wild Shore. Fai irruzione nell'accampamento. Portami le loro carte nautiche insieme ai loro ordini scritti. Vedremo esattamente cosa stanno tramando quei farabutti.",
  obj = "Fleet Master Seahorn, a Booty Bay, vuole che tu uccida 10 Bloodsail Swashbuckler e riporti le Bloodsail Charts e i Bloodsail Orders.",
  progress = "Ahoy, $N. Che notizie porti dall'accampamento dei Bloodsail a sud?",
  reward = "Perfetto, $N. Ora che conosciamo il loro piano, è solo questione di tempo.$B$BE pensare che quegli sciocchi hanno gettato l'ancora proprio al largo del capo...",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.",
}
T[605] = {
  title = "Frammenti blu cantanti",
  desc = "I Singing Crystals esistono solo a Stranglethorn, e per certa gente valgono parecchio. Io quei cristalli riesco a piazzarli, ma quella maledetta Venture Company rende difficile a un onesto imprenditore come me raccoglierne anche solo uno!$B$BVorrei assumerti.$B$BI basilischi di Stranglethorn mangiano il cristallo. È questo che dà loro la pelle indurita, e a volte se ne può ricavare cristallo di discreta qualità.$B$BPuoi prenderlo da qualsiasi basilisco, ma quelli meno cattivi stanno lungo le rive a sud di Zul'Kunda, a nord.",
  obj = "Porta 10 Singing Crystal Shard a Crank Fizzlebub.",
  progress = "Hai già quei frammenti? Ti darò una bella fetta dei profitti!",
  reward = "Aha! Questi andranno benissimo, $N. Sì, proprio benissimo!$B$BEcco la tua parte, e... è stato un piacere fare affari con te.",
  en_title = "Singing Blue Shards",
  en_obj = "Bring 10 Singing Crystal Shards to Crank Fizzlebub.",
}
T[606] = {
  title = "Spaventare Shaky",
  desc = "Se c'è una cosa che non sopporto, è la gente che non paga i debiti di gioco! E sono in tanti a dovermi dei soldi. Pensi di potermi aiutare a riscuotere?$B$BPer cominciare, c'è \"Shaky\" Phillipe, giù ai moli. Mi deve parecchio dopo la partita della settimana scorsa e voglio quello che mi spetta! Ma per averlo dovremo spaventarlo.$B$BEsci dalla città e dai la caccia agli Elder Mistvale Gorilla. Trova una bella scelta di frattaglie, poi portale a Shaky. Non fargli capire che vengono da un animale: lascia che pensi al peggio.",
  obj = "Porta 5 Mistvale Giblets a \"Shaky\" Phillipe, a Booty Bay.",
  progress = "Ehi! Non mi piace come mi guardi, $Gsignore:signora;.",
  reward = "Ack! Dove le hai prese? No, non dirmelo. Non voglio saperlo!$B$BChi ti manda? Sea Wolf?",
  en_title = "Scaring Shaky",
  en_obj = "Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay.",
}
T[607] = {
  title = "Torna da MacKinley",
  desc = "Ecco, prendi questo sacchetto e dallo a Sea Wolf. E digli che avevo intenzione di ripagarlo! Lo giuro!$B$BMi sono solo ubriacato un po' e ho perso la strada, e... sai com'è. Capirà — non c'è bisogno di passare alle maniere forti!",
  obj = "Porta Shaky's Payment a \"Sea Wolf\" MacKinley.",
  progress = "Ecco, ecco, $N. Hai preso Shaky's Payment?",
  reward = "Eh eh, ben fatto! E quando hai mostrato a Shaky quelle frattaglie, quanto ha tremato?$B$BAh! È così facile da leggere che quando gioco a carte con lui non posso fare a meno di vincere!$B$BGrazie per l'aiuto, $N. Ora tocca a te ricevere la paga...",
  en_title = "Return to MacKinley",
  en_obj = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley.",
}
T[608] = {
  title = "I Bloodsail Buccaneers",
  desc = "Maledetta la sfacciataggine di Firallon! Non saprebbe guidare una barchetta attraverso il Crystal Lake, figurarsi un'intera flotta contro di noi.$B$BI Bloodsail Buccaneers pagheranno per la loro imprudenza. Ora che conosciamo il loro piano d'attacco, possiamo contrattaccare prima che capiscano cosa li ha colpiti.$B$BMa perché mandare l'intera flotta a fare il lavoro di un solo gruppo di coraggiosi avventurieri? $N, porta alcuni dei tuoi compagni più abili al punto di sbarco di Firallon e assassina i capi dei Bloodsail. La loro flotta affonderà poco dopo...",
  obj = "Fleet Master Seahorn, a Booty Bay, vuole che tu uccida Captain Stillwater, Captain Keelhaul e Fleet Master Firallon.",
  progress = "Qual è il problema, $N? Dobbiamo attaccare prima che lo facciano i Bloodsail Buccaneers!",
  reward = "Ah, che grande giorno per i Blackwater Raiders! Tre urrà per te, $N!",
  en_title = "The Bloodsail Buccaneers",
  en_obj = "Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.",
}
T[609] = {
  title = "Debiti voodoo",
  desc = "La mia lista si sta accorciando, ma c'è ancora gente che mi deve dei soldi.$B$BPoi ci sono Maury \"Club Foot\" Wilkins, Jon-Jon the Crow e Chucky \"Ten Thumbs\".$B$BI debiti di questi cani rognosi sono scaduti da mesi, e pensavo che avessero lasciato la città per non pagare! Poi ho sentito che sono maledetti e stregati e che ora vagano tra le rovine nella giungla. Ma non m'importa che fine abbiano fatto — voglio quello che è mio!$B$BSono nelle Ruins of Aboraz e nelle Ruins of Jubuwal, a nord-est di qui. Trovali e riscuoti.",
  obj = "Porta Maury's Clubbed Foot, Jon-Jon's Golden Spyglass e Chucky's Huge Ring a \"Sea Wolf\" MacKinley, a Booty Bay.",
  progress = "$N, hai trovato quei tre cani? Hai riscosso i loro oggetti di valore?",
  reward = "Ottimo! Posso ricavarci un buon prezzo, soprattutto da quello che c'è dentro il piede di Maury! Grazie mille, $N!$B$BSpero che quei tre abbiano imparato la lezione: non scommettere mai qualcosa che non puoi permetterti di perdere.$B$BE forse per loro è troppo tardi, ma... dovrebbero scegliere con più attenzione con chi giocare d'azzardo.",
  en_title = "Voodoo Dues",
  en_obj = "Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay.",
}
T[610] = {
  title = "\"Pretty Boy\" Duncan",
  desc = "Ti ha mandato mio PADRE? Pensavo che quel vecchio brontolone avesse già rinunciato a me.$B$BNon è davvero colpa sua se sono scappata, solo che non avrebbe dovuto aspettarsi che accettassi di vivere una vita noiosa, a leggere libri ammuffiti e a frequentare maghi grigi, rigidi e barbosi!$B$BSe ti serve il mio pugnale, dovrai riprenderlo a \"Pretty Boy\" Duncan, uno dei Bloodsail Buccaneers. Piantagli qualcosa tra le spalle e sono sicura che te lo darà.",
  obj = "Prendi Catelyn's Blade a \"Pretty Boy\" Duncan.",
  progress = "Non ero mai stata battuta prima, sai, $N? Certo, qualche taglio l'avevo preso, in un duello al coltello non si può evitare, ma lui mi ha colpita di lato alla testa e mi ha fatto perdere i sensi. Quando mi sono ripresa, la mia lama era sparita.$B$BPer quanto il mio soprannome possa far pensare il contrario, mi serve comunque un coltello per combattere, e per me deve essere quello.",
  reward = "Hai battuto Duncan? Allora non sei $Gcosì inesperto:così inesperta; come sembravi a prima vista.$B$BImmagino che questo voglia dire anche che non dovrei sfidarti a duello tanto presto!",
  en_title = "\"Pretty Boy\" Duncan",
  en_obj = "Get Catelyn's dagger from \"Pretty Boy\" Duncan.",
}
T[611] = {
  title = "La maledizione delle maree",
  desc = "Quindi cerchi una specie di altare? Be', io non sono un'esperta di rovine troll come mio padre, ma ho sentito parlare di una città troll sommersa vicino a quell'isola che stai cercando. Forse dovresti provare lì.$B$BMi hai riportato il coltello, quindi immagino che tu possa prenderlo in prestito... ma quando hai finito lo rivoglio!",
  obj = "Distruggi l'Altar of the Tides con Catelyn's Blade, uccidi Gazban e riporta la Stone of the Tides e Catelyn's Blade a Baron Revilgaz.",
  progress = "Hai recuperato la Stone of the Tides per me, $N? Ho già fatto spazio e comprato un bel piedistallo per metterla in mostra.",
  reward = "Straordinario! La Stone of the Tides! Avrà un posto d'onore nella mia collezione di manufatti troll antichi. Hai visto come sembra quasi che una marea sia intrappolata nella sua superficie? Magnifico!",
  en_title = "The Curse of the Tides",
  en_obj = "Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.",
}
T[613] = {
  title = "Aprire il piede di Maury",
  desc = "Maledizione! Quel mozzo di Maury ha messo un lucchetto al suo piede, e non riesco ad aprirlo! Il suo bottino è dentro il piede, ed è quello che mi deve!$B$BDobbiamo trovare la chiave per aprire il lucchetto. Si sapeva che Maury giocava d'azzardo con gli ogre Mosh'Ogg, nel loro tumulo a nord-est. E mi ha raccontato, quando era ancora vivo, che l'ultima volta che era andato al tumulo l'avevano cacciato via perché aveva vinto troppo. Forse gli ogre di laggiù hanno la sua chiave.$B$BMa se ce l'hanno, potresti dover ucciderne un bel po' per trovare quello giusto...",
  obj = "Porta Maury's Key a \"Sea Wolf\" Mackinley, a Booty Bay.",
  progress = "Ohilà, $N! Hai già trovato Maury's Key?",
  reward = "L'hai trovata! Grazie mille, $N. Mi sei $Gstato:stata; di grande aiuto!$B$BEcco qua — te lo sei $Gguadagnato:guadagnata;!",
  en_title = "Cracking Maury's Foot",
  en_obj = "Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.",
}
T[614] = {
  title = "Il forziere del capitano",
  desc = "Un tempo navigavo da qui fino a Ratchet, in Kalimdor. Ero un capitano di successo, con una reputazione impeccabile.$B$BFinché...$B$BQuei maledetti giganti marini mi hanno rovinato! Mi hanno distrutto la nave, ucciso l'equipaggio e mi hanno messo su una scialuppa diretta a Booty Bay. E uno dei giganti, Gorlash, mi ha rubato il mio forziere del capitano. Ha detto che lo voleva come tabacchiera. Che faccia tosta!$B$BHo sentito che Gorlash si aggira lungo la costa a est di qui. Trovalo e riportami il mio forziere! Fallo, e ti sarai $Gguadagnato:guadagnata; la gratitudine di un capitano.",
  obj = "Porta Smotts' Chest a Hecklebury Smotts, a Booty Bay.",
  progress = "Ahoy, $N! Hai trovato Gorlash? Quel forziere era il mio preferito, e ha uno scomparto segreto dove tenevo i miei tesori più preziosi!",
  reward = "L'hai trovato! Oh, che giorno felice, questo! Grazie, $N. Riavere il mio forziere spegne un po' del fuoco che ho dentro.$B$BMa la mia vendetta non è completa...",
  en_title = "The Captain's Chest",
  en_obj = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",
}
T[615] = {
  title = "La sciabola del capitano",
  desc = "Dopo aver perso la mia prima nave per colpa di quei giganti, ne ho comprata un'altra. L'ho chiamata Smotts' Revenge, l'ho riempita di provviste e di marinai e sono partito alla ricerca di quei farabutti. Li ho trovati, ma... mi hanno battuto. Hanno distrutto la Smotts' Revenge, ucciso il mio secondo equipaggio e mi hanno messo su un'altra scialuppa.$B$BStavolta un altro dei giganti, Negolash, mi ha rubato la sciabola.$B$BAffronta Negolash e riportami la mia sciabola!$B$BParla con Sprogger. Era il mio cuoco sulla Smotts' Revenge, ed è sopravvissuto all'ultimo attacco. Può aiutarti a trovare il gigante.",
  obj = "Parla con Sprogger.",
  reward = "Salve, salve, $N. Il capitano mi ha detto che vuoi dare la caccia a Negolash, eh?",
  en_title = "The Captain's Cutlass",
  en_obj = "Speak with Sprogger.",
}
T[616] = {
  title = "L'isola infestata",
  desc = "Baron Revilgaz mi ha chiesto di tenere le orecchie aperte per le voci su cose strane e fuori posto a Booty Bay e a Stranglethorn. Di solito non do molto peso alle storie di fantasmi, ma alla taverna ho sentito dei marinai parlare di un'isola infestata al largo della costa. Dei Water Elemental e un fantasma goblin che delira, dicono.$B$BSe vai a parlare con Revilgaz, potresti riferirgli questa storia?",
  obj = "Parla con Baron Revilgaz, a Booty Bay.",
  reward = "Interessante. Tempo fa, mi pare di ricordare di aver letto un libro che suggeriva...$B$BAh, certo, era una leggenda troll. Se quello che riferisce Krazek è vero, forse presto potrò aggiungere la Stone of the Tides alla mia collezione di manufatti e reliquie antiche.",
  en_title = "The Haunted Isle",
  en_obj = "Speak with Baron Revilgaz in Booty Bay.",
}
T[617] = {
  title = "Akiris a mazzi",
  desc = "Cerchi lavoro, $N? Potrei averne un po', se te la senti di affrontare una piccola sfida.$B$BHo un amico, Groy, che fa soldi a palate vendendo quella che i naga chiamano Akiris Reed: è una specie di pregiata canna marina. Non so bene a cosa serva, ma paga bene per i mazzi di quella roba.$B$BPortami dieci steli di quella roba, e faremo affari. I naga sono stati visti l'ultima volta lungo la spiaggia a nord di qui.",
  obj = "Porta 10 Akiris Reed a Privateer Bloads, a Booty Bay.",
  progress = "Se non hai affari da fare con me, allora circola, $N.",
  reward = "Ben fatto, $N. Dieci steli di Akiris Reed non erano poi una sfida così grande, eh? Senza offesa per i naga, ma ehi, tutti devono pur campare.",
  en_title = "Akiris by the Bundle",
  en_obj = "Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.",
}
T[618] = {
  title = "Affrontare Negolash",
  desc = "Negolash è un gigante affamato.$B$BQuando i giganti hanno distrutto la nostra nave, Negolash è andato dritto nella mia cucina. Non aveva fame di marinai come gli altri giganti. Negolash voleva il vino... e le mie Barbecued Buzzard Wing. Sono la mia specialità, e sono dovuto andare fino alle Badlands per la ricetta!$B$BSe vuoi attirare il gigante, procurati del vino e un mucchio di Buzzard Wing. Mettili nella nostra vecchia scialuppa, a sud-est di qui lungo la costa. Quando Negolash sentirà l'odore di tutto quel cibo, verrà di sicuro!",
  obj = "Porta 10 Barbecued Buzzard Wing e 5 bottiglie di Junglevine Wine a Captain Smotts' Lifeboat.$B$BUccidi Negolash e porta Smotts' Cutlass a Captain Smotts, a Stranglethorn.",
  progress = "Hai recuperato la mia sciabola, $N?",
  reward = "Hai tolto la mia sciabola a Negolash! Non posso credere alla mia fortuna, $N! Incontrarti ha girato la mia sorte in meglio, puoi starne certo!$B$BGrazie! E se mai avrò una nuova nave e vorrai solcare i mari, sarai mio ospite d'onore.",
  en_title = "Facing Negolash",
  en_obj = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.$B$BKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.",
}
T[619] = {
  title = "Attirare Negolash",
  progress = "È una scialuppa di salvataggio abbandonata. Sulla fiancata, in vernice graffiata e sbiadita, sono dipinte le parole:$B$B\"Smotts' Revenge\"",
  reward = "Ammucchi cibo e bevande sulla zattera...",
  en_title = "Enticing Negolash",
}
T[620] = {
  title = "La Monogrammed Sash",
  desc = "Questa elegante fascia ha le lettere \"HS\" ricamate lungo l'orlo.",
  obj = "Riporta la Monogrammed Sash al suo proprietario.",
  progress = "Salve. Hai affari da trattare con me?",
  reward = "Hai recuperato la mia fascia? Allora... devi aver ucciso Mok'rash, il gigante marino! Evviva!$B$BSono contento che quel lurido farabutto sia morto: Mok'rash era uno dei tre giganti marini che mi hanno distrutto le navi e ucciso l'equipaggio.$B$BTre volte.$B$BSei $Gun:una; $C di valore, $N.",
}
T[621] = {
  title = "Il segreto di Zanzil",
  desc = "Zanzil the Outcast vive con i suoi seguaci nelle Jubuwai e Aboraz Ruins, a nord-est di Booty Bay. È stato esiliato dalla sua tribù. Perché? Be'...$B$BZanzil conosce dei metodi per piegare la mente degli altri, e i suoi capi lo temono. Sui suoi seguaci usa una miscela di piante della giungla che ne sopprime la volontà e ne rafforza il corpo.$B$BLa sua miscela varrebbe molto per chi vuole controllare gli altri.$B$BPortami dei campioni della sua miscela, e troverò il modo di usarli.",
  obj = "Porta 12 campioni di Zanzil's Mixture a Crank Fizzlebub, a Booty Bay.",
  progress = "Hai i campioni di Zanzil's Mixture??",
  reward = "Ah, molto bene! Ecco la tua paga.$B$BEd ecco un piccolo extra... per la tua discrezione.",
  en_title = "Zanzil's Secret",
  en_obj = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.",
}
T[622] = {
  title = "Torna da Corporal Kaleb",
  desc = "Mentre eri via ho aggiustato la pentola che mi hai portato. Ci ho perfino aggiunto un fischietto a vapore in più, e guarda! C'è un nuovo trinciatore sul fondo che taglia anche le ossa delle gambe!$B$BSì, sì, la Krazek's Crock Pot soddisfa il cuoco al cento per cento! Sono sicuro che il suo proprietario sarà contento.",
  obj = "Porta Krazek's Fixed Pot a Corporal Kaleb, al Rebel Camp.",
  progress = "Salve, $N. Sei $Garrivato:arrivata; fino a Booty Bay? Il goblin Krazek ha aggiustato la mia pentola??",
  reward = "È aggiustata! Fantastico, ora posso mettermi a preparare la cena! Grazie mille, $N.$B$BSpero che a Booty Bay sia andato tutto bene. Quel posto può diventare parecchio pericoloso, e... ho sentito dire che a volte i goblin trascinano i marinai ubriachi sulle loro navi di schiavi e li portano chissà dove... a fare chissà cosa...",
  en_title = "Return to Corporal Kaleb",
  en_obj = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.",
}
T[623] = {
  title = "Akiris a mazzi",
  desc = "$N, visto che sei qui: mentre eri via mi è arrivato un messaggio da Groy. Dice di essere soddisfatto dell'ultimo carico che gli è arrivato, e ha un cliente che ne vuole subito dell'altro.$B$BIo non andrò a Theramore prima di una settimana, ma se te la senti di fare il viaggio, non c'è motivo per cui tu non possa portargli la roba al posto mio.$B$BHai voglia di avventura? Lo sai dov'è il Dustwallow Marsh, vero? Però fa' attenzione: Theramore può essere pericolosa se sei della gente sbagliata.",
  obj = "Porta un Bundle of Akiris Reeds a Privateer Groy, a Theramore.",
  progress = "Sì?",
  reward = "Cosa?! Ho cose molto migliori da fare che parlare con gente come te, $C. Fa' che ne valga la pena o levati di torno.$B$BEh? Ti manda Bloads, eh? Be', che mi hai portato?$B$B<Privateer Groy esamina con cura il mazzo.>$B$BNiente male, niente male davvero. Un altro mazzo renderà il mio cliente molto contento.$B$BImmagino che la tua prossima domanda riguarderà i soldi, eh, $C? Certo che sì!$B$BEcco, prendi queste monete e un consiglio: sparisci dai miei moli.",
  en_title = "Akiris by the Bundle",
  en_obj = "Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.",
}
T[624] = {
  title = "L'indovinello di Cortello",
  desc = "Un ponte adorno, da molti passanti calcato$BA est di Deadwind e a sud di Redridge situato$BLà sotto qualcosa ti aspetta, lo sai$BChi lo chiama traccia, chi indizio: vedrai$BLì resterà per infiniti domani$BAttendendo nella Swamp of Sorrows, tra i pantani.",
  obj = "Risolvi l'indovinello!",
  reward = "La pergamena fradicia contiene il prossimo indizio...",
  en_title = "Cortello's Riddle",
  en_obj = "Solve the riddle!",
}
T[625] = {
  title = "L'indovinello di Cortello",
  desc = "In Kalimdor ti attendono luoghi lontani$BDove il pericolo ha reso speranze e destini vani$BA est delle Barrens il clima è impietoso$BNel Dustwallow Marsh tutto è cupo e insidioso$BMa per chi supera la prova un indizio c'è$BIn una grotta a sud-ovest, che aspetta te.",
  obj = "Risolvi l'indovinello!",
  reward = "Trovi una pergamena ammuffita.",
  en_title = "Cortello's Riddle",
  en_obj = "Solve the riddle!",
}
T[626] = {
  title = "L'indovinello di Cortello",
  desc = "A Lordaeron! Grande terra di tormento$BDove prodi soldati si battono con la morte a ogni momento$BAttraversa i grandi disordini con coraggio$BLà troverai la fine di questo viaggio$BLungo la costa delle Hinterlands, ai piedi delle grandi cascate$BSott'acqua il tuo tesoro ti chiama dalle onde agitate!",
  obj = "Risolvi l'indovinello!",
  reward = "Apri il forziere e scopri...",
  en_title = "Cortello's Riddle",
  en_obj = "Solve the riddle!",
}
T[627] = {
  title = "Un favore per Krazek",
  desc = "C'è una grotta di montagna nella Drywhisker Gorge, lontano a nord, negli Arathi Highlands. In quella grotta c'è un minerale raro: la sanguinaria. La sanguinaria di questa grotta non è della qualità migliore, ma anche quella di bassa qualità ha valore... per chi sa come usarla.$B$BNe vorrei un po'.$B$BIo aggiusto la tua pentola, ma mentre ci lavoro... portami dei campioni di sanguinaria. Portamene abbastanza e ti darò anche un extra.$B$BAh, e se non hai la capacità di estrarla... trova qualcuno che ce l'ha!",
  obj = "Porta 4 carichi di Lesser Bloodstone Ore a Krazek, a Booty Bay.",
  progress = "Salve, $N. Hai avuto fortuna con la sanguinaria?",
  reward = "Ah, splendido! Mi hai fatto proprio un bel favore.$B$BEcco il tuo compenso...",
  en_title = "Favor for Krazek",
  en_obj = "Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.",
}
T[628] = {
  title = "Excelsior",
  desc = "Finito l'interno, non resta che aggiungere lo strato esterno. Per questo uso solo le migliori pelli di coccodrillo anziano. Sono più resistenti e sono una tela migliore, per così dire, per aggiungere i disegni e le rifiniture che fanno la linea Excelsior di Drizzlik.$B$BPerò è difficile trovare la pelle perfetta: l'unica adatta al mio progetto è quella di un Elder Saltwater Crocolisk. Gli esemplari anziani escono solo per difendere gli altri crocolisk d'acqua salata, quindi potresti doverne uccidere qualcuno per farne uscire uno.",
  obj = "Porta un Elder Crocolisk Skin a Drizzlik, a Booty Bay.",
  progress = "Ho letto da qualche parte che i crocolisk d'acqua salata si stanno lentamente estinguendo... brutte notizie per i miei affari, no?$B$BComunque, spero che tu abbia quella pelle di Elder Saltwater Crocolisk per me!",
  reward = "Grande! Grazie al tuo aiuto evaderò questo ordine e lo spedirò a Director Riddlevox con la prossima nave per Undermine. Addirittura in anticipo!$B$BPer tutto il tuo lavoro, ecco: ne ho fatti qualche paio in più, quindi prendine uno. Offre Drizzlik.$B$BE ricorda: non c'è stivale più raffinato di uno della linea Excelsior di Drizzlik!",
  en_title = "Excelsior",
  en_obj = "Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.",
}
T[629] = {
  title = "La Vile Reef",
  desc = "Tanto tempo fa, un grande tremito della terra fece sprofondare un'antica città troll sotto le acque della Savage Coast, a nord-ovest. Chiamiamo quel luogo la Vile Reef, perché ora nelle rovine della città vivono i murloc, che attaccano chiunque si avvicini.$B$BTra quelle rovine c'è una vecchia tavoletta che narra l'antica storia di Gri'lek, un eroe delle leggende troll. La storia è sacra per la tribù Darkspear, e anche se la tavoletta è troppo grande per essere spostata, ne voglio un frammento da custodire come reliquia nella nostra nuova casa a Orgrimmar.",
  obj = "Porta un Tablet Shard a Kin'weelay, al Grom'gol Base Camp.",
  progress = "Attendo il Tablet Shard, $N.",
  reward = "Bene. Quando tornerò a Orgrimmar metterò questo frammento in un luogo sacro. Ci ricorderà la potenza e l'onore di Gri'lek.$B$BGrazie, $N. Le tue imprese segnano un'amicizia crescente con la tribù Darkspear.",
  en_title = "The Vile Reef",
  en_obj = "Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.",
}
T[630] = {
  title = "Messaggio in bottiglia",
  desc = "$N, ripongo la mia fiducia in te e in chiunque tu riesca a radunare per liberarmi. Il grande Skymane King Mukla è il mio carceriere. Comanda le bestie di quest'isola, e mi tengono qui contro la mia volontà con questa catena. Se riesci a ucciderlo e a trovare la chiave di questo ceppo, ti sarò molto debitrice.$B$BLo sento spesso dalla parte sud-orientale dell'isola, ma ti prego, fa' attenzione: non è uno da prendere alla leggera.",
  obj = "Uccidi King Mukla e torna da Princess Poobah con la Shackle Key per liberarla.",
  progress = "Ringrazio i miei antenati che qualcuno sia venuto ad aiutarmi. Hai la chiave che mi libererà?",
  reward = "$N, mi hai salvata da un grande disonore. Se fosse in mio potere, ti offrirei un posto nella mia tribù. Ma per ora posso offrirti solo questo pegno, per il coraggio e la nobiltà che hai dimostrato.",
  en_title = "Message in a Bottle",
  en_obj = "Slay King Mukla and return to Princess Poobah with the Key to free her.",
}
T[631] = {
  title = "Il Thandol Span",
  desc = "Un'esplosione tremenda ha rombato tra le colline. È stato orribile, credimi!$B$BBravi soldati sono morti difendendo il Thandol Span. Longbraid dice che ci vendicheremo sui Dark Iron prima che sia tutto finito.$B$BSiamo messi malissimo, però, e non vedo rinforzi all'orizzonte. Longbraid ha mandato Ol' Rustlocke a esplorare il ponte orientale, per vedere se potevamo metterlo in sicurezza.$B$BÈ successo giorni fa. Non abbiamo uomini a sufficienza per cercarlo, con Dun Modr sotto assedio.$B$BForse tu puoi trovarlo...",
  obj = "Rhag Garmason vuole che tu trovi Ol' Rustlocke.",
  reward = "Frughi il piccolo cadavere del nano. Inciso nell'elmo si legge chiaramente: Ebenezer Rustlocke.",
  en_title = "The Thandol Span",
  en_obj = "Rhag Garmason wants you to locate Ol' Rustlocke.",
}
T[632] = {
  title = "Il Thandol Span",
  desc = "Sembra che il povero Ol' Rustlocke sia finito in un'imboscata dei Dark Iron. Noti una pergamena accanto al suo pugno serrato.$B$BRiferisci la triste notizia a Rhag Garmason e mostragli quello che hai trovato.",
  obj = "Torna da Rhag Garmason e mostragli la pergamena che hai trovato sul cadavere di Rustlocke.",
  progress = "Qualche traccia di Ol' Rustlocke, $N?",
  reward = "Oh cielo, la notizia è grave...",
  en_title = "The Thandol Span",
  en_obj = "Report back to Rhag Garmason and show him the parchment you found on Rustlocke's corpse.",
}
T[633] = {
  title = "Il Thandol Span",
  desc = "Santo cielo, no! Povero Rustlocke. È davvero una gran tragedia.$B$BNon dobbiamo lasciare che la sua morte sia vana. Questa pergamena che hai scoperto indica che Kam Deepfury, la mente dietro l'attacco originale, ha fatto nascondere una scorta di esplosivi appena oltre il Thandol Span, negli Arathi Highlands.$B$BSe quegli esplosivi arrivano al ponte, la nostra principale linea di rifornimento verso nord sarà recisa! La scorta va distrutta, $N! Torna da me quando la missione sarà compiuta.$B$BSei la nostra unica speranza.",
  obj = "Distruggi la scorta di esplosivi.",
  progress = "La scorta di esplosivi va distrutta!",
  reward = "Il ponte rimasto è salvo! Hai reso un grande servizio a King Magni e alla gente del Khaz Modan.$B$BOra, se solo riuscissimo a resistere abbastanza perché arrivino i rinforzi...",
  en_title = "The Thandol Span",
  en_obj = "Destroy the cache of explosives.",
}
T[634] = {
  title = "Appello all'Alleanza",
  desc = "Ti chiedo ancora un piccolo favore, $C. Attendiamo le riserve di Ironforge. Roggo però sa di un campo dell'Alleanza a nord, negli Arathi Highlands, a Refuge Pointe.$B$BVa' laggiù e cerca Captain Nials. Chiedi alla brava Captain se l'Alleanza può concederci qualche soldato per aiutarci a riprendere Dun Modr e il Thandol Span.",
  obj = "Cerca Captain Nials a Refuge Pointe.",
  reward = "Le mie condoglianze vanno a Longbraid e ai suoi coraggiosi soldati. La notizia della tragedia del Thandol Span e della caduta di Dun Modr mi pesa sul cuore.$B$BMa Stromgarde è caduta! Da qui la nostra presenza a Refuge Pointe. Ci troviamo a dover riprendere la nostra stessa grande città.$B$BL'onore e il dovere impongono che non lasciamo gli Highlands finché Stromgarde non tornerà a innalzare il possente stendardo del Re. Manderò a dire a Longbraid che dovrà cavarsela da solo...",
  en_title = "Plea To The Alliance",
  en_obj = "Seek out Captain Nials at Refuge Pointe.",
}
T[635] = {
  title = "Il cristallo nelle montagne",
  desc = "Questo frammento pulsa mentre lo tieni in mano...$B$BSenti un senso di supplica provenire dal frammento, come se qualcuno cercasse di comunicare, qualcuno che ha disperatamente bisogno del tuo aiuto.$B$BNella tua mente appare una visione: le montagne settentrionali di Arathi, e un cristallo splendente che spunta dalla terra.$B$BTi senti $Gattratto:attratta; da quel luogo.",
  obj = "Trova il cristallo della tua visione.",
  reward = "Questo cristallo pulsa, come se dentro vi fosse intrappolata una forza viva.",
  en_title = "Crystal in the Mountains",
  en_obj = "Find the crystal from your vision.",
}
T[637] = {
  title = "Sully Balloo's Letter",
  desc = "La busta inzuppata e malridotta si sfalda tra le tue mani e ti lascia in pugno qualche pagina di lettera, scritta con cura minuziosa.$B$BLa lettera è indirizzata a una certa Mrs. Sara Balloo di Ironforge e comincia così: \"Mia cara Sara....\"",
  obj = "Consegna Sully Balloo's Letter a Sara Balloo.",
  progress = "Sembri aver viaggiato a lungo e aver visto molti tumulti ai tuoi tempi, $C. I tempi in cui viviamo mettono a dura prova l'anima. Che notizie mi porti adesso?",
  reward = "Dici di aver visto il mio Sully intrappolato sotto le acque gelide? Dimmi che non è vero!$B$BLascia che legga quel che ha scritto....",
  en_title = "Sully Balloo's Letter",
  en_obj = "Deliver Sully Balloo's Letter to Sara Balloo.",
}
T[638] = {
  title = "Trollbane",
  desc = "Con Thoras Trollbane morto e Stromgarde in rovina, Vol'jin ci ha ordinato di fare di tutto per sottrarre agli umani la leggendaria spada Trol'kalar, così da poterla usare nelle prossime battaglie contro i troll di Zul'Gurub.$B$BZengu, uno dei nostri cacciatori più esperti, è stato mandato a Hammerfall, nel nord-est degli Arathi Highlands, per occuparsi di procurarla.",
  obj = "Va' a Hammerfall, negli Arathi Highlands, e parla con Zengu.",
  reward = "Come va, $C? Il compito che Vol'jin ci ha affidato sarà difficile, e qualunque aiuto tu possa darci sarà gradito e necessario.",
  en_title = "Trollbane",
  en_obj = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.",
}
T[639] = {
  title = "Sigil of Strom",
  desc = "In tempi antichi, i troll combatterono contro l'Arathorian Empire e contro il nostro avversario più capace, Lord Ignaeus of Strom, detto Trollbane. Cavalcava in battaglia brandendo Trol'kalar — ammazzatroll, nella loro antica lingua.$B$BMa ora i figli di Trollbane sono indeboliti, e la loro roccaforte è andata in rovina.$B$BLa spada è protetta da diversi sigilli, divisi tra i sopravvissuti di Stromgarde, e dobbiamo recuperarli.$B$BIl primo l'ha preso il Syndicate; dovrebbe averlo uno dei loro uomini a Stromgarde.",
  obj = "Procura il Sigil of Strom per Zengu, a Hammerfall.",
  progress = "Hai già trovato il primo sigillo? Molto probabilmente ce l'ha addosso uno degli agenti del Syndicate a Stromgarde.",
  reward = "Eccellente, $Gamico:amica;. È un buon inizio per raccogliere i sigilli che ci serviranno per togliere Trol'kalar dalla tomba di Trollbane.",
  en_title = "Sigil of Strom",
  en_obj = "Get the Sigil of Strom for Zengu in Hammerfall.",
}
T[640] = {
  title = "Il sigillo spezzato",
  desc = "La tomba di Thoras Trollbane è protetta da tre sigilli; il primo l'hai recuperato dal Syndicate. Gli altri due saranno più difficili da prendere, perché sono in mano alla milizia di Stromgarde, ben trincerata.$B$BIl Sigil of Thoradin è stato diviso in undici pezzi dal figlio di Thoras, Galen, e distribuito tra i difensori di Stromgarde. Recupera i pezzi e portali a Tor'gan, lo sciamano troll: sarà in grado di ricomporli nel sigillo completo.",
  obj = "Recupera gli 11 Sigil Fragment dai difensori di Stromgarde e portali a Tor'gan, a Hammerfall.",
  progress = "Throm'ka, $C. Zengu mi ha detto che avevi bisogno del mio aiuto?",
  reward = "Ah, hai bisogno che ricomponga questo sigillo? Non dovrebbe essere troppo difficile... tutti i pezzi sembrano esserci, e la struttura magica sarà facile da ricostruire.$B$BForse ti conviene chiudere gli occhi.",
  en_title = "The Broken Sigil",
  en_obj = "Retrieve the 5 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.",
}
T[641] = {
  title = "Sigil of Thoradin",
  desc = "La ricostruzione è riuscita alla perfezione. Ora il sigillo può servire a spezzare il suggello sulla tomba di Trollbane. Riportalo a Zengu; di sicuro ha altri compiti per te.",
  obj = "Porta il Sigil of Thoradin restaurato a Zengu, a Hammerfall.",
  progress = "$N! Hai il secondo sigillo?",
  reward = "Siamo a metà strada per poter togliere Trol'kalar dalla tomba di Trollbane. Non sappiamo con precisione dove sia il terzo sigillo, perché chi lo custodisce sembra spostarsi parecchio per l'Arathi, ma ho fiducia che riuscirai a trovarlo.",
  en_title = "Sigil of Thoradin",
  en_obj = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.",
}
T[642] = {
  title = "La principessa intrappolata",
  desc = "Il mio nome è Myzrael. Sono una principessa della terra, e i miei carcerieri, i giganti, mi hanno intrappolata nelle profondità delle Arathi Highlands. Questi frammenti di cristallo sono l'unico modo in cui posso parlare con il mondo di superficie.$B$BTi prego, aiutami. Alleati dei giganti, i Drywhisker Kobold hanno un frammento come questo nella loro Drywhisker Gorge, a est. Per alimentare il gruppo di frammenti, devi raccogliere i Mote of Myzrael dai kobold e applicarli ad esso.$B$BTi supplico, $N, aiutami!",
  obj = "Raccogli 12 Mote of Myzrael, poi portali agli Iridescent Shards nella Drywhisker Gorge.",
  progress = "Questo gruppo di frammenti somiglia molto agli Shards of Myzrael. Ma non ne emana la stessa sensazione di sicurezza.",
  reward = "Ah! Hai attivato questi frammenti. Mi sento già più me stessa!$B$BMa ahimè, sono ancora lontana dall'essere libera...",
  en_title = "The Princess Trapped",
  en_obj = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.",
}
T[643] = {
  title = "Sigil of Arathor",
  desc = "Anche se a malapena si può dire che controllino Stromgarde, figurarsi tutti gli Arathi Highlands, il principe umano fa trottare i resti della sua cavalleria per le campagne. Non capisco perché lo faccia, ma chi capisce come ragionano gli umani, eh?$B$BQualunque sia il suo motivo, la cosa più importante è che ha dato uno dei sigilli a Lieutenant Valorcall, il capo della loro cavalleria. Trovalo e riportami il suo sigillo.",
  obj = "Recupera il Sigil of Arathor e riportalo a Zengu, a Hammerfall.",
  progress = "Non sarà facile rintracciare Valorcall, $N. A cavallo copre grandi distanze in fretta. Ciononostante, il suo sigillo ci serve.",
  reward = "Perdere il capo della cavalleria sarà un duro colpo per i difensori di Stromgarde. Meglio ancora, significa che ci manca un solo sigillo per poter avere Trol'kalar tutta per noi.",
  en_title = "Sigil of Arathor",
  en_obj = "Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.",
}
T[644] = {
  title = "Sigil of Trollbane",
  desc = "L'ultimo dei sigilli necessari per aprire la tomba di Thoras Trollbane lo custodisce di persona suo figlio. Vive nel cuore di Stromgarde, in una cappella dei quartieri in mano alla milizia. Prince Galen è ben protetto, ed è lui stesso un guerriero tutt'altro che scarso, quindi questo compito potrebbe rivelarsi molto difficile.",
  obj = "Uccidi Prince Galen Trollbane e porta il Sigil of Trollbane a Zengu, a Hammerfall.",
  progress = "Sei $Gtornato:tornata;, $N. La stirpe di Ignaeus Trollbane è spezzata?",
  reward = "Che giornata, $C. Il sangue di Trollbane non perseguiterà più la mia gente, e i sigilli necessari per prendere Trol'kalar sono in nostro possesso. Presto, molto presto, colpiremo gli odiati troll di Zul'Gurub.",
  en_title = "Sigil of Trollbane",
  en_obj = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.",
}
T[645] = {
  title = "Trol'kalar",
  desc = "Cos'è questo? Riuniti, i quattro sigilli si sono fusi in un unico sigillo. Non c'è dubbio che potrà spezzare le protezioni poste sulla tomba di Trollbane.$B$BI resti di Trollbane sono sepolti nel Sanctum, dietro la cappella di Stromgarde. Recupera Trol'kalar.",
  obj = "Recupera Trol'kalar dalla tomba di Trollbane, a Stromgarde.",
  progress = "Le incisioni nella pietra sulla facciata della tomba di Trollbane corrispondono alle linee luminose del Sigil of Ignaeus...",
  reward = "Mentre fai combaciare le linee sulla facciata della tomba di Trollbane con quelle luminose del Sigil of Ignaeus, un lampo di luce lo consuma, e la leggendaria spada Trol'kalar si libera dalla stretta delle mani di pietra.",
  en_title = "Trol'kalar",
  en_obj = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde.",
}
T[646] = {
  title = "Trol'kalar",
  desc = "La luce svanisce lentamente: la spada Trol'kalar, custodita in un fodero di pietra, è stata liberata.",
  obj = "Consegna Sheathed Trol'kalar a Zengu, a Hammerfall.",
  progress = "$N! Hai preso la spada?",
  reward = "Per generazioni le forze di Strom e di Arathor hanno devastato i troll. Ora la loro arma più potente è nelle nostre mani. La nostra lenta avanzata nelle foreste afose di Zul'Gurub finirà.$B$BIl tuo aiuto è stato prezioso, $N, e i troll Darkspear ti sono debitori.$B$BMi assicurerò che la spada venga consegnata a Nimboya, a Grom'gol.",
  en_title = "Trol'kalar",
  en_obj = "Deliver Trol'kalar to Zengu in Hammerfall.",
}
T[647] = {
  title = "MacKreel's Moonshine",
  desc = "Ieri sera ho alzato un po' troppo il gomito con la vecchia Moonshine! Longbraid mi staccherebbe la testa se sapesse che sono svenuto durante il turno di guardia.$B$BLa zucca mi fa un male cane. Mi è sembrato che una brigata intera di macchine d'assedio passasse di sopra, con tutto quel rimbombo.$B$BOh, guarda che ora! Avevo promesso a Brewmeister Bilger, a Southshore, che gli avrei ripagato il debito mandandogli un po' di Moonshine.$B$BMa mancano solo 15 minuti alla scadenza! Portagliene questa partita, per favore. E sbrigati!",
  obj = "Porta MacKreel's Moonshine a Brewmeister Bilger, a Southshore.",
  progress = "Che buone nuove porti, $R?",
  reward = "Ah, niente come Foggy MacKreel's Moonshine per scaldarti in una giornata fredda! E io che pensavo che quel furfantello sarebbe stato di nuovo in ritardo con i conti. Grazie, $Gamico:amica;! Grazie mille davvero!",
  en_title = "MacKreel's Moonshine",
  en_obj = "Take MacKreel's Moonshine to Brewmeister Bilger in Southshore.",
}
T[651] = {
  title = "Stones of Binding",
  desc = "Quattro Stones of Binding sono sparse per Arathi. Queste pietre mi tengono inchiodata sotto terra.$B$BPer sbloccarle devi sbloccare la più forte: la Stone of Inner Binding. E per farlo devi raccogliere le chiavi dalle altre tre.$B$BQueste pietre sono sorvegliate da guardiani, ma se sei $Gastuto:astuta;, o $Gfortunato:fortunata;, potresti trovare il modo di scacciarli.",
  obj = "Raccogli la Burning Key, la Cresting Key e la Thundering Key dalla Stone of West Binding, dalla Stone of East Binding e dalla Stone of Outer Binding.$B$BPortale alla Stone of Inner Binding.",
  progress = "Questa è la Stone of Inner Binding. È la più forte delle pietre del vincolo, e va sbloccata perché le altre si aprano.",
  reward = "<Myzrael parla attraverso la pietra.>$B$BCe l'hai fatta! Hai aperto le Stones of Binding! Sento allentarsi le catene che mi stringono, e la libertà si fa sempre più vicina.$B$BSei $Gun nobile:una nobile; $C, $N. $GIl mio salvatore:La mia salvatrice;!",
  en_title = "Stones of Binding",
  en_obj = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.$B$BBring them to the Stone of Inner Binding.",
}
T[652] = {
  title = "Spezzare la Keystone",
  desc = "Aprire le Stones of Binding ha allentato molto la mia prigionia, ma un lucchetto mi tiene ancora in catene. È la Keystone che vedi in questo cerchio di pietre. E la chiave è in mano a uno dei miei carcerieri, il guardiano di pietra Fozruk.$B$BDevi prendere a Fozruk quella chiave, che i guardiani di pietra chiamano Rod of Order, e usarla per aprire la Keystone.$B$B$N, hai fatto così tanto per aiutarmi. Ancora un piccolo sforzo... e la mia gratitudine scuoterà le fondamenta stesse della terra!",
  obj = "Trova e uccidi Fozruk. Porta il Rod of Order alla Keystone, nelle Arathi Highlands.",
  progress = "La Keystone è carica di un'enorme energia geomantica.",
  reward = "Inserisci la verga nella Keystone. E sotto di te si avverte un fremito...",
  en_title = "Breaking the Keystone",
  en_obj = "Find and kill Fozruk.  Bring the Rod of Order to the Keystone in the Arathi Highlands.",
}
T[653] = {
  title = "Gli alleati di Myzrael",
  desc = "<Myzrael parla.>$B$BLibera! SONO LIBERA! Sono libera di raccogliere le forze, nascosta ai miei carcerieri. Perché se mi affrontassero adesso, di certo mi sopraffarebbero e mi imprigionerebbero di nuovo.$B$BMa col tempo affronterò i giganti, e si pentiranno di avermi tenuta prigioniera!$B$BSei $Gun nobile alleato:una nobile alleata;, $N. Col tempo avrò di nuovo bisogno del tuo aiuto. Quando sarò pronta, dovrai evocarmi in superficie.$B$BParla con Gerrig Bonegrip. Si trova a Ironforge, in una bottega della Forlorn Cavern. Lui sa come evocarmi.",
  obj = "Parla con Gerrig Bonegrip, nella Forlorn Cavern, a Ironforge.",
  reward = "La Signora mi ha annunciato il tuo arrivo, $C. Sei $Gil benvenuto:la benvenuta; nella mia dimora, perché tu, come me, servi una causa più alta.",
  en_title = "Myzrael's Allies",
  en_obj = "Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.",
}
T[655] = {
  title = "Hammerfall",
  desc = "Lo vedo ancora chiaro, come fosse ieri... Tanti anni senza speranza, con legno e acciaio a legarmi a questo luogo terribile. Poi finalmente, finalmente! Ecco il Capoguerra. Doomhammer nella sua armatura color mezzanotte, il martello da guerra alzato al cielo.$B$BFu... troppo terribile... Che il colpo di un codardo abbattesse il nostro più grande eroe. Arrivò alle sue spalle a cavallo, e poi la sua lancia lo trafisse... Caddi in ginocchio. Che speranza c'era? Che speranza c'è...",
  obj = "Parla con Tor'gan, a Hammerfall.",
  reward = "Ah, parli di Gor'mul. Sì, da quello che dice, pare che non si sia mai ripreso dalla morte di Doomhammer.$B$BGor'mul era prigioniero qui quando Thrall e Orgrim combatterono per liberare il campo, ma mentre la terra tremava e i nostri fratelli fuggivano, lui fu lasciato indietro. Ha vagato da solo e smarrito per anni, senza meta né speranza, finché non siamo tornati a stabilirci qui a Hammerfall.",
  en_title = "Hammerfall",
  en_obj = "Speak with Tor'gan in Hammerfall.",
}
T[656] = {
  title = "Evocare la principessa",
  desc = "Devi sconfiggere Myzrael prima che diventi più forte. Altrimenti, quando avrà raccolto abbastanza potere, sfiderà i suoi carcerieri! C'è chi pensa di poterla controllare, ma se si può controllare, perché mai i giganti l'avrebbero incatenata?$B$BLogica da pazzi, eh?$B$BPer sconfiggerla, evocala agli Shards of Myzrael, dove le hai parlato la prima volta. Sconfiggila e raccogli le sue Eldritch Shackles, poi legale agli Shards of Myzrael.$B$BFallo, e sarà di nuovo intrappolata.",
  obj = "Va' agli Shards of Myzrael, evocala e sconfiggila.$B$BRaccogli le sue Eldritch Shackles e legale agli Shards of Myzrael.",
  progress = "Gli Shards of Myzrael ora sono stranamente silenziosi.",
  reward = "Mentre le Eldritch Shackles vengono poste intorno agli Shards, dal profondo si leva un lamento disumano. All'urlo segue un ruggito.$B$BGli Shards of Myzrael non suscitano più il senso di calore e di sicurezza di un tempo. Ora pulsano di una minaccia aperta... come se la cosa sotto di loro nutrisse rancore verso la superficie.",
  en_title = "Summoning the Princess",
  en_obj = "Go to the Shards of Myzrael, summon her and defeat her.$B$BGather her Eldritch Shackles and bind them to the Shards of Myzrael.",
}
T[657] = {
  title = "Indizi di una nuova piaga?",
  desc = "<Quae comincia a sfogliare la cartella.>$B$BQuesto sì che è interessante. Pare che Apothecary Jorell stia lavorando a esperimenti letali qui a Go'Shek. Non so cosa c'entri con Hillsbrad, ma a Phin non piacerebbe se lasciassimo che continui.$B$BAbbiamo avuto uno scontro con degli orchi mentre eri via, e non sono in condizioni di aiutare Kinelory. Se te la senti, le servirà protezione quando scenderà alla fattoria a rubare tutte le ricerche che Jorell non ha ancora mandato a Tarren Mill.",
  obj = "Parla con Kinelory.",
  reward = "Se questo dà pace a Phin, distruggerò ogni singolo Reietto di persona. Ha fatto tanto per noi dopo la piaga. Non avremmo mai pensato di ritrovare amici o famiglia.$B$BQuando sei $Gpronto:pronta;, fammelo sapere. Cominciamo subito.",
  en_title = "Hints of a New Plague?",
  en_obj = "Speak to Kinelory.",
}
T[658] = {
  title = "Indizi di una nuova piaga?",
  desc = "Allora, Phin ti ha mandato a controllare come stiamo? Non mi sorprende: si preoccupa troppo.$B$BTeniamo d'occhio la fattoria da giorni, e Kin sostiene di aver visto un corriere uscire da quella casetta a sud non molto tempo fa.$B$BParla tanto, ma dei suoi sensi mi fido sempre quando siamo in zone pericolose.$B$BNon è che per caso sei $Gun abile battitore:un'abile battitrice; di piste? Crediamo che il corriere stia portando appunti a Tarren Mill. Se riuscissimo a mettere le mani su quei documenti, forse capiremmo qualcosa di quel che sta succedendo a Hillsbrad.",
  obj = "Trova la Forsaken Courier e porta il suo Sealed Folder a Quae, vicino alla Go'Shek Farm.",
  progress = "Ti siamo grati dell'aiuto nella ricerca di quel corriere, $N.$B$BMentre eri via, Kin ha visto uno speziale uscire dalla stessa casa qui a sud. Sono convinta che stiano tramando qualcosa: mi serve solo la prova prima di andare a fare qualche sciocchezza.$B$BHai avuto fortuna?",
  reward = "Ottimo!$B$BVediamo di cosa si tratta...",
  en_title = "Hints of a New Plague?",
  en_obj = "Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.",
}
T[659] = {
  title = "Indizi di una nuova piaga?",
  desc = "Salve, e ben $Gincontrato:incontrata;, $N. Guido un gruppo di avventurieri che indaga su strani fatti in questa zona.$B$BMio cugino, a Hillsbrad, ha dovuto abbattere il suo cane Stanley perché l'animale è cresciuto misteriosamente fino a diventare enorme e attaccava con ferocia chiunque gli si avvicinasse.$B$BCredo che di mezzo ci siano i non morti, e stiamo cercando prove che lo dimostrino.$B$BDue miei compagni, Quae e Kinelory, sono andati alla Go'Shek Farm, nelle Arathi Highlands, e non si fanno vivi da giorni. Me li trovi? Comincio a preoccuparmi.",
  obj = "Trova Quae e Kinelory vicino alla Go'Shek Farm, nelle Arathi Highlands.",
  reward = "Cerca di fare meno rumore possibile, $Gviaggiatore:viaggiatrice;.$B$BGli orchi non la prendono bene quando li si spia, e in questa fattoria c'è più di quel che sembra.",
  en_title = "Hints of a New Plague?",
  en_obj = "Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands.",
}
T[660] = {
  title = "Indizi di una nuova piaga?",
  desc = "Bene, $N. Io sono pronta, se lo sei tu.$B$BAndiamo?",
  obj = "Proteggi Kinelory finché non torna da Quae.",
  progress = "Il tempo delle chiacchiere è finito. Proteggi Kinelory, se ti importa qualcosa della gente di Hillsbrad.",
  reward = "Ci hai reso un grande servizio, $N. Grazie.$B$BSpero che Kin non ti abbia dato troppo filo da torcere laggiù. È molto amichevole, ma sa essere altrettanto letale quando le sei $Gnemico:nemica;.",
  en_title = "Hints of a New Plague?",
  en_obj = "Protect Kinelory until she returns to Quae.",
}
T[661] = {
  title = "Indizi di una nuova piaga?",
  desc = "Ho visto Kinelory messa molto peggio dopo una notte in taverna di come sta adesso. Si vede che l'hai protetta bene.$B$BQueste cose che ha riportato dalla fattoria dovrebbero almeno far capire a Phin cosa sta succedendo qui in Arathi. Giusto per essere sicuri che non ci siano rappresaglie dopo il vostro attacco, ci fermeremo qui ancora un po'. Te la sentiresti di tornare a Southshore e parlare con Phin?",
  obj = "Trova Phin Odelic, a Southshore.",
  reward = "Allora, i due piantagrane stanno bene dopotutto? Ahah, sono contento di saperlo. Ti ringrazio per avermi portato notizie di dove sono e di come stanno: mi fa molto piacere che siano ancora vivi; come amici e compagni di viaggio quei due sono insostituibili.$B$BMa... è più importante ringraziarti come si deve per il tuo aiuto. Tieni. Prendi questo, insieme ai ringraziamenti del mio gruppo.$B$BCon un po' di fortuna capiremo cosa stanno combinando i Reietti e vi metteremo fine.",
  en_title = "Hints of a New Plague?",
  en_obj = "Find Phin Odelic in Southshore.",
}
T[662] = {
  title = "Recupero in acque profonde",
  desc = "O'Breen ha guidato le navi nella baia. Eravamo certi che il tesoro si trovasse qui. La Harbinger ha attraccato senza problemi, ma mentre la Maiden's Folly e la Spirit of Silverpine si avvicinavano, la marea ha cominciato ad abbassarsi. La cosa più strana che abbia mai visto!$B$BQuelle due navi si sono arenate contro qualcosa... una specie di tempio nella scogliera. Sono affondate così in fretta, è stata una vera tragedia.$B$BPrima di partire dobbiamo recuperare i loro diari di bordo e le loro carte nautiche. Non possiamo lasciare quelle informazioni a occhi indiscreti!",
  obj = "First Mate Nilzlix vuole che tu recuperi Maiden's Folly Charts, Maiden's Folly Log, Spirit of Silverpine Charts e Spirit of Silverpine Log.",
  progress = "Come va la missione di ricerca e recupero, $N? Dobbiamo proprio riavere quei diari di bordo e quelle carte nautiche della Maiden's Folly e della Spirit of Silverpine.$B$BSe le informazioni di quelle fonti cadessero in mano al nemico, Fleet Master Seahorn ci farebbe camminare sull'asse.$B$BSempre che riusciamo a uscire da questo pasticcio...",
  reward = "Sapere che queste informazioni sono al sicuro darà un po' di sollievo al comando di Booty Bay. Ben fatto, $N.",
  en_title = "Deep Sea Salvage",
  en_obj = "First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine.",
}
T[663] = {
  title = "Terra in vista!",
  desc = "Lolo vede $Gun piccolo:una piccola; $R! Sempre di vedetta, Lolo è!$B$B$GBenvenuto:Benvenuta; al Faldir's Cove. Captain O'Breen ha detto che saremmo rimasti qui solo poche ore. Giusto il tempo di recuperare il tesoro e tornare a Booty Bay.$B$BMa Lolo pensa che resteremo qui molto più a lungo. Abbiamo perso le altre due navi della nostra formazione. Povere Spirit of Silverpine e Maiden's Folly. Ora riposano in fondo al mare!$B$BLolo ti consiglia di parlare con Captain O'Breen, se pensi di fermarti da queste parti.",
  obj = "Parla con Captain O'Breen, al Faldir's Cove.",
  reward = "Ahoy, $Gcompagno:compagna;.$B$BÈ stato un disastro terribile. Seahorn mi toglierà la nave, se scopre cos'è successo.$B$BUno degli aggeggi del professore indicava che il tesoro perduto era vicino a questa baia. Ho portato la Harbinger all'attracco e ho fatto segno alla Spirit of Silverpine e alla Maiden's Folly di fare lo stesso.$B$BPoi il mare ha brontolato. La marea si è abbassata e le due navi si sono schiantate contro la scogliera.$B$BNon è solo una scogliera. Laggiù c'è qualcosa...$B$BAiuta il mio equipaggio e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Land Ho!",
  en_obj = "Talk to Captain O'Breen in Faldir's Cove.",
}
T[664] = {
  title = "Dispiaceri annegati",
  desc = "Argh, che vita orribile. Adesso dovrei trovarmi in una tomba d'acqua, non seduto qui accanto al fuoco a respirare aria fresca.$B$BL'equipaggio ha fatto di tutto per salvare la mia bella Maiden's Folly. Benedetti ragazzi, benedetti i loro cuori.$B$BO'Breen è arrivato a riva sano e salvo, ma noi non siamo stati così fortunati. Il mare ci è crollato sotto, lo giuro.$B$BUn attimo prima galleggiamo e un attimo dopo l'acqua entra a fiotti. E quelle bestie! Hanno ucciso tutti i sopravvissuti. Orribile feccia naga. Ho perso i sensi e mi sono ritrovato qui, salvo.$B$BVoglio quelle bestie morte.",
  obj = "Captain Steelgut, al Faldir's Cove, vuole che tu uccida 10 Daggerspine Raider e 3 Daggerspine Sorceress.",
  progress = "Bah, forse dovrei andare io stesso a uccidere quella feccia naga. È evidente che tu non lo farai.$B$BForse posso trovarti dei ferri da maglia, così hai qualcosa da fare.",
  reward = "Bel lavoro là fuori, $N.$B$BQuella feccia ha avuto quello che si meritava. Anche se niente mi restituirà la mia nave o il mio equipaggio, la morte di quei naga mi dà un po' di conforto.",
  en_title = "Drowned Sorrows",
  en_obj = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.",
}
T[665] = {
  title = "Tesoro sommerso",
  desc = "Ora che siamo Blackwater Raiders a tutti gli effetti, è nostro compito aiutare il signor O'Breen a trovare il tesoro elfico perduto.$B$BÈ quasi impossibile trovare le gemme nel buio del mare senza aiuto. Il dottore ha costruito degli occhialoni che serviranno allo scopo. Ha bisogno che vengano caricati con l'energia della pietra incantata che si trova nella grotta, appena su per la collina.$B$BMa la grotta è maledetta! Quando ci avviciniamo, ci tendono un'imboscata. Difendimi e riuscirò a imbrigliare negli occhialoni l'energia della pietra.",
  obj = "Scorta Professor Phizzlethorpe fino alla grotta e ritorno.",
  progress = "Non è il momento di chiacchierare! Gli occhialoni devono essere caricati con il potere della pietra!",
  reward = "Adesso gli occhialoni funzionano alla perfezione! Ben fatto, $N.",
  en_title = "Sunken Treasure",
  en_obj = "Escort Professor Phizzlethorpe to the cave and back.",
}
T[666] = {
  title = "Tesoro sommerso",
  desc = "Il tesoro è rimasto sul fondo del mare così a lungo che le gemme si sono calcificate in una spessa pietra. Ma il potere racchiuso in questi occhialoni ti permetterà di trovarle facilmente.$B$BUn pizzico di ingegno gnomesco fa molta strada!$B$BQuindi prendi in prestito i Goggles of Gem Hunting, $N, e vedi se riesci a raccogliere un po' del tesoro perduto per Captain O'Breen.$B$BCi andrei a nuoto io stesso, ma... ehm... be', ho importanti faccende scientifiche da sbrigare quassù, sulla terraferma sicura e asciutta... ehm, sì.",
  obj = "Doctor Draxlegauge, al Faldir's Cove, vuole che tu raccolga 10 Elven Gem e che restituisca i Goggles of Gem Hunting quando hai finito.",
  progress = "Come sono andati gli occhialoni? Ha funzionato tutto a dovere? Se serve, si possono fare delle regolazioni.$B$BAh, e quando hai finito mi servono indietro quegli occhialoni. Sono sicuro che Captain O'Breen troverà molti modi di usarli più avanti.",
  reward = "Magnifico, $N! Il capitano sarà molto contento! E aspetta che la notizia arrivi a Fleet Master Seahorn!",
  en_title = "Sunken Treasure",
  en_obj = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.",
}
T[667] = {
  title = "Morte dal profondo",
  desc = "Questa è brutta. Sembra che i Daggerspine si stiano radunando per un attacco.$B$BI naga sono noti per la loro spietatezza in battaglia. Continueranno ad attaccare finché non sarò morto.$B$BNon considero la mia vita più preziosa di quella dei miei uomini, ma devi aiutarmi a difendermi. L'equipaggio non riuscirà a tornare a Booty Bay senza la mia conoscenza dei mari.$B$BI naga arriveranno dal mare. Ho bisogno che resti quassù con me a respingere l'attacco. Mettiti al cannone e ricacciali indietro.$B$BSei $Gpronto:pronta;, $N?",
  obj = "Proteggi Shakes O'Breen durante l'attacco.",
  reward = "Siamo sopravvissuti all'attacco!$B$BNon ce l'avremmo mai fatta senza di te, $N.$B$BSalperemo appena la marea salirà. Se non fossi $Gun eroe:un'eroina; così promettente, ti offrirei un posto nel mio equipaggio. Ma vedo che hai cose più grosse a cui pensare.$B$BAnche se sei $Gun:una; $R $Gmingherlino:mingherlina;...",
  en_title = "Death From Below",
  en_obj = "Protect Shakes O'Breen during the attack.",
}
T[668] = {
  title = "Tesoro sommerso",
  desc = "Non facciamo aspettare Captain O'Breen. Vorrà vedere queste gemme con i suoi occhi. Dopotutto, è per questo che siamo qui!$B$BE dopo qualche settimana passata in compagnia di questi pirati, io e il professore ci siamo resi conto che la cosa peggiore per la nostra salute è farci trovare con il loro tesoro in mano.$B$BTieni, $N, portale a O'Breen.",
  obj = "Porta le Elven Gems a Captain O'Breen.",
  progress = "Ahoy, $C. Cosa ti porta sul ponte di comando?",
  reward = "Allora quei piccoli gnomi si sono dimostrati utili, dopotutto? Lo sapevo che c'era un motivo per tenerci intorno quei mezzi tappi!",
  en_title = "Sunken Treasure",
  en_obj = "Take the Elven Gems to Captain O'Breen.",
}
T[669] = {
  title = "Tesoro sommerso",
  desc = "Fleet Master Seahorn vorrà sapere subito della nostra scoperta.$B$BMa come vedi, non siamo nella posizione di andarcene da qui. Non solo la marea è troppo bassa, ma quelle maledette creature che abbiamo disturbato tengono d'occhio ogni nostro movimento.$B$BPuoi rendere un grande servizio ai Blackwater Raiders se riesci a far sapere a Fleet Master Seahorn, a Booty Bay, che abbiamo scoperto il tesoro e che stiamo lavorando per recuperarne altro. Portagli questo campione come prova.",
  obj = "Porta il Sample Elven Gem a Fleet Master Seahorn, a Booty Bay.",
  progress = "Cosa ti porta a Booty Bay, $C?",
  reward = "Ah, ci si può sempre fidare del buon vecchio Shakes O'Breen! Sapevo che era il capitano giusto per la missione!",
  en_title = "Sunken Treasure",
  en_obj = "Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay.",
}
T[670] = {
  title = "Tesoro sommerso",
  desc = "Ehi, $N, mi sembri il tipo avventuroso. La mia flotta è bloccata a Booty Bay finché non riusciamo a rifornirci.$B$BQui e altrove bollono in pentola cose grosse, e devo far arrivare della corrispondenza segretissima a Shakes O'Breen, che è bloccato al largo della costa di Arathi.$B$BPosso fidarmi di te per consegnare questo messaggio al sicuro e in tutta riservatezza?",
  obj = "Consegna Seahorn's Sealed Letter a Shakes O'Breen, negli Arathi Highlands.",
  progress = "Allora, Seahorn è rimasto colpito? Scommetto che il suo sorriso andava da Booty Bay fino a Ratchet.",
  reward = "Grazie per aver affrontato un viaggio così lungo e pericoloso. Hai la gratitudine dei Blackwater Raiders.",
  en_title = "Sunken Treasure",
  en_obj = "Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands.",
}
T[671] = {
  title = "Magie immonde",
  desc = "Ho sentito una stranezza nell'aria... una sensazione che mi ribolle nel sangue. Avevo i miei sospetti. Sono partito per trovare l'origine del mio disagio e ho scoperto a ovest, a Northfold Manor, le tracce residue di un'evocazione demoniaca. Man mano che mi avvicinavo, il sangue ha cominciato a ribollirmi e la rabbia dentro di me è cresciuta.$B$BA terra ho notato un amuleto di sanguinaria, usato per aiutare le evocazioni demoniache. Quello che ho trovato però era esaurito. Me ne servirà un altro da esaminare, ma non oso tornare al maniero. Puoi portarmene qualcuno?",
  obj = "Procura 10 Bloodstone Amulet per Tor'gan, a Hammerfall.",
  progress = "Nelle mie vene scorre ancora sangue un tempo maledetto, $N. Se qualcuno... qualcosa sta evocando demoni, va fermato.",
  reward = "Mi ci vorrà un po' di tempo per accertare le vere intenzioni del Syndicate, ma il loro evidente legame con la magia oscura e demoniaca mi preoccupa. Ti dirò quando ne saprò di più.",
  en_title = "Foul Magics",
  en_obj = "Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.",
}
T[672] = {
  title = "Risollevare lo spirito",
  desc = "Abbiamo cercato di farlo ambientare, di tirargli su il morale, raccontandogli della nostra potente città di Orgrimmar, a Kalimdor, ma niente riusciva a smuoverlo.$B$BRacconti del nostro giovane Capoguerra, Thrall, che porta l'armatura e il martello di Orgrim... ma forse... Forse! Una dimostrazione della magia sciamanica che abbiamo ritrovato da poco gli darebbe nuova speranza. Vale la pena tentare!$B$BUn piccolo oggetto che potremmo fare per lui, sì... Portami degli occhi di raptor, e vedrò cosa posso fare.",
  obj = "Procura 10 Highland Raptor Eye dagli Highland Strider e dagli Highland Thrasher per Tor'gan, a Hammerfall.",
  progress = "Creerò un amuleto che darà a Gor'mul un po' della forza dei raptor. Forse risveglierà una fiamma dentro di lui...",
  reward = "Eccellente. Gli spiriti dei raptor che hanno dato questi occhi presteranno la loro forza a chi porterà questo amuleto.",
  en_title = "Raising Spirits",
  en_obj = "Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.",
}
T[673] = {
  title = "Magie immonde",
  desc = "Non ho dubbi che dentro le mura di Stromgarde viva un potente stregone. Di tanto in tanto, con una reliquia magica arcana, questo stregone evoca terribili demoni in gran numero. Dobbiamo eliminare la fonte del suo potere.$B$BTrova lo stregone e uccidilo. Portami qualunque oggetto magico gli trovi addosso, e farò in modo di distruggerlo e di impedire che il suo potere venga usato ancora per portare la corruzione in questa terra.",
  obj = "Recupera il Befouled Bloodstone Orb di Marez Cowl e portalo a Tor'gan, a Hammerfall.",
  progress = "Il bruciore nel mio sangue... cresce ogni giorno. Lo stregone va fermato.",
  reward = "Le mie notti inquiete diventeranno sonni tranquilli quando avrò distrutto questo globo. Grazie, $N. È un agghiacciante ricordo del terribile potere che i demoni avevano sugli orchi prima che Hellscream li liberasse dalla loro maledizione.",
  en_title = "Foul Magics",
  en_obj = "Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.",
}
T[674] = {
  title = "Risollevare lo spirito",
  desc = "Ecco, porta questo amuleto a Gor'mul, e vedi se la forza dei raptor riesce a risvegliare la fiamma del guerriero che un tempo gli ardeva nelle vene.",
  obj = "Dai il Raptor Talon Amulet a Gor'mul.",
  progress = "Che speranza c'è, quando la mano di un codardo può uccidere il più possente tra i possenti? Che speranza, ti chiedo!",
  reward = "Cos'è questo? Osso levigato. Che me ne faccio di un osso levigato? Un ninnolo riporterà l'Orda alla sua gloria?",
  en_title = "Raising Spirits",
  en_obj = "Give the Raptor Talon Amulet to Gor'mul.",
}
T[675] = {
  title = "Risollevare lo spirito",
  desc = "<Gor'mul getta l'amuleto a terra.>$B$BTi ha mandato Tor'gan, vero? Pah! Non capisco perché provi pietà per me. La pietà mi è stata negata quando non mi è stato permesso di morire in battaglia con il mio Capoguerra. Un colpo crudele mi ha inflitto il destino...",
  obj = "Parla con Tor'gan.",
  reward = "Non ha funzionato, vedo. Tuttavia, sento che mostrargli il potere degli sciamani alla fine riporterà Gor'mul a essere fiero come un tempo. Il potere dell'amuleto non era abbastanza grande per mostrargli il nostro nuovo potere.",
  en_title = "Raising Spirits",
  en_obj = "Speak with Tor'gan.",
}
T[676] = {
  title = "Il martello potrebbe cadere",
  desc = "Deboli... tutti quanti. Tu, $C, cos'hai da guardare? Ti credi $Gqualcuno di speciale:qualcuna di speciale;, eh? Perché non lo dimostri?$B$BL'avamposto di Hammerfall, in Arathi, è sotto attacco. Se non mandiamo aiuto presto, la loro fine è vicina.$B$BMa prima di correre via, forse ti conviene mettere alla prova le tue capacità. A nord-est di Stromgarde, in Arathi, c'è un tumulo di ogre abitato dalla tribù Boulderfist. Quando te la saprai cavare con gli ogre e gli enforcer che ci sono là, va' a rapporto da Drum Fel, a Hammerfall.",
  obj = "Uccidi 8 Boulderfist Ogre e 10 Boulderfist Enforcer, poi trova Drum Fel all'avamposto di Hammerfall, nelle Arathi Highlands.",
  progress = "Non ho tempo di affilare la mia ascia, figuriamoci di lasciare l'avamposto per uccidere quelle bestie che vogliono uccidere i miei simili.$B$BNon sembri avere l'esperienza di un grunt, figuriamoci quella di $Gun vero e proprio:una vera e propria; $C. Cosa vuoi, $N?",
  reward = "Allora, ti credi abbastanza forte da aiutare Hammerfall? E sia.$B$BO Tallow ti ha mandato a quel tumulo di ogre sperando che ti facessi ammazzare, o ti crede abbastanza forte da aiutarci. In un modo o nell'altro adesso sei qui, e a me servono altri soldati nella lotta contro questi attacchi continui.$B$BSe hai intenzione di fermarti a Hammerfall, riposati e torna a parlarmi quando sei $Gpronto:pronta;. Di battaglie da combattere ce n'è in abbondanza.",
  en_title = "The Hammer May Fall",
  en_obj = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.",
}
T[677] = {
  title = "Chiamata alle armi",
  desc = "I troll Witherbark e gli ogre Boulderfist di Arathi collaborano per cacciarci da questa terra, ma non incontreremo il nostro destino per mano loro, né di nessun altro. Li uccideremo e mostreremo loro che anche noi abbiamo una casa qui.$B$BI troll ci hanno voltato le spalle; gli ogre ci userebbero come cibo e come giaciglio, se glielo permettessimo: tutto questo non accadrà.$B$BCominciamo il nostro attacco contro i troll Witherbark a sud di qui. Uccidili a frotte, e torna solo quando i loro accampamenti saranno inondati di sangue.",
  obj = "Uccidi 10 Witherbark Axe Thrower, 10 Headhunter e 8 Witch Doctor, e torna da Drum Fel all'avamposto di Hammerfall.",
  progress = "Se non hai ancora portato a termine il mio compito, forse sei $Gun vigliacco:una vigliacca; di cuore, oltre che $Gun principiante:una principiante; in guerra.",
  reward = "I segni della guerra sono sui tuoi abiti, e il sudore ti gocciola dalla fronte. Bene, davvero molto bene.",
  en_title = "Call to Arms",
  en_obj = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.",
}
T[678] = {
  title = "Chiamata alle armi",
  desc = "La tua forza è evidente, $N. Ora vediamo come te la cavi contro un vero nemico.$B$BI Boulderfist hanno una tana a sud-ovest di qui, verso il ponte dei nani, e, se non mi sbaglio, i picchiatori e i maghi che ci vivono saranno per te una sfida più grande: finora lo sono stati per noi.$B$BUccidine quanti più puoi e vieni da me in carne e ossa se ci riesci, o in spirito se fallisci. In entrambi i casi loderò la tua tenacia in battaglia.",
  obj = "Uccidi 10 Boulderfist Brute e 4 Boulderfist Magus, e torna da Drum Fel all'avamposto di Hammerfall.",
  progress = "Esiti. Perché? Finora hai dimostrato grande forza, $N. Non deludermi proprio adesso.",
  reward = "Sei forte come un kodo, e la tua sete di battaglia fa onore al tuo popolo.",
  en_title = "Call to Arms",
  en_obj = "Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost.",
}
T[679] = {
  title = "Chiamata alle armi",
  desc = "La testa della bestia è pronta per essere mozzata... con grande forza, $N. Hai dato ogni prova di poterci aiutare a sferrare questo potente colpo finale. I capi di questi attacchi hanno fatto la loro tana tra le rovine di Stromgarde, simbolo lampante della fragilità umana.$B$BTrova e uccidi quei Boulderfist Lord e gli sciamani loro tirapiedi che vorrebbero cacciarci da queste terre.",
  obj = "Uccidi 15 Boulderfist Shaman e 10 Boulderfist Lord e torna da Drum Fel all'avamposto di Hammerfall.",
  progress = "Vedo che il tuo coraggio finalmente vacilla. Pare che il mio istinto su di te avesse ragione: la tua forza non è niente in confronto alla tua spavalderia.$B$BTorna da me quando la testa della bestia sarà stata mozzata, o non tornare mai più.",
  reward = "Fai onore al tuo popolo, $N. La minaccia si è molto ridotta, e sono certo che cominceremo a prosperare qui nelle Highlands.",
  en_title = "Call to Arms",
  en_obj = "Kill 7 Boulderfist Shaman and 3 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost.",
}
T[680] = {
  title = "La vera minaccia",
  desc = "Servi bene mio marito, $C, ma lui non sa perché Hammerfall è sotto attacco.$B$BOr'Kalar, la pedina di Mug'thol a Stromgarde, nutre un odio profondo per mio marito, e non desidera altro che la sua morte, per averlo sconfitto anni fa.$B$BLe mie divinazioni mi dicono che Or'Kalar ha teso una trappola a mio marito, perciò gli ho nascosto i segni della presenza dell'ogre.$B$BSe mio marito scoprisse dove si trova l'ogre, si precipiterebbe là come uno sciocco, e io vorrei chiederti di aiutarmi a uccidere la creatura.",
  obj = "Uccidi Or'Kalar e porta Or'Kalar's Head a Korin Fel, all'avamposto di Hammerfall.",
  progress = "Vicino alla Tower of Arathor: è lì che troverai Or'Kalar. La sua morte fermerà gli attacchi a Hammerfall e proteggerà la vita di mio marito.$B$BVedo nei tuoi occhi che mi credi debole, persino senza onore, per il mio silenzio. Un giorno imparerai cosa significa amare come amo io. Forse allora capirai che esiste un altro tipo di forza e di onore.$B$BNel frattempo, fa' come ti chiedo e uccidi Or'Kalar.",
  reward = "Mi hai reso un grande servizio, $N. Sappi che grazie alle tue azioni la vita di mio marito e la sicurezza di Hammerfall sono salve per un altro giorno. Ti prego, accetta questo come ricompensa per il tuo coraggio.",
  en_title = "The Real Threat",
  en_obj = "Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.",
}
T[681] = {
  title = "Northfold Manor",
  desc = "Stiamo combattendo una guerra per Stromgarde, e la stiamo perdendo. Gli ogre, il Syndicate e noi ci siamo divisi la nostra città un tempo grande, e ogni fazione combatte le altre in uno stallo sanguinoso.$B$BMa le nostre forze diminuiscono mentre il nemico cresce.$B$BCi serve aiuto dalla città di Southshore, ma è difficile ricevere rifornimenti finché il Syndicate controlla il territorio tra noi.$B$BVa' alla base del Syndicate a Northfold Manor e uccidili. Allora, forse, la pressione sui nostri convogli di rifornimenti diminuirà e ne arriveranno di più.",
  obj = "Uccidi 10 Syndicate Highwayman e 6 Syndicate Mercenary.$B$BTorna da Captain Nials, a Refuge Pointe.",
  progress = "$N, ogni ora che passa la nostra presa su Stromgarde si fa più debole. Devi sbrigarti, o la nostra città cadrà di sicuro.",
  reward = "Molto bene, $N. Con la morte di quei membri del Syndicate dovremmo ricevere più facilmente i rifornimenti da Southshore.$B$BForse la nostra causa ha ancora speranza.",
  en_title = "Northfold Manor",
  en_obj = "Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries.$B$BReturn to Captain Nials at Refuge Pointe.",
}
T[682] = {
  title = "Stromgarde Badges",
  desc = "A Stromgarde il Syndicate combatte contro il nostro contingente di miliziani. Per spingere la marmaglia a battersi contro le nostre truppe, più disciplinate, i capi del Syndicate hanno messo una taglia sui nostri soldati: pagano in oro ogni Stromgarde Badge preso ai miliziani uccisi.$B$BVogliamo recuperare quei distintivi: non possiamo permettere a quei tagliagole di prendersi trofei dai nostri coraggiosi caduti!$B$BEntra nella zona di Stromgarde controllata dal Syndicate e dai loro la caccia per riprenderti i nostri distintivi.",
  obj = "Porta gli Stromgarde Badge a Captain Nials, a Refuge Pointe.",
  progress = "Hai recuperato qualche Stromgarde Badge, $N? Il Syndicate deve imparare che non può trarre profitto dai nostri morti.",
  reward = "Grazie, $N. Informeremo le famiglie di questi soldati che sono caduti in battaglia.$B$BSarà una triste notizia da portare, ma è meglio dell'incertezza per una persona cara scomparsa.",
  en_title = "Stromgarde Badges",
  en_obj = "Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe.",
}
T[683] = {
  title = "La supplica di Sara Balloo",
  desc = "$N, ho solo una piccola richiesta da farti.$B$BPorta questo biglietto che ho preparato al nostro grande sovrano di Ironforge, King Magni Bronzebeard. È un compito da poco per una persona come te, che finora ha dato grandi prove di valore per la causa dell'Alleanza.$B$BPresentarmi davanti al Re nello stato di dolore in cui sono non gioverebbe alla mia causa. Sono certa che capisci.",
  obj = "Porta il biglietto di Sara Balloo a King Magni Bronzebeard, a Ironforge.",
  progress = "Quindi sei tu $N, $Gil:la; $C? Le notizie del tuo contributo all'Alleanza sono arrivate piuttosto lontano, lo sai?$B$BPer quale faccenda ti presenti oggi davanti a me?",
  reward = "Mi basterà un momento per scorrere questa lettera...",
  en_title = "Sara Balloo's Plea",
  en_obj = "Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.",
}
T[684] = {
  title = "Wanted! Marez Cowl",
  desc = "È stata messa una taglia sulla testa di Marez Cowl, consigliera di alto rango e agente del Syndicate. È stata vista l'ultima volta nel territorio di Stromgarde controllato dal Syndicate.$B$BLa taglia si può riscuotere da Captain Nials.$B$BAttenzione: Marez è una strega abile e astuta, nota per i suoi traffici con i demoni. Si raccomanda la massima prudenza a chi le dà la caccia.",
  obj = "Porta Marez's Head a Captain Nials, a Refuge Pointe.",
  progress = "Salve, $C. Hai un rapporto da fare?",
  reward = "Hai abbattuto Marez Cowl? Ben fatto, $N. Davvero ben fatto!$B$BMarez minacciava i nostri difensori di Stromgarde, e si dice che facesse da tramite tra il Syndicate e un altro potere, più oscuro. Siamo lieti di sapere che non userà più i suoi poteri contro di noi.",
  en_title = "Wanted!  Marez Cowl",
  en_obj = "Bring Marez's head to Captain Nials at Refuge Pointe.",
}
T[685] = {
  title = "Wanted! Otto e Falconcrest",
  desc = "La Stromgarde Militia ha messo una taglia sulla testa di Lord Falconcrest e della sua guardia del corpo, Otto. Falconcrest guida le operazioni del Syndicate nelle Arathi Highlands, e la sua morte le metterebbe in grave difficoltà.$B$BLa sua guardia del corpo, Otto, pur non essendo un obiettivo strategico, è un avversario feroce e ha ucciso decine dei nostri difensori.$B$BLe taglie si possono riscuotere da Captain Nials.",
  obj = "Porta Otto's Head e Falconcrest's Head a Captain Nials, a Refuge Pointe.",
  progress = "Salve. Hai un rapporto da presentare?",
  reward = "Falconcrest e Otto? Magnifico!$B$BEcco la tua ricompensa, $N. Sono felice di pagarla.",
  en_title = "Wanted!  Otto and Falconcrest",
  en_obj = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.",
}
T[686] = {
  title = "Il tributo di un re",
  desc = "Non mi aspetto che brave nane come Mrs. Balloo capiscano perché le brutture della guerra vadano sopportate per il bene più grande del nostro popolo. La perdita di suo marito, e quella di ogni nano che combatte nel nome dell'Alleanza, mi pesa sull'anima.$B$BNon posso riportare indietro suo marito dal Twisting Nether, ma posso rendergli omaggio.$B$BCommissionerò a Grand Mason Marblesten un memoriale per Sully Balloo.$B$BMandagli parola subito, $C. Sarai tu a portare il mio ordine.",
  obj = "King Magni Bronzebeard vuole che tu parli con Grand Mason Marblesten.",
  reward = "Quindi ti manda King Magni Bronzebeard in persona?$B$BPerbacco! Dev'essere una cosa importante!",
  en_title = "A King's Tribute",
  en_obj = "King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.",
}
T[687] = {
  title = "Theldurin the Lost",
  desc = "Theldurin the Lost un tempo era un membro del nostro ordine, il Martello del Crepuscolo. Ma ha perso il senno e ha disprezzato i nostri insegnamenti. E prima di fuggire da noi, ha rubato la pergamena di Myzrael! Non siamo riusciti a prenderlo, ma si dice che si nasconda nei Badlands, farfugliando come un pazzo.$B$BPer riportare la Signora da noi, devi trovare la pergamena. E per farlo, devi trovare Theldurin.",
  obj = "Trova Theldurin the Lost.",
  reward = "Ciao. Ciao, ciao ciao ciao ciao CIAO!$B$BMi dispiace... un momento, no, non mi dispiace affatto! Non essere scortese!$B$BOh no... questi sono discorsi da pazzo.$B$BMa... a volte essere pazzo è il mio unico conforto.",
  en_title = "Theldurin the Lost",
  en_obj = "Find Theldurin the Lost.",
}
T[688] = {
  title = "Gli alleati di Myzrael",
  desc = "<Myzrael parla.>$B$BLibera! SONO LIBERA! Sono libera di raccogliere le forze, nascosta ai miei carcerieri. Perché se mi affrontassero adesso, di certo mi sopraffarebbero e mi imprigionerebbero di nuovo.$B$BMa col tempo affronterò i giganti, e si pentiranno di avermi tenuta prigioniera!$B$BSei $Gun nobile alleato:una nobile alleata;, $N. Col tempo avrò di nuovo bisogno del tuo aiuto. Quando sarò pronta, dovrai evocarmi in superficie.$B$BParla con Zaruk, a Hammerfall. Lui sa come evocarmi.",
  obj = "Parla con Zaruk, a Hammerfall.",
  reward = "$GBenvenuto:Benvenuta;, $C. La Signora mi ha informato del tuo arrivo, e se dobbiamo riportarla in superficie, abbiamo molto di cui parlare...",
  en_title = "Myzrael's Allies",
  en_obj = "Speak with Zaruk in Hammerfall.",
}
T[689] = {
  title = "Il tributo di un re",
  desc = "Quindi il nostro buon Re vuole un memoriale in onore di un soldato di nome Sully Balloo? E tu dici che il poveretto è morto durante la tragedia del Thandol Span?$B$BBah, ci sarà mai pace su Azeroth?$B$BIn ogni caso, ogni incarico del Re è della massima importanza. Per fare un'opera davvero epica e duratura voglio lavorare con una delle pietre migliori che ci siano. Va' a Darrow Hill, a Hillsbrad, e raccogli per me un po' di Alterac Granite.",
  obj = "Grand Mason Marblesten, a Ironforge, vuole 5 Alterac Granite.",
  progress = "$N, $N, $N! Dimmi che hai abbastanza Alterac Granite perché io possa cominciare il mio capolavoro in onore di Sully Balloo.",
  reward = "Perfetto! Meglio di come potessi immaginare!$B$BE di immaginazione ne ho parecchia, sai...",
  en_title = "A King's Tribute",
  en_obj = "Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.",
}
T[690] = {
  title = "La richiesta di Malin",
  desc = "Salve, $N. Hai l'aria di $Gun avventuriero:un'avventuriera;, e io ho un compito di cui qualcuno deve occuparsi.$B$BArchmage Trelane, il mio primo maestro, è fuggito da Stromgarde, nelle Arathi Highlands, non molto tempo fa, e mi ha chiesto di aiutarlo a recuperare alcune delle cose che ha lasciato indietro.$B$BLa città è caduta sotto assedio e lui ha tentato di difendere la Tower of Arathor, ma senza risultato. Ho già degli agenti nelle Highlands, ma mi hanno chiesto di mandare altro aiuto. Ti interessa?",
  obj = "Trova Skuerto a Refuge Pointe, nelle Arathi Highlands.",
  reward = "Allora, ti manda Malin? Non m'importa se Muradin è risorto dai morti e ti ha portato qui in volo su un drago. Sono occupato! Parla con Kryten se ti serve qualcosa.",
  en_title = "Malin's Request",
  en_obj = "Find Skuerto at Refuge Pointe in the Arathi Highlands.",
}
T[691] = {
  title = "Vale tanto oro quanto pesa",
  desc = "Archmage Malin ha mandato qui Skuerto e me a raccogliere reagenti per lui. Non sapevo proprio come avrei fatto a procurarmi queste cose, ma ora che sei qui credo che il mio problema sia risolto.$B$BMi serve questo: Witherbark Tusk, Witherbark Medicine Pouch e uno Shadow Hunter Knife.$B$BPotresti trovarmeli? I Witherbark vivono nel sud-est di Arathi.",
  obj = "Trova 10 Witherbark Tusk, 4 Witherbark Medicine Pouch e uno Shadow Hunter Knife per Apprentice Kryten, a Refuge Pointe.",
  progress = "Hai avuto fortuna finora, $N?$B$B<Kryten prende qualche appunto sul suo diario mentre legge.>$B$BSe le mie ricerche sono corrette, le zanne dovrebbero venire da qualunque troll Witherbark. Le borse di medicine vengono dagli stregoni Witherbark, e i più forti tra i cacciatori delle ombre Witherbark dovrebbero portare il coltello speciale che ricevono dopo aver completato i riti di passaggio. Non c'è modo di sapere quali cacciatori delle ombre abbiano il coltello finché non li affronti.",
  reward = "Incredibile! Capisco perché Malin ti ha chiesto di unirti a noi: davvero un ottimo lavoro!$B$BDi questo passo, Skuerto e io torneremo a Stormwind in un attimo.$B$BCredo che il mio compagno nano sia tornato dalla ricognizione di Boulderfist Hall; va' a parlargli quando sei $Gpronto:pronta;.$B$BSembrava che avesse avuto una piccola zuffa con gli ogre. Ma non dirglielo: è molto suscettibile alle critiche sulle sue capacità di esploratore.",
  en_title = "Worth Its Weight in Gold",
  en_obj = "Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.",
}
T[692] = {
  title = "I frammenti perduti",
  desc = "Lo Scroll of Myzrael... lo Scroll of Myzrael?! Non ti conviene! La sua magia può trascinare Myzrael nel mondo di superficie, e se lo fai, siamo nei guai!$B$BOppure... forse è troppo tardi. Forse è già libera. Forse sta solo raccogliendo le forze prima di scatenarsi su di noi. Se è così, allora ti SERVIRÀ la pergamena!$B$B...peccato che sia distrutta. Degli elementali infuriati l'hanno rubata e fatta a pezzi, e ora si contendono i frammenti.$B$BMa se riesci a raccogliere quei frammenti, forse possiamo aggiustarla...",
  obj = "Porta il Torn Scroll Fragment, il Crumpled Scroll Fragment e il Singed Scroll Fragment a Theldurin the Lost.",
  progress = "Hai trovato quei frammenti?! Ti servirà lo Scroll of Myzrael se vuoi intrappolarla di nuovo, prima che sia troppo tardi!",
  reward = "Ah, li hai trovati! Ottimo lavoro, $N! Potrebbero essere l'unica possibilità che abbiamo contro la malvagità di Myzrael!$B$BLasciami solo trovare il mio cricchetto per rattoppi e vedere se riesco a riattaccare questi frammenti...",
  en_title = "The Lost Fragments",
  en_obj = "Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.",
}
T[693] = {
  title = "Bacchetta in pugno",
  desc = "Ehi, $N. Scusa se prima sono stato così sbrigativo... e no, non è una battuta sulla mia statura.$B$BHo scoperto dove è finito il primo oggetto di Trelane: ce l'ha Kor'gresh, a Boulderfist Hall. E da come scagliava raffiche di ghiaccio sui suoi simili per tenerli in riga, deve essere vicino a capire come usarne tutti i poteri.$B$BBoulderfist Hall è a sud di qui, e poi a est del Thandol Span. Trova l'ogre e riprendi quella bacchetta.$B$BMentre sei via, penserò a cosa fare con Stromgarde.",
  obj = "Trova Trelane's Wand of Invocation e riportala a Skuerto, a Refuge Pointe.",
  progress = "Il nostro obiettivo è la bacchetta, $N. Per ora pensa solo a quella.",
  reward = "Magnifico, $N. Un oggetto recuperato, e secondo la mia lista ne mancano altri tre. Gli altri tre oggetti sono tutti a Stromgarde.$B$BRiposati e recupera le forze: la prossima fase del mio piano richiederà un po' più di tempo e di impegno. Torna da me dopo aver mangiato un pasto caldo e aver riposato un po'.",
  en_title = "Wand over Fist",
  en_obj = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.",
}
T[694] = {
  title = "Le difese di Trelane",
  desc = "Ti sei $Griposato:riposata;?$B$BEcco il prossimo passo: ci sono ogre tutto intorno alla Tower of Arathor, a Stromgarde. Dovremo attivare le difese della torre, se vuoi avere una possibilità contro di loro e arrivare $Gvivo:viva; fino agli oggetti. Per farlo ci servono delle gemme a cui i Boulderfist Shaman si sono affezionati. Le hanno prese dalla torre, ma non resteranno a lungo in mano loro.$B$BProcurati una di quelle gemme e portala a Kryten: conosce l'incantesimo che la farà funzionare come una chiave.",
  obj = "Trova un'Azure Agate e portala ad Apprentice Kryten, a Refuge Pointe.",
  progress = "$N, eccoti di nuovo. Hai già trovato un'Azure Agate?",
  reward = "Mi stupisci, $N. Ancora un ottimo lavoro.$B$BDammi un momento per lanciare sulla gemma l'incantesimo adatto, e sarai $Gpronto:pronta;.",
  en_title = "Trelane's Defenses",
  en_obj = "Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.",
}
T[695] = {
  title = "L'incantesimo dell'apprendista",
  desc = "Ecco a te, $N. Per attivare le difese della torre basta premere la gemma contro uno dei piedistalli vicino alla sua base. Usala quando sarai $Gpronto:pronta; a entrare nella torre per trovare gli oggetti rimasti di Trelane.$B$BBuona fortuna. Aspetterò il tuo ritorno qui all'accampamento. Ah, e parla con Skuerto prima di partire. Ti darà il resto dei dettagli che ti servono.",
  obj = "Parla con Skuerto.",
  reward = "Bene, bene.$B$BSe non ci sono altri ritardi, che ne dici di cominciare?",
  en_title = "An Apprentice's Enchantment",
  en_obj = "Speak to Skuerto.",
}
T[696] = {
  title = "Attacco alla torre",
  desc = "Ecco cosa cerchi: Trelane's Phylactery, Trelane's Orb e Trelane's Ember Agate.$B$BTutti e tre dovrebbero trovarsi in alcuni forzieri dentro la torre, e non dovresti avere problemi ad aprirli da $Gsolo:sola;; devi solo fare attenzione agli ogre.$B$BLe difese della torre non basteranno a sistemarli: dovrai tenere le armi pronte. Se quegli ogre scoprono che sei lì a derubarli, te la faranno pagare cara.$B$BSta' $Gattento:attenta;, e buona fortuna.",
  obj = "Trova Trelane's Phylactery, Trelane's Orb e Trelane's Ember Agate, e riportali a Skuerto, a Refuge Pointe.",
  progress = "Fai questo, e sono sicuro che Malin sarà più che soddisfatto di te.",
  reward = "Malin non avrebbe potuto chiedere a una persona più degna di venire qui ad aiutarci, $N. Hai fatto un lavoro magnifico!$B$BSarà contento di vedere che successo travolgente è stata la nostra missione.",
  en_title = "Attack on the Tower",
  en_obj = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.",
}
T[697] = {
  title = "La richiesta di Malin",
  desc = "Porta questa lettera a Stormwind e fai sapere a Malin che Kryten e io torneremo presto a casa. Ti ricompenserà bene per averci aiutato qui, $N, non ne ho alcun dubbio.$B$BFa' buon viaggio.",
  obj = "Porta la Sealed Letter ad Archmage Malin, nel Mage Quarter di Stormwind.",
  progress = "Sì? Hai un'aria vagamente familiare. Chiedo scusa, ma ci siamo già conosciuti? Sono così impegnato che perdo il filo.",
  reward = "<Archmage Malin apre la lettera e sgrana gli occhi.>$B$BPer la Luce, ce l'hai fatta. Meraviglioso. Trelane sarà contentissimo. Sono sicuro che Kryten e Skuerto siano entusiasti quanto me di vederli in viaggio verso Stormwind.$B$BGrazie, $N. Ti prego, prendi questo: ti aiuterà nei tuoi viaggi.",
  en_title = "Malin's Request",
  en_obj = "Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.",
}
T[698] = {
  title = "Scorte insufficienti",
  desc = "Sto cercando di mettere insieme un po' di provviste per il nostro avamposto vicino alla spiaggia, a est. Tok'Kar fa quel che può, ma tra i turni di guardia e il cucinare per i suoi soldati non gli resta molto tempo durante il giorno.$B$BA loro piace cucinare un po' di carne di sawtooth quando possono, ma non ho avuto tempo di mandargli un altro carico. Ti spiacerebbe dargli una mano?$B$BI sawtooth giovani non sono saporiti come quelli più vecchi, quindi lasciali stare; dagli un anno o due per crescere del tutto.",
  obj = "Porta 8 Unprepared Sawtooth Flank a Tok'Kar, nella Swamp of Sorrows.",
  progress = "Lok'tar, $C. Attraversare le paludi non è un rischio da prendere alla leggera. Hai coraggio a metterti alla prova qui.",
  reward = "Ah! Magnifico. Carne fresca per il fuoco di stasera. Grazie, $N.$B$BHai reso le prossime notti più sopportabili. Il fuoco arde luminoso, e avremo la pancia piena.$B$BÈ una piacevole sorpresa che sia tu a portarci un carico; Dar non è l'orco più attraente su cui qualcuno abbia mai posato gli occhi, ma almeno il suo carattere puzza molto meno del suo odore.",
  en_title = "Lack of Surplus",
  en_obj = "Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.",
}
T[699] = {
  title = "Scorte insufficienti",
  desc = "Con la minaccia dei murloc lungo la costa, siamo di stanza qui per proteggere Stonard da ogni minaccia in arrivo, o per dare l'allarme se le forze sono troppo grandi. Non ci lascia molto tempo per rilassarci, e un altro po' di aiuto ci farebbe comodo, se puoi.$B$BLe chele dei Sawtooth Snapper, se preparate a dovere, diventano ottime armi. Portami un po' delle loro chele, e farò in modo che tu venga $Gricompensato:ricompensata; con una delle nostre armi, per ringraziarti della carne fresca e della buona compagnia.",
  obj = "Porta 6 Sawtooth Snapper Claw a Tok'Kar, nella Swamp of Sorrows.",
  progress = "Buon idromele, un fuoco caldo, un esercito di orchi e un arsenale di armi... è tutto quello che ci serve davvero qui sulla costa. Non mi pento del mio posto qui a proteggere Stonard, ma sarebbe bello se un giorno potessimo avere una tana, o almeno una torre.",
  reward = "Mi fa piacere vederti $Gvivo:viva; e in salute, $N.$B$BQueste chele andranno benissimo. Più armi abbiamo pronte contro gli attacchi, meglio sarà per noi.$B$BMi metterò al lavoro sulla tua arma il prima possibile. Ci vorrà poco. Sono diventato piuttosto abile e veloce nel fabbricarle.",
  en_title = "Lack of Surplus",
  en_obj = "Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows.",
}
T[700] = {
  title = "Il tributo di un re",
  desc = "Ah, che bella pietra viene da Lordaeron. Che peccato che quella terra sia così allo sfascio.$B$BMa il Memoriale è venuto proprio bene! Credo che il Re ne sarà molto soddisfatto.$B$BOra, se ti va, manda parola a Sua Maestà che il Memoriale è finito come richiesto.",
  obj = "Fa' rapporto a King Magni Bronzebeard.",
  reward = "Il granito sembra ben poca cosa in confronto alla vita di un grande nano. Ma nessun nano durerà in eterno su questo pianeta.$B$BSperiamo soltanto che il memoriale resti a ricordare a chi calcherà la grande Azeroth del futuro che è per loro che soldati coraggiosi come Sully Balloo hanno dato la vita con tanto valore.",
  en_title = "A King's Tribute",
  en_obj = "Report to King Magni Bronzebeard.",
}
T[701] = {
  title = "L'astuzia del raptor",
  desc = "Con qualche altro oggetto potrò creare qualcosa che infonderà in Gor'mul l'astuzia del raptor! Con il potere del raptor che gli scorre dentro, Gor'mul conoscerà il nostro nuovo potere e riscoprirà il guerriero che dorme in lui!$B$BMi servono dei Raptor Heart per creare l'oggetto e l'incantesimo.",
  obj = "Procura 12 Raptor Heart dagli Highland Fleshstalker per Tor'gan.",
  progress = "I miei preparativi sono pronti: mi mancano solo i Raptor Heart.",
  reward = "Sì, questi andranno benissimo. Trasferirò il loro potere e lo spirito dei raptor in questo globo. Il globo infonderà in Gor'mul la forza ardente e l'intelligenza del raptor.",
  en_title = "Guile of the Raptor",
  en_obj = "Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.",
}
T[702] = {
  title = "L'astuzia del raptor",
  desc = "Prendi questo globo e usa la sua energia per dare a Gor'mul l'essenza del raptor. Di sicuro gli rinvigorirà lo spirito e darà un nuovo scopo alla sua vita. Quando sarà tornato quello di prima, potremo spiegargli come sta oggi l'Orda, e avremo l'aiuto di un grande guerriero nelle nostre battaglie senza fine.",
  obj = "Dai Tor'gan's Orb a Gor'mul.",
  progress = "Sei $Gtornato:tornata; di nuovo, eh? In effetti, ora non potrei desiderare niente di meglio che altra pietà da parte di Tor'gan.$B$BCosa mi porti stavolta? Un pezzo di spago dai colori vivaci, forse? O un pezzo di corda per porre fine a questa mia miseria...",
  reward = "Almeno stavolta mi porti qualcosa di interessante. Emana uno strano potere...",
  en_title = "Guile of the Raptor",
  en_obj = "Give Tor'gan's Orb to Gor'mul.",
}
T[703] = {
  title = "Barbecued Buzzard Wings",
  desc = "Oh sì, le mie Barbecued Buzzard Wing sono le preferite di tutti! La salsa è ricca e la carne è saporita. E il profumo farà accorrere gli affamati da miglia di distanza!$B$BHo tutto quello che mi serve per prepararne una porzione. Tutto... tranne le Buzzard Wing!$B$BSe ne vuoi un po', procurami le Buzzard Wing. Portamene abbastanza e magari ti darò anche la ricetta!",
  obj = "Porta 4 Buzzard Wing a Rigglefuzz.",
  progress = "Salve, $N. Mi hai portato le mie ali?",
  reward = "Ah, mi metto subito al lavoro su quelle ali. Quasi quasi ne sento già il sapore!$B$BEd ecco la ricetta, nel caso volessi prepararle da te!",
  en_title = "Barbecued Buzzard Wings",
  en_obj = "Bring 4 Buzzard Wings to Rigglefuzz.",
}
T[704] = {
  title = "La sorte di Agmond",
  desc = "L'ultimo rapporto che ho ricevuto da Agmond è preoccupante, e ancora di più ora che è morto! Diceva che i suoi scavatori avevano portato alla luce delle \"urne antiche\" nel sito di scavo fuori Uldaman. Temo che le urne trovate in quel sito abbiano aizzato i trogg, proprio come gli idoli che ho trovato qui.$B$BMi servono quelle urne per i nostri studi. Va' al sito di Uldaman, raccogli le urne, poi torna da me.",
  obj = "Porta 4 Carved Stone Urn a Prospector Ironband, a Loch Modan.",
  progress = "Hai trovato quelle urne, $N? Dobbiamo scoprire il legame tra loro e i trogg!",
  reward = "Ben fatto! Con fortuna e diligenza scopriremo qualunque legame ci sia tra i trogg e questi antichi manufatti.$B$BHai compiuto una grande impresa per i cercatori, $N. I tuoi sforzi non saranno dimenticati. E nemmeno Agmond.",
  en_title = "Agmond's Fate",
  en_obj = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.",
}
T[705] = {
  title = "A caccia di perle",
  desc = "I Badlands sono un posto duro, pieno di predatori feroci e di necrofagi sfrontati. Fa paura, soprattutto a un goblin piccolo e basso come me. Per sopravvivere devo essere furbo!$B$BConosco la ricetta delle Flash Bomb. Le uso per spaventare gli animali. Ma sto finendo uno degli ingredienti: la polvere di perle blu frantumate. Procuramene un po' e ti ripagherò della fatica.$B$BEh, e spero che tu abbia un buon paio di stivali. Le Blue Pearl che mi servono si trovano nei molluschi del Vile Reef.$B$BGià, il Vile Reef, a Stranglethorn!",
  obj = "Porta 9 Blue Pearl a Rigglefuzz, nei Badlands.",
  progress = "Hai preso le mie perle? Sono quasi a corto di Flash Bomb!",
  reward = "Andranno benissimo! Devo solo ridurle in polvere... poi mescolarle con un po' di questo e un po' di quello.$B$BAttenti, necrofagi! Preparatevi a restare accecati!",
  en_title = "Pearl Diving",
  en_obj = "Bring 9 Blue Pearls to Rigglefuzz in the Badlands.",
}
T[706] = {
  title = "Incantamenti di fuoco ardente",
  desc = "Come apprendista di Feranor Steeltoe, ho imparato la sua tecnica speciale per infondere nelle armi incantamenti di fuoco. L'ultima volta che ho avuto sue notizie, lavorava in una fucina con una compagnia di cacciatori, su a Lordaeron.$B$BNon posso dirti troppi dettagli sul procedimento, ma posso dirti che richiede il sangue del cuore ancora pulsante di un raro cucciolo di drago nero. Non ho molto da fare mentre aspetto notizie da Ironforge. Se mi porti un cuore dei cuccioli della Lethlor Ravine, ti mostrerò la mia abilità!",
  obj = "Procura un Black Drake's Heart per Sigrun Ironhew.",
  progress = "Come va la caccia, $C?",
  reward = "Ah sì, questo andrà benissimo. Permetterà alle tue armi di colpire con un calore rovente!",
  en_title = "Fiery Blaze Enchantments",
  en_obj = "Acquire a Black Drake's Heart for Sigrun Ironhew.",
}
T[707] = {
  title = "Ironband ha bisogno di te!",
  desc = "$N. Ho ricevuto rapporti da Prospector Ironband, dal suo sito di scavo a Loch Modan: gli serve qualcuno che si muova per un altro dei nostri scavi.$B$BNon ho altri dettagli, ma se hai voglia di sgranchirti le gambe va' a parlare con Ironband.",
  obj = "Parla con Prospector Ironband, all'Ironband's Excavation Site di Loch Modan.",
  reward = "Quindi ti manda Stormpike, eh? Bene.$B$BHo un bel compito per te...",
  en_title = "Ironband Wants You!",
  en_obj = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.",
}
T[708] = {
  title = "La scatola nera",
  desc = "La superficie di questa scatola nera di metallo è tutta butterata, come se fosse stata immersa nell'acido: deve essere rimasta a lungo nello stomaco del condor gigante.$B$BRigirando la scatola, trovi un simbolo impresso sul fondo. Sotto il simbolo ci sono le parole:$B$B\"Engine #19 — Ironforge Siege Brigade\"",
  obj = "Porta la Corroded Black Box all'Hall of Arms, a Ironforge.",
  en_title = "The Black Box",
  en_obj = "Take the Corroded Black Box to the Hall of Arms in Ironforge.",
}
T[709] = {
  title = "Rimedio alla sventura",
  desc = "Povero me! Povero me! Si avvicina una sventura. Ascoltami bene! Una sventura!$B$BNo, non posso parlarne... non posso pronunciare i loro nomi, o potrebbero sentirmi! Ma se scopriamo, sì, se scopriamo di più su di loro... allora forse possiamo capire come sventare i loro piani!$B$BForse.$B$BVa' a Uldaman. No! L'ho detto! Devi trovare... trovare la tavoletta di... Ryun'eh. Sì, trovala! E non farmi pronunciare di nuovo quel nome!$B$BÈ nel profondo di quel luogo, in un antico forziere. È lì che si nasconde... in un forziere costruito prima di qualunque opera dei nani.",
  obj = "Porta la Tablet of Ryun'eh a Theldurin the Lost.",
  progress = "Hai trovato la tavoletta? Deve contenere dei segreti! Segreti per salvarci!",
  reward = "Oh, la fortuna è con noi! Grazie! Forse possiamo ancora salvarci!",
  en_title = "Solution to Doom",
  en_obj = "Bring the Tablet of Ryun'eh to Theldurin the Lost.",
}
T[710] = {
  title = "Studio degli elementi: la roccia",
  desc = "Qui nelle Badlands mi sono fermato a lavorare al mio ultimo progetto: i miei ceppi di vincolo elementale.$B$BUna volta completati, permetteranno ai maghi di evocare elementali ancora più potenti, da usare per compiti ancora più grandi. Per cominciare, mi servono dei Small Stone Shard per provare alcuni dei miei nuovi incantesimi offensivi, insieme a qualche aggeggio che ho messo insieme.$B$BI frammenti si raccolgono facilmente dai Lesser Rock Elemental, a ovest di qui. Potresti portarmene un po'?",
  obj = "Trova 10 Small Stone Shard e portali a Lotwil Veriatus, nelle Badlands.",
  progress = "Questa zona è perfetta per — Potresti tenermi fermi questi per un momento? Sì, proprio così, lungo la normale del vettore. Allora, cosa stavo... Ah, sì. Perfetta per provare il mio ultimo progetto. Le materie prime, lo spazio aperto... cosa potrebbe chiedere di più un praticante delle arti intelligente e illuminato?",
  reward = "Andranno benissimo, $N. Grazie. Mmh, un po' più di sabbia di quanto mi aspettassi. Dovrò correggere il coefficiente di attrito. No, aspetta; con il Frost Oil dovrebbe restare comunque trascurabile.$B$B<Borbottando tra sé, Lotwil mette un pugno nel palmo dell'altra mano e li fissa come affascinato.>",
  en_title = "Study of the Elements: Rock",
  en_obj = "Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.",
}
T[711] = {
  title = "Studio degli elementi: la roccia",
  desc = "$N, ti sei già $Gdimostrato:dimostrata; più capace di tutti i miei apprendisti messi insieme.$B$BI prossimi pezzi che mi servono richiedono un po' più di forza. Se stai $Gattento:attenta;, puoi trovare dei Large Stone Slab sui Rock Elemental. Il loro corpo è più forte e più grande, e quindi è più facile che abbia pezzi abbastanza grandi per le mie prove. Li trovi più a ovest di qui, o a sud-est, lungo i margini delle montagne.$B$BFa' con calma; mi ci vorrà un po' per provare questi pezzi più piccoli che mi hai portato.",
  obj = "Porta 3 Large Stone Slab a Lotwil Veriatus, nelle Badlands.",
  progress = "Sono molto soddisfatto, $N. I miei incantesimi hanno agito sui pezzi più piccoli esattamente come avevo previsto. Se questo esperimento riuscirà come prevedo, gli elementali che potrò controllare faranno sfigurare qualunque cosa sia mai stata evocata prima.",
  reward = "$N, semplicemente incredibile! Avrei pensato che ci volesse mezza dozzina di tauren per portarmi tutta questa roba.",
  en_title = "Study of the Elements: Rock",
  en_obj = "Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands.",
}
T[712] = {
  title = "Studio degli elementi: la roccia",
  desc = "$N, mi serve un'ultima parte dagli elementali qui nelle Badlands: i Bracers of Rock Binding dei Greater Rock Elemental. Secondo i miei calcoli, quei bracciali dovrebbero bastare a misurare la forza dei miei ceppi.$B$BI miei tentativi di scrutare i Greater Rock Elemental ne hanno mostrato un gruppo a sud-ovest di qui, vicino ad alcuni ogre, se ricordo bene.$B$BPortamene 5, giusto per averne di scorta. Servo è famoso per smarrire i miei reagenti e le mie ricerche.",
  obj = "Porta 5 Bracers of Rock Binding a Lotwil Veriatus, nelle Badlands.",
  progress = "Le lastre di pietra che hai trovato erano perfette, $N. Lucien riporterà quelle in più a Kharanos quando avremo finito qui. Dopotutto, potrebbero tornare utili.$B$BPer esempio, sarebbero un'ottima base per un comodo rifugio, quando comincerò a studiare un approccio multidisciplinare agli esplosivi ad alto potenziale...$B$B<La voce di Lotwil si spegne mentre torna al suo esperimento.>",
  reward = "$N, hai mai pensato di diventare assistente di ricerca? No? Non so proprio cosa farò qui senza le tue capacità. Intelligenza, curiosità e forza: tutto in un unico pacchetto.",
  en_title = "Study of the Elements: Rock",
  en_obj = "Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.",
}
T[713] = {
  title = "Vince chi resta freddo",
  desc = "Lascia che ti dica una cosa sul Frost Oil: niente impedisce a un motore o a degli ingranaggi di surriscaldarsi come lui.$B$BLe sue proprietà refrigeranti sono straordinarie, e come lubrificante dura come nessun altro. E non è tutto: aiuta anche a mantenere gli incantamenti sugli oggetti magici.$B$BMe ne serve una fiala per aumentare la capacità magica dei miei ceppi e renderli abbastanza potenti da impedire al nostro amico evocato di ucciderci tutti.$B$BBro'kin, un mio amico goblin, può insegnarti a prepararlo. Si trova ad Alterac.",
  obj = "Trova del Frost Oil e portalo a Lotwil Veriatus, nelle Badlands.",
  progress = "Hai trovato l'olio che mi serve? Mi sarebbe davvero utile se riuscissi a trovarne un po'.",
  reward = "Stupendo! Dovrebbe essere il refrigerante perfetto per i miei nuovi bracciali. Se gli incantamenti non dureranno un secolo, darò tutti i miei averi a Servo.$B$BTutti i maghi dell'Assembly resteranno a bocca aperta quando avrò finito, $N. Aspetta e vedrai.",
  en_title = "Coolant Heads Prevail",
  en_obj = "Find Frost Oil and bring it to Lotwil Veriatus in Badlands.",
}
T[714] = {
  title = "Giro... cosa?",
  desc = "$N, hai fatto il tuo lavoro ben oltre ogni aspettativa.$B$B<Lotwil è chiaramente distratto dal suo lavoro.>$B$BSe mai ci incontreremo a Kharanos, vieni pure a chiedere lavoro.$B$BOps! Presto, prendi il... sì, quello. Grazie.$B$BOra mi serve solo un'altra cosa. È un pezzo piccolo, ma piuttosto cruciale, temo: un Gyrochronatom.$B$BSe potessi andarne a prendere uno e portarmelo, dovrei essere pronto a completare il lavoro.",
  obj = "Porta un Gyrochronatom a Lotwil Veriatus, nelle Badlands.",
  progress = "Sì, sì, sì. Solo un momento.$B$B<Lotwil continua a lavorare a una specie di congegno.>",
  reward = "AH!$B$B<Lotwil ti strappa di mano il Gyrochronatom.>$B$BPerfetto... ho quasi finito. No, davvero. ORA ho quasi finito. Questo progetto è la mia massima priorità... al momento. Lascia che lo metta al suo posto, e potrai vedere con i tuoi occhi cosa mi hai aiutato a creare. Mi ci vorrà solo qualche altro minuto... forse... magari di più. Be', forse molto di più. Vedremo...",
  en_title = "Gyro... What?",
  en_obj = "Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.",
}
T[715] = {
  title = "Pietra liquida",
  desc = "Credo che gli oggetti che hai procurato per Lotwil saranno l'ultimo dei nostri problemi, $N. D'altra parte, ti sei $Gdimostrato:dimostrata; più che abile nelle scienze che Lotwil considera sacre, quindi che ne dici di darmi una mano?$B$BMi servono una pozione d'invisibilità e una Healing Potion; potrebbero tornare utili molto presto, se lui ci riesce.$B$BIn cambio ti darò questa ricetta per una pozione che ho messo a punto mentre imparavo da Lotwil. È basata su alcune delle ricerche che sta facendo qui nelle Badlands.",
  obj = "Porta una Healing Potion e una Lesser Invisibility Potion a Lucien Tosselwrench, nelle Badlands.",
  progress = "Sta per finire. Come vanno le cose dalla tua parte?",
  reward = "SÌ!$B$BCioè, grazie, $N. Queste saranno utili per viaggiare attraverso le Badlands.",
  en_title = "Liquid Stone",
  en_obj = "Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.",
}
T[716] = {
  title = "La pietra è meglio della stoffa",
  desc = "So quanto può essere tirchio Lotwil, $N, quindi lascia che ti prepari qualcosa per tutto il disturbo. Magari ti aiuterà perfino a proteggerti dall'imminente atrocità che è l'ultima invenzione di Lotwil.$B$BHo lavorato con tutte le pietre in più che hai raccolto per lui, e posso farti dei bei bracciali che potrebbero servirti. Incantati, naturalmente.$B$BMi servono solo dei Patterned Bronze Bracers fatti da un fabbro, così posso completare i bracciali che sto preparando per te.",
  obj = "Porta dei Patterned Bronze Bracers a Lucien Tosselwrench, nelle Badlands.",
  progress = "Non aspetterei troppo a procurarti quel bracciale, $N.$B$BChi sa cosa succederà adesso?",
  reward = "Ecco qua, $N. Provali.",
  en_title = "Stone Is Better than Cloth",
  en_obj = "Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands.",
}
T[717] = {
  title = "Tremori della terra",
  desc = "Ormai è evidente che non possiamo garantire che Blacklash e Hematus restino imprigionati a Lethlor. Il fatto che dei draghi neri si siano stabiliti lì, e che gli ogre siano riusciti a rubare il Sign, indica che bisognerà prendere misure più drastiche.$B$BLa prigione dei draghi è mantenuta da tre pietre runiche che si possono recuperare solo usando il Sign of the Earth. Quelle pietre runiche possono poi servire a spezzare il sigillo che li tiene prigionieri.$B$B$N... fa' che i loro sogni siano eterni.",
  obj = "Usa il Sign of the Earth per attivare il Pillar of Amethyst, il Pillar of Opal e il Pillar of Diamond e ottenere l'Amethyst Runestone, l'Opal Runestone e la Diamond Runestone.$B$BMetti le pietre runiche nel Seal of the Earth per liberare Blacklash e Hematus.$B$BUccidili e riporta Blacklash's Bindings, le Chains of Hematus e il Sign of the Earth a Garek.",
  progress = "Magie e poteri forti hanno tenuto la prigione dei draghi per tanto tempo, ma non possiamo permettere che ci sia alcuna possibilità che Blacklash e Hematus vengano liberati.",
  reward = "Il Kirin Tor non dovrà più preoccuparsi dei prigionieri di Lethlor. Tornerò a riferire il successo al mio maestro. Krasus sarà senza dubbio soddisfatto.",
  en_title = "Tremors of the Earth",
  en_obj = "Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.$B$BPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.$B$BSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.",
}
T[718] = {
  title = "Miraggi",
  desc = "Nella fretta di lasciare il sito di scavo di Uldaman, siamo stati costretti ad abbandonare molti carri e casse di provviste lungo la strada. Gli ogre del Camp Kosh si sono gettati sulla nostra attrezzatura abbandonata come avvoltoi su una carcassa in putrefazione. E non hanno nemmeno un odore migliore. Delle carcasse, intendo.$B$BComunque, hanno preso il carro che trasportava tutte le nostre armi e roba simile... quindi... be', è un po' imbarazzante... non siamo riusciti a procurarci da mangiare.$B$BSiamo un po' nei guai, qui: pensi di poterci aiutare?",
  obj = "Recupera la Supply Crate per Sigrun Ironhew.",
  progress = "Il deserto è un brutto posto dove avere fame, $Gamico mio:amica mia;, te lo dico io.$B$BEhi... cos'è quello laggiù...",
  reward = "Grazie mille, $N. Mentre eri via, io... ehm... ho mandato giù una boccata di sabbia. Era...$B$BBe', basta così: stasera usciamo a procurarci del cibo. Mangeremo come re!",
  en_title = "Mirages",
  en_obj = "Retrieve the Supply Crate for Sigrun Ironhew.",
}
T[719] = {
  title = "Un nano e i suoi attrezzi",
  desc = "Ehi, $N. Sta' $Gattento:attenta; da queste parti. Ci sono nani Dark Iron dappertutto: sembravano del clan Shadowforge.$B$BHanno appena attaccato il sito di scavo dove lavoravo e hanno ucciso quasi tutti, compreso il mio capo, Hammertoe. Ho salvato la pelle per un pelo.$B$BIl sito è appena a nord di qui, e sto cercando un modo per riprenderci un po' delle nostre provviste, soprattutto il mio piccone portafortuna.$B$BTe la senti di darmi una mano? Uno di quei maledetti Dark Iron deve avere il mio piccone! Potrebbe essere uno qualunque di loro.",
  obj = "Trova Ryedol's Lucky Pick e riportalo a Prospector Ryedol, a sud dell'Hammertoe's Dig Site.",
  progress = "Non so cosa cercassero gli Shadowforge, ma di sicuro avevano uno scopo.",
  reward = "Sei $Gil mio salvatore:la mia salvatrice;, $C. Sono contento che qualcuno abbia dato una lezione o due a quegli Shadowforge. Grazie per l'aiuto.",
  en_title = "A Dwarf and His Tools",
  en_obj = "Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site.",
}
T[720] = {
  title = "Un segno di speranza",
  desc = "<Sulla mappa c'è un testo scarabocchiato col gesso.>$B$B\"Ryedol,$Bmi stanno portando a Uldaman. Manda aiuto.$B— Hammertoe\"",
  obj = "Trova Prospector Ryedol e digli che Hammertoe Grez è vivo.",
  reward = "Hammertoe è vivo?! È incredibile, $N!",
  en_title = "A Sign of Hope",
  en_obj = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.",
}
T[721] = {
  title = "Un segno di speranza",
  desc = "$N, riesci a trovarlo? Riesci a trovare Hammertoe a Uldaman?$B$BSe quei luridi Shadowforge lo tengono in ostaggio per scoprire cosa sa degli scavi dei titani, allora tutta Ironforge potrebbe essere in guai grossi.$B$BÈ da tanto tempo che quei Dark Iron cercano magie per costruire golem più potenti. Anche Hammertoe faceva lo stesso, certo, ma solo per fermarli.$B$BProbabilmente lo tengono in vita finché non scoprono quello che sa. Devi sbrigarti, se vuoi salvarlo!",
  obj = "Trova Hammertoe Grez a Uldaman.",
  reward = "Sì? Mi dispiace... <coff> Mi sento così debole. Puoi avvicinarti, $C?$B$BTi manda Ryedol? Sia lodato Muradin, quel ragazzo non è lento di comprendonio come pensavo una volta. <coff>",
  en_title = "A Sign of Hope",
  en_obj = "Find Hammertoe Grez in Uldaman.",
}
T[722] = {
  title = "L'amuleto dei segreti",
  desc = "Hai coraggio... <coff>... a venire a Uldaman per me, $C.$B$BSe sei davvero qui per aiutare... il vecchio Hammertoe, allora... <coff>... devi trovare... il mio amuleto.$B$BCe l'ha Deepshadow... Magregan Deepshadow. È da queste parti... di sicuro tra le rovine. Quell'amuleto li porterà... <coff>... dritti alle pergamene, se nessuno lo ferma. Tocca a te, $N. Ti prego... prendi quell'amuleto.$B$BLe pergamene aiuteranno di sicuro i Dark Iron a creare golem ancora più potenti. Lo so e basta. Me lo sento nelle ossa.",
  obj = "Trova Hammertoe's Amulet e riportalo a Hammertoe, a Uldaman.",
  progress = "Il clan Shadowforge... <coff> è pericoloso. Sta' $Gattento:attenta;. <coff> Devi trovare l'amuleto.",
  reward = "Ah! <coff coff>$B$BLo sapevo che avresti trovato il mio amuleto, $N.$B$B<ansima> Ben fatto davvero, $N. <coff>",
  en_title = "Amulet of Secrets",
  en_obj = "Find Hammertoe's Amulet and return it to him in Uldaman.",
}
T[723] = {
  title = "Un cercatore di fede",
  desc = "<Hammertoe si tiene le ferite e si prende un momento per ricomporsi prima di parlare di nuovo.>$B$BTrova Ryedol, $N. Portagli il mio amuleto. <coff coff> Lui... <coff> saprà cosa fare. Sa che cercavo le origini del nostro popolo, e lui... <coff>... sa che la mia missione era anche fermare il clan Shadowforge. Non devono trovare le pergamene... <coff>",
  obj = "Porta Hammertoe's Amulet a Prospector Ryedol, nelle Badlands.",
  progress = "Direi che è stata una brutta giornata, ma queste sono le Badlands: ogni giorno è una brutta giornata.",
  reward = "Hammertoe's Amulet? Credo che il mio morale fosse più alto quando lo credevo morto. Saperlo con certezza rende il dolore solo più forte. Questo amuleto era l'opera di tutta la sua vita. Non posso lasciare che sia morto invano.",
  en_title = "Prospect of Faith",
  en_obj = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.",
}
T[724] = {
  title = "Un cercatore di fede",
  desc = "Va bene, va bene... chi potrebbe sapere cosa fare?$B$BHistorian Karnik! Ecco!$B$BÈ a Ironforge. Lui potrà aiutarci. Lui e Hammertoe lavoravano insieme per trovare i manufatti perduti di Uldaman.$B$BSembra che gli Shadowforge abbiano scoperto che quei due ne sapevano più di quanto lasciassero intendere.$B$BRacconta a Karnik cos'è successo a Hammertoe e dagli l'amuleto: ti dirà lui cosa bisogna fare dopo.",
  obj = "Porta Hammertoe's Amulet a Historian Karnik, a Ironforge.",
  progress = "Ah, sì. $GUn altro viaggiatore:Un'altra viaggiatrice; che cerca qualcosa dai nani.$B$B$GSignore:Signora;, sono davvero spiacente, ma adesso non ho tempo di rispondere a domande inutili.",
  reward = "Oh! Be', questa è tutta un'altra faccenda. Probabilmente non ti rendi ancora conto della gravità della cosa, vero?$B$BLa morte di Hammertoe mi addolora profondamente, ma se ti ha mandato qui con il suo amuleto, allora aveva capito cosa c'è in gioco.$B$BPiangeremo la sua morte più tardi.$B$BLascia che ti mostri uno dei motivi per cui questo amuleto è così prezioso.",
  en_title = "Prospect of Faith",
  en_obj = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.",
}
T[725] = {
  title = "Avvisare di una minaccia",
  desc = "$N, corri a cercare Advisor Belgrum il più in fretta possibile. Digli quello che hai visto e chiedigli come vuole che procediamo. Questo biglietto gli spiegherà il resto.$B$BNel frattempo, mi prenderò il tempo di parlare con lo spirito di Hammertoe. Forse sa qualcosa che ci aiuterà a fermare le attività di quei cretini degli Shadowforge nelle Badlands. Possiamo solo pregare.",
  obj = "Trova Advisor Belgrum e consegnagli il suo biglietto.",
  progress = "Mm? Sì, $C.",
  reward = "Ah, notizie da Historian Karnik. Eccellente.$B$BPer le sue faccende ho sempre tempo.$B$B<Advisor Belgrum apre il biglietto e comincia a leggere.>",
  en_title = "Passing Word of a Threat",
  en_obj = "Find Advisor Belgrum and give him his note.",
}
T[726] = {
  title = "Avvisare di una minaccia",
  desc = "<Advisor Belgrum arriva in fondo al biglietto, e per un attimo spalanca gli occhi.>$B$BOhi, queste sono notizie funeste.$B$B$N, ti prego, torna da Historian Karnik e digli che, per autorità del re, deve agire su queste informazioni in modo rapido e deciso. Deve fermare le attività degli Shadowforge nelle Badlands.",
  obj = "Parla con Historian Karnik.",
  reward = "Stai trattando questa faccenda con un'urgenza che mi aspetterei dal re in persona, $N.$B$BD'accordo, allora. So io cosa metterà in ginocchio gli Shadowforge.$B$BLa loro presenza a Uldaman si può rallentare se li colpiamo nella loro base operativa: Angor Fortress.",
  en_title = "Passing Word of a Threat",
  en_obj = "Speak to Historian Karnik.",
}
T[727] = {
  title = "A Ironforge per Yagyin's Digest",
  desc = "La tavoletta dice molto. Ma non abbastanza! Nemmeno lontanamente abbastanza!$B$BC'è un libro, un compendio che Yagyin scrisse in tempi antichi. Le... persone da cui sono fuggito... custodiscono questo libro in molti luoghi. E i più dotti tra loro lo studiano. Contiene un sapere immenso. Un sapere che può proteggerci!$B$BVa' da Gerrig Bonegrip. Ha una bottega a Ironforge, nella Forlorn Cavern. Mostragli questo sigillo e ti crederà $Guno:una; di loro. Chiedigli Yagyin's Digest... e portalo a me!",
  obj = "Dai il Sigil of the Hammer a Gerrig Bonegrip, nella Forlorn Cavern, a Ironforge.",
  progress = "Salve. $GBenvenuto:Benvenuta; nella mia bottega, ma fa' attenzione a quello che tocchi.$B$BIl sapere può essere letale.",
  reward = "Oh. Salve, $Gfratello:sorella;.$B$BE lode a coloro che dimorano nel profondo.",
  en_title = "To Ironforge for Yagyin's Digest",
  en_obj = "Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.",
}
T[728] = {
  title = "All'Undercity per Yagyin's Digest",
  desc = "La tavoletta dice molto. Ma non abbastanza! Nemmeno lontanamente abbastanza!$B$BC'è un libro, un compendio che Yagyin scrisse in tempi antichi. Le... persone da cui sono fuggito... custodiscono questo libro in molti luoghi. E i più dotti tra loro lo studiano. Contiene un sapere immenso. Un sapere che può proteggerci!$B$BVa' da Keeper Bel'dugur, nell'Undercity di Lordaeron. Mostragli questo sigillo e ti crederà $Guno:una; di loro. Chiedigli Yagyin's Digest... e portalo a me!",
  obj = "Porta il Sigil of the Hammer a Keeper Bel'dugur, nell'Undercity.",
  progress = "Ah, vedo che abbiamo $Gun:una; $C zelante. Sei qui per imparare dalla mia collezione? Bene!$B$BMa attenzione: come il sapere dà potere ai forti... così fa impazzire i deboli.",
  reward = "Sii $Gdiscreto:discreta; con i tuoi segni, $C. C'è chi non crede nella giustezza del nostro giuramento.$B$BE c'è chi vorrebbe vederci fallire, se sapesse di noi.$B$BDobbiamo sempre essere prudenti. E vigili. E pazienti.",
  en_title = "To the Undercity for Yagyin's Digest",
  en_obj = "Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.",
}
T[729] = {
  title = "Il Prospector distratto",
  desc = "Che onore fu quando Master Greywhisker mi assegnò al servizio del grande Prospector Remtravel. All'accademia di Ironforge tutti conoscevano le grandi scoperte di Remtravel.$B$BMa il prospector è piuttosto... ehm... ignaro... di ciò che lo circonda.$B$BAvevamo scoperto le prove di una grande civiltà. Orribili golem sono sbucati dal terreno e hanno invaso il sito. Remtravel sembrava non accorgersene. Io sono corsa ad Auberdine a chiedere aiuto.$B$BTi prego, vai a sud e controlla se il prospector sta bene!",
  obj = "Vai a sud e controlla come sta Prospector Remtravel.",
  reward = "Hollee... sei tu? Ho bisogno di aiuto per scalpellare questa pietra. Passami la spazzola per la pietra, mi pare di vedere qualcosa.$B$BEhi, non sei Hollee! Non avrai mica visto la mia spazzola per la pietra?$B$BNon importa ora! Ho promesso alla Lega che avrei mandato il misterioso fossile che ho trovato. Dov'è andata Hollee?$B$BC'è così tanto lavoro da fare! Ora, dov'è quel misterioso fossile... e la mia spazzola... e Hollee...$B$BE tu chi sei... non importa, purché tu sia qui ad aiutarmi.$B$BDimmi quando sei pront$Go:a; a iniziare la ricerca.",
  en_title = "The Absent Minded Prospector",
  en_obj = "Travel south and check on Prospector Remtravel.",
}
T[730] = {
  title = "Guai a Darkshore?",
  desc = "Che piacere vedere un $c interessato alle grandi meraviglie archeologiche del nostro mondo.$B$BSpesso il nostro lavoro è liquidato come un semplice hobby dai nostri amici dell'Alleanza. Ma molti non si rendono conto che le recenti scoperte a Khaz Modan hanno dimostrato che una forza grande e potente minaccia tutta Azeroth, da Lordaeron a Kalimdor.$B$BSono molto preoccupato per la mia squadra che ho mandato a Darkshore. Non mandano notizie da settimane.$B$BVai ad Auberdine e cerca un indizio su dove si trovino.",
  obj = "Recati ad Auberdine e cerca tracce della squadra di scavo dei nani.",
  reward = "Sono così felice che Chief Archeologist Greywhisker ci abbia mandato a chiamare... ",
  en_title = "Trouble In Darkshore?",
  en_obj = "Travel to Auberdine and look for signs of the dwarven excavation team.",
}
T[731] = {
  title = "Il Prospector distratto",
  desc = "Dunque, Hollee... ah già, tu non sei Hollee. Dov'è Hollee?$B$BBah, non è questo il punto. Dobbiamo trovare quella spazzola per la pietra... cioè il misterioso fossile! Dobbiamo trovare quel fossile. L'Explorers' League a Darnassus vorrà qualche prova di ciò che ho fatto.$B$BDimmi quando sei pront$Go:a; e daremo la caccia a quella spazzola... cioè al fossile! Troveremo qualcosa di scritto per accontentare la Lega.$B$BAllora, sei già pront$Go:a;?",
  obj = "Proteggi Prospector Remtravel mentre cerca il misterioso fossile, poi torna da Archaeologist Hollee ad Auberdine.",
  progress = "Il prospector è vivo?",
  reward = "Grazie alle stelle, Prospector Remtravel è salvo! Te l'avevo detto che è distratto. Non posso credere che abbia insistito a restare laggiù con tutte quelle orribili creature in agguato.",
  en_title = "The Absent Minded Prospector",
  en_obj = "Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine.",
}
T[732] = {
  title = "Tremori della terra",
  desc = "Sigrun mi ha detto che gli sei $Gstato:stata; di grande aiuto. Forse potrei chiedere il tuo aiuto anch'io. Mi ha mandato qui il mio maestro, Krasus del Kirin Tor, per porre fine ai guai che si stanno preparando nella Lethlor Ravine.$B$BNon posso rivelare la natura esatta del mio incarico qui, né i compiti che devo svolgere, ma stai $Gcerto:certa; che è di vitale importanza.$B$BUna banda di ogre nomadi, che a volte si vedono vicino al Camp Boff, ha rubato un oggetto chiamato Sign of the Earth; devo averlo. Portamelo, e ti dirò di più.",
  obj = "Recupera il Sign of the Earth per Garek.",
  progress = "La banda nomade di ogre si sposta tra i suoi accampamenti in tutte le Badlands; il calore che sale dalla terra arida e i venti vorticosi renderanno difficile seguirne le tracce. Ho sentito che a volte passano per il Camp Boff. Se ti sei $Gperso:persa;, potresti cercare lì.",
  reward = "Con il Sign mi porti buone notizie, $N. Il Sign of the Earth fu creato dai nani Dark Iron di Angor Fortress per imprigionare due degli spietati luogotenenti di Deathwing, i gemelli Blacklash e Hematus.",
  en_title = "Tremors of the Earth",
  en_obj = "Retrieve the Sign of the Earth for Garek.",
}
T[733] = {
  title = "Arrangiarsi",
  desc = "Qui sarà dura andare avanti, se non riesco a racimolare un po' di materiali per costruire delle difese e altre cose necessarie. Ho notato che gli ogre della zona sembrano ben forniti di Scrap Metal. Forse le storie sulle macchine d'assedio nelle Badlands non erano poi così lontane dal vero...$B$BComunque, il cercatore si sta preoccupando per lo stato del nostro piccolo accampamento, quindi vorrei mettermi al lavoro presto, se posso.$B$BL'accampamento principale degli ogre è alla Dustbelch Grotto, un bel tratto di cammino a ovest di qui.",
  obj = "Procura 7 pezzi di Scrap Metal per Sigrun.",
  progress = "Be', ho fatto quel che potevo con quello che avevo, ma... non è molto. Hai trovato altre provviste?",
  reward = "È un inizio, $N, e dovrà bastare finché non avremo notizie da Ironforge o dalla Lega degli Esploratori.$B$BOra, se solo trovassi un po' di sale da qualche parte per la mia tinozza da tempra...",
  en_title = "Scrounging",
  en_obj = "Get 7 pieces of Scrap Metal for Sigrun.",
}
T[734] = {
  title = "Sarà dura",
  desc = "Meraviglioso, meraviglioso.$B$B<Lotwil alza lo sguardo su di te per un momento, prima di tornare ai suoi ceppi.>$B$BVa' a parlare con Lucien, $N. Mi serve un Cog #5. Me lo porti, vero?",
  obj = "Parla con Lucien Tosselwrench, nelle Badlands.",
  reward = "Un Cog #5, eh? Già, questo non promette niente di buono.",
  en_title = "This Is Going to Be Hard",
  en_obj = "Speak to Lucien Tosselwrench in the Badlands.",
}
T[735] = {
  title = "La stella, la mano e il cuore",
  desc = "Yagyin's Digest, eh? Stai fondando un nuovo capitolo del nostro ordine, da qualche parte? Lascia stare, non sta a me chiederlo.$B$BTi aiuterò, perché ne ho una copia in più. Dobbiamo aiutarci a vicenda, no? È così che prosperiamo.$B$BMi servono tre oggetti di potere. Portameli e ti darò il compendio.$B$BNon pronuncerò i loro nomi. Potrebbero esserci orecchie in ascolto. Ma ecco, te li scrivo.",
  obj = "Porta gli oggetti elencati nella Bonegrip's Note a Gerrig Bonegrip, a Ironforge.",
  progress = "Hai le reliquie che ti ho chiesto?",
  reward = "Sei $Gpieno:piena; di risorse, $C. Se il tuo compito è davvero fondare un nuovo capitolo del nostro ordine, credo che lo guiderai bene.",
  en_title = "The Star, the Hand and the Heart",
  en_obj = "Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.",
}
T[736] = {
  title = "La stella, la mano e il cuore",
  desc = "Ti serve lo Yagyin's Digest? Il tuo piano, quindi, è radunare un altro gregge? Ma certo... e certo che ti aiuterò, $Gfratello:sorella;.$B$BMa anche tu devi aiutare me.$B$BMi servono tre oggetti di potere. Portameli e il compendio sarà tuo.$B$BNon posso pronunciare i nomi di questi oggetti, ma li scriverò.$B$BProcurami gli oggetti di questa lista. Se ci riesci, allora sei davvero $Gdegno:degna; di aprire un tuo capitolo del nostro ordine.",
  obj = "Porta gli oggetti elencati nella Bel'dugur's Note a Keeper Bel'dugur, nell'Undercity.",
  progress = "Come procede la tua missione, $C?",
  reward = "Mi hai davvero colpito! Hai grande abilità, o grande fortuna, per aver ottenuto queste reliquie. In ogni caso, sei una risorsa preziosa per noi.",
  en_title = "The Star, the Hand and the Heart",
  en_obj = "Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.",
}
T[737] = {
  title = "Il sapere proibito",
  desc = "Ho il compendio per te, $N. Non c'è bisogno che ti dica di averne gran cura. E di tenerlo lontano da mani ostili.$B$BQuesto libro racchiude molte verità...$B$B...E la verità può bruciare.",
  obj = "Porta Yagyin's Digest a Theldurin.",
  progress = "Oh! Sei $Gstato:stata; via a lungo. Hai preso il compendio?",
  reward = "Ce l'hai! Oh, la speranza riluce!$B$BI tuoi sforzi potrebbero ancora salvarci, $N. Dovrebbero farti un monumento! Dovrebbero costruirti un santuario! Che il tuo nome sia lodato finché i tuoi nipoti non avranno nipoti!$B$BA meno che... LORO non vengano liberati e risalgano in superficie. Se succede, puoi scordarti i figli.$B$BSe LORO vengono liberati, siamo tutti cibo per i vermi.",
  en_title = "Forbidden Knowledge",
  en_obj = "Bring Yagyin's Digest to Theldurin.",
}
T[738] = {
  title = "Trova Agmond",
  desc = "Prospector Agmond dirigeva i nostri siti di scavo nei Badlands, a sud-ovest. Dico \"dirigeva\" perché... be', non ho sue notizie da settimane. Ho bisogno che tu trovi Agmond, così potrò avere il suo rapporto.$B$BL'ultima volta che ne ho avuto notizie, Agmond era al sito di scavo più a sud dei Badlands: un piccolo cantiere oltre l'Angor Fortress. Io comincerei a cercarlo da lì.",
  obj = "Trova Agmond.",
  reward = "Questo scheletro dev'essere ciò che resta dello sfortunato Agmond. Il suo corpo è spezzato e malridotto, e le sue ossa sono state spolpate.",
  en_title = "Find Agmond",
  en_obj = "Find Agmond.",
}
T[739] = {
  title = "Murdaloc",
  desc = "Le tracce di Agmond arrivano da ovest. Dalle strisciate di sangue sulla roccia e sulla sabbia si capisce facilmente che il nano si è trascinato per un bel tratto.$B$BE qui è morto.$B$BOsservando da vicino, si vede la parola \"Murdaloc\" scarabocchiata alla meglio su un tratto di arenaria dei Badlands.$B$BScarabocchiata accanto alla mano morta di Agmond.",
  obj = "Uccidi l'assassino di Agmond, Murdaloc.$B$BUccidi 12 Stonevault Bonesnapper.$B$BFai rapporto a Prospector Ironband, a Loch Modan.",
  progress = "Hai notizie sulla sorte di Agmond? L'hai trovato?",
  reward = "È una notizia amara, $N. Ma Agmond aveva un braccio forte e un colpo di martello feroce, e una testa dura come poche! Anche se è stato ucciso da quei maledetti trogg, sono sicuro che ne ha trascinati parecchi con sé.",
  en_title = "Murdaloc",
  en_obj = "Slay Agmond's killer, Murdaloc.$B$BSlay 12 Stonevault Bonesnappers.$B$BReport to Prospector Ironband in Loch Modan.",
}
T[741] = {
  title = "Il Prospector distratto",
  desc = "Quindi il prospector vuole mandare il misterioso fossile all'Explorers' League a Darnassus? Non mi sento a mio agio a lasciare Darkshore senza di lui.$B$BTieni, $N, consegna il misterioso fossile a Chief Archaeologist Greywhisker a Darnassus.",
  obj = "Porta il misterioso fossile a Chief Archaeologist Greywhisker a Darnassus.",
  progress = "Cosa posso fare per te, $R?",
  reward = "Santo cielo! Lascia fare a Prospector Remtravel, che scopre un ritrovamento simile!",
  en_title = "The Absent Minded Prospector",
  en_obj = "Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.",
}
T[742] = {
  title = "La caccia di Ashenvale",
  desc = "Attenzione, giovani avventurieri! Le terre selvagge di Ashenvale vi aspettano!$B$BL'Orda ha stabilito una forte presenza nelle terre a nord dei Barrens. I nostri due avamposti, Splintertree Post e Zoram Strand Outpost, si impegnano a portare gloria all'Orda! Chi vuole mettersi alla prova dovrebbe cercare lì una guida. In particolare: Senani Thunderheart, a Splintertree Post, appena a nord dei Barrens, cerca avventurieri disposti a partecipare a una grande caccia di Ashenvale!",
  obj = "Parla con Senani Thunderheart a Splintertree Post, Ashenvale.",
  reward = "Benvenut$Go:a; sulla nuova frontiera, $N. Ashenvale è una terra di opportunità, dove un giovane $C come te può trovare infinite occasioni per dimostrare il proprio valore. Dai un'occhiata all'avamposto qui intorno e assicurati di recarti anche a Zoram Strand, perché l'Orda ha un altro avamposto laggiù.$B$BLa tua presenza qui mi dice che sei venut$Go:a; per saperne di più sulla caccia. Ascolta con attenzione e ti dirò volentieri ciò che ti serve sapere.",
  en_title = "The Ashenvale Hunt",
  en_obj = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.",
}
T[743] = {
  title = "I pericoli dei Windfury",
  desc = "Grazie per aver trovato il tempo di parlarmi, $N. Sono Ruul, guerriero e maestro.$B$BHai evidentemente raggiunto un'età in cui devi prepararti alle tue prove, se vuoi avventurarti oltre Mulgore.$B$BSe desideri mettere alla prova la tua forza, comincia cercando le arpie Windfury a sud-est. Si annidano lungo i bordi della montagna, lontano dalla strada.$B$BSono uno dei nostri nemici naturali qui a Mulgore e saranno un buon metro della tua abilità.",
  obj = "Porta 8 Windfury Talons a Ruul Eagletalon a Bloodhoof Village.",
  progress = "Le Windfury sono nemici mortali. La loro forza in battaglia è eguagliata solo dal loro desiderio di carne fresca.",
  reward = "Hai fatto bene, $N. Sembri ben preparat$Go:a; a proseguire il viaggio. Che il vento ti soffi sempre alle spalle.",
  en_title = "Dangers of the Windfury",
  en_obj = "Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village.",
}
T[744] = {
  title = "Preparativi per la cerimonia",
  desc = "$N, mio fratello sta per presentarsi davanti a Chief Bloodhoof, ed è un onore per me realizzare il suo copricapo.$B$BVorrei chiederti un favore mentre finisco di conciare queste strisce di cuoio. Non ho il tempo di trovare abbastanza piume, e mi chiedevo se potresti raccoglierne altre per me.$B$BPuoi trovare piume della misura giusta presso le arpie che vivono lontano a nord e a nordovest di Thunder Bluff. Me ne servono solo 6 azzurre e 6 bronzee per completare il disegno.",
  obj = "Raccogli 6 Azure Feathers e 6 Bronze Feathers e portale a Eyahn Eagletalon a Thunder Bluff.",
  progress = "Questo copricapo sarà certamente un magnifico regalo per mio fratello.",
  reward = "Grazie per il tuo aiuto, $N.$B$BLa mia parte nella cerimonia di mio fratello è quasi completa. Consegnargli il copricapo e assistere alla cerimonia sono tutto ciò che il mio dovere richiede.",
  en_title = "Preparation for Ceremony",
  en_obj = "Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff.",
}
T[745] = {
  title = "Condividere la terra",
  desc = "$N, molti conflitti feriscono questa terra. Spero che tu non debba assistere a tanti di essi quanti ne ho visti io. Eppure ce n'è uno che ti chiedo di andare a vedere. Ti darà un'idea di quanto terribile possa essere, se lasciata incontrollata, anche una piccola minaccia per la terra.$B$BI gnoll Palemane si sono stabiliti a sud di Bloodhoof e in una caverna a ovest. Disprezzano i nostri tentativi di comunicare con loro e uccidono senza freni la fauna di Mulgore.$B$BLe parole non sono più la risposta.",
  obj = "Uccidi 10 Palemane Tanners, 8 Palemane Skinners e 5 Palemane Poachers, poi torna da Baine Bloodhoof a Bloodhoof Village.",
  progress = "Se i Palemane avessero rispettato di più la terra e i suoi abitanti, questo conflitto non sarebbe mai nato.",
  reward = "$N, è bene che tu abbia preso sul serio il mio incarico. Il rispetto per la terra e le sue creature è importante. Morte e vita sono un cerchio... una necessità. L'una non può esistere senza l'altra. Prenditi il tempo di rifletterci e non dimenticarlo mai.",
  en_title = "Sharing the Land",
  en_obj = "Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Baine Bloodhoof in Bloodhoof Village.",
}
T[746] = {
  title = "Scavi dei nani",
  desc = "Alcuni nani stanno preparando un sito di scavo a nord-ovest. Pensano che la terra nasconda dei segreti, ed è vero, ma svuotarla e profanarla non è il modo di meritare i suoi insegnamenti.$B$BRaccogli gli attrezzi da scavo dei nani, distruggili e torna da me con gli attrezzi rotti.$B$BPuoi distruggere gli attrezzi presso una forgia. Ne troverai una a Thunder Bluff, ma qualsiasi forgia -- anche quella dell'accampamento dei nani -- andrà bene.",
  obj = "Raccogli 5 Prospector's Picks.$B$BPresso una forgia, distruggi i Prospector's Picks per ottenere dei Broken Tools.$B$BPorta 5 Broken Tools a Baine Bloodhoof a Bloodhoof Village.",
  progress = "Salve, $N. Hai i Broken Tools? Gli scavi dei nani faranno infuriare i kodo di Mulgore. Questa profanazione deve essere fermata!",
  reward = "Grazie, $N. Questo calmerà le bestie di Mulgore. E, se gli spiriti vorranno, insegnerà ai nani che svuotare la terra non è la via della conoscenza.",
  en_title = "Dwarven Digging",
  en_obj = "Collect 5 Prospector's Picks.$B$BAt a forge, smash the Prospector's Picks to create Broken Tools.$B$BBring 5 Broken Tools to Baine Bloodhoof in Bloodhoof Village.",
}
T[747] = {
  title = "La caccia ha inizio",
  desc = "Hai un'aria promettente e ti dimostrerai degno della tribù. Forse un giorno non lontano sarai accolt$Go:a; nella grande città di Thunder Bluff. Ma prima dovrai metterti alla prova davanti a mio padre, Chief Hawkwind.$B$BQui su Red Cloud Mesa andiamo fieri della nostra abilità nella caccia. I Tauren cacciano per necessità e per sport. Le nostre scorte di carne sono scarse e ci servono piume per i vestiti. Dai la caccia ai plainstrider qui vicino e dimostra il tuo valore rifornendo il villaggio.",
  obj = "Grull Hawkwind a Camp Narache vuole che tu gli porti 7 Plainstrider Feathers e 7 pezzi di Plainstrider Meat.",
  progress = "Procurare carne e piume per la tribù è il primo passo per dimostrare il tuo valore come $C davanti al Chief.",
  reward = "I Tauren di Narache ti ringraziano, $N. Mostri grandi promesse.",
  en_title = "The Hunt Begins",
  en_obj = "Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat.",
}
T[748] = {
  title = "Acqua avvelenata",
  desc = "I goblin e i loro servi hanno contaminato i nostri sacri pozzi d'acqua! Non possiamo permetterlo.$B$BPer purificare ogni pozzo devo creare un totem purificatore, poi tu dovrai portare il totem al pozzo ed eseguire un rito di purificazione.$B$BPer prima cosa creeremo il totem purificatore per il Winterhoof Water Well. Per farlo, la terra deve offrirci il suo aiuto. Dai la caccia ai lupi della prateria per le loro zampe e ai plainstrider adulti per i loro artigli. Li troverai a sud-ovest.$B$BTorna da me con le zampe e gli artigli, $N.",
  obj = "Porta 6 Prairie Wolf Paws e 4 Plainstrider Talons a Mull Thunderhorn a Bloodhoof.",
  progress = "Hai le zampe e gli artigli, $N?",
  reward = "Hai fatto bene, $N. Prenderò questi oggetti e ne legherò il potere in un totem di purificazione.",
  en_title = "Poison Water",
  en_obj = "Bring 6 Prairie Wolf Paws and 4 Plainstrider Talons to Mull Thunderhorn in Bloodhoof.",
}
T[749] = {
  title = "La carovana devastata",
  desc = "Qualche giorno fa abbiamo trovato una carovana della Venture Co. in viaggio sotto scorta sulla riva settentrionale dello Stonebull Lake. Avevamo perso due dei nostri in uno scontro precedente, perciò non abbiamo esitato ad attaccare e a radere al suolo la carovana.$B$BAbbiamo lasciato le loro casse di rifornimenti, pensando che le nostre torce avrebbero distrutto qualunque cosa di valore, ma visto che dei recuperatori della Venture Co. sono stati avvistati vicino ai carri bruciati, forse ci sbagliavamo.$B$BForse potresti recarti alla carovana ed esaminare il contenuto delle casse.",
  obj = "Morin Cloudstalker vuole che tu esamini il contenuto di una cassa di rifornimenti presso la Ravaged Caravan.",
  reward = "Tutti i lati della cassa recano il marchio della Venture Co. Mining Division. Gli appunti scritti con cura sul fianco della scatola indicano che il contenuto deve essere lavorato in uno dei loro impianti centrali.",
  en_title = "The Ravaged Caravan",
  en_obj = "Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan.",
}
T[750] = {
  title = "La caccia continua",
  desc = "Un tauren esperto nell'arte della caccia sa che la sua preda non è un semplice trofeo. Le bestie delle pianure ci offrono un mezzo di sopravvivenza. Farai una grande impressione sugli anziani se riuscirai a riportare alcune preziose Mountain Cougar Pelts. Troverai le bestie in agguato sulle colline a sud.$B$BI nostri figli hanno bisogno di vestiti e le nostre tende vanno rammendate.",
  obj = "Grull Hawkwind a Camp Narache vuole che tu gli porti 10 Mountain Cougar Pelts.",
  progress = "Se riuscirai a procurare le pelli per la tribù, riferirò a mio padre, Chief Hawkwind, della tua generosità.",
  reward = "I Tauren di Narache ti ringraziano per questi rifornimenti, $N. Con la tua abilità nell'arte della caccia, un giorno sarai di certo venerat$Go:a; a Thunder Bluff.",
  en_title = "The Hunt Continues",
  en_obj = "Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts.",
}
T[751] = {
  title = "La carovana devastata",
  desc = "Sollevando il coperchio scopri un assortimento di minerali e metalli grezzi, strettamente stipati: un'ulteriore prova dell'attività mineraria della Venture Co. a Mulgore. In cima ai minerali trovi un fascio di carte legate con cura.$B$BSulle colline a est senti appena i rumori del lavoro e vedi levarsi il fumo di un grande fuoco.",
  obj = "Riporta i Venture Co. Documents a Morin Cloudstalker vicino a Bloodhoof Village.",
  progress = "Salute, $N. Hai scoperto qualcosa di nuovo sui piani e sulle operazioni della Venture Co. nella nostra terra?$B$BSe intendono sfruttare le nostre terre come hanno fatto con le altre, gli Outrunner non tarderanno a fermarli.",
  reward = "Sembra davvero che la Venture Co. stia cercando di derubarci delle nostre risorse naturali. È bene saperlo con certezza e ora, a quanto pare, dobbiamo fare qualcosa.",
  en_title = "The Ravaged Caravan",
  en_obj = "Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village.",
}
T[752] = {
  title = "Un compito umile",
  desc = "Tutti i membri della tribù condividono l'armonia della vita. Viviamo insieme e lavoriamo insieme.$B$BIl nostro impegno reciproco comporta un alto grado di responsabilità. Ora ti chiedo un compito umile.$B$BQuesta mattina mia madre è partita per prendere l'acqua al pozzo a sud-est di Narache. È passato parecchio tempo ormai. Forse potresti controllare come sta, mentre io mi occupo qui degli affari della tribù?",
  obj = "Chief Hawkwind vuole che tu cerchi sua madre vicino al pozzo a sud-est di Camp Narache.",
  reward = "Hai fatto tutta questa strada solo per aiutare una vecchia? Santo cielo, sei proprio un tesoro!",
  en_title = "A Humble Task",
  en_obj = "Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.",
}
T[753] = {
  title = "Un compito umile",
  desc = "Ho percorso molte strade nella vita e queste vecchie gambe non hanno più il vigore di un tempo. Posso ancora svolgere i miei doveri verso la tribù. A volte a una vecchia serve solo un po' più di tempo.$B$BMa tu sembri $Gun:una; $c volenteros$Go:a;. Mettiamo alla prova un po' di quella vitalità giovanile. Prendi una brocca d'acqua dal pozzo e portala a mio figlio, il Chief, a Camp Narache.$B$BRicorda che anche il compito più umile può attirare il riconoscimento degli anziani.",
  obj = "Prendi una Water Pitcher dal pozzo.$B$BPorta la brocca a Chief Hawkwind a Camp Narache, a nord-ovest del pozzo.",
  progress = "Sembra che tu sia appena tornat$Go:a; dalle pianure. Hai notizie dalla Greatmother Hawkwind?",
  reward = "Vedo che hai riportato questa brocca per volere della Greatmother.$B$BLa tua disponibilità ad aiutare gli altri e a provvedere ai tauren di Camp Narache mi fa credere che un giorno renderai orgogliosa la tribù a Thunder Bluff.",
  en_title = "A Humble Task",
  en_obj = "Take a Water Pitcher from the water well.$B$BReturn the pitcher to Chief Hawkwind in Camp Narache which is northwest from the water well.",
}
T[754] = {
  title = "Purificazione di Winterhoof",
  desc = "Ho forgiato il totem per purificare il Winterhoof Water Well. Ora devi portarlo al pozzo ed eseguire un rito di purificazione. Lo troverai a sud-est, sorvegliato da immondi goblin!$B$BNon sarà un compito facile, ma devi portarlo a termine se vogliamo usare ancora le sue acque.$B$BBuona fortuna, $N.",
  obj = "Usa il Winterhoof Cleansing Totem presso il Winterhoof Water Well, poi torna da Mull Thunderhorn.",
  progress = "Non indugiare, $N. La contaminazione del Winterhoof Well deve essere rimossa!",
  reward = "La notizia della tua impresa mi è giunta pochi istanti fa: già le bestie vicino al pozzo vi bevono con gioia.$B$BHai compiuto una grande opera per la terra, $N. E per il popolo dei Tauren.",
  en_title = "Winterhoof Cleansing",
  en_obj = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well, then return to Mull Thunderhorn.",
}
T[755] = {
  title = "I Riti della Madre Terra",
  desc = "La tua disponibilità a svolgere un compito umile per i tauren di Narache e la tua voglia di imparare sono qualità nobili, $n. Credo che un giorno sarai acclamat$Go:a; a Thunder Bluff come $c di grande valore.$B$BPrima di allora devi intraprendere i Riti della Madre Terra, che sono tre.$B$BLa prima prova è il Rito della Forza. Recati da Seer Graytongue e digli che ti manda Chief Hawkwind.$B$BTroverai la dimora del veggente subito a sud di Camp Narache, nascosta tra le colline.",
  obj = "Recati da Seer Graytongue, che vive sulle colline a sud di Camp Narache.",
  reward = "Ti manda Chief Hawkwind? Intraprendere i Riti della Madre Terra non è impresa da poco...",
  en_title = "Rites of the Earthmother",
  en_obj = "Travel to Seer Graytongue who lives in the hills directly south of Camp Narache.",
}
T[756] = {
  title = "Totem di Thunderhorn",
  desc = "Per creare il Thunderhorn Cleansing Totem devi raccogliere gli artigli dei predatori delle pianure di Mulgore. Dai la caccia ai prairie stalker per i loro Stalker Claws e ai flatland cougar per i loro Cougar Claws, poi torna da me.$B$BTroverai i prairie stalker e i flatland cougar a est e a ovest.",
  obj = "Porta 6 Stalker Claws e 6 Cougar Claws a Mull Thunderhorn.",
  progress = "$N, hai gli artigli che ti ho mandato a raccogliere? Il Thunderhorn Water Well si contamina sempre di più a ogni ora che passa!",
  reward = "Grazie, $N. La purezza con cui queste bestie cacciano è essenziale per creare il prossimo totem di purificazione.$B$BI goblin non impareranno mai la differenza tra lottare contro la terra e vivere in armonia con essa.",
  en_title = "Thunderhorn Totem",
  en_obj = "Bring 6 Stalker Claws and 6 Cougar Claws to Mull Thunderhorn.",
}
T[757] = {
  title = "Rito della Forza",
  desc = "I Riti della Madre Terra sono i passi che un giovane tauren deve compiere per guadagnarsi il rispetto di Thunder Bluff.$B$BPer prima cosa devi superare il Rito della Forza. In questa prova devi dimostrare il tuo coraggio uccidendo i nemici della tribù.$B$BI Bristleback di Brambleblade Ravine, a est, stanno invadendo le nostre terre. Tendono imboscate alle nostre squadre di caccia e di notte rubano al villaggio.$B$BDimostra il tuo valore uccidendo questi furfanti e torna dal Chief a Camp Narache con le loro cinture come prova delle tue gesta.",
  obj = "Uccidi i Bristleback a Brambleblade Ravine e porta 12 Bristleback Belts a Chief Hawkwind a Camp Narache.",
  progress = "Hai completato il Rito della Forza, $N? Esigo la prova del tuo valore contro il nemico della nostra tribù, i Bristleback.",
  reward = "Hai superato la prima prova dei Riti della Madre Terra. La tribù sarà orgogliosa.",
  en_title = "Rite of Strength",
  en_obj = "Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache.",
}
T[758] = {
  title = "Purificazione di Thunderhorn",
  desc = "Il totem è pronto, $N. E ancora una volta spetta a te eseguire il rito di purificazione.$B$BVai al Thunderhorn Water Well, a nord del villaggio, e usa il Thunderhorn Cleansing Totem durante il rito. Fatto questo, torna da me.$B$BChe gli spiriti ti guidino.",
  obj = "Usa il Thunderhorn Cleansing Totem presso il Thunderhorn Water Well, poi torna da Mull.",
  progress = "Il Thunderhorn Water Well è ancora contaminato, $N. Ti prego, devi eseguire il rito!",
  reward = "Gli antenati del clan Thunderhorn mi hanno parlato in sogno, lodando le tue azioni presso il loro pozzo.$B$BIn segno di gratitudine, desiderano donarti questo...",
  en_title = "Thunderhorn Cleansing",
  en_obj = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull.",
}
T[759] = {
  title = "Totem di Wildmane",
  desc = "Resta un solo pozzo da purificare, quello che porta il nome del clan Wildmane. Perché sia puro, la terra deve offrire i denti di un feroce predatore, il prairie wolf alpha. Trova gli alpha a nord e torna da me quando la tua caccia sarà finita.$B$BGli alpha spesso si aggirano alla base della nostra possente città, Thunder Bluff.",
  obj = "Porta 8 Prairie Alpha Teeth a Mull Thunderhorn a Bloodhoof Village.",
  progress = "$N. Hai i denti che ti ho chiesto?",
  reward = "Molto bene, $N. Sento il sacrificio della terra in questa offerta e il mio spirito si gonfia di tristezza e di orgoglio.",
  en_title = "Wildmane Totem",
  en_obj = "Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village.",
}
T[760] = {
  title = "Purificazione di Wildmane",
  desc = "La purificazione dei pozzi di Winterhoof e Thunderhorn è sulla bocca degli spiriti, giovane $N. Il Wildmane Totem è pronto e ti attende l'ultimo compito.$B$BIl Wildmane Water Well si trova a nord di Thunder Bluff. Esegui il rito! Guarisci la terra dai veleni dei goblin! Che l'acqua pura torni a scorrere!",
  obj = "Usa il Wildmane Cleansing Totem presso il Wildmane Water Well, poi torna da Mull Thunderhorn.",
  progress = "L'ultimo pozzo è ancora fetido e velenoso, $N. Non devi indugiare!",
  reward = "Ce l'hai fatta. Hai purificato i pozzi e guarito la nostra terra. Il villaggio di Bloodhoof ti è grato, $N.$B$BChe il vento sussurri le tue gesta per cento stagioni e che le acque di Mulgore restino pure per sempre.",
  en_title = "Wildmane Cleansing",
  en_obj = "Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.",
}
T[761] = {
  title = "Caccia agli Swoop",
  desc = "Lo swoop è un uccello astuto, difficile da trovare e da cacciare. Una collezione di Swoop Quills è un emblema di astuzia e determinazione per un cacciatore.$B$BSe sei disposto a raccogliere questa sfida, addentrati nelle pianure e dai la caccia agli swoop.$B$BPortami le loro penne e rendi onore al tuo clan.$B$BGli swoop possono trovarsi ovunque a Mulgore, ma i tuoi occhi dovranno essere acuti per scorgerli e i tuoi zoccoli veloci per raggiungerli.",
  obj = "Porta 8 Trophy Swoop Quills a Harken Windtotem a Bloodhoof Village.",
  progress = "Hai trovato gli swoop, $N? Hai le loro penne?",
  reward = "So che raccogliere queste penne non è stata un'impresa facile, $N. Così facendo dimostri di essere un $C di valore. È un bene averti a Bloodhoof Village.",
  en_title = "Swoop Hunting",
  en_obj = "Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village.",
}
T[762] = {
  title = "Un ambasciatore del male",
  desc = "Ambassador Infernus è stato mandato ad Angor Fortress da Ragnaros in persona per sorvegliare gli Shadowforge che cercano i manufatti perduti a Uldaman.$B$BHa già causato perdite enormi al nostro popolo, ma è evidente che la situazione è peggiorata. Esito a immaginare quanti manufatti riuscirebbero a trovare e a usare contro Ironforge.$B$BIl nostro obiettivo è semplice, $C. Torna nelle Badlands e distruggi Ambassador Infernus. Una volta eliminata la minaccia, torna da Advisor Belgrum con una prova della tua vittoria.$B$BOra è nelle tue mani.",
  obj = "Uccidi Ambassador Infernus ad Angor Fortress e porta una prova della sua morte ad Advisor Belgrum, a Ironforge.",
  progress = "Il tempo stringe, $N. Ragnaros non aspetterà che siamo pronti.",
  reward = "$N, la tua dedizione a Ironforge e al popolo dei nani è indiscutibile. Ti ringrazio per il tuo aiuto in questa faccenda.$B$BManderò notizia a Historian Karnik per informarlo che ce l'hai fatta, e farò anche mandare aiuti nelle Badlands il prima possibile, per aiutare a recuperare il sito di scavo. Grazie ancora.$B$BPrima che tu vada, c'è un'altra cosa che vorrei chiederti in nome di King Bronzebeard.",
  en_title = "An Ambassador of Evil",
  en_obj = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.",
}
T[763] = {
  title = "I Riti della Madre Terra",
  desc = "Per proseguire con i Riti della Madre Terra devi superare altre due prove. È tempo di ampliare la tua esperienza, $n.$B$BRecati a Bloodhoof Village e cerca il Chief, Baine Bloodhoof, figlio di Cairne. Lì potrai continuare il tuo cammino e ottenere l'approvazione degli anziani di Thunder Bluff.$B$BPorta questo totem a Baine. Riconoscerà i miei intagli e ti aiuterà lungo la tua strada.$B$BSegui la strada fuori da Camp Narache e viaggia con premura. Non allontanarti dal sentiero o ti perderai.",
  obj = "Porta il Totem of Hawkwind a Baine Bloodhoof a Bloodhoof Village. Segui la strada fuori da Camp Narache.",
  progress = "Cosa ti porta nel mio villaggio, $C?",
  reward = "Notizie dal mio buon amico, Chief Hawkwind! Ah, dai suoi intagli vedo che sei di una stirpe speciale.",
  en_title = "Rites of the Earthmother",
  en_obj = "Take the Totem of Hawkwind to Baine Bloodhoof in Bloodhoof Village. Follow the road out of Camp Narache.",
}
T[764] = {
  title = "La Venture Co.",
  desc = "Ecco spiegato l'accumulo di dipendenti e attrezzature della Venture Co. che abbiamo visto nel Mulgore. Quei goblin... la loro compagnia si sta espandendo troppo in fretta per il loro bene. Si dice che basti mostrare qualcosa a un goblin per sentire le bilance tintinnare in sottofondo.$B$BSono creaturine avide, ecco cosa sono. Purtroppo per i loro affari, noi tauren non possiamo permettere che portino avanti le loro attività sulle nostre terre. Vai alla loro miniera a nordest della carovana devastata e manda loro un messaggio.",
  obj = "Uccidi 14 Venture Co. Worker e 6 Venture Co. Supervisor per Morin Cloudstalker al Bloodhoof Village.",
  progress = "Alla Venture Co. sono stati negati i diritti di estrazione qui nel Mulgore, ma a quanto pare non accettano un no come risposta. Noi tauren, però, non siamo tipi da giri di parole, e abbiamo altri modi per far arrivare il nostro messaggio.",
  reward = "Non credo che quel segnale possa essere frainteso o ignorato, hm? La Venture Co. saprà di non dover prendere alla leggera i tauren, né di essere così arrogante da credere che lasceremo rubare le risorse naturali che ci circondano senza protestare.",
  en_title = "The Venture Co.",
  en_obj = "Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village.",
}
T[765] = {
  title = "Supervisor Fizsprocket",
  desc = "Secondo i documenti che hai recuperato dalla carovana, la Venture Co. ha ideato molti piani per cacciarci da queste terre, così da avere campo libero per saccheggiarle.$B$BLe bassezze a cui sono disposti a scendere per raggiungere i loro scopi mi disgustano e mi sconvolgono. Voglio morta la mente dietro i loro piani. Il suo nome è Supervisor Fizsprocket e lo troverai alla miniera della Venture Co. a est della carovana devastata. Portami il suo blocco per appunti: vedremo se ci rivela qualcosa di utile.",
  obj = "Uccidi Supervisor Fizsprocket e riporta il suo blocco per appunti a Morin Cloudstalker al Bloodhoof Village.",
  progress = "Ribollo di rabbia al pensiero delle atrocità che la Venture Co. è disposta a commettere contro di noi in nome del profitto.",
  reward = "La mia rabbia si placa un poco alla notizia che quel mascalzone di Fizsprocket è morto. Esaminerò i suoi effetti personali per vedere se contengono altre informazioni su ciò che la Venture Co. ha in serbo per il futuro. Grazie per il tuo impegno, $N.",
  en_title = "Supervisor Fizsprocket",
  en_obj = "Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village.",
}
T[766] = {
  title = "Mazzranache",
  desc = "Mio nonno mi raccontava delle sue battaglie contro un corridore chiamato Mazzranache. Mi parlava dei suoi occhi rossi e demoniaci, dei suoi artigli affilati come rasoi e del suo morso velenoso.$B$BVolle il caso che, viaggiando attraverso le pianure, lo incontrassi, e mi strappò un brutto morso dalla spalla. Era terribile proprio come lo descriveva mio nonno. Mi serviranno alcune parti di animali difficili da trovare per ripulire l'infezione del suo morso: un cuore di lupo, un femore di puma, una scaglia di plainstrider e un ventriglio di swoop.$B$BPresto, il tempo stringe.",
  obj = "Porta un Prairie Wolf Heart, un Flatland Cougar Femur, una Plainstrider Scale e uno Swoop Gizzard a Maur Raincaller al Bloodhoof Village.",
  progress = "La febbre peggiora e sento la mente scivolare in incubi deliranti... Avrei dovuto sapere che non sarei stato in grado di affrontare una bestia che mio nonno non riuscì a sconfiggere...$B$BHai gli ingredienti per il rimedio? Temo che se non ripulisco presto l'infezione, sarà la mia fine.",
  reward = "Ah, grazie, $N. Con gli oggetti che mi hai portato potrò preparare il rimedio che mi serve per fermare il diffondersi dell'infezione e, col tempo, guarirla del tutto. Ti devo la vita.$B$BMa non dimenticherò mai quel richiamo stridulo quando Mazzranache mi piombò addosso, il bagliore di colori mentre il suo becco scendeva...$B$BSta' in guardia nei tuoi viaggi.",
  en_title = "Mazzranache",
  en_obj = "Bring a Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale and Swoop Gizzard to Maur Raincaller at Bloodhoof Village.",
}
T[767] = {
  title = "Rito della Visione",
  desc = "Il Rito della Visione, uno dei Riti della Madre Terra, ti guiderà verso il rispetto degli anziani di Thunder Bluff.$B$BIl nostro popolo ha imparato che la terra è la nostra più sacra fonte di sostentamento. Per prendere parte alla visione rituale, devi parlare con la guida spirituale del villaggio, Zarlman Two-Moons.",
  obj = "Parla con Zarlman Two-Moons al Bloodhoof Village.",
  reward = "Sentivo che saresti venut$Go:a; da me, $c. So sempre riconoscere chi cerca di superare i Riti della Madre Terra.",
  en_title = "Rite of Vision",
  en_obj = "Speak with Zarlman Two-Moons in Bloodhoof Village.",
}
T[768] = {
  title = "Raccogliere cuoio",
  desc = "Salute, giovane. Hai una luce negli occhi; si vede che sei ansios$Go:a; di tornare sulle pianure per la caccia. Che tu possa portare onore al tuo clan!$B$BLavoro le pelli delle bestie, ricavandone abiti e armature per la gente di Thunder Bluff.$B$BSe cacci bestie e mi porti le loro pelli, ti confezionerò qualcosa.",
  obj = "Porta 12 Light Leather a Veren Tallstrider a Thunder Bluff.",
  progress = "Di nuovo qui. Hai cacciato? Hai delle pelli per me?",
  reward = "Ah, sono pezzi molto belli. Ne verranno ottimi oggetti di cuoio.$B$BEcco, $N. Prendi questo in cambio...",
  en_title = "Gathering Leather",
  en_obj = "Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff.",
}
T[769] = {
  title = "Borsa di pelle di kodo",
  desc = "I kodo di Mulgore sono forti e robusti, qualità molto rispettate tra noi. Se sei abile nella lavorazione del cuoio e desideri conoscere il modo di fabbricare una Kodo Hide Bag, portami le provviste per il mio mestiere.$B$BFallo, e condividerò con te il mio sapere.",
  obj = "Porta 4 Light Leather e 4 Coarse Thread a Veren Tallstrider a Thunder Bluff.",
  progress = "Hai le mie provviste, $N?",
  reward = "Ah, bene. Grazie, $N. Il mio cuore si gonfia d'orgoglio nel vedere dei giovani interessati all'arte della lavorazione del cuoio.",
  en_title = "Kodo Hide Bag",
  en_obj = "Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff.",
}
T[770] = {
  title = "Il mantello segnato dai demoni",
  desc = "Il pelo logoro di Ghost Howl porta ancora una terribile ferita, riportata nelle battaglie del lupo contro la Burning Legion.$B$BForse qualcuno al Bloodhoof Village dovrebbe sapere della fine di Ghost Howl....",
  obj = "Trova qualcuno che sappia di Ghost Howl.",
  reward = "Non riesco quasi a credere ai miei vecchi occhi! Hai sconfitto il grande lupo Ghost Howl? Ti guardo con nuovo rispetto, giovane $C. Sei un $C di straordinaria abilità!$B$BLascia che ti offra qualcosa. I miei giorni di caccia sono finiti, ma sarei onorato se usassi una delle mie armi nelle tue battute.$B$BPossa colpire dritto e portarti fama.$B$BE speriamo che lo spirito di Ghost Howl abbia finalmente trovato pace.",
  en_title = "The Demon Scarred Cloak",
  en_obj = "Find someone who knows of Ghost Howl.",
}
T[771] = {
  title = "Rito della Visione",
  desc = "Per superare il Rito della Visione devi raccogliere i reagenti necessari a preparare l'Acqua dei Veggenti.$B$BMi serviranno delle pietre di pozzo, che si trovano attorno ai pozzi d'acqua del Mulgore. Ad esse unirò dell'Ambercorn, che cade sotto i possenti alberi della nostra terra.$B$BQuesti reagenti contengono elementi magici e, una volta preparati e bevuti davanti al fuoco tribale, ti faranno incontrare una visione. Seguila, e ti condurrà al passo successivo di questa sacra missione.",
  obj = "Raccogli 2 Well Stone e 2 Ambercorn e riportali a Zarlman Two-Moons al Bloodhoof Village.",
  progress = "Quando avrai raccolto abbastanza pietre di pozzo attorno ai pozzi d'acqua e Ambercorn da sotto gli alberi, preparerò per te l'Acqua dei Veggenti.",
  reward = "Vedo che hai imparato a raccogliere dalla nostra terra sacra, $N. Mi ci vorrà solo un attimo per preparare l'Acqua dei Veggenti.",
  en_title = "Rite of Vision",
  en_obj = "Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village.",
}
T[772] = {
  title = "Rito della Visione",
  desc = "Ora ti presento l'Acqua dei Veggenti.$B$BQuando sei pront$Go:a;, bevi l'acqua vicino al fuoco tribale. Dopo aver ingerito le acque sacre, ci vorranno pochi istanti prima che la visione si manifesti davanti al fuoco.$B$BA quel punto spetta a te seguirla verso il tuo destino....",
  obj = "Bevi l'Acqua dei Veggenti davanti al fuoco tribale del Bloodhoof Village e segui la visione quando apparirà.",
  reward = "Non temere, $N. Hai superato con successo il Rito della Visione.",
  en_title = "Rite of Vision",
  en_obj = "Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.",
}
T[773] = {
  title = "Rito della Saggezza",
  desc = "Per ottenere l'accettazione degli anziani di Thunder Bluff devi ora completare il Rito della Saggezza.$B$BOra che hai superato il Rito della Visione, gli spiriti ancestrali di Red Rocks ti doneranno la benedizione dei nostri antenati. Solo chi ha bevuto l'Acqua dei Veggenti può ottenere la benedizione.$B$BViaggia a est di Thunder Bluff, fino a Red Rocks, e cerca l'Ancestral Spirit, $n.",
  obj = "Recati a Red Rocks, a est di Thunder Bluff, e parla con l'Ancestral Spirit.",
  reward = "Hai mostrato grande diligenza nel tuo desiderio di superare i Riti della Madre Terra, $N.$B$BNoi, gli Spiriti Ancestrali, rappresentiamo i possenti tauren che diedero con coraggio la vita per fondare e proteggere la nostra grande città di Thunder Bluff. Con questo affido a te il dovere di quella protezione.$B$BHai superato il Rito della Saggezza, giovane $C. Entra a Thunder Bluff a testa alta.",
  en_title = "Rite of Wisdom",
  en_obj = "Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit.",
}
T[775] = {
  title = "Viaggio a Thunder Bluff",
  desc = "Ora sarai riverit$Go:a; nella nostra grande città. Ogni $r degn$Go:a; di completare i Riti della Madre Terra si guadagna quell'onore.$B$BPer la tua ultima missione, cerca il nostro nobile capo, Cairne Bloodhoof, che dimora sulla mesa più alta di Thunder Bluff.",
  obj = "Parla con Cairne Bloodhoof a Thunder Bluff.",
  reward = "Salute, giovane $C. Vedo che hai trovato la strada fino alla mia porta.",
  en_title = "Journey into Thunder Bluff",
  en_obj = "Speak with Cairne Bloodhoof in Thunder Bluff.",
}
T[776] = {
  title = "I Riti della Madre Terra",
  desc = "Hai superato i Riti della Madre Terra e ti sei guadagnat$Go:a; il tuo posto a Thunder Bluff.$B$BMa per mantenere il posto che ti sei sudat$Go:a; con tanta fatica, devi continuare a dimostrare il tuo valore al tuo popolo.$B$BNoi siamo cacciatori, $n. Laggiù nel Mulgore vive un possente kodo di nome Arra'chea. Mostrami la tua abilità nell'inseguire e cacciare portandomi l'Horn of Arra'chea.",
  obj = "Cairne Bloodhoof a Thunder Bluff vuole che tu gli porti l'Horn of Arra'chea.",
  progress = "Hai già rintracciato Arra'chea?",
  reward = "Ben fatto! Una bella uccisione.$B$BManderò un gruppo di raccolta a recuperare la carcassa, così potremo ottenere la pelle e la carne.$B$BHai compiuto una grande impresa per il tuo popolo, $N.",
  en_title = "Rites of the Earthmother",
  en_obj = "Cairne Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.",
}
T[777] = {
  title = "Sarà dura",
  desc = "Ok, ecco qua.$B$BIo sarò laggiù... al riparo.$B$BSe vuoi, raggiungimi.",
  obj = "Porta Cog #5 a Lotwil Veriatus.",
  progress = "<Senza alzare gli occhi dai ceppi, Lotwil tende una mano e agita le dita con impazienza.>$B$BL'ingranaggio, $N, l'ingranaggio!",
  reward = "Ah, perfetto. Sta' indietro mentre mi preparo a fare di nuovo la storia!$B$B<Lotwil continua a lavorare febbrilmente.>",
  en_title = "This Is Going to Be Hard",
  en_obj = "Bring Cog #5 to Lotwil Veriatus.",
}
T[778] = {
  title = "Sarà dura",
  desc = "Ahah! Fatto! I ceppi sono pronti!$B$BÈ il momento, Lucien. È il momento, Servo!$B$BSei $Gpronto:pronta; ad assistere alla fusione perfetta di alchimia, ingegneria e arcano, $N?$B$BOra evocherò un potente elementale. Questo è un giorno rivoluzionario per tutti noi.",
  obj = "Sconfiggi il Fam'retor Guardian e riporta Lotwil's Shackles of Elemental Binding a Lotwil Veriatus.",
  progress = "Non proprio il risultato che mi aspettavo. Potresti recuperare i miei ceppi?",
  reward = "Grazie, $N. È stata una bella prova, vero?$B$BNon sono sicuro di cosa possa essere andato storto. Per fortuna c'erano le mie magie, ad aiutare a rimandare la creatura nel suo piano d'origine.$B$BForse un piccolo segno di gratitudine per tutto il tuo duro lavoro...",
  en_title = "This Is Going to Be Hard",
  en_obj = "Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.",
}
T[779] = {
  title = "Seal of the Earth",
  progress = "Qui c'è il Seal of the Earth, con tre nicchie incassate per l'Amethyst Runestone, l'Opal Runestone e la Diamond Runestone.",
  reward = "Mentre metti le pietre runiche negli incavi corrispondenti, un violento boato scuote la terra e il sigillo si spezza.",
  en_title = "Seal of the Earth",
}
T[780] = {
  title = "I Battleboar",
  desc = "I Battleboar di Brambleblade Ravine, a est, stanno invadendo i nostri territori di caccia tribali. Sono addestrati alla malvagità dai Quilboar Bristleback, con cui siamo in guerra.$B$BVai e abbatti quelle vili creature e riporta dei musi e dei fianchi, così potremo preparare uno stufato per i nostri piccoli.",
  obj = "Grull Hawkwind a Camp Narache vuole che tu uccida dei Battleboar e porti 8 Battleboar Snout e 8 Battleboar Flank.",
  progress = "L'aggressività dei Battleboar sta aumentando. Hai già mandato loro un messaggio chiaro e portato dei musi e dei fianchi?",
  reward = "Eccellente. Questi ingredienti faranno un ottimo stufato, e la perdita di quei cinghiali sarà una giusta lezione per quei vili Bristleback.",
  en_title = "The Battleboars",
  en_obj = "Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks.",
}
T[781] = {
  title = "Attacco a Camp Narache",
  desc = "Dopo aver esaminato con cura la mappa, ti rendi conto che quello che hai scoperto sono i piani del capoguerra dei Bristleback per un lungo assedio a Camp Narache.$B$BDi certo il Chief Hawkwind potrà fare buon uso di queste informazioni!",
  obj = "Porta i Bristleback Attack Plans al Chief Hawkwind a Camp Narache.",
  progress = "Hai un'aria preoccupata, $N. Quali notizie porti?",
  reward = "È davvero allarmante! Ma con queste informazioni possiamo chiamare in aiuto i nostri fratelli del Bloodhoof Village per sventare l'attacco. Hai salvato la vita a molti tauren, $N.",
  en_title = "Attack on Camp Narache",
  en_obj = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.",
}
T[782] = {
  title = "Alleanze spezzate",
  desc = "Dall'alleanza dell'Orda con il drago Deathwing durante la Seconda Guerra, sappiamo che due dei suoi luogotenenti, Blacklash e Hematus, furono imprigionati nella Lethlor Ravine, lontano a est. Dobbiamo mettere a tacere i nostri depravati alleati di un tempo per restituire l'onore all'Orda!$B$BAbbiamo assoldato Tho'grun e la sua banda di mercenari ogre perché ci aiutassero a ottenere il Sign of the Earth, una chiave necessaria per aprire la prigione dei draghi. Ma Tho'grun ci ha traditi: ci ha sopraffatti e l'ha tenuto per sé. Va' al Camp Boff e riprendilo!",
  obj = "Uccidi Boss Tho'grun e porta il Sign of the Earth a Gorn, a Kargath.",
  progress = "Il tradimento di Tho'grun... c'è da stupirsi se gli ogre non fanno più parte dell'Orda? Mi farà piacere vederlo morto, e vedere il Sign of the Earth restituito.$B$BSe non l'hai ancora tolto di mezzo, non perdere tempo e va' al Camp Boff. Si trova a sud-est di Kargath.",
  reward = "Con Tho'grun morto, e il suo cadavere spolpato dai venti del deserto e dalle poiane in cerca di carcasse, gli ogre saranno nel caos. Anche se è una piccola vittoria, porterà a una ben più grande.$B$BOra il Sign of the Earth è nelle nostre mani, e possiamo aprire la prigione dei draghi neri a Lethlor. Li libereremo dalla loro prigionia senza fine, anche se per andare incontro alla loro fine!",
  en_title = "Broken Alliances",
  en_obj = "Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.",
}
T[783] = {
  title = "Una minaccia interna",
  desc = "Spero che tu abbia stretto bene la cintura, giovane $c, perché qui a Northshire c'è del lavoro da fare.$B$BE non parlo di lavorare nei campi.$B$BLe guardie di Stormwind faticano a mantenere la pace, con tanti di noi partiti per terre lontane e tante minacce così vicine. Per questo chiediamo l'aiuto di chiunque sia disposto a difendere la propria casa. E la propria alleanza.$B$BSe sei qui per rispondere alla chiamata, parla con il mio superiore, il Marshal McBride. Si trova dentro l'abbazia, alle mie spalle.",
  obj = "Parla con il Marshal McBride.",
  reward = "Ah, bene. Un altro volontario. Ne arrivano parecchi di questi tempi.$B$BSpero che basti.$B$BLe terre degli umani sono minacciate dall'esterno, e tante delle nostre forze sono state schierate all'estero. Questo, a sua volta, lascia spazio a gruppi corrotti e fuorilegge che prosperano entro i nostri confini.$B$BÈ una battaglia su più fronti quella che combattiamo, $N. Preparati a una lunga campagna.",
  en_title = "A Threat Within",
  en_obj = "Speak with Marshal McBride.",
}
T[784] = {
  title = "Sconfiggi i Traditori",
  desc = "Guidati dall'Admiral Proudmoore, gli umani di Kul Tiras si sono spinti nel Durotar, violando il patto stretto dal Capoguerra con Jaina Proudmoore per sconfiggere Archimonde anni fa.$B$BL'aggressione umana fu respinta e la Tiragarde Keep cadde. Ma di recente le riserve dell'Admiral, guidate dal Lieutenant Benedict, hanno riconquistato la fortezza e rappresentano di nuovo una minaccia per la nostra patria. Questi umani non mostrano alcun rispetto per la diplomazia.$B$BDimostra il tuo onore e viaggia a sud fino alla Tiragarde Keep per eliminare gli invasori umani.",
  obj = "Uccidi 10 Kul Tiras Sailor, 8 Kul Tiras Marine e il Lieutenant Benedict, poi torna da Gar'Thok a Razor Hill.",
  progress = "Hai i tuoi ordini, $N. La sicurezza del Durotar è in pericolo. Porta a termine il compito che ti è stato affidato o china il capo per la vergogna.$B$BMostra il tuo onore e sconfiggi gli umani della Tiragarde Keep.",
  reward = "La notizia del tuo coraggio viaggia veloce, $C. I racconti della tua vittoria alla Tiragarde Keep saranno celebrati a Orgrimmar.",
  en_title = "Vanquish the Betrayers",
  en_obj = "Kill 10 Kul Tiras Sailors, 8 Kul Tiras Marines and Lieutenant Benedict and return to Gar'Thok in Razor Hill.",
}
T[785] = {
  title = "Un'alleanza strategica",
  desc = "Thrall è un capo saggio e nobile come pochi. La sua tenacia sul campo di battaglia è pari solo al suo tatto diplomatico.$B$BI Darkspear Trolls si sono rivelati alleati preziosissimi per la gente orchesca. Per lealtà e per onore abbiamo giurato con loro un patto di protezione.$B$BIl Capoguerra ha mandato ordine di accertarsi che i nostri amici Darkspear di Sen'jin Village non siano sotto una minaccia diretta. Uno dei loro esploratori più fidati, Lar Prowltusk, tiene d'occhio il loro fianco occidentale.$B$BCerca Lar e aiutalo come serve.",
  obj = "Cerca Lar Prowltusk sul fianco occidentale di Sen'jin Village.",
}
T[786] = {
  title = "Sventare l'aggressione dei Kolkar",
  desc = "Abbassa la voce, $c. I centauri Kolkar si trovano appena oltre la cresta a ovest, nel Kolkar Crag.$B$BLa scorsa notte, mentre erano in razzia, mi sono introdotto nel loro villaggio e ho scoperto che quelle sporche bestie hanno pianificato un attacco su tre livelli contro i troll e gli orchi del Durotar.$B$BNon dobbiamo permettere che la loro invasione si compia. Forse tu hai la forza necessaria per infiltrarti nel Kolkar Crag e distruggere i loro piani d'attacco.$B$BDa quel che ho visto, li hanno divisi tra tre dei loro capi.",
  obj = "Lar Prowltusk fuori dal Sen'jin Village vuole che tu distrugga i 3 set di Attack Plans custoditi nel Kolkar Crag.",
  progress = "I centauri si sono dimostrati una costante seccatura per la Horde. Le loro intenzioni di assediare la nostra patria non possono essere tollerate.",
  reward = "La Horde prevarrebbe di certo se i centauri Kolkar attaccassero. Ma impedendo un simile attacco abbiamo risparmiato ai nostri possenti guerrieri un inutile spargimento di sangue.$B$BE com'è certo che c'è sabbia nel deserto di Tanaris, sappiamo che altro sangue sarà versato prima che questi tempi difficili finiscano.$B$BHai servito bene il tuo popolo, $C.",
  en_title = "Thwarting Kolkar Aggression",
  en_obj = "Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag.",
}
T[787] = {
  title = "La nuova Horde",
  desc = "Throm'ka, $C. Sono Eitrigg, incaricato da Thrall di sovrintendere all'addestramento delle reclute.$B$BL'Horde è cambiata rispetto a ciò che era un tempo. Ci fu un periodo in cui la abbandonai, disilluso dalla crescente influenza dei burattini assetati di potere della Burning Legion. Durante il mio esilio fui fatto prigioniero da un gruppo di umani, ma venni salvato dal Warchief. Quando ascoltai la sua visione di un'Horde libera dall'influenza demoniaca e guidata dagli sciamani, tornai.$B$BGornek avrà altre istruzioni per te.",
  obj = "Riferisci a Gornek nel Den.",
  reward = "Un'altra recluta di Eitrigg, eh?$B$BTriste stato di cose, se questo è il meglio che l'Horde sa produrre. Non importa. Quando penseremo che sei pront$Go:a; a lasciare la Valley, sarai un orgoglioso guerriero dell'Horde.",
  en_title = "The New Horde",
  en_obj = "Report to Gornek in the Den.",
}
T[788] = {
  title = "Mettere i denti",
  desc = "La prima cosa da fare sarà metterti un po' di forza nella schiena. Potrei mandarti nei Barrens a dare la caccia ai kodo, ma, a dirla tutta, per noi sei più utile vivo che morto.$B$BCredo che troverai un buon avversario nei mottled boar che si trovano a nord di qui.",
  obj = "Uccidi 10 Mottled Boar, poi torna da Gornek al Den.",
  progress = "Spero che tu non sia tornat$Go:a; per cercare di convincermi di aver portato a termine il tuo compito, $N. No, certo che no. Ho una stima migliore di te.",
  reward = "Hmmm, non male, $N. Ma non montarti la testa... nella tua carriera combatterai contro nemici più duri dei cinghiali.$B$BCiononostante, ti sei dimostrat$Go:a; valido, e la tua prossima prova sarà contro un avversario ben più pericoloso, quindi ti servirà qualche protezione in più.",
  en_title = "Cutting Teeth",
  en_obj = "Kill 10 Mottled Boars then return to Gornek at the Den.",
}
T[789] = {
  title = "Il pungiglione dello Scorpid",
  desc = "Potenti guerrieri e maldestri novizi sono caduti sotto il pungiglione velenoso degli scorpid. Ne troverai un gran numero a nordovest di qui. Portami dieci delle loro code come prova del tuo valore in battaglia.$B$BL'antidoto al loro veleno si ricava proprio dal veleno estratto dai loro pungiglioni. Teniamo sempre a portata di mano grandi quantità di antidoto per curare giovani sangue caldo come te...$B$BMa sono sicuro che tu non ne avrai bisogno, vero?",
  obj = "Procura 10 Scorpid Worker Tail a Gornek al Den.",
  progress = "La corazza di uno scorpid non è così spessa da fermare la forza di un $C determinato. Colpisci con vigore e senza esitare, e gli scorpid si riveleranno facili prede.",
  reward = "C'è una lezione importante che devi trarre dallo scontro con gli scorpid. Anche l'avversario più piccolo o più grande può condurti alla rovina. In un combattimento feroce, molte cose possono causare la tua caduta.$B$BNon ho altro da insegnarti, $N. Hai fatto bene, e seguirò i tuoi progressi con interesse.",
  en_title = "Sting of the Scorpid",
  en_obj = "Get 10 Scorpid Worker Tails for Gornek in the Den.",
}
T[790] = {
  title = "Sarkoth",
  desc = "$C! Pensavo che sarei morto qui senza che nessuno lo sapesse. Mentre davo la caccia agli scorpid della Valley, mi sono imbattuto in uno dall'aspetto particolarmente feroce. Mi sono lanciato contro di lui e sono riuscito a infliggere un colpo tremendo alla sua chela prima che si chiudesse attorno alla mia gamba.$B$BMa non ero pronto al suo pungiglione: mi è calato addosso, mi ha squarciato il petto, tagliandomi la carne e lasciando scorrere il mio sangue. Ti prego, devi uccidere quello scorpid per me! Il mio onore deve essere difeso! L'ho affrontato sull'altopiano a sud.",
  obj = "Uccidi Sarkoth e riporta la sua chela a Hana'zua.",
  progress = "Ahhh... mio padre diceva sempre che non sarei mai arrivato a niente, e ora, disteso sotto un albero mentre la vita mi abbandona, temo che avesse ragione.$B$BAlmeno voglio morire sapendo che il mio ultimo nemico giace morto.",
  reward = "Il mio colpo non è bastato a ucciderlo, ma vedere il danno che ho inflitto mi dà un piccolo motivo d'orgoglio. Quel poco sarà tutto ciò che mi sosterrà se morirò, e in quest'ottica la breve lista delle imprese della mia vita mi riempie di rabbia.",
  en_title = "Sarkoth",
  en_obj = "Kill Sarkoth and bring his claw back to Hana'zua.",
}
T[791] = {
  title = "Fai la tua parte",
  desc = "L'età mi ha reso inutile in battaglia. Ora mi rendo utile in altri modi.$B$BDa questo punto di osservazione vigilo sugli invasori. Man mano che la nostra forza qui cresce, mi ritrovo a suonare il corno di segnalazione sempre meno.$B$BPer passare il tempo fabbrico oggetti che aiutino i guerrieri più giovani e capaci a difendere la nostra terra.$B$BPer te posso fabbricare una borsa per i tuoi effetti personali. Se un oggetto simile ti può servire, portami della tela, un materiale comune tra gli umani e i centauri.",
  obj = "Furl Scornbrow, nella torre di guardia di Razor Hill, vuole 8 Canvas Scrap.",
  progress = "Ho combattuto con orgoglio al fianco del Warchief quando queste terre furono colonizzate. Le cicatrici di battaglia segnano la mia pelle.$B$BL'onore dell'Horde è stato difeso con l'aiuto della mia ascia e del mio grido di guerra durante la sconfitta di Archimonde, quando fu stretta l'empia alleanza con umani ed elfi, nata dalla necessità.$B$BMa il mio ruolo di sentinella e fornitore mi ha dato un nuovo senso di valore.",
  reward = "Ottimo, $N. Qualsiasi buon $C troverà senz'altro un uso per questa borsa sul campo di battaglia.$B$BSaluto il tuo vigore e la tua disponibilità a morire in nome dell'Horde!",
  en_title = "Carry Your Weight",
  en_obj = "Furl Scornbrow in the Razor Hill watchtower wants 8 Canvas Scraps.",
}
T[792] = {
  title = "Famigli immondi",
  desc = "Confido che la Valley of Trials ti insegnerà molto, giovane $C.$B$BSono stato mandato nella Valley per guidarti, ma ho scoperto una corruzione crescente in questo luogo...$B$BUn gruppo che si fa chiamare Burning Blade ha un covo qui nella Valley of Trials. Si nascondono in una caverna a nordest, e i loro Vile Familiar sono usciti dalla bocca della grotta a seminare il caos.$B$BCome primo compito contro la Burning Blade, ti ordino di sconfiggere questi famigli. Uccidine molti e, se sopravvivi, torna da me.",
  obj = "Uccidi 12 Vile Familiar.$B$BTorna da Zureetha Fargaze fuori dal Den.",
  progress = "Per metterti alla prova contro la Burning Blade, devi prima sconfiggere i suoi Vile Familiar. Torna da me quando l'avrai fatto.",
  reward = "Hai fatto bene, $N.$B$BAnche se i Vile Familiar erano solo animali al servizio dei poteri più oscuri della Burning Blade, il tuo successo contro di loro preannuncia imprese più grandi.",
  en_title = "Vile Familiars",
  en_obj = "Kill 12 Vile Familiars.$B$BReturn to Zureetha Fargaze outside the Den.",
}
T[793] = {
  title = "Alleanze spezzate",
  desc = "Il Seal of the Earth è tenuto da tre pietre runiche, custodite nei Pillar of Diamond, Opal e Amethyst, nella Lethlor Ravine. Usando il Sign of the Earth, potrai rimuovere le pietre runiche e aprire il Seal of the Earth.$B$BMa sta' $Gattento:attenta;, $N: i draghi neri Blacklash e Hematus non sono da prendere alla leggera. Assicurati che muoiano e riportami i loro vincoli.$B$BPer raggiungere la gola, va' all'estremità orientale delle Badlands. Ma fa' attenzione, perché la gola è la dimora di innumerevoli draghi.",
  obj = "Usa il Sign of the Earth per attivare il Pillar of Diamond, il Pillar of Opal e il Pillar of Amethyst e ottenere la Diamond Runestone, l'Opal Runestone e l'Amethyst Runestone.$B$BMetti le pietre runiche nel Seal of the Earth per liberare Blacklash e Hematus.$B$BUccidili e riporta Blacklash's Bindings, le Chains of Hematus e il Sign of the Earth a Gorn.",
  progress = "Ci sono pochi nemici più letali della stirpe dei draghi, e pochi draghi hanno combattuto con la ferocia di Blacklash e Hematus.",
  reward = "Lo stormo dei draghi neri continua ad allearsi con gli orchi rinnegati Blackrock, ed entrambi vanno rimessi in riga, o eliminati. Con Blacklash e Hematus morti, possiamo volgere la nostra attenzione a ovest, verso la Blackrock Spire.",
  en_title = "Broken Alliances",
  en_obj = "Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones.$B$BPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.$B$BSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn.",
}
T[794] = {
  title = "Il medaglione della Burning Blade",
  desc = "Attraverso le mie divinazioni vedo che un oggetto di potere si nasconde nel profondo del Burning Blade Coven, custodito da bestie e magia nera.$B$BSi chiama Burning Blade Medallion, e il tuo prossimo compito è trovarlo e portarlo via dal covo.$B$BMa sii cauto: il medaglione potrebbe essere in possesso di un agente della Burning Blade, e in tal caso il suo potere sarebbe superiore a quello dei famigli che hai già incontrato.$B$BVai, $N. Troverai il covo in una caverna, a nord e a ovest.",
  obj = "Porta il Burning Blade Medallion a Zureetha Fargaze, fuori dal Den.",
  progress = "Il tuo compito è concluso, $N? Hai con te il Burning Blade Medallion?",
  reward = "L'hai recuperato! Ben fatto!$B$BI tuoi sforzi nel Burning Blade Coven sono fondamentali per estirpare questo culto dalla Valley of Trials. Ma temo che abbiano altri scopi nella nostra terra.$B$BNon abbiamo ancora visto la fine di loro.",
  en_title = "Burning Blade Medallion",
  en_obj = "Bring the Burning Blade Medallion to Zureetha Fargaze, outside The Den.",
}
T[795] = {
  title = "Seal of the Earth",
  progress = "Qui c'è il Seal of the Earth, con tre nicchie incassate per l'Amethyst Runestone, l'Opal Runestone e la Diamond Runestone.",
  reward = "Mentre metti le pietre runiche negli incavi corrispondenti, un violento boato scuote la terra e il sigillo si spezza.",
  en_title = "Seal of the Earth",
}
T[804] = {
  title = "Sarkoth",
  desc = "Vedere ciò che hai fatto per me tempra il mio cuore. Non posso cadere così facilmente! Devo resistere!$B$BResta il fatto che non posso tornare al Den senza aiuto. Ti prego, $N, torna al Den e racconta a Gornek la mia situazione. Forse potrà aiutarmi.",
  obj = "Porta a Gornek, al Den, la notizia della sorte di Hana'zua.",
  reward = "Dalla tua descrizione della bestia, credo che tu stia parlando di Sarkoth! Non c'è da stupirsi che Hana'zua ne sia stato sopraffatto. Invierò subito dei soccorsi: non preoccuparti oltre della sorte di Hana'zua.$B$BDevo però dirti che sono davvero colpito nel sentire che hai ucciso Sarkoth. È un'impresa di cui andare fieri, $N. E il fatto che tu abbia combattuto per l'onore di uno sconosciuto, pur avendo altri compiti da svolgere, accresce il tuo stesso onore.",
  en_title = "Sarkoth",
  en_obj = "Bring the news of Hana'zua's plight to Gornek at the Den.",
}
T[805] = {
  title = "Riferisci a Sen'jin Village",
  desc = "Le tue prove contro la Burning Blade sono concluse... qui nella Valley. Ma voglio che tu riferisca ciò che hai scoperto.$B$BVai al villaggio troll di Sen'jin e cerca Master Gadrin. Sen'jin Village si trova a est, fuori dalla valle, poi a destra al bivio.$B$BParla a Gadrin della Burning Blade e di come sia arrivata fino alla Valley of Trials. Scopri da lui se abbia già raggiunto Sen'jin.$B$BVai, $N, e sii rapid$Go:a;. Temo che il male trovato nel Burning Blade Coven sia solo l'araldo di una minaccia più grande...",
  obj = "Parla con Master Gadrin a Sen'jin Village.",
  reward = "Hm... il tuo rapporto arriva in un brutto momento. La Burning Blade non si vede qui a Sen'jin, ma il suo male ha messo radici al largo della costa, sulle Echo Isles.$B$BGli orchi sono amici dei Darkspear Troll. Amici onorevoli. Vogliamo aiutare gli orchi, ma... anche noi abbiamo bisogno di aiuto.$B",
  en_title = "Report to Sen'jin Village",
  en_obj = "Speak with Master Gadrin in Sen'jin Village.",
}
T[806] = {
  title = "Tempeste oscure",
  desc = "Non possiamo permettere alla Burning Blade di mettere piede a Durotar! Dobbiamo distruggerli prima che il loro male si diffonda!$B$BHo condotto delle indagini per conto mio e ho scoperto che uno stregone della Burning Blade, il goblin Fizzle Darkstorm, si è accampato a Thunder Ridge, a nordovest. Là lui e i suoi servitori cultisti seminano il caos.$B$BTrova e sconfiggi Fizzle, e portami il suo artiglio mozzato!",
  obj = "Porta il Fizzle's Claw a Orgnil Soulscar a Razor Hill.",
  progress = "Hai trovato Fizzle, $N? Lui, e il resto della Burning Blade, devono essere ripuliti dalle nostre terre!",
  reward = "Aha! L'hai preso!$B$BOnori il tuo clan, $N. E grazie a te, Durotar è libera da un altro agente del male.",
  en_title = "Dark Storms",
  en_obj = "Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill.",
}
T[808] = {
  title = "Il teschio di Minshina",
  desc = "Sento la voce di mio fratello, Minshina, che mi chiama nei sogni.$B$BFu catturato da Zalazane, lo stregone delle Echo Isles a est. Ed è morto.$B$BMa la morte non è libertà per mio fratello. Lo spirito di Minshina è stato intrappolato nel suo stesso teschio dalle magie di Zalazane. Nei miei sogni lo vedo insieme ad altri teschi, in un cerchio di potere sulla più grande delle Echo Isles. Finché resterà là, l'anima di mio fratello è condannata.$B$BTi prego, $N. Trova il cerchio e recupera il teschio di Minshina. Portamelo.$B$BLiberalo!",
  obj = "Recupera il teschio di Minshina dal cerchio di potere sulle Echo Isles.$B$BPortalo a Master Gadrin a Sen'jin Village.",
  progress = "Hai il teschio di mio fratello, $N? È finalmente libero?",
  reward = "Grazie, $N. Hai salvato Minshina. Hai salvato lo spirito di mio fratello dalla schiavitù!",
  en_title = "Minshina's Skull",
  en_obj = "Retrieve Minshina's skull from the circle of power on the Echo Isles.$B$BBring it to Master Gadrin in Sen'jin Village.",
}
T[809] = {
  title = "Ak'Zeloth",
  desc = "Dall'ultima grande guerra, quando la Burning Legion fu sconfitta, ho cercato fonti di corruzione demoniaca nella società degli orchi. Il collare che mi hai portato conferma i miei timori.$B$BAppartiene alla Burning Blade, un culto che si raccoglie attorno a un oggetto di potere demoniaco. Si chiama Demon Seed e si trova nei Barrens, in cima a Dreadmist Peak. Deve essere distrutto!$B$BVai a Far Watch Post, al confine dei Barrens a ovest, e parla con il mio assistente, Ak'Zeloth. Ti darà ulteriori indicazioni.",
  obj = "Parla con Ak'Zeloth nei Barrens.",
  reward = "Neeru vuole che il Demon Seed sia distrutto, eh? Strano...$B$BVa bene. Se vuole che il seme sparisca, ti dirò come rimuoverlo.",
  en_title = "Ak'Zeloth",
  en_obj = "Speak with Ak'Zeloth in the Barrens.",
}
T[812] = {
  title = "Bisogno di una cura",
  desc = "$N... il tuo tempismo è perfetto. Spero solo di poter elogiare anche la tua rapidità.$B$BSono stato incauto combattendo contro alcuni venomtail qui vicino, e uno di loro mi ha punto in profondità. Sento il suo veleno indebolirmi mentre parliamo. Di questo passo, mi resta forse un'ora di vita. Ma avrò bisogno del tuo aiuto per sopravvivere...$B$BKor'ghan a Orgrimmar sa preparare l'antidoto. Trovalo... e sbrigati, $N. Non resisterò ancora a lungo. Dovrebbe trovarsi nella Cleft of Shadow.",
  obj = "Trova Kor'ghan a Orgrimmar e procurati il Venomtail Antidote. Poi porta l'antidoto a Rhinag, vicino al confine nordoccidentale di Durotar.",
  progress = "Sono quasi contento di non poter tornare a Sen'jin così com'ero. La mia debolezza e la mia stupidità sarebbero di certo derise.",
  reward = "$N, mi hai salvato la vita. Grazie.$B$BTieni questo; spero che almeno ti aiuti nei tuoi viaggi, se non ti frutta qualche moneta. Da come dici, non lo userò presto. Kor'ghan mi farà passare attraverso altri suoi rituali finché non mi sarò dimostrato all'altezza. Più cinghiali da uccidere, più code di scorpid da raccogliere... <sospiro>",
  en_title = "Need for a Cure",
  en_obj = "Find Kor'ghan in Orgrimmar and get the Venomtail Antidote. Then bring the antidote to Rhinag near the northwestern border of Durotar.",
}
T[813] = {
  title = "Alla ricerca dell'antidoto",
  desc = "I venomtail sono tra gli scorpid più letali di Durotar. È stato imprudente da parte di Rhinag andare a caccia senza un po' di antidoto con sé, ma in questo momento l'ultima cosa di cui ha bisogno è una ramanzina.$B$BPortami qualche Venomtail Poison Sac da uno dei venomtail vicino all'ingresso di Orgrimmar e preparerò un antidoto per lui.$B$BFai in fretta, $N. Uno dei nostri ha bisogno del tuo aiuto.",
  obj = "Porta 4 Venomtail Poison Sac a Kor'ghan a Orgrimmar.",
  progress = "Ricorda, qualunque creatura tu cacci, farai bene a studiarla e a comprenderne il comportamento. Quella conoscenza potrebbe salvarti la vita.",
  reward = "Ecco l'antidoto, $N. Portalo a Rhinag il prima possibile, e sii prudente.",
  en_title = "Finding the Antidote",
  en_obj = "Bring 4 Venomtail Poison Sacs to Kor'ghan in Orgrimmar.",
}
T[815] = {
  title = "Rompere qualche uovo",
  desc = "Bah! Quasi dimenticavo che devo preparare la colazione.$B$B$N, datti una mossa e portami delle uova di taillasher. Me ne servono almeno tre se voglio averne abbastanza per il pasto di domani.$B$BI Bloodtalon Taillasher possono essere feroci e il più delle volte difendono le loro uova fino alla morte. A volte le seppelliscono troppo in profondità per recuperarle in sicurezza, ma se vai alle Echo Isles, a sudest di Sen'jin Village, di solito le trovi sparse per tutte quelle isole.",
  obj = "Porta 3 Taillasher Egg a Cook Torka a Razor Hill.",
  progress = "Colazione, pranzo, cena! Chi se ne importa di quale pasto sia? Deve comunque essere cucinato da qualcuno... cioè da me!",
  reward = "Sarai pure debole, ma almeno non sei maldestr$Go:a;, $N.$B$BTieni, prendi questo e levati dai piedi. Ho da cucinare.",
  en_title = "Break a Few Eggs",
  en_obj = "Bring 3 Taillasher Eggs to Cook Torka in Razor Hill.",
}
T[816] = {
  title = "Perso ma non dimenticato",
  desc = "$N, ti prego, puoi aiutarmi? Mio figlio Kron è partito a caccia giorni fa e non è ancora tornato. È andato a ovest, verso i Barrens, a cacciare coccodrilli lungo il Southfury River. Temo il peggio.$B$BPer quanto fosse forte, il suo testardo orgoglio lo ha sempre cacciato nei guai. Lo avevo avvertito che i coccodrilli erano potenti e feroci. Si è arrabbiato ed è uscito sbattendo la porta.$B$BSe non riesci a trovarlo, portami almeno un segno del suo destino... anche se dovrai aprire lo stomaco di ogni coccodrillo lungo le rive del Southfury.",
  obj = "Porta un segno del destino di Kron a Misha Tor'kren, alla fattoria a nordovest di Razor Hill.",
  progress = "Prego che Kron torni da me, ma sono quasi certa di conoscere già il suo destino.",
  reward = "Oh, figlio mio... il mio bel ragazzo.$B$BNon sapendo che ne fosse stato di lui, mi sono tormentata da quando è partito. Ora che so cos'è successo, forse potrò finalmente iniziare a piangerlo.$B$BGrazie, $N. Prendi questo. Volevo darlo a Kron come dono al suo ritorno da vincitore. Ora che so che è morto, non sopporto di guardarlo.",
  en_title = "Lost But Not Forgotten",
  en_obj = "Bring a sign of Kron's fate to Misha Tor'kren at the farmstead northwest of Razor Hill.",
}
T[817] = {
  title = "Prede pratiche",
  desc = "Molte delle pelli che usiamo provengono dalle tigri di Durotar, $N. Coperte, armature, tende: ci sono moltissime ragioni per cui cacciamo queste bestie, e molte ragioni per cui le lasciamo prosperare.$B$BÈ giunto il momento di sfoltire il branco, per così dire. Il nostro numero cresce e le nostre necessità iniziano a sopraffare le scorte. Mi servono più pelli per preparare merci adatte al nostro popolo.$B$BPortami 4 Durotar Tiger Furs e ti ricompenserò. Le troverai sulle isole a sud di qui.",
  obj = "Porta 4 Durotar Tiger Furs a Vel'rin Fang a Sen'jin Village.",
  progress = "Ricordo la mia prima caccia alla tigre, $N. Scelsi di cacciare sulla più grande delle Echo Isles e rimasi perfettamente immobile all'ombra del fogliame per quasi un giorno intero... a osservare... ad aspettare.$B$BI miei muscoli erano tesi, ero pronto a colpire. Fu una delle mie più grandi vittorie quando quella tigre finalmente abboccò all'esca.",
  reward = "Sono soddisfatto, $N. Grazie al tuo aiuto, il nostro popolo sarà protetto e non patirà il freddo al cambiare delle stagioni.$B$BGrazie.",
  en_title = "Practical Prey",
  en_obj = "Bring 4 Durotar Tiger Furs to Vel'rin Fang in Sen'jin Village.",
}
T[818] = {
  title = "Uno spirito solvente",
  desc = "Anche se la vista mi abbandona, vedo ancora abbastanza bene. Più spesso devo affidarmi alla mia arte alchemica per aiutarmi in magie che un tempo mi riuscivano con facilità. Ma mi rifiuto di prendere un apprendista: nessun troll o orco degno si è mai fatto avanti.$B$BSei $Gdegno:degna; tu? Sì, certo che lo sei... certo che lo credi.$B$BHo bisogno di alcune cose. Me le porterai?$B$BMi servono Intact Makrura Eyes e fiale di Crawler Mucus. Potrai trovarli su qualsiasi makrura o crawler in Durotar. Parleremo di nuovo presto.",
  obj = "Porta 4 Intact Makrura Eyes e 8 fiale di Crawler Mucus a Master Vornal a Sen'jin Village.",
  progress = "Il tempo è la vera prova della tua forza e della tua volontà. Perdi la pazienza o cedi alla debolezza, e il tuo vero io verrà rivelato.",
  reward = "Ben fatto, giovane... davvero ben fatto.",
  en_title = "A Solvent Spirit",
  en_obj = "Bring 4 Intact Makrura Eyes and 8 vials of Crawler Mucus to Master Vornal in Sen'jin Village.",
}
T[819] = {
  title = "Il barile vuoto di Chen",
  desc = "Una piccola targa su un lato del barile dice:$B$B\"Chen Stormstout-$B$BPossa il tuo spirito essere elevato e possa tu sempre sollevare gli spiriti.\"",
  obj = "Trova qualcuno che sappia qualcosa sul barile vuoto di Chen.",
  progress = "Sì?",
  reward = "Ma guarda un po'...$B$BQuesto era uno dei barili di Chen Stormstout. Viaggiava con Rexxar tanto tempo fa. Non ho sue notizie da un'era di kodo. Ti ringrazio per avermelo portato, $N.",
  en_title = "Chen's Empty Keg",
  en_obj = "Find someone who knows about Chen's Empty Keg.",
}
T[821] = {
  title = "Il barile vuoto di Chen",
  desc = "Vorresti assaggiare l'omonima birra di Chen? Ah, la stormstout è un infuso potente. Chen insegnò la ricetta al mio maestro, e il mio maestro la tramandò a me. Mi serviranno alcune cose, ma una cosa posso dirtela: il colpo ne vale la pena.$B$BPortami 5 zanne di leone della savana da un qualsiasi leone della savana, 5 reni di plainstrider da un qualsiasi plainstrider e 1 corno di lucertola del tuono da una qualsiasi specie di lucertola del tuono. Dovrebbe bastare.$B$BTroverai questi ingredienti in tutti i Barrens.",
  obj = "Porta 5 Savannah Lion Tusks, 5 Plainstrider Kidneys e 1 Thunder Lizard Horn a Brewmaster Drohn a Ratchet.",
  progress = "Come procede la ricerca?",
  reward = "Haha... non pensavo che avrei mai più preparato questa roba.$B$BHai risvegliato in me una grande nostalgia, $N. Mi ricorda l'ultima volta che ho perso i sensi per troppa birra di trogg. Grazie. I ricordi mi scaldano lo stomaco.",
  en_title = "Chen's Empty Keg",
  en_obj = "Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet.",
}
T[822] = {
  title = "Chen's Empty Keg",
  desc = "Roba buona, quella stormstout, eh?$B$BHo un'altra ricetta che ho imparato da Chen. Ti interessa? Non ci vuole molto a prepararla, e potrebbe tornarti utile se hai in mente di andare ancora in giro per avventure.$B$BPortami 5 Lightning Gland da uno Stormhide qualsiasi, 1 Thunderhawk Saliva Gland dai Greater Thunderhawk e un Kodo Liver da uno qualsiasi dei kodo delle Barrens.$B$BCome ti ho detto, questa roba ha una bella botta: è la birra dei trogg di cui ti avevo parlato.",
  obj = "Porta 5 Lightning Gland, 1 Thunderhawk Saliva Gland e 1 Kodo Liver a Brewmaster Drohn, a Ratchet.",
  progress = "Ci stai lavorando sodo per trovare quegli ingredienti, $N?",
  reward = "Ahah! Lo sapevo che non avresti resistito a un po' di questa birra. Torna quando vuoi se te ne serve altra, $N. Basta che mi porti altri ingredienti come quelli che ti ho fatto raccogliere.",
  en_title = "Chen's Empty Keg",
  en_obj = "Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet.",
}
T[823] = {
  title = "Riferisci a Orgnil",
  desc = "A Sen'jin Village non mancano i nostri guai, e ti ringraziamo per il tuo aiuto. Ma le notizie che porti sulla Burning Blade potrebbero essere un guaio per tutti.$B$BC'è un orco di stanza a Razor Hill, Orgnil Soulscar, che protegge Durotar da mali come la Burning Blade! Va' da Orgnil e raccontagli della nostra situazione, oltre alle tue notizie dalla Valley of Trials. Vorrà saperle.$B$BRazor Hill si trova a nord.",
  obj = "Parla con Orgnil Soulscar a Razor Hill.",
  reward = "Sì? Hai qualcosa da riferire? Bene, sentiamo!",
  en_title = "Report to Orgnil",
  en_obj = "Speak with Orgnil Soulscar in Razor Hill.",
}
T[824] = {
  title = "Je'neu del Circolo della Terra",
  desc = "Il Circolo della Terra è un gruppo sciamanico che si dedica a studiare e preservare gli elementi. Di antichi dèi folli, di leggende e di saperi antichi ha dimenticato più cose di quante la maggior parte degli studiosi ne saprà mai.$B$BPer tua fortuna, conosco qualcuno del Circolo della Terra qui ad Ashenvale. Va' allo Zoram'gar Outpost, sulla costa dello Zoram Strand; mostra a Je'neu Sancrea quello che hai trovato. Se c'è qualcuno che può capire il significato di quel globo, è lui.",
  obj = "Porta il Befouled Water Globe a Je'neu Sancrea, allo Zoram'gar Outpost, in Ashenvale.",
  progress = "Ah, salve. Passo molto tempo a studiare l'acqua — tutti gli elementi, a dire il vero — tanto che a volte non mi accorgo nemmeno di chi mi sta intorno.$B$BC'è qualcosa in cui posso aiutarti?",
  reward = "Questo globo... è davvero inquietante. Molti degli elementali più potenti ricevono potere ed energia attraverso congegni simili. Trovarne uno così quasi intatto è una cosa — trovarlo tanto corrotto è un'altra.$B$BFarò in modo che il Circolo della Terra studi questo globo come si deve. Forse possiamo mettere fine a questa corruzione degli elementi. Ti prego — accetta questo come giusto scambio per aver portato il globo all'attenzione del Circolo della Terra.",
  en_title = "Je'neu of the Earthen Ring",
  en_obj = "Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
}
T[825] = {
  title = "Dal relitto....",
  desc = "Uno dei miei esploratori più attenti riferisce che il relitto della flotta di Proudmoore giace ancora al largo della costa di Durotar, appena a est di Tiragarde Keep.$B$BNon è un segreto che gli umani, alleati di quelle disgustose creaturine note come gnomi, abbiano una conoscenza avanzata della meccanica. Dobbiamo comprendere appieno tutti i nostri potenziali nemici. E il nostro popolo trarrà beneficio anche da queste nuove conoscenze.$B$BNuota tra i relitti, $n, e recupera per me gli attrezzi dell'Alleanza.",
  obj = "Gar'Thok di Razor Hill vuole che tu recuperi 3 Gnomish Tools dal relitto al largo della costa.",
  progress = "Una volta imparato come gli umani azionano i loro strani macchinari, avremo maggiori possibilità di sconfiggerli nelle battaglie future.$B$BCon la nostra nuova conoscenza, la Horde non può che crescere in forza.",
  reward = "La tua missione di recupero è stata un successo, $C. Farò in modo che questi attrezzi arrivino a Orgrimmar con la prossima carovana.$B$BOttimo lavoro.",
  en_title = "From The Wreckage....",
  en_obj = "Gar'Thok of Razor Hill wants you to retrieve 3 Gnomish Tools from the wreckage off the coast.",
}
T[826] = {
  title = "Zalazane",
  desc = "Lo stregone Zalazane dimora sulle Echo Isles a est. Sono le isole che un tempo chiamavamo casa.$B$BDa lì manda i suoi troll sulla terraferma, per gettare malefici sul nostro popolo e trascinarne altri sotto il suo dominio.$B$BDeve essere fermato.$B$BSconfiggi Zalazane e i suoi servitori -- ex troll Darkspear, ora perduti per noi. Portami la sua testa e saprò che il suo regno del male è finito.",
  obj = "Sconfiggi Zalazane.$B$BUccidi 8 Voodoo Trolls e 8 Hexed Trolls.$B$BPorta la testa di Zalazane a Gadrin.",
  progress = "Zalazane è stato sconfitto, $N?",
  reward = "Con Zalazane scomparso, la nostra tribù può tornare a dormire in pace.$B$BGrazie, $N. La tribù Darkspear ti deve molto. Se soffri di qualche malanno, visita il mio assistente Bom'bay, qui dietro di me. Il suo voodoo è potente...",
  en_title = "Zalazane",
  en_obj = "Defeat Zalazane.$B$BKill 8 Voodoo Trolls and 8 Hexed Trolls.$B$BBring Zalazane's Head to Gadrin.",
}
T[827] = {
  title = "Skull Rock",
  desc = "$N. La Burning Blade ha infestato la caverna a est di Orgrimmar nota come Skull Rock. Là dentro compiono rituali immondi e bruciano la propria carne con i Searing Collars.$B$BIndossando questi collari, credo che i cultisti si sintonizzino con il potere demoniaco. Ma per confermarlo devo avere una collezione di collari da studiare.$B$BVa' a Skull Rock e raccogli Searing Collars dai cultisti che troverai là. Portameli e ne svelerò i segreti.",
  obj = "Raccogli Searing Collars dai cultisti di Skull Rock.$B$BPortali a Margoz al suo accampamento.",
  progress = "Sei già entrat$Go:a; a Skull Rock, $N? Hai i Searing Collars?",
  reward = "Bene. Dentro questi collari si nasconde il segreto della Burning Blade. E io scoprirò quel segreto...",
  en_title = "Skull Rock",
  en_obj = "Gather Searing Collars from the cultists in Skull Rock.$B$BBring them to Margoz at his camp.",
}
T[828] = {
  title = "Margoz",
  desc = "Uno dei nostri sciamani, Margoz, sa di più sulla corruzione della Burning Blade. Parla di una caverna chiamata Skull Rock tra le montagne - appena fuori Orgrimmar! - che ospita un grosso gruppo di cultisti della Burning Blade.$B$BPrima di andare a Skull Rock, parla con Margoz. È saggio e il suo consiglio è prezioso.$B$BÈ accampato a nordest, tra la costa e Drygulch Ravine.$B$BSegui il suo consiglio, ma qualunque cosa dica Margoz, $N, voglio comunque che tu schiacci quei cultisti!",
  obj = "Parla con Margoz.",
  reward = "Benvenut$Go:a;, $N. La notizia del tuo arrivo e delle tue imprese in Durotar mi è giunta.$B$BSei $Gun:una; $C di crescente abilità e fama.$B$BRimani sul sentiero puro e il tuo futuro sarà davvero grande.",
  en_title = "Margoz",
  en_obj = "Speak with Margoz.",
}
T[829] = {
  title = "Neeru Fireblade",
  desc = "I Searing Collars che mi hai portato sono strumenti demoniaci e potenti. Scoprirne l'origine, temo, va oltre le mie capacità di sciamano. Ci serve uno stregone che li studi.$B$BPorta un Searing Collar a Neeru Fireblade. Sebbene sia un abile stregone, dichiara di usare i suoi poteri per sventare i demoni e sostiene che le sue ricerche sull'occulto siano innocue. Che sia vero o falso, potremmo aver bisogno del suo aiuto contro il culto demoniaco in Durotar.$B$BPuoi trovare Neeru a Orgrimmar, nella Cleft of Shadow.",
  obj = "Porta un Example Collar a Neeru Fireblade a Orgrimmar.",
  progress = "I miei più umili saluti, $C. Come posso aiutare oggi il mio fratello $R?",
  reward = "Ah, e dove l'hai preso? Il buon Margoz di Razor Hill ti ha mandato da me, vero?$B$BBene, vediamo più da vicino...",
  en_title = "Neeru Fireblade",
  en_obj = "Bring an Example Collar to Neeru Fireblade in Orgrimmar.",
}
T[830] = {
  title = "Gli ordini dell'Ammiraglio",
  desc = "Apri la busta vecchia e consunta e scopri un documento dall'aspetto ufficiale. Riconosci il sigillo dell'Ammiraglio Proudmoore.$B$BSembra importante. Forse Gar'Thok, il comandante di Razor Hill, sarebbe interessato a ricevere queste informazioni.",
  obj = "Porta gli Admiral Proudmoore's Orders a Gar'Thok a Razor Hill.",
  progress = "Hai un'aria preoccupata, $C. Cosa porti con te?",
  reward = "Questo non promette nulla di buono. Hai fatto bene a portare queste informazioni alla mia attenzione.",
  en_title = "The Admiral's Orders",
  en_obj = "Take Admiral Proudmoore's Orders to Gar'Thok in Razor Hill.",
}
T[831] = {
  title = "Gli ordini dell'Ammiraglio",
  desc = "Degli umani non ci si può fidare. Abbiamo combattuto al loro fianco con il cuore stanco, sapendo che un giorno ci avrebbero traditi.$B$BLa morte dell'Ammiraglio Proudmoore non è bastata a fermare la sua eredità di inganni. Quella feccia umana aveva i suoi piani ben tracciati prima ancora di incontrare la sua fine.$B$BPare che il suo dominio non morirà nemmeno con Benedict. Chissà quanto passerà prima che le prossime ondate di uomini di Proudmoore sbarchino sulle nostre coste.$B$BDobbiamo portare questi ordini a Nazgrel a Orgrimmar immediatamente! Lo troverai nella stanza di Thrall.",
  obj = "Consegna gli Admiral Proudmoore's Orders a Nazgrel nella stanza di Thrall a Orgrimmar.",
  progress = "Non vedi che sono occupato? Spero che sia urgente...",
  reward = "Innumerevoli volte ho esortato il Capoguerra a non fidarsi degli umani, ma qui in gioco non c'è l'orgoglio personale.$B$BHai servito la Horde con onore, giovane $C.$B$BOra scusami, devo consigliare Thrall su queste faccende immediatamente...",
  en_title = "The Admiral's Orders",
  en_obj = "Deliver Admiral Proudmoore's Orders to Nazgrel in Thrall's chamber in Orgrimmar.",
}
T[832] = {
  title = "Ombre ardenti",
  desc = "<Parole emanano dal pendente e giungono nella tua mente.>$B$BGazz'uz?$B$BGazz'uz... rapporto!$B$BCorre voce della tua scoperta a Skull Rock. Devi prepararti a un attacco!$B$BGazz'uz, ti ordino di parlare! Parla o farò in modo che Neeru Fireblade sappia della tua presenza, e si abbatterà su di te con rapida brutalità.$B$BNon mettere alla prova le tue capacità contro Neeru...$B$B...Gazz'uz, ci sei...?",
  obj = "Porta quest'occhio a Neeru Fireblade.",
  progress = "Hai qualcosa di vitale da riferire. Lo percepisco dietro i tuoi occhi.",
  reward = "<Esamina l'Eye of Burning Shadow>$B$BInteressante. La voce che hai sentito ha menzionato il mio nome? Sono noto per dare la caccia ai nemici del nostro Capoguerra, ma... è strano che io sia stato preso di mira. Ancora più strano che i cultisti della Burning Blade, a cui hai sottratto questo pendente, abbiano un nome così simile al mio.$B$BDevo studiare questo pendente. Devo studiare e ponderare il significato del suo messaggio.$B$BGrazie per averlo portato alla mia attenzione, $N. Hai reso un grande servizio al tuo popolo.",
  en_title = "Burning Shadows",
  en_obj = "Take this eye to Neeru Fireblade.",
}
T[833] = {
  title = "Una sepoltura sacra",
  desc = "Solo i tauren più valorosi vengono sepolti a Red Rocks, il nostro sacro cimitero. È un onore concesso ai grandi guerrieri che hanno aiutato a fondare e difendere Thunder Bluff e a coloro che hanno dato la vita per il bene più grande delle loro tribù e dei loro capi.$B$BMa pare che una turpe minaccia sia penetrata nella nostra terra santa. Una banda di Bristleback Interlopers sta devastando il luogo di sepoltura e io sono troppo vecchio e oltre il mio massimo splendore per scacciarli.$B$BDevono essere cacciati con la forza, $n.",
  obj = "Lorekeeper Raintotem vuole che tu uccida 8 Bristleback Interlopers a Red Rocks.",
  progress = "I Bristleback Interlopers devono essere scacciati dal nostro sacro cimitero, $n.",
  reward = "Ben fatto. Hai mandato a quei turpi Bristleback un messaggio chiaro. Ci penseranno due volte prima di tentare di nuovo di profanare questo luogo sacro.",
  en_title = "A Sacred Burial",
  en_obj = "Lorekeeper Raintotem wants you to kill 8 Bristleback Interlopers at Red Rocks.",
}
T[834] = {
  title = "Venti nel deserto",
  desc = "Sono Rezlak, uno dei ragazzi di Gazlowe. Il capo mi ha mandato ad aiutare gli orchi qui in Durotar. Le cose andavano bene, tranne che per le carovane. Non riesco a tenerle al sicuro! Mi rende il lavoro un po' più difficile, sai?$B$BL'ultimo carico, che avevano promesso sarebbe arrivato, è stato rapito dalle arpie Dustwind di... com'era... Razorwind Canyon?$B$BMi servono quei rifornimenti o non combinerò mai niente! Segui il grande canyon verso sud: troverai il burrone che si apre nelle pareti a ovest e a est.",
  obj = "Recupera 5 Sacks of Supplies e riportali a Rezlak vicino a Orgrimmar.",
  progress = "Sono bravo in quello che faccio, non fraintendermi, ma questa è assurda! Che dovrei fare, castelli di sabbia?",
  reward = "Ehi, ma guarda un po'! Hai recuperato i nostri rifornimenti. Ottimo. Potrò rimettermi al lavoro non appena troverò qualcuno che mi porti questi sacchi.",
  en_title = "Winds in the Desert",
  en_obj = "Retrieve 5 Sacks of Supplies and return them to Rezlak near Orgrimmar.",
}
T[835] = {
  title = "Mettere in sicurezza le linee",
  desc = "Gazlowe una volta mi disse: \"Rezlak. C'è una sola cosa che devi sapere nella vita: se vuoi che una cosa sia fatta bene, falla da te.\"$B$BNon posso permettermi di perdere tutte le nostre carovane, quindi prenderò in mano la situazione. Drygulch Ravine si trova nella parte orientale di Razorwind Canyon. Se uccidiamo tutte le arpie là, le rotte saranno sicure.$B$BNaturalmente Gazlowe mi ha insegnato anche un'altra cosa: \"Tutto si può ottenere, per il giusto prezzo.\" Allora, mi darai una mano, $n?",
  obj = "Uccidi 12 Dustwind Savages e 8 Dustwind Storm Witches per Rezlak vicino a Drygulch Ravine.",
  progress = "Non lo diresti da uno come il mio capo Gazlowe, ma ha sempre saputo come va il mondo. \"Non aver paura di fare il grande passo\", diceva.$B$BLe arpie non smetteranno di darci fastidio e le carovane non smetteranno di essere attaccate, a meno che non facciamo qualcosa, eh?",
  reward = "Credo di poter finalmente tirare un sospiro di sollievo, ora che le arpie non daranno più noia alle nostre carovane. E non un attimo troppo presto! Pare che con la prossima spedizione mi arriveranno dei bei giocattolini!$B$BSei davvero in gamba, $N: dovresti cercare il mio capo a Ratchet. Scommetto che avrebbe del lavoro per te.$B$BAh, e non preoccuparti, non dimenticherò di pagarti per il servizio che mi hai reso.",
  en_title = "Securing the Lines",
  en_obj = "Kill 12 Dustwind Savages and 8 Dustwind Storm Witches for Rezlak near Drygulch Ravine.",
}
T[837] = {
  title = "Invasione",
  desc = "Quando siamo arrivati, i quilboar Razormane possedevano gran parte di queste terre e si sono rivelati una spina nel fianco. Con i nostri sforzi abbiamo scacciato la maggior parte di loro, ma in alcune zone restano ben fortificati.$B$BÈ andata avanti anche troppo, però. Per la nostra sicurezza, non possiamo permettere ai Razormane alcun dominio sulle nostre terre. I loro accampamenti si trovano a ovest di qui. Cerca i rovi e li troverai. Oggi li cacciamo dal Durotar, domani, forse, da tutto Kalimdor.",
  obj = "Uccidi 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners e 4 Razormane Battleguards per Gar'Thok a Razor Hill.",
  progress = "Sebbene possiedano una certa intelligenza e organizzazione, trovo sempre sorprendente che i quilboar siano riusciti a conquistare e tenere tanto territorio a Kalimdor. Forse sono un nemico più astuto di quanto credessi...",
  reward = "Farò sapere che i quilboar sono stati scacciati dalle loro tane e che le loro strutture possono essere date alle fiamme. La rimozione dei Razormane dal Durotar ci avvicina a rendere sicuri i confini della nostra nuova patria.",
  en_title = "Encroachment",
  en_obj = "Kill 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners and 4 Razormane Battleguards for Gar'Thok at Razor Hill.",
}
T[840] = {
  title = "Coscritto dell'Orda",
  desc = "Hmm, sembri piuttosto forte.$B$BAscolta, il mio buon amico Kargal ha bisogno di nuove reclute per il servizio nei Barrens. So che vuoi fare ciò che è giusto per l'Orda. Bene, questa è la tua occasione.$B$BPorta questa lettera di reclutamento a Kargal e vedi se la firma.",
  obj = "Segui la strada occidentale da Razor Hill fino ai Barrens, oltre un ponte.$B$BFermati all'avamposto orco dall'altra parte del ponte.$B$BConsegna la tua lettera di reclutamento a Kargal Battlescar all'avamposto dei Barrens.",
  progress = "Che vuoi, cucciolo? Se non sei qui per l'arruolamento, non ho tempo per te.",
  reward = "Oh, quindi ti ha mandato Takrin? È un ottimo esploratore, non so cosa farei senza di lui.$B$BFirmerò la tua lettera di reclutamento, ma quello che ci serve davvero è qualcuno ai Crossroads.",
  en_title = "Conscript of the Horde",
  en_obj = "Follow the western road from Razor Hill to the Barrens over a bridge.$B$BStop at the orc outpost across the bridge.$B$BGive Kargal Battlescar at the Barrens outpost your recruitment letter.",
}
T[842] = {
  title = "Coscrizione ai Crossroads",
  desc = "Porta questa lettera di reclutamento firmata ai Crossroads.$B$BSergra Darkthorn, che la pelle le si rovini, comanda là. È una sciamana pestifera che ti farà girare la testa a forza di parole prima di lasciarti fare qualcosa di utile. Thrall è convinto che sia speciale, ma io non ne sono così sicuro.$B$BDovrai giudicare da te, cucciolo...",
  obj = "Segui la strada occidentale da Kargal's Far Watch Outpost.$B$BAll'incrocio a T, svolta a sinistra e segui la strada verso sud.$B$BTrova Sergra Darkthorn all'incrocio delle strade dentro i Crossroads.",
  progress = "Ma guarda un po' chi abbiamo qui! Kargal mi ha ritenuta degna di un'altra recluta?",
  reward = "Bene, $N. Vuoi guadagnarti il pane con l'Orda? C'è parecchio da fare qui, quindi ascolta bene e fa' ciò che ti viene detto.$B$B$GVedo quello sguardo nei tuoi occhi, non pensare che tollererò insolenze. Thrall in persona ha dichiarato che le femmine dell'Orda sono pari a voi uomini. Mancami di rispetto anche solo un poco e conoscerai il vero dolore.:Sono felice di averti incontrata. Thrall sarà lieto di sapere che altre femmine come noi prendono l'iniziativa per avanzare nei Barrens.;",
  en_title = "Crossroads Conscription",
  en_obj = "Follow the western road from Kargal's Far Watch Outpost.$B$BAt the T intersection, turn left and follow the road south. $B$BFind Sergra Darkthorn at the crossing of roads within the Crossroads.",
}
T[843] = {
  title = "La riconquista di Gann",
  desc = "In solitudine percorro queste strade.$B$BI nani di Bael Modan non mostrano rispetto per la mia terra. Esplosioni orrende aprono buche profonde nel terreno mentre macchine rumorose fanno a pezzi le colline. Terre che un tempo erano casa e sostentamento per la mia tribù sono ora crivellate di nani distruttori.$B$BI tentativi di arrivare a una soluzione diplomatica sono falliti. È il momento di un'azione decisiva.$B$BCaccia i nani dallo scavo di Bael Modan con la forza e portami il diario del loro capo, Prospector Khazgorm.",
  obj = "Gann Stonespire vuole che tu uccida 15 Bael'dun Excavator e 5 Bael'dun Foreman.$B$BPorta Khazgorm's Journal a Gann Stonespire.",
  progress = "Molti tauren innocenti hanno perso la vita o sono stati cacciati dalla terra dei loro avi quando sono arrivati i nani di Bael Modan. La mia terra va riconquistata!",
  reward = "Khazgorm ha incontrato la sorte che si era guadagnato. Non provo rimorso per quello sciocco. Era un infedele su queste terre.$B$BChe la sua morte serva da monito a tutti quelli che minacciano di sconvolgere il nostro modo di vivere.$B$BOra lasciami un momento per studiare il diario del nano...",
  en_title = "Gann's Reclamation",
  en_obj = "Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.$B$BBring Khazgorm's Journal to Gann Stonespire.",
}
T[844] = {
  title = "La minaccia dei Plainstrider",
  desc = "La tua prima preda sarà facile.$B$BI plainstrider a est stanno molestando le nostre scorte di cibo e sono diventati un fastidio.$B$BAbbatti i plainstrider e torna da me con i loro becchi.",
  obj = "Raccogli 7 Plainstrider Beaks e riportali a Sergra Darkthorn ai Crossroads.",
  progress = "Hai raccolto i becchi dei plainstrider?",
  reward = "Molto bene, $N. Senza i plainstrider sarà più facile mantenere intatte le nostre linee di rifornimento. E spero che tu abbia imparato qualche trucco là fuori nei Barrens, perché la tua prossima preda ha un po' più di fuoco nel sangue dei plainstrider...",
  en_title = "Plainstrider Menace",
  en_obj = "Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads.",
}
T[845] = {
  title = "Gli Zhevra",
  desc = "Gli zhevra, pur non essendo le bestie più feroci dei Barrens, sono un po' più coriacei dei plainstrider. Non temere: a tempo debito ti manderemo contro prede più grosse, ma per ora i tuoi denti hanno bisogno di un po' più di affilatura.$B$BCaccia gli zhevra a nord e a sud e raccogli i loro zoccoli. Portameli e forse poi ti manderemo contro qualcosa di più duro.",
  obj = "Uccidi gli Zhevra Runners per raccogliere 4 Zhevra Hooves per Sergra Darkthorn ai Crossroads.",
  progress = "Quanti zhevra hai ucciso?",
  reward = "Non male, $N. Quegli zhevra hanno una gran forza nelle zampe. Un calcio ben assestato può far finire a terra persino un tauren!$B$BSembra che anche tu abbia della forza. Sei pront$Go:a; per una vera sfida?",
  en_title = "The Zhevra",
  en_obj = "Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads.",
}
T[846] = {
  title = "La vendetta di Gann",
  desc = "È chiaro che il cercatore contava sugli esplosivi e su quei veicoli rumorosi per fare a pezzi il terreno. C'è da aspettarsi che presto prenda il comando un nuovo caposquadra.$B$BVoglio ripagare i nani con la loro stessa moneta. Secondo questi piani, se combiniamo nitroglicerina con pasta di legno e nitrato di sodio possiamo creare una carica esplosiva. Pare che i fucilieri, i soldati e gli ufficiali del Keep abbiano il materiale.$B$BRaccogli questa roba e portamela. Fabbricherò una carica che i nani non dimenticheranno!",
  obj = "Gann Stonespire vuole che tu gli porti 6 fiale di Nitroglycerin, 6 fasci di Wood Pulp e 6 campioni di Sodium Nitrate.",
  progress = "Vedo che sei $Gtornato:tornata;, $N.$B$BAnche se la morte di Khazgorm ritarderà un po' gli scavi nelle terre dei miei avi, non metterà certo fine del tutto alla distruzione.$B$BIl Keep di Bael Modan è una minaccia militare sempre più grande. Costruito per difendere il sito di scavo, ora è pronto anche a farsi forza d'attacco.$B$BSe hai gli ingredienti che ti ho chiesto, posso fabbricare una carica che farà ripensare ai nani frettolosi quello che stanno facendo qui nelle Barrens.",
  reward = "Vedo che sei molto $Gindustrioso:industriosa;, $C.$B$BSenza dubbio avremo presto una bella sorpresa per quei nani.",
  en_title = "Revenge of Gann",
  en_obj = "Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate.",
}
T[847] = {
  title = "L'astuzia del raptor",
  desc = "Questo... questo potere... È questo il potere degli sciamani che Tor'gan ha cercato di mostrarmi? Devo ammettere che è interessante. Di' a Tor'gan che mi ha convinto... per il momento. Ascolterò quello che ha da dire.",
  obj = "Parla con Tor'gan.",
  reward = "Quando l'incantesimo svanirà, parlerò con Gor'mul. Ti ringrazio per avermi aiutato a riportare Gor'mul nel mondo dei vivi. Non ho dubbi che anche lui ti sia molto grato.",
  en_title = "Guile of the Raptor",
  en_obj = "Speak with Tor'gan.",
}
T[848] = {
  title = "Spore fungine",
  desc = "Le oasi dei Barrens nascondono un mistero. Un'energia vitale scorre dalle loro acque, rinvigorendo le piante e le bestie che ne bevono.$B$BRinvigorendo, e alterando.$B$BVicino a queste oasi cresce un fungo. Le sue spore hanno proprietà che noi, gli speziali di Lordaeron, troviamo utili.$B$BPortami queste spore e ti guadagnerai la nostra gratitudine.",
  obj = "Porta 4 Fungal Spores a Apothecary Helbrim ai Crossroads.",
  progress = "Hai le spore, $N? C'è una miscela che devo inviare al mio socio a Thunder Bluff, e per prepararla servono le spore...",
  reward = "Ah, sì. Sono ottimi esemplari. Potenti.$B$BSono un Reietto, e noi onoriamo i nostri contratti. Ecco la tua ricompensa, $N.",
  en_title = "Fungal Spores",
  en_obj = "Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads.",
}
T[849] = {
  title = "La vendetta di Gann",
  desc = "Seguendo i piani di Khazgorm non dovrebbe essere un problema fabbricare una carica esplosiva.$B$BAh, ecco fatto.$B$BOra, $N, ti affiderò un incarico speciale. Prendi questo candelotto esplosivo e usalo per far saltare la macchina volante a Bael Modan.$B$BLa macchina volante non è solo un pezzo fondamentale dell'infrastruttura del sito: serve anche come arma da guerra. E soprattutto è un simbolo di potere e un insulto alla memoria della mia tribù.$B$BRendimi fiero portando a termine questa impresa eroica, e sarai $Gricompensato:ricompensata;.",
  obj = "Distruggi la macchina volante a Bael Modan e torna da Gann Stonespire.",
  progress = "Una volta distrutta la macchina volante dei nani, proverò la dolce soddisfazione della vendetta.",
  reward = "Hai fatto bene, $N! Che a Thunder Bluff tu sia $Gonorato:onorata; come chi difende le terre sacre dei tauren e come $Gcampione:campionessa; della tribù perduta.",
  en_title = "Revenge of Gann",
  en_obj = "Destroy the flying machine at Bael Modan and return to Gann Stonespire.",
}
T[850] = {
  title = "I capi dei Kolkar",
  desc = "I centauri affliggono i Tauren da anni. E di recente i centauri Kolkar dei Barrens sono diventati una vera minaccia. Di solito erano disorganizzati in queste terre, ma tra loro sono sorti nuovi capi. Che li radunano.$B$BPer preservare i nostri possedimenti qui, questi capi centauri devono essere distrutti.$B$BPortami la testa di Barak Kodobane. Si accampa vicino a Forgotten Pools, a nord.$B$BSconfiggilo, poi torna da me.",
  obj = "Porta Barak's Head a Regthar Deathgate, a ovest dei Crossroads.",
  progress = "Salute, $N. Hai con te Barak's Head?",
  reward = "Ben fatto, $N. I centauri sono creature bestiali e meschine, ma alcuni hanno l'ingegno e la visione per guidare. E quelli sono i più pericolosi.$B$BBarak era uno di loro. È un bene che sia morto.",
  en_title = "Kolkar Leaders",
  en_obj = "Bring Barak's Head to Regthar Deathgate, west of the Crossroads.",
}
T[851] = {
  title = "Verog il Derviscio",
  desc = "Il centauro Verog il Derviscio vaga per i Barrens e sarà difficile da trovare. Ma ha la sua base alla tenda di comando dei centauri presso Stagnant Oasis, a sud-est. Forse è possibile attirarlo da te.$B$BRecati a Stagnant Oasis, a sud-est, e attacca i centauri vicino alla tenda di comando. Sarà pericoloso, ma se ne uccidi abbastanza daranno l'allarme. E Verog verrà.$B$BPortami la sua testa e la metterò accanto a quella di Barak Kodobane.",
  obj = "Porta Verog's Head a Regthar Deathgate, a ovest dei Crossroads.",
  progress = "Hai trovato Verog, $N?",
  reward = "Molto bene. Devi aver agitato parecchio quei centauri: le nostre guardie hanno notato attività nei pressi di Stagnant Oasis, probabilmente eri tu.$B$BDovresti essere orgoglios$Go:a; della tua impresa, $N. C'è molto coraggio in te.",
  en_title = "Verog the Dervish",
  en_obj = "Bring Verog's Head to Regthar Deathgate, west of the Crossroads.",
}
T[852] = {
  title = "Hezrul Bloodmark",
  desc = "Hezrul Bloodmark è il capo dei centauri Kolkar nei Barrens. È feroce, brutale e astuto. Sconfiggerlo disgregherebbe e spezzerebbe i Kolkar, riducendo di molto la loro minaccia per noi.$B$BQuindi uccidilo. Come per Barak e Verog, portami Hezrul's Head.$B$BGuida il suo popolo da Lushwater Oasis, a sud.",
  obj = "Porta Hezrul's Head a Regthar Deathgate, a ovest dei Crossroads.",
  progress = "Hezrul è stato sconfitto, $N?",
  reward = "Mi complimento con te, $N. Questi centauri sono indisciplinati e non sanno concentrare la loro rabbia come gli orchi, ma sono comunque feroci. Sconfiggendoli hai dimostrato il tuo valore.",
  en_title = "Hezrul Bloodmark",
  en_obj = "Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads.",
}
T[853] = {
  title = "Apothecary Zamah",
  desc = "Ho trasformato le spore che mi hai dato in un'emulsione. Ora devo inviarla alla mia socia, Apothecary Zamah. Se la porterai a lei, ti offrirà qualcosa dalle nostre scorte di beni alchemici.$B$BSi trova nei Pools of Vision, una caverna sotto gli sciamani di Thunder Bluff. Il sentiero per questa caverna è ben nascosto, ma lo troverai sull'altura di Spirit Rise.$B$BSbrigati. Questa emulsione manterrà la sua potenza solo per poco tempo e deve essere risigillata e lavorata prima.",
  obj = "Porta la Rendered Spores a Apothecary Zamah a Thunder Bluff, prima che scada il tempo.",
  progress = "Hai qualcosa da parte di Apothecary Helbrim?",
  reward = "Ah, le spore dei Barrens che Helbrim stava raccogliendo. Ha richiesto il tuo aiuto per consegnarle? Bene.$B$BE l'emulsione è ancora potente, quindi non devi aver perso tempo nella consegna. Ben fatto, $C.",
  en_title = "Apothecary Zamah",
  en_obj = "Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.",
}
T[854] = {
  title = "Viaggio ai Crossroads",
  desc = "Avevo previsto il tuo arrivo, giovane $c. Anche se forse non sei più così giovane.$B$BPenso sia giunto il momento che tu ti addentri in questa terra. Sento che sei destinat$Go:a; a grandi cose.$B$BDevi cercare i Crossroads, perché le nostre vite con quelle degli orchi si sono intrecciate ed essi hanno bisogno di aiuto. Continua lungo questa strada verso est e seguila a nord fino ai Crossroads. Trova Thork tra le sue mura: ha la benedizione della Madre Terra.",
  obj = "Parla con Thork ai Crossroads nei Barrens.",
  reward = "È bello vedere che altri alleati $R sono venuti ad aiutarci da luoghi lontani come Thunder Bluff. Ancora una volta, ti do il benvenuto.",
  en_title = "Journey to the Crossroads",
  en_obj = "Speak with Thork at the Crossroads in the Barrens.",
}
T[855] = {
  title = "Bracciali dei centauri",
  desc = "I Kolkar sono una minaccia per le pretese dell'Orda nei Barrens: dobbiamo ridurre il numero delle loro truppe. Per questo ho una taglia per te.$B$BMentre sei nei territori dei Kolkar, uccidi i loro guerrieri e raccogli bracciali di centauro. Torna quando ne avrai un bel mucchio e l'Orda ti ricompenserà bene.",
  obj = "Porta 15 Centaur Bracers a Regthar Deathgate, a ovest dei Crossroads.",
  progress = "Come va la caccia, $N?",
  reward = "Ben fatto. Sono certo che hai seminato la paura tra i centauri sopravvissuti, $N. Se hanno buon senso, ora si calmeranno e cesseranno le loro avanzate.$B$BMa non credo che lo faranno, ed è un peccato.$B$BUn peccato... per loro.",
  en_title = "Centaur Bracers",
  en_obj = "Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads.",
}
T[857] = {
  title = "La Tear of the Moons",
  desc = "Il potere era mio! Proprio nelle mie mani! E lo rivoglio! Lo rivoglio, ti dico!$B$BQuegli sporchi scavatori l'hanno portata alla luce... com'era bella. La chiamarono la Tear of the Moons, fu la prima grande scoperta che facemmo a Bael Modan.$B$BDoveva essere mia! Mia, ti dico!$B$BGeneral Twinbraid diventò geloso del potere che mi dava. La chiuse a chiave nel Keep. Disse che era maledetta! Lo sciocco!$B$BAltri la volevano e bisognava fermarli! Quel bastardo di Twinbraid mi ha cacciato via.$B$BOra lo rivoglio. Lo rivoglio, ti dico!",
  obj = "Feegly the Exiled vuole che tu recuperi per lui la Tear of the Moons.",
  progress = "Dov'è la Tear of the Moons? Mi serve adesso! Mi serve, ti dico!",
  reward = "Finalmente il potere è di nuovo mio! Mio, ti dico!",
  en_title = "The Tear of the Moons",
  en_obj = "Feegly the Exiled wants you to retrieve for him the Tear of the Moons.",
}
T[858] = {
  title = "Accensione",
  desc = "Non è che ti ha mandato Sputtervalve? Sono in un guaio. Sono salito senza accorgermi che serve una chiave per sbloccare la colonna di comando del shredder. Un altro operatore di shredder mi ha chiesto se andava tutto bene e io sono andato nel panico! Invece di dirgli che mi mancava la chiave, gli ho detto che c'era un qualche problema meccanico.$B$BDobbiamo andarcene di qui alla svelta! Sali alla sala di controllo in cima al derrick, il supervisore dovrebbe avere una chiave per questo shredder.$B$BAiutami!",
  obj = "Ottieni la Ignition Key e portala a Wizzlecrank.",
  progress = "Presto, dobbiamo andarcene prima che qualcuno si insospettisca!",
  reward = "Sì, questa sembra la chiave giusta. Fammi solo assicurare di saper far funzionare questo coso...$B$BHmm... controllo della rotazione... questo regola velocità e stabilità... controllo fine del braccio. Guarda qua! Non riesco a credere che la Venture Company abbia saputo progettare qualcosa di tanto migliore del nostro. Devo riportarlo a Ratchet!",
  en_title = "Ignition",
  en_obj = "Get the Ignition Key and bring it to Wizzlecrank.",
}
T[860] = {
  title = "Sergra Darkthorn",
  desc = "Se desideri percorrere la via del cacciatore, il tuo cammino porta ai Barrens. Le sue bestie sono testarde e feroci. Cacciando laggiù imparerai molto, e il tuo spirito crescerà.$B$BParla con Sergra Darkthorn. Sarà la tua prima guida nei Barrens.$B$BSergra si trova al Crossroads. Per raggiungerla, viaggia verso est da Bloodhoof Village fino ai Barrens, poi verso nord alla biforcazione della strada. E fai attenzione durante il viaggio: i Barrens nascondono grandi pericoli per chi è impreparat$Go:a; e incaut$Go:a;.",
  obj = "Parla con Sergra Darkthorn al Crossroads.",
  reward = "Vuoi cacciare nei Barrens?$B$BI tuoi occhi sono ansiosi e giovani. Non sono ancora socchiusi per aver inseguito la preda attraverso le aride pianure di questa terra.$B$BMa non temere. Tempreremo il tuo corpo e la tua mente. E ti insegneremo che la caccia è molto più che trovare e uccidere la preda.$B$BPreparati. Il tuo viaggio comincia. Ora.",
  en_title = "Sergra Darkthorn",
  en_obj = "Speak with Sergra Darkthorn at the Crossroads.",
}
T[861] = {
  title = "La via del cacciatore",
  desc = "Sei ansios$Go:a; di esplorare, lo vedo. Anch'io un tempo provavo la brama di vagare...$B$BVagare, e cacciare. Perché la caccia è il più grande onore di un Tauren.$B$BSe desideri davvero seguire la via del cacciatore, Melor Stonehoof può mostrarti il cammino. Si trova a Thunder Bluff, sulla Hunter's Rise.$B$BE per mostrargli la tua abilità e la tua determinazione, portagli gli artigli dei Flatland Prowler del Mulgore. Sono duri e astuti: una preda degna di un giovane $C sulla via del cacciatore.",
  obj = "Porta 4 Flatland Prowler Claws a Melor Stonehoof a Thunder Bluff.",
  progress = "Salute. C'è un'aria intorno a te che mi dice molto. Abbiamo degli affari da sbrigare, io e te?",
  reward = "Skorn Whitecloud è un saggio tauren. Ha cacciato per anni e anni e, benché il suo corpo sia vecchio, il suo spirito arde con forza. Siamo onorati di averlo con noi.$B$BSe Skorn ti ha mandato da me, allora anche tu devi avere lo spirito del cacciatore. E aver raccolto questi artigli dimostra la tua abilità nascente.$B$BForse sei pronto$Go:a; a percorrere la via.",
  en_title = "The Hunter's Way",
  en_obj = "Bring 4 Flatland Prowler Claws to Melor Stonehoof in Thunder Bluff.",
}
T[862] = {
  title = "Dig Rat Stew",
  desc = "$GUn:Una; $C come te deve avere parecchia fame qui nelle Barrens. Io muoio di fame tutto il giorno.$B$BFacciamo così: ti preparo un bello stufato. Mi servono solo un po' di Dig Rat.$B$BPare che quei sudici nani di Bael Modan siano invasi dal banchetto preferito da tutti. Ora scendi a sud fino a Bael Modan e riportami un po' di Dig Rat.$B$BNon puoi dirti $Gun avventuriero esperto:un'avventuriera esperta; finché non hai passato un po' di tempo ad ammazzare ratti! Ah!",
  obj = "Porta 8 Dig Rat a Grub, a est del Crossroads.",
  progress = "Hai già fatto fuori abbastanza Dig Rat, $N?",
  reward = "Di solito non mi piace mangiare questi roditori quando sono così... così... maturi. Mi piace lasciarli marcire per qualche settimana, per far uscire davvero il sapore. Ma sembri così $Gaffamato:affamata;.$B$BLascia che ti prepari un po' di Dig Rat Stew. Ah, ecco fatto.$B$BEcco a te!",
  en_title = "Dig Rat Stew",
  en_obj = "Bring 8 Dig Rats to Grub east of the Crossroads.",
}
T[863] = {
  title = "La fuga",
  desc = "Suppongo che imparerò strada facendo... Non può essere troppo difficile. Qualche pulsante qui, una leva o due... Bene, sei pront$Go:a; a partire?",
  obj = "Proteggi Wizzlecrank e lo shredder goblin rubato lungo la strada verso Sputtervalve a Ratchet.",
  progress = "Posso aiutarti?",
  reward = "Spero che riusciremo a ricavare qualcosa di valore dal prototipo di shredder distrutto... il mio tempo sta per scadere! Manderò subito una squadra di recupero dove si trova Wizzlecrank.$B$BOh, lascia che ti dia qualcosa anche per il disturbo.",
  en_title = "The Escape",
  en_obj = "Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet.",
}
T[865] = {
  title = "Corna di raptor",
  desc = "I raptor dei Barrens sono più intelligenti di quelli delle altre terre. E io penso che tutta quell'intelligenza si nasconda nelle loro corna! Se è così, potrei ridurre le corna in polvere e usarla per fare \"bevande dell'intelligenza\". Potrei venderle a peso d'oro!!!$B$BE tu puoi aiutarmi. Trovami delle corna di raptor intatte dagli Sunscale Scytheclaw. Vagano nei Barrens meridionali e nei Barrens settentrionali, vicino al confine con Ashenvale Forest.",
  obj = "Raccogli 5 Intact Raptor Horns dagli Sunscale Scytheclaw e portale a Mebok Mizzyrix a Ratchet.",
  progress = "Hai preso le corna, $N? Quelle cose mi faranno ricco!",
  reward = "Ottimo, le hai prese! Ora devo solo macinarle e mescolarle con un po' di vino, e poi...",
  en_title = "Raptor Horns",
  en_obj = "Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet.",
}
T[866] = {
  title = "Root Samples",
  desc = "Le erbe delle Barrens non sono proprio come quelle di altre terre. Le loro proprietà sono quasi le stesse, ma l'acqua delle oasi di qui altera le piante: sono appena un po' diverse.$B$BVoglio studiare quelle differenze... per vedere se si possono sfruttare!$B$BSe te ne intendi di erbalismo, raccogli dei Root Sample dalle erbe che trovi nelle Barrens. Portami questi campioni, così posso confrontarli con le erbe di altre regioni.",
  obj = "Porta 8 Root Sample a Mebok Mizzyrix, a Ratchet.",
  progress = "Ciao, $N. Hai preso quei Root Sample?",
  reward = "Sì sì, questi sono molto belli! Da queste radici coltiverò degli esemplari e li studierò. Spero di scoprirne proprietà nuove. Proprietà nascoste, preziose...!$B$BE non preoccuparti: se le trovo, sarai $Gil primo:la prima; a saperlo. Perché mi servirà qualcuno che ne raccolga altri!",
  en_title = "Root Samples",
  en_obj = "Bring 8 Root Samples to Mebok Mizzyrix in Ratchet.",
}
T[867] = {
  title = "Predatrici arpie",
  desc = "Quelle maledette arpie saccheggiano le provviste delle nostre carovane da troppo tempo. È ora di tagliare qualche gola e di ridurre il loro numero.$B$BHo curiosato attorno ai loro nidi e ho capito chi comanda chi. L'attacco più devastante distruggerà buona parte della loro catena di comando inferiore, e poi potremo risalire fino in cima.$B$BTi farò iniziare con calma: elimina le Witchwing Harpy e le Witchwing Roguefeather a nordovest e portami 8 Witchwing Talon. Dovrebbe essere un buon inizio...",
  obj = "Raccogli 8 Witchwing Talon.$B$BPortali a Darsok Swiftdagger al Crossroads.",
  progress = "Ne hai già fatte a pezzi abbastanza? Continua a tagliare e a prendere trofei. Voglio 8 Witchwing Talon.",
  reward = "Oh, sono belli. Davvero belli... Ottimo lavoro, $N. Non vedo l'ora di assistere ad altre tue imprese.",
  en_title = "Harpy Raiders",
  en_obj = "Collect 8 Witchwing talons.$B$BReturn them to Darsok Swiftdagger at the Crossroads.",
}
T[868] = {
  title = "Caccia alle uova",
  desc = "Ehi, $N. Mi hanno mandato al Crossroads a sorvegliare la terra e a prendere nota di quello che ci succede, per i miei padroni a Orgrimmar.$B$BUno degli oggetti dei miei studi sono quelle creature simili a insetti che si trovano a sud, nel Field of Giants. Sappiamo poco di quelle creature, e io ci tengo a scoprirne di più. Sembrano avere una loro intelligenza, più di qualunque animale normale.$B$BPrendi questo Digging Claw e raccogli qualcuna delle uova delle creature dai loro cumuli, ma sta' $Gattento:attenta;: se le allarmi, ti attaccano.",
  obj = "Porta 12 Silithid Egg e il Digging Claw a Korran, al Crossroads.",
  progress = "Sta' $Gattento:attenta; con le uova che trovi, $N. Se si rompono, per me non valgono niente.",
  reward = "Sono soddisfatto di te, $N. Le uova e l'attrezzo. Ben fatto.$B$BE per la tua ricompensa...",
  en_title = "Egg Hunt",
  en_obj = "Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.",
}
T[869] = {
  title = "Ladri di raptor",
  desc = "Non molto tempo fa un carico d'argento è stato rubato dalla nostra torre di guardia. Era destinato alla paga delle guardie del Crossroads, e rivogliamo quell'argento.$B$BLa cosa strana è che... abbiamo catturato uno dei ladri la notte del furto. Ed era... un raptor! Incredibile!$B$BNon so cosa se ne facciano i raptor dell'argento. Ma non mi importa: voglio quei raptor morti, così non ci deruberanno più!$B$BCaccia i raptor nei Barrens. Portami le loro teste!",
  obj = "Porta 12 Raptor Head a Gazrog al Crossroads.",
  progress = "Hai quelle teste, $N?",
  reward = "Ti sei sbarazzat$Go:a; dei raptor!$B$BGrazie, $N. Sei un $C di valore.",
  en_title = "Raptor Thieves",
  en_obj = "Bring 12 Raptor Heads to Gazrog at the Crossroads.",
}
T[870] = {
  title = "Le Forgotten Pools",
  desc = "Molto tempo fa i Barrens erano un luogo rigoglioso, pieno di vita. Ma guerra e cataclismi imperversarono sulla terra, bruciandola e lasciandone un guscio arido. Così vanno le cose, e questo mi rattrista il cuore.$B$BEppure, negli ultimi anni, nei Barrens si sono formate nuove oasi, e la vita si risveglia. E nel profondo noi druidi avvertiamo un potere che si fa strada verso la superficie.$B$BDobbiamo trovarne la fonte. Recati alle Forgotten Pools, a nordovest del Crossroads. Cerca nelle loro acque l'origine di quel potere, poi torna qui.",
  obj = "Riferisci le tue scoperte a Tonga Runetotem.",
  progress = "Sei stat$Go:a; alle Forgotten Pools, $N? Hai trovato qualcosa?",
  reward = "Hai trovato una fenditura nella terra, da cui sgorgano dei gas? Strano. Potrebbe essere una risposta alle nostre domande, ma non possiamo ancora esserne certi.$B$BÈ comunque un indizio. E ti sono grato per averlo trovato.",
  en_title = "The Forgotten Pools",
  en_obj = "Report back to Tonga Runetotem with your findings.",
}
T[871] = {
  title = "Fermare gli attacchi",
  desc = "Tutti i quilboar sono nostri nemici, $N. Alcuni però si rivelano una seccatura maggiore di altri.$B$BLa tribù dei Razormane attacca le nostre linee di rifornimento dal Durotar, causandoci guai senza fine. Ho degli esploratori sulle tracce del capo di queste incursioni, ma fino ad allora ogni perdita che potrai infliggere a quegli sporchi uomini-porco ci sarà d'aiuto.$B$BComincia a nordest, verso il Durotar. Riconoscerai le loro tane dai giganteschi rampicanti spinosi che spuntano dalla terra. Cercali e uccidili.",
  obj = "Della tribù dei Razormane, uccidi 8 Water Seeker, 8 Thornweaver e 3 Hunter, poi torna da Thork al Crossroads.",
  progress = "Più tempo ci vorrà per fermare questi attacchi, più sarà difficile rifornire la gente del Crossroads.",
  reward = "Hai fatto bene, $N. Quegli insolenti quilboar impareranno finalmente che la potenza dell'Orda non va ignorata.",
  en_title = "Disrupt the Attacks",
  en_obj = "Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads.",
}
T[872] = {
  title = "La fine degli attacchi",
  desc = "Uno dei miei esploratori ha assistito all'attacco a una carovana proveniente dal Durotar, $N. I colpevoli sono davvero i quilboar della tribù dei Razormane. Uno di loro in particolare guida le incursioni: Kreenig Snarlsnout. È stato visto a nordest di qui, appena a sud della strada del Durotar. Per porre fine alla minaccia, Kreenig deve morire.$B$BPer essere certi che gli attacchi cessino, però, io dico di aggiungere la beffa al danno. Uccidi Kreenig insieme ad altri della sua tribù e torna da me quando avrai la sua zanna.",
  obj = "Uccidi 8 Razormane Geomancer, 8 Razormane Defender e Kreenig Snarlsnout.$B$BPoi porta la Kreenig Snarlsnout's Tusk a Thork al Crossroads.",
  progress = "Taglia la testa al loro capo e scoppia il caos, $N. Impara bene questa lezione. Ti sarà utile in futuro.$B$BI cinghiali annasperanno senza una guida, e potremo riprenderci i Barrens.",
  reward = "Ben fatto, $N. Con la morte di Kreenig, gli attacchi alle nostre carovane caleranno di sicuro.$B$BIl tuo popolo dovrebbe essere fiero di annoverarti tra i suoi.",
  en_title = "The Disruption Ends",
  en_obj = "Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout.$B$BThen bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads.",
}
T[873] = {
  title = "Isha Awak",
  desc = "Il grande Isha Awak è signore di queste acque. Grande è la sua forza, e solenne il suo orgoglio. Gli umani sulla costa lo temono, perché ne ha divorati molti.$B$BMa io non lo temo. Sono grata che sia qui. È una sfida degna, e una preda onorevole.$B$BSe sei $Gpronto:pronta;, allora nuota al largo e cerca Isha Awak, il Deep Doom.$B$BIl suo spirito dimora nel suo cuore, e sentirne il battito è conoscere il proprio destino.",
  obj = "Porta l'Heart of Isha Awak a Mahren Skyseer.",
  progress = "Non temere le acque, $R.",
  reward = "Ora sei una cosa sola con Isha Awak, $N. Il suo spirito è con te. Si acquatta nei tuoi occhi...$B$BOcchi che, un giorno, impareranno a vedere.",
  en_title = "Isha Awak",
  en_obj = "Bring the Heart of Isha Awak to Mahren Skyseer.",
}
T[874] = {
  title = "Mahren Skyseer",
  desc = "Hai cacciato le bestie delle Barrens. Il tuo spirito è forte. Ma un cacciatore deve essere sempre pronto. Un vero cacciatore sa inseguire la preda per qualunque sentiero. Montagne e paludi non $Glo:la; faranno vacillare.$B$BE nemmeno il mare.$B$BTrova mia sorella, Mahren. Caccia le grandi bestie d'acqua lungo la costa. Sarà lei a insegnarti le loro vie.$B$BMa sta' $Gattento:attenta; mentre la cerchi, perché la costa delle Barrens è in mano agli umani.",
  obj = "Parla con Mahren Skyseer.",
  reward = "Ti manda mio fratello, vero? Allora devi esserti $Gguadagnato:guadagnata; la sua stima. Se hai ottenuto il rispetto di Jorn, hai anche il mio.$B$BSei $Gpronto:pronta; a percorrere ancora la via del cacciatore?",
  en_title = "Mahren Skyseer",
  en_obj = "Speak with Mahren Skyseer.",
}
T[875] = {
  title = "Tenenti arpia",
  desc = "Hahaha, $N. Sei tornat$Go:a; per averne ancora? Bene, mi piace sentirlo.$B$BQuesta volta voglio che tu assassini alcuni tenenti delle arpie nelle Dry Hills. Solo le Witchwing Slayer possono essere tenenti, e le riconoscerai dagli anelli che portano. Sono una masnada schifosa, ma comandano parte dei subalterni della zona. Eliminarne 6 sarà un colpo decisivo al loro matriarcato.$B$BAssicurati che muoiano tra atroci dolori, $N. Vogliamo che quelle arpie sappiano quanto è stupido attaccare briga con l'Orda.",
  obj = "Raccogli 6 Harpy Lieutenant Ring dalle Witchwing Slayer e riportali a Darsok Swiftdagger al Crossroads.",
  progress = "Hai già 6 Harpy Lieutenant Ring? Giustizia deve essere fatta per i loro attacchi spietati contro l'Orda.",
  reward = "Eccellente lavoro, amico mio. Penso che andrai lontano nell'Orda.",
  en_title = "Harpy Lieutenants",
  en_obj = "Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads.",
}
T[876] = {
  title = "Serena Bloodfeather",
  desc = "Te la sei cavata così bene con i tenenti e i subalterni che vorrei chiederti un'ultima cosa.$B$BSerena Bloodfeather è la sorella di un'arpia chiamata Bloodfeather, uccisa da Rexxar parecchio tempo fa. A quanto pare, questi attacchi alle carovane dell'Orda sono una vendetta per la morte di sua sorella.$B$BDevi tagliarle la gola e riportarmi la sua testa. Voglio metterla sulla prossima carovana che manderemo... Diamo a quelle arpie qualcosa su cui riflettere.",
  obj = "Uccidi Serena Bloodfeather e riporta la sua testa a Darsok Swiftdagger al Crossroads.",
  progress = "Non avrai nulla finché non vedrò la testa di Serena.",
  reward = "HA! Ben fatto, $N! Molto ben fatto... Non ero sicuro che fossi all'altezza, ma ti sei dimostrat$Go:a; un vero tagliagole. Grazie ancora per averci aiutato a reprimere l'epidemia di arpie. Ecco la tua ricompensa, usala bene.",
  en_title = "Serena Bloodfeather",
  en_obj = "Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads.",
}
T[877] = {
  title = "La Stagnant Oasis",
  desc = "Come quella che hai trovato alle Forgotten Pools, potrebbero esserci fenditure anche nelle altre oasi dei Barrens. Se è così, forse le fenditure sono la fonte di vita delle oasi.$B$BDobbiamo metterlo alla prova.$B$BPrendi questi semi. Sono morti e sterili, ma portali alla Stagnant Oasis a sudest. Se laggiù c'è una fenditura, collocali dentro... e osserva.",
  obj = "Torna da Tonga al Crossroads dopo aver investigato la Stagnant Oasis.",
  progress = "Sei stat$Go:a; alla Stagnant Oasis? C'era una fenditura sotto le sue acque?",
  reward = "Le tue scoperte sono sorprendenti! I semi che ti ho dato erano secchi e morti. Qualunque cosa riposi sotto queste oasi può creare vita dal nulla!$B$BDobbiamo studiare meglio la faccenda...",
  en_title = "The Stagnant Oasis",
  en_obj = "Return to Tonga at The Crossroads, after investigating the Stagnant Oasis.",
}
T[878] = {
  title = "Tribù in guerra",
  desc = "Devi colpire i miei nemici. <grugnito> Devi aiutare Mangletooth e i Razormane indebolendo i Bristleback. Tutte e due le tribù sono molto spirituali — legate alla terra e al suo potere. <grugnito> Ci dà forza in ogni cosa... soprattutto in guerra.$B$BSe vuoi scoprire chi causa davvero a Thork <grugnito> e all'Orda tanto tormento, allora aiuta Mangletooth! Attacca i capi spirituali dei Bristleback a nord; indeboliscili, così i Razormane potranno sconfiggerli e dominare le Barrens.",
  obj = "Uccidi 6 Bristleback Water Seeker, 12 Bristleback Thornweaver e 12 Bristleback Geomancer, poi torna da Mangletooth a Camp Taurajo, nelle Barrens.",
  progress = "Altre informazioni <grugnito> per l'Orda quando avrai ucciso i saggi dei Bristleback, $R. <grugnito> Non un momento prima! Mangletooth non è uno sciocco.",
  reward = "Sì, sì... pieno di gioia perché finalmente <grugnito> i Bristleback conoscono il dolore della mia tribù, $R. Così dovrei sentirmi, ma <grugnito> non è così.$B$BTu aiuti la tua gente e loro ti onorano. Mangletooth aiuta la sua gente, e loro che fanno? Gli voltano le spalle. Lo dimenticano e lo lasciano marcire in gabbia!$B$BIo li aiuto perfino da qui, chiuso dietro le sbarre, e loro non mandano nessuno a salvarmi!",
  en_title = "Tribes at War",
  en_obj = "Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens.",
}
T[879] = {
  title = "Tradimento dall'interno",
  desc = "Tre della mia tribù sono usciti dal Kraul per guidare le incursioni contro l'Orda, $R. <grugnito> Sono spietati e astuti, e se li sconfiggi, allora il tuo Crossroads e perfino gran parte delle Barrens conosceranno la pace... <grugnito> almeno da parte della tribù Razormane. <grugnito>$B$BNak, Kuz e Lok Orcbane sono quelli che cerchi. Sono molto a sud delle Barrens. Uno è un incantatore, un altro un battitore, e il loro capo, quello che chiamano Orcbane, <grugnito> un guerriero. Uccidili, $R, come hanno ucciso me.",
  obj = "Uccidi Nak, Kuz e Lok Orcbane e porta i loro teschi a Mangletooth, a Camp Taurajo, nelle Barrens.",
  progress = "Come va la tua caccia, $R? <grugnito>$B$BThork crede di sapere la verità su chi guida le incursioni contro la sua gente, <grugnito> ma imparerà quanto si sbaglia, se riesci nell'impresa.$B$BLa mia morte è inevitabile, ma tu hai causato grande dolore ai miei nemici, quindi Mangletooth non rimpiange nulla. <grugnito>",
  reward = "È fatta, allora. Meglio che finisca così, dice Mangletooth. <grugnito> Avrebbero dovuto <grugnito> assicurarsi che fossi morto quando mi hanno voltato le spalle, invece di lasciarmi <grugnito> qui in questa gabbia maledetta.$B$BResta un solo incarico da portare a termine, $R.",
  en_title = "Betrayal from Within",
  en_obj = "Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.",
}
T[880] = {
  title = "Esseri alterati",
  desc = "Le tue scoperte sono incredibili, $N. Queste oasi possiedono proprietà che devono provenire da una fonte esterna. O forse interna.$B$BVoglio sapere come queste fenditure influenzano le bestie che bevono l'acqua delle oasi.$B$BCaccia gli oasis snapjaw alle Lushwater e Stagnant Oasis. Portami i loro gusci, così che io possa esaminarli.",
  obj = "Porta 8 Altered Snapjaw Shell a Tonga Runetotem al Crossroads.",
  progress = "Come procede la raccolta? Hai preso i gusci?",
  reward = "Grazie, $N. Studiare le bestie di un luogo può rivelare molto sul luogo stesso. Vedremo quale storia raccontano questi gusci.$B$BAccetta la mia gratitudine per il tuo aiuto... e forse puoi usare queste monete. Io non ne ho bisogno.",
  en_title = "Altered Beings",
  en_obj = "Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.",
}
T[881] = {
  title = "Echeyakee",
  desc = "Whitemist, Echeyakee nella lingua dei Tauren, è il re dei felini della savana. Caccia con tale furtività che si dice sia come una sottile nebbia bianca sulla terra. E uccide così in fretta che le sue prede non hanno il tempo di provare paura, né dolore.$B$BI Tauren dicono che sia insieme misericordia e morte.$B$BScoprirai se è vero, perché ora ti pongo sulla strada della caccia a Echeyakee. La sua tana si trova a nordest del Crossroads, tra le ossa di giganteschi Kodo.$B$BVai. Soffia in questo corno quando raggiungerai la sua tana. Soffia nel corno, ed egli verrà.",
  obj = "Porta la Echeyakee's Hide a Sergra Darkthorn al Crossroads.",
  progress = "Il grande felino ti chiama, $N.",
  reward = "Hai sconfitto Echeyakee e, sebbene i suoi giorni di caccia siano finiti... il suo spirito è con te. Ti mostrerà la forza che si trova nella sottigliezza e l'onore che c'è nella misericordia.$B$BLa tua strada è ancora lunga, $C. Speriamo che tu la percorra bene.",
  en_title = "Echeyakee",
  en_obj = "Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads.",
}
T[882] = {
  title = "Ishamuhale",
  desc = "Ishamuhale, Speartooth, è il più feroce raptor Sunscale dei Barrens. Non caccia per sport, né per fame. Caccia perché la caccia è la sua passione. Uccide perché è nella sua natura uccidere.$B$BE tu imparerai la sua natura, $N, perché ora il tuo cammino segue le tracce artigliate di Ishamuhale.$B$BDai inizio alla caccia. Uccidi la sua preda preferita, una zhevra, poi porta la carcassa all'albero morto a nordovest di Ratchet. Ishamuhale sentirà l'odore della carcassa e ne sarà attirato.$B$BSii pronto$Go:a; quando arriverà.",
  obj = "Porta la Ishamuhale's Fang a Jorn a Camp Taurajo.",
  progress = "$N, hai sconfitto Ishamuhale?",
  reward = "Questa zanna è solo un simbolo, ma ciò che rappresenta è profondo.$B$BLa forza di Ishamuhale è in te, $N. Possa tu usarla con temperanza. Questo è il tuo fardello.$B$BQuesto è il tuo onore.",
  en_title = "Ishamuhale",
  en_obj = "Bring Ishamuhale's Fang to Jorn at Camp Taurajo.",
}
T[883] = {
  title = "Lakota'mani",
  desc = "L'Hoof of Lakota'mani è simbolo della forza del grande kodo.",
  obj = "Porta l'Hoof of Lakota'mani a Jorn, a Camp Taurajo.",
  progress = "$N, quando ti sei $Gavvicinato:avvicinata; ho visto un potere nuovo nel tuo passo. Dimmi — il tuo spirito ha incontrato il grande Lakota'mani?",
  reward = "Lakota'mani nella nostra lingua si chiama \"Earthshaker\", e i suoi passi sono come tuono raccolto. Ora è con te, e il suo coraggio si mescola al tuo. Insieme non c'è scontro che non possiate affrontare.$B$BCammina a testa alta, $N. Cammina a testa alta, Earthshaker.",
  en_title = "Lakota'mani",
  en_obj = "Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo.",
}
T[884] = {
  title = "Owatanka",
  desc = "Al tocco, dalla spina della coda di Owatanka volano scintille.",
  obj = "Porta Owatanka's Tailspike a Jorn, a Camp Taurajo.",
  progress = "$N, c'è un potere nuovo dietro i tuoi occhi! Hai incontrato il possente Owatanka, non è vero?",
  reward = "Il thunder lizard Owatanka è chiamato \"Bluebolt\" dai tauren, perché dentro di lui risiede una velocità che smentisce la sua mole. Si dice che un fulmine abbia colpito Bluebolt molto tempo fa e che, nutrita dall'ira del cielo, l'energia della grande bestia sia senza limiti.$B$BChe la sua energia scorra in te, $N. Perché ora tieni il passo di Owatanka.",
  en_title = "Owatanka",
  en_obj = "Bring Owatanka's Tailspike to Jorn at Camp Taurajo.",
}
T[885] = {
  title = "Washte Pawne",
  desc = "La piuma di Washte Pawne fa male al tatto.",
  obj = "Porta Washte Pawne's Feather a Jorn Skyseer, a Camp Taurajo.",
  progress = "C'è una nuova determinazione dentro di te, $N. Una determinazione nata dal dolore...$B$BTi pesa la morte di Washte Pawne?",
  reward = "Il thunderhawk è una bestia rara delle Barrens, e la sua morte può presagire grande fortuna, o grande rovina.$B$BMa Washte Pawne, chiamato \"Spirit Biter\" in Taurahe, non può portare né l'una né l'altra... o tutte e due.$B$BIl dolore che hai provato cacciando Spirit Biter è la fitta che provano tutti quelli che ottengono molto a caro prezzo. La stretta che hai sentito è il dolore del rimpianto.$B$BMa vedo che l'hai superata. Hai imparato che il rimpianto diventa saggezza, e che attraverso il dolore si guadagna forza.$B$BHai imparato molto, $N.",
  en_title = "Washte Pawne",
  en_obj = "Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo.",
}
T[886] = {
  title = "Le oasi del Barrens",
  desc = "I druidi di Thunder Bluff avvertono uno strano potere che filtra nel Barrens, a est di Mulgore.$B$BTonga Runetotem è stato mandato a scoprirne la fonte, ma temiamo che abbia bisogno di aiuto.$B$BRecati nel Barrens e parla con Tonga. Lo troverai al Crossroads. Per raggiungerlo, prendi la strada verso est fuori dal villaggio di Bloodhoof. Entra nel Barrens, poi svolta a nord quando la strada si biforca. Prosegui verso nord e troverai il Crossroads.$B$BE non abbandonare la strada, $N, perché il Barrens è una terra aspra.",
  obj = "Parla con Tonga Runetotem al Crossroads.",
  reward = "I miei fratelli di Thunder Bluff hanno fatto bene a mandarti, giovane $C. Il mistero del Barrens è uno che non posso sciogliere da solo.$B$BCon il tuo aiuto, speriamo di trovare risposta alle nostre domande.",
  en_title = "The Barrens Oases",
  en_obj = "Speak with Tonga Runetotem at the Crossroads.",
}
T[887] = {
  title = "I filibustieri di Southsea",
  desc = "Vorrei proprio che il Vice Admiral Grezzlik facesse un lavoro migliore nel tenere sicuri i mari per le nostre navi mercantili. Con tutto l'oro che i principi mercanti hanno versato nelle Trade Fleets, mi manda in bestia vedere tanti pirati scorrazzare impuniti, razziare le mie navi e rubare le mie merci!$B$BHo sentito che i Southsea Freebooters hanno messo un accampamento appena a sud di qui. Sono una vera spina nel fianco e, se Grezzlik non si occupa di loro, beh, forse puoi aiutarmi tu a sbarazzarmene.",
  obj = "Uccidi 12 Southsea Brigands e 6 Southsea Cannoneers per Gazlowe a Ratchet.",
  progress = "Non voglio nemmeno pensare ai profitti persi per le razzie dei pirati, e ora si accampano pure sulla mia porta? La situazione sta sfuggendo di mano, Undermine deve fare qualcosa.",
  reward = "Hai fatto un buon lavoro, ragazzo. Ancora un po' di lavoro così e sarà una preoccupazione in meno per me. Speriamo che si convincano a trasferire altrove le loro operazioni.$B$BNel frattempo, resta la piccola questione di riprendermi le merci che mi hanno rubato!",
  en_title = "Southsea Freebooters",
  en_obj = "Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet.",
}
T[888] = {
  title = "Il bottino rubato",
  desc = "Vorrei recuperare tutte le mie merci, ma so che non è possibile. Eppure ci sono un paio di cose di cui ho assolutamente bisogno!$B$BVedi, il mio osservatorio è pronto, ma gli serve la più piccola delle due lenti. La prima è arrivata con una carovana da Durotar, ma la seconda viaggiava per nave e non è mai arrivata. Inoltre non ho mai ricevuto il mio carico di stivali da Drizzlik a Booty Bay!$B$BVai all'accampamento dei pirati e vedi se riesci a trovarli.",
  obj = "Recupera la Shipment of Boots e la Telescopic Lens per Gazlowe a Ratchet.",
  progress = "Hai trovato le mie cose, $N?",
  reward = "È un sollievo riavere tutta questa roba, quindi grazie per l'aiuto, $N. Sai, mi servirebbe un$Go:a; $R come te per dare una mano con le mie attività qui. Se mai cerchi lavoro, non dimenticare quanto bene Gazlowe paga per i servigi resi!",
  en_title = "Stolen Booty",
  en_obj = "Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet.",
}
T[889] = {
  title = "Spirito del vento",
  progress = "Portami 10 blood shards a Mangletooth e ti benedirò con grande velocità. Correrai con le zhevra e il vento sarà geloso di te.$B$BNon durerà a lungo, ma dovrebbe bastare ad aiutarti a viaggiare per tutto il Barrens.",
  reward = "Bene. Va' con lo spirito di Agamaggan come guida, $R. Torna da me se desideri altra magia di Agamaggan.",
  en_title = "Spirit of the Wind",
}
T[890] = {
  title = "Il carico scomparso",
  desc = "Aspetto da una vita il mio ultimo carico di merci da Booty Bay! Sono quasi certo che sia stato rubato dai Freebooters, ma per esserne sicuro, vorresti andare giù al molo e chiedere a Dizzywig se per caso le mie merci sono già state messe nel mio magazzino a mia insaputa?$B$BTieni, porta il mio registro a Dizzywig e fagli controllare i miei inventari con i suoi registri.",
  obj = "Porta il Gazlowe's Ledger a Wharfmaster Dizzywig.",
  progress = "Merci da spedire con la prossima nave, $N?",
  reward = "Ah, ti manda Gazlowe, eh? Un momento, do un'occhiata ai miei registri per assicurarmi di non aver mandato il carico di Gazlowe nel posto sbagliato.$B$BScommetto che sta aspettando quegli stivali da Drizzlek...",
  en_title = "The Missing Shipment",
  en_obj = "Bring Gazlowe's Ledger to Wharfmaster Dizzywig.",
}
T[891] = {
  title = "I cannoni di Northwatch",
  desc = "Un'altra nave della mia flotta è andata perduta per colpa di quegli umani troppo zelanti a Northwatch Hold!$B$BQuei bastardi vanno fermati. La loro paranoia li ha ridotti in uno stato di frenesia. Zoticoni spericolati dal grilletto facile, sparano a tutto ciò che hanno nel mirino.$B$BViaggia verso sud lungo la Merchant Coast fino al Hold e assedia le loro forze. Portami le medaglie dei loro soldati come prova. E per amore della mia flotta, uccidi Captain Fairmount e i suoi cannonieri troppo zelanti!",
  obj = "Captain Thalo'thas Brightsun di Ratchet vuole che tu raccolga 10 Theramore Medals e uccida Captain Fairmount, Cannoneer Whessan e Cannoneer Smythe.",
  progress = "La mia flotta è in pericolo, con Captain Fairmount e i suoi maledetti cannonieri che sparano da Northwatch Hold. Voglio che anche i suoi soldati paghino. Riempimi la mano con le medaglie dei loro morti e saprò che i miei corsari caduti sono stati vendicati.",
  reward = "Ahimè, i giusti cannoni dell'Alleanza sono stati messi a tacere. Sarai ricompensat$Go:a; per il tuo aiuto, $N.$B$BOra devo occuparmi del triste compito di recuperare i corpi dei caduti...",
  en_title = "The Guns of Northwatch",
  en_obj = "Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe.",
}
T[892] = {
  title = "Il carico scomparso",
  desc = "Dai miei registri è tutto in regola, $n. Torna da Gazlowe e digli che è sfortunato. Non mi stupirei se fossero stati i pirati a ghermire le sue merci.$B$BNon posso fare altro per lui. Ah... potresti dirgli che ho delle cose da Undermine per lui, quando avrà tempo di venirle a ritirare.",
  obj = "Riporta il Gazlowe's Ledger a Gazlowe a Ratchet.",
  progress = "Allora, che cos'ha detto Dizzywig?",
  reward = "Niente da fare, eh? Dev'essere stato per forza opera dei Freebooters, allora... Dizzywig è onesto, sono sicuro che non mi imbroglierebbe così. Dopotutto, è sul mio libro paga.$B$BSembra che ci sia della merce da riprendere, $N. Che ne dici?",
  en_title = "The Missing Shipment",
  en_obj = "Return Gazlowe's Ledger to Gazlowe in Ratchet.",
}
T[893] = {
  title = "Armi preferite",
  desc = "I quilboar Razormane a sud, oltre il Field of Giants, non hanno fabbri esperti, da quel che mi risulta, ma a quanto pare hanno cominciato a mettere a punto armi più robuste. Vorrei mettere le mani su qualche tipo diverso, per imparare le loro tecniche, se possibile.$B$BSe vuoi portare onore all'Orda, allora portami degli esemplari delle loro armi. Trovami un pugnale dai loro Stalker, una bacchetta dai loro Seer e uno scudo dai loro Warfrenzy. Sarebbe perfetto!",
  obj = "Porta un Razormane Backstabber, un Charred Razormane Wand e un Razormane War Shield a Tatternack Steelforge, a Camp Taurajo, nelle Barrens.",
  progress = "Anch'io dubito che quei patetici quilboar possano raggiungere un qualche livello di abilità nella forgiatura, ma faccio come comanda il Capoguerra, e imparerò quello che posso sulla tribù Razormane.$B$BHo avuto incarichi più umili di questo, e li svolgo volentieri se servono al popolo degli orchi.",
  reward = "Esemplari eccellenti, davvero eccellenti.$B$BI quilboar sono più avanti di quanto mi aspettassi.$B$BEcco, $C, prendi questo e togliti di mezzo. È meglio che dia un'occhiata più attenta a queste armi. Potremmo aver sottovalutato il nemico, ed è il tipo di errore che non possiamo permetterci.",
  en_title = "Weapons of Choice",
  en_obj = "Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.",
}
T[894] = {
  title = "Samophlange",
  desc = "La Venture Company ha allestito una piccola struttura di ricerca molto a nord di qui, a sudovest del Sludge Fen. Non so molto di ciò che stanno facendo, ma sono riuscito a scoprire che stanno sperimentando qualcosa chiamato \"samophlange\".$B$BOra, che diamine è un samophlange? Beh, qualunque cosa sia, voglio esaminarlo, quindi mi serve qualcuno che vada a prenderlo.$B$BHo ottenuto una copia del manuale operativo del loro sistema di controllo: dovresti riuscire a capire da lì come disinnestare il samophlange.",
  obj = "Accedi alla console di controllo nel sito di ricerca della Venture Company.",
  reward = "Pulsanti, leve e luci lampeggianti sono disposti in modo piuttosto caotico sulla facciata della console di controllo. Un piccolo indicatore segnala che l'apparato funziona entro livelli ottimali e che le valvole di controllo da uno a tre sono attualmente aperte. Sul lato inferiore destro del pannello di controllo c'è una piccola serratura.",
  en_title = "Samophlange",
  en_obj = "Access the control console at the Venture Company research site.",
}
T[895] = {
  title = "RICERCATO: Baron Longshore",
  desc = "RICERCATO!$B$BBaron Longshore, Capitano della Heedless$B$BIl Capitano Longshore di Gilneas guida le navi dei Southsea Freebooters ed è ricercato con l'accusa di pirateria. I resti devono essere in condizioni riconoscibili!$B$B-- Gazlowe",
  obj = "Porta la testa di Baron Longshore a Gazlowe a Ratchet.",
  progress = "Che succede? Posso aiutarti in qualcosa? Merci da spedire, magari un lavoro di ingegneria?",
  reward = "Ahhhh! Quel genere di affari. Sai, una volta ho visto la Heedless in mare aperto. Una nave temibile, o era una barca... questi marinai sono così pignoli!$B$BComunque, vederla scivolare sull'acqua era uno spettacolo. Sono lieto che il suo infame capitano non darà più fastidio alle mie navi.",
  en_title = "WANTED: Baron Longshore",
  en_obj = "Bring the head of Baron Longshore to Gazlowe in Ratchet.",
}
T[896] = {
  title = "La fortuna del minatore",
  desc = "Essendo Wharfmaster di un porto trafficato come Ratchet, tengo sempre il dito sul polso delle informazioni. So tutto sugli scambi di merci e denaro tra qui e Booty Bay.$B$BL'ultima notizia che ho sentito riguarda la miniera Boulder Lode della Venture Company, a nordest del Sludge Fen. Uno dei minatori ha scoperto uno smeraldo grande quanto il tuo pugno. Conosco qualche acquirente che sarebbe interessato a mettere le mani su una cosa simile, e sarei disposto a dividere a metà il ricavato della vendita.",
  obj = "Recupera il Cats Eye Emerald da uno dei Venture Co. Overseers o Enforcers per Wharfmaster Dizzywig a Ratchet.",
  progress = "Se solo sapessimo quale dei minatori ha trovato lo smeraldo, sarebbe una passeggiata...",
  reward = "Guarda che dimensioni, $N! Saremo ricchi! Vediamo, in base ai prezzi che ho visto per le gemme dirette a Undermine, dovrei riuscire a calcolare la tua parte... il cinquanta per cento, non preoccuparti!$B$BOra vediamo... credo che questo dovrebbe andare bene. È stato un piacere fare affari con te, $N.",
  en_title = "Miner's Fortune",
  en_obj = "Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers for Wharfmaster Dizzywig at Ratchet.",
}
T[897] = {
  title = "The Harvester",
  desc = "Questa strana creatura simile a un insetto sembra fuori dall'ordine naturale, come se non appartenesse alle Barrens.",
  obj = "Porta l'Harvester's Head a Jorn Skyseer.",
  progress = "Sembravi $Gturbato:turbata;, $N. Come vanno le tue lezioni nelle Barrens? Hai trovato qualcosa che ti inquieta?",
  reward = "Non posso dire nulla della natura di questa bestia, perché il suo spirito è fuggito. Ma come avevi intuito, non appartiene alle Barrens. Temo che possa annunciare un futuro cupo per la nostra gente...$B$BMa per ora preparati, e speriamo che il tempo sciolga il mistero di questa creatura.",
  en_title = "The Harvester",
  en_obj = "Bring the Harvester's Head to Jorn Skyseer.",
}
T[898] = {
  title = "Liberi dal Hold",
  desc = "Finalmente! Qualcuno che mi salva!$B$BNon posso credere che tu sia passat$Go:a; oltre le guardie. Questi zelanti di Theramore sono fuori di testa. Hanno affondato la nostra nave e imprigionato me, l'unico sopravvissuto. Mi hanno chiamato nemico e minaccia per l'Alleanza.$B$BIo! Una minaccia per la loro grande farsa di Alleanza? Ero un mozzo su un trasporto di liquore di contrabbando tra Ratchet e Booty Bay.$B$BBasta chiacchiere. Aiutami a tornare a Ratchet, ti va? Dimmi quando sei pront$Go:a; e tenteremo la fuga.",
  obj = "Scorta in sicurezza Gilthares Firebough da Captain Brightsun a Ratchet.",
  progress = "Sì?",
  reward = "E pensare che credevamo Firebough morto da tempo!$B$BLe tue gesta eroiche ti hanno guadagnato un posto d'onore tra i Thalo'dan Privateers, $N.",
  en_title = "Free From the Hold",
  en_obj = "Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet.",
}
T[899] = {
  title = "Consumato dall'odio",
  desc = "Forse conosci il dolore dell'incertezza, forse no, $c. Ma sappi questo: sto qui ogni giorno, dall'alba al tramonto, scrutando l'orizzonte in cerca di altri di quei mostri. Da allora ho ucciso ogni uomo-porco che ho incontrato, ma la mia sete del loro sangue è ben lontana dall'essere placata. Forse invece di dirigermi a nord verso il Crossroads avrei dovuto andare a Taurajo.$B$BTu, $c... tu potresti aiutarmi.$B$BUccidili. Uccidine quanti più puoi. Portami le loro zanne e celebreremo insieme la loro morte.",
  obj = "Porta 60 Bristleback Quilboar Tusks a Mankrik al Crossroads.",
  progress = "I quilboar la pagheranno per questo, $N. Lo giuro.",
  reward = "$C, prendi sul serio il mio compito, e per questo ti ringrazio.$B$BAnche se il mio desiderio di vendetta resta, posso almeno sorridere vedendo che i quilboar hanno provato a loro volta il dolore.",
  en_title = "Consumed by Hatred",
  en_obj = "Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads.",
}
T[900] = {
  title = "Samophlange",
  desc = "Le tre valvole di controllo sono attualmente aperte. Le varie letture sul pannello di controllo ti portano a ritenere che vadano chiuse prima di poter spegnere l'apparato.",
  obj = "Chiudi la Fuel Control Valve, la Regulator Valve e la Main Control Valve, poi usa di nuovo la console di controllo.",
  progress = "Le luci lampeggianti sulla console di controllo indicano che le valvole di controllo principali non sono state chiuse.",
  reward = "Le luci che indicano le tre valvole di controllo si affievoliscono man mano che vengono chiuse. Il verde sfuma lentamente in giallo e l'interruttore che comanda l'apparato ora si muove: con le valvole chiuse, si può spegnere.",
  en_title = "Samophlange",
  en_obj = "Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.",
}
T[901] = {
  title = "Samophlange",
  desc = "Con l'apparato disattivato, il pannello di controllo può essere aperto e il samophlange rimosso dalla console. Con tutto il resto a posto, non resta che procurarsi la chiave per sbloccare la console.",
  obj = "Ottieni la Console Key da Tinkerer Sniggles da usare sulla console di controllo.",
  progress = "Le luci della console sono spente e gli indicatori e i quadranti segnano tutti zero, tutto è inattivo.",
  reward = "Giri la chiave nella serratura e la console di controllo si sblocca. Una luce rossa in cima alla console si spegne e tutta l'energia defluisce dal terminale.",
  en_title = "Samophlange",
  en_obj = "Get the Console Key from Tinkerer Sniggles to use on the control console.",
}
T[902] = {
  title = "Samophlange",
  desc = "Aprendo la facciata della console di controllo scopri un fitto groviglio di fili, tubi e strani oggetti meccanici, la maggior parte dei quali sembra non avere alcuna utilità pratica. Spostandoli da parte e scavando più a fondo nella console, trovi il samophlange. Con uno strattone lo estrai dal suo alloggiamento.",
  obj = "Riporta il Samophlange a Sputtervalve a Ratchet.",
  progress = "Oh, sei tornat$Go:a;, $N! Hai il samophlange?",
  reward = "È... ehm... interessante... sì. Lo farò spedire al quartier generale del Tinkers' Union a Undermine. Sono certo che, dopo un'attenta dissezione e qualche ricerca, riusciranno a capirci qualcosa.$B$BMa forse prima gli darò una piccola occhiata io stesso...",
  en_title = "Samophlange",
  en_obj = "Return the Samophlange to Sputtervalve in Ratchet.",
}
T[903] = {
  title = "Prowlers of the Barrens",
  desc = "Ora è tempo di dare la caccia a qualcosa che morde davvero. I prowler dei Barrens sono una razza tenace. Tenaci, pieni di risorse, astuti... e letali. Li troverai tra le erbe alte. Ne vedrai molti a sudovest del Crossroads.$B$BSta' in guardia mentre li cacci, $N, o potresti ritrovarti non più predatore, ma preda.",
  obj = "Raccogli 7 Prowler Claws dai Savannah Prowlers per Sergra Darkthorn al Crossroads.",
  progress = "Come procede la caccia, $N? Hai trovato i prowler?",
  reward = "Ah, vedo che sei stat$Go:a; impegnat$Go:a;, appostato tra le erbe a dare la caccia ai prowler. Credi dunque sia giunto il momento di affrontare un campione tra di loro?",
  en_title = "Prowlers of the Barrens",
  en_obj = "Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads.",
}
T[905] = {
  title = "Gli Scytheclaw infuriati",
  desc = "Ora, $N, la caccia si fa più profonda. Ora devi sconfiggere la tua preda e poi trovare la via fino alla sua tana.$B$BDai la caccia ai raptor Sunscale a sud. Uccidili e strappa le piume che portano. Poi posa le piume sui nidi degli Scytheclaw a sudovest della Stagnant Oasis. Mostra ai loro simili che non li temi!",
  obj = "Uccidi i raptor Sunscale e raccogli le loro piume. Usa le piume sui 3 nidi degli Scytheclaw. Torna da Sergra Darkthorn al Crossroads.",
  progress = "Sei stato ai nidi, $N?",
  reward = "Il tuo compito è finito? Rifletti sulla vita dello Scytheclaw mentre lo svolgi. In ogni creatura, per quanto breve sia la sua esistenza, ci sono lezioni importanti.$B$BAlcuni degli altri credono che io sia stato troppo pesante nella mia lezione. So che stai solo eseguendo i miei ordini, ma voglio che tu pensi alla vita delle creature che stai massacrando.$B$BSebbene a volte siano una seccatura, diventano pericolose solo quando siamo noi a cercarne la strage. La profanazione di oggi ci causerà più guai di quanti ne risolverà...",
  en_title = "The Angry Scytheclaws",
  en_obj = "Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads.",
}
T[906] = {
  title = "Tradimento dall'interno",
  desc = "Porta la testa di Lok a Thork, al Crossroads, $R. <grugnito> Dovrebbe capire cos'è successo alla mia tribù senza bisogno di parole — ah, non che crederebbe mai che Mangletooth abbia avuto parte <grugnito> in queste cose. Ma sono sicuro che ti ricompenserà per aver compiuto un'impresa simile. <grugnito>$B$BContinuerò a benedirti con il potere di Agamaggan finché resterò in questa gabbia, $R. Fino ad allora, addio.",
  obj = "Porta Lok's Skull a Thork, al Crossroads, nelle Barrens.",
  progress = "Sì, che c'è?",
  reward = "Hai trovato il capo dei Razormane e l'hai ucciso con le tue mani, $N? Straordinario.$B$BSono senza parole, ma questo non vuol dire che sia senza gratitudine. La gente del Crossroads farebbe bene a rispettare la tua forza.$B$BDevo ammetterlo: credevo che il capo di queste incursioni alle nostre linee di rifornimento fosse un altro quilboar. Grazie ancora, $N.",
  en_title = "Betrayal from Within",
  en_obj = "Bring Lok's Skull to Thork at the Crossroads in the Barrens.",
}
T[907] = {
  title = "Thunder Lizard infuriate",
  desc = "Ora, $N, devi affrontare i grandi thunder lizard. Queste bestie sono così enormi che il terreno rimbomba quando attraversano le pianure. Fa' attenzione mentre le combatti: un passo falso e potresti ritrovarti sotto i loro piedi.$B$BTroverai i thunder lizard nei Barrens meridionali. Sono noti come Stormsnout, Stormhide e Thunderhead. Torna da me dopo averli sconfitti.",
  obj = "Porta 3 Thunder Lizard Blood a Jorn Skyseer a Camp Taurajo.",
  progress = "I thunder lizard sono stati sconfitti, $N?",
  reward = "È bello vederti tornare con la prova della vittoria. Ed è bello sapere che ci sei riuscit$Go:a; con le ossa intatte.",
  en_title = "Enraged Thunder Lizards",
  en_obj = "Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo.",
}
T[908] = {
  title = "Tra le rovine",
  desc = "Il Martello del Crepuscolo si è insediato nelle Moonshrine Ruins delle Blackfathom Deeps. La sua presenza non può che costringere gli elementi a lavorare contro di noi. Se non lo fermiamo, questa regione sarà sua per sempre.$B$B$N, va' a Blackfathom e trova la Fathom Stone delle rovine; dovrebbe essere lì vicino, nell'acqua. Dentro c'è un Fathom Core, un congegno che, letto come si deve, racconta la storia di tutta l'attività elementale. Se l'avrò io, io e il Circolo della Terra potremo forse fare qualcosa per fermarlo!",
  obj = "Porta il Fathom Core a Je'neu Sancrea, allo Zoram'gar Outpost, in Ashenvale.",
  progress = "Sei $Griuscito:riuscita; a individuare il Fathom Core? Senza, non avremo idea di cosa stia combinando esattamente il Martello del Crepuscolo laggiù.",
  reward = "È esattamente quello che mi serve! Un Fathom Core è una fonte incredibile di informazioni, da cui potremo ricavare molto di buono. Qualunque cosa stia combinando il Martello del Crepuscolo là dentro — e credimi quando dico che non è niente di buono — io e i miei compagni ora la scopriremo.$B$BOggi qui hai fatto bene; il Circolo della Terra ti guarda con favore per averci aiutato. Hai aiutato anche l'Orda tutta, e di questo dovresti essere $Gfiero:fiera;.",
}
T[909] = {
  title = "Baron Aquanis",
  desc = "L'elementale dell'acqua sconfitto ha lasciato uno strano globo d'acqua. Immagini che l'oggetto alimentasse in qualche modo la bestia. Dentro il globo sciaborda un'acqua dall'aspetto putrido. Il globo in sé sembra impermeabile a qualsiasi forza fisica.$B$BSe c'è qualcuno che può venire a capo di questo oggetto, è Je'neu Sancrea del Circolo della Terra. Si trova allo Zoram'gar Outpost dell'Orda, in Ashenvale.",
  obj = "Porta lo Strange Water Globe a Je'neu Sancrea, allo Zoram'gar Outpost, in Ashenvale.",
  progress = "Ah, ciao di nuovo, $N. Stavo giusto leggendo le onde del mare, come faccio sempre. Cosa ti porta all'avamposto?",
  reward = "Questo... questo è proprio un bel ritrovamento, $N.$B$BDici di averlo preso a Baron Aquanis, a Blackfathom? Baron Aquanis è considerato da tempo una potenza elementale corrotta; questo globo dimostrerà che cosa esattamente lo abbia corrotto. Non sarebbe una sorpresa scoprire che è stato il Martello del Crepuscolo, ma i nostri studi mostreranno anche come ci è riuscito.$B$BHai fatto bene a portarmelo. Ti prego — prendi questo, insieme ai più calorosi saluti del Circolo della Terra.",
}
T[910] = {
  title = "Giù al porto",
  desc = "Ho sentito racconti sulle grandi navi che fanno la spola tra Ratchet e Booty Bay! Sarebbe fantastico navigare sull'oceano e combattere in tante grandi battaglie navali. Forse da grande sarò un grande marinaio dell'Orda! Sì!$B$BMi porteresti a vedere il porto di Ratchet, per piacere? Prometto che non entrerò in acqua e non combinerò guai: voglio solo vedere le navi grandi e sentire l'odore dell'acqua salata! Sì!",
  obj = "Porta il tuo protetto al porto di Ratchet, nelle Barrens.",
  progress = "Siamo arrivati?",
  reward = "Wow, l'oceano è ENORME! C'erano anche tanti gabbiani e roba del genere: è rumoroso e movimentato proprio come pensavo. E ci sono pure dei pirati qui vicino: troppo forte!$B$BGrazie di avermi portato a Ratchet, $N. È stato fantastico!",
  en_title = "Down at the Docks",
  en_obj = "Take your ward to the docks of Ratchet in the Barrens.",
}
T[911] = {
  title = "La porta della frontiera",
  desc = "Dicono che Ashenvale sia la nuova frontiera, e che il Mor'shan Rampart, nelle Barrens, ne sia la porta. Sarebbe fantastico essere un pioniere e ricavare tutto quello che ti serve dalle terre selvagge! Dicono che sarà lì che l'Orda e l'Alleanza si scontreranno di più in futuro, e io voglio esserci, $N!$B$BMi porteresti al Mor'shan Rampart, così vedo com'è la frontiera, per piacere? Voglio vedere dove l'Orda sta cacciando via quei puzzolenti elfi della notte!",
  obj = "Porta il tuo protetto al Mor'shan Rampart, nella parte settentrionale delle Barrens, poco prima di entrare ad Ashenvale.",
  progress = "Siamo arrivati?",
  reward = "Wow, è ad Ashenvale che si vivono le vere avventure! Hai mai combattuto ad Ashenvale, $N? Quando da grande diventerò un eroe, voglio venire ad Ashenvale a combattere per la gloria dell'Orda!$B$BGrazie di avermi portato alla frontiera, $N. Sei $Gil migliore:la migliore;!",
  en_title = "Gateway to the Frontier",
  en_obj = "Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale.",
}
T[912] = {
  title = "Stonesplinter Trogg Disguise",
}
T[913] = {
  title = "Il grido del Thunderhawk",
  desc = "Il thunderhawk, $N, è una bestia feroce. È ora che tu li affronti. Devi scoprire dove si aggira e portarmi le sue ali come prova della tua caccia riuscita.$B$BFallo, e il tuo tempo con me volgerà al termine.",
  obj = "Trova e uccidi un Thunderhawk, poi porta le sue ali a Jorn Skyseer a Camp Taurajo.",
  progress = "È fatta? Hai ucciso il thunderhawk?",
  reward = "Tu, come il thunderhawk, dovresti essere fier$Go:a;. Hai sconfitto ogni nemico che ti abbiamo posto davanti, e lo hai fatto con forza, coraggio e onore.$B$BMa il tuo cammino, $N, continua. Anzi, scoprirai che i veri cacciatori non smettono mai di migliorarsi, e percorrono per sempre la loro strada con lo stesso orgoglio che hai mostrato a me.$B$BOra è tempo di andare avanti.",
  en_title = "Cry of the Thunderhawk",
  en_obj = "Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo.",
}
T[914] = {
  title = "I capi dei Druids of the Fang",
  desc = "I druidi delle Wailing Caverns, i Druids of the Fang, sono un'aberrazione. Facevano parte di un ordine di nobili druidi il cui piano era guarire le Barrens, ma ora cercano di rifare quella terra a immagine dei loro sogni contorti.$B$BI Druids of the Fang hanno quattro capi, e ognuno possiede una gemma di sogno. Perfino adesso le loro facce mi perseguitano! Sconfiggi i capi e portami le loro gemme, e le Barrens potranno conoscere di nuovo la pace.$B$BVa', $N. Li troverai in agguato nel profondo delle Wailing Caverns.",
  obj = "Porta le Gems of Cobrahn, Anacondra, Pythas e Serpentis a Nara Wildmane, a Thunder Bluff.",
  progress = "I ricordi dei miei incubi mi perseguitano, $N. Hai sconfitto i capi dei Druids of the Fang e preso le loro gemme?",
  reward = "Ce l'hai fatta, $N. Hai ucciso i capi dei Druids of the Fang. I miei sogni ora sono liberi dalle loro facce malvagie, e hai contribuito a salvare le Barrens da un futuro maledetto.$B$BTi ringrazio, $N. Ti ringrazio per me, per i druidi di Thunder Bluff e per la terra.",
  en_title = "Leaders of the Fang",
  en_obj = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.",
}
T[915] = {
  title = "Tu gridi, io grido...",
  desc = "GELATO! Oh, per piacere per piacere per piacere, mi prendi un gelato?! La fragola è il mio gusto preferito, e al mondo non c'è gelato alla fragola migliore del Tigule and Foror's Strawberry Ice Cream! È il mio gelato preferito in tutto il mondo!$B$BL'ho mangiato una volta, tanto tempo fa, quando ero alla pista da corsa delle Shimmering Flats, ma ho sentito dire che adesso potrebbero venderlo in città! Per piacere? Per piacere per piacere? Con sopra il Tigule and Foror's Strawberry Ice Cream??!?!",
  obj = "Procura un po' di Strawberry Ice Cream al tuo protetto. Il ragazzo sembra preferire il gelato della marca di Tigule e Foror.",
  progress = "Vorrei che facessero altri gusti di gelato oltre alla fragola, ma immagino di essere fortunato, visto che la fragola è il mio preferito!",
  reward = "Mmmmmmmmm! Adoro il loro gelato alla fragola! Se c'è una cosa che Tigule e Foror sanno fare, è il gelato!$B$BGrazie mille, $N: è la cosa più buona di sempre!",
  en_title = "You Scream, I Scream...",
  en_obj = "Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.",
}
T[916] = {
  title = "Veleno dei Webwood",
  desc = "Sono venut$Go:a; a Shadowglen per osservare i ragni Webwood che abitano la Shadowthread Cave. Sono cugini di una varietà di ragni molto più piccola; credo che l'albero del mondo abbia avuto su di loro un effetto profondo, e vorrei dei campioni da studiare per confermarlo.$B$BPer prima cosa vorrei un po' del loro veleno. Raccogli le sacche di veleno Webwood dai ragni dentro e intorno alla Shadowthread Cave, a nord. Potrò così esaminarle e cercare somiglianze con il veleno dei loro cugini più piccoli.",
  obj = "Porta 10 Webwood Venom Sacs a Gilshalan Windwalker ad Aldrassil.",
  progress = "Hai raccolto le sacche di veleno, $N?",
  reward = "Grazie, $N. Quando tornerò a Darnassus confronterò il veleno contenuto in queste sacche con quello di altri ragni. Credo che abbia proprietà legate alla recente crescita del nostro nuovo albero del mondo.",
  en_title = "Webwood Venom",
  en_obj = "Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil.",
}
T[917] = {
  title = "Webwood Egg",
  desc = "Ora che ho il veleno dei ragni, vorrei degli esemplari vivi da studiare. Purtroppo catturare un ragno gigante vivo è più di quanto possa chiederti, giovane $C. E un ragno gigante è più di quanto potrei gestire io stess$Go:a;!$B$BMa se riesci a trovare un uovo non ancora schiuso, consegnare degli esemplari sarà molto più semplice, e potrò far custodire i piccoli ragni prima della schiusa.$B$BDeve esserci un nido nel profondo della Shadowthread Cave. Ti prego, cerca un uovo nel nido e portamelo.",
  obj = "Porta un Webwood Egg a Gilshalan ad Aldrassil.",
  progress = "Sei stat$Go:a; dentro la Shadowthread Cave, $N? Hai trovato un uovo di ragno?",
  reward = "Ah, benissimo. Farò trasportare questo uovo e il veleno a Darnassus, e tornerò laggiù quando i miei studi qui saranno terminati. Mi aspetto di scoprire moltissimo da questi esemplari, $N. Mi sei stat$Go:a; di grande aiuto.",
  en_title = "Webwood Egg",
  en_obj = "Bring a Webwood Egg to Gilshalan in Aldrassil.",
}
T[918] = {
  title = "Semi dei Timberling",
  desc = "I timberling di Teldrassil sono elementali della natura. In certi aspetti riflettono l'ordine naturale di piante e animali del nostro grande albero.$B$BPerciò è inquietante vedere quanto siano diventati furiosi.$B$BCredo che c'entri il terreno. Ho lavorato a diversi metodi per nutrire le piante e vorrei provarli sui semi dei timberling. Ti prego, puoi raccogliere i semi dai timberling intorno a Lake Al'Ameth e portarmeli?",
  obj = "Porta 8 Timberling Seeds a Denelan a Lake Al'Ameth.",
  progress = "Hai i semi? Non vedo l'ora di piantarli.",
  reward = "Ce l'hai fatta. Ottimo!$B$BPianterò questi semi nel terreno speciale che ho preparato. Credo che i semi germoglieranno in timberling molto più docili. Magari più avanti potrai vederne i risultati!",
  en_title = "Timberling Seeds",
  en_obj = "Bring 8 Timberling Seeds to Denelan at Lake Al'Ameth.",
}
T[919] = {
  title = "Germogli dei Timberling",
  desc = "Piccoli timberling stanno germogliando intorno alle acque di Lake Al'Ameth. Temo che questi germogli siano ormai perduti: dovremmo ripulire la terra da loro prima che crescano abbastanza da causare problemi.$B$BQuando ti aggiri intorno al lago, se vedi dei germogli di timberling, ti prego di prenderli. Aiutaci a tenere pulita la nostra terra!",
  obj = "Porta 12 Timberling Sprouts a Denalan a Lake Al'Ameth.",
  progress = "Salve, $N. Hai trovato dei germogli vicino alle acque?",
  reward = "Quanti! Temo che si stiano diffondendo a un ritmo pericoloso. Spero di riuscire a risolvere l'enigma di ciò che li sta corrompendo.$B$BGrazie per il tuo aiuto, $N. Grazie ai tuoi sforzi la terra è un posto più pulito.",
  en_title = "Timberling Sprouts",
  en_obj = "Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth.",
}
T[920] = {
  title = "La convocazione di Tenaron",
  desc = "$N, giusto? Ho sentito che Tenaron ti sta cercando. Lo troverai nella stanza più alta in cima ad Aldrassil.$B$BPotremo anche vivere a lungo, ma è meglio non farlo aspettare troppo.",
  obj = "Parla con Tenaron Stormgrip in cima ad Aldrassil, a Shadowglen.",
  reward = "Ah, $N. Speravo che avresti risposto con prontezza alla mia convocazione. Ho un compito importante che vorrei affidarti.",
  en_title = "Tenaron's Summons",
  en_obj = "Speak with Tenaron Stormgrip atop Aldrassil in Shadowglen.",
}
T[921] = {
  title = "La corona della Terra",
  desc = "È tempo che tu parta in cerca del tuo destino, $N. Ma prima di essere pront$Go:a; ad avventurarti nel mondo oltre le nostre foreste incantate, c'è molto che devi imparare sulla nostra storia recente.$B$BMolto è cambiato per il nostro popolo dopo la Battle of Mount Hyjal. Nordrassil è l'ombra pallida di ciò che era un tempo, il suo potere usato per sconfiggere Archimonde e respingere la Burning Legion...$B$BC'è un compito che devi svolgere. Va' al pozzo lunare a nord di Aldrassil e portami una fiala della sua acqua.",
  obj = "Riempi la Crystal Phial e riportala a Tenaron Stormgrip in cima ad Aldrassil.",
  progress = "I pozzi lunari contengono le acque del Well of Eternity, l'antica fonte di magia che ha causato tanti orrori nel nostro mondo.$B$BI druidi sfruttano le sue proprietà e le Sentinel venerano i pozzi come santuari di Elune, ma la stregoneria è proibita a tutti.",
  reward = "Dunque hai ascoltato la prima parte delle conseguenze della Battle of Mount Hyjal. C'è molto altro da raccontare, e il compito che hai iniziato qui proseguirà per tutto il tuo viaggio attraverso Teldrassil fino a Darnassus.",
  en_title = "Crown of the Earth",
  en_obj = "Fill the Crystal Phial and bring it back to Tenaron Stormgrip atop Aldrassil.",
}
T[922] = {
  title = "Rellian Greenspyre",
  desc = "$N, puoi portare uno dei semi che mi hai consegnato al mio amico Rellian Greenspyre? È un druido a Darnassus e, l'ultima volta che ci siamo parlati, ha mostrato interesse per il mio lavoro con i Timberling. Aveva anche alcune idee sue e gradirà un seme da usare per i suoi esperimenti.$B$BGrazie, $N. Mi sei stat$Go:a; di grande aiuto. Spero che un giorno vedrai i frutti del mio lavoro.$B$BDi solito troverai Rellian a passeggio lungo i sentieri del Cenarion Enclave a Darnassus.",
  obj = "Porta un Timberling Seed a Rellian Greenspyre a Darnassus.",
  progress = "Salve...$B$BE come posso aiutarti?",
  reward = "Ah, un seme di timberling? Volevo provare a farne crescere uno per aiutare Denalan con i suoi studi.$B$BMa temo di aver scoperto che una corruzione si è diffusa in molti timberling, e i semi di tali creature portano la macchia del loro genitore. Sono oltre le mie capacità di guarigione.$B$BDenalan è molto abile con ciò che cresce. Potrebbe trovare una cura per i futuri timberling. Potrebbe essere la loro unica speranza.",
  en_title = "Rellian Greenspyre",
  en_obj = "Bring a Timberling Seed to Rellian Greenspyre in Darnassus.",
}
T[923] = {
  title = "Tumori",
  desc = "Una malvagità sta crescendo nei timberling. Stiamo cercando di trovarne l'origine, ma fino ad allora, per mantenere Teldrassil al sicuro, dobbiamo abbattere i timberling ormai perduti. Quelli che vagano intorno a Wellspring Lake, nel nord di Teldrassil, sono i più corrotti. Vanno eliminati!$B$BDistruggi i Timberling che trovi laggiù e raccogli i tumori muschiosi che crescono su di loro. Portameli, così che possano essere bruciati.",
  obj = "Porta 5 Mossy Tumors a Rellian Greenspyre a Darnassus.",
  progress = "Sei stat$Go:a; a Wellspring Lake, $N? Hai dato la caccia ai timberling laggiù?",
  reward = "Ben fatto! Questi tumori sono il sintomo della malattia dei timberling. Sono pieni di un veleno che dobbiamo purificare dalla nostra nuova terra.$B$BMe ne occuperò io. Grazie, $N.",
  en_title = "Tumors",
  en_obj = "Bring 5 Mossy Tumors to Rellian Greenspyre in Darnassus.",
}
T[924] = {
  title = "Il Seme Demoniaco",
  desc = "Il Demon Seed è un potente strumento della Burning Legion. Giace in una caverna su Dreadmist Peak, sopra un altare demoniaco del fuoco.$B$BHo preparato delle pietre del potere che, poste vicino al Seed, ne spezzeranno il legame con la Legion.$B$BPrendi una pietra dal tavolo e portala all'altare del fuoco in cima a Dreadmist Peak. Viaggia a ovest, poi a nord quando la strada si biforca. Il Peak sarà alla tua sinistra. La salita più sicura verso la cima è sul versante nord.$B$BE sbrigati: il potere della pietra si consumerà col tempo.",
  obj = "Prendi una Flawed Power Stone. Portala all'Altar of Fire prima che la pietra si esaurisca, poi torna da Ak'Zeloth.",
  progress = "Il Demon Seed esiste ancora. Sento il suo potere...",
  reward = "Il tuo compito è compiuto. Hai distrutto il Demon Seed come Neeru aveva ordinato. Ma questa non è la fine...$B$BLa distruzione del Demon Seed ha inviato onde di potere attraverso l'etere, onde di forza impressionante. Le ho percepite, e sono certo che l'abbiano fatto anche altri esseri. Altri che si chiederanno chi ha rotto il loro giocattolo...$B$BMa a prescindere dai guai futuri, ho qualcosa per te. Neeru l'ha mandato come ricompensa e mi ha chiesto di ringraziarti.$B$BQuindi, grazie.",
  en_title = "The Demon Seed",
  en_obj = "Grab a Flawed Power Stone.  Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth.",
}
T[925] = {
  title = "Cairne's Hoofprint",
  desc = "Dicono che Cairne Bloodhoof sia uno dei più grandi eroi che l'Orda abbia mai visto. Da grande voglio essere un eroe dell'Orda anch'io!$B$BConosci Cairne, $N? Mi faresti un favore, per piacere? Potresti procurarmi l'impronta del suo zoccolo? Non so come chiederglielo, e probabilmente sarebbe troppo occupato per uno come me... ma tu! Sei $Gun avventuriero:un'avventuriera; proprio come lui! Scommetto che a te l'impronta la darebbe subito!$B$BPer piacere?",
  obj = "Raggiungi Thunder Bluff e cerca di ottenere l'impronta dello zoccolo di Cairne Bloodhoof per il tuo protetto.",
  progress = "Quando gli orchi erano soli e senza amici, i tauren li accolsero in una terra sconosciuta e condivisero tutto con loro senza chiedere niente in cambio. Questo è onore, $N.",
  reward = "WOW! Mi hai procurato l'impronta dello zoccolo di Cairne! Grazie mille! E wow... ci ha scritto sopra un messaggio personale, per me! Lo sapevo che sarebbe stato fantastico, lo sapevo! Magari un giorno lo ringrazierò di persona... quando diventerò un eroe dell'Orda!$B$BSei $Gil migliore:la migliore;, $N. Grazie di essere così gentile con me.",
  en_title = "Cairne's Hoofprint",
  en_obj = "Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward.",
}
T[926] = {
  title = "Flawed Power Stone",
  reward = "Queste pietre sono intrise di energia magica, ma volutamente difettose. Sono molto instabili e, una volta rimosse dal tavolo, si consumeranno rapidamente.",
  en_title = "Flawed Power Stone",
}
T[927] = {
  title = "Il cuore intrecciato di muschio",
  desc = "Il cuore di Blackmoss the Fetid è ricoperto da un muschio scuro e oleoso. Anzi, l'unico modo per capire che si tratta di un cuore è il suo battito lento e ritmico... Un battito che continua ancora adesso.$B$BForse Denalan vorrà vedere questo cuore.",
  obj = "Porta il Moss-twined Heart a Denalan a Lake Al'Ameth.",
  progress = "$N! Hai qualcosa per me?",
  reward = "...Cos'è questo? Un cuore di timberling?? È coperto da un muschio disgustoso!$B$BGrazie per avermelo portato, $N. Esaminerò il cuore e, se la fortuna ci assiste, scoprirò la natura del muschio che lo avvolge.",
  en_title = "The Moss-twined Heart",
  en_obj = "Bring the Moss-twined Heart to Denalan at Lake Al'Ameth.",
}
T[928] = {
  title = "La Corona della Terra",
  desc = "Avrei ancora molto da dirti sui pozzi lunari e su Teldrassil, ma devo mandarti avanti. Corithras Moonrage ti sta aspettando. Ho versato in questo recipiente l'acqua della fiala che mi hai portato, così che tu possa consegnarla a lui.$B$BCerca Corithras. Lo troverai al pozzo lunare di Dolanaar. Segui la strada a sud di Aldrassil, fuori da Shadowglen, e continua lungo il selciato quando la strada gira a ovest.$B$BBada di restare sulla strada, però, $N. Negli ultimi tempi nei boschi si aggirano bestie pericolose.",
  obj = "Porta il Partially Filled Vessel a Corithras Moonrage a Dolanaar.",
  progress = "Salute, $C. A cosa devo il piacere di questo incontro?",
  reward = "Ah, capisco. Ti ha mandat$Go:a; Tenaron. Bene, allora a quanto pare abbiamo molto di cui parlare, molto da fare e poco tempo per farlo.$B$BCredo sia meglio iniziare subito.",
  en_title = "Crown of the Earth",
  en_obj = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.",
}
T[929] = {
  title = "La Corona della Terra",
  desc = "Per prima cosa, lascia che ti spieghi meglio il compito che devi portare a termine. I druidi di Darnassus usano l'acqua dei pozzi lunari di Teldrassil, e il loro pozzo lunare deve essere rifornito di tanto in tanto. Con queste fiale lavorate appositamente puoi raccogliere l'acqua dei pozzi lunari.$B$BPorta questo recipiente al pozzo lunare fuori da Starbreeze Village, a est, riempilo con un po' delle sue acque e poi torna da me. Quando avrai finito, continuerò la storia da dove l'ha lasciata Tenaron...",
  obj = "Riempi la Jade Phial e riportala a Corithras Moonrage a Dolanaar.",
  progress = "Ben tornat$Go:a;, $N. Hai portato a termine il tuo compito?",
  reward = "Dopo la Battaglia del Monte Hyjal eravamo senza una guida. Nordrassil fumava per il fuoco che aveva scatenato, e la nostra immortalità, la vera essenza del nostro essere, era perduta!$B$BFu in quel periodo difficile che il Traditore venne liberato dalla sua prigione e che Shan'do Stormrage scomparve. Un'epoca oscura per tutti.",
  en_title = "Crown of the Earth",
  en_obj = "Fill the Jade Phial and bring it back to Corithras Moonrage in Dolanaar.",
}
T[930] = {
  title = "Il Frutto Luminoso",
  desc = "Sotto le fronde di questa pianta luminosa pende un grosso frutto rotondo.$B$BDenalan vorrebbe senza dubbio studiarlo, ne sei sicur$Go:a;.",
  obj = "Porta il frutto luminoso a Denalan a Lake Al'Ameth.",
  progress = "$N, hai l'aria di chi ha qualcosa da dirmi. Hai notizie sui timberling?",
  reward = "L'hai trovato su Teldrassil? Interessante... questo frutto è esotico. Forse i suoi semi sono stati portati qui da molto lontano. Magari persino da Azeroth! E c'è qualcosa in questo frutto... sembra aver reagito in modo stranissimo al terreno di Teldrassil.$B$BGrazie, $N. Ora, se vuoi scusarmi, devo studiarlo meglio...",
  en_title = "The Glowing Fruit",
  en_obj = "Bring the glowing fruit to Denalan at Lake Al'Ameth.",
}
T[931] = {
  title = "La Fronda Scintillante",
  desc = "Le fronde di questa pianta scintillano nella luce del bosco, conferendole un'aura contorta e pulsante.$B$BSei convint$Go:a; che Denalan vorrebbe un esemplare di questa pianta.",
  obj = "Porta una Shimmering Frond a Denalan a Lake Al'Ameth.",
  progress = "Hai qualcosa per me?",
  reward = "Dove l'hai presa? Non vedevo una pianta simile da un soggiorno che feci nelle Swamp of Sorrows... decenni fa! È incredibile che un esemplare sia arrivato fino a Teldrassil. E sia cresciuto fino a queste dimensioni!$B$BGrazie, $N. Perdona la mia brevità, ma c'è una prova che vorrei eseguire su questa fronda...",
  en_title = "The Shimmering Frond",
  en_obj = "Bring a Shimmering Frond to Denalan at Lake Al'Ameth",
}
T[932] = {
  title = "Odio Distorto",
  desc = "Devo avvertirti, $N: questa faccenda deve restare tra noi. I satiri sono già una vergogna abbastanza grave per noi, e questo è fin troppo vicino a casa.$B$BSi chiama Lord Melenas. Vive nella vicina caverna di Fel Rock, dove ha radunato un folto gruppo di guerrieri grell. Il suo cuore è nero come la notte e trama qualcosa di orribile.$B$BDevi trovarlo nella sua caverna, poco a nord di qui, e portarmi la sua testa.",
  obj = "Uccidi Lord Melenas e porta la sua testa a Tallonkai Swiftroot a Dolanaar.",
  progress = "Hai già ucciso Lord Melenas? È di vitale importanza che ci si occupi di lui in fretta e in silenzio, $N. La sua stessa esistenza è una vergogna per tutti noi.",
  reward = "Ora che Lord Melenas riposa, posso finalmente dedicarmi ad altre questioni. Grazie, $N.",
  en_title = "Twisted Hatred",
  en_obj = "Kill Lord Melenas and bring his head to Tallonkai Swiftroot in Dolanaar.",
}
T[933] = {
  title = "La Corona della Terra",
  desc = "C'è un altro pozzo lunare a sud-est dell'ingresso di Darnassus, sulle rive delle Pools of Arlithrien. Le Sentinelle hanno difficoltà a pattugliare la zona a causa degli attacchi e del carattere sempre più irascibile dei furbolg Gnarlpine.$B$BSta' in guardia mentre cerchi il pozzo e tieni le armi a portata di mano.",
  obj = "Riempi la Tourmaline Phial e riportala a Corithras Moonrage a Dolanaar.",
  progress = "All'inizio i resoconti sugli attacchi dei furbolg impazziti furono ignorati. Chi avrebbe mai pensato che quegli uomini-orso amanti della pace si sarebbero abbandonati a una furia cieca? Ecco un altro dei problemi che ci affliggono nella nostra nuova casa.",
  reward = "Shan'do Stormrage non fece mai ritorno, i druidi erano allo sbando e ancora oggi non sappiamo che ne sia stato di lui. Con Malfurion scomparso, l'Arcidruido Fandral Staghelm assunse la guida dei druidi, convincendo il Circle of Ancients di Darkshore che era tempo per il nostro popolo di ricostruire e di riconquistare la propria immortalità.$B$BCon l'approvazione del Circle, Staghelm e i druidi più potenti fecero crescere Teldrassil, il nuovo Albero del Mondo.",
  en_title = "Crown of the Earth",
  en_obj = "Fill the Tourmaline Phial and bring it back to Corithras Moonrage in Dolanaar.",
}
T[934] = {
  title = "La Corona della Terra",
  desc = "Ma non tutto andava bene con Teldrassil. I piani meticolosi di Staghelm per il nuovo Albero del Mondo erano andati come sperava, ma c'era un piccolo problema, al quale si possono attribuire molti dei guai di Teldrassil.$B$BTuttavia, per ora non ne parlerò. Devi visitare l'ultimo pozzo lunare, a nord-ovest, nell'Oracle Glade. Sotto i rami dell'Oracle Tree si trova il primo e più potente dei nostri pozzi. Recupera una fiala della sua acqua e torna da me.",
  obj = "Riempi l'Amethyst Phial e riportala a Corithras Moonrage a Dolanaar.",
  progress = "Insieme ai druidi, l'Oracle Tree e l'Arcidruido hanno osservato con attenzione la crescita di Teldrassil. Ma sebbene abbiamo una nuova casa, le nostre vite immortali non ci sono state restituite.",
  reward = "Trovarsi al cospetto dell'Oracle Tree... è quasi come sentire la saggezza prendere forma. Lascia che continui il racconto...$B$BUna volta cresciuta Teldrassil, l'Arcidruido si rivolse ai draghi per ottenere la loro benedizione, come i draghi avevano fatto con Nordrassil in tempi antichi. Ma Nozdormu, Signore del Tempo, rifiutò di concederla, rimproverando il druido per la sua arroganza. D'accordo con Nozdormu, anche Alexstrasza rifiutò Staghelm, e senza la sua benedizione la crescita di Teldrassil è stata imperfetta e imprevedibile...",
  en_title = "Crown of the Earth",
  en_obj = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.",
}
T[935] = {
  title = "La Corona della Terra",
  desc = "Senza la benedizione di Alexstrasza la Custode della Vita e di Nozdormu il Senza Tempo, la crescita di Teldrassil non è stata priva di difetti. Si dice che strane bestie emergano dal suolo stesso dell'albero, e che furbolg impazziti attacchino i viaggiatori di passaggio.$B$BNon posso che sperare che la soluzione cercata dall'Arcidruido sia trovata presto. Verserò tutte le fiale che mi hai portato in questo recipiente, perché tu lo consegni a Darnassus.$B$BPortalo a Fandral Staghelm: lo troverai nel boschetto dei druidi.",
  obj = "Porta il Filled Vessel all'Arch Druid Fandral Staghelm a Darnassus.",
  progress = "So di non averti convocat$Go:a;, perciò non posso fare a meno di chiedermi perché tu sia venut$Go:a; a parlarmi.$B$BQualunque cosa sia, ti prego, sii breve.",
  reward = "Ah sì, l'acqua che avevo richiesto. Tenaron e Corithras hanno certo preso il loro tempo per farmela recapitare... forse non hanno scelto i messaggeri più affidabili... hmm.$B$BComunque sia, ora posso finalmente tornare al mio lavoro. Il peso dei problemi di Teldrassil grava sulle mie spalle. Un giogo di cui spero di liberarmi presto.$B$BPrendi questo, potrebbe esserti utile.",
  en_title = "Crown of the Earth",
  en_obj = "Bring the Filled Vessel to Arch Druid Fandral Staghelm in Darnassus.",
}
T[937] = {
  title = "La Radura Incantata",
  desc = "Sono stato inviato qui con un piccolo gruppo di Sentinelle per proteggere l'Oracle Tree dalle arpie che hanno costruito i loro nidi tutto intorno alla radura. Poco alla volta stiamo cercando di respingerle.$B$BQuando l'Oracle Tree tentò di mandare un corriere a Darnassus con un rapporto, il messaggero fu attaccato e ucciso da un gruppo di arpie.$B$BSe te la senti, va' ai loro nidi, uccidile e portami le loro cinture come prova delle tue imprese.",
  obj = "Procurati 6 Bloodfeather Belts e portali alla Sentinel Arynia Cloudsbreak nell'Oracle Glade.",
  progress = "I loro artigli taglienti e i becchi penetranti potrebbero rivelarsi un osso duro per le tue capacità, $N, ma ho fiducia che non fallirai in questo compito.",
  reward = "Sono colpita da ciò che hai ottenuto qui in così poco tempo, $N. Vorrei poterti chiedere di restare ad assistermi nei miei doveri... ma so in cuor mio che compiti più grandi ti attendono.$B$BHo notato che l'Oracle Tree ha appena perso un pezzo di corteccia. Senza dubbio ha un compito che desidera veder compiuto. Dovresti parlargli.",
  en_title = "The Enchanted Glade",
  en_obj = "Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade.",
}
T[938] = {
  title = "Mist",
  desc = "Il pelo della sabercat è di un caratteristico grigio, che si confonde con la foresta circostante. Mentre giace lì, noti che è gravemente ferita, con profonde lacerazioni sulla schiena e sul ventre.$B$BAlza il capo e ti fissa, con una luminosa intelligenza negli occhi azzurri. Sembra voler seguirti.",
  obj = "Scorta Mist dalla Sentinel Arynia Cloudsbreak al pozzo lunare vicino all'Oracle Tree.",
  progress = "Mist... È stata colpa mia! Le streghe mi hanno colto di sorpresa... Non avrei dovuto lasciare che ti prendessero...",
  reward = "Oh, grazie, $N! Temevo di non rivedere mai più Mist, con nel cuore solo la certezza della sua morte, senza mai potermi riunire alla mia fedele compagna. Ti devo più di quanto tu possa immaginare, e hai la mia eterna gratitudine.",
  en_title = "Mist",
  en_obj = "Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree.",
}
T[940] = {
  title = "Teldrassil",
  desc = "La foresta mormora delle tue gesta valorose, $N. Mentre sentivo le arpie cacciate dai loro nidi, una calma più profonda si è diffusa nel bosco, e le sue creature si sentono di nuovo al sicuro. Ho temuto di mandare un altro messaggero all'Arcidruido, ma so che tu porterai il mio messaggio da lui sano e salvo.$B$BConsegnaglielo e sappi che la foresta ti guiderà al sicuro lungo i suoi sentieri fino alla foresta di pietra.",
  obj = "Consegna il rapporto dell'Oracle Tree all'Arch Druid Fandral Staghelm a Darnassus.",
  progress = "Hmm... Porti con te il forte spirito della foresta, $C. Che affari hai con l'Arcidruido dei Kaldorei?",
  reward = "Mi chiedevo perché l'Oracle Tree non comunicasse con me da così tanto tempo... Pare che alcuni problemi si attenuino mentre altri diventino più gravi.$B$BTemo che il mio lavoro su Teldrassil non sarà mai completato e che la nostra immortalità non sarà mai restituita.$B$BCiononostante, hai svolto bene il compito dell'Oracle Tree e meriti di essere ricompensat$Go:a; per la tua diligenza.",
  en_title = "Teldrassil",
  en_obj = "Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus.",
}
T[941] = {
  title = "Piantare il Cuore",
  desc = "Ho rimosso quel muschio immondo dal cuore, ma resta contaminato...$B$BProva a mettere il cuore nel mio vaso. È pieno di un terriccio nutriente che potrebbe purificarlo e guarirlo.",
  obj = "Pianta il Tainted Heart nel Denalan's Planter.",
  progress = "Questo vaso è pieno di terriccio, preparato appositamente da Denalan.",
  reward = "Metti il cuore nel vaso, ed esso si interra subito!$B$BQualche secondo dopo riemerge contorcendosi, purificato. Pulsa debolmente... come per invitarti a prenderlo.",
  en_title = "Planting the Heart",
  en_obj = "Plant the Tainted Heart in Denalan's Planter.",
}
T[942] = {
  title = "Il Prospettore Distratto",
  desc = "Questo fossile somiglia in modo impressionante a uno che vidi una volta a Ironforge. Un archeologo di nome Flagongut lo portò alla nostra conferenza annuale della Explorers' League. Credeva che il fossile avesse un potere che si potesse in qualche modo liberare.$B$BL'ultima volta che ho sentito, Flagongut si era rintanato alla Deepwater Tavern di Menethil Harbor, in attesa di una scorta per il Whelgar Excavation Site. Cercalo e mostragli il fossile di Remtravel. Forse potrà svelare i segreti del passato.$B$BLa nave per Menethil parte da Auberdine.",
  obj = "Porta il fossile misterioso all'Archaeologist Flagongut a Menethil Harbor.",
  progress = "Che ci hai lì, amico?",
  reward = "Oh santo cielo! Dici che viene dalle lontane terre di Kalimdor?$B$BStupefacente! Semplicemente stupefacente!",
  en_title = "The Absent Minded Prospector",
  en_obj = "Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor.",
}
T[943] = {
  title = "Il cercatore distratto",
  desc = "Prospector Whelgar ha ora il fossile originale nel suo sito, nelle Wetlands. Quando scoprii la Stone of Relu, credevo fosse la chiave per svelare il mistero del fossile.$B$BMentre viaggiavo sulla strada per incontrare Whelgar, fui attaccato dai raptor e la reliquia andò persa. Non so quale di quelle bestie chiazzate si sia inghiottita la reliquia, ma se riesci a recuperarla posso scatenare il potere di questi artefatti.$B$BPortami sia la Stone of Relu sia il fossile originale che ha lui.",
  obj = "Archaeologist Flagongut, a Menethil Harbor, vuole che tu gli porti la Stone of Relu e Flagongut's Fossil.",
  progress = "Con la Stone of Relu riuscirò a liberare i segreti nascosti del mio fossile e anche del fossile di Remtravel, quello di Darkshore, $N.",
  reward = "Ottimo, $N!$B$BOra vediamo se riesco a usare la pietra per decifrare i poteri dei fossili.",
  en_title = "The Absent Minded Prospector",
  en_obj = "Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.",
}
T[944] = {
  title = "Il Glaive del Maestro",
  desc = "È strano che i naga siano qui, a Darkshore. Ma ancora più strano... è che ci sia il Twilight's Hammer. Quel culto venera gli antichissimi signori della terra. Signori sconfitti da tempo.$B$BIl Master's Glaive, a sud, è un luogo dove uno di quegli antichi signori è caduto.$B$BVa' laggiù e cerca altri cultisti del Twilight's Hammer.$B$BPrendi questa fiala della veggenza. Usala per creare una scrying bowl dopo aver perlustrato il Master's Glaive. Poi parlami attraverso la coppa.",
  obj = "Raccogli informazioni, poi usa la Phial of Scrying per creare una Scrying Bowl. Usa la coppa per parlare con Onu.",
  progress = "Il Master's Glaive, $N.$B$BVa' là, poi parlami di nuovo.",
  reward = "Il Twilight's Hammer è al Master's Glaive?$B$BChe sventura.$B$BL'antico signore trafitto dal glaive è morto da tempo, ma ciò non significa che non restino ancora schegge del suo potere.$B$BIl Twilight's Hammer deve essere in cerca di quel potere.",
  en_title = "The Master's Glaive",
  en_obj = "Gather information, then use the Phial of Scrying to create a Scrying Bowl.  Use the bowl to speak with Onu.",
}
T[945] = {
  title = "La Fuga di Therylune",
  desc = "Aiuto!$B$BStavo vagando intorno al Master's Glaive e questi sporchi cultisti mi hanno circondata. Per fortuna sono brava a nascondermi!!$B$BPuoi aiutarmi a uscire di qui? E devo far sapere a mia sorella Therysil che sto bene. Si trova ad Ashenvale, a sud, al Shrine of Aessina.",
  obj = "Aiuta Therylune a fuggire, poi riferisci a Therysil al Shrine of Aessina che sua sorella è al sicuro.",
  reward = "Mia sorella era dove?? A Therylune non dispiace sporcarsi, ma insomma! È una lunga strada da percorrere, e il Master's Glaive è un posto malsano...$B$BBene, grazie, $N. È stato molto gentile da parte tua farmi sapere che sta bene.",
  en_title = "Therylune's Escape",
  en_obj = "Help Therylune escape, then tell Therysil at the Shrine of Aessina that her sister is safe.",
}
T[947] = {
  title = "Funghi di caverna",
  desc = "Sto preparando una pozione che richiede funghi rari, funghi che crescono solo in una certa caverna. La caverna si trova dietro Cliffspring Falls, a est e leggermente a nord lungo le montagne.$B$BCi andrei di persona, ma il Grove of the Ancients mi ha consigliato di starne alla larga. I nostri venerabili alleati sentono che la caverna è il nascondiglio di un nuovo male a Darkshore.$B$BTi prego, $N, raccogli i funghi per me. E già che ci sei, esplora la caverna per confermare i timori degli Ancients.",
  obj = "Porta 5 Scaber Stalk e 1 Death Cap a Barithras Moonshade ad Auberdine.",
  progress = "Hai i miei funghi, $N? Sei stat$Go:a; nella caverna?",
  reward = "Molte grazie, $N. Questi funghi sono esemplari magnifici!$B$BE mentre eri a Cliffspring Falls, hai trovato qualcosa che confermi gli avvertimenti degli Ancients?$B$BGli Ancients sono saggi, ma speravo che, per questa volta, si sbagliassero.",
  en_title = "Cave Mushrooms",
  en_obj = "Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine.",
}
T[948] = {
  title = "Onu",
  desc = "Onu, un Ancient of Lore al Grove of the Ancients, sa del tuo viaggio a Cliffwater Falls e desidera parlarti. Il bosco si trova a sud, adagiato accanto alle montagne.$B$BGli Ancients sono pazienti e saggi, $N. Ma se Onu cerca il tuo parere su ciò che hai visto alle cascate, temo che la cosa sia urgente.",
  obj = "Parla con Onu al Grove of the Ancients.",
  reward = "$N. Sei qui.$B$BBene.$B$BCi sono questioni... da discutere. Tu ed io.",
  en_title = "Onu",
  en_obj = "Speak with Onu at the Grove of the Ancients.",
}
T[949] = {
  title = "Il campo dei Twilight",
  desc = "Lo scopo dei Twilight's Hammer al Master's Glaive non è noto. Ma dev'essere oscuro.$B$BFruga nel loro accampamento al Glaive... Cerca qualcosa che possa rivelarci le loro intenzioni.$B$BPerché dobbiamo conoscere le loro intenzioni prima di elaborare un piano.",
  obj = "Trova un indizio nell'accampamento dei Twilight's Hammer al Master's Glaive.",
  reward = "Questo libro è stampato a mano in una lingua antica ed è illustrato da un artista sopraffino.",
  en_title = "The Twilight Camp",
  en_obj = "Find a clue in the Twilight's Hammer camp at the Master's Glaive.",
}
T[950] = {
  title = "Ritorno da Onu",
  desc = "Fissare il Twilight Tome è da impazzire. Il testo comincia a ondeggiare e a danzare dopo un solo istante di sguardo, e i fregi un tempo bellissimi si contorcono in forme grottesche.$B$BStrappare una pagina di folli scarabocchi è tutto ciò che puoi fare prima che un mancamento ti sopraffaccia.",
  obj = "Porta a Onu gli Insane Scribbles recuperati.",
  progress = "$N. Sei tornat$Go:a;.",
  reward = "Una magia caotica e primordiale avvolge questa pergamena di scarabocchi. Vi sento l'opera degli antichi.$B$BSperiamo che riveli lo scopo dei Twilight's Hammer a Darkshore...",
  en_title = "Return to Onu",
  en_obj = "Bring Onu the recovered Insane Scribbles.",
}
T[951] = {
  title = "Reliquie di Mathystra",
  desc = "La pergamena che hai trovato al Master's Glaive è una pagina di un antico testo... scritto da elfi! È pesantemente maledetta e contaminata dalla corruzione dei Twilight's Hammer, ma pare che il culto usi l'antica magia elfica per riportare nel nostro mondo i loro vecchi padroni.$B$BRecati alle rovine di Mathystra a nordest e cerca antiche reliquie tra l'erba e le pietre spezzate. Studiandole, potremmo capire come i Twilight's Hammer intendano sfruttare la magia degli elfi.",
  obj = "Porta 6 Mathystra Relic a Onu al Grove of the Ancients.",
  progress = "$N. Il tuo frugare tra le Ruins of Mathystra è stato fruttuoso?",
  reward = "Grazie. Queste reliquie vengono da un tempo in cui Mathystra splendeva. Quel che fu un grande baluardo degli elfi è sbiadito, ma frammenti della sua magia restano. Speriamo di svelare i segreti di quel luogo prima dei nostri nemici...$B$BSii vigile, $N.",
  en_title = "Mathystra Relics",
  en_obj = "Bring 6 Mathystra Relics to Onu at the Grove of the Ancients.",
}
T[952] = {
  title = "Grove of the Ancients",
  desc = "Se hai avuto tempo di portare messaggi per l'Oracle Tree, sono certo di poterti arruolare per consegnare un messaggio al Grove of the Ancients, a Darkshore, subito a sud di Auberdine.$B$BCon ogni probabilità dovrai procurarti un passaggio su un ippogrifo, ma ho abbastanza fiducia in te da credere che ce la farai. Porta questo a Onu, l'Ancient of Lore. Attende notizie da me, così come io attendevo notizie dall'Oracle Glade.",
  obj = "Consegna il messaggio di Fandral a Onu nel Grove of the Ancients a Darkshore, a sud di Auberdine.",
  progress = "Ah. $C. In che modo Onu può esserti d'aiuto?",
  reward = "Ah. Grazie, $N. È strano, però. L'Arch Druid sembra sempre avere una gran fretta. La foresta sa che tutto accadrà a tempo debito. Shan'do Stormrage lo capiva.",
  en_title = "Grove of the Ancients",
  en_obj = "Deliver Fandral's message to Onu in the Grove of the Ancients in Darkshore, south of Auberdine.",
}
T[953] = {
  title = "La caduta di Ameth'Aran",
  desc = "A est troverai le rovine di Ameth'Aran. Oggi sono abitate dagli spiriti inquieti degli Highborne che un tempo vivevano tra quelle mura, ma una volta era un luogo dove i servitori di Azshara praticavano liberamente le loro potenti magie.$B$BFui mandata a esplorare le rovine e mi imbattei in due grandi tavole, incise con le storie di Ameth'Aran e della sua caduta. Mentre leggevo le rune, fui assalita dagli spiriti e fuggii.$B$BTi prego, se puoi, avventurati nelle rovine e decifra le tavole al posto mio.",
  obj = "Studia le tavole che narrano di Ameth'Aran e della sua caduta, poi torna da Sentinel Tysha Moonblade a Darkshore.",
  progress = "Quando avrai studiato le tavole e appreso la caduta di Ameth'Aran, porterò la conoscenza ad Auberdine e informerò il Circle of Ancients.",
  reward = "Abbiamo pochi documenti del periodo intorno alla War of the Ancients, specie vicino alla distruzione del Well of Eternity. Considerati gli sconvolgimenti e gli eventi cataclismatici di allora, non è una grande sorpresa.$B$BGrazie, $N. Con il tuo aiuto il mio lavoro qui è concluso e potrò consegnare un rapporto completo al Circle.",
  en_title = "The Fall of Ameth'Aran",
  en_obj = "Study the tablets which tell of Ameth'Aran and of its fall, then return to Sentinel Tysha Moonblade in Darkshore.",
}
T[954] = {
  title = "Bashal'Aran",
  desc = "Le rovine di Bashal'Aran a est sono invase da servitori demoniaci. Gli sprite e i satiri che vi si sono stabiliti si nutrono delle energie magiche del luogo, e i loro poteri crescono con l'esposizione continua.$B$BEppure ho notato che c'è un santuario al quale non si avvicinano. Sul lato occidentale delle rovine, in cima a una piccola altura, si diffonde uno strano alone azzurro... Deve esserci una spiegazione per la riluttanza dei demoni.$B$BVorrei che tu indagassi.",
  obj = "Trova la fonte dello strano alone azzurro nelle rovine di Bashal'Aran.",
  reward = "Ahh... A cosa devo l'onore tanto speciale della compagnia di un $r come voi? In verità dice molto dei miei attuali compagni — senza offesa per i miei ospiti, i nobili grell e satiri — che la vostra presenza possa essere considerata un miglioramento.$B$BMa vi prego, non lasciate che la mia lingua scortese vi scacci da questo luogo. Sono davvero molti anni, decenni persino, che non ho una compagnia civile.",
  en_title = "Bashal'Aran",
  en_obj = "Find the source of the strange blue aura in the ruins of Bashal'Aran.",
}
T[955] = {
  title = "Bashal'Aran",
  desc = "Se dovessi raccontare la storia della mia vita, non dubito che supererebbe i limiti della tua pazienza. Diciamo che la mia è stata una vita lunga e dolorosa, e questa forma spettrale ne è forse il tormento peggiore.$B$BSono trattenuto qui tramite la magia. Sebbene le mie parole possano sembrare insincere, ti assicuro che ti sarei grato oltre ogni parola se mi aiutassi a trovare il mezzo della mia prigionia. Un sigillo mi lega, e esaminando gli orecchini degli sprite e dei grell potrei trovarne una traccia.",
  obj = "Procura 8 Grell Earring ad Asterion a Bashal'Aran.",
  progress = "Una volta che avrò gli orecchini, lancerò l'incantesimo per cercare dove si trovi il sigillo che mi lega. Per secoli ho pensato alla libertà che la distruzione del sigillo mi porterebbe... Forse quei secoli hanno gravato sulla mia mente al punto che non potrò mai riprendermi...",
  reward = "Davvero... I grell di Bashal'Aran non possiedono ciò che cerco... tuttavia sono entrati in contatto con esso di recente. Di recente... direi secondo il tuo tempo, non il mio. Per me il recente si perde nel velo del passato, quasi un'altra Era...",
  en_title = "Bashal'Aran",
  en_obj = "Acquire 8 Grell Earrings for Asterion in Bashal'Aran.",
}
T[956] = {
  title = "Bashal'Aran",
  desc = "Se i grell sono venuti a stretto contatto con il sigillo che forma la mia prigione eterna, credo di sapere il motivo. Senza dubbio il sigillo è finito in possesso del satiro che li guida.$B$BSento con forza che dev'essere vero, $n. Uno dei satiri di certo lo possiede. Se riuscirai a ottenerlo, mi porterai così vicino a varcare le sbarre della mia prigione che mi verrebbero le lacrime agli occhi.",
  obj = "Ottieni l'Ancient Moonstone Seal e portalo ad Asterion a Bashal'Aran.",
  progress = "I pilastri di questo santuario sono per me come le sbarre di una prigione, $N. Nessuna forza che ancora possiedo potrebbe spezzarli, e nessuna magia che padroneggio potrebbe distruggerli...$B$BPer mille anni e più li ho fissati, chiedendomi se, sopravvivendo alla pietra stessa, sarei stato libero. O sarebbero state sbarre invisibili a trattenermi allora...",
  reward = "È... è difficile persino credere che ciò che ora stringo sia ciò che mi ha trattenuto così a lungo. Non perdiamo tempo, $N. Quando il sigillo sarà distrutto, potrò camminare di nuovo liberamente per le foreste del mondo.",
  en_title = "Bashal'Aran",
  en_obj = "Obtain the Ancient Moonstone Seal and bring it to Asterion in Bashal'Aran.",
}
T[957] = {
  title = "Bashal'Aran",
  desc = "Fu l'arte di uno dei più potenti tra gli Highborne a creare il sigillo che forma la mia prigione. Ad Ameth'Aran, le rovine a sud gemelle di queste, persiste ancora oggi un'antica fiamma, di colore blu. In questa fiamma il sigillo potrà essere distrutto.$B$BSta' in guardia nelle rovine, $n...",
  obj = "Distruggi l'Ancient Moonstone Seal alla fiamma antica di Ameth'Aran, poi torna da Asterion a Bashal'Aran.",
  progress = "In verità, $N, ho paura... Paura che il tuo arrivo — tutto questo — sia solo un parto di una mente sconvolta. Puoi immaginare la tortura che è? Io... Ti prego, devi andare in fretta.",
  reward = "Sono libero, $N! Ora posso vedere con i miei occhi i cambiamenti giunti nel nostro mondo... Ne ho conosciuti solo frammenti. Pensare che quando camminavo libero per l'ultima volta, il Well era ancora in piedi e gli Highborne tenevano corte con Azshara, la nostra amata regina.$B$BSento che il mio carceriere, il mio antico padrone, Athrikus, vive ancora... Già il mio sconforto cede il posto a pensieri di vendetta.",
  en_title = "Bashal'Aran",
  en_obj = "Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran.",
}
T[958] = {
  title = "Gli strumenti degli Highborne",
  desc = "$C. Ho un compito da chiederti.$B$BHai visto le rovine di Ameth'Aran? Se no, le troverai sul lato orientale della strada principale, un po' più a sud. Un tempo furono la casa di molti potenti Highborne, ora sono la testimonianza della distruzione prodotta dai loro esperimenti.$B$BLe Sentinel mi hanno detto che gli spiriti degli Highborne persistono e che brandiscono i loro antichi strumenti magici. Quelle reliquie vanno sottratte, così da poterle distruggere.",
  obj = "Recupera 7 Highborne Relic per Thundris Windweaver ad Auberdine.",
  progress = "Se solo gli strumenti della loro rovina fossero stati distrutti nel cataclisma che devastò il nostro mondo... Eppure dobbiamo fare ciò che possiamo per assicurarci che gli orrori del nostro passato non si ripetano in futuro.",
  reward = "Sarà certo frutto della mia immaginazione, ma mi pare quasi di sentire su di esse la lordura della vile magia degli Highborne. Le farò distruggere, perché il loro male a lungo sopito non venga mai più liberato.",
  en_title = "Tools of the Highborne",
  en_obj = "Retrieve 7 Highborne Relics for Thundris Windweaver in Auberdine.",
}
T[959] = {
  title = "Guai ai moli",
  desc = "Ops!$B$BC'è stato un piccolo incidente, come vedi! Il carico che è arrivato stamattina da Booty Bay era enorme. Enorme, ti dico! Non ho mai visto tante casse. Be', cercavo di sbrigarmi e ho cominciato a scaricare un po' più di quanto riuscissi a reggere. Ed è lì che è venuto giù tutto.$B$BPrima che capissi cosa stava succedendo, ho visto quella peste di Mad Magglish scappare via con una bottiglia di porto di 99 anni. L'ho inseguito fin dentro le Wailing Caverns. Là dentro non ci entravo di sicuro.$B$BMagari tu sei abbastanza $Gcoraggioso:coraggiosa; da trovarlo?",
  obj = "Crane Operator Bigglefuzz, a Ratchet, vuole che tu recuperi la bottiglia di 99-Year-Old Port da Mad Magglish, che si nasconde nelle Wailing Caverns.",
  progress = "Il capo del molo mi sta addosso da quando Mad Magglish se n'è andato con quel porto di 99 anni. A quanto pare quella bottiglia era un regalo per Gazlowe niente meno che da Baron Revilgaz in persona.$B$BSe sei abbastanza $Gcoraggioso:coraggiosa; e paziente da cercare Mad Magglish e riprenderti quel porto, farò in modo che tu abbia una bella ricompensa.",
  reward = "Magnifico! E proprio mentre stavo per perdere il lavoro! Farò in modo che Gazlowe riceva subito questo regalo.$B$BGrazie, $N. Ben fatto, ti dico!",
  en_title = "Trouble at the Docks",
  en_obj = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.",
}
T[960] = {
  title = "Onu sta meditando",
  reward = "Sto meditando sul tuo compito, $N. Medito sulle ragioni per cui i Twilight's Hammer e i naga sono qui.$B$BQuando sarai pront$Go:a;, usa la phial of scrying per creare uno scrying bowl. Poi contattami attraverso la coppa.$B$BSe hai perso la tua phial of scrying, eccone un'altra.",
  en_title = "Onu is meditating",
}
T[961] = {
  title = "Onu sta meditando",
  reward = "La presenza dei cultisti dei Twilight's Hammer è inquietante. Devo meditare sulle loro intenzioni...$B$BQuando avrai più informazioni, parlami attraverso uno scrying bowl. Se ti serve una phial of scrying per creare una coppa, allora... eccone un'altra.",
  en_title = "Onu is meditating",
}
T[962] = {
  title = "Serpentbloom",
  desc = "La Royal Apothecary Society, con sede nella grande Undercity di Lordaeron, mi ha mandata qui per un servizio molto preciso, $N. Forse vuoi aiutare me, e con me la Signora Oscura, nei nostri sforzi per far avanzare i Reietti.$B$BDi recente ho studiato un raro esemplare di flora chiamato Serpentbloom. Credo che in quantità maggiori questa erba abbia un grande potenziale.$B$BPurtroppo la Serpentbloom si trova solo nei recessi più bui delle Wailing Caverns, un sistema di grotte pericoloso che si trova nelle Barrens.",
  obj = "Apothecary Zamah, a Thunder Bluff, vuole che tu raccolga 10 Serpentbloom.",
  progress = "Non vedo l'ora di scoprire se riesci a raccogliere abbastanza Serpentbloom nelle Wailing Caverns. Ne ho mandati molti a fare quello che chiedo, ma nessuno è tornato.",
  reward = "Ah, esemplari splendidi. Hai fatto bene, $N.",
  en_title = "Serpentbloom",
  en_obj = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.",
}
T[963] = {
  title = "Per amore eterno",
  desc = "All'indomani delle battaglie al Well of Eternity, seppi che Ameth'Aran era stata distrutta, il suo popolo morto, compreso il mio amore, Anaya.$B$BMai avrei pensato che, migliaia di anni dopo, il ricordo di Anaya avrebbe ancora tormentato i miei sogni. Vagando in stato di stordimento nei boschi di Darkshore, mi sono ritrovato nelle rovine di Ameth'Aran... dove ho visto lo spirito tormentato della mia amata.$B$BDeve essere liberata, ma non ho il cuore di farlo. Il suo spirito deve essere distrutto.",
  obj = "Libera lo spirito di Anaya Dawnrunner e riporta il suo pendente a Cerellean Whiteclaw ad Auberdine.",
  progress = "Con un grande dolore nel cuore seguii lo Shan'do Stormrage nell'ibernazione, e portai la mia pena nei sogni, dormendo per il trascorrere di migliaia di anni.",
  reward = "Grazie, $n. Forse sarebbe stato meglio... se lo avessi fatto io. Ma persino dopo migliaia di anni non ho potuto sopportare di alzare la mano contro la mia amata.$B$BTi prego, vorrei restare solo con il mio dolore...",
  en_title = "For Love Eternal",
  en_obj = "Free the spirit of Anaya Dawnrunner and bring her pendant back to Cerellean Whiteclaw in Auberdine.",
}
T[965] = {
  title = "La torre di Althalaxx",
  desc = "Salute, giovane $r. Sono Elissa Starbreeze, ed è mio compito proteggere Auberdine dai pericoli.$B$BA tal fine ho mandato Balthule Shadowstrike a osservare gli strani eventi attorno alla Tower of Althalaxx a nordest.$B$BÈ passato da un pezzo il momento in cui sarebbe dovuto tornare. Temo che abbia incontrato qualche pericolo imprevisto nella foresta. Ti sarei molto grata se lo trovassi e ti assicurassi che stia bene.",
  obj = "Trova Balthule Shadowstrike vicino alla Tower of Althalaxx a Darkshore.",
  reward = "Ti ha mandato Elissa? Allora porti buone notizie. Ho notizie preoccupanti da riferirle e non avevo modo di consegnargliele.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore.",
}
T[966] = {
  title = "La Tower of Althalaxx",
  desc = "Un gruppo di stregoni si è stabilito attorno e dentro la torre. Sarei tornato prima ad Auberdine per riferire a Elissa, ma temevo di perdermi qualcosa durante la mia assenza.$B$BDelgren sospettava che una simile congrega si stesse radunando alla torre, ma non sapeva perché.$B$BQualche frammento di pergamena in possesso degli stregoni è finito nelle mie mani, ma me ne servono altri per completare il quadro. Ti avverto però: non avventurarti dentro la torre, gli stregoni là dentro sono molto più potenti!",
  obj = "Raccogli 4 Worn Parchments per Balthule Shadowstrike vicino alla Tower of Althalaxx.",
  progress = "Hai trovato altri dei loro rotoli? Dovrei riuscire a ricostruire un quadro più ampio del culto, se riesci a trovarli.",
  reward = "Molte grazie, $n. Questo dovrebbe far luce sul raduno di questi stregoni...$B$BHmm... il Cult of the Dark Strand... Non ho mai sentito parlare di questo gruppo. Senza alcuna conoscenza della loro storia, è quasi impossibile dire quali siano i loro piani.$B$BNon c'è più tempo da perdere. Delgren deve essere avvisato immediatamente.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx.",
}
T[967] = {
  title = "La Tower of Althalaxx",
  desc = "Il mio maestro, Delgren the Purifier, è un paladino che ha generosamente offerto il suo aiuto nel difendere le nostre foreste dalle forze dei demoni e dei non morti. Mi ha insegnato molto sulla Sacra Luce e sull'arte della battaglia.$B$BDelgren deve essere informato subito delle operazioni del culto.$B$BLo troverai molto a sud di qui, a Maestra's Post nella Ashenvale Forest. Sii rapido$Go:a;, temo che la minaccia del Dark Strand cresca a ogni ora che passa.",
  obj = "Consegna la lettera di Balthule a Delgren the Purifier nella Ashenvale Forest.",
  progress = "Hai da trattare qualche affare con me, $C?",
  reward = "Se non ti dispiace che lo dica, sembri un po' troppo ben equipaggiat$Go:a; per essere un messaggero, eh? Suppongo che Balthule volesse essere certo che la sua lettera giungesse nelle mie mani. Vediamo cosa dice...$B$BQueste sono notizie inquietanti. Quando vengono avvistate forze non morte o demoniache, aiuto le Sentinelle a distruggerle.$B$BAll'inizio non ero abituato ai modi degli elfi della notte, ma sono arrivato a rispettarli profondamente come alleati.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest.",
}
T[968] = {
  title = "The Powers Below",
  desc = "Sebbene terribilmente consumato e graffiato, il titolo di questo libro si legge ancora sulla copertina:$B$BThe Powers Below$B$BAll'interno c'è un elenco di nomi impronunciabili con titoli sinistri, metodi di adorazione e sacrifici preferiti... molti dei quali includono creature umanoidi vive.$B$BSulla copertina interna ci sono queste parole: \"Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge. Proprietario: Gerrig Bonegrip.\"$B$BSe Bonegrip vende libri come questo, forse lo ricomprerà.",
  obj = "Porta il libro The Powers Below a Gerrig Bonegrip nella Forlorn Cavern, a Ironforge.",
  progress = "Salve, $Gsignore:signora;.$B$BPosso interessarvi a uno dei miei tomi?",
  reward = "Ah, una copia di The Powers Below. Un testo interessante, questo. E c'è chi potrebbe trovarlo utile...$B$BMa questa copia è ridotta male. E guarda qui! Ci sono appunti a margine in quasi ogni pagina!$B$BHm... conosco questa copia. L'ho venduta a Bolgar l'anno scorso. Sei... un suo amico? Sì, lo pensavo. Hai la stessa fiamma negli occhi!$B$BBene, per definizione, un amico di Bolgar è un amico mio. E noi ci prendiamo cura dei nostri, vero?",
  en_title = "The Powers Below",
  en_obj = "Bring the Book: The Powers Below to Gerrig Bonegrip in the Forlorn Cavern, Ironforge.",
}
T[970] = {
  title = "La Tower of Althalaxx",
  desc = "La lettera di Balthule è allarmante. Questo Cult of the Dark Strand è una spina nel fianco che va tolta. Mi sono già occupato di un po' di quella feccia del Dark Strand a nord-est di qui, a Ordil'Aran. Uno di loro possiede una gemma dell'anima che, credo, racchiude il segreto del potere del culto.$B$BPortamela, e riuscirò a decifrare i segreti che contiene.",
  obj = "Procurati una Glowing Soul Gem e portala a Delgren the Purifier, a Maestra's Post.",
  progress = "Ce l'hai quella gemma dell'anima?",
  reward = "Hmm, una magia oscura incanta questa pietra dell'anima. Vediamo cosa c'è intrappolato dentro, che ne dici?",
  en_title = "The Tower of Althalaxx",
  en_obj = "Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post.",
}
T[971] = {
  title = "Conoscenza nelle Deeps",
  desc = "Come forse saprai, io colleziono sapere. Sapere antico. Sapere potente. Sapere che apre porte, e sapere che può risvegliare Coloro Che Dormono.$B$BCorre voce che un antico frammento di sapere, il Lorgalis Manuscript, si trovi in fondo alle Blackfathom Deeps, in Ashenvale. Quel luogo è l'antica dimora di elfi morti da tempo. Elfi che possedevano una grande conoscenza, prima che la loro città cadesse in rovina.$B$BCerca il manoscritto nelle Blackfathom Deeps. Fallo, e non me ne dimenticherò. Nemmeno dopo... i giorni della fine.",
  obj = "Porta il Lorgalis Manuscript a Gerrig Bonegrip, nella Forlorn Cavern a Ironforge.",
  progress = "Il viaggio fino ad Ashenvale è lungo, e il tuo compito non è facile. Ma se mi porti il manoscritto, $N... allora la tua ricompensa sarà grande.",
  reward = "Hai trovato il manoscritto! Che giorno lieto è questo! Ne verranno fatte copie che saranno distribuite, e l'antica conoscenza di Lorgalis sarà finalmente nota ai miei fratelli e alle mie sorelle!$B$BIl tuo servizio per noi vale più di quanto tu sappia, $N. Ma spero che questo dono ti mostri la gratitudine che riserviamo ai nostri alleati.",
  en_title = "Knowledge in the Deeps",
  en_obj = "Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.",
}
T[972] = {
  title = "Water Sapta",
  reward = "Prendi la sapta dell'acqua e trova la pozza d'acqua corrotta a Silverpine, $N. Ho molta fiducia nelle tue capacità.",
  en_title = "Water Sapta",
}
T[973] = {
  title = "La Tower of Althalaxx",
  desc = "Ilkrud Magthrull. Sì, so di lui. È un potente stregone orco che ha preso dimora al Fire Scar Shrine, un luogo di grande malvagità nel sud-ovest di Ashenvale.$B$BFinora è stato poco più di una seccatura e non me ne sono occupato, ma pare che il suo momento sia arrivato.",
  obj = "Porta Ilkrud Magthrull's Tome a Delgren the Purifier, a Maestra's Post.",
  progress = "Sembri un po' $Gscosso:scossa;, $N. Stai bene?",
  reward = "Hai fatto una cosa grande, oggi, $N. Dovresti essere molto $Gfiero:fiera; di te per aver affrontato uno stregone di tale potere.$B$BOra vediamo cosa possiamo imparare dagli scritti di Ilkrud.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.",
}
T[976] = {
  title = "Rifornimenti per Auberdine",
  desc = "Delgren mi ha chiesto di consegnare messaggi e rifornimenti a Sentinel Starbreeze ad Auberdine, ma non me la sento di partire da solo. Nemici pericolosi si aggirano per la foresta, e non voglio rischiare che questi rifornimenti e queste informazioni finiscano nelle mani sbagliate.$B$BSe tu e altri faceste da scorta, potrei partire subito. Con la vostra protezione non ho dubbi che riusciremo a portare questi beni fino ad Auberdine sani e salvi.",
  obj = "Parla con Delgren the Purifier a Maestra's Post dopo aver portato Feero sano e salvo attraverso l'Ashenvale Forest.",
  progress = "Le Sentinelle hanno grande bisogno di rifornimenti per rafforzarsi a Darkshore.",
  reward = "Oggi hai fatto un buon lavoro, $C. Gli oggetti che abbiamo mandato in aiuto ad Auberdine serviranno subito ad affrontare le minacce oscure che infestano la foresta.$B$BPrendi questi, con la mia sincera gratitudine.",
  en_title = "Supplies to Auberdine",
  en_obj = "Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest.",
}
T[981] = {
  title = "La Tower of Althalaxx",
  desc = "Per tutto il lavoro che hai fatto, meriti una bella ricompensa. Torna da Delgren e digli che Athrikus Narassin giace ucciso per mano tua, e che il Cult of the Dark Strand è battuto e disperso.",
  obj = "Parla con Delgren the Purifier, a Maestra's Post.",
  reward = "Sapevo che saresti $Gstato:stata; all'altezza, $N.$B$BSento che grandi imprese ti attendono, e che raddrizzerai molti dei torti che affliggono le nostre terre. Porta con te le mie benedizioni, $N, e anche questo dono.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Talk to Delgren the Purifier at Maestra's Post.",
}
T[982] = {
  title = "Oceano profondo, mare sconfinato",
  desc = "Al largo della costa di Darkshore, a nord, giacciono due navi naufragate: la Silver Dawning e la Mist Veil. Tempo fa entrambe incapparono nei maledetti murloc mentre solcavano il vasto mare verso Auberdine. Ora riposano in fondo all'oceano come trofei per quei miscredenti.$B$BEntrambi i capitani non sono sopravvissuti quella notte, e i loro diari e i loro effetti personali sono ancora laggiù, in forzieri sigillati. Vorrei che tu li recuperassi per noi: significherebbe molto per i membri dell'equipaggio che si trovano ancora da queste parti.",
  obj = "Recupera il Silver Dawning's Lockbox e il Mist Veil's Lockbox per Gorbold Steelhand ad Auberdine. Entrambi gli oggetti dovrebbero trovarsi a bordo dei relitti delle navi, a nord del villaggio.",
  progress = "I capitani di quelle navi erano bravi elfi della notte, e meritano un destino migliore di quello che è toccato loro. Forse prendersi cura dei loro effetti personali è il modo migliore per dare pace ai loro spiriti.",
  reward = "Hai reso un grande servigio a noi di Auberdine, ragazzo. Ci assicureremo che i loro effetti siano trattati come si deve.$B$BQuanto a te, prendi questo. È il minimo che io possa fare per chi ha il coraggio di rimettere le cose a posto.",
  en_title = "Deep Ocean, Vast Sea",
  en_obj = "Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine.  Both items should be found aboard the wreckage of the ships to the north of the village.",
}
T[983] = {
  title = "Buzzbox 827",
  desc = "Ehi! Dammi una mano con la mia ultima invenzione, la buzzbox. Ti permette di parlare con persone lontane!$B$BForse ne hai già viste: sono scatole con delle leve. L'unico problema è che hanno bisogno di manutenzione costante.$B$BOgnuna ha un guasto diverso, ma ho preso una decisione davvero intelligente. Ho piazzato ciascuna vicino a creature che hanno i pezzi giusti per ripararla. In questo momento la Buzzbox 827 è fuori uso. Si trova appena a sud di Auberdine, proprio vicino. Servono 6 Crawler Legs per ripararla. Ti pagherò...",
  obj = "Raccogli 6 Crawler Legs e mettili nella Buzzbox 827.",
  progress = "La Buzzbox 827 è avvolta da uno strano silenzio. Una singola luce lampeggiante indica che servono 6 Crawler Legs da inserire nel suo scomparto.",
  reward = "Mentre inserisci le Crawler Legs nella macchina, senti gli ingranaggi iniziare a stridere. Dai colpi che provengono dalla Buzzbox, intuisci che le Crawler Legs stanno andando al loro posto. Presto la macchina inizia a ronzare, e senti una vocina chiamare dall'interno.$B$B\"Pronto? Ehm... Pronto! L'hai riparata! Qui è Wizbang, comunque! Grazie mille... Ehi, non vorresti ripararne un'altra, eh?\"",
  en_title = "Buzzbox 827",
  en_obj = "Collect 6 Crawler Legs and place them in Buzzbox 827.",
}
T[984] = {
  title = "Quanto è grande la minaccia?",
  desc = "Alcuni dei miei fratelli sono stati salvati da un furbolg corrotto a Teldrassil, e ho giurato di fermare altre atrocità prima che altri della nostra specie siano feriti... o peggio.$B$BHo già visto un paio di indizi di corruzione a Darkshore, ma non ho ancora trovato segni diffusi. Credo sarebbe logico proseguire l'indagine con i furbolg. Potresti trovare uno dei loro accampamenti e tornare da me se vedi segni di corruzione?",
  obj = "Trova un accampamento di furbolg corrotti a Darkshore e torna da Terenthis ad Auberdine.",
  progress = "Come procede la tua ricerca, $N?",
  reward = "Notizie davvero terribili, $N.$B$BCon i furbolg così vicini ad Auberdine, dovremo prepararci all'inevitabile.$B$BGrazie, $N.",
  en_title = "How Big a Threat?",
  en_obj = "Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine.",
}
T[985] = {
  title = "Quanto è grande la minaccia?",
  desc = "Hai già dimostrato di essere abile nell'esplorare le linee nemiche, $N. Hai ciò che serve anche per combatterli?$B$BNon tutti gli avventurieri preferiscono lo scontro diretto all'arte della furtività e dell'elusione.$B$BSe ti senti all'altezza, l'accampamento di furbolg a sud di Auberdine è al momento la più grande minaccia per il nostro popolo. Lì troverai alcuni membri della tribù Blackwood. Uccidi 8 pathfinder e 5 windtalker, poi torna qui da me.",
  obj = "Uccidi 8 Blackwood Pathfinders e 5 Blackwood Windtalkers e torna da Terenthis ad Auberdine.",
  progress = "Non trattenere la mano da ciò che va fatto, bambin$Go:a;. So quanto debba sembrarti ripugnante l'idea di uccidere le creature della foresta, ma in questo caso è necessario. Nessun rimedio è stato scoperto per la corruzione scatenata sulla foresta, e dobbiamo fare il possibile per arrestarne l'avanzata finché non se ne trova uno.",
  reward = "Lava via il sangue dalle tue vesti, $N, e non piangere ciò che hai dovuto fare. Piuttosto, rendi grazie. Hai ridotto la minaccia per il nostro popolo qui ad Auberdine, anche se Darkshore è ancora in pericolo a causa degli effetti del fel moss.",
  en_title = "How Big a Threat?",
  en_obj = "Kill 8 Blackwood Pathfinders and 5 Windtalkers and return to Terenthis in Auberdine.",
}
T[986] = {
  title = "Un maestro perduto",
  desc = "$N, le tue abilità mi hanno già aiutato nella mia impresa. Posso chiederti ancora di aiutare Grimclaw e il suo maestro Volcor? Inoltre posso creare per te un mantello magico che ti permetterà di camminare indisturbat$Go:a; tra le creature di Darkshore mentre lo cerchi.$B$BPer creare il mantello mi servono cinque Fine Moonstalker Pelts, prese da un moonstalker sire o matriarch per avere materiale sufficiente. I felini si trovano vicino al Wildbend River, a sud, o anche più a sud, verso Ashenvale.",
  obj = "Trova 5 Fine Moonstalker Pelts e portale a Terenthis ad Auberdine.",
  progress = "Non posso in buona coscienza permetterti di cercare Volcor finché non avrò creato quel mantello per te.",
  reward = "Andranno benissimo, $N. Mi metterò subito al lavoro sul mantello.$B$BDammi qualche istante, poi torna da me.$B$BAh, un'ultima cosa: dopo aver usato l'incantesimo sul mantello, le tue interazioni con gli altri saranno limitate. Se puoi evitarlo, limitati a parlare con gli altri. Fare di più potrebbe dissolvere l'illusione.",
  en_title = "A Lost Master",
  en_obj = "Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine.",
}
T[990] = {
  title = "Viaggio verso Ashenvale",
  desc = "$N, la mia signora, Raene Wolfrunner, ti attende nella città di Astranaar, ad Ashenvale. Con il tuo aiuto, forse potremo almeno alleviare parte della corruzione che si è radicata laggiù.$B$BDirigiti a sud da qui e resta vicin$Go:a; alla strada: se segui queste indicazioni arriverai senza problemi.",
  obj = "Trova Raene Wolfrunner ad Ashenvale.",
  reward = "Ah, un $C da Darkshore. Selarin ha fatto bene a mandarti qui così in fretta, $N. Vorrei che il tuo viaggio non fosse avvenuto in circostanze così gravi. Forse con il tuo aiuto potremo migliorare la situazione.$B$BIo comincerei la tua visita parlando con gli altri cittadini di Astranaar. Alcuni potrebbero davvero aver bisogno del tuo aiuto.",
  en_title = "Trek to Ashenvale",
  en_obj = "Find Raene Wolfrunner in Ashenvale.",
}
T[991] = {
  title = "La purificazione di Raene",
  desc = "$N, un mio vecchio amico sta aiutando anche lui le Sentinelle qui ad Ashenvale, ma non è ancora tornato.$B$BAveva una pista per trovare un oggetto che pensava potesse rallentare gli attacchi dei furbolg al nostro popolo: un bastone creato da un malvagio stregone ormai morto.$B$BPrima di partire accennò alla ricerca di una gemma per il bastone.$B$BDisse che la gemma poteva essere nascosta al santuario di Lake Falathim, ai piedi della montagna a ovest. La gemma era custodita lì prima che il luogo fosse invaso.$B$BTrova il mio amico, $N, ti prego.",
  obj = "Trova Teronis ad Ashenvale.",
  reward = "Il corpo di Teronis giace straziato in cima all'isola. Per qualche ignota ragione, i murloc lo hanno lasciato in pace.$B$BI profondi squarci sul suo cadavere sono ovviamente opera delle armi e degli artigli dei murloc.",
  en_title = "Raene's Cleansing",
  en_obj = "Find Teronis in Ashenvale.",
}
T[993] = {
  title = "Un maestro perduto",
  desc = "Il mantello è pronto, $N. È giunto il momento di trovare Volcor. Posso solo sperare che siamo in tempo.$B$BLa magia del mantello, una volta invocata, non durerà a lungo; forse cinque minuti. Sta a te capire quando usarlo: ti suggerisco di aspettare di aver trovato Grimclaw.$B$BSe ciò che mi ha detto è vero, troverai il suo maestro in una caverna a sud di qui. Grimclaw ti aspetterà lungo la strada. Fagli un cenno di saluto quando lo vedi, e lui ti indicherà la via verso il suo maestro.",
  obj = "Trova Volcor a Darkshore e consegnagli l'Enchanted Moonstalker Cloak.",
  reward = "Meraviglioso! Terenthis ha trovato qualcuno che mi aiutasse.$B$BE guarda. un mantello di moonstalker... <tossisce> Oh... che dolore. Grazie, $N.$B$BI furbolg mi hanno ferito prima che riuscissi a sfuggire loro. Dammi un momento, e dovrei essere in grado di parlare ancora un po'.",
  en_title = "A Lost Master",
  en_obj = "Find Volcor in Darkshore and give him the Enchanted Moonstalker Cloak.",
}
T[994] = {
  title = "Fuga di forza",
  desc = "E va bene, $N, sia la forza. Usciamo di qui appena sei $Gpronto:pronta;. Ci apriremo la strada combattendo fino alla via — Grimclaw dovrebbe essere ancora lì. Arrivati là, ci separiamo.$B$BTerenthis vorrà sentire subito la tua versione dei fatti, quindi va' ad Auberdine dopo che saremo usciti.",
  obj = "Proteggi Volcor finché non arrivate alla strada, poi parla con Terenthis, ad Auberdine.",
  reward = "$N! Che piacere vederti tornare con successo. Il tuo aiuto a Volcor mi dà fiducia che riusciremo a superare le prove che ci aspettano qui a Darkshore e oltre.",
  en_title = "Escape Through Force",
  en_obj = "Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.",
}
T[995] = {
  title = "Fuga attraverso la furtività",
  desc = "Bene, allora... se ne sei certo$Go:a;, sgattaioleremo via di qui. Partiamo quando sei pront$Go:a;.$B$BRicorda, dopo la fuga, raggiungi Terenthis ad Auberdine. Andrò là per conto mio, dato che probabilmente mi muoverò più velocemente di te.",
  obj = "Fuggi dalla caverna dei Furbolg e raggiungi Terenthis ad Auberdine.",
  progress = "Sì, $n?",
  reward = "$N! Sono lieto di vedere che sei tornat$Go:a; con successo. Il tuo aiuto a Volcor mi ha dato fiducia che potremo superare le sfide che ci attendono qui a Darkshore e oltre.",
  en_title = "Escape Through Stealth",
  en_obj = "Escape the Furbolg cave and meet Terenthis in Auberdine.",
}
T[997] = {
  title = "La terra di Denalan",
  desc = "Stai andando a sud? A Lake Al'Ameth? Se è così, avrei un compito da chiederti...$B$BIl mio collega Denalan ha un accampamento sulla sponda orientale del lago, dove studia e sperimenta sulla flora di Teldrassil. Ha richiesto un pacco di terre rare da Darnassus ed è arrivato in ritardo, giungendo qui a Dolanaar solo di recente.$B$BPuoi portarglielo?",
  obj = "Porta il pacco di Rare Earth a Denalan a Lake Al'Ameth.",
  progress = "Hai qualcosa per me?",
  reward = "Ah, è arrivata! Ho atteso questa terra rara per parecchio tempo. Spero sia ancora fresca...$B$BGrazie per avermela portata, $N. Sei un $R che ha a cuore il proprio tempo per gli altri... anzi, che lo dona con generosità.",
  en_title = "Denalan's Earth",
  en_obj = "Bring the package of Rare Earth to Denalan at Lake Al'Ameth.",
}
T[1000] = {
  title = "La nuova frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una desolazione proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.$B$BTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con Arch Druid Hamuul Runetotem, sull'Elder's Rise di Thunder Bluff, per maggiori informazioni!",
  obj = "Parla con Arch Druid Hamuul Runetotem, sull'Elder Rise di Thunder Bluff, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Salve, $C.$B$BSono lieto di vedere che gente come te si interessa al benessere della natura; i racconti delle tue grandi imprese ti precedono, e qui sei $Gbenvenuto:benvenuta;. Vederti davanti a me mi dà fiducia che il Cenarion Circle riceverà l'aiuto di cui ha bisogno.$B$BIl nostro legame con il Cenarion Circle di Moonglade supera le divisioni tra razze e quelle politiche. Ricordalo mentre lavori per il Circle, e farai bene.",
  en_title = "The New Frontier",
  en_obj = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.",
}
T[1001] = {
  title = "Buzzbox 411",
  desc = "Una vocina gracchia dal profondo della macchina.$B$B\"Qui Wizbang! La prossima Buzzbox è a nord di Auberdine, sulla spiaggia.$B$BQuindi, quella Buzzbox è la numero 411 e per le riparazioni servono 3 Thresher Eyes. Si trovano appena al largo! I darkshore thresher... *Hic*... Scusa, mi è scappato...$B$BCome l'altra volta, quando darai alla Buzzbox il materiale, ti sputerà fuori la ricompensa. *Hic*... Cosa? No, sto benissimo!\"",
  obj = "Raccogli 3 Thresher Eyes dai Darkshore Threshers nel mare profondo vicino alla Buzzbox 411.",
  progress = "Lo sportello della macchina è aperto e sembra attendere con impazienza che vengano inseriti 3 Thresher Eyes.",
  reward = "La Buzzbox si anima con un ronzio subito dopo che hai inserito i Thresher Eyes. C'è un momento di statica prima che senta una familiare vocina chiamare.$B$B\"Il vino di crawler è il migliore...\" *hic*$B$B\"Cosa? Oh, l'hai già riparata? Wow, sei un fulmine. Allora, ne vuoi riparare un'altra?\"$B$BTi sembra di sentire un liquido versato in una tazza, seguito da forti sorsate.",
  en_title = "Buzzbox 411",
  en_obj = "Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411.",
}
T[1002] = {
  title = "Buzzbox 323",
  desc = "La Buzzbox emette una raffica di statica mentre Wizbang inizia a parlare.$B$B\"La prossima Buzzbox è la numero 323. È a nord di Auberdine ma... dov'è la birra? Eh? Oh, è sulla strada quindi non dovresti avere problemi a trovarla vicino al ponte.\"$B$BWizbang borbotta qualcosa di incomprensibile prima di un forte rumore di sorsate.$B$B\"Questa richiede Moonstalker Fangs... 6 di esse.\"",
  obj = "Raccogli 6 Moonstalker Fangs e mettile nella Buzzbox 323.",
  progress = "Anche se non hai ancora inserito le 6 Moonstalker Fangs, ti sembra di sentire statica e sproloqui incomprensibili di gnomo provenire dall'interno. Che qualcun altro abbia già riparato la macchina?",
  reward = "La Buzzbox entra improvvisamente in azione, e senti distintamente il rumore di denti macinati in polvere provenire dall'interno.$B$B\"Allora, ce l'hai fatta! Ottime notizie... Allora... Perché non ti muovi? Oh! A meno che non vuoi un altro lavoretto!\"",
  en_title = "Buzzbox 323",
  en_obj = "Collect 6 Moonstalker Fangs and place them in Buzzbox 323.",
}
T[1003] = {
  title = "Buzzbox 525",
  desc = "Sopra i rumori di bollore e il gocciolio che provengono dalla macchina, senti la voce tremolante di Wizbang.$B$B\"La prosshima è poco più a sud lungo la strada. Non dovresshi fare fatica a trovarla... appena fuori dal sentiero... vicino a una shteccionata. Credo di averla nashosta in mezzo ai cheshpugli... Cheshpuglii. Eheheh... Shì, la Buzzbox 525 funzionsha con i scalpi grizzled dei Grizzled Thistle Bear. Che boccone... Grizzshled... Eheheh...\"$B$BSenti altri rumori di gola mentre la macchina si spegne. Poi, all'improvviso, torna a vivere con uno scoppio.$B$B\"4!\"",
  obj = "Raccogli 4 Grizzled Scalp dai Grizzled Thistle Bear a sud di Auberdine e mettili nella Buzzbox 525.",
  progress = "Dalla Buzzbox 525 senti provenire un canto.$B$B\"Il vino di granchio è dolce, la birra di thresher è fine, e il liquore di moonstalker è grandioso. Ma niente è più caro d'una birra d'orso di cardo, e preshto ne avrò una gran scorta!\"$B$BIl portello è aperto e attende i 4 scalpi, mentre la canzone si ripete all'infinito.",
  reward = "\"Shì che hai portato gli scalpi? Che meraviglia... Eh? Beh, shì, immagino tu abbia capito che posso parlarti anche shenza i materiali nella macchina. Ma dicevo la verità quando ho detto che erano rotte!$B$BVedi, oltre a esshere shtrumenti di comunimacazione, le Buzzbox producono e distillano anche liquori pregiati. Scusha per l'inganno, ma agli elfi della notte il mio commercio di liquori non piace, nelle loro città. In questa scatola ho messho qualcosa di shpeciale per ringraziarti dei tuoi shforzi. Goditela!\"",
  en_title = "Buzzbox 525",
  en_obj = "Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525.",
}
T[1007] = {
  title = "L'antica statuetta",
  desc = "Ho un compito da affidarti, $N.$B$BMi trovavo sulla mia piccola imbarcazione, scivolando sulle rovine sommerse di Zoram, quando i naga mi hanno attaccato, balzando fuori dall'acqua e dilaniandomi con gli artigli! Sono fuggito, portando con me quel poco che potevo per allestire questo misero accampamento.$B$BMa quando ho raggiunto la riva e sono corso via... ho perso il mio bene più prezioso.$B$BTi prego, $N, trova il luogo dell'agguato, lungo la costa a nord, e cerca un'antica statuetta. È la ragione per cui ho sfidato i pericoli della Zoram Strand.",
  obj = "Porta l'Ancient Statuette a Talen, nel suo accampamento vicino alla Zoram Strand.",
  progress = "Hai trovato la statuetta, $N?",
  reward = "L'hai trovata! Grazie, $N!$B$BLa vecchia città di Zoram custodisce molti segreti, e questa statuetta potrebbe essere la chiave di molti di essi.",
  en_title = "The Ancient Statuette",
  en_obj = "Bring the Ancient Statuette to Talen, in his camp near the Zoram Strand.",
}
T[1008] = {
  title = "La Zoram Strand",
  desc = "Un male si annida sulla nostra costa nordoccidentale, nota come Zoram Strand.$B$BÈ il luogo di riposo della città condannata di Zoram, distrutta durante lo Sundering e sommersa dai mari. Gli elfi della notte l'hanno perduta da secoli. Perduta, e quasi dimenticata.$B$BOra i naga sono tornati, e non ne conosciamo il motivo. Ma il motivo conta poco: dobbiamo uccidere questi demoni e ricacciarli negli abissi!$B$BTorna da me quando la tua missione sarà compiuta.",
  obj = "Porta 20 Wrathtail Head a Shindrell Swiftfire ad Astranaar.",
  progress = "Non possiamo permettere ai naga di invadere le nostre coste, $N. È vitale che tu vada alla Zoram Strand e porti a termine la tua missione.",
  reward = "Ben fatto, $N. Le tue azioni contro i naga alla Zoram Strand sono encomiabili.$B$BSo che l'impresa non è stata facile, perché la forza e l'astuzia dei naga sono ben note agli elfi della notte. Lo sappiamo, perché condividiamo con loro una storia.$B$BÈ una storia che non ho alcun desiderio di ripetere.",
  en_title = "The Zoram Strand",
  en_obj = "Bring 20 Wrathtail Heads to Shindrell Swiftfire in Astranaar.",
}
T[1009] = {
  title = "Ruuzel",
  desc = "Temo che i segreti dell'antica statuetta resteranno per sempre nascosti, a meno che tu non trovi la chiave della sua antica serratura.$B$BQuella chiave è un anello, il Ring of Zoram. Apparteneva a chi governava questa città, prima che le onde della Grande Separazione la sommergessero.$B$BPer anni l'anello è rimasto perduto, ma i naga l'hanno ritrovato di recente.$B$BLa loro condottiera, Ruuzel, vive su un'isola all'estremità settentrionale di Zoram. Ti prego, $N, recupera l'anello per me!",
  obj = "Porta il Ring of Zoram a Talen, vicino allo Zoram Strand.",
  progress = "Si dice che il Ring of Zoram sia la chiave di qualsiasi serratura della città. Ce l'hai, $N?",
  reward = "Hai trovato l'anello! Grazie, $N. Prendi questo come pagamento, e sappi che quel che hai fatto oggi resterà per sempre nella mia memoria.",
  en_title = "Ruuzel",
  en_obj = "Bring the Ring of Zoram to Talen near the Zoram Strand.",
}
T[1010] = {
  title = "I capelli di Bathran",
  desc = "C'è una pianta che un tempo cresceva nelle antiche rovine di Bathran's Haunt, a nord. Si chiamava Bathran's Hair ed era nota per curare i mali dello spirito.$B$BNel villaggio c'è un bambino malato, e credo che il suo male sia più di una semplice malattia del corpo. Andrai a Bathran's Haunt a cercare la Bathran's Hair? Potrei averne bisogno per curare bene il piccolo.$B$BBathran's Haunt si trova a nord di Maestra's Post e appena a sud del confine con Darkshore.",
  obj = "Porta 5 Bathran's Hair a Orendil Broadleaf ad Ashenvale.",
  progress = "Hai raccolto la Bathran's Hair, $N? La salute del bambino peggiora di ora in ora...",
  reward = "Ah, hai i capelli! Ora preparerò un rimedio per il bambino, e pregherò che il mio intruglio funzioni.$B$BE... i Forsaken a Bathran's Haunt? È davvero preoccupante. Davvero molto preoccupante...",
  en_title = "Bathran's Hair",
  en_obj = "Bring 5 Bathran's Hair to Orendil Broadleaf in Ashenvale.",
}
T[1011] = {
  title = "Le malattie dei Reietti",
  desc = "I Reietti, il braccio non morto dell'Orda, si sono insinuati ad Ashenvale e si aggirano tra le nostre rovine e i nostri tumuli. Crediamo che il loro scopo sia diffondere malattie nelle terre degli elfi della notte. Dobbiamo averne la conferma!$B$BI Reietti hanno un accampamento a sud di qui, vicino al Dor'Danil Barrow Den, dove preparano veleni e malattie e li mettono in bottiglie. Apriti la strada in quell'accampamento e ruba una bottiglia di malattia. Torna con una di quelle bottiglie. La analizzerò e ne scoprirò lo scopo.",
  obj = "Porta una Bottle of Disease a Kayneth Stillwind, a Forest Song.",
  progress = "Hai trovato l'accampamento, $N? Hai una bottiglia di malattia?",
  reward = "Molto bene, $N. Ora... analizzando il contenuto di questa bottiglia, gli scopi dei Reietti verranno alla luce!",
  en_title = "Forsaken Diseases",
  en_obj = "Bring a Bottle of Disease to Kayneth Stillwind in Forest Song.",
}
T[1012] = {
  title = "Druidi impazziti",
  desc = "Mentre lottavo con i veleni dei Reietti, ho avuto una visione. Ho visto i druidi del Dor'danil Barrow Den, avvelenati... assassinati dai non morti! Ora sono spettri erranti, separati dai loro corpi e impazziti.$B$BPerché un giorno gli spiriti dei druidi trovino pace, devi entrare nel Dor'danil Barrow Den e distruggere quelli che un tempo erano i suoi grandi capi: Taneel Darkwood, Uthil Mooncall e Mavoris Cloudsbreak.$B$BFa' questo, poi torna da me.",
  obj = "Uccidi i druidi: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; poi torna da Kayneth Stillwind, a Forest Song.",
  progress = "L'angoscia dei druidi di Dor'danil perseguita ancora i miei sogni, $N. Devi distruggere i loro capi!",
  reward = "Ho sentito l'angoscia dei Dor'danil Barrows attenuarsi, e ho capito che avevi portato a termine il tuo compito.$B$BÈ stato un lavoro cupo il tuo, $N, perché gli spiriti che hai distrutto erano soltanto vittime del male dei Reietti. Ma con la loro distruzione, speriamo che gli altri spiriti impazziti trovino pace.",
  en_title = "Insane Druids",
  en_obj = "Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song.",
}
T[1013] = {
  title = "Il Book of Ur",
  desc = "$N, Shadowfang Keep custodisce un libro, il Book of Ur, che sarebbe molto prezioso nella mia collezione. Ur era un grande mago di Dalaran prima dell'arrivo del Flagello, e i suoi studi su altri mondi sono di grande valore per... certi ambienti tra i Reietti.$B$BEntra a Shadowfang Keep e trova il libro. Portamelo, e riferirò il tuo servizio alla nostra Signora Oscura...",
  obj = "Porta il Book of Ur a Keeper Bel'dugur, all'Apothecarium, nell'Undercity.",
  progress = "Hai trovato il libro, $N?",
  reward = "Molto bene. Questo libro si aggiungerà degnamente alle mie raccolte delle opere di Ur. Il suo sapere era grande, ma la sua coscienza gli impedì di arrivare al vero potere. E così, quando venne il Flagello e la sua forza fu messa alla prova, non resse.$B$BNoi Reietti non possiamo permetterci una debolezza simile, se vogliamo sopravvivere...$B$B...Se vogliamo conquistare.",
  en_title = "The Book of Ur",
  en_obj = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.",
}
T[1014] = {
  title = "Arugal deve morire",
  desc = "Arugal risiede ancora a Shadowfang Keep. Non possiamo rivendicare Silverpine come roccaforte strategica per la Signora Oscura finché Arugal non sarà ucciso.$B$BMi occuperò io di sradicare la sua magia, $N. Ma lascio nelle tue mani il compito di far incontrare ad Arugal la morte che tanto si merita.$B$BVa' a Shadowfang Keep e metti fine una volta per tutte agli incantesimi immondi di Arugal. Portami la testa di quel vile mago!",
  obj = "Uccidi Arugal e porta la sua testa a Dalar Dawnweaver, al Sepulcher.",
  progress = "Con la morte di Arugal rafforzeremo la presa della Signora Oscura su Lordaeron.",
  reward = "La Silverpine Forest è finalmente libera dalla morsa di quel miserabile di Arugal. Hai reso un grande servizio alla Signora Oscura, $N. La tua tenacia sarà ricompensata.",
  en_title = "Arugal Must Die",
  en_obj = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.",
}
T[1015] = {
  title = "La nuova frontiera",
  desc = "Attenzione, eroi!$B$BIl Cenarion Circle cerca persone in grado di aiutarlo a esplorare le vaste nuove frontiere di Kalimdor! Molto a ovest di Tanaris e di Gadgetzan si stende una desolazione proibita, piena di pericoli inimmaginabili, e il Circle ha bisogno di persone volenterose e d'onore che agiscano per suo conto.$B$BTutti gli interessati chiedano udienza al Cenarion Circle. Parlate con l'arcidruido di Darnassus, Fandral Staghelm, per maggiori informazioni!",
  obj = "Parla con Arch Druid Fandral Staghelm, al Cenarion Enclave di Darnassus, della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.",
  reward = "Cosa ti fa pensare che io abbia voglia di essere $Gscocciato:scocciata; da gente come te, $C? Aspetta, lascia che interrompa i compiti importanti che svolgo ogni giorno per aiutarti a trovare un aggeggio da qualche parte. Ma certo, il bene di Darnassus, anzi, di tutta Teldrassil, deve venire dopo l'acquisto di un gingillo per la tua collezione.$B$BQuegli sciocchi del Moonglade mi fanno perdere tempo con le loro richieste di aiuto, e ora devo sopportare anche questo?",
  en_title = "The New Frontier",
  en_obj = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.",
}
T[1016] = {
  title = "Bracciali elementali",
  desc = "Prendi questa pergamena divinatoria — può rivelare chi ha creato questi elementali. Ma ti servirà qualcosa che appartenga a loro, da usare come reagente per concentrare la magia della pergamena — i loro bracciali dovrebbero andare benissimo.$B$BBastano pochi bracciali intatti presi dalle creature. Gli altri bracciali non ci serviranno, ma forse per un mercante varranno qualcosa, se vuoi venderli. Quando hai i bracciali intatti, prova a usare la pergamena. Torna da me con il risultato e vedremo come procedere.",
  obj = "Raccogli 5 Intact Elemental Bracer e usa su di essi la Divining Scroll. Poi porta la Divined Scroll a Sentinel Velene Starstrike al Silverwind Refuge.",
  progress = "Visto che per uccidere gli elementali devi distruggere i loro bracciali, sarà probabilmente difficile trovare proprio quelli che contengono le informazioni di cui la pergamena divinatoria ha bisogno. Puoi scambiare bracciali con altri per ottenere quelli che ti servono, o forse hai già il foglio divinato?",
  reward = "Ben fatto, $N, questo dovrebbe darci le informazioni che ci servono per scoprire il colpevole. Che ne diresti di eliminare il mago che riempie i nostri specchi d'acqua di elementali corrotti? La corruzione di Ashenvale e di altre terre mi rivolta lo stomaco già di suo — sapere che un mago si adopera per peggiorarla mi disgusta oltre ogni dire. Gliela faremo pagare.",
  en_title = "Elemental Bracers",
  en_obj = "Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge.",
}
T[1017] = {
  title = "Il mago evocatore",
  desc = "C'è un solo mago non morto nelle Barrens capace di profanare tutti questi elementali dell'acqua. Ed è anche l'unico abbastanza folle da provarci. Sarilus Foulborne se ne sta probabilmente in cima al Dreadmist Peak, a ridere di me.$B$B$N, devi entrare in territorio nemico e distruggere quel farabutto. Ne ho abbastanza della sua idiozia, e dobbiamo mostrargli cosa succede a chi infastidisce le Sentinelle.$B$BDistruggilo e portami la sua testa. Fa' attenzione, però: l'Orda potrebbe essere in cerca di te.",
  obj = "Uccidi Sarilus Foulborne e porta la sua testa a Sentinel Velene Starstrike, al Silverwind Refuge.",
  progress = "È fatta? Sarilus Foulborne è morto?",
  reward = "Ora posso vedere quel sorriso ripugnante cancellato per sempre dalla sua faccia. Hai fatto davvero un ottimo lavoro, $N. Prendi questa, la Light of Elune, e bevine quando tutto sembra perduto e la morte è vicina. Potrebbe salvarti, se la Dea vorrà.",
  en_title = "Mage Summoner",
  en_obj = "Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge.",
}
T[1020] = {
  title = "Il rimedio di Orendil",
  desc = "$N, ho preparato un rimedio che credo aiuterà il bambino malato. Portalo ad Astranaar e consegnalo al genitore del piccolo, Pelturas Whitemoon.$B$BPer raggiungere Astranaar, segui la strada verso sud, poi verso est.",
  obj = "Porta l'Orendil's Cure a Pelturas Whitemoon ad Astranaar.",
  progress = "Devo scusarmi, non ho tempo di parlare. Mia figlia Relara è gravemente malata!",
  reward = "Questo viene da Orendil?$B$BLa sua abilità con le erbe e la guarigione è grande. Questo rimedio mi dà speranza, quando prima ne avevo ben poca...",
  en_title = "Orendil's Cure",
  en_obj = "Bring Orendil's Cure to Pelturas Whitemoon in Astranaar.",
}
T[1021] = {
  title = "Satiro immondo! Driadi in pericolo!",
  desc = "Ascolta, non so chi sei, ma mi serve il tuo aiuto. Le mie sorelle sono andate a riprendere il Branch of Cenarius ai satiri. Hanno detto che sarebbero tornate presto, ma sono passati due giorni interi!$B$B$N, devi trovarle! Cercavano le rovine di un tempio degli elfi della notte a Xavian, a nord-est. Non so cosa pensare. Cerca Anilia, era lei a guidarle nella ricerca.",
  obj = "Trova Anilia, a Xavian.",
  reward = "A giudicare dalla ferita aperta nel fianco, Anilia è in punto di morte.",
  en_title = "Vile Satyr! Dryads in Danger!",
  en_obj = "Find Anilia in Xavian.",
}
T[1022] = {
  title = "L'Howling Vale",
  desc = "Anche se abbiamo dedicato molte risorse e molti sforzi a scacciare i demoni rimasti dal Felwood a nord, i successi sono stati pochi. Siamo riusciti a tenere gran parte della presenza demoniaca lontana da Ashenvale.$B$BA nord, vicino al confine del Felwood, il santuario in rovina di Mel'Thandris è stato occupato da misteriosi uomini-lupo. I loro richiami agghiaccianti hanno fatto sì che la zona venisse chiamata Howling Vale. Il Tome of Mel'Thandris custodito nel santuario potrebbe far luce sul motivo per cui questi uomini-lupo sono arrivati.",
  obj = "Va' all'Howling Vale e studia il Tome of Mel'Thandris, poi torna da Sentinel Melyria Frostshadow, allo Shrine of Aessina.",
  progress = "Il tomo del santuario è un oggetto misterioso. Non è un libro nel senso comune. I fogli del tomo furono benedetti da Mel'Thandris in persona, e nelle sue pagine registra gli eventi importanti.$B$BPer me è difficile da spiegare. Se vai al santuario, capirai.",
  reward = "Il Tome of Mel'Thandris funziona in modi strani. Gli eventi che registra, gli eventi che mostra... Nessuno capisce davvero perché faccia quello che fa.$B$BResta però chiaro che ciò che ha ricevuto Priestess Starsong — questa Scythe of Elune — merita altre indagini.",
  en_title = "The Howling Vale",
  en_obj = "Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song.",
}
T[1023] = {
  title = "La purificazione di Raene",
  desc = "Mentre frughi tra le cose di Teronis, trovi un diario ancora in buone condizioni.$B$BPrendi il diario e lasci il corpo di Teronis com'è.$B$BNon resta che trovare la gemma che Teronis stava cercando. Raene ha detto che si trova in zona. Forse ce l'hanno i murloc...",
  obj = "Trova la Glowing Gem e torna da Raene Wolfrunner ad Astranaar con Teronis' Journal.",
  progress = "Ah, $Gbentornato:bentornata;, $N.",
  reward = "È terribile, $N. Teronis è morto?!$B$BVerrà il tempo del lutto, ma per ora dobbiamo concentrare i nostri sforzi. Manderò alcune Sentinelle a recuperare il corpo di Teronis appena possibile.$B$BHai il diario di Teronis e la gemma che stava cercando. Pensi di essere in grado di portare a termine il suo compito? Dormirei molto più tranquilla sapendo che la sua morte non è stata vana.",
  en_title = "Raene's Cleansing",
  en_obj = "Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal.",
}
T[1024] = {
  title = "La purificazione di Raene",
  desc = "La ricerca dovrai farla da $Gsolo:sola;, ma da quel che ha annotato Teronis sembra che il prossimo passo sia trovare gli altri pezzi della verga creata da Dartol. Io comincerei andando al pozzo lunare a est dell'Iris Lake. Quando sei $Gpronto:pronta;, segui la strada e gira a nord quando arrivi a una piccola area di sosta sulla sinistra.$B$BLì c'è una driade di nome Shael'dryn, più adatta di me a guidarti. Cercala.$B$BTieni la gemma con te — a Shael'dryn servirà, se deve aiutarti a ricreare la verga.",
  obj = "Trova Shael'dryn al pozzo lunare a nord-est.",
  progress = "Salve. Come stai?",
  reward = "Oh, ti manda Raene? Allora dev'essere davvero grave. In cosa posso aiutarti?",
  en_title = "Raene's Cleansing",
  en_obj = "Find Shael'dryn at the moonwell to the northeast.",
}
T[1025] = {
  title = "Una difesa aggressiva",
  desc = "Prima che tu vada al pozzo lunare ho un altro incarico che aiuterà la gente di Ashenvale, se vuoi metterti alla prova.$B$BLungo la strada che va a est, prima del Falfarren River, i furbolg attaccano i viaggiatori. Le loro menti torturate si nutrono di paura e la loro fame si sazia del sangue degli innocenti.$B$BAiuta le Sentinelle a proteggere queste terre mostrando a quei mostri la stessa pietà che hanno mostrato alla nostra gente.$B$BCredo che i loro accampamenti siano a sud della strada... sta' $Gattento:attenta;.",
  obj = "Uccidi 1 Den Watcher, 2 Ursa, 10 Totemic e 12 Warrior della tribù Foulweald, poi torna da Raene Wolfrunner ad Astranaar.",
  progress = "I furbolg non sono sempre stati nostri nemici, $N. Ma i tempi cambiano, e questo non è più un tempo di pace in questi boschi oscuri.",
  reward = "Hai fatto un buon lavoro, $N. Grazie.",
  en_title = "An Aggressive Defense",
  en_obj = "Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar.",
}
T[1026] = {
  title = "La purificazione di Raene",
  desc = "Vorrei che le tue notizie fossero migliori.$B$BRaene ha ragione: conosco la creazione di Dartol e i treant della zona — o almeno li conoscevo. Ora sono stati corrotti, la loro natura è stata stravolta.$B$BSe il tuo scopo è trovare il prossimo pezzo della verga, dovrai trovare la chiave per aprire la cassa in cui si trova.$B$BLa chiave di legno è addosso a uno dei treant a nord-est di qui, vicino a Felwood. Quando ce l'hai, cerca una piccola radura a ovest della strada, vicino al confine di Felwood... la cassa dovrebbe essere nascosta da quelle parti.",
  obj = "Trova la Wooden Key e un pezzo di Dartol's Rod prima di tornare da Shael'dryn, al pozzo lunare.",
  progress = "Mi addolora tanto che i treant siano stati corrotti. Vorrei poter fare di più per aiutarli.",
  reward = "Sono contenta di vederti di ritorno, $N.",
  en_title = "Raene's Cleansing",
  en_obj = "Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell.",
}
T[1027] = {
  title = "La purificazione di Raene",
  desc = "L'ultimo pezzo della verga fu affidato ai druidi di Dor'danil perché lo custodissero. Non ho idea di dove l'abbiano nascosto. Mi dispiace, non posso aiutarti oltre.$B$BPosso solo dirti di seguire la strada che porta verso le Barrens. I druidi si erano rifugiati a est di quella strada, ma non ti saranno di grande aiuto: sono stati uccisi di recente... è una cosa a cui non mi piace pensare troppo.$B$BQuando trovi l'ultimo pezzo, portamelo e ti aiuterò a ricostruire la verga.",
  obj = "Trova l'ultimo pezzo di Dartol's Rod e torna da Shael'dryn, al pozzo lunare.",
  progress = "Hai trovato l'ultimo pezzo della verga, $N?",
  reward = "Hai trovato l'ultimo pezzo? Che meraviglia per te... e per Raene.$B$BA questo punto dovremo pensare a ripararla, no?",
  en_title = "Raene's Cleansing",
  en_obj = "Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.",
}
T[1028] = {
  title = "La purificazione di Raene",
  desc = "Ecco la verga completa, $N. Ricostruirla è stato semplice... la parte difficile sarà trovare il santuario che ha il potere di ricaricarla.$B$BCon un po' di concentrazione e di impegno non dovrebbe essere troppo difficile per qualcuno come te, che ha già fatto tanto.$B$BVa' a sud-est di qui — i sentieri sono pochissimi, quindi fa' attenzione — e tieni gli occhi verso nord. Il santuario è nascosto tra le montagne che circondano questa radura.$B$BUna volta lì, posa la verga nel santuario... il resto è magia. Eheh.",
  obj = "Trova il santuario nascosto e incanta di nuovo Dartol's Rod.",
  progress = "Percepisci una forza sottile ma potente nel santuario e negli alberi intorno.$B$BCominci a posare la verga nel santuario e intorno a te si leva un lieve ronzio mentre il santuario inizia a brillare...",
  reward = "Quando il bagliore si spegne, vedi la verga di nuovo incantata nella conca del santuario.",
  en_title = "Raene's Cleansing",
  en_obj = "Find the hidden shrine and re-enchant Dartol's Rod.",
}
T[1029] = {
  title = "La purificazione di Raene",
  desc = "Ti consiglio di cercare Raene e di farle sapere che la verga è pronta. Sono sicura che saprà dirti qual è il prossimo passo.$B$BBuona fortuna, $N.",
  obj = "Torna da Raene Wolfrunner, ad Astranaar.",
  reward = "Hai ricreato la verga che Teronis era partito a cercare? È una notizia meravigliosa.$B$BTeronis sarebbe fiero di vedere che la sua impresa continua anche dopo la sua tragica fine.",
  en_title = "Raene's Cleansing",
  en_obj = "Return to Raene Wolfrunner in Astranaar.",
}
T[1030] = {
  title = "La purificazione di Raene",
  desc = "Ahimè, non sono del tutto sicura di cosa avesse in mente dopo.$B$BSe quel che diceva sul potere della verga è vero, allora ti permetterà di assumere tutt'altra forma. Quale forma, non lo so.$B$BForse voleva usarne i poteri per avvicinarsi ai furbolg corrotti, ma anche le creature non corrotte lo avrebbero fatto a pezzi, se non fosse stato prudente. Trasformato dalla verga, Dartol avrebbe dovuto parlare con un furbolg al riparo dagli effetti del Fel Moss.$B$BIo comincerei la ricerca a sud-est del Mystral Lake.",
  obj = "Trova un furbolg non corrotto e, usando il potere di Dartol's Rod of Transformation, parlagli.",
  reward = "Sì, sì... sei $Guno:una; dei miei, ma ancora $Gintegro:integra;. Ancora $Gpuro:pura;.$B$BNon so come tu sia $Gsfuggito:sfuggita; alle atrocità che gli elfi della notte hanno inflitto alla nostra gente, ma sono lieto di sapere che non sono più solo.$B$BLa corruzione scorre ormai nelle vene dei nostri simili, giovane, una corruzione che ci hanno portato addosso gli orgogliosi elfi della notte. Sono loro ad aver fatto questo alla nostra gente... Sono loro che incolpo per essere stato cacciato dalla mia tribù.$B$BDi notte vedo ancora i fuochi da campo ardere nel buio.",
  en_title = "Raene's Cleansing",
  en_obj = "Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him.",
}
T[1031] = {
  title = "Il Branch of Cenarius",
  desc = "Anilia ti posa le mani sulle spalle e ti attira a sé. Ansimando, indica l'arco a nord, prima che i suoi occhi si chiudano e l'ultimo respiro affannoso le lasci il corpo. \"L'ha preso lui... Geltharis...\" Senti nel cuore che l'ultimo desiderio di Anilia è rivedere il Branch of Cenarius nelle mani delle driadi.",
  obj = "Uccidi Geltharis e riporta il Branch of Cenarius a Illiyana, allo Shrine of Aessina.",
  progress = "Le hai trovate? Cos'ha detto Anilia? Dov'è?",
  reward = "Anilia è morta? No... non può essere! Era solo ieri che correvamo e giocavamo insieme nei boschi.$B$BImmagino che quei giorni siano finiti...",
  en_title = "The Branch of Cenarius",
  en_obj = "Kill Geltharis and return the Branch of Cenarius to Illiyana at Forest Song.",
}
T[1032] = {
  title = "Strage di satiri!",
  desc = "Non riesco a credere che Anilia non ci sia più... Giocavamo sempre insieme nelle foreste. Mi sento quasi... triste.$B$BSo una cosa che potrebbe farmi stare meglio. Ti prego, uccidi i satiri che mi hanno portato via Anilia! Portami le loro corna come prova di quel che hai fatto e avrai per sempre la mia gratitudine.",
  obj = "Porta 16 Satyr Horn a Illiyana, allo Shrine of Aessina.",
  progress = "Ti prego, aiutami a vendicare la morte di Anilia.",
  reward = "Grazie, gentile $R. Lo spirito di mia sorella è confortato da quel che hai fatto.",
  en_title = "Satyr Slaying!",
  en_obj = "Bring 16 Satyr Horns to Illiyana in Forest Song.",
}
T[1033] = {
  title = "Elune's Tear",
  desc = "Speravo che la cura di Orendil salvasse Relara, ma temo che abbia solo rallentato il male che scorre in mia figlia. Dobbiamo trovare una medicina più potente! Per fortuna Orendil mi ha parlato di altri rimedi da provare, nel caso il primo fallisse.$B$BElune's Tear è un tipo di pietra che si trova in un solo posto: l'isola sull'Iris Lake, a est di Astranaar. Orendil ha detto che la pietra lava via la corruzione... ti prego, $N, portami Elune's Tear e prega che ponga fine alla malattia di mia figlia!",
  obj = "Porta Elune's Tear a Pelturas ad Astranaar.",
  progress = "$N, hai trovato l'Iris Lake? Hai la Tear?",
  reward = "Oh, l'hai trovata! Metterò la lacrima in uno stufato e pregherò che la guarisca.$B$BGrazie! Grazie, $N!",
  en_title = "Elune's Tear",
  en_obj = "Bring Elune's Tear to Pelturas in Astranaar.",
}
T[1034] = {
  title = "Le Ruins of Stardust",
  desc = "Elune's Tear ha lavato via una parte del male di mia figlia. I suoi incubi si sono attenuati e ringrazio la dea per la sua benedizione. Ma... la febbre infuria ancora dentro di lei.$B$BOrendil mi ha parlato di una polvere gelida che si trova tra le Ruins of Stardust. Forse placherà la febbre di Relara. Raccogline un po', poi torna da me, ti prego.$B$BLe Ruins of Stardust si trovano a sud, $N. Che Elune renda veloce il tuo viaggio.",
  obj = "Porta 5 Handful of Stardust a Pelturas ad Astranaar.",
  progress = "Hai già la Stardust, $N?",
  reward = "Hai raccolto la polvere! Ne farò un impiastro — dovrebbe far scendere la febbre di Relara.$B$BGrazie ancora, $N. Senza il tuo aiuto mia figlia morirebbe di sicuro.",
  en_title = "The Ruins of Stardust",
  en_obj = "Bring 5 Handfuls of Stardust to Pelturas in Astranaar.",
}
T[1035] = {
  title = "Il Fallen Sky Lake",
  desc = "La febbre di Relara è passata, ma è ancora molto debole. Non credo che il tempo da solo le restituirà le forze che ha perso. Credo che serva il potere di una pietra di luna.$B$BUn tempo raccoglievamo pietre di luna al Fallen Sky Lake, a sud-est... finché non sono arrivati gli Shadethicket.$B$BIl loro capo, uno Shadethicket Oracle, ha raccolto tutte le Fallen Moonstone e se le tiene. Ora devi recuperarne una dall'Oracle.$B$BE per farlo, temo che dovrai ucciderlo.",
  obj = "Recupera una Fallen Moonstone dallo Shadethicket Oracle, poi portala a Pelturas ad Astranaar.",
  progress = "Hai affrontato lo Shadethicket Oracle, $N? Se sì, dammi la Fallen Moonstone, ti prego. A Relara restano le forze per pochi respiri!",
  reward = "Oh, $N, hai salvato mia figlia! So che il potere della pietra di luna le ridarà le forze!$B$BNon potrò mai ripagarti del tutto per l'aiuto che mi hai dato, ma... ti prego, prendi questo. A parte Relara, è la cosa più cara che ho.",
  en_title = "Fallen Sky Lake",
  en_obj = "Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar.",
}
T[1036] = {
  title = "Alt là, canaglia",
  desc = "$N... sì, ho sentito parlare di te. Ho sentito che non sei $Gamico:amica; di Booty Bay, proprio come noi Bloodsail Buccaneers. Fleet Master Firallon cerca $Guomini:donne; forti e $Gvigorosi:vigorose; proprio come te per una missione speciale.$B$BSe ti interessa, va' alla Crimson Veil e parlagli sottocoperta. È ancorata al largo della Wild Shore, a est di qui, accanto alla Riptide e alla Damsel's Luck.",
  obj = "Parla con Fleet Master Firallon a bordo della Crimson Veil, al largo della costa di Stranglethorn Vale.",
  reward = "Alt là, canaglia. Mi dicono che sei il tipo da qualche losco affare. Be', se non sei $Gamico:amica; di Booty Bay, allora potresti avere un posto speciale tra i Bloodsail Buccaneers.$B$BArrrrr...",
  en_title = "Avast Ye, Scallywag",
  en_obj = "Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale.",
}
T[1037] = {
  title = "Velinde Starsong",
  desc = "Velinde Starsong era la mia predecessora qui nell'Ashenvale Forest. All'inizio sembrava che avesse la situazione del Felwood sotto controllo, ma a poco a poco i suoi sforzi si sono indeboliti. Un giorno è semplicemente sparita.$B$BMi hanno mandata qui a continuare il suo lavoro. Temo però di non sapere nulla della sacerdotessa. Forse Thyn'tel Bladeweaver, una delle comandanti delle Sentinelle, conosce altri dettagli sulla sua scomparsa che a me non sono stati riferiti.$B$BDi sicuro capirà l'importanza di simili informazioni.",
  obj = "Parla con Thyn'tel Bladeweaver, alla Warrior's Terrace di Darnassus.",
  reward = "Velinde Starsong? Che la sacerdotessa sia sparita tempo fa è quasi di sicuro cosa risaputa. Quanto ad altri dettagli sugli eventi attorno alla sua partenza... mi servirebbe una buona ragione per divulgare simili informazioni.",
  en_title = "Velinde Starsong",
  en_obj = "Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus.",
}
T[1038] = {
  title = "Gli effetti personali di Velinde",
  desc = "Il Tome of Mel'Thandris ti ha mostrato questo? Immagino non ci sia gran male a lasciarti esaminare le sue cose. Questa chiave ti permetterà di aprire la cassa in cui abbiamo riposto la sua roba, nella camerata delle Sentinelle. Teneva un diario dei suoi incarichi: se c'è qualcosa da scoprire, verrà da lì.$B$BDevo dirti che le Sentinelle credono che avesse le sue ragioni per andarsene, e si aspettano che possa tornare da un momento all'altro. In passato la sacerdotessa ha fatto molto per guadagnarsi la nostra fiducia.",
  obj = "Cerca il diario nella cassa di Velinde, poi riportalo insieme alla chiave a Thyn'tel Bladeweaver, a Darnassus.",
  progress = "Cos'hai scoperto?",
  reward = "Sembra che la scomparsa di Velinde sia più inquietante di quanto sembrasse all'inizio. Eppure non riesco a credere che abbia fatto una brutta fine. Forse ci gioverebbe metterci in contatto con lei.$B$B$N, visto che hai dimostrato un interesse personale in questa faccenda, vorrei chiedere il tuo aiuto.",
  en_title = "Velinde's Effects",
  en_obj = "Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.",
}
T[1039] = {
  title = "Il porto delle Barrens",
  desc = "Ratchet è l'unico porto delle Barrens. Con ogni probabilità Velinde ha trovato a Ratchet una nave mercantile che la portasse a Blackwater Cove, ad Azeroth. Abbiamo pochi rapporti con i goblin che gestiscono il porto, ma il padrone del molo dovrebbe avere informazioni sull'andirivieni dei passeggeri.$B$BSegui la strada a sud-est attraverso Ashenvale e ti ritroverai nelle Barrens. Guarda dove metti i piedi, $N: guerrieri dell'Orda pattugliano quelle terre. Al porto, però, sarai al sicuro.",
  obj = "Parla con Wharfmaster Dizzywig, a Ratchet.",
  reward = "$R, eh? Devo ammettere che da queste parti non ne capitano molti come te. Cerchi qualcuno, eh? Dammi solo un momento, sono sicuro di averlo scritto in uno dei miei registri.$B$BDi gente però ne passa parecchia, quindi dammi un attimo.",
  en_title = "The Barrens Port",
  en_obj = "Speak with Wharfmaster Dizzywig in Ratchet.",
}
T[1040] = {
  title = "Passaggio per Booty Bay",
  desc = "Ah, sì, finalmente l'ho trovato. Dovevi dirmi che era passata di qui così tanto tempo fa. Vediamo.$B$BVelinde. Ha prenotato un passaggio per Booty Bay sulla Black Osprey. Qui non c'è scritto niente in contrario, quindi direi che sia arrivata in porto senza problemi.$B$BOltre a questo non posso esserti di grande aiuto, ma mi ha chiesto dei viaggi via terra dall'altra parte del mondo, e le ho parlato di Ruzzgot, un carovaniere che sta a Booty Bay. Può darsi che questa Velinde abbia viaggiato con lui.$B$BOra circola. Non ho tutto il giorno per te.",
  obj = "Prendi una nave per Booty Bay e parla con Caravaneer Ruzzgot.",
  reward = "Sì? Be', non mi sembri il tipo con merce da spedire, quindi o cerchi lavoro con la mia carovana — e di lavoro adesso non ce n'è — o probabilmente stai parlando con il goblin sbagliato.$B$BAllora, quale delle due?",
  en_title = "Passage to Booty Bay",
  en_obj = "Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.",
}
T[1041] = {
  title = "La strada della carovana",
  desc = "A quanto pare su di te mi sbagliavo, e non è una cosa che capiti tutti i giorni.$B$BGuarda caso mi ricordo di questa Velinde che cerchi. Non capita tutti i giorni che una sacerdotessa elfa della notte voglia viaggiare con una carovana vecchia e sporca — ma perfetta per le tue spedizioni! — come la mia.$B$BCi siamo separati lungo la strada verso nord, lei era diretta a Darkshire. Il cancelliere di là tiene registri di ogni genere. Potrebbe sapere qualcosa di utile.$B$BFa' attenzione nella giungla: è un posto letale anche nei periodi migliori.",
  obj = "Parla con Clerk Daltry, a Darkshire.",
  reward = "Con tutte le stranezze degli ultimi anni, tengo i registri degli stranieri più accurati che posso. Non si sa mai quando possano tornare utili... anche se di solito, quando succede, non è per faccende piacevoli. Non che voglia insinuare nulla su questa Velinde che cerchi.",
  en_title = "The Caravan Road",
  en_obj = "Speak with Clerk Daltry in Darkshire.",
}
T[1042] = {
  title = "La famiglia Carevin",
  desc = "No, non ho alcuna traccia di una Velinde Starsong che abbia soggiornato a Darkshire... anche se, se posso permettermi, faccio fatica a immaginare una sacerdotessa elfa della notte che prende una stanza alla locanda, mi spiego?$B$BQuesti uomini-lupo di cui parli, però, ne ho sentito parlare. Proprio l'altro giorno Calor è arrivato in città con una fila delle loro teste. Lavora con la famiglia Carevin. Cacciatori di demoni, non morti e altre mostruosità. Parla con Jonathan, è lui il capofamiglia.",
  obj = "Parla con Jonathan Carevin, a Darkshire.",
  reward = "Sono tempi oscuri. Brutte notizie si sussurrano da ogni ramo che oscilla, e il male si trova sotto ogni pietra.$B$BE in tempi simili $Guno sconosciuto:una sconosciuta; entra in casa mia e chiede dei worgen... Non chiederò scusa per i miei sospetti, voglio solo risposte.$B$BE risposte avrò.",
  en_title = "The Carevin Family",
  en_obj = "Speak with Jonathan Carevin in Darkshire.",
}
T[1043] = {
  title = "La Scythe of Elune",
  desc = "La tua storia suona vera... Non capisco del tutto le tue ragioni, ma se quel che hai da fare qui a Duskwood comporta liberare la foresta da un certo numero di worgen, allora posso rinunciare a capire in cambio di risultati.$B$BA sud c'è una miniera invasa dai worgen... Sono comparsi dal nulla, ma da quel che sappiamo è lì che sono stati visti per la prima volta.$B$BFa' quel che devi, ma ti chiedo che, se trovi qualcosa di importante, tu lo condivida con me. Accetteremo qualsiasi aiuto nella nostra guerra contro il male.",
  obj = "Cerca tracce della Scythe of Elune, poi torna da Jonathan Carevin, a Darkshire.",
  progress = "I boschi sono pericolosi per chi non è preparato. Tieni le armi a portata di mano e l'ingegno ancora più vicino, o il tuo prossimo viaggio nella foresta infestata potrebbe essere l'ultimo.",
  reward = "È una storia interessante quella che racconti, $N. Anche se l'influenza della famiglia Carevin non è tale da permetterci di trovare la radice di questi guai e di porvi fine una volta per tutte, faremo il possibile per contenere il numero dei worgen a Duskwood.$B$BHo già ordinato a Calor di farne la sua prima priorità.",
  en_title = "The Scythe of Elune",
  en_obj = "Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.",
}
T[1044] = {
  title = "Domande con risposta",
  desc = "Terremo a freno il problema dei worgen, non preoccuparti. Questo male che la tua amica ha portato nei nostri boschi verrà contenuto, e non le porto rancore per quel che ha fatto. In questi tempi accadono cose strane, $N, e l'oscurità non conosce tregua.$B$BNon ti tratterrò oltre. Immagino che ci siano altri che dovrebbero sapere quel che hai trovato nelle miniere di Duskwood.",
  obj = "Torna da Thyn'tel Bladeweaver, a Darnassus.",
  reward = "Dunque questo è il destino di Velinde? La somma sacerdotessa sarà delusa nel saperlo: erano buone amiche prima della sua scomparsa. Eppure la Scythe of Elune le fu certo concessa in dono dalla nostra dea, e mi inquieta che sia sfuggita dalle mani delle sue serve.$B$BMa questa è un'altra faccenda, per un'altra volta. Ti devo un ringraziamento non da poco per quel che hai fatto.",
  en_title = "Answered Questions",
  en_obj = "Return to Thyn'tel Bladeweaver in Darnassus.",
}
T[1045] = {
  title = "La purificazione di Raene",
  desc = "Gli elfi della notte sono antichi come il tempo, ma la loro arroganza distrugge il loro stesso mondo. E ora distrugge anche le nostre vite. Ma ormai non si può più controllare...$B$BDo la colpa agli elfi per molte cose, ma restiamo comunque responsabili delle nostre azioni. Anche al di là della corruzione, siamo capaci di grande male.$B$BRan Bloodtooth è uno di questi mali. Avido di potere, bramoso... la corruzione lo ha solo reso più forte. Il mio odio per gli elfi brucia, ma non auguro il male ai loro figli, quindi dobbiamo fare ordine tra i nostri.",
  obj = "Uccidi Ran Bloodtooth e 4 Bloodtooth Guard, poi torna da Krolg, vicino al Lake Mystral.",
  progress = "Hai già ucciso Ran, $Gamico mio:amica mia;?$B$BPersino gli elfi della notte non meritano davvero la sua ira. Il suo odio brucia ancora più del mio, ma la sua mente non gli appartiene più. È una minaccia per tutte le creature naturali di questa foresta.",
  reward = "Hai fatto bene, $Gamico mio:amica mia;.$B$BLa foresta è ancora corrotta, ma almeno sappiamo di aver fatto la nostra piccola parte per riportarla all'antica gloria. Se vorrai tornare da me, mi farebbe piacere la compagnia di uno dei miei.$B$BStammi bene. Forse le nostre tribù si incontreranno di nuovo in tempi meno violenti.",
  en_title = "Raene's Cleansing",
  en_obj = "Kill Ran Bloodtooth and 4 Bloodtooth Guards and return to Krolg near Lake Mystral.",
}
T[1046] = {
  title = "La purificazione di Raene",
  desc = "Torna dalla tua tribù e falle sapere della tua vittoria qui.$B$BMostra loro il tuo trofeo, e crogiolati nella gloria...",
  obj = "Porta Ran Bloodtooth's Skull e Dartol's Rod of Transformation a Raene Wolfrunner, ad Astranaar.",
  progress = "Le Sentinelle fanno quel che possono qui ad Ashenvale, ma è grazie a gente come te se abbiamo guadagnato il terreno che abbiamo.",
  reward = "Dunque questo è il teschio della più feroce minaccia furbolg di Ashenvale?$B$BSono più che soddisfatta delle tue capacità, $N. Le Sentinelle non potranno mai ringraziarti abbastanza. Spero che in futuro potremo contare ancora su di te per aiutare la nostra gente.$B$BMetterò questo teschio e Dartol's Rod in un luogo d'onore, perché tutti li vedano.$B$BTeronis ne sarebbe fiero. Grazie ancora.",
  en_title = "Raene's Cleansing",
  en_obj = "Bring Ran Bloodtooth's Skull and Dartol's Rod of Transformation to Raene Wolfrunner in Astranaar.",
}
T[1048] = {
  title = "Nello Scarlet Monastery",
  desc = "Mentre la Signora Oscura si occupa della pressante questione dell'avanzata del Re dei Lich a nord, io faccio in modo che le faccende più vicine a casa vengano sistemate come si deve.$B$BNon c'è dubbio che i parassiti umani che si fanno chiamare Crociata Scarlatta si stiano rivelando la spina più dolorosa nel nostro fianco, qui in patria. Le Tirisfal Glades brulicano letteralmente di quelle piccole formiche rosse.$B$BVa' al Monastery, $C, e annienta High Inquisitor Whitemane e i suoi luogotenenti più alti in grado.",
  obj = "Uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion e Houndmaster Loksey, poi torna a riferire a Varimathras, nell'Undercity.",
  progress = "Forse non sono stato abbastanza esplicito nei miei ordini, $C. Voglio High Inquisitor Whitemane morta, una volta per tutte. E già che ci sei, elimina anche i suoi pezzi grossi.$B$BUccidi quel fanatico, Scarlet Commander Mograine. Annienta Herod, the Scarlet Champion. E massacra Houndmaster Loksey, e anche i suoi luridi cagnacci.$B$BOra vattene!",
  reward = "Hai servito bene la Signora Oscura, $C. Non era cosa da poco, quello che ti ho chiesto.$B$BLa tua lealtà verso i Reietti è stata notata. E la tua tenacia in combattimento sarà ricordata.",
  en_title = "Into The Scarlet Monastery",
  en_obj = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.",
}
T[1049] = {
  title = "Compendium of the Fallen",
  desc = "Il Circolo della Terra aveva intenzioni pure nei confronti dei nostri fratelli appestati. Ma chi può conoscere le motivazioni di chi sussurra all'orecchio dell'Elder Council?$B$BI Reietti con cui ci siamo alleati hanno un passato intriso di inganni. Il nostro patto è stato troppo frettoloso. Forse Cairne avrebbe fatto bene a dare ascolto agli avvertimenti di Orgrimmar.$B$BNel profondo dello Scarlet Monastery si trova il Compendium of the Fallen, sorvegliato da folli fanatici umani. Il loro metodo nasce dalla follia, ma le loro ricerche potrebbero rivelarsi utili.",
  obj = "Recupera il Compendium of the Fallen dal Monastery nelle Tirisfal Glades e torna da Sage Truthseeker, a Thunder Bluff.",
  progress = "Cairne è un capo coraggioso e nobile, e gli affiderei la mia stessa vita. Ma in questo clima politico sono altri quelli di cui non mi fido.$B$BQuando avrò modo di raccogliere tutte le conoscenze disponibili, potrò dare consigli solidi al capotribù.$B$BHai avuto modo di andare nelle Tirisfal Glades? Allo Scarlet Monastery? Il Compendium of the Fallen è solo un pezzo di questo complicato rompicapo...",
  reward = "Il Compendium of the Fallen! Cominciavo a chiedermi se quel libro esistesse davvero!$B$BHai servito bene i tauren di Thunder Bluff, $N. La tua dedizione non sarà dimenticata.",
  en_title = "Compendium of the Fallen",
  en_obj = "Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.",
}
T[1050] = {
  title = "Mythology of the Titans",
  desc = "Il futuro è inevitabile! Ci gettiamo verso di esso come gocce di pioggia che cadono nel Great Sea.$B$BMa forse, studiando il passato, possiamo sapere cosa aspettarci ed essere più preparati all'ignoto.$B$BPrima che terribili sventure si abbattessero su Lordaeron, c'era un bastione del sapere nascosto nelle Tirisfal Glades. Si dice che un libro intitolato Mythology of the Titans fosse custodito nella biblioteca del vecchio Monastery.$B$BPortamelo, e forse insieme potremo svelare i segreti del passato!",
  obj = "Recupera Mythology of the Titans dal Monastery e portalo a Librarian Mae Paledust, a Ironforge.",
  progress = "Il Monastery era un seminario per paladini in addestramento. Un tempo roccaforte della Luce, è caduto nelle mani dei folli fanatici della Crociata Scarlatta.$B$BLa Crociata riteneva nobile il proprio scopo: purificare la terra dalla piaga dei non morti. Ma la follia ha corrotto la sua missione, e ora è nemica di tutti.$B$BPortami Mythology of the Titans, così potrò studiarlo e custodirlo qui a Ironforge.$B$BLe sale corrotte del Monastery non sono il posto per un tesoro storico simile.",
  reward = "Hai salvato il testo sacro!$B$BIl tuo viaggio è stato lungo e recuperare il libro non è stato certo un compito facile. Ma i nani di Ironforge trarranno beneficio dal tuo successo.$B$BGrazie, $N, a nome della Lega degli Esploratori.",
  en_title = "Mythology of the Titans",
  en_obj = "Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.",
}
T[1051] = {
  title = "La vendetta di Vorrel",
  desc = "Anche se la mia volontà è libera, non posso più servire la Signora Oscura. Sento che il mio tempo su Azeroth è giunto alla fine. La mia forza vitale è distrutta.$B$BÈ stato Interrogator Vishas a ridurmi così! Mi ha torturato per settimane! Mi ha preso la fede nuziale e l'ha data a sua moglie. Quel bastardo!$B$BVendetta... voglio vendetta!$B$BQuello stolto pieno di sé si vantava della sua preziosa moglie, Nancy, che viveva sulle rive del Lake Lordamere. Trova quella donnaccia, uccidila e riporta la mia fede nuziale a mia moglie, Monika, a Tarren Mill.$B$BRispetta le mie ultime volontà...",
  obj = "Riporta la fede nuziale di Vorrel Sengutz a Monika Sengutz, a Tarren Mill.",
  progress = "Cosa vuoi, $Gstraniero:straniera;?",
  reward = "Vorrel ha avuto un'esistenza così travagliata. E che buon compagno era...$B$BMaledetti quei luridi umani!$B$BVorrel non c'è più, e non godrà mai più della non morte. Almeno posso trovare conforto nella vendetta che hai compiuto in suo nome. Per questo ti ringrazio.$B$BOra lasciami al mio lutto...",
  en_title = "Vorrel's Revenge",
  en_obj = "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.",
}
T[1052] = {
  title = "Lungo il sentiero scarlatto",
  desc = "Noi della Crociata Scarlatta rivendichiamo roccaforti da Hearthglen fino alle Tirisfal Glades. Siamo molto fieri dei nostri bastioni di purificazione in tutta Lordaeron.$B$BHai dimostrato il tuo valore contro i non morti di Desolace. Ma la vera minaccia della piaga si trova a Lordaeron.$B$BVa' nella cittadina di Southshore, negli Eastern Kingdoms. Cerca un crociato di nome Raleigh the Devout. Dagli questa Letter of Commendation con il mio sigillo e ti accompagnerà a un posto d'onore nel nostro Scarlet Monastery.",
  obj = "Porta la Letter of Commendation di Brother Anton a Raleigh the Devout, a Southshore.",
  progress = "Chi va là? Che cosa vuoi da me?",
  reward = "Brother Anton diffonde ancora la parola della Crociata Scarlatta? Oh, cielo...",
  en_title = "Down the Scarlet Path",
  en_obj = "Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.",
}
T[1053] = {
  title = "Nel nome della Luce",
  desc = "Un tempo servivo la Crociata Scarlatta con onore, lealtà e orgoglio. Credevo che la sua causa fosse nobile: liberare Azeroth dai non morti.$B$BMa durante il tempo che ho passato al Monastery, nelle Tirisfal Glades, mi sono reso conto che stavano perdendo il contatto con la realtà. Ora pensano che chiunque non indossi il tabarro della Crociata sia appestato. Uomini e donne innocenti sono stati torturati perché, a quanto si diceva, erano appestati.$B$BLa Crociata Scarlatta deve essere schiacciata nel nome della Luce. Tu, $N, devi distruggere questo regime folle.",
  obj = "Uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion e Houndmaster Loksey, poi torna a riferire a Raleigh the Devout, a Southshore.",
  progress = "La corruzione nel Monastery non finirà finché non saranno eliminati i suoi capi di grado più alto.$B$BNel nome della Luce, uccidi High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion e Houndmaster Loksey. Una volta caduti loro, forse la vera causa potrà riaccendersi. Fino ad allora, chiunque incroci il cammino della Crociata è in pericolo.$B$BParti da Southshore e fa' che accada!",
  reward = "Anche se i discepoli della Luce non gioiscono mai della perdita di vite, dobbiamo accettare che a volte questi sacrifici siano necessari per il bene superiore del Regno e del pianeta.$B$BCon le tue imprese nel Monastery hai risparmiato molte vite innocenti, $N. Rendo omaggio alla tua tenacia.",
  en_title = "In the Name of the Light",
  en_obj = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.",
}
T[1054] = {
  title = "Ridurre la minaccia",
  desc = "Subito a nord di Astranaar ci sono i furbolg Thistlefur. I miei esploratori riferiscono che il loro numero è cresciuto molto negli ultimi mesi. Se diventano troppi, potrebbero trovare il coraggio di attaccare Astranaar direttamente.$B$BUccidine quanti più puoi, ma portami il teschio del loro capotribù come prova che i loro sforzi sono stati soffocati... per ora.$B$BIo resterò qui ad Astranaar e aspetterò tue notizie. Che Elune sia con te.",
  obj = "Porta Dal Bloodclaw's Skull a Raene Wolfrunner, ad Astranaar.",
  progress = "La corruzione dei furbolg ha ridotto Ashenvale a una frazione della sua antica gloria.",
  reward = "Ben fatto, $N.$B$BI furbolg ci minacciano di continuo. Si spera che questo li tenga a bada ancora per un po'.",
  en_title = "Culling the Threat",
  en_obj = "Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar.",
}
T[1055] = {
  title = "La purificazione di Raene",
  desc = "La verga, ora completa, è nelle tue mani. Shael'dryn vorrà sapere del tuo successo.",
  obj = "Torna da Shael'dryn, al pozzo lunare.",
  reward = "Ce l'hai fatta, $N! Ben fatto!",
  en_title = "Raene's Cleansing",
  en_obj = "Return to Shael'dryn at the moonwell.",
}
T[1056] = {
  title = "Viaggio a Stonetalon Peak",
  desc = "Gli spiriti della foresta mi dicono che sei coraggios$Go:a; e pront$Go:a; a viaggiare.$B$BA sud, non lontano da Mystral Lake, si trova un tunnel chiamato Talondeep Path. Attraverso questo tunnel giungerai in una zona detta Windshear Crag, nelle Stonetalon Mountains. Una volta lì, prosegui verso sudovest oltre Cragpool Lake e poi verso nord, su per il ripido pendio, fino a raggiungere Stonetalon Peak.$B$BLì ti attende Keeper Albagorm. Ascolta il suo volere, $r.$B$BIl viaggio sarà pericoloso.",
  obj = "Recati da Keeper Albagorm a Stonetalon Peak.",
  reward = "Ahimè, sei giunt$Go:a;. Vedo che Faldreas ha dato ascolto agli spiriti della foresta...",
  en_title = "Journey to Stonetalon Peak",
  en_obj = "Travel to Keeper Albagorm on Stonetalon Peak.",
}
T[1057] = {
  title = "Riconquistare la Charred Vale",
  desc = "Come $Gprotettore:protettrice; degli spiriti della foresta, puoi senza dubbio immaginare perché sono allarmato.$B$BHai attraversato queste montagne per raggiungere questo picco. Di certo hai visto lo scempio che si è abbattuto su questa terra. L'avidità ha portato alla distruzione di queste colline sacre.$B$BLa Charred Vale a sud è stata data alle fiamme dall'avida armata meccanizzata degli industriali. Peggio ancora, le Bloodfury che hanno invaso la terra ci negano il passaggio per cominciare a farla rinascere.$B$BScaccia le miserabili arpie, $N!",
  obj = "Keeper Albagorm, su Stonetalon Peak, vuole che tu uccida 7 Bloodfury Harpy, 7 Bloodfury Ambusher, 7 Bloodfury Slayer e 7 Bloodfury Roguefeather.",
  progress = "C'è molto lavoro da fare prima che la Charred Vale possa tornare la foresta rigogliosa che era un tempo.$B$BRipulisci la zona da quelle minacce immonde, $N! Solo allora potremo cominciare a riprenderci ciò che appartiene alla natura.",
  reward = "Ora che le Bloodfury hanno subito una perdita così grande, forse il vero lavoro di risanamento della terra può cominciare...",
  en_title = "Reclaiming the Charred Vale",
  en_obj = "Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.",
}
T[1058] = {
  title = "La magia della foresta di Jin'Zil",
  desc = "Come sono emozionato!$B$BTre gabbiette per tre elfetti! Ma cosa ne facciamo dei nostri cari amici amanti degli alberi? Ma sì, diamogli un assaggio di... come la chiamano... magia della foresta!$B$BMi servirà un bel mucchio di Stonetalon Sap. Da quei felini orrendi portami dei Twilight Whisker. Per questa ci vogliono un sacco di Courser Eye, naturalmente: gli occhi non bastano mai. Ah, e non dimentichiamo, una preziosa scaglia di Fey Dragon.$B$BCorri allo Stonetalon Peak, $N, così posso preparare un po' di magia della foresta!",
  obj = "Witch Doctor Jin'Zil, a Malaka'jin, vuole 5 porzioni di Stonetalon Sap, 5 Twilight Whisker, 30 Courser Eye e un Fey Dragon Scale.",
  progress = "Guarda i nostri poveri amici elfi. Tutti in gabbia, senza una foresta in cui sgambettare!$B$BAllora, sei $Griuscito:riuscita; a trovarmi un po' di linfa? E i baffi dei Twilight Runner? Non è che per caso hai addosso quel Fey Dragon Scale?$B$BE occhi! Mi serviranno tanti occhi! Non si può proprio mescolare un bell'intruglio di magia della foresta senza una buona dose di occhi!",
  reward = "Oh, come saranno felici queste ninfette dei boschi! Le faremo sentire proprio a casa con questo intruglio speciale!",
  en_title = "Jin'Zil's Forest Magic",
  en_obj = "Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.",
}
T[1059] = {
  title = "Riconquistare la Charred Vale",
  desc = "Le Bloodfury sono state sottomesse. Ma si riorganizzeranno molto presto, se non si fa qualcosa.$B$BMolto a sud delle Barrens si estende una terra conosciuta come Thousand Needles. Se in Thousand Needles viaggi verso ovest finché non raggiungi il limitare della foresta rigogliosa di Feralas, troverai un druido di nome Falfindel Waywarder.$B$BQuesto druido grande e saggio è capace di evocare grandi spiriti della foresta, che possono aiutare nel recupero della Charred Vale.$B$BManda notizia del nostro bisogno! Cercalo subito!",
  obj = "Raggiungi Falfindel Waywarder al confine tra Thousand Needles e Feralas.",
  reward = "Keeper Albagorm è stato saggio a mandarti con tanta urgenza.$B$BVediamo se non riusciamo a chiamare aiuto dalla grande foresta perché raggiunga la Charred Vale prima che sia troppo tardi.",
  en_title = "Reclaiming the Charred Vale",
  en_obj = "Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.",
}
T[1060] = {
  title = "Lettera per Jin'Zil",
  desc = "Hai fatto un ottimo lavoro per me, $n. Sei un vero portafortuna, e c'è una cosa che voglio mostrarti.$B$BLe arpie non vengono dai Barrens. Vengono da un luogo chiamato Stonetalon, lontano a nordovest di qui. Per te è probabilmente un posto pericoloso, ma ho bisogno che questa lettera sia consegnata a un vecchio amico che vive là, uno stregone guaritore di nome Jin'Zil.$B$BSarà felice di sapere che Serena Bloodfeather è morta, e credo che troverai Stonetalon un luogo interessante.",
  obj = "Consegna la lettera di Darsok a Jin'Zil, nella sua grotta a Malaka'Jin, a Stonetalon.",
  progress = "Hai l'aria di un tipo losco. Hai qualcosa da mostrarmi?",
  reward = "Ahh, una lettera di Darsok. Non ho sue notizie da molti anni.$B$BQuindi l'ultima dei Bloodfeather è morta, eh? Ottima notizia: ricordo quando il mio amico Rokhan andò con quel pazzo di mok'nathal a uccidere sua sorella maggiore. Ah, essere giovani come te...",
  en_title = "Letter to Jin'Zil",
  en_obj = "Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon.",
}
T[1061] = {
  title = "Gli spiriti di Stonetalon",
  desc = "Gli spiriti delle Stonetalon Mountains sono adirati, perché i goblin e i loro servi stanno saccheggiando e bruciando la terra. Così la terra ha gridato, e coloro che sanno ascoltare certe cose... hanno sentito.$B$BSeereth Stonebreak, una promettente sciamana dell'Orda, è stata mandata a Stonetalon. Riferisce di una massiccia deforestazione per mano dei goblin e chiede aiuto.$B$BIncontra Seereth a Stonetalon. Per raggiungerla, segui la strada a ovest del Crossroads dei Barrens. È accampata vicino a Greatwood Vale.",
  obj = "Parla con Seereth Stonebreak nelle Stonetalon Mountains.",
  reward = "Ah, $Gun:una; $C. Molto bene. Avremo bisogno delle tue capacità per occuparci di questi predoni!",
  en_title = "The Spirits of Stonetalon",
  en_obj = "Speak with Seereth Stonebreak in the Stonetalon Mountains.",
}
T[1062] = {
  title = "Invasori goblin",
  desc = "La Venture Company, gestita dai goblin, si è insediata nelle Stonetalon Mountains, abbattendo alberi e bruciando enormi tratti di foresta. Gli spiriti di questo luogo sono quasi accecati dal dolore e dalla rabbia. Dobbiamo fermare la Venture Company!$B$BDirigiti a nordovest, oltre Greatwood Vale e dentro Windshear Crag. Troverai i goblin e i loro servi al lavoro: mostra loro che l'Orda non permetterà lo sfruttamento di Stonetalon. Mostraglielo nella lingua che capiscono meglio...$B$BLa violenza.",
  obj = "Uccidi 15 Venture Co. Logger, poi torna da Seereth Stonebreak al confine tra Stonetalon e i Barrens.",
  progress = "Greatwood Vale si trova a nordovest, $N. Va'. Semina la paura in chi vorrebbe saccheggiare questa terra!",
  reward = "Coraggiosamente fatto, $N.$B$BAlla fine potremmo aver bisogno della saggezza degli anziani tauren per calmare gli spiriti di Stonetalon, ma...$B$BLiberarsi del personale della Venture Company è un'ottima prima mossa contro di loro.",
  en_title = "Goblin Invaders",
  en_obj = "Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens.",
}
T[1063] = {
  title = "L'anziana megera",
  desc = "Per prenderci davvero cura degli spiriti di Stonetalon dobbiamo consultare gli anziani tauren.$B$BNon conosco i nomi di molti dei loro capi, ma di uno sì: Magatha. Ho sentito dire che è molto anziana e che sa molte cose. Se c'è qualcuno in grado di radunare un aiuto spirituale dai tauren, è lei.$B$BMagatha risiede nella capitale dei tauren, Thunder Bluff, su Elder Rise, l'altura nordorientale della città. Parla con Magatha e raccontale del pericolo che incombe sulle Stonetalon Mountains.",
  obj = "Parla con Magatha a Thunder Bluff.",
  reward = "Ti porgo il mio saluto. Sei qui in cerca di consiglio?",
  en_title = "The Elder Crone",
  en_obj = "Speak with Magatha in Thunder Bluff.",
}
T[1064] = {
  title = "Aiuto dai Rinnegati",
  desc = "I tauren hanno un legame con la terra, e mi addolora sentire delle sofferenze di Stonetalon. Ma temo che, per guarire la terra, dobbiamo prima eliminare il male che la affligge.$B$BNon è una fortuna che i Rinnegati siano nostri alleati? Sanno molto di malattie. Credo che possano aiutarci, e così facendo rafforzeranno la fiducia tra i nostri popoli.$B$BParla con Apothecary Zamah. È una studiosa e un'emissaria dei Rinnegati. La troverai nelle Pools of Vision, sotto Spirit Rise.",
  obj = "Parla con Apothecary Zamah nelle Pools of Vision a Thunder Bluff.",
  reward = "Magatha mi ha avvisata del tuo arrivo, $N. Anche se il mio cuore non batte più, provo ancora dolore per gli spiriti di Stonetalon.$B$BI Rinnegati sono ansiosi di offrire l'aiuto che possiamo.",
  en_title = "Forsaken Aid",
  en_obj = "Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff.",
}
T[1065] = {
  title = "Viaggio a Tarren Mill",
  desc = "Per liberare Stonetalon dalla Venture Company servono misure estreme. Estreme, ma senza spargimenti di sangue.$B$BUn mio collega potrebbe avere proprio lo strumento che ci serve. Si chiama Lydon e vive nella città di Tarren Mill, nelle Hillsbrad Foothills, nella lontana terra di Lordaeron.$B$BPer raggiungere Hillsbrad, viaggia in dirigibile fino alla nostra capitale, Undercity. Poi vai a nord fino a Tirisfal Glades, a sudovest fino a Silverpine e a sud fino a Hillsbrad.$B$BCerca Lydon e consegnagli questa nota. Gli spiega ciò di cui abbiamo bisogno.",
  obj = "Porta la Zamah's Note ad Apothecary Lydon a Tarren Mill.",
  progress = "Ah, sei qui con i miei nuovi soggetti di prova?",
  reward = "Una nota di Zamah? Le sue necessità devono essere grandi, se manda un messaggio da così lontano. Vediamo cosa dice...$B$BAh, splendido! So esattamente cosa fare!",
  en_title = "Journey to Tarren Mill",
  en_obj = "Bring Zamah's Note to Apothecary Lydon in Tarren Mill.",
}
T[1066] = {
  title = "Sangue di innocenti",
  desc = "Creerò una tossina per prosciugare la violenza dalla Venture Company, rendendoli deboli e docili. Dovrebbe risolvere il problema dell'Orda a Stonetalon, no?$B$BMa per creare la tossina mi servirà il sangue di innocenti, un ingrediente difficile da procurarsi.$B$BPer fortuna il Syndicate, un gruppo di briganti umani di questa zona, si serve di maghi delle ombre... e quei maghi raccolgono sangue innocente per i loro scopi poco raccomandabili.$B$BPuoi trovare i Syndicate Shadow Mage a Durnholde Keep, a sud-est.",
  obj = "Porta 5 Vial of Innocent Blood ad Apothecary Lydon, a Tarren Mill.",
  progress = "Hai trovato i Syndicate Shadow Mage e raccolto da loro il sangue?",
  reward = "Molto bene! Immagino che il Syndicate ti abbia dato poco filo da torcere, no?$B$BCome ho detto, il sangue di innocenti non è una cosa facile da procurarsi. Siamo fortunati che i Syndicate Shadow Mage abbiano fatto il lavoro difficile per noi.$B$BOra aspetta un momento, mentre preparo il mio intruglio...",
  en_title = "Blood of Innocents",
  en_obj = "Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.",
}
T[1067] = {
  title = "Ritorno a Thunder Bluff",
  desc = "Ecco la tossina. Se la usi contro la Venture Company dovrebbe dare risultati favorevoli, forse perfino contagiosi. Devo dire che è piuttosto entusiasmante vedere il mio lavoro applicato sul campo!$B$BMa prima di usarla, portala ad Apothecary Zamah. Deve creare un metodo per somministrare la tossina, in modo da massimizzarne l'effetto.",
  obj = "Porta Lydon's Toxin ad Apothecary Zamah, a Thunder Bluff.",
  progress = "Sei $Gtornato:tornata;, $N. Porti aiuto da parte di Apothecary Lydon?",
  reward = "Una tossina da Apothecary Lydon? Molto bene. Se conosco Lydon, questa tossina sarà piuttosto efficace contro la Venture Company...",
  en_title = "Return to Thunder Bluff",
  en_obj = "Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.",
}
T[1068] = {
  title = "Macchine sminuzzatrici",
  desc = "C'è un legame tra la magia spirituale degli sciamani e la magia naturale dei druidi. È per questo che noi sciamani possiamo sentire la supplica degli spiriti di Stonetalon. Molti dei loro sussurri mi sfuggono, ma un messaggio, una visione, è chiara...$B$BHo avuto la visione di due macchine a forma d'uomo nel Windshear Crag, a nord-ovest della Greatwood Vale, che abbattevano alberi a una velocità impossibile. Queste bestie di metallo vanno fermate!$B$BNella mia visione, le macchine erano marchiate con simboli strani:$B$BXT:4 e XT:9.",
  obj = "Uccidi le sminuzzatrici XT:4 e XT:9, poi torna da Seereth Stonebreak, al confine tra le Stonetalon Mountains e le Barrens.",
  progress = "Gli spiriti degli alberi gemono per la perdita dei loro fratelli, $N. Devi distruggere le sminuzzatrici XT:4 e XT:9, o temo che Stonetalon non sarà mai risanata.",
  reward = "La distruzione delle macchine XT:4 e XT:9 ha placato molti degli spiriti di Stonetalon, $N. Con la loro perdita, speriamo che la Venture Company si tolga da queste montagne.$B$BPerché se non lo farà, temo che le atrocità subite da questo luogo impallidiranno davanti a ciò che verrà.",
  en_title = "Shredding Machines",
  en_obj = "Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.",
}
T[1069] = {
  title = "Uova di ragno Deepmoss",
  desc = "Le frittate di uova di ragno sono l'ultima moda a Booty Bay! Il problema è... che a Booty Bay non ci sono uova.$B$BPercepisco un'occasione!$B$BA Windshear Crag e a Sishir Canyon, nelle Stonetalon Mountains a nordovest, vive il ragno deepmoss. Portami le sue uova e ti pagherò una fortuna!$B$BA Windshear Crag le uova si trovano a grappoli sotto i pochi alberi rimasti.$B$BA Sishir Canyon... beh, se hai lo stomaco debole forse faresti meglio a raccogliere solo le uova di Windshear Crag...",
  obj = "Porta 15 Deepmoss Egg a Mebok Mizzyrix a Ratchet.",
  progress = "Hai preso le uova, $N? Ho già concluso un accordo di spedizione con Wharfmaster Dizzywig!",
  reward = "Le hai prese! Grazie!$B$BLe farò mandare a Dizzywig e spedire a Booty Bay. Sento già il profumo dei profitti!$B$BEcco la tua parte, $N. Senza di te non avrei mai concluso l'affare.",
  en_title = "Deepmoss Spider Eggs",
  en_obj = "Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet.",
}
T[1070] = {
  title = "Di guardia a Stonetalon",
  desc = "Salve, $N.$B$BA vederti sembri $Gpieno:piena; di voglia di girare il mondo. Sei mai $Gstato:stata; alle Stonetalon Mountains? È una terra flagellata dalla Venture Co. e da altri nemici degli elfi della notte.$B$BDi recente Sentinel Wolfrunner ha mandato là la mia amica Kaela Shadowspear a indagare su quel che sta accadendo a quella terra, ma non ho ancora sue notizie. Sono ancora più preoccupata perché l'Alleanza ha mandato con lei un mago gnomo... segno di guai, di sicuro.$B$BLa cercheresti, per poi riferire a me?",
  obj = "Trova Kaela Shadowspear, che domina la valle all'ingresso di Windshear Crag, nelle Stonetalon Mountains.",
  reward = "Ah, sei $Gvenuto:venuta; da Ashenvale per volere di Tara — quanto mi mancano lei, la mia terra e i miei amici. Deve cavarsela bene con le Sentinelle, se può permettersi di assoldare avventurieri per altri incarichi. Sono orgogliosa di lei.$B$BÈ un piacere conoscerti, $N.",
  en_title = "On Guard in Stonetalon",
  en_obj = "Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.",
}
T[1071] = {
  title = "La tregua di uno gnomo",
  desc = "Vedi, $N, io sono un membro dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, e il mio obiettivo... anzi, il mio DOVERE! è mostrare agli elfi della notte che un misto di magia, miscele e meccanismi può aiutare a salvare le loro foreste.$B$BMa è una guerra dura da combattere, e i goblin sembra si riproducano come conigli. Non ho nemmeno avuto il tempo di costruire le mie invenzioni più nuove!$B$BMi serve un po' di tempo per pianificare e organizzarmi. Ma per farlo mi serve il tuo aiuto per tenere a bada i goblin nel Windshear Crag, a est...",
  obj = "Uccidi 10 Venture Co. Logger e 10 Venture Co. Deforester, poi torna da Gaxim Rustfizzle a Stonetalon.",
  progress = "Come va la battaglia dalle tue parti, $N?",
  reward = "Grazie mille del tuo aiuto, $N. Sei $Gtornato:tornata; giusto in tempo, tra l'altro.$B$BCredo di avere un piano perfetto... esplosivi. No, quello non è il piano, ma ne fa parte.$B$BVedi, sto usando esplosivi ad alto potenziale (non preoccuparti, non sono pericolosi come pensano tutti) per ricacciare un po' indietro i goblin. Riesco a spingerli dove voglio con qualche detonazione ben piazzata lungo i bordi delle montagne, ma da qualche giorno sono a corto di scorte...",
  en_title = "A Gnome's Respite",
  en_obj = "Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.",
}
T[1072] = {
  title = "Un vecchio collega",
  desc = "Il congegno a cui penso è la mia versione più avanzata finora. Ma servirà una pozione speciale perché funzioni. Tanto vale prendere la roba buona, visto che questa missione potrebbe essere la tua ultima.$B$BE per questo ci serviranno esplosivi potenti: il Nitromirglyceronium.$B$BL'unico che sa fare l'NG-5 è un mio vecchio amico: Lomac Gearstrip. Cercalo a Tinker Town.$B$BTu convincilo a farcene un po', di NG-5, e io mi metto al lavoro sulla disposizione dei miei congegni.",
  obj = "Parla con Lomac Gearstrip a Ironforge.",
  reward = "Ahhh... Ti manda Gaxim, eh? E come faccio a sapere che non mi stai mentendo?! Mmh? Mmh...?",
  en_title = "An Old Colleague",
  en_obj = "Speak to Lomac Gearstrip in Ironforge.",
}
T[1073] = {
  title = "Incapacità + sostanze chimiche = divertimento",
  desc = "Ahahah... ti serve il Nitromirglyceronium per impedire a dei goblin di distruggere una foresta?!$B$BNon mi importa se conosci Gaxim o no... ti do la roba solo per vedere te o loro esplodere in mille pezzettini.$B$BC'è un problema, però: sono a secco.$B$BMa facciamo così: tu mi porti le pozioni giuste e io te ne preparo subito un po'.$B$BIl minimo che puoi fare è dimostrare di avere un po' di abilità come alchimista, prima che ti dia un campione della mia più grande creazione.",
  obj = "Porta 4 Minor Mana Potion e 2 Elixir of Fortitude a Lomac Gearstrip, a Ironforge.",
  progress = "Non posso fare Nitromirglyceronium se non ho le pozioni... sono essenziali per prepararlo.",
  reward = "Andranno benissimo.$B$BSe non sapessi come stanno le cose, $Gstraniero:straniera;, direi che te ne intendi di alchimia. Bene, bene... il mondo non è fatto solo di spade e stregoneria, sai?",
  en_title = "Ineptitude + Chemicals = Fun",
  en_obj = "Bring 4 Minor Mana Potions and 2 Elixirs of Minor Fortitude to Lomac Gearstrip in Ironforge.",
}
T[1074] = {
  title = "Incapacità + sostanze chimiche = divertimento",
  desc = "Eccoti $Gservito:servita;, $Gstraniero:straniera;. Stacci $Gattento:attenta;, però... è roba volatile.$B$BSe sei davvero $Gun amico:un'amica; di Gaxim, salutamelo. Se non lo sei, divertiti a farti saltare in aria.",
  obj = "Riporta il Nitromirglyceronium a Gaxim Rustfizzle, a Stonetalon.",
  progress = "Ah, che bello, sei $Gtornato:tornata;.",
  reward = "Il tuo compito è stato svolto alla perfezione, $N.$B$BL'NG-5 è il componente indispensabile della ricetta per far detonare i carri di dinamite.$B$BCosa? Sì, dinamite... carri interi. È la distrazione perfetta, te lo dico io... aspetta e vedrai.",
  en_title = "Ineptitude + Chemicals = Fun",
  en_obj = "Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.",
}
T[1075] = {
  title = "Una pergamena da Mauren",
  desc = "Bene, passiamo alla parte del mio piano sulla detonazione a distanza... oh, non te l'ho ancora spiegata, vero?$B$BAllora, in breve è così: con un po' di magia posso fare in modo che gli esplosivi saltino mentre tu non sei nei paraggi. Sto mettendo insieme un congegno che ti permetterà di premere un solo pulsante e far esplodere l'NG-5 quando sei $Gpronto:pronta;.$B$BMa mi serve un incantesimo da un amico a Stormwind: si chiama Collin Mauren. Lo trovi nel Mage Quarter, laggiù. È umano, quindi non dovrebbe essere difficile da notare.",
  obj = "Trova Collin Mauren a Stormwind.",
  reward = "Dunque, questo incantesimo che ti serve: uno che ti permetta di far detonare esplosivi a distanza... mmm.",
  en_title = "A Scroll from Mauren",
  en_obj = "Find Collin Mauren in Stormwind.",
}
T[1076] = {
  title = "Diavoli a Westfall",
  desc = "Ah, credo di averlo. Un incantesimo di messaggio... credo sia questo l'effetto che cerca.$B$BDovrò creare una pergamena con l'incantesimo impresso sopra. Per farlo mi serviranno i detriti di un Dust Devil.$B$BMentre io raccolgo il resto dei componenti, perché non vai a Westfall a cercare una di quelle creature immonde? Sono pericolose, ma sono sicuro che non è nulla che tu non possa gestire, se sei $Gdisposto:disposta; a sottoporti a uno degli esperimenti di Gaxim.$B$BSarò qui quando torni.",
  obj = "Porta Dust Devil Debris a Collin Mauren, a Stormwind.",
  progress = "Salve, $N. Hai trovato il componente che mi serve?",
  reward = "Concedimi solo qualche momento e avrò pronta la tua pergamena.",
  en_title = "Devils in Westfall",
  en_obj = "Bring Dust Devil Debris to Collin Mauren in Stormwind.",
}
T[1077] = {
  title = "Consegna speciale per Gaxim",
  desc = "Ecco a te, $N. Questa dovrebbe andare benissimo.$B$BTi prego, porta i miei saluti a Gaxim quando lo rivedrai. Non vedo l'ora di sentire di questa avventura, quando sarà giunta al termine.$B$BSta' bene.",
  obj = "Porta la Scroll of Messaging a Gaxim Rustfizzle, a Stonetalon.",
  progress = "Ahah! Sei $Gtornato:tornata;! Ce l'hai? Hai l'incantesimo?",
  reward = "È perfetto, $N! Ben fatto.$B$BQuesto incantesimo, mescolato all'NG-5, farà l'esplosivo a distanza perfetto.$B$BRiusciremo a creare la distrazione perfetta per te, così potrai intrufolarti e rubare le lettere e i piani di ingegneria della Venture Co.$B$BQuesto rallenterà di sicuro le loro opere di deforestazione.",
  en_title = "Special Delivery for Gaxim",
  en_obj = "Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.",
}
T[1078] = {
  title = "Recupero per Mauren",
  desc = "I viaggiatori continuano a chiedermi delle Stonetalon Mountains. Pare sia un luogo molto amato per le avventure: non importa se cerchi wyvern, elementali o se hai affari con la Venture Co.$B$BNella Charred Vale, nel cuore di Stonetalon, c'era una specie di basilischi le cui scaglie, ridotte in polvere, erano un reagente meraviglioso per certi incantesimi che ho creato.$B$BSe quei basilischi vivono ancora, mi piacerebbe molto avere qualcuna delle loro scaglie.$B$BFa' con calma, non c'è fretta, ma posso pagare bene.",
  obj = "Porta 8 Crystalized Scale a Collin Mauren, a Stormwind.",
  progress = "Salve di nuovo, $N.$B$BSei già $Gtornato:tornata; dalla Vale di Stonetalon con quelle scaglie?",
  reward = "È perfetto, $N. Grazie infinite.$B$BForse un giorno, in futuro, potrò aiutarti come tu hai aiutato me.",
  en_title = "Retrieval for Mauren",
  en_obj = "Bring 8 Crystalized Scales to Collin Mauren in Stormwind.",
}
T[1079] = {
  title = "Operazioni segrete — Alpha",
  desc = "Ci siamo, $N. Presta molta attenzione. I congegni sono pronti e possono essere usati.$B$BPrendi queste pagine: ti spiegheranno meglio i detonatori e gli esplosivi, e dove dovresti piazzarli.$B$BRicorda, il successo della tua missione non dipende da quanta distruzione provochi. Il successo del piano Alpha dipende dal fatto che tu riporti indietro i piani di ingegneria della Venture Co. da dentro la segheria a sud del Cragpool Lake.",
  obj = "Recupera i Venture Co.'s Engineering Plans dalla segheria nel Windshear Crag.",
  progress = "Hai preso i piani, $N?",
  reward = "Davvero straordinario! È un colpo enorme per la Venture Co.$B$BRiusciremo a trovare i punti deboli delle loro macchine e anche a incorporare i loro progetti nelle nostre creazioni. Questa sì che è una giornata meravigliosa.",
  en_title = "Covert Ops - Alpha",
  en_obj = "Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.",
}
T[1080] = {
  title = "Operazioni segrete — Beta",
  desc = "Il piano Beta è proprio come il piano Alpha, $N.$B$BCreiamo una distrazione e poi rubiamo le loro preziose lettere.$B$BLa chiave è prendere le lettere... ricordalo.$B$BLe pagine che ti ho già dato ti diranno dove piazzare gli esplosivi. Tu torna qui $Gvivo:viva; e con quelle lettere...",
  obj = "Recupera le Venture Co. Letters dalla Windshear Mine, all'estremità est del Windshear Crag.",
  progress = "Com'è andata, $N?",
  reward = "Incredibile, $N! Kaela e le Sentinelle saranno felicissime. Con la tua abilità e le mie creazioni, siamo inarrestabili.",
  en_title = "Covert Ops - Beta",
  en_obj = "Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.",
}
T[1081] = {
  title = "Accoglienza da Tyrande",
  desc = "$N, non ho dubbi che Tyrande Whisperwind in persona vorrebbe ringraziarti per aver preso parte a questa missione.$B$BIn superficie può non sembrare, ma quello che hai contribuito a mettere in moto potrebbe benissimo rafforzare la nostra posizione nelle Stonetalon Mountains.$B$BSe ti consideri $Gnostro alleato:nostra alleata; contro queste atrocità, va' da Tyrande nel Temple of the Moon, a Darnassus.",
  obj = "Trova Tyrande Whisperwind a Darnassus.",
  reward = "Salve, $N. Ho davvero già sentito il tuo nome e, per quanto tu sia ancora $Gpieno:piena; di giovinezza, sono lieta di vedere la strada che hai scelto per te $Gstesso:stessa;.$B$BMi faresti un grande onore se accettassi questo come dono di riconoscenza.",
  en_title = "Reception from Tyrande",
  en_obj = "Find Tyrande Whisperwind in Darnassus.",
}
T[1082] = {
  title = "Aggiornamento per Sentinel Thenysil",
  desc = "$N, hai compiuto una grande azione dando una mano qui.$B$BLe Sentinelle di Ashenvale ti ricompenseranno bene se le informerai che Gaxim e io siamo vivi. Di' loro che siamo sulla buona strada per fermare la Venture Co. e risanare queste terre.$B$BTrova Tara Thenysil ad Astranaar; sarà contenta di vedere che sei $Gtornato:tornata; con buone notizie.",
  obj = "Torna da Sentinel Thenysil, ad Ashenvale.",
  reward = "Grazie, $N. Hai reso un servizio alle Sentinelle.$B$BSono felice di sapere che Kaela... e persino Gaxim, stanno bene.$B$BTi sei $Gguadagnato:guadagnata; la nostra stima.",
  en_title = "Update for Sentinel Thenysil",
  en_obj = "Return to Sentinel Thenysil in Ashenvale.",
}
T[1083] = {
  title = "Spiriti infuriati",
  desc = "Non so con certezza cosa abbia fatto la Venture Co. alla Vale, ma è evidente che sono stati sopraffatti dalle creature del posto.$B$BHanno dato fuoco alla foresta e hanno usato le loro invenzioni di distruzione per decimare quanto più possibile della Vale.$B$BMa nella loro ignoranza hanno liberato anche qualcos'altro: spiriti ardenti, elementali di fiamma, pietra e rabbia.$B$BLa terra non ha speranza di vedere il sorriso di Elune finché queste creature vagano libere.$B$BPortami i loro Smoldering Ember a dimostrazione di averne ridotto il numero.",
  obj = "Porta 8 Smoldering Ember, presi da uno qualsiasi degli elementali del fuoco nella Charred Vale, a Kaela Shadowspear, a Stonetalon.",
  progress = "La prima volta che ho visto la Charred Vale ho quasi pianto, $N.",
  reward = "I resti del nostro nemico... la tua forza ci è molto utile, $N. Grazie.",
  en_title = "Enraged Spirits",
  en_obj = "Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.",
}
T[1084] = {
  title = "Antichi feriti",
  desc = "Mi sembra evidente che i protettori della Vale, i treant, c'entrino qualcosa con il fatto che la Venture Co. sia stata respinta. Purtroppo, anche quei guardiani, un tempo gloriosi, ora sono corrotti.$B$BGaxim pensa che la loro corruzione sia in qualche modo legata alle armi che i goblin hanno usato durante la ritirata.$B$BGli ho detto che avrei raccolto un campione da un treant ferito e gliel'avrei lasciato studiare, per capire se è vero.$B$BPortami un po' di quelle schegge, così lo gnomo potrà dirmi di più...",
  obj = "Porta un pezzo di Corroded Shrapnel a Kaela Shadowspear, a Stonetalon.",
  progress = "Ho la sensazione che Gaxim troverà un uso per quelle schegge, a prescindere da come la Venture Co. le ha usate in passato.",
  reward = "Grazie, $N.$B$BQuesto dovrebbe bastare e avanzare perché Gaxim capisca come i treant sono stati corrotti. Glielo porterò subito.",
  en_title = "Wounded Ancients",
  en_obj = "Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.",
}
T[1085] = {
  title = "Di guardia a Stonetalon",
  desc = "La situazione qui a Stonetalon è evidentemente grave, se un elfo della notte e uno gnomo lavorano insieme.$B$BLa Venture Co. ha devastato queste terre e ho passato quasi tutto il mio tempo a mettere fine alla distruzione.$B$BNon giudicare Gaxim troppo in fretta: capisce che abbiamo bisogno di collaborare.$B$BSe vuoi aiutarci, comincia col parlare con Gaxim.$B$BMi dispiace di non poterti ancora rimandare da Tara con buone notizie. Forse presto.",
  obj = "Parla con Gaxim.",
  reward = "Infida... infida e pericolosa, ecco com'è questa terra.$B$BMa io sono qui per mostrare agli elfi della notte che con l'aiuto della cara vecchia ingegneria e un pizzico di magia è un po' più sicura.$B$BVedi, rinunciare del tutto alla magia non aiuterà gli elfi della notte — ne hanno bisogno. Il mondo ne ha bisogno. E se ci metti anche ingegneria e alchimia, non puoi sbagliare. Le possibilità sono infinite.",
  en_title = "On Guard in Stonetalon",
  en_obj = "Speak to Gaxim.",
}
T[1086] = {
  title = "L'aeroporto delle macchine volanti",
  desc = "La tossina è pronta. Non resta che consegnarla. Sei tu, $N, a doverlo fare.$B$BLa Venture Company deve pur avere un modo per mandare messaggi e carichi leggeri tra il suo quartier generale e le sue attività a Stonetalon. Probabilmente è un piccolo porto aereo — non abbastanza grande per uno zeppelin, ma forse per una macchina volante. Devi cercare nelle zone di Stonetalon controllate dalla Venture Company e trovare questo porto aereo, se esiste. Se lo trovi, metti lì la tossina.$B$BMettila, e corri via.",
  obj = "Porta il Toxic Fogger al porto aereo della Venture Co., poi torna da Apothecary Zamah.",
  progress = "Devi trovare l'aeroporto della Venture Company, se esiste, $N.",
  reward = "Hai trovato il porto? Ben fatto, $N! Sono certa che i goblin siano rimasti piuttosto sorpresi dalla tua consegna! Speriamo che quella tossina trovi la strada per il loro quartier generale.$B$BHai servito bene il tuo popolo, e ti consiglio di ignorare qualunque senso di colpa tu possa provare per aver avvelenato la Venture Company. Meritano di molto peggio.$B$BE se c'è un briciolo di saggezza che i Reietti possono insegnare ai loro alleati, è questo:$B$BNon evitare le strade oscure... se quelle strade portano alla vittoria.",
  en_title = "The Flying Machine Airport",
  en_obj = "Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.",
}
T[1087] = {
  title = "L'eredità di Cenarius",
  desc = "Non puoi immaginare l'odio che provo per questa terra miserabile. La genia di Cenarius e i druidi kaldorei sul picco usano i loro patetici poteri per soffocare il flusso della magia, persino così a sud dei loro patetici possedimenti... le loro amate foreste.$B$BVorrei poter tornare a Jaedenar ed esultare nel flusso della magia, ma il mio padrone non mi permetterà di tornare finché il mio lavoro non sarà finito.$B$BNon ho dubbi che tu ami gli elfi della notte e i loro alleati quanto poco li amo io. Aiutami, e i nostri fini saranno soddisfatti entrambi.",
  obj = "Uccidi 4 Son of Cenarius, 4 Daughter of Cenarius e 4 Cenarion Botanist per Braelyn Firehand, vicino al Sun Rock Retreat.",
  progress = "Qui, incanalare la magia è come tirare su acqua da un pozzo con un secchio pieno di buchi.",
  reward = "Già lo sento... sì... un potere così dolce... la piena che irrompe. I kaldorei sono sciocchi a disprezzare i doni di questo mondo, a rifiutare lo scorrere della magia mentre fluisce cantando nelle tue vene.$B$BChe pallida farsa è la vita senza il suo abbraccio ardente!",
  en_title = "Cenarius' Legacy",
  en_obj = "Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.",
}
T[1088] = {
  title = "Ordanus",
  desc = "Credevano di poter fermare il flusso della magia. Si sbagliavano. Credevano di poter nascondere Ordanus, ma avrò la sua testa!$B$BLa magia mi concede la vera vista. Sì... eccolo là. Un crocevia... In cima a un grande albero, nell'Ashenvale Forest. Un nome... Raynewood. Uno dei figli più antichi del dio della foresta. Lo hanno portato via dal picco prima che potessi trovarlo, ma il suo tempo sta per finire.$B$BPortamela, e condividerò con te un dono potente.",
  obj = "Porta la testa di Ordanus a Braelyn Firehand, vicino al Sun Rock Retreat.",
  progress = "Quando il mio padrone mi ha mandata al picco di Stonetalon, mi aspettavo che tutto ciò che mi sarebbe servito fosse fare scempio degli elfi della notte che brulicavano tra le sacre rovine del nostro antico tempio di Azshara, profanandone la sacralità con il loro tocco... ma Ordanus mi era sfuggito.",
  reward = "Ho conosciuto Ordanus, un tempo, molto tempo fa. Aveva l'arroganza della sua specie, e si teneva al di sopra perfino degli Alti Nobili.$B$BOra la sua testa non sta più così in alto, vero, $N?$B$BTi ho promesso una ricompensa, e l'avrai. Vieni da me.",
  en_title = "Ordanus",
  en_obj = "Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.",
}
T[1089] = {
  title = "Il Den",
  desc = "I druidi hanno costruito il Talon Den su Stonetalon Peak, dove custodiscono molti oggetti potenti.$B$BHanno ideato uno schema complesso per impedire che finiscano nelle mani sbagliate.$B$BPer fortuna, sono riuscita a... estrarre qualche dettaglio da uno di loro.$B$BNascosta in una piccola lanterna all'ingresso del Den, troverai la Gatekeeper's Key: con quella potrai aprire i nascondigli sparsi per il Den. Gli oggetti di quei nascondigli ti permetteranno di aprire il loro tesoro, che si trova in una delle aree centrali.",
  obj = "Raggiungi il Den su Stonetalon Peak. Usando la Gatekeeper's Key, procurati gli oggetti nascosti dei druidi. Usa quegli oggetti per aprire il Talon Den Hoard.",
  progress = "Tre serrature sono scolpite nella pietra.",
  reward = "Mentre le tre chiavi scivolano nelle rispettive aperture, in mezzo alla luce splendente compaiono diversi oggetti.",
  en_title = "The Den",
  en_obj = "Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard. ",
}
T[1090] = {
  title = "Gli ordini di Gerenzo",
  desc = "Sai, un tempo ero la seconda persona più importante di questo cantiere. È cambiato tutto quando è arrivato Gerenzo. Ha licenziato il mio capo, Ziz Fizziks, e mi ha spedito a lavorare giù nelle miniere. Ziz però mi ha detto di restare qui e raccogliere informazioni. Il suo nuovo capo ci pagherà bene se riusciamo a scoprire quali sono i piani di Gerenzo.$B$BComunque, quello che so è che Gerenzo ha ordinato di estrarre grandi quantità di questo minerale verde-oro. Posso procurarti un campione da portare a Ziz, ma dovrai fare attenzione alle pattuglie mentre lo prendo.",
  obj = "Prendi il minerale misterioso da Piznik dopo che ha finito di estrarlo.",
  reward = "Grazie, $N. Per un attimo si è messa un po' male e probabilmente abbiamo attirato fin troppa attenzione su di noi.$B$BLa cosa importante, però, è che abbiamo il campione di minerale, e dovremmo portarlo a Ziz il prima possibile.",
  en_title = "Gerenzo's Orders",
  en_obj = "Get the mysterious ore from Piznik after he finishes mining it.",
}
T[1091] = {
  title = "L'aggiornamento di Kaela",
  desc = "$N, porta queste lettere a Kaela. Sono sicuro che vorrà saperne. O almeno lo vorranno le Sentinelle.$B$BMi raccomando, raccontale che successo abbiamo avuto e che non ce l'avremmo fatta senza un po' di magia.",
  obj = "Porta le Venture Co. Letters a Kaela Shadowspear.",
  progress = "Sì, $N? Cosa posso fare per te?",
  reward = "Questo è davvero interessante.$B$BTu e Gaxim avete fatto un ottimo lavoro, $N. Grazie.",
  en_title = "Kaela's Update",
  en_obj = "Bring the Venture Co. Letters to Kaela Shadowspear.",
}
T[1092] = {
  title = "Gli ordini di Gerenzo",
  desc = "Credo che farei meglio a pensare ad andarmene anch'io. Non ci vorrà molto perché la voce di quello che è successo qui arrivi ai piani alti, e sono sicuro che non la prenderebbero bene a rivedermi.$B$BSgattaiolerò via e raggiungerò Ziz. Si spera che riesca a trovarmi un nuovo lavoro!$B$BProverò a ripulire un po' questo disastro, ma tu porta subito il campione di minerale a Ziz. Mi ha detto che si sarebbe accampato da qualche parte sul lato occidentale del Windshear Crag. Buona fortuna.",
  obj = "Consegna l'Unidentified Ore a Ziz Fizziks, nelle Stonetalon Mountains.",
  progress = "Posso aiutarti in qualcosa?",
  reward = "Ahhh, sapevo di aver fatto la cosa giusta a dire a Piznik di restare indietro. Sono sicuro che gli ingegneri di Undermine saranno molto interessati a dare un'occhiata a questo...$B$BNaturalmente vorrò tenerne un pezzetto per me, ma quello che non sanno non gli fa male, no?",
  en_title = "Gerenzo's Orders",
  en_obj = "Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.",
}
T[1093] = {
  title = "Super Reaper 6000",
  desc = "Terribile quello che la Venture Company ha fatto qui, eh? Ma cosa avevano in testa? Una compagnia di goblin che assume uno gnomo!$B$BPer mia fortuna, Sputtervalve riconosce un genio quando lo vede. Mi ha assunto appena dopo che mi avevano cacciato!$B$BMi dice che hanno costruito una macchina taglialegna enorme, e Sput' vuole che gli rubi i progetti. Purtroppo Gerenzo, maledetto gnomo, mi vuole morto a vista... magari potresti rubare tu i progetti per me? Dovresti riuscire a trovarli addosso a uno dei loro operatori.",
  obj = "Procura i Super Reaper 6000 Blueprints a Ziz Fizziks, nelle Stonetalon Mountains.",
  progress = "Hai trovato quei progetti? Non vedo l'ora di fare colpo sul nuovo capo. Si spera che, una volta convinto della mia lealtà (be', per quanto lo si possa convincere... onore da goblin, sai com'è?), si senta a suo agio a servirsi del mio genio piuttosto notevole.",
  reward = "Ehi, è quello che penso? Ottimo!$B$BAllora, vediamo. Uff... come dovrei capirci qualcosa... non riesco a farmi una ragione di come ragionano gli gnomi. Ti dirò, mi stupisce che siano riusciti a costruire la ruota, figurarsi quelle macchine volanti che gli piacciono tanto.",
  en_title = "Super Reaper 6000",
  en_obj = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.",
}
T[1094] = {
  title = "Altre istruzioni",
  desc = "Questa busta contiene tutte le informazioni che sono riuscito ad arraffare mentre mi buttavano fuori dalla porta... documenti interni della Venture Company, qualche manuale, roba tecnica... Ah, e naturalmente i Super Reaper 6000 Blueprints.$B$BSputtervalve si è stabilito a Ratchet, nelle Barrens. Non dovresti far fatica a trovarlo: è un tipetto verde.",
  obj = "Consegna la Sealed Envelope a Sputtervalve, nelle Barrens.",
  progress = "Salve! Come posso aiutarti?",
  reward = "Fizziks, eh? Non posso dire di fidarmi di lui, ma queste informazioni sembrano abbastanza buone. Cosa non darei per togliermi la Venture Company dai piedi.$B$BCerte macchine però le inventano buone... non posso negare che abbiamo tratto vantaggio da qualcuna delle migliorie che hanno messo a punto.",
  en_title = "Further Instructions",
  en_obj = "Deliver the Sealed Envelope to Sputtervalve in the Barrens.",
}
T[1095] = {
  title = "Altre istruzioni",
  desc = "La faccenda di questo gnomo assunto dalla Venture Company ha fatto un po' di rumore a Undermine. I principi del commercio non approvano che Razdunk si accompagni a questo Gerenzo.$B$BRiddlevox mi ha chiesto di occuparmi del problema, e sono sicuro che glielo abbiano ordinato uno o più principi del commercio. Naturalmente, il direttore non me l'ha detto. Diciamo che ho un presentimento.$B$BComunque sia, Gerenzo va tolto di mezzo, e sarebbe una prova adatta affidare a Fizziks il compito di sistemarlo.",
  obj = "Porta i nuovi ordini a Ziz Fizziks, nelle Stonetalon Mountains.",
  reward = "Eliminare Gerenzo? Ecco una prospettiva a cui non ho niente da obiettare.$B$BGli gnomi sono già abbastanza insopportabili di loro, ma quello che ho saputo di Gerenzo peggiora solo le cose. A quanto pare era uno dei capi ingegneri a Gnomeregan, dove lavorava al loro progetto segreto: non siamo mai riusciti a infiltrarci a Dun Morogh abbastanza a fondo da scoprire i dettagli precisi. È stato un fallimento. I nostri rapporti dicono che, qualunque cosa fosse, è letteralmente esplosa in faccia a loro.",
  en_title = "Further Instructions",
  en_obj = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.",
}
T[1096] = {
  title = "Gerenzo Wrenchwhistle",
  desc = "Ho incontrato Gerenzo una volta, ma lascia che te lo dica: non è bello da vedere. La sua carne sembra marcire, e si è innestato metallo e ingranaggi sul corpo, sostituendo alcune membra con altre meccaniche.$B$BA nord-est di qui, molto sopra Cragpool Lake, su vicino alla ruota ad acqua, è lì che Gerenzo sorveglia tutto il cantiere. Non c'è verso che io riesca a farmi strada combattendo fin lassù, per non parlare di affrontare Gerenzo... Ma tu hai l'aria di potercela fare.$B$BSe lo uccidi per me, ti ricompenserò a dovere!",
  obj = "Porta Gerenzo Wrenchwhistle's Mechanical Arm a Ziz Fizziks, nelle Stonetalon Mountains.",
  progress = "Sputtervalve vorrà una qualche prova che Gerenzo è morto. Credo che il suo braccio meccanico andrà bene.",
  reward = "Guarda quel coso... ci voleva uno gnomo per inventarsi una cosa del genere. Non riesco a capire perché uno dovrebbe tagliarsi un braccio e sostituirlo con quello, quando potrebbe benissimo tenerseli tutti e due e aggiungerne un terzo!$B$BGnomi, te lo dico io...$B$BAlmeno Gerenzo è fuori gioco. Speriamo che basti come prova e che Sputtervalve mi assegni a una delle officine della Tinkers' Union a Gadgetzan o magari perfino a Undermine.",
  en_title = "Gerenzo Wrenchwhistle",
  en_obj = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.",
}
T[1097] = {
  title = "Il compito di Elmore",
  desc = "C'è un fabbro d'armi nano a Stormwind, Grimand Elmore, che mi ha fatto sapere di aver bisogno di aiuto per una consegna. Credo voglia far recapitare un pacco nella sua terra natale, a nord.$B$BHai un bel paio di gambe robuste! Quindi, se ti va di fare un po' di strada, parla con Grimand. Ci faresti comodo qui, ma dobbiamo anche mantenere saldi i legami con i nani.$B$BPuoi trovare Grimand Elmore nell'armeria del Dwarven District di Stormwind, nella zona nordest della città.",
  obj = "Parla con Grimand Elmore.",
  reward = "Sei qui per aiutarmi con la consegna? Benissimo!",
  en_title = "Elmore's Task",
  en_obj = "Speak with Grimand Elmore.",
}
T[1098] = {
  title = "Inseguitori della Morte a Shadowfang",
  desc = "In preparazione di un assalto a Shadowfang, due Inseguitori della Morte sono stati mandati alla fortezza per raccogliere informazioni. Sono passati molti giorni e non sono tornati, ma dobbiamo avere il loro rapporto se vogliamo sperare in un attacco riuscito!$B$BEcco dunque il tuo compito, $N. Va' a Shadowfang Keep, a sud, e trova Deathstalker Adamant e Deathstalker Vincent. Trovali, e se hanno bisogno di aiuto daglielo.$B$BQuesta missione è tanto pericolosa quanto decisiva, $N. Non fallire.",
  obj = "Trova Deathstalker Adamant e Deathstalker Vincent.",
  reward = "Il corpo di Vincent giace spezzato e immobile.$B$BDeathstalker Adamant manderà il suo rapporto a Hadrec... ma qualunque altro dettaglio Vincent avesse scoperto resterà con lui.$B$BStretto nella sua mano, però, c'è un piccolo ninnolo...",
  en_title = "Deathstalkers in Shadowfang",
  en_obj = "Find the Deathstalker Adamant and Deathstalker Vincent.",
}
T[1100] = {
  title = "Il diario di Lonebrow",
  desc = "Apri lentamente il diario consunto di Henrig Lonebrow....",
  obj = "Leggi Henrig Lonebrow's Journal.",
  progress = "Dalla tua aria preoccupata capisco che qualcosa non va....",
  reward = "Dici di aver trovato questo diario addosso a un nano morto? Dammi solo un momento per scorrere le pagine...",
  en_title = "Lonebrow's Journal",
  en_obj = "Read Henrig Lonebrow's Journal.",
}
T[1101] = {
  title = "La megera del Kraul",
  desc = "Povero Heralath! E questo nano... Lonebrow. Che anima coraggiosa era.$B$BNon dobbiamo lasciare che il loro valore vada sprecato. Questa megera... Charlga Razorflank... va fermata.$B$BDi sicuro infiltrarsi nel Kraul sarà pericoloso. Non c'è tempo di mandare notizia a Darnassus. $N, raduna un gruppo per uccidere la megera.$B$BPortami Razorflank's Medallion come prova della sua fine.",
  obj = "Porta Razorflank's Medallion a Falfindel Waywarder, a Thalanaar.",
  progress = "Finché Charlga Razorflank raduna forze nel Razorfen Kraul, queste terre sono in grave pericolo.",
  reward = "La megera ha trovato il riposo eterno. È una notizia fantastica, $N.$B$BIn questi tempi di pericolo, è confortante vedere una persona coraggiosa come te.$B$BCon i tirapiedi di Razorflank sistemati, i nostri studi nella zona possono continuare. Forse adesso potremo capire meglio che cosa, esattamente, abbia corrotto il luogo di riposo di Agamaggan.$B$BTemo però che anche la risposta a questa domanda stia nel tradimento...",
  en_title = "The Crone of the Kraul",
  en_obj = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.",
}
T[1102] = {
  title = "Un destino di vendetta",
  desc = "Cairne è un nobile capo, per aver unito il nostro popolo qui a Thunder Bluff.$B$BMa io non riesco a perdonare chi ci ha cacciati dalle nostre terre ancestrali con la stessa facilità di altri. Il mio popolo ha abitato le Barrens meridionali per decenni. Quella terra per noi era sacra. Ma siamo stati cacciati da numerosi nemici.$B$BUn destino di vendetta attende la megera, Charlga Razorflank, che raduna un immondo esercito dall'interno del Razorfen Kraul.$B$BPortami il cuore di Razorflank e potrò morire in pace, $N.",
  obj = "Porta Razorflank's Heart ad Auld Stonespire, a Thunder Bluff.",
  progress = "Quando saprò che le immonde bestie del Razorfen Kraul sono state cacciate dalla loro immonda tana, potrò riposare in pace, sapendo che la vendetta è stata servita.$B$BHai cacciato i quilboar dal Kraul? Mi porti buone notizie sotto forma del cuore di Razorflank?",
  reward = "Vedo che l'odiosa tribù del Razorfen Kraul ora conosce il dolore del mio popolo. Ben gli sta, a quelle bestie immonde.$B$BCacciare qualcuno da una terra sacra è un peccato che merita la vendetta più severa.$B$BGrazie, $N, per avermi aiutato nella mia sventura.",
  en_title = "A Vengeful Fate",
  en_obj = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.",
}
T[1104] = {
  title = "Veleno delle saline",
  desc = "Ho tanti progetti per la nostra auto a razzo! Tantissimi! E devo provarli tutti!!$B$BSto lavorando a un nuovo tipo di carburante. Uno che brucia davvero davvero davvero caldo!! Non ho ancora azzeccato la miscela, ma credo di sapere cosa mi serve...$B$BGli scorpidi che vagano per le Shimmering Flats hanno un veleno pieno zeppo di sale. È unico nel suo genere! Ed è proprio quel che mi serve!$B$BPortami il veleno e fidati: la nostra auto volerà!!",
  obj = "Porta 6 Salty Scorpid Venom a Fizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Ehi ehi ehi! L'hai preso quel veleno??",
  reward = "Benissimo! Questo veleno funzionerà alla grande! Grazie, $N!$B$BOra devo solo farlo bollire, applicare lo skipper-otomero, aggiungere un nega-catalizzatore e... Accidenti! Dove sono i miei appunti!?",
  en_title = "Salt Flat Venom",
  en_obj = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.",
}
T[1105] = {
  title = "Gusci induriti",
  desc = "Mio fratello sta lavorando a un nuovo carburante per la sua auto a razzo. È geniale, davvero. Così geniale che... credo che quel nuovo carburante che sta progettando sia abbastanza forte da mangiarsi il telaio dell'auto!$B$BVoglio rinforzare i serbatoi prima che succeda.$B$BLe tartarughe là fuori nelle saline hanno gusci durissimi. Voglio usarli per fare serbatoi nuovi per la nostra auto a razzo. Serbatoi che reggano il nuovo carburante di mio fratello.$B$BMi sembri abbastanza responsabile. Me li prendi quei gusci?",
  obj = "Porta 9 Hardened Tortoise Shell a Wizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Mio fratello sta facendo progressi con il suo nuovo carburante, e la cosa mi preoccupa. Devo mettermi al lavoro su un serbatoio di guscio di tartaruga il prima possibile!$B$B$N, ce li hai quei gusci?",
  reward = "Li hai presi! Grazie, $N!$B$BCaspita, questi gusci sono più duri di quanto pensassi! Eh, a lavorarli piegherò di sicuro una cassetta intera di attrezzi!",
  en_title = "Hardened Shells",
  en_obj = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.",
}
T[1106] = {
  title = "Martek the Exiled",
  desc = "Sto sviluppando un motore nuovo che farà andare l'auto velocissima! Abbastanza veloce da volare, lo so! Mi servono solo pistoni che reggano sforzi molto molto pesanti. Tutte le mie prove sono fallite perché non riesco a fare pistoni abbastanza duri!$B$BMa c'è qualcuno che forse sa come si fa.$B$BSi chiama Martek the Exiled. È un grande fabbro e di metalli ne sa più di chiunque altro. Portagli questa lettera, so che può aiutare!$B$BMa è lontano lontano: ad Azeroth, nei Badlands, in un accampamento, con un goblin!$B$BTrovalo!",
  obj = "Porta Fizzle's Letter a Martek the Exiled, nei Badlands.",
  progress = "Be', mi hai trovato. Buon per te.$B$BSei qui per quell'ascia che ho fatto per Gath'Ilzogg? O sei qui a riscattare l'onore di Duchess Pamay?$B$BA dire il vero non m'importa quale delle due. Se sei qui per combattere, allora sbrighiamoci...",
  reward = "Ti manda Fizzle? Be', allora la cosa cambia! Certo che ti aiuto. Fizzle e suo fratello sono tra le poche persone che non mi vogliono morto!$B$BQuindi Fizzle vuole fare dei pistoni, eh? Pistoni abbastanza robusti da reggere qualunque sforzo abbia in mente, e se conosco Fizzle questa sua nuova auto è un vulcano su ruote!",
  en_title = "Martek the Exiled",
  en_obj = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.",
}
T[1107] = {
  title = "Encrusted Tail Fins",
  desc = "La nostra auto a razzo è la cosa più veloce delle saline! Così veloce che... temo che l'attrito la farà a pezzi!$B$BPer evitarlo devo creare un composto con cui rivestire le parti in movimento. Deve essere duro ma non fragile, e deve resistere alla corrosione del sale, altrimenti il tempo passato nelle Shimmering Flats se lo mangerà.$B$BHai mai sentito parlare del Vile Reef, $N? È al largo della costa di Stranglethorn Vale. Là vivono i murloc Saltscale, e le loro pinne caudali sono un ingrediente fondamentale del mio composto.",
  obj = "Porta 10 Encrusted Tail Fin a Wizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Ce le hai le pinne caudali? Se non riesco a proteggere la nostra auto dalla sua stessa velocità, in queste corse non durerà molto.",
  reward = "Grazie, $N! Dopo averle macinate e fuse con qualche altro ingrediente, il composto sarà pronto. E dopo di che l'auto sarà al sicuro dalla propria velocità.$B$BAl sicuro, finché non va a sbattere contro qualcosa...",
  en_title = "Encrusted Tail Fins",
  en_obj = "Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats.",
}
T[1108] = {
  title = "Indurium",
  desc = "Non sto qui fuori solo per stare lontano dalla gente. Nei Badlands c'è una ricchezza di metallo, $N, se hai il fegato di andartela a prendere.$B$BIl metallo si chiama indurium e, guarda caso, si dice che abbia un'alta resistenza al calore e agli sforzi. Potrebbe andar bene per l'auto di Fizzle.$B$BMa assicuriamocene. Procurami dei campioni di indurium e ne proverò le proprietà.$B$BIl vero minerale di indurium sta nel profondo di Uldaman, ma i trogg Stonevault dei Badlands a volte ne hanno addosso delle scaglie. Portami quelle scaglie.",
  obj = "Porta 10 Indurium Flake a Martek the Exiled, nei Badlands.",
  progress = "Hai trovato delle scaglie di indurium, $N? Ho la forgia accesa e pronta per provarle.",
  reward = "Ah sì, queste andranno bene. Ora mettiamole sul fuoco e vediamo come se la cavano...",
  en_title = "Indurium",
  en_obj = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.",
}
T[1109] = {
  title = "Uno, due... guano!",
  desc = "Come vedi, $N, alla Royal Apothecary Society stiamo conducendo degli esperimenti molto... interessanti.$B$BIn quanto Master, qui, è mio compito sovrintendere ai più ambiziosi dei nostri tentativi alchemici. Tanto lavoro e così poco tempo!$B$BPer $Gun:una; $C, hai l'aria di chi ha viaggiato molto. Forse puoi aiutarmi.$B$BHo bisogno di una sostanza rara. È un materiale immondo; viene da una rara specie di pipistrelli che si trova solo in quel buco fangoso noto come Razorfen Kraul. Portami il guano dei Kraul Bat, così potremo cominciare il nostro lavoro...",
  obj = "Porta 1 mucchio di Kraul Guano a Master Apothecary Faranell, nell'Undercity.",
  progress = "Ah, vedo che sei $Gtornato:tornata;. Sei $Griuscito:riuscita; a procurarti del Kraul Guano?",
  reward = "Splendido! È proprio l'inizio che ci serviva, $N.",
  en_title = "Going, Going, Guano!",
  en_obj = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.",
}
T[1110] = {
  title = "Rocket Car Parts",
  desc = "Eh eh, con tutte le corse che fanno qui, non c'è da stupirsi che ogni tanto capiti qualche incidente. Se ti guardi intorno nelle Shimmering Flats vedrai i segni degli schianti passati: pezzi di auto a razzo sparsi dappertutto!$B$BE quei pezzi valgono soldi per gnomi e goblin. Sono sempre a caccia di altri aggeggi da montare sulle loro auto.$B$BQuindi va' là fuori e procurami dei pezzi. Portamene un mucchio e ti pagherò bene.",
  obj = "Porta 30 Rocket Car Parts a Kravel Koalbeard, nelle Shimmering Flats.",
  progress = "$N, sei $Gstato:stata; là fuori nelle Flats? Hai riportato quel carico di pezzi che volevo?",
  reward = "Perbacco, guarda che roba! In quel mucchio di rottami c'è della bella merce. Sono sicuro che riuscirò a rivenderla per una bella sommetta.$B$BE... è un orecchio quello che vedo schiacciato tra quelle due lamiere?? Ahia! Eh, non vorrei proprio essere quel pilota!$B$BGrazie, $N. Ecco la tua paga. Ed ecco un consiglio, gratis...$B$BSe cerchi abbastanza bene, nella disgrazia altrui trovi sempre un profitto.",
  en_title = "Rocket Car Parts",
  en_obj = "Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats.",
}
T[1111] = {
  title = "Wharfmaster Dizzywig",
  desc = "Il mio mestiere è procurare alla gente quel che le serve, e gli gnomi là in fondo hanno un ordine di pezzi da far arrivare. I loro pezzi sono stati spediti a Ratchet una settimana fa, ma non sono riuscito a fare il viaggio.$B$BAllora, te la senti di sgambettare un po'? Va' a Ratchet e consegna questo ordine a Wharfmaster Dizzywig: probabilmente sarà ai moli.$B$BFammi questo favore e avrò altri lavori per te.$B$BLavori, $Gamico mio:amica mia;, con un bel potenziale di profitto...",
  obj = "Porta Kravel's Parts Order a Wharfmaster Dizzywig, a Ratchet.",
  progress = "Parla più forte! Dimmi, consegni o ritiri?",
  reward = "Oh sì. I pezzi per Kravel. Meno male che sei qui. Questa roba è rimasta qui fuori per giorni e temevo che arrugginisse!",
  en_title = "Wharfmaster Dizzywig",
  en_obj = "Bring Kravel's Parts Order to Wharfmaster Dizzywig in Ratchet.",
}
T[1112] = {
  title = "Parti per Kravel",
  desc = "Ecco il pacco di Kravel, $N. E quando glielo consegni, digli... che se vuole altri ordini speciali, dovrà pagare il conto!",
  obj = "Porta Kravel's Parts a Kravel Koalbeard, nelle Shimmering Flats.",
  progress = "Ce l'hai fatta ad arrivare a Ratchet e a prendere quei pezzi?",
  reward = "Ottimo, li hai presi! Ora dobbiamo portarli agli gnomi. Ma prima...$B$BTogliamo un piccolo pezzo...",
  en_title = "Parts for Kravel",
  en_obj = "Bring Kravel's Parts to Kravel Koalbeard in the Shimmering Flats.",
}
T[1113] = {
  title = "Hearts of Zeal",
  desc = "Perché mi serve un tipo raro di guano, ti chiederai. Be', con questo esperimento voglio vedere che effetto possono avere l'una sull'altra due sostanze chimiche diametralmente opposte, soprattutto se unite entrambe a un agente sempre tossico, per ottenere i risultati più... raccapriccianti.$B$BTra le vette nord-orientali delle Tirisfal Glades si trova lo Scarlet Monastery. Là si radunano i folli discepoli della Crociata Scarlatta. Uccidili e portami i loro cuori zelanti.$B$BIl nostro intruglio sarà malvagissimo!",
  obj = "Master Apothecary Faranell, nell'Undercity, vuole 20 Heart of Zeal.",
  progress = "Sei $Gtornato:tornata; dallo Scarlet Monastery? Mi serviranno molti cuori per questo delizioso esperimento!$B$BSenza dubbio anche Varimathras e la Signora Oscura saranno lieti di sbarazzarsi della feccia scarlatta...",
  reward = "Caspita, quanto sangue mi hai portato, $N! I tuoi sforzi sono stati eccellenti!",
  en_title = "Hearts of Zeal",
  en_obj = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.",
}
T[1114] = {
  title = "Consegna agli gnomi",
  desc = "Ora che ho quel che mi serve, da' questi pezzi a Fizzle Brassbolts. Li aspetta da un pezzo: sono sicuro che non sentirà la mancanza del pezzettino che ho tolto dal suo ordine...$B$BE non mi metterei a parlargliene. Era piccolo e senza valore.$B$BFidati.",
  obj = "Porta le Delicate Car Parts a Fizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Hai qualcosa per me? Che bello! Vediamo!",
  reward = "Eccoli! I miei cricchetti idraulici e i bulloni a ripetizione! Andranno benissimo. Grazie!",
  en_title = "Delivery to the Gnomes",
  en_obj = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.",
}
T[1115] = {
  title = "Il pettegolo",
  desc = "Ora che abbiamo fatto un servizio agli gnomi, è ora di fare un favore ai goblin!$B$BHo sentito che il pilota goblin Nazz Steamboil non si è sempre chiamato così. Mi chiedo perché abbia cambiato nome. Mi chiedo se sia un segreto e... mi chiedo quanto ci tenga a quel segreto.$B$BSe qualcuno sa la verità, è Krazek di Booty Bay, sulla punta meridionale di Stranglethorn. Parla con Krazek e chiedigli del nostro pilota goblin.$B$BSe riesci a farti dare informazioni utili, magari ci ricaviamo un profitto.",
  obj = "Parla con Krazek, a Booty Bay.",
  reward = "Vuoi sapere di Nazz Steamboil? È un pilota da corsa là alle Shimmering Flats, no?$B$BSì, forse riesco a scoprire qualcosa su di lui... ma non sarà facile. Né veloce.$B$BNé a buon mercato.",
  en_title = "The Rumormonger",
  en_obj = "Talk to Krazek in Booty Bay.",
}
T[1116] = {
  title = "Dream Dust nella palude",
  desc = "Avere informazioni su Nazz è un bel favore, $N. Sì, proprio un bel favore. Ma sei $Gvenuto:venuta; fin qui dalle Shimmering Flats per averle... te la senti di viaggiare ancora un po'?$B$BMentre contatto le mie fonti, perché non mi raccogli qualcosa, eh?$B$BHmm... cosa potrebbe essere? Che ne dici di un po' di Dream Dust, dai cuccioli di drago dello Swamp of Sorrows. Sì, mi piacerebbe avere un po' di Dream Dust per la mia tabacchiera!$B$BProcuramela, $N, e ti darò le informazioni che cerchi.",
  obj = "Porta 10 Speck of Dream Dust a Krazek, a Booty Bay. La Dream Dust si raccoglie dai cuccioli di drago dello Swamp of Sorrows.",
  progress = "Già di ritorno? Ce l'hai la mia Dream Dust?",
  reward = "Ma guarda un po'. Hai trovato la Dream Dust!$B$BE com'è la palude, $N? Non è facile mangiare caldo là, vero?",
  en_title = "Dream Dust in the Swamp",
  en_obj = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay.  Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.",
}
T[1117] = {
  title = "Voci per Kravel",
  desc = "Ho dovuto spendere qualche favore, regalare una rara bottiglia di vino elfico e fare anche un bel po' di deduzioni da solo! Ma le informazioni che cerchi le ho trovate.$B$BTieni, ho scritto una lettera con qualche particolare molto interessante sul nostro amico Nazz Steamboil. Fanne quel che vuoi: per me è troppo pericoloso usarla.$B$BSolo, non dire a nessuno da chi l'hai avuta!",
  obj = "Porta i Goblin Rumors a Kravel Koalbeard, nelle Shimmering Flats.",
  progress = "Hai trovato qualcosa su Nazz Steamboil? Qualcosa che magari vorrebbe tenere segreto??",
  reward = "Bene bene! Questa è interessante... molto interessante. Eh, forse la prossima volta che lo vedo dovrei fare un inchino al pilota goblin.$B$BVale parecchio, $N. Sono sicuro che Nazz pagherà una piccola fortuna per tenere il suo segreto... segreto.",
  en_title = "Rumors for Kravel",
  en_obj = "Bring the Goblin Rumors to Kravel Koalbeard in the Shimmering Flats.",
}
T[1118] = {
  title = "Ritorno a Booty Bay",
  desc = "$N, sei $Gun:una; $C di cui posso fidarmi, sia per portare a termine il lavoro sia per tenere la bocca chiusa mentre lo fai.$B$BSto architettando un nuovo piano. È rischioso, ma se funziona potremmo fare un bel gruzzolo tutti e due! E credo che tu sia proprio la persona giusta per portarlo a compimento.$B$BPer cominciare, devi tornare a Booty Bay. Chiedo scusa, $Gbuon:buona; $N. So che il mio ultimo incarico ti ha già portato là. Ma questa volta parla con Crank Fizzlebub.$B$BDagli questa lettera. E se ha bisogno di aiuto, fa' del tuo meglio per aiutarlo. Ne varrà la pena.",
  obj = "Porta Kravel's Scheme a Crank Fizzlebub, a Booty Bay.",
  progress = "Salve, salve. E cosa porta $Gun nobile:una nobile; $R come te quaggiù a Booty Bay?",
  reward = "Capisco. Kravel ha in mente un grosso piano. Ha una mente diabolica — ed è questo che mi piace di lui.$B$BQuindi ti servirà qualcosa per annebbiare il cervello, eh? Qualcosa di potente...$B$BMi chiedo se si potrebbe usare la miscela che Zanzil dà ai suoi zombi...",
  en_title = "Back to Booty Bay",
  en_obj = "Bring Kravel's Scheme to Crank Fizzlebub in Booty Bay.",
}
T[1119] = {
  title = "Zanzil's Mixture e una Fool's Stout",
  desc = "Ho capito come usare Zanzil's Mixture con la stout per ottenere una bevanda potente. Una Fool's Stout. Credo che sarà proprio quello che serve a Kravel, ma provala e fammi sapere come funziona.$B$BE, $N, non tenere questa roba troppo a lungo senza usarla. Zanzil's Mixture ha uno strano effetto sul lievito della stout: lo fa lavorare a pieno ritmo. Quindi non resterà fresca per sempre.",
  obj = "Riporta la Fool's Stout a Kravel, nelle Shimmering Flats.",
  progress = "Salve, $N. Fizzlebub è riuscito ad aiutarci?",
  reward = "Magnifico! Fizzlebub ce l'ha fatta! Me ne ricorderò la prossima volta che lo vedrò.$B$BE grazie, $N. Stai facendo un ottimo lavoro, e tutti e due potremmo guadagnarci un sacco di soldi...",
  en_title = "Zanzil's Mixture and a Fool's Stout",
  en_obj = "Bring the Fool's Stout back to Kravel in the Shimmering Flats.",
}
T[1120] = {
  title = "Fai ubriacare gli gnomi",
  desc = "Dobbiamo provare la Fool's Stout su una delle squadre ai box. Se vuoi provarla sugli gnomi, allora tieni — prendi la stout e dalla allo Gnome Pit Boss.$B$BE non aspettare troppo. Prima o poi questa stout andrà a male.",
  obj = "Porta la Fool's Stout allo Gnome Pit Boss.",
  progress = "Ciao! Hai qualcosa per me?",
  reward = "Una stout? Che pensiero gentile! Grazie!$B$BCon la corsa in arrivo non dovremmo bere, ma... forse ai miei ragazzi un goccio non farebbe male. E poi, non può essere così forte, no?",
  en_title = "Get the Gnomes Drunk",
  en_obj = "Bring the Fool's Stout to the Gnome Pit Boss.",
}
T[1121] = {
  title = "Fai ubriacare i goblin",
  desc = "Dobbiamo provare la Fool's Stout su una delle squadre ai box. Se vuoi provarla sui goblin, allora tieni — prendi la stout e dalla al Goblin Pit Boss.$B$BE non aspettare troppo. Prima o poi questa stout andrà a male.",
  obj = "Porta la Fool's Stout al Goblin Pit Boss.",
  progress = "Che hai da guardare?",
  reward = "Cos'abbiamo qui? Alcol, eh?$B$BBe', non mi dispiace se ne beviamo solo un goccio...",
  en_title = "Get the Goblins Drunk",
  en_obj = "Bring the Fool's Stout to the Goblin Pit Boss.",
}
T[1122] = {
  title = "Torna a riferire a Fizzlebub",
  desc = "Quella Fool's Stout ha funzionato alla grande! Ho scommesso sulla prossima corsa e... speriamo che la squadra che hai fatto ubriacare abbia conciato per le feste la propria auto!$B$BTi resta solo un altro compito — riporta questo biglietto a Crank Fizzlebub, a Booty Bay. Vorrà sapere che la prova è riuscita.$B$BE speriamo di poter avere altra Fool's Stout per le prossime corse!",
  obj = "Porta il Fool's Stout Report a Crank Fizzlebub, a Booty Bay.",
  progress = "Salve, $N. Com'è andata con quella stout? È roba forte, vero?",
  reward = "Qui dice che la Fool's Stout è stata un successo. È una bella notizia!$B$BSe mai ne vorrai ancora, fammelo sapere e ti farò raccogliere altra Zanzil's Mixture.",
  en_title = "Report Back to Fizzlebub",
  en_obj = "Bring the Fool's Stout report to Crank Fizzlebub in Booty Bay.",
}
T[1123] = {
  title = "Rabine Saturna",
  desc = "Per questo compito, il maggiordomo di Keeper Remulos a Moonglade — Rabine Saturna — cerca aiuto per esplorare le vaste desolazioni molto a ovest di Tanaris e di Un'Goro. Si trova a Nighthaven, il villaggio principale di Moonglade.$B$BVoglio farti capire quanto sia importante la tua presenza. Crescono le tensioni tra gli elfi della notte di Darnassus e il Cenarion Circle di Moonglade. Guarda oltre i confini tra le razze e attingi alla saggezza dei tuoi antenati nei rapporti con il Circle laggiù, $N. Buona fortuna.",
  obj = "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade. Moonglade si trova tra il Felwood e Winterspring, e ci si arriva da un sentiero che parte dalla Timbermaw Hold.",
  reward = "Sono Rabine Saturna, e a nome di Keeper Remulos e di tutti gli abitanti di questa radura sacra ti do il benvenuto.$B$BApprezzo il tuo interesse e la tua voglia di aiutare il Cenarion Circle. I tauren hanno mostrato un'incredibile inclinazione verso i precetti di Cenarius, e grazie a loro l'Orda è accolta al sicuro in questa radura. La salvaguardia di Azeroth è un obiettivo che condividiamo.$B$BQui sei tra amici, $N.",
  en_title = "Rabine Saturna",
  en_obj = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.",
}
T[1130] = {
  title = "Melor manda notizia",
  desc = "$N, Melor Stonehoof ha sentito parlare delle tue imprese, e ti ha posto davanti un cammino.$B$BSe vuoi intraprenderlo, va' a Thunder Bluff e parla con Melor. Lo troverai sull'Hunter's Rise.",
  obj = "Parla con Melor Stonehoof a Thunder Bluff.",
  reward = "Dunque, $N, sei $Gvenuto:venuta;. E ora, sei $Gpronto:pronta; a viaggiare per terre lontane?$B$BSe è così, giovane $C, allora ascolta...",
  en_title = "Melor Sends Word",
  en_obj = "Speak with Melor Stonehoof in Thunder Bluff.",
}
T[1131] = {
  title = "Steelsnap",
  desc = "A volte cacciamo per il cibo. A volte cacciamo per l'onore. E a volte cacciamo per meritare gli insegnamenti della Madre Terra.$B$BMa la caccia che ora ti affido non è nessuna di queste cose. È uccidere una creatura fuori dalla benedizione della Madre Terra.$B$BLa iena Steelsnap si aggira per le Thousand Needles, a sud delle Barrens. È un tiranno: attira a sé altre iene e sparge paura e sangue tra le bestie più pacifiche.$B$BTrova Steelsnap, $N. Trovalo, e sconfiggilo.",
  obj = "Porta Steelsnap's Rib a Melor Stonehoof, a Thunder Bluff.",
  progress = "Hai sconfitto l'immondo Steelsnap, $N?",
  reward = "Sconfiggendo la creatura Steelsnap, hai purificato le Thousand Needles da una corruzione orribile.$B$BE questa, $N, è la tua lezione di oggi.",
  en_title = "Steelsnap",
  en_obj = "Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.",
}
T[1132] = {
  title = "Fiora Longears",
  desc = "Oh, tornare ancora una volta per mare! Sentire il bacio del vento e farmi cullare dalle onde come da mia madre, tanto tempo fa!$B$BOh, vorrei avere la tua fortuna, $Gbravo:brava; $c, perché vedo il mare nel tuo futuro!$B$BIl mio compito è parlare alle anime desiderose della terra di Kalimdor, la terra delle opportunità! Se sei $Gdisposto:disposta; a tentare la sorte oltre il mare, prendi una nave da qui fino all'incantevole porto di Theramore. Là parla con la mia socia, l'elfa Fiora Longears.$B$BLei ti farà iniziare la tua avventura a Kalimdor!",
  obj = "Parla con Fiora Longears sui moli di Theramore, a Dustwallow Marsh.",
  reward = "Buongiorno! Ti ha mandato Mr. Flint di Menethil Harbor? Beh, Mr. Flint ha un ottimo intuito per le persone. Se ha mandato te, non c'è dubbio che il tuo posto sia qui a Kalimdor!",
  en_title = "Fiora Longears",
  en_obj = "Speak with Fiora Longears on the docks at Theramore in Dustwallow Marsh.",
}
T[1133] = {
  title = "Viaggio ad Astranaar",
  desc = "Se sei appena sbarcat$Go:a; da Menethil, la prima cosa da fare è... andare ad Astranaar. Sono certo che $Gun:una; $Gvolenteroso:volenterosa; membro dell'Alleanza come te possa fare del vero bene lassù. Parla con Shindrell Swiftfire e offri i tuoi servigi.$B$BMa non preoccuparti di dire chi ti manda. Shindrell non mi conosce...",
  obj = "Parla con Shindrell Swiftfire ad Astranaar.",
  reward = "Sei qui per offrire i tuoi servigi all'Alleanza, $N? Accogliamo volentieri l'aiuto, perché sebbene la sua bellezza rimanga... Ashenvale Forest non è più il luogo pacifico di un tempo.",
  en_title = "Journey to Astranaar",
  en_obj = "Speak with Shindrell Swiftfire in Astranaar.",
}
T[1134] = {
  title = "I Pridewing di Stonetalon",
  desc = "Non siamo in guerra aperta con l'Orda, ma la nostra è una pace fragile. Spesso scopriamo i loro agenti che tramano contro di noi, ma lo fanno di nascosto.$B$BUna di queste mosse ci è stata rivelata da fonti nascoste a Theramore: dicono che gli orchi raccolgano il veleno dai Pridewing vicino al Mirkfallon Lake, nelle Stonetalon Mountains a sud. Poi gli assassini orchi usano quel veleno nelle loro incursioni mortali e segrete contro l'Alleanza!$B$BSe è vero, dobbiamo fermarli, $N. Dobbiamo togliere loro la fonte del veleno.",
  obj = "Porta 12 Pridewing Venom Sac a Shindrell Swiftfire ad Astranaar.",
  progress = "Hai le Pridewing Venom Sac, $N? Non possiamo permettere che gli orchi usino contro di noi il veleno di quelle bestie!",
  reward = "Grazie, $N. Mi rattrista ordinare il massacro di creature che forse non aiutano di loro volontà i nostri nemici, eppure è mio dovere farlo.$B$BIl tuo cuore forse piangerà per i Pridewing che hai ucciso, $Gamico mio:amica mia;, ma che poi si riempia di gioia sapendo che i tuoi alleati sono al sicuro dal veleno dei Pridewing.",
  en_title = "Pridewings of Stonetalon",
  en_obj = "Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar.",
}
T[1135] = {
  title = "Il veleno di Highperch",
  desc = "Come forse sai, i wyvern vengono spesso addomesticati dagli orchi per farne cavalcature. Ma quello che si sa meno è che il veleno di un wyvern, in certi ambienti, vale più della bestia stessa. Quindi, se non hai paura di andare un po' a caccia di wyvern, allora... ho un lavoro per te.$B$BC'è un posto chiamato Highperch nella terra di Thousand Needles, a ovest di qui. Gli Highperch Wyvern hanno un veleno potente. Potente, e prezioso.",
  obj = "Porta 10 Highperch Venom Sac a Fiora Longears, a Theramore.",
  progress = "Hai trovato Highperch, $N? Hai avuto fortuna con i wyvern laggiù?",
  reward = "Ah, quasi tutte queste stanno per scoppiare di veleno, $N. Di solito sacche così si raccolgono solo dai wyvern giovani o dalle femmine fertili. Dev'essere stata una bella strage lassù a Highperch!",
  en_title = "Highperch Venom",
  en_obj = "Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore.",
}
T[1136] = {
  title = "Frostmaw",
  desc = "$N, è giunto il momento che tu viaggi verso terre lontane. Sei $Gpronto:pronta;.$B$BOra dai la caccia a Frostmaw, uno yeti nelle Alterac Mountains. È sfuggente, e il suo manto bianco si confonde con le nevi della sua montagna. Si mostra di rado.$B$BMa io ti mostrerò come attirare una creatura come lui. Ecco, prendi questa pergamena. Vi ho scritto sopra come si può adescare Frostmaw.$B$BOra va', $N. Il tuo viaggio è lungo e molte prove ti aspettano. Solo quando tornerai con Frostmaw's Mane il tuo compito sarà compiuto.",
  obj = "Porta Frostmaw's Mane a Melor Stonehoof, a Thunder Bluff.",
  progress = "Sei $Gstato:stata; alle Alterac Mountains, $N? Hai affrontato lo sfuggente Frostmaw?",
  reward = "Per trovare e sconfiggere Frostmaw servivano sia la forza sia l'astuzia, $N. Tu hai entrambe.$B$BIl tuo cammino ti ha portato nelle valli delle Thousand Needles e sulle alte montagne di Alterac. Un giorno ti condurrà per tutte le terre della Madre Terra, perché tale è la via del cacciatore.",
  en_title = "Frostmaw",
  en_obj = "Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.",
}
T[1137] = {
  title = "Notizie per Fizzle",
  desc = "L'indurium ha una resistenza al calore incredibile! Sono sicuro che andrà bene per i pistoni di Fizzle. Ma gli servirà vero minerale di indurium, non solo le scaglie.$B$BPer avere il minerale bisogna estrarlo nel profondo di Uldaman, ai confini settentrionali dei Badlands. È quella la vera fonte dell'indurium.$B$BSaluta Fizzle Brassbolts da parte mia e digli quel che ti ho detto.$B$BBuon viaggio, $N. E non mi stupirò se ci rivedremo: quando Fizzle saprà dell'indurium, probabilmente ti manderà a Uldaman a prenderlo!",
  obj = "Parla con Fizzle Brassbolts, nelle Shimmering Flats.",
  reward = "$N, sei $Gtornato:tornata;! Hai trovato Martek? Gli hai parlato? Cos'ha detto? Può aiutarci??$B$BDimmi, dimmi, dimmi!!",
  en_title = "News for Fizzle",
  en_obj = "Speak with Fizzle Brassbolts in the Shimmering Flats.",
}
T[1138] = {
  title = "Frutti di mare",
  desc = "Adoro il granchio. I granchi sono il frutto del mare! Si può cuocere al forno, alla griglia, bollire e arrostire. Si friggono in padella, si friggono in olio, si saltano. C'è l'insalata di granchio, la zuppa di granchio, lo stufato di granchio, il granchio al pepe, il granchio al limone, il granchio alla whipper root e il granchio a sorpresa di Ironforge. Ecco... più o meno è tutto.$B$BIo sono qui a pescare, quindi non posso procurarmi dei bei pezzi di granchio. Tu puoi prenderli dai reef crawler e dagli encrusted tide crawler. Se ne fanno un sacco di cose. Si può cuocere al forno, alla griglia, bollire...",
  obj = "Raccogli 6 Fine Crab Chunk per Gubber Blump ad Auberdine.",
  progress = "...il granchio al limone, alla whipper root e a sorpresa di Ironforge. Più o meno è tutto.$B$BOh, ciao $N. Hai quei bei pezzi di granchio di cui ti parlavo?",
  reward = "Wow, questi pezzi di granchio sono proprio quello che mi serve. Grazie $N! Ho trovato questa cosa mentre pescavo tempo fa, e non so che farmene. Magari tu ci combini qualcosa. Di sicuro non ci si fanno buoni piatti di granchio.$B$BTi ho parlato di tutto sui granchi, vero?",
  en_title = "Fruit of the Sea",
  en_obj = "Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine.",
}
T[1139] = {
  title = "Le Tablet of Will perdute",
  desc = "Abbiamo rallentato il clan Shadowforge tagliandolo fuori dalla Blackrock Spire, ma la missione di Hammertoe non è ancora compiuta. La sua morte non deve essere stata vana. Sognava di trovare la Tablet of Will: un frammento di pietra inciso con la magia dai titani in persona per aiutare a infondere la vita nelle loro creazioni, perché avessero una volontà propria, o almeno così dicono le leggende.$B$BDobbiamo ancora recuperare la tavoletta prima che la trovi il clan Shadowforge.$B$BTorna a Uldaman, trova la tavoletta e torna qui immediatamente.",
  obj = "Trova la Tablet of Will e riportala ad Advisor Belgrum, a Ironforge.",
  progress = "La missione di Hammertoe deve essere portata a compimento, $N. Glielo devo.$B$BIl tuo ritorno a Uldaman è indispensabile non solo per questo scopo, ma anche per la sicurezza di tutto il popolo dei nani. Con la tavoletta nelle mani dei Dark Iron, chissà quanto diventerebbe potente il loro esercito di golem.",
  reward = "<Advisor Belgrum scuote la testa incredulo mentre gli porgi il frammento di pietra.>$B$B$N, è straordinario. Farò portare questo ai maghi del re il prima possibile. Vorranno studiarlo per scoprire se le leggende sono vere. Ma ne parleremo un'altra volta: hai aiutato il nostro popolo più di quanto mi sarei mai aspettato. Grazie.",
  en_title = "The Lost Tablets of Will",
  en_obj = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.",
}
T[1140] = {
  title = "La Tower of Althalaxx",
  desc = "La scrittura degli orchi è poco meglio degli scarabocchi di un bambino. Molti del mio ordine storsero il naso quando scelsi di impararne la lingua, ma l'ho trovato utile per capire meglio i miei nemici.$B$BDagli scarabocchi di Ilkrud sembra che Athrikus possieda ancora due gemme dell'anima, e che siano custodite a Night Run e a Satyrnaar, zone in mano ai satiri nel nord-est di Ashenvale.$B$BSta' $Gattento:attenta; là fuori, $N: i templi intrisi di sangue dei satiri possono turbare anche $Gun:una; $C $Gnavigato:navigata; come te.",
  obj = "Libera le anime degli Alti Nobili intrappolate a Night Run e a Satyrnaar, poi torna da Delgren the Purifier, a Maestra's Post.",
  progress = "Una volta sentii sussurrare che la storia dei satiri è in qualche modo legata a quella degli elfi della notte, ma ho trovato i miei stimati ospiti restii a parlarne.",
  reward = "Forse ai satiri è stato permesso di restare nella foresta troppo a lungo. Ne parlerò con Elissa la prossima volta che andrò ad Auberdine.$B$BComunque sia, con le gemme dell'anima distrutte il potere di Athrikus sarà molto ridotto. Dobbiamo cogliere l'occasione per eliminare lui e il suo culto.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.",
}
T[1141] = {
  title = "La famiglia e la canna da pesca",
  desc = "Adoro pescare. La famiglia Blump è famosa per la pesca. Mi chiamo Gubber Blump; io pesco.$B$BC'è un tipo di pesce che mi piace prendere da queste parti, il Darkshore grouper. Prima andavo in barca a pescare cernie, ma nessuna barca esce più da quando quei cattivi murloc si sono insediati. Scommetto che si sono pure mangiati tutte le cernie.$B$BSenti, vuoi aiutarmi a pescare dei Darkshore grouper? Ti darei una vera Blump Family Fishing Pole, se lo facessi! È una canna davvero ottima per pescare.",
  obj = "Pesca 6 Darkshore Grouper per Gubber Blump ad Auberdine.",
  progress = "Ci sono un sacco di bei piatti da fare con i Darkshore grouper. Sono buoni da mangiare, ma secondo me è più divertente pescarli.$B$BNe hai già pescato qualcuno?",
  reward = "Questi sì che sono dei bei grouper, $N! Grazie per l'aiuto!$B$BSei bravo a pescare almeno quanto mia cugina, Graun Blump. Ha pure la barba e puzza un po' strano, ma questo non le impedisce di pescare. Mi sa che hai quel che serve per usare una Blump Family Fishing Pole.",
  en_title = "The Family and the Fishing Pole",
  en_obj = "Catch 6 Darkshore Grouper for Gubber Blump in Auberdine.",
}
T[1142] = {
  title = "La vita si spegne",
  desc = "Non mi resta molto da vivere... così... così... debole.$B$B...il c-c-coraggioso nano, Lonebrow, è stato mandato ad a-a-avvertire Falfindel...$B$BMa prima che io... m-m-muoia...$B$B...mia moglie, Treshala... il suo ciondolo del legame con me... rubato... da uno degli i-i-immondi aggressori...$B$BTrovalo, p-p-per favore... e riportalo a Treshala, a Darnassus...$B$B...insieme alla n-n-notizia della mia solitaria... morte.",
  obj = "Trova Treshala's Pendant e riportalo a Treshala Fallowbrook, a Darnassus.",
  progress = "Cosa ti porta a casa mia, $R?",
  reward = "No!$B$BNon è giusto. Oh, mondo crudele e intollerabile!$B$BOra devo portare questo fardello di dolore e non lasciare che l'opera di Heralath muoia con lui.$B$BHai avuto coraggio a venire da un luogo così pericoloso, $N. Ma ora, ti prego, lasciami.$B$BIn solitudine piangerò.",
  en_title = "Mortality Wanes",
  en_obj = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.",
}
T[1143] = {
  title = "La Tower of Althalaxx",
  desc = "Capisco. Be', se quello che dici è vero, allora è il momento di colpire. Credo che Athrikus stia in cima alla torre. Sta' $Gattento:attenta;, però: è circondato da molti stregoni potenti, ben più letali di quelli che hai affrontato finora.",
  obj = "Uccidi Athrikus Narassin e porta la sua testa a Balthule Shadowstrike, vicino alla Tower of Althalaxx.",
  progress = "Athrikus Narassin è uno stregone antico e potente. Forse dovremmo aspettare l'aiuto di Delgren, ma è evidente che aveva molta fiducia in te, per mandarti $Gda solo:da sola;.",
  reward = "Con la morte di Athrikus spero che le forze demoniache di questa zona vengano respinte. Non ho dubbi che si riorganizzeranno e torneranno, ma allora saremo ancora più pronti ad affrontare la loro minaccia.",
  en_title = "The Tower of Althalaxx",
  en_obj = "Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.",
}
T[1144] = {
  title = "Willix the Importer",
  desc = "Finalmente sono arrivati i soccorsi!$B$BNon hai idea di quanto tempo mi abbiano tenuto prigioniero qui. Non ricordo più l'ultima volta che ho visto l'esterno di questo posto.$B$BVedi, io sono un imprenditore. Sempre a caccia di un rame, come si dice. Ho sentito dire che Mebok Mizzyrix pagava bene i Redleaf Tuber di questo porcile. Pensavo che sarebbe stato un lavoretto facile, dentro e fuori. Come vedi, mi sbagliavo un pochino!$B$BComunque, se sei così gentile da aiutarmi a uscire di qui, ti ripagherò come si deve.",
  obj = "Scorta Willix the Importer fuori dal Razorfen Kraul.",
  reward = "Grazie ancora, $Gamico:amica;! Te l'avevo detto che ti avrei ripagato come si deve.",
  en_title = "Willix the Importer",
  en_obj = "Escort Willix the Importer out of Razorfen Kraul.",
}
T[1145] = {
  title = "Lo sciame cresce",
  desc = "Molti viaggiatori passati dal Crossroads mi hanno aiutato a raccogliere uova nel Field of Giants, e molti hanno storie su quanto sono letali quelle creature. Ne ho sentite abbastanza da considerare quegli insetti una minaccia molto più grande di quanto i miei padroni credessero all'inizio.$B$BMi serve un corriere che vada a Orgrimmar a incontrare Belgrom Rockmaul. Non è una faccenda semplice, e dovrebbe andarci qualcuno che prenda l'incarico sul serio.$B$BBelgrom di solito si trova fuori dalla casa della gilda dei guerrieri.",
  obj = "Consegna la Korran's Sealed Note a Belgrom Rockmaul, a Orgrimmar.",
  progress = "Ti invidio, $C. Hai l'aria di chi è stato fuori dalle mura di Orgrimmar per un po'.$B$BIo stesso viaggerei nel nome del Capoguerra, se Thrall non avesse bisogno delle mie capacità qui in città. Ma ci guida bene, e mi fido del suo giudizio — resto qui finché ha bisogno di me.",
  reward = "Ah, un biglietto da Korran. È un servitore fedele ormai da tempo. Mi chiedevo come andassero i suoi incarichi al Crossroads.",
  en_title = "The Swarm Grows",
  en_obj = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.",
}
T[1146] = {
  title = "Lo sciame cresce",
  desc = "Quindi Korran è arrivato a una conclusione simile su questi insetti: sembrano una minaccia più grande di quanto pensassimo.$B$BQualche giorno fa un cacciatore è tornato da me da Thousand Needles, quasi morto. Era con un gruppo d'assalto mandato a cacciare una squadra di scavo nanica dalle Shimmering Flats. Durante l'attacco altri di questi insetti sono sbucati da una grotta nel sito di scavo e hanno quasi ucciso il gruppo.$B$BLi guidava Moktar Krin, e si sono rifugiati ai confini delle Shimmering Flats. Portagli questo biglietto.",
  obj = "Consegna Belgrom's Sealed Note a Moktar Krin, a Thousand Needles.",
  progress = "È la guerra a portare me e il mio gruppo qui, nelle Shimmering Flats, $C. E te cosa ci porta?",
  reward = "Non badare all'eco tonante che rimbomba sulle pareti delle montagne. I goblin e gli gnomi sono là nelle Flats a correre l'uno contro l'altro su certe atrocità create da quella che chiamano scienza. Qui a Thousand Needles ci sono minacce più grosse, e una di queste ha ucciso più di metà della mia banda di guerra.$B$BMa restiamo qui finché non avremo notizie da Belgrom, a Orgrimmar. Fino ad allora teniamo la posizione e restiamo vigili.",
  en_title = "The Swarm Grows",
  en_obj = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.",
}
T[1147] = {
  title = "Lo sciame cresce",
  desc = "Hmm. Pare che Belgrom consideri quei mostri una minaccia. Vuole che vengano ricacciati nelle profondità da cui sono strisciati fuori.$B$BImmagino che uccidere i nani mandati dalla Lega degli Esploratori non sia bastato: adesso devo mandare in un'altra battaglia una banda di guerra mezza morta. Non possiamo farcela da soli, non nelle condizioni in cui siamo. Il sito di scavo è a sud di qui. Non dovrebbero esserci altri nani di cui occuparsi. Te la senti di impugnare una lama o un bastone e di fare la tua parte per aiutarci?",
  obj = "Uccidi 5 Silithid Searcher, 5 Silithid Hive Drone e 5 Silithid Invader, poi torna da Moktar Krin, a Thousand Needles.",
  progress = "Con tutti i viaggiatori che vanno alle Flats per quelle corse, sono sicuro che riusciremo a convincere abbastanza cercatori d'avventura ad aiutarci a ricacciare indietro quegli insetti. Io e la mia banda non potremo muoverci finché non sarà fatto.",
  reward = "Ah! Quell'icore di cui sei $Gcoperto:coperta; ti rende perfino più $Gcarino:carina;, $N! Anche se allo stesso tempo ti fa puzzare da morire. Non stare troppo vicino ai kodo: o scateni una fuga in massa o li mandi in calore.$B$BCredo che i miei compagni saranno d'accordo: già solo il tuo odore è la prova che hai fatto la tua parte per aiutarci contro quelle creature insettoidi. Grazie, $N.",
  en_title = "The Swarm Grows",
  en_obj = "Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.",
}
T[1148] = {
  title = "Parti dello sciame",
  desc = "Esamini con attenzione il carapace. Rigirandolo tra le mani ti accorgi che le placche chitinose si intrecciano in modo da renderlo incredibilmente resistente. Non è come niente che tu abbia mai visto. Esamini meglio il resto del cadavere e capisci che queste creature sono molto potenti e molto evolute.$B$BGuardando di nuovo il carapace, pensi che a Korran piacerebbe studiare altre creature come questa. Potrebbe aiutarlo a capire cosa sono e da dove vengono.",
  obj = "Porta 1 Silithid Heart, 5 Silithid Talon e 3 Intact Silithid Carapace a Korran, al Crossroads.",
  progress = "Ah, è passato tanto tempo dall'ultima volta che sei $Gvenuto:venuta; a trovarmi, $N. Cosa posso fare per te oggi? Hai l'aria di chi ha visto la battaglia di recente. Bene... bene per l'Orda e bene per te. Più battaglie hai visto, più sarai utile; e anche più forte.",
  reward = "Ahh, hai visto Moktar di recente? Lui bada sempre a me. Mi dispiace sentire che passa il tempo a sorvegliare la sua piccola banda di guerra invece di andare in battaglia, ma sono sicuro che si gode un bel po' l'uccidere i membri della Lega degli Esploratori.$B$BHai fatto bene a portarmi questi campioni, $N. Insieme alle uova che stiamo trovando nel Field of Giants, dovrebbero darmi un buon punto di partenza per capire cosa sono questi insetti e cosa vogliono.",
  en_title = "Parts of the Swarm",
  en_obj = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.",
}
T[1149] = {
  title = "Prova di fede",
  desc = "Allora, mi hai cercato, o forse è il destino a portarti da me? Non importa. Ora sei qui, e il tuo viaggio ricomincerà daccapo.$B$BUn essere è fatto di molte facce: lo spirito, il corpo, la mente. Alcune si possono misurare con le tradizioni di un popolo. Di altre possiamo solo sperare che esistano dentro di noi. Se sei d'accordo, metterò alla prova alcune delle facce che hai dentro.$B$BSe passerai le prove, diventerai più forte. Se fallirai, ti renderai conto della vastità del Nether.$B$BLa prima è una Prova di Fede.",
  obj = "Se hai fede, salta dalle assi che si affacciano su Thousand Needles.",
  progress = "La fede. È molto più importante di quanto qualcuno creda.$B$BA volte non conta in cosa credi. Conta soltanto che tu creda in qualcosa.",
  reward = "È solo davanti a un'avversità imprevista che cominciamo a vedere quanto è forte il nostro spirito. Hai fatto il salto della fede pur non avendo alcuna garanzia di sopravvivere. La tua mente è aperta e il tuo spirito è pronto per quel che verrà.$B$BSe te la senti, la prossima prova è pronta.",
  en_title = "Test of Faith",
  en_obj = "If you have faith, leap from the planks overlooking Thousand Needles.",
}
T[1150] = {
  title = "Prova di resistenza",
  desc = "Mi fa piacere vedere che il tuo coraggio resta saldo dopo quel che hai già fatto. Dato che la tua fede è intatta, è arrivato il momento di mettere alla prova il tuo corpo.$B$BPer prima cosa una prova di resistenza. Va' con degli amici alla Roguefeather Den, a ovest di Freewind Post. Arriva fino in fondo alla loro tana e distruggi le loro provviste. A quel punto dovresti averne scatenato la furia, e se riuscirai a sopravvivere abbastanza a lungo verrà a prenderti Grenka Bloodscreech in persona: uccidila e portami il suo artiglio per completare la prova.",
  obj = "Porta Grenka's Claw a Dorn Plainstalker, a Thousand Needles.",
  progress = "Devi essere $Gpronto:pronta; nello spirito, nel corpo e nella mente per le sfide che ti aspettano.$B$BTroppo spesso corriamo avanti prima di essere pronti. Considero un mio dovere verso i giovani, a qualunque tribù appartengano, prepararli ai pericoli che potranno incontrare una volta lasciata la sicurezza di casa.",
  reward = "Grenka era potente, perfino per $Gun:una; $R come te. Dovresti essere $Gfiero:fiera; di quel che hai compiuto oggi.$B$BNella prova di fede hai mostrato forza di spirito, e ora hai mostrato resistenza in battaglia affrontando le arpie Roguefeather, ma è arrivato il momento di una nuova prova.",
  en_title = "Test of Endurance",
  en_obj = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.",
}
T[1151] = {
  title = "Prova di forza",
  desc = "Al tempo degli Antichi Dei gli elementali abitavano gran parte di questo mondo. Veneravano gli Antichi Dei, e gli Dei, con il loro potere, tenevano gli elementali legati a questo mondo. Quando gli Antichi Dei furono banditi, gli elementali svanirono dal nostro mondo e ora tornano solo al comando di maghi potenti.$B$BCi sono però delle eccezioni. Alcuni elementali erano abbastanza potenti da restare qui da soli. Uno di questi è Rok'Alim.$B$BPer mettere alla prova la tua forza, trova Rok'Alim a Thousand Needles e uccidilo.",
  obj = "Porta Fragments of Rok'Alim a Dorn Plainstalker, a Thousand Needles.",
  progress = "Le tribù dei centauri di Thousand Needles chiamano Rok'Alim anche il Percussore, per il tuono che fanno i suoi pugni quando prende a botte le creature abbastanza coraggiose, o stupide, da mettersi sulla sua strada.",
  reward = "La Prova di Forza è compiuta. Hai mostrato forza e coraggio, e ora sei $Gpronto:pronta; per l'ultima prova prima che questi riti siano completati.",
  en_title = "Test of Strength",
  en_obj = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.",
}
T[1152] = {
  title = "Prova di sapienza",
  desc = "Il tuo tempo con me sta per finire. Io ho molto sapere, ma la Prova di Sapienza non tocca a me. Ci sono lezioni da imparare e luoghi da visitare su cui altri rivendicano il dominio.$B$BSe sei $Gpronto:pronta;, cerca Braug Dimspirit: è uno sciamano di grande saggezza. Ti metterà ancora alla prova, quindi ascolta bene le sue parole, $N.$B$BQuando sei $Gpronto:pronta;, trova il tunnel che collega le Stonetalon Mountains con Ashenvale: Braug abita lì vicino. E sta' $Gattento:attenta;, $N, gli elfi della notte potrebbero voler ostacolare la tua prova.",
  obj = "Trova Braug Dimspirit vicino all'ingresso del Talondeep Path, nelle Stonetalon Mountains.",
  reward = "I giorni e le notti si fanno più freddi in tutto il mondo mentre i goblin violentano la terra e gli elfi della notte puntano il dito contro le razze più giovani. I Reietti e gli orchi non sono i soli responsabili delle sofferenze che si trovano in tutta Kalimdor e in Lordaeron. Molte delle razze intelligenti hanno contribuito al dolore del mondo. Dorn lo sa, e ti ha mandato da me perché hai mostrato le qualità necessarie per capirlo anche tu.$B$BOra sei davanti a Braug.",
  en_title = "Test of Lore",
  en_obj = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.",
}
T[1153] = {
  title = "Un nuovo campione di minerale",
  desc = "$C, mi hai aiutato bene in passato. Il capoguerra finora è soddisfatto di quello che ho ottenuto, e mi chiede di continuare con rinnovata determinazione. Il mio onore mi impone di darti il giusto riconoscimento davanti al capoguerra per tutto quello che hai fatto, ma prima vorrei chiederti ancora aiuto.$B$BDi recente sono arrivati dei viaggiatori da sud, da un posto chiamato Thousand Needles. Là hanno ucciso un kobold che aveva un campione di minerale insolito, ma non hanno voluto venderlo. Voglio un campione di quel minerale da esaminare.",
  obj = "Trova un Unrefined Ore Sample su un Gravelsnout Digger o Surveyor e portalo a Tatternack Steelforge, a Camp Taurajo, nelle Barrens.",
  progress = "Ho rivisto quei viaggiatori — quelli che non volevano vendermi un campione del minerale. Gli sputo addosso, per non aver aiutato il capoguerra.$B$BChe muoiano in battaglia come codardi e non come guerrieri, come sarebbe diritto di tutti i popoli che si alleano con l'Orda.",
  reward = "Un buon campione, $N. Un ottimo campione davvero.$B$BQuei viaggiatori non possono più vantarsi con me del minerale che hanno trovato, ora che tu ci sei $Griuscito:riuscita;.$B$BMi metterò al lavoro subito. Se si rivelerà abbastanza resistente, manderò al capoguerra un'arma forgiata con questo materiale, per mostrargli il nostro successo.$B$BNon dimenticherò il tuo aiuto, $C.",
  en_title = "A New Ore Sample",
  en_obj = "Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.",
}
T[1154] = {
  title = "Prova di sapienza",
  desc = "Hai superato le prove di Dorn e ora cerchi di superare la prossima. Molto bene. Ma finora le tue sfide sono state roba da bambini. È facile mettere alla prova il tuo corpo: la tua mente è tutta un'altra faccenda.$B$BTe la spiego in modo semplice: trova il libro che ti dirò, studialo e rispondi alla mia domanda sul suo contenuto.$B$BQuale libro, ti starai chiedendo? The Legacy of the Aspects. Si trova in fondo a Dor'danil, nell'Ashenvale meridionale, protetto dai druidi morti e dai loro carnefici.",
  obj = "Trova la Legacy of the Aspects e portala a Braug Dimspirit, vicino all'ingresso del Talondeep Path, nelle Stonetalon Mountains.",
  progress = "Portami il libro dopo che l'avrai studiato. Non ti farò la domanda finché non me lo avrai consegnato.",
  reward = "Questo è il libro che ti avevo detto. C'è speranza che tu risponda bene alla mia domanda, allora... a meno che tu non ti sia $Gdimenticato:dimenticata; di studiarne il contenuto.$B$BQuando sei $Gpronto:pronta;, parlami di nuovo e ti farò una domanda.",
  en_title = "Test of Lore",
  en_obj = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.",
}
T[1159] = {
  title = "Prova di sapienza",
  desc = "Ben fatto, $N. Hai superato la prima parte della Prova di Sapienza, ma c'è ancora una domanda a cui rispondere. E non tocca a me farla.$B$BCerca Parqual Fintallas, a Lordaeron City. Era un grande storico degli umani, prima che la Piaga lo cogliesse. Ora continua a cercare l'illuminazione, ma di natura diversa.$B$BTi chiederà qualcos'altro prima di farti la domanda, ma finora te la sei cavata da maestro: sono sicuro che supererai anche il suo ostacolo.",
  obj = "Trova Parqual Fintallas, nell'Undercity.",
  reward = "Ti manda Braug? Impossibile.$B$B<Parqual ti squadra da capo a piedi.>$B$BHai affrontato Dor'Danil, hai fatto il salto della fede, hai combattuto e sopraffatto un elementale potente? Bah! Probabilmente sei una farsa, $Gun avventuriero qualsiasi:un'avventuriera qualsiasi; che ha sentito due chiacchiere in taverna. E adesso credi di avere le carte in regola per superare la mia prova. E sia... $C.",
  en_title = "Test of Lore",
  en_obj = "Find Parqual Fintallas in Undercity.",
}
T[1160] = {
  title = "Prova di sapienza",
  desc = "Ti dirò che cosa devi cercare, e ti farò perfino la mia domanda, ma non perché tu voglia dimostrare il tuo valore. La conoscenza è molto più importante della forza. Anche se altri sembrano superarti in abilità, la tua conoscenza del mondo varrà di più.$B$BVa' al Monastery, nel nord delle Tirisfal Glades. Nella sua biblioteca si trova un libro intitolato Beginnings of the Undead Threat. I paladini di quel luogo, ora corrotti, lo usavano per addestrarsi a combattere quelli come me.$B$BPortamelo.",
  obj = "Trova The Beginnings of the Undead Threat e riportalo a Parqual Fintallas, nell'Undercity.",
  progress = "Spero che tu abbia fatto soffrire un po' la Crociata Scarlatta prima di rubarle il libro.$B$BLe mie opinioni su quella gente non sono infondate. Un tempo la Crociata avrà anche seguito la Luce, ma ora cerca di distruggere qualunque creatura non si sia schierata con la sua religione. Crede che tutti i non morti, Reietti o no, vadano purificati, e che chi viaggia nelle sue terre sia pazzo o soggiogato dalla potente magia dei non morti. Idioti. Idioti e stolti, tutti quanti.",
  reward = "Questo è il libro che ti ho mandato a cercare.$B$B<Parqual passa lentamente la mano sulla copertina del libro, fissandolo.>$B$BE ora vuoi una domanda per dimostrare che la tua mente è potente quanto il tuo corpo e il tuo spirito. Se hai studiato il libro abbastanza a lungo, ti farò la tua domanda e avrai chiuso con queste prove!",
  en_title = "Test of Lore",
  en_obj = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.",
}
T[1164] = {
  title = "Rubare ai ladri",
  desc = "Quella sgualdrina! Quella scrofa! Kenata è ancora viva; la sua famiglia è sana e prospera mentre io soffro. Reietti, davvero!$B$BLa mia famiglia non c'è più, portata via dalla piaga. Anche la nostra tenuta è andata perduta, saccheggiata e bruciata durante la guerra. E dopo tutto questo, lei e i suoi figli pidocchiosi hanno avuto la sfacciataggine di rubare gli unici beni preziosi che mi erano rimasti.$B$BNon m'importa più delle cose che hanno rubato. Ora voglio le loro teste!$B$BUccidili per me! Va' alla Dabyrie Farmstead, in Arathi, a nord-est di Refuge Point.",
  obj = "Porta Kenata's Head, Fardel's Head e Marcel's Head dei Dabyrie a Genavie Callow, nell'Undercity.",
  progress = "Uccidili tutti e portami le loro teste!",
  reward = "Sei davanti a me come una figura di vendetta, e mi inchino davanti a te per ringraziarti.$B$BCon la morte di quella vacca, e sapendo che il loro seme non si spargerà più sulla faccia di Azeroth, posso dedicare le mie energie a qualcosa di più redditizio. Spero che tu abbia saccheggiato la loro fattoria dopo averli fatti fuori.",
  en_title = "To Steal From Thieves",
  en_obj = "Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",
}
T[1166] = {
  title = "La preoccupazione di Overlord Mok'Morokk",
  desc = "Inchinati davanti a Overlord Mok'Morokk!$B$BRexxar fare me potente capo di Stonemaul Clan!$B$BIo buon capo. Io tenere clan al sicuro.$B$BGrossi draghi venire e dare fuoco a vecchia casa. Io ogre furbo. Trovare nuova casa per clan qui.$B$BLasciare vecchia casa così in fretta, io dimenticare roba. $GPiccolo:Piccola; $R, tu andare prendere mie cose. Andare a sud e trovare mio grog buonissimo, mio tabacco da fiuto e mia cassaforte. A me piacere tu dopo che tu fare questo. Tu guardare in Den of Flame e Stonemaul Ruins... loro essere lì, io sicuro!",
  obj = "Overlord Mok'Morokk, a Brackenwall Village, vuole che tu recuperi il suo grog, il suo tabacco da fiuto e la sua cassaforte nel Dustwallow Swamp.",
  progress = "Io avere sete di grog. A me mancare anche tabacco da fiuto. Dove essere cassaforte? Tu andare prendere per Overlord Mok'Morokk.$B$BAndare cercare a sud in vecchia casa. Io troppo occupato a guidare ogre per andare prendere.",
  reward = "Tu essere $Gun bravo:una brava; $R. A me mancare tanto mie cose. A me piacere tu adesso.",
  en_title = "Overlord Mok'Morokk's Concern",
  en_obj = "Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.",
}
T[1167] = {
  title = "La Tower of Althalaxx",
  desc = "Prima di affrontare Athrikus, sarebbe saggio che ti consultassi con Balthule. Non ho dubbi che abbia vegliato con attenzione sulla torre, e potrebbe avere notizie sugli ultimi sviluppi.",
  obj = "Parla con Balthule Shadowstrike, vicino alla Tower of Althalaxx.",
  reward = "Ah, che piacere rivederti, $N! Qui stanno succedendo le cose più strane, sono contento che tu sia $Garrivato:arrivata;!$B$BÈ stato stranissimo, $N. Sembrava tutto normale — be', normale per quanto lo siano le cose da queste parti — e poi all'improvviso c'è stato un lampo accecante dalla stanza in cima alla torre. Poi sono arrivate le urla. Le grida squarciavano l'aria, e ogni tanto un fulmine colpiva il terreno. Che sta succedendo?",
  en_title = "The Tower of Althalaxx",
  en_obj = "Speak with Balthule Shadowstrike near the Tower of Althalaxx.",
}
T[1168] = {
  title = "L'esercito del drago nero",
  desc = "Mok'Morokk è stato fatto signore supremo da Rexxar. Lui tenere più a potere che a ogre.$B$BDraghi neri uccidere molti ogre. Uccidere moglie di Tharg. Mok'Morokk dire a noi di scappare. Fare noi venire qui.$B$BOgre dovere combattere. Ogre non bravi a scappare. A Mok'Morokk importare solo di Mok'Morokk.$B$BIo chiamare casa Stonemaul Ruins. A me piacere stare a sud. Questo posto non casa.$B$BAiutare ogre combattere esercito di drago nero. Io volere vendetta. Io volere tornare a casa.",
  obj = "Tharg, a Brackenwall Village, vuole che tu uccida 15 Firemane Scout, 10 Firemane Ash Tail e 5 Firemane Scalebane.",
  progress = "Mok'Morokk dire a tutti ogre di restare e tenere al sicuro questo posto. Io pensare ogre dovere uccidere esercito di drago nero e riprendere vecchia casa.$B$BTu aiutare ogre riprendere casa. Aiutare ogre avere vendetta.",
  reward = "Tu uccidere molti di esercito di drago nero. Tu $Gun:una; $R $Gcoraggioso:coraggiosa;.$B$BTu fare Tharg contento.",
  en_title = "Army of the Black Dragon",
  en_obj = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.",
}
T[1169] = {
  title = "Identificare la covata",
  desc = "Mentre quel vile sciocco di Mok'Morokk si crogiola nel potere, e Tharg lotta con i demoni del dolore e della vendetta e si contende la guida del clan, sembra che io sia l'unico a preoccuparsi di scoprire l'origine dell'aggressione alla nostra vecchia casa.$B$BPerché quello sguardo perplesso, $N? Ti aspettavi che parlassi come un rozzo attaccabrighe solo perché sono un ogre?$B$BOra torniamo agli affari: portami i cuori e le lingue dei cuccioli e dei piccoli appena nati. Risalirò alla radice di questo male...",
  obj = "Draz'Zilb, a Brackenwall Village, vuole che tu gli porti 15 Searing Tongue e 15 Searing Heart.",
  progress = "Con i cuori e le lingue della progenie bruciata dell'esercito del drago nero, potrò decifrare quale bestia immonda abbia portato la sua prole nella nostra casa. Forse, conoscendo meglio i nostri aggressori, potremo cercare di distruggerli una volta per tutte e strappare Stonemaul Village alla rovina.$B$BNaturalmente, convincere Mok'Morokk a spostare la sua pigra mole di grasso fuori da questo buco fangoso sarà già di per sé un'impresa epica...",
  reward = "È stata di certo un'impresa pericolosa raccogliere tutti questi cuori e queste lingue. Mi addentrerò nelle profondità dell'arcano per risalire all'origine della minaccia nera che si è abbattuta sulla nostra vecchia casa.",
  en_title = "Identifying the Brood",
  en_obj = "Draz'Zilb in Brackenwall Village would like you to bring him 15 Searing Tongues and 15 Searing Hearts.",
}
T[1170] = {
  title = "La covata di Onyxia",
  desc = "Stonemaul Village è stato invaso dalla covata di Onyxia. Ma perché la figlia del signore dei draghi neri, Deathwing, dovrebbe calare sulle nostre terre?$B$BÈ molto preoccupante. Di certo Onyxia è stata spinta fin qui da uno scopo che va oltre l'assedio di una piccola banda di ogre.$B$BAvverti subito Mok'Morokk! Bisogna agire.",
  obj = "Parla con Overlord Mok'Morokk, a Brackenwall Village.",
  reward = "Perché tu dire a me di draghi? A me non piacere draghi. A me piacere qui. Qui niente draghi.",
  en_title = "The Brood of Onyxia",
  en_obj = "Speak with Overlord Mok'Morokk in Brackenwall Village.",
}
T[1171] = {
  title = "La covata di Onyxia",
  desc = "Tu lasciare me in pace adesso. Andare dire a Draz'Zilb che noi restare qui. Qui niente drago nero.",
  obj = "Parla con Draz'Zilb, a Brackenwall Village.",
  reward = "Quel pigro codardo!$B$BMok'Morokk mostrava forza quando Rexxar era il nostro capo. Ma poco dopo la partenza di Rexxar, Mok'Morokk è caduto preda delle tentazioni del potere. Invece di guidare, pretendeva. Non serve la sua gente: si aspetta piuttosto che siamo noi a servire lui.$B$BBisogna fare qualcosa.",
  en_title = "The Brood of Onyxia",
  en_obj = "Speak with Draz'Zilb in Brackenwall Village.",
}
T[1172] = {
  title = "La covata di Onyxia",
  desc = "La covata di Onyxia è stata sparsa per tutto il Dragonmurk. È indispensabile che non si permetta ad altri cuccioli di uscire dall'uovo.$B$BSbrigati a raggiungere il Wyrmbog, nel sud del Dustwallow Marsh. Di certo è lì che ha fatto la sua tana. Trova le uova del drago malvagio e distruggile.$B$BNon riconquisteremo mai Stonemaul Village se i dintorni restano una zona di nidificazione.$B$BQuanto a Mok'Morokk... ho altri piani per quell'idiota.",
  obj = "Draz'Zilb, a Brackenwall Village, vuole che tu distrugga 5 Egg of Onyxia.",
  progress = "Devi correre al Dragonmurk, $N. Con le uova di Onyxia sparse per tutto il Wyrmbog, ci troveremo davanti a un numero schiacciante di nemici, se non si fa qualcosa in fretta.$B$BDistruggi le sue uova! Non lasciare che la piaga del drago nero si diffonda nella nostra terra!",
  reward = "Splendido! Passerà del tempo prima che Onyxia possa produrre altre uova.$B$BA nome della mia gente, ti ringrazio, $N.$B$BFinora ti ho chiesto molto. Forse puoi rendere un ultimo servizio allo Stonemaul Clan.$B$BMok'Morokk non è adatto a guidarci. Tharg sarebbe un capo eccellente, ma è frenato dalle ferite e dall'età. Caccia Mok'Morokk da questo posto con la forza. Solo allora potremo nominare un nuovo capo che ci riporti alla nostra vera casa, a sud.",
  en_title = "The Brood of Onyxia",
  en_obj = "Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.",
}
T[1173] = {
  title = "Sfida Overlord Mok'Morokk",
  desc = "Tu osare sfidare Overlord Mok'Morokk?$B$BAh ah!$B$BIo schiacciare $Gpiccolo:piccola; $R!$B$BTu dire a me quando $Gpronto:pronta; per bella batosta.",
  obj = "Sconfiggi Mok'Morokk e riferisci la notizia a Draz'Zilb, a Brackenwall Village.",
  progress = "Credevo che avresti tentato di cacciare Mok'Morokk dal villaggio. E invece sei $Gvenuto:venuta; da me a fare due chiacchiere?",
  reward = "Quel vile ammasso di grasso di Mok'Morokk è fuggito come un bambino spaventato. Hai reso un grande servizio, $N.$B$BOra la mia gente potrà nominare un nuovo capo, uno che ci aiuti a riconquistare una volta per tutte la nostra vecchia casa.",
  en_title = "Challenge Overlord Mok'Morokk",
  en_obj = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.",
}
T[1175] = {
  title = "Un ostacolo sulla strada",
  desc = "Dopo il grande schianto tra il Red Thunder dei goblin e un basilisco, Kronkrider mi ha assunto per occuparmi della pista. Non so cosa mangino tutti gli animali qui nelle saline per diventare così grossi, ma dobbiamo stare attenti a diradarli, così non finiscono in pista durante una corsa.$B$BFacciamo così. Se vuoi guadagnarti qualcosa, va' là fuori e togli di mezzo i basilischi della zona.",
  obj = "Uccidi 10 Saltstone Basilisk, 10 Saltstone Crystalhide e 6 Saltstone Gazer per Trackmaster Zherin, nelle Shimmering Flats.",
  progress = "Già è brutto dover ripulire i rottami delle vetture, figurarsi doverli staccare da pezzi di animale bruciacchiati.",
  reward = "Spero che tu non abbia ucciso nessuno dei basilischi proprio sulla pista! Le carcasse ci mettono un sacco a decomporsi al sole, e preferirei non dover tirare fuori la pala per ripulire.",
  en_title = "A Bump in the Road",
  en_obj = "Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats.",
}
T[1176] = {
  title = "Alleggerire il carico",
  desc = "Quando si corre, ogni minima cosa conta! Che sia una piccola regolazione della potenza, un leggero allentamento delle molle o l'alleggerimento del telaio, devi tenere conto di tutto.$B$BPer molte delle piccole modifiche strutturali alle nostre vetture usiamo ossa di avvoltoio: hanno l'equilibrio perfetto tra robustezza e peso. E per di più è facile procurarcene altre, perché le saline sono piene di avvoltoi.$B$BPortamene un po' e te le pagherò bene.",
  obj = "Procura 10 Hollow Vulture Bone a Pozzik, nelle Shimmering Flats.",
  progress = "Ce le hai quelle ossa per me? Stavo giusto per mettermi ad alleggerire il gruppo dello sterzo, ma non voglio aprirla senza avere tutti i pezzi che mi servono.",
  reward = "Ottimo! Posso mettere subito la squadra al lavoro. Grazie, $N!",
  en_title = "Load Lightening",
  en_obj = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.",
}
T[1177] = {
  title = "Fame!",
  desc = "Mud grosso ogre.$B$BIo avere fame.$B$BTu andare picchiare pesciolini. Portare cibo a Mud.$B$BTu dare da mangiare a Mud o Mud mangiare te.",
  obj = "Mudcrush Durtfeet, nel Dustwallow settentrionale, vuole 12 Mirefin Head.",
  progress = "Dare cibo a me o io mangiare te.",
  reward = "A me piacere testa di pesciolino!$B$BIo non mangiare te adesso.",
  en_title = "Hungry!",
  en_obj = "Mudcrush Durtfeet in northern Dustwallow wants 8 Mirefin Heads.",
}
T[1178] = {
  title = "Gli sponsor goblin",
  desc = "La nostra squadra da corsa è l'orgoglio dei goblin di tutto il mondo. Ti sorprenderebbe sapere quanta gente contribuisce in un modo o nell'altro alla squadra.$B$BConosci Gazlowe? Ci trova pezzi in giro per il mondo. Una volta è perfino venuto qui a lavorare su una delle nostre vetture!$B$BQualche settimana fa ha detto che ci avrebbe mandato un nuovo prototipo di regolatore del carburante, ma non è ancora arrivato. Di solito è puntualissimo... Ti dispiacerebbe andare a Ratchet a chiedergli com'è la faccenda? Non vorrei insistere, ma gli gnomi ci stanno raggiungendo!",
  obj = "Parla con Gazlowe, a Ratchet.",
  reward = "Ti manda Pozzik, eh? Sai, Pozzik era uno degli artigiani più rispettati di Undermine prima di ritirarsi per mettersi a lavorare sulle vetture da corsa.$B$BLa prima cosa che ha fatto quando è entrato nella squadra è stata sviluppare le vetture a due motori. Può darsi che gli affari ne risentano, senza di lui alla Tinkers' Union, ma chi se ne importa, no? Non c'è niente come le corse!",
  en_title = "Goblin Sponsorship",
  en_obj = "Speak to Gazlowe in Ratchet.",
}
T[1179] = {
  title = "I fratelli Brassbolts",
  desc = "Hai mai sentito parlare delle Shimmering Flats? È una distesa di saline laggiù a Kalimdor, appena a sud del canyon di Thousand Needles. È un posto perfetto per le corse perché, be', è pianissimo!$B$BCi sono due fratelli gnomi laggiù, amici miei, che stanno provando la loro nuova auto a razzo, e da quel che ho sentito è veloce! Eh, così veloce che i loro piloti continuano a schiantarsi. E a prendersi delle belle botte in testa.$B$BCosì mi hanno chiesto qualche elmo da macchina d'assedio, ma io qui ho i miei compiti. Non posso fare il viaggio!$B$BTu puoi?",
  obj = "Porta la cassa di caschi protettivi a Wizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Guarda dove metti i piedi! Guarda guarda guarda!! Qui c'è roba delicata, e se vogliamo vincere deve funzionare tutto alla perfezione!",
  reward = "Ah! Ti manda Longbeard con un carico di elmi! Evviva!$B$BAdesso forse riusciamo a convincere un pilota a guidare la nostra auto...",
  en_title = "The Brassbolts Brothers",
  en_obj = "Bring the crate of crash helmets to Wizzle Brassbolts in the Shimmering Flats.",
}
T[1180] = {
  title = "Gli sponsor goblin",
  desc = "Torniamo al motivo per cui sei qui. Lo so che avevo promesso a Pozzik di consegnargli un nuovo regolatore del carburante, ma non l'ho ancora ricevuto. Revilgaz, laggiù a Booty Bay, aveva detto che me l'avrebbe fatto spedire, ma può darsi che in qualche modo sia finito nel dimenticatoio.$B$BSe è così, non possiamo farci molto. Almeno possiamo scoprire se è mai partito da Booty Bay.$B$BSenti Wharfmaster Lozgil laggiù: dovrebbe poter controllare i registri del carico.",
  obj = "Parla con Wharfmaster Lozgil, a Booty Bay.",
  reward = "Spedizioni per Ratchet? Fammi controllare i registri...$B$BNo, l'ultima spedizione per Ratchet che risulta erano stivali di Drizzlik. Non c'è stato molto altro, a parte materiali da costruzione e attrezzi. Di sicuro nessun pezzo da corsa.",
  en_title = "Goblin Sponsorship",
  en_obj = "Speak with Wharfmaster Lozgil in Booty Bay.",
}
T[1181] = {
  title = "Gli sponsor goblin",
  desc = "Temo di non poterti essere di grande aiuto, $N. Se vuoi approfondire, ti consiglio di rivolgerti al barone in persona. Se c'è qualcuno che conosce gli affari di Revilgaz, è Revilgaz.$B$BLo trovi alla taverna dall'altra parte del porto, all'ultimo piano.",
  obj = "Parla con Baron Revilgaz, a Booty Bay.",
  reward = "Oh, certo che so di cosa parli. Però no, non posso aiutarti. Alcuni dei miei uomini dovevano andare a recuperare i progetti del regolatore del carburante, ma sono tornati a mani vuote.",
  en_title = "Goblin Sponsorship",
  en_obj = "Speak with Baron Revilgaz in Booty Bay.",
}
T[1182] = {
  title = "Gli sponsor goblin",
  desc = "Vedi, le sminuzzatrici della Venture Company là al Lake Nazferiti (nella Stranglethorn settentrionale) sono state dotate di un regolatore del carburante di nuovo modello. Pensavo che Pozzik potesse sfruttarlo, se solo avesse qualche dettaglio. Purtroppo Cozzle, il caposquadra laggiù, sembra un po' più furbo di quanto credessi.$B$BTu però potresti avere più fortuna nel trovare i progetti. So che li tiene in casa sua, ma quasi di sicuro sono sotto chiave.",
  obj = "Porta i Fuel Regulator Blueprints a Baron Revilgaz, a Booty Bay.",
  progress = "Per quanto mi costi ammetterlo, quella squadra di gnomi laggiù è piuttosto brava. I nostri ragazzi hanno bisogno di ogni vantaggio possibile.",
  reward = "Ora, fammi solo fare una copia di questi progetti per i miei appunti e poi puoi portarli dritti a Pozzik. Non vorrei che pensasse che uno dei suoi sponsor lo sta abbandonando.",
  en_title = "Goblin Sponsorship",
  en_obj = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.",
}
T[1183] = {
  title = "Gli sponsor goblin",
  desc = "Dovresti essere a posto. Saluta Pozzik da parte mia e digli che se gli serve qualcosa non esiti a chiedere. Aspetto la notizia che presto batterà il record della pista!",
  obj = "Consegna i Fuel Regulator Blueprints a Pozzik, nelle Shimmering Flats.",
  progress = "$N! Sei $Griuscito:riuscita; a rintracciare il regolatore del carburante?",
  reward = "Speravo che fosse già assemblato, ma così ho l'occasione unica di migliorare il progetto da zero. Grazie, $N. Riuscirò a buttare giù qualche schema migliorato, a costruire l'aggeggio e a farlo installare molto presto.",
  en_title = "Goblin Sponsorship",
  en_obj = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.",
}
T[1184] = {
  title = "Parti dello sciame",
  desc = "Torna da Belgrom, a Orgrimmar, e digli che Moktar esegue bene i suoi ordini là a Thousand Needles. Digli anche che i miei studi procedono e che spero di saperne di più presto. Questo gli farà molto piacere.",
  obj = "Torna da Belgrom Rockmaul, a Orgrimmar.",
  reward = "Apprezzo i tuoi sforzi, $C. Il Capoguerra sarà contento di sentire con quanta tenacia hai svolto i tuoi doveri.$B$BOh, certo che gli farò il tuo nome. Mi parla spesso e tiene molto in conto le mie opinioni.$B$BOra va', ho molto da fare. E se parlerai presto con Korran e lui avrà notizie di queste creature, torna da me: credo siano una minaccia da prendere sul serio.",
  en_title = "Parts of the Swarm",
  en_obj = "Return to Belgrom Rockmaul in Orgrimmar.",
}
T[1186] = {
  title = "Il diciottesimo pilota",
  desc = "Io sarò impegnato a integrare questo nuovo regolatore del carburante nei progetti delle nostre vetture, ma se ti va di dare ancora una mano alla squadra, parla con Razzeric. È il nostro pilota, anzi, il nostro diciottesimo pilota, per l'esattezza, e gli piace aggiungere qualche modifica sua alle vetture.$B$BÈ un po' fuori di testa, però, quindi cerca di non sembrare troppo $Gsorpreso:sorpresa;.",
  obj = "Parla con Razzeric, nelle Shimmering Flats.",
  reward = "Sei tu $Gil:la; $R che sta dando una mano a Pozzik, vero? Una volta ero come te: correvo su e giù per i box, aiutando in qualunque lavoro i meccanici mi lasciassero fare.$B$BE adesso guardami! Il pilota straordinario della squadra da corsa dei goblin!",
  en_title = "The Eighteenth Pilot",
  en_obj = "Speak with Razzeric on the Shimmering Flats.",
}
T[1187] = {
  title = "Le modifiche di Razzeric",
  desc = "Pozzik è un grande meccanico, lo so, ma ha paura di caricare potenza e basta e tenersi forte. Io no, però.$B$BDopo che Pozzik ha finito una vettura, mi prendo un po' di tempo per metterci le mie modifiche: sai, allentare i comandi, togliere pezzi di telaio e aggiungere più spinta!$B$BHo ordinato un seaforium booster da Shreev, al Gizmorium di Gadgetzan, ma a quanto pare lo zeppelin su cui viaggiava si è schiantato nel Dustwallow Marsh! Mi serve, $N!",
  obj = "Recupera il Seaforium Booster per Razzeric, nelle Shimmering Flats.",
  progress = "Come faccio a farmi vedere in pista senza una spintarella in più per partire? È uno scandalo, te lo dico io.",
  reward = "Ma guarda che bellezza! Quindici libbre di pura potenza al seaforium! Appena me lo lego al fianco della vettura, girerò in pista così veloce che batterò gli gnomi due volte!",
  en_title = "Razzeric's Tweaking",
  en_obj = "Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.",
}
T[1188] = {
  title = "Prima la sicurezza",
  desc = "Ma un momento, cos'è questa? Shreev ha lasciato inserita la sicura. Così limiterà la potenza che posso tirare fuori dal booster ogni volta. Gli avevo detto che la volevo tolta! Non va bene.$B$BDevi portarlo al Gadgetzan Gizmorium, nel Tanaris Desert, e farlo togliere da Shreev.",
  obj = "Porta il Seaforium Booster a Shreev, a Gadgetzan.",
  progress = "Come saprai di certo, il Gizmorium può soddisfare ogni tua esigenza di meccanica! Come posso aiutarti?",
  reward = "Solo Razzeric poteva guardare questo aggeggio e dire che ci avevo messo su chissà quale sicura. Questo booster è quasi tutto esplosivo al seaforium. L'ho già modificato perché all'uso rilasci più carica, ma Razzeric non è mai contento finché non si arriva a undici!",
  en_title = "Safety First",
  en_obj = "Bring the Seaforium Booster to Shreev in Gadgetzan.",
}
T[1189] = {
  title = "Prima la sicurezza",
  desc = "Ecco, ho fatto quel che voleva Razzeric. Digli solo di stare attento quando lo fa partire. Se sbaglia anche di poco, non andrà avanti: sarà solo una macchia bruciata sulla pista.$B$BSarebbe anche un peccato, se succedesse. Chissà se il nostro diciannovesimo pilota sarebbe altrettanto bravo.",
  obj = "Riporta il Modified Seaforium Booster a Razzeric, nelle Shimmering Flats.",
  progress = "Ci credi che Pozzik ha messo un secchio di sabbia sulla vettura? Come faccio a raggiungere la velocità massima con un secchio di sabbia sotto il sedile?",
  reward = "Ecco, così va meglio! Vorrei tanto vedere che faccia faranno gli gnomi quando lo vedranno partire.$B$BPeccato che sarò troppo occupato a stabilire un nuovo record sul tracciato!",
  en_title = "Safety First",
  en_obj = "Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats.",
}
T[1190] = {
  title = "Stare al passo",
  desc = "I fratelli Brassbolts hanno scoperto un nuovo materiale da costruzione: è l'unica spiegazione che abbia senso. Le loro auto vanno più veloci di prima, ma i progetti, e tutti gli altri dati che abbiamo raccolto dalle loro corse, sono identici.$B$BQuel che sappiamo è che Rizzle Brassbolts è concentrato quasi di continuo sui piani di questa nuova scoperta.$B$BZamek può creare un diversivo per te, così potrai rubargli quei piani.",
  obj = "Fa' creare un diversivo a Zamek, poi ruba i piani di Rizzle per Pozzik, nelle Shimmering Flats.",
  reward = "Scritti in fretta e furia, un rotolo di appunti e di disegni per la raffinazione di una materia prima.",
  en_title = "Keeping Pace",
  en_obj = "Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats.",
}
T[1191] = {
  title = "La distrazione di Zamek",
  reward = "Andiamo!",
  en_title = "Zamek's Distraction",
}
T[1192] = {
  title = "Indurium Ore",
  progress = "Vorrei integrare l'indurium in varie parti delle nostre vetture, ma per fare quei pezzi mi servono grandi quantità di indurium grezzo.$B$BIl minerale di indurium lo trovi nello scavo di Uldaman, nei Badlands, oltre il mare a Khaz Modan.$B$BGli gnomi si stanno procurando la loro scorta, quindi è importante che ci procuriamo la nostra per stare al passo con loro.",
  reward = "Eccellente! Metto subito la squadra al lavoro sui pezzi che ci serviranno per la prossima corsa.",
  en_title = "Indurium Ore",
}
T[1194] = {
  title = "Gli schemi di Rizzle",
  desc = "Gli schemi di Rizzle descrivono il procedimento di raffinazione del minerale di indurium. Dai suoi scarabocchi si capisce che il minerale di indurium viene estratto dal sito di scavo nanico di Uldaman, nei Badlands.$B$BGran parte degli altri appunti riguarda le proprietà di resistenza al calore.$B$BCome fermacarte sui piani c'è un pezzo di quello che sembra minerale di indurium grezzo.",
  obj = "Porta il Sample of Indurium Ore a Pozzik, nelle Shimmering Flats.",
  reward = "Indurium? Interessante... Se resiste al calore quanto dici, spiegherebbe l'aumento di prestazioni che gli gnomi hanno mostrato ultimamente.$B$BAnche questo campione che mi hai portato sarà preziosissimo. Potrò fare qualche prova, ma perché ci serva davvero a qualcosa me ne servirà di più.",
  en_title = "Rizzle's Schematics",
  en_obj = "Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats.",
}
T[1195] = {
  title = "La fiamma sacra",
  desc = "I centauri Galak, nelle Thousand Needles, custodiscono un manufatto che risale al tempo della creazione dei centauri.$B$BVorremmo recuperarlo, ma ci serve una fiala d'acqua presa da uno dei pozzi lunari degli elfi della notte.$B$BPer raccogliere l'acqua dovrai prima procurarti una delle fiale portate dalle driadi vicino al Raynewood Retreat, nel cuore dell'Ashenvale Forest. C'è un pozzo lunare vicino alla riva occidentale del Falfarren River, a sud della strada principale, dove puoi riempire la fiala.",
  obj = "Riporta un Filled Etched Phial a Zangen Stonehoof, a Thunder Bluff.",
  progress = "Una volta che avremo la fiala piena, potremo mandarla al mio socio, Rau, nelle Thousand Needles. È stato lui a chiedere la fiala d'acqua, quindi saprà meglio di noi come possiamo usarla.",
  reward = "Molto bene. Questo dovrebbe soddisfare in pieno la richiesta di Rau. Potresti consegnarglielo? Forse ti farà piacere passare un po' di tempo nelle Needles.",
  en_title = "The Sacred Flame",
  en_obj = "Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.",
}
T[1196] = {
  title = "La fiamma sacra",
  desc = "Porta la fiala piena a Rau Cliffrunner, al Freewind Post, nelle Thousand Needles sud-orientali. Puoi arrivare alle Thousand Needles prendendo il Great Lift, al margine meridionale delle Barrens.$B$BNon mi stupirei se potessi aiutarci ancora.",
  obj = "Consegna il Filled Etched Phial a Rau Cliffrunner, al Freewind Post.",
  progress = "Non sarai $Gstato mandato:stata mandata; da Zangen, eh?",
  reward = "Hm, sì, questa fiala d'acqua servirà perfettamente ai nostri scopi. Per via della discendenza comune delle driadi e dei centauri, l'acqua dei pozzi lunari ci permetterà di forzare la protezione della fiamma eterna che circonda la reliquia dei centauri.",
  en_title = "The Sacred Flame",
  en_obj = "Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.",
}
T[1197] = {
  title = "La fiamma sacra",
  desc = "Usando l'acqua che hai portato, potrai spegnere per un po' la fiamma che trattiene la reliquia dei centauri. Non durerà per sempre, però, quindi dovrai fare in fretta.$B$BTroverai lo Splithoof Crag, la roccaforte dei centauri, a nord di qui. La fiamma è custodita nello Splithoof Hold, una parte della rupe sorvegliata a vista.$B$BSta' $Gattento:attenta;, però: i centauri Galak qui sono in gran numero, e saranno piuttosto restii a cedere qualcosa a cui tengono tanto.",
  obj = "Recupera il Cloven Hoof per Rau Cliffrunner, al Freewind Post.",
  progress = "Non vedo l'ora di mettere le mani sul Cloven Hoof. L'hai già preso?",
  reward = "Sento una strana energia emanare dall'Hoof... Non ho dubbi che dal suo studio scopriremo informazioni nuove e sorprendenti sui centauri.$B$BTi ringrazio, $N. Ora devo cominciare a decifrare i misteri che mi hai portato.",
  en_title = "The Sacred Flame",
  en_obj = "Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.",
}
T[1198] = {
  title = "Alla ricerca di Thaelrid",
  desc = "In questi giorni girano molte voci sull'unione tra il Martello del Crepuscolo e i naga nelle Blackfathom Deeps, sulle coste di Ashenvale.$B$BIl mio ruolo qui, nell'Argent Dawn, è raccogliere quante più informazioni posso, così da sapere quando e dove serve aiuto.$B$BSono passate settimane da quando ho mandato un esploratore a controllare le attività alle Blackfathom Deeps. Argent Guard Thaelrid non ha ancora riferito.$B$BGli altri miei esploratori sono impegnati in faccende urgenti.$B$BTrova Thaelrid e aiutalo per me, $N.",
  obj = "Trova Argent Guard Thaelrid nelle Blackfathom Deeps.",
  reward = "Dawnwatcher Shaedlass ha fatto bene a mandarti. In questo luogo corrotto è davvero in corso un piano malvagio.",
  en_title = "In Search of Thaelrid",
  en_obj = "Seek out Argent Guard Thaelrid in Blackfathom Deeps.",
}
T[1199] = {
  title = "Il Twilight cade",
  desc = "Rafforzati dai riti ancestrali dei caotici Antichi Dei, i membri del Martello del Crepuscolo si adoperano per riportare i loro oscuri padroni e diffondere morte e terrore per il mondo.$B$BCrediamo che il Martello del Crepuscolo si sia alleato con i naga e si stia radunando nelle Blackfathom Deeps, sulla costa di Ashenvale.$B$BQualunque piano malvagio si stia preparando nelle profondità dell'antico tempio va sventato.$B$BMuovi guerra al Martello e riporta la prova delle tue imprese. I tuoi sforzi saranno ricompensati con generosità.",
  obj = "Porta 10 Twilight Pendant ad Argent Guard Manados, a Darnassus.",
  progress = "Le Blackfathom Deeps un tempo erano un antico tempio degli elfi della notte. Un tempo ospitavano un pozzo lunare potentissimo. Chissà quale male vi si prepara ora per mano del Martello del Crepuscolo.$B$BHai fatto progressi nel liberare il luogo dalla loro presenza?",
  reward = "Sei senza dubbio di sangue coraggioso e nobile, $N. L'Argent Dawn ti loda per i tuoi sforzi contro il male.",
  en_title = "Twilight Falls",
  en_obj = "Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.",
}
T[1200] = {
  title = "La malvagità di Blackfathom",
  desc = "Le forze mi hanno abbandonato. Serve il tuo aiuto!$B$BTanto tempo fa questo luogo era un grande tempio di Elune. Ma la sventura lo portò in rovina quando la corruzione di un Antico Dio filtrò da sotto la terra e contaminò il sacro pozzo lunare.$B$BAku'Mai, servitore dell'Antico Dio, si levò dalle acque.$B$BI cultisti del Martello del Crepuscolo si sono alleati con i naga per occupare questi luoghi. I cultisti, guidati da Kelris, sacrificano innocenti ad Aku'Mai per averne potere.$B$BUccidi Kelris e porta la sua testa a Selgorm, a Darnassus, $N, ti prego.",
  obj = "Porta la testa di Twilight Lord Kelris a Dawnwatcher Selgorm, a Darnassus.",
  progress = "Il tempo è una merce preziosa, $C.$B$BIl mio ruolo qui a Darnassus è fare in modo che l'Argent Dawn prosperi e che le forze del male che avanzano su Kalimdor siano fermate.$B$BDi' in fretta cosa vuoi, oppure va' per la tua strada.",
  reward = "Kelris ci è sfuggito per parecchio tempo.$B$BSembra che ogni volta che il male si è fatto sentire da queste parti, Kelris ci avesse messo lo zampino. Per un po' lo abbiamo creduto morto o scomparso.$B$BMa ora torna tutto. Ponendo fine al suo dominio hai risparmiato la vita a molti innocenti.$B$BPer la Luce! Sacrificare qualcuno a un servitore di un Antico Dio per il proprio tornaconto è al di là di ogni vergogna!$B$BHai compiuto una grande impresa, $N. Ti saluto a nome dell'Argent Dawn.",
  en_title = "Blackfathom Villainy",
  en_obj = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.",
}
T[1201] = {
  title = "Spie di Theramore",
  desc = "L'Orda e l'Alleanza mantengono una tregua precaria. Scaramucce ai confini e azioni segrete vengono condotte da una parte contro l'altra, ed è nostro dovere fare in modo che l'Orda abbia la meglio!$B$BOra è il momento di fare proprio questo.$B$BInfiltrati dell'Alleanza hanno preso posizione a est di Brackenwall Village. Spiano il villaggio e riferiscono i nostri movimenti a Theramore, cosa che non possiamo permettere.$B$BDai la caccia agli infiltrati e uccidili. Manda ai loro superiori un messaggio chiaro: non tollereremo la presenza delle loro spie!",
  obj = "Uccidi 9 Theramore Infiltrator, poi torna da Nazeer Bloodpike, a Brackenwall Village.",
  progress = "Hai trovato gli infiltrati, $N?",
  reward = "Buon lavoro. I loro infiltrati sono abili, ma non abbastanza da sfuggire all'occhio vigile dell'Orda!",
  en_title = "Theramore Spies",
  en_obj = "Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village.",
}
T[1202] = {
  title = "I moli di Theramore",
  desc = "$N, due delle nostre spie sono state mandate a rubare dei documenti da una nave ai moli di Theramore. Hanno preso le carte ma sono state scoperte, e sono state costrette a gettare i documenti in mare.$B$BPiù tardi una delle spie è fuggita, ma non è riuscita a recuperare il bottino. Mi ha riferito il suo fallimento, e ora affido il compito a te.$B$BI documenti sono in un baule, da qualche parte nell'acqua sotto i moli di Theramore. Trova quei documenti, $N, e portameli.",
  obj = "Porta i Captain's Documents a Nazeer Bloodpike, a Brackenwall Village.",
  progress = "Hai trovato i documenti, $N? Contengono informazioni vitali per la stabilità dell'Alleanza e, quindi, vitali per la sicurezza dell'Orda.",
  reward = "Mi congratulo con te, $N. Non era una missione facile. Ma i documenti che hai preso sono molto apprezzati dai nostri superiori.",
  en_title = "The Theramore Docks",
  en_obj = "Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village.",
}
T[1203] = {
  title = "A Jarl serve una lama",
  desc = "Devo tagliare delle cose. Non posso dirti cosa taglierò, ma... mi serve una lama. Una lama particolare...$B$BAlcuni la chiamano Moonsteel Broadsword. Io la chiamo lama da falciare.$B$BMi aiuti? Magari la trovi in città, magari parli con un fabbro e lui te la fa apposta.$B$BMa non dormirci sopra. Quello che devo tagliare non si conserva per sempre...",
  obj = "Porta un Moonsteel Broadsword a Jarl, nel Dustwallow Marsh.",
  progress = "Hai la mia lama??",
  reward = "È una bella lama. Falcia bene. È proprio una bella lama da falciare. Grazie. Grazie, grazie, grazie!!! Adesso voglio provarla...$B$BDopo. La provo dopo. Ma come stavo dicendo... grazie.",
  en_title = "Jarl Needs a Blade",
  en_obj = "Bring a Moonsteel Broadsword to Jarl in Dustwallow Marsh.",
}
T[1204] = {
  title = "Zuppa di Mudrock e crostacei",
  desc = "Sto lavorando a un piatto che chiamo \"Zuppa di Mudrock e crostacei\". Mi mancano ancora gli ingredienti principali, e... be', non credo che durerei a lungo arrancando per il Dustwallow Marsh!$B$BAllora, $N, puoi andare a caccia per me? Prima di tutto mi servono le lingue delle tartarughe Mudrock. Trovi le Mudrock lungo la costa, soprattutto intorno alla baia.$B$BMa non voglio lingue qualsiasi! Ho sentito che alcune Mudrock hanno la lingua biforcuta...$B$BDicono che le lingue biforcute abbiano un sapore particolare, e io voglio quel sapore nel mio piatto...",
  obj = "Porta 8 Forked Mudrock Tongue a Morgan Stern, a Theramore.",
  progress = "Hai preso le lingue biforcute?",
  reward = "Queste andranno benissimo! Grazie, $N!$B$BOra proverò diverse tecniche di cottura su queste lingue, per trovare il modo migliore di esaltarne il sapore.$B$BAlla fine avrò un piatto degno di essere servito al Blue Recluse di Stormwind!",
  en_title = "Mudrock Soup and Bugs",
  en_obj = "Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore.",
}
T[1205] = {
  title = "Deadmire",
  desc = "Deadmire è un antico crocolisk del Dustwallow Marsh. Ed è giunta la sua ora di morire.$B$BLe vecchie ossa scricchiolano mentre trascina il suo corpo enorme attraverso la palude, e benché si muova ancora con la forza e la velocità della giovinezza, il suo corpo che invecchia tormenta il grande spirito che racchiude, uno spirito la cui fiamma non vacilla.$B$BEppure ora vive in un dolore costante, che fa impazzire. Devi porre fine alla vita di questa nobile creatura, $N. Devi condurre Deadmire alla pace.",
  obj = "Porta Deadmire's Tooth a Melor, a Thunder Bluff.",
  progress = "Hai il dente di Deadmire, $N? Hai posto fine alle sofferenze della creatura?",
  reward = "Molto bene, $N.$B$BSono sicuro che la caccia non sia stata facile, ma è bello sapere che il dolore della bestia è finalmente finito.",
  en_title = "Deadmire",
  en_obj = "Bring Deadmire's Tooth to Melor in Thunder Bluff.",
}
T[1206] = {
  title = "A Jarl servono occhi",
  desc = "Il succo d'occhi è un buon succo da bere. Peccato che quasi tutte le bestiole abbiano solo due occhi.$B$BMa i ragni hanno tanti occhi. Tanti, tantissimi. E il succo d'occhi di Darkmist è saporito. Vellutato e salato! Occhi di ragno non scoppiati... ne sento già il sapore.$B$BI Darkmist Spider sono a ovest di qui, nella Darkmist Cavern. Secondo te i ragni prendono il nome dalla caverna... o è il contrario?",
  obj = "Porta 40 Unpopped Darkmist Eye a \"Swamp Eye\" Jarl, allo Swamplight Manor.",
  progress = "Dove sono quegli occhi?",
  reward = "Hai gli occhi! Hai gli occhi! Gustosi, gustosi occhi di ragno!$B$BCerti occhi... quando li fissi, ti fissano anche loro. Quelli mangiali per ultimi. Ti tengono compagnia... qui fuori nella palude.$B$BCiao, occhietti di ragno. Ciao! Sapete di pollo. Pollo appiccicoso e salato!$B$BMmmh.",
  en_title = "Jarl Needs Eyes",
  en_obj = "Bring 20 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor.",
}
T[1218] = {
  title = "Soothing Spices",
  desc = "Mi piace cucinare. La buona cucina di palude. Cosce di rana verde fritte e cose simili.$B$BE per cucinare mi servono spezie. Spezie lenitive. Poi preparo uno stufato, lo faccio stufare per bene, me lo sorbisco e ne do un po' anche a te.$B$BTi piace lo stufato?",
  obj = "Porta 3 Soothing Spices a \"Swamp Eye\" Jarl, nel Dustwallow Marsh.",
  progress = "Spezie. A tutti farebbe comodo un po' di spezie nella vita. Sei d'accordo?",
  reward = "Ah, queste sì che sono spezie! Ecco del buono stufato di palude.",
  en_title = "Soothing Spices",
  en_obj = "Bring 3 Soothing Spices to \"Swamp Eye\" Jarl in Dustwallow Marsh.",
}
T[1219] = {
  title = "Il rapporto dell'orco",
  desc = "Setacciando la terra smossa, si trova la mano mozzata di un orco. E stretto nella mano c'è un tubo intagliato nell'osso. E nel tubo c'è una pergamena macchiata di terra.$B$BLa pergamena è scritta in orchesco... e sembra importante.",
  obj = "Porta lo Spy's Report a un Theramore Lieutenant.",
  progress = "Hai un rapporto da fare?",
  reward = "Hm... non leggo molto bene l'orchesco, ma questo sembra un rapporto... scritto da una spia orchesca!",
  en_title = "The Orc Report",
  en_obj = "Bring the Spy's Report to a Theramore Lieutenant.",
}
T[1220] = {
  title = "Captain Vimes",
  desc = "Captain Vimes dovrebbe vedere il rapporto orchesco che hai trovato, $N. Conosce la lingua degli orchi meglio di molti altri. E dovrebbe sapere che ci sono spie dell'Orda vicino a Theramore!$B$BIl capitano è nella caserma, sul lato nord-orientale di Theramore Isle.",
  obj = "Porta lo Spy's Report a Captain Garran Vimes.",
  progress = "Hai qualcosa per me?",
  reward = "Un rapporto di una spia orchesca! Come l'hai trovato? Non importa, vediamo cosa dice...",
  en_title = "Captain Vimes",
  en_obj = "Bring the Spy's Report to Captain Garran Vimes.",
}
T[1221] = {
  title = "Blueleaf Tubers",
  desc = "I Blueleaf Tuber sono una prelibatezza in tutto il mondo! Ma sono rari, molto rari. L'unico posto dove trovarli è qui nelle Barrens, nelle profondità della terra, nel Razorfen Kraul.$B$BE anche lì è impossibile trovarli, a meno di sapere esattamente dove cercare! Per questo ho addestrato questi Snufflenose Gopher a trovarli per me. Hanno un gran fiuto e sentono l'odore di un tubero a cinquanta passi di distanza.$B$BNon sarà facile, ma se mi porti qualche tubero ti pagherò profumatamente.",
  obj = "Prendi una Crate with Holes.$BPrendi uno Snufflenose Command Stick.$BPrendi e leggi lo Snufflenose Owner's Manual.$B$BNel Razorfen Kraul, usa la Crate with Holes per evocare uno Snufflenose Gopher e usa il Command Stick sul gopher per fargli cercare i Tuber.$B$BPorta 6 Blueleaf Tuber, lo Snufflenose Command Stick e la Crate with Holes a Mebok Mizzyrix, a Ratchet.",
  progress = "Hai i tuberi, $N?",
  reward = "Perfetto, li hai presi! Posso venderli ai miei contatti a peso d'oro!$B$BGrazie della consegna, $N! Sei $Gun ottimo socio:un'ottima socia;.",
  en_title = "Blueleaf Tubers",
  en_obj = "Grab a Crate with Holes.$BGrab a Snufflenose Command Stick.$BGrab and read the Snufflenose Owner's Manual.$B$BIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.$B$BBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.",
}
T[1222] = {
  title = "La fuga di Stinky",
  desc = "Grande, finalmente qualcosa che non vuole mangiarmi!$B$BMi serve aiuto per tenere a bada le bestiacce di qui, e tu fai al caso mio, $Gamico:signora;.$B$BIl cuoco Morgan Stern sta studiando una nuova ricetta, e mi ha mandato qui a raccogliere foglie di bogbean. Immagino che le trovi gustose.$B$BComunque, mentre cercavo una pianta di bogbean... mi sono fatto circondare! Puoi aiutarmi a uscire di qui e guardarmi le spalle mentre cerco il bogbean?",
  obj = "Scorta \"Stinky\" Ignatz, poi parla con Morgan Stern, a Theramore.",
  progress = "Hai visto il signor Ignatz? L'ho mandato nella palude un po' di tempo fa e non è tornato!",
  reward = "Il signor Ignatz è appena passato di qui con le foglie di bogbean, e mi ha detto che l'hai aiutato a uscire da un bel guaio.$B$BGrazie, $N. Chiederò a mio zio di offrirti un banchetto la prossima volta che visiterai il Blue Recluse, a Stormwind.",
  en_title = "Stinky's Escape",
  en_obj = "Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.",
}
T[1238] = {
  title = "Il rapporto perduto",
  desc = "Setacciando la terra smossa, si trova la mano mozzata di un orco. E stretto nella mano c'è un tubo intagliato nell'osso. E nel tubo c'è una pergamena macchiata di terra.$B$BLa pergamena è un rapporto scritto da un orco che ha passato settimane a spiare la città di Theramore.$B$BDopo aver scorso la pergamena, è chiaro che va portata al capo delle spie degli orchi, a Brackenwall Village.",
  obj = "Porta lo Spy's Report a Nazeer Bloodpike, a Brackenwall Village.",
  progress = "Hai qualcosa per me?",
  reward = "Buon lavoro, $N. Il nostro agente, Marg Nighteye, era di stanza fuori Theramore. Aveva il compito di spiare la città.$B$BQuesto è il suo rapporto più recente, e potrebbe essere l'ultimo: da quello che racconti, temo che Marg abbia trovato la fine nella palude...",
  en_title = "The Lost Report",
  en_obj = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.",
}
T[1239] = {
  title = "La testa mozzata",
  desc = "Uno scavo vigoroso porta alla luce la testa di un orco maschio, mozzata malamente all'altezza del collo. Le labbra sono irrigidite in un ringhio, e gli occhi scuri fissano con aria di sfida.",
  obj = "Porta la Defiant Orc Head a Nazeer Bloodpike, a Brackenwall Village.",
  progress = "Hai un'altra questione da riferire, $N?",
  reward = "Questa è la testa di Marg Nighteye! Come temevo, è morto.$B$BGuarda la ferita sul collo! Può essere stata un'arma a fare quel taglio frastagliato, o è stata qualche bestia a uccidere il nostro agente?$B$BÈ un mistero che dobbiamo risolvere, $N. Dobbiamo scoprire se la morte di Marg è opera dell'Alleanza!",
  en_title = "The Severed Head",
  en_obj = "Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.",
}
T[1240] = {
  title = "Lo stregone troll",
  desc = "Dobbiamo conoscere i fatti legati alla morte di Marg! E l'unico modo per farlo, $N, è la magia stregonesca dei troll.$B$BPorta la testa di Marg a Kin'weelay, nella Stranglethorn Vale, al Grom'gol Base Camp.$B$BKin'weelay è lo stregone più potente dei troll Darkspear. Se qualcuno può parlare con lo spirito di Marg Nighteye, è lui.",
  obj = "Porta la Defiant Orc Head a Kin'weelay, al Grom'gol Base Camp, nella Stranglethorn Vale.",
  progress = "C'è uno spirito furioso intorno a te, $Gfratello:sorella;. Cosa ti porta da Kin'weelay?",
  reward = "Ah, ora vedo. Lo spirito di questo orco è legato al nostro mondo, e ribolle di rabbia per un compito non ancora portato a termine.$B$BBene, facciamo due chiacchiere con questo orco arrabbiato...",
  en_title = "The Troll Witchdoctor",
  en_obj = "Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.",
}
T[1241] = {
  title = "Il diplomatico scomparso",
  desc = "Di recente un diplomatico è stato mandato a Theramore per incontrare Jaina Proudmoore. Quel diplomatico non è mai arrivato.$B$BCredo che in questa trama ci siano di mezzo i Defias, ma non so come. La scomparsa del diplomatico sfugge ancora all'attenzione del pubblico, ma non potrà restare così a lungo.$B$BGli agenti del re stanno già setacciando la città in cerca di indizi, ma ho anche i miei contatti, e voglio coinvolgerli.$B$BNella Valley of Heroes c'è un mio vecchio amico di nome Jorgen. Trovalo, dagli questo biglietto e segui le sue istruzioni.",
  obj = "Trova Jorgen, a Stormwind City.",
  progress = "Hmph, sarà meglio che tu abbia un buon motivo per disturbare un uomo che pesca. Non mi vanno a genio i venditori ambulanti, figurarsi gli accattoni.",
  reward = "Hmm... <Jorgen alza gli occhi verso di te socchiudendoli.>$B$BVa bene. Ti aiuto, ma non perché ne ho voglia: perché sono obbligato.$B$BE mettiamo in chiaro una cosa: già così ne sai molto più di quanto dovresti. Teniamolo per noi questo piccolo segreto, e non andare a spettegolare nelle taverne di quel che scopri. Intesi?",
  en_title = "The Missing Diplomat",
  en_obj = "Find Jorgen in Stormwind City.",
}
T[1242] = {
  title = "Il diplomatico scomparso",
  desc = "Porta questo biglietto a Elling Trias. Non dirgli nient'altro. Sii soltanto $Geducato:educata; e aspetta che risponda. E non preoccuparti, risponderà.$B$BTe lo ripeto un'ultima volta, $N: prendi questa faccenda sul serio, e tieni la bocca chiusa.$B$BTrias lo trovi alla sua bottega di formaggi, Trias' Cheese, nel Trade District. Buona fortuna.",
  obj = "Consegna Jorgen's Sealed Note a Elling Trias, a Stormwind City.",
  progress = "Salve, $N. C'è qualcosa che posso fare per te? Magari vuoi assaggiare un po' del nostro cheddar speciale di Trias? O un pezzo di bleu darnassiano?",
  reward = "Scusa, una lettera per me? Ma guarda... non capita spesso di ricevere una consegna che non sia una cassa o un barile, quando non fai altro che lavorare. Vediamo di che si tratta.$B$B<Elling alza gli occhi verso di te mentre apre la lettera.>$B$BSembri un po' $Gteso:tesa;, tutto bene, $N?",
  en_title = "The Missing Diplomat",
  en_obj = "Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.",
}
T[1243] = {
  title = "Il diplomatico scomparso",
  desc = "Jorgen, vecchio figlio di.... Ah, quindi la mettiamo così, eh?$B$BVa bene, posso conviverci. Spero che finisca nel Twisting Nether il prima possibile!$B$BEcco come andrà, $N. Io comincio a muovere i miei contatti qui, ma il grosso del lavoro sul campo lo fai tu, così risparmio qualche moneta.$B$BVa' a Darkshire, a Duskwood, e trova Watcher Backus: di solito pattuglia la strada a nord, appena fuori dal paese. Digli soltanto che stai indagando per me su eventuali attività dei Defias e ti darà tutte le informazioni che può.",
  obj = "Consegna la Sealed Note a Watcher Backus, a Duskwood.",
  progress = "Non è troppo sicuro andare in giro per i boschi, $N. Sta' $Gattento:attenta;, e se vedi qualcosa di sospetto o pericoloso avvisa subito i Watcher. Non provare ad affrontare niente da $Gsolo:sola;. Noi non siamo responsabili di quel che di terribile potrebbe capitarti.$B$BMa lo sappiamo tutti e due che mi ignorerai e combatterai comunque qualunque cosa sbuchi dal buio, vero? Ahah, già, voi avventurieri... tutti uguali.",
  reward = "Oh, ti manda Trias, eh? Allora è un'altra cosa.$B$BCombatti pure qualunque mostruosità ti venga addosso dal buio. Sono sicuro che te la caverai facilmente, se sei il tipo che bazzica con uno come lui.$B$BAllora, cosa vuole il mio amico da me in una giornata tetra come questa?",
  en_title = "The Missing Diplomat",
  en_obj = "Give the Sealed Note to Watcher Backus in Duskwood.",
}
T[1244] = {
  title = "Il diplomatico scomparso",
  desc = "Attività dei Defias? Be', un po' di attività c'è sempre; anche se se ne stanno per conto loro li consideriamo una minaccia.$B$BMa ora che ci penso, c'è stato un avvistamento recente che pareva strano. Sarà stato un paio di settimane fa: alcuni dei loro agenti si erano radunati intorno ad Addle's Stead. Dal rapporto, direi che è successo qualcosa di grosso.$B$BPerché non provi a controllare prima là e mi riporti quel che trovi?$B$BLa fattoria è a sud della strada che viene da Westfall, appena entri a Duskwood.",
  obj = "Trova il Defias Docket e portalo a Watcher Backus, a Duskwood.",
  progress = "Sta' $Gattento:attenta; là fuori, $N. So che è stato Trias a mandarti qui, ma questo non vuol dire che nei boschi non ci sia in agguato qualcosa capace di darti dei guai... soprattutto se stai indagando sui Defias.",
  reward = "Sei di ritorno $Gsano:sana; e $Gsalvo:salva;. Non si può chiedere molto di più, no?$B$BOra, vediamo cos'abbiamo qui. Sembra piuttosto ufficiale, per quel che ho visto dei documenti dei Defias. Ma potrebbe essere un falso, giusto per farti perdere le tracce di quel che stai cercando.",
  en_title = "The Missing Diplomat",
  en_obj = "Find the Defias Docket and return it to Watcher Backus in Duskwood.",
}
T[1245] = {
  title = "Il diplomatico scomparso",
  desc = "Uau, questo sembra troppo complesso per essere qualcosa messo lì solo per sviarti. Non dovrei nemmeno metterci gli occhi sopra. Portalo a Trias: lui saprà venirne a capo. E NON lasciare che nessuno ti metta i bastoni tra le ruote. Questa cosa è più grossa di me. Forse è più grossa anche di lui, ma vedremo.$B$BE fammi un favore, $N: non dire a nessuno che ti ho aiutato. Se i miei superiori scoprissero che sapevo di tutto questo e non gliel'ho detto, probabilmente mi impiccherebbero.",
  obj = "Porta il Defias Docket a Elling Trias, a Stormwind.",
  progress = "Vedo che sei di ritorno, e tutto $Gintero:intera;. Sappiamo tutti e due che non sei qui per il formaggio, quindi tagliamo corto con i convenevoli. Backus è stato d'aiuto, o non sei ancora $Gpartito:partita; per Duskwood?",
  reward = "Già... è una lettura interessante. Jorgen e DeLavey hanno fatto bene a coinvolgermi.$B$BPare che i Defias si siano dati parecchio da fare per portare a termine questo loro piano. Hmm... e questo cos'è? \"Fist\"? È un nome che mi dice qualcosa.",
  en_title = "The Missing Diplomat",
  en_obj = "Bring the Defias Docket to Elling Trias in Stormwind.",
}
T[1246] = {
  title = "Il diplomatico scomparso",
  desc = "Già, ora che ci penso... Dashel... Dashel qualcosa... Come si chiamava? FIST! Dashel Stonefist. In certi giri lo chiamano Fist, probabilmente perché gli piace fare a botte.$B$BDi solito lo trovi a Old Town, proprio nel bel mezzo. Va' a parlargli. Se serve, usa una spada o qualcosa di pesante e smussato per convincerlo ad aprirsi un po'. E non esitare. Se è dentro questa storia fino al collo come dicono queste carte, non ti darà nessuna informazione di sua spontanea volontà.",
  obj = "Parla con Dashel Stonefist, a Stormwind.",
  reward = "Cosa?!$B$BTu vieni nel mio vicolo a far domande sugli affari miei? Affari con cui evidentemente non c'entri niente.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Dashel Stonefist in Stormwind.",
}
T[1247] = {
  title = "Il diplomatico scomparso",
  desc = "Allora sì... ehm... qualcosa su quell'incontro ad Addle's Stead forse la so. È successo qualche settimana fa, mi pare. Io non c'entravo davvero niente. La mia parte era finita quando è fallito il piano A... maledetti avventurieri.$B$BIl tizio che abbiamo messo dentro per il piano B veniva da Menethil; uno che chiamano Slim. È tutto quel che so del loro piano di riserva.",
  obj = "Parla con Elling Trias, a Stormwind.",
  reward = "Bello vedere che sei ancora $Gvivo:viva;, $N. Quindi con Dashel è andata bene, eh?$B$BHo letto meglio questo loro piano e, anche se non dice il nome del diplomatico che volevano, parla di questo piano B che hanno messo in atto dopo aver fallito il primo tentativo di catturarlo.$B$BDi questo Slim che ha nominato Dashel qui non c'è scritto nessun altro nome, ma se dici che è a Menethil, è già un inizio.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Elling Trias in Stormwind.",
}
T[1248] = {
  title = "Il diplomatico scomparso",
  desc = "Un mio contatto si è ritirato nelle Wetlands, nella città portuale di Menethil. Dovrebbe essere disposto ad aiutarti sulla mia sola parola, se gli dici che lavori per me. Si chiama Mikhail. Prima di lasciare Stormwind, qualche anno fa, aveva accennato che voleva fare il barista.$B$BParlagli, trova questo Slim e scopri se c'è altro da sapere su questo diplomatico rapito. Dobbiamo scoprire dove l'hanno portato, o almeno chi è. Il Defias Docket non dice niente sui loro piani dopo la cattura.",
  obj = "Parla con Mikhail, nelle Wetlands.",
  reward = "$GBenvenuto:Benvenuta;, $Gbenvenuto:benvenuta;, $Gbenvenuto:benvenuta;, $N. Fai bene a unirti a noi. Magari una birra, oggi? O del montone?$B$BDi' pure cosa desideri e farò in modo che tu sia $Gservito:servita; a dovere. Mi chiamo Mikhail, e non vedo l'ora di servirti.$B$BHmm? Cosa? Trias? Abbassa la voce, $Gamico mio:amica mia;. Non è una cosa che debba sentire tutta la taverna.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Mikhail in the Wetlands.",
}
T[1249] = {
  title = "Il diplomatico scomparso",
  desc = "Dici che ti manda Elling? E allora l'ospitalità che ti ho offerto adesso vale dieci volte tanto. Qualunque cosa ti serva, basta chiedere. Farò del mio meglio per aiutarti.$B$BHmm, Slim, dici? Non sono sicuro che il nome mi dica qualcosa, ma terrò gli occhi aperti.$B$BNon guardare adesso, $N, ma il signore laggiù vicino all'uscita sta guardando da questa parte. Ascolta la nostra conversazione un po' troppo attentamente, se capisci cosa intendo. Se fossi in te, farei il possibile per bloccarlo prima che scappi verso la porta.",
  obj = "Blocca Tapoke Jahn prima che scappi, poi torna da Mikhail, a Menethil.",
  progress = "Ti è sgusciato via? Aveva un'aria losca, dal modo in cui ci guardava.",
  reward = "L'hai preso, eh? $GBravo:Brava;. Mi sorprende che fosse Slim.$B$BSarò sincero: non avrei mai pensato di sentire la mancanza dell'eccitazione di certe attività clandestine più losche. Immagino che il vizio sia duro a morire. Non dirlo a Elling: se sapesse che mi manca l'azione, probabilmente cercherebbe di farmi tornare a Stormwind.$B$BSono contento di esserti stato almeno un po' utile mentre eri a Menethil. Se ti serve altro, basta chiedere.",
  en_title = "The Missing Diplomat",
  en_obj = "Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.",
}
T[1250] = {
  title = "Il diplomatico scomparso",
  desc = "I Defias non mi pagavano abbastanza da morire per la loro causa. Hanno preso il re. Sì, il re di Stormwind, non un diplomatico qualunque. Stava andando a Theramore per incontrare Jaina Proudmore: a quanto pare era una cosa grossa, e un gran segreto. Ma non ci sono dentro solo i Defias. Stanno lavorando con qualcuno. Credo sapessero che la cosa era più grande di loro.$B$BLa mia parte era solo far salire il loro uomo sulla nave del re mentre era in porto. Il tizio si chiamava Hendel. È tutto quel che so. Lo giuro!",
  obj = "Parla con Mikhail, nelle Wetlands.",
  reward = "IL RE?! Cioè... il re? Il re vero? Stai scherzando? Non avevi detto che cercavi i rapitori del re. Non avevo nemmeno sentito che era scomparso... questo spiegherebbe in parte perché abbiano incoronato suo figlio.$B$BManderò subito parola a Elling. Vorrà sapere che sei sulle tracce.$B$BNon avrei mai immaginato che Jahn avrebbe venduto Stormwind per due monete schifose. Anche un ladro deve avere il suo onore su certe cose.$B$BOra il punto è trovare questo Hendel. E credo di poterti aiutare.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Mikhail in the Wetlands.",
}
T[1251] = {
  title = "Lo scudo nero",
  desc = "Uno scudo di ferro, annerito dall'incendio che ha devastato la locanda, è fissato al camino in rovina, una delle poche parti rimaste dell'edificio che un tempo era la Shady Rest Inn.$B$BLo scudo si può staccare dai mattoni del camino.",
  obj = "Porta il Blackened Iron Shield a Krog, a Brackenwall Village.",
  progress = "Che cos'è quello che hai lì, $N? Delle prove dai resti della Shady Rest Inn?",
  reward = "Ammetto che gli umani abbiano strani gusti nell'arredamento, ma userebbero davvero un semplice scudo di ferro per decorare il camino? Forse questo scudo l'hanno messo lì quelli che hanno bruciato la locanda.$B$BUn avvertimento? Una minaccia?",
  en_title = "The Black Shield",
  en_obj = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.",
}
T[1252] = {
  title = "Lieutenant Paval Reethe",
  desc = "Un luccichio a terra, sotto le macerie, attira il tuo sguardo. Togliendo i detriti e la cenere incrostati sull'oggetto, appare l'insegna di un'ancora d'oro su fondo bianco, smaltata sulla superficie: il simbolo di Theramore.$B$BSotto l'ancora è impresso in rilievo il nome \"Lieutenant Paval Reethe\".",
  obj = "Porta Reethe's Badge a Captain Garran Vimes, a Theramore.",
  progress = "Hai trovato qualcosa di interessante alla Shady Rest Inn?",
  reward = "Non è mai una buona notizia quando mi portano il distintivo di una guardia.$B$BA volte è un uomo o una donna caduti in battaglia, e tocca a me portare la notizia alla famiglia in lutto. Altre volte non scopriamo mai cosa gli sia successo. E altre volte è anche peggio.",
  en_title = "Lieutenant Paval Reethe",
  en_obj = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.",
}
T[1253] = {
  title = "Lo scudo nero",
  desc = "Uno scudo di ferro, annerito dall'incendio che ha devastato la locanda, è fissato al camino in rovina, una delle poche parti rimaste dell'edificio che un tempo era la Shady Rest Inn.$B$BLo scudo si può staccare dai mattoni del camino.",
  obj = "Porta il Blackened Iron Shield a Captain Garran Vimes, a Theramore.",
  progress = "Hai trovato prove sul luogo della Shady Rest Inn?",
  reward = "Hm, non sono un esperto nella costruzione di armi e armature. Nel loro uso sì, ma non nella loro fabbricazione.$B$BQuesto scudo sembra comunissimo, a parte i danni dell'incendio che ha avvolto la locanda.",
  en_title = "The Black Shield",
  en_obj = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.",
}
T[1258] = {
  title = "... e crostacei",
  desc = "Un altro ingrediente della mia nuova ricetta è la zampa con il guscio di un granchio gigante. E i granchi che hanno nel Dustwallow — li chiamano Muckshell — proprio non vanno bene! Temo che gli unici granchi adatti vivano lontano, nella Swamp of Sorrows.$B$BIl guscio della zampa è un elemento chiave nella presentazione del piatto, quindi mi servono zampe intatte, senza graffi. Un granchio adulto può averne solo una o due così, e a me ne servono molte per mettere a punto il piatto.$B$BAllora, $N... sei $Gdisposto:disposta; a viaggiare?",
  obj = "Porta 12 Pristine Crawler Leg a Morgan Stern, a Theramore.",
  progress = "Le mie ricerche sulle lingue di Mudrock procedono bene. La tua caccia ai granchi va bene, spero?",
  reward = "Sono esemplari magnifici, $N! I gusci sono in perfette condizioni, e la carne è rosa e tenera. Nelle tue vene scorre sangue da chef, ne sono sicuro!",
  en_title = "... and Bugs",
  en_obj = "Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore.",
}
T[1259] = {
  title = "Lieutenant Paval Reethe",
  desc = "Non riconosco il nome di Lieutenant Paval Reethe. La cosa migliore è chiedere ad Adjutant Tesoran. Tiene i registri di tutta la guardia di Theramore, dal personale all'equipaggiamento.$B$BCon una rapida occhiata ai suoi libri dovrebbe riuscire a dirti chi è questo Reethe.",
  obj = "Scopri di più su Reethe da Adjutant Tesoran, a Theramore.",
  reward = "Salve, $N. Vuoi informazioni su un membro in particolare della guardia di Theramore? Reethe, hai detto?$B$BDammi solo un momento per trovare il libro giusto.",
  en_title = "Lieutenant Paval Reethe",
  en_obj = "Find out more about Reethe from Adjutant Tesoran in Theramore.",
}
T[1260] = {
  title = "Morgan Stern",
  desc = "Sto preparando un nuovo menù per il ristorante. Sarà pieno di piatti rustici a tema \"bayou\". Credo che la mia clientela del Blue Recluse li adorerà!$B$BHo mandato mio nipote Morgan a Theramore, una città ai margini del Dustwallow Marsh. È lì a raccogliere ricette dalla gente del posto, e devo sapere che cosa ha trovato finora.$B$BIl viaggio fino a Theramore è lungo. Troppo lungo per me. Ma scommetto che $Gun giovane:una giovane; $C come te coglierebbe al volo l'occasione di viaggiare, vero?",
  obj = "Parla con Morgan Stern, a Theramore.",
  reward = "Oh, ti ha mandato mio zio, eh?$B$BBe', sto facendo ricerche sulle ricette e ho qualche pista, ma mi serve aiuto.$B$BL'aiuto di qualcuno che non abbia paura di bagnarsi i piedi.",
  en_title = "Morgan Stern",
  en_obj = "Speak with Morgan Stern in Theramore.",
}
T[1261] = {
  title = "Marg parla",
  desc = "Maledetto muckshell! Non puoi uccidere Marg! Ah, ma io sono morto. Quindi deve avermi ucciso...$B$BMa la mia missione! La mia missione! Tu, $N, devi portarla a termine.$B$BMentre ero vicino a Theramore, ho spiato un gruppo di soldati dell'Alleanza accampati sulla spiaggia. E un soldato portava un ciondolo... un ciondolo carico di più gemme di quante un soldato potrebbe mai permettersi!$B$BQuella notte mi sono intrufolato nel loro accampamento e ho rubato il ciondolo, ma sulla via del ritorno alla base un uomo-granchio muckshell mi ha ucciso!$B$B$N, devi trovare quel muckshell e recuperare il ciondolo!",
  obj = "Porta il Jeweled Pendant a Nazeer, a Brackenwall Village.",
  progress = "$N, hai scoperto la sorte di Marg?",
  reward = "Questo ciondolo lo portava un soldato di Stormwind??$B$BGrazie, $N. Hai svelato il segreto della morte di Marg. Ma questo ciondolo è un nuovo mistero da risolvere, un mistero che potrebbe avere conseguenze terribili per l'Alleanza, e per l'Orda.",
  en_title = "Marg Speaks",
  en_obj = "Bring the Jeweled Pendant to Nazeer in Brackenwall Village.",
}
T[1262] = {
  title = "Rapporto a Zor",
  desc = "È strano che il ciondolo rubato da Marg fosse nelle mani di semplici soldati. Forse il suo proprietario era travestito, o forse l'hanno rubato i soldati stessi!$B$BQualunque sia la verità, questo è il ciondolo di un nobile, e dobbiamo scoprire il suo vero proprietario se vogliamo svelarne il mistero.$B$BPorta il ciondolo a Zor Lonetree, a Orgrimmar. Conosce bene la politica dell'Alleanza, e saprà se questo ciondolo ha una storia tra i nobili di Stormwind.",
  obj = "Porta il Jeweled Pendant a Zor Lonetree, a Orgrimmar.",
  progress = "Hai viaggiato da Brackenwall Village, nel Dustwallow? Come sta Nazeer, e come procedono i suoi sforzi nella palude?",
  reward = "Questo ciondolo è stato lavorato con grande abilità e precisione, $N. Nessun orco desidererebbe un gioiello simile...$B$BMa molti umani sì.$B$BFarò studiare questo ciondolo. Speriamo che col tempo i suoi misteri ci vengano svelati.",
  en_title = "Report to Zor",
  en_obj = "Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.",
}
T[1264] = {
  title = "Il diplomatico scomparso",
  desc = "All'inizio di ogni mese i Kul Tiras Marine vengono pagati e di solito lasciano Theramore per andare da qualche altra parte. Molti vengono qui a correre dietro alle donne, a far baldoria e a divertirsi. Uno di quei gruppi ormai lo considero di casa qui alla taverna, e credo che questo Hendel sia dei loro.$B$BCommander Samaul, a Theramore, potrebbe aiutarti a trovarlo se Hendel è ancora di stanza là. È del tutto fedele a Proudmoore, ma se fai il nome di Elling dovrebbe darti una mano... con discrezione.",
  obj = "Trova Commander Samaul, nel Dustwallow Marsh.",
  reward = "Un piacere conoscerti, $N. Sono Commander Samaul. Comando io le forze di Miss Proudmoore qui a Theramore.$B$BAnche se sono molto occupato, se hai domande non farti problemi a parlare. Forse dovrò essere breve, ma non c'è motivo che io sia scortese se ti serve il mio aiuto.$B$BSe hai intenzione di viaggiare fuori città, ti consiglio di stare $Gattento:attenta;. Oltre a ogre, orchi e murloc, la parte meridionale della palude è piena di draghi neri.",
  en_title = "The Missing Diplomat",
  en_obj = "Find Commander Samaul in Dustwallow Marsh.",
}
T[1265] = {
  title = "Il diplomatico scomparso",
  desc = "Hendel? Sì, conosco quell'uomo. Ma perché ti servirebbe uno dei miei soldati?$B$BTi manda Elling a cercarlo? Hmm, la cosa non mi piace. Elling non ti avrebbe mandato prima da me se la tua faccenda non fosse seria. Capisco se non puoi dirmi di cosa si tratta, ma sappi una cosa: ho il dovere di proteggere queste terre. Se hai intenzione di creare disordini, allora ti consiglio di informarmi di quel che puoi.$B$BCredo che Hendel fosse di stanza alla prima torre fuori Theramore. Sta' $Gattento:attenta;.",
  obj = "Cerca a Sentry Point qualche traccia di Private Hendel.",
  progress = "Sì, $N?",
  reward = "L'uomo che cerchi, quello noto come Hendel, non è qui. Altre fonti hanno portato a Lady Proudmoore informazioni che credo tu già conosca. Mi ha chiesto di trovarti e di darti aiuto nella tua impresa. Se me lo permetti, ti dirò dove trovare Private Hendel, così potremo consegnarlo alla giustizia.",
  en_title = "The Missing Diplomat",
  en_obj = "Search Sentry Point for any sign of Private Hendel.",
}
T[1266] = {
  title = "Il diplomatico scomparso",
  desc = "Private Hendel è a ovest di qui. Al momento è di guardia e protegge alcuni degli infiltrati di Theramore mentre riposano. Tengono d'occhio la base dell'Orda, Brackenwall, e cercano qualunque altra cosa possa minacciare i nostri confini.$B$BNon dovresti avere problemi a trovarlo: cerca le tende lungo la strada.$B$BHo un'altra faccenda da sbrigare, ma ti raggiungerò presto. Se hai problemi, mi trovi sempre nella torre di Lady Proudmoore.",
  obj = "Trova Private Hendel, nel Dustwallow Marsh.",
  reward = "Salve, $Gcittadino:cittadina;. Questo è un posto pericoloso in cui andare in giro. Se tieni alla vita, non mi fermerei troppo a lungo.$B$BSe fai domande brevi, vedrò di aiutarti. Tieni solo gli occhi aperti per quei luridi ogre. Si dice che ci sia una base dell'Orda da qualche parte nelle paludi. Gli infiltrati fanno quel che possono per trovarla, ma il lavoro va a rilento e abbiamo fatto pochi progressi.",
  en_title = "The Missing Diplomat",
  en_obj = "Find Private Hendel in Dustwallow Marsh.",
}
T[1267] = {
  title = "Il diplomatico scomparso",
  obj = "Parla con Jaina Proudmore, nel Dustwallow Swamp.",
  reward = "Lascia che sia io la prima a ringraziarti per tutto quel che hai fatto, $N. Sei $Gstato:stata; una benedizione incredibile per la mia gente e per quella di Stormwind. Mi dispiace non aver potuto fare la tua conoscenza in circostanze migliori.$B$BCapisci anche che non posso ringraziarti apertamente per i tuoi sforzi, ma ti assicuro ancora una volta che sono apprezzati.$B$BQuando in futuro verrai a Theramore, cercami e cercherò di tenerti $Gaggiornato:aggiornata; sulla situazione.$B$BGrazie ancora, $N.",
  en_title = "The Missing Diplomat",
  en_obj = "Speak to Jaina Proudmore in Dustwallow Swamp.",
}
T[1268] = {
  title = "Impronte di zoccoli sospette",
  desc = "File di impronte di zoccoli si allontanano dallo scheletro ancora fumante della Shady Rest Inn. Ci sono almeno alcune impronte visibili, e altre file di orme quasi impercettibili nel fango molle della palude.",
  obj = "Riferisci a Krog, a Brackenwall Village, delle impronte sospette alla Shady Rest Inn.",
  reward = "Impronte di zoccoli... Potrebbero essere stati i quilboar, suppongo. O forse perfino i centauri. La loro presenza nelle Barrens non è trascurabile, e non mi sembrerebbe esagerato pensarli capaci di un gesto simile.$B$BTe l'ho detto? Non hanno soltanto bruciato la locanda... La donna e il cucciolo del proprietario sono stati uccisi. Brutta faccenda.$B$BComunque, manderò Kagoro a scoprire dove portano le tracce.",
  en_title = "Suspicious Hoofprints",
  en_obj = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.",
}
T[1269] = {
  title = "Lieutenant Paval Reethe",
  desc = "Un luccichio a terra, sotto le macerie, attira il tuo sguardo. Togliendo i detriti e la cenere incrostati sull'oggetto, appare l'insegna di un'ancora d'oro su fondo bianco, smaltata sulla superficie: il simbolo di Theramore.$B$BSotto l'ancora è impresso in rilievo il nome \"Lieutenant Paval Reethe\".",
  obj = "Porta Reethe's Badge a Krog, a Brackenwall Village.",
  progress = "Hai trovato qualche pista su cosa è successo alla Shady Rest Inn?",
  reward = "Conosco questo umano, Paval Reethe. Patetico, perfino per quelli della sua razza. Ha abbandonato i suoi commilitoni e ora si nasconde nei boschi.$B$BHo mandato Ogron a cercarlo. Alcuni degli altri sospettano che abbia rubato dalle nostre provviste. Mi pare di aver visto Ogron dirigersi a sud-est.",
  en_title = "Lieutenant Paval Reethe",
  en_obj = "Bring Reethe's Badge to Krog in Brackenwall Village.",
}
T[1270] = {
  title = "La fuga di Stinky",
  desc = "Grande, finalmente qualcosa che non vuole mangiarmi!!$B$BMi serve aiuto per tenere a bada le bestiacce di qui, e tu fai al caso mio, $Gamico:signora;.$B$BUn goblin di Ratchet che si chiama Mebok Mizzyrix ha bisogno di foglie di bogbean per una pozione, o roba simile... Sinceramente non m'importa il perché: pagava bene e io questa palude la conosco, quindi eccomi qui.$B$BPeccato che mi sia fatto circondare prima di trovare il bogbean! Puoi aiutarmi a uscire di qui e guardarmi le spalle mentre cerco la pianta di Mebok?",
  obj = "Scorta \"Stinky\" Ignatz, poi parla con Mebok Mizzyrix, a Ratchet.",
  reward = "Stinky è passato di qui con le erbe che gli avevo chiesto, e mi ha detto che l'hai tirato fuori dai guai. Ottimo lavoro! Chi è amico di Stinky è amico mio!$B$BMi ha chiesto di darti questo se mai ti avessi visto, poco prima di tornarsene a sud, verso la palude.",
  en_title = "Stinky's Escape",
  en_obj = "Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.",
}
T[1271] = {
  title = "Banchetto al Blue Recluse",
  reward = "Mio nipote mi ha detto che l'hai aiutato nelle sue ricerche nel Dustwallow e che hai tirato fuori dai guai il suo socio. Beh, noi Stern restiamo uniti e non ci dimentichiamo dei nostri amici!$B$BQuindi lavati le mani, $N, perché stiamo per dare una festa in tuo onore!",
  en_title = "Feast at the Blue Recluse",
}
T[1273] = {
  title = "Interrogare Reethe",
  desc = "Ci è voluto tanto, ma ho trovato Reethe. Si è nascosto bene, per essere un umano.$B$BOgron teme che sia diventato pazzo dopo tanto tempo nella palude. Vieni con me, così andiamo a farci dare delle risposte.",
  obj = "Vai con Ogron a parlare con Reethe, poi torna da Krog, a Brackenwall Village.",
  progress = "Hai trovato Reethe?",
  reward = "Hmph. È un bene che Reethe non si aggiri più per la palude, ma è un peccato che gli umani siano fatti così fragili che lui non sia riuscito a riprendersi da una piccola ferita di freccia.$B$BSembra che questa pista del mistero non abbia portato da nessuna parte, e dobbiamo cercare altrove.",
  en_title = "Questioning Reethe",
  en_obj = "Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.",
}
T[1274] = {
  title = "Il diplomatico scomparso",
  desc = "Scusami, $Gsignore:signora;. Bishop DeLavey mi ha chiesto di rivolgermi agli avventurieri che potrebbero aiutarlo in una faccenda delicata.$B$BSe puoi andare a Stormwind Keep senza dare nell'occhio e parlargli appena ti è possibile, sono sicuro che apprezzerà il tuo aiuto. Ancora una volta, ti prego, sii $Gdiscreto:discreta;. È una faccenda di una certa importanza.",
  obj = "Trova Bishop DeLavey, a Stormwind Keep.",
  reward = "Salve, $N. Io sono Bishop DeLavey.$B$BSe mi chiedi dei miei affari qui nella fortezza, di sicuro il giovane Thomas è riuscito a reclutarti per aiutare il nostro regno. È sempre stato bravo a seguire le mie richieste.$B$BTemo di non avere tempo per dilungarmi, quindi lascia che sia schietto... e ti prego, cerca di non farne cosa di dominio pubblico.",
  en_title = "The Missing Diplomat",
  en_obj = "Find Bishop DeLavey in Stormwind Keep.",
}
T[1275] = {
  title = "Studiare la corruzione",
  desc = "Gli sciocchi elfi del sangue si trastullano con la magia demoniaca. Non hanno visto cosa è successo ai naga e ai satiri di Kalimdor?$B$BTemo che gli elfi del sangue vadano incontro a una deformazione simile. Azeroth non può permettersi di dare alla luce un'altra razza immonda di mostri.$B$BDesidero studiare i tronchi encefalici dei satiri e dei naga, per dedurre verso quale destino siano diretti gli elfi. Nelle Blackfathom Deeps, sulla costa di Ashenvale, troverai sia satiri sia naga.$B$BÈ un lungo viaggio, $N.",
  obj = "Gershala Nightwhisper, ad Auberdine, vuole 8 Corrupt Brain Stem.",
  progress = "Una volta che avrò abbastanza campioni da studiare, potrà cominciare il mio vero lavoro. Con i tronchi encefalici corrotti dei satiri e dei naga delle Blackfathom Deeps posso provare a stabilire una correlazione tra le mutazioni.$B$BForse, con quella conoscenza, potremo impedire agli elfi del sangue di sprofondare ancora di più nella deformità e nel male.",
  reward = "Hai viaggiato a lungo e senza dubbio hai affrontato grandi pericoli.$B$BLe tue azioni sono state altruiste. È per il bene di tutta Azeroth che mi aiuti nella mia ricerca. Ti ringrazio, $N, per tutto quello che hai fatto.$B$BOra, se vuoi scusarmi, ho molto lavoro da fare...",
  en_title = "Researching the Corruption",
  en_obj = "Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.",
}
T[1276] = {
  title = "Lo scudo nero",
  desc = "Ah, ora ricordo! Mosarn è un fabbro molto stimato di Thunder Bluff. Sapevo di aver già sentito il suo nome da qualche parte.$B$BPer ringraziarmi, il Circolo della Terra mi ha donato un'armatura forgiata da Mosarn. Ottimo lavoro.$B$BForse può dirti di più sullo scudo che ha forgiato.$B$BNon è una gran pista, ma visto che da Reethe non abbiamo ricavato niente di utile, è tutto quello che abbiamo.",
  obj = "Mostra il Blackened Iron Shield a Mosarn, a Thunder Bluff.",
  progress = "Salve, $C. Posso aiutarti in qualcosa?",
  reward = "Sì, hai senz'altro ragione. Questo è uno scudo fatto da me.$B$BTemo però di non poterti dire molto altro, $N. Forgio così tanti scudi e armature diversi che non riesco a ricordarmeli tutti.",
  en_title = "The Black Shield",
  en_obj = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.",
}
T[1282] = {
  title = "Lo chiamano Smiling Jim",
  desc = "Non posso farci niente se mi dispiace per il vecchio Jim, laggiù. Non è sempre stato così. Per un po' ha gestito una locanda là fuori nella palude, un posto meraviglioso.$B$BSenti, non ho proprio voglia di parlarne. Chiedi a Captain Vimes, se proprio devi.",
  obj = "Parla con Captain Garran Vimes, a Theramore.",
  reward = "Il suo vero nome è James Hyal. Ha aperto una locanda al limitare delle Barrens. Voleva creare un bel posto dove i viaggiatori potessero fermarsi...$B$BForse puntava troppo in alto, ma per un po' la locanda è andata bene. Poi abbiamo perso il controllo delle strade nella palude, e gli ogre hanno preso il sopravvento.$B$BJames era troppo testardo per rinunciare al suo sogno in cambio della sicurezza dentro le nostre mura, e la Shady Rest Inn è stata rasa al suolo dalle fiamme. Stiamo indagando, ma finora con poca fortuna. Se vuoi dare una mano, guarda cosa riesci a trovare tra le macerie.",
  en_title = "They Call Him Smiling Jim",
  en_obj = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.",
}
T[1284] = {
  title = "Impronte di zoccoli sospette",
  desc = "File di impronte di zoccoli si allontanano dallo scheletro ancora fumante della Shady Rest Inn. Ci sono almeno alcune impronte visibili, e altre file di orme quasi impercettibili nel fango molle della palude.",
  obj = "Riferisci a Captain Garran Vimes, a Theramore, delle impronte sospette alla Shady Rest Inn.",
  reward = "Impronte di zoccoli, eh? È vero che nelle terre vicino al Dustwallow Marsh c'è un'attività straordinaria di centauri. In brevi incursioni nelle Barrens abbiamo trovato i loro accampamenti e i loro possedimenti sparsi per la zona.$B$BManderò Falgran Hastil, uno dei nostri esploratori, a vedere se riesce a scoprire dove portano le tracce.",
  en_title = "Suspicious Hoofprints",
  en_obj = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.",
}
T[1285] = {
  title = "Gli uomini di Daelin",
  desc = "Reddon... Redpath... Ah, eccolo! Lieutenant Paval Reethe.$B$BSi è unito alla guardia di Theramore insieme alla maggior parte delle reclute che hanno attraversato il mare con Lady Proudmoore. Arruolato nella fanteria di marina di Kul Tiras all'età di sedici anni. Servizio distinto, promozioni...$B$BRisulta disperso.",
  obj = "Riporta a Captain Garran Vimes, a Theramore, le informazioni su Reethe.",
  reward = "Disperso? È il modo gentile di Tesoran per dire traditore.$B$BSenza dubbio è uno di quegli stolti così ciecamente fedeli ad Admiral Daelin da diventare un traditore. Non è un'ironia deliziosa? I disertori accusano noi di tradire l'Alleanza.",
  en_title = "Daelin's Men",
  en_obj = "Return the information about Reethe to Captain Garran Vimes in Theramore.",
}
T[1286] = {
  title = "I disertori",
  desc = "È stata una lotta mantenere una presenza nella palude, ma grazie alla forza della nostra determinazione siamo riusciti a mantenere diverse torri di guardia difensive in tutta la zona.$B$BLe ultime informazioni e i rapporti degli esploratori che ho ricevuto indicano che un gruppo di disertori si è stabilito abusivamente nella nostra torre abbandonata a Lost Point, a sud-est della locanda.$B$BIl capo dei disertori è un uomo di nome Jacken. Vedi se riesci a cavargli qualche informazione.$B$BTi avverto, $N. Potrebbe essere un osso duro.",
  obj = "Ottieni informazioni su Reethe da Balos Jacken e dai disertori, nel Dustwallow Marsh.",
  reward = "Ti ha mandato Vimes? Non poteva fare il lavoro sporco da solo, eh...",
  en_title = "The Deserters",
  en_obj = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.",
}
T[1287] = {
  title = "I disertori",
  desc = "Reethe? Quel codardo?$B$BL'abbiamo cacciato dal campo perché insisteva a razziare le provviste degli ogre su a Brackenwall Village. Non siamo abbastanza numerosi da poter tener testa a quei bruti senza cervello.$B$BHa passato il limite una volta di troppo, così l'abbiamo lasciato a cavarsela da solo.$B$BOra, io ti ho aiutato... Allora perché non aiuti noi e ti dimentichi di averci incontrati?",
  obj = "Parla con Captain Garran Vimes, a Theramore, di Reethe.",
  reward = "Manderò Lieutenant Caldwell a occuparsi dei disertori a Lost Point. Inoltre gli darò ordine di trovare Reethe. La palude non è così grande e senza sentieri da impedirgli di trovarlo.",
  en_title = "The Deserters",
  en_obj = "Speak with Captain Garran Vimes in Theramore about Reethe.",
}
T[1288] = {
  title = "Vimes's Report",
  desc = "Hai fatto un buon lavoro, $N, il migliore che abbia mai visto da parte di $Gun dilettante:una dilettante;.$B$BLady Proudmoore mi ha chiesto di tenerla informata su questa situazione delicata, e ormai è da un po' che non le parlo.$B$BAvevo intenzione di consegnarle il mio rapporto più tardi, ma mi sembra più giusto che sia tu a parlargliene. Probabilmente puoi rispondere alle sue domande meglio di me.",
  obj = "Porta Vimes's Report a Lady Jaina Proudmoore, a Theramore.",
}
T[1289] = {
  title = "Vimes's Report",
  desc = "Bene, a giudicare dal rapporto di Captain Vimes, hai dato un enorme aiuto alla sua indagine, e per questo ti ringrazio.$B$BHo la mente più in pace sapendo che la faccenda è in mani così capaci. Se vuoi, ti chiederei di tornare da Captain Vimes e di aiutarlo ad andare fino in fondo a questo mistero.",
  obj = "Torna da Captain Garran Vimes, a Theramore.",
}
T[1301] = {
  title = "James Hyal",
  desc = "Prima di lavorare qui al Blue Recluse, sono stato istruito da uno dei migliori cuochi e locandieri che abbia mai conosciuto. Si chiamava James Hyal. Tutto quel che ho e tutto quel che ho raggiunto nella vita lo devo a lui.$B$BMi chiedo come se la passi. Lui e suo fratello Vincent sono andati a lavorare in una taverna a Menethil Harbor, ma da un po' non ho sue notizie.$B$BSe mai dovessi andare da quelle parti, magari potresti salutarlo da parte mia?",
  obj = "Parla con Vincent Hyal, a Menethil Harbor.",
  reward = "James? Oh, se n'è andato parecchio tempo fa.$B$BGli è tornata la voglia di patria, immagino. Non è difficile capire perché. Con tutta la follia che c'è in Lordaeron, molti si sono uniti a Jaina Proudmoore quando ha attraversato il mare.",
  en_title = "James Hyal",
  en_obj = "Speak with Vincent Hyal in Menethil Harbor.",
}
T[1302] = {
  title = "James Hyal",
  desc = "Mio fratello James è partito con Lady Proudmoore oltre il mare. L'ultima volta che ne ho avuto notizia, i combattimenti laggiù si erano calmati e James stava aprendo una locanda da qualche parte sul continente. Ovunque sia, sono sicuro che gli affari gli vanno bene. Era un gran cuoco.$B$BNon ho sue notizie da un pezzo ormai (troppo preso dalla locanda, scommetto), ma l'impiegato di Theramore potrebbe indicarti dove trovarlo.",
  obj = "Parla con Clerk Lendry, a Theramore.",
  reward = "James Hyal, James Hyal... Perché quel nome mi suona così familiare?$B$BMa certo! L'incidente della Shady Rest Inn. Se hai qualche informazione su quello che è successo laggiù, ti consiglio vivamente di parlarne con Captain Vimes. È lui che segue le indagini.",
  en_title = "James Hyal",
  en_obj = "Speak with Clerk Lendry at Foothold Citadel in Theramore.",
}
T[1319] = {
  title = "Lo scudo nero",
  desc = "Mi dispiace non poterti essere di grande aiuto, $N, ma posso indirizzarti da qualcuno che lo sarebbe. Caz Twosprocket, uno dei nostri migliori fabbri, lavora alla forgia della bottega del fabbro.$B$BPortagli lo scudo e senti cosa sa dirti.",
  obj = "Mostra il Blackened Iron Shield a Caz Twosprocket, a Theramore.",
  progress = "Qualcosa da farmi vedere?",
  reward = "Hm... interessante pezzo di ferro, quello che hai qui. Di sicuro non l'ha fatto nessuno dei fabbri che conosco da questa parte del mare, e di certo non è opera mia.",
  en_title = "The Black Shield",
  en_obj = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.",
}
T[1320] = {
  title = "Lo scudo nero",
  desc = "Ah, per poco non mi sfuggiva... La cinghia di cuoio sul retro dev'essere bruciata, ma sembra fatta per una persona grossa. Direi un tauren, a dire il vero.$B$BÈ più o meno tutto quello che posso dirti. Di' a Captain Vimes che mi dispiace di non aver potuto aiutare di più.",
  obj = "Parla con Captain Garran Vimes, a Theramore.",
  reward = "Non sono molte informazioni su cui lavorare, ma dovremo tenerne conto. Speriamo che altri pezzi di questo mistero vadano al loro posto e ci diano un quadro più utile di quello che è successo.",
  en_title = "The Black Shield",
  en_obj = "Speak with Captain Garran Vimes in Theramore.",
}
T[1321] = {
  title = "Lo scudo nero",
  desc = "Hmm... non vedo niente di strano in questo scudo. Dovremmo farlo vedere a Do'gol, il fabbro, e sentire se può dirci qualcosa di più, ma non ci spererei troppo...",
  obj = "Mostra il Blackened Iron Shield a Do'gol, a Brackenwall Village.",
  progress = "Qualcosa per me, $C?",
  reward = "Questo è un buono scudo. Molto forte, pesante, buono. Ma a Do'gol non serve. Io gli scudi li faccio, non li compro, $N.$B$BDovresti saperlo.",
  en_title = "The Black Shield",
  en_obj = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.",
}
T[1322] = {
  title = "Lo scudo nero",
  desc = "Hmmm, c'è una scritta proprio qui sul bordo dello scudo, ma è difficile da leggere con tutta questa roba bruciata.$B$BMi serve dell'acido per renderla chiara. Il veleno dei Darkfang Spider della palude andrebbe bene. Portami un po' delle loro sacche e posso ripulirlo.",
  obj = "Procura 6 Acidic Venom Sac per Do'gol, a Brackenwall Village.",
  progress = "Hai preso quelle sacche dai ragni?",
  reward = "Non mi piacciono i ragni così grossi che non posso sedermici sopra e schiacciarli.$B$BGrazie di averle prese, $N. Ora le squarcio e le verso sullo scudo...",
  en_title = "The Black Shield",
  en_obj = "Acquire 5 Acidic Venom Sacs for Do'gol in Brackenwall Village.",
}
T[1323] = {
  title = "Lo scudo nero",
  desc = "Oh, credo di aver versato troppo acido sullo scudo. Fammi solo strofinare un po'...$B$BHm, si legge a fatica, ma sembra il nome Mosarn. Mai sentito nominare. Forse Krog lo sa. Krog conosce tanta gente.",
  obj = "Parla con Krog, a Brackenwall Village.",
  reward = "Mosarn? Mi dice qualcosa... ma non riesco a ricordare cosa. Forse mi verrà in mente più tardi.$B$BProbabilmente non è importante. Uno scudo può venire da qualsiasi parte e non significare niente...",
  en_title = "The Black Shield",
  en_obj = "Talk with Krog in Brackenwall Village.",
}
T[1324] = {
  title = "Il diplomatico scomparso",
  desc = "Cosa?! Vieni qui ad accusarmi di essermi alleato con i Defias, e pensi che me ne starò qui fermo mentre mi insulti?! Qualcosa mi dice che te la sei cercata da un pezzo.",
  obj = "Sconfiggi Private Hendel, nel Dustwallow Marsh.",
  progress = "Ciao di nuovo, $N. Spero non ti dispiaccia l'aiuto, ma non potevamo permetterci che Hendel scappasse o, peggio, che ci restasse secco.",
  reward = "Ti assicuro che siamo tutti parecchio scossi da quel che sta succedendo, ma lascia che lo riportiamo a Theramore per qualche domanda, e vedremo di trovare il Re.$B$BSono sicuro che la mia signora Proudmore vorrà ringraziarti per l'aiuto. Parlale quando hai un momento.",
  en_title = "The Missing Diplomat",
  en_obj = "Defeat Private Hendel in Dustwallow Marsh.",
}
T[1338] = {
  title = "L'ordine di Stormpike",
  desc = "C'è un armaiolo nano di cui ammiro moltissimo il lavoro. Si chiama Furen Longbeard, e la sua abilità non ha pari. Mi serve uno scudo nuovo, e deve essere uno dei suoi!$B$BIl problema è che... Furen è molto a sud, nel quartiere dei nani dentro Stormwind. Nelle terre degli umani! Non riesco a immaginare perché viva lì, così lontano da Ironforge. Gli umani devono pagarlo una fortuna per tenerlo là!$B$BAllora, se ti va di viaggiare e non ti dispiace guadagnare qualcosa, porteresti a Furen la mia richiesta per uno scudo?",
  obj = "Porta la Stormpike's Request a Furen Longbeard a Stormwind.",
  progress = "Una lettera dalle terre dei nani? Chissà chi mi scrive da così lontano, a nord...$B$BTi prego, fammi vedere l'ordine.",
  reward = "Ah, una richiesta da uno degli Stormpike. È un clan fiero, pieno di nani di qualità. E anche ricchi.$B$BGrazie, $N. Mi metterò al lavoro sullo scudo di Mountaineer Stormpike entro la fine della giornata.",
  en_title = "Stormpike's Order",
  en_obj = "Bring Stormpike's Request to Furen Longbeard in Stormwind.",
}
T[1339] = {
  title = "L'incarico di Mountaineer Stormpike",
  desc = "Ho sentito che Mountaineer Stormpike cerca un corriere. Qualcuno che faccia un po' di strada per lui. Che ne dici? Sei tu $Gil:la; $R giust$Go:a; per il lavoro?$B$BSe sì, troverai Stormpike in cima alla torre di guardia settentrionale.",
  obj = "Parla con Mountaineer Stormpike.",
  reward = "Esatto. Ho un incarico che non posso svolgere mentre sono di guardia. Anzi, ti porterà lontano da Loch Modan.$B$BL'occasione perfetta per un'avventura!",
  en_title = "Mountaineer Stormpike's Task",
  en_obj = "Speak with Mountaineer Stormpike.",
}
T[1358] = {
  title = "Campione per Helbrim",
  desc = "Un collega a Kalimdor, Apothecary Helbrim, sta studiando gli effetti delle tossine di Lordaeron sulle bestie di Kalimdor. Sarebbe molto interessato a un campione dei cuori di lupo che Renferrel mi ha mandato.$B$BHelbrim è di stanza nei Barrens, in un villaggio chiamato Crossroads. Per raggiungerlo devi viaggiare in dirigibile fino alla capitale degli orchi, Orgrimmar, poi proseguire a piedi verso sud, a Durotar. Vai a ovest nei Barrens e raggiungerai presto il Crossroads.",
  obj = "Porta il Wolf Heart Sample ad Apothecary Helbrim nei Barrens.",
  progress = "Hai un pacco per me?",
  reward = "Ah, molto bene. Se i rapporti iniziali sono veri, la tossicità di questi cuori potrebbe portare a ulteriori progressi nella nostra conoscenza dei veleni.$B$BÈ una consegna gradita, $N. La tua ricompensa è meritata.",
  en_title = "Sample for Helbrim",
  en_obj = "Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens.",
}
T[1359] = {
  title = "La consegna per Zinge",
  desc = "I cuori di lupo che hai procurato hanno una qualità mai vista in esemplari simili. Hanno una tossicità che dovrebbe essere letale per gli stessi lupi nei quali quei cuori battono!$B$BÈ davvero incredibile, e dobbiamo studiarlo ulteriormente. Ho tenuto qualche campione dei cuori ottenuti. Portali alla mia collega, Apothecary Zinge. La troverai nel nostro quartier generale a Undercity.",
  obj = "Porta i Wolf Heart Samples ad Apothecary Zinge a Undercity.",
  progress = "Hai qualcosa per me?",
  reward = "Ah sì, i campioni di cuore di cui parlava Renferrel. Sono ansiosa di sperimentare con questi... alla Royal Apothecary Society interessa sempre quando si scoprono nuove forme di tossine.",
  en_title = "Zinge's Delivery",
  en_obj = "Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity.",
}
T[1360] = {
  title = "Tesori recuperati",
  desc = "Avevo un bel lavoro come scavatore al sito di scavo di Uldaman, nelle Badlands... finché non sono arrivati quei maledetti trogg. Sono scampato per un pelo con la pelle a malapena intera, e nient'altro. Nel caos ho lasciato il mio bene più prezioso. È al sicuro dai trogg nel mio forziere, certo, ma proprio in mezzo a loro.$B$BTi sarei debitore, sia in onore sia in monete, se potessi andarlo a prendere per me! In fondo alla North Common Hall c'è un forziere con il mio nome sopra. È quello che devi aprire.",
  obj = "Prendi il bene più prezioso di Krom Stoutarm dal suo forziere nella North Common Hall di Uldaman, e portalo a Krom, a Ironforge.",
  progress = "Allora, sei $Griuscito:riuscita; a tenere a bada quei trogg abbastanza a lungo da aprire il mio forziere e prendere il mio tesoro?",
  reward = "Ah, mi sento di nuovo completo: grazie di cuore.$B$BAlcuni nani apprezzano la lucentezza del metallo, e altri lo scintillio delle gemme... ma uno Stoutarm senza il suo prezioso boccale in mano non è quasi più uno Stoutarm!",
  en_title = "Reclaimed Treasures",
  en_obj = "Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.",
}
T[1361] = {
  title = "Regthar Deathgate",
  desc = "Un guerriero dell'Orda, Regthar Deathgate, sta reclutando agenti per una missione nella terra di Desolace. Parla con lui se vuoi offrirti come $Gvolontario:volontaria;. È di stanza nelle Barrens, in una serie di bunker a ovest del Crossroads.$B$BE affila le armi. Desolace è un luogo dilaniato dalla guerra.",
  obj = "Parla con Regthar Deathgate.",
  reward = "Sì, sto reclutando. Questa missione porta a Desolace, contro i centauri che ci vivono. Sarò breve, così potrai cominciare subito.",
  en_title = "Regthar Deathgate",
  en_obj = "Speak with Regthar Deathgate.",
}
T[1362] = {
  title = "I Kolkar di Desolace",
  desc = "I centauri Kolkar vivono a Desolace, e le loro forze si sono estese fino alle Barrens. È un fatto noto, e qui abbiamo agenti dell'Orda che se ne occupano.$B$BMa finché i centauri saranno forti a Desolace, saranno sempre una minaccia. È ora di liberarci di quella minaccia.$B$BParla con Felgur Twocuts al Ghost Walker Post, a Desolace. È stato mandato a raccogliere informazioni sui centauri. Saprà come affrontare al meglio i Kolkar di Desolace.",
  obj = "Parla con Felgur Twocuts al Ghost Walker Post, a Desolace.",
  reward = "Sei qui per ordine di Regthar? Allora sei qui per occuparti dei centauri. Bene.$B$BSpero che tu sia $Griposato:riposata;. Non so come finirà la nostra campagna contro i centauri, ma so che la lotta sarà lunga.$B$BSiediti e ascolta.",
  en_title = "The Kolkar of Desolace",
  en_obj = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.",
}
T[1363] = {
  title = "L'incarico di Mazen",
  desc = "In quanto custode delle opere di questa biblioteca dell'Academy of Arcane Arts and Sciences, è mia responsabilità assicurarmi che tutti i tomi e le pergamene magiche siano sempre al loro posto. Chissà quali follie succederebbero se alcuni di questi testi incantati finissero nelle mani sbagliate?$B$BIl che mi ricorda... il mio assistente, Dellis, la settimana scorsa ha fatto un errore terribile. In biblioteca se la cava bene, ma quando esce dalle porte di Stormwind è un incapace. Fa' $Gl'eroe:l'eroina;, e aiuta il vecchio Dellis, vuoi?",
  obj = "Parla con Acolyte Dellis, a Stormwind.",
  reward = "Non è stata colpa mia. Davvero, non è stata colpa mia.",
  en_title = "Mazen's Behest",
  en_obj = "Speak with Acolyte Dellis in Stormwind.",
}
T[1364] = {
  title = "L'incarico di Mazen",
  desc = "Le istruzioni del maestro Mazen erano chiarissime: consegnare un saggio importantissimo a Watcher Mahar Ba, a Nethergarde Keep.$B$BMa io non ero mai stato nelle Blasted Lands! Il viaggio è stato spaventoso!$B$BQuando sono arrivato nella Swamp of Sorrows, ho sbagliato strada e mi sono ritrovato circondato da orribili creature della palude simili a piante. Barcollavano verso di me come per attaccarmi, e così sono scappato. Ma nella fretta ho perso il saggio. Una di quelle bestie l'ha preso, ne sono sicuro.$B$BPotresti provare a recuperarlo e consegnarlo a Mahar Ba?",
  obj = "Recupera Khadgar's Essays on Dimensional Convergence e consegnali a Watcher Mahar Ba, a Nethergarde Keep.",
  progress = "Che cosa ti porta a Nethergarde Keep, $R?",
  reward = "Ah, splendido!$B$BPer un po' ho temuto che la mia richiesta di Khadgar's Essays on Dimensional Convergence fosse stata trascurata dal maestro Mazen dell'Academy of Arcane Arts and Sciences.$B$BDev'essere sommerso di richieste, visti i tanti strani avvenimenti in corso.$B$BOra, se vuoi scusarmi, devo cominciare subito le mie ricerche. Poter finalmente intravedere il pensiero di qualcuno grande come Khadgar mi entusiasma senza fine.",
  en_title = "Mazen's Behest",
  en_obj = "Retrieve Khadgar's Essays on Dimensional Convergence and deliver them to Watcher Mahar Ba in Nethergarde Keep.",
}
T[1365] = {
  title = "Khan Dez'hepah",
  desc = "I Kolkar non sono gli unici centauri di Desolace. Molti clan vagano per queste pianure aride, combattendo e morendo l'uno contro l'altro. Ed è un bene che combattano tra loro, perché sono forti e brutali. Se i centauri si unissero contro di noi, sarebbero un nemico feroce.$B$BDobbiamo occuparci di loro prima che si uniscano.$B$BIl tuo primo compito è gettare nel caos il clan Kolkar. Fallo uccidendo il suo capo, Khan Dez'hepah.$B$BIl Kolkar Village è a nord-est di qui. Va', e che la fortuna ti accompagni.",
  obj = "Porta Khan Dez'hepah's Head a Felgur Twocuts, a Desolace.",
  progress = "$N, hai sconfitto Khan Dez'hepah?",
  reward = "Ben fatto. Questa rapida azione contro i Kolkar è un'efficace dimostrazione di forza, e la forza è ciò che i centauri capiscono meglio.$B$BLa morte del capo dei Kolkar non solo getterà nel caos quel clan, ma farà riflettere anche gli altri.",
  en_title = "Khan Dez'hepah",
  en_obj = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.",
}
T[1366] = {
  title = "Taglia sui centauri",
  desc = "Ora che hai spaventato i clan dei centauri, è il momento di dissanguarli. Quando viaggi per Desolace, dai la caccia ai centauri. Non m'importa a quale clan. Raccogli orecchie e basta. Un mucchio di orecchie.$B$BRiducendo il loro numero indebolirai la loro determinazione e soffocherai ogni pensiero di espansione.$B$BBuona caccia, $N.",
  obj = "Porta 15 Centaur Ear a Felgur Twocuts, a Desolace.",
  progress = "Come va la tua collezione di orecchie, $N? È grande?",
  reward = "Ormai i centauri devono conoscere il tuo nome. Sono sicuro che lo conoscono, lo rispettano e lo temono. E così come conoscono te, conoscono lo stendardo sotto cui cavalchi.$B$BLo stendardo dell'Orda.",
  en_title = "Centaur Bounty",
  en_obj = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.",
}
T[1367] = {
  title = "Alleanza con i Magram",
  desc = "Per battere i centauri dobbiamo usare il loro odio contro di loro. Ci alleeremo con uno dei clan e, attraverso di loro, impareremo a sconfiggere tutti i clan.$B$BSe scegli di allearti con i Magram, uccidi i loro nemici, i Gelkis. Così ti guadagnerai il rispetto dei Magram. Quando ne avrai abbastanza, incontra il portavoce dei Magram, Warug, ai margini del Magram Village, nel sud-est di Desolace.",
  obj = "Raggiungi la reputazione Friendly con i Magram, poi parla con Warug.",
  progress = "Vattene! I Magram non parlano con i deboli. Noi li uccidiamo!$B$BSe vuoi parlare con me, dimostrami che sei forte. Torna dopo aver ucciso molti Gelkis.",
  reward = "I Gelkis piangono quando sentono il tuo nome, $N. Ti temono e ti odiano. Ti odiano come odiano i Magram!$B$BForse sei forte come i Magram. Vedremo...",
  en_title = "Magram Alliance",
  en_obj = "Gain a Friendly reputation with the Magram, then speak with Warug.",
}
T[1368] = {
  title = "Alleanza con i Gelkis",
  desc = "Per battere i centauri dobbiamo usare il loro odio contro di loro. Ci alleeremo con uno dei clan e, attraverso di loro, impareremo a sconfiggere tutti i clan.$B$BSe scegli di allearti con i Gelkis, uccidi i loro rivali più odiati, i Magram. Dopo aver ottenuto il rispetto dei Gelkis, incontra la sciamana dei Gelkis, Uthek the Wise, ai margini del Gelkis Village, nel sud-ovest di Desolace.",
  obj = "Raggiungi la reputazione Friendly con i Gelkis, poi parla con Uthek the Wise.",
  progress = "I tuoi due piedi calpestano la terra dei Gelkis. Qui non sei $Gbenvenuto:benvenuta;!$B$BDimostra che cerchi l'amicizia dei Gelkis. Uccidi i centauri Magram. Torna quando il terreno sarà bagnato di sangue Magram.",
  reward = "La terra mi parla. E dice che hai ucciso molti Magram. Questo è bene.$B$BSe sei $Gun amico:un'amica; dei Gelkis, allora ascolta. Ho altri compiti per te.",
  en_title = "Gelkis Alliance",
  en_obj = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.",
}
T[1369] = {
  title = "Broken Tears",
  desc = "I Gelkis pensano che Theradras, la madre di noi centauri, ci protegga. Sono stupidi. Nessuno protegge i centauri. I Magram non hanno bisogno di protezione! Siamo i più forti!$B$BMostra ai Gelkis che sono stupidi. Va' nella grotta del loro villaggio. In quella grotta accumulano cristalli, le lacrime di Theradras. Distruggi le lacrime e portami i pezzi rotti!",
  obj = "Mantieni la tua reputazione con i Magram e porta 3 Broken Tear a Warug, al Magram Village.",
  progress = "Se non sei $Gnostro nemico:nostra nemica;, farai quello che ti chiedo!",
  reward = "Hai preso le lacrime! Ora i Gelkis sapranno che Theradras non li aiuterà. Non piangerà quando li schiacceremo! I Magram regneranno!$B$BSei $Gfurbo:furba; ad aiutarci, $N. Siamo i più forti.",
  en_title = "Broken Tears",
  en_obj = "Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village.",
}
T[1370] = {
  title = "Rubare le provviste",
  desc = "Quando non siamo in guerra, cacciamo per procurarci carne. La carne ci dà forza, e le pance piene combattono meglio di quelle vuote.$B$BÈ lo stesso per i Magram. Mettono da parte carne in più per poter combattere più a lungo tra una caccia e l'altra. Se fai razzia nel loro villaggio a est e prendi le loro scorte di carne, la loro forza verrà meno.",
  obj = "Porta 6 sacchetti di Crudely Dried Meat a Uthek the Wise, al Gelkis Village.",
  progress = "Torna dopo aver dimostrato ancora il tuo valore ai Gelkis!",
  reward = "Bene. Sento brontolare le rumorose pance dei Magram fin dal loro villaggio, lontano!$B$BDarò questa carne ai Gelkis. E combatteremo per molti giorni senza riposo.$B$BQuello che hai fatto è un bene per i Gelkis, $N.",
  en_title = "Stealing Supplies",
  en_obj = "Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.",
}
T[1371] = {
  title = "Un aggeggio per Warug",
  desc = "Tanto tempo fa, un piccolo gnomo venne a Desolace. Aveva cavalli e un carro, e il carro conteneva cose strane. Cose buffe. Cose che bruciavano di colori diversi. Cose che si muovevano e non erano vive. Ho ucciso il piccolo gnomo, ma prima... mi ha fatto ridere.$B$BMi sono tenuto la cosa che mi piaceva di più del suo carro. Era un umano di legno, e mi salutava con la mano finché non l'ho colpito e rotto.$B$BNe voglio uno nuovo. Portamene uno nuovo!",
  obj = "Mantieni la tua reputazione con i Magram e porta un Advanced Target Dummy a Warug, al Magram Village, a Desolace.",
  progress = "Se non sei $Gnostro nemico:nostra nemica;, farai quello che ti chiedo!",
  reward = "Sì, è proprio quello che avevo! Lo farò muovere di nuovo. Mi fa ridere!",
  en_title = "Gizmo for Warug",
  en_obj = "Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace.",
}
T[1372] = {
  title = "Nient'altro che la verità",
  desc = "La nostra forza di spedizione è stata mandata per volere di Varimathras a perlustrare la parte bassa di Azeroth.$B$BMentre ero in ricognizione ho notato un Infiltrator umano che spiava il Beggar's Haunt. Prima che riuscissi a catturarlo, alcuni dei nostri... fratelli... orchi l'hanno preso e portato a Stonard, la loro roccaforte nella Swamp of Sorrows.$B$BVoglio... aiutare... i nostri alleati orchi. Non hanno visto il nostro accampamento qui, ma voglio comunque dare una mano.$B$BLavora con Faustin, qui, per preparare un... siero della verità per il nostro amico a Stonard.",
  obj = "Parla con Apothecary Faustin al Beggar's Haunt.",
  reward = "Zraedus mi stava giusto parlando di quel ficcanaso di un Infiltrator, prima che arrivassi.$B$BUn bel problema, davvero. L'ultima cosa che ci serve è un impiccione che fiuta in giro per il Beggar's Haunt.$B$BSono sicuro che gli orchi di Stonard siano ansiosi di sentire cosa ha da dire il nostro amico. Visto che sono nostri alleati, ehm, dobbiamo aiutarli a ottenere dall'umano tutte le informazioni che possono.$B$BLavora con me, $N, e porteremo un siero della verità a Stonard.$B$BPer l'Orda!$B$B...l'ho detto giusto?",
  en_title = "Nothing But The Truth",
  en_obj = "Speak with Apothecary Faustin at Beggar's Haunt.",
}
T[1373] = {
  title = "Ongeku",
  desc = "Hai ancora molto da dimostrare, e il tuo prossimo compito ti porterà lontano, quindi per ora i Gelkis combatteranno i Magram senza di te.$B$BLa terra sussurra molti segreti a chi ascolta. Uno dei segreti che sento parla di un cristallo rosso. Si chiama draenethyst, ed è nuovo per la nostra terra. Viene da un luogo dove le montagne volano e dove regnano i demoni.$B$BPortami una scheggia di draenethyst, e renderà forte la mia magia! La scheggia si trova in un luogo chiamato Swamp of Sorrows, nelle mani del perduto Ongeku.",
  obj = "Mantieni la tua reputazione con i Gelkis e porta una Draenethyst Shard a Uthek the Wise, al Gelkis Village, a Desolace.",
  progress = "Dimostrami che sei $Gun amico:un'amica; dei Gelkis, $N.",
  reward = "Sì, questa è la scheggia di cui sussurrava la terra. Sento una magia potente al suo interno! Userò questa magia contro i nemici dei Gelkis.$B$BHai svolto un altro compito per noi, $N. Forse presto ti chiameremo $Gamico:amica;.",
  en_title = "Ongeku",
  en_obj = "Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.",
}
T[1374] = {
  title = "Khan Jehn",
  desc = "La terra mi parla, e dice che i Magram si stanno indebolendo. Ora è il momento di uccidere il loro Khan!$B$BPortami la testa del Khan dei Magram, Jehn!",
  obj = "Porta la Khan Jehn's Head a Uthek the Wise, al Gelkis Village, a Desolace.",
  progress = "Dimostrami che sei $Gun amico:un'amica; dei Gelkis, $N.",
  reward = "Khan Jehn era forte, ma stupido. Pensava che la sua forza fosse grande. Non vedeva che la magia della terra è più forte. Ora i centauri Magram cadranno senza il loro capo, e un giorno i Gelkis regneranno!",
  en_title = "Khan Jehn",
  en_obj = "Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace.",
}
T[1375] = {
  title = "Khan Shaka",
  desc = "Tu aiuti i Magram, e mi piaci. Ora uccidi il Khan dei Gelkis! È Khan Shaka, e voglio la sua testa! Voglio fissare la sua testa e ridere di lui!",
  obj = "Mantieni la tua reputazione con i Magram e porta l'Head of Khan Shaka a Warug, al Magram Village, a Desolace.",
  progress = "Fai dei compiti per i Magram, e io ti aiuterò.",
  reward = "Khan Shaka è morto! Metterò la sua testa su una picca e la terrò con me, così Shaka potrà vedere la forza dei Magram!",
  en_title = "Khan Shaka",
  en_obj = "Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace.",
}
T[1380] = {
  title = "Khan Hratha",
  desc = "$N, ci hai aiutato contro i Magram. Ora aiutaci a battere i Maraudine! Uccidi il capo del loro clan, Khan Hratha!$B$BPer affrontarlo, suona il Maraudine War Horn. Si trova in cima a un'alta rupe nella Valley of Spears.$B$BMa per suonare il corno ti serve un bocchino per il corno da guerra. Sono rari, e li portano solo i centauri Maraudine di fiducia.$B$BDopo che avrai suonato il corno, arriveranno i centauri. Uccidili finché non compare Hratha.$B$BKhan Hratha custodisce il pezzo di... una chiave. Portamelo...",
  obj = "Mantieni la tua reputazione con i Gelkis e porta il Maraudine Key Fragment a Uthek the Wise, al Gelkis Village.",
  progress = "Khan Hratha è morto? Hai il frammento di chiave?",
  reward = "È morto! Khan Hratha è morto! E ora i Maraudine cadranno! Quando i Gelkis regneranno su questa terra, $N, ci ricorderemo di te. E gli spiriti della terra canteranno il tuo nome per sempre.",
  en_title = "Khan Hratha",
  en_obj = "Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.",
}
T[1381] = {
  title = "Khan Hratha",
  desc = "Il Khan dei Gelkis è morto, e ora cadranno i Maraudine! Uccidi il Khan dei Maraudine, Hratha!$B$BPer affrontarlo, suona il corno sull'alta rupe nella Valley of Spears. Ma per suonare il corno ti serve un bocchino. Per avere un bocchino, uccidi i centauri Maraudine. Continua a ucciderli finché non trovi un bocchino. Poi suona il corno.$B$BFai questo e i centauri Maraudine verranno alla torre. Uccidili finché non compare Khan Hratha. Hratha ha il pezzo di una chiave. Dai questo pezzo a me...",
  obj = "Mantieni la tua reputazione con i Magram e porta il Maraudine Key Fragment a Warug, al Magram Village, a Desolace.",
  progress = "Fai quello che ti chiedo. Dimostrami che sei $Gun alleato:un'alleata; dei Magram!",
  reward = "Khan Hratha è morto! Ora i Magram sono i più forti tra i centauri! Schiacceremo gli altri e regneremo su Desolace!$B$BCi ricorderemo di te, $N, e sarai $Grisparmiato:risparmiata; dai nostri zoccoli quando tutti gli altri saranno calpestati.",
  en_title = "Khan Hratha",
  en_obj = "Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.",
}
T[1382] = {
  title = "Una strana alleanza",
  desc = "Siamo fortunati che i clan dei centauri combattano tra loro, perché se si unissero in un'unica forza sarebbero inarrestabili. Sì, siamo fortunati, e dovremmo sfruttare il nostro vantaggio.$B$BUno dei clan dei centauri, il clan Gelkis, è in guerra brutale con il clan Magram. Se attacchiamo i Magram, forse potremo stringere un'alleanza con i Gelkis.$B$BParla con Uthek the Wise, ai margini degli accampamenti Gelkis nel sud-ovest di Desolace. Attraverso di lei potremmo stringere un'alleanza con i Gelkis.",
  obj = "Raggiungi la reputazione Friendly con i Gelkis, poi parla con Uthek the Wise.",
  progress = "Sparisci! I Gelkis non ti vogliono qui. Vattene subito!!$B$BTorna dopo aver ucciso molti Magram, e allora parlerò con te.",
  reward = "Il tuo nome si sussurra tra i Gelkis. Hai molto sangue Magram sulle mani. Questo è bene.$B$BForse è bene anche che parliamo. Parliamo di cosa puoi fare tu per i Gelkis, e di cosa possiamo fare noi per te.",
  en_title = "Strange Alliance",
  en_obj = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.",
}
T[1383] = {
  title = "Nient'altro che la verità",
  desc = "Ho in mente proprio il siero giusto. Tratterà la verità esattamente come la verità va trattata.$B$BPer questo intruglio mi serviranno parecchi cuori di Shadow Panther della Swamp. Mi serve anche il fungo incantato del Mire Lord che vive laggiù. Sono sicuro che qualcuno in gamba come te, $N, saprà convincerlo a cedertene un po'.$B$BOra, la parte difficile sarà trovare un tumore di Deepstrider nella lontana Desolace. Molto di rado i giganti di laggiù si ammalano e si forma un tumore.$B$BOra, va'!",
  obj = "Apothecary Faustin, al Beggar's Haunt, ha bisogno di 5 Shadow Panther Heart, del Mire Lord Fungus e di un Deep Strider Tumor.",
  progress = "Quell'Infiltrator a Stonard di sicuro... si aprirà... dopo aver bevuto il mio siero speciale. Ahah!$B$BGli ingredienti che servono non sono affatto facili da procurare. Le Shadow Panther sono comuni nella Swamp, ma raccogliere abbastanza cuori per il nostro scopo può essere un'impresa. E il Mire Lord sa essere una bestia molto difficile.$B$BQuanto al tumore di Deepstrider, è terribilmente difficile da trovare. Ma la reazione chimica che posso ricavarne non ha eguali.",
  reward = "Splendido, $N! E proprio in tempo. Da quel che mi dice Zraedus, l'Infiltrator si è ripreso dalle ferite ed è pronto per essere interrogato dagli orchi.$B$BDammi solo un momento per preparare il vel... voglio dire, per preparare il siero della verità.",
  en_title = "Nothing But The Truth",
  en_obj = "Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and a Deep Strider Tumor.",
}
T[1384] = {
  title = "Incursione contro i Kolkar",
  desc = "I centauri Kolkar pensano che la loro magia sia forte. Non sanno cos'è la magia! Non la riconoscerebbero nemmeno se li mordesse!$B$BTu mostrerai loro che la loro magia è debole. Va' dai Kolkar a nord-est e uccidili. Prendi i loro amuleti. Portami gli amuleti e io li getterò nel fuoco ridendo!",
  obj = "Mantieni la tua reputazione con i Gelkis e porta 10 Crude Charm a Uthek the Wise, al Gelkis Village, a Desolace.",
  progress = "Hai gli amuleti? Hai mostrato ai Kolkar che sono deboli?",
  reward = "Fai una cosa buona per i Gelkis. I Kolkar sono deboli e moriranno. La loro magia è patetica e non li salverà. Tu gliel'hai mostrato, e la loro paura li renderà ancora più fiacchi!$B$BE nelle nostre terre, chi è fiacco muore presto.",
  en_title = "Raid on the Kolkar",
  en_obj = "Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace.",
}
T[1385] = {
  title = "Politica brutale",
  desc = "Desolace è una terra in guerra. I centauri si fanno guerra tra loro, e crediamo che il vincitore finirà per riversarsi fuori e minacciare le nostre roccaforti. Questo non possiamo permetterlo.$B$BDobbiamo imparare a battere i centauri, e per farlo... dobbiamo allearci con uno dei clan. I centauri Magram sono in guerra con i Gelkis. Se combatti i Gelkis, i Magram potrebbero prendere in considerazione un'alleanza.$B$BGuadagnati il favore dei Magram, poi parla con Warug, nel villaggio dei Magram, nel sud-est di Desolace.",
  obj = "Raggiungi la reputazione Friendly con i Magram, poi parla con Warug.",
  progress = "Ora te ne vai, o i Magram ti schiacceranno! Per essere $Gnostro amico:nostra amica;, devi uccidere i Gelkis.",
  reward = "Molti Gelkis cadono per mano tua. Mi piace. Forse puoi fare altre cose che mi piacciono. Forse tu e i Magram potete essere amici.",
  en_title = "Brutal Politics",
  en_obj = "Gain a Friendly reputation with the Magram, then speak with Warug.",
}
T[1386] = {
  title = "Assalto ai Kolkar",
  desc = "I Kolkar pensano di essere forti, ma noi ridiamo di loro! Ridiamo e li uccidiamo! Uccidili anche tu. Dimostrami che sai uccidere i Kolkar come facciamo noi. Va' a nord e sterminali tutti!",
  obj = "Mantieni la tua reputazione con i Magram. Uccidi 12 Kolkar Centaur, 12 Kolkar Scout e 6 Kolkar Mauler, poi torna da Warug, al Magram Village, a Desolace.",
  progress = "Hai paura dei Kolkar? Perché non li uccidi? Forse hai dimenticato come si uccide. Sbrigati e uccidi i Kolkar prima che siano morti!",
  reward = "Ora i Kolkar hanno paura di te! Spero che tu abbia riso mentre li uccidevi. È meglio ridere quando uccidi, così il nemico vede che è debole.",
  en_title = "Assault on the Kolkar",
  en_obj = "Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace.",
}
T[1387] = {
  title = "Taglia sui centauri",
  desc = "La razza dei centauri è formata da molti clan. Ognuno ha il suo capo e i suoi scopi, ma tutti i clan hanno una cosa in comune. La crudeltà.$B$BSe vogliamo mai trovare la pace, i centauri vanno eliminati. E perciò affido a te proprio questo compito.$B$BMentre giri per Desolace, dai la caccia ai centauri e prendi le loro orecchie. Portami tante, tante orecchie.$B$BFallo al servizio dell'Alleanza, $N, e saremo un passo più vicini alla fine della guerra.",
  obj = "Porta 15 Centaur Ear a Corporal Melkins, a Nijel's Point, a Desolace.",
  progress = "Hai un rapporto, $N?",
  reward = "Ah, le orecchie. Ben fatto.$B$BIl tuo servizio all'Alleanza è fuori discussione, $N. Il sangue che hai versato a Desolace salverà, senza dubbio, innumerevoli vite.",
  en_title = "Centaur Bounty",
  en_obj = "Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.",
}
T[1388] = {
  title = "Nient'altro che la verità",
  desc = "Tutto procede secondo i piani, $N. Voglio che tu dia questo siero della verità a Deathstalker Zraedus, e lui ti mostrerà come somministrarlo... come si deve.$B$BAhah!",
  obj = "Dai Faustin's Truth Serum a Deathstalker Zraedus al Beggar's Haunt.",
  progress = "Spero che tu ti sia $Gdimostrato:dimostrata; utile al nostro caro amico, Apothecary Faustin.",
  reward = "Sapevo che il vecchio Faustin avrebbe tirato fuori qualcosa di buono! Sei $Gstato:stata; di grandissimo aiuto, non c'è dubbio.$B$BOra mettiamoci al lavoro, che ne dici?",
  en_title = "Nothing But The Truth",
  en_obj = "Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt.",
}
T[1389] = {
  title = "Draenethyst Crystals",
  desc = "I perduti che vivono nel Fallow Sanctuary hanno il nostro aspetto, ma sono mostri... impazziti per le fatiche del nostro viaggio verso Azeroth. Un tempo erano nostri fratelli, ora vivono nel Fallow Sanctuary a est, e catturano o uccidono chiunque si avvicini.$B$BE ci hanno rubato qualcosa di sacro: i cristalli di draenethyst.$B$BNon abbiamo le forze per entrare nel Fallow Sanctuary e riprenderci il draenethyst che ci hanno rubato, tra le loro capanne e i loro fuochi, ma senza quei cristalli... anche noi potremmo perdere la strada.",
  obj = "Porta 6 Draenethyst Crystal a Magtoor, all'Harborage, nella Swamp of Sorrows.",
  progress = "Hai i cristalli?",
  reward = "Grazie, $N. Siamo in debito con te.",
  en_title = "Draenethyst Crystals",
  en_obj = "Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows.",
}
T[1390] = {
  title = "Ops, li abbiamo uccisi di nuovo.",
  desc = "Testo mancante.",
  obj = "Testo mancante.",
  reward = "Grazie per il lavoro fatto!",
}
T[1391] = {
  title = "Nient'altro che la verità",
  desc = "Dobbiamo agire con una certa discrezione. Dopotutto, non è che puoi entrare lì con disinvoltura e convincere quell'idiota a bere l'intruglio di Faustin, giusto?$B$BMa se c'è una cosa a cui quegli umani non sanno dire di no, è l'alcol. Prenderò il siero di Faustin e lo mescolerò a questa birra. Ti garantisco che quel poveraccio non esiterà un attimo a scolarsi una birra.$B$BSbrigati a raggiungere Stonard, nella Swamp of Sorrows, $N. E mi raccomando, che la nostra piccola missione resti tranquilla e silenziosa...",
  obj = "Porta Zraedus's Brew a Infiltrator Marksen, a Stonard.",
  progress = "Ti prego, abbi pietà di me! Ho informazioni che vanno oltre gli schieramenti. Non sono un simpatizzante dell'Orda, ma c'è in atto un tradimento politico che deve essere svelato!",
  reward = "Da bere per me? Che gentile. Sono giorni che non mi lasciano bere. Fammi mandare giù questa, e poi ti dirò quello che ho scoperto...",
  en_title = "Nothing But The Truth",
  en_obj = "Take Zraedus's Brew to Infiltrator Marksen in Stonard.",
}
T[1392] = {
  title = "Noboru the Cudgel",
  desc = "Da mesi Noboru tormenta i draenei dell'Harborage, e il suo randello è un simbolo della brutalità che hanno subito per mano dei perduti.",
  obj = "Porta Noboru's Cudgel al capo dell'Harborage, nella Swamp of Sorrows.",
  progress = "Salute. E $Gbenvenuto:benvenuta; all'Harborage.",
  reward = "Hai preso l'arma del temuto Noboru? Allora è morto?$B$BÈ un giorno di gioia per l'Harborage. Noboru e la sua banda ci terrorizzavano, vagando per le paludi e uccidendo tutti i draenei che incrociavano la sua strada. Era una minaccia diretta alla nostra sopravvivenza, e non avevamo la forza di affrontarlo.$B$BSiamo fortunati ad avere in te $Gun amico:un'amica;, $N.",
  en_title = "Noboru the Cudgel",
  en_obj = "Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.",
}
T[1393] = {
  title = "La fuga di Galen",
  desc = "Aiuto, ti prego! Queste creature stanno per mangiarmi!$B$BAiutami a uscire di qui, e ti darò un grande tesoro! È nel mio accampamento nella palude, a nord di Stonard, ma è chiuso in un forziere che si può aprire solo con un trucco che conosco soltanto io.$B$BSe mi aiuti a scappare, te lo insegnerò.",
  obj = "Scorta Galen fuori pericolo, poi trova il suo accampamento nella Swamp of Sorrows e apri il suo forziere.",
  progress = "Il buco della serratura di questo forziere è pieno di resina nera. È impossibile aprirlo.",
  reward = "Il buco della serratura di questo forziere è pieno di resina nera. È impossibile aprirlo.$B$BMa Galen ti ha parlato di un fermo nascosto sul fondo del forziere...$B$B...Dopo una breve ricerca, il fermo viene trovato. Il fermo viene sganciato, e il forziere si apre...",
  en_title = "Galen's Escape",
  en_obj = "Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.",
}
T[1394] = {
  title = "Il passaggio finale",
  desc = "Hai fatto bene, $N. Hai superato la mia prova e quelle prima della mia. Torna da Dorn, a Thousand Needles. Sentirà il cambiamento dentro di te e vedrà che la tua mente, il tuo corpo e il tuo spirito sono abbastanza forti da meritare una ricompensa per quel che hai fatto.$B$BResta fedele all'equilibrio che hai mostrato in tutte queste prove, $N. Se lo farai, in futuro Dorn ti metterà di nuovo alla prova.",
  obj = "Parla con Dorn Plainstalker, a Thousand Needles.",
  reward = "Ah, $N. È passato molto tempo dall'ultima volta che hai messo piede in casa mia. Sembrano passate molte lune da quando hai fatto il primo salto che ti ha messo sul tuo cammino.$B$BE ora torni da me più forte di prima... più $Gilluminato:illuminata;. Questo mi fa piacere. Ed è giusto che tu sia $Gricompensato:ricompensata; per aver portato a termine le mie prove.",
  en_title = "Final Passage",
  en_obj = "Speak to Dorn Plainstalker in Thousand Needles.",
}
T[1395] = {
  title = "Rifornimenti per Nethergarde",
  desc = "Questa cassa di pietre del potere deve arrivare a Nethergarde Keep, nelle Blasted Lands. Non conserveranno il loro potere a lungo, quindi non possiamo spedirle con la prossima carovana.$B$BDevi portarle tu, e devi portarle in fretta.$B$BPortale a Quartermaster Lungertz, a Nethergarde Keep. Per raggiungere la fortezza devi andare a est attraverso il Deadwind Pass, poi a est attraverso la Swamp of Sorrows, poi a sud attraverso le Blasted Lands.$B$BSta' $Gattento:attenta;, $N. Attraverserai terre pericolose, eppure non devi fallire.",
  obj = "Porta la Crate of Powerstones a Quartermaster Lungertz, prima che le pietre del potere si esauriscano.",
  progress = "Salve! Non badare a tutto questo trambusto, è la solita vita di Nethergarde Keep.$B$BHai qualcosa per me?",
  reward = "Ah, le pietre del potere! I maghi saranno contenti di vederle!$B$BMille grazie, $N. So che il viaggio da Darkshire non è stato facile.",
  en_title = "Supplies for Nethergarde",
  en_obj = "Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire.",
}
T[1396] = {
  title = "La fauna selvatica avanza",
  desc = "La mia carovana era diretta alla costa orientale, ma non abbiamo raggiunto la meta. I Perduti ci hanno attaccati, uccidendo le guardie e distruggendo le provviste.$B$BSono l'unico sopravvissuto al loro assalto. Ho giurato di proteggere le provviste rimaste, ma le creature selvatiche si aggirano qui vicino. Ti prego, aiutami a difendere il mio accampamento dalle bestie!",
  obj = "Uccidi 8 Young Sawtooth Crocolisk, 10 Sorrow Spinner e 10 Swamp Jaguar, poi torna da Watcher Biggs, nella Swamp of Sorrows.",
  progress = "Le creature della palude si fanno sotto, $N. Ti prego, devi difendere l'accampamento!",
  reward = "I versi degli animali ora sono deboli, più lontani. Grazie, $N. Speriamo che non tornino!",
  en_title = "Encroaching Wildlife",
  en_obj = "Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows.",
}
T[1398] = {
  title = "Legni spiaggiati",
  desc = "Ti devo moltissimo, $N. Dentro di te batte un cuore onorevole. E ora ho un altro compito per cui chiedo umilmente il tuo aiuto.$B$BSe mai voglio raggiungere Nethergarde, devo riparare questo carro. E per farlo... mi servirà del legno. Legno robusto e asciutto, non il legno spugnoso e contorto degli alberi della palude.$B$B$N, va' a est verso la costa e cerca legni spiaggiati seccati dal sole. Portameli.",
  obj = "Porta 8 pezzi di Sundried Driftwood a Watcher Biggs, nella Swamp of Sorrows.",
  progress = "Hai trovato dei legni spiaggiati, $N?",
  reward = "Questo legno è leggero, ma resistente. Grazie, $N. Andrà benissimo.",
  en_title = "Driftwood",
  en_obj = "Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows.",
}
T[1418] = {
  title = "Neeka Bloodscar",
  desc = "I Badlands sono una terra dura e si trovano vicino a Loch Modan, terra controllata dall'Alleanza, perciò le comunicazioni tra Stonard e l'avamposto di Kargath nei Badlands vengono spesso interrotte.$B$BDimostra il tuo valore, $N. Va' nei Badlands e parla con Neeka Bloodscar, a capo degli esploratori dell'avamposto di Kargath. Parla con lei, e poi rimanda a me il suo rapporto.",
  obj = "Parla con Neeka Bloodscar.",
  reward = "Helgrum vuole un rapporto, eh? Ho mandato un corriere a Stonard nemmeno tre giorni fa. Ha fallito la sua missione? Se Stonard non ha il mio rapporto, allora sembra proprio che abbia fallito.$B$BSperiamo che il prossimo corriere che mando abbia più abilità, o più fortuna.",
  en_title = "Neeka Bloodscar",
  en_obj = "Speak with Neeka Bloodscar.",
}
T[1419] = {
  title = "I coyote ladri",
  desc = "Hai passato molti giorni nei Badlands, $C? Hai sentito il caldo di questa terra? Hai affrontato le bestie che vagano per le sue pianure polverose? È ora di farlo.$B$BI Crag Coyote sono una razza tosta. Tosti, e abbastanza sfrontati da intrufolarsi a Kargath e rubare le nostre provviste di cibo. Aiutaci a liberare l'avamposto da questi ladri!$B$BDai la caccia ai Crag Coyote, $N. Cacciali e portami le loro mascelle. Portamene abbastanza, e forse ti crederò quando dirai di conoscere i Badlands.",
  obj = "Porta 30 Coyote Jawbone a Neeka Bloodscar, a Kargath.",
  progress = "Hai le mascelle?",
  reward = "Una bella collezione di mascelle, $N. Ora quei coyote non faranno più a pezzi le nostre provviste in cerca di avanzi.$B$BBen fatto. I coyote dei Badlands non sono prede facili. La tua impresa mi dimostra che forse qui riuscirai a sopravvivere.",
  en_title = "Coyote Thieves",
  en_obj = "Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath.",
}
T[1420] = {
  title = "A rapporto da Helgrum",
  desc = "Ho scritto un nuovo rapporto per Helgrum, a Stonard. Portaglielo.$B$BE se ti consideri una staffetta, allora non perderti per strada. E non cadere per mano di un nemico.",
  obj = "Porta Neeka's Report a Helgrum the Swift, a Stonard.",
  progress = "Sei $Gtornato:tornata;. Hai un rapporto?",
  reward = "Grazie, $N. Dal rapporto di Neeka vedo che anche l'Alleanza ha i suoi problemi. E potremmo scoprire di avere qualche nemico in comune.",
  en_title = "Report to Helgrum",
  en_obj = "Bring Neeka's Report to Helgrum the Swift in Stonard.",
}
T[1421] = {
  title = "La carovana perduta",
  desc = "Sono rimasto stordito durante l'attacco dei Perduti, ma prima che mi si oscurasse la vista ho visto uno dei nostri carri trascinato al Fallow Sanctuary, il villaggio dei perduti a nord.$B$BIn quel carro c'era una Caravan Chest con reagenti preziosi, reagenti vitali per gli studi dei maghi della Nethergarde Keep. Trova la cassa e prendi quei reagenti, $N. Prendili e portali a me.",
  obj = "Trova la Caravan Chest nel Fallow Sanctuary, prendi i Wizards' Reagents e portali a Watcher Biggs.",
  progress = "Hai i reagenti dei maghi, $N?",
  reward = "Ah, li hai trovati! Con questi, i maghi di Nethergarde potranno continuare il loro lavoro. Non so che cosa facciano di preciso, ma ha a che fare con il Dark Portal nelle Blasted Lands, ed è vitale per la sicurezza dell'Alleanza.",
  en_title = "The Lost Caravan",
  en_obj = "Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs.",
}
T[1422] = {
  title = "Minaccia dal mare",
  desc = "Mentre comincio a lavorare alla tua arma, perché non parli con Katar? Ha detto che gli serve aiuto con le pattuglie lungo la spiaggia, e preferirei vederti con la mente lucida e le armi pronte, invece che a ubriacarti con qualcuno degli altri pidocchi con cui divido questo accampamento.",
  obj = "Parla con Katar, nella Swamp of Sorrows.",
  reward = "Fa' silenzio un momento, $C. Anche sopra il ruggito sordo del mare si sentono ancora quei disgustosi gorgoglii degli uomini pesce.",
  en_title = "Threat From the Sea",
  en_obj = "Speak to Katar in the Swamp of Sorrows.",
}
T[1423] = {
  title = "Le Lost Supplies",
  desc = "Questo barile è piccolo ma robusto. Le giunture sono sigillate con una cera gialla dall'odore pungente. Sul fondo del barile sono stampate le parole:$B$BQUARTERMASTER LUNGERTZ$B$BNETHERGARDE KEEP",
  obj = "Porta le Lost Supplies a Quartermaster Lungertz.",
  progress = "Hai qualcosa per me?",
  reward = "Ah, grazie, $N! Tra Darkshire e qui si perdono così tante provviste. È bello vedere che qualcuna viene recuperata.",
  en_title = "The Lost Supplies",
  en_obj = "Bring the Lost Supplies to Quartermaster Lungertz.",
}
T[1424] = {
  title = "Il Pool of Tears",
  desc = "Il Capoguerra ci ha mandati a indagare su strani avvenimenti al Temple of Atal'Hakkar.$B$BI troll Atal'ai sono una tribù di incantatori oscuri, noti per praticare magie proibite. Puoi immaginare il nostro stupore quando, arrivati qui, abbiamo scoperto che il tempio era sprofondato.$B$BOra i draghi verdi sorvegliano il luogo, e sostengono di essere i protettori di Azeroth.$B$BDobbiamo scoprire cos'è successo. Esplora i dintorni del Pool of Tears e raccogli degli Atal'ai Artifact. Partendo da quelli potrò cominciare a ricomporre questo enigma.",
  obj = "Fel'zerul, a Stonard, vuole che tu raccolga 10 Atal'ai Artifact.",
  progress = "Nessuno sa quali pratiche oscure si svolgessero dentro il Temple of Atal'Hakkar. Ma sappiamo che sono state usate forze magiche grandi e potenti.$B$BDobbiamo imparare il più possibile su questa magia. Forse gli incantesimi degli Atal'ai si riveleranno utili all'Orda.$B$BQuando avrai raccolto abbastanza Atal'ai Artifact intorno al Pool of Tears, potrò cominciare a capire cosa speravano di ottenere i troll e cosa è andato così terribilmente storto.",
  reward = "La diligenza con cui hai raccolto gli Atal'ai Artifact merita un elogio, $C.",
  en_title = "Pool of Tears",
  en_obj = "Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts.",
}
T[1425] = {
  title = "Consegna il carico",
  desc = "Mentre riparo questo carro, $N, ho un ultimo compito per te.$B$BHo imballato le provviste più vitali salvate dagli attacchi degli ogre. Portale alla Nethergarde Keep. La fortezza è annidata tra le colline settentrionali delle Blasted Lands, e sorveglia il Dark Portal.$B$BPer raggiungere Nethergarde, segui la strada verso est. Quando si dirama, va' a sud nelle Blasted Lands, poi alla biforcazione successiva gira a sinistra. Segui la strada, $N, e fa' attenzione.",
  obj = "Porta lo Shipment to Nethergarde a Quartermaster Lungertz, nella Nethergarde Keep.",
  progress = "Hai qualche affare con me?",
  reward = "Cosa? Un pacco dalla carovana di Biggs? Credevamo che la carovana, e lui, fossero andati perduti.$B$BGrazie, $N. Con un po' di fortuna, queste provviste conterranno il reagente di cui abbiamo tanto bisogno, gli Azoran Crystal. Le nostre scorte si stanno esaurendo...",
  en_title = "Deliver the Shipment",
  en_obj = "Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep.",
}
T[1426] = {
  title = "Minaccia dal mare",
  desc = "Non ho alcun amore per il mare, né per le creature che ho visto uscire dai suoi abissi. È un'amante potente ma cieca; spietata e brutale. Mi darebbe un gran piacere uccidere gli uomini pesce a centinaia, se fosse in mio potere. Ma provo un certo piacere a guardarli morire per mano di chiunque compia la volontà dell'Orda.$B$BIl che ci porta a te, $C. Quanti riesci a ucciderne? Vuoi metterti alla prova contro i più potenti della loro specie?",
  obj = "Uccidi 10 Marsh Murloc, 10 Marsh Inkspewer e 10 Marsh Flesheater, poi torna da Katar, nella Swamp of Sorrows.",
  progress = "Sono paziente. Paziente ed eterno come una vecchia pietra kank di Draenor. Gli uomini pesce non supereranno i nostri confini, non finché resterò in piedi. Se avessimo un esercito a disposizione, ripulirei questo mondo e tutti gli altri dalla loro presenza. Sento il mio odio ribollire solo a parlarne.",
  reward = "Il mare sembra vasto e implacabile, ma tu l'hai macchiato con il sangue della sua stessa progenie. Gli uomini pesce conoscono il dolore. La loro stupidità li costringerà a rinforzare le file dopo la devastazione che hai causato, ed è un bene.$B$BChe le loro grida gorgoglianti coprano il ruggito del mare fino a notte fonda. Sorriderò ogni volta che ne sentirò uno messo a tacere.$B$BTorna da me se vuoi uccidere altri uomini pesce. Ti ricompenserò di nuovo volentieri.",
  en_title = "Threat From the Sea",
  en_obj = "Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.",
}
T[1427] = {
  title = "Minaccia dal mare",
  desc = "Prima di riposarti, parla di nuovo con Tok'Kar. Mentre eri via credo abbia finito qualche arma. Per il tuo aiuto qui, vorrebbe offrirtene una. Faresti bene a metterne alla prova la forza contro gli uomini pesce quando sarai $Gpronto:pronta;... ma solo per farmi ancora più piacere.",
  obj = "Parla con Tok'Kar, nella Swamp of Sorrows.",
  reward = "Ah, $N, sei $Gtornato:tornata;. Bene. Ho finito di forgiare altre armi per la nostra lotta contro i murloc. Per averci portato la carne fresca di sawtooth, e per aver strappato un piccolo sorriso a Katar, te ne offro una.",
  en_title = "Threat From the Sea",
  en_obj = "Speak with Tok'Kar in the Swamp of Sorrows.",
}
T[1428] = {
  title = "Una minaccia che continua",
  desc = "Mi fa piacere vedere che il tuo odio per gli uomini pesce cresce insieme al mio.$B$BTrovane altri della loro specie lungo la spiaggia, e quando avrai combattuto abbastanza torna da me. Allora parleremo di una ricompensa per la tua diligenza.",
  obj = "Uccidi 10 Marsh Inkspewer, 10 Marsh Flesheater e 10 Marsh Oracle, poi torna da Katar, nella Swamp of Sorrows.",
  progress = "Non sarò soddisfatto finché il mare e tutti i suoi figli non saranno ridotti al silenzio... soprattutto quei disgustosi uomini pesce.",
  reward = "Ben fatto, $C. Voglio altro del loro sangue. Che periscano tutti gli uomini pesce.",
  en_title = "Continued Threat",
  en_obj = "Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.",
}
T[1429] = {
  title = "L'Atal'ai Exile",
  desc = "Mentre affrontavi i pericoli del Pool of Tears, uno dei miei esploratori è tornato con una pergamena scritta col sangue su pelle secca. Sembra una sentenza contro un sacerdote della tribù Atal'ai.$B$BTra gli Atal'ai, questo sacerdote è stato condannato a un destino peggiore della morte.$B$BÈ stato esiliato a vivere lontano, a nord, nelle Hinterlands, con i troll Witherbark.$B$BImpacchetterò questi manufatti. Tu devi cercare l'esule e scoprire a cosa servono davvero. Torna da me quando il tuo viaggio sarà concluso.",
  obj = "Porta il Bundle of Atal'ai Artifacts all'Atal'ai Exile, nelle Hinterlands.",
  progress = "Hai coraggio a venire qui. Coraggio o follia...",
  reward = "Mi porti i manufatti di evocazione degli Atal'ai?$B$BVedo che Jammal'an the Prophet sta guidando i discepoli della Chamber of Blood verso il destino che hanno scelto. Mi chiedo se Hakkar sia tornato al tempio. Si è compiuto il loro destino?",
  en_title = "The Atal'ai Exile",
  en_obj = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.",
}
T[1430] = {
  title = "Carne fresca",
  desc = "Tra i miei clienti c'è molta richiesta del sapore succulento della carne di crawler, soprattutto quella dei Monstrous Crawler.$B$BSe hai intenzione di andare sulla costa, potrei facilmente fare in modo che ti convenga riportarmi un po' delle loro zampe, da spedire a Orgrimmar.$B$BLa costa è a est di qui, e non dovresti avere problemi a trovare le creature che zampettano lungo le spiagge e sotto il mare.",
  obj = "Porta 10 Monstrous Crawler Leg a Dar, nella Swamp of Sorrows.",
  progress = "Ho una botte di vino che aspetta il tuo successo, $N. È giusto che io assaggi la merce prima di spedirla ai miei clienti.",
  reward = "Ah, queste dovrebbero essere perfette. Non vedo l'ora di assaggiarle, dopo averle cotte a puntino sul fuoco. Dovresti portartene un campione nei tuoi viaggi. È davvero deliziosa.",
  en_title = "Fresh Meat",
  en_obj = "Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.",
}
T[1431] = {
  title = "Rapporti con l'Alleanza",
  desc = "Fermati, $C, e lascia che ti dica una cosa importante per il nostro popolo, ma tutt'altro che ovvia.$B$BSiamo una razza orgogliosa, e la guerra con gli umani ha messo alla prova perfino la grande pazienza di Thrall. Vedi, il nostro Capoguerra è saggio e prudente, e continua a mettere al primo posto la sua gente. In fondo è un diplomatico, e nel tempo passato con gli umani ha imparato molto dei loro modi.$B$BSe la storia che ho cominciato ti incuriosisce, cerca Keldran vicino all'uscita occidentale della città. La sua casupola è là.",
  obj = "Parla con Keldran, a Orgrimmar.",
  reward = "Putanni, nobile $C. Io sono Keldran, studioso di magia... e di altre arti mistiche.$B$BLa faccenda di cui Craven ti ha mandato a parlarmi richiede un po' più di finezza di quanta te ne sia servita finora, ma questo non vuol dire che tu non possa comunque aiutare la nostra causa.$B$BTi prego, mettiti $Gcomodo:comoda;, e ti dirò perché il Capoguerra ha bisogno del mio aiuto... e del tuo.$B$BTutto comincia dalle apparenze, $N. Da come l'Orda vede se stessa. Da come ci vedono i nostri alleati. E soprattutto da come ci vedono i nostri nemici.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Keldran in Orgrimmar.",
}
T[1432] = {
  title = "Rapporti con l'Alleanza",
  desc = "Mentre l'Alleanza avanza sempre più a fondo in Kalimdor, si potrebbero trarre conclusioni sbagliate sull'Orda e su presunti patti con la Legione Infuocata. Il Capoguerra non può permetterlo. E con la sua benedizione sto prendendo io in mano il compito di farli eliminare.$B$BHo agenti nella zona di Desolace, al Ghost Walker Post, a nord del grande Kodo Graveyard. Va' a sud del Charred Vale, nelle Stonetalon Mountains, e lo troverai. Quando arrivi, cerca Takata Steelblade.",
  obj = "Parla con Takata Steelblade, a Desolace.",
  reward = "Salve, $C. Porti notizie da Orgrimmar: bene.$B$BL'infestazione di demoni soffoca questa zona ancora più della puzza di sterco di centauro. Gli uomini-cavallo rivendicano questa terra come propria, ma è chiaro che ci sono forze fuori dal loro controllo che li schiacceranno, se non le si tiene a bada.$B$BNon mi fa piacere che aiutiamo indirettamente i centauri, ma è per il bene dell'Orda, quindi faccio il mio dovere per il Capoguerra, anche se vuol dire aiutare gli stregoni dentro l'Orda.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Takata Steelblade in Desolace.",
}
T[1433] = {
  title = "Rapporti con l'Alleanza",
  desc = "I Burning Blade hanno molti piani, ma sappi che sono malvagi fino al midollo, con lo spirito corrotto, e distruggerli è l'unico modo per mandare all'aria i loro obiettivi.$B$BKeldran ha mandato Maurin con me per la sua conoscenza della Blade e delle vie degli stregoni.$B$BÈ lui a guidare le nostre trame contro la Blade, mentre io mi occupo delle altre minacce demoniache qui a Desolace.$B$BParlagli e ti guiderà nei suoi piani.",
  obj = "Parla con Maurin Bonesplitter, a Desolace.",
  reward = "Ah, sì. L'aiuto di chi è fedele al Capoguerra è sempre gradito.$B$BMi chiamo Maurin. Sono qui su richiesta di Keldran e del cucciolo di Capoguerra, Thrall. È mio desiderio aiutare quel giovane capo contro i mali che minacciano il suo governo.$B$BVieni, avvicinati, $C. Ti spiegherò il mio piano per eliminare quel bubbone purulento che sono i Burning Blade.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Maurin Bonesplitter in Desolace.",
}
T[1434] = {
  title = "Corrotti dai satiri",
  desc = "Un'infestazione di demoni non capita senza altre influenze: c'è sempre qualcos'altro che permette al male di prendere piede.$B$BPuò cominciare con uno spirito indebolito, con un desiderio inutile di potere; forse è sete di vendetta, o il richiamo di una giustizia definitiva. Quando siamo assaliti dal dolore, il male approfitta di noi: un male come i satiri.$B$BSono stati trovati legami tra loro e i Burning Blade, e Thrall li vuole morti. Cercali a nord-est di qui e torna da me quando li avrai ricacciati indietro.",
  obj = "Uccidi 7 Hatefury Rogue, 7 Hatefury Felsworn, 7 Hatefury Betrayer e 7 Hatefury Hellcaller, poi torna da Takata Steelblade, a Desolace.",
  progress = "Un compagno tauren mi ha avvertito che i satiri non sono come sembrano. Crede che ci sia qualcosa di più in loro, che il loro male sia una distorsione della loro vera natura. Ma io queste cose non le ho viste.$B$BIo vedo solo il massacro spietato dei deboli e la corruzione di chi cerca un potere oscuro.$B$BContinuerò nel mio dovere di annientarli finché il Capoguerra non mi ordinerà altro. Fino ad allora, non ho pietà di loro.",
  reward = "Hai fatto bene, $C. Hai mostrato onore e dedizione.$B$BQuando la nostra campagna a Desolace sarà finita, il Capoguerra saprà che ci hai aiutato in quel che abbiamo fatto qui e che hai contribuito a realizzare la sua volontà.$B$BTi ringrazio.",
  en_title = "Befouled by Satyr",
  en_obj = "Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.",
}
T[1435] = {
  title = "Spiriti in fiamme",
  desc = "La morte è quanto di più desiderabile per quelle creature spregevoli che voltano le spalle al loro signore per ragioni tanto egoistiche. Ma la morte non basta, quando si ha a che fare con chi si è consegnato all'oscurità.$B$BPrendi questa gemma. Quando uno dei Burning Blade è vicino alla morte, attivane la magia. L'incantesimo strapperà lo spirito corrotto dalla sua vittima e lascerà una gemma infusa.$B$BPortami queste gemme infuse, così potrò disfarmene come si deve.$B$BOra va', e possa tu sfuggire alla morte.",
  obj = "Riporta la Burning Gem e 15 Infused Burning Gem a Maurin Bonesplitter, a Desolace.",
  progress = "Ho cercato di rendere la magia più semplice possibile. Tirare fuori lo spirito della tua vittima dal suo corpo ferito dovrebbe essere un gioco da ragazzi. Non contare sul potere della gemma per uccidere del tutto il nemico. Devi attivarla solo quando è vicino alla morte, altrimenti non servirà a nulla.",
  reward = "Ah, sei $Gtornato:tornata; con successo. Bene. Dammi le gemme e le metterò in un posto sicuro....$B$BI miei compiti per te sono finiti, $C. Parla con Takata quando ti sarai $Griposato:riposata;. Potrebbe avere altri incarichi per te, o magari avrà bisogno che tu torni a Orgrimmar a informare Keldran dei nostri progressi qui a Desolace.",
  en_title = "The Burning of Spirits",
  en_obj = "Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.",
}
T[1436] = {
  title = "Rapporti con l'Alleanza",
  desc = "La lotta va bene, $N. Forse il Capoguerra ci lascerà tornare alle nostre case prima del cambio di stagione, se continuiamo a fare passi avanti così grandi nella battaglia contro i demoni e i loro servi.$B$BTorna da Keldran e fagli sapere cosa abbiamo fatto. Sono sicuro che ti ricompenserà per quel che hai fatto qui. La sua causa gli sta a cuore, e sarà fiero di sapere che il Capoguerra tiene conto delle sue preoccupazioni.",
  obj = "Parla con Keldran, a Orgrimmar.",
  reward = "Sei $Gtornato:tornata; da Desolace con più che un successo, $N. Grazie.$B$BGrazie per il tuo impegno, per il tuo tempo e per aver capito la mia richiesta. Thrall comprende e desidera la pace tra l'Orda e l'Alleanza, e prendendo provvedimenti perché il nostro aspetto sia accettabile, non provocheremo altre minacce di violenza inutile.$B$BTi sono debitore.",
  en_title = "Alliance Relations",
  en_obj = "Speak to Keldran in Orgrimmar.",
}
T[1437] = {
  title = "La ricerca di Vahlarriel",
  desc = "Sono Vahlarriel, $N. Mi trovo qui per scoprire dove siano finiti due nobili scomparsi di una famiglia di mercanti di Darnassus, la casata Malem. Il padre della casata teme il peggio, e io devo fare tutto il possibile per ritrovare i suoi figli scomparsi. Non ho ancora cominciato a cercare Tyranis o Dalinda, ma spero di non dover restare qui a lungo.$B$BLe ultime notizie dicono che sono passati per le Stonetalon Mountains qualche settimana fa.$B$BSe trovi il loro carro, ti prego, vieni a cercarmi immediatamente.",
  obj = "Trova e perquisisci il carro di Tyranis e Dalinda Malem, a Desolace.",
  reward = "Frugando tra i resti del carro, diventa evidente che è stato attaccato sia con incantesimi sia con armi. Lo scontro sembra essere stato rapido e a senso unico: non c'è traccia di sangue, né resti di corpi.$B$BChiunque abbia attaccato il carro è stato efficiente e rapido.",
  en_title = "Vahlarriel's Search",
  en_obj = "Find and search Tyranis and Dalinda Malem's wagon in Desolace.",
}
T[1438] = {
  title = "La ricerca di Vahlarriel",
  desc = "Trova sia Dalinda sia Tyranis, se puoi, e torna da me con quello che hai scoperto. Comincia le ricerche da questa fortezza. Contatterò subito i miei superiori a Darnassus e li informerò della situazione.$B$B$N, c'è un'altra cosa che voglio farti capire bene. I miei superiori si sono mostrati preoccupati per Tyranis e per i motivi che l'hanno spinto a venire qui. Per loro è più importante che Dalinda venga ritrovata e riportata a casa sana e salva. Tyranis va... valutato prima di essere riportato a casa.",
  obj = "Trova Dalinda Malem, a Desolace.",
  reward = "Grazie a Elune, finalmente qualcuno è venuto ad aiutarmi. Ti prego, $C, ho bisogno del tuo aiuto. Mio fratello Tyranis e io siamo stati catturati e portati qui dalla Burning Blade. Credo che vogliano sacrificarmi ai loro padroni demoniaci!$B$BSapevo che venire a Desolace era un errore, ma di recente Tyranis ha cominciato a bramare la conoscenza di tutto ciò che è arcano, perfino contro la volontà del nostro popolo. Ha deciso di fare questo viaggio anche dopo aver sentito i racconti sull'infestazione di demoni di questa terra.$B$BTemo il peggio per lui.",
  en_title = "Vahlarriel's Search",
  en_obj = "Find Dalinda Malem in Desolace.",
}
T[1439] = {
  title = "Alla ricerca di Tyranis",
  desc = "Siamo stati portati qui dopo che gli orchi hanno massacrato tutte le nostre guardie e i nostri servitori. Oh, le cose terribili che hanno fatto loro! Pensavo che di sicuro ci avrebbero uccisi lì, seduta stante, ma è diventato chiaro che avevano altri piani.$B$BTyranis ha cercato di parlare con loro. Credo che volesse impressionarli con la sua conoscenza dell'arcano... non so bene perché.$B$BTi prego, non posso andarmene da qui finché non so cosa è successo a mio fratello. Trovalo, poi torna a prendermi quando la sua sorte sarà nota.",
  obj = "Trova Tyranis Malem, a Desolace.",
  progress = "Temo che Tyranis cercherà di imparare i segreti della Burning Blade e di unirsi a loro, se glielo permetteranno: ha sempre adorato il potere che la magia dà a chi se ne lascia sedurre.$B$BNon so se potrei sopportare di tornare a casa dalla mia famiglia con la notizia che Tyranis sta flirtando con simili pericoli. Tra la mia gente è già un crimine abbastanza grave inseguire queste cose, ma diventare ciò da cui cerchiamo di proteggerci, beh, è riprovevole.",
  reward = "È terribile! Ma suppongo che fosse necessario. Se non fosse stato per mano tua, di sicuro sarebbe stato per mano della mia gente. Credo di doverti ringraziare... perdonami se il mio grazie non sembra sincero. Non intendo offenderti.$B$BOra che conosco la sorte di mio fratello, sembra che sia giunto il momento della mia fuga. Se sei ancora $Gdisposto:disposta;, accetterò il tuo aiuto per fuggire da questo posto orribile.$B$BQuando sei $Gpronto:pronta;, possiamo metterci in salvo.",
  en_title = "Search for Tyranis",
  en_obj = "Find Tyranis Malem in Desolace.",
}
T[1440] = {
  title = "Ritorno da Vahlarriel",
  desc = "Allora, è giunto il momento? Apprezzo i tuoi sforzi, e se poi non ci sarà occasione, lascia che ti ringrazi adesso per tutto quello che hai fatto per me e per la mia famiglia. Se sei $Gpronto:pronta;, qui non c'è più niente per me: possiamo partire quando ritieni che sia il momento giusto.",
  obj = "Scorta Dalinda Malem fuori dalla Thunder Axe Fortress, poi torna da Vahlarriel Demonslayer, a Desolace.",
  reward = "Grazie, $N. Dalinda è tornata sana e salva qui a Nijel's Point, e in condizioni molto migliori di quanto potessi sperare. Il fatto che sia arrivata qui con le sue forze è un buon segno. Tu stai bene, spero?$B$BMi addolora sapere che non sono tornati entrambi, Tyranis e Dalinda, ma la vergogna per le scelte di Tyranis dovrà sopportarla lei. È qualcosa che dovrà affrontare quando tornerà a Darnassus.",
  en_title = "Return to Vahlarriel",
  en_obj = "Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.",
}
T[1447] = {
  title = "Il diplomatico scomparso",
  desc = "Già, non sei certo $Gil:la; $C più $Gsveglio:sveglia; che sia mai entrato a Stormwind, ma stai per essere $Guno:una; dei più stupidi che non ne usciranno mai.$B$BHai conosciuto i miei amici?",
  obj = "Sconfiggi Dashel Stonefist, a Stormwind.",
  progress = "Non volevo dire niente con quella battuta sul fatto che sei $Gun:una; $C $Gstupido:stupida;. Siamo amici, no? Nessun rancore?",
  reward = "Allora, sei $Gvenuto:venuta; da me per un motivo. Di cosa hai bisogno?",
  en_title = "The Missing Diplomat",
  en_obj = "Defeat Dashel Stonefist in Stormwind.",
}
T[1448] = {
  title = "Alla ricerca del Tempio",
  desc = "C'è stato un tempo in cui ero giovane e pieno di vigore come te, $C.$B$BMa ora sono vecchio e non posso più esplorare il mondo come facevo una volta. Ah, le cose che ho visto!$B$BMa c'era un mistero che mi è sempre sfuggito. Per la mia ultima impresa, la Lega degli Esploratori mi ha mandato in cerca del Temple of Atal'Hakkar. Si diceva che si trovasse nella Swamp of Sorrows.$B$BVisto il mio stato fragile, ho sorvolato i cieli in grifone per cercarlo, ma non l'ho mai trovato.$B$BDai una mano a un vecchio nano? Magari tu avrai più fortuna a piedi.",
  obj = "Brohann Caskbelly, a Stormwind, vuole che tu cerchi il Temple of Atal'Hakkar.",
  progress = "Ho girato il mondo, dalle giungle di Azeroth alle cime innevate di Khaz Modan.$B$BMai prima d'ora avevo chiesto aiuto nelle mie avventure. Ma le mie vecchie ossa sono stanche.$B$BNiente mi renderebbe più soddisfatto che sapere di aver portato a termine la mia ultima impresa per la Lega degli Esploratori.$B$BSe fossi così gentile da aiutarmi a cercare il Temple of Atal'Hakkar, $C, te ne sarei molto grato.$B$BPerlustra la Swamp of Sorrows e torna a riferirmi quello che hai trovato!",
  reward = "Il Temple of Atal'Hakkar è sprofondato sotto il Pool of Tears? E circondato dallo stormo dei draghi verdi?$B$BUna scoperta incredibile, $C. Ma è chiaro che qualcosa è andato terribilmente storto.",
  en_title = "In Search of The Temple",
  en_obj = "Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.",
}
T[1449] = {
  title = "Verso le Hinterlands",
  desc = "Come ti ho detto prima, ho cercato di esplorare il tempio da solo, dall'alto. Be', non ero proprio solo.$B$BSono andato alla famosa voliera dei grifoni dell'Aerie Peak, nelle Hinterlands. Lì ho chiesto l'aiuto di uno dei loro piloti migliori. Il pilota è caduto dalla sua cavalcatura, giù nella palude...$B$BAlla mia età il nome di quel poveretto mi sfugge. Il capo della voliera se lo ricorderà di sicuro.$B$BVa' laggiù e cerca Falstad Wildhammer.$B$BDobbiamo scoprire che fine ha fatto quel pilota.",
  obj = "Parla con High Thane Falstad Wildhammer all'Aerie Peak, nelle Hinterlands.",
  reward = "Che vuoi, $Gragazzo:ragazza;? Non vedi che ho dei problemi da sistemare qui? Chi ha tempo di stare lì a chiacchierare con $Gun:una; $R $Gchiacchierone:chiacchierona;?$B$BI troll sbucano da tutte le parti! Sbrigati.",
  en_title = "To The Hinterlands",
  en_obj = "Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.",
}
T[1453] = {
  title = "Affari dei Reclaimers a Desolace",
  desc = "C'è del lavoro da fare a Desolace, $N. È un posto atroce, infestato dai centauri e da altre bestiacce. Ma se cerchi una buona settimana di lavoro onesto, va' là, incontra Kreldig Ungor e digli che ti mando io.$B$BLo trovi rintanato a Nijel's Point: è un piccolo accampamento accogliente nascosto tra le montagne della Desolace settentrionale. Se entri dalle Stonetalon Mountains, va' semplicemente a est. È facile non vederlo, quindi tieni gli occhi aperti.",
  obj = "Parla con Kreldig Ungor, a Desolace.",
  reward = "Che piacere vedere che ai Reclaimers non manca il lavoro, né gente disposta a dare una mano.$B$BIo sono Kreldig, $N. Hai fatto una mossa furba a dare una mano ai Reclaimers. Di questi tempi tutti hanno bisogno di qualcosa: chi ha perso un cimelio di famiglia, chi un oggetto magico, chi una persona cara. Non si sa mai. Ma finché ci sono i Reclaimers, non c'è motivo che qualcuno non ritrovi quel che ha perso, al giusto prezzo.",
  en_title = "Reclaimers' Business in Desolace",
  en_obj = "Speak to Kreldig Ungor in Desolace.",
}
T[1454] = {
  title = "Il naufragio di Karnitol",
  desc = "Il mio primo incarico è per il mago Karnitol, un nobile di qualche tipo a Stormwind. Pare che la sua nave sia stata attaccata dai giganti marini al largo della costa, nel nord-ovest di Desolace. Lui e i suoi servitori hanno cercato di portare a riva uno dei suoi forzieri più preziosi, ma quando i giganti marini hanno attaccato in massa, ha scelto di abbandonarlo e di teletrasportare sé stesso e i servitori al sicuro.$B$BVuole che troviamo il forziere e il suo contenuto e che glieli riportiamo a Stormwind.",
  obj = "Trova Karnitol's Chest, a Desolace.",
  reward = "Noti che il forziere non sembra danneggiato dall'acqua.$B$BLa seconda cosa che noti è che il coperchio è stato forzato, e qualunque trappola magica fosse stata messa a proteggerlo è scattata da tempo: lo si capisce chiaramente dai segni di bruciatura lungo i bordi.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Find Karnitol's Chest in Desolace.",
}
T[1455] = {
  title = "Il naufragio di Karnitol",
  desc = "Ti prendi qualche momento per capire che cosa abbia scardinato il forziere, e noti lungo i lati e sul coperchio dei graffi lunghi e profondi, segno che qualcosa di diverso da un uomo o da un gigante si è interessato al forziere. I segni non sembrano fatti da un pugnale o da una spada.$B$BFrugando nel forziere, scopri che è completamente vuoto.$B$BNon avendo altro da fare, chiudi il forziere e ti prepari ad andartene. Kreldig sarà deluso.",
  obj = "Torna da Kreldig Ungor, a Desolace.",
  reward = "$GBentornato:Bentornata; a Nijel's Point, $N. Allora, dimmi cosa hai trovato.$B$BCosa!? Niente? Temo che un forziere vuoto non ci farà pagare.$B$BRaccontami di più di quei segni che hai visto... di quei tagli.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Return to Kreldig Ungor in Desolace.",
}
T[1456] = {
  title = "Il naufragio di Karnitol",
  desc = "Interessante.$B$BBeh, forse non abbiamo ancora perso ogni speranza.$B$BLungo quella stessa costa, ma più a nord, vicino alla Ranazjar Isle, ci sono delle rovine degli elfi della notte in fondo all'oceano. Una tribù di naga, gli Slitherblade, ci ha fatto casa. Credo che sia la nostra carta migliore.$B$BSe un gruppo di esploratori si è spinto così a sud, doveva essere piuttosto potente. Se vuoi trovare gli effetti personali di Karnitol, io comincerei dai naga più potenti: i tidehunter o le sea witch.",
  obj = "Trova Karnitol's Satchel e riportala a Kreldig Ungor, a Desolace.",
  progress = "Senza offesa per chiunque sia questo Nijel, ma questo accampamento non è il posto più comodo in cui abbia mai passato una notte, se capisci cosa intendo, $N.",
  reward = "Fantastico, $N! Hai trovato gli effetti personali di Karnitol!$B$BQuei maledetti naga, sempre a creare guai. Credo che preferirei passare la vita in guerra con l'Orda piuttosto che dover affrontare quelli della loro specie. Hai reso un grande servizio ai Reclaimers.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace.",
}
T[1457] = {
  title = "Il naufragio di Karnitol",
  desc = "Riporta le cose di Karnitol a Roetten, a Ironforge, e lui ti pagherà per il lavoro ben fatto.$B$BAhah, se non fai attenzione, sarà così contento di te che ti chiederà di unirti a noi a tempo pieno.$B$BDi nuovo, ottimo lavoro, $N.$B$BFa' attenzione sulla via del ritorno, e non metterci troppo: Karnitol non è il più paziente degli uomini, ma è comunque molto generoso.",
  obj = "Porta Karnitol's Satchel a Roetten Stonehammer, a Ironforge.",
  progress = "Gli affari vanno a gonfie vele, $N, e non ho molto tempo per le domande. Se hai affari con i Reclaimers, sentiamo. Altrimenti dovrò chiederti di parlare con uno dei miei sottoposti: sono abbastanza bravi a sbrigare le cose da queste parti.",
  reward = "Ah, la faccenda di Karnitol a Desolace. Eccellente!$B$BQuindi il forziere è stato distrutto, ma gli oggetti ci sono tutti, eh? Beh, lascerò che sia lui a giudicare. Una cosa buona di questo mio giro d'affari è che, se non sono soddisfatti, posso mandarli a quel paese! Contano su di noi per ritrovare la loro roba... non per assicurarci che sia tutta bella e in buono stato quando la riavranno.$B$BBuon lavoro, $N. Vediamo di farti pagare.",
  en_title = "The Karnitol Shipwreck",
  en_obj = "Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge.",
}
T[1458] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Uno dei miei compiti qui fuori è procurare dei reagenti per Leftwitch, un mago gnomo di Kharanos. Roetten pensa che siano soldi facili, visto che siamo già qui. Non gli importa granché che siamo già a corto di personale.$B$BLe prime cose sulla sua lista dovrebbero essere abbastanza facili da trovare, e ci sarebbe un bel gruzzolo per chi mi dà una mano.$B$BMi servono corna e artigli dei satiri Hatefury, a est di qui. Portameli e cominceremo con il resto della lista.",
  obj = "Porta 10 Hatefury Claw e 10 Hatefury Horn a Kreldig Ungor, a Desolace.",
  progress = "Creature spregevoli, i satiri. Si racconta che siano in qualche modo legati agli elfi della notte, ma non so se ci credo davvero.$B$BCredo che quella storia venga da quell'elfo che li ha trascinati nella guerra qualche anno fa. Da allora il mondo non è più stato lo stesso. Molto più pericoloso, e molto più spaventoso.",
  reward = "Bene, bene, $N. Non so se siano di buona qualità, ma se Leftwitch voleva un tipo particolare, avrebbe dovuto specificarlo prima di mandare i Reclaimers quaggiù.$B$BChe ne dici di passare alla prossima voce della sua lista?",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace.",
}
T[1459] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "La prossima voce sulla lista di Leftwitch è... vediamo... hmm. Ah, eccola.$B$BAbbastanza semplice, ma le sue istruzioni sono piuttosto precise. Gli serve veleno di scorpashi e pelle di kodo. Le note in piccolo dicono che tutti e due devono venire da creature specifiche: il veleno deve venire da uno scorpashi qualsiasi, e la pelle da un kodo vecchio, non da quelli morenti o antichi.$B$BI maghi, te lo dico io, certe cose che vogliono... sono proprio strane.",
  obj = "Porta 7 fiale di Scorpashi Venom e 3 Aged Kodo Hide a Kreldig Ungor, a Desolace.",
  progress = "Mi dispiace di non averti saputo dire dove trovare i kodo o gli scorpashi. Non conosco molto bene la zona, e non ho avuto tempo di esplorarla.",
  reward = "Il tuo aiuto qui è una manna, $N. Stai dimezzando come minimo il tempo che devo passare qui a Desolace. Con il tuo aiuto, in un attimo sarò di nuovo a Ironforge a scaldarmi i piedi.$B$BQuando avremo sistemato questa lista e sarò di nuovo a casa, vieni a trovarmi: una birra te la offro di sicuro.$B$BMa fino ad allora, raccogliamo il resto di questi reagenti.",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring 7 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace.",
}
T[1462] = {
  title = "Earth Sapta",
  obj = "Parla con Seer Ravenfeather per avere un'altra Earth Sapta.",
  reward = "Prendila, e ricorda: è sacra.",
  en_title = "Earth Sapta",
  en_obj = "Speak to Seer Ravenfeather for another Earth Sapta.",
}
T[1463] = {
  title = "Earth Sapta",
  obj = "Parla con Canaga Earthcaller per avere un'altra Earth Sapta.",
  reward = "Te ne do una in buona fede. Hai già dimostrato il tuo valore una volta, ma secondo me in futuro dovresti stare più $Gattento:attenta;.",
  en_title = "Earth Sapta",
  en_obj = "Speak to Canaga Earthcaller for another Earth Sapta.",
}
T[1464] = {
  title = "Fire Sapta",
  obj = "Parla con Telf Joolam per avere un'altra Fire Sapta.",
  reward = "Che il fuoco arda nel tuo cuore, $N.$B$BGli elementi ti aspettano.",
  en_title = "Fire Sapta",
  en_obj = "Speak to Telf Joolam for another Fire Sapta.",
}
T[1465] = {
  title = "La ricerca di Vahlarriel",
  desc = "Continuando a perquisire il carro trovi non solo un ciondolo, ma anche delle impronte che si allontanano verso sud. In lontananza vedi il fumo che sale da un grande forte. È il fumo di un fuoco acceso di proposito, non di edifici in fiamme, e l'istinto ti dice che i Malem, se ancora vivi, sono stati portati in quella direzione.$B$BPensi che Vahlarriel, a Nijel's Point, non debba solo vedere il ciondolo che hai trovato, ma anche sapere dei segni di vita a sud.",
  obj = "Riporta il Malem Pendant a Vahlarriel Demonslayer, a Desolace.",
  reward = "Esasperante! Tutto questo disastro!$B$BEntrambi erano stati avvertiti di quanto sarebbe stato pericoloso venire qui. Ora sono spariti tutti e due... o peggio.$B$BHai detto di aver visto delle tracce dirette verso un forte qui vicino? Potrebbe essere la nostra carta migliore.$B$BDa quello che dice la gente del posto, quella fortezza è infestata da membri della Burning Blade, orchi che si sono votati alla causa dei demoni. Forse non rappresentano ciò in cui crede la maggior parte dell'Orda, ma sono malvagi e ti uccideranno a vista se ti sorprendono a spiare.",
  en_title = "Vahlarriel's Search",
  en_obj = "Return the Malem Pendant to Vahlarriel Demonslayer in Desolace.",
}
T[1466] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Questa è l'ultima voce, e non ti mentirò: non è una bella cosa. Mi aspetto anche che ti porti via un po' più di tempo delle altre.$B$BAllora, basta avvertimenti, cominciamo. Leftwitch dice che gli servono: dieci cervelli di mana eater, mage hunter o ley hunter. Dieci Nether Wing da una nether maiden, sister o sorceress. E... dieci fiale di Doomwarder Blood da un doomwarder captain o lord.$B$BAbbastanza semplice, eh? Accidenti... se vuoi rinunciare a questa, ti capirei.",
  obj = "Porta 10 Felhound Brain, 10 Nether Wing e 10 fiale di Doomwarder Blood a Kreldig Ungor, a Desolace.",
  progress = "Non sapevo nemmeno che a Desolace ci fossero queste cose demoniache. L'ultima volta che ho letto qualcosa in proposito, i centauri erano praticamente i padroni di queste terre, da quando gli elfi della notte avevano fatto i bagagli ed erano partiti anni fa.$B$BMi chiedo perché si siano stabiliti qui, e come.",
  reward = "Sul serio? Non l'avrei mai detto. Sei incredibile, $N. Affrontare dei demoni per gli esperimenti di un mago, e per giunta tornare $Gtutto intero:tutta intera;. Ottimo lavoro!$B$BParlerò di te a Roetten di persona quando tornerò a Ironforge.",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring 10 Felhound Brains, 10 Nether Wings, and 10 vials of Doomwarder Blood to Kreldig Ungor in Desolace.",
}
T[1467] = {
  title = "Reagenti per la Reclaimers Inc.",
  desc = "Per ricevere la paga, dovrai tornare a Ironforge e parlare con Roetten in persona. Sarà comunque felice di togliersi di mezzo il pacco di Leftwitch. Dagli solo questo e dovrebbe bastare per avere il tuo bottino.$B$BE non preoccuparti, metterò comunque una buona parola per te quando tornerò. Non dovrei restare a Desolace ancora per molto.",
  obj = "Riporta Leftwitch's Package a Roetten Stonehammer, a Ironforge.",
  progress = "Salute, $N. Gli affari vanno a gonfie vele, il suono delle incudini risuona per tutta Ironforge, i mantici attizzano i fuochi e mia moglie mi sta preparando una torta per il dessert dopo la cena di stasera. La vita potrebbe essere più bella?",
  reward = "Ah, il pacco per Leftwitch da Desolace. Eccellente. Apprezzo il lavoro, e la tua puntualità, $C. Sono contento di averti avuto con noi almeno per questo piccolo lavoro.$B$BHo il tuo pagamento proprio qui. Che si sappia: la Reclaimers Inc. paga sempre bene per una dura settimana di lavoro.",
  en_title = "Reagents for Reclaimers Inc.",
  en_obj = "Bring Leftwitch's Package back to Roetten Stonehammer in Ironforge.",
}
T[1468] = {
  title = "Settimana dei Bambini",
  desc = "Vuoi aiutarci qui all'orfanotrofio? Che il cielo ti benedica, $Gamico:amica;: il tuo aiuto durante la Settimana dei Bambini sarà prezioso.$B$BPrendi questo fischietto. Potrai usarlo solo per poco tempo, di solito non più a lungo della Settimana dei Bambini stessa. Quando lo usi, potrai parlare con il bambino di cui hai accettato di occuparti. Se lo usi di nuovo, il bambino se ne andrà.$B$BForza, $N, usa il fischietto e conosci il tuo protetto! Sono sicura che il bambino non vedrà l'ora di conoscerti.",
  obj = "Usa lo Human Orphan Whistle per parlare con il bambino di cui ti occuperai durante la Settimana dei Bambini.",
  reward = "Ehm... ciao. Mi chiamo Randis, e immagino che sarai tu a occuparti di me? Sei $Gun avventuriero:un'avventuriera;, come lo erano la mia mamma e il mio papà. Sono contento di conoscerti.$B$BSpero che ci divertiremo un sacco insieme. Ho alcune cose che vorrei fare, e la matrona dice che durante questa settimana sarai come $Gun fratello maggiore:una sorella maggiore; per me. Mi piacerebbe un sacco, sì, $Gsignore:signora;.",
  en_title = "Children's Week",
  en_obj = "Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week.",
}
T[1470] = {
  title = "Squarciare il velo",
  desc = "Salve, $Gfigliolo:figliola;. Vedo che sei ancora $Gacerbo:acerba; nelle vie $Gdel:della; $C, e il potere ti sfugge ancora di mano. Percepisco la tua voglia di imparare.$B$BE imparerai.$B$BNon c'è forza nell'ignoranza. La conoscenza è il nostro potere più grande. Applicandola possiamo controllare le magie caotiche e gli esseri del vuoto, piegandoli alla nostra volontà.$B$BTi mostrerò come vincolare un servitore alla tua volontà, ma prima devi portarmi tre teschi dei Rattlecage Skeleton vicino alla fucina abbandonata.",
  obj = "Porta a Venya Marthand 3 Rattlecage Skull.",
  progress = "Il tuo potere ora è poco, anche se sospetto che tu ne intuisca già le possibilità.$B$BPerfino i morti potrebbero sentirsi vivi, con quel potere che ci scorre dentro.",
  reward = "Anche se non sei ancora $Gstato messo:stata messa; alla prova e sei agli inizi del tuo apprendistato, hai dimostrato di possedere abilità sufficienti a padroneggiare l'evocazione e il vincolo di un Imp. Non lasciarti ingannare dalle dimensioni di un Imp. Anche se gli manca la forza fisica, possiede poteri e un'astuzia che ti saranno molto utili.$B$BAscoltami con attenzione, $N, perché non ripeterò questa lezione, e lascerò a te il compito di padroneggiarla.",
  en_title = "Piercing the Veil",
  en_obj = "Bring Venya Marthand 3 Rattlecage Skulls.",
}
T[1471] = {
  title = "Il vincolo",
  desc = "Avrai certamente visto il cerchio di evocazione qui sotto? Solo lì potrai richiamare un Voidwalker non vincolato.$B$BCon queste rune potrai richiamarlo, e poi dovrai dominarlo con la forza delle armi e della magia.$B$BUna volta sottomesso, sarà al tuo servizio. Allora vieni da me, e ti spiegherò l'incantesimo di evocazione, così che possa servirti per qualunque scopo tu voglia.",
  obj = "Usando le Runes of Summoning, evoca e sottometti un Voidwalker, poi riporta le Runes of Summoning a Carendin Halgar, nel Magic Quarter dell'Undercity.",
  progress = "Mi aspetto di sentire del tuo successo, $N. Se dovessi fallire, però, deludere le mie aspettative sarà l'ultima delle tue preoccupazioni.",
  reward = "Hai fatto bene, $N. Ora ti trasmetterò l'incantesimo per evocare il Voidwalker.$B$BIl potere che ha scatenato contro di te ora è tuo da comandare. Usalo con saggezza.",
  en_title = "The Binding",
  en_obj = "Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity.",
}
T[1472] = {
  title = "Divoratrice di anime",
  desc = "Una Succubus è una divoratrice di anime, una distruttrice di cuori, una tentatrice di uomini. Una creatura di profonda malvagità, con la mente fissa su un solo scopo.$B$BNon può essere portata nel nostro mondo senza uno stimolo.$B$BPer questo usiamo la sua stessa forza contro di lei. Con i cuori di uomini buoni, uomini puri, uomini amorevoli, la Succubus non potrà resistere e passerà nel nostro mondo. Allora potrai dominarla e renderla tua.$B$BParla con il mio assistente, Godrick Farsan, nel Temple. Ti aiuterà a trovare l'esca.",
  obj = "Parla con Godrick Farsan, nel Temple of the Damned.",
  reward = "Ti manda Carendin? Allora sei $N.$B$BNon prendermi alla leggera perché ho perso la vista. Ora vedo le cose che si celano dietro, con una chiarezza che non avevo mai conosciuto. Quella che un tempo credevo una maledizione, ora è una benedizione.",
  en_title = "Devourer of Souls",
  en_obj = "Speak with Godrick Farsan in the Temple of the Damned.",
}
T[1473] = {
  title = "Creatura del vuoto",
  desc = "Sembra che tutti siano d'accordo sul fatto che tu sia $Gpronto:pronta; a imparare a evocare un Voidwalker.$B$BÈ un essere creato dal caos che si trova oltre: se ne evochi uno ma non riesci a controllarlo, verrai $Gfatto:fatta; a pezzi.$B$BIl primo Voidwalker fu evocato da Egalin, e il procedimento è spiegato nel suo grimorio.$B$BPurtroppo ce l'ha rubato un agente della Crociata Scarlatta, che lo tiene nascosto nella sua base, in una torre a ovest. Portamelo, e ti trasmetterò la conoscenza.",
  obj = "Recupera Egalin's Grimoire e portalo a Carendin Halgar, nel Temple of the Damned.",
  progress = "Egalin è stato il maestro che mi ha istruito. Gli bastava un'occhiata per comandare il Voidwalker che aveva evocato.$B$BQuando venne il mio turno di provarci, peccai di presunzione. Non prendere alla leggera i poteri che maneggi, $N: possono consumare anche chi sta in guardia.",
  reward = "Ah, è eccellente. Con ogni probabilità, Perrine ignorava il vero potere del libro ammuffito che ci aveva rubato.$B$BNon ci sfuggirà più di mano. Osserva, $N, la struttura dell'incantesimo, il modo in cui il tuo potere deve essere incanalato.",
  en_title = "Creature of the Void",
  en_obj = "Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned.",
}
T[1474] = {
  title = "Il vincolo",
  desc = "Usando questi cuori, lancia un incantesimo nel cerchio di evocazione per aprire un varco da cui la Succubus possa passare. Ora i tuoi poteri sono maggiori, e ti serviranno tutti per sconfiggere la Succubus.$B$BGuardati dal suo fascino, $N: molte menti forti sono state piegate alla sua volontà. Una volta sconfitta, la Succubus tornerà nel vuoto, e io ti insegnerò l'incantesimo per richiamarla ai tuoi ordini.",
  obj = "Usando i Pure Hearts, evoca e sottometti una Succubus, poi riporta i Pure Hearts a Carendin Halgar, nel Magic Quarter dell'Undercity.",
  progress = "Tra i poteri che vengono da oltre il vuoto, la Succubus è uno dei più pericolosi, perché i deboli sono i più facili da rigirare come vuole.$B$BRicordalo, ora e in futuro.",
  reward = "Ancora una volta hai fatto bene, $N. Era da parecchio tempo che non vedevo $Gun giovane stregone:una giovane strega; con un potenziale come il tuo. Ti assicuro che continuerò a seguire i tuoi progressi, e a prepararti e aiutarti nelle tue prove future.$B$BPer ora, lascia che ti mostri l'incantesimo di evocazione per la Succubus che hai appena dominato.",
  en_title = "The Binding",
  en_obj = "Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.",
}
T[1476] = {
  title = "I cuori dei puri",
  desc = "Uomini d'onore e di bontà? Esiste davvero un uomo così?$B$BCi sono volute molte ricerche, ma mettendo insieme frammenti di storie sentite qua e là, sono riuscito a trovare due uomini che dovrebbero andare bene.$B$BIl primo è Dalin Forgewright, che si è dedicato alla cura dei profughi di Lordaeron, respinti dalla loro stessa gente al Greymane Wall.$B$BL'altro è Comar Villard, un uomo che resta fedele al suo amore perduto e vaga per le Wetlands in cerca di un segno di sua moglie.$B$BConsegna i loro cuori a Carendin. Ma prima, lascia che ti mostri le tue prede.",
  obj = "Porta i cuori di Dalin Forgewright e di Comar Villard a Carendin Halgar, nel Temple of the Damned.",
  progress = "Sono piacevolmente sorpreso dalla rapidità dei tuoi progressi finora, $N. Portami i cuori e mi stupirai ancora una volta.",
  reward = "Il cuore di un uomo buono sembra uguale a qualsiasi altro, visto così, non trovi?$B$BForse abbiamo una visione un po'... diversa... della cosa. Questi andranno bene, comunque. Non ho dubbi che una Succubus sarebbe attratta dalla loro purezza.",
  en_title = "Hearts of the Pure",
  en_obj = "Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned.",
}
T[1477] = {
  title = "Rifornimenti vitali",
  desc = "I nostri maghi stanno conducendo delle ricerche a Nethergarde Keep, nelle Blasted Lands: ricerche vitali per capire i Dark Portal. Hanno bisogno di rifornimenti quasi continui, ma la nostra linea di rifornimento verso Nethergarde è fragile.$B$BDevi aiutarci a fare in modo che i rifornimenti arrivino a Nethergard. Presentati a Watchmaster Sorigal, a Darkshire, e fa' quello che ti chiede. Questo compito ti porterà in terre ostili, $N. Preparati.",
  obj = "Parla con Watchmaster Sorigal.",
  reward = "Ti ha mandato Andromath? Molto bene. Ho un compito importante per te...",
  en_title = "Vital Supplies",
  en_obj = "Speak with Watchmaster Sorigal.",
}
T[1478] = {
  title = "La convocazione di Halgar",
  desc = "Ah, $N! Ho appena saputo da Carendin Halgar che vorrebbe vederti per continuare il tuo addestramento.$B$BDovresti essere $Gfiero:fiera; di te $Gstesso:stessa;, $N. Non capita tutti i giorni che il maestro Halgar ritenga opportuno istruire di persona $Gun giovane stregone:una giovane strega;.$B$BLo troverai nel Magic Quarter dell'Undercity, vicino al Temple of the Damned.",
  obj = "Parla con Carendin Halgar, nell'Undercity.",
  reward = "Bene, vedo che Ageron ti ha trovato, $N. Non perdiamo tempo in chiacchiere e convenevoli e concentriamoci sul tuo addestramento. Hai ancora molto da imparare.",
  en_title = "Halgar's Summons",
  en_obj = "Speak with Carendin Halgar in the Undercity.",
}
T[1479] = {
  title = "Il Bough of the Eternals",
  desc = "Ho sentito storie su come gli elfi della notte tengano la loro banca in un albero, uno che sembra un orso! Troppo forte! Gli elfi della notte sono simpatici, con quella loro passione per la natura e tutto il resto, ma gli orsi sono proprio fantastici!$B$BMi porteresti a vedere l'albero-orso a Darnassus, per piacere? C'è una nave che ci porta lì vicino, e non dovrebbe volerci molto. Per piacere, per piacere, per piacere!",
  obj = "Porta l'orfano alla banca di Darnassus. La banca è scavata in un albero noto come Bough of the Eternals.",
  progress = "Siamo arrivati?",
  reward = "Wow, era ancora più bello di come me l'ero immaginato: il Bough of the Eternals! Non pensavo fosse così grande, e invece lo era! Hai visto anche l'uccello in cima?! Chissà come hanno fatto a dare quella forma ai rami!$B$BGrazie di avermi portato a Darnassus, $N. Sei $Gfantastico:fantastica;!",
  en_title = "The Bough of the Eternals",
  en_obj = "Take the orphan to the bank of Darnassus.  The bank itself is hollowed out of a tree known as the Bough of the Eternals.",
}
T[1480] = {
  title = "Il corruttore",
  desc = "La pelle strappata ha un odore di marcio ed è sorprendentemente flessibile per qualcosa che sembra secco e fragile.$B$BMentre la srotoli, vedi chiaramente su un lato dei segni rossi di una qualche lingua. In fondo alla pelle c'è un simbolo molto chiaro che immagini sia una specie di firma.$B$BForse Maurin potrebbe dirti qualcosa di più?",
  obj = "Porta la Flayed Demon Skin a Maurin Bonesplitter, a Desolace.",
  progress = "Quelli della Burning Blade cominciano a capire quanto siano davvero deboli. Le loro magie sono patetiche, la loro forza misera.$B$BIl loro unico potere viene da coloro che servono, non da una vera comprensione del potere e della conoscenza.",
  reward = "Hmm, queste rune sono davvero una lingua, $N, una lingua antica. Somigliano vagamente alla lingua Eredun, ma le differenze sono enormi. Se non mi sbaglio, questo è una specie di contratto... Qui, sì, questo simbolo è la firma del demone: Lord Azrethoc.",
  en_title = "The Corrupter",
  en_obj = "Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.",
}
T[1481] = {
  title = "Il corruttore",
  desc = "Credo di poter trovare questo signore dei demoni, con i reagenti giusti.$B$BSe è davvero potente come sospetto, mi serviranno oggetti presi da creature letali. Ma tu agisci in nome del Capoguerra, quindi di sicuro accetterai il mio compito.$B$BPer prima cosa dovrò spezzare le protezioni che ha contro la divinazione. Per questo mi servirà lo scalpo di un satiro, ma non di un satiro qualsiasi. Lo scalpo deve venire da un Hatefury Shadowstalker.$B$BCercali tra le antiche rovine nel nord-est di Desolace.",
  obj = "Porta uno Shadowstalker Scalp a Maurin Bonesplitter, a Desolace.",
  progress = "Non portarmi uno scalpo sbagliato, $C. Usare i reagenti sbagliati potrebbe costarci la vita. Il signore dei demoni potrebbe avere su di sé incantesimi di riserva per uccidere chi tenta di spiarlo con la divinazione.$B$BIl destino mi ha già inflitto abbastanza dolore.",
  reward = "Gli shadowstalker non sono riusciti a ucciderti, $C. Notevole... davvero notevole.$B$BQuesto scalpo andrà benissimo per il mio incantesimo. Mentre eri via, ho potuto raccogliere alcuni degli altri reagenti necessari per l'incantesimo.$B$BCi sono quasi. Mi serve solo un catalizzatore per l'incantesimo: qualcosa che proietti un'immagine del signore dei demoni e del luogo in cui si trova.",
  en_title = "The Corrupter",
  en_obj = "Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.",
}
T[1482] = {
  title = "Il corruttore",
  desc = "Un Oracle Crystal andrebbe benissimo. I naga li fabbricano perché li usino i loro oracoli.$B$BA nord-ovest di qui, lungo la costa, c'è una vasta barriera corallina che i naga hanno preso come dimora quando si trovano così vicini alla riva. Là troverai i loro oracoli. Gli Slitherblade sono letali e non accoglieranno di buon grado le tue intrusioni, quindi fa' attenzione e sbrigati.$B$BQuando tornerai, vedremo di trovare questo signore dei demoni, Azrethoc.",
  obj = "Porta un Oracle Crystal a Maurin Bonesplitter, a Desolace.",
  progress = "Sono pronto per l'Oracle Crystal, $C. Trovare e distruggere questo Lord Azrethoc ci farebbe guadagnare parecchio favore presso il Capoguerra, a tutti e due. Faremmo bene a lavorare insieme, e a farlo in fretta, così da perseguire i nostri scopi e ingraziarci il Capoguerra.",
  reward = "Un prezioso Oracle Crystal... perfetto... bellissimo. Davvero.$B$BCominceremo subito. Trovare questo signore dei demoni dev'essere la nostra prima preoccupazione, e ucciderlo richiede tutta la nostra attenzione.$B$BFai un passo indietro, $C, e vediamo che cos'è questo demone e dove si può trovare.",
  en_title = "The Corrupter",
  en_obj = "Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.",
}
T[1483] = {
  title = "Ziz Fizziks",
  desc = "La Venture Company ci ha rubato molte delle migliori teste goblin, ma ogni tanto capita l'occasione di rubarne indietro qualcuna.$B$BTempo fa la squadra della Venture Company nelle Stonetalon Mountains ha assunto Gerenzo Wrenchwhistle — uno gnomo! L'altro loro ingegnere, Ziz Fizziks, ci è rimasto talmente male che mi ha supplicato di trovargli un nuovo impiego nella Tinkers' Union. Gli ho affidato qualche incarico, ma potrebbe aver bisogno d'aiuto.$B$BMagari potresti andare a dargli un'occhiata per me? Sta al margine occidentale di Windshear Crag.",
  obj = "Parla con Ziz Fizziks, a Windshear Crag.",
  reward = "Pensavo che i pezzi grossi della Venture Company fossero degli aguzzini, poi ho conosciuto Sputtervalve, il più crudele di tutti!$B$BAh! Anche se è sempre meglio che restare senza lavoro, immagino... O peggio, lavorare con quel Gerenzo. Se sei qui per aiutare, ho qualcosa da farti fare.",
  en_title = "Ziz Fizziks",
  en_obj = "Speak with Ziz Fizziks in Windshear Crag.",
}
T[1484] = {
  title = "Il corruttore",
  desc = "Questa creatura è molto più pericolosa di quanto avessi previsto. Di sicuro Takata dubita delle mie capacità di affrontare una creatura simile, e sarebbe un'offesa al suo onore non informarlo di quello che è appena successo.$B$BParla con lo spadaccino, digli che sei $Gdisposto:disposta; a uccidere il demone se lui te lo permette, ma non insistere troppo. È meglio se pensa che l'idea sia sua.",
  obj = "Parla con Takata Steelblade, a Desolace.",
  reward = "Ho visto quello che è appena successo con Maurin e il signore dei demoni. Quella creatura, anche solo come apparizione, sembra avere più potere del mio compagno stregone. Mi chiedo: sarà all'altezza di sconfiggere il mostro? Servirei meglio il Capoguerra se andassi io stesso, ma con le responsabilità che ho qui, disonorerei il mio clan se voltassi le spalle ai miei doveri per combattere questo male in nome del mio onore.",
  en_title = "The Corrupter",
  en_obj = "Speak to Takata Steelblade in Desolace.",
}
T[1485] = {
  title = "I Vile Familiar",
  desc = "Gli stregoni che ci hanno preceduto si sono guadagnati la sfiducia dell'Orda, e anche se siamo tollerati, non siamo amati.$B$BQuesto però non ha avvicinato gli stregoni tra loro, perché molti scelgono di vivere appartati, dilettandosi con la magia da soli. Non cercherò di condurti su una strada o sull'altra, ma solo di aiutarti a crescere.$B$BPrima che ti insegni l'arte dell'evocazione, portami sei teste dei Vile Familiar dalla caverna a nord-est.",
  obj = "Porta 6 Vile Familiar Head a Ruzan.",
  progress = "È importante che tu sappia controllare gli esseri che evochi con la tua magia. Sono così pochi quelli interessati a imparare le vie $Gdel:della; $C che non rischierei la tua vita insegnandoti qualcosa prima che tu sia $Gpronto:pronta;.",
  reward = "Durante il tuo addestramento da $C, imparerai a richiamare esseri di molti tipi. Alcuni potrebbero non sembrarlo, ma sono tutti strumenti utili.$B$BNon lasciarti ingannare dalle piccole dimensioni dell'Imp. Come avrai certamente notato, resta un avversario temibile.",
  en_title = "Vile Familiars",
  en_obj = "Bring 6 Vile Familiar Heads to Ruzan.",
}
T[1486] = {
  title = "I Deviate Hide",
  desc = "Mentre Naralex scendeva sempre più a fondo nel suo incubo, una strana stirpe di bestie è salita da sotto le Barrens dentro le Wailing Caverns.$B$BQueste creature deviate hanno proprietà strane, ultraterrene. Sono malvagie per natura, ma secondo me dalla loro esistenza qui in Kalimdor può venire qualcosa di buono. Credo che le loro pelli saranno particolarmente utili nella conciatura.$B$BSe te la senti, avventurati nelle grotte qui sotto e recupera qualche Deviate Hide.",
  obj = "Nalpak, nelle Wailing Caverns, vuole 20 Deviate Hide.",
  progress = "Mi interessa molto esaminare le pelli delle creature deviate che hanno infestato queste grotte. Hai avuto fortuna a raccoglierne qualcuna, $C?",
  reward = "I tuoi sforzi nel raccogliere queste pelli non passeranno inosservati, $N.$B$BGrazie per la tua dedizione.",
  en_title = "Deviate Hides",
  en_obj = "Nalpak in the Wailing Caverns wants 20 Deviate Hides.",
}
T[1487] = {
  title = "Sterminio dei deviate",
  desc = "Naralex aveva un fine nobile.$B$BIl nostro grande capo aspirava a entrare nell'Emerald Dream e ad aiutare queste terre dure a tornare la foresta rigogliosa che erano un tempo. Ma qualcosa è andato terribilmente storto.$B$BIl sogno di Naralex si è trasformato in un incubo e creature corrotte hanno cominciato ad abitare le caverne.$B$BMentre alcuni Disciples of Naralex cercano di svegliare il nostro maestro, io mi preoccupo di liberare queste grotte dalle bestie malvagie.$B$BAffronta le caverne, $N, e stermina la progenie dei deviate.",
  obj = "Ebru, nelle Wailing Caverns, vuole che tu uccida 7 Deviate Ravager, 7 Deviate Viper, 7 Deviate Shambler e 7 Deviate Dreadfang.",
  progress = "$N, noi Disciples of Naralex abbiamo bisogno del tuo aiuto. Il nostro numero si assottiglia, con il nostro maestro intrappolato nel suo incubo contorto. Non abbiamo le forze necessarie per affrontare le creature corrotte che ora infestano queste caverne.$B$BTi supplico, entra nelle grotte e fa' guerra alle creature deviate!",
  reward = "Da Disciple of Naralex, lodo il tuo coraggio, $N.$B$BIl tuo aiuto nel ripulire le caverne è il primo passo nella nostra lunga battaglia per vedere le Barrens risanate.$B$BGrazie, e che tu prosperi.",
  en_title = "Deviate Eradication",
  en_obj = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.",
}
T[1488] = {
  title = "Il corruttore",
  desc = "Anche se non so nulla di questo Lord Azrethoc, sono d'accordo con Maurin: va fermato, soprattutto se sta cercando di ottenere influenza sulla Burning Blade per i suoi scopi.$B$BHai già dimostrato di voler aiutare il Capoguerra, e mi fiderei di te per radunare un gruppo e uccidere il signore dei demoni e il suo servo stregone.$B$BQuando sei $Gpronto:pronta;, va' dritto a sud, e torna da me quando la minaccia sarà eliminata.",
  obj = "Uccidi Lord Azrethoc e Jugkar Grim'rod e torna da Takata Steelblade, a Desolace.",
  progress = "Gloria all'Orda, e morte ai nostri nemici, $N!$B$BI demoni di Desolace sono una minaccia più grande che mai. La mia speranza di tornare dal Capoguerra si affievolisce man mano che compaiono sempre più di quelle creature immonde.$B$BA volte vorrei che avessimo a che fare solo con i centauri.",
  reward = "Una vittoria possente per tutti noi, $N. Gioiamo del tuo successo. Ora confido che il nostro futuro qui non sia così cupo come pensavo un tempo.$B$BI demoni saranno uccisi, la Burning Blade fallirà nei suoi sforzi, e un giorno potremo avere di nuovo un posto da chiamare casa, al sicuro.",
  en_title = "The Corrupter",
  en_obj = "Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.",
}
T[1489] = {
  title = "Hamuul Runetotem",
  desc = "I gusci che mi hai portato hanno una corruzione, una che non avevo mai visto prima. Sono certo che la causa sia l'acqua delle oasi, e sento la confusione che provocano in questa terra. È come se la terra sognasse e non riuscisse a svegliarsi.$B$BLe Wailing Caverns devono essere l'origine della corruzione. Ma prima di andarci, parla con Hamuul Runetotem, il druido anziano. Gli ho mandato notizia di quello che succede nelle Barrens. È saggio, e può darti consiglio.$B$BLo troverai a Thunder Bluff, sull'Elder Rise.",
  obj = "Parla con Hamuul Runetotem.",
  reward = "Ti porgo il mio saluto, $N. Sei $Gil benvenuto:la benvenuta; qui, e ti consiglio di raccogliere tutte le tue forze. Perché l'incarico che ora ti mettiamo davanti... è terribile.",
  en_title = "Hamuul Runetotem",
  en_obj = "Speak with Hamuul Runetotem.",
}
T[1490] = {
  title = "Nara Wildmane",
  desc = "Sono entrato nella terra dei sogni, e ho sognato di una setta di druidi che abita nelle Wailing Caverns. Ho visto che un tempo i loro fini erano nobili, ma hanno perso la strada. Ora sono servi della corruzione che filtra nelle Barrens.$B$BSono vecchio e le forze mi vengono meno. Non potevo restare a lungo in quel luogo di sogno e so poco altro dei druidi corrotti. Ma Nara è giovane e il suo spirito è fiero. Lei è rimasta nel sogno quando io sono fuggito.$B$BParla con Nara. È nella tenda, là in fondo.",
  obj = "Parla con Nara Wildmane.",
  reward = "Sì, è vero. So dei druidi nelle Wailing Caverns. Ho visto le loro facce contorte e squamose. Conosco i loro crimini, e conosco i loro piani.$B$BDevi fermarli, $N.",
  en_title = "Nara Wildmane",
  en_obj = "Speak with Nara Wildmane.",
}
T[1491] = {
  title = "Bevande dell'intelligenza",
  desc = "Ok, i corni di raptor non hanno funzionato granché. Ma va bene — nessuno è diventato ricco al primo tentativo! E poi credo di aver trovato qualcosa che funzionerà ancora meglio nelle mie bevande dell'intelligenza!$B$BC'è una sostanza che si chiama Wailing Essence, e secondo me è la causa delle piante e degli animali strani delle Barrens. Procurami quella e la proverò nella mia bevanda!$B$BHo sentito che l'essenza si raccoglie nelle creature ectoplasmiche delle Wailing Caverns, a ovest. Caccia quelle creature e raccogli l'essenza.",
  obj = "Porta 6 porzioni di Wailing Essence a Mebok Mizzyrix, a Ratchet.",
  progress = "Dov'è la mia Wailing Essence?",
  reward = "Ottimo, ce l'hai! Non vedo l'ora di provarla. Questa mi farà fare una fortuna, lo so e basta!$B$BGrazie, $N. Prendi questo, e quando sarò ricco te ne manderò dell'altro, promesso!",
  en_title = "Smart Drinks",
  en_obj = "Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.",
}
T[1492] = {
  title = "Wharfmaster Dizzywig",
  desc = "Devo spedire una cassa di pozioni, reagenti e altri oggetti ai miei soci nel Vecchio Mondo. Ho poco tempo per portarla personalmente al molo di Ratchet, e l'ultima carovana è già partita.$B$BSe puoi, porta questa cassa a Wharfmaster Dizzywig. Lui farà in modo che venga caricata sulla prossima nave diretta a Blackwater Cove.",
  obj = "Porta la Secure Crate a Wharfmaster Dizzywig a Ratchet.",
  progress = "Cercate un passaggio sulla prossima nave, o avete qualcosa da spedire a bordo?",
  reward = "Una cassa abbastanza piccola. Sì, dovrei riuscire a trovarle posto a bordo. La nave salpa con la prossima marea, spero che vada bene. Eccellente. Lasciate che la annoti sul mio registro.$B$BTutto sistemato! Buona giornata a te, $C.",
  en_title = "Wharfmaster Dizzywig",
  en_obj = "Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet.",
}
T[1498] = {
  title = "La via della difesa",
  desc = "Per noi guerrieri, uno dei compiti più importanti è... la protezione. Siamo lo scudo dell'Orda, e teniamo al sicuro i nostri fratelli più deboli. Se vuoi unirti alle nostre file, devi dimostrarmi quanto vali.$B$BVa' a Thunder Ridge, in Durotar, dove vivono i Lightning Hide e i Thunder Lizard. Caccia quelle bestie! Dimostrami che sei più resistente di loro! Affronta i loro attacchi e portami un mucchio delle loro Singed Scale come prova.$B$BFallo, e allora ti insegnerò.",
  obj = "Porta 5 Singed Scale a Uzzek, al Far Watch Post, nelle Barrens.",
  progress = "Hai le scaglie, $N? Se non riesci a resistere agli attacchi dei Thunder Lizard, i miei insegnamenti non ti serviranno a niente.",
  reward = "Ah. Vedo che hai sconfitto i Thunder Lizard, e questo dimostra che sei resistente. Ora ti mostrerò come una pelle dura e movimenti accorti possano unirsi a formare un impenetrabile muro di difesa.$B$BImpara bene la lezione, $N. E tieniti $Gpronto:pronta; per i prossimi insegnamenti.",
  en_title = "Path of Defense",
  en_obj = "Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens.",
}
T[1499] = {
  title = "I Vile Familiar",
  desc = "Zureetha manda i novizi come te ad aiutare a sfoltire le creature nella caverna vicino a dove hai combattuto i Vile Familiar.$B$BCredo che ti farebbe bene fare esperienza aiutandola. Dille che hai contribuito a risolvere il problema degli Imp: probabilmente avrà una ricompensa per te.",
  obj = "Parla con Zureetha Fargaze.",
  reward = "Hai fatto un buon lavoro, $N.$B$BAnche se i Vile Familiar erano solo animaletti al servizio dei poteri più oscuri della Burning Blade, il tuo successo contro di loro fa presagire imprese più grandi.",
  en_title = "Vile Familiars",
  en_obj = "Speak with Zureetha Fargaze.",
}
T[1501] = {
  title = "Creatura del vuoto",
  desc = "Sono rimasti così pochi stregoni... Rischiamo molto, ma i rischi sono giustificati. Devi raggiungere in fretta la piena maturità nelle tue capacità, se vuoi essere utile all'Orda e al Capoguerra.$B$BÈ ora che tu impari un nuovo incantesimo di evocazione.$B$BPrima devi recuperare la Tablet of Verga, rubata dagli stregoni della Burning Blade e ora custodita nel loro covo a Skull Rock, a est della città. Con la tavoletta, ti mostrerò le rune necessarie per evocare un Voidwalker.",
  obj = "Recupera la Tablet of Verga per Gan'rul Bloodeye, a Orgrimmar.",
  progress = "Hai la Tablet of Verga, $N? Se no, non voglio parlarti finché non ce l'avrai.",
  reward = "Bene. Spero che tu abbia inflitto qualche altra perdita alla Burning Blade quando sei $Gandato:andata; a recuperarla.$B$BSono stati una grande seccatura per il Capoguerra, e una grande piaga per tutti gli stregoni.",
  en_title = "Creature of the Void",
  en_obj = "Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar.",
}
T[1502] = {
  title = "Thun'grim Firegaze",
  desc = "È fondamentale che l'arma di un guerriero sia di qualità. E se c'è un orco capace di forgiare armi di qualità, quell'orco è Thun'grim Firegaze. È un eremita che vive in cima alle colline a est del Crossroads.$B$BSe cerchi un'arma, $Gguerriero:guerriera;, allora dovresti cercare Thun'grim. Per trovarlo, raggiungi prima il Crossroads, a ovest, poi dirigiti a est tra le colline. Il suo accampamento è in alto, sulla cima di una collina.",
  obj = "Parla con Thun'grim Firegaze, nelle Barrens.",
  reward = "I miei occhi si sono seccati da tempo a forza di fissare la fiamma della forgia, ma certe cose riesco ancora a vederle. Vedo che vuoi qualcosa.$B$BE se hai trovato la strada fin qui, posso immaginare cosa desideri.",
  en_title = "Thun'grim Firegaze",
  en_obj = "Speak with Thun'grim Firegaze in the Barrens.",
}
T[1503] = {
  title = "Acciaio forgiato",
  desc = "Ti darò un'arma, $N, ma prima devi aiutarmi. I Razormane a nord-ovest sono entrati nel mio accampamento qualche notte fa. Non volevano affrontarmi in combattimento, ma sanno che ci vedo poco: alcuni mi hanno distratto con i loro grugniti mentre altri mi derubavano! Codardi!$B$BHanno preso un forziere di ferro, e dentro c'erano delle Forged Steel Bars. Se riesci a recuperarle, ti darò l'arma che cerchi.$B$BCerca la cassa di ferro negli accampamenti dei quilboar e torna con le Forged Steel Bars.",
  obj = "Porta le Forged Steel Bars a Thun'grim Firegaze, nelle Barrens.",
  progress = "Hai le mie barre d'acciaio?",
  reward = "Le hai trovate! E ci sono tutte, il che non mi sorprende. Non credevo che i Razormane sapessero cosa farsene di un acciaio pregiato come questo.$B$BGrazie, $N. Ecco la tua ricompensa. Che ti sia utile.",
  en_title = "Forged Steel",
  en_obj = "Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens.",
}
T[1504] = {
  title = "Il vincolo",
  desc = "Ora osserva la Tablet of Verga, perché contiene i glifi che ti serviranno per l'evocazione. Portali al cerchio nella tenda di Neeru Fireblade, dall'altra parte della caverna. Lì potrai richiamare il Voidwalker.$B$BDevi sconfiggerlo con qualunque mezzo fisico e magico tu abbia a disposizione. Fatto questo, torna da me con le Glyphs of Summoning e ti mostrerò come vincolare la creatura alla tua volontà.",
  obj = "Usando le Glyphs of Summoning, evoca e sottometti un Voidwalker, poi riporta le Glyphs of Summoning a Gan'rul Bloodeye, a Orgrimmar.",
  progress = "Il Voidwalker è una creatura potente. Ricordo quando ero io al tuo posto, $N. Negli anni il mio Voidwalker ha imparato a combattermi di meno, anche se sospetto che sia solo perché spera che io abbassi la guardia.$B$BRicordalo, $N.",
  reward = "Hai fatto bene, $N. Ti mostrerò come evocare un Voidwalker simile a quello che hai appena sconfitto.$B$BDevi sapere che abbiamo grandi aspettative su di te, e finora le hai rispettate.$B$BMa non montarti la testa, perché i compiti che ti aspettano faranno sembrare questo facile come svegliarsi al mattino.",
  en_title = "The Binding",
  en_obj = "Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar.",
}
T[1505] = {
  title = "Il veterano Uzzek",
  desc = "L'Orda onora i suoi guerrieri perché la loro forza è indiscussa. Ma i guerrieri davvero grandi sono anche grandi allievi.$B$BCerca Uzzek. È un veterano di molte battaglie e ora insegna ai giovani guerrieri le vie del combattimento. Lo troverai a sud del Far Watch Post, la guarnigione orchesca al confine tra le Barrens e Durotar, a est.",
  obj = "Parla con Uzzek al Far Watch Post.",
  reward = "Salve, giovane. Sei qui per un po' di addestramento, eh?",
  en_title = "Veteran Uzzek",
  en_obj = "Speak with Uzzek at Far Watch Post.",
}
T[1506] = {
  title = "La convocazione di Gan'rul",
  desc = "Ehi, tu. $N, giusto?$B$BSpero che tu non abbia troppi impegni, perché Gan'rul vuole vederti subito. Lo troverai con gli stregoni anziani nella Cleft of Shadow.$B$BA giudicare dai miei trascorsi con Gan'rul, questa convocazione è o un'ottima cosa o una pessima cosa.",
  obj = "Parla con Gan'rul Bloodeye, a Orgrimmar.",
  reward = "Bene. Temevo che Ophek non riuscisse a raggiungerti.$B$BÈ ora che io porti avanti il tuo addestramento da $Gstregone:strega;. Qualunque faccenda tu abbia in corso dovrà aspettare.$B$BConfido che non ci saranno problemi?",
  en_title = "Gan'rul's Summons",
  en_obj = "Speak with Gan'rul Bloodeye in Orgrimmar.",
}
T[1507] = {
  title = "Divoratrice di anime",
  desc = "È giunto il momento che tu impari di più sulle magie di evocazione. Imparerai a evocare una Succubus, una creatura dai poteri mentali incredibili. Può ridurre al suo servizio chi ha una mente debole, ma non temere! Sono certo che sarai all'altezza della sfida.$B$BUna Succubus si può evocare solo attirandola con un oggetto che rappresenti una grande devozione e un grande amore. Lascio a te il compito di trovarlo.$B$BUn suggerimento? Parla con Cazul... Sembra che ci sia ben poco che l'antico stregone non sappia.",
  obj = "Parla con Cazul, nella Cleft of Shadow.",
  reward = "Mm... $N. Sei ancora agli inizi del tuo cammino, ma percepisco in te la possibilità della grandezza.$B$BSei $Gnato:nata; con dei doni, $N. Fa' in modo che non vadano sprecati.",
  en_title = "Devourer of Souls",
  en_obj = "Speak with Cazul in the Cleft of Shadow.",
}
T[1508] = {
  title = "Il cieco Cazul",
  desc = "Mm... Ma certo, non è per questo che sei $Gvenuto:venuta; a parlarmi.$B$BSe Gan'rul ti ha mandato da me, dev'essere che devi evocare una Succubus e ti serve un oggetto per attirarla.$B$BMm... Se ti fidi a farti guidare da un cieco, $N, allora ascolta. Sulle alture di Orgrimmar, a ovest della torre dei wind rider, vive Zankaja. Aspetta il ritorno del suo compagno.$B$BVa' da lei.",
  obj = "Parla con Zankaja, a Orgrimmar.",
  reward = "Porti notizie di Dogran? Sarebbe dovuto tornare giorni fa, e non ho saputo niente...",
  en_title = "Blind Cazul",
  en_obj = "Speak with Zankaja in Orgrimmar.",
}
T[1509] = {
  title = "Notizie di Dogran",
  desc = "Il mio compagno, Dogran, è stato mandato da poco in servizio al Crossroads. Era una promozione, e ne andava molto fiero.$B$BIo ero triste, naturalmente, ma non gliel'ho fatto capire. E anche preoccupata. Le Barrens sono un posto più pericoloso di Orgrimmar, e temevo il peggio.$B$BOra è passata una settimana da quando sarebbe dovuto tornare, e non ho ricevuto sue notizie...$B$BForse potresti andare al Crossroads a vedere se hanno notizie? Lavorava con Gazrog, che dovrebbe essere ancora di stanza lì.",
  obj = "Parla con Gazrog, al Crossroads.",
  reward = "Zankaja? È la compagna di Dogran, giusto?$B$BSì, ho avuto sue notizie, ma non sono il genere di notizie da far arrivare a lei...$B$BNo, non è morto. Ma è ferito ed è prigioniero dei quilboar.",
  en_title = "News of Dogran",
  en_obj = "Speak with Gazrog at the Crossroads.",
}
T[1510] = {
  title = "Notizie di Dogran",
  desc = "Era di stanza a Camp Taurajo, dove stiamo cercando di sbarazzarci dei quilboar. Ha guidato alcuni grunt in uno dei loro accampamenti, dove è stato ferito gravemente. Gli altri sono riusciti a tornare e hanno cercato di salvarlo. Era messo male, le ferite si erano infettate, quindi avevano paura di spostarlo senza prima medicarlo.$B$BHanno mandato un messaggio qui, chiedendo una pozione curativa ai troll di Malaka'jin, ai piedi delle Stonetalon Mountains. Abbiamo mandato qualcuno a prenderla, ma non è ancora tornato.",
  obj = "Parla con Ken'zigla, a Malaka'jin.",
  reward = "$GUn altro orco:Un'altra orchessa;, eh? Spero che tu non sia qui per l'altro. Non ce l'ha fatta. Quei goblin l'hanno sistemato per bene.$B$BHa detto che gli serviva una pozione curativa, e poco altro.",
  en_title = "News of Dogran",
  en_obj = "Speak with Ken'zigla at the Malaka'jin.",
}
T[1511] = {
  title = "Ken'zigla's Draught",
  desc = "Immaginavo che sarebbe venuto qualcun altro a prendere la pozione, così l'ho preparata comunque.$B$BEcco qua, $N. Mi raccomando, dagliene solo metà! Gli darà abbastanza forza per muoversi senza dissanguarsi. Aspetta una notte, poi dagli l'altra metà.$B$BComunque, dovrai portarla a Logmar, a Camp Taurajo. Da quello che mi ha detto il primo, lui dovrebbe sapere dove si trova questo Dogran.",
  obj = "Porta Ken'zigla's Draught a Grunt Logmar, a Camp Taurajo.",
  progress = "Sì, che c'è?",
  reward = "Beh, era ora! Dogran sta morendo là fuori, in attesa di questa.$B$BDobbiamo fargliela avere subito, ma la maggior parte dei grunt di stanza qui è fuori in missione per procurarsi viveri.",
  en_title = "Ken'zigla's Draught",
  en_obj = "Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo.",
}
T[1512] = {
  title = "Il dono dell'amore",
  desc = "Zankaja è giovane e bella. Legata a un invalido... Non le permetterò di subire questa ingiustizia.$B$BLasciami, $N. E grazie. Potrò porre fine alla mia vita in una battaglia gloriosa, invece che come un guscio vuoto.$B$BE ti prego, non dire niente di tutto questo alla mia compagna... Non voglio che si senta in colpa.",
  obj = "Porta il Dirt-caked Pendant a Gan'rul Bloodeye, a Orgrimmar.",
  progress = "Sei $Gtornato:tornata;. Sei $Gpronto:pronta; ad affrontare una Succubus?",
  reward = "Se mi dici che basterà, allora mi fido di te, $N. Lascia però che lo pulisca... Immacolato e splendente, potrebbe essere ancora più allettante per una Succubus.",
  en_title = "Love's Gift",
  en_obj = "Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar.",
}
T[1513] = {
  title = "Il vincolo",
  desc = "Porta questo al cerchio di evocazione nella tenda di Neeru, $N. Richiama un'immonda Succubus, poi mostrale la tua maestria. Credo nella forza della tua magia. Come sempre, però, sta' in guardia, perché l'orgoglio e la presunzione hanno perduto molti stregoni promettenti.$B$BQuando l'avrai sconfitta, riportami il ciondolo, così che io possa dare la notizia a Zankaja.",
  obj = "Usando Dogran's Pendant, evoca e sottometti una Succubus, poi riporta Dogran's Pendant a Gan'rul Bloodeye, a Orgrimmar.",
  progress = "Quando guardo una Succubus, il mio cuore prende il volo... Ma allo stesso tempo, sento quasi la mia anima che si ritira, come la marea.$B$BSta' in guardia, $Gamico mio:amica mia;.",
  reward = "Ce l'hai fatta! Non mi aspettavo niente di meno $Gdal mio allievo migliore:dalla mia allieva migliore;.$B$BHai dimostrato il tuo valore, e ti mostrerò volentieri il metodo per evocare la Succubus che hai sottomesso. Ora va', hai molto da imparare, e la prossima volta che ti vedrò mi aspetto che tu abbia raggiunto la vera padronanza della tua Succubus.$B$BLascia il dolore di Dogran e Zankaja a quelli tra noi che hanno più anni sulle spalle, ma ricordalo, e tienilo come protezione contro le lusinghe del potere oscuro che hai imparato a evocare oggi.",
  en_title = "The Binding",
  en_obj = "Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.",
}
T[1515] = {
  title = "La prigionia di Dogran",
  desc = "Sei $Garrivato:arrivata; fin qui, quindi se vuoi andare fino in fondo, non ti fermerò. Però non posso darti altri uomini: sarai $Gda solo:da sola;.$B$BDogran è tenuto prigioniero in un accampamento dei quilboar a nord di qui. Cerca un gruppo di due capanne. Sarà sorvegliato a vista... sempre che non l'abbiano già ucciso, o che non sia morto per le ferite.$B$BBuona fortuna.",
  obj = "Porta Ken'zigla's Draught a Dogran, nelle Barrens.",
  progress = "Urrrghhhh...",
  reward = "Che intruglio disgustoso...$B$BOra sento la forza dentro di me, abbastanza per trascinarmi via... Ma la gamba, l'avrò persa per il resto della mia vita. E anche il braccio.",
  en_title = "Dogran's Captivity",
  en_obj = "Bring Ken'zigla's Draught to Dogran in the Barrens.",
}
T[1516] = {
  title = "Il richiamo della terra",
  desc = "È giunto il momento, giovane $C. Sei $Gdiventato:diventata; forte e il tuo spirito resiste come la terra. Seguire la via dello sciamano è segno che hai saggezza, prima ancora di aver dimostrato il tuo valore.$B$BL'elemento della terra guiderà il tuo destino, e diventerà parte di te se sei $Gpronto:pronta;. Ma devi presentarti davanti alla terra stessa. Se sei $Gpronto:pronta;, vedrai cose che solo gli sciamani conoscono.$B$BCerca i Felstalker a nord e prendi due dei loro zoccoli. Poi torna da me, e parleremo ancora del tuo futuro.",
  obj = "Porta 2 Felstalker Hoof a Canaga Earthcaller, nella Valley of Trials.",
  progress = "La pazienza è la più grande virtù della terra. La terra è testimone del ciclo di tutte le cose: le montagne che diventano deserti; i fiumi che diventano canyon. La terra è il più ostinato e il più saggio di tutti gli elementi, e non tollera l'impazienza.$B$BLa terra ti chiama ora perché si avvicina un tempo di conflitto. Quando tornerai da me $Gvittorioso:vittoriosa;, sarai molto più $Gvicino:vicina; a raggiungere la tua pienezza.$B$BGli altri invidieranno la tua saggezza e ti odieranno per la loro ignoranza.",
  reward = "Eccellente. Il tuo successo dimostra che sei $Gpreparato:preparata;.$B$BDi tutti gli elementi, la terra rappresenta le fondamenta di ogni cosa. È la tua forza, la tua resistenza e la tua pazienza. La terra ti proteggerà, ma solo se le si mostra il dovuto rispetto. Come gli altri elementi, anche la terra può essere volubile. La terra è la base della vita, e osservandone le leggi otterrai una saggezza più grande. Non dimenticare mai i segreti che la terra condivide con te.$B$BOra preparerò una sapta per te, e accettandola capirai qual è la tua strada.",
  en_title = "Call of Earth",
  en_obj = "Bring 2 Felstalker Hooves to Canaga Earthcaller in the Valley of Trials.",
}
T[1517] = {
  title = "Il richiamo della terra",
  desc = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Intrisa di magia, la pozione permette a chi ha una volontà forte di vedere gli elementi come nessun altro può. Il tuo spirito sarà legato all'elemento per cui la sapta è stata creata, e solo una ristretta cerchia di sciamani ne conosce la ricetta.$B$BLa sapta si beve sempre in un luogo sacro, e mai altrove — ricordalo.$B$BCerca la Spirit Rock, a sud-ovest di qui — si trova alla fine dell'Hidden Path. Bevi lì la tua sapta, e... be', vedrai.",
  obj = "Trova la Spirit Rock e bevi l'Earth Sapta.",
  reward = "Ah... $N... lieta è la terra di averti qui.$B$BOra che siamo uniti nel corpo e nello spirito, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso la tua essenza.$B$BPresentarti umilmente davanti alla terra è tutto ciò che ti si chiede per superare questo rito. Ma gli altri elementi non sono altrettanto tranquilli. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature doppie che si oppongono l'una all'altra: devi imparare a conoscerle a fondo.",
  en_title = "Call of Earth",
  en_obj = "Find Spirit Rock and drink the Earth Sapta.",
}
T[1518] = {
  title = "Il richiamo della terra",
  desc = "Prendi da me questo Rough Quartz e portalo a Canaga Earthcaller come prova del nostro incontro. Creerà un totem per te, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che le dimensioni non contano, e che anche le cose più piccole possono sopravvivere a molte altre.$B$BSii paziente, $N. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra — rispettala, come lei rispetterà te.",
  obj = "Porta il Rough Quartz a Canaga Earthcaller, nella Valley of Trials.",
  progress = "Voglio essere il primo a darti il benvenuto, a pieno titolo, sulla prima delle quattro vie che guideranno per sempre il tuo destino.$B$BSe hai la pietra che ti ha dato la terra, ti darò il totem che ti ha promesso.$B$BAltrimenti, vattene finché non avrai trovato la tua strada.",
  reward = "Eccellente!$B$BIl totem che creerò per te è più di un simbolo del tuo rango di $C — ha anche poteri che vanno oltre. Il totem serve, tra l'altro, a concentrare gli incantesimi. Quegli incantesimi sono legati alla terra, e man mano che la tua saggezza crescerà, ti saranno accessibili sempre più poteri della terra.$B$BGli istruttori sapranno quando sarai $Gpronto:pronta; per conoscenze più grandi.$B$BMa per ora prendi questo Earth Totem, e una pergamena che ti insegnerà la tua prima abilità.",
  en_title = "Call of Earth",
  en_obj = "Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials.",
}
T[1519] = {
  title = "Il richiamo della terra",
  desc = "È giunto il momento, giovane $C. Il tuo corpo matura e si fa forte, e il tuo spirito resiste come la terra. Lo vedo dentro di te — hai già saggezza.$B$BLa terra guida il nostro popolo, e ci parla, come a suo tempo parlerà a te. Ma devi essere $Gmesso:messa; alla prova. Se sei $Gpronto:pronta;, vedrai cose che solo la nostra gente conosce.$B$BCerca gli sciamani Bristleback nel loro burrone a est, e prendi loro un unguento che usano nei loro rituali. Torna da me solo quando ne avrai abbastanza per la tua pozione.",
  obj = "Porta 2 dosi di Ritual Salve a Seer Ravenfeather, a Camp Narache.",
  progress = "La terra è paziente, e ti aspetterà finché non sarai $Gpronto:pronta;, perché sa che col tempo tutte le cose si consumano e rinascono. È il ciclo delle cose. Le montagne diventano deserti. I fiumi diventano canyon. La terra è il più ostinato e il più saggio di tutti gli elementi.$B$BDevi imparare la pazienza e la resistenza sopra ogni cosa. La terra ora ti chiama perché sente che sei $Gpronto:pronta;. Se ci riuscirai, considerala la tua rinascita. Dopo, non potrai mai più tornare all'ignoranza.",
  reward = "Bene, $N. Il tuo ritorno significa che sei davvero $Gpronto:pronta; per il passo successivo.$B$BDi tutti gli elementi, la terra rappresenta le fondamenta di ogni cosa. È la tua forza, la tua resistenza e la tua pazienza. La Madre Terra ti proteggerà, ma solo se le mostrerai il dovuto rispetto. Lei è la base della vita, e osservandone le leggi otterrai una saggezza più grande. Non dimenticare mai i segreti che condivide con te.$B$BOra preparerò la tua sapta, e accettandola vedrai aprirsi davanti a te una nuova strada.",
  en_title = "Call of Earth",
  en_obj = "Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache.",
}
T[1520] = {
  title = "Il richiamo della terra",
  desc = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Intrisa di magia, la pozione permette a chi ha la mente aperta di vedere gli elementi come nessuno li ha mai visti. Il tuo spirito sarà legato per sempre all'elemento per cui la sapta è stata creata, e solo una ristretta cerchia della nostra gente conosce i segreti della sua preparazione.$B$BLa sapta si beve sempre in un luogo sacro, e mai altrove.$B$BCerca il santuario sciamanico a est di qui e bevi la sapta.",
  obj = "Trova la Kodo Rock e bevi l'Earth Sapta.",
  reward = "Ah... $N... lieta è la terra di averti qui.$B$BOra che siamo uniti nel corpo e nello spirito, andrai avanti sapendo che le montagne sono la tua forza; le pianure, la tua pazienza; e il mondo stesso la tua essenza.$B$BPresentarti umilmente davanti alla terra è tutto ciò che ti si chiede per superare questo rito. Ma gli altri elementi non sono altrettanto tranquilli. Possono essere caotici e spesso violenti, ma tale è la natura degli elementi. Nature doppie che si oppongono l'una all'altra: devi imparare a conoscerle a fondo.",
  en_title = "Call of Earth",
  en_obj = "Find Kodo Rock and drink the Earth Sapta.",
}
T[1521] = {
  title = "Il richiamo della terra",
  desc = "Prendi da me questo Rough Quartz e portalo a Seer Ravenfeather come prova del nostro incontro. Creerà un totem per te, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che le dimensioni non contano, e che anche le cose più piccole possono sopravvivere alle montagne.$B$BSii paziente, $N. Resta forte. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra — rispettala, come lei rispetterà te.",
  obj = "Porta il Rough Quartz a Seer Ravenfeather, a Camp Narache.",
  progress = "Salve, $N. Non torneresti da me se non avessi portato a termine il tuo compito. Lascia che sia la prima a darti il benvenuto, a pieno titolo, sulla prima delle quattro vie che governeranno per sempre i tuoi viaggi.$B$BSe hai la pietra che ti ha dato la terra, ti darò il totem che ti ha promesso. Altrimenti, mi fai pena. Quando ci si dedica completamente agli elementi, c'è molto di cui andare fieri.",
  reward = "Splendido.$B$BIl totem che creerò per te è più di un simbolo — ha anche poteri che vanno oltre. Il totem serve, tra l'altro, a concentrare gli incantesimi. Quegli incantesimi sono legati alla terra, e man mano che la tua saggezza crescerà, ti saranno accessibili sempre più poteri della terra. Gli istruttori che troverai in tutta Kalimdor sapranno quando sarai $Gpronto:pronta; per conoscenze più grandi, e te lo diranno quando andrai da loro.$B$BMa per ora prendi questo Earth Totem...",
  en_title = "Call of Earth",
  en_obj = "Bring the Rough Quartz to Seer Ravenfeather in Camp Narache.",
}
T[1522] = {
  title = "Il richiamo del fuoco",
  desc = "Il fuoco sia con te, $Gamico:amica;. Vedo che sei già forte nelle vie della terra, e secondo me sei $Gpronto:pronta; a parlare con Kranal.$B$BKranal vive a nord del Crossroads, nelle Barrens. È forte nelle vie degli elementi e può insegnarti le vie del fuoco... se pensi di essere $Gpronto:pronta;.$B$BÈ facile da trovare, basta non andare troppo lontano — se vai troppo lontano, ti ritrovi nelle terre degli elfi.",
  obj = "Trova Kranal Fiss, nelle Barrens.",
  reward = "Hmmm, ti ha mandato Searn, vero?$B$BBe', di Searn ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.$B$BLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[1523] = {
  title = "Il richiamo del fuoco",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la distruzione... e il caos. Comprendere l'elemento del fuoco è alla tua portata, se sei $Gdisposto:disposta; a pagarne il prezzo.$B$BCerca Kranal Fiss nelle Barrens. Vive in una piccola dimora a nord del Crossroads, ma fai attenzione: se arrivi alle terre degli elfi della notte, sei $Gandato:andata; troppo lontano.",
  obj = "Trova Kranal Fiss, nelle Barrens.",
  reward = "Hmmm, ti ha mandato Narm, vero?$B$BBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.$B$BLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[1524] = {
  title = "Il richiamo del fuoco",
  desc = "Sei abbastanza potente per impugnare il Fire Totem, ma questo non significa che tu sia $Gpronto:pronta;.$B$BLungo il Southfury River, a Durotar, prima del Great Sea, c'è un sentiero nascosto che porta a una delle vette più alte di queste terre. Trova la strada per la cima e troverai uno dei nostri santuari sacri, custodito da Telf Joolam — lo Shrine of the Dormant Flame.$B$BPortagli questa torcia — è il segno che stai tentando di domare il fuoco. Riportamela dopo averla accesa al braciere del santuario, e farò in modo che tu riceva il Fire Totem.",
  obj = "Porta la Torch of the Dormant Flame a Telf Joolam, a Durotar.",
  progress = "Salve, $N. Sei $Garrivato:arrivata; allo Shrine of the Dormant Flame. Solo chi è abbastanza esperto nelle arti sciamaniche arriverà mai a conoscere i segreti di questo luogo e il potere che custodisce. Mi dispiace che tu abbia fatto tutta questa strada per essere $Grespinto:respinta; proprio adesso — dopotutto la salita fin quassù è tutt'altro che sicura — ma sono il custode del santuario, e non posso permettere a chiunque di aggirarsi da queste parti.",
  reward = "Ah, errore mio, $N. Ti chiedo scusa. Non mi ero accorto che avessi con te la torcia. Sono lieto di fare la tua conoscenza.$B$BMolti avventurieri arrivano fin qui in cerca di tesori perduti o attratti dalla promessa di creature mistiche da uccidere, solo per essere respinti da un santuario che sembra vuoto. Ma noi conosciamo la verità, non è vero, $N?$B$BQuesto santuario custodisce un segreto più grande, nascosto ai membri comuni dell'Orda. Per noi è sacro.",
  en_title = "Call of Fire",
  en_obj = "Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.",
}
T[1525] = {
  title = "Il richiamo del fuoco",
  desc = "Ma non sei $Gvenuto:venuta; qui per una lezione di storia, vero? Sei $Gvenuto:venuta; per l'Eternal Flame e per il Fire Totem.$B$BIl primo passo è creare una sapta e legarti alla fiamma.$B$BPosso creare la sapta del fuoco per te, se mi porti due oggetti. Il primo è il Fire Tar, un oggetto comune che di solito portano con sé gli incantatori Razormane nelle Barrens orientali.$B$BIl secondo sarà più pericoloso da procurare: una Reagent Pouch presa a uno dei cultisti della Burning Blade. Li trovi in una grotta sopra i burroni a nord-est di Razor Hill.",
  obj = "Porta 1 Fire Tar e 1 Reagent Pouch a Telf Joolam, a Durotar.",
  progress = "Ho abbastanza ingredienti per una sapta del fuoco, se riesci a trovare la Reagent Pouch e un po' di Fire Tar. I fanatici della Burning Blade tengono in quelle sacche i componenti adatti per la maggior parte dei loro incantesimi, e di solito hanno abbastanza di quello che mi serve, così non dovremo cercare nient'altro molto più lontano.$B$BLe sapta si preparano sempre con ingredienti strettamente legati ai rispettivi elementi. Grazie al legame degli stregoni con il fuoco, il nostro lavoro è più facile.",
  reward = "Andranno benissimo, $N.$B$BIl fuoco è più che caos e distruzione — faresti bene a ricordarlo. Riguarda anche la vita, e la creazione. Tutte le cose sono legate tra loro in questo modo. Le forze si oppongono l'una all'altra, ma allo stesso tempo l'una non può esistere senza l'altra. Si spengono a vicenda, ma si danno anche un senso a vicenda. Ricordalo sempre.$B$BUsare diversi tipi di magia insieme dimostrerà non solo una vera abilità, ma anche una grande saggezza.",
  en_title = "Call of Fire",
  en_obj = "Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.",
}
T[1526] = {
  title = "Il richiamo del fuoco",
  desc = "La sapta del fuoco è pronta. È giunto il momento di affrontare la fiamma. Usa la sapta al santuario e sali in cima alla montagna per affrontare la manifestazione che si trova lassù. Non attaccherà finché non sarai $Gpronto:pronta;, ma si renderà conto che riesci a vederla.$B$BAbbattila in fretta, $N, perché più tempo impiegherai a ucciderla, più diventerà potente. Una volta sconfitta, metti le sue braci ardenti nel braciere e accendi la torcia.",
  obj = "Sconfiggi la Minor Manifestation of Fire e metti la Glowing Ember nel braciere in cima allo Shrine of Eternal Flame.",
  progress = "Il braciere è alto circa un terzo di te, e sembra normale, a parte le iscrizioni lungo i suoi lisci montanti di metallo. Il metallo non mostra segni di usura dovuti alle intemperie, e la coppa posta in cima è fresca al tatto.",
  reward = "Una fiamma bianca, rovente, si accende nella coppa quando ci metti dentro la brace. Senti gli effetti magici della sapta scorrerti nel corpo, e il fuoco danza a ritmo davanti a te.$B$BInfili la punta della torcia nel bacile, e prende subito fuoco.",
  en_title = "Call of Fire",
  en_obj = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.",
}
T[1527] = {
  title = "Il richiamo del fuoco",
  desc = "Con la torcia ben stretta in mano, ti allontani dal braciere e il tuo sguardo spazia su Durotar. Senti un fremito agitarti lo spirito, mentre il vento si alza e costringe la fiamma a una danza violenta.$B$BTi incammini lungo il sentiero che riporta alle Barrens, in cerca di Kranal Fiss.",
  obj = "Porta la Torch of Eternal Flame a Kranal Fiss, nelle Barrens.",
  progress = "Sì, $N? Cos'hai lì?",
  reward = "Il tuo spirito arde più luminoso di qualunque torcia io abbia mai visto, $N, e per questo dovresti andarne $Gfiero:fiera;.$B$BSe continuerai su questa strada, gli elementi saranno ai tuoi ordini, e i nostri fratelli si rivolgeranno a te per avere guida e saggezza. Lascia che sia il primo a congratularmi con te e a consegnarti il tuo nuovo totem.",
  en_title = "Call of Fire",
  en_obj = "Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.",
}
T[1528] = {
  title = "Il richiamo dell'acqua",
  desc = "C'è acqua nel tuo futuro, $Gamico:amica;. Vedo che sei già forte nelle vie del fuoco, e secondo me sei $Gpronto:pronta; a parlare con Islen.$B$BIslen vive lungo la costa delle Barrens. Se vai a sud lungo il Southfury River, non puoi sbagliare — cerca il grosso squalo! È forte nelle vie degli elementi e può insegnarti le vie dell'acqua... se pensi di essere $Gpronto:pronta;.$B$BÈ facile da trovare, basta non andare troppo a sud — sta appena oltre Ratchet.",
  obj = "Trova Islen Waterseer, nelle Barrens.",
  reward = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.$B$BLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[1529] = {
  title = "Il richiamo dell'acqua",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.$B$BCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Southfury River e di Ratchet. La troverai lì, alla sua capanna da pesca. Buona fortuna, $N.",
  obj = "Trova Islen Waterseer, nelle Barrens.",
  reward = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.$B$BLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[1530] = {
  title = "Il richiamo dell'acqua",
  desc = "Se c'è una lezione che devi imparare sull'acqua, è questa: l'acqua significa rinascita.$B$BIl suo potere scorre, erode e purifica ogni genere di cosa. Scoprirai che la sua capacità di guarire e di ristorare non ha eguali, ma solo quando è pura.$B$BQuando capirai che l'acqua, se inquinata, può devastare tutto ciò che tocca, comprenderai quanto sia vitale questa risorsa.$B$BSe vuoi la sapta dell'acqua, trova Brine nel profondo delle Barrens del sud. La sua casa è continuamente tormentata dai quilboar della zona.",
  obj = "Trova Brine, nelle Barrens del sud.",
  reward = "Sì?$B$BMmm. Ho la sensazione di sapere cosa stai per chiedermi: cosa spinge qualcuno a vivere quaggiù, nella parte più remota delle Barrens, con la minaccia dei quilboar tutt'intorno e nessuna protezione? Be', tutti abbiamo le nostre ragioni per giustificare quello che facciamo. La vera domanda è: cosa porta $Gun semplice:una semplice; $R fin nel cuore delle Barrens a parlare con una donna a cui chiaramente non importa niente della propria incolumità?$B$BScommetto che la risposta la conosciamo $Gtutti e due:tutte e due;.",
  en_title = "Call of Water",
  en_obj = "Find Brine in Southern Barrens.",
}
T[1531] = {
  title = "Il richiamo dell'aria",
  desc = "Stai facendo progressi, $Gamico:amica;. Sei $Gpronto:pronta; a dimostrare di essere $Gdegno:degna; dell'Air Totem, ma prima devi trovare Prate Cloudseer a Thousand Needles. Sarà disposta a dirti come ottenere il tuo Air Totem, se la tratti con abbastanza rispetto.$B$BVa' a sud attraverso le Barrens, e quando arrivi a Thousand Needles, va' a est. La troverai nascosta in una buca con il suo fidanzato — ah ah, non dirle che parlo male di lei — non la prenderebbe molto bene.",
  obj = "Trova Prate Cloudseer, a Thousand Needles.",
  reward = "Per il momento, ti darò ciò che ti serve per concentrare i tuoi incantesimi e invocare gli spiriti dell'aria. Prendi questo totem, e quando sarai $Gpronto:pronta;, allenati ancora con me.",
  en_title = "Call of Air",
  en_obj = "Find Prate Cloudseer in Thousand Needles.",
}
T[1532] = {
  title = "Il richiamo dell'aria",
  desc = "I venti di Kalimdor ti corrono incontro, e sarai $Gannoverato:annoverata; tra $Gi nostri fratelli:le nostre sorelle; più potenti. È un orgoglio per me vedere che sei $Garrivato:arrivata; fin qui e che hai un futuro così promettente.$B$BL'elemento dell'aria è difficile da controllare, ma ho fiducia che le tue abilità supereranno qualunque ostacolo ti venga posto davanti.$B$BVa' all'estremo sud delle Barrens ed entra a Thousand Needles. È lì, molto a est, che troverai Prate Cloudseer. Ti insegnerà di più.",
  obj = "Trova Prate Cloudseer, a Thousand Needles.",
  reward = "Per il momento, ti darò ciò che ti serve per concentrare i tuoi incantesimi e invocare gli spiriti dell'aria. Prendi questo totem, e quando sarai $Gpronto:pronta;, allenati ancora con me.",
  en_title = "Call of Air",
  en_obj = "Find Prate Cloudseer in Thousand Needles.",
}
T[1534] = {
  title = "Il richiamo dell'acqua",
  desc = "Prendi quest'otre e addentrati nella foresta rigogliosa che gli elfi della notte chiamano Ashenvale. Si trova all'estremo nord delle Barrens.$B$BQuando sarai nella foresta, dirigiti a ovest. Lungo le montagne che separano Stonetalon e Ashenvale, e oltre il Lake Mystral, troverai un luogo sacro: le Ruins of Stardust. Al centro del lago troverai una piccola fontana.$B$BPortami un campione dell'acqua della fontana. Sarà l'ultimo componente che ti servirà prima che ti rimandi da Islen.",
  obj = "Riempi l'Empty Blue Waterskin alle Ruins of Stardust, in Ashenvale, e torna da Brine, nelle Barrens.",
  progress = "Hai già l'acqua, $N? Le leggende dicono che le rovine erano protette da grandi creature della natura a cui non piacciono i visitatori, ma potrebbero essere miti per spaventare i nemici degli elfi della notte.$B$BIn ogni caso, fai attenzione.",
  reward = "Magnifico, $N. Con tutti e tre i campioni raccolti, posso creare per te una fiala dell'acqua più pura che una creatura vivente possa trovare. Servirà nelle prossime tappe del tuo rito di passaggio.$B$BSono lieta di contarti tra la nostra gente, $N. Fai onore a ogni $C, e non vedo l'ora di sentir parlare delle tue imprese in futuro.",
  en_title = "Call of Water",
  en_obj = "Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens.",
}
T[1535] = {
  title = "Il richiamo dell'acqua",
  desc = "Per arrivare a capire, e per ottenere da me la sapta, devi cercare solo le forme più pure d'acqua. Mentre raccogli i campioni per me, osserva bene ciò che ti circonda. Fai attenzione alle creature che dipendono dall'acqua, che la proteggono. Guarda come influisce sulle foreste e sui deserti. Osserva come proprio la sostanza che sostiene la vita spinga le creature a uccidere.$B$BCominceremo con un compito semplice: sotto la mia capanna c'è uno stagno di questo liquido prezioso. Riempi quest'otre e torna da me.",
  obj = "Riempi l'Empty Brown Waterskin alla pozza sotto la capanna di Brine e riportalo a lei, nelle Barrens.",
  progress = "Sono quasi pronta a mandarti a svolgere gli altri compiti. Hai già riempito l'otre?$B$BSo quanto possono essere protettivi i quilboar. Anche una fonte d'acqua così piccola per loro è un immenso tesoro. Fanno grandi banchetti ogni volta che sulle Barrens cade anche la più leggera pioggia. L'acqua è sacra per la loro specie perché è così scarsa. Capisci?",
  reward = "Immaginavo che ci sarebbe scappato del sangue se avessi provato a prendere l'acqua dalla pozza. È un peccato che i quilboar non si rendano conto che tutti gli esseri viventi sono legati tra loro; che la loro avidità non fa che perpetuare il dolore e la sofferenza del loro popolo. Quante cose potrebbero ottenere, se mettessero da parte le loro divisioni e i loro clan si unissero.$B$BAncora una volta, è un peccato, ma con ogni probabilità è una fortuna per le altre razze delle Barrens.",
  en_title = "Call of Water",
  en_obj = "Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens.",
}
T[1536] = {
  title = "Il richiamo dell'acqua",
  desc = "Molto tempo fa seguii alcuni compagni nelle Hillsbrad Foothills. Ci difendemmo da certi umani tenaci che vivono lì, e ci ritrovammo in una cittadina che i Reietti avevano conquistato: Tarren Mill.$B$BFu lì che trovai una cosa davvero curiosa: al centro del paese c'era un piccolo pozzo di acqua sorgiva fresca. Non sono sicura che gli abitanti appestati della cittadina ne capiscano davvero il valore — è un piccolo vestigio sacro in un mare sconsacrato.$B$BPortami un campione di quell'acqua in quest'otre.",
  obj = "Riempi l'Empty Red Waterskin al pozzo di Tarren Mill e torna da Brine, nelle Barrens.",
  progress = "Il pozzo rimasto puro in mezzo alla cittadina mi ricorda le storie che mi raccontavano quand'ero più giovane, $N. Anche nei momenti di grande dolore e tristezza si può trovare uno spiraglio di speranza, un piccolo simbolo attorno a cui stringersi. Gli orchi vedono Thrall in questo modo. È sopravvissuto contro ogni previsione e si è sollevato per guidare il nostro popolo con la sua forza e il suo esempio.$B$BNon so se ci sia un orco che abbia sofferto quanto lui, ma allo stesso tempo non so nemmeno se ci sia un orco forte quanto lui.",
  reward = "Bene così, $N. Ti dedichi al compito che hai davanti e sai cercare ciò che serve.$B$BMi serve solo un altro campione per creare il reagente necessario per la tua sapta. Anche Islen ne sarà contenta.",
  en_title = "Call of Water",
  en_obj = "Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens.",
}
T[1558] = {
  title = "La Stonewrought Dam",
  desc = "Ironforge è dove vivono tutti i nani e gli gnomi. Lì vicino c'è un posto chiamato Loch Modan, e i nani ci hanno costruito una diga ENORME. Dicono che sia una delle cose più grandi che siano mai state costruite. Wow!$B$BMi porteresti a Loch Modan a vedere la diga, per piacere? Mi sembra che si chiami Stone... ehm... Stonewrench Dam? Stonewrought? È grande, questo è sicuro. Vorrei affacciarmi sulla grande cascata. Prometto che non mi sporgerò troppo!",
  obj = "Porta l'orfano alla Stonewrought Dam, a Loch Modan. Dovresti portarlo al centro della diga, così potrà guardare la cascata gigante.",
  progress = "Siamo arrivati?",
  reward = "WOW, la diga era MOLTO più grande di quanto pensassi! Riuscivo a malapena a sentirmi parlare per il rumore di tutta quell'acqua che scorreva! Ehi, pensi che l'acqua possa mai finire? Accidenti, cosa succederebbe se quella diga si rompesse! WOW, sarebbe spaventoso!$B$BGrazie di avermi portato a vedere la diga. È stato molto gentile da parte tua. Te l'avevo detto che non mi sarei sporto troppo!",
  en_title = "The Stonewrought Dam",
  en_obj = "Take the orphan to the Stonewrought Dam in Loch Modan.  You should take him to the middle of the dam so he can see out over the giant waterfall.",
}
T[1559] = {
  title = "La ricetta delle Flash Bomb",
  reward = "Quindi sei $Gun ingegnere:un'ingegnera;, eh? Be', in cambio del tuo aiuto per procurarmi quelle perle, ecco la ricetta delle Flash Bomb.$B$BBuona fortuna, e cerca di non accecarti!",
  en_title = "Flash Bomb Recipe",
}
T[1578] = {
  title = "Rifornire il fronte",
  desc = "I montanari del Loch Modan stanno combattendo contro i trogg, e hanno il loro bel da fare! Hanno bisogno di rifornimenti continui di armature e armi nuove, se vogliamo mai riuscire a tenere a bada quei trogg.$B$BPer questo il mio collega Thorvald è laggiù, a cercare di tenere i montanari ben equipaggiati. Quindi, se tu fabbricassi qualche Copper Axe e qualche Copper Chain Belt e li portassi a Thorvald, te ne sarebbe grato. Potrebbe perfino condividere con te le sue conoscenze.$B$BThorvald si trova nella torre di guardia a sud del Loch Modan.",
  obj = "Porta 6 Copper Axe e 6 Copper Chain Belt a Thorvald, nella torre di guardia a sud del Loch Modan.",
  progress = "Non ho tempo per chiacchierare. Hai qualche affare da sbrigare con me?",
  reward = "Ah, scusami! Non avevo capito che eri qui per aiutare a rifornire le nostre truppe. Quello che hai fabbricato sarà di grande aiuto!$B$BEcco gli schemi di un'armatura. Spero che ti siano utili.",
  en_title = "Supplying the Front",
  en_obj = "Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan.",
}
T[1579] = {
  title = "Gaffer Jacks",
  desc = "Sono venuto ad Auberdine per la tranquillità. Voglio inventare le mie invenzioni dove c'è silenzio, perché dopo una notte di bevute non sopporto tutto il rumore di Ironforge!$B$BCosì ho preso una nave per Auberdine e durante il viaggio ho bevuto un po' troppo. Ho fatto cadere in mare la mia scatola di Gaffer Jack! Mi servono i miei Gaffer Jack!$B$BNon so di preciso dove li ho fatti cadere, ma se li peschi nell'oceano forse ti andrà bene...",
  obj = "Porta 8 Gaffer Jack a Wizbang Cranktoggle, ad Auberdine.",
  progress = "Hai trovato i miei Gaffer Jack, $N? Senza i miei Gaffer Jack non posso regolare i miei pioli stintle!",
  reward = "Non ci posso credere, li hai trovati! Devi essere $Gil:la; $R più $Gfortunato:fortunata; di Kalimdor!",
  en_title = "Gaffer Jacks",
  en_obj = "Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine.",
}
T[1580] = {
  title = "Electropellers",
  desc = "Sappiamo che sei $Gfortunato:fortunata;, ma... quanto sei $Gfortunato:fortunata;, di preciso, $N?$B$BUna notte vagavo per le strade di Darkshore. Cercavo un bel fiume o un lago per provare il mio nuovo richiamo per anatre esplosivo e semovente, e credo di essere stato un po' brillo... perché sono svenuto e mi sono risvegliato ore dopo ad Auberdine. Avevo i capelli bruciacchiati e la mia borsa di Electropeller era sparita! Devo averli fatti cadere in acqua!$B$BMi servono quegli Electropeller! Magari riesci a ripescarli da qualche lago o torrente di Darkshore...",
  obj = "Porta 12 Electropeller a Wizbang Cranktoggle, ad Auberdine.",
  progress = "Hai trovato qualche Electropeller? Mi serviranno se voglio continuare le mie ricerche sui richiami per anatre...",
  reward = "Non ci posso credere! Li hai trovati! Sei $Gil miglior pescatore:la miglior pescatrice; che abbia mai visto!$B$BGrazie, $N. E tieni, prendi questi. Anche se sei così $Gbravo:brava; che probabilmente non ti servono, ti aiuteranno a pescare.",
  en_title = "Electropellers",
  en_obj = "Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine.",
}
T[1581] = {
  title = "Elisir per i Bladeleaf",
  desc = "Il nostro negozio di erbe e di alchimia va a gonfie vele, ma mio marito passa così tanto tempo a mescolare pozioni che non abbiamo mai tempo l'uno per l'altra.$B$BPuoi aiutarci?$B$BSe mi porti una scorta di elisir già pronti, sarò felice di fare uno scambio con te. Ho alcune erbe rare che potrebbero esserti utili.",
  obj = "Porta 6 Elixir of Lion's Strength e 2 Elixir of Minor Defense a Syral Bladeleaf, a Dolanaar.",
  progress = "Salve, $N. Hai gli elisir da scambiare?",
  reward = "Sono miscelati bene. Metti grande cura nel tuo mestiere, $N, ed è importante per un alchimista.$B$BEcco le tue erbe, appena raccolte. Possa tu usarle bene.",
  en_title = "Elixirs for the Bladeleafs",
  en_obj = "Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar.",
}
T[1582] = {
  title = "Moonglow Vest",
  desc = "Noi di Darnassus, e soprattutto noi artigiani, abbiamo molto da fare. I giovani avventurieri sono impazienti di mettersi alla prova nelle terre selvagge, e hanno sempre bisogno di rifornimenti.$B$BSe mi aiuti a evadere i miei ordini di articoli di cuoio, forse potrò insegnarti una tecnica di conciatura avanzata.",
  obj = "Porta 1 Embossed Leather Gloves, 5 Embossed Leather Boots e 5 Embossed Leather Cloak a Lotherias, a Darnassus.",
  progress = "Salve, $N.",
  reward = "Sì, sono pezzi di buona fattura. Hai una mano abile e occhio per i dettagli. Come $Gconciatore:conciatrice; hai un futuro promettente.$B$BEcco, $N. Lascia che ti mostri lo schema per fare il Moonglow Vest.",
  en_title = "Moonglow Vest",
  en_obj = "Bring 1 Embossed Leather Gloves, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.",
}
T[1598] = {
  title = "Il tomo rubato",
  desc = "Ehi, tu! $N, giusto?$B$BSpero che tu sia $Gsicuro:sicura; di voler diventare $Gun stregone:una strega;, perché se non riesci a cavartela, rischi di essere $Gtrascinato:trascinata; a fondo.$B$BDevo insegnarti, ma prima devo assicurarmi che tu sia abbastanza forte.$B$BC'era un novizio che studiava all'Abbey ed è scappato per unirsi alla Defias Brotherhood. Perché mi importa? Beh, ha rubato alcuni libri importanti.$B$BUno di questi è proprio un libro che volevo per me, Powers of the Void. Rubamelo: lo tengono nascosto nella loro tenda nei Vineyards.",
  obj = "Recupera Powers of the Void per Drusilla La Salle.",
  progress = "Sarebbe stato troppo vistoso rubare il libro di persona. Che fortuna che uno dei loro galoppini abbia fatto il lavoro sporco al posto mio.",
  reward = "Eccellente... Non ero mai riuscita ad accedere a questo testo: era custodito in un'ala protetta della biblioteca, e se mi fossi aggirata da quelle parti sarei sembrata sospetta.$B$BBeh, hai fatto un buon lavoro a procurartelo, e sono convinta che probabilmente sai gestire un Imp tutto tuo, quindi non c'è motivo per non mostrarti come evocarne uno.",
  en_title = "The Stolen Tome",
  en_obj = "Retrieve the Powers of the Void for Drusilla La Salle.",
}
T[1599] = {
  title = "Inizi",
  desc = "Devi essere $Glo stregone nuovo:la strega nuova; di cui tutti bisbigliano. Qualcuno deve avertela presa a benvolere, se mi hanno chiesto di distogliermi dalle mie ricerche per iniziare il tuo addestramento.$B$BNon preoccuparti, non te ne farò una colpa.$B$BIl più semplice degli incantesimi di evocazione che imparerai è quello dell'imp. Prima però di insegnartelo, devi dimostrare di possedere le capacità magiche e fisiche necessarie.$B$BPortami tre feather charms dai frostmane novices della caverna a sud-ovest.",
  obj = "Porta 3 Feather Charms ad Alamar Grimm ad Anvilmar.",
  progress = "Quei feather charms che portano i novizi hanno una qualche forma di potere magico. Sarà interessante studiarli. Non me lo sarei aspettato dai troll.",
  reward = "Molto bene, molto bene! Hai fatto un buon lavoro, $n. Forse l'interesse che si mostra nei tuoi confronti è meritato, dopotutto.$B$BQuesto lo decideranno gli altri... sempre che il tuo imp non ti sopraffaccia e non stronchi la tua carriera sul nascere. Per ora mi basta che tu probabilmente sopravviverai ai tuoi primi mesi da $Gstregone:strega;.$B$BUna parola sull'imp, $n. Come sa ogni gnomo, non farti ingannare dalle dimensioni: la sua magia può essere molto pericolosa.",
  en_title = "Beginnings",
  en_obj = "Bring 3 Feather Charms to Alamar Grimm in Anvilmar.",
}
T[1618] = {
  title = "Equipaggiare Redridge",
  desc = "Non siamo solo noi nani a combattere. Anche i nostri alleati umani hanno il loro bel da fare!$B$BRedridge subisce attacchi periodici dagli orchi Blackrock, e le loro scorte di equipaggiamento sono sempre scarse. Se li aiutassi, di sicuro il loro fabbro, Verner Osgood, ti insegnerebbe un trucco o due.",
  obj = "Tormus Deepforge vuole che tu porti 4 Runed Copper Belt e 4 Heavy Copper Maul a Verner Osgood, a Redridge.",
  progress = "Spero che tu sia qui con buone notizie da Ironforge. Perché io non so più dove sbattere la testa!",
  reward = "Grazie, $N. Questo mi aiuterà tantissimo. Con gli orchi Blackrock che attaccano dallo Stonewatch Keep e gli gnoll di Redridge in agguato sulle colline a nord, non faccio che riparare armature e forgiare armi nuove per le nostre truppe.$B$BI rifornimenti che hai portato mi daranno un momento di pace. Avrò abbastanza tempo per insegnarti qualcosa...",
  en_title = "Gearing Redridge",
  en_obj = "Tormus Deepforge  wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge.",
}
T[1638] = {
  title = "L'addestramento di un guerriero",
  desc = "Hai dimostrato di essere $Gun guerriero capace:una guerriera capace;, $N. Ma sei ancora giovane e hai molto da imparare.$B$BParla con Harry Burlguard: di solito sta nella taverna Pig and Whistle, nell'Old Town di Stormwind. Harry è un vecchio veterano e un buon insegnante. Può mostrarti qualche mossa che ti terrà in vita più a lungo.",
  obj = "Parla con Harry Burlguard.",
  reward = "Oh oh! Bevi qualcosa con me, $N. Fuori sembri $Gtosto:tosta;, ma vediamo se il tuo stomaco regge qualche boccale della roba più forte del Pig and Whistle!!$B$BOppure... sei qui per una lezione?",
  en_title = "A Warrior's Training",
  en_obj = "Speak with Harry Burlguard.",
}
T[1639] = {
  title = "Bartleby l'ubriacone",
  desc = "Sì, posso insegnarti. Ma prima voglio vedere che mosse conosci già.$B$BVedi quell'ubriaco laggiù, in fondo al bancone? Bartleby? Voglio che tu gli prenda il boccale.$B$BAh, e se conosci Bartleby, sai che non te lo darà tanto facilmente.",
  obj = "Parla con Bartleby.",
  reward = "Salve, $Gbel ragazzino:bella ragazzina;! Che ci fa una cosina delicata come te al Pig and Whistle? Sta' $Gattento:attenta;, o potresti romperti un'unghia...",
  en_title = "Bartleby the Drunk",
  en_obj = "Speak with Bartleby.",
}
T[1640] = {
  title = "Batti Bartleby",
  desc = "Che cosa vuoi?? Sei $Gpazzo:pazza;!$B$BL'unico modo per avere questo boccale è strapparmelo dalle dita fredde e morte...",
  obj = "Batti Bartleby, poi parla con lui.",
  progress = "L'unico modo per avere questo boccale è strapparmelo dalle dita fredde e morte...",
  reward = "Sei molto più $Gtosto:tosta; di quanto sembri!",
  en_title = "Beat Bartleby",
  en_obj = "Beat Bartleby, then talk to him.",
}
T[1641] = {
  title = "Il Tome of Divinity",
  reward = "Qui a Stormwind, il mio compito è avviare i paladini sul cammino verso una virtù più grande, mentre si dedicano alla Luce e difendono Azeroth dal Flagello e da altre minacce.$B$BÈ giunto il momento che tu faccia il primo passo per diventare $Gdavvero virtuoso:davvero virtuosa;. Se accetti, ti darò un Book of Divinity. Studiandolo, imparerai qualcosa sulla Luce, e su ciò che ci si aspetta da te. Se lo comprenderai, e ne sarai capace, riuscirai a ottenere abilità più grandi.",
  en_title = "The Tome of Divinity",
}
T[1642] = {
  title = "Il Tome of Divinity",
  desc = "In ogni cosa, un paladino deve riflettere la Luce che integra la nostra forza. Per uno come noi, sforzarsi di essere divino non significa aspirare alla divinità — significa sforzarsi di essere buoni in ogni azione.$B$BAnche se in questi tempi duri sei $Gchiamato:chiamata; a colpire il male, devi sempre ricordare che è aiutare gli altri che ti distinguerà davvero dagli abitanti di Azeroth. Compassione, pazienza, coraggio — queste cose contano per un paladino quanto la forza in battaglia.$B$BSappilo bene, e non dimenticarlo mai.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Ciao di nuovo, $N. Come procedono i tuoi studi sul Tome of Divinity?$B$BAllora dovresti essere $Gpronto:pronta; a essere $Gmesso:messa; alla prova. Ci sono sempre compiti da svolgere in città e nelle nostre terre; atti di compassione e di comprensione; persone che hanno bisogno di aiuto; creature da uccidere.$B$BDimostrando di avere la pazienza di aiutare gli altri, soprattutto i meno fortunati, dimostri di essere $Gun servitore:una servitrice; della Luce e di mente salda.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1643] = {
  title = "Il Tome of Divinity",
  desc = "Il tuo compito, allora, $N, è trovare qualcuno qui a Stormwind che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenzioni. Forse qualcuno che aiuta gli altri. Forse qualcuno che ha bisogno di una guida. In ogni caso, quella persona deve avere intenzioni nobili e contare sulla tua gentilezza.$B$BFa' questo, e torna da me quando hai finito. Allora parleremo ancora del tuo cammino e di cosa significa essere un paladino della Luce.",
  obj = "Cerca Stephanie Turner nel Trade District di Stormwind.",
  reward = "Oh, ciao, tesoro. Come vanno le tue avventure? Oh, sono così contenta di sentire che ti va tutto bene.$B$BOh, io? Grazie per avermelo chiesto — sto bene, tutto sommato.$B$BL'aumento degli artigiani ha un po' ridotto la quantità di cuoio e di stoffa che la gente è disposta a cedere di questi tempi, quindi è stato più difficile fare vestiti per i bambini dell'orfanotrofio, ma ce la caveremo. Con \"noi\" intendo me e mio marito. È su a Ironforge a cercare aiuto tra i cittadini di là.",
  en_title = "The Tome of Divinity",
  en_obj = "Search the Trade District of Stormwind for Stephanie Turner.",
}
T[1644] = {
  title = "Il Tome of Divinity",
  desc = "Poveri cari, quasi tutti non hanno più una famiglia per colpa degli attacchi del Flagello nell'ultimo decennio.$B$BMio marito John raccoglie i materiali con cui cucio le camicie e i pantaloni per i bambini, ma non ho avuto nemmeno il tempo di farlo. Ho pensato solo a mettere il cibo nei loro piatti e un tetto sopra le loro teste.$B$BCome dici? Saresti $Gdisposto:disposta; ad aiutarmi? Oh, sia ringraziata la Luce, e grazie a te, $N.$B$BSe potessi portarmi un po' di Linen Cloth per cucire i vestiti ai bambini, mi aiuteresti tantissimo.",
  obj = "Porta 10 Linen Cloth a Stephanie Turner, a Stormwind.",
  progress = "Spero che il mio John abbia più fortuna a Ironforge. Detesta tanto i suoi viaggi là, perché lasciano soli me e i bambini, ma sa che vanno fatti. Ha un cuore così buono.$B$BAlcuni anni sono stati più facili di altri, ma questo è stato di gran lunga il più duro. È quasi come se nell'aria ci fosse il segnale di un grande cambiamento. Ma chi lo sa?",
  reward = "Grazie, $N, grazie mille!$B$BI bambini saranno contentissimi, e mi hai fatto risparmiare un sacco di tempo. Ora potrò pensare agli altri bisogni dei bambini, e spero che il mio John possa tornare a casa prima del previsto.$B$BGrazie ancora, $N. Sapevo di poter contare sulla carità degli altri. Che la Luce sia con te.",
  en_title = "The Tome of Divinity",
  en_obj = "Bring 10 Linen Cloth to Stephanie Turner in Stormwind.",
}
T[1645] = {
  title = "Il Tome of Divinity",
  reward = "Piacere di conoscerti, $N. Il mio compito è avviare i paladini sul cammino verso una virtù più grande, mentre si dedicano alla Luce e difendono Azeroth dal Flagello e da altre minacce.$B$BÈ giunto il momento che tu faccia il primo passo per diventare $Gdavvero virtuoso:davvero virtuosa;. Se accetti, ti darò un Book of Divinity. Studiandolo, imparerai qualcosa sulla Luce, e su ciò che ci si aspetta da te. Se lo comprenderai, e ne sarai capace, riuscirai a ottenere abilità più grandi.",
  en_title = "The Tome of Divinity",
}
T[1646] = {
  title = "Il Tome of Divinity",
  desc = "In ogni cosa, un paladino deve riflettere la Luce che integra la nostra forza. Per uno come noi, sforzarsi di essere divino non significa aspirare alla divinità — significa sforzarsi di essere buoni in ogni azione.$B$BAnche se in questi tempi duri sei $Gchiamato:chiamata; a colpire il male, devi sempre ricordare che è aiutare gli altri che ti distinguerà davvero dagli abitanti di Azeroth. Compassione, pazienza, coraggio — queste cose contano per un paladino quanto la forza in battaglia.$B$BSappilo bene, e non dimenticarlo mai.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "$GBentornato:Bentornata;, $N. Hai passato del tempo a leggere il libro, spero?$B$BAllora dovresti essere $Gpronto:pronta; a essere $Gmesso:messa; alla prova. Ci sono sempre compiti da svolgere in città e nelle nostre terre; atti di compassione e di comprensione; persone che hanno bisogno di aiuto; creature da uccidere.$B$BDimostrando di avere la pazienza di aiutare gli altri, soprattutto i meno fortunati, dimostri di essere $Gun servitore:una servitrice; della Luce e di mente salda.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[1647] = {
  title = "Il Tome of Divinity",
  desc = "Il tuo compito, allora, $N, è trovare qualcuno qui a Ironforge che abbia bisogno di aiuto. Qualcuno puro di cuore e di intenzioni. Forse qualcuno che aiuta gli altri. Forse qualcuno che ha bisogno di una guida. In ogni caso, quella persona deve avere intenzioni nobili e contare sulla tua gentilezza.$B$BFa' questo, e torna da me quando hai finito. Allora parleremo ancora del tuo cammino e di cosa significa essere un paladino della Luce. Resterò qui nel tempio ad aspettare il tuo ritorno. Anche altri paladini avranno bisogno della mia guida.",
  obj = "Cerca John Turner nell'anello esterno di Ironforge.",
  reward = "L'ORFANOTROFIO DI STOR... oh, scusa, non volevo urlarti contro, $Gsignore:signorina;.$B$BMi chiamo John Turner. Come stai?$B$BBene, bene, sono contento di sapere che ti va tutto bene. Ho già avuto una lunga giornata di lavoro, e mi manca terribilmente mia moglie, ma è il prezzo da pagare quando ci sono bocche da sfamare e schiene da vestire.",
  en_title = "The Tome of Divinity",
  en_obj = "Search the outer ring of Ironforge for John Turner.",
}
T[1648] = {
  title = "Il Tome of Divinity",
  desc = "Mia moglie e io gestiamo un orfanotrofio a Stormwind, soprattutto per i bambini che hanno perso i genitori negli attacchi del Flagello dell'ultimo decennio. Vengo a Ironforge più o meno una volta al mese per vedere di raccogliere altre provviste dai cittadini di qui, e per parlare con i vari gruppi e capire se possono fare qualcosa per aiutare.$B$BQuesto viaggio è stato lentissimo, e non molto fruttuoso.$B$BSe solo riuscissi a procurare un po' di lino in più a mia moglie per fare dei vestiti, potrei finalmente spedire un carico a casa.",
  obj = "Porta 10 Linen Cloth a John Turner, a Ironforge.",
  progress = "Con tutti gli artigiani che arrivano qui e in tutta Azeroth, ci sono meno materiali per fare i vestiti ai bambini del nostro orfanotrofio. Aiutarmi a raccogliere il lino perché mia moglie possa fargli dei vestiti nuovi è molto nobile da parte tua, $N. Grazie.$B$BSpero di poter tornare presto a casa da mia moglie.",
  reward = "È davvero magnifico da parte tua, $N. Grazie ancora.$B$BSei $Gun uomo nobile:una donna nobile; a fare questo per me. Non c'è da stupirsi che tu abbia scelto di seguire la Luce. Vorrei che ci fosse un modo per ripagarti di tutto quello che hai fatto... come dici? È il minimo che potessi fare? Visto? È proprio di questo che parlo, $N: nobile fino in fondo.$B$BStammi bene, e che la Luce ti protegga nei tuoi viaggi.",
  en_title = "The Tome of Divinity",
  en_obj = "Bring 10 Linen Cloth to John Turner in Ironforge.",
}
T[1649] = {
  title = "Il Tome of Valor",
  desc = "Il valore, e tutte le virtù che lo accompagnano, sono come minerali rari: devi custodirli gelosamente quando li trovi, per il loro valore, ma devi anche prenderti il tempo di estrarli... di raffinarli. Quando si fondono nel modo giusto, formano una lega resistente, a volte infrangibile anche dai colpi più potenti.$B$BQuesta forza, la tua fede, il tuo coraggio, devono essere messi alla prova. Devi imparare a non perdere mai la fede, e a capire che con il potere della Luce puoi superare prove che la maggior parte degli altri non riesce a superare.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Ah, desideri chiedermi una prova di valore. Splendido.$B$BCi sono molti compiti in città e nelle terre circostanti che presentano grandi sfide, e servirebbe $Gun uomo:una donna; con le tue capacità.$B$BQuesta prova non va presa alla leggera, $N. Questa, come molte cose lungo il nostro cammino, potrebbe costarci la vita. La Chiesa desidera sempre rafforzare i suoi ranghi, ma comprende i sacrifici necessari per assicurarsi che i paladini al suo servizio ne siano degni.$B$BSei $Gpronto:pronta;?",
  en_title = "The Tome of Valor",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1650] = {
  title = "Il Tome of Valor",
  desc = "Bene! Non hai esitato, ed è il segno sicuro che sei $Gpronto:pronta; e impaziente di metterti alla prova. Così sia.$B$BProprio in fondo alla Longshore, a Westfall, c'è una casetta che si affaccia sull'oceano. Lì vive una coppia, gli Stilwell. Jordan è un fabbro straordinario, ed è andato per un po' a Ironforge a incontrare i nani. Ma così Daphne, sua moglie, è rimasta sola e senza protezione.$B$BStando ai rapporti, i Defias hanno quasi preso il controllo della zona: Daphne potrebbe aver bisogno di qualcuno che la protegga da quei furfanti. Va' laggiù.",
  obj = "Trova Daphne Stilwell a Westfall.",
  reward = "Salve, $N. Con tutta quell'armatura e quell'arma, immagino che tu sia qui o per cercare di prenderti la mia terra, o perché la Chiesa ha finalmente mandato qualcuno ad aiutarmi a difendermi finché il mio Jordan è via.$B$BBe', lascia che mi presenti: sono Daphne Stilwell. Piacere.$B$BComunque, non sei in ritardo... Dall'alba ho fatto fuori solo una mezza dozzina di quei farabutti. Ci hanno messo un po' a sbucare dalla curva lassù, ma probabilmente ti hanno visto arrivare, quindi saranno qui da un momento all'altro.",
  en_title = "The Tome of Valor",
  en_obj = "Find Daphne Stilwell in Westfall.",
}
T[1651] = {
  title = "Il Tome of Valor",
  desc = "Allora, torneranno presto, ci scommetto, quindi preparati.$B$BIn casa ho un fucile. Vado a prenderlo e sarò pronta a darti una mano, ma per lo più te la dovrai cavare da $Gsolo:sola;.$B$BNon ho idea di quanti ne manderanno, ma di sicuro saranno più dei pochi che hanno mandato prima.$B$BChiedi alla Luce tutte le benedizioni che puoi, perché... hai sentito? Credo che stiano arrivando.$B$BResisteremo vicino alla casa!",
  obj = "Difendi Daphne Stilwell dall'attacco dei Defias.$B$BSe vuoi riuscire, nessuno dei vostri due spiriti deve abbandonare il proprio corpo mortale.$B$BDopo la vittoria, parla di nuovo con Daphne Stilwell.",
  progress = "Resisteremo qui, alla casa!",
  reward = "Ce l'abbiamo fatta, $N! Grazie per l'aiuto. Là fuori sei $Gstato:stata; davvero $Gstraordinario:straordinaria;. Non avrei mai pensato che un paladino potesse tenere testa a così tanti nemici tutti insieme.$B$BHai dimostrato un vero coraggio, contro forze di gran lunga superiori.",
  en_title = "The Tome of Valor",
  en_obj = "Defend Daphne Stilwell from the Defias attack.$B$BNeither of your spirits must be released from their mortal coils if you wish to succeed.$B$BAfter you are successful, speak to Daphne Stilwell again.",
}
T[1652] = {
  title = "Il Tome of Valor",
  desc = "Ti prego, torna da Duthorian e fagli sapere che per ora sono al sicuro. Per questo devo ringraziare te e la Chiesa.$B$BManderà un messaggio a Ironforge per far sapere al mio Jordan che non ha niente da temere.$B$BOh, quanto mi manca mio marito. Non vedo l'ora che torni.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Dunque ci rincontriamo, $N, e vedo che sei di ottimo umore.$B$BLa casa degli Stilwell sarà al sicuro per un altro giorno, e dal tuo racconto capisco che il pericolo non è mancato. Ben fatto.$B$BDaphne e Jordan hanno aiutato molto la Chiesa, e mandarti a proteggere la loro proprietà — e la loro stessa vita — era il minimo che potessimo fare per loro.$B$BPer il tuo valore, sarai $Gricompensato:ricompensata;.",
  en_title = "The Tome of Valor",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1653] = {
  title = "La prova della rettitudine",
  desc = "A dire il vero, non ho dubbi che Jordan in persona vorrebbe ringraziarti, e visto che mi serve un messaggero che gli faccia sapere che sua moglie è salva, penso che saresti la scelta perfetta.$B$BJordan doveva diventare un paladino della Luce, prima che la dedizione al mestiere di suo padre lo portasse su un'altra strada — conosce a fondo il nostro modo di vivere, ed è considerato tra i nostri più fedeli.$B$BDovrebbe essere ancora a Ironforge — di giorno gli piace lavorare fuori dai cancelli, per via dell'aria fresca di montagna o qualcosa del genere.",
  obj = "Parla con Jordan Stilwell, a Ironforge.",
  reward = "Buongiorno, $N. La Luce è con te, spero?$B$BCome dici? Ti ha mandato Duthorian!? Mia moglie, come sta? Sapevo che ci sarebbero stati guai se fossi partito. Ti prego, dimmi che è... oh, grazie al cielo. Sono così contento che sia salva. I Defias erano una minaccia molto prima di questi attacchi, ma ora i consiglieri del re non possono più negarlo.$B$BCos'altro ha detto Duthorian?$B$BSei tu che hanno mandato a proteggere mia moglie? Allora ti ringrazio di nuovo, $N. Non saprei immaginare una prova di valore migliore di questa.",
  en_title = "The Test of Righteousness",
  en_obj = "Speak to Jordan Stilwell in Ironforge",
}
T[1654] = {
  title = "La prova della rettitudine",
  desc = "Vorrei ricompensarti, se ti va di accettare una cosa del genere. Non fraintendermi, la mia generosità dipende da quanto potrai essermi d'aiuto, ma vedo un grande vantaggio per tutti e due in un'alleanza del genere.$B$BForgerò per te un'arma degna di ciò che hai compiuto, un simbolo della condizione di paladino e della Luce, ma dovrai raccogliere tu gli oggetti che mi servono per forgiarla. Ho già cominciato a prendere appunti sugli oggetti, serve solo qualcuno abbastanza coraggioso e abile da recuperarli. Che ne dici, $C?",
  obj = "Usando Jordan's Weapon Notes, trova del Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer e una Kor Gem, e riportali a Jordan Stilwell, a Ironforge.",
  progress = "Gli oggetti che cerchi saranno difficili da procurare, ma ti assicuro che l'arma che forgerò per te varrà la fatica.$B$BSarà il mio lavoro migliore fino a oggi, e solo un piccolo compenso per il servizio che mi hai reso.",
  reward = "È magnifico! Hai preso tutti gli oggetti.$B$BNon dovrei avere problemi a forgiarti un'arma grandiosa con questi. A dire il vero ho i progetti per farla da un po' di tempo. Non avevo mai avuto l'occasione di raccogliere il materiale. Grazie, $N.$B$BÈ bello riavere il martello di mio padre... e una Kor Gem. Non avrei mai pensato di vederne una con i miei occhi.",
  en_title = "The Test of Righteousness",
  en_obj = "Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge.",
}
T[1656] = {
  title = "Un compito incompiuto",
  desc = "$N, ti prego, puoi aiutarmi? Non ho ancora finito i miei compiti qui sulla Mesa... sono nel mezzo del mio Rito della Forza... e mio padre mi ha chiesto di consegnare queste pellicce alla locanda di Bloodhoof.$B$BSono ben lontan$Go:a; dall'essere abbastanza riposat$Go:a; per completare sia il mio rito sia questo incarico per mio padre. Andresti tu al posto mio?$B$BLa locanda è accogliente e perfetta per riposarsi durante i tuoi lunghi viaggi. Sono certo che concorderai quando la vedrai.",
  obj = "Porta il Bundle of Furs a Innkeeper Kauth a Bloodhoof Village.",
  progress = "Sì, giovane? Che cosa può fare Kauth per te?$B$BIl viaggio fin qui dalla Mesa può essere un fardello enorme per alcuni, ma una vista gradita per altri. Chissà quale dei due è il tuo caso?",
  reward = "Ah, le pellicce che aspettavo. Grazie.$B$BSono arrivate più in fretta del previsto. Faranno ottime coperte per chiunque voglia fermarsi qui.$B$BSentiti libero di restare quanto vuoi. La mia locanda è sempre aperta e tutta la nostra gente è la benvenuta. E non sottovalutare una buona notte di riposo: può fare una grande differenza mentre sei in viaggio.",
  en_title = "A Task Unfinished",
  en_obj = "Bring the Bundle of Furs to Innkeeper Kauth in Bloodhoof Village.",
}
T[1657] = {
  title = "Appestare Southshore",
  desc = "Festeggia la Veglia delle Ombre con stile... portando dolore ai nostri nemici di Southshore!$B$BPrendi una di queste bombe puzzolenti preparate apposta. È piena di un tanfo nauseabondo che nessun umano, né alcuna bestia dalla volontà debole, può sopportare di annusare. Dovrai lanciarla proprio nel cuore di Southshore perché faccia effetto, quindi preparati a combattere contro l'Alleanza!$B$BQuando avrai portato a termine questo compito... questo tributo alla nostra liberazione, torna da me!",
  obj = "Lancia tre Forsaken Stink Bomb nel cuore di Southshore, nelle Hillsbrad, e torna da Darkcaller Yanka al Wickerman Festival, nelle Tirisfal Glade.",
  progress = "Hai consegnato il nostro \"regalo\" alla gente di Southshore?$B$B<Darkcaller Yanka ride malvagiamente.>",
  reward = "Ah, ben fatto! Spero che l'Alleanza soffochi con il regalo schifoso che le abbiamo fatto, proprio come noi siamo stati costretti a soffocare sotto il giogo della schiavitù al Flagello!$B$BHai onorato il vero spirito della Veglia delle Ombre, $N, e per questo ti rendo omaggio. Come premio in più, lascia che divida con te alcuni di questi dolcetti della Veglia delle Ombre. Credo che li troverai un diversivo piuttosto piacevole!",
  en_title = "Stinking Up Southshore",
  en_obj = "Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.",
}
T[1658] = {
  title = "Imbucarsi al Wickerman Festival",
  desc = "Mi servono persone coraggiose che vadano nelle Tirisfal Glade a dare un'occhiata al Wickerman Festival. Non ti mentirò: andare lassù sarà pericoloso. Le guardie della festa saranno spietate come non mai. Però dobbiamo sapere quanto è grande la festa quest'anno, e quanti guai ci daranno i Reietti durante la Veglia delle Ombre.$B$BSe te la senti, va' a Tirisfal e perlustra la festa. Torna da me con le informazioni, e farò in modo che tu venga $Gricompensato:ricompensata; bene.",
  obj = "Trova il Wickerman Festival dei Reietti nelle Tirisfal Glade. Quando l'avrai trovato, torna da Sergeant Hartman a Southshore.",
  progress = "Sei $Gandato:andata; nelle Tirisfal Glade a dare un'occhiata? Di solito tengono la festa vicino all'Undercity...",
  reward = "Ben fatto, $N. Il Wickerman Festival continuerà a darci problemi finché agli abominevoli Reietti sarà permesso di infestare i resti di Lordaeron. NON è un tributo degno di quel regno un tempo fiero, te lo dico io...$B$BEcco qualche moneta per le riparazioni che ti serviranno, e nello spirito della festa ci ho messo anche qualche dolcetto che potrebbe piacerti. Buona Veglia delle Ombre: cerchiamo di passarla il più possibile al sicuro, qui a Southshore.",
  en_title = "Crashing the Wickerman Festival (PvP)",
  en_obj = "Locate the Forsaken's Wickerman Festival in Tirisfal Glade.  Return to Sergeant Hartman in Southshore once you've done so.",
}
T[1665] = {
  title = "Bartleby's Mug",
  desc = "Va bene, ecco il mio boccale. Aspetta! Prima lasciami finire quello che c'è dentro... ecco fatto.",
  obj = "Porta Bartleby's Mug a Burlguard.",
  progress = "Ho visto il tuo scontro con Bartleby. Bel lavoro! Hai preso il suo boccale?",
  reward = "Eccolo! Di certo non voleva separarsene, ma sei $Gstato:stata; convincente. Ben fatto.$B$BE ora la tua lezione...",
  en_title = "Bartleby's Mug",
  en_obj = "Bring Bartleby's Mug to Burlguard",
}
T[1666] = {
  title = "Marshal Haggard",
  desc = "Hai imparato qualche mossa, ma ti farebbe comodo un'arma decente. Scommetto che, se parlassi con Marshal Haggard, potrebbe aiutarti.$B$BMarshal Haggard vive in una casa padronale nell'Elwynn Forest, all'Eastvale Lumber Camp. Ora è in pensione, ma durante la sua carriera ha messo insieme un sacco di equipaggiamento.$B$BDigli che ti mando io e, con un po' di fortuna, avrà un'arma in più da offrirti.",
  obj = "Parla con Marshal Haggard.",
  reward = "Chi è?$B$BBurlguard, sei tu?$B$BDevi avvicinarti un po'. I miei occhi non sono più quelli di una volta.$B$BA vederti arrivare così, ti avevo preso per uno gnoll!",
  en_title = "Marshal Haggard",
  en_obj = "Speak with Marshal Haggard.",
}
T[1667] = {
  title = "Dead-tooth Jack",
  desc = "Ti manda Burlguard, eh? Sì, qui ho delle armi in più, ma prima ho un compito per te...$B$BTempo fa un furfante dei Defias, Dead-tooth Jack, mi ha ingannato. Era buio, lui indossava una tabarda di Stormwind e io l'ho preso per Marshal Dughan. Ha detto che gli serviva il mio vecchio distintivo da maresciallo di Stormwind e io gliel'ho dato... poi è scoppiato a ridere ed è scappato prima che riuscissi a prenderlo!$B$BRiprendi il mio distintivo! Probabilmente Dead-tooth Jack l'ha nascosto nel suo accampamento, a sud.",
  obj = "Recupera Haggard's Badge dall'accampamento di Dead-tooth Jack e torna da Marshal Haggard.",
  progress = "Hai il mio distintivo? Non voglio neanche pensare ai guai che Dead-tooth Jack potrebbe combinare con quello.",
  reward = "Magnifico, l'hai trovato! Temevo che fosse perduto per sempre, e che i Defias lo usassero per spacciarsi per un funzionario di Stormwind. Beh, ora non succederà, grazie a te.$B$BEcco alcune armi che usavo quando ero maresciallo. Le ho tenute in ottimo stato: scegli quella che preferisci!",
  en_title = "Dead-tooth Jack",
  en_obj = "Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.",
}
T[1678] = {
  title = "Vejrek",
  desc = "Se vuoi salire di grado tra i guerrieri, faresti meglio a essere $Gtosto:tosta;. Posso insegnarti mosse nuove, ma prima dimostrami che sai cavartela contro nemici veri.$B$BVejrek è il troll più duro che troverai da queste parti, ed è lui che devi battere. Ha una capanna sulle colline appena a sud del Frostmane Hold.$B$BPortami la testa di Vejrek e saprò che hai fegato.",
  obj = "Porta Vejrek's Head a Muren Stormpike, a Ironforge.",
  progress = "Sei $Gstato:stata; alla capanna di Vejrek, $N? È puzza di $R quella che sento addosso a te?",
  reward = "Era proprio brutto, Vejrek, eh? Bel lavoro, $N! Hai la stoffa giusta, ora cominciamo la lezione...$B$BForse non lo sai, ma per $Gun:una; $C una buona difesa è molto importante. Permette di restare in piedi contro nemici che abbatterebbero chiunque altro, ed è proprio quello di cui i tuoi alleati hanno bisogno.",
  en_title = "Vejrek",
  en_obj = "Bring Vejrek's Head to Muren Stormpike in Ironforge.",
}
T[1679] = {
  title = "Muren Stormpike",
  desc = "Salve, $Gguerriero:guerriera;! Sei molto promettente, ma devi ancora imparare qualche trucco, e Muren Stormpike è proprio il nano giusto per insegnarteli.$B$BTroverai Muren all'Hall of Arms, nel Military Ward di Ironforge. Parla con lui quando sei $Gpronto:pronta; a imparare cosa significa essere $Gun guerriero:una guerriera;.",
  obj = "Parla con Muren Stormpike.",
  reward = "Ah, $N. Ho sentito i guerrieri del Dun Morogh fare il tuo nome. Spero che tu non abbia passato tutto il tempo nei birrifici!",
  en_title = "Muren Stormpike",
  en_obj = "Speak with Muren Stormpike.",
}
T[1680] = {
  title = "Tormus Deepforge",
  desc = "Ora che hai imparato qualche mossa, è il momento di procurarti un'arma decente. Parla con Tormus Deepforge. Può farti un'arma che, ne sono sicuro, ti piacerà.$B$BTroverai Tormus qui a Ironforge, alla Great Forge.",
  obj = "Parla con Tormus Deepforge.",
  reward = "Ti manda Muren, eh? Sì, posso farti una bella arma... ma prima ho un favore da chiederti.$B$BNon preoccuparti. È parecchio pericoloso e potrebbe costarti la vita: è proprio il genere di lavoro che $Gun:una; $C desidera.",
  en_title = "Tormus Deepforge",
  en_obj = "Speak with Tormus Deepforge.",
}
T[1681] = {
  title = "Ironband's Compound",
  desc = "Il mio maestro, Sturgy Ironband, aveva un complesso a sud dell'Helm's Bed Lake, nel Dun Morogh orientale. Lì insegnava la forgiatura, ed era il migliore.$B$BMa un giorno uno dei suoi allievi gli portò un carico di uno strano minerale. Mastro Ironband lo chiamò Umbral Ore e non vedeva l'ora di lavorarlo, ma poco dopo il suo arrivo... una banda di nani Dark Iron attaccò il complesso. Uccisero tutti!$B$BEntra nell'Ironband's Compound, $N, e vendica la morte del mio maestro. E portami il carico di Umbral Ore che l'ha causata.",
  obj = "Porta un carico di Umbral Ore a Tormus Deepforge, a Ironforge.",
  progress = "Sei $Gentrato:entrata; nell'Ironband's Compound? Hai trovato l'Umbral Ore?",
  reward = "L'hai trovato! Ben fatto!$B$BSpero che tu abbia ucciso una schiera di nani Dark Iron mentre cercavi. Temo che l'Ironband's Compound non sarà l'ultimo posto in cui li vedremo.$B$BMa grazie per il minerale, $N. Non vedo l'ora di lavorarlo e di scoprirne le proprietà.",
  en_title = "Ironband's Compound",
  en_obj = "Bring a load of Umbral Ore to Tormus Deepforge in Ironforge.",
}
T[1682] = {
  title = "Armi di ferro grigio",
  reward = "Ecco delle armi, appena uscite dall'incudine e fatte con il nuovo Umbral Ore che mi hai portato!$B$BPer favore, $N, scegli quella che preferisci!",
  en_title = "Grey Iron Weapons",
}
T[1683] = {
  title = "Vorlus Vilehoof",
  desc = "Prima che io possa insegnarti, devi dimostrarmi la tua determinazione.$B$BIl satiro Vorlus Vilehoof ha trovato uno dei nostri pozzi lunari più remoti, a sud-est del Ban'ethil Barrow Den. Ora ci sguazza dentro, profanando le sue acque pure con la sua sozzura.$B$BTrova Vorlus al pozzo lunare e distruggilo. Portami il suo corno come prova e comincerò il tuo addestramento avanzato da $Gguerriero:guerriera;.$B$BIl sentiero per il pozzo lunare è ben nascosto, $N, ma resta $Gconcentrato:concentrata; e vigile e lo troverai.",
  obj = "Porta l'Horn of Vorlus a Elanaria, a Darnassus.",
  progress = "Hai il corno, $N? Il nostro pozzo lunare è libero da quel demonio di Vorlus?",
  reward = "Ben fatto, $N. È bello sapere che Vorlus è stato sconfitto e che il nostro pozzo lunare è purificato, ed è bello vedere giovani guerrieri desiderosi di tenere la nostra amata Teldrassil libera dalla corruzione.$B$BOra cominciamo il tuo addestramento...",
  en_title = "Vorlus Vilehoof",
  en_obj = "Bring the Horn of Vorlus to Elanaria in Darnassus.",
}
T[1684] = {
  title = "Elanaria",
  desc = "Salve, $Gguerriero:guerriera;. La tua abilità cresce, ma nella tua professione c'è più di quanto tu possa credere. Per progredire ancora, presto dovrai trovare un insegnante.$B$BLa guerriera Elanaria vive a Darnassus, alla Warrior's Terrace. Sarà lei a istruirti.",
  obj = "Parla con Elanaria.",
  reward = "Ti porgo i miei saluti, $N. Il tuo nome risuona forte a Darnassus, perché mostri del talento. Ma presto vedremo se possiedi la forza di volontà per seguire la via $Gdel:della; $C.",
  en_title = "Elanaria",
  en_obj = "Speak with Elanaria.",
}
T[1685] = {
  title = "La convocazione di Gakin",
  desc = "Non va sempre così? Ti ho cercato tutto il giorno senza trovarti, e ora che non me lo aspetto, mi vieni incontro.$B$BHo perso abbastanza tempo a cercarti, quindi non ti trattengo oltre. Il maestro Gakin ti ha convocato per un ulteriore addestramento. Mi sa che dovresti andare a cercarlo il prima possibile.$B$BLo troverai nel seminterrato della taverna Slaughtered Lamb. A proposito, faresti bene a non parlare in giro di quel posto. Meglio che non se ne sparga la voce.",
  obj = "Presentati da Gakin the Darkbinder, nel Mage Quarter di Stormwind.",
  reward = "Era ora che arrivassi. Anche se forse avrei dovuto mandare qualcuno più capace di Remen a cercarti.$B$BNon importa.$B$BSei $Grimasto:rimasta; troppo a lungo senza addestramento, e uno stregone senza addestramento difficilmente tiene la testa sulle spalle a lungo.",
  en_title = "Gakin's Summons",
  en_obj = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1686] = {
  title = "La Shade of Elura",
  desc = "Hai imparato molto, $N. Ora ti forgeremo un'arma. Un'arma da guerriero.$B$BPer farlo, devi andare a Darkshore.$B$BMolto tempo fa una nave si schiantò sugli scogli vicino al faro di Auberdine, spargendo molte casse di Elunite Ore sul fondo dell'oceano.$B$BPrima devi sconfiggere la guardiana dell'elunite, la Shade of Elura. Un tempo era il capitano della nave; lanciò una maledizione su se stessa per vagare negli abissi e proteggere il suo carico in eterno. Sconfiggila, prendi il suo medaglione e raccogli le casse di Elunite perduta.",
  obj = "Porta 8 carichi di Elunite Ore e il Medallion of Elura a Elanaria, a Darnassus.",
  progress = "Hai sconfitto la Shade of Elura, $N? E hai l'Elunite Ore perduto?",
  reward = "Hai agito con coraggio, $N.$B$BHai dato alla Shade of Elura la pace che meritava, e useremo l'elunite raccolta per forgiarti un'arma pregiata.",
  en_title = "The Shade of Elura",
  en_obj = "Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus.",
}
T[1687] = {
  title = "Il faro spettrale",
  desc = "A volte, a notte fonda, le matrone dell'orfanotrofio ci raccontano storie di paura. Sono FANTASTICHE! Ce n'è una su un fantasma che infesta un faro a Westfall. Dicono che fosse un capitano pirata a cui altri pirati avevano preso la nave. Wow!$B$BMi porteresti a vedere il faro a Westfall, per piacere? Voglio vedere se il fantasma di quel capitano c'è davvero! Prometto di starti vicino; non scapperò né niente!",
  obj = "Porta l'orfano a vedere il faro al largo della costa di Westfall.",
  progress = "Siamo arrivati?",
  reward = "WOW, era un fantasma vero! È stato fantastico: non vedo l'ora di raccontarlo a tutti all'orfanotrofio. Captain Grayson... sembrava proprio un pirata! Da grande voglio essere un pirata fantasma anch'io!$B$BGrazie di avermi portato a Westfall, $N. So che là fuori, nelle terre selvagge di Westfall, ci sono cose che fanno paura, e spero di non essere stato troppo una seccatura. Sei $Gfantastico:fantastica;!",
  en_title = "Spooky Lighthouse",
  en_obj = "Take the orphan to see the lighthouse off the coast of Westfall.$B",
}
T[1688] = {
  title = "Surena Caledon",
  desc = "Avevo un'allieva di nome Surena Caledon. Stava dove stai tu ora, desiderosa di imparare la magia degli stregoni, e con un talento non da poco. Per di più era giovane e piacevole allo sguardo. Se solo me ne fossi accorto allora, quella sgualdrina traditrice!$B$BQuella ladra è scappata con uno dei Defias, Erlan Drudgemoor. La sua perdita conta poco, ma le avevo regalato un Bloodstone Choker che devo riavere.$B$BOra la sua vita non significa niente per me. La troverai al Brackwell Pumpkin Patch. Recupera ciò che è mio.",
  obj = "Recupera il Surena's Choker per Gakin the Darkbinder, a Stormwind.",
  progress = "Anche i più anziani e saggi possono perdere la testa davanti alle lusinghe della giovinezza e della bellezza, $N. Un consiglio che faresti bene a ricordare per tutta la vita.",
  reward = "Surena aveva talento, ma non abbastanza da padroneggiare da sola la magia degli stregoni. È un peccato vedere un talento sprecato, ma a volte è necessario.$B$BSpero che l'investimento che ho fatto su di te dia risultati diversi.",
  en_title = "Surena Caledon",
  en_obj = "Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind.",
}
T[1689] = {
  title = "Il vincolo",
  desc = "Recuperando il mio collare e battendo Surena, hai dimostrato di essere capace almeno quanto lei.$B$BDetto questo, vedo che hai un disperato bisogno di addestramento. Sai gestire i flussi della magia, sì, ma essere uno stregone è molto più di questo.$B$BTi mostrerò come comandare un Voidwalker, ma prima devi richiamarne uno in un cerchio di evocazione e sottometterlo con qualunque arma, fisica o magica, tu abbia a disposizione. Usa la magia di questo collare nel cerchio di evocazione qui sotto.",
  obj = "Usando il Bloodstone Choker, evoca e sottometti un Voidwalker, poi riporta il Bloodstone Choker a Gakin the Darkbinder, a Stormwind.",
  progress = "Non posso mostrarti come controllare un Voidwalker finché non ne avrai sopraffatto uno.",
  reward = "Hai fatto meglio di quanto mi aspettassi, $N, ma bene quanto speravo. Ora puoi imparare a comandare il Voidwalker che hai soggiogato, un alleato che ti sarà prezioso nelle prove che di certo ti aspettano.$B$BPer ora non ho altro da insegnarti, ma con te sono ben lontano dall'aver finito, $N.",
  en_title = "The Binding",
  en_obj = "Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind.",
}
T[1692] = {
  title = "Smith Mathiel",
  desc = "Ho messo in una cassa l'elunite che hai raccolto. Portala al fabbro Mathiel, e lui ti forgerà un'arma di elunite.$B$BMathiel è a sud, dall'altra parte di questo edificio.",
  obj = "Porta la Case of Elunite a Smith Mathiel.",
  progress = "Salve, giovane $C. Come posso servirti con la mia arte?",
  reward = "Ah, l'Elunite Ore. È un metallo splendido da lavorare, perché è benedetto dalla dea Elune in persona. Sarebbe un onore forgiare armi con esso.$B$BAttendi, per favore, mentre lavoro...",
  en_title = "Smith Mathiel",
  en_obj = "Bring the Case of Elunite to Smith Mathiel. ",
}
T[1693] = {
  title = "Armi di elunite",
  reward = "$N, ho forgiato queste armi con l'elunite che mi hai portato. Per favore, prendi quella che ti si addice di più.$B$BE devo ringraziarti. Lavorare l'elunite è sia un onore sia un piacere.",
  en_title = "Weapons of Elunite",
}
T[1698] = {
  title = "Yorus Barleybrew",
  desc = "Yorus Barleybrew ha lanciato una sfida a tutti i guerrieri valenti dell'Alleanza. Aspetta alla Lakeshire Inn, a Redridge, e promette una grande ricompensa a chiunque riesca a superare la sua prova.",
  obj = "Parla con Yorus Barleybrew.",
  reward = "Ah! Quindi hai sentito parlare della mia sfida, eh?$B$BBeh, siediti e ascolta. Bevi qualcosa, e gustatelo... perché potrebbe essere l'ultimo.",
  en_title = "Yorus Barleybrew",
  en_obj = "Speak with Yorus Barleybrew.",
}
T[1699] = {
  title = "La Prova di Rethban",
  desc = "La mia sfida la chiamo la Prova di Rethban. Per superarla, devi solo entrare nelle Rethban Caverns, arrivare al primo bivio e tornare qui. Facile! Se non fosse per qualche piccolo intoppo...$B$BDevi tornare entro un'ora.$B$BSulla strada ci sono mucchi di gnoll di Redridge.$B$BPrima di partire, devi mandare giù un sorso della bevanda tipica della mia famiglia: la Barleybrew Scalder!$B$BAllora, che ne dici? Le Rethban Caverns sono sulle colline a nord di Lakeshire. Sei $Gpronto:pronta; ad affrontare la Prova di Rethban?",
  obj = "Entra nelle Rethban Caverns, raggiungi il primo bivio e torna da Yorus Barleybrew entro il tempo stabilito.$B$BNon devi morire né rilasciare lo spirito.",
  progress = "Il tempo stringe, $N. Se fossi in te, mi darei una mossa...",
  reward = "Ce l'hai fatta! Ben fatto! Tre urrà per $N!",
  en_title = "The Rethban Gauntlet",
  en_obj = "Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.$B$BYou must not die and release your spirit.",
}
T[1700] = {
  title = "Grimand Elmore",
  desc = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre facevo la tua armatura, e devo farli avere a Grimand Elmore. È qui nel Dwarven District, nella bottega di armi.$B$BE abbassati quando glieli dai. È orgogliosissimo della sua abilità, e non gli piacerà l'idea di imparare qualcosa da me...",
  obj = "Porta Furen's Notes a Grimand Elmore.",
  progress = "Salve, piacere di conoscerti. Come posso esserti utile?",
  reward = "L'ha scritto Furen? Come si permette! Ma se gli ho insegnato tutto quello che sa! Pensare che possa insegnarmi qualcosa è un oltraggio! Un oltraggio!$B$BMm... però c'è una cosa nei suoi appunti che vorrei provare...",
  en_title = "Grimand Elmore",
  en_obj = "Bring Furen's Notes to Grimand Elmore.",
}
T[1701] = {
  title = "Maglia temprata nel fuoco",
  desc = "Ti ho dato un bello scudo, ma non dobbiamo fermarci qui. Conosco i segreti per fare un'armatura di maglia durissima. Non è facile e servono materiali molto rari, ma se sei $Gdisposto:disposta; a darti da fare, te ne farò un pezzo.$B$BChe ne dici, $N? Se sei all'altezza della sfida, ti darò un elenco di cosa procurarti e dove trovarlo.",
  obj = "Raccogli i materiali che servono a Furen Longbeard e portaglieli, a Stormwind.",
  progress = "Come va la caccia al tesoro, $N? Hai i materiali?",
  reward = "Hai preso tutto? Incredibile! Temevo proprio che quelle chimere ti avrebbero divorato!$B$BBeh, mettiamoci al lavoro su quell'armatura...",
  en_title = "Fire Hardened Mail",
  en_obj = "Gather the materials Furen Longbeard requires, and bring them to him in Stormwind.",
}
T[1702] = {
  title = "Il fabbro di scudi",
  desc = "Hai davvero dimostrato di che pasta sei $Gfatto:fatta; quando hai affrontato la Prova di Rethban, $N. E io mantengo la parola. Ti darò la ricompensa che ti ho promesso...$B$BSolo che si trova a Stormwind.$B$BParla con il mio amico Furen Longbeard, nel Dwarven District di Stormwind. È il miglior fabbro di scudi che incontrerai mai, e mi deve un grosso favore.$B$BEcco, porta a Furen questo barile di Barleybrew Scalder e chiedigli uno scudo. Te ne darà uno bello.",
  obj = "Porta il Cask of Scalder a Furen Longbeard.",
  progress = "Salve! Che sete, di questi tempi, non trovi?",
  reward = "Ah, la Barleybrew Scalder. Roba ottima! Quindi sei $Gstato:stata; da Yorus, eh?$B$BUno scudo te lo procuro, eccome! Non ne troverai uno migliore, e non è una bugia!",
  en_title = "The Shieldsmith",
  en_obj = "Bring the Cask of Scalder to Furen Longbeard.",
}
T[1703] = {
  title = "Mathiel",
  desc = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre facevo la tua armatura, e devo farli avere al fabbro Mathiel. Vive a Darnassus, che è piuttosto lontano, ma sono sicuro che sarà molto grato di imparare quello che ho imparato io.",
  obj = "Porta Furen's Notes a Mathiel.",
  progress = "Ti porgo i miei saluti, $C.",
  reward = "Sono interessanti, davvero molto interessanti. Il mio collega nano Furen ha fatto una grande scoperta!$B$BGrazie, $N. Sarà un onore applicare le sue nuove tecniche alle mie creazioni.",
  en_title = "Mathiel",
  en_obj = "Bring Furen's Notes to Mathiel.",
}
T[1704] = {
  title = "Klockmort Spannerspan",
  desc = "Ho fatto una copia dei miei appunti sulle tecniche che ho imparato mentre facevo la tua armatura, e mi serve qualcuno che li porti a Klockmort Spannerspan. È un fabbro gnomo di Ironforge, e quando scoprirà quello che ho imparato... scommetto che si strapperà la barba per l'emozione.",
  obj = "Porta Furen's Notes a Klockmort Spannerspan.",
  progress = "Buona giornata. O buongiorno, o buonasera: da quaggiù non riesco a capirlo. Allora, hai affari per me?",
  reward = "Oh, cielo! Questi appunti sono fantastici! E per giunta... sono incredibili, sono stupefacenti e mi fanno tremare le ginocchia!$B$BFuren ha fatto una scoperta! Una vera scoperta! Non vedo l'ora di provare la sua nuova tecnica!",
  en_title = "Klockmort Spannerspan",
  en_obj = "Bring Furen's Notes to Klockmort Spannerspan.",
}
T[1705] = {
  title = "Burning Blood",
  desc = "Mi secca ammetterlo, ma Furen potrebbe aver davvero scoperto qualcosa. Per esserne sicuro, però, devo provare le sue tecniche su un'armatura nuova. Se mi aiuti con i materiali, $N, l'armatura potrai tenerla tu.$B$BPer fare questa armatura mi servono dei campioni di Burning Blood e una Burning Rock.$B$BL'unico posto che conosco dove trovarli è Duskwood. I worgen Nightbane che hanno la loro base nella miniera di Roland's Doom hanno il Burning Blood, e il loro capo, Gutspill, avrà la roccia.$B$BChe la fortuna ti metta le ali ai piedi, $N.",
  obj = "Porta 20 fiale di Burning Blood e 1 Burning Rock a Grimand Elmore, a Stormwind.",
  progress = "$N, hai il Burning Blood e la Burning Rock? Mi servono per completare l'armatura.",
  reward = "Bel lavoro! Ora, se vuoi scusarmi, anch'io ho del lavoro da fare...",
  en_title = "Burning Blood",
  en_obj = "Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind.",
}
T[1706] = {
  title = "L'armatura di Grimand",
  reward = "Stento a crederci! La tecnica di Furen ha funzionato, e questa armatura dovrebbe reggere a sollecitazioni enormi.$B$BEccola, $N. E grazie. Non avrei creduto alla scoperta di Furen se tu non avessi raccolto i materiali che mi servivano per metterla alla prova di persona.",
  en_title = "Grimand's Armor",
}
T[1708] = {
  title = "Corallo di ferro",
  desc = "Voglio provare le nuove tecniche di Furen Longbeard su un'armatura tutta mia. E visto che tu hai aiutato Furen e lui ha aiutato me, l'armatura, una volta fatta, sarà tua!$B$BPer finire il pezzo mi serve un corallo speciale, il Searing Coral. Cresce in un solo posto: lungo la costa a sud di Menethil Harbor, nelle Wetlands.$B$BPortami abbastanza Searing Coral e mi metterò subito al lavoro sull'armatura. E sbrigati, $N. Sono così impaziente di cominciare che mi si attorcigliano le dita dei piedi!",
  obj = "Porta 20 carichi di Searing Coral a Klockmort Spannerspan, a Ironforge.",
  progress = "Salve, salve, $N! Hai il Searing Coral? Non vedo l'ora di mettermi al lavoro!",
  reward = "È questo! Ben fatto! Ora lascia che lo fonda e lo martelli, così posso combinare la tecnica di Furen con la mia, e poi vediamo che succede!$B$BOh cielo, oh cielo! Me lo sento che l'armatura sarà molto molto molto resistente!",
  en_title = "Iron Coral",
  en_obj = "Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge.",
}
T[1709] = {
  title = "La creazione di Klockmort",
  reward = "Ecco la tua armatura, $N. Il procedimento di Furen ha funzionato benissimo! Alla perfezione! Davvero a meraviglia!$B$BPotresti passarci sopra con una macchina d'assedio e riprenderebbe subito la sua forma!",
  en_title = "Klockmort's Creation",
}
T[1710] = {
  title = "Sunscorched Shells",
  desc = "Il mio collega Furen Longbeard ha fatto una scoperta che non vedo l'ora di mettere alla prova. Vorrei provarla su una nuova armatura che sto studiando, perché credo che le tecniche di Furen daranno risultati migliori.$B$BMi aiuterai? Se raccogli ciò che mi serve per fare l'armatura, ne farò un pezzo in più per te.$B$BMi servono i gusci d'uovo bruciati dal sole degli Highperch Wyvern che vivono a Highperch, nelle Thousand Needles. Cerca i gusci sotto i loro nidi, e torna da me quando ne avrai abbastanza.",
  obj = "Porta 20 Sunscorched Shell a Mathiel, a Darnassus.",
  progress = "Hai i gusci, $N? Sono molto robusti, e se ne può ricavare una lacca con cui rivestirò gli anelli della mia nuova armatura di maglia.",
  reward = "Ah, grazie. Andranno benissimo!$B$BComincerò subito a forgiare l'armatura...",
  en_title = "Sunscorched Shells",
  en_obj = "Bring 20 Sunscorched Shells to Mathiel in Darnassus.",
}
T[1711] = {
  title = "L'armatura di Mathiel",
  reward = "Ho finito il tuo pezzo d'armatura, e ne sono molto soddisfatto. Le nuove tecniche di Furen si sono fuse alla perfezione con le mie, e sono sicuro che questa armatura si dimostrerà molto resistente.$B$BGrazie, $N. Che ti sia utile nelle battaglie future.",
  en_title = "Mathiel's Armor",
}
T[1712] = {
  title = "Cyclonian",
  desc = "Ho passato secoli a osservare questo luogo. Osservo, perché un giorno possa vedere cadere il grande Cyclonian. Ma non ho ancora trovato un campione capace di sconfiggere il signore del vento.$B$BForse sei tu quel campione.$B$BDimostramelo. Raccogli gli oggetti che mi servono per evocare Cyclonian, e saprò che sei $Gun grande guerriero:una grande guerriera;. Forse allora potrai sconfiggerlo e prendere il suo Whirlwind Heart.$B$BSe ci riuscirai, infonderò il potere del cuore in un'arma, e quell'arma la darò a te.$B$BEcco una pergamena con gli oggetti che mi servono.",
  obj = "Porta gli oggetti elencati nella Bath'rah's Parchment a Bath'rah the Windwatcher, ad Alterac.",
  progress = "Hai gli oggetti, $N? Raccoglierli è la prova che mi serve per sapere che hai la forza di affrontare Cyclonian.",
  reward = "Hai raccolto gli oggetti per il mio incantesimo, e mi hai mostrato la tua forza e la tua astuzia. Ma la prossima fase della nostra impresa è ancora più pericolosa.$B$BSperiamo che la tua forza non vacilli.",
  en_title = "Cyclonian",
  en_obj = "Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.",
}
T[1713] = {
  title = "L'evocazione",
  desc = "Sono pronto a compiere il rituale per evocare Cyclonian. Quando sarà evocato, dovrai sconfiggerlo e prendere il suo Whirlwind Heart. Lo userò per infondere in un'arma il potere di Cyclonian.$B$B$N, sei $Gpronto:pronta; ad affrontare il signore del vento?",
  obj = "Porta il Whirlwind Heart a Bath'rah Windwatcher.",
  progress = "$N, devo avere il Whirlwind Heart!",
  reward = "Ce l'hai fatta! Hai sconfitto Cyclonian e hai preso il Whirlwind Heart!",
  en_title = "The Summoning",
  en_obj = "Bring the Whirlwind Heart to Bath'rah Windwatcher.",
}
T[1714] = {
  title = "Essence of the Exile",
  progress = "Il calderone ribolle. I suoi vapori ti chiamano...",
  reward = "Gli amuleti affondano lentamente nelle profondità del calderone...$B$BUna grossa bolla sale in superficie e scoppia...$B$B...e appare un grumo di roccia fusa che ribolle.",
  en_title = "Essence of the Exile",
}
T[1715] = {
  title = "Lo Slaughtered Lamb",
  desc = "Hmph. Un tempo tutti gli stregoni del Khaz Modan venivano addestrati sotto la guida dei maestri di Gnomeregan, ma ora che siamo stati tutti costretti a trasferirci in questa tana di topi a Ironforge, e che Magni ha deciso di tenerci d'occhio, dobbiamo mandare i nostri novizi ad addestrarsi a Stormwind.$B$BPer fortuna Gakin non è uno sprovveduto, quindi imparerai comunque quello che ti serve, ma mi fa ribollire il sangue!$B$BComunque, troverai Gakin nel seminterrato dello Slaughtered Lamb, a Stormwind.",
  obj = "Presentati da Gakin the Darkbinder, nel Mage Quarter di Stormwind.",
  reward = "Ti manda Blackwrench, eh? Quei dannati stregoni di Ironforge devono sistemare le loro faccende. A Stormwind c'è poco spazio e ci sono pochi insegnanti. Con tutto questo via vai, prima o poi attireremo l'attenzione.",
  en_title = "The Slaughtered Lamb",
  en_obj = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1716] = {
  title = "Divoratrice di anime",
  desc = "Una Succubus è una divoratrice di anime, una distruttrice di cuori e una dominatrice di menti. Non conosce altro che il male.$B$BSarà questa la creatura che imparerai a evocare e controllare, ma non può essere portata nel nostro mondo senza uno stimolo.$B$BCon un simbolo d'amore come esca, risponderà di certo al tuo richiamo. Allora potrai sconfiggerla e farne il tuo strumento.$B$BSarà difficile trovare qualcosa del genere, però. Dovresti parlare con Takar the Seer. Lo troverai nelle Barrens di Kalimdor, vicino a Camp Taurajo.",
  obj = "Parla con Takar the Seer, nelle Barrens.",
  reward = "La traversata è stata difficile, $N? Hai fatto molta strada per parlare con me. Ma non temere: so perché Gakin ti ha mandato, e ha fatto bene, perché posso aiutarti nella tua ricerca.",
  en_title = "Devourer of Souls",
  en_obj = "Speak with Takar the Seer in the Barrens.",
}
T[1717] = {
  title = "La convocazione di Gakin",
  desc = "$N! Non mi aspettavo di vederti da queste parti, ma mi avevano chiesto di tenere gli occhi aperti nel caso passassi.$B$BÈ più che ora che tu riceva altro addestramento, quindi la prossima volta che sei a Stormwind dovresti passare da Gakin. Ti starà aspettando.",
  obj = "Presentati da Gakin the Darkbinder, nel Mage Quarter di Stormwind.",
  reward = "Sono contento che qualcuno sia riuscito a rintracciarti, $N. Cominciavo a temere il peggio. Sarebbe un peccato perderti, dopo tutto il tempo che abbiamo investito su di te.$B$BMa ne parleremo più tardi. Adesso conta solo il tuo addestramento.",
  en_title = "Gakin's Summons",
  en_obj = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1718] = {
  title = "L'isolano",
  desc = "La tua fama di $Gguerriero:guerriera; cresce, $N. Ora è il momento di misurarti con i tuoi pari e di vedere a che punto sei.$B$BAl largo della costa delle Barrens, a sud di Ratchet, c'è un'isola. Si chiama Fray Island, ed è un luogo dove i guerrieri si incontrano.$B$BSi incontrano, e combattono.$B$BParla con il capo dei guerrieri di Fray Island, Klannoc Macleod. Se ti riterrà $Gdegno:degna;, Klannoc ti guiderà più avanti sulla via del guerriero.$B$BPer raggiungere Fray Island, cerca le secche del banco di sabbia lungo la Merchant Coast.",
  obj = "Parla con Klannoc Macleod.",
  reward = "Salve, $Gguerriero:guerriera;. Mi fa piacere vedere che sei $Garrivato:arrivata; a Fray Island. Spero che sia di tuo gradimento...",
  en_title = "The Islander",
  en_obj = "Speak with Klannoc Macleod.",
}
T[1719] = {
  title = "La Zuffa",
  desc = "Se vuoi imparare da me, prima devi superare la Zuffa. È una sfida che noi di Fray Island offriamo ai guerrieri emergenti che si credono duri, e se riesci a superarla saprò che lo sei davvero.$B$BPer cominciare, entra in mezzo a quella folla laggiù e sali sulla grata. Così Twiggy Flathead saprà che sei $Gpronto:pronta;, e ti manderà contro degli sfidanti.$B$BBatti tutti gli sfidanti e lui chiamerà Big Will. Uccidi Big Will, e torna da me entro il tempo concesso.",
  obj = "Uccidi Big Will, poi parla con Klannoc Macleod, a Fray Island.",
  progress = "Hai completato la tua sfida?",
  reward = "Ben fatto, $N. Hai superato la Zuffa!$B$BSei $Gun guerriero degno:una guerriera degna;, ed è un onore per me insegnarti...",
  en_title = "The Affray",
  en_obj = "Kill Big Will, then speak to Klannoc Macleod on Fray Island.",
}
T[1738] = {
  title = "Heartswood",
  desc = "In attesa del tuo arrivo, ho usato la mia vista per scrutare il mondo attraverso le nebbie del tempo. Ho trovato ciò che cerchi.$B$BDurante la Guerra degli Antichi, due amanti caddero insieme in battaglia. Là dove esalarono l'ultimo respiro crebbe un albero noto come Heartswood, simbolo del loro amore eterno.$B$BDovrebbe bastare a tentare una Succubus. Lo troverai tra le rovine di Ordil'Aran, nella parte nord-occidentale della foresta di Ashenvale.",
  obj = "Recupera l'Heartswood ad Ashenvale e portalo a Gakin the Darkbinder, nel Mage Quarter di Stormwind.",
  progress = "La tua ricerca ha avuto successo, $N?",
  reward = "Sì, vedo che andrà benissimo. Lascia che ci lavori un momento...$B$BTakar è un tipo pieno di risorse, vero? Se solo riuscissi a convincerlo a tornare alla civiltà.",
  en_title = "Heartswood",
  en_obj = "Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.",
}
T[1739] = {
  title = "Il vincolo",
  desc = "Con l'Heartswood Core potrai lanciare un incantesimo nel cerchio di evocazione, nella cripta qui sotto, per aprire un portale da cui la Succubus possa passare.$B$BFa' attenzione, $N: le Succubus hanno sopraffatto anche le menti più forti.$B$BUna volta che l'avrai battuta e rimandata nel vuoto, torna da me e ti mostrerò come richiamarla e controllarla.",
  obj = "Usando l'Heartswood Core, evoca e sottometti una Succubus, poi riporta l'Heartswood Core a Gakin the Darkbinder, allo Slaughtered Lamb.",
  progress = "A volte mi chiedo se Surena non fosse una Succubus travestita, mandata a distorcere e confondere la mia mente... Ah! Credo di darle troppo credito.",
  reward = "Ben fatto, ben fatto, $N. Vedo che abbiamo fatto bene a decidere di addestrarti. Le tue prove non deludono di certo.$B$BNon ho esitazioni a mostrarti come controllare la Succubus che hai appena vincolato. Osserva con attenzione.",
  en_title = "The Binding",
  en_obj = "Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.",
}
T[1740] = {
  title = "L'Orb of Soran'ruk",
  desc = "Quando i demoni della Legione cadono in disgrazia, i loro spiriti vengono imprigionati in sfere e distribuiti ai loro maghi e stregoni.$B$BMolte furono portate su Azeroth dai loro servitori. Anche in frammenti, possiedono ancora i poteri dei demoni intrappolati al loro interno.$B$BL'Orb of Soran'ruk fu spezzata in due parti: una fu ridotta in pezzi ancora più piccoli, usati dagli accoliti del Martello del Crepuscolo nelle Blackfathom Deeps. L'altra, più grande, era in possesso di un mago di Shadowfang Keep. Trovale e potrò ricomporla.",
  obj = "Trova 3 Soran'ruk Fragment e 1 Large Soran'ruk Fragment e riportali a Doan Karhan, nelle Barrens.",
  progress = "Mi ci sono voluti molti anni per raccogliere i pezzi della sfera di Zargain, ma mi è stata molto utile, come sono sicuro che l'Orb of Soran'ruk sarà utile a te.",
  reward = "Sì... La sfera non era molto frammentata, e qui ci sono quasi tutti i pezzi. Ricomporli è una cosa semplice, e Soran'ruk tornerà intera.$B$BHo dedicato la mia vita allo studio delle sfere della Legione Infuocata e alla loro ricostruzione. Mi hai fatto un favore raccogliendo questi pezzi da studiare, e te li restituirò — completamente ricostruiti — nella forma che preferisci.",
  en_title = "The Orb of Soran'ruk",
  en_obj = "Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.",
}
T[1758] = {
  title = "Tome of the Cabal",
  desc = "Per richiamare un Felhunter da sfidare non basterà un semplice cerchio di evocazione.$B$BI miei tre accoliti e io ti aiuteremo a creare i cerchi magici. Ti serve una copia del Tome of the Cabal, che abbiamo perduto da tempo. Fu scritto dal primo gruppo di stregoni che riuscì a evocare un Felhunter senza aiuto.$B$BForse Krom Stoutarm può aiutarti. Oggi è uno stregone girovago, e passa le giornate ad accumulare testi antichi e ad aggirarsi furtivo nella biblioteca di Ironforge.",
  obj = "Parla con Krom Stoutarm, a Ironforge.",
  reward = "Il Tome of the Cabal? Mm... mi dice qualcosa. Però qui non l'ho mai visto — e credimi, mi ricordo ogni libro che leggo.$B$BMm...$B$BAh, sì! Ne ho visto dei riferimenti nei cataloghi della biblioteca.",
  en_title = "Tome of the Cabal",
  en_obj = "Speak with Krom Stoutarm in Ironforge.",
}
T[1778] = {
  title = "Il Tome of Divinity",
  desc = "Vedrò di organizzarmi per tornare presto a casa. Spero che Stephanie stia bene, a Stormwind. Non vedo l'ora di rivederla. Alla prossima, $C.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "Allora, sei $Ggià tornato:già tornata;, eh? E di grazia, cosa hai combinato mentre eri via?$B$BSei $Griuscito:riuscita; ad aiutare una nobile causa? Forse hai imparato il valore della carità, o qualcosa di più sui tuoi doveri verso i cittadini di Azeroth. Dimmi, chi hai aiutato e come... Notevole, $N, queste sono di certo le azioni di chi segue la Luce.$B$BUn simile sacrificio sarà sempre ricompensato, col tempo.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[1779] = {
  title = "Il Tome of Divinity",
  desc = "Voglio che tu prenda questo, $N. Si chiama Symbol of Life.$B$BHai dato prova di carità e di pazienza, e ora voglio che tu dimostri quanto sei $Gdiventato:diventata; abile sia nel combattimento sia nel potere.$B$BMio marito Muiredon è tornato di recente da uno scontro con alcuni nani Dark Iron, e ne è uscito vivo per un pelo — è laggiù a farsi curare le ferite da uno dei nostri sacerdoti.$B$BPrendi il Symbol e parla con lui. Se riesci ad aiutarlo, ci parleremo di nuovo presto. Che la Luce risplenda su di te.",
  obj = "Prendi il Symbol of Life e parla con Muiredon Battleforge, a Ironforge.",
  reward = "*tossisce*$B$BBuongiorno a te, $C. Non badare alle mie ferite, il buon sacerdote qui si prenderà cura del vecchio Muiredon a tempo debito. Non ho ancora bisogno del potere di quel Symbol of Life che hai lì.$B$BAllora, mia moglie ti ha mandato qui a parlare con me, eh? D'accordo. Mi prenderò il tempo di parlarti — ti racconterò esattamente cos'è successo a Muiredon e al suo migliore amico Narm, un paladino proprio come te.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge.",
}
T[1780] = {
  title = "Il Tome of Divinity",
  desc = "Porterò queste cose ai bambini oggi stesso. Ti prego, sta' $Gattento:attenta;, $Gbuon:buona; $C. Non capita spesso che $Guomini:donne; della tua levatura si facciano vedere in città, ma hai dimostrato che i paladini qui a Stormwind non volteranno mai le spalle a chi ha bisogno.$B$BAddio.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Sei $Gtornato:tornata; così in fretta, $N. E cosa hai combinato mentre eri $Glontano:lontana; dalla Cathedral?$B$BHai aiutato una nobile causa? Forse hai imparato il valore della carità, o qualcosa di più sui tuoi doveri verso i cittadini di Azeroth. Dimmi, chi hai aiutato e come... Be', sono colpito, $N, queste sono di certo le azioni di chi segue la Luce e mette gli altri prima di sé.$B$BUn simile sacrificio sarà sempre ricompensato, col tempo.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1781] = {
  title = "Il Tome of Divinity",
  desc = "Prendi questo, $N. Si chiama Symbol of Life.$B$BHai dato prova di carità e di pazienza, e ora è giunto il momento di vedere se sei abbastanza potente da concentrare uno dei più grandi doni della Luce.$B$BIl mio amico Gazin è tornato di recente da uno scontro con alcuni Defias a Elwynn, vicino all'Heroes' Vigil — ne è uscito vivo per un pelo. È vicino all'altare a farsi curare le ferite dai nostri sacerdoti.$B$BPrendi il Symbol e parla con lui. Se riesci ad aiutarlo, ci parleremo di nuovo presto. Che tu possa crogiolarti nella gloria della Luce.",
  obj = "Porta il Symbol of Life a Gazin Tenorm, a Stormwind.",
  reward = "*tossisce*$B$BPiacere di conoscerti, $C. Non badare alle mie ferite, il buon sacerdote qui stavolta si prenderà cura del vecchio Gazin. Non avrò bisogno del potere di quel Symbol of Life che hai lì... non ancora, almeno.$B$BAllora, ti ha mandato Duthorian a parlare con me, eh? D'accordo. Ti racconterò esattamente cosa è capitato a me e al mio amico Henze. E con un po' di fortuna, e un po' di abilità da parte tua, forse puoi ancora aiutarci tutti.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life to Gazin Tenorm in Stormwind.",
}
T[1782] = {
  title = "L'armatura di Furen",
  reward = "Ecco la tua armatura, $N. Reggerà agli assalti più violenti, o non mi chiamo Furen Longbeard!$B$BE devo ringraziarti. Ho imparato molto lavorando con i materiali$Bche mi hai portato. Credo che un giorno farò un'altra scoperta!$B$BManderò quello che ho imparato ad altri$Bfabbri dell'Alleanza.$B$BDirò loro che mi sei $Gstato:stata; di grande aiuto, e magari vorranno ricambiare il favore.",
  en_title = "Furen's Armor",
}
T[1783] = {
  title = "Il Tome of Divinity",
  desc = "Stavamo spiando alcuni dei nani Dark Iron che si sono trincerati a sud dell'Helm's Bed Lake. Sapevamo che stavano tramando qualcosa, così Narm e io abbiamo pensato di dare un'occhiata più da vicino — siamo riusciti a vedere il loro capo che dava ordini ad alcuni dei suoi uomini.$B$BNarm e io ne abbiamo approfittato per farne fuori qualcuno, ma si sono rivelati più duri del previsto, e altri di loro ci sono piombati addosso. Narm mi ha detto di scappare e di andare a cercare rinforzi, ed eccomi qui.$B$BNarm ha bisogno di aiuto, e non avrò pace finché non l'avrà avuto.$B$BPuoi dare una mano, $N?",
  obj = "Prendi il Symbol of Life e riporta in vita Narm Faulk, a Dun Morogh.",
  reward = "Non so come ringraziarti, $Gfratello:sorella;.$B$BSe porti il Symbol of Life, posso solo pensare che ti abbiano mandato qui Tiza e Muiredon ad aiutarmi.$B$BÈ vero, sono caduto per mano dei Dark Iron mentre cercavo di prendere uno dei loro documenti: ho resistito abbastanza a lungo da permettere a Muiredon di fuggire, ma la Luce mi aveva quasi del tutto accolto quando sei $Garrivato:arrivata; tu. Il fatto che tu sia $Gstato:stata; abbastanza potente da usare il Symbol significa grandi cose per te, ma ci sarà tempo per parlarne più avanti.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh.",
}
T[1784] = {
  title = "Il Tome of Divinity",
  desc = "Prima che cadessi in battaglia, Muiredon e io avevamo quasi sconfitto una delle spie Dark Iron vicino a quella casetta. Avevamo visto il loro capitano passare degli ordini alle spie, e abbiamo cercato di ucciderlo e di prendere gli ordini.$B$BAlcuni membri del consiglio di Ironforge non credono ancora che a Dun Morogh ci siano nani Dark Iron. Se prendiamo uno di quei documenti, non solo avremo la prova dei loro movimenti, ma forse anche un'idea di cosa stanno tramando.$B$BPrendi uno di quei documenti e portalo a Muiredon, $N.",
  obj = "Recupera un Dark Iron Script dai nani Dark Iron vicino all'Helm's Bed, e torna da Muiredon Battleforge, a Ironforge.",
  progress = "Sei $Gtornato:tornata;! Mi fa piacere vederti, $N. Le mie ferite sono guarite e sono quasi pronto a tornare all'Helm's Bed Lake, appena riesco a convincere mia moglie che starò bene.",
  reward = "Ah ah! Ce l'hai fatta! Hai salvato Narm, e hai trovato la prova che serve a mia moglie da portare al consiglio. Sei una benedizione della Luce, se mai ne ho vista una... senza contare mia moglie, s'intende.$B$BGrazie ancora, $N.",
  en_title = "The Tome of Divinity",
  en_obj = "Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge.",
}
T[1785] = {
  title = "Il Tome of Divinity",
  desc = "Vedo che mia moglie laggiù è già raggiante d'orgoglio. Faresti meglio a portare le tue chiappe laggiù, e alla svelta. Credo proprio che voglia dirti qualcosa.$B$BLa Luce sia con te, possente $C. Ti cercherò sul campo di battaglia contro il Flagello e quei Dark Iron, quando verrà il momento.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "Oggi hai fatto un grande favore a tutta Ironforge, $N. Sono fiera di annoverarti tra noi, e se ti senti $Gpronto:pronta;, vorrei benedirti con questa pergamena. Il Symbol of Life avrebbe funzionato solo nelle mani di un paladino pronto per una delle più grandi benedizioni della Luce — il potere di riportare in vita i morti.$B$BTi insegnerò l'abilità di resuscitare i tuoi compagni. Usala con saggezza, $N, e grazie, a nome mio, di mio marito e di Ironforge.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[1786] = {
  title = "Il Tome of Divinity",
  desc = "Henze e io eravamo arrivati all'Heroes' Vigil, un'isola in mezzo allo Stone Cairn Lake, nel nord-est di Elwynn. Avevamo sentito che i Defias si erano infiltrati oltre i nostri confini, e volevamo una prova da portare ai consiglieri del re.$B$BAbbiamo avvistato un paio di quei farabutti che esaminavano dei documenti, e li abbiamo attaccati. Purtroppo siamo stati presto sopraffatti da altri maghi.$B$BHenze li ha trattenuti per me mentre scappavo... quello sciocco, a fare il coraggioso.$B$BÈ ancora là fuori, Henze. Puoi aiutarci, $N?",
  obj = "Prendi il Symbol of Life e riporta in vita Henze Faulk, a Elwynn.",
  reward = "Grazie, $Gfratello:sorella;.$B$BVisto che impugni il Symbol of Life, posso supporre che ti abbiano mandato Duthorian o Gazin?$B$BSono caduto per mano degli incantatori Defias mentre Gazin e io cercavamo di sottrarre loro i piani: ho resistito abbastanza a lungo da permettere a Gazin di fuggire, ma alla fine la loro magia mi ha sopraffatto.$B$BMa tu sei $Griuscito:riuscita; a riportarmi indietro: la capacità di usare il Symbol non è concessa a chiunque, $N. È di buon auspicio per te che tu sia $Griuscito:riuscita; a caricarlo con la tua fede.",
  en_title = "The Tome of Divinity",
  en_obj = "Take the Symbol of Life and resurrect Henze Faulk in Elwynn.",
}
T[1787] = {
  title = "Il Tome of Divinity",
  desc = "Avremo tempo di parlare ancora del Symbol più avanti. Ora l'importante è prendere quelle carte che abbiamo visto esaminare dai Defias. Se riusciamo a metterci le mani sopra, potremo dimostrare che i Defias si sono infiltrati a Elwynn, e magari capire qualcosa dei loro piani.$B$BPer ora non sono in condizioni di combattere, $N. Pensi di essere abbastanza forte da prendere quelle carte ai Defias qui sull'isola?$B$BSe riesci a prenderle, portale a Gazin e digli che sto bene.",
  obj = "Recupera un Defias Script dai Defias Rogue Wizard a Elwynn, e torna da Gazin Tenorm, a Stormwind.",
  progress = "Henze è salvo, $N? Ci sei $Griuscito:riuscita;?$B$BTra la tua abilità con le armi e il potere della Luce, immagino che l'Heroes' Vigil sia al sicuro da qualunque minaccia dei Defias, ma questo spetta al Re e ai suoi consiglieri dirlo.",
  reward = "Magnifico! Ce l'hai fatta, e hai salvato Henze. La Luce è con te, non c'è dubbio, $N!",
  en_title = "The Tome of Divinity",
  en_obj = "Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind.",
}
T[1788] = {
  title = "Il Tome of Divinity",
  desc = "Porterò il documento ai consiglieri del re dopo che Duthorian gli avrà dato un'occhiata, ma nel frattempo dovresti andare a parlare con Duthorian. Vorrà di sicuro darti una pacca sulla spalla!$B$BGrazie ancora, $N. Spero che ci rivedremo. Sei di sicuro $Gun alleato:un'alleata; che sono fiero di chiamare $Gamico:amica;.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "Oggi hai fatto un buon lavoro, $N. Dovresti andare un po' $Gfiero:fiera; di quello che hai realizzato.$B$BE ancora di più dovresti essere $Gfiero:fiera; delle tue capacità. Non tutti possono usare il potere del Symbol of Life. Invocare la Luce per riportare indietro i morti significa che sei $Gpronto:pronta; per uno dei più grandi onori del paladino: il potere della resurrezione.$B$BAvrai il potere di riportare indietro i compagni caduti, proprio come hai fatto con Henze.$B$BStammi bene, $N. La Luce risplende su di te, e dovresti accoglierla del tutto.",
  en_title = "The Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[1789] = {
  title = "Il Symbol of Life",
  reward = "Affrettati, $N: se fallisci, più di una vita è in pericolo.$B$BSe per qualche motivo non riesci ad aiutare Muiredon e Narm, torna da me e ti darò un altro Symbol of Life per il viaggio.$B$BNon scambiare il mio aiuto per semplice carità: devi dimostrarti $Gdegno:degna; come $Gqualunque altro:qualunque altra; $C, e i fallimenti continui potrebbero ricadere su di te più avanti.",
  en_title = "The Symbol of Life",
}
T[1790] = {
  title = "Il Symbol of Life",
  reward = "Affrettati, $N: se fallisci, più di una vita è in pericolo.$B$BSe per qualche motivo non riesci ad aiutare Gazin e Henze, torna da me e ti darò un altro Symbol of Life per il viaggio.$B$BNon scambiare il mio aiuto per semplice carità: devi dimostrarti $Gdegno:degna; come $Gqualunque altro:qualunque altra; $C, e i fallimenti continui potrebbero ricadere su di te più avanti.",
  en_title = "The Symbol of Life",
}
T[1791] = {
  title = "Il Windwatcher",
  desc = "Ora che hai imparato la Berserker Stance, ti servirà una bella arma da usare con quella.$B$BParla con Bath'rah the Windwatcher, un eremita troll che vive tra le Alterac Mountains e le Western Plaguelands. È un abile fabbricante d'armi e un potente sciamano.$B$BPer trovare Bath'rah, raggiungi il fiume che scorre lungo il fianco orientale di Tarren Mill. Seguilo verso nord: Bath'rah è accampato vicino a delle rovine sulla riva est del fiume.",
  obj = "Parla con Bath'rah the Windwatcher.",
  reward = "Hai viaggiato a lungo, $Ggiovane guerriero:giovane guerriera;. Vedo fuoco nei tuoi occhi. Cerchi un'arma di grande potere, vero?$B$BPosso aiutarti nella tua ricerca. E tu puoi aiutare me nella mia.",
  en_title = "The Windwatcher",
  en_obj = "Speak with Bath'rah the Windwatcher.",
}
T[1792] = {
  title = "L'arma del turbine",
  reward = "Ho il Whirlwind Heart, e sono pronto a infonderlo nell'arma che sceglierai.$B$BScegli la tua arma, $N, e sappi che il suo potere è il potere di Cyclonian.",
  en_title = "Whirlwind Weapon",
}
T[1793] = {
  title = "Il Tome of Valor",
  reward = "È stato dimostrato che la Luce è con te, $N, ma man mano che i tempi si fanno più pericolosi, diventa importante sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?$B$BIl coraggio, qualunque sia la situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella Cathedral of Light.",
  en_title = "The Tome of Valor",
}
T[1794] = {
  title = "Il Tome of Valor",
  reward = "È stato dimostrato che la Luce è con te, $N, ma man mano che i tempi si fanno più pericolosi, diventa importante sapere quale forza si nasconde sotto la carne. Quando demoni, draghi o qualunque altro male metteranno piede nelle tue terre, la tua tempra sarà messa alla prova. Sarai abbastanza forte?$B$BIl coraggio, qualunque sia la situazione, fa parte dell'essere paladino quanto la Luce, la tua armatura e la tua arma. Proteggere i deboli e non perdere la fede sono altre due lezioni che dovrai padroneggiare mentre studi nella Cathedral of Light.",
  en_title = "The Tome of Valor",
}
T[1795] = {
  title = "Il vincolo",
  desc = "Se sei abbastanza $Gpreparato:preparata;, possiamo cominciare. Lascia che ti spieghi il procedimento.$B$BComincerò creando il cerchio di evocazione di base. Quando sarà finito, i miei accoliti useranno i Rod of Channeling per creare il cerchio maggiore.$B$BFatto questo, leggi l'incantesimo dal Tome of the Cabal, e il Felhunter verrà richiamato. Fa' attenzione, $N. Un Felhunter è un avversario potente, e mi piacerebbe vederti con la testa ancora sulle spalle.",
  obj = "Usando il Tome of the Cabal, evoca e sottometti un Felhunter, poi riporta il Tome of the Cabal a Strahad Farsan, a Ratchet.",
  progress = "Ogni stregone dovrebbe avere un Felhunter ai suoi ordini. Anche se è difficile da domare, i poteri che dà al suo padrone valgono ben più del prezzo.",
  reward = "Devo dire che sono colpito, $N. Quando affrontai il mio Felhunter, me la cavai per un pelo. Sento che hai il potenziale per diventare $Guno degli stregoni più potenti:una delle streghe più potenti; di quest'epoca.",
  en_title = "The Binding",
  en_obj = "Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.",
}
T[1798] = {
  title = "In cerca di Strahad",
  desc = "È ora che tu impari a evocare il Felhunter, $N. Qui non ho i reagenti e gli oggetti necessari per insegnartelo, quindi dovrai cercare qualcun altro, Strahad Farsan, anche lui della nostra cerchia ristretta.$B$BAbita nel porto goblin di Ratchet. Gli manderò un messaggio per avvisarlo del tuo arrivo.",
  obj = "Parla con Strahad Farsan, nelle Barrens.",
  reward = "$N? Ah, certo. Il nostro ultimo prodigio. Temo che la realtà non sia all'altezza della leggenda.$B$BNon importa: sei qui per imparare, non per sentirmi fare battute a me stesso.",
  en_title = "Seeking Strahad",
  en_obj = "Speak with Strahad Farsan in the Barrens.",
}
T[1800] = {
  title = "Lordaeron Throne Room",
  desc = "Le matrone dell'orfanotrofio dove vivo, la sera, ci raccontano grandi storie di battaglie e di leggende, se siamo stati buoni e abbiamo fatto le faccende. Una storia parlava di come cadde Lordaeron, e di come il malvagio Arthas tolse la vita a suo padre per diventare sovrano.$B$BNon aveva onore, $N! Quando sarò grande e diventerò un grande guerriero dell'Orda, la mia lama sarà guidata dall'onore, mai dal male!$B$BMi porteresti a vedere la sala del trono, per piacere? È proprio prima di dove si scende nell'Undercity.",
  obj = "Porta il tuo protetto alla vecchia Lordaeron Throne Room, che si trova poco prima della discesa nell'Undercity.",
  progress = "Siamo arrivati?",
  reward = "Quella sala del trono faceva paura, $N! Anche se era vuota, sembrava che lì fosse successo un grande male. Mi sono sentito arrabbiato... ma anche triste. Capisco perché le matrone ci raccontano storie così: io non tradirò mai il mio popolo in quel modo!$B$BGrazie di avermi portato nella sala del trono, $N. Ho imparato tante cose.",
  en_title = "Lordaeron Throne Room",
  en_obj = "Take your ward to the old Lordaeron Throne Room that lies just before descending into the Undercity.$B",
}
T[1801] = {
  title = "Tome of the Cabal",
  desc = "Per richiamare un Felhunter da sfidare non basterà un semplice cerchio di evocazione.$B$BI miei tre accoliti e io ti aiuteremo a creare i cerchi magici. Ti serve una copia del Tome of the Cabal, che abbiamo perduto da tempo. Fu scritto dal primo gruppo di stregoni che riuscì a evocare un Felhunter senza aiuto.$B$BForse Jorah Annison può aiutarti. Oggi lavora come cartografo nell'Undercity, ma di testi antichi ne sa più di chiunque io conosca.",
  obj = "Parla con Jorah Annison, nell'Undercity.",
  reward = "Fare mappe! Immagini, stime della realtà. Non so che farmene.$B$BNei libri, nel racconto, nella descrizione! È lì che sta la verità. Darei tutte le mappe di questo negozio per un solo libro sull'ascesa della negromanzia, o per un racconto del trionfo della Signora Oscura.",
  en_title = "Tome of the Cabal",
  en_obj = "Speak with Jorah Annison in the Undercity.",
}
T[1802] = {
  title = "Tome of the Cabal",
  desc = "È andato perduto, ma c'è qualche idea su dove si possa trovare.$B$BNe fu fatta una sola copia, che a un certo punto venne danneggiata: una buona parte fu strappata dalla rilegatura. Si dice che in qualche modo sia finita nelle mani dei centauri delle Thousand Needles.$B$BIl resto andò perduto al largo della costa a ovest di Southshore, mentre veniva trasportato in nave a Menethil Harbor. Non arrivò mai.$B$BIn cambio di queste informazioni ti chiedo solo una cosa: se lo trovi, portamelo, così posso vederlo.",
  obj = "Recupera il Moldy Tome e il Tattered Manuscript per Krom Stoutarm, a Ironforge.",
  progress = "Le voci si sono rivelate vere, $N?",
  reward = "Fantastico! Ora potrò unirmi ai pochi che ne hanno sbirciato il contenuto.$B$BNon vedo l'ora di studiare meglio questo testo. È un gran giorno, $N! Lasciami solo dargli un'occhiata prima che tu te ne vada. Sono sicuro che Strahad sarà disposto a mandarmene una copia.",
  en_title = "Tome of the Cabal",
  en_obj = "Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge.",
}
T[1803] = {
  title = "Tome of the Cabal",
  desc = "Ah! Vedo che sei $Gun stregone:una strega; con gusti simili ai miei. Procurarsi il Tome of the Cabal è davvero un'aspirazione degna. Sapevi che un tempo era custodito tra le mura di Lordaeron? Però fu danneggiato, e quasi metà delle pagine venne strappata. Chi commetterebbe un atto così infame?$B$BQuella metà è perduta, anche se si dice che sia finita nelle mani dei centauri delle Thousand Needles.$B$BIl resto del testo doveva essere trasferito a Ironforge, ma andò perduto durante il viaggio, sulla costa a ovest di Southshore.",
  obj = "Recupera il Moldy Tome e il Tattered Manuscript per Jorah Annison, nell'Undercity.",
  progress = "Può darsi che tu stia inseguendo delle favole, $N, ma un fondo di verità si trova anche nelle voci più assurde.",
  reward = "Bene bene bene! Cosa abbiamo qui?$B$BÈ notevole, $N. Non l'avrei creduto possibile, eppure eccolo qui, nelle mie mani: il Tome of the Cabal completo.$B$BLasciami sfogliare le sue pagine solo un momento, prima che tu riparta.",
  en_title = "Tome of the Cabal",
  en_obj = "Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity.",
}
T[1804] = {
  title = "Tome of the Cabal",
  desc = "Beh, ecco, è difficile lasciarlo andare. Ma l'hai trovato tu, e hai cose più importanti da farci, naturalmente. Solo, ti prego, ricordati di dire a Strahad che ne volevo una copia.$B$BMentre eri via, ti ha mandato un messaggio. Voleva che ti dicessi che, perché i suoi accoliti possano aiutarti con l'evocazione, dovrai procurarti tre Rod of Channeling.$B$BLui forse non sa dove trovarli, ma io sì! Gli ultimi a usarli sono stati gli orchi del clan Dragonmaw, nelle Wetlands. Io controllerei i loro incantatori!",
  obj = "Porta il Reconstructed Tome e 3 Rod of Channeling a Strahad Farsan, a Ratchet.",
  progress = "È da un po' che non ti vedo da queste parti. Hai trovato il tomo e le verghe?",
  reward = "Ben fatto! Il Tome of the Cabal e tre Rod of Channeling in perfetto stato — be', un po' graffiati, direi.$B$BSarà interessante. È da tempo che $Gun giovane stregone:una giovane strega; non affronta un Felhunter per farlo suo.",
  en_title = "Tome of the Cabal",
  en_obj = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.",
}
T[1805] = {
  title = "Tome of the Cabal",
  desc = "È uno dei testi più interessanti che abbia letto negli ultimi anni. Qui la scelta è scarsa — soprattutto libri di geografia — e li ho già letti tutti. Spero che Strahad mi mandi una copia di questo tomo quando potrà.$B$BA proposito di lui, mentre eri via mi ha mandato un messaggio. Per il tuo compito devi procurarti tre Rod of Channeling.$B$BPer avermi lasciato guardare questo testo, ti svelerò un segreto: le verghe le trovi sugli orchi del clan Dragonmaw, nelle Wetlands.",
  obj = "Porta il Reconstructed Tome e 3 Rod of Channeling a Strahad Farsan, a Ratchet.",
  progress = "Sì, $N? In cosa posso esserti utile?",
  reward = "Ben fatto! Il Tome of the Cabal e tre Rod of Channeling in perfetto stato — be', un po' graffiati, direi.$B$BSarà interessante. È da tempo che $Gun giovane stregone:una giovane strega; non affronta un Felhunter per farlo suo.",
  en_title = "Tome of the Cabal",
  en_obj = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.",
}
T[1806] = {
  title = "La prova della rettitudine",
  desc = "Perché non andiamo alla forgia e cominciamo? È da un po' che mi preparo al tuo arrivo, quindi non ci vorrà molto.$B$BQuando avremo finito, sarai molto più $Gpronto:pronta; di prima a difendere la Luce, questo te lo giuro.$B$BTi confesso una cosa, $N: vedere i frutti delle tue imprese mi rende un po' invidioso. Ma sapere che posso dare alle tue avventure un contributo tutto mio, e non da poco, mi rende contento.",
  obj = "Aspetta che Jordan Stilwell finisca di forgiare un'arma per te.",
  reward = "Eccola, $N. Un'arma degna di $Gun campione:una campionessa; della Luce come te. Le ho dato il nome di un grande paladino nanico, un mio amico. Si chiamava Verigan... Bosch Verigan.$B$BTi prego, accettala da parte mia e di mia moglie. Abbiamo un grande debito con te, e il mondo sarà un posto più sicuro con qualcuno abile come te in giro per queste terre.",
  en_title = "The Test of Righteousness",
  en_obj = "Wait for Jordan Stilwell to finish forging a weapon for you.",
}
T[1818] = {
  title = "Parla con Dillinger",
  desc = "Mi hanno detto che Deathguard Dillinger ha un lavoro per qualcuno come te. Se vuoi dimostrare il tuo valore alle forze della Signora Oscura, presentati subito da Dillinger.$B$BDeathguard Dillinger è di guardia all'estremità ovest di Brill, vicino al cimitero.",
  obj = "Parla con Deathguard Dillinger, a Brill.",
  reward = "Sei qui per una missione? Bene. Ne ho una importante, che metterà alla prova la tua abilità in combattimento... e la tua determinazione nel difendere i Reietti.",
  en_title = "Speak with Dillinger",
  en_obj = "Speak with Deathguard Dillinger in Brill.",
}
T[1819] = {
  title = "Ulag the Cleaver",
  desc = "Quando il Flagello dilagò nelle Tirisfal Glades, ne catturammo uno per studiarlo. Aveva una mente libera, e si faceva chiamare Ulag the Cleaver. Ma, anche se la sua volontà era libera, era ancora soggiogato dal Re dei Lich.$B$BSperavamo di trovare un modo per spezzare il controllo del re su Ulag, ma abbiamo fallito. Ora, finalmente, è il momento di liberarlo.$B$BLiberalo, e uccidilo.$B$BAttiva il meccanismo della pietra a forma di teschio vicino al mausoleo, a nord. Solleverà il sigillo magico che lo tiene prigioniero.$B$BPoi... tieniti $Gpronto:pronta;, $N.",
  obj = "Uccidi Ulag the Cleaver, poi parla con Deathguard Dillinger.",
  progress = "Il tuo compito non è ancora compiuto, $N. Non è saggio per un guerriero mostrare paura...",
  reward = "Ben fatto, $N. Ulag non era un agente qualsiasi del Flagello. Hai dimostrato ai Guardiamorte, e quindi alla Signora Oscura, di essere $Gun guerriero:una guerriera; di abilità e determinazione, e di meritare un ulteriore addestramento.",
  en_title = "Ulag the Cleaver",
  en_obj = "Kill Ulag the Cleaver, then speak with Deathguard Dillinger.",
}
T[1820] = {
  title = "Parla con Coleman",
  desc = "Hai dimostrato il tuo valore alla Signora Oscura; ora forse puoi dimostrarlo a uno dei suoi sudditi.$B$BColeman Farthing aspetta un guerriero disposto a essere lo strumento della sua vendetta contro i nemici dei Reietti.$B$BLo troverai alla Gallows' End Tavern, nella parte est di Brill.",
  obj = "Parla con Coleman Farthing.",
  reward = "Sì, è vero. Ho bisogno delle tue abilità in combattimento. I miei mezzi sono pochi, ma il mio compito aiuta sia me sia la causa dei Reietti. Fallo, e la tua ricompensa sarà doppia.",
  en_title = "Speak with Coleman",
  en_obj = "Speak with Coleman Farthing.",
}
T[1821] = {
  title = "I cimeli degli Agamand",
  desc = "Lavoravo per la famiglia Agamand quando ero in vita, e sono stati loro la causa della mia morte! È giusto che ora gli Agamand siano servitori senza mente del Re dei Lich.$B$BOra voglio prendermi quel che resta del loro onore. Entra nella loro cripta di famiglia e deruba gli Agamand dei cimeli di famiglia: una spada, un'ascia, un pugnale e una mazza. Portameli!$B$BLa cripta della famiglia Agamand si trova all'estremità nord degli Agamand Mills, protetta dal Flagello in agguato e dagli Agamand morti.",
  obj = "Porta a Coleman Farthing l'Agamand Family Axe, l'Agamand Family Sword, l'Agamand Family Mace e l'Agamand Family Dagger.",
  progress = "Hai i cimeli, $N?",
  reward = "Ah! Li hai recuperati! Ora l'ultima parvenza di onore e di memoria è strappata alle maledette terre degli Agamand. La famiglia non esiste davvero più!",
  en_title = "Agamand Heirlooms",
  en_obj = "Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger.",
}
T[1822] = {
  title = "L'arma di famiglia",
  reward = "Terrò tre delle armi che mi hai riportato, come ricordo del mio dolore e della mia perdita. Ma ti prego, $N, scegli il cimelio che preferisci e tienilo per te.$B$BChe ti serva meglio di quanto abbia servito i suoi maledetti vecchi proprietari.",
  en_title = "Heirloom Weapon",
}
T[1823] = {
  title = "Parla con Ruga",
  desc = "Sei $Gun guerriero:una guerriera; di talento e di fama crescente. Forse sei $Gpronto:pronta; per la prova di Ruga Ragetotem? Se è così, trova Ruga a Camp Taurajo, nelle Barrens.$B$BAspetta i guerrieri che rispondono alla sua chiamata.",
  obj = "Parla con Ruga Ragetotem.",
  reward = "Sei qui per la mia prova, $N?",
  en_title = "Speak with Ruga",
  en_obj = "Speak with Ruga Ragetotem.",
}
T[1824] = {
  title = "La prova al Field of Giants",
  desc = "Per superare questa prova, devi andare a sud, nel Field of Giants. Lì troverai una moltitudine di creature striscianti simili a insetti. Sono arrivate da poco nelle Barrens, e non mi piace ciò che annunciano.$B$BPortami le loro antenne ancora frementi, e non perdere tempo, $N, perché le antenne raccolte non fremono a lungo. Portami le antenne entro il tempo stabilito e avrai superato la prova.",
  obj = "Porta 5 Twitching Antenna a Ruga Ragetotem, a Camp Taurajo.",
  progress = "Hai le antenne? Se sì, dammele in fretta, perché le antenne frementi non fremono per sempre...",
  reward = "Ottimo lavoro, $N! Superando la prova al Field of Giants, fai un altro passo lungo la via $Gdel:della; $C.",
  en_title = "Trial at the Field of Giants",
  en_obj = "Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo",
}
T[1825] = {
  title = "Parla con Thun'grim",
  desc = "Thun'grim Firegaze, un famoso fabbro orco, ha sentito parlare delle tue continue imprese valorose al servizio dell'Orda. Vorrebbe forgiarti un'armatura, e ti chiede di andare subito a parlare con lui.$B$BL'accampamento di Thun'grim è a est del Crossroads, nelle Barrens.",
  obj = "Parla con Thun'grim Firegaze, nelle Barrens.",
  reward = "Sì, sei $Gvenuto:venuta;. Bene, perché abbiamo molto di cui discutere, io e te.",
  en_title = "Speak with Thun'grim",
  en_obj = "Speak with Thun'grim Firegaze in the Barrens.",
}
T[1838] = {
  title = "L'armatura brutale",
  desc = "Ho sentito racconti sulla tua forza e sul tuo valore, e voglio farti un'armatura, una compagna che ti aiuti mentre crescono i racconti delle tue grandi imprese.$B$BMa forgiare questa armatura sarà un'impresa a sé, $N. Mi servirà il tuo aiuto, e quello di altri fabbri dell'Orda.$B$BEcco, prendi questa pergamena. Ho passato molte notti, lottando con i miei occhi quasi ciechi, a scriverci ciò che mi serve per l'armatura. Portami gli oggetti di questa pergamena e ti creerò il primo pezzo.",
  obj = "Porta a Thun'grim Firegaze 15 Smoky Iron Ingot, 10 Powdered Azurite, 10 Iron Bar e una Vial of Phlogiston.",
  progress = "Hai gli oggetti della mia pergamena, $N?",
  reward = "Hai portato tutto quello che ho chiesto. Ora farò la mia parte...",
  en_title = "Brutal Armor",
  en_obj = "Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.",
}
T[1839] = {
  title = "Ula'elek e i Brutal Gauntlets",
  desc = "Il fabbro troll Ula'elek ti forgerà i Brutal Gauntlets. Vive in Durotar, a Sen'jin Village, con i suoi fratelli Darkspear, e aspetta il tuo arrivo.",
  obj = "Parla con Ula'elek, in Durotar.",
  reward = "Salve, $N. Il vecchio Thun'grim mi ha avvisato del tuo arrivo, ma anche se non avesse detto niente, la tua presenza qui non mi avrebbe sorpreso.$B$BGli spiriti seguono i tuoi progressi, giovane $C, e mi dicono che molti nemici sono caduti davanti a te.",
  en_title = "Ula'elek and the Brutal Gauntlets",
  en_obj = "Speak with Ula'elek in Durotar.",
}
T[1840] = {
  title = "Orm Stonehoof e il Brutal Helm",
  desc = "Orm Stonehoof è molto rispettato per la sua abilità. Sarà lui a farti il Brutal Helm.$B$BCercalo a Thunder Bluff, vicino alla pozza accanto al grande totem centrale della città.",
  obj = "Parla con Orm Stonehoof, a Thunder Bluff.",
  reward = "Salve, $C. Sono Orm, e Thun'grim mi dice che vuoi farti fare un elmo?",
  en_title = "Orm Stonehoof and the Brutal Helm",
  en_obj = "Speak with Orm Stonehoof in Thunder Bluff.",
}
T[1841] = {
  title = "Velora Nitely e i Brutal Legguards",
  desc = "Si dice che, prima di morire, Velora Nitely fosse una delle migliori armaiole di Lordaeron. A quanto pare la morte non ha diminuito il suo talento. Parla con Velora: sarà lei a farti i Brutal Legguards.$B$BVelora esercita il suo mestiere nell'Undercity di Lordaeron, nel Trade Quarter.",
  obj = "Parla con Velora Nitely, nell'Undercity.",
  reward = "Sei qui per un'armatura per le gambe? Magnifico!$B$BEhm... sono io che faccio l'armatura per te, o sei tu che la fai per me?$B$BEra una battuta. Faceva ridere? Non riesco a capirlo... Ho perso il senso dell'umorismo insieme all'olfatto. Più o meno quando ho smesso di respirare.",
  en_title = "Velora Nitely and the Brutal Legguards",
  en_obj = "Speak with Velora Nitely in the Undercity.",
}
T[1842] = {
  title = "Zoccoli di satiro",
  desc = "Posso farti un paio di Brutal Gauntlets, e racchiuderanno una grande magia. Ma prima devi raccogliere questa magia e portarmela.$B$BI satiri vivono nella parte nord-orientale di Ashenvale per via del potere della foresta. Si nutrono della sua purezza, succhiandola e corrompendola. Puoi capire quali satiri hanno assorbito più magia di Ashenvale dai loro zoccoli gonfi e non fessi.$B$BQuesti zoccoli racchiudono un grande potere. Mi serviranno per forgiare i tuoi guanti.",
  obj = "Porta 7 Uncloven Satyr Hoof a Ula'elek, a Sen'jin Village, in Durotar.",
  progress = "Hai gli zoccoli, $N? La magia che contengono è forte.",
  reward = "Ah, li hai! Ora, proprio come i satiri succhiavano la forza di Ashenvale, io succhierò il potere racchiuso in questi zoccoli e lo imbriglierò nel mio lavoro...",
  en_title = "Satyr Hooves",
  en_obj = "Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar.",
}
T[1843] = {
  title = "Brutal Gauntlets",
  reward = "Grazie, $N. Questi guanti sono il mio lavoro migliore. Prendili. Indossandoli, porti onore a me e ai miei antenati.",
  en_title = "Brutal Gauntlets",
}
T[1844] = {
  title = "Il corno della chimera",
  desc = "Ti farò l'elmo, ma devi dimostrarmi di esserne $Gdegno:degna;.$B$BNelle regioni nord-occidentali delle Stonetalon Mountains si trova la Charred Vale. Un tempo era un luogo verdeggiante, ma ora è profanata e coperta di cenere, e le creature che vi sono rimaste sono impazzite per il dolore e la disperazione.$B$BÈ lì che ti mando, $N.$B$BDevi andare nella Charred Vale e trovare una Chimaera Matriarch. Uccidila, liberala dalla sua sofferenza. Portami il suo Galvanized Horn come prova, e ti farò l'elmo.",
  obj = "Porta un Galvanized Horn a Orm Stonehoof, a Thunder Bluff.",
  progress = "Hai il corno? La matriarca è libera dal dolore?",
  reward = "Hai portato a termine il tuo compito, $N, e mi hai mostrato il tuo valore e la tua determinazione. L'elmo sarà tuo...",
  en_title = "Chimaeric Horn",
  en_obj = "Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff.",
}
T[1845] = {
  title = "Brutal Helm",
  reward = "Ti consegno questo elmo.$B$BGrandi imprese ti hanno portato da me, $N, e, se la Madre Terra vorrà... imprese ancora più grandi ti attendono.",
  en_title = "Brutal Helm",
}
T[1846] = {
  title = "Gli stinchi dei Dragonmaw",
  desc = "Per fare i Brutal Legguards mi serve un paio di stinchi robusti. Gli orchi Dragonmaw delle Wetlands hanno stinchi belli spessi. Mi servono i loro.$B$BMa devono essere robusti. Assicurati di metterli alla prova mentre li raccogli. Se riesci a spezzarli a mani nude, non saranno abbastanza robusti per lavorarci.",
  obj = "Porta 8 Sturdy Dragonmaw Shinbone a Velora Nitely, nell'Undercity.",
  progress = "Aspetto quegli stinchi, $N. Faranno da bella struttura per le tue gambiere.",
  reward = "Ben fatto! Sembrano tutti robusti. Credo che andranno benissimo. Come l'hanno presa quegli orchi, quando gli hai portato via gli stinchi, $N? Si sono lamentati molto?$B$BEra un'altra battuta. Non ridi.$B$BNon sono molto divertente di questi tempi, vero...",
  en_title = "Dragonmaw Shinbones",
  en_obj = "Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity.",
}
T[1847] = {
  title = "Brutal Legguards",
  reward = "Ecco le tue gambiere, $N. Fammi sapere come ti stanno o se servono modifiche. Il mio scopo è accontentare! Almeno, una volta lo era.$B$BDi questi tempi non m'importa molto del mio mestiere. Ma è sempre meglio che essere una serva senza mente del Flagello!$B$BCredo.",
  en_title = "Brutal Legguards",
}
T[1848] = {
  title = "Brutal Hauberk",
  reward = "Sono sicuro che hai sopportato molte fatiche e versato molto sangue per il mio compito, $N. Ecco il frutto del tuo lavoro.$B$BPortalo bene, e che un giorno tu possa tornare qui a raccontarmi come ti ha servito.",
  en_title = "Brutal Hauberk",
}
T[1858] = {
  title = "La Shattered Hand",
  desc = "Lascio a te il compito di aprire Tazan's Satchel e di tornare da me con il suo contenuto. Il meccanismo della serratura è complesso, quindi probabilmente la cosa più facile sarebbe procurarti la chiave.$B$BVisto che non l'hai trovata sul corpo di Tazan, posso solo supporre che l'abbia lasciata in custodia a qualcun altro... Ah, sì, è così. Aveva un assistente di nome Gamon. È un ubriacone: con ogni probabilità lo troverai alla taverna. Forse potresti alleggerirlo della chiave senza dare nell'occhio.",
  obj = "Ruba la chiave di Tazan, poi usala per aprire la sua borsa (Tazan's Satchel) e consegnane il contenuto a Therzok, nella Cleft of Shadow, a Orgrimmar.",
  progress = "Non è irritante avere l'oggetto del desiderio a portata di mano, e nessun modo per arrivarci?",
  reward = "Mmm, questo sì che è interessante. Con questo hai più che dimostrato il tuo valore, $N. Sono davvero colpito. Considerati il membro più recente della Shattered Hand. E prendi questo: penso che in futuro ti sarà di grande aiuto.",
  en_title = "The Shattered Hand",
  en_obj = "Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar.",
}
T[1859] = {
  title = "Therzok",
  desc = "Abbassa la voce, $N. Sì, so come ti chiami. Mi hanno detto di tenere d'occhio $Gun orco:un'orchessa; che corrisponde alla tua descrizione.$B$BDa quello che abbiamo sentito su di te, sai cavartela in combattimento, e ogni tanto non disdegni un po' di sotterfugi.$B$BHo ragione?$B$BComunque, dovresti andare a trovare Therzok a Orgrimmar. Ha un'offerta da farti.",
  obj = "Parla con Therzok nella Cleft of Shadow, a Orgrimmar.",
  reward = "Molto bene, sono contento che Kaplak ti abbia rintracciato.$B$BAbbiamo alcune cose di cui parlare, non ultimo il tuo futuro con la Hand.",
  en_title = "Therzok",
  en_obj = "Speak with Therzok in the Cleft of Shadow in Orgrimmar.",
}
T[1860] = {
  title = "Parla con Jennea",
  desc = "Noi maghi abbiamo un compito da portare a termine. Un compito vitale per la sicurezza di Stormwind e dell'Elwynn Forest.$B$BI dettagli li ha Jennea Cannon. Studia nel Wizard's Sanctum, nel Mage District di Stormwind. Dovresti raggiungerla al più presto.",
  obj = "Parla con Jennea Cannon, a Stormwind.",
  reward = "Ti hanno mandato ad aiutarmi nel mio compito, $N? Bene. Fa piacere vedere giovani maghi così desiderosi di aiutare la nostra causa...$B$BQuale causa, chiedi? A tempo debito, giovane. Lo saprai... a tempo debito.",
  en_title = "Speak with Jennea",
  en_obj = "Speak with Jennea Cannon in Stormwind.",
}
T[1861] = {
  title = "Mirror Lake",
  desc = "Questo mondo è stato vittima di immense lotte mistiche, che hanno strappato le correnti magiche a canali un tempo stabili. Facciamo fatica a capire quali effetti abbiano causato questi cambiamenti, e alcuni di noi temono il peggio!$B$BMa te ne parlerò meglio più avanti. Per ora ci serve che tu raccolga informazioni.$B$BEcco, prendi questa fiaschetta. Va' ai piedi della cascata del Mirror Lake, a sud-ovest delle porte di Stormwind, e preleva un campione dell'acqua. Riportamelo, così potrò analizzarlo per vedere se contiene tracce di corruzione magica.",
  obj = "Porta un campione del Mirror Lake a Jennea Cannon, a Stormwind.",
  progress = "Hai il campione, $N? Il flusso della magia a Stormwind e a Elwynn è stato alterato, e devo sapere se sta filtrando nell'acqua.",
  reward = "Grazie, $N. Analizzerò quest'acqua per scoprire se ha proprietà magiche. Speriamo che non ne abbia, altrimenti potremmo scoprire che chi beve dal Mirror Lake troppo a lungo ne subisce gli effetti negativi.$B$BEcco, $N. Prendi questo globo o questo bastone come segno di riconoscimento per il tuo servizio. Che possa esserti utile.",
  en_title = "Mirror Lake",
  en_obj = "Bring a Mirror Lake sample to Jennea Cannon in Stormwind.",
}
T[1879] = {
  title = "Parla con Bink",
  desc = "$N! Bink, la mia collega gnoma di Ironforge, manda a dire che ha un compito da sbrigare e che non lo affiderà a nessuno se non a un mago! Sei tu $Gquel mago:quella maga;, $N?$B$BSe è così, va' a parlare con Bink. Passa le sue giornate nell'Hall of Mysteries, nel Mystic Ward di Ironforge.",
  obj = "Parla con Bink, a Ironforge.",
  reward = "Oh, vedo che hai del potenziale, eccome se ce l'hai! Ma per essere un buon mago non basta il potenziale. E se non sei $Gun buon mago:una buona maga;, allora sei $Gun pessimo mago:una pessima maga;. E i pessimi maghi fanno parte del problema, eccome se ne fanno parte!$B$BOps, sto correndo troppo. Cominciamo dall'inizio!",
  en_title = "Speak with Bink",
  en_obj = "Speak with Bink in Ironforge.",
}
T[1880] = {
  title = "Mage-tastic Gizmonitor",
  desc = "Noi maghi non ci limitiamo ad agitare le dita e a fare delle belle scintille! Noi controlliamo la magia, il tessuto fondamentale del nostro mondo! E per farlo servono grande attenzione e determinazione. E conoscenza... tantissima conoscenza!$B$BUno dei miei congegni, il Mage-tastic Gizmonitor, raccoglie e conserva quella conoscenza in quantità enormi! Ma è andato perduto! Quando siamo fuggiti da Gnomeregan, la nostra casa, l'ho lasciato in una cassa, dentro una delle nostre capanne fuori città, e adesso il posto brulica di Leper Gnome!$B$BTi prego, $N, recupera il mio gizmonitor!",
  obj = "Porta a Bink il suo Mage-tastic Gizmonitor.",
  progress = "Hai trovato il gizmonitor? Devo riaverlo prima che la sua riserva di energia si esaurisca!",
  reward = "Oh, che splendida giornata! Quando ho costruito il gizmonitor non mi rendevo conto di quanto ne sarei diventata dipendente. Adesso posso ricominciare i miei studi!$B$BGrazie, $N! Ed ecco — questi sono stati i miei primi strumenti da maga. Sono un po' graffiati, ma sono ben collaudati. Scegli quello che preferisci — sono sicura che l'uno o l'altro ti tornerà utile.",
  en_title = "Mage-tastic Gizmonitor",
  en_obj = "Bring Bink her Mage-tastic Gizmonitor.",
}
T[1881] = {
  title = "Parla con Anastasia",
  desc = "$N, Anastasia Hartwell ha un compito per qualcuno con il tuo talento. Va' a parlarle nel Magic Quarter dell'Undercity e preparati al tuo primo incarico per i maghi dei Reietti.",
  obj = "Parla con Anastasia Hartwell.",
  reward = "Salve, $N. Hai agito con saggezza rispondendo alla mia chiamata, e ne mostrerai ancora di più se darai ascolto a quello che sto per dirti...",
  en_title = "Speak with Anastasia",
  en_obj = "Speak with Anastasia Hartwell.",
}
T[1882] = {
  title = "La Balnir Farmstead",
  desc = "Le Plaguelands a est sono un'aberrazione. Ideate dal Re dei Lich, diffondono la loro magia nel suolo, corrompendo e uccidendo tutto ciò che vive. Per quanto le forze distruttive della piaga abbiano un certo fascino, noi maghi dei Reietti riteniamo che sia ingovernabile e che vada tenuta a freno.$B$BMa prima dobbiamo misurare fin dove si è estesa dentro Tirisfal. Va' alla Balnir Farmstead, nella parte orientale di Tirisfal. Nel giardino ci sono dei fiori — bocche di leone. Raccoglile e torna qui.",
  obj = "Porta Balnir Snapdragons ad Anastasia Hartwell, nel Mage Quarter dell'Undercity.",
  progress = "Hai le bocche di leone? Quella varietà di fiore è molto sensibile alle energie magiche, e studiando quelle cresciute così vicino alle Plaguelands possiamo capire se la piaga è entrata nelle Tirisfal Glades.",
  reward = "Ah, questo è un bell'esemplare. Lo farò studiare ai nostri speziali, per stabilire fin dove arriva la corruzione delle Plaguelands.$B$BBen fatto, $N. Per i tuoi servigi ti offro una scelta: un globo o un bastone. Qualunque cosa sceglierai, ti sarà molto utile.",
  en_title = "The Balnir Farmstead",
  en_obj = "Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity.",
}
T[1883] = {
  title = "Parla con Un'thuwa",
  desc = "Un'thuwa, il mago della tribù di Sen'jin Village, avverte una perturbazione nelle correnti magiche di Durotar e chiede aiuto. Parla con Un'thuwa e fa' il possibile per aiutarlo.$B$BFallo, e col tempo ti saranno svelati altri segreti.",
  obj = "Parla con Un'thuwa.",
  reward = "Salute, $N. Sia lode a te, perché la mia richiesta d'aiuto ha avuto risposta. Speriamo che tu sia all'altezza del compito...",
  en_title = "Speak with Un'thuwa",
  en_obj = "Speak with Un'thuwa.",
}
T[1884] = {
  title = "I Ju-Ju Heap",
  desc = "Lo stregone Zalazane delle Echo Isles ha sconvolto il normale flusso della magia in Durotar. Ci riesce grazie a dei feticci corrotti, i Ju-Ju Heap, che ha piazzato fra le sue capanne sull'isola principale delle Echo Isles.$B$BQuesti cumuli corrompono la nostra fauna e danno potere agli stregoni e alle creature infernali in agguato negli angoli oscuri di queste terre.$B$BDevi distruggere i Ju-Ju Heap, $N, prima che il flusso della magia cambi per sempre.",
  obj = "Distruggi 4 Ju-Ju Heap, poi torna da Un'thuwa, a Sen'jin Village.",
  progress = "Devi sbrigarti, $N. Distruggi i Ju-Ju Heap!",
  reward = "Sento che i Ju-Ju Heap di Zalazane sono stati distrutti, e con il tempo e un po' di fortuna il flusso della magia in Durotar tornerà normale.$B$BHai compiuto una grande impresa per la tua gente, $N. E hai dimostrato il tuo valore a noi maghi dell'Orda.",
  en_title = "Ju-Ju Heaps",
  en_obj = "Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village.",
}
T[1885] = {
  title = "Mennet Carkad",
  desc = "$N? Non proprio ciò che mi aspettavo, visto che Carkad in persona si è interessato a te. Ma l'apparenza inganna, giusto?$B$BIn ogni caso, dovresti andare da lui il prima possibile. Non vorresti sapere cosa è successo agli ultimi che hanno scelto di ignorare la sua convocazione.",
  obj = "Parla con Mennet Carkad nel Rogues' Quarter dell'Undercity.",
  reward = "Mm. Senza dubbio sei $Gvenuto:venuta; qui appena hai sentito parlare della mia convocazione, vero? Naturalmente. Non mi aspetterei niente di meno da chi aspira a diventare Inseguitore della Morte.",
  en_title = "Mennet Carkad",
  en_obj = "Speak with Mennet Carkad in the Rogues' Quarter of the Undercity.",
}
T[1886] = {
  title = "Gli Inseguitori della Morte",
  desc = "Se vuoi unirti agli Inseguitori della Morte, la guardia scelta di Lord Varimathras, dovrai dimostrare il tuo valore.$B$BNon ti mentirò, $N: questo compito potrebbe costarti la vita.$B$BHo alcune faccende di cui occuparmi. Mi servono gli effetti personali di Astor Hadren, che porta messaggi tra Silverpine e l'Undercity. Lascio a te la scelta del modo di procurarteli.$B$BMeglio per te sapere il meno possibile sulla natura di questa faccenda. Riesci, e ti dirò di più.",
  obj = "Procurati Astor's Letter of Introduction e riportala a Mennet Carkad, nel Rogues' Quarter.",
  progress = "Hai buone notizie da riferire?",
  reward = "Ben fatto, $N. Hai superato la prima parte di questa prova. Speriamo che Andron non abbia avuto sentore delle tue attività: così potremo convincerlo che sei proprio $Gil messaggero:la messaggera; che aspetta.",
  en_title = "The Deathstalkers",
  en_obj = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.",
}
T[1898] = {
  title = "Gli Inseguitori della Morte",
  desc = "La lettera di presentazione dovrebbe bastare a convincere Andron che sei $Gil messaggero:la messaggera; che aspettava. Ho già incontrato Andron: non ha abbastanza cervello per essere così sospettoso.$B$BLord Varimathras sospetta che Andron stia aiutando qualche altro gruppo. Vuole sapere di quale organizzazione si tratta, e gliene serve la prova.$B$BVoglio che tu parli con Andron e che ottenga questa informazione. Lo troverai nella sua bottega, vicino all'Apothecarium.",
  obj = "Parla con Andron Gant, nell'Undercity.",
  progress = "Salve. Posso fare qualcosa per te?",
  reward = "Ah, sì, ti stavo aspettando. Non ho dubbi che i nostri comuni conoscenti siano soddisfatti delle informazioni che ho fornito finora, vero?$B$BImmagino sia inutile chiederlo a te: dubito che ti carichino di queste conoscenze. Perché riporre tanta fiducia in chi porta i messaggi, eh?",
  en_title = "The Deathstalkers",
  en_obj = "Speak with Andron Gant in the Undercity.",
}
T[1899] = {
  title = "Gli Inseguitori della Morte",
  desc = "Il registro con le informazioni che cercano i tuoi datori di lavoro è sullo scaffale dietro di me. Consegnalo con i miei saluti, e di' loro che preferirei che mandassero te, se ritengono che valga la pena continuare il nostro accordo.",
  obj = "Porta Astor's Ledger a Mennet Carkad, nel Rogues' Quarter dell'Undercity.",
  progress = "Ce l'hai fatta, $N?",
  reward = "Beh, sono certamente più informazioni di quante mi aspettassi di ottenere da Andron. Dammi un momento per esaminarle, prima di affidarti il prossimo compito.",
  en_title = "The Deathstalkers",
  en_obj = "Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.",
}
T[1918] = {
  title = "L'elemento corrotto",
  desc = "L'elementale ucciso ha lasciato un globo d'acqua che brilla intensamente. Il contenuto del globo è, a dir poco, disgustoso. È lecito supporre che ciò che ha corrotto l'acqua del Mystral Lake si trovi con ogni probabilità anche nell'acqua del globo.$B$BNon è cosa risaputa chi possa interessarsi a un ritrovamento simile; forse chi ti ha mandato al lago, Mastok Wrilehiss a Splintertree Post, ha qualche idea.",
  obj = "Porta il Befouled Water Globe a Mastok Wrilehiss, a Splintertree Post, in Ashenvale.",
  progress = "Sì, cosa ti serve?",
  reward = "Trovi una brutta palla d'acqua e decidi di portarla a me? Chi sono io, il Circolo della Terra o roba del genere?$B$BA dire il vero, mi viene un'idea... forse per questa cosa ti serve davvero il Circolo della Terra. Voglio dire, se serve a sistemare per sempre la situazione al lago, ci sto.$B$BSai chi è il Circolo della Terra, $N?",
  en_title = "The Befouled Element",
  en_obj = "Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale.",
}
T[1919] = {
  title = "Presentati a Jennea",
  desc = "La tua conoscenza dell'arte cresce, giovane $N. Adesso sei $Gpronto:pronta; a cominciare le tue vere lezioni? Sei $Gpronto:pronta; a prendere il tuo posto nella guerra segreta che combattiamo?$B$BSe è così, parla con Jennea Cannon, nel Wizard's Sanctum, nel Mage District di Stormwind. Ha per te un compito che ti aprirà la prima finestra sul mondo invisibile.",
  obj = "Parla con Jennea Cannon, a Stormwind.",
  reward = "$N, ho una missione per te, qui nel Mage District. Ascoltami bene, perché non c'è tempo da perdere.",
  en_title = "Report to Jennea",
  en_obj = "Speak with Jennea Cannon in Stormwind.",
}
T[1920] = {
  title = "Indaga sul Blue Recluse",
  desc = "È stata segnalata una perturbazione alla taverna Blue Recluse, nel Mage Quarter. Strane creature invisibili ora si aggirano per la taverna, e temo che lì si sia aperta una fenditura di mana.$B$BVoglio che tu indaghi nella taverna e catturi quelle creature. Usa la Cantation of Manifestation dentro la taverna per renderle visibili, sottomettile e poi usa uno scrigno di contenimento (Containment Coffer) per catturarle. Quando ne avrai abbastanza, torna da me con gli scrigni pieni, quelli vuoti e la Cantation of Manifestation.",
  obj = "Prendi una Cantation of Manifestation e una Chest of Containment Coffers alle spalle di Jennea Cannon. Porta 3 Filled Containment Coffer a Jennea, al Wizard's Sanctum.",
  progress = "Hai catturato le creature, $N? Vanno studiate per capire il motivo del loro arrivo.",
  reward = "Ottimo lavoro! Studierò queste creature e, con impegno e un po' di fortuna, scoprirò come sono sgusciate nel nostro mondo.$B$BIl tuo valore per la società dei maghi cresce, $N.",
  en_title = "Investigate the Blue Recluse",
  en_obj = "Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon.  Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum.",
}
T[1921] = {
  title = "Raccogliere i materiali",
  desc = "Hai servito bene i tuoi compagni maghi, e ora è tempo che tu indossi la tua veste da $Gmago:maga;. Wynne Larson può confezionartela, ma devi portarle i materiali necessari.$B$BLa veste sarà di lino, che è facile da trovare, ma dovrai anche procurarti delle Charged Rift Gem, e l'unico posto noto in cui trovarle è la Silver Stream Mine di Loch Modan: la lega dei minatori nani le ha lasciate lì, in alcune casse.$B$BRaccogli il lino e le gemme e portali a Wynne Larson, ai Larson Clothiers nel Mage District.",
  obj = "Porta 10 Linen Cloth e le 6 Charged Rift Gem a Wynne Larson, a Stormwind.",
  progress = "Ciao, $N. Jennea mi aveva detto che saresti $Gvenuto:venuta;. Hai qualcosa per me?",
  reward = "Sì, questi sono ottimi pezzi di lino. Ci posso fare una bella veste. E quando ci avrò intessuto le gemme, avremo un abito degno di un mago!",
  en_title = "Gathering Materials",
  en_obj = "Bring 10 Linen Cloth and the 6 Charged Rift Gems to Wynne Larson in Stormwind.",
}
T[1938] = {
  title = "Ur's Treatise on Shadow Magic",
  desc = "Molto tempo fa, tre maghi studiavano in questa torre, finché uno di loro cadde preda delle arti oscure. Fu esortato ad abbandonare quella magia malvagia, ma non riuscì a resisterle. E così fu esiliato.$B$BIl nuovo dominio del mago caduto è la Tower of Ilgalar, a Redridge, e con sé ha portato un libro potente — Ur's Treatise on Shadow Magic.$B$BNoi maghi di Stormwind vogliamo che quel libro ci venga restituito. Entra nella Tower of Ilgalar, trova il tomo nella sua biblioteca e portamelo.",
  obj = "Porta Ur's Treatise on Shadow Magic a High Sorcerer Andromath, a Stormwind.",
  progress = "Hai il libro, $N? I suoi segreti non sono fatti per chi non ha la preparazione necessaria, e scandagliarne le profondità può portare alla rovina e alla distruzione.",
  reward = "Temevo che Morganth avesse nascosto il libro altrove, o che avesse trovato il modo di aprirlo e di leggerne il contenuto.$B$BPer fortuna non l'ha fatto, e i sigilli che abbiamo posto su Ur's Treatise on Shadow Magic reggono ancora.",
  en_title = "Ur's Treatise on Shadow Magic",
  en_obj = "Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind.",
}
T[1939] = {
  title = "High Sorcerer Andromath",
  desc = "High Sorcerer Andromath desidera parlarti, $N. Si trova in cima al Wizard's Sanctum, nel Mage District di Stormwind.$B$BFaresti bene a parlargli, perché Andromath è uno dei maghi più potenti fra quelli che non sono rinchiusi a Dalaran. Un suo consiglio è davvero un consiglio di alto livello.",
  obj = "Parla con High Sorcerer Andromath.",
  reward = "Salve, $N. Sono lieto di vederti, e spero che tu abbia il tempo di ascoltare le parole di un vecchio...",
  en_title = "High Sorcerer Andromath",
  en_obj = "Speak with High Sorcerer Andromath.",
}
T[1940] = {
  title = "Pristine Spider Silk",
  desc = "Il tuo impegno non è mai venuto meno, $N. Penso che forse sia giunto il momento che tu abbia un abito più raffinato, più adatto al tuo rango di $Gmago esperto:maga esperta;. Se raccoglierai i materiali necessari, provvederemo a farti confezionare la veste.$B$BDevi andare a Duskwood e cacciare i ragni (Carrion Recluse). Estrai la loro seta, ma andrà bene solo la seta più fine e immacolata. Quando ne avrai abbastanza, portala a Wynne Larson, qui nel Mage District, ai Larson Clothiers. Sarà lei a confezionarti la veste.",
  obj = "Porta 8 Pristine Spider Silk a Wynne Larson, a Stormwind.",
  progress = "Ah, sì. I maghi del Wizard's Sanctum mi avevano detto che saresti $Gvenuto:venuta; a parlarmi. Hai la seta che serve?",
  reward = "Begli esemplari, questi. Mi metto subito al lavoro!",
  en_title = "Pristine Spider Silk",
  en_obj = "Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind.",
}
T[1941] = {
  title = "Manaweave Robe",
  reward = "Ecco la tua veste. È una delle migliori che abbia mai fatto! Indossala con orgoglio, e quando te lo chiederanno... di' che l'hai presa ai Larson Clothiers!",
  en_title = "Manaweave Robe",
}
T[1942] = {
  title = "Astral Knot Garment",
  reward = "Il tuo abito è pronto! E quella seta che hai raccolto era così bella... non ti dispiace se l'ho fatto un filo più corto per tenermi un avanzo di seta, vero?$B$BSto solo scherzando. Ti starà benissimo, e sarà perfetto sia per l'avventura sia per le cene di gala. Goditelo!",
  en_title = "Astral Knot Garment",
}
T[1943] = {
  title = "Parla con Deino",
  desc = "La maga troll Deino ha bisogno del tuo aiuto, $N. Vive a Orgrimmar, nella Darkbriar Lodge.",
  obj = "Parla con Deino.",
  reward = "Bene, sei $Gvenuto:venuta;. Il mio compito non è facile, ma è vitale per la società dei maghi. Se mi aiuterai, sono sicura che ne varrà la pena.",
  en_title = "Speak with Deino",
  en_obj = "Speak with Deino.",
}
T[1944] = {
  title = "Le acque di Xavian",
  desc = "La leggendaria città di Xavian si trova annidata nel cuore della parte orientale di Ashenvale, e i racconti sul suo antico sapere sono ben noti fra i dotti. Si dice che le acque di Xavian abbiano immensi poteri magici.$B$BVorrei un campione di quelle acque, preso alla fonte.$B$BPrendi questa fiasca e va' a Xavian. Raccogli l'acqua ai piedi della sua cascata più alta e torna da me. E fa' attenzione mentre ti muovi in quell'antica città — ora le rovine sono in mano ai satiri, che non gradiscono che i maghi ficchino il naso nei loro affari.",
  obj = "Porta lo Xavian Water Sample a Deino, a Orgrimmar.",
  progress = "Sono lieta che tu sia $Gtornato:tornata; con la pelle intatta, $N. Hai il campione d'acqua? Non vedo l'ora di studiarne le proprietà.",
  reward = "Ah, molto bene. I satiri di Xavian non ti hanno dato troppi problemi, spero?$B$BGrazie, $N. Studierò subito questo campione d'acqua di Xavian.",
  en_title = "Waters of Xavian",
  en_obj = "Bring the Xavian Water Sample to Deino in Orgrimmar.",
}
T[1945] = {
  title = "Le Laughing Sister",
  desc = "Per i tuoi servigi ho fatto in modo che ti venga confezionata una veste nuova, purché tu riesca a raccogliere i materiali necessari...$B$BPer questa veste devi tornare in Ashenvale a prendere le ciocche di capelli delle Laughing Sister — driadi che si radunano vicino al Raynewood Retreat.$B$BQuando avrai i loro capelli, portali a Kil'hala, un sarto troll al Crossroads, nelle Barrens. Ti starà aspettando, e sarà lui a confezionarti la veste.",
  obj = "Porta 12 Laughing Sister's Hair a Kil'hala, al Crossroads.",
  progress = "Salve, $N. Deino mi ha detto che saresti $Gvenuto:venuta; e che mi avresti portato i capelli delle Laughing Sister. Ce li hai?",
  reward = "Ah, con questi capelli si tesserà una bella veste, $N. Peccato che le Laughing Sister siano dovute morire per separarsene, anche se dubito che li avrebbero mai dati di loro spontanea volontà.$B$BUn peccato, ma da poco.",
  en_title = "Laughing Sisters",
  en_obj = "Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads.",
}
T[1946] = {
  title = "Nether-lace Garment",
  reward = "Ecco il tuo nether-lace, $N. È comodo e resistente, e racchiude la magia dei capelli delle Laughing Sister.$B$BGoditelo e, se ti soddisfa, per favore fallo sapere a Deino. È una maga con cui ci tengo a restare in buoni rapporti...",
  en_title = "Nether-lace Garment",
}
T[1947] = {
  title = "Viaggio nella palude",
  desc = "Ora è il momento di guadagnarti la tua bacchetta da $Gmago:maga;. Per cominciare questa impresa, parla con Tabetha, l'eremita umana, nel Dustwallow Marsh. Troverai la sua capanna nel cuore della palude, a ovest di Theramore.$B$BParla con lei, perché il suo sapere è vasto. Troverai la casupola di Tabetha a ovest di Theramore, appena a nord delle Stonemaul Ruins.",
  obj = "Parla con Tabetha.",
  reward = "Silenzio! Sono in un momento delicato e non devo essere disturbata!$B$BUn momento...",
  en_title = "Journey to the Marsh",
  en_obj = "Speak with Tabetha.",
}
T[1948] = {
  title = "Oggetti di potere",
  desc = "Costruire la bacchetta di un mago non è facile. Servono sostanze rare, e bisogna creare un recipiente capace di contenere grandi quantità di energia magica. Devi raccogliere queste cose e portarmele.$B$BSu questa pergamena ho scritto ciò che ti serve e come procurartelo. Portami esattamente quello che c'è nell'elenco, e segui alla lettera le mie istruzioni scritte, perché se non lo farai, quando creeremo la tua bacchetta le cose potrebbero andare... male.",
  obj = "Porta 1 Jade e il Bolt Charged Bramble a Tabetha, nel Dustwallow Marsh.",
  progress = "Ciao, $N. Hai gli oggetti che mi servono?",
  reward = "Aha! Hai preso la Jade e hai preparato il rovo! Ben fatto!$B$BÈ fumo quello che ti vedo uscire dalle orecchie? Forse ti sei $Gavvicinato:avvicinata; troppo quando il fulmine ha colpito i bastoncini del totem, ma non preoccuparti. Essere colpiti da un fulmine porta fortuna!",
  en_title = "Items of Power",
  en_obj = "Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh.",
}
T[1949] = {
  title = "Segreti nascosti",
  desc = "Per fare la tua bacchetta devo leggere alcuni passi fondamentali di un certo libro. Si intitola Rituals of Power, e l'ha scritto Magus Tirth.$B$BNon ho una copia del suo libro, e nessuna delle grandi biblioteche del mondo lo possiede. Quindi devi parlare con Tirth e fartelo dare da lui.$B$BBuona fortuna. Un tempo Tirth era un grande mago e studioso, ma ora passa il tempo alle corse degli gnomi e dei goblin nelle Shimmering Flats, a bere e a scommettere.",
  obj = "Parla con Magus Tirth, nelle Shimmering Flats.",
  reward = "Cosa? Parla più forte! Queste vecchie orecchie non sono più buone come una volta.$B$BBeh, spero che tu sia qui con un boccale di birra appena spillata o con qualche soffiata sulla prossima corsa! Altrimenti faresti meglio a tirare dritto... perché ho una bacchetta di metamorfosi con sopra scritto il tuo nome!",
  en_title = "Hidden Secrets",
  en_obj = "Speak with Magus Tirth in the Shimmering Flats.",
}
T[1950] = {
  title = "A caccia di notizie",
  desc = "Posso aiutarti con il libro, ma prima devi aiutare me!$B$BIl tomo che cerchi è nel mio forziere chiuso con la magia. Per aprirlo bisogna pronunciare una frase speciale, e io non me la ricordo! Di solito è il mio assistente ad aiutarmi a ricordare queste cose, ma non si trova da nessuna parte.$B$BSe vuoi il mio libro, allora trova il mio apprendista! Chiedi in giro vicino alla pista delle corse — con un po' di fortuna, qualcuno l'avrà visto. Trascinalo qui, o almeno fatti dire da lui la mia frase magica, così possiamo aprire il forziere!",
  obj = "Trova la frase che apre il forziere di Tirth, poi torna da Tirth.",
  progress = "Cosa aspetti? Mi serve la mia frase magica!",
  reward = "Ah, ora mi ricordo...$B$BMi ero dimenticato di quella piccola maledizione che ho lanciato su Johnson. Non ricordo perché l'ho fatto, ma di sicuro se l'era meritata, quel piccolo ingrato!",
  en_title = "Get the Scoop",
  en_obj = "Find the phrase to Tirth's strongbox, then return to Tirth.",
}
T[1951] = {
  title = "Rituals of Power",
  desc = "Mm... ora che ci penso, il libro non ce l'ho! Vedi, avevo dei debiti di gioco, e per saldarli ho venduto l'ultima copia di Rituals of Power a un membro del clero...$B$BUn membro della Scarlet Brotherhood. Deve averlo portato nella loro biblioteca, allo Scarlet Monastery nelle Tirisfal Glades!$B$BSe vuoi quel libro, dovrai andare al monastero a cercarlo. E scusa per tutto il disturbo. In questi giorni non sono in me...",
  obj = "Porta il libro Rituals of Power a Tabetha, nel Dustwallow Marsh.",
  progress = "Salve, $N. Hai trovato il libro Rituals of Power?",
  reward = "È questo! È proprio quello che mi serve per preparare il rituale che creerà la tua bacchetta! Spero che trovarlo non ti abbia dato troppo disturbo...",
  en_title = "Rituals of Power",
  en_obj = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.",
}
T[1952] = {
  title = "Bacchetta da mago",
  desc = "Ora vado a fare le bacchette.",
  obj = "Parla con Tabetha dopo il suo rituale.",
  reward = "Ecco le bacchette che ho fatto. Scegli quella che preferisci!",
  en_title = "Mage's Wand",
  en_obj = "Speak with Tabetha after her ritual.",
}
T[1959] = {
  title = "Presentati ad Anastasia",
  desc = "I maghi dell'Undercity hanno notato una perturbazione magica all'interno della città, e hanno mandato a chiamare i maghi dell'Orda perché indaghino.$B$BAnastasia Hartwell può dirti di più. Va' a parlarle nel Magic Quarter dell'Undercity.",
  obj = "Parla con Anastasia Hartwell.",
  reward = "È vero. Nella nostra città è stata rilevata una perturbazione magica. Non siamo ancora certi della sua origine, né se sia maligna o benigna. Prima dobbiamo raccogliere altre informazioni...$B$BE questo, $N, ci porta al tuo compito.",
  en_title = "Report to Anastasia",
  en_obj = "Speak with Anastasia Hartwell.",
}
T[1960] = {
  title = "Indaga sulla bottega dell'alchimista",
  desc = "La bottega d'alchimia di Algernon, nell'Apothecarium, è il centro di una strana perturbazione. Creature invisibili, fatte solo di magia, si aggirano per la bottega — ci dev'essere un motivo, e dobbiamo scoprirlo!$B$BIndaga sulla perturbazione e cattura quelle creature. Prendi una cassa di scrigni e una pergamena, qui dietro di me. Usa la pergamena nella bottega per rendere visibili le creature, sottomettile con i tuoi incantesimi, poi getta a terra uno scrigno per catturarle. Torna con gli scrigni pieni, quelli vuoti e la Cantation of Manifestation.",
  obj = "Prendi una Cantation of Manifestation e una Chest of Containment Coffers alle spalle di Anastasia Hartwell. Porta 3 Filled Containment Coffer, la Chest of Containment Coffers e la Cantation of Manifestation ad Anastasia, nell'Undercity.",
  progress = "Hai indagato sulla perturbazione, $N? Hai catturato le creature?",
  reward = "Molto bene, $N. Le creature chiuse in questi scrigni di contenimento saranno studiate dalle nostre menti migliori, e il motivo della loro presenza nell'Undercity verrà chiarito.$B$BSe la loro comparsa è causata da una fenditura nel flusso naturale della magia, dobbiamo stabilire se la fenditura è stata casuale. Se non lo è stata, e si tratta invece di un attacco da parte di qualche forza magica, allora dobbiamo prepararci a perturbazioni future, e più gravi.",
  en_title = "Investigate the Alchemist Shop",
  en_obj = "Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell.  Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity.",
}
T[1961] = {
  title = "Raccogliere i materiali",
  desc = "È tempo che tu indossi la tua prima veste da $Gmago:maga;, $N. È un segno del tuo rango e una prova del tuo valore.$B$BPer ottenerla, devi prendere le gemme di mana ai maghi di Dalaran che stanno a Silverpine. Le loro convinzioni sono simili alle nostre, quindi ucciderli è un po' sgradevole; ma se non hanno la forza di resisterci, non meritano di vivere.$B$BPorta le gemme e una scorta di lino a Josef Gregorian, nella sartoria del Magic Quarter.",
  obj = "Porta 10 Linen Cloth e 6 Dalaran Mana Gem a Josef Gregorian.",
  progress = "Anastasia mi ha detto che saresti $Gvenuto:venuta; da me, e sono pronto a confezionare la tua veste. Hai le gemme e il lino?",
  reward = "È un materiale molto buono, e anche se non ho il talento per giudicare la qualità di queste gemme di mana, sapremo presto se hanno il potere necessario per creare le Spellfire Robes...",
  en_title = "Gathering Materials",
  en_obj = "Bring 10 Linen Cloth and 6 Dalaran Mana Gems to Josef Gregorian.",
}
T[1962] = {
  title = "Spellfire Robes",
  reward = "Ecco la tua veste, $N. Indossala degnamente.",
  en_title = "Spellfire Robes",
}
T[1963] = {
  title = "La Shattered Hand",
  desc = "Il Capoguerra è troppo sottile nei suoi metodi. È cauto nello scatenare la potenza dell'Orda. Un tempo eravamo più forti, tutti potenti conquistatori. Dobbiamo riconquistare quell'orgoglio, e la Shattered Hand lo farà.$B$BCostruiamo la nostra forza nell'ombra e colpiamo chi resta scoperto, abbattendo i nostri nemici in segreto. C'è un compito che devi portare a termine per me, per dimostrare il tuo valore.$B$BIl troll Tazan commercia con i pirati vicino a Ratchet. Ha delle informazioni che devo avere. Uccidilo e portami la sua borsa.",
  obj = "Uccidi Tazan e porta la sua borsa (Tazan's Satchel) a Therzok, nella Cleft of Shadow, a Orgrimmar.",
  progress = "Solo uno sciocco crede che una carica con l'ascia in pugno sia più pericolosa di un coltello nel buio.",
  reward = "Mm, anche se mi fa piacere sapere che Tazan non è più tra noi, una borsa chiusa a chiave non ci serve a niente. Ci servono le informazioni che contiene.$B$BQuesta dovrebbe essere una seconda prova degna per chi desidera unirsi alla Shattered Hand.",
  en_title = "The Shattered Hand",
  en_obj = "Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar.",
}
T[1978] = {
  title = "Gli Inseguitori della Morte",
  desc = "Il Syndicate? Non l'avrei mai sospettato. Sembra che i nobili di Alterac siano caduti molto in basso negli anni dopo il loro tradimento.$B$BLord Varimathras sarà lieto di saperlo, e visto che sei $Gstato:stata; così determinante per questa scoperta, sarebbe giusto che fossi tu a consegnarglielo.$B$BAh, e come potevo dimenticarlo?$B$B$GBenvenuto:Benvenuta; tra gli Inseguitori della Morte.",
  obj = "Consegna Andron's Ledger a Varimathras nella Hall of the Dark Lady, nell'Undercity.",
  progress = "Sì?",
  reward = "Mmm, questo è interessante. Gli Inseguitori della Morte hanno svolto il loro compito in modo egregio, scovando tutto questo.$B$BA quanto mi risulta, anche tu meriti un encomio per il tuo operato. Spero che per te diventi un'abitudine, $N: ai miei Inseguitori della Morte fa sempre comodo $Gun uomo:una donna; in gamba.",
  en_title = "The Deathstalkers",
  en_obj = "Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity.",
}
T[1998] = {
  title = "Fenwick Thatros",
  desc = "Lord Varimathras mi ha appena mandato un messaggio su una minaccia per i Reietti che va eliminata immediatamente. Si chiama Fenwick Thatros, e Lord Varimathras crede che sia uno dei capi dei non morti che hanno messo radici nella Silverpine Forest.$B$BIl tuo nome mi è venuto subito in mente, $N. Ho abbastanza fiducia nelle tue capacità da essere certo che porterai a termine questa missione alla perfezione.$B$BGli ultimi rapporti degli Inseguitori della Morte a Silverpine indicano che Thatros si trova vicino al molo in rovina sul Lordamere.",
  obj = "Uccidi Fenwick Thatros e porta la sua testa a Mennet Carkad, nel Rogues' Quarter dell'Undercity.",
  progress = "Ho riposto in te la massima fiducia perché tu renda questo servizio a Lord Varimathras.",
  reward = "Hai fatto bene, $N. Mi rendo conto che hai reso molti servigi agli Inseguitori della Morte, dimostrando il tuo valore, e che forse è tempo di approfondire il tuo addestramento nelle arti dell'ombra.",
  en_title = "Fenwick Thatros",
  en_obj = "Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity.",
}
T[1999] = {
  title = "Gli attrezzi del mestiere",
  desc = "I maghi del Kirin Tor ad Ambermill hanno messo al sicuro documenti importanti sulla situazione attuale di Dalaran. Lo sappiamo dalla confessione di uno dei nostri prigionieri. Lord Varimathras ha affidato agli Inseguitori della Morte il compito di recuperarli.$B$BQuesto compito spetta a te, $N. Però ti serviranno un po' di attrezzatura e la capacità di scassinare le serrature. Parla con Estelle Gendry, la nostra fornitrice, e chiedile un set di attrezzi prima di partire.",
  obj = "Trova il Dalaran Status Report e riportalo a Mennet Carkad, nel Rogues' Quarter dell'Undercity.",
  progress = "Hai trovato i documenti, $N?",
  reward = "Molto bene, $N! Hai imparato bene la raffinata arte dello scasso, e più in fretta di quanto potessi mai aspettarmi.$B$BVedo che ho fatto bene a fidarmi di te. Credimi, $Gragazzo:ragazza;, prevedo che farai molta strada in questo mestiere.",
  en_title = "Tools of the Trade",
  en_obj = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.",
}
T[2038] = {
  title = "Le provviste perdute di Bingles",
  desc = "Come se schiantarmi nel Loch non fosse già abbastanza, i trogg dell'isola qui vicino mi hanno attaccato e rubato gli attrezzi e gli speciali esplosivi Blastenheimer Blastencapper. Senza girocottero e senza esplosivi, il movimento non ha alcuna speranza!$B$BRecupera i miei attrezzi e trova i miei esplosivi Blastencapper, $N. Per Gnomeregan!",
  obj = "Trova e riporta le provviste di Bingles:$B$BBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer e Bingles' Blastencapper.",
  progress = "$N! Dove sono le mie cose?!",
  reward = "Hai reso un grande servizio al movimento, $N. I trogg e gli gnomi lebbrosi che infestano Gnomeregan sentiranno presto tutto il peso di un attacco aereo gnomico!",
  en_title = "Bingles' Missing Supplies",
  en_obj = "Find and return Bingles' supplies:$B$BBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.",
}
T[2039] = {
  title = "Trova Bingles",
  desc = "Abbiamo perso i contatti con Bingles! Era stato mandato in ricognizione su Gnomeregan e non si fa sentire da più di una settimana. Sono certo che sia andato a farsi saltare in aria.$B$BÈ stato visto per l'ultima volta mentre volava sul Loch. Forse puoi indagare, $N.",
  obj = "Trova Bingles Blastenheimer a Loch Modan.",
  reward = "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...$B$BMa lascia perdere, ho bisogno del tuo aiuto! Anzi! Il movimento ha bisogno del tuo aiuto!",
  en_title = "Find Bingles",
  en_obj = "Find Bingles Blastenheimer in Loch Modan.",
}
T[2040] = {
  title = "Assalto sotterraneo",
  desc = "Gnomeregan è caduta sotto il controllo di quegli infami trogg! La situazione è grave, ma forse puoi aiutarci, $N.$B$BNelle profondità delle Deadmines c'è una sminuzzatrice goblin ancora funzionante. Trova quella sminuzzatrice e riporta indietro l'alimentatore intatto. Con l'alimentatore della sminuzzatrice possiamo dare ai nostri escavatori girotrivellomatici la potenza che serve per sfondare le barriere di roccia sotterranee di Gnomeregan, aprendo la strada a un assalto gnomesco!",
  obj = "Recupera lo Gnoam Sprecklesprocket dalle Deadmines e riportalo a Shoni the Shilent, a Stormwind.",
  progress = "Hai trovato lo Gnoam Sprecklesprocket, $N?",
  reward = "Ben fatto, $N. Grazie a te, Gnomeregan è un passo più vicina al giorno della sua liberazione!",
  en_title = "Underground Assault",
  en_obj = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.",
}
T[2041] = {
  title = "Parla con Shoni",
  desc = "Forse... forse puoi aiutarci nella battaglia per Gnomeregan.$B$BA Stormwind troverai il comandante della nostra squadra d'assalto sotterranea, Shoni the Shilent. Shoni ha bisogno di aiuto con i suoi gyrodrillmatic excavationators.$B$BProbabilmente la troverai tra i nani di Stormwind.$B$BBuona fortuna, $N. ",
  obj = "Parla con Shoni the Shilent a Stormwind.",
  reward = "Porti notizie dal comando centrale?",
  en_title = "Speak with Shoni",
  en_obj = "Speak with Shoni the Shilent in Stormwind.",
}
T[2078] = {
  title = "La vendetta di Gyromast",
  desc = "Marinaio d'acqua dolce, devi trovare il mio primo ufficiale.$B$BPrendi questa chiave, infilagliela nella testa e riportalo qui a servire il Capitano.$B$BQuei murloc e il loro capo non saranno per niente contenti quando il mio primo ufficiale metterà le mani su di loro!",
  obj = "Trova il Primo Ufficiale di Gelkak, il Threshwackonator 4100, e riportalo da Gelkak.",
  progress = "Dov'è il mio primo ufficiale, $N? Catene e squali ti aspettano se non ti sbrighi!",
  reward = "Arrr... Ti stai dimostrando più di un vigliacco lupo di mare, marinaio d'acqua dolce.$B$BIl Capitano potrebbe promuoverti a sguattero di poppa se continui così...",
  en_title = "Gyromast's Revenge",
  en_obj = "Find Gelkak's First Mate, the Threshwackonator 4100, and lead it back to Gelkak.",
}
T[2098] = {
  title = "Il recupero di Gyromast",
  desc = "La vita del pirata non è facile, marinaio d'acqua dolce. Non è solo saccheggi e rum! Ahimè, la mia nave è affondata poco al largo per colpa di quei fastidiosi Threshadon.$B$BQuello che mi serve è il mio primo ufficiale di nuovo in funzione!$B$BQuando sono approdato a riva, la chiave del mio primo ufficiale si è spezzata sugli scogli ed è stata trafugata dalle bestie di Darkshore. Con la coda dell'occhio ho visto dei Ragin' Crawler, dei Ferocious Foreststrider e dei murloc frugare tra i relitti...",
  obj = "Trova e riporta i tre pezzi della Gelkak's Key a Gelkak Gyromast.",
  progress = "Hai trovato la mia chiave rotta, marinaio d'acqua dolce?",
  reward = "Ohé, vecchio lupo di mare! Ce l'hai fatta! Presto il mio primo ufficiale sarà di nuovo in funzione e quelle bestiacce non sapranno cosa le ha colpite!$B$BHmm, hai per caso visto il mio primo ufficiale?",
  en_title = "Gyromast's Retrieval",
  en_obj = "Find and return the three pieces of Gelkak's Key to Gelkak Gyromast.",
}
T[2118] = {
  title = "Terre appestate",
  desc = "Una malattia si diffonde per Darkshore, stringendo menti e corpi di tutto ciò che tocca.$B$BI Thistle Bear sono i più colpiti da questa piaga. Quelle un tempo nobili creature sono ora strumenti di distruzione: rabbiose e frenetiche. Forse ho una cura per questo male.$B$BPrendi questa trappola, portala nella foresta e posala a terra. Ogni Rabid Thistle Bear che attraverserà la luce diventerà docile per breve tempo. Quando l'orso sarà docile, ti seguirà. Riportalo qui, $N.",
  obj = "Cattura un Rabid Thistle Bear vivo e portalo a Tharnariun.$B$BSe non riesci a catturare un Rabid Thistle Bear e perdi la trappola, torna da Tharnariun Treetender e chiedine un'altra.",
  progress = "Mi hai portato l'animale malato, $N?$B$BSe la trappola non è scattata, non preoccuparti: la Speranza di Tharnariun è eterna. Se ti serve un'altra trappola, abbandona il tuo compito e torna da me.",
  reward = "Il nostro lavoro è appena cominciato, $N. Sei pronto$Go:a; per il prossimo compito?",
  en_title = "Plagued Lands",
  en_obj = "Capture a living Rabid Thistle Bear and bring it back to Tharnariun.$B$BShould you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap.",
}
T[2138] = {
  title = "La purificazione degli infetti",
  desc = "Come temevo, la cura non funziona.$B$BMi addolora profondamente ordinare la morte di una qualsiasi bestia della natura, ma gli orsi malati e contaminati devono essere abbattuti.$B$BTorna nella foresta e distruggi 20 Rabid Thistle Bear, $N. Di certo non fermerà la piaga, ma rallenterà per un breve periodo il danno che questi animali infliggono alla nostra foresta e ai suoi abitanti.",
  obj = "Purifica la foresta da 20 Rabid Thistle Bear e torna da Tharnariun Treetender a Darkshore.",
  progress = "Il tuo compito è concluso?",
  reward = "Hai reso un grande servizio ad Auberdine, $N, ma il tuo compito non è ancora finito.",
  en_title = "Cleansing of the Infected",
  en_obj = "Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore.",
}
T[2139] = {
  title = "La speranza di Tharnariun",
  desc = "La sopravvivenza del nostro popolo e delle nostre terre ha un prezzo sfortunato, $N.$B$BHai versato il sangue dei servitori della natura; hai abbattuto molti animali malati. La gente di Auberdine è in debito con te, perché il dolore della foresta si è alleviato, anche se solo per un istante.$B$BHo un ultimo compito per te, ma sii avvisat$Go:a;: dovrai uccidere ancora. È mia speranza che questa sia l'ultima volta che ti chiamo in causa, $N.$B$BIn una caverna a nordest, vicino a Bashal'Aran, dimora la Den Mother. Uccidila.",
  obj = "Trova e uccidi la Den Mother.",
  progress = "Con la Den Mother infetta morta, il numero di Rabid Thistle Bear che entrano nelle nostre terre diminuirà. Non perdere tempo, $N.",
  reward = "Hai combattuto per Auberdine con coraggio e onore, $N. Nelle nostre terre dilaniate dalla guerra, morte e disperazione sono comuni. Molti non sapranno affrontare la sfida della vita nella nostra nuova casa, scegliendo invece di nascondersi nelle proprie dimore o di fuggire verso le terre più fortificate dell'Alleanza.$B$BGrazie, $N. Forse un giorno non lontano combatteremo fianco a fianco come compagni contro un altro nemico.",
  en_title = "Tharnariun's Hope",
  en_obj = "Find and kill the Den Mother.",
}
T[2158] = {
  title = "Riposo e relax",
  desc = "Ogni avventuriero dovrebbe riposare quando la stanchezza si fa sentire, e non c'è posto migliore per riposo e relax della Lion's Pride Inn!$B$BIl mio migliore amico, Innkeeper Farley, gestisce la Lion's Pride. Se gli dici che ti mando io, potrebbe offrirti tariffe speciali scontate su cibo e bevande.$B$BPer trovare la Lion's Pride Inn, viaggia verso sud lungo la strada da qui: non puoi sbagliare!",
  obj = "Parla con Innkeeper Farley alla Lion's Pride Inn.",
  reward = "Riposo e relax per chi è stanco e infreddolito: questo è il nostro motto! Prego, siediti accanto al fuoco e riposa le tue stanche ossa.$B$BVuoi assaggiare un po' del nostro ottimo cibo e delle nostre bevande?",
  en_title = "Rest and Relaxation",
  en_obj = "Speak with Innkeeper Farley at the Lion's Pride Inn.",
}
T[2159] = {
  title = "Consegna a Dolanaar",
  desc = "Salute, giovane $c. Puoi offrirmi il tuo aiuto? Ho un pacco di erbe che devo consegnare alla città di Dolanaar. Ma ho ancora faccende da sbrigare con i druidi di Shadowglen e non posso partire.$B$BPuoi consegnare tu questo pacco al posto mio? Deve andare a Innkeeper Keldamyr, alla locanda di Dolanaar. Si trova lungo la strada, a sud.",
  obj = "Porta la Dolanaar Delivery a Innkeeper Keldamyr.",
  progress = "Come posso esserti utile, giovane? Sei qui per riposare alla locanda? Ti serve una pietra del ritorno?",
  reward = "Ah sì, la consegna di erbe da Shadowglen. Peccato che Porthannius non abbia potuto portarla di persona, perché abbiamo molto da discutere, lui e io. Ma sono comunque lieto di avere le erbe, e sono lieto che tu sia venut$Go:a;.$B$BFinché sei qui, ti prego, riposati. Gli eroi devono mantenere alte le forze e lo spirito, e trovare riposo e conforto ogni volta che possono. Perché trascurare la pace del corpo e della mente è una via sicura verso il fallimento.$B$BDunque... riposa.",
  en_title = "Dolanaar Delivery",
  en_obj = "Bring the Dolanaar Delivery to Innkeeper Keldamyr.",
}
T[2160] = {
  title = "Provviste per Tannok",
  desc = "Ehi! Sembri $Gun avventuriero robusto:un'avventuriera robusta;. Se hai intenzione di affrontare il passo, potresti portare un pacco alla locanda di Kharanos?$B$BAvevi intenzione di fermarti alla locanda, vero? Se superi il passo, vorrai di sicuro riprendere fiato lì.$B$BComunque, porta questo a Tannok Frosthammer, l'aiutante del locandiere. Io non posso attraversare il passo, e ci vorranno giorni prima che passi una scorta di Mountaineer!",
  obj = "Consegna la Crate of Inn Supplies a Tannok Frosthammer a Kharanos.",
  progress = "Salve! Entra, siediti accanto al fuoco e scaldati con un boccale di birra.",
  reward = "Ah, finalmente le provviste di Hands! Cominciavo a preoccuparmi: da quando i trogg hanno invaso il passo abbiamo avuto pochissime notizie da Anvilmar.$B$BGrazie per avermele portate, $N. E ti prego, mettiti comod$Go:a;. Devi essere stanc$Go:a; dopo il viaggio.",
  en_title = "Supplies to Tannok",
  en_obj = "Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.",
}
T[2161] = {
  title = "Il fardello di un Peon",
  desc = "Scusa? Puoi aiutarmi?$B$BHo un carico di cibo qui. Ho percorso la strada affrontando scorpidi, ragni e di peggio! Ho portato il cibo alla Valley of Trials perché pensavo ne avessero bisogno e mi piace dare una mano. Ma non ne hanno bisogno! Ora devo riportarlo a Razor Hill e ho paura di tutte le bestie lungo il cammino...$B$BPuoi portarlo tu al posto mio? Io sono solo un peon, ma tu sei un eroe. Non temi nulla!$B$BPortalo a Innkeeper Grosk alla locanda di Razor Hill. Grazie!",
  obj = "Porta Ukor's Burden a Innkeeper Grosk a Razor Hill.",
  progress = "Benvenut$Go:a; a Razor Hill!",
  reward = "Ah, questo è il cibo che Ukor ha portato alla Valley of Trials. Non ne avevano bisogno? Beh, immagino che amino far morire di fame voi eroi in addestramento. Tempra lo spirito, dicono!$B$BGrazie per aver riportato il cibo. Lo rimetterò sugli scaffali... ma prima, lascia che ti offra un ristoro!$B$BE non dimenticare di riposare qui alla locanda. Sarai anche un coraggioso $C pront$Go:a; ad affrontare il mondo, ma se le tue energie sono esaurite non farai un gran bene né a te stess$Go:a; né alla Horde.",
  en_title = "A Peon's Burden",
  en_obj = "Bring Ukor's Burden to Innkeeper Grosk in Razor Hill.",
}
T[2178] = {
  title = "Vita facile con gli strider",
  desc = "Senti questo profumo delizioso? È la mia ricetta segreta, $N — Strider Stew appena fatto. Delizioso!$B$BTi piacerebbe imparare la ricetta?$B$BPrima di insegnartela, dovrai dimostrare di saper tenere testa a quelle bestie.$B$BOra, non mi aspetto che tu vada ad addomesticarne uno e me lo riporti in groppa, ma se riesci a ucciderne qualcuno e a riportarmi un po' della loro carne succulenta, forse riuscirai a convincermi a mostrarti i segreti dello Strider Stew.",
  obj = "Riporta 5 Strider Meat ad Alanndarian Nightsong, ad Auberdine.",
  progress = "La pentola è vuota e ho fame! Perché ci metti così tanto?",
  reward = "Fantastico! Assaggialo e dimmi cosa ne pensi, $N!",
  en_title = "Easy Strider Living",
  en_obj = "Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.",
}
T[2198] = {
  title = "La Shattered Necklace",
  desc = "Hai trovato una collana annerita, anche se la patina nasconde una lavorazione elaborata e magica. La collana è rotta: al castone sembrano mancare tre gemme. Sul retro della collana c'è l'impronta sbiadita del sigillo cittadino di Ironforge. Sotto il sigillo ci sono tre minuscole lettere incise: \"TdK\".$B$BSe c'è qualcosa da ricavare da questa collana, dovrai scoprirne le origini. Forse il sigillo e le iniziali sono un punto di partenza...",
  obj = "Cerca chi ha creato la Shattered Necklace, per scoprire quanto potrebbe valere.",
  progress = "Hai sbagliato gnomo, $Gamico:amica;! Io non c'ero! Non puoi dimostrare niente!$B$BAspetta un attimo... chi sei? Ma che... dove l'hai trovata questa collana?",
  reward = "Sì... sono io il gioielliere che ha fatto questa collana. E non sono nemmeno uno che dà informazioni gratis. Le informazioni non sono mai gratis, $Gamico:amica;. Se devo aiutarti, prima devi aiutare ME.",
  en_title = "The Shattered Necklace",
  en_obj = "Search for the original creator of the shattered necklace to learn of its potential value.",
}
T[2199] = {
  title = "Informazioni a pagamento",
  desc = "Sono un gioielliere di grande fama, qui a Ironforge! Be', di fama passata, almeno... Sono caduto in disgrazia per colpa degli imbrogli di un concorrente! In questo mestiere una cattiva reputazione vuol dire la rovina. Il risultato è che mi ritrovo senza un soldo, con un buon nome che al momento è infangato.$B$BVoglio che tu mi procuri cinque Silver Bar per completare un ordine che ho ricevuto, il primo da quella che sembra un'eternità.$B$BPortami quelle cinque Silver Bar, e risponderò alle tue domande sulla collana.",
  obj = "Porta cinque Silver Bar a Talvash del Kissel, a Ironforge.",
  progress = "Hai le cinque Silver Bar che ti ho chiesto? Ti racconterò la mia triste storia di sventure riguardo alla collana che hai adesso... ma solo dopo aver avuto quelle barre! Ti prego, dai una mano a uno gnomo, vuoi?",
  reward = "Per me sei a posto; non m'importa cosa dicono tutti gli altri... Scherzo, scherzo! Davvero, grazie, $Gamico mio:amica mia;.$B$BAllora, la collana che hai è una delle mie creazioni migliori, ma le mancano tre gemme che la aiutano a legare a sé il potere magico. L'ho fatta tempo fa per un paladino. Si era dato da solo la missione di ripulire dalla \"corruzione malvagia\" un sito di scavo nelle Badlands chiamato Uldaman.$B$BBe'... quel paladino è morto a Uldaman, e quello è stato solo l'inizio delle mie disgrazie.",
  en_title = "Lore for a Price",
  en_obj = "Bring five silver bars to Talvash del Kissel in Ironforge.",
}
T[2200] = {
  title = "Ritorno a Uldaman",
  desc = "Un mio concorrente ha messo in giro la voce che la mia collana ha maledetto il paladino. Inutile dire che nessuno vuole comprare oggetti maledetti da un gioielliere.$B$B$N, ti propongo un accordo: trova le gemme e io rimetterò insieme la collana, a patto che tu vada in giro a dire che io NON faccio oggetti maledetti!$B$BProva a cercare indizi a Uldaman; magari vedi se il corpo del paladino è laggiù, visto che è l'ultimo che sappiamo averla avuta! Quando trovi le gemme, usa questa: ti permetterà di contattarmi qui a Ironforge.",
  obj = "Cerca a Uldaman indizi su dove si trova ora la collana di Talvash. Il paladino ucciso di cui ha parlato è l'ultimo che l'ha avuta.",
  reward = "Resti di un paladino: leggendo il diario scopri che, dopo molti sforzi, il paladino aveva individuato dove si trovano tutte e tre le gemme mancanti:$B$BI nani Shadowforge hanno nascosto il rubino nella loro zona barricata, mentre combattevano contro i trogg per il controllo di Uldaman.$B$BI trogg hanno nascosto il topazio in un'urna vicino ad alcuni abitanti insoliti di Uldaman: dei nani dell'Alleanza!$B$BInfine, l'anziano dei trogg in persona ha preso lo zaffiro per sé.",
  en_title = "Back to Uldaman",
  en_obj = "Search for clues as to the current disposition of Talvash's necklace within Uldaman.  The slain paladin he mentioned was the person who had it last.",
}
T[2201] = {
  title = "Trova le gemme",
  desc = "Il diario del paladino ha fornito forse gli unici indizi che Uldaman potrà dare su dove si trovano le gemme della collana. Se quello che ha scritto il paladino è ancora esatto, bisognerà occuparsi dei nani Shadowforge e dei trogg che si contendono il controllo del sito di scavo.$B$BForte di queste informazioni, la ricerca delle gemme comincia sul serio. Quando avrai recuperato tutte le gemme, dovrai avvisare Talvash, a Ironforge, con la Phial of Scrying, come da sue istruzioni.",
  obj = "Trova il rubino, lo zaffiro e il topazio sparsi per Uldaman. Una volta recuperati, contatta Talvash del Kissel a distanza usando la Phial of Scrying che ti ha dato.$B$BDal diario sai che...$B* Il rubino è stato nascosto in una zona barricata degli Shadowforge.$B* Il topazio è stato nascosto in un'urna in una delle zone dei trogg, vicino ad alcuni nani dell'Alleanza.$B$B* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.",
  progress = "Dalle acque della Scrying Bowl prende forma l'immagine di Talvash.$B$B\"Wow, sei ancora $Gvivo:viva;! Sei $Griuscito:riuscita; a trovare le gemme? Sei davvero $Gil salvatore:la salvatrice; della mia reputazione che speravo? Ti prego, dimmi che non hai sprecato una carica della fiala solo per chiacchierare: quelle cose NON costano poco, e sono già in gravi difficoltà economiche.",
  reward = "Sì, sono proprio le tre gemme. Ottimo lavoro! Purtroppo il tuo lavoro non è ancora del tutto finito.$B$BNo, non sto cercando di fregarti, $C $Gsciocco:sciocca;. Si tratta di fare gioielli magici: gioielli della qualità di Talvash del Kissel! Serve una fonte di energia potente per dargli un po' di grinta. Be', quella collana di grinta da dare non ne ha più.",
  en_title = "Find the Gems",
  en_obj = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B$B* The sapphire has been claimed by Grimlok, the trogg leader.",
}
T[2202] = {
  title = "Reagenti da Uldaman",
  desc = "Ho sentito parlare di una pianta scoperta da poco, i Magenta Fungus Cap. Crescono a grappoli, nel profondo del sito di scavo di Uldaman; forse si trovano anche altrove, ma per ora è l'unico posto che conosco. Voglio studiarne il possibile uso in alchimia, ed è qui che entri in gioco tu.$B$BTrova i Magenta Cap Clusters e portami una dozzina di cappelli. Sta' $Gattento:attenta;: se li urti, i grappoli potrebbero sputare spore velenose.$B$BFallo per me, e ti preparerò una partita di uno dei miei famosi elisir ristoratori!",
  obj = "Porta 12 Magenta Fungus Cap a Jarkal Mossmeld, a Kargath.",
  progress = "Ti sei $Gprocurato:procurata; i Magenta Fungus Cap che mi servono per il mio lavoro alchemico? Niente cappelli, niente ricompensa!",
  reward = "Ben fatto, $N: hai dimostrato ancora una volta quanto vali! I cappelli saranno uno studio interessante, puoi scommetterci.$B$BE ora, come promesso, gusta un assaggio di uno dei miei intrugli ristoratori più potenti, dalla mia scorta personale...$B$BSe sei $Gun alchimista esperto:un'alchimista esperta;, forse potremmo fare altri affari. In ogni caso, ti ringrazio per il tuo aiuto!",
  en_title = "Uldaman Reagent Run",
  en_obj = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.",
}
T[2203] = {
  title = "Reagenti dalle Badlands II",
  desc = "Mi sei $Gstato:stata; di grande aiuto, $C. Vorrei ricompensarti con la ricetta stessa dell'intruglio che ti ho dato prima... ma devo chiederti un compito piuttosto pericoloso. Ascolta la mia richiesta.$B$BIn questa cassetta ci sono tre recipienti taumaturgici vuoti; sono intrisi di un'aura di sintonia che assorbirà il sangue di uno Scorched Guardian. Usarne uno sulla bestia la farà infuriare parecchio, quindi sei $Gavvisato:avvisata;. Quando li avrai riempiti tutti e tre, portameli.$B$BFallo, e la ricetta sarà tua.",
  obj = "Usa gli Empty Thaumaturgy Vessel sugli Scorched Guardian delle Badlands. Quando li avrai riempiti, portali a Jarkal Mossmeld, a Kargath.",
  progress = "Hai usato i recipienti per procurarmi il sangue di Scorched Guardian che mi serve? Sì, lo so che è un compito pericoloso... ma la ricetta del mio intruglio ristoratore aspetta solo il tuo successo. Rischio e ricompensa, $Gamico mio:amica mia;... rischio e ricompensa...",
  reward = "Da alchimista ad alchimista, ti rendo omaggio. Ecco, prendi questa ricetta e imparala a memoria. Che ti porti il successo e le ricompense che ha portato a me in tutti questi anni.",
  en_title = "Badlands Reagent Run II",
  en_obj = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Jarkal Mossmeld in Kargath.",
}
T[2204] = {
  title = "Restaurare la collana",
  desc = "Dovrai trovare un po' di \"grinta\" per la collana, e Uldaman è probabilmente il posto migliore dove cercarla, in effetti. Immagino che là dentro ci siano un sacco di costrutti in giro, eh? Be', fai fuori il costrutto più grosso e più cattivo di quel posto e prendi la sua fonte di energia! Sono quasi sicuro di poterla fondere con la collana.$B$BSenza quella fonte di energia sarà impossibile riparare la collana. Torna da me qui a Ironforge quando l'avrai, e ti sistemeremo tutto!",
  obj = "Procurati una fonte di energia dal costrutto più potente che riesci a trovare a Uldaman, e consegnala a Talvash del Kissel, a Ironforge.",
  progress = "Non ti sei nemmeno $Gfermato:fermata; a darti una ripulita dopo aver lasciato Uldaman, eh? Sei $Gvenuto:venuta; dritto qui, alla faccia degli odori di sotterraneo che ti porti dietro. Be', speriamo che questa visita sia solo maleodorante, e non pure inutile.$B$BHai la fonte di energia per la collana?",
  reward = "Accidenti: sono proprio contento di vedere te e questa fonte di energia tutti interi. Mi ci vorrà un momento per fondere magicamente la fonte di energia con la collana, ora che le gemme sono tornate al loro posto. Una volta finito, però, la collana sarà tua!$B$BSei $Gemozionato:emozionata;, vero? $GTutto:Tutta; un fremito per l'attesa? Ora, dove ho messo quel focus per incantesimi...",
  en_title = "Restoring the Necklace",
  en_obj = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.",
}
T[2205] = {
  title = "Cerca lo SI: 7",
  desc = "Il distintivo? Oh, non è niente, $Gpivello:pivella; — niente alla tua portata, in ogni caso. A giudicare dal tuo aspetto, direi che Mathias probabilmente ti scambierà per $Gil ragazzo:la ragazza; che consegna il formaggio invece che per $Gun vero ladro:una vera ladra;. Comunque sia, mi è stato affidato un lavoro e ho promesso di portarlo a termine.$B$BA proposito di consegne, porta questo pacco a Mathias: forse ti darà un incarico o due.$B$BDatti da fare.",
  obj = "Consegna il pacco di Keryn Sylvius a Master Mathias Shaw, agli Stormwind Barracks.",
  progress = "Posso aiutarti, $C?",
  reward = "Mi hai trovato — e a guardarti, direi che la corsa e la ricerca che ne è seguita potrebbero averti messo a dura prova, sia nella mente sia nel corpo.$B$BVuoi che Renzik ti mostri la strada per una locanda, o sei $Gpronto:pronta; per un po' di lavoro?",
  en_title = "Seek out SI: 7",
  en_obj = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.",
}
T[2206] = {
  title = "Arraffa e scappa",
  desc = "I nostri agenti sul campo riferiscono un'intensa attività dei Defias a sud di Goldshire. Dai rapporti risulta che i Defias hanno preso il controllo di Jerod's Landing e ora lo usano per contrabbandare grandi quantità di merce illegale da Redridge a Westfall.$B$BHo bisogno che tu ti infiltri nella casa del molo e mi porti quello Shipping Schedule, $N. Probabilmente lo troverai sepolto in fondo alle tasche del Dockmaster.$B$B...e, $N, se dovessi essere $Gscoperto:scoperta;, lo SI:7 negherà di sapere alcunché della tua esistenza.",
  obj = "Trova il Defias Dockmaster e recupera lo Shipping Schedule per Master Mathias Shaw.",
  progress = "La tua vita mortale si consuma a ogni istante che sprechi a gironzolare per la caserma, $C.",
  reward = "Sono sbalordito... Sbalordito che Keryn abbia finalmente trovato una recluta che forse ha la stoffa per diventare $Gun vero ladro:una vera ladra;. Prendi questa lama, $N. Verrà il giorno in cui sarai $Gchiamato:chiamata; di nuovo a servire lo SI:7. Affina le tue abilità, tieni gli occhi aperti e quella lama affilata.$B$BNon ci vedrai arrivare, ma lo sentirai, quando arriveremo...",
  en_title = "Snatch and Grab",
  en_obj = "Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.$B",
}
T[2218] = {
  title = "La via della salvezza",
  desc = "Un'altra anima perduta in cerca di una guida, eh? Immagino che tu voglia trovare uno scopo — il tuo scopo. L'ho visto mille volte: $Gun altro eroe:un'altra eroina; in cerca di lavoro.$B$BBeh, oggi è il tuo giorno fortunato, $Gamico:amica;. Hogral ha la cura per il tuo male.$B$BEcco cosa devi fare: prendi questa strada fino a Ironforge e raggiungi la Forlorn Cavern. Una volta lì, trova la gilda dei ladri e parla con Hulfdan Blackbeard. Sarà lui a metterti sulla via della salvezza.",
  obj = "Parla con Hulfdan Blackbeard, a Ironforge.",
  reward = "Così credi d'essere $Gun vero furfante:una vera furfante;? $GDestinato:Destinata; a essere $Guno:una; dei pochi eletti di Blackbeard — $Gun ufficiale:un'ufficiale; dell'Hidden Circle?$B$BSolo un buono a nulla da strapazzo penserebbe così bene di sé.$B$BÈ proprio quello che cerchiamo! $GBenvenuto:Benvenuta; a bordo, $N!",
  en_title = "Road to Salvation",
  en_obj = "Speak with Hulfdan Blackbeard in Ironforge.",
}
T[2238] = {
  title = "Semplici sotterfugi",
  desc = "Vedi, il re sta raschiando la cava fino all'osso per estrarre minerali e gemme. Più ricchezze di quante un nano dovrebbe vederne in dieci vite.$B$BL'Hidden Circle ha dei valori, $N. Diamo valore a ciò che ha valore. Capisci?$B$BOra, noi pensiamo che il re dovrebbe spartire un po' di quel bottino, ma non vogliamo che il vecchio 'Barbapuzza' sappia che sta spartendo... se capisci cosa intendo.$B$BC'è bisogno che tu vada a parlare con Onin MacHammar, dalle parti di Gnomeregan, e che ci riporti un rapporto. Quel nano furbo si è nascosto tra i lebbrosi. Fa' attenzione.",
  obj = "Trova Onin MacHammar, vicino a Gnomeregan.",
  reward = "Shhhh! Abbassa la voce, testa vuota. Ci sentiranno.",
  en_title = "Simple Subterfugin'",
  en_obj = "Find Onin MacHammar by Gnomeregan.",
}
T[2239] = {
  title = "Onin's Report",
  desc = "La cava? Sì, vedo passare qui davanti quei mostruosi carri a vapore corazzati quasi ogni giorno.$B$BI miei contatti a est mi dicono che il carro parte da Ironforge, carica merce alla Gol'Bolar Quarry, si ferma a Kharanos per fare rifornimento e poi, per qualche maledetto motivo, fa il giro lungo passando da Gnomeregan, prima di arrivare a Ironforge a scaricare la merce.$B$BÈ tutto nel rapporto, $R. Riportalo a Hulfdan, così può pianificare la prossima mossa.",
  obj = "Riporta Onin's Report a Hulfdan, a Ironforge.",
  progress = "Ti è piaciuto il fetore degli gnomi lebbrosi? Te lo chiedo solo perché hai un sorriso folle stampato in faccia.$B$BChe notizie mi porti da Onin?",
  reward = "Il giro lungo? Per la mia barba!$B$BHai fatto un buon lavoro, $N. Prendi questo pugnale e sparisci. Il Circle ti chiamerà di nuovo quando il passo tre sarà pronto per partire.$B$BCos'è il passo tre? Viene subito dopo il passo due: io che ti pianto lo stivale nel sedere.$B$BTi interessa?",
  en_title = "Onin's Report",
  en_obj = "Take Onin's Report back to Hulfdan in Ironforge.",
}
T[2240] = {
  title = "La camera nascosta",
  desc = "E ora veniamo al compito da svolgere.$B$BC'è una camera segreta, la Chamber of Khaz'mul, che va esplorata. Il problema è che la camera si trova dietro un'enorme porta chiusa! Per fortuna io so come aprirla.$B$BHo descritto tutto nel mio diario, qui sul tavolo. Io e la mia banda per ora siamo bloccati qui... quindi tocca a te, $N, trovare la Chamber of Khaz'mul per noi!$B$BLeggi il mio diario, esplora la camera, poi fai rapporto a Prospector Stormpike, alla Lega degli Esploratori, a Ironforge.",
  obj = "Leggi Baelog's Journal, esplora la camera nascosta, poi fai rapporto a Prospector Stormpike.",
  progress = "Hai qualcosa da riferire?",
  reward = "Hai visto la Chamber of Khaz'mul? Straordinario! Baelog era sicuro che esistesse, ma devo ammettere che avevo i miei dubbi.$B$BGrazie, $N. Con un po' di fortuna la tua scoperta spingerà i nostri capi a rinnovare gli sforzi per riprendere Uldaman. E se mai tornerà sotto il controllo di Ironforge, i segreti della Chamber of Khaz'mul saranno nostri!",
  en_title = "The Hidden Chamber",
  en_obj = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.",
}
T[2241] = {
  title = "La mela cade",
  desc = "Dicono che sono 'innamorato perso', qualunque cosa voglia dire.$B$BCerto, passo ogni momento da sveglio a pensare a Syurna. Certo, la mia casa è piena di quadri e disegni di Syurna. Certo, spesso passo giorni senza mangiare, senza dormire e senza bere, mentre mi struggo per l'amore che avremmo potuto avere. È così sbagliato?$B$BE ora lei non vuole vedermi! ME! Ho provato a mandarle dei messaggi, ma lei non parla nemmeno con chi non sia un ladro.$B$BPotresti consegnarle questo fiore? Non dimenticare di dirle che è da parte di Jannok.",
  obj = "Porta Jannok's Rose a Syurna, a Darnassus.",
  progress = "Oh, ma che meraviglia. Hai portato dei fiori per il tuo funerale.",
  reward = "Se avessi conservato ogni fiore che quello zuccone di Jannok mi ha mandato, avrei avuto di che aprire un negozio. Comunque sia, sembra che $Gl'ultimo messaggero:l'ultima messaggera; di Jannok possa rivelarsi utile.$B$BTi interessa un po' di lavoro, $C?",
  en_title = "The Apple Falls",
  en_obj = "Take Jannok's Rose to Syurna in Darnassus.",
}
T[2242] = {
  title = "Il destino chiama",
  desc = "Crediamo che esista un essere che potrebbe aiutarci a capire cosa sta succedendo alle foreste di Teldrassil. Purtroppo, convincere la creatura a collaborare si è rivelato un disastro.$B$BSi nasconde su un ramo ai margini dell'Oracle Glade. Tutti quelli che finora si sono avvicinati al satiro, con la forza o con la diplomazia, hanno fatto una brutta fine. Forse la risposta è la furtività, $N.$B$BScopri cosa porta Sethir the Ancient nelle sue borse e fammi rapporto.",
  obj = "Trova Sethir the Ancient e porta a Syurna tutti gli indizi che riesci a scoprire.",
  progress = "Hai qualcosa da riferire su Sethir the Ancient, $N?",
  reward = "Sono notizie cupe, $N. Sembrerebbe che il morbo che ha colpito le foreste e i fiumi di Darkshore abbia cominciato a portare la corruzione nella nostra casa.$B$BCi hai servito bene, ma qui non c'è più nulla che tu possa fare. Prendi questa lama come ricompensa per i tuoi servigi a Teldrassil.",
  en_title = "Destiny Calls",
  en_obj = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna.$B",
}
T[2258] = {
  title = "Reagenti dalle Badlands",
  desc = "$N, mi servirebbe il tuo aiuto, se te la senti. Sono un alchimista di una certa fama, e cerco il tuo aiuto per procurarmi alcuni reagenti che si trovano nelle Badlands.$B$BPer rifornire le mie scorte mi servono queste cose: cinque Buzzard Gizzard, dieci Crag Coyote Fang e cinque Rock Elemental Shard. Ovviamente puoi prenderli dalle bestiacce stesse; se non sei $Gil tipo:la tipa; che combatte, trovati degli amici che lo siano.$B$BProcurami queste cose e ci guadagnerai qualche moneta. Allora, che vuoi fare?",
  obj = "Porta 5 Buzzard Gizzard, 10 Crag Coyote Fang e 5 Rock Elemental Shard a Jarkal Mossmeld, a Kargath, nelle Badlands.",
  progress = "Hai già preso le cose che mi servono? Non sarai $Gpagato:pagata; se non mi porti quei reagenti.",
  reward = "Ah, ben fatto! Queste mi basteranno almeno per un po'. Ecco la tua paga, come promesso.$B$BSe ti interessa, ci sono altri reagenti che mi farebbero comodo. Questi però si trovano solo nelle profondità degli scavi di Uldaman. Non sarà facile procurarli, ma se vorrai aiutarmi ancora farò in modo che ne valga la pena.$B$BMagari qualcosa di più di qualche moneta luccicante, eh?",
  en_title = "Badlands Reagent Run",
  en_obj = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.",
}
T[2259] = {
  title = "Erion Shadewhisper",
  desc = "Non preoccuparti, $N, non ti sto mandando da Syurna. Erion richiede la tua presenza al Cenarion Enclave. Sbrigati!",
  obj = "Mettiti in contatto con Erion Shadewhisper, a Darnassus.",
  reward = "È ora di allargare i tuoi orizzonti, $R: il mondo ti aspetta.",
  en_title = "Erion Shadewhisper",
  en_obj = "Contact Erion Shadewhisper in Darnassus.$B",
}
T[2260] = {
  title = "Per volere di Erion",
  desc = "La notizia delle tue imprese si è diffusa in lungo e in largo, $N. Così lontano, anzi, che la Stormwind Intelligence ha chiesto di te per nome.$B$BIl viaggio è faticoso e non privo di pericoli, ma l'occasione di addestrarsi presso lo SI:7 non va presa alla leggera.$B$BUn mondo nuovo ti aspetta, $N. Raggiungi Old Town, a Stormwind, e parla con Renzik \"The Shiv\" al quartier generale dello SI:7.",
  obj = "Raggiungi Stormwind City e chiedi di parlare con Renzik \"The Shiv\".",
  reward = "Hai risposto alla chiamata dello SI:7, $N, e hai viaggiato da coste lontane per unirti a noi; tuttavia, hai ancora molto da imparare.",
  en_title = "Erion's Behest",
  en_obj = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\"$B",
}
T[2278] = {
  title = "I dischi di platino",
  desc = "Al centro di questa camera del tesoro ci sono quattro enormi dischi di platino, ognuno ornato di numerosi sigilli di origine sconosciuta. Toccarli ti fa formicolare la mano. Subito dopo che hai toccato i dischi, compare l'immagine di un grande guardiano di pietra.$B$B\"Saluti. Sono un custode della conoscenza. La sintesi dei Terrigeni compiuta dai Creatori è stata registrata e conservata qui, per questo mondo, nei Discs of Norgannon.\"$B$BHai scoperto una ricchezza di sapere sul mondo mai scoperta prima!",
  obj = "Parla con il guardiano di pietra e scopri quale antico sapere custodisce. Quando avrai appreso il sapere che ha da offrire, attiva i Discs of Norgannon.",
  progress = "La voce del guardiano di pietra sembra risuonare nel profondo del tuo essere:$B$B\"Prima devi soddisfare il requisito di assimilazione dei dati dei Discs of Norgannon; una volta soddisfatto questo requisito, ti sarà permesso ottenere una versione portatile dei dati archiviati. Assicurati prima di aver esplorato a fondo le informazioni di questo archivio.\"",
  reward = "Seguendo le istruzioni del guardiano di pietra, accedi di nuovo ai Discs of Norgannon, ora che hai appreso la storia dei Terrigeni, dei trogg e dei nani. Dall'interno dei dischi si sente un ronzio debole e breve. Poi il guardiano di pietra parla:$B$B\"I dischi sono stati sintetizzati. Accedi ancora una volta ai Discs of Norgannon per ricevere la tua copia personale.\"",
  en_title = "The Platinum Discs",
  en_obj = "Speak with stone watcher and learn what ancient lore it keeps.  Once you have learned what lore it has to offer, activate the Discs of Norgannon.",
}
T[2279] = {
  title = "I dischi di platino",
  desc = "Toccare di nuovo i Discs of Norgannon ti fa formicolare la mano. Questa volta, però, dall'interno dei dischi si sente uno strano rumore di ingranaggi.$B$BIl tuo zaino diventa all'improvviso più pesante di prima. Dentro scopri una versione in miniatura dei dischi!$B$BSenza dubbio, un oggetto del genere sarebbe prezioso per chiunque si interessi alla storia antica di Azeroth. La Lega degli Esploratori di Ironforge è proprio un gruppo così, conosciuto in tutta l'Alleanza; forse potrà farne buon uso.",
  obj = "Porta la versione in miniatura dei Discs of Norgannon alla Lega degli Esploratori, a Ironforge.",
  progress = "Sì, posso aiutarti in qualcosa? Ti assicuro che in questo momento sono molto occupato. Se però è una questione di grande importanza per la Lega degli Esploratori, allora sono tutt'orecchi!",
  reward = "Cos'hai lì... oh, cielo. Dove l'hai trovato?$B$BNo, davvero?$B$BHai parlato con chi, di cosa?$B$BNO, DAVVERO?!$B$B$GMio caro:Mia cara; $C, potresti aver appena fatto la scoperta archeologica dell'anno! Per gli dèi, chi voglio prendere in giro: la scoperta del secolo! Se questi dischi sono quello che penso, potrebbero essere proprio la chiave che cercavamo! Potrebbero dimostrare una volta per tutte la legittimità della creazione incantata dei nani!",
  en_title = "The Platinum Discs",
  en_obj = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.",
}
T[2280] = {
  title = "I dischi di platino",
  desc = "Toccare di nuovo i Discs of Norgannon ti fa formicolare la mano. Questa volta, però, dall'interno dei dischi si sente uno strano rumore di ingranaggi.$B$BIl tuo zaino diventa all'improvviso più pesante di prima. Dentro scopri una versione in miniatura dei dischi!$B$BSenza dubbio, un oggetto del genere sarebbe prezioso per chiunque si interessi alla storia antica di Azeroth. I saggi di Thunder Bluff sono proprio storici di questo tipo, conosciuti in tutta l'Orda; forse potranno farne buon uso.",
  obj = "Porta la versione in miniatura dei Discs of Norgannon a uno dei saggi di Thunder Bluff.",
  progress = "Sì, giovane, ti vedo entrare nella mia tenda con passo deciso... con determinazione nei tuoi propositi. Cerchi il mio consiglio su una questione di grande importanza per l'Orda? O forse desideri che ti venga svelato un mistero dell'universo?",
  reward = "Cosa sono questi, allora?$B$BNotevole, giovane! In questi dischi percepisco segreti che la terra ha custodito gelosamente per molti anni. Hai fatto molto bene a portarli qui da me.",
  en_title = "The Platinum Discs",
  en_obj = "Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff.",
}
T[2281] = {
  title = "Appuntamento a Redridge",
  desc = "Mandarti sul campo adesso sarebbe un suicidio. A Renzik non serve un altro ladro morto sulla coscienza. Ma non preoccuparti, $N: Renzik ti metterà al passo.$B$BRaggiungi le Redridge Mountains e parla con un collaboratore dello SI:7 di nome Lucius. Lo troverai a bighellonare vicino ai moli di Lakeshire, insieme agli altri buoni a nulla dall'aria losca.",
  obj = "Mettiti in viaggio verso Lakeshire, nelle Redridge Mountains, e parla con Lucius.",
  reward = "Ah, quindi hai le dita un po' grassocce, eh? Non preoccuparti, $N: ho trasformato in ladri provetti dei borsaioli ben più inetti di te.",
  en_title = "Redridge Rendezvous",
  en_obj = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius.$B",
}
T[2282] = {
  title = "Alther's Mill",
  desc = "Qui addestriamo ladri da anni! Dopotutto, non tutti i furfanti nascono con la grazia e la finezza del vecchio Lucius.$B$BQui sopra, poco fuori dalla strada, troverai Alther's Mill. Lassù ho un forziere con dentro una cosa importante. Va' a prendermela! Riportami quel gettone e riceverai il tuo Certificate of Thievery!",
  obj = "Apri Lucius's Lockbox, recupera il Token of Thievery e riportalo a Lucius, a Lakeshire.",
  progress = "Mi sono dimenticato di dirti degli orchi?$B$BHo sentito che ficcanasano lassù, vicino al mulino.",
  reward = "L'hai scassinato, eh? Bel lavoro, $N.$B$BSe muori adesso, possiamo stare tranquilli: sarà per colpa della tua stupidità e non dell'inesperienza.",
  en_title = "Alther's Mill",
  en_obj = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire.",
}
T[2283] = {
  title = "Recupero della collana",
  desc = "Abbiamo un lavoro per te, sempre che tu abbia il fegato di farlo!$B$BNel profondo delle Badlands c'è il sito di scavo di Uldaman. Ci è arrivata la storia di un paladino idiota che ci è morto di recente. Il motivo per cui ce ne importa è che aveva addosso una collana di grande valore. A quanto pare ha tre grosse gemme: un rubino, uno zaffiro e un topazio.$B$BEcco il punto: la vogliamo, e per averla paghiamo IL MASSIMO in argento. Potrebbe essere danneggiata, ma poco importa: qualunque graffio abbia, lo sistemiamo noi.",
  obj = "Cerca una collana di valore nel sito di scavo di Uldaman e riportala a Dran Droffers, a Orgrimmar. La collana potrebbe essere danneggiata.",
  progress = "Allora, ce l'hai la collana? Da noi non vedrai un soldo, se non hai quella collana!",
  reward = "Mmm, roba da recupero! Sento l'odore della collana da qui. Ora diamo un'occhiata a questa bellezza...$B$BEhi, cosa credi di fare? Questa collana non ha le gemme! Pensavi che non ce ne saremmo accorti? Perfino Malton vedrebbe che le gemme non ci sono.$B$BBe', forse non le hai rubate tu... ma senza quelle gemme questa collana non vale niente! Il tuo lavoro qui non è ancora finito, nemmeno per sogno!",
  en_title = "Necklace Recovery",
  en_obj = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar.  The necklace may be damaged.",
}
T[2284] = {
  title = "Recupero della collana, secondo tentativo",
  desc = "Com'è vero che Malton è uno stupido, quelle gemme sono ancora da qualche parte a Uldaman. Dovrai tornare laggiù a cercarle.$B$BCome ho detto prima, se le informazioni che abbiamo sono giuste, con la collana vanno un rubino, uno zaffiro e un topazio. Trovali e rimettili nella collana.$B$BQuanto a dove siano le gemme, chi lo sa? Magari avrai fortuna e troverai il cadavere del paladino. Se non l'hanno già spogliato di tutto, magari le ha ancora addosso.",
  obj = "Trova un indizio su dove si trovano le gemme, nelle profondità di Uldaman.",
  reward = "Sembra che tu abbia trovato i resti del paladino di cui ti aveva parlato Dran. Frugando tra i resti scopri quello che sembra il suo diario. Il libro è in pessime condizioni: il sangue secco ha macchiato quasi tutto il testo. Quello che riesci a leggere, però, è incomprensibile: per quanto ne sai, è scritto nella lingua degli umani.$B$BSe vuoi ricavarne qualcosa, dovrai far tradurre il libro.",
  en_title = "Necklace Recovery, Take 2",
  en_obj = "Find a clue as to the gems' whereabouts in the depths of Uldaman.",
}
T[2298] = {
  title = "Una retata reale",
  desc = "Allora, eravamo lì lì per cominciare a pianificare la fase III, quando un paio di teste di legno di Magni piombano qui dentro parlando di un qualche colpo e arrestano alcuni dell'Hidden Circle.$B$BBeh, nessuno mette i ferri al vecchio Blackbeard! La discussione si è fatta pesante e accesa, e in qualche modo è saltato fuori il tuo nome!$B$BIl mio consiglio? Prendi il primo grifone che parte da Ironforge e vai a Stormwind. Raggiungi Old Town e, una volta lì, parla con un mio vecchio amico di nome Renzik \"The Shiv\".",
  obj = "Raggiungi Stormwind e cerca Renzik \"The Shiv\".",
  reward = "Fa sempre piacere avere $Guno:una; dei ladri di Hulfdan tra le nostre file!",
  en_title = "Kingly Shakedown",
  en_obj = "Travel to Stormwind and seek out Renzik \"The Shiv.\"",
}
T[2299] = {
  title = "Da Hulfdan!",
  desc = "Dove ti eri $Gcacciato:cacciata;, $N? Hulfdan ti sta cercando dappertutto. Pensavamo che il re ti avesse messo ai ferri.$B$BVa' a Ironforge il prima possibile e parla con Hulfdan!",
  obj = "Raggiungi Ironforge e parla con Hulfdan Blackbeard.",
  reward = "Abbassa la voce, $N, le guardie potrebbero sentirti.",
  en_title = "To Hulfdan!",
  en_obj = "Travel to Ironforge and speak with Hulfdan Blackbeard.",
}
T[2300] = {
  title = "SI:7",
  desc = "Renzik ti stava cercando, $Gpivello:pivella;.$B$BIo, al posto tuo, non farei aspettare il vice di Mathias.",
  obj = "Raggiungi Stormwind e cerca Renzik \"The Shiv\".",
  reward = "Sei $Gpronto:pronta; a metterti al lavoro o ti serve un pisolino prima di cominciare?",
  en_title = "SI:7",
  en_obj = "Travel to Stormwind and seek out Renzik \"The Shiv.\"$B",
}
T[2318] = {
  title = "Tradurre il diario",
  desc = "In una specie di vicolo cieco, sai che dovrai far tradurre il libro in una lingua che capisci. Nel mondo ci sono di sicuro parecchie persone in grado di farlo; il posto più vicino dove potrebbe esserci qualcuno capace, però, è l'avamposto di Kargath, nelle Badlands. Forse è un buon punto di partenza.",
  obj = "Trova qualcuno che sappia tradurre il diario del paladino. Il posto più vicino dove potrebbe esserci qualcuno è Kargath, nelle Badlands.",
  reward = "Potente $C, so cosa fai qui nelle Badlands. So che cerchi il mio dono delle lingue. Sei sulle tracce dei pezzi di quella collana che hai trovato a Uldaman.$B$BTi sorprende? Non dovrebbe: sapere queste cose è il mio lavoro. Parliamo piuttosto di cosa farai in cambio di un diario tradotto. Fidati: sono l'unico che troverai in grado di tradurlo.$B$BMeglio ancora, lascia che ti faccia un'offerta migliore di quella di Dran Droffers, che ti permetterà comunque di portare a termine il tuo accordo con loro. Ora ti interessa, vero?",
  en_title = "Translating the Journal",
  en_obj = "Find someone who can translate the paladin's journal.  The closest location that might have someone is Kargath, in the Badlands.",
}
T[2338] = {
  title = "Tradurre il diario",
  desc = "Quelli della Droffers and Son Salvage non sono abbastanza furbi da ridare magia alla collana, ma io sì. Voglio solo studiare la collana per imparare a farne anch'io. Per farlo, mi serve la tua collana. Prestamela, e in cambio del tempo che avrò per studiarla ti tradurrò il diario. Mentre tu cerchi le gemme, dovrei avere abbastanza tempo per imparare quello che mi serve.$B$BÈ un accordo semplice, e nessun altro lo verrà a sapere. Allora, che vuoi fare?",
  obj = "Presta la collana a Jarkal. In cambio, lui ti tradurrà il diario.",
  progress = "Ci hai pensato, vero? Sei $Gun:una; $C $Gfurbo:furba; se accetti questo accordo: tu e io otterremo quello che vogliamo tutti e due, e quelli della Droffers and Son Salvage crederanno di ottenere quello che vogliono loro.",
  reward = "Un buon affare lo riconosci quando lo vedi: sapevo di poter contare su di te.$B$BCi vorrà solo un momento, il tempo di lanciare un incantesimo per tradurre in fretta la lingua degli umani in una forma che tu possa capire. Sono un troll di parola: chiedi a chiunque nell'Orda di Jarkal Mossmeld. Ora cominciamo...",
  en_title = "Translating the Journal",
  en_obj = "Let Jarkal borrow the necklace.  In exchange, he will translate the journal for you.",
}
T[2339] = {
  title = "Trova le gemme e la fonte di energia",
  desc = "Ecco il diario, tradotto perché tu possa leggerlo da te. Il succo è che i nani hanno nascosto il rubino, i trogg hanno nascosto il topazio, e un trogg di nome Grimlok ha lo zaffiro.$B$BSenti: ti servirà una fonte di energia per far funzionare di nuovo la collana. Dran Droffers non lo sa. Per trovarne una, ecco cosa farei io: scendi più in profondità che puoi a Uldaman e uccidi il costrutto più forte che c'è. Senza dubbio, qualunque cosa sia, ce l'avrà.$B$BQuando avrai raccolto tutto, torna qui!",
  obj = "Recupera a Uldaman tutte e tre le gemme e una fonte di energia per la collana, poi portale a Jarkal Mossmeld, a Kargath. Jarkal crede che una fonte di energia si possa trovare sul costrutto più forte di Uldaman.$B$BDal diario sai che...$B* Il rubino è stato nascosto in una zona barricata degli Shadowforge.$B* Il topazio è stato nascosto in un'urna in una delle zone dei trogg, vicino ad alcuni nani dell'Alleanza.$B* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.",
  progress = "Ti aspetta un altro viaggio nelle profondità di Uldaman, se non hai le gemme e una fonte di energia in grado di incanalare di nuovo il potere magico nella collana.$B$BLe gemme te le riprenderai per consegnarle a quegli scagnozzi di Orgrimmar; io terrò la fonte di energia, visto che è proprio quella che farà funzionare la collana...",
  reward = "Ben fatto davvero, $C. Ora i frutti del nostro piccolo dirottamento ripagheranno lautamente. Con la collana in sé ho finito, e sono sicuro di poter ripetere il procedimento di costruzione ogni volta.$B$BMa prima userò un incantesimo preparato apposta per analizzare in fretta quelle gemme, prima che tu riporti loro e la collana a Orgrimmar. Ci vorrà solo un attimo.",
  en_title = "Find the Gems and Power Source",
  en_obj = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B* The sapphire has been claimed by Grimlok, the trogg leader.",
}
T[2340] = {
  title = "Consegna le gemme",
  desc = "Va bene qualunque castone e qualunque gemma, purché siano dello stesso materiale. Questa fonte di energia, invece, è quella che riporterà la magia nella collana... spero.$B$BTi fornirò volentieri le gemme che servono per la tua versione della collana, a patto che la fonte di energia funzioni davvero.$B$BVa' a Orgrimmar e mantieni la tua parte del patto con la Droffers and Son Salvage. Solo, tieni la bocca chiusa sul nostro accordo, e quando torni potrei avere una splendida sorpresa per te.",
  obj = "Consegna il Necklace and Gem Salvage a Dran Droffers, a Orgrimmar.",
  progress = "Ma guarda chi si vede! Te la sei presa comoda, vedo. Speriamo che non sia una perdita di tempo! Non verrai $Gpagato:pagata; se non hai tutto quello che ti ho chiesto. E fidati: controlleremo tutto due e tre volte!",
  reward = "Sì, c'è tutto. Senti, ti spiace se ci teniamo anche la borsa? No? Grazie, molto gentile! Ah!$B$BQuesta collana sarà il nostro colpo migliore di sempre! Ma non prendertela troppo: sono sicuro che comunque la collana non ti sarebbe andata. Ah, di nuovo!$B$BPatti chiari: ecco il tuo compenso per il recupero. Per ora i nostri affari sono chiusi; ripassa più tardi per vedere se abbiamo altro lavoro. Fino ad allora, sparisci!",
  en_title = "Deliver the Gems",
  en_obj = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.",
}
T[2341] = {
  title = "Recupero della collana, terzo tentativo",
  desc = "Mentre Dran e Malton Droffers cominciano a litigare sul loro nuovo bottino, metà dell'accordo è conclusa. Ora ci vuole un viaggio nelle Badlands per chiudere la faccenda: Jarkal Mossmeld, a Kargath, potrebbe avere una ricompensa speciale che ti aspetta.",
  obj = "Va' da Jarkal Mossmeld, a Kargath, per vedere se ci è riuscito.",
  reward = "La fonte di energia che mi hai dato ha superato ogni mia aspettativa. Sono riuscito a fare una collana per te e una per me, e me ne avanza abbastanza per farne almeno altre tre. Frutteranno un bel compenso, e la Droffers and Son Salvage non ne saprà niente.$B$BEcco a te, $Gamico mio:amica mia;. Ti ringrazio per un lavoro splendido... e ti do qualcosa di davvero speciale per il disturbo.",
  en_title = "Necklace Recovery, Take 3",
  en_obj = "Visit Jarkal Mossmeld in Kargath to see if he was successful.",
}
T[2342] = {
  title = "Tesori recuperati",
  desc = "Spazzare i recinti dei pipistrelli con questa scopa non si addice a un Garrett! Con questo lavoro maledetto ho messo da parte qualche moneta, e sono disposto a spenderla per te pur di migliorare la mia posizione.$B$BL'arma preferita della famiglia Garrett è chiusa nel nostro forziere nella South Common Hall di Uldaman, da quando noi Garrett lavoravamo lì come scavatori. Senza di essa resterò bloccato qui per sempre, letteralmente, a spazzare dietro a questi pipistrelli infernali.$B$BRecupera il tesoro della mia famiglia e portamelo! Aiutami a riprendermi ciò che mi spetta per nascita!",
  obj = "Prendi il tesoro di famiglia di Patrick Garrett dal forziere di famiglia nella South Common Hall di Uldaman, e portalo a Patrick, nell'Undercity.",
  progress = "Non si finisce mai di spazzare... questi pipistrelli non si stancano mai di prendersi gioco di me e della mia scopa. Dimmi che hai recuperato il tesoro della mia famiglia! Ti ho offerto il mio argento: non basta?!",
  reward = "Finalmente, una scopa degna di un Garrett. Vali fino all'ultima moneta d'argento che ho speso per te, parola mia!$B$BMi sentite, pipistrelli schifosi? Ora impugno l'arma preferita della famiglia Garrett! Tremate, pipistrelli, tremate!!",
  en_title = "Reclaimed Treasures",
  en_obj = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.",
}
T[2358] = {
  title = "Horns of Nez'ra",
  desc = "Molti anni fa, gli Horns of Nez'ra furono rubati dal Ravenholdt Manor. Li ho cercati attraverso continenti e oceani, solo per scoprire che queste bestie insignificanti li avevano sempre avuti in mano loro.$B$BUccidi ogni orco Blackrock che incontri finché non avrai recuperato gli Horns of Nez'ra. Se recuperi le corna, mi troverai a Lakeshire.$B$BFallo per me, e il tuo nome sarà noto a Ravenholdt, $N.",
  obj = "Riporta gli Horns of Nez'ra ad Arantir's Shadow, a Lakeshire.",
  progress = "Hai le corna del principe demone?",
  reward = "Negare il manufatto a Ravenholdt significherebbe negare la propria stessa esistenza. Ben fatto, $Gladro:ladra;. Un giorno potresti camminare tra gli assassini di Ravenholdt.$B$BDa giovane ladro, durante le mie avventure a Darkshore, ho scoperto un tè che ridà energia in combattimento. Mi è stato utile per tutti questi anni, e ora ti lascio assaggiare il Thistle Tea. Bevilo quando sei $Gstanco:stanca;, $N, e torna a combattere con vigore!",
  en_title = "Horns of Nez'ra",
  en_obj = "Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire.",
}
T[2359] = {
  title = "Klaven's Tower",
  desc = "Tengo d'occhio questa torre da settimane, $N. Di recente è arrivato un grosso carico da Duskwood, e insieme sono arrivate quelle guardie.$B$BChe cosa sono? Ne so quanto te. Una cosa però posso dirtela: non sono umani.$B$BComunque, nel carico c'era un forziere, ed è quello che immagino stiano sorvegliando quegli abomini. Lo zombie con gli spuntoni ha una chiave che ci servirà.$B$BPrendi quella chiave, entra nella torre e scopri cosa c'è in quel forziere. Porta quello che trovi a Mathias.",
  obj = "Ruba la Defias Tower Key, entra con la forza nella Defias Tower e scopri il contenuto della Duskwood Chest. Porta tutte le informazioni che trovi a Mathias Shaw, a Stormwind. Leggi Kearnen's Journal per saperne di più sulla torre.",
  progress = "Notizie da Agent Kearnen?",
  reward = "Questo spiegherebbe i droni dei Defias che tu e Kearnen avete visto fuori dalla torre, $N. E spiegherebbe anche il coinvolgimento della Venture Company con i Defias e gli strani carichi provenienti da Duskwood.$B$BSecondo questo libro, i troll di Zanzil a Stranglethorn hanno scoperto un modo per risvegliare i morti con le pozioni... o, per essere più precisi, con il veleno.$B$BSenza una solida conoscenza dei veleni non servirai a niente allo SI:7, $N — soprattutto ora che abbiamo a portata di mano la ricetta per creare la non morte.",
  en_title = "Klaven's Tower",
  en_obj = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.$B",
}
T[2360] = {
  title = "Mathias e i Defias",
  desc = "Appena in tempo, $N. La ricognizione dello SI:7 segnala un'attività dei Defias insolitamente intensa a Westfall.$B$BSembra che i Defias abbiano occupato una torre di guardia abbandonata dell'Alleanza a sud-est di Sentinel Hill, e che la usino come base operativa per contrabbandare merci dalla via di rifornimento di Redridge.$B$BRaggiungi Westfall e mettiti in contatto con Agent Kearnen per il resoconto. La troverai nascosta vicino alla torre.$B$B...e, $N, se dovessi essere $Gscoperto:scoperta;, lo SI:7 negherà di sapere alcunché della tua esistenza.",
  obj = "Raggiungi Westfall e trova Agent Kearnen per il resoconto.",
  reward = "Mathias ha finalmente mandato $Gun altro agente:un'altra agente; a darmi man forte, eh? Beh, spero che sia $Gpronto:pronta; a sentire qualche brutta notizia.",
  en_title = "Mathias and the Defias",
  en_obj = "Travel to Westfall and find Agent Kearnen for your debriefing.",
}
T[2361] = {
  title = "Restaurare la collana",
  reward = "Ti do volentieri questa collana, potente $C. Mi hai reso un servizio inestimabile, e per questo ti ringrazio. Indossala con orgoglio, e assicurati di dire ad alta voce e più volte chi te l'ha fatta!$B$BE poi, se potessi aggiungere che non è affatto maledetta, sarebbe fantastico.",
  en_title = "Restoring the Necklace",
}
T[2378] = {
  title = "Trova la Shattered Hand",
  desc = "Hai servito bene gli Inseguitori della Morte, $N, ma forse è ora che tu ti spinga più lontano. Anche se hai mostrato attitudine per la furtività e l'inganno, hai ancora bisogno di molto addestramento.$B$BGli Inseguitori della Morte hanno degli alleati nella Shattered Hand. Cerca quelli che potrebbero aiutarci: trova Shenthul a Orgrimmar.",
  obj = "Raggiungi Orgrimmar e parla con Shenthul nella Cleft of Shadow.",
  reward = "Dunque è questo ciò che i nostri potenti alleati hanno mandato a Shenthul? Che delusione...",
  en_title = "Find the Shattered Hand",
  en_obj = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.",
}
T[2379] = {
  title = "Zando'zan",
  desc = "La tua determinazione da sola non basta a superare gli ostacoli che ci aspettano.$B$BParla con Zando'zan per cominciare il tuo addestramento come agente della Shattered Hand.$B$BSolo quando avrai padroneggiato le arti della furtività e del furto potrai fare il passo successivo verso il tuo destino.",
  obj = "Parla con Zando'zan nella Cleft of Shadow.",
  reward = "Forse Zando'zan si è sbagliato. Zando'zan chiede scusa.",
  en_title = "Zando'zan",
  en_obj = "Speak with Zando'zan at the Cleft of Shadow.",
}
T[2380] = {
  title = "A Orgrimmar!",
  desc = "Non sei $Gun maestro:una maestra; della furtività e dell'inganno, ma tutto questo può cambiare, e cambierà. Evidentemente hai fatto colpo su chi comanda con le tue misere abilità, visto che il grande Shenthul ha chiesto di te per nome.$B$BPrendi la strada a nord di qui fino a Orgrimmar e parla con Shenthul nella Cleft of Shadow.",
  obj = "Parla con Shenthul nella Cleft of Shadow, a Orgrimmar.",
  reward = "È importante che la Shattered Hand resti vigile di fronte ai cambiamenti che Thrall vuole portare nell'Orda. Il nostro numero da solo non basterà a rovesciare il suo dominio: bisogna padroneggiare la furtività e l'inganno.",
  en_title = "To Orgrimmar!",
  en_obj = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar.",
}
T[2381] = {
  title = "Depredare i predoni",
  desc = "Non voglio spaventarti, $N, ma gli ultimi cinque ladri che ho mandato a rubare il Southsea Treasure mi sono tornati indietro a pezzi.$B$BPiù a sud lungo la costa troverai la Tide Razor, la nave dei Southsea Freebooter. Nella stiva c'è il bottino: il Southsea Treasure. Al secondo ponte della nave c'è il covo dei pirati, il posto dove addestrano tutti i loro ladri.$B$BSali su quella nave, ruba il tesoro e portamelo. Se hai bisogno di esercitarti a rubare, usa il covo dei pirati, ma fa' attenzione!",
  obj = "Riporta il Southsea Treasure a Wrenix the Wretched, a Ratchet. Non dimenticare di prendere un E.C.A.C. e i Thieves' Tools da Wrenix's Gizmotronic Apparatus. Ti serviranno entrambi per completare la missione.$B$BSe dovessi essere $Gattaccato:attaccata; da pappagalli insolitamente ostili, usa il tuo E.C.A.C.!",
  progress = "Beh, almeno hai ancora tutti i pezzi al loro posto. Hai trovato il tesoro?",
  reward = "Incredibile! Improbabile! Semplicemente strabiliante! Hai talento, $N. O quello, o sei $Gl'uomo più fortunato:la donna più fortunata; del mondo!$B$BEcco la tua parte del bottino. Di sicuro tu ne farai un uso migliore del mio.",
  en_title = "Plundering the Plunderers",
  en_obj = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.$B$BShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!$B$B",
}
T[2382] = {
  title = "Wrenix di Ratchet",
  desc = "Zando'zan l'ha visto! Sì, il giorno arriva! La morte di Thrall... il pugnale nella sua schiena, il veleno che gli scorre in ogni vena... Zando'zan ha detto troppo.$B$B$N! Zando'zan ha un compito per $N! $N deve andare a Ratchet, a est del Crossroads, e parlare con Wrenix the Wretched. Va'!",
  obj = "Raggiungi Ratchet e parla con Wrenix the Wretched.",
  reward = "$GUn altro:Un'altra;? Gli ultimi cinque che quel troll matto mi ha mandato sono finiti in pasto agli squali. Speriamo che a te vada un po' meglio, eh?",
  en_title = "Wrenix of Ratchet",
  en_obj = "Travel to Ratchet and speak with Wrenix the Wretched.",
}
T[2383] = {
  title = "Simple Parchment",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Frang, l'istruttore di guerrieri. Vuole parlarti quando sei $Gpronto:pronta;. Lo trovi fuori dal Den, al riparo all'ombra.",
  obj = "Leggi la Simple Parchment e parla con Frang, nella Valley of Trials.",
  progress = "Cos'hai lì? Una pergamena? Non sarai $Guno studioso:una studiosa;, spero...",
  reward = "Ah, è la mia pergamena. Avevo sentito che saresti $Garrivato:arrivata; nella Valley, $N. Sono contento di vedere che ce l'hai fatta: speriamo che tu sopravviva alle prove che ti aspettano. Come dicevo, man mano che cresci in potenza vieni da me: farò il possibile per addestrarti nelle vie $Gdel:della; $C.$B$BBuona fortuna, $N, e torna da me quando ti senti $Gpronto:pronta;.",
  en_title = "Simple Parchment",
  en_obj = "Read the Simple Parchment and speak to Frang in the Valley of Trials.",
}
T[2398] = {
  title = "I nani perduti",
  desc = "Il sito di scavo di Uldaman non è sempre stato invaso. Noi nani di Ironforge controllavamo la zona, ma... era prima che arrivassero i trogg. Sono arrivati così in fretta e in numero così grande che nemmeno la forza dei nani è riuscita a fermarli!$B$BAnzi, il loro attacco è stato così improvviso che temo che alcuni dei nostri siano rimasti intrappolati dietro le linee nemiche.$B$BIl mio amico Baelog ha guidato un piccolo gruppo di nani nel cuore del sito poco prima che si facessero vivi i trogg. Se lui e la sua compagnia sono vivi, voglio che tu li trovi.",
  obj = "Trova Baelog a Uldaman.",
  reward = "Era ora che arrivassi! Stavo per perdere una scommessa con Olaf!$B$BAveva scommesso che la barba gli sarebbe arrivata alle ginocchia prima di vedere $Gun altro:un'altra; $R in vita. Be', eccoti qui, e come vedi alla barba di Olaf mancano ancora un bel po' di centimetri.$B$BGrazie, $N. Dividerò la vincita con te.",
  en_title = "The Lost Dwarves",
  en_obj = "Find Baelog in Uldaman.",
}
T[2399] = {
  title = "Le fronde germogliate",
  reward = "Le fronde che Denalan ha piantato nel suo giardino sono germogliate e cresciute. Tremano, impazienti di essere raccolte...",
  en_title = "The Sprouted Fronds",
}
T[2418] = {
  title = "Pietre energetiche",
  desc = "Tempo fa ho avuto una disavventura con i nani Shadowforge. Mi hanno portato ad Angor Fortress per studiare due tipi di strane pietre di Uldaman. Ho scoperto che, se trattate nel modo giusto, erano fonti di energia durature e stabili. È incredibile quello che si trova in quel vecchio sito di scavo!$B$BComunque, dopo che gli ho svelato il segreto delle pietre, mi hanno cacciato da Angor Fortress e si sono messi a scavare a Uldaman per trovarne altre.$B$BQuelle pietre le voglio io! Portami tutti e due i tipi e ti pagherò un sacco!",
  obj = "Porta 8 Dentrium Power Stone e 8 An'Alleum Power Stone a Rigglefuzz, nei Badlands.",
  progress = "Hai le pietre energetiche, $N? Ho un roditore robotico che ha bisogno di una fonte di energia...",
  reward = "Fantastico, ne hai trovate! Grazie mille, $N. Sei $Gil:la; $R più affidabile che abbia mai incontrato!$B$BNon vedo l'ora di provarle su certi congegni che sto mettendo a punto. Scommetto che, nelle giuste condizioni, i congegni alimentati con queste pietre andranno avanti, e avanti, e avanti...",
  en_title = "Power Stones",
  en_obj = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.",
}
T[2438] = {
  title = "L'Emerald Dreamcatcher",
  desc = "Un tempo ricevetti un acchiappasogni di smeraldo da Gaerolas Talvethen, il custode dei druidi della Ban'ethil Barrow Den. Questo potente amuleto è in grado di attingere energia dall'Emerald Dream, concedendo fortuna a chi lo porta.$B$BPurtroppo non sono riuscito a recuperarlo dal mio comò a Starbreeze Village... Un tempo Starbreeze era un luogo tranquillo, ma ora è caduta preda della corruzione dei furbolg che vi risiedono.$B$BForse saresti disposto a recuperare il mio acchiappasogni, $c? ",
  obj = "Porta l'Emerald Dreamcatcher a Tallonkai Swiftroot a Dolanaar.",
  progress = "Ti prego, fa' in fretta. Posso solo sperare che il mio acchiappasogni di smeraldo non sia stato danneggiato dai furbolg.$B$BL'hai già recuperato, $N?",
  reward = "Il mio acchiappasogni di smeraldo è di grande importanza per me. È un dono concesso a pochi. Grazie per averlo riportato, $N.",
  en_title = "The Emerald Dreamcatcher",
  en_obj = "Bring the Emerald Dreamcatcher to Tallonkai Swiftroot in Dolanaar.",
}
T[2440] = {
  title = "I dischi di platino",
  desc = "Concentrerò le mie energie su questi dischi; a tempo debito mi riveleranno il loro vero funzionamento.$B$BQuanto a te, $N, ora ti ricompenserò per la diligenza con cui me li hai segnalati. Porta questo buono a Bena Winterhoof, l'istruttrice di alchimia di Thunder Bluff. Ti darà un oggetto speciale che credo troverai interessante, e ti offrirà una scelta di pozioni dalla mia scorta personale.$B$BTorna presto da me, perché sento che c'è ancora molto da fare riguardo a questa scoperta.",
  obj = "Porta il Reward Voucher a Bena Winterhoof, a Thunder Bluff.",
  progress = "Salve, $C! Sei qui per imparare l'alchimia, o per qualcos'altro?",
  reward = "Be', $N, devi aver fatto molto piacere a Sage Truthseeker, se ti ha dato questo oggetto. Ti spetta anche un dono dalla sua scorta di pozioni; come ricompensa puoi scegliere tra 5 Superior Healing Potion e 5 Greater Mana Potion.",
  en_title = "The Platinum Discs",
  en_obj = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.",
}
T[2458] = {
  title = "Sotto copertura",
  desc = "La Venture Company... Forse ne hai sentito parlare?$B$BPer un anno ci siamo impegnati a infiltrare un agente nel cuore delle loro file. Con molto lavoro e un'attenta pianificazione, ci siamo riusciti.$B$BDi recente ci è giunta voce che la Venture Co. sta preparando qualcosa in grande. Va' a nord dello Sludge Fen, alla torre della Venture Co., e mettiti in contatto con il nostro agente sotto copertura, Taskmaster Fizzule.$B$BQuando trovi la torre, usa questa Flare Gun, poi avvicinati a Fizzule e fagli il saluto della Shattered Hand.",
  obj = "Raggiungi la Venture Co. Tower, a nord dello Sludge Fen, e mettiti in contatto con l'agente segreto della Shattered Hand, Taskmaster Fizzule.$B$BQuando la torre è in vista, usa la Flare Gun per segnalare il tuo arrivo a Taskmaster Fizzule. Spara DUE razzi, poi avvicinati a Taskmaster Fizzule ed esegui lo Shattered /Salute.$B$BQueste azioni vanno eseguite nell'ordine giusto, perché Fizzule attacca ed elimina chiunque non riconosca.",
  reward = "Fa piacere vedere $Gun altro agente:un'altra agente; della Shattered Hand da queste parti; però il razzo forse era un po' troppo!$B$BLa prossima volta che devi parlarmi, soffia due volte in questo fischietto e saprò che sei $Gun alleato:un'alleata;.",
  en_title = "Deep Cover",
  en_obj = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.$B$BWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.$B$BThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.",
}
T[2459] = {
  title = "Ferocitas the Dream Eater",
  desc = "Lo smeraldo... è sparito! Il mio acchiappasogni è stato danneggiato!$B$BC'è una banda di mistici Gnarlpine a nord di Starbreeze. Ho sentito dire che il loro capo, Ferocitas the Dream Eater, porta una collana che brilla di verde nella notte. Ora, vedendo il mio acchiappasogni, sono certo che ha rubato il mio smeraldo... Non si renderebbe mai conto che il suo potere è inutile per lui.$B$BTrova questo gioiello scomparso, $N. E, già che ci sei, elimina anche un po' di quei mistici corrotti.",
  obj = "Tallonkai Swiftroot a Dolanaar vuole che tu uccida 7 Gnarlpine Mystic e trovi il Missing Jewel.",
  progress = "Ferocitas e i Gnarlpine Mystic devono restituire ciò che è mio. Ti prego, recupera lo smeraldo così che io possa riparare il mio acchiappasogni di smeraldo.",
  reward = "Ora posso riparare il mio acchiappasogni. Grazie, $N.",
  en_title = "Ferocitas the Dream Eater",
  en_obj = "Tallonkai Swiftroot in Dolanaar wants you to kill 7 Gnarlpine Mystics and find the Missing Jewel.",
}
T[2460] = {
  title = "Lo Shattered Salute",
  desc = "Come $Gladro:ladra; della Shattered Hand, è indispensabile che tu impari lo Shattered Salute. È l'unico modo per riconoscere con certezza un altro membro della Hand.$B$BGuarda, impara, ripeti.",
  obj = "Esegui lo Shattered Salute davanti a Shenthul.",
  progress = "Esercitati!",
  reward = "Ben fatto, $N. Ora sei $Gpronto:pronta; per andare avanti.",
  en_title = "The Shattered Salute",
  en_obj = "Perform the Shattered Salute on Shenthul.",
}
T[2478] = {
  title = "Missione: possibile ma non probabile",
  desc = "Dovrai rubare la chiave della torre a Foreman Silixiz, $N. Una volta che l'avrai in tuo possesso, tienila: potrebbe servirmi più tardi.$B$BRicorda, il veleno ha indebolito tutti quelli che stanno in questa torre. Usa le tue abilità per portare caos e distruzione tra i suoi abitanti. Uccidili tutti — nessuna pietà!$B$BQuando dentro non resterà che un mucchio di corpi insanguinati, scassina Gallywix's Lockbox e ruba la scorta della miscela di Zanzil che contiene. Porta sia la testa di Gallywix sia la miscela a Shenthul, a Orgrimmar.",
  obj = "Ruba Silixiz's Tower Key a Foreman Silixiz, poi uccidi due Mutated Venture Co. Drone, due Venture Co. Patroller e due Venture Co. Lookout.$B$BAssassina Grand Foreman Gallywix e prendi la sua testa, poi scassina Gallywix's Lockbox e ruba la Cache of Zanzil's Altered Mixture. Porta la Cache e Gallywix's Head a Shenthul, a Orgrimmar, per ulteriori istruzioni.",
  progress = "Cosa hai da riferire, $N?",
  reward = "Povero Fizzule, era un buon agente — uno dei nostri migliori. Ahimè, è il prezzo che paghiamo, $N. Essere un agente sul campo della Shattered Hand è un lavoro pericoloso.$B$BHai svolto bene il tuo dovere, $C. Sarebbe un peccato se non vivessi abbastanza da servirci ancora.",
  en_title = "Mission: Possible But Not Probable",
  en_obj = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.$B$BAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.$B",
}
T[2479] = {
  title = "L'aiuto di Hinott",
  desc = "Porta un campione della miscela a Serge Hinott, a Tarren Mill.$B$BSe qualcuno può curarti, quello è Serge. Se vivrai abbastanza, Serge ti mostrerà come si creano e si usano i veleni.",
  obj = "Raggiungi Tarren Mill, nelle Hillsbrad Foothills, e consegna il Sample of Zanzil's Mixture a Serge Hinott.$B$BPer arrivare a Tarren Mill, prendi lo zeppelin per l'Undercity e segui la strada verso sud attraverso Silverpine, in direzione di Hillsbrad. Segui i cartelli!",
  progress = "Cos'è questo???",
  reward = "Hai un pallore delizioso, $C. E cos'è quell'odore nauseabondo che emani? Devo saperlo!",
  en_title = "Hinott's Assistance",
  en_obj = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.$B$BTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!$B$B",
}
T[2480] = {
  title = "L'aiuto di Hinott",
  desc = "Non ho mai visto risultati così meravigliosi da un veleno! Zanzil, dici? Mai sentito nominare; però devo fargli i miei complimenti per aver creato questo intruglio.$B$BDunque, dovrei curarti da questo e poi insegnarti a usare il veleno?$B$BDammi qualche momento per esaminare la tossina, $N.",
  obj = "Aspetta che Serge Hinott abbia preparato la cura.",
  reward = "La cura è pronta! Bevi questa antitossina e la follia strisciante si fermerà; per l'odore, però, non potrò fare niente.",
  en_title = "Hinott's Assistance",
  en_obj = "Wait for Serge Hinott to complete the cure.",
}
T[2498] = {
  title = "Ritorno da Denalan",
  desc = "Ho appena ricevuto notizia che Denalan, a Lake Al'Ameth, ha scoperto quella che potrebbe essere la causa dei tumori che affliggono i timberling. Ti prego, parlagli e digli che ti mando io.$B$BSbrigati, $N: ha bisogno del nostro aiuto.",
  obj = "Rellian Greenspyre vuole che tu parli con Denalan a Lake Al'Ameth.",
  reward = "Ah, dunque Rellian ti ha mandat$Go:a; ad aiutarmi. Sono lieto che tu sia arrivat$Go:a; così presto.$B$BHo scoperto qualcosa di piuttosto inquietante!",
  en_title = "Return to Denalan",
  en_obj = "Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth.",
}
T[2499] = {
  title = "Oakenscowl",
  desc = "In una caverna lungo la riva meridionale del lago, un timberling di nome Oakenscowl sta diffondendo la corruzione a tutte le creature che hanno fatto di Lake Al'Ameth la loro casa.$B$BNon ho osato avvicinarmi troppo, ma anche da lontano è evidente: Oakenscowl è avvelenato dal tumore più grande che io abbia mai visto... Lo definirei persino gargantuesco.$B$B$N, hai già fatto molto per aiutare i miei sforzi, ma ti chiedo un ultimo compito. Dai la caccia a Oakenscowl e raccogli il tumore; rimuovi questa fonte di corruzione dalla mia casa.",
  obj = "Denalan a Lake Al'Ameth vuole che tu raccolga il Gargantuan Tumor da Oakenscowl.",
  progress = "Hai già individuato Oakenscowl, $R?",
  reward = "Sapevo che eri più che capace di liberare il lago da quella orribile bestia.$B$BÈ una situazione angosciante: Oakenscowl era un tempo un grande capo tra i suoi simili... ma la corruzione non fa distinzione tra umili e nobili.$B$BLe dimensioni di questo tumore sono davvero inquietanti, ma devo studiarlo per saperne di più sulla malattia che sconvolge la popolazione dei timberling.$B$BGrazie, $N.",
  en_title = "Oakenscowl",
  en_obj = "Denalan at Lake Al'Ameth wants you to collect the Gargantuan Tumor from Oakenscowl.",
}
T[2500] = {
  title = "Reagenti delle Badlands",
  desc = "$C, vorrei avvalermi dei tuoi servigi. Sono un alchimista di una certa fama e cerco il tuo aiuto per procurarmi alcuni reagenti che si trovano nelle Badlands.$B$BPer rifornire le mie scorte mi servono: cinque ventrigli di avvoltoio, dieci zanne di coyote delle rupi e cinque frammenti di elementale di roccia. Ovviamente puoi prenderli dalle bestie stesse; se non sei $Gtipo:tipa; da combattimento, trova degli amici che lo siano.$B$BProcurami questa roba e ci guadagnerai qualche moneta.$B$BAllora, che ne dici?",
  obj = "Procura i reagenti delle Badlands che servono a Ghak Healtouch, poi torna da lui a Thelsamar.",
  progress = "Hai già trovato quello che mi serve? Non sarai pagat$Go:a; finché non mi porti quei reagenti.",
  reward = "Ah, ben fatto, $N. Questi dovrebbero bastarmi almeno per un po'. Ecco la tua paga, come promesso.$B$BSe ti interessa, mi servirebbero altri reagenti. Questi però si trovano solo nelle profondità dello scavo di Uldaman. Non sarà facile procurarli, ma se vorrai aiutarmi di nuovo ne varrà la pena.$B$BMagari qualcosa di più di qualche moneta luccicante, eh?",
  en_title = "Badlands Reagent Run",
  en_obj = "Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar.",
}
T[2501] = {
  title = "Reagenti delle Badlands II",
  desc = "Mi sei stat$Go:a; di grande aiuto, $N. Vorrei ricompensarti con la ricetta della bevanda che ti ho dato prima, ma devo chiederti un favore piuttosto pericoloso.$B$BQuesto scrigno contiene tre recipienti taumaturgici vuoti; sono intrisi di un'aura di sintonia che prosciugherà il sangue di un scorched guardian dragon. Usarne uno sulla bestia la farà infuriare parecchio, quindi fai attenzione. Quando li avrai riempiti tutti e tre, portameli.$B$BFallo, e la ricetta sarà tua.",
  obj = "Usa gli empty thaumaturgy vessels sugli scorched guardian dragons delle Badlands. Quando li avrai riempiti, portali a Ghak Healtouch a Thelsamar.",
  progress = "Hai usato i recipienti per procurarmi il sangue di scorched guardian dragon che mi serve? Sì, lo so che è un compito pericoloso... ma la ricetta del mio tonico ristoratore attende il tuo successo. Rischio e ricompensa, amic$Go:a; mi$Go:a;... rischio e ricompensa...",
  reward = "Da alchimista ad alchimista, ti saluto. Ecco, prendi questa ricetta e imparala a memoria. Che ti porti il successo e le ricompense che ha portato a me in tutti questi anni!",
  en_title = "Badlands Reagent Run II",
  en_obj = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Ghak Healtouch in Thelsamar.",
}
T[2518] = {
  title = "Lacrime della Luna",
  desc = "Lady Sathrah era un tempo amata da Elune. Aggraziata e pura, il ragno filava i suoi fili d'argento alla luce della luna, catturando la foschia della sera. La rugiada argentea aveva forti poteri curativi ed era custodita qui nel tempio.$B$BMa di recente Sathrah è precipitata nella follia. Anche le sue future generazioni sono ora in pericolo.$B$BTrova Lady Sathrah, $N, e metti fine alla sua sofferenza. Vive lungo i confini settentrionali di Teldrassil, vicino a Wellspring Lake. Raccogli le sue filiere argentee e riportamele.",
  obj = "Priestess A'moora nel Temple of the Moon a Darnassus vuole che le porti le Lady Sathrah's Silvery Spinnerets.",
  progress = "Mi dispiace per il compito che ti ho chiesto di svolgere; ma Lady Sathrah è oltre ogni speranza.$B$BSperiamo di offrire a Elune il sacrificio delle filiere. Con questo sacrificio, Elune benedirà Sathrah affinché possa rinascere, in pace.",
  reward = "La foresta piange Lady Sathrah, ma era qualcosa che andava fatto.$B$BGrazie, $N.",
  en_title = "Tears of the Moon",
  en_obj = "Priestess A'moora in the Temple of the Moon at Darnassus wants you to bring her Lady Sathrah's Silvery Spinnerets.",
}
T[2519] = {
  title = "Il Temple of the Moon",
  desc = "Una creatura un tempo grandiosa della foresta ha bisogno di aiuto, $r.$B$BC'è un compito difficile da portare a termine.$B$BCerca Priestess A'moora: ti spiegherà tutto. La troverai a sudest di qui, dentro il Temple of the Moon.",
  obj = "Sister Aquinne vuole che tu parli con Priestess A'moora nel Temple of the Moon.",
  reward = "Dunque ti ha mandato Sister Aquinne?",
  en_title = "The Temple of the Moon",
  en_obj = "Sister Aquinne wants you to speak with Priestess A'moora in the Temple of the Moon.",
}
T[2520] = {
  title = "Il sacrificio di Sathrah",
  desc = "Ora devi portare a termine il compito che ti è stato affidato. Prendi le filiere e offri il sacrificio di Lady Sathrah a Elune; dai pace alla grande aracnide.$B$BDentro questo tempio trova la fontana centrale. È lì che puoi lasciare il sacrificio. Le acque sacre purificheranno e puliranno la corruzione che ha fatto impazzire Sathrah.$B$BQuando hai finito, torna da me.",
  obj = "Priestess A'moora vuole che tu deponga le Lady Sathrah's Silvery Spinnerets alla fontana dentro il tempio, e che poi torni da lei.",
  progress = "Hai deposto il sacrificio alla fontana, $n?",
  reward = "La perdita di Lady Sathrah è angosciante, ma solo così può rinascere con uno spirito rinnovato.$B$BPossa Elune accogliere di buon grado il sacrificio che le hai offerto.",
  en_title = "Sathrah's Sacrifice",
  en_obj = "Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.",
}
T[2541] = {
  title = "Il druido addormentato",
  desc = "Gli sciamani Gnarlpine che abitano questo luogo hanno scoperto il modo di separare lo spirito di un druido addormentato dal suo corpo fisico. I furbolg hanno animato la mia forma fisica e la usano per attaccare chiunque tenti di esplorare la Ban'ethil Barrow Den. Ora sono intrappolato nell'Emerald Dream, impotente di fronte a tutto questo.$B$BDevi aiutarmi. Gli sciamani Gnarlpine portano con sé uno strano amuleto usato per compiere questo rituale, e vorrei esaminarlo. Ti prego, $N, portamene uno.",
  obj = "Porta un Shaman Voodoo Charm a Oben Rageclaw nella Ban'ethil Barrow Den.",
  progress = "Se riuscirò a esaminare l'amuleto, forse scoprirò come spezzare l'incantesimo. Ne hai trovato uno?",
  reward = "Grazie, $N.$B$BChe strano ninnolo... Percepisco l'aura malvagia che emana: è un incantesimo potentissimo.",
  en_title = "The Sleeping Druid",
  en_obj = "Bring a Shaman Voodoo Charm to Oben Rageclaw in the Ban'ethil Barrow Den.",
}
T[2561] = {
  title = "Druido dell'Artiglio",
  desc = "Dopo aver esaminato questo amuleto, $N, ora vedo cosa va fatto. Ti prego, prendilo e fai ciò che ti chiedo.$B$BDevi esplorare le zone più profonde della Ban'ethil Barrow Den. Là troverai il mio corpo senz'anima... Per quanto mi dispiaccia dirtelo, non vedo altro modo per liberarmi dal controllo dei Gnarlpine.$B$BPerché io possa sfuggire loro, devi uccidere la mia forma fisica. Fatto questo, usa l'amuleto voodoo sul mio corpo caduto. Quando avrai terminato, torna da me.",
  obj = "Oben Rageclaw vuole che tu uccida il suo corpo senz'anima, e che poi usi il Voodoo Charm.",
  progress = "$N, sii prudente quando ti avvicini alla mia forma fisica: l'incantesimo che la tiene prigioniera è molto potente.",
  reward = "Finalmente sono libero dal controllo dei Gnarlpine. Grazie, $N.$B$BOra il mio spirito potrà riposare in pace per sempre nell'Emerald Dream.$B$BForse un giorno ci rivedremo, giovane $C. Ma per ora, accetta questa ricompensa come simbolo della mia gratitudine.",
  en_title = "Druid of the Claw",
  en_obj = "Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm.",
}
T[2607] = {
  title = "Il tocco di Zanzil",
  desc = "Sembra che tu abbia riportato più informazioni di quante me ne aspettassi perfino io. Questa sì che è una strana piega degli eventi, $N.$B$BUna cura? Mmh... Scendi in cantina e parla con Doc Mixilpixil: forse può aiutarti.",
  obj = "Parla con Doc Mixilpixil nella cantina dei Barracks.",
  reward = "Era ora! Metti il formaggio sul tavolo e fila via. Osborne ti pagherà all'uscita.",
  en_title = "The Touch of Zanzil",
  en_obj = "Speak with Doc Mixilpixil in the cellar of the Barracks.",
}
T[2608] = {
  title = "Il tocco di Zanzil",
  desc = "Oh cielo, sembri la morte in persona. Correggo: io la morte l'ho vista, e tu sei $Gmesso:messa; peggio. Tu, $Gsignore:signorina;, saresti quello che la morte ha tossito fuori alla sua ultima visita medica.$B$BAh! Hai sentito, Noarm? Scrivitela!$B$B*Coff* Ehm, sì, per poterti aiutare dovrò prelevarti un po' di sangue. Non preoccuparti, fa male solo le prime... cinquanta volte o giù di lì... Usa /lay down quando sei $Gpronto:pronta; per il trattamento, $N.",
  obj = "Usa /Lay down per farti visitare da Doc Mixilpixil. Come può trovare la cura se non trova la causa?",
  progress = "Quando sei $Gpronto:pronta; per la visita, sdraiati a terra con /lay down e comincerò la flebotomia.",
  reward = "Dammi un momento per consultarmi con i miei colleghi, $N. Dottor Montgomery, signor Noarm, a consulto!",
  en_title = "The Touch of Zanzil",
  en_obj = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?$B",
}
T[2609] = {
  title = "Il tocco di Zanzil",
  desc = "Siamo tutti d'accordo, $N. Hai la 'ite'.$B$BPer fortuna, ho una cura per la 'ite'.$B$BEcco cosa mi serve: un mazzo di Simple Wildflowers, un Leaded Vial, un Bronze Tube e, ultimo ma non meno importante, uno Spool of Light Chartreuse Silk Thread. Ol' Emma me ne ha lasciata una bobina a 'The Finest Thread'. Trovi la bottega lungo i canali.$B$BOra sbrigati, $N, e cerca di non toccare nessuno finché non sarai $Gguarito:guarita;. Ah, e il dottor Montgomery dice che hai bisogno di una doccia — parole sue, non mie.",
  obj = "Porta a Doc Mixilpixil un mazzo di Simple Wildflowers, un Leaded Vial, un Bronze Tube e uno Spool of Light Chartreuse Silk Thread. La 'ite' non guarisce da sola, $Ggiovanotto:signorina;.",
  progress = "Se vuoi guarire dalla 'ite', dovrai impegnarti più di così, $N. Dove sono i reagenti per la cura?",
  reward = "Che cosa sto facendo? Che cosa ti sembra che stia facendo? Sto preparando una cura per la tua 'ite'! Non ti indignare con me, $N!$B$BAncora qualche secondo. Ecco! Spruzzati addosso questa, ehm, medicina dal profumo fantastico e tornerai $Gcome nuovo:come nuova;.",
  en_title = "The Touch of Zanzil",
  en_obj = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young $g fella:lady;. ",
}
T[2622] = {
  title = "Gli ordini scomparsi",
  desc = "Gli ordini? Cosa te ne faresti mai degli ordini?$B$BCosa vorresti insinuare, $N? Certo che ho trasmesso quegli ordini! I soldati a cui li avevo affidati sono stati attaccati e massacrati di botte dai murloc. Ne è sopravvissuto uno solo, se così si può dire. Riesce a malapena a parlare, non può camminare, e bisogna nutrirlo con un tubo. Se vuoi sapere che fine hanno fatto quegli ordini, parla con Bengor. Sono sicuro che è qui da qualche parte... e, $N, sta' $Gattento:attenta; a dove ficchi il naso: potrebbero staccartelo a morsi.",
  obj = "Parla con Bengor.",
  reward = "Swamp tal... talk... talker...",
  en_title = "The Missing Orders",
  en_obj = "Speak to Bengor.",
}
T[2623] = {
  title = "Lo Swamp Talker",
  desc = "Ordini dati dal comandante dei dispacci. Noi presi... presi ordini. Verso Blasted Lands, agguato.$B$BMurloc... Tanti murloc... Uno chiamato Swamp Talker. Preso ordini da mie mani mentre lancia entrava nel cranio. Est... grotta...$B$B<Bengor sviene.>",
  obj = "Recupera i Warchief's Orders e riportali al Fallen Hero of the Horde.",
  progress = "In attesa di ordini.",
  reward = "È peggio di quanto immaginassi. Diciannove dei miei uomini avrebbero potuto essere risparmiati dall'agonia che hanno affrontato. Se solo non avessi agito in modo così irrazionale.$B$BDevi aiutarli, $N! Io non posso fare niente.",
  en_title = "The Swamp Talker",
  en_obj = "Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde.",
}
T[2745] = {
  title = "Infiltrarsi nel castello",
  desc = "Hmm, una storia interessante, e non da prendere alla leggera. Sì, posso aiutarti, ma quel che devi fare è distribuire una forma di giustizia che non è... legale, se vuoi arrivare in fondo a questa storia.$B$BBisogna occuparsi di Lescovar e Marzon, e in fretta. Pensi di essere in grado di una cosa simile?$B$BDecidi tu. Se sì, allora corri al castello e trova un mio vecchio amico, uno gnomo di nome Tyrion. Sono un paio di settimane che tiene d'occhio Lescovar. Dovrebbe riuscire ad aiutarti a chiudere questa faccenda.",
  obj = "Parla con Tyrion, a Stormwind Castle.",
  reward = "Ma che...?! Non sbucarmi addosso in quel modo! E abbassa la voce! In nome dell'Ombra, perché mai vieni a sbucarmi addosso di soppiatto? Non vedi che sono occupato, $Gstupido sciocco:stupida sciocca;?$B$BCome sarebbe, cosa sto facendo? Sto aspettando che si apra il prossimo Dark Portal, tu che diamine credi che stia facendo? Di' quel che hai da dire e vattene... prima che le guardie notino noi due nascosti insieme tra i cespugli. Ho una reputazione da mantenere.",
  en_title = "Infiltrating the Castle",
  en_obj = "Speak to Tyrion in Stormwind Castle.",
}
T[2746] = {
  title = "Oggetti di una certa importanza",
  desc = "Trias vuole anticipare un po' i tempi, eh? Va bene, si può fare, ma io non sono pronto. E sappi una cosa: la parte difficile la faccio io, ma sei tu $Gquello:quella; che si sporcherà le mani, chiaro? Bene.$B$BAllora, mi serve che tu mi procuri qualche cosa prima che possa mettere in atto il mio piano. Ho il travestimento perfetto per far passare Spybot davanti a quelle guardie.$B$BPortami un po' di seta e un paio di mele. La seta la trovi come vuoi, ma la piccola fattoria di Clara appena fuori città ha mele della misura perfetta.",
  obj = "Porta 3 Silk Cloth e 2 Clara's Fresh Apple a Tyrion, a Stormwind.",
  progress = "Sono un paio di settimane che tengo d'occhio Lescovar. Trias non si è mai fidato di lui, ma non sospettavamo che fosse coinvolto in qualcosa che riguarda la Defias Brotherhood. Seguivamo piste che lo legavano al Martello del Crepuscolo. In ogni caso è diventato più pericoloso di quanto questa città possa gestire, ed è lì che entriamo in gioco noi.$B$BProcurami quelle cose e potremo mettere in atto il mio piano.",
  reward = "Questi andranno benissimo, $N. Ottimo lavoro.$B$BIl resto dell'attrezzatura che mi serve ce l'ho nello zaino... ringrazio la Luce di essermi fatto fare da un amico sarto una borsa di seta. Stavo finendo lo spazio, a portarmi dietro tutta la roba.$B$BPrima che Spybot entri, mettiamo a punto i dettagli, così sai cosa devi fare.",
  en_title = "Items of Some Consequence",
  en_obj = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.",
}
T[2766] = {
  title = "Trova OOX-22/FE!",
  desc = "Hai scoperto una specie di strano congegno di metallo a forma di uovo. Armeggiando con una delle sue manopole, l'uovo prende vita e si apre in una specie di aggeggio robotico gnomesco! Dall'interno dell'uovo robotico gracchia una voce.$B$B\"Mi chiamo Oglethorpe Obnoticus, e il mio robot a ritorno automatico si è schiantato! Ti ricompenserò se lo recuperi; ti prego, porta questo segnalatore al robot!\"$B$B\"Ho calcolato per te le coordinate del robot: è in una grotta vicino a Feral Scar Vale!\"",
  obj = "Porta l'OOX-22/FE Distress Beacon al robot a ritorno automatico di Oglethorpe, in una grotta vicino a Feral Scar Vale.",
  progress = "Sembra che tu abbia scoperto il relitto di... un pollo robotico? La voce dall'interno dell'uovo gracchia di nuovo:$B$B\"Sì, ottimo lavoro! Questo è proprio il mio robot a ritorno automatico, anche se i miei sensori indicano che ha bisogno di una spinta per ripartire prima di poter tornare in volo a Booty Bay per le riparazioni. Coraggio, metti il segnalatore dentro il rover: al resto penserà il segnalatore!\"",
  reward = "Metti l'uovo... il segnalatore di soccorso... dentro il pollo... il robot a ritorno automatico.$B$BDall'interno del robot si sentono ronzii e fruscii mentre cerca di rimettersi in piedi. Quando il robot prende vita, si sente di nuovo la voce di Oglethorpe, ma ora dall'interno del robot:$B$B\"OOX-22/FE almeno funziona, ma ha bisogno di riparazioni importanti! È troppo pesante perché tu possa portarlo... ma credo di avere un'idea. Te la senti di sorvegliarlo ancora un po'?\"",
  en_title = "Find OOX-22/FE!",
  en_obj = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.",
}
T[2767] = {
  title = "Salva OOX-22/FE!",
  desc = "La voce dello gnomo gracchia di nuovo dal robot:$B$B\"Devo portare OOX-22/FE in un posto aperto e sicuro, così potrà cominciare una lunga procedura di decollo. Ha un occultamento incorporato, ma dalla mia parte mi serve tempo per rimetterlo in funzione. Scorta il robot da dove si trova ora fino a, diciamo, il molo lungo la Forgotten Coast! Dovrebbe essere il posto perfetto, e il tempo sufficiente, per rimettere tutto in linea!\"$B$B\"Scortalo al molo sano e salvo, e poi vieni a parlarmi a Booty Bay! Oglethorpe Obnoticus, passo e chiudo!\"",
  obj = "Scorta OOX-22/FE fino al molo lungo la Forgotten Coast, poi fai rapporto a Oglethorpe Obnoticus, a Booty Bay.",
  progress = "Sì, sono Oglethorpe Obnoticus, maestro inventore al tuo servizio! Allora, c'è qualcosa in cui posso aiutarti?",
  reward = "Oh, sei TU $Gil grande salvatore:la grande salvatrice; di OOX-22/FE! Non so nemmeno da dove cominciare per ringraziarti del tuo aiuto! La mia serie di robot a ritorno automatico ha bisogno di altro sviluppo, ma il tuo recupero mi ha risparmiato innumerevoli ore di ricostruzione, e anche parecchie monete d'oro in costi di fabbricazione!$B$BTi prego, scegli uno di questi oggetti che ho. Grazie ancora per il tuo generoso aiuto, $N: io e i miei robot siamo in debito con te!",
  en_title = "Rescue OOX-22/FE!",
  en_obj = "Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.",
}
T[2768] = {
  title = "Divino-matic Rod",
  desc = "Sergeant Bly mi ha derubato! Aveva detto che me la prendeva solo in prestito, ma mi ha rubato la mia preziosa Divino-matic Rod!! Senza quella verga come faccio a sapere dove scavare nuovi pozzi d'acqua??$B$BTrova Bly e riportami la mia verga! Ho sentito che ha portato la sua banda di avventurieri di dubbia fama a caccia di tesori a Zul'Farrak, a ovest. Scommetto che lo troverai lì.$B$BSperiamo che i troll l'abbiano già sistemato, perché se dovrai batterti con lui per la verga, ti aspetta uno scontro serio.",
  obj = "Porta la Divino-matic Rod a Chief Engineer Bilgewhizzle, a Gadgetzan.",
  progress = "Hai trovato Sergeant Bly? Hai preso la mia Divino-matic Rod?",
  reward = "L'hai trovata! Ben fatto, $N! Hai dovuto combattere con Bly per averla? Spero che tu abbia steso lui e la sua banda come si deve!",
  en_title = "Divino-matic Rod",
  en_obj = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.",
}
T[2769] = {
  title = "I fratelli Brassbolts",
  desc = "Hai conosciuto i fratelli Brassbolts? Sono laggiù nelle Shimmering Flats, in Kalimdor, a gareggiare con la loro auto a razzo contro i goblin. Di solito vincono, e non c'è da stupirsi — l'auto dei goblin esplode così spesso che non taglia quasi mai il traguardo!$B$BMa anche così, i fratelli Brassbolts cercano sempre nuovi modi per far andare più veloce la loro auto, e Wizzle mi ha detto che gli serve un componente molto raro per il suo prossimo esperimento.$B$BProbabilmente ha bisogno di aiuto per procurarsi quel pezzo. Parla con lui e scoprilo.",
  obj = "Parla con Wizzle Brassbolts, nelle Shimmering Flats.",
  reward = "Ah, vuoi aiutarmi? Fantastico!$B$BC'è un pezzo che voglio per un esperimento a cui sto lavorando, e mi serve $Gun:una; $C $Gcoraggioso:coraggiosa; come te che mi aiuti a procurarmelo!",
  en_title = "The Brassbolts Brothers",
  en_obj = "Speak with Wizzle Brassbolts in the Shimmering Flats.",
}
T[2770] = {
  title = "Gahz'rilla",
  desc = "Nel profondo di Zul'Farrak, la città dei troll delle sabbie a Tanaris, c'è una vasca sacra. Da quella vasca i troll evocano una bestia enorme! Gahz'rilla! È così feroce che perfino le sue scaglie crepitano di energia. È quell'energia che voglio imbrigliare per la mia macchina!$B$BPortami la scaglia elettrificata di Gahz'rilla!$B$BMa l'evocazione di Gahz'rilla è un segreto ben custodito dai troll. Per affrontarlo, prima dovrai strappare loro il segreto.",
  obj = "Porta Gahz'rilla's Electrified Scale a Wizzle Brassbolts, nelle Shimmering Flats.",
  progress = "Hai la scaglia? Non vedo l'ora di provare vari modi per imbrigliarne l'energia!",
  reward = "Caspita, hai preso la scaglia! Grazie, $N. Non vedo l'ora di mettermi al lavoro su questa cosa!$B$BAllora hai visto Gahz'rilla? Era grosso come dicono??",
  en_title = "Gahz'rilla",
  en_obj = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.",
}
T[2841] = {
  title = "La guerra dei rig",
  desc = "La tecnologia gnomica: due anni fa la si usava soprattutto come battuta finale. I tempi sono cambiati, eccome. Adesso hanno costruito un rig nuovo che è meglio di tutti i nostri modelli di sminuzzatrice messi insieme. Mi servono i progetti, $N!$B$BPurtroppo i piani sono chiusi in una cassaforte vicino a Mekgineer Thermaplugg. E per peggiorare le cose, la combinazione della cassaforte la conosce solo Mekgineer Thermaplugg.$B$BFa' quel che devi per avere quella combinazione, $N. Poi apri quella cassaforte e riporta indietro quei progetti!",
  obj = "Recupera i Rig Blueprints e Thermaplugg's Safe Combination da Gnomeregan e portali a Nogg, a Orgrimmar.",
  progress = "Non vedo nessun progetto. Li hai nascosti da qualche parte addosso o te ne stai qui impalato solo per irritarmi?",
  reward = "Sapevo che ce l'avresti fatta, $N! Sovik invece aveva i suoi dubbi.$B$B<Nogg si schiarisce la gola.>$B$BOra che i progetti sono nostri, è solo questione di tempo prima che capiamo tutte le trovate gnomiche finite nella costruzione del rig e le trasformiamo in trovate goblin per i nostri nuovi modelli di sminuzzatrice.",
  en_title = "Rig Wars",
  en_obj = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.$B",
}
T[2842] = {
  title = "Chief Engineer Scooty",
  desc = "Appena abbiamo avuto notizie da Kernobee sul nuovo rig gnomico, io e Scooty ci siamo messi a lavorare al Transpolyporter 6000: il modo più veloce e affidabile per arrivare a Gnomeregan.$B$BFinalmente è pronto a imbarcare passeggeri, $N. Se vuoi provarlo, va' a Booty Bay e parla con Scooty al posatoio dei wind rider. Per arrivare a Booty Bay, prendi la nave da Ratchet.$B$BCerto, potresti sempre provare a farti la corsa fino a Gnomeregan attraverso le montagne di Dun Morogh infestate dai nani!",
  obj = "Parla con Scooty, a Booty Bay.",
  reward = "È una bellezza, vero? L'apice della tecnologia goblin dei trasporti — è esplosa sì e no una dozzina di volte.$B$BNon preoccuparti, $N, l'ho rimessa a posto tutta. Non ti scoppierà addosso — e se succede, sarà rapido e indolore.",
  en_title = "Chief Engineer Scooty",
  en_obj = "Speak with Scooty in Booty Bay.",
}
T[2843] = {
  title = "Gnomer-gooooone!",
  desc = "Finché hai il transponder con te, basta che salga sulla piattaforma e verrai $Gteletrasportato:teletrasportata; a Gnomeregan.$B$BPotresti avvertire qualche effetto collaterale insolito, ma nessuno dovrebbe essere permanente... ormai.$B$BQuasi dimenticavo la parte più importante: tornare indietro. Quando sei $Gpronto:pronta; a rientrare, sali sulla piattaforma del transpolyporter a Gnomeregan!$B$BOra calibriamo il transponder sulla tua taglia e sul tuo peso.",
  obj = "Aspetta che Scooty calibri il Goblin Transponder.",
  progress = "È pronto!",
  reward = "Fatto! Quando sei $Gpronto:pronta;, sali sulla piattaforma.",
  en_title = "Gnomer-gooooone!",
  en_obj = "Wait for Scooty to calibrate the Goblin Transponder.",
}
T[2846] = {
  title = "La Tiara of the Deep",
  desc = "Molto tempo fa possedevo un gioiello bellissimo, la Tiara of the Deep. E non era solo graziosa: racchiudeva un grande potere per chi sapeva usarlo.$B$BQuando la voce della tiara arrivò a Hydromancer Velratha, lei volle averla a tutti i costi. Mandò dei suoi agenti a casa mia, e me la rubarono mentre ero via. Ladri!$B$BRivoglio la mia tiara! Va' a Zul'Farrak, la città troll di Tanaris, trova Velratha e strappale la tiara. Riportamela e ti guadagnerai il mio favore.",
  obj = "Porta la Tiara of the Deep a Tabetha, nel Dustwallow Marsh.",
  progress = "Hai la tiara, $N? Velratha ha imparato quanto costa mettersi contro di me?",
  reward = "Magnifico! L'hai trovata! E cosa altrettanto importante, Velratha non ce l'ha più! Grazie, $N. Ti sarò per sempre debitrice!$B$BE se prima ti sono sembrata un po'... cattiva, non farci caso. Scoprirai che sono una persona molto più gentile con chi non mi ha derubata.",
  en_title = "Tiara of the Deep",
  en_obj = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.",
}
T[2847] = {
  title = "Armatura Wild Leather",
  desc = "$N, come $Gconciatore:conciatrice; stai diventando davvero abile! Conosco alcuni schemi che potrebbero interessarti... l'armatura Wild Leather! Il Wild Leather sfrutta le proprietà potenti e caotiche delle Wildvine, che si trovano nelle zone di vegetazione rigogliosa e addosso ad alcune delle creature che ci vivono. Per chi ha la tua abilità non c'è armatura migliore di quella che se ne ricava, garantito.$B$BTi insegnerò a farla, ma per un po' lavorerai per me. Come primo pagamento mi bastano dieci pezzi di Thick Leather. Dopo, parleremo dei dettagli.",
  obj = "Porta 10 Thick Leather a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Come ti ho detto, lavorerai per me mentre impari a conoscere l'armatura Wild Leather. Dato che le Wildvine sono insieme potenti e caotiche, danno un vantaggio casuale ma forte all'armatura che realizzerai, già robusta di suo. Però non è stato facile per me arrivare a questa conoscenza.$B$BPer avviare il lavoro, il costo iniziale è di dieci pezzi di Thick Leather.$B$BQuando avremo sistemato questo, passeremo al lavoro che dovrai fare per ottenere gli schemi.",
  reward = "Bene, $N, sono contento di averti con me. Come $Gconciatore:conciatrice; hai fatto una scelta intelligente: chi indossa armature di cuoio farà a gara per venire da te, quando avrai imparato a fare uno qualsiasi dei pezzi dell'armatura Wild Leather.$B$BMettiamoci al lavoro — da dove vuoi cominciare?",
  en_title = "Wild Leather Armor",
  en_obj = "Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2848] = {
  title = "Wild Leather Shoulders",
  desc = "I Wild Leather Shoulders sostengono benissimo il fisico di chi li indossa e offrono una protezione di prim'ordine alla parte alta delle braccia e alle spalle stesse. Come per tutta l'armatura Wild Leather, cucendoci dentro la Wildvine il pezzo acquista un vantaggio potente ma casuale.$B$BPer questo schema mi serviranno sei Thick Armor Kit e una Wildvine. Non dovrebbe essere un ordine troppo impegnativo da evadere, per te.",
  obj = "Porta 6 Thick Armor Kit e una Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Hai i sei Thick Armor Kit e la Wildvine che ti ho chiesto?$B$BNon pensare che fare kit per armature sia un lavoro monotono: il metodo di lavorazione regolare che acquisisci esercitando il mestiere su questi kit ti aiuta a sviluppare le capacità necessarie per il lavoro minuzioso che richiede l'armatura Wild Leather.$B$BVedi, c'è un vero motivo dietro a quello che fai per me...",
  reward = "Questi kit per armature sono di buona qualità, $N. Se c'è una cosa che pretendo, non solo dal mio lavoro ma anche da quello di chi lavora per me, è la qualità.$B$BHai lavorato bene per guadagnarti questo schema; spero che ti renda quanto ha reso a me.",
  en_title = "Wild Leather Shoulders",
  en_obj = "Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2849] = {
  title = "Wild Leather Vest",
  desc = "I Wild Leather Vest sono il pezzo base di ogni set di armatura Wild Leather. La struttura del corpetto si fonde con la Wildvine per dare vita a un capo che offre la massima protezione al torso, lasciando che la potente magia si diffonda in tutto l'indumento.$B$BPer questo schema mi serviranno due Turtle Scale Breastplate, due paia di Turtle Scale Gloves e una Wildvine. È un ordine impegnativo, ma non dovresti avere grandi difficoltà a evaderlo per me.",
  obj = "Porta 2 Turtle Scale Breastplate, 2 Turtle Scale Gloves e una Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Hai le due Turtle Scale Breastplate e i Turtle Scale Gloves che ti ho ordinato? E non dimenticare la Wildvine!$B$BGià dai primi schemi impariamo che le basi della forma si applicano bene anche ai capi più difficili. Anche se sono oggetti diversi, la forma delle Turtle Scale Breastplate ti prepara ai dettagli che servono per fare un Wild Leather Vest.$B$BE i guanti... be', quelli servono solo a me. Ricorda che lavori per me!",
  reward = "Sono pezzi davvero belli, $N. Solo per la maestria e la cura con cui sono stati fatti, varrebbero diverse monete d'argento in più rispetto a un pezzo qualunque.$B$BHai evaso il mio ordine, e per questo ti spetta la ricompensa. Ora la conoscenza per fare i Wild Leather Vest è tua!",
  en_title = "Wild Leather Vest",
  en_obj = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2850] = {
  title = "Wild Leather Helmet",
  desc = "Un Wild Leather Helmet offre a chi lo indossa una protezione superiore per i punti vitali della testa, senza rinunciare alla comodità. Come per tutta l'armatura Wild Leather, la Wildvine incorporata nell'elmo dà alla sua struttura un potenziamento forte ma casuale. Chi indossa il cuoio vorrà di sicuro questo pezzo!$B$BPer questo schema mi serviranno due Nightscape Tunic, due Nightscape Headband e una Wildvine. Completa questo ordine e lo schema sarà tuo!",
  obj = "Porta 2 Nightscape Tunic, 2 Nightscape Headband e una Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Ho bisogno che tu mi faccia quelle tuniche e quelle fasce, e mi serve anche quel pezzo di Wildvine, prima di svelarti come si fanno i Wild Leather Helmet.$B$BTra gli avventurieri le protezioni per la testa sono molto ricercate, che si tratti di una fascia di una semplicità disarmante o di un elmo che copre tutto il capo. Le basi per creare un copricapo pregiato restano le stesse, qualunque sia il suo aspetto esteriore.",
  reward = "L'equipaggiamento Nightscape che mi hai portato soddisfa l'ordine alla perfezione, $N. Non mi aspetto niente di meno da $Gun conciatore:una conciatrice; del tuo calibro.$B$BQuesto schema te lo sei davvero $Gguadagnato:guadagnata;. Te lo do volentieri, e spero che tu ne tragga il giusto profitto.",
  en_title = "Wild Leather Helmet",
  en_obj = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2851] = {
  title = "Wild Leather Boots",
  desc = "Ormai hai imparato parecchio, $N, ma c'è ancora altro da imparare. Adesso tocca ai Wild Leather Boots, la pietra angolare di ogni set.$B$BQuesti stivali sono fatti per avvolgere il piede nella comodità e al tempo stesso proteggerlo dai pericoli dell'avventura. Le suole morbide sono una benedizione per chi cerca calzature con cui muoversi in silenzio.$B$BPer questo schema devi evadere un ordine di due Nightscape Pants e due Nightscape Boots. Mi serviranno anche due Wildvine... non una sola. Quando hai tutto, fammelo sapere.",
  obj = "Porta 2 Nightscape Pants, 2 Nightscape Boots e 2 Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "L'ordine dei pantaloni, degli stivali e delle Wildvine va evaso prima che tu abbia lo schema, $N. Hai finito?$B$BFin dal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve stare in perfetto equilibrio tra comodità e funzionalità. Unendole, riusciamo a creare oggetti che permettono a chi li indossa di ignorare una fatica che stroncherebbe chi porta articoli di qualità inferiore.",
  reward = "Ancora una volta hai evaso un ordine complesso con l'abilità di un professionista esperto. Ti sei $Gguadagnato:guadagnata; questo schema, e anche la mia gratitudine.",
  en_title = "Wild Leather Boots",
  en_obj = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2852] = {
  title = "Wild Leather Leggings",
  desc = "Ora che hai le basi, sei $Gpronto:pronta; a padroneggiare lavori più complessi, $N. I Wild Leather Leggings sono tra i pezzi di cuoio più robusti e potenti che esistano. Vita, cosce, polpacci e punti vitali — tutto riceve una protezione enorme. Con in più il potenziamento della Wildvine, gli avventurieri che li possiedono ti ringrazieranno ogni volta che ti vedranno.$B$BPer questo schema devi evadere un ordine di due Turtle Scale Helm, due Turtle Scale Bracers e due Wildvine.",
  obj = "Porta 2 Turtle Scale Helm, 2 Turtle Scale Bracers e 2 Wildvine a Pratt McGrubben, a Feathermoon Stronghold.",
  progress = "Hai pronti i Turtle Scale Bracers e i Turtle Scale Helm? Non dimenticare le due Wildvine che mi servono!$B$BOrmai cominci a renderti conto di quanto potere possa racchiudere l'armatura Wild Leather. Un'armatura che non ha limiti di impiego ha un valore quasi inestimabile per un conciatore. Gli unici limiti stanno nella quantità di materiali per fare gli oggetti — non nella qualità dei prodotti finiti!",
  reward = "Di nuovo hai evaso un ordine senza sbavature. Forse un giorno sarò io a venire da TE in cerca di conoscenza, eh, $N?$B$BEcco lo schema dei gambali, con la mia gratitudine. Fai tesoro di questo sapere, e lascia che i tuoi prodotti finiti attingano alla tua notevole abilità!",
  en_title = "Wild Leather Leggings",
  en_obj = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.",
}
T[2853] = {
  title = "$GMaestro:Maestra; del Wild Leather",
  desc = "Be', $N, sei la diligenza fatta persona. Rimane un solo schema dell'armatura Wild Leather; gli altri li padroneggi già. Non ti farò sgobbare inutilmente per averlo. Te lo sei $Gguadagnato:guadagnata; pienamente, e anche di più... ma non posso dartelo io. È il mio maestro, colui che mi ha iniziato al mestiere, che deve ricompensarti.$B$BPorta questa lettera a Telonis; insegna conciatura a Darnassus. Mostragli la lettera, e lascia che ti riconosca come $Gsuo pari:sua pari;, come faccio io.",
  obj = "Consegna Pratt's Letter a Telonis, il maestro conciatore di Darnassus.",
  progress = "Salve, $R... dal tuo aspetto capisco che sei $Gun conciatore:una conciatrice; come me. Sei $Gvenuto:venuta; ad attingere alla mia abilità, o forse hai altre faccende da sbrigare con me?",
  reward = "Ah, sì, ti manda Pratt. Anche se è un umano, a volte mi ricorda noi elfi della notte. La sua dedizione e il suo talento con il cuoio sono notevoli. Se in questa lettera ti loda così tanto, è un segno di rispetto che riconosco.$B$BSo che ti ha insegnato l'arte del Wild Leather. Permettimi di completare il tuo addestramento con questo schema. Usalo bene; pochi al mondo conoscono i segreti dei Wild Leather Cloak.",
  en_title = "Master of the Wild Leather",
  en_obj = "Give Pratt's Letter to Telonis, the master leatherworker of Darnassus.",
}
T[2854] = {
  title = "Armatura Wild Leather",
  desc = "$N, la tua abilità di $Gconciatore:conciatrice; ti precede. Custodisco un sapere di conciatura che faresti bene ad acquisire... l'armatura Wild Leather! Il Wild Leather sfrutta le proprietà potenti e caotiche delle Wildvine, che si trovano nelle zone di vegetazione rigogliosa e addosso ad alcune delle creature che ci vivono. Per $Gun artigiano:un'artigiana; della tua abilità non c'è armatura migliore di quella che se ne ricava, garantito.$B$BTi insegnerò, ma per un po' lavorerai per me. Come primo pagamento mi bastano dieci pezzi di Thick Leather. Dopo, parleremo dei dettagli.",
  obj = "Porta 10 Thick Leather a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Mettiamo le cose in chiaro: sarai $Gil mio apprendista:la mia apprendista; mentre impari l'arte dell'armatura Wild Leather. Dato che le Wildvine sono insieme potenti e caotiche, danno un vantaggio casuale ma forte all'armatura che realizzerai, già robusta di suo. Però non è stato facile per me acquisire questa conoscenza.$B$BPer avviare il lavoro, il costo iniziale è di dieci pezzi di Thick Leather.$B$BQuando avremo sistemato questo, passeremo al lavoro che dovrai fare per ottenere gli schemi.",
  reward = "Bene, $N, sono lieto di averti come $Gmio apprendista:mia apprendista;. Come $Gconciatore:conciatrice; hai fatto una scelta saggia: chi usa armature di cuoio farà a gara per venire da te, quando avrai imparato a padroneggiare l'arte del Wild Leather.$B$BMettiamoci al lavoro — da dove vuoi cominciare?",
  en_title = "Wild Leather Armor",
  en_obj = "Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache.",
}
T[2855] = {
  title = "Wild Leather Shoulders",
  desc = "I Wild Leather Shoulders sostengono benissimo il fisico di chi li indossa e offrono una protezione superiore alla parte alta delle braccia oltre che alle spalle. Come per tutta l'armatura Wild Leather, cucendoci dentro la Wildvine il pezzo si impregna di un potenziamento casuale ma molto potente.$B$BPer questo schema mi serviranno sei Thick Armor Kit e una Wildvine. Non dovrebbe essere un ordine troppo impegnativo da evadere, per te.",
  obj = "Porta 6 Thick Armor Kit e una Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Hai i sei Thick Armor Kit e la Wildvine che ti ho chiesto?$B$BConsidera la fabbricazione dei kit per armature una lezione di lavoro costante e affidabile: il metodo di lavorazione regolare che acquisisci esercitando il mestiere su questi kit ti aiuta a sviluppare le capacità necessarie per il lavoro minuzioso che richiedono le armature Wild Leather.$B$BOgni lezione ha uno scopo, $N. È importante accoglierle tutte con lo spirito giusto.",
  reward = "Questi kit per armature sono di buona qualità, $N. Se c'è una cosa che pretendo, non solo dal mio lavoro ma anche da quello di chi è sotto la mia guida, è la qualità.$B$BHai lavorato bene per guadagnarti questo schema; spero che ti renda quanto ha reso a me.",
  en_title = "Wild Leather Shoulders",
  en_obj = "Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
}
T[2856] = {
  title = "Wild Leather Vest",
  desc = "I Wild Leather Vest sono il pezzo base di ogni set di armatura Wild Leather. La struttura del corpetto e la Wildvine intrecciata al suo interno danno vita a un capo che offre la massima protezione al torso, lasciando che una potente magia si diffonda in tutto l'indumento.$B$BPer questo schema mi serviranno due Turtle Scale Breastplate, due paia di Turtle Scale Gloves e una Wildvine. Non è una lezione facile, ma di sicuro hai l'abilità per portarla a termine.",
  obj = "Porta 2 Turtle Scale Breastplate, 2 Turtle Scale Gloves e una Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Hai le due Turtle Scale Breastplate e i Turtle Scale Gloves? E non dimenticare la Wildvine!$B$BGià dai primi schemi impariamo che le basi della forma si applicano bene anche ai capi più difficili. Anche se sono oggetti diversi, la forma delle Turtle Scale Breastplate ti prepara ai dettagli che servono per fare un Wild Leather Vest.$B$BMan mano che andrai avanti con le lezioni, le abilità che ti insegno diventeranno arte.",
  reward = "Sono pezzi davvero belli, $N. La maestria e la cura con cui li hai fatti mostrano che hai scelto di dedicarti completamente a questi compiti.$B$BHai soddisfatto le mie richieste, e per questo ti spetta la ricompensa. Ora la conoscenza per fare i Wild Leather Vest è tua!",
  en_title = "Wild Leather Vest",
  en_obj = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
}
T[2857] = {
  title = "Wild Leather Helmet",
  desc = "Un Wild Leather Helmet offre a chi lo indossa una protezione superiore per i punti vitali della testa, senza rinunciare alla comodità. Come per tutta l'armatura Wild Leather, la Wildvine incorporata nell'elmo infonde nella sua struttura una magia potente ma casuale. Chi indossa il cuoio vorrà di sicuro questo pezzo!$B$BPer questo schema mi serviranno due Nightscape Tunic, 2 Nightscape Headband e una Wildvine. Completa questa lezione e lo schema sarà tuo!",
  obj = "Porta 2 Nightscape Tunic, 2 Nightscape Headband e una Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Ho bisogno che tu mi faccia quelle tuniche e quelle fasce, e mi serve anche quel pezzo di Wildvine, prima di svelarti come si fanno i Wild Leather Helmet.$B$BTra gli avventurieri le protezioni per la testa sono molto ricercate, che si tratti di una fascia di una semplicità disarmante o di un elmo che copre tutto il capo. Le basi per creare un copricapo pregiato restano le stesse, qualunque sia il suo aspetto esteriore.",
  reward = "L'equipaggiamento Nightscape che mi hai portato soddisfa alla perfezione le richieste che ti avevo fatto, $N. Non mi aspetto niente di meno da $Gun conciatore:una conciatrice; del tuo calibro.$B$BTi sei $Gguadagnato:guadagnata; l'onore di fabbricare i Wild Leather Helmet. Ti do questo schema volentieri, e spero che tu ne tragga il giusto profitto.",
  en_title = "Wild Leather Helmet",
  en_obj = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",
}
T[2858] = {
  title = "Wild Leather Boots",
  desc = "La tua conoscenza dell'armatura Wild Leather cresce, $N, ma c'è ancora altro da imparare.$B$BI Wild Leather Boots sono la pietra angolare di ogni set. Stivali come questi sono fatti per avvolgere il piede nella comodità e al tempo stesso proteggerlo dai pericoli dell'avventura. Le suole morbide sono una benedizione per chi cerca calzature con cui muoversi in silenzio.$B$BPer questo schema devi fabbricare due Nightscape Pants e due Nightscape Boots. Mi serviranno anche due Wildvine... non una sola. Quando avrai questi oggetti, andremo avanti.",
  obj = "Porta 2 Nightscape Pants, 2 Nightscape Boots e 2 Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "I pantaloni, gli stivali e le Wildvine devono arrivarmi prima che tu impari lo schema, $N. Hai fatto come ti ho chiesto?$B$BFin dal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve stare in perfetto equilibrio tra comodità e funzionalità. Unendole, riusciamo a creare oggetti che permettono a chi li indossa di ignorare una fatica che stroncherebbe chi porta articoli di qualità inferiore.",
  reward = "Ancora una volta hai prodotto oggetti con l'abilità di un professionista esperto. Ti sei $Gguadagnato:guadagnata; questo schema, e anche le mie congratulazioni.",
  en_title = "Wild Leather Boots",
  en_obj = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",
}
T[2859] = {
  title = "Wild Leather Leggings",
  desc = "Sei $Gpronto:pronta; a padroneggiare lezioni più complesse, $N. I Wild Leather Leggings sono tra i pezzi di cuoio più robusti e potenti che esistano. Vita, cosce, polpacci e punti vitali — tutto riceve una protezione enorme. Con in più il potenziamento della Wildvine, gli avventurieri che li possiedono ti ringrazieranno ogni volta che ti vedranno.$B$BPerché tu possa avere questo schema, mi servono due Turtle Scale Helm, due Turtle Scale Bracers e due Wildvine.",
  obj = "Porta 2 Turtle Scale Helm, 2 Turtle Scale Bracers e 2 Wildvine a Jangdor Swiftstrider, a Camp Mojache.",
  progress = "Hai pronti i Turtle Scale Bracers e i Turtle Scale Helm? Non dimenticare le due Wildvine che ti ho chiesto.$B$BOrmai cominci a renderti conto di quanto potere possa racchiudere l'armatura Wild Leather. Un'armatura che non ha limiti di impiego ha un valore quasi inestimabile per un conciatore. Gli unici limiti stanno nella quantità di materiali per fare gli oggetti — non nella qualità dei prodotti finiti!",
  reward = "Di nuovo hai portato a termine il mio compito senza sbavature. Forse un giorno sarò io a venire da TE in cerca di conoscenza, eh, $N?$B$BEcco lo schema dei gambali, con la mia gratitudine. Fai tesoro di questo sapere, e lascia che i tuoi prodotti finiti attingano alla tua notevole abilità!",
  en_title = "Wild Leather Leggings",
  en_obj = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",
}
T[2860] = {
  title = "$GMaestro:Maestra; del Wild Leather",
  desc = "$N, hai imparato tutto quello che sono in grado di insegnarti. Resta però un ultimo schema dell'armatura Wild Leather. Non ti farò sgobbare inutilmente per averlo; te lo sei $Gguadagnato:guadagnata; pienamente, e anche di più. Questo schema, però, non posso condividerlo con te liberamente.$B$BÈ la mia maestra, colei che mi ha iniziato al mestiere, che deve ricompensarti. Porta questo biglietto a Una; insegna conciatura a Thunder Bluff. Mostrale la lettera, e lascia che ti riconosca come $Gsuo pari:sua pari;, come faccio io.",
  obj = "Consegna Jangdor's Letter a Una, la maestra conciatrice di Thunder Bluff.",
  progress = "Salve, $R... dal tuo aspetto capisco che sei $Gun conciatore:una conciatrice; come me. Sei $Gvenuto:venuta; ad attingere alla mia abilità, o forse hai altre faccende da sbrigare con me?",
  reward = "Ah, sì, ti manda Jangdor. Sono lieta di vedere che uno dei miei allievi migliori ora ha $Gun allievo tutto suo:un'allieva tutta sua;.$B$BLa sua dedizione e il suo talento con il cuoio sono notevoli. Se in questa lettera ti loda così tanto, è un segno di rispetto che riconosco.$B$BSo che ti ha insegnato l'arte del Wild Leather. Permettimi di completare il tuo addestramento con questo schema. Usalo bene; pochi al mondo conoscono i segreti dei Wild Leather Cloak.",
  en_title = "Master of the Wild Leather",
  en_obj = "Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff.",
}
T[2861] = {
  title = "Il compito di Tabetha",
  desc = "Si dice che Tabetha, una collega maga che vive nel profondo del Dustwallow Marsh, abbia un conto in sospeso con un certo troll delle sabbie di Zul'Farrak. Se parli con Tabetha, potrà dirti di più.$B$BE porta con te qualche amico, $N. Se Tabetha ti manda a Zul'Farrak, non vorrai andarci da $Gsolo:sola;.$B$BTroverai la casetta di Tabetha a ovest di Theramore, appena a nord della Stonemaul Ruin.",
  obj = "Parla con Tabetha, nel Dustwallow Marsh.",
  reward = "Proprio così. Ho davvero un conto in sospeso con una troll. Anzi, più d'uno. Voglio tutte le sue ossa!$B$BVuoi aiutarmi?",
  en_title = "Tabetha's Task",
  en_obj = "Speak with Tabetha in Dustwallow Marsh.",
}
T[2862] = {
  title = "Guerra ai Woodpaw",
  desc = "Gli gnoll... sono più di un fastidio. Sono una minaccia costante per l'esistenza stessa di questo campo! Poco importa se siano originari di Feralas o no: se non rafforziamo la nostra determinazione contro di loro, ci ritroveremo cacciati dall'intera regione.$B$BUltimamente gli attacchi degli gnoll contro il campo si sono fatti più accaniti. Ci serve il tuo aiuto per sfoltirne il numero; portami dieci delle loro criniere, e ti ricompenserò generosamente per il tuo impegno.$B$BVa'!",
  obj = "Porta 10 Woodpaw Gnoll Mane a Hadoken Swiftstrider, a Camp Mojache.",
  progress = "Li respingiamo, eppure continuano ad attaccare! Qualcuno o qualcosa deve farli impazzire... oh, sei $Gtornato:tornata;, eh, $N? Hai le criniere che mi servono per riscuotere la taglia?",
  reward = "Questa è la prova di un buon inizio, $N. Le tue capacità di $Gsoldato:soldatessa; meritano un elogio.$B$BNon sei $Gl'unico:l'unica; a cui chiedo questo compito. Molti prima di te li hanno combattuti, e in passato i nostri sforzi li hanno tenuti a bada. Di recente, però, i loro tentativi di spingersi a nord, nella nostra zona d'influenza, sono aumentati moltissimo. E anche i loro attacchi sono diventati più feroci... quasi come se fossero disperati.$B$BMa ho un piano, $N, che potrebbe sistemare le cose con loro una volta per tutte...",
  en_title = "War on the Woodpaw",
  en_obj = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.",
}
T[2863] = {
  title = "Attacco agli Alpha",
  desc = "Il piano è abbattere in rapida successione vari capi degli gnoll, gli Alpha, come si fanno chiamare. Se riusciamo a colpirli con una devastazione così rapida e precisa, porteremo il caos nelle loro file. Forse faremo anche entrare nelle loro teste dure e piene di pulci il messaggio che possiamo distruggerli, e che lo faremo!$B$BVoglio che tu sia $Gil messaggero:la messaggera; della mia volontà: elimina cinque dei loro Alpha entro un'ora perché funzioni, $N, altrimenti resteremo in questa situazione di stallo!",
  obj = "Uccidi 5 Woodpaw Alpha e torna da Hadoken Swiftstrider entro un'ora.",
  progress = "Il tempo stringe, $N! Se non sei qui per riferirmi che hai fatto fuori gli Alpha, stai perdendo tempo!",
  reward = "Hai fatto quello che ti ho chiesto, e per questo ti rendo onore. Prendi questa piccola ricompensa come compenso per i tuoi sforzi, $N.$B$BCon il loro numero sfoltito e i loro capi uccisi, gli gnoll ci penseranno due volte prima di assaltare il campo. Ma questo non chiude la questione...$B$BDeve esserci un motivo se gli gnoll sono stati aizzati fino a questo stato di frenesia. Prima che abbiano la possibilità di riorganizzarsi, voglio scoprire cosa lo provoca.",
  en_title = "Alpha Strike",
  en_obj = "Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.",
}
T[2864] = {
  title = "Tran'rek",
  desc = "Mio cugino Tran'rek è in una situazione difficile. Settimane fa mi aveva promesso un carico di gusci di scarabeo e non l'ha ancora consegnato. È mio cugino, quindi non vorrei dover mandare qualcuno a Gadgetzan a rompergli qualcosa addosso.$B$BPuoi parlare con Tran'rek per me? Fagli sapere che deve preparare quella consegna prima che io faccia qualcosa di avventato!$B$BGadgetzan si trova nel nord di Tanaris, in Kalimdor.",
  obj = "Parla con Tran'rek, a Gadgetzan.",
  reward = "Salve!$B$BOh, hai parlato con mio cugino Krazek? Come sta? Spero che Booty Bay lo tratti bene...$B$BGusci di scarabeo, dici? Be'... lascia che ti racconti una storia...",
  en_title = "Tran'rek",
  en_obj = "Speak with Tran'rek in Gadgetzan.",
}
T[2865] = {
  title = "Gusci di scarabeo",
  desc = "Gli scarabei di Tanaris hanno gusci durissimi! Abbastanza duri da usarli come materiale da costruzione per un sacco di cose. Tantissime cose!$B$BAnzi, quei gusci sono così utili... che gli scarabei sono stati cacciati quasi fino all'estinzione!$B$BIo so dove ci sono altri scarabei, e se mi prometti di portarmi i loro gusci, ti dirò dove sono. Promesso?$B$BBene, gli scarabei hanno una colonia a Zul'Farrak. A quanto pare i troll non li cacciano per i gusci.$B$BMa tu sì! Va' a Zul'Farrak e portami dei gusci non incrinati!",
  obj = "Porta 5 Uncracked Scarab Shell a Tran'rek, a Gadgetzan.",
  progress = "Hai i gusci? Mio cugino a Booty Bay aspetta un carico, e si sta spazientendo!",
  reward = "Oh, fantastico! Ce l'hai fatta!$B$BGrazie, $N. Mi hai proprio salvato la vita!",
  en_title = "Scarab Shells",
  en_obj = "Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.",
}
T[2866] = {
  title = "Le Ruins of Solarsal",
  desc = "A sud di qui ci sono le Ruins of Solarsal: una zona che risale a molto prima dei tempi moderni. All'inizio abbiamo esplorato le rovine e non abbiamo trovato niente di notevole; per questo le abbiamo lasciate in pace.$B$BDi recente, però, i naga Hatecrest hanno occupato queste rovine in numero allarmante. All'inizio l'abbiamo considerato il preludio di un attacco. Anche se quella minaccia resta possibile, crediamo che stia succedendo qualcos'altro.$B$BVa' là, esplora le rovine e cerca qualunque cosa ti sembri fuori dal comune. Buona fortuna, $N.",
  obj = "Esplora le Ruins of Solarsal e indaga sulla presenza dei naga.",
  reward = "Esaminando il gazebo scopri alcune cose interessanti e insolite, rispetto alle rovine circostanti.$B$BPrima di tutto, il gazebo è chiaramente una costruzione più recente degli altri elementi delle rovine. Poi, sui suoi lati è incisa una piccola serie di glifi; i glifi seguono uno schema che si ripete, ma per il resto la loro origine e il loro significato sono sconosciuti. Infine, la pietra del gazebo è calda al tatto.$B$BQuesto rientra di sicuro tra le cose \"fuori dal comune\" nella ricerca tra le rovine!",
  en_title = "The Ruins of Solarsal ",
  en_obj = "Explore the Ruins of Solarsal and investigate the presence of the naga there.",
}
T[2867] = {
  title = "Ritorno alla Feathermoon Stronghold",
  desc = "Con la scoperta dello strano gazebo nel cuore delle Ruins of Solarsal, è giunto il momento di tornare alla Feathermoon Stronghold e riferire a General Shandris Feathermoon quello che hai scoperto.",
  obj = "Torna da Shandris Feathermoon, alla Feathermoon Stronghold, e riferisci le tue scoperte.",
  reward = "$GBentornato:Bentornata;, $N. Il tuo rapporto su questo gazebo è molto... inquietante. Sembra che, anche se i naga non stavano progettando un attacco, la loro presenza continua non promette niente di buono per la nostra avanzata in Feralas. Comunque, ecco un compenso per la tua indagine.$B$BSembra che la Feathermoon Stronghold abbia un disperato bisogno di altro aiuto contro i naga Hatecrest. Vorrei affidarti questo compito, se te la senti. C'è molto da fare.",
  en_title = "Return to Feathermoon Stronghold",
  en_obj = "Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.",
}
T[2869] = {
  title = "Contro gli Hatecrest",
  desc = "A questo punto la cosa migliore da fare è dare per scontato che, qualunque cosa stiano tramando, i naga prima o poi cercheranno di prendersi l'isola. Dobbiamo fare passi decisi per contrastare questa minaccia prima che sia troppo tardi.$B$BPortami dieci Hatecrest Naga Scale in buone condizioni; dovrebbe esserti chiaro come procurartele. Farai le tue prime armi contro i naga, e noi avremo una presenza naga più debole a Sardor Isle: due prospettive che vanno entrambe a nostro vantaggio.",
  obj = "Porta 10 Hatecrest Naga Scale a Latronicus Moonspear, alla Feathermoon Stronghold.",
  progress = "$N, se sei qui per il compito che ti è stato affidato, ottimo: cerco dieci scaglie Hatecrest. Se sei qui per fare due chiacchiere, al momento non ho tempo per simili sciocchezze.$B$BSappi questo: noi elfi della notte non siamo guerrafondai. La nostra razza è votata alla conservazione della pace e dell'armonia. Questo però non vuol dire che non proteggeremo in anticipo i nostri interessi. È il mio dovere verso il generale Feathermoon e verso la roccaforte.",
  reward = "Sì, sì, queste scaglie sono più che soddisfacenti. Anzi, credo che le manderò giù a Pratt perché le guardi. Magari riuscirà a ricavarne qualcosa di utile.$B$BQuanto a te, ho un'altra missione per cui voglio mandarti. Ma prima, ecco la tua ricompensa per le scaglie. Il tuo servizio costante per il generale e per tutta la Feathermoon Stronghold è una benedizione nelle avversità.",
  en_title = "Against the Hatecrest",
  en_obj = "Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.",
}
T[2870] = {
  title = "Contro Lord Shalzaru",
  desc = "$N, nuovi rapporti degli esploratori ci hanno dato un'idea chiara della catena di comando dei naga. Tra le loro file c'è anche la nobiltà, ed è lei a dare tutti gli ordini.$B$BIn particolare, abbiamo individuato uno dei nobili più crudeli: Lord Shalzaru. Gli esploratori riferiscono che lui stesso ha portato alla luce una strana reliquia durante un recente scavo dei naga, in una grotta a sud delle rovine principali, oltre l'acqua, sulla Isle of Dread.$B$BMetti fine a tutto questo mettendo fine a lui, e portami la sua reliquia perché possiamo studiarla.",
  obj = "Elimina Lord Shalzaru, poi porta la Mysterious Relic che ha portato alla luce a Latronicus Moonspear, alla Feathermoon Stronghold.",
  progress = "Abbattere Lord Shalzaru farebbe di sicuro arretrare i loro piani di settimane, se non di mesi. Oltretutto, la reliquia che ha portato alla luce ci interessa senza dubbio.$B$BHai portato a termine la missione che ti è stata affidata, $N?",
  reward = "Ben giocata, $N! La morte di Lord Shalzaru getterà i naga nello scompiglio per un po' di tempo, se non per sempre. La minaccia che rappresentano è ora sotto il nostro controllo più di quanto lo sia mai stata, e lo dobbiamo a te.$B$BEcco altro denaro della taglia dalle casse della roccaforte: te lo sei $Gguadagnato:guadagnata; fino all'ultima moneta. Tu e i tuoi siete sempre i benvenuti alla Feathermoon Stronghold, $Gamico mio:amica mia;.$B$BUn'ultima cosa prima che tu vada, $N... se potessi...",
  en_title = "Against Lord Shalzaru",
  en_obj = "Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.",
}
T[2871] = {
  title = "Consegnare la reliquia",
  desc = "Se fossi così gentile da consegnare la reliquia a mia moglie Vestia, te ne sarei grato. Non è solo un'ottima sacerdotessa per la nostra comunità, ma è anche una delle studiose più esperte che troverai ovunque. Io non capirei nulla di questo congegno nemmeno se ci fosse una scommessa in ballo. Mia moglie invece, se c'è qualcuno che può capire cos'è questa cosa, è lei... e dobbiamo saperlo!$B$BÈ appena dietro l'angolo, di sicuro a studiare. Grazie, $N.",
  obj = "Consegna la Mysterious Relic a Vestia Moonspear, alla Feathermoon Stronghold.",
  progress = "Sì, posso esserti utile?$B$BAspetta, sei tu $Gil:la; $C che ha aiutato il generale Feathermoon e Latro con la minaccia dei naga, vero? Sono Vestia, la moglie di Latro... ehm, anzi, di Latronicus. È un piacere conoscerti!$B$BScusa, sei qui per lavoro, naturalmente. Hai qualcosa per me... da parte sua, per caso?",
  reward = "Interessante... dici che viene dalle Ruins of Solarsal? Be', Latro ha ragione: devo esaminarla. A prima vista non sembra originaria delle rovine. D'altra parte, non è di fattura naga... non una cosa così aliena.$B$BCi vorrà un po' di tempo per studiare questo oggetto. Quando avrò finito le mie ricerche, forse sfrutterò il tuo talento, se sarai da queste parti.$B$BTieni, prendi uno di questi oggetti in più che abbiamo; spero che ti sia utile!",
  en_title = "Delivering the Relic",
  en_obj = "Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.",
}
T[2902] = {
  title = "Indagine sui Woodpaw",
  desc = "Gli gnoll non sono esattamente dei geni, ma di sicuro avranno una qualche strategia scritta sulle loro attività recenti. Se trovassimo quei piani, avremmo un'idea più chiara di cosa li agita tanto.$B$BVoglio che tu torni dai Woodpaw e trovi qualunque cosa somigli ai loro piani di battaglia. Devono avere qualcosa: i loro attacchi sono stati troppo coordinati per essere fatti senza. Trovali, e torna da me quando li avrai.",
  obj = "Trova i piani di battaglia degli gnoll da qualche parte negli accampamenti degli gnoll a sud di Camp Mojache.",
  reward = "Esaminando la mappa scopri che si tratta dei piani di battaglia che vuole Hadoken Swiftstrider. Sulla mappa sono disegnate numerose frecce che forse rappresentano movimenti di truppe, anche se quasi tutte sembrano dirette verso sud, e non verso nord, dove si trova Camp Mojache.$B$BUn'altra parte della mappa mostra il disegno di quello che credi sia un grosso insetto di qualche tipo, con sotto varie tacche. A giudicare dagli gnoll, forse rappresentano le loro perdite contro questi insetti sconosciuti...",
  en_title = "Woodpaw Investigation",
  en_obj = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.",
}
T[2903] = {
  title = "I piani di battaglia",
  desc = "Ora che hai scoperto i piani di battaglia degli gnoll, non resta che riportarli a Hadoken Swiftstrider, a Camp Mojache. Forse lui, o qualcun altro lì, riuscirà a capire meglio cosa stanno tramando gli gnoll.",
  obj = "Porta i Woodpaw Battle Plans a Hadoken Swiftstrider, a Camp Mojache.",
  progress = "$GBentornato:Bentornata;, $N. Sei $Griuscito:riuscita; a trovare qualche prova concreta dei piani degli gnoll?",
  reward = "Ah, è proprio quello che ci serviva. Anche se non sono molto abile a decifrare la maggior parte degli scarabocchi di questa mappa, ai miei tempi ho visto abbastanza piani di battaglia da capire cosa sta succedendo con gli gnoll. Sembra che al momento stiano combattendo una guerra su due fronti. Uno è contro di noi... ma pare che le loro energie principali siano rivolte contro un nemico a sud.$B$BQui c'è più di quanto sembri. Forse è il momento di capire chi sia davvero quest'altro nemico che stanno affrontando.",
  en_title = "The Battle Plans",
  en_obj = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.",
}
T[2904] = {
  title = "Un bel guaio",
  desc = "<Kernobee geme.> Cos... Cos'è successo?$B$BL'ultima cosa che ricordo è che un gruppo di nani Dark Iron mi ha catturato, mi ha pestato a un passo dalla morte e poi mi ha buttato qui dentro con questi trogg immondi.$B$BPortami fuori di qui, $N!$B$BEcco il piano: portami all'uscita; se ne usciamo vivi, tu vai a Booty Bay e fai sapere a Scooty che sono andato a Ratchet ad avvertire Tinkerwiz che i Dark Iron hanno messo mano alla costruzione di quel super rig.$B$BMuoviamoci!",
  obj = "Scorta Kernobee fino all'uscita della Clockwerk Run, poi riferisci a Scooty, a Booty Bay.",
  progress = "Eh? Kernobee è vivo??",
  reward = "Immagino che tu meriti una ricompensa per averci riportato Kernobee tutto intero, $N. Se torni a Gnomeregan, questi potrebbero darti il vantaggio che ti serve per sconfiggere quel buono a nulla di un traditore, Mekgineer Thermaplugg.",
  en_title = "A Fine Mess",
  en_obj = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.",
}
T[2922] = {
  title = "Salva il cervello di Techbot!",
  desc = "Quando la nostra amata città di Gnomeregan è caduta, una scintilla impazzita deve aver scosso la mia povera creatura, Techbot. Un tempo aiutava me e i miei soci con i suoi innumerevoli aggeggi e il suo sterminato archivio di informazioni, ma il suo cervello positronico si è polarizzato. Adesso è negatronico... e i comportamenti di Techbot sono invertiti. Si aggira per Gnomeregan in preda alla frenesia!$B$BMa forse si può recuperare. Forse, se riesci a recuperare il Memory Core di Techbot e a portarmelo, posso scoprire la causa della polarizzazione e riparare il mio povero Techbot.",
  obj = "Porta Techbot's Memory Core a Tinkmaster Overspark, a Ironforge.",
  progress = "L'hai trovato Techbot? L'hai recuperato il suo Memory Core??",
  reward = "Oh, è meraviglioso! Grazie, $N! Mi metto subito al lavoro!!$B$BPovero, povero Techbot... Non prendertela. Ti rimettiamo a posto noi.$B$BOra, dove ho messo lo spinotto della mia chiave idro-snodata...",
  en_title = "Save Techbot's Brain!",
  en_obj = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.",
}
T[2923] = {
  title = "Tinkmaster Overspark",
  desc = "Tinkmaster Overspark è molto turbato per la sorte della sua creatura meccanica, Techbot. Io ricordo Techbot come uno strumento gentile e utile per gli gnomi, ma Overspark mi dice che si è guastato.$B$BMolto triste. Ma con un po' di fortuna forse lo si può riparare!$B$BParla con Tinkmaster Overspark, a Tinker Town, a Ironforge. Sarà contento del tuo aiuto.",
  obj = "Parla con Tinkmaster Overspark, a Ironforge.",
  reward = "Sì, è vero. Techbot è impazzito! Ti prego, puoi aiutarmi?",
  en_title = "Tinkmaster Overspark",
  en_obj = "Speak with Tinkmaster Overspark in Ironforge.",
}
T[2924] = {
  title = "Essential Artificials",
  desc = "Un componente meccanico quasi universale — l'Essential Artificial — era molto utile ai meccanici e ai fabbri di Gnomeregan. Ma durante l'esodo frenetico dalla nostra città nessuno si è ricordato di portarne via nemmeno uno! E a me ne serve una grande scorta per un lavoro che comincerò presto.$B$BTi prego, entra a Gnomeregan e portamene un po'. Li troverai nelle zone più profonde della nostra città, dentro contenitori chiamati artificial extrapolator.$B$BGrazie, $N, e fa' in fretta, ti prego!",
  obj = "Porta 12 Essential Artificial a Klockmort Spannerspan, a Ironforge.",
  progress = "Ce li hai gli Essential Artificial?",
  reward = "Li hai presi! Ora posso cominciare i miei nuovi esperimenti!$B$BNon so come ringraziarti, $N! Il tuo coraggio ha fatto fare alla ricerca gnomica un balzo in avanti!",
  en_title = "Essential Artificials",
  en_obj = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.",
}
T[2925] = {
  title = "Gli essenziali di Klockmort",
  desc = "Un amico gnomo, Klockmort Spannerspan, mi ha mandato un messaggio da Ironforge. Mi dice che gli serve aiuto per una missione pericolosa, ma essenziale, dentro Gnomeregan, la città gnomica un tempo grande e ora contaminata e piena di gnomi impazziti e dei loro congegni.$B$BIo devo restare qui, ma il cuore mi si stringe dalla voglia di aiutare il mio amico. Se puoi andare al mio posto, ti sarò molto in debito.$B$BKlockmort lo trovi a Tinkertown, a Ironforge.",
  obj = "Parla con Klockmort Spannerspan, a Ironforge.",
  reward = "Sì! Sì che mi serve aiuto per una missione dentro Gnomeregan. E tu sei proprio $Gil:la; $C che ci vuole!",
  en_title = "Klockmort's Essentials",
  en_obj = "Speak with Klockmort Spannerspan in Ironforge.",
}
T[2926] = {
  title = "Gnogaine",
  desc = "Dall'incidente in poi, Gnoarn non pensa e non parla d'altro che ripulire Gnomeregan dall'infestazione dei trogg e trovare una cura per il male che l'affligge, $N.$B$BPer fortuna io e Razzle siamo vicini a una specie di cura — o quello, o la ricetta di un rum davvero potente. Non lo sapremo finché non proviamo! Naturalmente, per provare la nostra teoria ci serviranno alcune cose: in particolare, la ricaduta radioattiva dei trogg irradiati di Gnomeregan. Riempi questa fiala con il bagliore verde e riportamela!",
  obj = "Usa l'Empty Leaden Collection Phial sugli Irradiated Invader o sugli Irradiated Pillager per raccogliere la ricaduta radioattiva. Quando è piena, riportala a Ozzie Togglevolt, a Kharanos.",
  progress = "Non vedi che qui stiamo cercando di curare un'intera specie di gnomi??! Ci serve altro bagliore verde!",
  reward = "Ottimo lavoro! È arrivato il momento di provare la nuova formula. Se funziona, non solo quel Leper Gnome catturato sarà guarito, ma io dovrei ritrovarmi con una bella chioma folta! Indietro!",
  en_title = "Gnogaine",
  en_obj = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.",
}
T[2927] = {
  title = "Il giorno dopo",
  desc = "Non penserai mica che sia sempre stato calvo, vero? No di certo, $Gsignore:signora;! È stata la fuga di radiazioni a Gnomeregan a causare questa tragica perdita di capelli. Prima di quel giorno avevo l'unico gnomefro di tutta Azeroth.$B$B<Gnoarn agita il pugno in aria.>$B$BMaledetti quei maledetti sporchi trogg — maledetti tutti!!$B$BForse non è troppo tardi, $N. Forse possiamo ancora salvarla — la città, intendo! Parla con Ozzie Togglevolt, a Kharanos. Lui e il suo socio Razzle stanno lavorando a una soluzione.",
  obj = "Parla con Ozzie Togglevolt, a Kharanos.",
  reward = "Pensavo che perdere quella chioma straordinaria sarebbe stata la sua fine, e invece è sopravvissuto!$B$BEro proprio accanto a lui quando l'ha colpito la scarica di radiazioni. Quelle deliziose ciocche castane sono cadute a terra a ciuffi! A grappoli! E l'orrore è diventato ancora più grande quando Gnoarn è andato completamente fuori di testa! Oh sì, fuori di testa, dico! Gnoarn si è toccato la testa pelata incredulo, e lo sguardo nei suoi occhi urlava vendetta, $N! Poi ha rivolto la sua rabbia contro i trogg!$B$B<Ozzie rabbrividisce.>",
  en_title = "The Day After",
  en_obj = "Speak with Ozzie Togglevolt in Kharanos.",
}
T[2928] = {
  title = "Gyrodrillmatic Excavationators",
  desc = "È terribile, $N. Non avremo abbastanza pezzi per portare la nostra flotta di gyrodrillmatic excavationator fino a Dun Morogh.$B$BQuel che ci serve sono pezzi di ricambio, $N. E quale posto migliore di Gnomeregan per procurarsi i ricambi dei nostri veicoli? Mi dicono che là dentro bot e mech girano come mandrie al pascolo.$B$BQuel che devi fare è andare a Gnomeregan e fare a pezzi quei robot. Riportami le loro interiora meccaniche. Due dozzine dovrebbero bastare.",
  obj = "Porta ventiquattro Robo-mechanical Gut a Shoni, a Stormwind.",
  progress = "Se fosse una gara, a quest'ora avresti perso.",
  reward = "Questi andranno benissimo, $N. Un gyrodrillmatic excavationator riparato; ne restano 398.",
  en_title = "Gyrodrillmatic Excavationators",
  en_obj = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.",
}
T[2929] = {
  title = "Il grande tradimento",
  desc = "Mi fidavo di Thermaplugg, $R. Non avrei mai immaginato che avrebbe tradito me e l'intero popolo gnomico. E per cosa? Potere? Ricchezza? Tutte cose che col tempo avrebbe avuto. Ora siamo stati cacciati da casa nostra e quel pazzo comanda. Il re del nulla....$B$BRiprenderemo Gnomeregan, $N. Non ci fermeremo finché la città non tornerà sotto il nostro controllo. Se vuoi unirti alla nostra lotta, ti chiedo un compito semplice: uccidi il traditore. Distruggi Mekgineer Thermaplugg.",
  obj = "Va' a Gnomeregan e uccidi Mekgineer Thermaplugg. Torna da High Tinker Mekkatorque a lavoro finito.",
  progress = "Il compito è finito? Ha implorato clemenza? Pietà??",
  reward = "Mi piace pensare che l'ultima cosa che gli è passata per la testa mentre crollava a terra sia stato il tuo piede, $R. Con Thermaplugg morto, i nostri piani per riprendere Gnomeregan sono un passo più vicini a diventare realtà.",
  en_title = "The Grand Betrayal",
  en_obj = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.",
}
T[2930] = {
  title = "Recupero dati",
  desc = "Quando siamo fuggiti da Gnomeregan ci siamo lasciati dietro tantissimi dati! Dati di importanza vitale!$B$BMi servono i dati su una Prismatic Punch Card, da un terminale ad alta sicurezza Matrix Punchograph 3005-D, in fondo a Gnomeregan. Devi accedere a quel terminale, ma per farlo ti serve prima l'autorizzazione... e per averla devi accedere ai terminali a sicurezza più bassa: i modelli -A, -B e -C. E per fare QUELLO ti servono le punch card di sicurezza, a cominciare da quella bianca... e le punch card le abbiamo lasciate tutte in città.$B$BÈ una catastrofe! Puoi aiutarci?",
  obj = "Porta una Prismatic Punch Card a Master Mechanic Castpipe, a Ironforge.",
  progress = "Ce l'hai la Prismatic Punch Card??",
  reward = "Ce l'hai fatta! Hai trovato la Prismatic Punch Card e recuperato i dati perduti! Dati di importanza vitale, critica, incommensurabile, senza i quali non saremmo potuti andare avanti un altro istante!$B$BIl servizio che hai reso agli gnomi sarà ricordato a lungo, $N.",
  en_title = "Data Rescue",
  en_obj = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.",
}
T[2931] = {
  title = "L'incarico di Castpipe",
  desc = "Master Mechanic Castpipe, a Ironforge, ha bisogno di avventurieri! Sta organizzando squadre per rientrare a Gnomeregan in una missione di recupero dati della massima segretezza e importanza.$B$BCastpipe non sarà un membro dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences come me, ma resta uno gnomo in gamba: quindi, se lui pensa che sia importante, per i miei calcoli c'è una probabilità dell'ottantaquattro per cento che lo sia davvero!$B$BSono buone probabilità!",
  obj = "Parla con Master Mechanic Castpipe, a Ironforge.",
  reward = "Sto organizzando missioni di estrazione dati dentro Gnomeregan. Se sei qui per questo, ascolta bene!",
  en_title = "Castpipe's Task",
  en_obj = "Speak with Master Mechanic Castpipe in Ironforge.",
}
T[2936] = {
  title = "La dea ragno",
  desc = "I Witherbark adorano una dea ragno, e da lei raccolgono il loro veleno più potente. Quindi, se vuoi il veleno, devi evocare la loro dea!$B$BPer farlo devi conoscere il suo vero nome, e quel nome è su una tavoletta sepolta a Tanaris, nella città troll di Zul'Farrak, in una tomba sorvegliata da Theka the Martyr.$B$BSconfiggi Theka, trova la sua tavoletta e leggila per scoprire il nome della dea ragno. Quando lo conoscerai, torna da me.",
  obj = "Leggi la Tablet of Theka per scoprire il nome della dea ragno dei Witherbark, poi torna da Master Gadrin.",
  progress = "Conosci il nome della dea ragno?",
  reward = "Ah, Elortha no Shadra... pronuncia questo nome solo a bassa voce, perché nei regni dello spirito ha un gran peso.$B$BLo metterò per iscritto e creerò per te un incantesimo di evocazione...",
  en_title = "The Spider God",
  en_obj = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.",
}
T[2945] = {
  title = "Grime-Encrusted Ring",
  desc = "Dal cadavere di uno dei nani Dark Iron hai tirato fuori quello che sembra un anello. È difficile però dire che tipo di anello sia: terra e residui induriti lo ricoprono del tutto e rendono impossibile indossarlo. Ti pare di intravedere il lieve luccichio di un metallo prezioso e forse perfino il bagliore di una gemma sotto i residui.$B$BSe vuoi servirti di questo anello, dovrai trovare qualcosa che gli tolga di dosso i residui induriti.",
  obj = "Trova un modo per togliere la sporcizia dal Grime-Encrusted Ring.",
  progress = "L'aggeggio gnomico davanti a te porta una targa che lo chiama \"The Sparklematic 5200\". Dalle istruzioni sotto la targa si capisce che la macchina serve a strofinare via lo sporco che un oggetto può avere. Ha una fessura per le monete, e accetta tre monete d'argento per avviare il processo una volta che l'oggetto è dentro.$B$BPare proprio che il Grime-Encrusted Ring che hai trovato prima sia la cosa giusta da provare in questa macchina!",
  reward = "Metti l'anello dentro lo Sparklematic 5200 e infili una moneta d'argento nella fessura.$B$BDalla macchina escono stridori dolorosi mentre comincia a sobbalzare violentemente. Si può solo immaginare cosa stia succedendo all'anello là dentro...$B$BLa macchina si ferma di colpo e annuncia la fine con un semplice \"Ding!\". Il ricettacolo si apre e rivela una scatoletta avvolta con cura in un nastro rosso. Pare che lo Sparklematic 5200 faccia anche i pacchetti regalo!",
  en_title = "Grime-Encrusted Ring",
  en_obj = "Figure out a way to remove the grime from the Grime-Encrusted Ring.",
}
T[2947] = {
  title = "Il ritorno dell'anello",
  desc = "Aprendo la scatola prodotta dallo Sparklematic 5200 trovi quel che sospettavi: un anello lucente! Indossandolo, senti un potere magico scorrerti nel corpo.$B$BDentro il cerchio c'è un'impronta piccola ma riconoscibile del sigillo di Ironforge. Accanto sono incise tre piccole iniziali: \"TdK\". Potrebbero essere le iniziali del precedente proprietario, oppure quelle di chi ha forgiato l'anello. Tenere l'anello... o restituirlo a questa persona. Che dilemma...",
  obj = "Puoi tenere l'anello, oppure cercare la persona a cui si devono l'impronta e le incisioni all'interno del cerchio.",
  progress = "Ehi, calma, socio: sono un uomo d'affari molto importante! Sono sicuro che il corriere è solo in ritardo con la consegna dell'affitto... aspetta... tu non sei $Gil mio padrone:la mia padrona; di casa.$B$BMa certo che no, che sciocco! Sei $Gvenuto:venuta; da me perché cerchi il miglior gioielliere di tutta Ironforge, uno che NON fa oggetti MALEDETTI! Sì!$B$BEhm... di cosa hai bisogno?",
  reward = "Un anello, dici? Vediamo... sì, perbacco, quell'anello l'ho fatto io.$B$BPrima che Gnomeregan saltasse avevo una botteguccia là. Forse è uno di quelli che mi sono lasciato dietro quando sono scappato a gambe levate: è un disegno semplice, e ne ho fatti parecchi così. Magari era di qualcuno che non ce l'ha fatta a uscire.$B$BCe l'avevano dei nani Dark Iron? Be', questo aggiunge uno strato di cospirazione ai nove che già girano. Forse le autorità vorrebbero saperlo; con uno come me è fiato sprecato.$B$BOra, torniamo all'anello...",
  en_title = "Return of the Ring",
  en_obj = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.",
}
T[2948] = {
  title = "Miglioria gnomesca",
  desc = "Senti, $N, quell'anello è tuo, certo... ma te ne posso fare uno migliore! Quel disegno, come ti ho detto, è davvero semplice. Ora sono molto più bravo, e per la modica cifra di trenta monete d'argento te lo rimetto a nuovo! Be', un pochino più di trenta, a dire il vero...$B$BAl momento sono in difficoltà: le mie scorte di materiale sono esaurite. Se mi porti una barra d'argento e un'agata muschiata, aggiungo all'anello un reticolo d'argento e agata che gli darà un po' più di brio!$B$BFidati!",
  obj = "Porta il Brilliant Gold Ring, un Silver Bar, un Moss Agate e 30 monete d'argento a Talvash del Kissel, a Ironforge.",
  progress = "Ce li hai i materiali che mi servono? Non te li chiederei, se non fossi in un periodo sfortunato...",
  reward = "Ah, proprio quel che mi serviva! Un giorno, quando sarò uscito da questo buco in cui mi trovo ingiustamente, farò per te, anzi, per TUTTI, i ninnoli più belli di tutta Azeroth! Fino ad allora, grazie della comprensione per i reagenti. Di solito per un anello di questa qualità chiedo dieci volte tanto...$B$BA proposito di anelli, ecco quello nuovo!",
  en_title = "Gnome Improvement",
  en_obj = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.",
}
T[2949] = {
  title = "Il ritorno dell'anello",
  desc = "Aprendo la scatola prodotta dallo Sparklematic 5200 trovi un anello lucente! Indossandolo, senti un potere magico scorrerti nel corpo.$B$BDentro il cerchio c'è un'impronta piccola ma riconoscibile del sigillo di Orgrimmar. Accanto ci sono delle lettere incise, ma anche dopo la pulizia se ne distinguono solo le prime tre: \"NOG...\"$B$BPotrebbero essere le iniziali del precedente proprietario, oppure quelle di chi ha forgiato l'anello. Tenere l'anello... o trovare \"NOG\": che dilemma...",
  obj = "Puoi tenere l'anello, oppure cercare la persona a cui si devono l'impronta e le incisioni all'interno del cerchio.",
  progress = "Uno penserebbe che un modo per battere quegli sporchi gnomettini ce lo trovassimo da soli. Anzi, scommetterei che quel rig ce l'hanno rubato loro, tanto per cominciare! Bah, quegli unti, lerci... ehm, sì? Ti serve qualcosa?",
  reward = "Un anello da Gnomeregan? Vediamo... non è mio, ma è interessante.$B$BLa faccenda di Gnomeregan: non poteva capitare a un gruppo di teste di legno più simpatico. Per anni sono stati una barzelletta, e adesso, quasi da un giorno all'altro, costruiscono rig migliori dei nostri?$B$BCe l'avevano dei nani Dark Iron, l'anello? Questo è ancora più interessante! Sai, magari gli gnomi hanno rubato i loro progetti folli dei golem e li hanno modificati. E quei Dark Iron vorrebbero di sicuro una bella vendetta. Vale di sicuro la pena indagare.$B$BA proposito, quell'anello...",
  en_title = "Return of the Ring",
  en_obj = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.",
}
T[2950] = {
  title = "L'anello rifatto da Nogg",
  desc = "No, no, no: non sto dicendo che all'improvviso l'anello è mio. Di solito non lo faccio, ma le tue informazioni sui Dark Iron sono state molto utili. Te lo miglioro io l'anello, meglio di come avrebbe mai potuto fare chi ha fatto questa cosetta semplice. Probabilmente qualche gnomo...$B$BSe mi porti una barra d'argento, un'agata muschiata e trenta monete d'argento per il disturbo, aggiungo all'anello un reticolo d'argento e agata che rafforzerà la magia che ha dentro. Ti interessa?",
  obj = "Porta il Brilliant Gold Ring, un Silver Bar, un Moss Agate e 30 monete d'argento a Nogg, a Orgrimmar.",
  progress = "Ce li hai i materiali che mi servono? Senza tutto quel che ti ho chiesto non posso migliorare questo lavoro.",
  reward = "Ecco il tuo anello, meglio di prima. Grazie ancora per le informazioni su quei nani Dark Iron. Sembra una buona pista per capire come mai quegli gnomi si siano ritrovati di colpo con un'ispirazione da goblin.",
  en_title = "Nogg's Ring Redo",
  en_obj = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.",
}
T[2951] = {
  title = "The Sparklematic 5200!",
  desc = "Questo aggeggio spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice \"The Sparklematic 5200\", e sotto c'è scritto:$B$B\"Sporcizia e residui rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendi-fantastico! Inserisci l'oggetto da pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 qualche istante di lavoro e voilà! I tuoi oggetti di valore usciranno puliti e splendenti!\"",
  obj = "Inserisci un Grime-Encrusted Item nello Sparklematic 5200, e assicurati di avere tre monete d'argento per far partire la macchina.",
  progress = "Pare che al congegno serva una specie di oggetto incrostato di sporcizia da pulire e tre monete d'argento per mettersi in moto. Se ci sono tutti e due, lo Sparklematic 5200 dovrebbe funzionare...",
  reward = "Inserisci l'oggetto incrostato e tre monete d'argento nello Sparklematic 5200. La macchina si anima in un tentativo frenetico di ripulire dalla sporcizia l'oggetto sconosciuto. Dal cuore della macchina battono rumori forti e violenti di ingranaggi che girano. Il telaio metallico della bestia scricchiola e geme mentre sobbalza da un lato all'altro...",
  en_title = "The Sparklematic 5200!",
  en_obj = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
}
T[2952] = {
  title = "The Sparklematic 5200!",
  reward = "Com'è cominciato, così lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\", e la bocca della macchina si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta avvolta in un nastrino. Pare che la macchina incarti l'oggetto dopo avergli tolto le incrostazioni. Anche se la macchina non avesse funzionato, almeno adesso l'oggetto è avvolto in una bella scatola.$B$BBe', c'è un modo solo per scoprire se l'ha pulito o no...",
  en_title = "The Sparklematic 5200!",
}
T[2953] = {
  title = "Ancora un giro di Sparklematic",
  progress = "Lo Sparklematic 5200 è vuoto, in attesa di un oggetto incrostato da pulire e di tre monete d'argento per partire!",
  reward = "Lo Sparklematic 5200 si anima, sobbalzando avanti e indietro. Dentro, la sporcizia indifesa che incrostava l'oggetto viene polverizzata dal detergente gnomico della macchina.$B$BLo Sparklematic 5200 si ferma, annunciato da un familiare \"ding!\". Il ricettacolo della macchina si apre a spirale e rivela una scatola avvolta con cura.",
  en_title = "More Sparklematic Action",
}
T[2962] = {
  title = "L'unica cura è altro bagliore verde",
  desc = "Il tuo campione non solo era insufficiente per quantità: era anche impuro.$B$BQuel che ci serve è altro bagliore verde. È chiaro che i trogg non sono irradiati abbastanza per i nostri scopi. Dovrai entrare a Gnomeregan e riportare della ricaduta radioattiva, presa direttamente alla fonte. Parlo degli slime, dei lurker e degli horror irradiati. Attenzione: contenere questo tipo di ricaduta è difficile. Potresti dover fare diversi tentativi con la fiala prima di recuperare un campione adatto.",
  obj = "Va' a Gnomeregan e riporta un High Potency Radioactive Fallout. Attenzione: la ricaduta è instabile e decade piuttosto in fretta.$B$BA lavoro finito Ozzie vorrà anche la tua Heavy Leaden Collection Phial.",
  progress = "Hrm, non stai brillando. È un buon segno.",
  reward = "<Ozzie ti esamina.> Notevole, hai ancora tutti gli arti al loro posto. Ora vediamo cosa sa fare questa roba!",
  en_title = "The Only Cure is More Green Glow",
  en_obj = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.$B$BOzzie will also require your Heavy Leaden Collection Phial when the task is complete.$B",
}
T[2965] = {
  title = "Presagi di Uldum",
  desc = "Ah, $N, è una fortuna che tu sia $Gvenuto:venuta; di nuovo da me. Le tue scoperte agli scavi di Uldaman hanno di certo dato a noi saggi molto di cui discutere. Ne stavo parlando proprio con una dei druidi, Nara Wildmane, quando mi è venuto in mente che le sue passate esperienze di avventuriera potrebbero avere grande importanza per il prossimo passo da compiere.$B$BVorrei che tu parlassi con lei dei suoi viaggi nella Valley of the Watchers, nel deserto di Tanaris. Ti aspetta sull'Elder Rise.",
  obj = "Parla con Nara Wildmane, sull'Elder Rise di Thunder Bluff.",
  reward = "Nel cuore del deserto di Tanaris c'è un luogo chiamato Valley of the Watchers. I dischi che hai recuperato... i loro glifi tradotti parlano di un luogo chiamato Uldum. Quasi tutti pensano che sia un mito.$B$BIo so che non è così; Uldum esiste. Ci sono stata. Be'... fuori, almeno.$B$BIl punto è questo, $N: pensiamo che ci sia un legame tra i dischi e Uldum, e vogliamo che tu ci vada.",
  en_title = "Portents of Uldum",
  en_obj = "Speak with Nara Wildmane on the Elder Rise in Thunder Bluff.",
}
T[2966] = {
  title = "Vedere cosa succede",
  desc = "Sage Truthseeker e io vorremmo che portassi i dischi in miniatura che hai trovato alle porte sigillate di Uldum. Non... non siamo sicuri di cosa succederà quando lo farai.$B$BSembra rischioso, certo, lo riconosciamo. Ma potrebbe anche non succedere niente. Forse dovrai usare i dischi su qualcosa. Forse le porte si aprono quando hai i dischi con te. Sii $Gdisposto:disposta; a provare qualsiasi cosa, e $Gpronto:pronta; a qualsiasi evenienza.$B$BScopri quello che puoi, poi torna da me. Avremo molto di cui parlare.",
  obj = "Porta i Miniature Platinum Discs alle porte di Uldum, a Tanaris, e cerca indizi sul legame tra le due cose.",
  progress = "Questo piedistallo dall'aspetto familiare spunta dalla sabbia rovente. Forse la sua presenza qui ha un significato...",
  reward = "Quando tocchi il piedistallo, i dischi in miniatura di Uldaman vibrano e brillano nel tuo zaino. Un formicolio familiare ti attraversa le mani, mentre l'immagine di un altro Stone Watcher prende vita davanti alle porte di Uldum.$B$B\"Saluti. Sono un guardiano dell'ingresso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Plates of Uldum. Si prega di integrare queste piastre nella struttura dei dischi e di ripetere la sequenza di accesso. Grazie.\"",
  en_title = "Seeing What Happens",
  en_obj = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.",
}
T[2967] = {
  title = "Ritorno a Thunder Bluff",
  desc = "Accedi di nuovo al piedistallo; i dischi di platino ricompaiono all'improvviso nel tuo zaino.$B$BOra che hai appreso ciò che sa il guardiano di pietra e i dischi sono tornati in tuo possesso, è giunto il momento di tornare a Thunder Bluff e informare Nara Wildmane della tua scoperta.",
  obj = "Parla con Nara Wildmane, a Thunder Bluff.",
  progress = "$GBentornato:Bentornata;, $N. Sei $Griuscito:riuscita; a usare i dischi a tuo vantaggio, o è stato tutto inutile?",
  reward = "Ti mancavano dei dischi? È interessante: sembra che i Discs of Norgannon siano solo una parte del set completo — come le chiavi di un mazzo, per così dire.$B$BSe riusciamo a trovare le Plates of Uldum, potremmo davvero accedere al complesso di Uldum. Non so se esserne entusiasta o terrorizzata.$B$BPotremmo dover rischiare tutto per fare in modo che i segreti custoditi dalla terra, che ci distruggerebbero tutti, restino proprio questo — segreti.",
  en_title = "Return to Thunder Bluff",
  en_obj = "Speak with Nara Wildmane in Thunder Bluff.",
}
T[2968] = {
  title = "Un compito futuro",
  desc = "Be', $N... sembra che siamo arrivati a un punto morto, purtroppo. Sappiamo cosa ci serve — le Plates of Uldum — ma non abbiamo idea di dove possano essere. Faremo delle ricerche, e poi elaboreremo un solido piano d'attacco. Ho un paio di idee su dove cominciare a cercare; spero proprio che presto ti chiederemo di unirti di nuovo ai nostri sforzi per scoprire la verità.$B$BSage Truthseeker deve esserne informato, $N; di certo vorrà anche ringraziarti di persona per aver risposto ancora una volta alla chiamata.",
  obj = "Parla con Sage Truthseeker, a Thunder Bluff.",
  reward = "Siamo tutti d'accordo, allora — la cosa migliore è aspettare finché non riusciremo a restringere le zone in cui potrebbero essere nascoste queste piastre. Ci hai portati fin qui, $N, e spero che sarai tu a tornare sul campo per affrontare i segreti di Uldum.$B$BNel frattempo permettimi di darti questo compenso; dovrebbe coprire le spese che hai sostenuto per aiutarci, più un piccolo extra. Torna presto a trovarci... Uldum chiama tutti noi, giovane.",
  en_title = "A Future Task",
  en_obj = "Speak with Sage Truthseeker in Thunder Bluff.",
}
T[2973] = {
  title = "Una nuova lucentezza per il mantello",
  desc = "$GBen trovato:Ben trovata;, $C. Sono venuto in Feralas con i miei compagni, per una missione per i nostri superiori di Orgrimmar.$B$BLa mia compagna di vita, Korrin, adora i vestiti nuovi, quindi voglio farle un nuovo mantello adornato con le ali diafane dei draghi fatati. Potresti aiutarmi? Gli Sprite Darter con le splendide ali che voglio si trovano a ovest di Camp Mojache.",
  obj = "Porta 10 Iridescent Sprite Darter Wing a Krueg Skullsplitter, a Camp Mojache.",
  progress = "Gli Sprite Darter possono essere bestiole pericolose, se provocati. Sta' $Gattento:attenta; quando hai a che fare con loro, $C. E fa' ancora più attenzione agli elfi della notte della zona. Quegli sciocchi fastidiosi tendono a rintanarsi anche loro nelle foreste.$B$BQuando avrai abbastanza ali, fammelo sapere: ti ricompenserò bene, puoi starne certo!",
  reward = "Magnifico, $C! Queste andranno benissimo. Ce n'è abbastanza per fare un mantello per Korrin, e forse anche di più! Grazie.$B$BSpero che il viaggio non sia stato troppo pericoloso? La zona di Feralas non è nota per essere clemente, ma è chiaro che te la sei $Gcavato:cavata; bene.$B$BGrazie ancora, $C.",
  en_title = "A New Cloak's Sheen",
  en_obj = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.",
}
T[2974] = {
  title = "Una scoperta cupa",
  desc = "Cosa?! Hai incontrato dei tauren da queste parti? Stai scherzando! Che aspetto avevano?!$B$BIl clan Grimtotem! Ne hai trovati alcuni? Belgrom, uno dei nostri superiori, ha un interesse per quelli come loro... ha perfino messo una taglia su di loro.$B$BDevi tornarci, $C. Torna e portami le loro corna... a mucchi, se puoi. I Grimtotem non vanno presi alla leggera né sottovalutati. Torna e uccidili; che i fiumi di Feralas scorrano rossi del loro sangue oscuro.",
  obj = "Porta 20 Grimtotem Horn a Krueg Skullsplitter, a Camp Mojache.",
  progress = "Prendi sul serio le mie parole, $C: il clan Grimtotem è malvagio. Se hai scoperto dove si trovano, tocca a te tornare e sferrare il primo colpo contro il loro clan... prima che possano venire nelle nostre terre e radere al suolo i nostri villaggi, o saccheggiare le nostre terre.",
  reward = "Sono buone corna, $C. Ben fatto. Le prendo io, e mi assicurerò di dirlo a Belgrom appena torneremo a Orgrimmar. Mi hai aiutato due volte, ormai, e per questo hai il mio riconoscimento. Forse in futuro potrò aiutarti io! Buona fortuna.",
  en_title = "A Grim Discovery",
  en_obj = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.",
}
T[2975] = {
  title = "Gli ogre di Feralas",
  desc = "Gli effetti della tribù dei Gordunni Ogre non possono passare inosservati da queste parti. Guardati intorno, $N: la loro sola presenza sfregia questa terra. Dobbiamo respingerli prima che si espandano ancora di più in Feralas.$B$BSegui il fiume verso nord e troverai il loro avamposto. Riduci il loro numero, $N. Dobbiamo mostrare loro che qui la loro specie non è gradita.",
  obj = "Rok Orhan, a Camp Mojache, vuole che tu uccida 10 Gordunni Ogre, 10 Gordunni Ogre Mage e 5 Gordunni Brute.",
  progress = "Muoviti in fretta, $N. O il compito che ti ho chiesto è troppo difficile?",
  reward = "Eccellente, $N. Col tempo, la terra guarirà. Non dobbiamo arrenderci.",
  en_title = "The Ogres of Feralas",
  en_obj = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes.",
}
T[2976] = {
  title = "Una scoperta cupa",
  desc = "Cosa?!$B$BAh, allora ho parlato di una taglia, vero? Be', così imparo ad aprire bocca, no?$B$BIl lavoro l'hai fatto tu, quindi immagino sia giusto che tu ne raccolga la ricompensa più grande. Prendi le corna: le farò mettere in una cassa per te. Trova Belgrom Rockmaul nella Valley of Honor: vorrà sapere cosa hai visto, e ti ricompenserà per il tuo duro lavoro.$B$BStammi bene, $C, e grazie ancora per tutto quello che hai fatto.",
  obj = "Porta la Crate of Grimtotem Horns a Belgrom Rockmaul, a Orgrimmar.",
  progress = "Fa' presto, $C, oggi ho molto da fare.",
  reward = "I Grimtotem!? Interessante. Dici di averli incontrati mentre cacciavi in Feralas? Davvero?$B$BI miei pari vorranno sentire le tue notizie, $C. Raccontami di più, e intanto ti conto le monete.$B$BE prima che tu vada, sappi che ti ringrazio per le informazioni che mi hai dato oggi.",
  en_title = "A Grim Discovery",
  en_obj = "Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar.",
}
T[2978] = {
  title = "La Gordunni Scroll",
  desc = "Raccogliendo la pergamena sudicia, noti che sembra raffigurare una specie di incontro o di cerimonia. A Rok Orhan interesserebbe questa pergamena, e cosa potrebbe significare per i Gordunni.",
  obj = "Porta la Gordunni Scroll a Rok Orhan, a Camp Mojache.",
  progress = "Cos'è questo?",
  reward = "Questa pergamena... L'hai trovata nel Gordunni Outpost?",
  en_title = "The Gordunni Scroll",
  en_obj = "Bring the Gordunni Scroll to Rok Orhan in Camp Mojache.",
}
T[2980] = {
  title = "Gli ogre di Feralas",
  desc = "Ora che hai dimostrato di essere $Gun vero combattente:una vera combattente;, confido che tu abbia il coraggio di continuare con il compito da svolgere.$B$BVa' nella High Wilderness, a sud-ovest di qui. Lì ci sono alcune strutture abbandonate e distrutte, su terre che un tempo appartenevano agli elfi della notte. Cerca queste rovine, e quando vedrai gli alberi avvizziti e il terreno profanato, troverai i Gordunni. Respingili.$B$BQuesti ogre sono molto più forti di quelli che hai affrontato prima, $N. Sta' $Gattento:attenta;.",
  obj = "Rok Orhan, a Camp Mojache, vuole che tu uccida 10 Gordunni Shaman, 10 Gordunni Warlock e 5 Gordunni Mauler.",
  progress = "Hai trovato le rovine, $N?",
  reward = "Hai dimostrato di essere $Gun alleato fidato e affidabile:un'alleata fidata e affidabile;, $N.",
  en_title = "The Ogres of Feralas",
  en_obj = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers.",
}
T[2982] = {
  title = "La High Wilderness",
  desc = "Anche se è pericoloso, io e Troyas stiamo esplorando le rovine che coprono le foreste di Feralas.$B$BUltimamente, però, Troyas va da solo nella High Wilderness, e sono davvero in pensiero per lui. I Gordunni Ogre hanno preso possesso di quella zona, e non vedono di buon occhio chiunque entri nel loro territorio.$B$BSperavo che fossi $Gdisposto:disposta; a raggiungere le rovine a sud-est e a sgombrare un po' di ogre. Rendi quel posto un po' più sicuro per il mio Troyas, e te ne sarò estremamente grata.",
  obj = "Angelas Moonbreeze vuole che tu uccida 8 Gordunni Warlock, 8 Gordunni Shaman e 8 Gordunni Brute.",
  progress = "Fa' attenzione con i Gordunni, $N. La loro magia sembra devastare la terra stessa su cui si trovano.",
  reward = "Ti sono molto grata per aver fatto questo per me.$B$BOra, ti prego, non dire una parola a Troyas di tutto questo...",
  en_title = "The High Wilderness",
  en_obj = "Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes.",
}
T[2983] = {
  title = "Il richiamo del fuoco",
  desc = "È passato un po' di tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora sei $Gstato:stata; paziente nei tuoi studi, ma è ora che tu conosca poteri più grandi... è ora che tu conosca il vero potere. L'elemento del fuoco è tuo, se sei $Gdisposto:disposta; a pagarne il prezzo.$B$BCerca Kranal Fiss nelle Barrens. Vive in una piccola dimora a nord del Crossroads, ma fai attenzione: se arrivi a quelle maledette terre degli elfi della notte, sei $Gandato:andata; fin troppo lontano.",
  obj = "Trova Kranal Fiss, nelle Barrens.",
  reward = "Hmmm, ti ha mandato Swart, vero?$B$BBe', di Swart ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.$B$BLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[2984] = {
  title = "Il richiamo del fuoco",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la distruzione... e il caos. Comprendere l'elemento del fuoco è alla tua portata, se sei $Gdisposto:disposta; a pagarne il prezzo.$B$BCerca Kranal Fiss nelle Barrens. Vive in una piccola dimora a nord del Crossroads, ma fai attenzione: se arrivi alle terre degli elfi della notte, sei $Gandato:andata; troppo lontano.",
  obj = "Trova Kranal Fiss, nelle Barrens.",
  reward = "Hmmm, ti ha mandato Narm, vero?$B$BBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei $Gpronto:pronta; a prendere la prossima sapta — la sapta del fuoco.$B$BLo vedo già nei tuoi occhi: l'ardore, il desiderio. Hai assaggiato il potere, e ora sei $Gpronto:pronta; per averne di più. Pazienza, $N. Ricorda ciò che ti ha insegnato la terra. Il potere e la distruzione verranno facilmente, ma devi comunque sapere quando trattenere la mano.",
  en_title = "Call of Fire",
  en_obj = "Find Kranal Fiss in the Barrens.",
}
T[2985] = {
  title = "Il richiamo dell'acqua",
  desc = "Mi sembri $Gpronto:pronta; per la tua prossima prova, $N. Sei $Gstato:stata; paziente nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.$B$BCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Southfury River e di Ratchet. La troverai lì, alla sua capanna da pesca. Buona fortuna, $N.",
  obj = "Trova Islen Waterseer, nelle Barrens.",
  reward = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.$B$BLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[2986] = {
  title = "Il richiamo dell'acqua",
  desc = "È passato molto tempo dall'ultima volta che sei $Gstato messo:stata messa; alla prova, $N. Finora hai dimostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.$B$BCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Southfury River e di Ratchet. La troverai lì, alla sua capanna da pesca. Buona fortuna, $N.",
  obj = "Trova Islen Waterseer, nelle Barrens.",
  reward = "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già riscaldato dal fuoco — direi che è ora che tu conosca la purezza dell'acqua.$B$BLa tua strada ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più avanti. Ma il primo passo spetta a te.",
  en_title = "Call of Water",
  en_obj = "Find Islen Waterseer in the Barrens.",
}
T[2987] = {
  title = "Gordunni Cobalt",
  desc = "Sono appena arrivato qui in Feralas, e ho sentito che i Gordunni Ogre che abitano queste terre selvagge hanno dei minerali interessanti. Chissà cosa combinano, ma di sicuro sono molto gelosi di quella roba! Non la lasciano in giro, no: la seppelliscono, per impedire a gente come me di metterci le mani sopra.$B$BSe ti va, ti darò la mia pala. Va' al Gordunni Outpost, a nord di qui, e dissotterrami un po' di Gordunni Cobalt. Cerca il bagliore blu, poi comincia a scavare!",
  obj = "Orwin Gizzmick, a Camp Mojache, vuole 12 campioni di Gordunni Cobalt.",
  progress = "Vai lassù e comincia a scavare!$B$BHo posti dove andare e gente da vedere: il tempo è denaro!",
  reward = "Perfetto! Li porterò con me nei miei viaggi, $N. Sono sicuro di poter trovare qualcuno che pagherà un bel po' per questo cobalto.$B$BTieni, prendi questo per il disturbo.",
  en_title = "Gordunni Cobalt",
  en_obj = "Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.",
}
T[2991] = {
  title = "Nekrum's Medallion",
  desc = "Scoprirò dov'è il tuo grifone, ma prima devi fare qualcosa per me. A Zul'Farrak c'è un troll, Nekrum Gutchewer, che possiede un medaglione che vorrei tanto studiare. Portami quel medaglione e userò i miei poteri per trovare Sharpbeak.$B$BZul'Farrak è oltre l'oceano, a ovest, nel deserto di Tanaris.",
  obj = "Porta Nekrum's Medallion a Thadius Grimshade, nelle Blasted Lands.",
  progress = "Hai Nekrum's Medallion, $N? Dentro ci sono poteri nascosti che sono ansioso di scoprire.",
  reward = "Ah, il medaglione di Nekrum. Si dice che abbia dato al troll una vita innaturalmente lunga, ma a caro prezzo. Spero di scoprire un modo per sfruttare il potere del medaglione evitando i suoi... sgradevoli effetti collaterali.$B$BMi hai reso un servizio, $N. Ora manterrò la mia parte del patto.",
  en_title = "Nekrum's Medallion",
  en_obj = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.",
}
T[2996] = {
  title = "In cerca di Strahad",
  desc = "Ti ho insegnato delle abilità in passato, ma è giunto il momento che sia un altro a istruirti. Si trova a Ratchet, e il suo nome è Strahad. È umano, ma non lasciarti ingannare e non pensare che sia debole. È potente, anche se può sembrare piccolo. Può insegnarti evocazioni più potenti: credo che tu sia $Gpronto:pronta;. Va' da lui ora. Si trova a Ratchet... sopra la città portuale, vicino alla sua torre.",
  obj = "Parla con Strahad Farsan, a Ratchet.",
  reward = "Una giornata piena di movimento a Ratchet, vero? Quanto mi piace osservare la fatica di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.$B$BÈ odio quello che vedo nei tuoi occhi, $N? Bene, lo metteremo a buon frutto.",
  en_title = "Seeking Strahad",
  en_obj = "Speak to Strahad Farsan in Ratchet.",
}
T[2997] = {
  title = "Tome of Divinity",
  desc = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire fino a Ironforge per parlare con una delle figure più rispettate della nostra gente: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su ciò che ci si aspetta da te.$B$BLa trovi al piano di sopra, nell'Hall of Mysteries. Se non ci sei mai $Gstato:stata;, è nel Mystic Ward. Buona fortuna, $N.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "$GBen trovato:Ben trovata;, $N. Spero che la Luce ti mostri la vera via e ti protegga dal male.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[2998] = {
  title = "Tome of Divinity",
  desc = "Salve, $Gfratello:sorella;. Duthorian Rall, uno dei nostri paladini più influenti, parlava di te di recente. L'ho sentito dire che era ora di metterti un po' alla prova... insieme a parecchi complimenti su quanto bene te la sei cavata finora.$B$BSe fossi in te, andrei a Stormwind a parlargli quando hai tempo. Di sicuro è nella Cathedral of Light — è lì che passa la maggior parte del tempo.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "È bello qui a Stormwind, non trovi?$B$BIn realtà non avresti potuto scegliere un momento migliore, $N.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Duthorian Rall in Stormwind.",
}
T[2999] = {
  title = "Tome of Divinity",
  desc = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire al piano di sopra e parlare con una delle figure più rispettate della nostra gente: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su ciò che ci si aspetta da te.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "$GBen trovato:Ben trovata;, $N. Spero che la Luce ti mostri la vera via e ti protegga dal male.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge",
}
T[3000] = {
  title = "Tome of Divinity",
  desc = "Salve, $N. So che sei $Gimpegnato:impegnata; ad aiutare la gente di Azeroth, ma quando hai tempo dovresti tornare a Ironforge e parlare con una dei paladini più rispettati della tua terra: Tiza Battleforge. È da lei che vanno i giovani paladini nani quando è il momento di imparare di più sulla Luce e su ciò che ci si aspetta da tutti noi.$B$BLa trovi al piano di sopra, nell'Hall of Mysteries, che si trova nel Mystic Ward.",
  obj = "Parla con Tiza Battleforge, a Ironforge.",
  reward = "Ti saluto, e ti do il benvenuto, $N.",
  en_title = "Tome of Divinity",
  en_obj = "Speak to Tiza Battleforge in Ironforge.",
}
T[3001] = {
  title = "In cerca di Strahad",
  desc = "Ti ho insegnato delle abilità in passato, ma è giunto il momento che sia un altro a istruirti. Si trova a Ratchet, e il suo nome è Strahad. È umano, ma non lasciarti ingannare e non pensare che sia debole, né che sia tuo nemico... almeno per ora. È potente e va rispettato. Può insegnarti evocazioni più grandi, evocazioni per cui credo tu sia $Gpronto:pronta;. Va' da lui ora.$B$BLo trovi a Ratchet... sopra la città portuale, vicino alla torre.",
  obj = "Trova Strahad Farsan, a Ratchet.",
  reward = "Una giornata piena di movimento a Ratchet, vero? Quanto mi piace osservare la fatica di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.$B$BÈ odio quello che vedo nei tuoi occhi, $N? Bene, lo metteremo a buon frutto.",
  en_title = "Seeking Strahad",
  en_obj = "Find Strahad Farsan in Ratchet.",
}
T[3042] = {
  title = "Troll Temper",
  desc = "I troll Sandfury di Zul'Farrak ricavano un agente di tempra dalle arenarie, e io posso usarlo per temprare le cose che fabbrico, eccome se posso! È molto apprezzato dagli intenditori, quindi se mi porti una buona scorta di tempra, ti ricompenserò bene.$B$BZul'Farrak è a nord-ovest di Gadgetzan. Buona fortuna.",
  obj = "Porta 20 Troll Temper a Trenton Lighthammer, a Gadgetzan.",
  progress = "Mi hai portato la tempra, $N?",
  reward = "Ah, questa sì che è un'ottima tempra! E quanta! Ci lavorerò per giorni prima di finirla tutta!$B$BGrazie, $N. Ti prego, prendi questo come pagamento.",
  en_title = "Troll Temper",
  en_obj = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.",
}
T[3065] = {
  title = "Simple Tablet",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Frang, l'istruttore di guerrieri. Vuole parlarti quando sei $Gpronto:pronta;. Lo trovi fuori dal Den, al riparo all'ombra.",
  obj = "Leggi la Simple Tablet e parla con Frang, nella Valley of Trials.",
  progress = "$GUn altro:Un'altra; $R a rinforzare le file. Per me va bene.$B$BProbabilmente farai fatica a sollevare una buona arma come un'ascia, ma una lancia vale quanto qualsiasi altra cosa.$B$B$GBenvenuto:Benvenuta; nella Valley of Trials.",
  reward = "Vedrai che questo posto è adatto a te, mentre continui ad addestrarti nelle vie $Gdel:della; $C. Se hai domande, chiedi pure a chiunque qui intorno, e quando ti senti $Gpronto:pronta;, torna da me per l'addestramento. Ne so quanto qualsiasi $C qui nella Valley e posso trasmetterti quello che so... per un compenso.",
  en_title = "Simple Tablet",
  en_obj = "Read the Simple Tablet and speak to Frang in the Valley of Trials.",
}
T[3082] = {
  title = "Etched Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Jen'shan, l'istruttrice di cacciatori. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Parla con Jen'shan, nella Valley of Trials.",
  progress = "Jen'shan vede davanti a sé $Gun potente cacciatore:una potente cacciatrice;, e gli spiriti approvano.$B$BLa via del cacciatore è uno dei nostri modi di vivere più antichi. Quelli dell'Orda si sono rivolti a noi quando lottavano soltanto per sopravvivere su Azeroth, e ci hanno chiesto di insegnare loro, di mostrare loro i segreti di molte cose. Erano già forti: forti nelle vie degli sciamani; forti nelle vie dei guerrieri. Ma la via del cacciatore non era la loro via... allora.",
  reward = "Ora noi insegniamo loro quelle cose, e loro ne insegnano altre a noi. Diventiamo una sola razza... quasi. Siamo alleati da tanto tempo ormai. Perciò ricordati di aiutarli. E Jen'shan si ricorda di aiutare te.$B$BJen'shan ti insegna le vie del cacciatore — te le insegna bene. Non dimenticarlo mai: i cacciatori sono molto rispettati dalla tribù. Avrai un ruolo importante da svolgere nel futuro... non dimenticarlo mai.$B$BQuando ne senti il bisogno, vieni da Jen'shan. Lei ti insegna tutto quello che può, quando sente che sei $Gpronto:pronta;.",
  en_title = "Etched Tablet",
  en_obj = "Speak to Jen'shan in the Valley of Trials.",
}
T[3083] = {
  title = "Encrypted Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Rwag, l'istruttore di ladri. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi l'Encrypted Tablet e parla con Rwag, nella Valley of Trials.",
  progress = "$GBenvenuto:Benvenuta; nella Valley of Trials, $N. Non saresti qui se non avessi ricevuto la mia tavoletta, quindi vengo al punto.$B$BSono Rwag, e mi occupo di addestrare i ladri, i furfanti e i tagliaborse qui nella Valley. Sono io quello a cui si rivolgerà la Hand se non sarai $Gpronto:pronta; per ciò che ti aspetta. Ma non preoccuparti: la Hand non controllerà tutto quello che fai, anche se, qualora avessero bisogno dei tuoi talenti, sarebbe saggio collaborare con loro.",
  reward = "Fino ad allora, sarai sotto la mia tutela. Ti insegnerò i trucchi del mestiere, come dice qualcuno. Quando ti senti $Gpronto:pronta;, vieni da me e vedrò di addestrarti ancora. Nel frattempo, esercita le tue abilità e tienile affilate come un rasoio. Non si sa mai quando potrà servirti anche l'abilità più insignificante.",
  en_title = "Encrypted Tablet",
  en_obj = "Read the Encrypted Tablet and speak to Rwag in the Valley of Trials.",
}
T[3084] = {
  title = "Rune-Inscribed Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Shikrik, l'istruttrice di sciamani. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Parla con Shikrik, nella Valley of Trials.",
  progress = "Ah, $Gbenvenuto:benvenuta;, $N. Sono lieta che tu sia $Garrivato:arrivata;. Con tutti questi allievi da istruire le mie giornate sono diventate lunghe e anche molto impegnate, ma l'arrivo di qualcuno come te mi dà un grande senso di soddisfazione — ricordo i giorni in cui ero io l'allieva di uno sciamano del tuo popolo.",
  reward = "Come probabilmente sai, gli elementi ci danno il nostro potere. Fuoco, terra, acqua e aria — sono i nostri strumenti.$B$BLa nostra forza viene dagli spiriti dei nostri antenati. Siamo le guide del nostro popolo. Come Thrall lo è per l'Orda, così saremo noi per i villaggi e le cittadine che visitiamo. Si rivolgeranno a noi per avere saggezza e protezione. Per essere più $Gpreparato:preparata;, devi allenarti spesso. Quando senti di aver acquisito più potere, vieni da me e ti insegnerò quello che posso.",
  en_title = "Rune-Inscribed Tablet",
  en_obj = "Speak to Shikrik in the Valley of Trials.",
}
T[3085] = {
  title = "Hallowed Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Ken'jai, l'istruttore di sacerdoti. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi l'Hallowed Tablet e parla con Ken'jai, fuori dal Den, nella Valley of Trials.",
  progress = "Allora ce l'hai fatta... bene, bene! Gli spiriti mi avevano detto che saresti $Gvenuto:venuta; presto da Ken'jai. Lascia che sia uno dei primi a darti il benvenuto nella Valley of Trials. Questo posto non sarà casa tua per molto, ma finché lo è, perché non ne approfitti al meglio?",
  reward = "Mettendoti alla prova, scoprirai di avere un controllo sempre migliore sugli spiriti — li chiamerai per cose sempre più grandi... ed è lì che entra in gioco il vecchio Ken'jai. Vieni a parlare con il vecchio Ken'jai quando ti senti $Gpronto:pronta;. Se gli spiriti sono d'accordo, allora vedremo di insegnarti abilità più potenti... ma solo se gli spiriti sono d'accordo.$B$BOra va', parla con il resto della gente della Valley. Torna a parlarmi più tardi.",
  en_title = "Hallowed Tablet",
  en_obj = "Read the Hallowed Tablet and speak to Ken'jai outside the Den in the Valley of Trials.",
}
T[3086] = {
  title = "Glyphic Tablet",
  desc = "Ah, mentre eri via è arrivata una tavoletta per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Mai'ah, l'istruttrice di maghi. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi la Glyphic Tablet e parla con Mai'ah, vicino all'ingresso del Den, nella Valley of Trials.",
  progress = "Hai già l'aria di voler fare contenta Mai'ah, $N. Questo è bene. Tu porti rispetto a Mai'ah, e forse Mai'ah ricambia il rispetto. Ma basta con questo: sei qui per imparare la magia, non per sentire Mai'ah chiacchierare.$B$BC'è una sola cosa sulla magia che Mai'ah non può insegnarti, $N, ed è come fermare la corruzione.",
  reward = "Sei tra gli esseri più potenti del pianeta, $N... su questo non si discute. E lo sanno tutti... e pure bene!$B$BMa devi stare in guardia! Perché non devi avere paura degli orchi, degli elfi o dei nani... ma delle cose che non puoi vedere. La magia è potente. Ti fa fare cose che forse non vuoi fare. Ti fa credere di essere più potente di quanto sei davvero. Sii paziente. Usa la testa.$B$BQuando pensi di essere $Gpronto:pronta; per l'addestramento, torna da Mai'ah. Lei ti insegna quello che sei $Gpronto:pronta; a imparare, nessun problema.",
  en_title = "Glyphic Tablet",
  en_obj = "Read the Glyphic Tablet and speak with Mai'ah near the entrance to the Den in the Valley of Trials.",
}
T[3087] = {
  title = "Etched Parchment",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Jen'shan, l'istruttrice di cacciatori. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi l'Etched Parchment e parla con Jen'shan, nella Valley of Trials.",
  progress = "Ah, allora sei $Garrivato:arrivata;, finalmente. Bene. Jen'shan ti stava aspettando.$B$BIn molti pensano che sia una via facile, ma Jen'shan ti dice che non è vero. Padroneggiare le bestie di Durotar e oltre richiede tanta abilità quanta ne serve per padroneggiare le arti arcane o per parlare con i nostri antenati.$B$BTirare con l'arco o con il fucile forse non è pericoloso per te quanto lanciare un incantesimo, ma di sicuro è altrettanto pericoloso per il tuo nemico.",
  reward = "Quando avremo finito di parlare, dovresti rivolgerti al resto degli abitanti della Valley. Ti chiedono di fare delle cose per loro... cose che metteranno alla prova la tua abilità e ti insegneranno alcuni dei pericoli di questa terra.$B$BMan mano che crescerai in esperienza e saggezza, avrai bisogno che Jen'shan ti mostri tecniche e abilità migliori. Torna spesso da Jen'shan. Ti farò sapere cosa posso insegnarti.",
  en_title = "Etched Parchment",
  en_obj = "Read the Etched Parchment and speak to Jen'shan in the Valley of Trials.",
}
T[3088] = {
  title = "Encrypted Parchment",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Rwag, l'istruttore di ladri. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi l'Encrypted Parchment e parla con Rwag, nella Valley of Trials.",
  progress = "Shhh, non così forte. Di Nartok, laggiù, non mi fido. Chi deve nascondersi in una caverna più in fondo di me non è uno con cui scherzare.$B$BImmagino che tu non abbia avuto problemi a trovare la strada?",
  reward = "Ora che sai dove mi sono rintanato, devo dirti una cosa: la Shattered Hand mi ha chiesto di tenerti d'occhio. Vogliono che sia io ad addestrarti e a tenerti al corrente di tutto ciò di cui potrebbero aver bisogno. Anche se per ora non ti interessa aiutarli — e saresti $Gpazzo:pazza; a non volerlo — farò quello che posso per addestrarti... in cambio di un piccolo compenso. Torna da me ogni volta che pensi di essere $Gpronto:pronta;, e vedremo cosa sei $Gpronto:pronta; a imparare.",
  en_title = "Encrypted Parchment",
  en_obj = "Read the Encrypted Parchment and speak to Rwag in the Valley of Trials.",
}
T[3089] = {
  title = "Rune-Inscribed Parchment",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BLeggila quando hai tempo. Se non sbaglio, viene da Shikrik, l'istruttrice di sciamani. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi la Rune-Inscribed Parchment e parla con Shikrik, nella Valley of Trials.",
  progress = "Allora sei $Garrivato:arrivata;. Cominciavo a chiedermi quando ti saresti $Gfatto vivo:fatta viva;. Ho mandato la pergamena un po' di tempo fa — non ero sicura che fosse arrivata.$B$BMa basta chiacchiere... sei qui perché sei $Gstato scelto:stata scelta;, $Gscelto:scelta; per guidare la vita spirituale del nostro popolo.",
  reward = "Sarai il tramite attraverso cui parlano i nostri antenati. Avrai il potere degli elementi ai tuoi ordini. Fare a pezzi i tuoi nemici sarà un gioco da ragazzi; curare i tuoi alleati sarà facile come respirare. Tieni a mente queste cose quando affronterai nuove sfide, e torna da me tutte le volte che vuoi. Resterò qui per insegnarti nuovi incantesimi e per metterti sulla strada giusta, quando sarai $Gpronto:pronta;.",
  en_title = "Rune-Inscribed Parchment",
  en_obj = "Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials.",
}
T[3090] = {
  title = "Tainted Parchment",
  desc = "Ah, mentre eri via è arrivata una pergamena per te, $N.$B$BDi solito, se posso, evito di avere a che fare con gli stregoni, ma credo che dovresti leggerla quando hai tempo. Se non sbaglio, viene da Nartok, il tuo nuovo istruttore. Vuole parlarti quando sei $Gpronto:pronta;.",
  obj = "Leggi la Tainted Parchment e parla con Nartok, dentro il Den, nella Valley of Trials.",
  progress = "Finalmente sei $Garrivato:arrivata;... e con discrezione, per giunta. Bene.$B$BIl nostro mondo è pieno di sciocchi, $N. Perfino il potente Thrall ha difetti più grandi di quanto molti riescano a vedere. Volta le spalle al potere che servirebbe per rendere questa terra completamente nostra! Non siamo più lo stesso popolo che fu manipolato e usato dalle creature del Nether. Siamo un popolo a sé. Siamo fieri... e siamo forti.",
  reward = "E ora anche tu sei $Gentrato:entrata; nelle nostre file. Non fraintendermi, $N. Solo perché hai accesso a un potere che molti ti invidieranno, non significa che sarai $Gaccettato:accettata; facilmente. Thrall permette alla nostra gente di stare a Orgrimmar perché siamo ancora suoi consanguinei: non può voltarci le spalle, altrimenti diventeremmo patetici come gli umani che lo resero schiavo. Il punto è: sta' $Gattento:attenta;. Puoi essere potente, ma se sei $Gsciocco:sciocca;, sei come morto.$B$BSe hai bisogno di imparare incantesimi, torna da me.",
  en_title = "Tainted Parchment",
  en_obj = "Read the Tainted Parchment and speak to Nartok inside the Den in the Valley of Trials.",
}
T[3091] = {
  title = "Simple Note",
  desc = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Harutt, l'istruttore di guerrieri. Se il biglietto è di Harutt, al posto tuo non aspetterei a leggerlo.",
  obj = "Leggi la Simple Note e parla con Harutt Thunderhorn, a Camp Narache.",
  progress = "Ah, finalmente sei $Garrivato:arrivata;, $C. Nel mio biglietto non ho mentito, $N. Anche noi siamo una stirpe speciale, come i druidi o gli sciamani della nostra tribù. Tu sei altrettanto importante. Siamo noi quelli chiamati a difendere i nostri confini, a cacciare i centauri e ad andare in guerra.",
  reward = "Ognuno di noi ha un ruolo nella nostra tribù. E ognuno di noi deve anche passare per gli stessi riti. Non lasciare mai che il tuo orgoglio ti dica il contrario.$B$BIo resto qui per addestrare i nuovi guerrieri che cercano la gloria della battaglia e seguono le vie dei nostri antenati più antichi. Quando ti senti $Gpronto:pronta;, torna da me e farò il possibile per addestrarti ancora. Va' con la benedizione della tribù, $N.",
  en_title = "Simple Note",
  en_obj = "Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache.",
}
T[3092] = {
  title = "Etched Note",
  desc = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Lanka, l'istruttore di cacciatori. Se questo biglietto viene da Lanka, non aspetterei troppo a leggerne il contenuto.",
  obj = "Leggi l'Etched Note e parla con Lanka Farshot, sulla Red Cloud Mesa.",
  progress = "$GBenvenuto:Benvenuta; a Camp Narache, $N. Sento dire cose buone su di te. La tua stirpe è forte, e molti degli anziani ti ritengono già abile. Ma questo lo metteremo alla prova.$B$BLe pianure di Mulgore saranno la tua casa per un po' di tempo — dovresti fare del tuo meglio per conoscerle molto bene. Un giorno viaggerai verso terre sconosciute per padroneggiare abilità più grandi. Devi essere $Gpronto:pronta;.",
  reward = "Ed è mio compito assicurarmi che tu sia $Gpreparato:preparata;, insegnandoti le basi della nostra professione — come addomesticare il tuo animale, come sparare con il fucile, e molte altre abilità che diventeranno necessarie.$B$BI cacciatori sono una parte importante della nostra tradizione e della nostra storia, $N. Faresti bene a ricordare quanto sei importante per la tribù. Sarai $Grispettato:rispettata; e $Gvenerato:venerata; se servirai bene il nostro popolo.",
  en_title = "Etched Note",
  en_obj = "Read the Etched Note and speak to Lanka Farshot in Red Cloud Mesa.",
}
T[3093] = {
  title = "Rune-Inscribed Note",
  desc = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Meela, l'istruttrice di sciamani. Se questo biglietto viene da Meela, non aspetterei troppo a leggerne il contenuto.",
  obj = "Leggi il Rune-Inscribed Note e parla con Meela Dawnstrider, a Camp Narache.",
  progress = "Veloce come l'acqua che cade dal cielo, eccoti davanti a me. La tua rapidità mi fa piacere. Vuol dire che hai capito quanto sono importanti sia il nostro incontro sia il fatto che tu sia qui. Non sono una guida, ma comprendo gli elementi e so parlare con gli spiriti del nostro popolo. Ti insegnerò a fare lo stesso.",
  reward = "Ci incontreremo molte volte nei giorni a venire. Ogni volta, spero, te ne andrai da me un po' più potente... un po' più $Gpreparato:preparata;. Come l'Eternal Flame, il tuo spirito arderà intenso e luminoso.$B$BOra va', $N. Va' e mettiti alla prova. Sarò qui per te quando ne avrai bisogno.",
  en_title = "Rune-Inscribed Note",
  en_obj = "Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache.",
}
T[3094] = {
  title = "Verdant Note",
  desc = "Poco fa una messaggera ti stava cercando, $N. Credo che l'abbia mandata Gart, l'istruttore di druidi. Se questo biglietto viene da Gart, non aspetterei troppo a leggerne il contenuto.",
  obj = "Leggi il Verdant Note e parla con Gart Mistrunner, a Camp Narache.",
  progress = "Sei $Garrivato:arrivata;. Bene. Gli spiriti dei nostri antenati sono diventati inquieti in tutta Mulgore e oltre, ma non riesco a capire perché. Sarà per sempre tuo dovere imparare ad ascoltare gli spiriti della natura, e a essere la loro incarnazione. Tienilo a mente.",
  reward = "Anche se ci unisce un legame comune, non aspettarti una grande accoglienza dagli elfi della notte. Il loro orgoglio offusca ancora il loro sguardo, ma non è affar nostro. Gli insegnamenti della Madre Terra sono tutto ciò di cui devi preoccuparti, e ti insegnerò quello che so man mano che crescerai in saggezza.$B$BTorna spesso da me, $N. Scoprirai che la Madre Terra concede abilità incredibili a chi le è più devoto.",
  en_title = "Verdant Note",
  en_obj = "Read the Verdant Note and speak to Gart Mistrunner in Camp Narache.",
}
T[3095] = {
  title = "Simple Scroll",
  desc = "Ah, mentre eri via a vedertela con il Flagello senza mente, è arrivato questo rotolo per te. Credo sia una faccenda importante, perché sembra portare il sigillo di Dannal, l'istruttore di guerrieri. Io mi prenderei il tempo di leggerlo prima di ripartire.",
  obj = "Leggi il Simple Scroll e parla con Dannal Stern, a Deathknell.",
  progress = "Ah, dunque sei $Garrivato:arrivata;. Bene. Ho sentito dire che alcuni altri sono riusciti a sfuggire alla \"morte\" e stavano venendo in città. Forse questa tenacia ripagherà anche in futuro.$B$BPuoi ringraziare Sylvanas per la tua libertà... libertà della mente e del corpo. Anche se sei ancora $Gtormentato:tormentata; dalla piaga e dai suoi effetti, ora sei $Glibero:libera; di andare e venire come meglio credi.",
  reward = "Sarò qui ad addestrarti man mano che acquisti esperienza... vieni da me tutte le volte che vuoi. Chiedo un compenso minimo, ma vedrai che tutto quello che posso insegnarti ne vale la pena.$B$BOra va' e metti alla prova la tua abilità. Molte altre cose ti saranno rivelate man mano che acquisti esperienza, e di alcune non posso parlarti qui. Sappi solo che in futuro Sylvanas avrà bisogno di guerrieri della tua tempra. Sarai la spina dorsale della nostra salvezza. Non dimenticarlo.",
  en_title = "Simple Scroll",
  en_obj = "Read the Simple Scroll and speak to Dannal Stern in Deathknell.",
}
T[3096] = {
  title = "Encrypted Scroll",
  desc = "Ah, mentre eri via a vedertela con il Flagello senza mente, è arrivato questo rotolo per te. Credo sia una faccenda importante, perché sembra portare il sigillo di David Trias, l'istruttore di ladri. Io mi prenderei il tempo di leggerlo prima di ripartire.",
  obj = "Leggi l'Encrypted Scroll e parla con David Trias, a Deathknell.",
  progress = "Quindi ce l'hai fatta? Bene, col tempo avremo bisogno di altri ladri. Probabilmente gli Shadowstalker finiranno per trovarti quando riterranno che sia il momento giusto, perciò non commettere passi falsi e non fare niente di cui potresti pentirti. Hanno bisogno di agenti di talento... non di borseggiatori e di sciocchi.",
  reward = "Passo la maggior parte del tempo qui alla locanda, a tenere d'occhio le facce nuove e a seguire da vicino le giovani promesse. Fila dritto e farò quello che posso per insegnarti un paio di cose. Torna da me quando vuoi, e vedremo se sei $Gpronto:pronta; per un'abilità nuova o due.",
  en_title = "Encrypted Scroll",
  en_obj = "Read the Encrypted Scroll and speak to David Trias in Deathknell.",
}
T[3097] = {
  title = "Hallowed Scroll",
  desc = "Ah, mentre eri via a occuparti delle creature senza mente del Flagello, è arrivata questa pergamena per te. Immagino sia qualcosa di importante, perché sembra portare il sigillo di Duesten, l'istruttore di sacerdoti. Io mi prenderei il tempo di leggerla prima di ripartire.",
  obj = "Leggi l'Hallowed Scroll e parla con Dark Cleric Duesten nella chiesa di Deathknell.",
  progress = "Ah, dunque tra incendi, peste, rivolte e cose ben peggiori, un altro dei \"fedeli\" bussa alla mia porta. Be', lascia che ti dia il benvenuto, $C. E concedimi un momento per spiegarti un paio di cose prima che tu decida che è ora di cercare ciò che ti spinge avanti: l'Holy Light non ti riguarda più, gli spiriti dei tuoi antenati sono favole e le creature del Nether non ti vogliono.$B$BFin qui mi segui?",
  reward = "C'è una sola cosa che devi sapere: siamo sopravvissuti solo grazie alla volontà. È la fede in noi stessi che ci separa dagli altri, e con i nostri poteri porteremo un grande cambiamento in tutta Azeroth. I deboli verranno ad appoggiarsi a te. I lebbrosi ti chiameranno $GSignore:Signora;. E gli ignoranti si rivolgeranno a te per avere una guida. È mio dovere assicurarmi che tu abbia gli strumenti necessari, così che quando verrà il momento sarai $Gpronto:pronta;. Man mano che acquisti esperienza, vieni a cercarmi. Ti insegnerò poteri più grandi, se sarai $Gpronto:pronta;.",
  en_title = "Hallowed Scroll",
  en_obj = "Read the Hallowed Scroll and speak to Dark Cleric Duesten in the church in Deathknell.",
}
T[3098] = {
  title = "Glyphic Scroll",
  desc = "Ah, mentre eri via a occuparti delle creature senza mente del Flagello, è arrivata questa pergamena per te. Immagino sia qualcosa di importante, perché sembra portare il sigillo di Isabella, che addestra ogni $C come te. Al posto tuo la leggerei prima di ripartire.",
  obj = "Leggi il Glyphic Scroll e parla con Isabella nella chiesa di Deathknell.",
  progress = "Sapevo che saresti $Gvenuto:venuta; da me, $N. Non perché ti manchi la volontà di seguire la tua strada, ma perché siamo anime affini. $GEntrambi:Entrambe; abbiamo provato il dolore. $GEntrambi:Entrambe; abbiamo sofferto. E ora vogliamo il potere per riprenderci ciò che sappiamo che ci appartiene: questa terra, le nostre vite, i nostri destini. Ma hai ancora molto da imparare.",
  reward = "Dovrai tornare spesso da me, se vuoi diventare abbastanza potente da distruggere chi ci si oppone. Le regole della magia valgono ancora per te, $N. Scoprirai che la corruzione ti segue come un branco di lupi affamati nella notte. Scoprirai che la sua carezza somiglia a una dipendenza, a un vecchio amante che vuole ancora starti accanto. Ma queste cose si possono tenere a bada. Ti controlleranno solo se glielo permetterai.$B$BOra va', e torna da me quando sarai $Gdiventato:diventata; più potente.",
  en_title = "Glyphic Scroll",
  en_obj = "Read the Glyphic Scroll and speak to Isabella in the church in Deathknell.",
}
T[3099] = {
  title = "Tainted Scroll",
  desc = "Ah, mentre eri via a vedertela con il Flagello senza mente, è arrivato questo rotolo per te. Credo sia una faccenda importante, perché sembra portare il sigillo di Maximillion, l'istruttore di stregoni. Io mi prenderei il tempo di leggerlo prima di ripartire.",
  obj = "Leggi il Tainted Scroll e parla con Maximillion, a Deathknell.",
  progress = "$GBenvenuto:Benvenuta;, $Gfratello:sorella;. Sapevo che saresti $Gvenuto:venuta;. Era solo questione di tempo.$B$BQuello che ho detto ti ha interessato, vero? Ho toccato una corda... qualcosa dentro di te sapeva che quello che affermavo era la verità. Bene.$B$BMa sappi questo: non sono un traditore di Sylvanas. Semmai, lei apprezzerebbe le mie parole, visto che sono state proprio le sue convinzioni a mettere i Reietti nella posizione in cui si trovano ora.",
  reward = "Ho detto che uno schiavo resta uno schiavo, qualunque sia il padrone. Ricordi? Sappiamo entrambi che è quel tipo di controllo, quel tipo di potere, a guidarci ora. Vogliamo creature che ci servano. Sappiamo di essere più potenti e di meritare più rispetto di quanto ci concedano gli altri... e così ora cerchiamo di prendercelo.$B$BSarò tuo alleato in questa lotta, la lotta per la nostra libertà. La libertà di scegliere le nostre alleanze. Quando ti senti $Gpronto:pronta;, torna da me e ti insegnerò tutto quello che so.",
  en_title = "Tainted Scroll",
  en_obj = "Read the Tainted Scroll and speak to Maximillion in Deathknell.",
}
T[3100] = {
  title = "Simple Letter",
  desc = "Mi hanno chiesto di darti questo non appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con lo stemma di Llane, il nostro istruttore di guerrieri. Al posto tuo la leggerei subito, prima di occuparti di qualsiasi altra faccenda qui all'Abbey.",
  obj = "Leggi la Simple Letter e parla con Llane Beshere, alla Northshire Abbey.",
  progress = "Ah, hai ricevuto la mia lettera, $N... bene.$B$BUltimamente a Elwynn sono arrivati molti guerrieri: una buona cosa per Stormwind, ma una brutta notizia per i kobold e i Defias della zona.",
  reward = "Sistemati per bene, impara com'è fatta la zona e torna da me ogni volta che hai bisogno di addestramento. Sarò qui giorno e notte.$B$BI Cavalieri della Mano d'Argento hanno fatto un buon lavoro nel rendere questo posto abbastanza sicuro, ma quando conoscerai gli altri cittadini, credo che scoprirai che tutti hanno problemi per cui un aiuto farebbe comodo — un aiuto che $Gun:una; $C può dare loro. Buona fortuna.",
  en_title = "Simple Letter",
  en_obj = "Read the Simple Letter and speak to Llane Beshere in Northshire Abbey.",
}
T[3101] = {
  title = "Consecrated Letter",
  desc = "Mi è stato chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con l'insegna di Brother Sammuel, il nostro istruttore di paladini. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui nell'Abbey.",
  obj = "Leggi la Consecrated Letter e parla con Brother Sammuel, nella Northshire Abbey.",
  progress = "Finalmente! Ci incontriamo faccia a faccia, da fratello a $Gfratello:sorella;. Ti do il benvenuto a Northshire. Questa sarà la tua casa per un breve periodo, mentre impari come funzionano le cose, ma sappi che Stormwind non è lontana, e prima o poi il tuo cammino ti porterà là. Ma fino ad allora, abbi pazienza... $GCavaliere:Cavaliera; della Mano d'Argento.",
  reward = "Nel frattempo, dovresti sapere un paio di altre cose. Sei un simbolo per molti, qui in questa terra — comportati di conseguenza. L'Holy Light risplende dentro di te, e sarà evidente sia ai tuoi alleati sia ai tuoi nemici.$B$BInoltre, man mano che crescerai in saggezza e potere, dovrai addestrarti per imparare nuove abilità. È qui che entro in gioco io. Quando senti di aver fatto un po' di esperienza qui a Northshire, torna da me e ti insegnerò quello che sento che sei $Gpronto:pronta; a imparare. Buona fortuna... $C!",
  en_title = "Consecrated Letter",
  en_obj = "Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey.",
}
T[3102] = {
  title = "Encrypted Letter",
  desc = "Mi hanno chiesto di darti questo non appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con lo stemma di Jorik, uno dei nostri istruttori. Al posto tuo la leggerei subito, prima di occuparti di qualsiasi altra faccenda qui all'Abbey.",
  obj = "Leggi l'Encrypted Letter e parla con Jorik Kerridan, nella stalla dietro la Northshire Abbey.",
  progress = "Sei $Garrivato:arrivata; fin qui senza un graffio, e non sembra che ti abbiano visto in molti. Tanto mi basta. Qui dietro non mi piace attirare troppo l'attenzione... tutto bello tranquillo. Sono sicuro che capisci.$B$BHai già avuto qualche guaio? Mi fa piacere sentire di no. Le cose cambieranno presto.",
  reward = "Troverai parecchi gruppi che farebbero di tutto per avere le nostre abilità, $N. Gli avventurieri, lo SI:7... accidenti, perfino la Defias Brotherhood non disdegnerebbe una spia o due dentro Stormwind. Ma ricordati questo: rispondi solo a te $Gstesso:stessa;. Non lasciare che nessuno ti costringa a fare qualcosa che non vuoi fare! E poi, le carte in mano le abbiamo tutte noi... almeno finché la partita non è finita. Capisci cosa intendo?$B$BComunque, volevo solo presentarmi e farti sapere che sono qui se hai bisogno di addestramento. Passa quando vuoi.",
  en_title = "Encrypted Letter",
  en_obj = "Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.",
}
T[3103] = {
  title = "Hallowed Letter",
  desc = "Mi è stato chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con l'insegna di Priestess Anetta, la nostra istruttrice di sacerdoti. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui nell'Abbey.",
  obj = "Leggi l'Hallowed Letter e parla con Priestess Anetta, nella Northshire Abbey.",
  progress = "Ah, finalmente sei $Garrivato:arrivata;. Sapevo che avresti trovato la strada fino a me. L'Holy Light risplende su di te e sul cammino che hai scelto. Questi sono tempi duri: la Legione Infuocata è ancora presente su Azeroth, l'intero Kalimdor cerca nuovi modi per difendersi dalle proprie tribolazioni, e sta a te aiutare quante più persone puoi.",
  reward = "Man mano che acquisti esperienza, torna da me e farò il possibile per trasmetterti il mio sapere. Fino ad allora, va' con la compassione nel cuore, e lascia che la saggezza ti guidi. Ricorda: il mondo diventa un posto migliore solo se sei tu a renderlo tale.",
  en_title = "Hallowed Letter",
  en_obj = "Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey.",
}
T[3104] = {
  title = "Glyphic Letter",
  desc = "Mi è stato chiesto di fartela avere appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con l'insegna di Khelden, il nostro istruttore di maghi. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui nell'Abbey.",
  obj = "Leggi la Glyphic Letter e parla con Khelden Bremen, dentro la Northshire Abbey.",
  progress = "Salve, $N. Sono Khelden. Posso fare qualcosa per te?",
  reward = "Ah ah, sapevo che il mio biglietto non ti avrebbe distolto dal tuo cammino. Quindi sei $Gpronto:pronta;, vero? $GPronto:Pronta; ad accettare il tuo destino? $GPronto:Pronta; a sfidare gli dei e qualsiasi altra forza ti si pari davanti nella ricerca della conoscenza e del potere?$B$BNon ti mentirò, $N: sarai $Gtemuto:temuta; quanto $Grispettato:rispettata;. Ma sappi anche questo: sarò qui per te quando avrai bisogno di addestramento. Basterà che tu venga a cercarmi man mano che diventerai più potente.",
  en_title = "Glyphic Letter",
  en_obj = "Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey.",
}
T[3105] = {
  title = "Tainted Letter",
  desc = "Mi hanno chiesto di darti questo non appena fossi $Gtornato:tornata; dagli accampamenti dei kobold, $N. Sembra una lettera sigillata con lo stemma di Drusilla, una delle nostre istruttrici. Al posto tuo la leggerei subito, prima di occuparti di qualsiasi altra faccenda qui all'Abbey.",
  obj = "Leggi la Tainted Letter e parla con Drusilla La Salle, accanto alla Northshire Abbey.",
  progress = "Ah, dunque sei $Garrivato:arrivata;, e appena in tempo, $N. Poco fa alcune guardie erano qui e mi lanciavano occhiate curiose... patetici profani.",
  reward = "Man mano che cresci in potere, sarai $Gtentato:tentata;: devi sempre ricordarti di controllarti. Non ti mentirò: la corruzione può colpire chiunque pratichi l'arcano, soprattutto chi ha a che fare con le creature del Twisting Nether. Sii paziente, e sii prudente... ma non lasciare che questo soffochi la tua ambizione.$B$BQuando sarai più potente, torna da me e ti insegnerò di più sulle nostre vie.",
  en_title = "Tainted Letter",
  en_obj = "Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey.",
}
T[3106] = {
  title = "Simple Rune",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Thran, l'istruttore di guerrieri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi la Simple Rune e parla con Thran Khorman, nella Coldridge Valley.",
  progress = "Accidenti che freddo oggi, eh? Sembra che la neve non se ne vada mai, $N.$B$BProbabilmente l'hai già notato, ma adesso nella nostra città vivono degli gnomi. È perché sono riusciti a farsi saltare in aria la loro casa. Non andarlo a raccontare in giro, ma non posso proprio dargli torto — credo che anch'io sarei ricorso agli esplosivi, se Ironforge fosse stata infestata dai Dark Iron o gente simile.",
  reward = "Altre cose che probabilmente vedrai, così sei al corrente: nani che in battaglia usano la magia invece del fucile. Alcuni di noi che si mettono a venerare l'Holy Light come certi umani e, ultimi ma non meno importanti, i trogg. Su di loro ne saprai di più in seguito, ma quello che devi sapere adesso è che sono qui per aiutarti.$B$BSono qui per insegnarti a essere $Gun vero:una vera; $C. Ogni volta che pensi di aver bisogno di altro addestramento, torna da me e vedrò cosa posso fare.",
  en_title = "Simple Rune",
  en_obj = "Read the Simple Rune and speak to Thran Khorman in Coldridge Valley.",
}
T[3107] = {
  title = "Consecrated Rune",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Bromos, l'istruttore di paladini. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi la Consecrated Rune e parla con Bromos Grummner, nella Coldridge Valley.",
  progress = "Allora, ce l'hai fatta! E appena in tempo. C'è molto da fare nella Coldridge Valley e oltre. Avrò bisogno del tuo aiuto quanto tu avrai bisogno del mio!$B$BOra sei $Gun Cavaliere:una Cavaliera; della Mano d'Argento, sii $Gpronto:pronta; a comportarti come tale.",
  reward = "Gli umani ci hanno insegnato molto sull'Holy Light e su quanto il loro ordine sia importante per loro... e per la protezione di tutta Azeroth. Abbiamo un grande rispetto per quanto sia intriso di tradizione, e per come una sola figura, un solo sacrificio, possa fare la differenza tra il dolore e la salvezza.$B$BNoi due lavoreremo insieme per un po'. Ogni volta che pensi di essere $Gpronto:pronta;, torna da me e vedremo di darti un po' di addestramento. Non possiamo mandarti in giro per il mondo $Gimpreparato:impreparata;, no?",
  en_title = "Consecrated Rune",
  en_obj = "Read the Consecrated Rune and speak to Bromos Grummner in Coldridge Valley.",
}
T[3108] = {
  title = "Etched Rune",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Thorgas, l'istruttore di cacciatori. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi l'Etched Rune e parla con Thorgas Grimson, nella Coldridge Valley.",
  progress = "Ce l'hai fatta! Mi fa piacere! Scommetto che non hai nemmeno dovuto seguire le mie tracce per trovare il posto. Ah ah!$B$BLa nostra professione è piuttosto intrisa di tradizione, $N. Imparare le vie della terra. Imparare a seguire le tracce di un orso tra le montagne. Anche solo sopravvivere contando soltanto sul proprio ingegno richiede molto coraggio e molta astuzia. Pensi di esserne capace?",
  reward = "Una cosa che dovresti ricordare sempre è che devi rispettare il mondo in cui vivi. Le bestie che scelgono di combattere al tuo fianco; il luccichio della tua arma; il peso delle tue munizioni; il morso di un vento gelido; tutte queste cose devi conoscerle a fondo.$B$BFarò quello che posso per aiutarti, ma la maggior parte del lavoro spetta a te. Ogni volta che pensi di essere $Gpronto:pronta;, torna a parlare con me. Ti addestrerò quando potrò.",
  en_title = "Etched Rune",
  en_obj = "Read the Etched Rune and speak to Thorgas Grimson in Coldridge Valley.",
}
T[3109] = {
  title = "Encrypted Rune",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Solm, l'istruttore di ladri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi l'Encrypted Rune e parla con Solm Hargrin, nella Coldridge Valley.",
  progress = "Ce l'hai fatta! Magnifico!$B$BUltimamente c'è un gran via vai, quindi sono contento di contare un altro membro del clan di Ironforge tra le nostre file. Per i miei gusti, troppi di noi guardano all'arcano e al divino. Niente contro di loro e le loro credenze, ma non c'è niente come una lama fredda in mano e un'ombra che ti tenga lontano dalla luce, capisci cosa intendo?",
  reward = "Comunque, quando comincerai a curiosare in giro per Coldridge, prima o poi avrai bisogno di addestramento. Torna da me ogni volta che senti di averne bisogno e ti insegnerò quello che so — un trucco qui, una manovra là. Sai, le cose che ti tengono in vita e ti fanno guadagnare qualche moneta in più.$B$BE tieni d'occhio anche i nostri amici gnomi... sono loro ad aver avuto la peggio, visto che Gnomeregan è stata... distrutta. Avranno bisogno del nostro aiuto per sentirsi i benvenuti.",
  en_title = "Encrypted Rune",
  en_obj = "Read the Encrypted Rune and speak to Solm Hargrin in Coldridge Valley.",
}
T[3110] = {
  title = "Hallowed Rune",
  desc = "Mentre mi davi una mano, mi hanno dato questa runa da passare a te. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene da Branstock, l'istruttore di sacerdoti. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi l'Hallowed Rune e parla con Branstock Khalder, ad Anvilmar.",
  progress = "Ah! Ce l'hai fatta, $N! Magnifico!$B$BStavo per dirti che ormai perdevo la fede nel tuo arrivo... capito, perdere la fede? È una battuta, $Gragazzo:ragazza;... uff, lascia stare. Tanto non sei $Gvenuto:venuta; qui per le mie battutacce.",
  reward = "Sono io quello che può addestrarti mentre cominci a orientarti nella Coldridge Valley. Quando ti senti $Gpronto:pronta;, torna da me e vedremo se insegnarti un incantesimo o due per difendere la valle da quei maledetti trogg.$B$BHai la Luce dalla tua parte, insieme a tutta Ironforge, $N... nessuna pressione perché tu diventi qualcosa di speciale.",
  en_title = "Hallowed Rune",
  en_obj = "Read the Hallowed Rune and speak to Branstock Khalder in Anvilmar.",
}
T[3111] = {
  title = "Glyphic Rune",
  desc = "Tanto tempo fa gli alti elfi insegnarono i segreti della magia a noi e ai nostri alleati umani. Ci facevano grandi prediche sulle regole e su come la magia possa farti impazzire! Ma non crederci. Noi non siamo come gli elfi; non abbiamo le loro stesse debolezze. Basta che tu resti sulla retta via, e scoprirai che la magia è potente come strumento quanto come arma.$B$BQuando sei $Gpronto:pronta;, vieni a cercarmi dentro Anvilmar. Ti aspetto!",
  obj = "Parla con Marryk Nurribit, dentro Anvilmar.",
}
T[3112] = {
  title = "Simple Memorandum",
  desc = "Mentre mi davi una mano, mi hanno dato questo memorandum da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Thran, l'istruttore di guerrieri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi il Simple Memorandum e parla con Thran Khorman, nella Coldridge Valley.",
  progress = "Ah, beh, un altro memorandum da $Gun:una; $R in missione... che cosa carina.$B$BNo, no, non ti sto prendendo in giro, $Gpiccoletto:piccoletta;. Bisogna rispettare la tua tenacia, questo è certo. Sarei altrettanto furioso se Ironforge fosse stata presa dai nani Dark Iron, quindi non pensare che non capisca la tua situazione...",
  reward = "Beh, visto che questa è la tua direttiva principale, o come la chiamate di questi tempi, ho dato la mia parola che avrei fatto tutto il possibile perché tu e i tuoi foste pronti a riprendervi la vostra casa... ed è proprio quello che farò.$B$BOgni volta che ti senti $Gpronto:pronta;, torna dal buon vecchio Thran e sarò felice di condividere con te quello che so. L'addestramento ha un costo, ma non sarà troppo caro. Buona fortuna.",
  en_title = "Simple Memorandum",
  en_obj = "Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley.",
}
T[3113] = {
  title = "Encrypted Memorandum",
  desc = "Mentre mi davi una mano, mi hanno dato questo memorandum da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Solm, l'istruttore di ladri. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi l'Encrypted Memorandum e parla con Solm Hargrin, nella Coldridge Valley.",
  progress = "Sono contento di vedere che hai ricevuto il mio biglietto e che sei $Gvenuto:venuta;. Scusa se ho finto che fosse un memorandum dei tuoi superiori... non volevo offenderti. Sapevo solo che noi due, insieme agli altri come noi, dobbiamo restare uniti.$B$BNon sono in molti a pensare che sia una gran cosa avere la tua gente e la mia rintanate nella stessa città, ma io credo che possiamo andare d'accordo benissimo. Tu che ne pensi?",
  reward = "Qui me ne sto per conto mio, così nessuno ci dà la colpa delle cose che spariscono, ma se ti serve qualcosa, un po' di addestramento o altro, torna pure quando vuoi.$B$BIo e te ci capiamo. Sappiamo che, quando si arriva al dunque, ci si può fidare solo della famiglia... ed è proprio quello che abbiamo qui, no? Anche se Gnomeregan è stata... invasa, e qualunque altra cosa ci capiti addosso, possiamo contare gli uni sugli altri per guardarci le spalle. Giusto?",
  en_title = "Encrypted Memorandum",
  en_obj = "Read the Encrypted Memorandum and speak to Solm Hargrin in Coldridge Valley.",
}
T[3114] = {
  title = "Glyphic Memorandum",
  desc = "Mentre mi davi una mano, mi hanno dato questo memorandum da passare a te. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene da Marryk, l'istruttore di maghi. Dagli un'occhiata e poi va' a cercarlo dentro Anvilmar quando ne hai l'occasione.",
  obj = "Leggi il Glyphic Memorandum e parla con Marryk Nurribit, dentro Anvilmar, sopra la Coldridge Valley.",
  progress = "Sì, cosa c'è, $R? Parla più forte, se non ti dispiace. Dopo qualche birra non ci sento tanto bene.",
  reward = "Ah, già! Le Arti Arcane... ma certo.$B$BEcco quello che devi sapere, $N: non cacciarti in troppi guai. Metti da parte qualche moneta per offrirmi una birra... o per qualunque incantesimo tu voglia. E per carità, stai alla larga da Gnomeregan. A parte questo, buona giornata! Sono qui se hai bisogno di me o vuoi addestrarti... o per qualsiasi altra cosa.",
  en_title = "Glyphic Memorandum",
  en_obj = "Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley.",
}
T[3115] = {
  title = "Il memorandum contaminato",
  desc = "Mentre mi davi una mano, mi hanno consegnato questo memorandum da passare a te. Leggilo quando hai un momento. Credo che venga dall'addestratore di stregoni, Alamar. Dagli un'occhiata e vai a cercarlo dentro Anvilmar quando puoi.$B$BE sta' attent$Go:a;, $N: quelli come te non godono di molta fiducia da queste parti.",
  obj = "Leggi il Tainted Memorandum e parla con Alamar Grimm dentro Anvilmar, sopra Coldridge Valley.",
  progress = "Meraviglioso! A quanto pare hai ricevuto il mio memorandum.$B$BIgnora gli sciocchi che ti circondano, $N. La Sacra Luce?! La spada e lo scudo?! Non sono strade per menti aperte come le nostre. Guarda cosa ha fatto alla nostra patria la magia \"normale\". Insieme a quei maledetti armeggiatori, la nostra razza per poco non si è estinta. E ora dobbiamo dipendere dai nani, che preferiscono passare il tempo ad allearsi con gli umani piuttosto che aiutarci a ricostruire la nostra casa. Siamo come cittadini di seconda classe. Hai visto come ci guardano?",
  reward = "Ma niente di tutto questo conta. Quello che conta è che hai visto la tua vera Sacra Luce! Sai da dove viene davvero il potere. Ti rendi conto che avere alleati nostri è molto più... prudente. Alleati speciali. Alleati che, qualunque sia il compito, obbediranno fino all'ultimo respiro.$B$BEd è qui che entro in gioco io, $N. Posso addestrarti agli inizi di quei poteri speciali. Cercami spesso e farò il possibile per insegnarti altri incantesimi.",
  en_title = "Tainted Memorandum",
  en_obj = "Read the Tainted Memorandum and speak to Alamar Grimm inside Anvilmar above Coldridge Valley.",
}
T[3116] = {
  title = "Simple Sigil",
  desc = "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice di guerrieri, Alyissia. Sembra che Alyissia voglia parlarti quando hai un momento. Leggilo e poi portalo a lei.",
  obj = "Leggi il Simple Sigil e parla con Alyissia, a Shadowglen.",
  progress = "Ce l'hai fatta. Ne sono davvero felice.$B$BNegli ultimi anni sono successe molte cose, $N: la creazione di Teldrassil, la corruzione di molte creature della foresta, qui e altrove, la scoperta di terre che credevamo perdute, come Feralas... tante cose, in così poco tempo. Ma queste sono solo alcune delle ragioni per cui siamo qui; la più importante è proteggere la nostra gente da altro male.",
  reward = "Presto vedrai gente di altre razze tra i rami della nostra casa: non lasciare che questo faccia nascere in te dei pregiudizi. Sono i benvenuti. Ci aiuteranno quando potranno. Non tutti saranno disinteressati, ma meritano un po' di fiducia.$B$BMa ora niente di tutto questo conta. Ora dobbiamo concentrarci su di te e su come puoi aiutare la nostra gente. Sono qui proprio per questo. Ti addestrerò nelle vie $Gdel:della; $C man mano che diventi più forte. Torna da me quando vuoi, e farò quello che posso per aiutarti.",
  en_title = "Simple Sigil",
  en_obj = "Read the Simple Sigil and speak to Alyissia in Shadowglen.",
}
T[3117] = {
  title = "Etched Sigil",
  desc = "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice di cacciatori, Ayanna. Sembra che Ayanna voglia parlarti quando hai un momento. Leggilo e poi portalo a lei.",
  obj = "Leggi l'Etched Sigil e parla con Ayanna Everstride, in cima ad Aldrassil, a Shadowglen.",
  progress = "Sei $Garrivato:arrivata;, e appena in tempo, $N. $GBenvenuto:Benvenuta; a Shadowglen.$B$BConfido che il mio sigillo ti abbia trovato in buona salute e di buon umore?$B$BCome ho detto prima, sono qui per addestrarti come $Gcacciatore:cacciatrice;, per insegnarti ad addomesticare le bestie perché ti aiutino in battaglia; a usare l'arco con precisione infallibile; a rispettare le terre che chiamiamo casa, e anche le terre al di là.",
  reward = "Mentre scopri quello che Shadowglen ha da insegnarti, vieni a trovarmi — potrò aiutarti a capire meglio il tuo ruolo di $Gcacciatore:cacciatrice; e ciò di cui sei capace.$B$BSono tempi pericolosi, $N, non dare per scontata l'abilità dei tuoi animali — in questo mondo ci sono cose più pericolose di quanto tu possa immaginare. Va' con Elune, e torna ancora da me.",
  en_title = "Etched Sigil",
  en_obj = "Read the Etched Sigil and speak to Ayanna Everstride at the top of Aldrassil in Shadowglen.",
}
T[3118] = {
  title = "Encrypted Sigil",
  desc = "Questo sigillo mi è stato consegnato da un messaggero del nostro istruttore di ladri, Frahun. Sembra che Frahun voglia parlarti quando hai un momento. Leggilo e poi portalo a lui.",
  obj = "Leggi l'Encrypted Sigil e parla con Frahun Shadewhisper, a Shadowglen.",
  progress = "Salve, $N. Sono contento che tu mi abbia trovato. Pensavo che magari ti fossi $Gperso:persa; lungo la strada.$B$BA Shadowglen non è successo niente di davvero nuovo da quando ti ho mandato il mio sigillo, ma lascio a te il compito di raccogliere informazioni. Parla con le altre persone intorno ad Aldrassil, se vuoi.",
  reward = "Fino ad allora, sappi che quelli come noi servono più che mai in questi tempi incerti. La pace con le altre razze può venire meno da un momento all'altro, e si parla molto di membri dell'Orda che cercano di seminare ancora più sfiducia. Ricordalo.$B$BMan mano che acquisti potere e ti senti più $Gpreparato:preparata;, torna da me qui e vedrò di farti avere un po' di addestramento. È importante che tu sappia maneggiare l'arma che preferisci, tra le altre cose.",
  en_title = "Encrypted Sigil",
  en_obj = "Read the Encrypted Sigil and speak to Frahun Shadewhisper in Shadowglen.",
}
T[3119] = {
  title = "Hallowed Sigil",
  desc = "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice di sacerdoti, Shanda. Sembra che Shanda voglia parlarti quando hai un momento. Leggilo e poi portalo a lei.",
  obj = "Leggi l'Hallowed Sigil e parla con Shanda, ad Aldrassil.",
  progress = "Mi fa piacere vedere che sei $Garrivato:arrivata; così in fretta, $N. $GBenvenuto:Benvenuta;.$B$BCome probabilmente avrai sentito, tutta Teldrassil è in fermento per l'andirivieni dei viaggiatori. Perfino ai membri dell'Alleanza è stato concesso di salire sui rami di Teldrassil, per incontrare altri Kaldorei che si preparano alle avventure che li attendono.",
  reward = "Per ora non preoccuparti del mondo sotto Teldrassil. Ci sarà tempo per quello più avanti. Ora va' a parlare con gli altri a Shadowglen — possono raccontarti di più sugli eventi che sono accaduti. Aiutali in ogni modo possibile, e ogni volta che senti di aver bisogno di altro addestramento, torna da me e ti insegnerò quello che posso.",
  en_title = "Hallowed Sigil",
  en_obj = "Read the Hallowed Sigil and speak to Shanda in Aldrassil.",
}
T[3120] = {
  title = "Verdant Sigil",
  desc = "Questo sigillo me l'ha dato un messaggero del nostro istruttore di druidi, Mardant. Pare che Mardant voglia parlarti quando hai un momento. Leggilo e poi portaglielo.",
  obj = "Leggi il Verdant Sigil e parla con Mardant Strongoak, nell'albero Aldrassil, a Shadowglen.",
  progress = "Ah, giovane $C. Vedo che sei impaziente di continuare i tuoi studi. Bene.$B$BMi chiedo: hai già passato molto tempo nell'Emerald Dream? Forse non sei ancora $Gpronto:pronta; per questo... Col tempo lo sarai, ne sono certo.$B$BMa fino ad allora, dovremmo parlare d'altro.",
  reward = "Per ora sarò il tuo mentore e la tua guida. È mio dovere insegnarti a interpretare non solo ciò che gli spiriti ci comunicano, ma anche le complessità e i segreti dell'Emerald Dream.$B$BMan mano che imparerai e crescerai in potere, conoscerai meglio la nostra trance del sonno. Ma fino ad allora, torna da me tutte le volte che vuoi e ti insegnerò quello che posso sulle vie della nostra gente.",
  en_title = "Verdant Sigil",
  en_obj = "Read the Verdant Sigil and speak to Mardant Strongoak, in the tree Aldrassil in Shadowglen.",
}
T[3130] = {
  title = "Contro gli Hatecrest",
  desc = "A questo punto ti indirizzerò al mio secondo, Latronicus. Finora ha tenuto d'occhio da vicino le forze dei naga. Io valuterò la situazione generale qui, per quanto riguarda i naga; per quanto vorrei impegnare tutte le nostre forze contro di loro, lasciare la roccaforte esposta a un attacco diretto dell'Orda, o peggio, non mi sembra la scelta migliore.$B$BComunque, Latronicus ti aspetta. Buon lavoro finora, $N. Continua così.$B$BPuoi andare.",
  obj = "Fai rapporto a Latronicus Moonspear, alla Feathermoon Stronghold.",
  reward = "Eccellente, $N: in chi lavora con me apprezzo un atteggiamento da \"si può fare\".$B$BIl generale Feathermoon mi ha incaricato di affrontare i naga in modo diretto. I miei piani sono due: primo, indeboliremo le loro forze, sia nel numero sia nel comando; secondo, scopriremo cosa stanno facendo tra le rovine. Con il tuo aiuto contrasteremo la presenza dei naga senza sacrificare la sicurezza generale della roccaforte.",
  en_title = "Against the Hatecrest",
  en_obj = "Report to Latronicus Moonspear in Feathermoon Stronghold.",
}
T[3182] = {
  title = "La prova dell'impresa",
  desc = "Ti aspetti che creda a una storia del genere? Il vero corno avrebbe avuto ancora conficcata la testa della mia ascia spezzata.$B$BAscolta, porta quel falso evidente a Curator Thorius a Ironforge. Se lui confermerà la tua versione, riceverai una prova dell'impresa. Riportami quella prova e ti darò la chiave per la Searing Gorge.$B$BMuoviti!",
  obj = "Porta il Margol's Gigantic Horn a Curator Thorius a Ironforge.",
  progress = "Oh, salve, $Ggiovanotto:signorina;. Ti andrebbe una visita guidata del museo?",
  reward = "Cos'è questo?$B$BOh, cielo, non ci credo! Ti rendi conto di cos'hai qui, $R? Questo è il corno di Margol the Rager! Margol, la rovina di ogni archeologo che abbia mai messo piede nella Searing Gorge.$B$BPosso tenerlo?",
  en_title = "Proof of Deed",
  en_obj = "Take Margol's Gigantic Horn to Curator Thorius in Ironforge.",
}
T[3221] = {
  title = "Parla con Renferrel",
  desc = "Mentre eri via ad aiutare i nostri deathstalker, l'Apothecary Renferrel ti ha mandato a chiamare. Non mi ha dato dettagli, ma voleva parlarti dei cuori di lupo che gli hai consegnato.",
  obj = "Parla con l'Apothecary Renferrel al Sepulcher.",
  reward = "Ah, molto bene. C'è una questione riguardo ai cuori di lupo che mi hai portato in precedenza che richiede la nostra attenzione.",
  en_title = "Speak with Renferrel",
  en_obj = "Speak with Apothecary Renferrel at the Sepulcher.",
}
T[3261] = {
  title = "Jorn Skyseer",
  desc = "Il tuo tempo con me è finito, $N. Per imparare di più, devi recarti a Camp Taurajo, a sud, e parlare con Jorn Skyseer. Sarà lui a proseguire la tua guida.",
  obj = "Parla con Jorn Skyseer a Camp Taurajo.",
  reward = "Salute, giovane. Sei qui per percorrere la via del cacciatore?$B$BMolto bene. Cominciamo.",
  en_title = "Jorn Skyseer",
  en_obj = "Speak with Jorn Skyseer at Camp Taurajo.",
}
T[3281] = {
  title = "Argento rubato",
  desc = "Avrai anche ucciso i raptor, ma l'argento che hanno rubato dev'essere recuperato! Mi dicono che i raptor hanno una vasta area di nidi a sud di Ratchet, nota come Raptor Grounds. È probabile che abbiano portato là il nostro argento rubato.$B$BVai in quel rifugio di raptor e cerca l'argento rubato. Quando lo troverai, riportamelo.",
  obj = "Porta lo Stolen Silver a Gazrog al Crossroads.",
  progress = "Hai l'argento?",
  reward = "Aha! Quindi i raptor hanno nascosto l'argento nella loro tana. Stento a credere che queste bestie desiderino l'argento. Forse le storie sulla loro intelligenza non sono poi così lontane dal vero!$B$BGrazie, $N. Prendi questo come ricompensa per il tuo servizio, e sappi che le guardie del Crossroads devono a te la paga del prossimo mese.",
  en_title = "Stolen Silver",
  en_obj = "Bring the Stolen Silver to Gazrog in the Crossroads.",
}
T[3301] = {
  title = "Mura Runetotem",
  desc = "Una mia compagna di clan, Mura Runetotem, è andata a Silverpine per aiutare i nostri alleati non morti. Silverpine è una foresta malata, una foresta morente, e Mura sperava di donarle nuova vita. Forse la strana vita che si trova qui nei Barrens potrà aiutare il suo lavoro a Silverpine.$B$BPrendi un campione dei gusci che hai raccolto e portalo a Mura a Silverpine. Si trova al Sepulcher. Con un po' di fortuna, lo studio del guscio le darà l'intuizione necessaria per guarire quel luogo morente.",
  obj = "Parla con Mura Runetotem al Sepulcher.",
  progress = "Sento addosso a te la polvere dei Barrens, $C. Hai viaggiato a lungo.",
  reward = "Ah, cos'è questo? Questo guscio ha un bagliore interiore, come se pulsasse ancora di vita. Straordinario! Devo studiarlo ancora.$B$BGrazie, $N. Con un po' di fortuna, questo guscio custodirà un segreto che potrò usare per aiutare la povera terra di Silverpine.",
  en_title = "Mura Runetotem",
  en_obj = "Speak with Mura Runetotem in the Sepulcher.",
}
T[3341] = {
  title = "Porta la fine",
  desc = "Nelle Barrens si trova un orrendo groviglio di rampicanti chiamato Razorfen Downs. Se le nostre prime osservazioni di quel luogo avevano rivelato una minaccia modesta, le nostre scoperte recenti sono molto più gravi...$B$BI quilboar di Razorfen Downs si sono alleati con il Flagello. Ora li governa un lich di nome Amnennar the Coldbringer, che usa il potere della sua immensa coscienza per controllare ogni loro mossa.$B$BAmnennar ha un legame telepatico diretto con Ner'zhul; dobbiamo spezzare questo legame, $N. Il Coldbringer deve trovare la sua fine.",
  obj = "Andrew Brownell vuole che tu uccida Amnennar the Coldbringer e riporti il suo teschio.",
  progress = "Questa faccenda è della massima importanza, $N. Dobbiamo fermare ogni tentativo del Flagello di rinforzare le sue file.",
  reward = "La lealtà di un lich è incrollabile, $N. Che sappiano che una simile lealtà porterà loro solo la distruzione.",
  en_title = "Bring the End",
  en_obj = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.",
}
T[3361] = {
  title = "Il dilemma di un profugo",
  desc = "Abbiamo cacciato i trogg da Gnomeregan, ma poi è andato tutto terribilmente storto! Ora la nostra casa è completamente irradiata e noi gnomi siamo sparpagliati per tutto Dun Morogh.$B$BNella fretta di sfuggire alle radiazioni ho perso tutti i miei effetti personali e i miei attrezzi. Sono stati i troll a prenderli. Mi hanno rubato il baule, la scatola e il secchio di bulloni! Li hanno portati nei loro accampamenti a sud-ovest di Anvilmar.$B$BIo non sono un avventuriero: potresti trovare le mie cose e riportarmele qui, per favore?",
  obj = "Porta Felix's Box, Felix's Chest e Felix's Bucket of Bolts a Felix Whindlebolt ad Anvilmar.",
  progress = "Oh cielo, $N, questa città non fa per uno come me. Qui ci sono tante creature orribili quante ce n'erano a Gnomeregan prima dell'incidente!$B$BHai le mie cose? Se no, chissà cosa ne avranno fatto i troll...",
  reward = "Evviva, le hai trovate! Mi hai salvato, amic$Go:a; mi$Go:a;. Ecco, non è molto, ma è qualcosa per il disturbo che ti ho dato! Grazie!",
  en_title = "A Refugee's Quandary",
  en_obj = "Bring Felix's Box, Felix's Chest and Felix's Bucket of Bolts to Felix Whindlebolt in Anvilmar.",
}
T[3364] = {
  title = "Consegna di Mornbrew bollente",
  desc = "Accidenti! Dovevo portare questa deliziosa mornbrew bollente a Durnan Furcutter, dentro Anvilmar, già da un po', ma prima ho dovuto consegnarne una a Grelin qui. Non arriverò mai ad Anvilmar prima che si raffreddi!$B$BTu sembri veloce. Forse ce la fai tu. Questa tazza resterà calda solo per altri cinque minuti, e Durnan non ha ordinato una mornbrew \"fresca\", quindi sbrigati. Anvilmar è a nord-est: un insediamento scavato nella montagna.$B$BGrazie, $N, e non dimenticare di riportarmi il boccale!",
  obj = "Porta una Scalding Mornbrew a Durnan Furcutter dentro Anvilmar entro cinque minuti, prima che si raffreddi!",
  progress = "Sì, sono Durnan Furcutter. Hai qualcosa per me?",
  reward = "Ah, bene, questa è proprio quello che ci voleva. Permettimi di fare una piccola pausa mentre mi godo questa mornbrew bollente!",
  en_title = "Scalding Mornbrew Delivery",
  en_obj = "Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!",
}
T[3365] = {
  title = "Riporta il boccale",
  desc = "Questa sì che ci voleva! Niente come una mornbrew fumante, anzi BOLLENTE, in una fredda giornata d'inverno per scaldarti il cuore.$B$BEcco qua, $N: fammi un favore e riporta questo boccale vuoto a Nori, ti va?",
  obj = "Restituisci il boccale di Nori a Nori Pridedrift.",
  progress = "Spero che la mornbrew bollente sia arrivata a Durnan in tempo! Ti sei ricordat$Go:a; di riportarmi il boccale?",
  reward = "Eccellente, $N! Saresti sorpres$Go:a; di quanti corrieri dimenticano una cosa semplice come riportare il boccale. I boccali non crescono sugli alberi, o almeno così mi dicono!$B$BEcco un piccolo compenso per il disturbo. Grazie ancora per l'aiuto.",
  en_title = "Bring Back the Mug",
  en_obj = "Return Nori's Mug to Nori Pridedrift.",
}
T[3366] = {
  title = "La scheggia luminosa",
  desc = "La scheggia è di un verde brillante e, pur essendo solida, sotto la superficie sembra muoversi qualcosa come fumo. Non riesci a smettere di fissare le profondità del cristallo; e allo stesso tempo sai che c'è qualcosa di molto inquietante in esso.$B$BForse dovresti vedere se a Ratchet c'è qualcuno che può dirti di più su questa strana scheggia.",
  obj = "Va' a Ratchet per scoprire il significato del Nightmare Shard.",
}
T[3369] = {
  title = "Negli incubi",
  desc = "Questa scheggia custodisce grandi segreti: è la pura essenza dell'Emerald Dream. Ma quello che vedo dentro non è un sogno: una visione del genere si chiamerebbe incubo.$B$BNon voglio allarmarti, $N, ma credo sia meglio che tu consegni questa scheggia nelle mani di un druido saggio appena puoi.$B$BQuello che devi trovare è Hamuul Runetotem, sull'Elder Rise. Va' a Thunder Bluff. Non posso dire altro.",
  obj = "Porta il Nightmare Shard a Hamuul Runetotem, sull'Elder Rise.",
  progress = "Posso esserti utile in qualcosa?",
  reward = "Ti manda Falla? Bene, vediamo questa scheggia di cui dici che lei era così restia a parlare...$B$B<Hamuul scruta dentro la scheggia>$B$BOh... io non... Be'.$B$B$N, ti ringrazio per avermela portata. Però ti consiglio di non parlare di cose come questa: non è saggio. Sono faccende di cui non dovresti occuparti.$B$BDiciamo solo che le cose nell'Emerald Dream non sono come credevamo...$B$BForse in futuro le nostre strade si incroceranno di nuovo.",
  en_title = "In Nightmares",
  en_obj = "Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.",
}
T[3370] = {
  title = "Negli incubi",
  desc = "Questa scheggia custodisce grandi segreti: è la pura essenza dell'Emerald Dream. Ma quello che vedo dentro non è un sogno: una visione del genere si chiamerebbe incubo.$B$BNon voglio allarmarti, $N, ma credo sia meglio che tu consegni questa scheggia nelle mani di un druido saggio appena puoi...$B$BQuello che devi trovare è Mathrengyl Bearwalker, nel Cenarion Circle. Va' a Darnassus. Non posso dire altro.",
  obj = "Porta il Nightmare Shard a Mathrengyl Bearwalker, a Darnassus.",
  progress = "Posso esserti utile in qualcosa?",
  reward = "Ti manda Falla? Bene, vediamo questa scheggia di cui dici che lei era così restia a parlare...$B$B<Mathrengyl scruta dentro la scheggia>$B$BOh... io non... Be'.$B$B$N, ti ringrazio per avermela portata. Però ti consiglio di non parlare di cose come questa: non è saggio. Sono faccende di cui devono occuparsi soltanto i druidi del Cenarion Circle.$B$BDiciamo solo che le cose nell'Emerald Dream non sono come credevamo...$B$BForse in futuro le nostre strade si incroceranno di nuovo.",
  en_title = "In Nightmares",
  en_obj = "Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus.",
}
T[3374] = {
  title = "L'essenza di Eranikus",
  desc = "Attivi la pietra del giuramento, e Itharius ti parla direttamente nella mente attraverso la pietra.$B$B\"Accettando l'incarico racchiuso in questa pietra del giuramento, accetti di aiutare la mia causa e quella dello stormo di Ysera nel redimere l'anima corrotta di Eranikus. Il primo sacrificio, uno dei tanti che senza dubbio tu e io faremo, sarà consegnarmi la gemma che tiene incatenato ciò che resta della parte libera della mente di Eranikus.\"$B$B\"Fallo, $N, e lavoreremo insieme per redimere un'anima degna di redenzione.\"",
  obj = "Porta l'Oathstone of Ysera's Dragonflight e la Chained Essence of Eranikus a Itharius, nella Swamp of Sorrows. Lì sceglierai se aiutare lo stormo di Ysera oppure no.",
  progress = "Eccoci, $N, a un altro bivio. È giunto il momento di fare un'altra scelta. Cosa scegli, mortale?",
  reward = "Hai fatto la tua scelta, e così comincia. Finora le tue scelte sono state quelle che considererei giuste; d'ora in poi, le tue azioni e le tue imprese decideranno se continuerà a essere così.",
  en_title = "The Essence of Eranikus",
  en_obj = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows.  It is there that you will make your choice to aid Ysera's Dragonflight or not.",
}
T[3376] = {
  title = "Spezza Sharptusk!",
  desc = "$N, ho sentito parlare di te, nuov$Go:a; arrivat$Go:a;. Forse sarai tu ad aiutarci, dove altri hanno fallito.$B$BNoi tauren ci siamo ricavati una casa in questa terra, ma non senza un prezzo. I quilboar Bristleback di Brambleblade Ravine, guidati dal Chief Sharptusk Thornmantle, ci rendono la vita difficile con la loro guerra incessante contro di noi. Ti incarico di portarmi la testa del capo!$B$BLo troverai nella gola a est, nel loro villaggio improvvisato.",
  obj = "Porta la testa del Chief Sharptusk Thornmantle a Brave Windfeather a Red Cloud Mesa.",
  progress = "Sharptusk non ci darà più problemi quando mi avrai portato la prova della sua morte. È la sua testa che cerco, $N.$B$BNoi tauren viviamo per la caccia, e non esiste caccia più grande di quella contro chi è abbastanza astuto da poterci dare la caccia a sua volta. Se avrai successo in questo compito, giovane, inizierai a capire cosa intendo.",
  reward = "Oggi è stata fatta giustizia grazie alla tua rapidità, $N. Che questa impresa sia un monito per chiunque minacci la nostra casa.$B$BTi sei guadagnat$Go:a; questa ricompensa per aiutarti nel tuo cammino, giovane $C.",
  en_title = "Break Sharptusk!",
  en_obj = "Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa.",
}
T[3512] = {
  title = "Con le parole di Eranikus",
  desc = "$N, il nostro primo passo sarà trovare un modo per parlare con Eranikus attraverso la gemma. Ora si trova in uno stato precario tra il sonno e la morte, avvolto in una trama di incubi. Anche se l'essenza che mi hai dato è gravemente corrotta, c'è la possibilità di raggiungerlo.$B$BViaggia lontano, fino alle terre gelide di Winterspring orientale, e cerca uno dei nostri alleati mortali, Umbranse the Spiritspeaker. È un medium umano che parla per i morti. Anche se Eranikus non è davvero morto, potrebbe comunque esserci d'aiuto.",
  obj = "Va' nella parte orientale di Winterspring e parla con Umbranse the Spiritspeaker.",
  reward = "Itharius ha fatto bene a mandarti da me. Anche se non è morto come tu intendi la morte, presto Eranikus ci darà consiglio con le sue stesse parole. Per ora, però, non posso aiutarti direttamente... almeno non ancora.$B$BMetterò al tuo servizio la mia abilità nel parlare con i morti, ma prima mi serve l'aiuto di qualcuno che, a differenza di me, non sia limitato dalle fragilità della vecchiaia. Il mio strumento di divinazione più potente mi è stato portato via contro la mia volontà, e se non lo riavrò non potremo aiutare Eranikus.",
  en_title = "In Eranikus' Own Words",
  en_obj = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.",
}
T[3513] = {
  title = "Il Runed Scroll",
  desc = "La pergamena, dall'aria ufficiale, è avvolta stretta in un nastro argenteo. Sei $Gsicuro:sicura; che a qualcuno interesserebbe vederla, ma a chi?$B$BC'è un avamposto vicino al confine di Ashenvale, a nord, e se le informazioni su questa pergamena riguardano gli elfi della notte, sarebbe quello il posto dove portarla.",
  obj = "Porta il Runed Scroll alla torre di guardia settentrionale delle Barrens.",
  progress = "Che hai lì?",
  reward = "Bene, bene... Dove l'hai trovata?",
  en_title = "The Runed Scroll",
  en_obj = "Take the Runed Scroll to the northern guard tower in the Barrens.",
}
T[3514] = {
  title = "Presenza dell'Orda",
  desc = "Questa pergamena viene da quella driade intrigante di Rynthariel, Keymaster del Talon Den su Stonetalon Peak.$B$BNon avrà più contatti con il messaggero da cui l'hai presa, eh, ma qui dobbiamo tenere la posizione. L'Orda non tollererà qui le sue staffette.$B$B$N, va' al Talon Den. Uccidi Rynthariel, e poi pianta un simbolo che tutti possano vedere. Prendi questa bandiera dell'Orda, $N. Piantala nel Talon Den, così non saranno più tanto avventati da mandare un altro messaggero nel nostro territorio.",
  obj = "Uccidi il capo del Talon Den, Rynthariel the Keymaster.",
  progress = "Non possiamo permettere all'Alleanza di stare sulla nostra terra, $N. Fallo sapere.",
  reward = "Sei $Guno tosto:una tosta;! Liberare il Den da Rynthariel è un passo importante, $N. Ci metteranno un po' a riorganizzarsi, e così possiamo contare su meno corrieri dell'Alleanza nelle Barrens. Ci penseranno due volte prima di mandarne un altro da queste parti.$B$BGrazie.",
  en_title = "Horde Presence",
  en_obj = "Kill the leader of the Talon Den, Rynthariel the Keymaster.",
}
T[3519] = {
  title = "Un amico in difficoltà",
  desc = "Uhhh... Sono stato morso malamente da un ragno di nome Githyiss the Vile mentre esploravo la caverna dei ragni qui vicino. Sono certo di essere stato avvelenato gravemente: devi aiutarmi.$B$BTi prego, avvisa Dirania Silvershine. Lei saprà come aiutarmi.$B$BSbrigati... Mi gira la testa...",
  obj = "Parla con Dirania Silvershine a Shadowglen.",
  reward = "Oh cielo; mi chiedevo perché oggi non avessi ancora visto Iverron. E l'ho sempre avvertito riguardo a quei ragni...",
  en_title = "A Friend in Need",
  en_obj = "Speak to Dirania Silvershine in Shadowglen.",
}
T[3521] = {
  title = "L'antidoto di Iverron",
  desc = "Forse possiamo aiutare Iverron: conosco un antidoto che dovrebbe funzionare contro il veleno. Ma servono alcuni ingredienti prima che io possa prepararlo.$B$BMi serviranno dei funghi Hyacinth. Li trovi che crescono sotto gli alberi, oppure puoi prenderli ai grell a sud di qui; sembra che li apprezzino molto. Mi serviranno anche dei Moonpetal Lily, che crescono solo vicino agli specchi d'acqua.$B$BL'ultimo ingrediente potrebbe rivelarsi il più difficile. Dagli stessi ragni che hanno avvelenato Iverron, raccogli del Webwood Ichor.",
  obj = "Raccogli 7 Hyacinth Mushroom, 4 Moonpetal Lily e 1 Webwood Ichor per Dirania Silvershine a Shadowglen.",
  progress = "Ti prego, raccogli gli ingredienti, $N. Iverron ha bisogno del nostro aiuto.",
  reward = "Sia ringraziata Elune, hai raccolto questi ingredienti così in fretta!$B$BTra un attimo l'antidoto sarà pronto.",
  en_title = "Iverron's Antidote",
  en_obj = "Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor for Dirania Silveshine in Shadowglen.",
}
T[3522] = {
  title = "L'antidoto di Iverron",
  desc = "L'antidoto è pronto, $N. Fai in modo che Iverron lo beva.$B$BC'è una cosa che devi sapere: l'antidoto rimarrà efficace solo per 5 minuti. Devi portarglielo in tempo.$B$BChe la velocità sia con te, $N.",
  obj = "Porta l'Iverron's Antidote a Iverron prima che scada il tempo. Iverron si trova vicino alla caverna a nord.",
  progress = "Oh... $N, sono così felice che tu sia tornat$Go:a;.",
  reward = "Cos'è questo, $N?$B$BOh, sapevo che Dirania avrebbe saputo aiutarmi!$B$B<Iverron beve l'antidoto>$B$BMi caccio sempre nei guai e Dirania, beh, riesce sempre a tirarmene fuori.$B$BMi sento molto meglio, ma credo che resterò seduto qui ancora un po', finché non starò del tutto bene. Beh, e speravo che mi aprissi un varco tra quei feroci ragni Webwood...",
  en_title = "Iverron's Antidote",
  en_obj = "Bring Iverron's Antidote to Iverron before the time limit is up. Iverron can be found by the cave to the north.",
}
T[3523] = {
  title = "Il Flagello dei Downs",
  desc = "Straordinario! Mi chiamo Belnistrasz, e ti ringrazio per avermi salvato. Mi ero già dato per morto... o peggio, per il pasto di questi parassiti infestati dal Flagello. Sì — ho detto proprio Flagello; hanno stretto una specie di patto con i quilboar di qui, e questo incubo ne è il risultato.$B$BAscolta... invece di fuggire e basta, voglio fare qualcosa di concreto, per il bene di tutti noi. Te la sentiresti di aiutarmi in questo? Probabilmente è pericoloso, ma mi sembri il tipo che non se ne preoccupa troppo.",
  obj = "Se accetti di aiutare Belnistrasz, parla di nuovo con lui e restituiscigli Belnistrasz's Oathstone che ti ha dato.",
  progress = "La politica non fa per me; non mi importa se stai con l'Orda o con l'Alleanza. Mi interessa di più schiacciare le minacce dirette e terribili per tutte le razze... e qui dentro ne abbiamo una bella grossa.$B$BSe vuoi essere $Gun vero eroe:una vera eroina; per tutti, allora dammi la pietra del giuramento che ti ho dato, come segno del tuo impegno. Io... non sono di queste parti; per quelli come me, una pietra del giuramento è importante come vincolo di un accordo.",
  reward = "Fantastico, mi sembravi proprio il tipo eroico! Ci aspetta un lavoro difficile, $N, non ti mentirò. Se restiamo concentrati sul compito che abbiamo davanti, dovremmo riuscire a spuntarla.$B$BOra lascia che ti metta al corrente di quello che sta succedendo...",
  en_title = "Scourge of the Downs",
  en_obj = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.",
}
T[3524] = {
  title = "Spiaggiato",
  desc = "È noto che maestose creature marine si lanciano contro la costa di Darkshore, restando spiaggiate fino alla morte. Ultimamente queste bestie arrivano a riva in numero sempre maggiore. Sono stata mandata qui dal Temple of the Moon per indagare, ma la presenza di murloc lungo la riva rende difficile la mia ricerca.$B$BC'è una creatura gigantesca spiaggiata subito a sud di Auberdine, circondata dai vili murloc Greymist. Potresti andare là e recuperare delle ossa della creatura per il nostro studio?",
  obj = "Recupera delle Sea Creature Bones dalla creatura marina spiaggiata subito a sud di Auberdine, poi torna da Gwennyth Bly'Leggonde ad Auberdine.",
  progress = "È solo da poco che queste creature hanno cominciato ad approdare sulla costa di Darkshore in numero così allarmante. Non posso fare a meno di pensare che sia un cattivo presagio. Recuperare un campione delle ossa di quella creatura a sud aiuterebbe noi di Darnassus a valutare la situazione!",
  reward = "Spero che i murloc non ti abbiano dato troppi problemi nel raccoglierle per noi! Mi assicurerò che arrivino sul prossimo ippogrifo diretto a Darnassus. Il Temple of the Moon mi ha dato dei fondi da distribuire a chi ci aiuta: prendine un po', con i nostri ringraziamenti.$B$BIl tuo successo qui mi spinge a offrirti la possibilità di aiutare ancora il Temple of the Moon, se ti interessa...",
  en_title = "Washed Ashore",
  en_obj = "Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine.",
}
T[3525] = {
  title = "Spegnere l'idolo",
  desc = "Vicino all'ingresso c'è un idolo che fa da forno macabro per i quilboar; quelle bestie... divorano letteralmente le persone che rapiscono nelle Barrens. Posso spegnere l'idolo e impedire che lo usino di nuovo, ma per farlo mi serve il tuo aiuto. Il mio piano: scortami fino all'idolo. Una volta arrivati, comincerò il rituale. Riuscirò a stento a comunicare con te, figurarsi a difendermi. Proteggimi mentre spengo l'idolo. Se mi abbattono, per noi è finita.$B$BSei con me?!",
  obj = "Scorta Belnistrasz fino all'idolo dei quilboar, a Razorfen Downs.$B$BProteggi Belnistrasz mentre esegue il rituale per spegnere l'idolo.",
  reward = "L'improvvisa partenza di Belnistrasz ha lasciato dietro di sé un braciere ardente. Mentre fissi la fiamma, l'immagine di un grande drago rosso dalle ampie ali ti riempie la mente. La voce di Belnistrasz, più roca, ti parla direttamente.$B$B\"Davvero, mortali, siete gli eroi che speravo. Grazie a voi, il massacro che queste bestie compivano appartiene al passato. La mia fiducia nei mortali come te si è rinnovata ancora una volta. Prendi questo come ricompensa degna di $Gun eroe:un'eroina;.\"",
  en_title = "Extinguishing the Idol",
  en_obj = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.$B$BProtect Belnistrasz while he performs the ritual to shut down the idol.",
}
T[3526] = {
  title = "Ingegneria goblin",
  desc = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Ovviamente, l'ingegneria goblin è la scelta di tutti gli ingegneri brillanti. Impara a dominare il mondo con l'uso giudizioso di esplosivi ad alto potenziale e di attrezzature fantastiche!$B$B$N, leggi questo manuale. Se vuoi imparare l'ingegneria goblin, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.",
  obj = "Se vuoi saperne di più sull'ingegneria goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.",
  progress = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?",
  reward = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'ingegneria goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).$B$BTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[3527] = {
  title = "La profezia di Mosh'aru",
  desc = "L'antica profezia di Mosh'aru parla di un modo per imprigionare l'essenza del dio Hakkar. Fu scritta su due tavolette e portata nella città troll di Zul'Farrak, a ovest di Gadgetzan.$B$BPortami le tavolette di Mosh'aru!$B$BLa prima tavoletta è custodita dal troll morto da tempo Theka the Martyr. Si dice che i suoi persecutori siano stati tramutati per maledizione in scarabei, e che ora zampettino intorno al suo santuario.$B$BLa seconda tavoletta è custodita dall'idromante Velratha, vicino alla vasca sacra di Gahz'rilla.$B$BQuando avrai le tavolette, portamele.",
  obj = "Porta la First Mosh'aru Tablet e la Second Mosh'aru Tablet a Yeh'kinya, a Tanaris.",
  progress = "Hai le tavolette della profezia di Mosh'aru, $N?$B$BQuando avrò le tavolette, le studierò e imparerò come imprigionare l'essenza di Hakkar!",
  reward = "Ah, questo è un bene. Posso fondere insieme queste antiche tavolette, e poi studiarne i segreti nascosti.$B$BIl mio debito con te cresce, $N. E crescerà ancora.",
  en_title = "The Prophecy of Mosh'aru",
  en_obj = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.",
}
T[3567] = {
  title = "Fino in cima",
  reward = "Ti piacerebbe vedere il panorama dalla cima di uno dei Twin Colossals? Posso mandartici io, $R.$B$BPensa però a come farai a scendere. È un viaggio di sola andata.",
  en_title = "To the Top",
}
T[3625] = {
  title = "Armi demoniache di Azsharite incantate",
  desc = "$N, la creazione di ogni arma richiederà un po' di tempo.$B$BInoltre, potrai usare il potere del Felcurse solo una volta ogni tre minuti. I suoi effetti indebolenti su Razelikh the Defiler e sui suoi servitori potrebbero avere una durata variabile. Per questo devi liberare il Felcurse solo al momento giusto!$B$BOra dammi un momento per forgiare la tua arma, $N.",
  obj = "Aspetta che Galvan finisca di forgiare le armi.",
  progress = "Interrompere la forgiatura potrebbe dare un'arma imperfetta. Abbi pazienza, $N.",
  reward = "<Galvan si asciuga il sudore dalla fronte.>$B$BNon è mai esistito un ammazzademoni migliore, $N.",
  en_title = "Enchanted Azsharite Fel Weaponry",
  en_obj = "Wait for Galvan to finish forging the weaponry.",
}
T[3626] = {
  title = "Ritorno nelle Blasted Lands",
  desc = "L'ora della redenzione è vicina, $N. Devi tornare nelle Blasted Lands con le tue nuove armi e parlare con il Fallen Hero of the Horde per ricevere il tuo ultimo obiettivo.",
  obj = "Torna dal Fallen Hero of the Horde.",
  reward = "Sembri $Gtemprato:temprata; dalle battaglie, $N. Sei $Gpronto:pronta; ad affrontare Razelikh e i suoi servitori?",
  en_title = "Return to the Blasted Lands",
  en_obj = "Return to the Fallen Hero of the Horde.",
}
T[3629] = {
  title = "Ingegneria goblin",
  desc = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Mi prendo la briga di nominare l'ingegneria goblin solo perché sono un istruttore imparziale. Agli ingegneri goblin piace costruire cose che esplodono, e raramente badano a cosa si trovi sulla loro strada — nemmeno quando si tratta di loro stessi.$B$B$N, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.",
  obj = "Se vuoi saperne di più sull'ingegneria goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.",
  progress = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?",
  reward = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'ingegneria goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).$B$BTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[3630] = {
  title = "Ingegneria gnomica",
  desc = "A livello esperto, l'ingegneria si divide in due discipline: gnomica e goblin. L'ingegneria gnomica è di gran lunga la migliore delle due! Si tratta di costruire congegni e dispositivi meravigliosi che migliorano la vita!$B$B$N, leggi questo manuale. Se vuoi saperne di più sull'ingegneria gnomica, porta il manuale a Tinkmaster Overspark, a Ironforge. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi accertati di esserne $Gsicuro:sicura; prima di portare a termine il suo incarico!",
  obj = "Se vuoi saperne di più sull'ingegneria gnomica, porta il Manual of Engineering Disciplines a Tinkmaster Overspark, a Ironforge.",
  progress = "Sì, sì, a quali tue esigenze posso dedicarmi oggi? Evidentemente ho tutto il tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.",
  reward = "Ah, $Gun giovane ingegnere:una giovane ingegnera; che vuole seguire l'unica, vera disciplina dell'ingegneria! Be', perdona il mio melodramma, $Gamico:amica;. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando si vede $Gun altro ingegnere:un'altra ingegnera; rispondere alla chiamata della vera ingegneria!",
  en_title = "Gnome Engineering",
  en_obj = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.",
}
T[3632] = {
  title = "Ingegneria gnomica",
  desc = "A livello esperto, l'ingegneria si divide in due discipline: gnomica e goblin. L'ingegneria gnomica è di gran lunga la migliore delle due! Si tratta di costruire congegni e dispositivi meravigliosi che migliorano la vita!$B$B$N, leggi questo manuale. Se vuoi saperne di più sull'ingegneria gnomica, porta il manuale a Tinkmaster Overspark, qui a Ironforge. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi accertati di esserne $Gsicuro:sicura; prima di portare a termine il suo incarico!",
  obj = "Se vuoi saperne di più sull'ingegneria gnomica, porta il Manual of Engineering Disciplines a Tinkmaster Overspark, a Ironforge.",
  progress = "Sì, sì, a quali tue esigenze posso dedicarmi oggi? Evidentemente ho tutto il tempo per farlo, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.",
