T[3644] = {
  title = "Rinnovo della tessera d'iscrizione",
  progress = "Per rinnovare la tua tessera d'iscrizione, dovrai pagare la quota di rinnovo di due monete d'oro.",
  reward = "Visto che pratichi l'ingegneria goblin e sei in regola, posso rinnovarti una tessera d'iscrizione scaduta per la quota di due monete d'oro. Una volta pagata la quota, ti verrà rilasciata una nuova tessera. Ti permetterà di accedere agli schemi d'ingegneria goblin presso gli istruttori competenti.$B$BQuesta tessera durerà due settimane di attività, al termine delle quali dovrai pagare di nuovo la quota d'iscrizione! Se vuoi accedere agli schemi, dovrai metterti in pari con i pagamenti arretrati.",
  en_title = "Membership Card Renewal",
}
T[3645] = {
  title = "Rinnovo della tessera d'iscrizione",
  progress = "Per rinnovare la tua tessera d'iscrizione, dovrai pagare la quota di rinnovo di due monete d'oro.",
