T[3681] = {
  title = "Tome of Divinity",
  desc = "Scusa se interrompo i tuoi viaggi, $R, ma ho pensato che dovessi sapere che di recente è arrivato un messaggio da Stormwind che chiede ai paladini di presentarsi là per l'addestramento.$B$BSe non sbaglio, direi che sei $Gvicino:vicina; a un momento speciale, ed è ora che cominci a studiare i Tome.$B$BCerca Duthorian Rall a Stormwind. Di solito addestra i paladini nella Cathedral of Light.",
  obj = "Parla con Duthorian Rall, a Stormwind.",
  reward = "$GBenvenuto:Benvenuta; nella Cathedral of Light, $C.",
  en_title = "Tome of Divinity",
  en_obj = "Speak with Duthorian Rall in Stormwind.",
}
T[3741] = {
  title = "La collana di Hilary",
  desc = "La mia amica Hilary ha perso la collana e non riusciamo a trovarla. Abbiamo pescato qui tutto il giorno e abbiamo già cercato qui intorno. L'unica cosa che mi viene in mente è che sia caduta nel lago. I nostri genitori non vogliono che nuotiamo nel lago... mia mamma dice che sott'acqua ci sono cose cattive, ma tu non sembri uno che ha paura delle cose cattive.$B$BPotresti trovarla per lei, per favore?",
  obj = "Trova la collana di Hilary e riportala a Hilary a Lakeshire.",
  progress = "Ciao. Mi manca la mia collana. Me l'ha regalata il mio papà. Papà dice che nel lago ci sono dei mostri. Hai picchiato qualche mostro?",
  reward = "Grazie per aver trovato la mia collana, signor $C... sei molto gentile! Anche il mio gattino ti ringrazia, vero Effsee?",
  en_title = "Hilary's Necklace",
  en_obj = "Find Hilary's Necklace, and return it to Hilary in Lakeshire.",
}
T[3761] = {
  title = "Un'Goro Soil",
  desc = "Si dice che la terra dell'Un'Goro Crater sia ricca di potenti qualità magiche. Il Cenarion Circle vuole studiarla in grandi quantità; addentrati nelle terre selvagge di Un'Goro e procuratene abbastanza per proseguire le nostre ricerche.$B$BQua e là la terra fertile affiora in mucchi, e alcune bestie potrebbero averne addosso dei campioni utilizzabili. Portali tutti fuori, da Ghede; basta cercare i mucchi di terra e il tauren che abbaia ordini. Ha buone intenzioni, ma non farlo arrabbiare!",
  obj = "Porta 20 Un'Goro Soil a Ghede, sull'Elder Rise di Thunder Bluff.",
  progress = "Riposo, $Gsoldato:soldatessa;. Se sei qui per scaricare terra di Un'Goro, magnifico! Altrimenti, sparisci.",
  reward = "Ma certo, $Gsoldato:soldatessa; $N, non fare il minimo sforzo per aiutarmi a scaricare questa terra sui mucchi! Se i Grandi Spiriti avessero voluto che fosse fatto, ce l'avrebbero portata lassù per miracolo, non ti pare?!$B$BArch Druid Runetotem vuole parlarti di nuovo, ma per il suo prossimo incarico scopri che ti sarebbe utile una conoscenza dell'erbalismo di livello Journeyman. Se però non ce l'hai, troverà comunque un modo di impiegarti.",
  en_title = "Un'Goro Soil",
  en_obj = "Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.",
}
T[3762] = {
  title = "Aiutare Arch Druid Runetotem",
  desc = "Scusami, $C, ma vorrei solo un momento del tuo tempo, se possibile.$B$BIl Cenarion Circle di Thunder Bluff è molto interessato ad avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Hamuul Runetotem.$B$BTi prego, se ti interessa, parla direttamente con lui sull'Elder Rise, dentro Thunder Bluff.",
  obj = "Parla con Arch Druid Hamuul Runetotem, a Thunder Bluff.",
  reward = "Salve, $C; sono lieto che tu voglia aiutare la nostra ricerca. C'è molto da fare, e ti renderei un cattivo servizio se ti dicessi che questo lavoro non è pericoloso. Spero che questo non ti spaventi... ma, a giudicare dal tuo aspetto, direi che col pericolo hai già avuto a che fare.",
  en_title = "Assisting Arch Druid Runetotem",
  en_obj = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.",
}
T[3765] = {
  title = "La corruzione lontano da qui",
  desc = "Stormwind — che centro brulicante di attività.$B$BHo viaggiato da lontano per cercare aiuto. Si sente dire spesso che avventurieri coraggiosi girano per queste strade.$B$BMio fratello, Gershala, ha bisogno di aiuto a Darkshore. Vive nella cittadina di mare di Auberdine.$B$BÈ un viaggio lungo ed epico. Per questo chiedo l'aiuto di $Gun:una; $C $Gesperto:esperta; come te.",
  obj = "Raggiungi Gershala Nightwhisper, ad Auberdine.",
  reward = "Ah, quindi ti manda mio fratello, Argos? Immagino che tu sia $Gstanco:stanca; per il viaggio. Ma abbiamo molto di cui parlare.",
  en_title = "The Corruption Abroad",
  en_obj = "Travel to Gershala Nightwhisper in Auberdine.",
}
T[3782] = {
  title = "Ricerche sulla Morrowgrain",
  desc = "Con quella che chiamiamo Evergreen Pouch, abbiamo coltivato semi di Tharlendris nella terra dell'Un'Goro Crater. Da questi semi sono sbocciate, in modo imprevedibile, erbe potenti di ogni genere. Una di queste è la Morrowgrain, un'erba misteriosa di cui sappiamo poco; spero davvero di svelare questo mistero per il Circle.$B$BPorta questo buono a mia figlia Bashana, e lei ti darà dei semi, così potrai aiutarci. Se li finisci, dovrai comprarne altri da lei.",
  obj = "Porta il Seed Voucher a Bashana Runetotem, a Thunder Bluff.",
  progress = "Pace a te, $Gamico:amica;. Sei qui per conto dell'arcidruido in persona, vero?",
  reward = "Sì, questo buono vale venti pacchetti di semi. Se finisci i semi, ne ho altri che posso venderti.$B$BPurtroppo, $N, produrre semi di Tharlendris in quantità significative è piuttosto costoso. Per questo il Cenarion Circle chiede a chi ci aiuta di contribuire coprendo parte della spesa. Chi torna con la Morrowgrain scopre che la ricompensa offerta dall'arcidruido ripaga ampiamente la spesa.",
  en_title = "Morrowgrain Research",
  en_obj = "Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.",
}
T[3786] = {
  title = "Ricerche sulla Morrowgrain",
  desc = "Ecco la tua Evergreen Pouch, che ti servirà per usare i semi di Tharlendris. Devi avere a portata di mano anche dei campioni di Un'Goro Soil, da usare come fertilizzante per i semi. Usa la sacca quando hai tutto; al resto penserà lei.$B$BQuando avrai abbastanza Morrowgrain, portala a me, qui sull'Elder Rise. Per favore, non disturbare l'arcidruido; sarà molto impegnato con la ricerca, oltre che con le mille preoccupazioni che ha!",
  obj = "Usa una Evergreen Pouch con un Packet of Tharlendris Seeds e due Un'Goro Soil per provare a coltivare campioni di Morrowgrain.$B$BPorta 10 Morrowgrain a Bashana Runetotem, a Thunder Bluff.",
  progress = "Sì, $N, hai coltivato un po' di Morrowgrain per l'importante ricerca dell'arcidruido? Le misteriose proprietà dell'Un'Goro Crater diventano più chiare ogni giorno che passa, grazie all'aiuto che ci stai dando.",
  reward = "Ben fatto, $N, mi assicurerò di consegnarla all'arcidruido in persona quando ne avrà bisogno. Nel frattempo, accetta questo come segno di gratitudine del Cenarion Circle.$B$BPer ora il nostro bisogno di Morrowgrain è costante; se vuoi continuare ad aiutarci, torna quando ne avrai coltivata altra.",
  en_title = "Morrowgrain Research",
  en_obj = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.$B$BBring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.",
}
T[3787] = {
  title = "La richiesta di Jonespyre",
  desc = "Scusami, $Gamico:amica;...$B$BUn mio collega vorrebbe parlarti delle ricerche che stai facendo insieme al Cenarion Circle. È un druido di nome Quintis Jonespyre, e vive a Feathermoon Stronghold, nel Feralas. Vorrebbe confrontarsi con te sulla morrowgrain... e ci terrebbe molto che la nostra conversazione non arrivasse alle orecchie dell'arcidruido.$B$BSe ti interessa, parla con lui; di sicuro, una volta che l'avrai fatto, tutto ti sarà svelato.",
  obj = "Parla con Quintis Jonespyre a Feathermoon Stronghold.",
  reward = "Ti ringrazio di essere $Gvenuto:venuta;, $Gstanco viandante:stanca viandante;! Permettimi di presentarmi: sono Quintis Jonespyre, druido e umile servitore di Malfurion e del Cenarion Circle. I miei colleghi (General Shandris Feathermoon e il Protectorate: forse hai sentito parlare di noi) e io volevamo parlarti del lavoro che stai facendo per Fandral Staghelm a Darnassus.$B$BPrima di andare oltre, vorrei chiederti che la nostra conversazione resti fra noi. Se per te va bene, possiamo proseguire.",
  en_title = "Jonespyre's Request",
  en_obj = "Speak with Quintis Jonespyre in Feathermoon Stronghold.",
}
T[3789] = {
  title = "Aiutare Arch Druid Staghelm",
  desc = "Scusami, $C, ma vorrei solo un momento del tuo tempo, se possibile.$B$BIl Cenarion Circle di Darnassus cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Arch Druid Fandral Staghelm.$B$BTi prego, se ti interessa, parla direttamente con lui nel Cenarion Enclave, a Darnassus.",
  obj = "Parla con Arch Druid Fandral Staghelm a Darnassus.",
  reward = "Bene, $C... visto che ti hanno detto che sono io a guidare questa ricerca, sei $Gvenuto:venuta; più in fretta che potevi, è evidente.$B$BOra che sei qui, mi raccomando, fa' attenzione la prima volta che ti spiego i dettagli: non ho nessuna voglia di ripetermi.",
  en_title = "Assisting Arch Druid Staghelm",
  en_obj = "Speak with Arch Druid Fandral Staghelm in Darnassus.",
}
T[3804] = {
  title = "Morrowgrain per Thunder Bluff",
  progress = "L'arcidruido cerca sempre altra Morrowgrain per il progetto di ricerca del Cenarion Circle sull'Un'Goro Crater. La accettiamo a gruppi di dieci, e in cambio ti diamo una scorta di beni che dovresti trovare utili. Quando ne avrai dieci, fammelo sapere e ti ricompenserò di conseguenza.",
  reward = "Eccellente — questa Morrowgrain sarà senza dubbio utile quando verrà il momento. Sappiamo che gli elfi della notte stanno conducendo ricerche simili su queste erbe, anche se non è chiaro a che scopo le useranno, se scopriranno qualcosa. L'arcidruido pensa che il bisogno di Morrowgrain resterà finché non avremo svelato i misteri di quest'erba.$B$BQuesto è per te, $N. Il Cenarion Circle ti ringrazia per il tuo costante sostegno.",
  en_title = "Morrowgrain to Thunder Bluff",
}
T[3821] = {
  title = "Dreadmaul Rock",
  desc = "Sha'ni è stata mandata a indagare su strane attività rituali segnalate tra gli ogre Firegut delle Burning Steppes, più di tre settimane fa.$B$BGoretooth mi dice che non ha avuto notizie da nessuno di quel plotone e che è meglio che io vada avanti e mi concentri sul compito che ho davanti. Ci credi? È mia moglie!$B$BNon posso lasciare il mio posto, $N, ma devo sapere che fine ha fatto Sha'ni. Va' nelle Burning Steppes e cercala.",
  obj = "Avventurati nelle Burning Steppes e scopri che fine ha fatto Sha'ni Proudtusk.",
  reward = "Il mio povero Thal'trak.$B$BAvevamo in programma di andare a vivere con mia madre e mio padre nelle Hinterlands, finito il servizio. Ora quei progetti sono rovinati!",
  en_title = "Dreadmaul Rock",
  en_obj = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.",
}
T[3901] = {
  title = "Scuotere i Rattlecage",
  desc = "Hai mostrato il tuo valore ai Forsaken in circostanze normali, $N: ora vediamo come te la cavi sotto pressione.$B$BGli scheletri Rattlecage, altri servi senza cervello del Lich King, sono un nemico più ostico degli zombie che hai affrontato finora. Ancora una volta, assottiglia le loro fila e dimostra il tuo valore ai Forsaken. Non indugiare: quando avrai finito, parla di nuovo con me.",
  obj = "Uccidi 12 Rattlecage Skeleton, poi torna dallo Shadow Priest Sarvis a Deathknell quando avrai finito.",
  progress = "Chi si attarda in questo compito potrebbe finire a vagare senza meta come i nostri fratelli e sorelle caduti nel villaggio. Speriamo che tu faccia meglio di loro, sì? $B$B",
  reward = "Con te ho finito, $N: ti sei dimostrat$Go:a; degn$Go:a; della libertà che ti è stata donata. Molti si opporranno a te per ciò che sei diventat$Go:a;, ma sappi che, qualunque cosa tentino contro di noi, siamo liberi e non saremo mai più incatenati.$B$BPrendi questi e va' per la tua strada. Hai molto da compiere, $C.",
  en_title = "Rattling the Rattlecages",
  en_obj = "Kill 12 Rattlecage Skeletons, and then return to Shadow Priest Sarvis in Deathknell when you are done.",
}
T[3902] = {
  title = "Rovistare a Deathknell",
  desc = "Ehi, tu! Se cerchi qualcosa per renderti utile, ascolta bene!$B$BCi servono reclute appena uscite dalla terra che vadano a Deathknell e cerchino qualsiasi equipaggiamento utile. Molto probabilmente si trova nelle pile di casse. Ci aspettiamo che presto sorgano altre reclute e, a meno che non vogliamo vederle andare in giro nude, è meglio darsi da fare a rovistare!$B$BAllora al lavoro, miserabile sacco di ossa! Non ricompenserò chi non si dà una mossa.",
  obj = "Cerca a Deathknell e nei dintorni 6 Scavenged Goods e portali al Deathguard Saltain.",
  progress = "Sei riuscit$Go:a; a recuperare qualche oggetto utile per noi? Non c'è vergogna nel riutilizzare ciò che è stato gettato via. Nessuno ci farà regali: noi Forsaken ci arrangeremo da soli!",
  reward = "Ottimo lavoro $N, sapevo che non eri inutile. Tieni: prendi uno degli oggetti migliori che ho trovato tra quelli raccolti finora.",
  en_title = "Scavenging Deathknell",
  en_obj = "Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.",
}
T[3903] = {
  title = "Milly Osworth",
  desc = "Ti sei dimostrat$Go:a; $Gun:una; $C affidabile, $N. Affidabile e per niente timoros$Go:a; di sporcarti le mani, eh?$B$BHo un'amica, Milly Osworth, che è nei guai. Si trova col suo carro dall'altra parte dell'abbazia, vicino alle stalle. Sono certo che una coppia di mani come le tue le farebbe comodo.",
  obj = "Parla con Milly Osworth.",
  reward = "Oh, il Deputy Willem ti ha detto di parlare con me? È un uomo coraggioso e sempre pronto ad aiutare, ma i suoi doveri lo tengono bloccato a Northshire Abbey e temo che il problema che ho oggi sia oltre le sue possibilità.$B$BForse puoi aiutarmi tu?",
  en_title = "Milly Osworth",
  en_obj = "Speak with Milly Osworth.",
}
T[3904] = {
  title = "Il raccolto di Milly",
  desc = "Una banda di briganti, i Defias, si è insediata nei Northshire Vineyards mentre stavo raccogliendo! L'ho riferito alle guardie di Northshire e mi hanno assicurato che se ne occuperanno, ma... temo per il mio raccolto d'uva! Se i Defias non lo rubano, ho paura che le nostre guardie lo calpestino mentre scacciano quei furfanti.$B$BTi prego, devi aiutarmi! Ho messo la maggior parte dell'uva in dei secchi, ma li ho lasciati nei vigneti a sudest.$B$BPortami quei secchi! Salva il mio raccolto!",
  obj = "Porta 8 casse di Milly's Harvest a Milly Osworth a Northshire Abbey.",
  progress = "Hai il mio raccolto, $N?",
  reward = "Oh, grazie, $N! Hai salvato il mio raccolto! Spero che tu abbia fatto capire a quei Defias che qui non possono creare problemi.$B$BForse di questi tempi abbiamo poche guardie, ma siamo fortunati ad avere eroi come te a proteggerci!",
  en_title = "Milly's Harvest",
  en_obj = "Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.",
}
T[3905] = {
  title = "Il registro dell'uva",
  desc = "Ora che il mio raccolto è salvo, porta questo Grape Manifest a Brother Neals. Si occupa delle scorte di cibo e bevande a Northshire, e sono certa che sarà felicissimo di sapere che ha uva fresca.$B$BTroverai Brother Neals nell'abbazia, nel campanile... dove ama assaggiare il suo vino.",
  obj = "Porta il Grape Manifest a Brother Neals a Northshire Abbey.",
  progress = "Sembri di ottimo umore! Vieni! Siediti e bevi qualcosa!",
  reward = "Vediamo un po'...$B$BOh cielo! L'uva di Milly è salva! Quando mi ha detto che dei briganti avevano invaso i suoi vigneti ho quasi disperato, ma la mia fede nella Luce non ha vacillato!$B$BE grazie al tuo coraggio ora avremo uva per altro vino! Che la Luce ti benedica, $N, e ti protegga!",
  en_title = "Grape Manifest",
  en_obj = "Bring the Grape Manifest to Brother Neals in Northshire Abbey.",
}
T[3921] = {
  title = "Wenikee Boltbucket",
  desc = "Credo di aver rotto quel Samophlange. Non va bene, perché ne ho già parlato ad alcuni colleghi di Undermine e ne erano molto incuriositi. Dobbiamo trovare un modo per ripararlo!$B$BPorta il samophlange rotto a Wenikee Boltbucket, appena a sud di Mor'shan Rampart, l'avamposto dell'Orda tra i Barrens e Ashenvale. È molto intelligente e curiosa. Se le mostri il samophlange, scommetto che non si lascerà sfuggire l'occasione di ripararlo.",
  obj = "Porta il Broken Samophlange a Wenikee Boltbucket.",
  progress = "Sono molto occupata con il mio lavoro, $C. A meno che tu non abbia qualcosa per me, faresti meglio a levarti di torno...",
  reward = "Oh, cos'è questo? Un samophlange, dici? Che cos'è un samophlange??$B$BAh... ma guarda come si muove quando lo maneggi. E senti il rumore di ingranaggi complessi all'interno. Oh cielo! Voglio ripararlo e vedere cosa fa, e tu no??",
  en_title = "Wenikee Boltbucket",
  en_obj = "Bring the Broken Samophlange to Wenikee Boltbucket.",
}
T[3922] = {
  title = "Nugget Slugs",
  desc = "Voglio riparare questo samophlange, ma per farlo mi serviranno delle scorte. Ho finito i nugget slug calibro diciassette virgola cinque e me ne serviranno un bel po' per il lavoro che mi aspetta.$B$BIl posto più vicino dove trovarli è il Sludge Fen, a est. La Venture Company di solito li tiene nelle sue cassette degli attrezzi. Vai al Sludge Fen e cerca nelle cassette degli attrezzi che troverai, poi torna da me quando avrai raccolto abbastanza nugget slug.",
  obj = "Porta 15 Nugget Slugs a Wenikee Boltbucket nei Barrens.",
  progress = "Hai i nugget slug, $N? Ho gli occhi puntati su questo Samophlange e non vedo l'ora di metterci le mani.",
  reward = "Ottimo, li hai presi! Ora posso mettermi al lavoro...",
  en_title = "Nugget Slugs",
  en_obj = "Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens.",
}
T[3923] = {
  title = "Rilli Greasygob",
  desc = "Beh, non ha funzionato. Ho aggiunto qualche indicatore al samophlange per misurarne l'integrità strutturale, e segnano un livello più basso che mai. Potrei aggiungere altri quadranti e magari una leva o due per provare a ripararlo, ma... credo che peggiorerebbe solo le cose.$B$BDovresti portare il samophlange da Rilli Greasygob. Lavorava per la Venture Company: se qualcuno sa come ripararlo, è Rilli.$B$BLo trovi al Nogg's Machine Shop a Orgrimmar, nella Valley of Honor.",
  obj = "Porta il Broken and Battered Samophlange a Rilli Greasygob a Orgrimmar.",
  progress = "Attento alla testa! Non voglio che intralci il mio lavoro!",
  reward = "Cos'è questo? Ma è un samophlange! Dove hai trovato questa cosa? Sei andat$Go:a; a ficcare il naso nei possedimenti della Venture Company nei Barrens?$B$BDevi essere molto coraggios$Go:a;, o molto stupid$Go:a;.",
  en_title = "Rilli Greasygob",
  en_obj = "Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar.",
}
T[3924] = {
  title = "Il manuale del Samophlange",
  desc = "Credo di poter riparare il samophlange, ma prima mi serve il manuale d'uso. Quando ero nella Venture Company avevo un rivale, Boss Copperplug, che custodiva gelosamente i segreti del samophlange, concedendo piccole nozioni sul congegno solo a chi si fidava di lui. Io non ero tra i fortunati...$B$BBoss Copperplug stava di solito alla Boulder Lode Mine, nei Barrens nordorientali. Prendigli il manuale, e se ha dato delle pagine a qualcuno, dovrai recuperare anche quelle.",
  obj = "Porta il Samophlange Manual a Rilli Greasygob a Orgrimmar.",
  progress = "Hai il manuale?",
  reward = "Hai il manuale! Non vedo l'ora di leggerlo e scoprire come riparare il Samophlange! Ho parlato con Sputtervalve a Ratchet: voleva ringraziarti per il tuo aiuto e ricompensare i tuoi sforzi.$B$BVoglio ringraziarti anch'io, e se mai riuscirò a ripararlo te lo farò sapere...",
  en_title = "Samophlange Manual",
  en_obj = "Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar.",
}
T[4021] = {
  title = "Contrattacco!",
  desc = "L'Orda elogia i tuoi successi contro i Kolkar, ma i Kolkar stessi sono furiosi. Ho notizia che un contingente di Kolkar è giunto nei Barrens dalla sua patria, Desolace, in cerca di vendetta. L'ultimo rapporto diceva che, proprio ora, avanzano contro questi bunker da ovest!$B$BAffronta gli invasori Kolkar e poni fine alla loro minaccia nei Barrens. Uccidili finché non comparirà il loro capo, Warlord Krom'zar. Sconfiggilo e portami un pezzo del suo stendardo come prova.$B$BContiamo su di te, $N.",
  obj = "Porta un Piece of Krom'zar's Banner a Regthar Deathgate, a ovest di Crossroads.",
  progress = "Hai lo stendardo?",
  reward = "Ce l'hai fatta! Hai sconfitto i Kolkar!$B$BMi assicurerò che Thrall riceva notizia delle tue gesta qui, $N.$B$BTieni la testa alta. Fai onore a te stess$Go:a; e all'Orda.",
  en_title = "Counterattack!",
  en_obj = "Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.",
}
T[4062] = {
  title = "L'ascesa delle macchine",
  desc = "G.L.A.$B$BSono queste le \"iniziali\" impresse sui frammenti elementali. Sotto le iniziali c'è una specie di segno di grado. Le macchine che hai distrutto nelle Burning Steppes erano di \"Rank IV\". Presumo che sia un grado basso.$B$BPorta questo campione di frammento a Lotwil Veriatus, nell'accampamento a est. È uno studioso di una certa fama nel campo delle scienze elementali. Potrebbe aiutarci nella nostra ricerca.",
  obj = "Porta l'Elemental Shard Sample a Lotwil Veriatus.$B$BRicordi che Theodora ha detto che Lotwil si trovava in un accampamento a est.",
  progress = "Cos'hai lì, $R?",
  reward = "<Il volto di Lotwil diventa bianco.>$B$BIo... io conosco questi segni.",
  en_title = "The Rise of the Machines",
  en_obj = "Take the Elemental Shard Sample to Lotwil Veriatus.$B$BYou recall Theodora saying that Lotwil was stationed in a camp to the east.$B",
}
T[4124] = {
  title = "Il corriere scomparso",
  desc = "Un mio collega, Ginro Hearthkindle, cerca aiuto per ritrovare un corriere e i pacchi che portava. È passata una settimana circa da quando il corriere è scomparso; le nostre ricerche non hanno dato frutti, e siamo a un punto morto. Purtroppo ho dovuto dichiarare il corriere disperso in azione.$B$BSe hai tempo e risorse da dedicarci, ti prego, parla con Ginro. Dovrebbe essere qui alla roccaforte, forse nei suoi alloggi.",
  obj = "Parla con Ginro Hearthkindle, alla Feathermoon Stronghold.",
  reward = "Ti manda Latro, immagino. Anche se a questo punto credo sia una causa persa, accetterò qualunque aiuto tu possa offrire. Devo ammetterlo... sarò contento quando potrò mettermi il cuore in pace su questa faccenda. Ogni giorno parto per le terre selvagge di Feralas in cerca di tracce di Raschal, e ogni sera torno senza niente da mostrare per il mio lavoro, a parte denti di gnoll e delusione.",
  en_title = "The Missing Courier",
  en_obj = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
}
T[4125] = {
  title = "Il corriere scomparso",
  desc = "È passata circa una settimana da quando Raschal, il corriere, è partito per Thalanaar. Conosce bene Feralas; è con noi da quando il generale Feathermoon ha guidato qui le forze di spedizione. So che il suo piano era prendere una barca a remi, scendere lungo la costa e poi provare ad attraversare il sud di Feralas per evitare il campo dell'Orda.$B$BIo non sono riuscito a trovare la sua barca, ma forse tu ci riuscirai. Forse è nascosta, o forse è affondata. In ogni caso, potrebbe contenere un indizio su dove si trova lui. Se scopri qualcosa, fammelo sapere.",
  obj = "Trova la barca del corriere da qualche parte lungo la costa di Feralas.",
  reward = "Hai trovato quella che sembra una barca a remi naufragata. Attraverso l'acqua un po' fangosa vedi grossi squarci che crivellano la fiancata di babordo; la barca è quasi ridotta alla sua semplice ossatura di legno. Qualunque cosa l'abbia distrutta, molto probabilmente ha cercato di spezzarla in due. Sulla fiancata di tribordo è dipinto un piccolo stemma della Feathermoon Stronghold.$B$BNel fango, alla base della barca, qualcosa di metallico ti cattura lo sguardo con un luccichio...",
  en_title = "The Missing Courier",
  en_obj = "Locate the courier's boat somewhere along the coast of Feralas.",
}
T[4127] = {
  title = "Il relitto della barca",
  desc = "Passando la mano nel fango, le tue dita sfiorano il manico di un coltello. Sembra ben tenuto, e si può presumere che chi era sulla barca l'abbia perso. Forse il grosso pezzo che manca alla barca ha qualcosa a che fare con la perdita.$B$BPrendi il coltello, ricordando che Ginro Hearthkindle, alla Feathermoon Stronghold, ti ha chiesto di tornare da lui con ogni indizio trovato. Hai però la sensazione di non essere del tutto $Gsolo:sola; nell'acqua...",
  obj = "Torna alla Feathermoon Stronghold e mostra a Ginro Hearthkindle il Discarded Knife che hai trovato.",
  progress = "Ah, $Gbentornato:bentornata;, $N. Spero che tu sia $Griuscito:riuscita; a scoprire qualche indizio sulla sorte di Raschal, per quanto tragica possa essere.",
  reward = "Interessante... credo che questo sia il coltello di Raschal. Dici di averlo trovato sul fondo dell'acqua, insieme alla sua barca? Be', il ritrovamento del coltello da solo potrebbe non bastare a collegarlo alla scomparsa di Raschal; abbiamo però un'opzione poco convenzionale per cercare di saperne di più.$B$BHai mai sentito parlare di psicometria?",
  en_title = "Boat Wreckage",
  en_obj = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.",
}
T[4129] = {
  title = "Ciò che il coltello rivela",
  desc = "Il druido della roccaforte, Quintis Jonespyre, ha delle capacità... insolite. Una di queste è la psicometria: la capacità di rivelare la storia di un oggetto toccandolo. Non chiedermi come faccia; per me è una magia che non capisco e che scelgo di non capire. So però due cose: primo, l'ho vista funzionare, e secondo, quel perdigiorno è in debito con me.$B$BPorta il coltello a Quint, su nella sua casetta sull'albero qui vicino, e digli da parte mia che il suo debito di Kalimdor Hold 'Em sarà saldato se fa la sua magia su quel coltello.",
  obj = "Porta il Discarded Knife a Quintis Jonespyre, alla Feathermoon Stronghold.",
  progress = "Ti manda Ginro, eh?$B$BLe mie letture psicometriche sono piuttosto sfiancanti per la mente... ma lo sono anche le mie perdite a Kalimdor Hold 'Em. Qui alla roccaforte mi chiamano \"il re delle batoste\". Sfortunato al gioco... fortunato nel padroneggiare i segreti della natura, direi.$B$BComunque, certo che lo farò. Potrebbe essere proprio la svolta che ci serve per scoprire la sorte di Raschal. Se mi dai il coltello, possiamo cominciare.",
  reward = "Grazie, $N.$B$BAnche se la psicometria non è affatto un'arte esatta, in passato l'ho usata per far luce su situazioni che altri avevano dato per perse. Credo che usarla sul coltello che hai trovato ci farà intravedere cosa è successo a Raschal.$B$BCi vorrà solo un momento, ma non è quello che chiamerei un compito leggero per chi lancia incantesimi. Abbi pazienza.",
  en_title = "The Knife Revealed",
  en_obj = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.",
}
T[4130] = {
  title = "Lettura psicometrica",
  desc = "Sono ancora un po' stordito, scusa. Comunque, ho avuto delle visioni utili.$B$BRaschal prende due grossi zaini di cuoio dalla sua barca e si addentra nell'entroterra; poi però torna alla barca. Vedo scalpi di gnoll... si è imbattuto in degli gnoll, i Woodpaw, credo si chiamino. È molto preoccupato, quasi terrorizzato, per qualcosa. Tanto che non si accorge degli elementali dell'acqua che si formano alle sue spalle. Le immagini... si fermano lì.$B$BDevo riposare, scusa, $N. Riferisci a Gin quello che ho visto. Deve saperlo.",
  obj = "Parla con Ginro Hearthkindle, alla Feathermoon Stronghold.",
  reward = "Grazie per avermi riferito le visioni di Quint, $N. Cercherò di ricordarmi di essere un po' più indulgente con lui la prossima volta che giochiamo a carte.$B$BRaschal sa cavarsela in un combattimento, e gli gnoll non sono certo qualcosa che potrebbe preoccuparlo, anzi, terrorizzarlo. Comunque, forse tu e i tuoi potete agire su queste nuove informazioni e trovare la svolta di cui abbiamo disperatamente bisogno.",
  en_title = "Psychometric Reading",
  en_obj = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
}
T[4131] = {
  title = "Gli gnoll Woodpaw",
  desc = "Alla fine i nostri \"amici\" Woodpaw potrebbero aver preso Raschal, ma qualcosa mi dice che non è andata così. Comunque, sono il posto migliore da cui cominciare a cercare.$B$BVorrei avere le idee più chiare su cosa fare, ma per ora ho solo \"Cerca negli accampamenti dei Woodpaw: vai.\" So che gli gnoll tengono gli oggetti che razziano e se li contendono; forse si sono imbattuti negli zaini di cui ha parlato Quint. Nelle ricerche passate non avevo rischiato uno scontro frontale, ma con la visione di Quint dico di farli a pezzi.",
  obj = "Cerca negli accampamenti degli gnoll Woodpaw, nel sud di Feralas, delle prove sugli averi del corriere o sul corriere stesso.",
  reward = "Appesi a un albero lì vicino ci sono due grossi zaini di cuoio. Ognuno porta sul davanti un piccolo stemma della Feathermoon Stronghold...",
  en_title = "The Woodpaw Gnolls",
  en_obj = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.",
}
T[4161] = {
  title = "La ricetta dei Kaldorei",
  desc = "Tanto tempo fa, gli elfi della notte erano chiamati kaldorei, un nome che significa \"figli delle stelle\". Conoscere il passato è un passo importante nel tuo cammino come $C, $N, quindi ascolta bene quello che ho da dirti.$B$BI kaldorei sono sempre stati molto fieri del loro rapporto armonioso con la natura. Questo significa che prendiamo dalla natura solo ciò che è necessario, e che restituiamo in egual misura. Questo equilibrio ci ha dato molto, $N.$B$BVa' a raccogliere sette Small Spider Leg — non di più, e torna da me.",
  obj = "Raccogli 7 Small Spider Leg per Zarrin, a Dolanaar.",
  progress = "Ricorda l'equilibrio, $N. Desidero che tu sviluppi comprensione e una forte empatia per le foreste viventi.",
  reward = "Ricorda sempre quello che ti ho mostrato oggi, $N. Fai parte dell'equilibrio che gli elfi della notte si sforzano di mantenere intatto, anche in tempi difficili.",
  en_title = "Recipe of the Kaldorei",
  en_obj = "Collect 7 Small Spider Legs for Zarrin in Dolanaar.",
}
T[4181] = {
  title = "Ingegneria goblin",
  desc = "L'ingegneria di livello esperto si divide in due discipline distinte: gnomica e goblin. Mi prendo la briga di nominare l'ingegneria goblin solo perché sono un istruttore imparziale. Agli ingegneri goblin piace costruire cose che esplodono, e raramente badano a cosa si trovi sulla loro strada — nemmeno quando si tratta di loro stessi.$B$B$N, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring, a Gadgetzan. Ricorda: l'iscrizione è permanente e impedisce di entrare nell'altra disciplina, quindi assicurati che sia ciò che vuoi prima di portare a termine il suo incarico.",
  obj = "Se vuoi saperne di più sull'ingegneria goblin, porta il Manual of Engineering Disciplines a Nixx Sprocketspring, a Gadgetzan.",
  progress = "Fiuto le nuove reclute come fiuto un'ottima polvere da mina — a un miglio di distanza. Sei $Gvenuto:venuta; a imparare come si padroneggia l'esplosione?",
  reward = "Be', $N, hai fatto bene a cercare la mia guida! Qualsiasi imbranato può diventare esperto nelle basi dell'ingegneria — gli gnomi e Gnomeregan, la loro casa irradiata, ne sono la prova. Ma per padroneggiare la disciplina dell'ingegneria goblin ci vogliono una mente salda e una mano ferma (e sottolineo FERMA).$B$BTieni le orecchie ben aperte, $N, e forse imparerai qualcosa.",
  en_title = "Goblin Engineering",
  en_obj = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
}
T[4281] = {
  title = "Consegna a Thalanaar",
  desc = "Questo pacco di merci che hai trovato negli accampamenti degli gnoll Woodpaw doveva essere consegnato alla piccola stazione di sosta di Thalanaar, nel sud-est di Feralas. Qualunque sia stata la sorte del corriere scomparso, il compito di consegnare il pacco resta da portare a termine.$B$BEsaminando il pacco con attenzione, scopri un nome scritto a mano sull'esterno dell'imballaggio: \"Falfindel Waywarder\". Forse è il destinatario finale del pacco.",
  obj = "Porta l'Undelivered Parcel a Falfindel Waywarder, a Thalanaar.",
  progress = "$GBenvenuto:Benvenuta; a Thalanaar, $C. Ti serve aiuto di qualche tipo?",
  reward = "Sia lodata Elune, la consegna dalla Feathermoon Stronghold è finalmente arrivata!$B$BLa tua presenza qui mi fa pensare che forse a Raschal, il nostro solito corriere, sia capitata una brutta sorte. Spero che tutto si sistemi. So che di recente i Woodpaw si sono molto agitati per qualcosa che viene da sud. Forse è caduto lì, nelle terre selvagge; io starei attento, $Gamico:amica;.$B$BComunque, grazie ancora. Ecco il pagamento per la consegna di questo pacco.",
  en_title = "Thalanaar Delivery",
  en_obj = "Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.",
}
T[4295] = {
  title = "La birra di Rocknot",
  progress = "Oh, birra! Ucciderei per un po' di Dark Iron Ale!! Presto, sto tornando sobrio! Lo so perché la sobrietà mi annebbia la vista... e mi fa sembrare che tu sia $Gil:la; $R che ho ucciso la settimana scorsa!",
  reward = "Cos'è questo? Ah! Sa di Dark Iron Ale! Il bere mi ha annebbiato la vista, ma capisco che tu, $Gsignore:signora;, sei $Gun vero amico:una vera amica;!",
  en_title = "Rocknot's Ale",
}
T[4402] = {
  title = "La sorpresa di mele di cactus di Galgar",
  desc = "Fa proprio caldo qui nella Valley of Trials.$B$B<Galgar si asciuga la fronte.>$B$BSe solo avessi delle mele di cactus, potrei preparare la mia famosa sorpresa di mele di cactus! Niente rinfresca più in fretta di un pezzo di quella squisita delizia.$B$BTi dico io, $N. Se mi porti 10 mele di cactus, ti preparerò qualche porzione di sorpresa di mele di cactus da portare con te nelle tue avventure. Se ti interessa, le mele di cactus crescono vicino alle piante di cactus qui intorno.",
  obj = "Porta a Galgar 10 Cactus Apples. Ricordi che ha detto che si trovano vicino ai cactus.",
  progress = "Hai finito di raccogliere le mele di cactus?",
  reward = "Meraviglioso, $N! Come promesso, ecco la tua sorpresa di mele di cactus più un piccolo extra.",
  en_title = "Galgar's Cactus Apple Surprise",
  en_obj = "Bring Galgar 10 Cactus Apples. You remember him saying that they could be found near cactuses.",
}
T[4495] = {
  title = "Un buon amico",
  desc = "Un mio amico di nome Iverron viene a trovarmi ogni giorno alla stessa ora. La cosa strana è che oggi non si è fatto vedere affatto: ha, anzi, parecchie ore di ritardo.$B$BLo ammetto, $N, sono un po' preoccupato. Iverron passa molto tempo vicino alla caverna a nord, e sono sicuro che sai quanto sia pericoloso laggiù: ragni ovunque!$B$BSe dovessi passare da quelle parti, potresti tenere gli occhi aperti per lui?",
  obj = "Trova Iverron vicino alla caverna a nord.",
  reward = "Sono così felice che tu mi abbia trovato, $N. Come facevi a sapere che ero qui?",
  en_title = "A Good Friend",
  en_obj = "Find Iverron by the cave to the north.",
}
T[4542] = {
  title = "Messaggio per Freewind Post",
  desc = "$GCoraggioso viaggiatore:Coraggiosa viaggiatrice;, i centauri hanno intensificato gli attacchi in questa zona. Freewind Post deve sapere subito di queste nuove molestie! Cerca Cliffwatcher Longhorn a Freewind Post, a sud-est, e consegnagli questo messaggio urgente.$B$BSta' in guardia, evita il Grimtotem Clan qui vicino... ultimamente si comportano in modo strano con noi.",
  obj = "Porta l'Urgent Message a Cliffwatcher Longhorn, a Freewind Post.",
  progress = "Cosa vuoi, $C? Un messaggio urgente... per me?",
  reward = "Altre cattive notizie! Questi centauri sono andati troppo oltre! Hanno assalito una delle mie carovane di rifornimenti e massacrato l'intero gruppo. È un oltraggio, e non resterà impunito!",
  en_title = "Message to Freewind Post",
  en_obj = "Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post.",
}
T[4581] = {
  title = "Kayneth Stillwind",
  desc = "Il druido Kayneth Stillwind mi ha mandato un messaggio. Vorrebbe un rapporto su quel che accade lungo la nostra costa e nelle foreste intorno ad Astranaar. Teme che una corruzione si stia muovendo per Ashenvale... e potrebbe avere ragione.$B$BEcco, portagli il mio rapporto. Lo troverai nel santuario di Forest Song, nei Nightsong Woods a est.",
  obj = "Porta Shindrell's Note a Kayneth Stillwind, a Forest Song.",
  progress = "Hai qualcosa per me?",
  reward = "Ah, il rapporto di Shindrell! Molte grazie, $N. Shindrell è un'ottima sentinella, coraggiosa e acuta. Devo leggerlo per cercare tracce di una malvagità che temo si stia muovendo per Ashenvale.",
  en_title = "Kayneth Stillwind",
  en_obj = "Take Shindrell's Note to Kayneth Stillwind in Forest Song.",
}
T[4601] = {
  title = "The Sparklematic 5200!",
  desc = "Questo aggeggio spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice \"The Sparklematic 5200\", e sotto c'è scritto:$B$B\"Sporcizia e residui rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendi-fantastico! Inserisci l'oggetto da pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 qualche istante di lavoro e voilà! I tuoi oggetti di valore usciranno puliti e splendenti!\"",
  obj = "Inserisci un Grime-Encrusted Item nello Sparklematic 5200, e assicurati di avere tre monete d'argento per far partire la macchina.",
  progress = "Pare che al congegno serva una specie di oggetto incrostato di sporcizia da pulire e tre monete d'argento per mettersi in moto. Se ci sono tutti e due, lo Sparklematic 5200 dovrebbe funzionare...",
  reward = "Inserisci l'oggetto incrostato e tre monete d'argento nello Sparklematic 5200. La macchina si anima in un tentativo frenetico di ripulire dalla sporcizia l'oggetto sconosciuto. Dal cuore della macchina battono rumori forti e violenti di ingranaggi che girano. Il telaio metallico della bestia scricchiola e geme mentre sobbalza da un lato all'altro...",
  en_title = "The Sparklematic 5200!",
  en_obj = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
}
T[4602] = {
  title = "The Sparklematic 5200!",
  desc = "Questo aggeggio spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice \"The Sparklematic 5200\", e sotto c'è scritto:$B$B\"Sporcizia e residui rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendi-fantastico! Inserisci l'oggetto da pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 qualche istante di lavoro e voilà! I tuoi oggetti di valore usciranno puliti e splendenti!\"",
  obj = "Inserisci un Grime-Encrusted Item nello Sparklematic 5200, e assicurati di avere tre monete d'argento per far partire la macchina.",
  progress = "Pare che al congegno serva una specie di oggetto incrostato di sporcizia da pulire e tre monete d'argento per mettersi in moto. Se ci sono tutti e due, lo Sparklematic 5200 dovrebbe funzionare...",
  reward = "Inserisci l'oggetto incrostato e tre monete d'argento nello Sparklematic 5200. La macchina si anima in un tentativo frenetico di ripulire dalla sporcizia l'oggetto sconosciuto. Dal cuore della macchina battono rumori forti e violenti di ingranaggi che girano. Il telaio metallico della bestia scricchiola e geme mentre sobbalza da un lato all'altro...",
  en_title = "The Sparklematic 5200!",
  en_obj = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
}
T[4603] = {
  title = "Ancora un giro di Sparklematic",
  progress = "Lo Sparklematic 5200 è vuoto, in attesa di un oggetto incrostato da pulire e di tre monete d'argento per partire!",
  reward = "Lo Sparklematic 5200 si anima, sobbalzando avanti e indietro. Dentro, la sporcizia indifesa che incrostava l'oggetto viene polverizzata dal detergente gnomico della macchina.$B$BLo Sparklematic 5200 si ferma, annunciato da un familiare \"ding!\". Il ricettacolo della macchina si apre a spirale e rivela una scatola avvolta con cura.",
  en_title = "More Sparklematic Action",
}
T[4604] = {
  title = "Ancora un giro di Sparklematic",
  progress = "Lo Sparklematic 5200 è vuoto, in attesa di un oggetto incrostato da pulire e di tre monete d'argento per partire!",
  reward = "Lo Sparklematic 5200 si anima, sobbalzando avanti e indietro. Dentro, la sporcizia indifesa che incrostava l'oggetto viene polverizzata dal detergente gnomico della macchina.$B$BLo Sparklematic 5200 si ferma, annunciato da un familiare \"ding!\". Il ricettacolo della macchina si apre a spirale e rivela una scatola avvolta con cura.",
  en_title = "More Sparklematic Action",
}
T[4605] = {
  title = "The Sparklematic 5200!",
  reward = "Com'è cominciato, così lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\", e la bocca della macchina si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta avvolta in un nastrino. Pare che la macchina incarti l'oggetto dopo avergli tolto le incrostazioni. Anche se la macchina non avesse funzionato, almeno adesso l'oggetto è avvolto in una bella scatola.$B$BBe', c'è un modo solo per scoprire se l'ha pulito o no...",
  en_title = "The Sparklematic 5200!",
}
T[4606] = {
  title = "The Sparklematic 5200!",
  reward = "Com'è cominciato, così lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\", e la bocca della macchina si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta avvolta in un nastrino. Pare che la macchina incarti l'oggetto dopo avergli tolto le incrostazioni. Anche se la macchina non avesse funzionato, almeno adesso l'oggetto è avvolto in una bella scatola.$B$BBe', c'è un modo solo per scoprire se l'ha pulito o no...",
  en_title = "The Sparklematic 5200!",
}
T[4621] = {
  title = "Alt là, ammiraglio!",
  desc = "Ascolta bene, lupo di mare... è il potere di Booty Bay che impedisce a noi Bloodsail di navigare dove ci pare e di prenderci quello che vogliamo per diritto di saccheggio. Se piantassi un coltello in Fleet Master Seahorn, non avremmo mai più guai con le navi di Booty Bay. Se piantassi un coltello in Baron Revilgaz, non dovremmo mai più fare i conti con la loro legge.$B$BSe vuoi diventare $Gammiraglio onorario:ammiraglia onoraria; tra noi, sì, $GAMMIRAGLIO:AMMIRAGLIA;, pianterai un coltello in tutti e due, come ho detto. Ora va', $Gragazzo:ragazza;, e torna da me quando avrai fatto il lavoro.",
  obj = "Uccidi Fleet Master Seahorn e Baron Revilgaz di Booty Bay, poi torna da Fleet Master Firallon a bordo della Crimson Veil, al largo della costa di Stranglethorn Vale.",
  progress = "Sei già di ritorno, maledetto marinaio! Hai fatto quello che ti ho ordinato? Deludici e camminerai sull'asse.$B$BArrrrr...",
  reward = "Alt là... $GAmmiraglio:Ammiraglia; $N! Sei il pirata dei pirati, $Gragazzo:ragazza;!$B$BMi scalda il cuore darti questo cappello. Non ne troverai mai un altro così da nessuna parte, e chiunque ti guardi vedrà che sei $Gun ammiraglio:un'ammiraglia; della Bloodsail Navy!",
  en_title = "Avast Ye, Admiral!",
  en_obj = "Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay, and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale.",
}
T[4641] = {
  title = "Il tuo posto nel mondo",
  desc = "Finalmente sei in età, $N... in età per combattere nel nome dell'Orda. Per conquistare per la gloria del Warchief.$B$BSì...$B$B<Kaltunk ti squadra da capo a piedi.>$B$BAndrai bene.$B$BSenza dubbio vorresti trovare un grande drago o un demone e strangolarlo a mani nude, ma forse sarebbe saggio iniziare con qualcosa di meno... pericoloso.$B$B<Kaltunk ride.>$B$BPresentati da Gornek, saprà assegnarti un compito più adatto a un giovane $c. Troverai Gornek nel Den, a ovest.",
  obj = "Parla con Gornek. Ricordi che Kaltunk ha segnato la sua posizione sulla tua mappa e ha detto che Gornek risiede nel Den, un edificio a ovest. ",
  progress = "La corazza di uno scorpide non è così spessa da fermare la forza di un $C determinato. Colpisci con vigore e senza esitare, e gli scorpidi si riveleranno facili prede.",
  reward = "Un'altra recluta di Kaltunk, eh?$B$BTriste stato di cose, se questo è il meglio che l'Orda sa produrre. Non importa. Quando penseremo che sei pront$Go:a; a lasciare la Valley, sarai un fiero $C dell'Orda.",
  en_title = "Your Place In The World",
  en_obj = "Speak with Gornek. You recall Kaltunk marking your map with his location and mentioning that Gornek resided in the Den, a building to the west. ",
}
T[4681] = {
  title = "Spiaggiati",
  desc = "Quella creatura spiaggiata non è un caso isolato qui a Darkshore. Ce ne sono altre lungo la costa e persino in acqua. Vorrei che tu ne esaminassi un'altra di cui siamo a conoscenza: è stata segnalata in acqua, a ovest di Auberdine, vicino a un relitto affondato. Torna da me con tutto ciò che riuscirai a recuperare che possa aiutare la nostra ricerca.$B$BInoltre, durante i tuoi viaggi potresti imbatterti in altre creature. Se dovessi scoprire qualcosa, ti prego di portarlo alla nostra attenzione!",
  obj = "Recupera i Sea Turtle Remains dallo Skeletal Sea Turtle nelle acque a ovest di Auberdine, poi parla con Gwennyth Bly'Leggonde di nuovo ad Auberdine.",
  progress = "Una volta che avrai esaminato i resti della creatura nell'acqua a ovest di qui, potrò presentare un rapporto adeguato al Temple of the Moon a Darnassus. Forse allora saremo più vicini a scoprire perché queste sfortunate creature scelgono di porre fine ai propri giorni spiaggiandosi sulla costa di Darkshore.",
  reward = "Oggi ci sei stato di enorme aiuto; ora abbiamo una concreta possibilità di svelare il mistero del perché queste creature scelgano di spiaggiarsi sulla costa di Darkshore. L'idea che possano fuggire dall'area intorno a Teldrassil è inquietante. Se ne incontrerai altre nei tuoi viaggi, fammelo sapere. La nostra ricerca è appena agli inizi.$B$BA nome del Temple of the Moon, accetta questo come ringraziamento per l'impegno che hai dedicato. Grazie, $N!",
  en_title = "Washed Ashore",
  en_obj = "Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine.",
}
T[4722] = {
  title = "Tartaruga marina spiaggiata",
  desc = "Trovi la carcassa di una tartaruga marina che si era spiaggiata sulla costa di Darkshore qualche tempo fa. È stata saccheggiata dai murloc che si sono accampati attorno ai suoi resti. Tuttavia sembrano rimasti dei campioni utili sui resti della creatura, che Gwennyth Bly'Leggonde ad Auberdine potrebbe riuscire a sfruttare.",
  obj = "Porta i Sea Turtle Remains a Gwennyth Bly'Leggonde ad Auberdine.",
  progress = "Salve, $N - hai da riferire qualche scoperta su creature spiaggiate?",
  reward = "Un'altra scoperta da studiare - ben fatto, $N! Questi resti saranno studiati a dovere una volta giunti a Darnassus. Ti prego di accettare questo piccolo compenso in cambio dei resti che ci hai fornito per il nostro studio.",
  en_title = "Beached Sea Turtle",
  en_obj = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.",
}
T[4723] = {
  title = "Creatura marina spiaggiata",
  desc = "I resti di un thresher gigante - molto più grande di quelli che ci si aspetterebbe di trovare a Darkshore - giacciono spiaggiati sulla costa di Mist's Edge. Come questa creatura sia finita qui è un mistero; il gruppo di murloc che ora banchetta con la sua carcassa sembra troppo debole, anche in gran numero, per aver abbattuto la bestia.$B$BSebbene parte di essa sia stata spolpata, ne rimane abbastanza per prelevare un campione da far studiare a Gwennyth Bly'Leggonde ad Auberdine.",
  obj = "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde ad Auberdine.",
  progress = "Di nuovo salve, $N! Sei qui per riferire su un'altra scoperta?",
  reward = "Le ossa che hai portato appartengono a gentili mammiferi marini che abitano le acque attorno alla base di Teldrassil. Non si era mai saputo che si spiaggiassero violentemente come i thresher. Perché mai queste creature lo farebbero, mi chiedo? Beh, forse lo studio dei loro resti porterà i frutti di conoscenza che cerchiamo.$B$BAncora una volta, grazie per il tuo aiuto. Ti prego di accettare questo compenso dal Temple of the Moon.",
  en_title = "Beached Sea Creature",
  en_obj = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
}
T[4725] = {
  title = "Tartaruga marina spiaggiata",
  desc = "Altri resti di tartarughe marine giacciono spiaggiati lungo la costa. Questo esemplare ha una carrozza abbandonata attaccata al guscio. Forse questa creatura è stata spinta a riva da esseri sconosciuti, invece di spiaggiarsi da sola come suggerivano altri resti. I murloc Greymist hanno ora fatto dei resti di questa creatura la propria dimora, banchettando con la carogna.$B$BNella carrozza trovi una scatola con strani segni; forse Gwennyth Bly'Leggonde ad Auberdine saprà dar loro un senso.",
  obj = "Porta la Strangely Marked Box a Gwennyth Bly'Leggonde ad Auberdine.",
  progress = "È un piacere rivederti, $N. Stiamo facendo grandi progressi nello svelare il mistero del perché le maestose creature marine si spiaggino sulla costa di Darkshore, ma a ogni domanda risolta ne sorgono altre due, a quanto pare.$B$BSei qui per offrirci altro aiuto nella nostra ricerca?",
  reward = "Ho sentito parlare del tipo di carrozze trovate sul dorso della tartaruga che hai scoperto. Credo siano carrozze dei naga, usate sia in battaglia sia per trasportare i rifornimenti sulla terraferma. I segni sulla scatola che hai trovato sono dei naga; questo spiegherebbe la loro presenza invasiva nell'estremo nord di Darkshore.$B$BInvierò questa scatola a Darnassus insieme al resto delle tue scoperte. Questo è per te - grazie ancora per la tua assistenza.",
  en_title = "Beached Sea Turtle",
  en_obj = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.",
}
T[4727] = {
  title = "Tartaruga marina spiaggiata",
  desc = "I resti scheletrici di una tartaruga marina giacciono sulla sabbia delle spiagge settentrionali di Darkshore. I murloc Greymist o non hanno trovato questa carcassa, o forse l'hanno trovata e la evitano per qualche ragione ignota. In ogni caso, della tartaruga rimane abbastanza da prelevare un campione e portarlo a Gwennyth Bly'Leggonde ad Auberdine, perché il Temple of the Moon lo studi.",
  obj = "Porta i Sea Turtle Remains a Gwennyth Bly'Leggonde ad Auberdine.",
  progress = "Di nuovo salve, $N! Sei qui per riferire su un'altra scoperta?",
  reward = "Hai trovato altre creature spiaggiate, $N? Le tartarughe marine si vedevano spesso scorrazzare alla base di Nordrassil prima della sua distruzione. Con la nascita di Teldrassil, però, sono state viste in numero sempre minore. Alcune, come abbiamo scoperto, finiscono i propri giorni qui per ragioni ignote.$B$BIl tuo aiuto forse scioglierà il mistero che abbiamo davanti. Ti prego di accettare questo in cambio dei resti che ci hai fornito per il nostro studio.",
  en_title = "Beached Sea Turtle",
  en_obj = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.",
}
T[4728] = {
  title = "Creatura marina spiaggiata",
  desc = "Il cadavere di quella che sembra una specie di gigantesca creatura marina giace sulla spiaggia, in parte sventrato. Una carriola e vari attrezzi sono abbandonati accanto all'enorme creatura spiaggiata, come se qualcuno avesse già tentato di studiarla. Sebbene i murloc abbiano banchettato con la carcassa, ne resta abbastanza per raccogliere un campione adatto per Gwennyth Bly'Leggonde, ad Auberdine.",
  obj = "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.",
  progress = "Salve ancora, $N! Cosa ti riporta ad Auberdine? Sei qui per riferire di un'altra scoperta, forse?",
  reward = "Ah, credo tu abbia trovato quella che stava già esaminando la Lega degli Esploratori. Hanno una presenza qui a Darkshore e avevano accennato a uno studio su una delle creature spiaggiate, finché i murloc non li hanno cacciati. Tu sembri esserci riuscit$Go:a; dove entrambi abbiamo fallito. Prego, accetta questo compenso a nome del Tempio della Luna.",
  en_title = "Beached Sea Creature",
  en_obj = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
}
T[4730] = {
  title = "Creatura marina spiaggiata",
  desc = "Il cadavere mezzo divorato di quella che doveva essere una gigantesca creatura marina giace sulla spiaggia. Un gruppo di murloc, più forti di quelli che si trovano vicino ad Auberdine, si è stabilito attorno alla carcassa. Ne resta abbastanza da poter consegnare un campione di ossa a Gwennyth Bly'Leggonde, ad Auberdine.",
  obj = "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.",
  progress = "Salve di nuovo, $N! Sei qui per riferire di un'altra scoperta?",
  reward = "Le ossa che hai portato appartengono a pacifici mammiferi marini che abitano le acque attorno alla base di Teldrassil. Non si era mai sentito dire che si spiaggiassero in modo violento, come facevano i threshers. Perché mai lo avranno fatto? Forse lo studio dei loro resti porterà il frutto di conoscenza che cerchiamo.$B$BDi nuovo, grazie per il tuo aiuto. Accetta questo compenso dal Tempio della Luna.",
  en_title = "Beached Sea Creature",
  en_obj = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
}
T[4731] = {
  title = "Tartaruga marina spiaggiata",
  desc = "Un altro insieme di resti di tartaruga marina giace spiaggiato sulla costa. Questi resti hanno una carrozza abbandonata, fissata a metà al guscio della tartaruga. Forse la creatura è stata spinta a riva da esseri sconosciuti, invece di spiaggiarsi da sola come suggerivano altri resti. Potenti murloc Greymist hanno fatto della carcassa la loro attuale dimora.$B$BNella carrozza trovi una scatola con strani segni; forse Gwennyth Bly'Leggonde, ad Auberdine, saprà decifrarli.",
  obj = "Porta la Strangely Marked Box a Gwennyth Bly'Leggonde, ad Auberdine.",
  progress = "Salve di nuovo, $N. Il lavoro che hai svolto per conto del Tempio della Luna è stato eccezionale. Saremo benedetti da altri tuoi sforzi in nostro favore?",
  reward = "Ho sentito parlare del tipo di carrozze trovate sul dorso di quella tartaruga. Credo siano carrozze naga, usate sia in battaglia sia per trasportare le provviste sulla terraferma. I segni sulla scatola che hai trovato sono dei naga; forse la creatura è stata uccisa mentre si dirigeva più a sud... magari verso Ashenvale?$B$BMi assicurerò di inviare questa scatola a Darnassus insieme alle altre tue scoperte. Questo è per te: grazie ancora per l'aiuto.",
  en_title = "Beached Sea Turtle",
  en_obj = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.",
}
T[4732] = {
  title = "Tartaruga marina spiaggiata",
  desc = "Trovi il cadavere di una tartaruga marina che si è spiaggiata sulla costa di Darkshore tempo fa. È stato spolpato quasi del tutto dai murloc Greymist, gli stessi che ora si sono accampati attorno ai suoi resti. Eppure sulla carcassa sembrano rimanere campioni adatti, di cui Gwennyth Bly'Leggonde, ad Auberdine, potrebbe fare uso.",
  obj = "Porta i Sea Turtle Remains a Gwennyth Bly'Leggonde, ad Auberdine.",
  progress = "Salve ancora, $N. Hai altre scoperte da riferire al Tempio della Luna?",
  reward = "Hai trovato altre creature spiaggiate, $N? Le tartarughe marine un tempo si vedevano spesso scorrazzare alla base di Nordrassil, prima della sua distruzione. Con la nascita di Teldrassil, però, se ne vedono sempre meno. Alcune, come abbiamo scoperto, finiscono i loro giorni qui per qualche ragione ignota.$B$BIl tuo aiuto forse scioglierà il mistero che abbiamo davanti. Accetta questo in cambio dei resti che ci hai fornito per il nostro studio.",
  en_title = "Beached Sea Turtle",
  en_obj = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.",
}
T[4733] = {
  title = "Creatura marina spiaggiata",
  desc = "I resti di quello che sembra un gigantesco thresher sono stati portati a riva nella baia rocciosa di Twilight Shore. Questo thresher è molte volte più grande di qualsiasi altro avvistato da queste parti. Da qualunque luogo provenga, non sembra originario di Darkshore.$B$BSebbene la creatura sia stata spolpata in alcuni punti, ne resta abbastanza per raccogliere un campione adatto per Gwennyth Bly'Leggonde, ad Auberdine.",
  obj = "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.",
  progress = "Sia lode a Elune, sono lieta di rivederti, caro $N. Il lavoro del Tempio della Luna sugli strani spiaggiamenti prosegue qui a Darkshore. Hai forse qualcos'altro da offrirci?",
  reward = "Le dimensioni del thresher che descrivi sono sbalorditive. Persino i più anziani dei thresher di questa regione raggiungono solo una frazione di quella stazza. Alcuni esemplari più grandi erano noti nei pressi di Teldrassil, ma il loro numero è calato costantemente. Non posso fare a meno di chiedermi se queste creature spiaggiate siano in qualche modo legate a ciò.$B$BMentre analizziamo le ossa che ci hai portato, accetta questo a nome del Tempio della Luna. Grazie, $N.",
  en_title = "Beached Sea Creature",
  en_obj = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
}
T[4740] = {
  title = "RICERCATO: Murkdeep!",
  desc = "Attenzione!$B$BÈ offerta una ricompensa per la morte del murloc \"Murkdeep\". Questa immonda bestia è nota per essere responsabile della morte di almeno una Sentinella e si sospetta abbia causato l'affondamento di almeno due navi da carico nelle acque al largo di Darkshore!$B$BMurkdeep è stato visto per l'ultima volta in un accampamento di capanne murloc a sud di Auberdine e si ritiene che protegga le capanne di quel luogo. La taglia va riscossa presso Sentinel Glynda Nal'Shea, ad Auberdine.$B$BIl Consiglio del Villaggio di Auberdine",
  obj = "Trova e uccidi il murloc noto come Murkdeep. Si ritiene che difenda le capanne murloc a sud di Auberdine, lungo l'acqua.$B$BRiferisci la morte di Murkdeep a Sentinel Glynda Nal'Shea, ad Auberdine.",
  progress = "Salve, $c. In cosa possono aiutarti oggi le Sentinelle? Forse sei qui per informarti sulla taglia su Murkdeep?",
  reward = "Be', pare che tu sia qui per più di una semplice richiesta di informazioni! I cittadini saranno lieti di sapere che stanotte dormiranno un po' più sereni e al sicuro.$B$BOggi sei stat$Go:a; il braccio della giustizia per la gente di Auberdine, $N. Per questo vorrei offrirti questo come giusta ricompensa... per un vero eroe del popolo di Auberdine.",
  en_title = "WANTED: Murkdeep!",
  en_obj = "Find and slay the murloc known as Murkdeep.  The creature is thought to be defending the murloc huts south of Auberdine along the water.$B$BReport the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine.",
}
T[4761] = {
  title = "Thundris Windweaver",
  desc = "Il tuo sopralluogo all'accampamento dei furbolg è un'informazione di cui Thundris Windweaver dovrebbe essere messo al corrente. Egli serve con grazia come anziano di Auberdine, offrendo una guida saggia e giusta negli affari quotidiani del villaggio. Ti prego, condividi con lui quanto hai scoperto finora sulla questione dei furbolg.$B$BCredo che abbia delle idee personali sulle ragioni della loro corruzione. Forse potrai collaborare con lui per attuare un piano che ristabilisca l'equilibrio della natura qui!",
  obj = "Parla con Thundris Windweaver ad Auberdine.",
  reward = "Ben trovat$Go:a;, $c. Il tuo sopralluogo sulla situazione dei furbolg arriva in un momento propizio per noi di Auberdine. Da tempo ci troviamo a fare i conti non solo con gli abitanti della foresta, ormai apertamente ostili alla nostra presenza, ma anche con la vera e propria corruzione della foresta stessa. Spero che tu possa offrire il tuo aiuto ad Auberdine in questi tempi difficili.",
  en_title = "Thundris Windweaver",
  en_obj = "Speak with Thundris Windweaver in Auberdine.",
}
T[4762] = {
  title = "Il fiume Cliffspring",
  desc = "Il fiume Cliffspring ha iniziato a diventare sporco e corrotto. Sfocia nel Mist's Edge e temo che la contaminazione raggiungerà presto Auberdine. Sospetto che i furbolg Blackwood a monte siano la causa del morbo, ma sospetto anche che non ne siano la vera origine.$B$BPrendi questa provetta e vai alla foce del fiume, a nord. Risali verso l'entroterra fino alla prima cascata e preleva un campione dalla pozza. Vedrai un ponte sopra di te. Una volta ottenuto il campione, torna da me ad Auberdine.",
  obj = "Viaggia a nord di Auberdine fino alla prima cascata lungo il fiume Cliffspring e preleva un campione dalla pozza.$B$BTorna da Thundris Windweaver ad Auberdine con il Cliffspring River Sample.",
  progress = "L'inquinamento del fiume Cliffspring è solo l'inizio di una tendenza allarmante qui a Darkshore. Il campione che porterai ci aiuterà a formulare un piano... un piano d'attacco, comincio a sospettare.",
  reward = "Non mi sorprende quanto sia contaminata quest'acqua, ma guarda quanto sta diventando putrida! Sembra che sia necessario agire il prima possibile, eh, $N?$B$BA est si trova Felwood; è quella la vera fonte di questa corruzione, che ho già visto in passato. Prevedo che questo campione lo confermerà. Potremmo riuscire ad attuare una cura qui, ma per tentare avremo bisogno di aiuto. Quando verrà il momento, $N, spero che potrai darci l'aiuto che ci serve.",
  en_title = "The Cliffspring River",
  en_obj = "Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.$B$BReturn to Thundris Windweaver in Auberdine with the Cliffspring River Sample.",
}
T[4763] = {
  title = "I Blackwood corrotti",
  desc = "Abbiamo scoperto che una fonte della corruzione dei furbolg sono i satiri. Esercitano il loro dominio tramite talismani attraverso cui incanalano la magia. Se i furbolg hanno una possibilità di salvezza, dobbiamo attirare allo scoperto il satiro corruttore e prendere quel talismano!$B$BRiempi questa ciotola al nostro pozzo lunare e raccogli campioni del cibo dei furbolg dal loro accampamento a nord. Mescolali e posali vicino al falò presso il fiume; tutti i furbolg che mangeranno saranno purificati giusto il tempo di attirare fuori il satiro corruttore... che dovrai uccidere!",
  obj = "Riempi l'Empty Cleansing Bowl al Pozzo Lunare di Auberdine.$B$BRaccogli un campione di frutta, noci e cereali dagli accampamenti settentrionali dei furbolg Blackwood.$B$BMescola il contenuto della ciotola e posala vicino al falò più prossimo al fiume Cliffspring nell'accampamento a nord, evocando così il satiro corruttore.$B$BPrendi il Talisman of Corruption e portalo a Thundris Windweaver ad Auberdine.",
  progress = "Il Talisman of Corruption è un oggetto sinistro che serve solo a pervertire l'equilibrio della natura. Quando ti procurerai questo oggetto dal satiro che tormenta i furbolg e me lo porterai perché venga distrutto, oggi avremo ottenuto una grande vittoria!",
  reward = "Abbiamo appena iniziato questa guerra per riconquistare la nostra foresta dalle forze della corruzione, ma oggi una battaglia è stata vinta! $N, il popolo di Auberdine ha nei tuoi confronti un debito di gratitudine che non sarà facile ripagare. Ti prego, accetta questo insieme ai nostri ringraziamenti. Ciò che abbiamo appreso oggi potrebbe un giorno liberare per sempre i nostri amici furbolg dalle catene del tormento.",
  en_title = "The Blackwood Corrupted",
  en_obj = "Fill the Empty Cleansing Bowl at the Auberdine Moonwell.$B$BGather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.$B$BMix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.$B$BTake the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.",
}
T[4767] = {
  title = "Wind Rider",
  desc = "Mi hanno incaricato di trovare nuove reclute tra i wyvern per i maestri dei wind rider. Il loro numero cresce e anch'io spero di diventare un wind rider, un giorno. Però non riusciamo ad addestrare abbastanza wyvern per stare dietro alla richiesta. Forse puoi aiutarmi tu, $N.$B$BHo bisogno che tu vada a Highperch a raccogliere qualche uovo di wyvern. Da qui prosegui a nord-ovest lungo le pareti del canyon fino a una rampa che ti porterà a Highperch. Sta' $Gattento:attenta;: i wyvern sono molto protettivi con le loro uova e non saranno gentili con gli intrusi.",
  obj = "Porta 10 Highperch Wyvern Egg a Elu, a Freewind Post.",
  progress = "$N, hai recuperato le uova di wyvern che cerco? Non vedo l'ora di cominciare l'addestramento da wind rider!",
  reward = "Perfetto! Con queste uova spero di fare il prossimo passo per diventare un wind rider. Ecco un segno della mia riconoscenza; che la buona caccia ti accompagni sempre, $C.",
  en_title = "Wind Rider",
  en_obj = "Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post.",
}
T[4770] = {
  title = "Verso casa",
  desc = "Aiutami, ti prego, $C! Sono nascosto qui a Highperch da un po' di tempo e sono giorni che non vedo una faccia amica. Sono venuto a studiare i wyvern e credo di essermi avvicinato un po' troppo. Dopo essere stato cacciato via da uno dei nidi mi sono perso.$B$BDevo tornare a Whitereach Post! Motega non sa che manco e andrà su tutte le furie quando saprà che mi sono avventurato a Highperch da solo.$B$BWhitereach Post è appena a est di qui... portamici, ti prego!",
  obj = "Scorta Pao'ka Swiftmountain fuori da Highperch, poi parla con Motega Firemane, a Whitereach Post.",
  reward = "Cosa?! Se avessi saputo che Pao'ka Swiftmountain sarebbe andato a ficcare il naso a Highperch, l'avrei incatenato a un totem! Suo padre era riluttante a lasciarlo venire con me a Thousand Needles. Siamo venuti qui a studiare le varie creature che abitano queste belle terre.$B$BTi ringrazio per l'aiuto che hai dato a Pao'ka. Spero che questo ripaghi i guai che l'impresa ti è costata.",
  en_title = "Homeward Bound",
  en_obj = "Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post.",
}
T[4811] = {
  title = "Il Cristallo Rosso",
  desc = "Moonkin ostili vagano in numero sempre maggiore a est di qui. Un tempo si pensava fossero creature miti, quasi mistiche. Sebbene alcuni continuino a venerarli, la sicurezza di Auberdine mi costringe ad avere una visione più realistica.$B$BHo ricevuto notizie secondo cui i moonkin sono attratti da un grande cristallo rosso lungo la catena montuosa orientale di Darkshore. Nessuno ha idea di cosa sia quel cristallo, né se esista davvero. Voglio che tu lo individui laggiù e mi riferisca ciò che trovi.",
  obj = "Viaggia a est di Auberdine e cerca un grande cristallo rosso lungo la catena montuosa orientale di Darkshore. Riferisci quanto scoperto a Sentinel Glynda Nal'Shea ad Auberdine.",
  progress = "Cos'hai da riferire su quel cristallo rosso? Esiste davvero?",
  reward = "Dunque il cristallo esiste, $N? Affascinante... comunque, hai svolto bene il tuo compito: ottimo lavoro!$B$BCos'è esattamente questo cristallo? È solo una domanda in un mare di domande. Un'altra che mi viene in mente è perché i moonkin ne siano attratti. Il cristallo è benigno, oppure nasconde uno scopo più sinistro?$B$BHo molte altre domande, ma per trovare risposte dovremo esaminare il cristallo da vicino.",
  en_title = "The Red Crystal",
  en_obj = "Travel east of Auberdine and look for a large, red crystal along Darkshore's eastern mountain range.  Report back what you find to Sentinel Glynda Nal'Shea in Auberdine.",
}
T[4812] = {
  title = "Come scorre l'acqua",
  desc = "Usa questa fiala vuota e riempila con l'acqua del pozzo lunare qui ad Auberdine. Una magia così potente dovrebbe fornire un indizio sulla composizione del cristallo. Per farlo, verserai il liquido sul cristallo; al resto dovrebbe pensare lui.$B$BNon prevedo che ti accada nulla di male, ma voglio comunque che tu stia attent$Go:a;. Sopra di noi, a est, si trova Felwood; se quel cristallo è legato a quel luogo come sospetto, potrebbe rivelarsi molto pericoloso.",
  obj = "Riempi l'Empty Water Tube al pozzo lunare di Auberdine, poi indaga sul cristallo rosso lungo la parete montuosa orientale di Darkshore.",
  progress = "Il cristallo appare davvero alieno sullo sfondo boscoso di Darkshore. Ti sembra di udire un leggerissimo ronzio provenire dal suo profondo.",
  reward = "Sei giunt$Go:a; ancora una volta al misterioso cristallo. Togli il tappo dalla provetta di acqua del pozzo lunare e ne versi con cautela il contenuto sulla cima del cristallo. Mentre l'acqua scorre lungo i suoi reticoli, vedi la superficie opaca farsi trasparente...",
  en_title = "As Water Cascades",
  en_obj = "Fill the Empty Water Tube at the Auberdine moonwell, and then investigate the red crystal along Darkshore's eastern mountain wall.",
}
T[4813] = {
  title = "I frammenti all'interno",
  desc = "L'acqua del pozzo lunare ha rivelato che all'interno del cristallo sono incastonati alcuni piccoli frammenti d'osso, oltre a metà di una mandibola. La mandibola sembra appartenere a un umanoide, ma senza spezzare il cristallo non è chiaro, impresa che persino la magia più potente troverebbe quasi impossibile.$B$BCompiuto il tuo compito, non resta che riferire a Sentinel Glynda Nal'Shea ad Auberdine.",
  obj = "Riferisci ciò che hai scoperto a Sentinel Glynda Nal'Shea ad Auberdine.",
  reward = "Be', pare che, pur sapendo di più su questo cristallo, ne risultino ancora più domande senza risposta!$B$BPorterò le informazioni che hai scoperto al consiglio di Auberdine. Forse sapranno quale linea d'azione seguire riguardo al cristallo. Ammesso che ce ne sia una; per ora la minaccia resta abbastanza a est da non essere pericolosa.$B$BQuanto a te, prendi questo. Consideralo una ricompensa per un lavoro ben fatto, $N.",
  en_title = "The Fragments Within",
  en_obj = "Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine.",
}
T[4821] = {
  title = "Alien Egg",
  desc = "È circolata la voce di un uovo alieno qui a Thousand Needles. Chi dice di averlo visto non è nemmeno riuscito ad avvicinarsi abbastanza da esaminarlo nei dettagli. I serpenti sorvegliano l'uovo come se fosse uno dei loro.$B$BVoglio che tu trovi questo uovo alieno e me lo porti, così potrò esaminarlo. Si dice che l'uovo si trovi in una tana di serpenti, ma di tane ce ne sono parecchie lungo la base delle pareti rocciose a sud e a nord-est di Freewind Post.",
  obj = "Porta l'Alien Egg a Hagar Lightninghoof, a Freewind Post.",
  progress = "Devo saperne di più su quest'uovo misterioso: chissà cosa ne uscirà.",
  reward = "Sì, finalmente... l'uovo misterioso mi è stato finalmente consegnato. Ora, fammi dare un'occhiata più da vicino... Cosa...! Cos'è questo...?",
  en_title = "Alien Egg",
  en_obj = "Return the Alien Egg to Hagar Lightninghoof in Freewind Post.",
}
T[4822] = {
  title = "Tu gridi, io grido...",
  desc = "GELATO! Oh, per piacere per piacere per piacere, mi prendi un gelato?! La fragola è il mio gusto preferito, e al mondo non c'è gelato alla fragola migliore del Tigule and Foror's Strawberry Ice Cream! È il mio gelato preferito in tutto il mondo!$B$BL'ho mangiato una volta, tanto tempo fa, quando ero alla pista da corsa delle Shimmering Flats, ma ho sentito dire che adesso potrebbero venderlo in città! Per piacere? Per piacere per piacere? Con sopra il Tigule and Foror's Strawberry Ice Cream??!?!",
  obj = "Procura un po' di Strawberry Ice Cream al tuo protetto. Il ragazzo sembra preferire il gelato della marca di Tigule e Foror.",
  progress = "Vorrei che facessero altri gusti di gelato oltre alla fragola, ma immagino di essere fortunato, visto che la fragola è il mio preferito!",
  reward = "Mmmmmmmmm! Adoro il loro gelato alla fragola! Se c'è una cosa che Tigule e Foror sanno fare, è il gelato!$B$BGrazie mille, $N: è la cosa più buona di sempre!",
  en_title = "You Scream, I Scream...",
  en_obj = "Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.",
}
T[4841] = {
  title = "Pacificare i centauri",
  desc = "$N, ti supplico di dare la caccia a questi centauri. Sentiranno l'ira della nostra vendetta. Attacca l'accampamento dei centauri a nord di Freewind Post! Che l'ira guidi la tua mano!",
  obj = "Uccidi 12 Galak Scout, 10 Galak Wrangler e 6 Galak Windchaser, poi torna da Cliffwatcher Longhorn, a Freewind Post.",
  progress = "Suvvia, $N, lo so che non ne hai ancora uccisi abbastanza. Dagli la caccia, e ti darò una ricompensa in segno di gratitudine.",
  reward = "In segno di gratitudine, questo è per te, $N.",
  en_title = "Pacify the Centaur",
  en_obj = "Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post.",
}
T[4865] = {
  title = "Serpente selvaggio",
  desc = "Se non l'avessi visto con i miei occhi non ci avrei mai creduto. La vendetta è arrivata a Thousand Needles!$B$B<Hagar si asciuga la fronte.>$B$B$N, devi agire in fretta! Va' subito a cercare Motega Firemane; si trova a Whitereach Post, appena a nord-ovest di Freewind Post lungo la strada. Lui saprà cosa fare!",
  obj = "Riferisci quel che hai scoperto a Motega Firemane.",
  reward = "Vendetta! Allora la leggenda di Arikara è vera. Sì, è un problema da risolvere subito.",
  en_title = "Serpent Wild",
  en_obj = "Report your findings to Motega Firemane.",
}
T[4881] = {
  title = "Complotto omicida",
  desc = "Il tauren Kanati Greycloud ha l'ardire di piantare un campo di caccia a Thousand Needles. Dobbiamo ucciderlo per liberarci di questo campo e di tutti quelli che potrebbero seguirlo. Ci raduneremo al piccolo avamposto a sud-ovest del Great Lift.",
  obj = "Avverti Kanati Greycloud, a Whitereach Post, del complotto per ucciderlo.",
  reward = "Vengono a uccidermi? Mostrerò loro come combatte un tauren!",
  en_title = "Assassination Plot",
  en_obj = "Warn Kanati Greycloud at Whitereach Post of the plot to kill him.",
}
T[4904] = {
  title = "Finalmente libera",
  desc = "Arnak crede che ci sposeremo... ma dopo che ho rifiutato la sua proposta è tornato quella notte e mi ha rapita. Mio fratello ha cercato di fermarlo, ma Arnak era troppo forte. Lui... ha ucciso mio fratello e poi mi ha portata qui. Povero fratello mio...$B$B$N, potresti scortarmi fuori da Darkcloud Pinnacle? Ti prego... devo tornare da Thalia! Sarà preoccupatissima per me.",
  obj = "Scorta Lakota Windsong fuori da Darkcloud Pinnacle, poi parla con Thalia Amberhide, a Freewind Post.",
  progress = "Thalia Amberhide:",
  reward = "Grazie, $N. Lo sentivo nelle ossa che avrebbe ritrovato la strada per tornare da me. Mi ha raccontato del tuo coraggio e di come l'hai aiutata a fuggire. Questi oggetti erano di suo fratello. So che vorrebbe li avessi tu.",
  en_title = "Free at Last",
  en_obj = "Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post.",
}
T[4921] = {
  title = "Perduta in battaglia",
  desc = "Combattevamo in un piccolo accampamento dei tauren quando siamo stati separati: lei ha tenuto a bada da sola tre dei Bristleback. Ma il numero dei nemici ha cominciato a sopraffarci. Ne ho portati via alcuni, solo per vederla travolta da nuovi arrivati. Preso dalla rabbia, mi sono voltato ad affrontare i miei nemici, ma mi hanno abbattuto con facilità, forti del loro gran numero.$B$BMi sono svegliato con un druido tauren che curava le mie ferite: mi aveva trovato sulla Gold Road mentre cadevo.$B$BTi prego, $c, trova qualche traccia di mia moglie.",
  obj = "Trova la moglie di Mankrik, poi torna da lui al Crossroads.",
  progress = "Hai trovato qualche segno di lei? Il dolore al petto mi dice che è accaduto il peggio, ma spero che tu la trovi sana e salva.",
  reward = "Capisco. Grazie, $C.",
  en_title = "Lost in Battle",
  en_obj = "Find Mankrik's wife and then return to him in the Crossroads.",
}
T[4966] = {
  title = "Proteggi Kanati Greycloud",
  desc = "Però i centauri potrebbero essere più di quanti pensassi: ti chiedo, $N, di combattere al mio fianco contro questi vili assassini.",
  obj = "Proteggi Kanati Greycloud dall'attacco dei centauri.",
  reward = "Grazie del tuo aiuto, $N. Senza di te non sarei riuscito a tenerli a bada.",
  en_title = "Protect Kanati Greycloud",
  en_obj = "Protect Kanati Greycloud from the centaur attack.",
}
T[5041] = {
  title = "Rifornimenti per il Crossroads",
  desc = "L'attacco alla carovana conteneva rifornimenti di cui avevamo disperatamente bisogno.$B$BHai già avuto il coraggio di affrontare la tribù dei Razormane e ti chiedo di farlo ancora, ma stavolta tieni gli occhi aperti per i nostri rifornimenti perduti. Probabilmente li troverai sparsi nei loro accampamenti, mentre i quilboar si ingrassano con le loro azioni disonorevoli.$B$BLa gente del Crossroads ti sarebbe debitrice.",
  obj = "Trova e riporta le Crossroads' Supply Crates a Thork, nei Barrens.",
  progress = "Come procede la ricerca dei rifornimenti, $N? Immagino che i quilboar cadano facilmente sotto la tua forza.",
  reward = "Haha! Grazie, $N! Ci sarà di grande aiuto. Sei una benedizione per il Crossroads e per l'Orda. Se posso fare qualcosa per te, non esitare a chiedere.",
  en_title = "Supplies for the Crossroads",
  en_obj = "Find and return Crossroads' Supply Crates to Thork in the Barrens.",
}
T[5042] = {
  title = "La forza di Agamaggan",
  progress = "Mi serviranno 4 blood shards se desideri la forza di Agamaggan, $r.$B$BI tuoi nemici tremeranno davanti alla tua forza, se riceverai questa benedizione. <sbuffa>$B$BI più grandi guerrieri dei Razormane sono pervasi da tale potere!",
  reward = "Se solo Mangletooth fosse libero di vederti annientare coloro che lo hanno tradito! <sbuffa>$B$BTi ringrazio per aver distrutto altri Bristleback raccogliendo questi frammenti. Ti prego, continua a farlo, e io continuerò ad aiutarti. <sbuffa>",
  en_title = "Agamaggan's Strength",
}
T[5043] = {
  title = "L'agilità di Agamaggan",
  progress = "Si dice che i più grandi esploratori della mia tribù siano ineguagliabili nella mira, e che nessun rogue <sbuffo> possa stare al pari alla loro rapidità in battaglia.$B$BPortami 4 blood shard e ti renderò più agile di qualsiasi quilboar mai nato.",
  reward = "Possa la tua mira essere infallibile e il colpo della tua arma andare sempre a segno, $R.$B$BLo spirito di Agamaggan è con te. Torna <sbuffo> da me, se vuoi. Mangletooth ti benedirà di nuovo, se il grande dio cinghiale mi riterrà degno. <sbuffo>",
  en_title = "Agamaggan's Agility",
}
T[5044] = {
  title = "La saggezza di Agamaggan",
  progress = "Gli sciamani e i geomanti delle tribù dei quilboar <sbuffo> invocano la forza di Agamaggan per aiutarli in battaglia e nei loro rituali, $r.$B$BSe anche tu desideri il potere aggiunto della benedizione di Agamaggan per i tuoi incantesimi, portami 4 blood shard e Mangletooth ti aiuterà. <sbuffo>",
  reward = "I tuoi nemici dovrebbero temerti ancora di più, $R. <sbuffo>$B$BRaccontate a Mangletooth le storie della tua astuzia in battaglia, quando ci incontreremo di nuovo... in questa vita o nella prossima. <sbuffo>",
  en_title = "Wisdom of Agamaggan",
}
T[5045] = {
  title = "Spirito ascendente",
  progress = "I guerrieri di ogni sorta <sbuffo> hanno bisogno di uno spirito forte. Ti spinge a imprese più grandi quando ogni speranza è perduta. Neppure i Razormane <sbuffo> lo ignorano. Siamo una tribù spirituale: siamo più orgogliosi del nostro legame con Agamaggan che della nostra abilità <sbuffo> in battaglia.$B$BPortami 4 blood shard e benedirò il tuo spirito per la battaglia. <sbuffo>",
  reward = "I nostri guerrieri più grandi, e i nostri più grandi <sbuffo> sciamani, invidierebbero la tua volontà, $R.$B$BSconfiggi altri Bristleback sapendo che non possono fermarti! <sbuffo>",
  en_title = "Rising Spirit",
}
T[5046] = {
  title = "Razorhide",
  progress = "Tutti coloro che <sbuffo> entrano in battaglia hanno bisogno di protezione. Le loro ossa devono essere forti. La loro pelle dura. <sbuffo> Anche la mia tribù lo sa e, oltre alla protezione naturale che ci donano aculei e pelle, <sbuffo> spesso invochiamo Agamaggan perché ci protegga dal male prima di andare in guerra.$B$BPortami 4 blood shard <sbuffo> e ti concederò la stessa protezione.",
  reward = "Va' in guerra, $R.",
  en_title = "Razorhide",
}
T[5048] = {
  title = "La buona Emma",
  desc = "È un po' scorbutica, e forse le manca qualche rotella... ma dai registri risulta che Ol' Emma corrisponde davvero a chi potrebbe essere Emma Felstone.$B$BForse hai visto Ol' Emma girare per la città: parla da sola, di solito dicendo cose senza senso. Comunque non fa male a niente e a nessuno, quindi la gente la lascia in pace.$B$BTutto considerato, direi che Ol' Emma è proprio Emma Felstone. Potresti provare a chiederle se il suo cognome è davvero Felstone.",
  obj = "Trova Ol' Emma a Stormwind e scopri se è davvero Emma Felstone. Se lo è, forse le farebbe piacere il pacco che Janice Felstone ha preparato per lei.",
  progress = "Ti direi di levarti dal mio prato, ma come vedi non ce l'ho.",
  reward = "Il mio nome è proprio Emma Felstone: sei la prima persona da anni a chiamarmi così. Chi... chi sei?$B$BDici che conoscevi... mia sorella?! È ancora viva? Ma chi voglio prendere in giro, certo che no. Quando scoppiò la piaga a Lordaeron, mi aspettavo il peggio. Tanti della mia famiglia sono morti... o peggio. Ed eccomi qui, la pazza Ol' Emma, tutta sola. Che cosa sei, $Gun tombarolo:una tombarola; o qualcosa del genere? Cerchi il tuo prossimo bersaglio?$B$BCosa... hai un pacco per me da parte di mia sorella?",
  en_title = "Good Natured Emma",
  en_obj = "Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone.  If she is, then perhaps she'd like the package Janice Felstone made for her.",
}
T[5052] = {
  title = "I Blood Shard di Agamaggan",
  desc = "Insieme alle spine, il sangue ha toccato <grugnito> altre parti della terra: pietre rosso sangue mescolate agli altri minerali. I Bristleback dissotterrano questi Blood Shard e li portano come totem <grugnito> per avere forza in battaglia e come totem per le loro magie. <grugnito>$B$BIo conosco i segreti di quella magia.$B$BPorta a Mangletooth uno di questi Blood Shard per dimostrare che hai capito. Portane molti a Mangletooth, e ti benedirà con la magia quilboar — la magia di Agamaggan! <grugnito>",
  obj = "Porta un Blood Shard a Mangletooth, a Camp Taurajo, nelle Barrens.$B$BRaccogli altri Blood Shard se vuoi che ti benedica con il potere di Agamaggan.",
  progress = "Le nostre tribù si radunano nelle zone spinose di tutte le Barrens <grugnito> perché sono luoghi sacri, ma nessuno è sacro quanto il Razorfen. Il corpo di Agamaggan forma per intero il Razorfen, <grugnito> ma le Downs sono protette in modo particolare, perché l'ingresso è fatto delle sue grandi fauci! <grugnito> Inghiottirà interi quelli che non gli sono fedeli, e sputerà fuori i loro corpi dopo averli masticati! <grugnito>$B$BAgamaggan ha lasciato indietro il suo corpo per proteggerci, e dona il suo spirito perché noi possiamo proteggere lui. <grugnito>",
  reward = "Ah, hai capito davvero. <grugnito> Le mie parole non sono andate perse nelle tue orecchie, $R. Mangletooth sarà anche in gabbia, ma nessuna gabbia può fermare il potere di Agamaggan! <grugnito>$B$BIl contatto del Blood Shard, la sua sensazione... era da tanto, $R.$B$BSai com'è? Avere il tuo potere reciso da te?$B$BMa questa è una storia per un'altra volta. Ti ho promesso informazioni. Ti ho promesso il potere di Agamaggan. La mia gente ha voltato le spalle a Mangletooth. Ora ti scateno contro di loro. <grugnito>",
  en_title = "Blood Shards of Agamaggan",
  en_obj = "Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.$B$BCollect more Blood Shards if you want him to bless you with Agamaggan's power.",
}
T[5061] = {
  title = "Aquatic Form",
  desc = "Hai completato le lezioni che tutti i giovani druidi devono imparare prima di poter assumere un aspetto acquatico. Ora torna dal tuo istruttore, Mathrengyl Bearwalker, a Darnassus. Mostragli il tuo pendente e dimostragli che sei $Gpronto:pronta; a imparare ciò che ha da insegnarti. Completerà il tuo addestramento, permettendoti di diventare una cosa sola con l'acqua.$B$BArrivederci, giovane $Gdruido:druida;. Parleremo ancora.",
  obj = "Torna a Darnassus e mostra il Pendant of the Sea Lion a Mathrengyl Bearwalker.",
  progress = "La notizia del tuo ritorno a Darnassus ti ha preceduto, ma mi servirà una prova delle lezioni che hai imparato a Moonglade prima di insegnarti la tua Aquatic Form.$B$BHai il Pendant of the Sea Lion?",
  reward = "Davvero notevole, $N. Sei $Gpronto:pronta; a imparare la tua Aquatic Form, ed è un piacere per me insegnartela.$B$BInoltre, in riconoscimento di quanto hai fatto nelle due prove, ti do questo oggetto. Spero che sia un'aggiunta gradita al tuo equipaggiamento di $Gprotettore:protettrice; della natura e custode dell'equilibrio.",
  en_title = "Aquatic Form",
  en_obj = "Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion.",
}
T[5062] = {
  title = "Il fuoco sacro",
  desc = "Arikara è una creatura letale di cui bisogna occuparsi in fretta. Per darle la caccia dovrai accendere il fuoco sacro della vita: sarà questo a evocare Arikara.$B$BVa' a raccogliere la rara pianta di Incendia agave. Quando ne avrai raccolta abbastanza, va' a chiedere consiglio a Magatha Grimtotem, all'Elder Rise di Thunder Bluff. È una sciamana potente e può incantare la pianta di agave per creare una polvere che accenda il fuoco.$B$BViaggia a nord-est fino al Boiling Pool e raccogli Incendia Agave.",
  obj = "Raccogli 10 fasci di Incendia Agave, poi consulta Magatha Grimtotem, all'Elder Rise di Thunder Bluff.",
  progress = "Allora, Motega Firemane manda notizia di Arikara... be', è una brutta notizia.$B$B<Magatha si guarda intorno.>$B$BArikara è una creatura letale che nasce solo per cercare vendetta contro chi ha commesso atti atroci.$B$B<Magatha sorride.>",
  reward = "Bene, hai raccolto la quantità necessaria di Incendia agave. Quest'erba rara, che si trova solo a Thousand Needles, aiuterà ad accendere il fuoco sacro della vita, ormai sopito.$B$B<Magatha comincia a incantare l'Incendia agave.>",
  en_title = "Sacred Fire",
  en_obj = "Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.",
}
T[5064] = {
  title = "Spiare i Grimtotem",
  desc = "$N, in passato ci hai servito bene, e per questo ora ti affido una missione importante. Il Grimtotem Clan sta tramando qualcosa in segreto. Nelle ultime settimane tre agenti di origine ignota sono stati visti in visita dai Grimtotem. Abbiamo scoperto che questi messaggi sorvegliati si trovano in casse separate a Darkcloud Pinnacle.$B$B$N, se riuscirai in questa missione pericolosa, ti ricompenserò come meriti.",
  obj = "Trova e recupera le tre Secret Note a Darkcloud Pinnacle.",
  progress = "Hai scoperto cosa stanno tramando i Grimtotem?",
  reward = "Grande Spirito del Totem! Sono notizie davvero gravi. Devo cominciare a prepararmi a qualunque cosa accada.$B$B$N, come promesso, ecco la tua ricompensa per il coraggioso servizio.",
  en_title = "Grimtotem Spying",
  en_obj = "Locate and retrieve the three Secret Notes in Darkcloud Pinnacle.",
}
T[5066] = {
  title = "Chiamata alle armi: le Plaguelands!",
  desc = "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!$B$BIl Regno di Stormwind ha lanciato una chiamata alle armi! Tutti coloro che sono in grado di combattere sono invitati a prendere le armi contro l'oscura minaccia del Flagello nelle terre settentrionali degli Eastern Kingdoms! Corrono voci di nuove minacce che sorgono dalle rovine delle Plaguelands!$B$BEroi del reame, cercate Commander Ashlam Valorfist, che ha allestito il suo accampamento a Chillwind Camp, a nord delle Alterac Mountains!",
  obj = "Cerca Commander Ashlam Valorfist. Il suo accampamento si trova a Chillwind Camp, a nord delle Alterac Mountains.",
  reward = "$GBenvenuto:Benvenuta; nelle Plaguelands, $Geroe:eroina;. È una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia incombente del Flagello a nord e a nord-est. Sono lieto di sapere che il richiamo del dovere e del servizio al bene comune non è caduto nel vuoto con te!$B$BSe sei $Gpronto:pronta; a sporcarti le mani, qui ai margini delle Plaguelands c'è tanto da fare per gli eroi volenterosi e capaci.",
  en_title = "A Call to Arms: The Plaguelands!",
  en_obj = "Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.",
}
T[5088] = {
  title = "Arikara",
  desc = "Porta questa polvere di Incendia raffinata e purificata a Thousand Needles e gettala sul fuoco sacro della vita. Si trova a Darkcloud Pinnacle, su un pinnacolo isolato dove seppelliscono i loro morti.$B$BL'incantesimo che ho intessuto nella polvere di Incendia evocherà Arikara davanti a te, $N.$B$BTemo che stia dando la caccia a Cairne Bloodhoof; troppe tradizioni tauren sono cambiate, e temo che questo abbia fatto infuriare Arikara. Muoviti in fretta, prima che tutto sia perduto, $C!",
  obj = "Uccidi Arikara. Porta i suoi resti e la polvere di Incendia a Motega Firemane, a Whitereach Post, come prova di quel che hai fatto.",
  progress = "Hai ucciso il serpente feroce, Arikara, $N?",
  reward = "Non ha senso. Perché Arikara dovrebbe dare la caccia a Cairne Bloodhoof? Magatha non può sbagliarsi, è la nostra sciamana più potente.$B$B<Motega scuote la testa.>$B$BIn ogni caso la tua grande impresa per l'Orda non passerà inosservata: ti prego, scegli una di queste cose come ricompensa per il tuo aiuto.",
  en_title = "Arikara",
  en_obj = "Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed.",
}
T[5147] = {
  title = "Wanted — Arnak Grimtotem",
  desc = "Wanted: Arnak Grimtotem$B$BArnak il reietto è ricercato per gli atroci crimini di omicidio e rapimento. Belle ricompense saranno date a chi avrà il coraggio di consegnare questo criminale alla giustizia.$B$BArnak è stato visto l'ultima volta sulle scogliere vicino a Darkcloud Pinnacle. Mostra la prova di quel che hai fatto a Cliffwatcher Longhorn, a Freewind Post, per riscuotere la ricompensa.",
  obj = "Uccidi Arnak Grimtotem e porta la prova di quel che hai fatto a Cliffwatcher Longhorn, a Freewind Post.",
  progress = "Hai notizie di quell'assassino di Arnak Grimtotem?",
  reward = "Ah! Be', questa sì che è un'ottima notizia! Cominciavo a pensare che non sarebbe mai stato consegnato alla giustizia!$B$BEccoti qua, $N... e grazie. La notizia delle malefatte di Arnak mi faceva ribollire il sangue!",
  en_title = "Wanted - Arnak Grimtotem",
  en_obj = "Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post.",
}
T[5151] = {
  title = "Hypercapacitor Gizmo",
  desc = "Sono l'unico superstite dell'attacco dei centauri alla nostra carovana! Una pantera rara ma possente sta facendo la guardia al mio aggeggio migliore, che porta al collo. Ah! Perfino i centauri tremano davanti a quella bestia feroce!$B$BEcco la chiave della gabbia. Là hanno preso tutto, ma lei l'hanno lasciata stare. Uccidi questa bestia e riportami il mio ipercondensatore, e ti ricompenserò.$B$BLa carovana distrutta è appena a nord di qui.",
  obj = "Uccidi la bestia e riporta l'Hypercapacitor Gizmo e la Panther Cage Key a Wizlo Bearingshiner.",
  progress = "Ce l'hai il mio ipercondensatore?",
  reward = "Il mio ipercondensatore! Questo mi terrà occupato per un bel po', finché non capirò a cosa serve...",
  en_title = "Hypercapacitor Gizmo",
  en_obj = "Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner.",
}
T[5261] = {
  title = "Eagan Peltskinner",
  desc = "Eagan Peltskinner cerca qualcuno che cacci lupi per lui. È una buona notizia, perché ultimamente a Northshire Valley vediamo molti più lupi.$B$BSe sei interessat$Go:a;, parla con Eagan. Lo trovi sul lato dell'abbazia, a sinistra.",
  obj = "Parla con Eagan Peltskinner.",
  reward = "È vero. Cerco qualcuno che cacci un po' di lupi per me! Sei tu quella persona?",
  en_title = "Eagan Peltskinner",
  en_obj = "Speak with Eagan Peltskinner.",
}
T[5321] = {
  title = "Il Dormiente si è risvegliato",
  desc = "Stavo andando a Maestra's Post per incontrare Liladris Moonriver, ma ho deciso di fermarmi qui a fare un breve pisolino. Da quando mi sono svegliato dal sogno di smeraldo, ho tanto sonno...$B$B<sbadiglio>$B$BTi dispiacerebbe mostrarmi la strada? Mi pare che Maestra's Post sia a sud di qui, lungo la strada di Ashenvale. Può essere pericoloso, quindi spero tu abbia degli amici che si uniscano a noi.$B$BInfine, potrei addormentarmi: se mai dovessi svegliarmi, usa il mio corno. Lo troverai nel baule qui.",
  obj = "Scorta Kerlonian Evershade da Liladris Moonriver a Maestra's Post, ad Ashenvale.",
  progress = "Kerlonian è arrivato?",
  reward = "Oh, sono così felice che Kerlonian ce l'abbia fatta! E sono certa che lo troverò addormentato da qualche parte qui intorno, vero?$B$BGrazie per avergli mostrato la strada, $N.",
  en_title = "The Sleeper Has Awakened",
  en_obj = "Escort Kerlonian Evershade to Liladris Moonriver at Maestra's Post in Ashenvale.",
}
T[5361] = {
  title = "Albero genealogico",
  desc = "Mio fratello Nataka è di stanza al Ghost Walker Post, laggiù a Desolace. Vorrei chiederti... potresti consegnargli questo rapporto da parte mia? È passato un anno dall'ultima volta che gli ho scritto: da allora i centauri sono stati insolitamente attivi, e lui dovrebbe esserne informato.$B$BViaggia fino alla Stonetalon Mountain, a nord del Crossroads, e poi dirigiti a ovest nella Charred Vale. Da lì prosegui a sud, fino a Desolace; là troverai una strada che porta a sud, fino al Ghost Walker Post.",
  obj = "Consegna Cliffwatcher Longhorn Report a Nataka Longhorn, al Ghost Walker Post, a Desolace.",
  progress = "Che notizie porti, $C? Ah, un messaggio da parte di mio fratello, dici? Be', allora consegnami il rapporto!",
  reward = "Non so che legame tu abbia con mio fratello, ma a quanto pare ha fiducia in te, $C.$B$BIo sono Nataka Longhorn e vorrei darti il benvenuto al Ghost Walker Post: abbiamo molto bisogno di $Gun:una; $C! Parla con gli altri, forse qui c'è bisogno di te.",
  en_title = "Family Tree",
  en_obj = "Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace.",
}
T[5381] = {
  title = "Hand of Iruxos",
  desc = "La Burning Blade possiede la Demon Box. Al suo interno si trova la potente Hand of Iruxos. La Burning Blade la usa per aprire portali demoniaci alla Mannoroc Coven. Dobbiamo fermare l'ondata di demoni che entra nel nostro mondo, $N!$B$BUsa questo Demon Pick sul cristallo rosso nella Thunder Axe Fortress per accedere alla Demon Box.",
  obj = "Recupera la Demon Box dalla Thunder Axe Fortress e riportala, insieme al Demon Pick, a Taiga Wisemane, a Shadowprey Village.",
  progress = "$N, hai la Demon Box?",
  reward = "Ah, la Demon Box. Dammela, $C, e la aprirò... rivelandoti così la Hand of Iruxos.",
  en_title = "Hand of Iruxos",
  en_obj = "Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village.$B",
}
T[5386] = {
  title = "Il pescato del giorno",
  desc = "Qui al Ghost Walker Post manca da tempo l'odore del pesce cotto. I troll di Shadowprey Village sono i migliori a pescare... ma purtroppo, con i centauri così attivi, ho poco tempo per fare un viaggio fino dai troll. Mmh...$B$BFammi un favore e va' a Shadowprey Village. Parla con Jinar'Zillen, il pescatore del posto, e portami i Bloodbelly Fish, i miei preferiti. La strada a sud di qui ti porterà a ovest, fino al villaggio dei troll.",
  obj = "Parla con Jinar'Zillen a Shadowprey Village, poi porta a Nataka Longhorn 2 Bloodbelly Fish.",
  progress = "Mi formicola lo zoccolo e mi viene l'acquolina in bocca quando penso ai Bloodbelly Fish fritti... Ne hai con te?",
  reward = "Sei $Gun salvatore:una salvatrice;, $N! Questi Bloodbelly Fish sembrano così buoni che si potrebbero quasi mangiare crudi.$B$B<Nataka comincia a salivare.>$B$BEcco qua — scegli uno di questi oggetti come pagamento per questi pesci.",
  en_title = "Catch of the Day",
  en_obj = "Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish.",
}
T[5421] = {
  title = "Pesci nel secchio",
  progress = "Ricompenserò chiunque mi renda la vita un po' più facile... Mi piace fare il meno possibile, $Gamico:amica;!$B$BSotto i moli, qui a Shadowprey Village, ho un sacco di trappole per molluschi. Se sei così gentile da fare il lavoro al posto mio e raccogliermi i molluschi, ti ricompenserò con qualcosa che vuoi... capisci cosa intendo, $Gamico:amica;? Per ogni cinque molluschi che mi porti ti darò un bel Bloodbelly Fish!",
  reward = "Ottimo, $Gamico:amica;, non c'è niente di meglio di un lavoro fatto, soprattutto se a farlo è qualcun altro... eh?",
  en_title = "Fish in a Bucket",
}
T[5441] = {
  title = "Peon pigri",
  desc = "Maledetti peon! Lavorano duramente raccogliendo legname dagli alberi della valle, ma fanno sempre pisolini! Mi serve qualcuno che aiuti a tenerli in riga.$B$BSembri proprio il $r giusto per il mio compito. Tieni, prendi questo blackjack e usalo su ogni peon pigro che trovi addormentato sul lavoro. Una bella botta li rimetterà subito al lavoro! Restituisci il blackjack quando hai finito.$B$BPeon fannulloni...",
  obj = "Usa il Foreman's Blackjack sui Lazy Peon quando dormono. Sveglia 5 peon, poi riporta il Foreman's Blackjack a Foreman Thazz'ril nella Valley of Trials.",
  progress = "Pigri buoni a nulla...$B$BEh? Hai il mio blackjack? Hai trovato dei peon addormentati sul lavoro?!",
  reward = "Bene, bene. Magari la prossima volta ci penseranno due volte prima di battere la fiacca! Grazie dell'aiuto!",
  en_title = "Lazy Peons",
  en_obj = "Use the Foreman's Blackjack on Lazy Peons when they're sleeping.  Wake up 5 peons, then return the Foreman's Blackjack to Foreman Thazz'ril in the Valley of Trials.",
}
T[5481] = {
  title = "Il compito di Gordo",
  desc = "Padrone vuole erbacce. Noi avere mani grosse e non bravi a raccogliere. Tu aiuti noi e noi non fa' male a te. Noi serve gloom weed. Tante erbe qui intorno e vicino strada.$B$BQuando hai gloom weed, tu porti a Padrone Holland nel cimitero di Brill.",
  obj = "Raccogli 3 Gloom Weed e consegnale a Junior Apothecary Holland nel cimitero di Brill.",
  progress = "Dov'è quella inutile abominazione? O hai ciò che mi serve, o faresti meglio ad andare là fuori a trovarlo.",
  reward = "Che cos'è questo? Gloom weed?! Non so che farmene della gloom weed! Quel cumulo di carne senza cervello è là fuori a raccogliere margherite e a convincere la Lady sa quanti babbei come te a fare lo stesso. Senza offesa.$B$BVa bene, ormai sei qui e questo è ciò che conta. Dato che non mi prenderò il disturbo di spiegare le cose a quell'abominazione, perché non raccogli ciò che mi serve davvero... la doom weed!",
  en_title = "Gordo's Task",
  en_obj = "Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in the Brill graveyard.",
}
T[5482] = {
  title = "Doom Weed",
  desc = "Dunque vedi il guaio in cui mi trovo, $N. Quella cosa là fuori raccoglie le erbe sbagliate! Ti ricompenserò a dovere se raccoglierai ciò che mi serve. Portami abbastanza doom weed e avrai una ricompensa adeguata.$B$BPer quanto ne so, amano infestare la flora vicino alla fossa comune, a nord del cimitero di Brill. Sbrigati e fai attenzione ai gnoll della zona.",
  obj = "Raccogli 10 Doom Weed e riportale a Junior Apothecary Holland.$B",
  progress = "Spero proprio che sia roba buona. Immagino tu abbia tutta la doom weed che mi serve?",
  reward = "Ah, la mia doom weed. Eccellente!$B$B<Junior Apothecary Holland si strofina le mani con avidità.>$B$BQuesta mi tornerà molto utile. Oggi hai fatto un bel servizio a me, ehm, alla Lady, $N. Come promesso, ecco la ricompensa che meriti.",
  en_title = "Doom Weed",
  en_obj = "Collect 10 Doom Weed and deliver them back to Junior Apothecary Holland.$B",
}
T[5501] = {
  title = "Il raccoglitore di ossa",
  desc = "Qui abbiamo per le mani una miniera d'oro, te lo dico io — una miniera d'oro! Le ossa di kodo cambieranno il mondo per sempre... ho clienti che ci fanno mobili, strumenti musicali e perfino polvere esplosiva.$B$BC'è una carovana che passa a ritirare le mie ossa di kodo e poi le vende a Shadowprey Village. Se riesci ad andare al Kodo Graveyard a sud di qui e a portarmi dieci Kodo Bone, ti darò qualcosa in cambio. Affare fatto?",
  obj = "Porta 10 Kodo Bone dal Kodo Graveyard a Bibbly F'utzbuckle, al Kormek's Hut.",
  progress = "Hai le ossa? La carovana arriverà da un momento all'altro. Mi servono solo altri dieci Kodo Bone per raggiungere il record della mia carriera. Il record della mia carriera, te lo dico io!",
  reward = "Ah, che bello! Le mie ossa!$B$BNon vedo l'ora che i ragazzi a casa vedano la mia faccia sulla copertina di Goblin'preneur. Sarò il goblin più ricco del mondo... e il mio insegnante di educazione fisica diceva che non avrei mai combinato niente.",
  en_title = "Bone Collector",
  en_obj = "Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut.",
}
T[5502] = {
  title = "$GUn tutore:Una tutrice; dell'Orda",
  desc = "Sei $Gstato:stata; così gentile con me, $N. Non avrei mai sognato di divertirmi così tanto durante la Settimana dei Bambini. Grazie. Non sarò triste per quello che mi è successo: i miei genitori mi hanno sempre detto di superare qualunque cosa brutta succeda. Sarò un eroe... proprio come te.$B$BMi dispiace dirlo, ma è ora che torni a casa. Torniamo indietro, e dirò alla matrona che persona fantastica sei!",
  obj = "Riporta il tuo protetto all'orfanotrofio di Orgrimmar consegnando l'Orcish Orphan Whistle a Orphan Matron Battlewail, nella Valley of Honor.",
  progress = "È un piacere rivederti, $N. Hai portato a termine i compiti di cui ti sei $Gfatto:fatta; carico durante la Settimana dei Bambini?",
  reward = "Che gli spiriti ti benedicano, $N. Hai fatto per Grunth più di quanto la maggior parte della gente penserebbe mai di fare per lui. Grazie: sei l'esempio perfetto di cosa significhi essere $Gun eroe:un'eroina; dell'Orda.$B$BTi prego, se riesci a trovare un po' di tempo, torna a trovarci. So che a Grunth farebbe piacere, e anche a me.$B$BGrunth si è divertito tantissimo con te, $N. Voleva darti uno dei suoi animaletti preferiti, perché ti ricordi di lui.",
  en_title = "A Warden of the Horde",
  en_obj = "Return your ward to the Orgrimmar orphanage by handing in the Orcish Orphan Whistle to Orphan Matron Battlewail in the Valley of Honor.",
}
T[5541] = {
  title = "Munizioni per Rumbleshot",
  desc = "Hegnar Rumbleshot vende armi da fuoco lungo la strada per Anvilmar. Fucilieri e squadre di mortai passano molto tempo ad addestrarsi vicino al suo negozio, e lui ha sempre bisogno di munizioni fresche.$B$BMa... l'ultima cassa di munizioni che gli ho mandato si è persa per strada. Il mio corriere dice che era accampato vicino al Grizzled Den quando i wendigo l'hanno messo in fuga... e quello sciocco ha lasciato lì le munizioni di Rumbleshot!$B$B$N, puoi recuperare quelle munizioni e portarle a Rumbleshot? Le sta aspettando e sono sicuro che è quasi a secco.",
  obj = "Porta Rumbleshot's Ammo a Hegnar Rumbleshot a Dun Morogh.",
  progress = "Spero che tu non sia qui per le munizioni, perché le ho quasi finite!",
  reward = "Fantastico, altre munizioni! Finalmente è arrivata la spedizione del vecchio Loslor! Saranno anche in ritardo, ma come diceva sempre mio nonno: meglio tardi che mai!$B$BGrazie mille, $N. Ho già dei clienti che non vedono l'ora di averle!",
  en_title = "Ammo for Rumbleshot",
  en_obj = "Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.",
}
T[5545] = {
  title = "Un fascio di guai",
  desc = "Ho un bel problema per le mani. Ho una scadenza incombente per un ordine di legname e il tempo stringe. I lupi e gli orsi a nord di qui hanno cacciato i miei operai lontano dai fasci di legna che avevano già tagliato.$B$BHo già parlato con Deputy Rainer per far sgombrare gli animali, ma mi serve qualcuno che vada a raccogliere la legna per me. Se riuscissi a portarmi otto fasci di legna, potrei rispettare la scadenza.",
  obj = "Porta 8 Bundle of Wood a Raelen all'Eastvale Logging Camp.",
  progress = "Quella scadenza non si allontana di certo, $C. Ti prego, sbrigati a raccogliere quei fasci di legna.",
  reward = "Eccellente! Grazie a te dovrei riuscire a completare l'ordine in tempo. Per dimostrarti la mia gratitudine, vorrei offrirti qualche moneta come compenso per il disturbo.$B$BGrazie e addio.",
  en_title = "A Bundle of Trouble",
  en_obj = "Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp.",
}
T[5561] = {
  title = "Il raduno dei kodo",
  desc = "Bibbly pensa di essere l'unico goblin di Desolace che sa fare soldi. Beh, l'unica carovana abbastanza coraggiosa da viaggiare da queste parti dipende da me. Da quando ho imparato a ringiovanire e a controllare i kodo vecchi e morenti con il mio Kodo Kombobulator, Cork, il proprietario della carovana, Rigger e io siamo entrati in società.$B$BPrendi il kombobulator e usalo su qualunque kodo antico, vecchio o morente: con una scossa trasformerà la bestia in un kodo addomesticato e la costringerà a seguirti. Quando avrai addomesticato un kodo, riportamelo.",
  obj = "Riporta cinque Tamed Kodo e il Kodo Kombobulator a Smeed Scrabblescrew, allo Scrabblescrew's Camp.",
  progress = "La carovana arriverà a breve: hai i cinque nuovi kodo addomesticati che ti avevo chiesto?",
  reward = "<Smeed Scrabblescrew comincia a contare.>$B$BTre, quattro e cinque... eccellente, chiedo cinque kodo addomesticati e ottengo cinque kodo addomesticati... diventerò ricco... sì, ricchissimo! Spero di vedere la faccia verde di Bibbly quando saprà del mio successo!",
  en_title = "Kodo Roundup",
  en_obj = "Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.",
}
T[5581] = {
  title = "I portali della Legione",
  desc = "Guarda — la Hand of Iruxos. Uno spettacolo davvero raccapricciante.$B$BDevi possederla, se si vogliono chiudere i portali demoniaci della Mannoroc Coven... ed è ciò che ora ti chiedo di fare. La minaccia dei demoni sta crescendo e dobbiamo chiudere questi portali per arginare l'ondata di demoni diretta verso questo mondo. Buona fortuna, $N... e fa' attenzione ai guardiani dei portali.",
  obj = "Chiudi 6 portali alla Mannoroc Coven e torna da Taiga Wisemane, a Shadowprey Village.",
  progress = "Hai chiuso i portali demoniaci della Mannoroc Coven?",
  reward = "Meriti un encomio, $N. Il tuo impegno ha aiutato molto nella lotta contro la minaccia dei demoni, e per questo tutta Azeroth è più sicura.",
  en_title = "Portals of the Legion",
  en_obj = "Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village.",
}
T[5621] = {
  title = "Le vesti della Luna",
  desc = "Ho bisogno del tuo aiuto, $N. Devo restare qui ad addestrare gli altri allievi, ma tu, tu puoi aiutare una delle nostre Sentinelle ferite, poco a sud di Dolanaar. È stata ferita mentre pattugliava il villaggio e le farebbe comodo il nostro aiuto. Si chiama Shaya.$B$BQuando la trovi, cura le sue ferite e poi rafforza il suo corpo con i tuoi incantesimi. Così almeno sarà protetta più a lungo, se dovesse finire nei guai. Torna qui da me dopo aver compiuto il tuo dovere verso Elune.",
  obj = "Trova Sentinel Shaya e cura le sue ferite con Lesser Heal (Rank 2). Poi concedile Power Word: Fortitude e torna da Laurna Morninglight, a Dolanaar.",
  progress = "I nostri incantesimi di Fortify sono molto potenti, Delor. Permettono ai nostri compagni di sopportare più ferite da ogni tipo di attacco e di sopravvivere in situazioni in cui di solito cadrebbero. Ma non è niente in confronto alla nostra capacità di guarire. Non ci sono guaritori più grandi di un sacerdote — ricordalo bene. Il tuo potere da solo può facilmente cambiare le sorti di una battaglia.",
  reward = "Hai fatto bene e hai servito Elune. Per questo ti ringrazio.$B$BTi prego, prendi questa veste come segno della mia gratitudine. Significa che hai conquistato il tuo posto nel nostro ordine. Se vuoi, indossala con orgoglio, ma in ogni caso ti riconosceremo sempre come $Guno:una; dei nostri.$B$BVa' con Elune, $N, e grazie.",
  en_title = "Garments of the Moon",
  en_obj = "Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.",
}
T[5622] = {
  title = "Nelle grazie di Elune",
  desc = "$N, devi andare a Dolanaar quando avrai finito i tuoi affari qui a Shadowglen. Là troverai Laurna Morninglight. Ti istruirà ancora nelle vie di Elune, ed è con lei che ti guadagnerai le tue prime vesti, segno del tuo rango di $Gsacerdote:sacerdotessa; di Elune.$B$BAbbi cura di te, e che tu sia $Gprotetto:protetta; nei tuoi viaggi.",
  obj = "Parla con Laurna Morninglight, a Teldrassil.",
  reward = "Sono felice di vedere che Shanda ti ha mandato da me, $N. Insegnare le vie di Elune ai giovani sacerdoti mi dà una grande soddisfazione.",
  en_title = "In Favor of Elune",
  en_obj = "Speak to Laurna Morninglight in Teldrassil.",
}
T[5623] = {
  title = "Nelle grazie della Luce",
  desc = "Salve di nuovo, $Ggiovane sacerdote:giovane sacerdotessa;. È giunto il momento che tu impari di più sulla nostra religione. Dopo aver completato i compiti che hai qui a Northshire, cerca Priestess Josetta a Goldshire. Ha altro da insegnarti e ha sentito dire che stai diventando forte nelle vie della Luce. Non vede l'ora di continuare a istruirti.",
  obj = "Parla con Priestess Josetta, nell'Elwynn Forest.",
  reward = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Abbiamo molto di cui parlare riguardo al tuo futuro e al tuo cammino nella Luce.",
  en_title = "In Favor of the Light",
  en_obj = "Speak to Priestess Josetta in Elwynn Forest.",
}
T[5624] = {
  title = "Le vesti della Luce",
  desc = "Di solito propongo una piccola sfida ai seguaci della Luce per mettere alla prova la loro abilità. Voglio vedere se sono degni di indossare le loro prime vesti — segno che la chiesa approva apertamente $Gil sacerdote:la sacerdotessa; e $Glo:la; sostiene.$B$BMa questa situazione è un po' diversa. Uno dei cittadini di Goldshire ha visto una guardia ferita vicino al lago, a est di qui. Si chiama Roberts. Trovalo, curalo, rafforza il suo corpo e torna qui. Se riesci a farlo per me, considererò la tua prova superata.",
  obj = "Trova Guard Roberts e cura le sue ferite con Lesser Heal (Rank 2). Poi concedigli Power Word: Fortitude e torna da Priestess Josetta, a Goldshire.",
  progress = "Come forse avrai già imparato, le nostre magie di guarigione sono vitali per la sopravvivenza della nostra gente in questi tempi duri — soprattutto per gli avventurieri e gli eroi che impugnano armi e magia per respingere tante minacce diverse.$B$BFaresti bene a ricordare sempre quanto sia importante questa abilità. Questa, unita a Fortitude, rende i tuoi compagni molto più capaci in battaglia, perché potranno reggere un numero maggiore di colpi.$B$BNon lasciare che nessuno sminuisca quanto sono potenti le tue magie.",
  reward = "Eccellente, $N. Con una guardia in salute in più là fuori ad aiutare il villaggio, saremo molto più al sicuro. Mi fa piacere vedere che stai già imparando a usare le tue abilità con saggezza. Se in qualsiasi momento ti senti $Gpronto:pronta; per altro addestramento, torna pure da me. Ma per ora prendi questa veste. Farà sapere agli altri che fai parte del nostro ordine. Se non vuoi indossarla, va bene lo stesso. Più avanti ci saranno altre prove, e per quelle questa veste non serve.",
  en_title = "Garments of the Light",
  en_obj = "Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire.",
}
T[5625] = {
  title = "Le vesti della Luce",
  desc = "Di solito è più o meno a questo punto che chi ha il tuo potere viene messo alla prova per vedere se è degno di indossare le vesti che indicano il suo posto nella chiesa. Ma, a dire il vero, ho questioni più urgenti di cui occuparmi. Un cittadino di Kharanos è appena venuto qui a dirmi di un montanaro ferito appena fuori dal villaggio, a sud — si chiama Dolf.$B$BTu cura Dolf e dagli Fortitude, e io considererò conclusa la tua prova. Che ne dici?",
  obj = "Trova Mountaineer Dolf e cura le sue ferite con Lesser Heal (Rank 2). Poi concedigli Power Word: Fortitude e torna da Maxan Anvol, a Kharanos.",
  progress = "Hai già trovato Dolf, $N?$B$BProbabilmente l'avrai già imparato, ma la nostra capacità di guarire è molto utile. Non solo possiamo prenderci cura dei feriti, ma siamo indispensabili per la sopravvivenza di tutti quegli aspiranti eroi là fuori che cercano di farsi un nome. Con Fortitude ad aumentare i colpi che possiamo reggere, e la nostra magia di guarigione a tenerli in vita, non c'è niente che non possiamo superare!",
  reward = "Eccellente, $N. Con una guardia in salute in più là fuori ad aiutare il villaggio, saremo molto più al sicuro. Mi fa piacere vedere che stai già imparando a usare le tue abilità con saggezza. Se in qualsiasi momento ti senti $Gpronto:pronta; per altro addestramento, torna pure da me. Ma per ora prendi questa veste. Farà sapere agli altri che fai parte del nostro ordine. Se non vuoi indossarla, va bene lo stesso. Più avanti ci saranno altre prove, e per quelle questa veste non serve.",
  en_title = "Garments of the Light",
  en_obj = "Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.",
}
T[5626] = {
  title = "Nelle grazie della Luce",
  desc = "Ehi! $N! Hai un minuto?!$B$BSegui la Luce da abbastanza tempo ormai: è ora che tu vada da Maxan Anvol, a Kharanos. Ti insegnerà di più sul cammino che stai seguendo e, se ti dimostrerai $Gdegno:degna;, ti darà le tue prime vesti, segno del tuo rango di $Gsacerdote:sacerdotessa;.$B$BOra muoviti! Appena hai finito qui, attraversa il tunnel — ti starà aspettando.",
  obj = "Parla con Maxan Anvol, nel Dun Morogh.",
  reward = "Oh, quindi ti ha mandato Branstock, eh? Bene, bene! Ha ragione, è ora che tu faccia un passo molto più grande verso la Luce. Ti formerà il carattere e ti renderà più forte... ed è quello che ti servirà più di ogni altra cosa: forza del corpo... forza della volontà.",
  en_title = "In Favor of the Light",
  en_obj = "Speak to Maxan Anvol in Dun Morogh.",
}
T[5627] = {
  title = "Le stelle di Elune",
  reward = "Ti sei $Gdimostrato:dimostrata; $Gdegno:degna; dell'attenzione di Elune, $N. Se ti senti $Gpronto:pronta;, mi piacerebbe molto insegnarti uno dei suoi incantesimi riservati al nostro popolo.",
  en_title = "Stars of Elune",
}
T[5628] = {
  title = "Il ritorno a casa",
  desc = "Ah, sì, salve, $N? Mi fa piacere che ti sia $Gfermato:fermata; a parlare un momento. Sei $Glontano:lontana; da casa, così giovane — ammiro questa ambizione. Vorrei aver trovato, da giovane, il coraggio di girare il mondo.$B$BNon molto tempo fa è passata di qui una sacerdotessa del tuo ordine a cercarti. Ha detto che era molto urgente che tu tornassi al Temple of the Moon di Darnassus e parlassi con Priestess Alathea — aveva a che fare con il tuo addestramento. Se puoi, non indugerei troppo.",
  obj = "Parla con Priestess Alathea, a Darnassus.",
  reward = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5629] = {
  title = "Il ritorno a casa",
  desc = "Salve di nuovo, $N. So che hai avuto da fare ad aiutare la nostra gente, ma devi prenderti un po' di tempo anche per te. Priestess Alathea ha mandato qualcuno qui a cercarti. Sembra che tu abbia attirato l'attenzione dei nostri anziani, e ritengono che tu sia $Gpronto:pronta; per cose più grandi. Va' al Temple of the Moon di Darnassus e cerca Alathea. Ti starà aspettando. Buona fortuna, e che Elune sia con te.",
  obj = "Parla con Priestess Alathea, a Darnassus.",
  reward = "Magnifico, sei $Gtornato:tornata;, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5630] = {
  title = "Il ritorno a casa",
  desc = "Salve, $Gragazzo:ragazza;. Che bello vederti viaggiare in lungo e in largo verso terre lontane. Senza offesa, ma molti della tua gente di solito non sopportano bene questi climi freddi. Mi fa piacere vedere che sei $Gfatto:fatta; di una pasta più dura.$B$BNon molto tempo fa è passata di qui una delle vostre sacerdotesse a cercarti — ha detto qualcosa sul fatto che dovevi trovare una certa Priestess Alathea nel Temple of the Moon, giù a Darnassus. Ha detto che era importante e che dovresti tornarci presto.",
  obj = "Parla con Priestess Alathea, a Darnassus.",
  reward = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5631] = {
  title = "Il ritorno a casa",
  desc = "Da poco una sacerdotessa è venuta nelle nostre sale a cercarti, giovane $R. Ha detto che aveva il compito di trovarti e che dovresti tornare al Temple of the Moon di Darnassus il prima possibile. Quando arrivi, cerca una certa Priestess Alathea — ti dirà di più.$B$BChe la Luce sia con te, $N.",
  obj = "Parla con Priestess Alathea, a Darnassus.",
  reward = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5632] = {
  title = "Il ritorno a casa",
  desc = "Oh, sì, certo. Salve, $N. Non molto tempo fa è passata di qui una messaggera del nostro ordine a cercarti. Ha parlato di qualcosa di importante che sta succedendo a Darnassus, e ha detto che dovresti tornare al Temple of the Moon appena puoi. Quando arrivi, parla con Priestess Alathea. Credo che abbia a che fare con i tuoi ottimi progressi nelle nostre vie.$B$BTe lo ripeto: torna a Darnassus quando puoi.",
  obj = "Parla con Priestess Alathea, a Darnassus.",
  reward = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5633] = {
  title = "Il ritorno a casa",
  desc = "Salute, $Gragazzo:ragazza;. Che bello vederti qui nelle nostre grandi sale. Che una benedizione sia su di te e sulla tua gente.$B$BMentre viaggiavi per le nostre terre, una sacerdotessa del tuo tempio è venuta qui a cercarti. Ha detto che dovevi tornare al Temple of the Moon il prima possibile. Mi dispiace non poterti dire di più, ma sembrava importante. Quando arrivi al tempio, parla con una certa Priestess Alathea.",
  obj = "Parla con Priestess Alathea, a Darnassus.",
  reward = "Magnifico, sei $Gtornato:tornata; a casa, $N. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della faccenda in questione, potrai raccontarmi di più dei tuoi viaggi.",
  en_title = "Returning Home",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5634] = {
  title = "Desperate Prayer",
  reward = "Hai reso un grande servizio alla Luce diventando un esempio luminoso per chi viaggia in queste terre pericolose e oltre. Ti prego, accetta questa lezione come ringraziamento per tutto ciò che hai fatto.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5635] = {
  title = "Desperate Prayer",
  desc = "Hai attirato l'attenzione dei nostri superiori, $N. Ti hanno chiesto di recarti alla Cathedral of Light di Stormwind il prima possibile. A quanto pare ritengono che tu abbia già dato prova di te e che sia $Gpronto:pronta; a proseguire il tuo addestramento. Quando arrivi, cerca High Priestess Laurena. Potrà guidarti oltre. Buona fortuna, e che la Luce sia con te.",
  obj = "Parla con High Priestess Laurena, a Stormwind.",
  reward = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5636] = {
  title = "Desperate Prayer",
  desc = "Elune ti benedica, $Gbuon:buona; $R. Spero che la tua Luce ti trovi e ti protegga bene oggi.$B$BNon molto tempo fa è passato di qui uno dei vostri sacerdoti a cercarti. Ha detto che dovresti tornare alla Cathedral of Light il prima possibile per parlare con High Priestess Laurena. Sembra che tu abbia fatto bene, per attirare tanta attenzione. Non passerei troppo tempo qui — la tua gente ha bisogno di te.",
  obj = "Parla con High Priestess Laurena, a Stormwind.",
  reward = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5637] = {
  title = "Desperate Prayer",
  desc = "È arrivato il momento che tu vada a Stormwind, $N. High Priestess Laurena, nella Cathedral of Light, vuole parlarti. Dev'essere qualcosa di molto buono o di molto brutto se la somma sacerdotessa ti vuole là di persona, ma scommetto che hai solo fatto bene, ed è una buona cosa che voglia parlarti.$B$BMa non perdere troppo tempo da queste parti. Io ci andrei appena possibile.",
  obj = "Parla con High Priestess Laurena, a Stormwind.",
  reward = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5638] = {
  title = "Desperate Prayer",
  desc = "Poco tempo fa è passato di qui uno dei vostri sacerdoti a cercarti, $R. Ha detto che, se ti avessi visto, avrei dovuto indirizzarti verso la Cathedral of Light. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Sembrava di buon umore... come se si trattasse di una bella notizia. Al tuo posto non ci metterei troppo ad andarci.$B$BElune sia con te, $Gbuon:buona; $R.",
  obj = "Parla con High Priestess Laurena, a Stormwind.",
  reward = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5639] = {
  title = "Desperate Prayer",
  desc = "C'è bisogno di te a Stormwind, $N. La somma sacerdotessa di laggiù, Laurena, dice che è ora che tu dimostri di essere $Gdegno:degna; del livello successivo del tuo addestramento. Non perdere troppo tempo per arrivarci. La trovi nella Cathedral of Light, al centro della città. Portale i miei saluti, e dimostra quanto sei $Gdegno:degna; di una simile chiamata. Che la Luce sia con te, $N.",
  obj = "Parla con High Priestess Laurena, a Stormwind.",
  reward = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.",
  en_title = "Desperate Prayer",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5640] = {
  title = "Desperate Prayer",
  desc = "Sia lodata Elune, e la tua Luce, $N.$B$BPiù o meno a questo punto, molti del nostro ordine imparano abilità che riflettono la loro fede in Elune. Se non ricordo male, credo che valga lo stesso anche per il tuo ordine.$B$BQuando avrai finito i tuoi affari a Darnassus, io cercherei una delle vostre somme sacerdotesse per proseguire l'addestramento.",
  obj = "Parla con High Priestess Laurena, a Stormwind.",
  reward = "Mi fa piacere che tu sia $Garrivato:arrivata;, $N. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.$B$BCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei $Gpronto:pronta;, cominceremo subito a parlarne.",
}
T[5641] = {
  title = "Una mancanza di paura",
  reward = "Hai la stoffa per diventare $Gun grande:una grande; $C, $N. Continua così!$B$BHai già dimostrato di essere $Gpronto:pronta; per la battaglia. Forse è ora di insegnarti qualcosina in più.",
  en_title = "A Lack of Fear",
  en_obj = "Speak to High Priest Rohan in Ironforge.",
}
T[5642] = {
  title = "Shadowguard",
  desc = "Sta succedendo qualcosa di importante a Orgrimmar, $N.$B$BI soliti messaggeri che passano di qui in cerca di sacerdoti troll di solito sono molto tranquilli. Questa volta sembravano avere molta più fretta. Non indugiare troppo a Thunder Bluff. Io tornerei alla Valley of Spirits il prima possibile.",
  obj = "Parla con Ur'kyo, a Orgrimmar.",
  reward = "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatterai contro i tuoi nemici.",
  en_title = "Shadowguard",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5643] = {
  title = "Shadowguard",
  desc = "Come per molti dei nostri sacerdoti, anche la tua tribù ti sottopone a riti di passaggio. Questi riti spesso insegnano ai sacerdoti abilità speciali, vitali per la loro sopravvivenza. Sento che per te quel momento è arrivato, proprio mentre parliamo. Devi tornare alla Valley of Spirits di Orgrimmar e parlare con Ur'kyo. Ciò che ti insegnerà potrebbe essere molto importante per il futuro.",
  obj = "Parla con Ur'kyo, a Orgrimmar.",
  reward = "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatterai contro i tuoi nemici.",
  en_title = "Shadowguard",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5644] = {
  title = "Devouring Plague",
  desc = "Ah, un giorno meraviglioso per te, $N. Dalle lezioni che hai imparato vedo che è giunto il momento di rimandarti da Aelthalyste. Ci sono cose che solo lei può insegnarti, e anche allora solo se ti dimostrerai $Gdegno:degna;.$B$BNon ti rovinerò la sorpresa, ma ricordo quando, da giovane, imparavo cos'è il vero potere... il potere divino. Sì, quelli sì che erano bei tempi.$B$BTorna da Aelthalyste nell'Undercity, $N. Ti aspetterà nel War Quarter.",
  obj = "Parla con Aelthalyste, nell'Undercity.",
  reward = "Ti insegnerei Devouring Plague, se ti senti $Gpronto:pronta;, $N. È un incantesimo di non poca potenza, e ti aiuterà nelle battaglie che verranno. Esercitati — più avanti ci saranno delle prove.",
  en_title = "Devouring Plague",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5645] = {
  title = "Una mancanza di paura",
  desc = "$N, il tuo sommo sacerdote, Rohan, vorrebbe riceverti a Ironforge. Affrettati, $Gmio forte amico:mia forte amica;, la tua prossima prova si avvicina in fretta. Anche se vorrei poter assistere ai riti speciali della tua razza, il mio posto è qui. Ma che la Luce ti accompagni nei tuoi viaggi. Quando arriverai in città, Rohan dovrebbe essere ancora nel Mystic Ward. Ti starà aspettando.",
  obj = "Parla con High Priest Rohan, a Ironforge.",
  reward = "È un bene che tu sia $Gvenuto:venuta;, $N. La nostra razza è fiera e forte, ed è ora che tu impari non solo a esserlo $Gtu stesso:tu stessa;, ma anche a suscitare questi sentimenti e questa fiducia negli altri. Sei $Gpronto:pronta;, $Gragazzo:ragazza;?",
  en_title = "A Lack of Fear",
  en_obj = "Speak to High Priest Rohan in Ironforge.",
}
T[5646] = {
  title = "Devouring Plague",
  desc = "Aelthalyste mostra grande rispetto per la nostra gente rimandandola da me per altro addestramento, e ora io faccio lo stesso per la sua tribù.$B$BTorna all'Undercity, $N. Là, nel War Quarter, sarà pronta a insegnarti di più sulla tua gente e sulle sue usanze. Va' là, e non aspettare troppo.",
  obj = "Parla con Aelthalyste, nell'Undercity.",
  reward = "Bene, sei $Gtornato:tornata;, e non un momento troppo tardi. Abbiamo grandi cose di cui parlare, $N. Le tue abilità si stanno rafforzando, e dobbiamo assicurarci che tu sia $Gpronto:pronta;.",
  en_title = "Devouring Plague",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5647] = {
  title = "Una mancanza di paura",
  desc = "La tua razza è davvero forte, $N. Siamo orgogliosi di chiamarvi alleati. E a ogni tramonto tu e la tua gente vi avvicinate non solo a scoprire le vostre vere origini, ma anche a trovare una grande sicurezza di essere sulla strada giusta in tante cose. Quella sensazione deve farti sentire così trionfante.$B$BDa poco è arrivato un messaggio da Ironforge. Chiede che tu torni là e parli con High Priest Rohan, nel Mystic Ward. Io non lo farei aspettare. Che Elune guidi i tuoi viaggi.",
  obj = "Parla con High Priest Rohan, a Ironforge.",
  reward = "Hai la stoffa per diventare $Gun grande:una grande; $C, $N. Continua così!$B$N, hai già dimostrato di essere $Gpronto:pronta; per la battaglia. Forse è ora di insegnarti qualcosina in più.",
  en_title = "A Lack of Fear",
  en_obj = "Speak to High Priest Rohan in Ironforge.",
}
T[5648] = {
  title = "Le vesti della spiritualità",
  desc = "Sei $Gpronto:pronta; per la tua prima prova, $N. A sud di Razor Hill, appena fuori dal villaggio, una delle nostre grunt è ferita dopo aver respinto alcune delle vecchie truppe di Proudmoore. Non sta molto bene, e le farebbe un gran bene se qualcuno come noi potesse aiutarla. Trovala — si chiama Kor'ja — cura le sue ferite e dalle la benedizione dei nostri antenati.$B$BSe lo fai, credo che sarà una prova sufficiente che sei $Gpronto:pronta; ad andare avanti nelle nostre vie.",
  obj = "Trova Grunt Kor'ja e cura le sue ferite con Lesser Heal (Rank 2). Poi concedile Power Word: Fortitude e torna da Tai'jin, a Razor Hill.",
  progress = "Quasi tutti pensano che sia logico che le magie di guarigione siano potenti, ma pochi capiscono quanto. Puoi tenere in vita molti che invece dovrebbero andare a incontrare i loro antenati. Questa magia di guarigione unita all'abilità Fortitude è una combinazione di incantesimi molto potente. Ricordatelo. È utile a ogni genere di persone: guerrieri, maghi e tutto quello che c'è in mezzo.",
  reward = "Bene, allora Kor'ja vive e torna a difendere il nostro villaggio da quei malvagi umani. Spesso vorrei ricordare i giorni di battaglia, quando la potenza si mostrava in combattimento ed erano spesso i saggi a distruggere chi contava solo sulla propria forza.$B$BHai fatto un buon lavoro per me, $N. Ora prendi questa veste. Forse ti aiuterà, forse non ti importa, ma l'hai meritata e sono fiera di chiamarti $Gfratello:sorella;.",
  en_title = "Garments of Spirituality",
  en_obj = "Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill.",
}
T[5649] = {
  title = "Nelle grazie della spiritualità",
  desc = "Sì, $Gamico:amica;. La nostra gente si è unita all'Orda perché è un bene per noi. Sono leali, e ci insegnano molto su cose come l'onore. Ma le vecchie usanze sono dure a morire. Gli orchi forse non approvano tutte le nostre tradizioni, ma questo non vuol dire che non possiamo continuare a praticarne alcune in segreto.$B$BTu lo sai, ed è per questo che ti mando da Tai'jin, a Razor Hill. Ti insegnerà di più sulla nostra storia. Ti insegnerà le vie della nostra tribù. Va' da lei quando sei $Gpronto:pronta;.",
  obj = "Parla con Tai'jin, a Durotar.",
  reward = "Ahh... allora finalmente sei $Gvenuto:venuta; da Tai'jin. Questo è un bene.$B$BSai già che non siamo la stessa tribù che un tempo si unì all'Orda. Adesso siamo molto più forti. Siamo più forti perché ci adattiamo — questo l'Orda ce l'ha insegnato. Non sconfiggiamo più i nemici per trarne forza; ora prima acquistiamo forza, e poi sconfiggiamo i nemici.$B$BLa differenza è sottile, ma imparerai. Vedrai. La tribù conta su di te perché tu impari queste cose.",
  en_title = "In Favor of Spirituality",
  en_obj = "Speak to Tai'jin in Durotar.",
}
T[5650] = {
  title = "Le vesti dell'oscurità",
  desc = "Il nostro potere viene dall'oscurità e dall'ombra, $N, ma questo non è il tuo unico ruolo. Hai riconosciuto che conoscere le arti della guarigione ha il suo valore. È una scelta saggia. Ma prima di poter conoscere il buio, devi conoscere anche la luce. E per questo ho una prova per te.$B$BA nord del cimitero c'è un Guardiamorte ferito: Deathguard Kel. Ci protegge dagli gnoll da tempo, e ha bisogno di cure. Ma devi anche rafforzare il suo corpo prima che possa tornare in servizio. Fai entrambe le cose con i tuoi incantesimi, e poi torna da me.",
  obj = "Trova Deathguard Kel e cura le sue ferite con Lesser Heal (Rank 2). Poi concedigli Power Word: Fortitude e torna da Dark Cleric Beryl, a Brill.",
  progress = "I nostri poteri ci rendono adatti a tantissime situazioni, $N. Scoprirai però che, in ogni caso, la nostra capacità di curare le ferite e di aumentare i danni che i nostri compagni possono sopportare sarà sempre il talento più richiesto tra quelli a nostra disposizione. Non lasciare che questo ti distolga dal seguire altre strade come $C — puoi essere efficace in molti modi. Ma... se desideri davvero distruggere i nemici con l'energia magica, forse l'arcano fa più per te.",
  reward = "Hai superato la mia prova con facilità. Bene.$B$BPresto sarai $Gpronto:pronta; ad assumerti più responsabilità, e quella strada ti porterà a poteri più oscuri — poteri che $Gnessun altro:nessun'altra; $C di un'altra razza possiede.$B$BPrendi questa veste come simbolo del tuo rango. L'hai meritata. Se non vuoi indossarla, così sia: puoi farne ciò che vuoi. Io e gli altri come noi riconosceremo sempre ciò che hai ottenuto nei nostri ranghi.",
  en_title = "Garments of Darkness",
  en_obj = "Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill.",
}
T[5651] = {
  title = "Nelle grazie dell'oscurità",
  desc = "Ci sono molte lezioni che i Reietti hanno imparato con l'esperienza: cose che alcune razze possono solo cominciare a comprendere. E anche se il nostro cammino è nell'oscurità, scoprirai che moltissime cose dipendono sia dalla luce sia dal buio. Le tue lezioni ti insegneranno a usarli entrambi... e con discrezione. Ma ascolta le mie parole: non dimenticare mai che siamo stati forgiati nella corruzione e lasciati a marcire come tante carogne. L'Oscurità è la nostra casa.$B$BCerca Dark Cleric Beryl a Brill quando sarai $Gpronto:pronta; a imparare di più.",
  obj = "Parla con Dark Cleric Beryl, nelle Tirisfal Glades.",
  reward = "Finalmente sei $Garrivato:arrivata;. La tua fede da sola non ti permetterà di superare le prove che ti attendono, giovane. Anche un senso di urgenza e un po' di ambizione ti saranno d'aiuto.",
  en_title = "In Favor of Darkness",
  en_obj = "Speak to Dark Cleric Beryl in Tirisfal Glades.",
}
T[5652] = {
  title = "Hex of Weakness",
  reward = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5654] = {
  title = "Hex of Weakness",
  desc = "È ora che tu incontri Ur'kyo, $N. Si trova nella Valley of Spirits, nella città degli orchi. Va' là e parlagli. È ora che tu impari di più sulle antiche vie della nostra gente. È ora che tu venga $Gaccolto:accolta; nel cerchio e che diventi $Gun vero sacerdote:una vera sacerdotessa; della nostra tribù.",
  obj = "Parla con Ur'kyo, a Orgrimmar.",
  reward = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5655] = {
  title = "Hex of Weakness",
  desc = "Mi hanno mandato qui per assicurarmi che tu non ti allontani troppo da casa, $N. Mi mandano per assicurarmi che tu torni a casa, perché Ur'kyo, il più grande dei nostri sacerdoti, vuole parlarti. Tu vai là. Vai nella Valley of Spirits, nella città degli orchi, e parli con Ur'kyo. Ora ti sta aspettando.",
  obj = "Parla con Ur'kyo, a Orgrimmar.",
  reward = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5656] = {
  title = "Hex of Weakness",
  desc = "Mi scalda sempre il cuore non morto vedere sacerdoti di tutte le culture girare il mondo. Sapere che esiste un potere che non è arcano e che è ben alla nostra portata. Ecco perché è un onore per me indirizzarti a casa, $N.$B$BUr'kyo, il tuo grande sacerdote a Orgrimmar, ha chiesto la tua presenza. Lo trovi nella Valley of Spirits.",
  obj = "Parla con Ur'kyo, a Orgrimmar.",
  reward = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5657] = {
  title = "Hex of Weakness",
  desc = "Casa. Torna a casa, giovane $R.$B$BIl tuo capo spirituale Ur'kyo ti prega di tornare da lui e di parlare del cammino che percorri.$B$BVa' nella Valley of Spirits, nella grande città dell'Orda, Orgrimmar. Lo troverai là.",
  obj = "Parla con Ur'kyo, a Orgrimmar.",
  reward = "Faresti bene a prestare attenzione a questa lezione, giovane. L'Hex of Weakness ti sarà di grande aiuto in battaglia. Più avanti avrò delle prove per te, per farti progredire e dimostrare il tuo valore alla tribù.",
  en_title = "Hex of Weakness",
  en_obj = "Speak to Ur'kyo in Orgrimmar.",
}
T[5658] = {
  title = "Touch of Weakness",
  reward = "Ah, giovane $C, mi fa piacere che tu sia $Gtornato:tornata; qui. Vorrei insegnarti una lezione che faresti bene a non dimenticare. Sei $Gpronto:pronta;?",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5659] = {
  title = "Touch of Weakness",
  desc = "Questo non è il posto per te, $N. Dovresti andare nel War Quarter dell'Undercity il prima possibile. Aelthalyste ha convocato là tutti i suoi sacerdoti e le sue sacerdotesse, non appena saranno pronti. È ora che imparino di più sul loro potere e su come dominarlo.$B$BNon tollererà ritardi né scuse, quindi faresti meglio a metterti in cammino.",
  obj = "Parla con Aelthalyste, nell'Undercity.",
  reward = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.",
}
T[5660] = {
  title = "Touch of Weakness",
  desc = "Sei $Glontano:lontana; da casa, $C. C'è bisogno di te là, nella tua città sotto terra. La tua signora, quella che chiamate Aelthalyste, ha bisogno che tu torni là. Come per la mia tribù, ci sono cose che puoi imparare solo da lei. Non restare qui troppo a lungo. Dovresti andare al War Quarter alla velocità con cui può portarti uno zeppelin.",
  obj = "Parla con Aelthalyste, nell'Undercity.",
  reward = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5661] = {
  title = "Touch of Weakness",
  desc = "Sei $Glontano:lontana; da casa, qui a Bloodhoof Village, $N. Mi hanno mandato qui a cercare sacerdoti della mia tribù da rimandare a parlare con i nostri capi, ma questo non vuol dire che non possa aiutare anche te.$B$BHo sentito dire che lo spirito della vostra sacerdotessa capo vuole che tutti i Reietti vadano da lei: ci sono cose che devi imparare.$B$BVa' a incontrare Aelthalyste nel War Quarter, in quella vostra città.",
  obj = "Parla con Aelthalyste, nell'Undercity.",
  reward = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5662] = {
  title = "Touch of Weakness",
  desc = "Il mio rispetto a te e alla tua gente, $N. Di solito insegno solo a quelli della mia tribù. Le tue lezioni vengono da Aelthalyste, nella città un tempo chiamata Lordaeron.$B$BDovresti tornare da lei, se vuoi imparare le abilità che ti distinguono dalle altre fedi.$B$BVa' nel War Quarter dell'Undercity e là troverai la tua signora.",
  obj = "Parla con Aelthalyste, nell'Undercity.",
  reward = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5663] = {
  title = "Touch of Weakness",
  desc = "Aelthalyste ha mandato un messaggio a tutti i suoi sacerdoti. Dobbiamo indirizzare i più giovani del nostro ordine all'Undercity per altro addestramento. Se ti consideri davvero $Guno:una; dei nostri fedeli, allora dovresti tornarci anche tu.$B$BTrovi Aelthalyste nel War Quarter, nel profondo dell'Undercity.",
  obj = "Parla con Aelthalyste, nell'Undercity.",
  reward = "Ah, bene, ne è $Garrivato un altro:arrivata un'altra;. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai $Gricompensato:ricompensata; generosamente.",
  en_title = "Touch of Weakness",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5672] = {
  title = "Elune's Grace",
  reward = "Dedicandoti a Elune e al nostro popolo, hai raggiunto uno stato che non tutti noi possiamo raggiungere. È tradizione che, per la tua devozione, ti vengano insegnate abilità ancora più grandi. Accetti?",
  en_title = "Elune's Grace",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5673] = {
  title = "Elune's Grace",
  desc = "Sai che puoi rivolgerti a qualunque dei nostri istruttori in qualsiasi momento, $N, ma ci sono cose che non possiamo trasmetterti. Tra queste ci sono gli insegnamenti della tua dea, Elune. Concede abilità speciali ai suoi fedeli e, se non sbaglio, è ora che tu torni a casa, al tuo Temple of the Moon, per essere $Gmesso:messa; alla prova.$B$BTorna là quando puoi e parla con Priestess Alathea.",
  obj = "Parla con Priestess Alathea, a Darnassus.",
  reward = "Elune ti benedica per essere $Gtornato:tornata; da noi così in fretta. Questo è un momento importante del tuo addestramento, e tutto il nostro ordine lo prende molto sul serio. Quando ti sarai $Griposato:riposata; dal viaggio, fammelo sapere, ti prego. Allora potremo discutere di come proseguire il tuo addestramento e di dove ti porterà il tuo cammino.",
  en_title = "Elune's Grace",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5674] = {
  title = "Elune's Grace",
  desc = "È giunto un giorno meraviglioso, $N. Hai raggiunto l'età in cui $Gi nostri sacerdoti:le nostre sacerdotesse; vengono $Gaddestrati:addestrate; in abilità che conoscono solo gli elfi della notte. Ma non spetta a me addestrarti. Devi tornare al Temple of the Moon e parlare con Priestess Alathea non appena avrai concluso i tuoi affari qui. Ti metterà alla prova per assicurarsi che tu sia $Gpronto:pronta;, e solo allora ti insegnerà Elune's Grace.",
  obj = "Parla con Priestess Alathea, a Darnassus.",
  reward = "Dedicandoti a Elune e al nostro popolo, hai raggiunto uno stato che non tutti noi possiamo raggiungere. È tradizione che, per la tua devozione, ti vengano insegnate abilità ancora più grandi. Accetti?",
  en_title = "Elune's Grace",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5675] = {
  title = "Elune's Grace",
  desc = "Non c'è tempo da perdere, $Gragazzo:ragazza;. È ora che tu torni a casa, a Darnassus. Priestess Alathea ha mandato a dire che devi tornare là per l'addestramento. Pare che ti ritengano $Gpronto:pronta; a essere $Gmesso:messa; alla prova, proprio come chi serve la Luce. Dovresti partire appena puoi. Nel suo messaggio Alathea diceva che ti avrebbe aspettato nel Temple of the Moon. Buona fortuna.",
  obj = "Parla con Priestess Alathea, a Darnassus.",
  reward = "Elune ti benedica per essere $Gtornato:tornata; da noi così in fretta. Questo è un momento importante del tuo addestramento, e tutto il nostro ordine lo prende molto sul serio. Quando ti sarai $Griposato:riposata; dal viaggio, fammelo sapere, ti prego. Allora potremo discutere di come proseguire il tuo addestramento e di dove ti porterà il tuo cammino.",
  en_title = "Elune's Grace",
  en_obj = "Speak to Priestess Alathea in Darnassus.",
}
T[5676] = {
  title = "Contraccolpo arcano",
  reward = "Siamo stati costretti a imparare alcune magie per proteggerci da quello che comunemente viene chiamato il nostro più grande nemico: l'arcano.$B$BVorrei insegnarti un incantesimo che ti aiuti a difendere te $Gstesso:stessa; e i tuoi compagni da chi vorrebbe usare un tale potere.",
  en_title = "Arcane Feedback",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5677] = {
  title = "Contraccolpo arcano",
  desc = "Per quanto mi piacerebbe mostrarti i nostri insegnamenti speciali sulla Luce, non sta a noi farlo. Il tuo posto è a Stormwind, con la tua gente, $N... per ora. Credimi, non intendo offenderti. Quando tornerai da High Priestess Laurena, nella Cathedral of Light, capirai di cosa parlo — è giunto il momento che la tua razza ti prepari per il futuro; che tu ti separi dagli altri che seguono un cammino simile.",
  obj = "Parla con High Priestess Laurena, a Stormwind.",
  reward = "Ah, arrivi proprio al momento giusto, $N. Cominciavo a chiedermi se tutti i miei messaggeri fossero riusciti nel loro compito. Sono contenta di vedere che ci sono riusciti, altrimenti scommetto che saresti ancora in giro per il mondo a scoprire di più su tutte le minacce che incombono sul nostro popolo.$B$BSei $Gpronto:pronta;? $GPronto:Pronta; per altro addestramento, intendo. Il tuo potere cresce sempre più in fretta, e sento che sei $Gpronto:pronta; a imparare di più sulla nostra fede.",
  en_title = "Arcane Feedback",
  en_obj = "Speak to High Priestess Laurena in Stormwind.",
}
T[5678] = {
  title = "Contraccolpo arcano",
  desc = "È ora che tu torni a Stormwind, giovane. I tuoi superiori ti hanno richiamato là per altro addestramento. E anche se la cosa mi turba un po', la tua razza e la mia sono alleate, e io non lo tradirei.$B$BNon voglio essere così reticente con te — la mia diffidenza verso le magie arcane, che siano di ispirazione divina o no, è ancora forte in me.$B$BCapirai di cosa parlo quando tornerai alla tua Cathedral of Light. Parla con High Priestess Laurena quando arrivi.",
  obj = "Parla con High Priestess Laurena, a Stormwind.",
  reward = "Ah, arrivi proprio al momento giusto, $N. Cominciavo a chiedermi se tutti i miei messaggeri fossero riusciti nel loro compito. Sono contenta di vedere che ci sono riusciti, altrimenti scommetto che saresti ancora in giro per il mondo a scoprire di più su tutte le minacce che incombono sul nostro popolo.$B$BSei $Gpronto:pronta;? $GPronto:Pronta; per altro addestramento, intendo. Il tuo potere cresce sempre più in fretta, e sento che sei $Gpronto:pronta; a imparare di più sulla nostra fede.",
}
T[5679] = {
  title = "Devouring Plague",
  reward = "Ti insegnerei Devouring Plague, se ti senti $Gpronto:pronta;, $N. È un incantesimo di non poca potenza, e ti aiuterà nelle battaglie che verranno. Esercitati — più avanti ci saranno delle prove.",
  en_title = "Devouring Plague",
  en_obj = "Speak to Aelthalyste in the Undercity.",
}
T[5680] = {
  title = "Shadowguard",
  reward = "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatterai contro i tuoi nemici.",
  en_title = "Shadowguard",
  en_obj = "Speak to Ur'kyo in Ogrimmar.",
}
T[5713] = {
  title = "Un colpo. Un morto.",
  desc = "Stavo viaggiando verso Auberdine con un messaggio importante quando sono stata attaccata dal furbolg Marosh e dai suoi segugi. Durante l'attacco sono stata avvelenata e riesco a malapena a reggermi in piedi. Posso preparare un antidoto, ma ci vorrà del tempo prima che sia pronto.$B$BTi chiedo di difendermi finché non potrò applicarlo. Ti aiuterò con il mio arco come meglio posso.$B$BSe sopravviviamo, potrò consegnare il mio messaggio ad Auberdine, mentre tu parlerai con Onaeya a Maestra's Post per informarla dell'accaduto.",
  obj = "Proteggi Sentinel Aynasha, poi parla con Onaeya a Maestra's Post, ad Ashenvale.",
  progress = "Hai visto Sentinel Aynasha lungo la strada? È partita per una missione importante ma non è ancora tornata.",
  reward = "Porti notizie quanto mai gradite, $C. È bello sapere che Aynasha è viva e in salute grazie a te. Spero che vorrai accettare una ricompensa per il tuo valore. Che Elune vegli su di te e illumini il tuo cammino.",
  en_title = "One Shot. One Kill.",
  en_obj = "Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale.",
}
T[5722] = {
  title = "Alla ricerca della sacca perduta",
  desc = "I trogg non sono l'unica cosa che ha attirato l'interesse di Magatha sul Ragefire Chasm. Le è giunta voce che uno dei suoi servitori, un certo Maur Grimtotem, aveva trovato qualcosa di singolare mentre era nel Chasm, ma non è mai uscito per mostrarle cosa fosse. Vorrebbe che si ritrovasse il corpo di Maur — se ancora esiste — e ogni traccia di ciò che aveva scoperto mentre cercava di parlare con i trogg.$B$BPorta a Magatha qualunque oggetto interessante, e sono certo che sarà molto generosa nella ricompensa.$B$BAncora una volta, cerca il Chasm nelle zone più buie di Orgrimmar.",
  obj = "Cerca il cadavere di Maur Grimtotem nel Ragefire Chasm e frugalo in cerca di oggetti interessanti.",
  reward = "Il corpo sembra massacrato da clave o da pugni, ma quasi tutti i vestiti e l'equipaggiamento del cadavere sembrano ancora al loro posto. Pare che i trogg non tengano granché alle ricchezze materiali.$B$BCominci a frugare il corpo in cerca di qualcosa di interessante che possa aiutare Magatha.",
  en_title = "Searching for the Lost Satchel",
  en_obj = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.",
}
T[5723] = {
  title = "Saggiare la forza del nemico",
  desc = "Sotto la città di Orgrimmar, creature tozze note come trogg hanno cominciato a salire in superficie dal fondo dei cunicoli colmi di lava. Nella sua immensa benevolenza, Magatha ha cercato di fare pace con quelle creature, ma loro si sono rivoltate contro i suoi diplomatici e li hanno uccisi. Non permetterà che il popolo tauren sia trattato così, e ora considera quelle creature una minaccia per tutta l'Orda.$B$BTi chiede di mettere fine alla minaccia dei trogg prima che sommerga l'Orda dal basso. Trova il Ragefire Chasm e distruggili tutti.",
  obj = "Cerca il Ragefire Chasm a Orgrimmar, poi uccidi 8 Ragefire Trogg e 8 Ragefire Shaman prima di tornare da Rahauro, a Thunder Bluff.",
  progress = "Come procede la ricerca del Chasm? E i trogg?$B$BLa minaccia non può continuare — se va avanti, farà solo del male ai nostri fratelli orchi.",
  reward = "Sono lieto di vedere che hai preso sul serio il compito di Magatha. Grazie, $N. Sono certo che i trogg faranno molta più fatica a salire in superficie, ora che il loro numero è tanto ridotto.$B$BForse in futuro potremo prenderci il tempo di capire da dove vengano creature simili, e cosa vogliano davvero.",
  en_title = "Testing an Enemy's Strength",
  en_obj = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.",
}
T[5724] = {
  title = "Riportare la sacca perduta",
  desc = "Sotto il corpo del tauren trovi una sacca. È ancora stretta forte fra le sue braccia, come se avesse cercato di proteggerla mentre i trogg lo attaccavano.$B$BLiberata la sacca da quella morsa, la riponi insieme al tuo equipaggiamento e ti prepari a uscire dai cunicoli e a tornare da Rahauro, a Thunder Bluff.",
  obj = "Porta la Grimtotem Satchel a Rahauro, a Thunder Bluff.",
  progress = "Sei $Griuscito:riuscita; a trovare qualcosa, $N? Qualunque indizio sul perché uno dei suoi compagni di clan sia dovuto morire senza motivo sarebbe utile.",
  reward = "Eccellente, $N. Grazie.$B$BMagatha mi ha detto di darti questo, se fossi $Griuscito:riuscita; a ritrovare il suo compagno di clan. Prendilo, ti prego, in segno di gratitudine.",
  en_title = "Returning the Lost Satchel",
  en_obj = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff.",
}
T[5725] = {
  title = "Il potere di distruggere...",
  desc = "Molti abitanti della Legione elargiscono doni ai loro seguaci, come forse ben sai. Alcuni di questi doni, secondo la Signora Oscura, starebbero meglio nelle sue mani che in quelle di chi ha... una visione più angusta.$B$BUna setta del Concilio dell'Ombra nascosta nelle caverne sotto Orgrimmar, nota come Searing Blade, ne è l'esempio perfetto. La Signora mi dice che i membri della Searing Blade sono entrati in possesso di due potenti libri di incantesimi: le piacerebbe \"prenderli in prestito\". Tu glieli procurerai.",
  obj = "Porta i libri Spells of Shadow e Incantations from the Nether a Varimathras, nell'Undercity.",
  progress = "Ci sono altri cento compiti che attendono la mia attenzione, $C. Hai i libri?",
  reward = "Bene, $C. Hai servito bene la Signora Oscura. La tua costanza e la tua ambizione saranno di grande utilità ai sudditi della Signora. Torna da me anche in futuro. Forse avrò altri compiti per te, che aiuteranno la Signora Oscura nel suo tentativo di soppiantare il Re dei Lich e di liberare del tutto il Flagello.",
  en_title = "The Power to Destroy...",
  en_obj = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",
}
T[5726] = {
  title = "Nemici nascosti",
  desc = "Una cosa che non tollero sono i traditori in mezzo a noi, $N. Ma sarei uno sciocco a scoprire le mie carte così presto: non basterebbe a estirpare la corruzione dalle nostre terre e farebbe solo peggiorare l'infezione.$B$BTu, invece, giovane avventuriero, puoi andare dove i miei agenti non possono... scoprire la verità... trovare il vero capo della bestia.$B$BSe hai abbastanza coraggio, entra a Skull Rock, a est di Orgrimmar, prendi l'insegna di un tenente a uno dei Burning Blade che ci sono e riportamela.",
  obj = "Porta una Lieutenant's Insignia a Thrall a Orgrimmar.",
  progress = "Hai già l'insegna, $N?$B$BSarà uno strumento fondamentale per infiltrarti in quella che credo sia la più grave minaccia per l'Orda e per la pace che finalmente potremo trovare nella nostra nuova casa.$B$BScoprirai quanto sia intricata la trama che uomini e orchi sanno tessere quando li muovono l'avidità e il potere. Le trame nascoste, la corruzione, tutto diventerà chiaro. Ti ritroverai in mezzo a una guerra di cui non sospettavi l'esistenza.",
  reward = "Bene, $N! Siano lodati gli spiriti, forse sarai tu a placare finalmente le mie paure più grandi! Chi avrebbe immaginato che qualcuno così giovane e coraggioso si sarebbe levato a difendere la nostra causa? Mi ricordi me stesso alla tua età. Farò in modo che tu sia ricompensat$Go:a; come meriti per i tuoi sforzi, se sopravvivremo entrambi alla tempesta che viene.$B$BMa ci sarà tempo per altre lodi. Non hai ancora compiuto nulla in confronto a ciò che dovrai affrontare... ma è un buon inizio.",
  en_title = "Hidden Enemies",
  en_obj = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.",
}
T[5727] = {
  title = "Nemici nascosti",
  desc = "Vediamo ora se l'insegna che hai trovato vale la fatica.$B$BIn città c'è uno stregone convinto di godere della mia fiducia. Non sa che conosco la sua vera lealtà: è in realtà il capo dei Burning Blade. Ma non precipitarti a combatterlo; ha uno scopo, e lo useremo contro i nostri nemici.$B$BPorta questa insegna da lui, nella Cleft of Shadow qui a Orgrimmar, parlagli e vedi se crede che tu sia uno dei suoi, poi torna da me.",
  obj = "Porta la Lieutenant's Insignia a Neeru Fireblade e parlagli. Capisci se crede che tu sia un membro dei Burning Blade, poi torna da Thrall a Orgrimmar.",
  progress = "Allora, $c? Crede al nostro inganno, o le cose vanno peggio di quanto stimassi all'inizio?$B$BDimostrarti utile a Neeru renderà molto più facile infiltrarci nello Shadow Council. Avrà molte informazioni che potremo usare per stanare chi vuole distruggere tutto ciò che abbiamo costruito a Durotar.",
  reward = "Eccellente! Davvero eccellente, $C!$B$BCiò che hai fatto oggi è solo il primo passo di una base molto più ampia: una base su cui costruiremo, una volta per tutte, la distruzione dello Shadow Council.$B$BDimmi tutto ciò che ha detto... e non tralasciare una sola parola: potrebbe essere più importante di quanto credi.",
  en_title = "Hidden Enemies",
  en_obj = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.",
}
T[5728] = {
  title = "Nemici nascosti",
  desc = "Hmm, i capi della Searing Blade... è questo che mi preoccupa di più. Se sono loro quelli che contano per Neeru, allora sono loro il primo bersaglio. Questo satiro... Bazzalan, e l'altro che Neeru ha nominato — cos'era, uno stregone? — devono morire.$B$BTorna alla Cleft of Shadow ed entra nel Ragefire Chasm, $N. Trova questi due capi della Searing Blade e uccidili. Ma sta' $Gattento:attenta; a non far sapere a Neeru che sei $Gstato:stata; tu. Devi conservare la tua identità di $Gfratello:sorella; d'arme.",
  obj = "Uccidi Bazzalan e Jergosh the Invoker prima di tornare da Thrall, a Orgrimmar.",
  progress = "Li hai già trovati, $N? I capi della Searing Blade.$B$BSapevo che il Concilio dell'Ombra voleva strapparmi Orgrimmar e tutta l'Orda, ma non immaginavo quanto in fretta sarebbero riusciti a infiltrarsi nella città. Quante braccia ha questa bestia... possiamo tagliarle finché non crolliamo dalla fatica, e non saremo più avanti di quando abbiamo cominciato. Dovrò far raddoppiare gli sforzi alle mie spie.",
  reward = "Sono lieto che tu sia $Gtornato:tornata;, $N. Alcuni dei miei fedeli mi hanno subito riferito che le caverne sotto Orgrimmar sono nel caos, ora che i loro capi sono stati uccisi. Ho perfino sentito dire che Neeru era più che agitato. Pare che gli abbiamo ammaccato l'armatura. Non posso dire di esserne dispiaciuto... nemmeno per una vittoria così piccola.",
  en_title = "Hidden Enemies",
  en_obj = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",
}
T[5729] = {
  title = "Nemici nascosti",
  desc = "Penso che il prossimo passo sia farti stare vicino a Neeru. Se è agitato quanto dicono i rapporti, potremmo ottenere due cose. Primo, potresti imparare qualcosa di più sul Council, o almeno sui Burning Blade; secondo, potrebbe iniziare a fidarsi abbastanza di te da chiederti di aiutarlo. Potrebbe benissimo vederti come qualcuno in grado di colmare il vuoto ora che parte dei vertici è in subbuglio.$B$BTorna alla Cleft e parlagli di nuovo, ma senza dare troppo nell'occhio.",
  obj = "Parla con Neeru Fireblade a Orgrimmar.",
  reward = "Che c'è?! Oh, sei tu, $C... mi scuso. La mia rabbia rivaleggia con quella di un toro kodo rabbioso... ma forse la colpa è mia. Mandando viaggiatori a Ragefire Chasm avrei dovuto prevedere che ne sarebbe derivato qualche danno. Sembra che sia Bazzalan sia Jergosh siano stati colti di sorpresa e uccisi da alcuni dei bravi samaritani di Thrall. Un momento davvero inopportuno, ma ormai non c'è nulla da fare.",
  en_title = "Hidden Enemies",
  en_obj = "Speak to Neeru Fireblade in Orgrimmar.",
}
T[5730] = {
  title = "Nemici nascosti",
  desc = "Sei uno dei miei tenenti! Preparati, $c. Presto ti chiamerò.$B$BIl tempo che ho passato sulla Searing Blade potrebbe ormai essere quasi sprecato, ma ciò non significa che i piani dello Shadow Council altrove debbano risentirne. Farò il possibile per ridurre i danni qui a Ragefire Chasm. Nel frattempo i miei agenti nei Barrens e ad Ashenvale cominceranno a lavorare al nostro nuovo piano. Torna presto da me.",
  obj = "Parla con Thrall a Orgrimmar e digli ciò che hai appreso.",
  reward = "Ashenvale? Hmm, non avevo sentito di alcuna presenza del Council o dei Burning Blade ad Ashenvale. I miei informatori indagheranno, $N. Hai fatto bene.$B$BPer ora riposa e tieniti occupat$Go:a; con altri compiti. Presto ti chiamerò di nuovo.$B$BLok-Tar Ogar!",
  en_title = "Hidden Enemies",
  en_obj = "Speak to Thrall in Orgrimmar and tell him what you've learned.",
}
T[5741] = {
  title = "Sceptre of Light",
  desc = "Si dice che la Burning Blade, nella Thunder Axe Fortress a est, si sia impossessata dello Sceptre of Light sottraendolo ai naga. La leggenda narra che lo scettro sia in grado di far sprofondare intere città sotto i grandi mari. Non si deve permettere alla Burning Blade di possedere un simile potere.$B$BPer questo devi recuperare tu $Gstesso:stessa; lo scettro! Lo custodisce un veggente della Burning Blade, che lo studia dalla cima di una delle torri di guardia di Thunder Axe.",
  obj = "Prendi lo Sceptre of Light e poi portalo ad Azore Aldamort, alla torre di Ethel Rethor.",
  progress = "Hai lo Sceptre of Light?",
  reward = "L'inafferrabile Sceptre of Light! Recuperandolo hai eliminato una grave minaccia per il mondo. Ben fatto, $C, ben fatto.",
  en_title = "Sceptre of Light",
  en_obj = "Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor.$B",
}
T[5761] = {
  title = "Uccidere la bestia",
  desc = "Il compito principale che il nostro grande Capoguerra mi ha affidato è stanare le creature responsabili di aver infestato la grande città del nostro signore con l'influsso demoniaco. La Burning Blade è una minaccia, ma ce ne sono altre; la Searing Blade, per esempio, che ha la sua tana nel Ragefire Chasm e tenta di sovvertire di nascosto membri innocenti dell'Orda.$B$BSe li si vuole fermare, bisogna uccidere il loro capo — un Felguard di nome Taragaman the Hungerer.$B$BUccidilo, e il suo cuore placherà Thrall, ne sono certo.",
  obj = "Entra nel Ragefire Chasm e uccidi Taragaman the Hungerer, poi riporta il suo cuore a Neeru Fireblade, a Orgrimmar.",
  progress = "Hai ucciso la bestia? Dev'essere senza dubbio lui il capo della Searing Blade nel Ragefire Chasm.",
  reward = "Ah! Ce l'hai fatta! Thrall ne sarà felicissimo.$B$BMi assicurerò che questo cuore sia trattato come si deve.$B$BPer ora, però, devi festeggiare la tua vittoria. Informerò Thrall del tuo successo.$B$BGrazie del tuo aiuto, $C.",
  en_title = "Slaying the Beast",
  en_obj = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.",
}
T[5762] = {
  title = "Hemet Nesingwary",
  desc = "Ho un pacco per un mio vecchio cliente, un nano di nome Hemet Nesingwary. Il pacco ci ha messo settimane ad arrivare, e ormai Hemet se n'è andato da un pezzo. Diceva che andava a Stranglethorn a cacciare le bestie di laggiù, ma mi ha lasciato dei soldi perché gli spedissi la consegna appena possibile.$B$BHemet è un nano ricco, e con i ricchi conviene tenere buoni rapporti, no? Allora... vuoi consegnargli tu il pacco?$B$BHo sentito che Hemet ha un campo a Stranglethorn, a nord di Grom'gol.",
  obj = "Porta Kravel's Crate a Hemet Nesingwary, a Stranglethorn.",
  progress = "Quella sul colletto è polvere del deserto?$B$BHmm... se il naso non mi inganna, direi che non è polvere del deserto, è sale del deserto! Sei $Gstato:stata; alle Shimmering Flats, eh?",
  reward = "Ottimo, il mio pacco da Koalbeard! Grazie, $N. Questa cassa contiene munizioni di calibro speciale, e ci servirà bene qui nella giungla!$B$BEcco la tua paga, e dimmi: come sta quel vecchio brontolone di Kravel? Ancora a combinare guai, scommetto...",
  en_title = "Hemet Nesingwary",
  en_obj = "Take Kravel's Crate to Hemet Nesingwary in Stranglethorn.",
}
T[5763] = {
  title = "A caccia a Stranglethorn",
  desc = "Tanto tempo fa, un nano venne in questa terra. Si chiamava Hemet e voleva cacciare grandi bestie. La sua abilità col fucile era prodigiosa, e passammo molti giorni a cacciare insieme. Perfino l'inimicizia tra i nostri popoli fu dimenticata.$B$BQuando lasciò Desolace per Stranglethorn, giurai che un giorno l'avrei accolto di nuovo, perché potessimo cacciare ancora. Ora è giunto quel momento.$B$BPorta questo corno di kodo a Hemet. Saprà che viene da me. Lo troverai a Stranglethorn, a nord del Grom'gol Base Camp.",
  obj = "Porta Roon's Kodo Horn a Hemet Nesingwary, a Stranglethorn.",
  progress = "Siediti, $C. Presto tornerai a lanciarti nella giungla.",
  reward = "Ah, questo corno appartiene a un tauren, Roon Wildmane. Io e lui ci siamo divertiti a cacciare le bestie di Desolace. Quindi Roon mi invita a tornare, eh?$B$BAl momento siamo immersi fino al collo nella giungla, ma grazie, $N. Forse la mia prossima spedizione mi riporterà a Desolace, la terra dei centauri.",
  en_title = "Hunting in Stranglethorn",
  en_obj = "Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn.",
}
T[5805] = {
  title = "Benvenut$Go:a;!",
  desc = "Benvenut$Go:a; in World of Warcraft!$B$BCome ringraziamento speciale per aver acquistato la Collector's Edition di World of Warcraft, consegna questo buono regalo a Merissa Stilwell a Northshire Valley. Riceverai in dono un piccolo compagno che si unirà alla tua ricerca di avventura e gloria.$B$BGrazie ancora, e goditi il tuo soggiorno in World of Warcraft!$B",
  obj = "Porta il Northshire Gift Voucher a Merissa Stilwell.",
  progress = "Salute! È un piacere conoscerti!$B$BVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.",
  reward = "Sei davvero $Gun eroe speciale:un'eroina speciale;, $N. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!",
  en_title = "Welcome!",
  en_obj = "Bring the Northshire Gift Voucher to Merissa Stilwell.",
}
T[5821] = {
  title = "Guardia del corpo a pagamento",
  desc = "In circostanze normali, Rigger e io guideremmo i nostri kodo oltre i Kolkar Centaur. Ogni tanto sentiamo i tamburi di guerra dei centauri, e quando li sentiamo ci fermiamo. Essere morti non fa bene agli affari!$B$BFacciamo così, $C: se ci proteggi finché non avremo superato il villaggio dei Kolkar, ne varrà la pena per te.$B$BÈ solo un breve tratto: devi soltanto tenere intatta la carovana e potrai ritirare la ricompensa da Smeed Scrabblescrew, che sta un po' più avanti lungo la strada. Facciamo qualche affare insieme.",
  obj = "Scorta la Gizelton Caravan oltre il villaggio dei Kolkar Centaur. Parla con Smeed allo Scrabblescrew's Camp per la ricompensa.",
  progress = "Perché mi ritrovo ad aspettare quella maledetta carovana?$B$B<Smeed si illumina.>$B$BAh già, pagano i conti. Li hai visti?",
  reward = "Sai, pagare gente come te per sorvegliare la Gizelton Caravan non sembra un grande affare. $C, se fossi un po' più alto potrei prendermi un secondo lavoro e sedermi all'amazzone su un kodo con il fucile più grosso che le mie mani possano reggere... e farei vedere io a quei maledetti centauri chi comanda.",
  en_title = "Bodyguard for Hire ",
  en_obj = "Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward.",
}
