T[5881] = {
  title = "Chiamare le riserve",
  desc = "L'Orda fa bene a tenere fresche le nostre truppe... dalla Grande Guerra siamo stati prosperi qui in Kalimdor.$B$BHo bisogno che tu mi faccia un favore. Ho un ragazzo di nome Grish Longrunner che presidia il Great Lift, nelle Barrens meridionali. Dagli questa lettera; la lettera gli farà sapere che ho un guerriero di riserva in arrivo per dargli il cambio, così potrà andare a trovare la famiglia. L'ha chiesto tempo fa e sarà felice di sentire la notizia.",
  obj = "Maggran vuole che tu consegni una lettera a Grish Longrunner, al Great Lift nelle Barrens.",
  progress = "Hai notizie da Maggran Earthbinder?",
  reward = "Questa sì che è una bella notizia; sono rimasto seduto qui a fare la guardia a questo pezzo di legno per troppo tempo. Ora posso passare un po' di tempo con la mia famiglia... Evviva!",
  en_title = "Calling in the Reserves",
  en_obj = "Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens.",
}
T[5901] = {
  title = "Che la piaga ti colga",
  desc = "Allora, per portare dolore e discordia alla Crociata Scarlatta, voglio togliere loro la preziosa segheria. Sono sicura che perdere una risorsa del genere danneggerà molto la difesa e la ricostruzione della città, per qualunque scopo la vogliano. Mi aiuterai, $N?$B$BComincia portando questo barattolo nella Plaguewood, nelle Eastern Plaguelands. Riempilo con le termiti che trovi nei loro cumuli, sparsi per il bosco. Torna quando ne avrai abbastanza.",
  obj = "Usa l'Empty Termite Jar sui Termite Mound delle Eastern Plaguelands. Quando avrai raccolto 100 Plagueland Termites, torna da Mickey Levine al Bulwark, nelle Tirisfal Glades.",
  progress = "Hai già le termiti, $N? Sono sicura che per $Gun:una; $C $Gsveglio:sveglia; come te sia una cosa ovvia.$B$BQuando ne avremo abbastanza, faremo in modo che nessuno possa più usare quella segheria!",
  reward = "Queste andranno benissimo, $N. Grazie.$B$BSe sei $Gpronto:pronta;, possiamo passare al prossimo passo.",
  en_title = "A Plague Upon Thee",
  en_obj = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.",
}
T[5902] = {
  title = "Che la piaga ti colga",
  desc = "Ora che abbiamo termiti in abbondanza, porta questo barile rinforzato d'acciaio alla Northridge Lumber Mill, a sud di Hearthglen: la troverai a ovest della strada che porta su fino alla città.$B$BUna volta lì, metti il barile al centro della segheria, in un punto rialzato, per esempio su una cassa o qualcosa del genere.$B$BDopo che l'avrai aperto, il resto verrà da sé. Poi torna qui e ti ricompenserò per avermi aiutata.",
  obj = "Trova un posto adatto al centro della Northridge Lumber Mill, nelle Western Plaguelands, per mettere il Barrel of Plagueland Termites.",
  reward = "Mentre metti il barile sopra la cassa, le termiti si agitano visibilmente.",
  en_title = "A Plague Upon Thee",
  en_obj = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.",
}
T[5921] = {
  title = "Moonglade",
  desc = "Tutti i druidi sono i benvenuti nelle terre sacre di Moonglade, nonostante le attuali tensioni nel Cenarion Circle tra Arch Druid Staghelm e Keeper Remulos — il guardiano di Moonglade. Ora che stai imparando le vie dell'Unghia, ti insegnerò l'incantesimo che ti permette di trasportarti laggiù. Lancialo ogni volta che cerchi la conoscenza o il conforto di Moonglade.$B$BQuanto alla tua prima lezione, va' a Moonglade e parla con Dendrite Starblaze, a Nighthaven, del cammino che hai intrapreso. Buona fortuna, giovane $Gdruido:druida;.",
  obj = "Usa l'incantesimo \"Teleport: Moonglade\" per raggiungere Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.",
  reward = "\"E così comincia, Padre Cenarius. E così comincia.\"$B$BDendrite fa un gesto rapido e invisibile nell'aria sopra di sé. Una leggera aura di potere scende su di lui.$B$B\"La prima prospettiva della natura a cui devi adattarti è quella dell'orso. Ti metterò sulla strada per comprendere questo aspetto della vita druidica, ma sei tu che devi abbracciarlo e diffonderlo — ora e per sempre!\"",
  en_title = "Moonglade",
  en_obj = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.",
}
T[5922] = {
  title = "Moonglade",
  desc = "Tutti i druidi sono i benvenuti nelle terre sacre di Moonglade, tauren ed elfi della notte allo stesso modo. Keeper Remulos — il guardiano di Moonglade — veglia su tutti i druidi che vi riposano in letargo. Ora che stai imparando le vie dell'Unghia, ti insegnerò l'incantesimo che ti permette di trasportarti laggiù. Lancialo ogni volta che cerchi la conoscenza o il conforto di Moonglade.$B$BQuanto alla tua prima lezione, va' a Moonglade e parla con Dendrite Starblaze, a Nighthaven, del cammino che hai intrapreso. Buona fortuna, giovane $Gdruido:druida;.",
  obj = "Usa l'incantesimo \"Teleport: Moonglade\" per raggiungere Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.",
  reward = "\"E così comincia, Padre Cenarius. E così comincia.\"$B$BDendrite fa un gesto rapido e invisibile nell'aria sopra di sé. Una leggera aura di potere scende su di lui.$B$B\"La prima prospettiva della natura a cui devi adattarti è quella dell'orso. Ti metterò sulla strada per comprendere questo aspetto della vita druidica, ma sei tu che devi abbracciarlo e diffonderlo — ora e per sempre!\"",
  en_title = "Moonglade",
  en_obj = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.",
}
T[5923] = {
  title = "Rispondere al richiamo",
  desc = "Scusa, $Gamico:amica;...$B$BMi è giunta voce che Mathrengyl Bearwalker ha fatto sapere di volerti parlare. Sembra che il tuo addestramento come $Gdruido:druida; stia per entrare in una nuova fase, e sarà lui a istruirti di persona. Mathrengyl è l'assistente diretto dell'arcidruido in persona, ed è uno dei druidi più saggi e venerabili che troverai a Teldrassil.$B$BLo troverai nel Cenarion Enclave di Darnassus, al piano superiore dell'albero di Fandral Staghelm.",
  obj = "Parla con Mathrengyl Bearwalker nel Cenarion Enclave, a Darnassus.",
  reward = "Sono lieto che oggi tu abbia trovato la strada fin qui, giovane $Gdruido:druida;. È giunto il momento di fare un grande passo verso un mondo molto più grande.$B$BIn ognuno dei figli di Cenarius c'è il richiamo a servire la natura. Gli animali e le piante sono nostri amici, oltre che nostri protetti. Scegliamo di dedicare la nostra vita a custodire l'equilibrio, per il loro bene e per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso, e imparare la forza del corpo e del cuore.$B$BPreparati!",
  en_title = "Heeding the Call",
  en_obj = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
}
