  en_title = "The Hunter's Path",
  en_obj = "Speak with Dazalar in Dolanaar.",
}
T[6074] = {
  title = "La via del cacciatore",
  desc = "Salve, $Ggiovane cacciatore:giovane cacciatrice;. Mi sembri abbastanza capace da saper gestire una bestia e addestrarla come compagna.$B$BDevi andare da Grif Wildheart, a Kharanos. Può metterti sulla via per guadagnarti un animale tutto tuo.",
  obj = "Parla con Grif Wildheart, a Kharanos.",
  reward = "Sì, credo proprio che anche tu sia $Gpronto:pronta;...",
  en_title = "The Hunter's Path",
  en_obj = "Speak with Grif Wildheart in Kharanos.",
}
