T[7025] = {
  title = "Dolcetti per Greatfather Winter",
  desc = "Ehi, puoi fare un favore a Greatfather Winter, ehm, $Gpiccolo:piccola;?$B$BNon per parlare di me in terza persona senza motivo, ma Greatfather Winter è impegnato in questa faccenda da tutto il giorno, e un dolcetto gli farebbe proprio bene. Qualche biscotto di pan di zenzero e del latte freddo per mandarli giù sarebbero proprio l'ideale. Pensi di poter fare un piacere a Greatfather e procurarmene un po'?",
  obj = "Porta 5 Gingerbread Cookie e un Ice Cold Milk a Greatfather Winter, a Ironforge.",
  progress = "Tutto questo parlare di dolcetti mi ha fatto venire voglia. Mmmm... biscotti di pan di zenzero e latte...",
  reward = "Sei proprio un bell'aiuto per il vecchio Greatfather Winter, $N. Buona Vigilia di Grande Inverno.$B$BEcco una cosetta... sai, per il disturbo.",
  en_title = "Treats for Greatfather Winter",
  en_obj = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge.",
}
T[7042] = {
  title = "Le leccornie rubate della Vigilia di Grande Inverno",
  desc = "Senti... non per rovinare la magia della festa, ma alla Smokywood Pastures farebbe comodo un po' d'aiuto: quello che di solito date voi avventurieri.$B$BManca un carico importante di leccornie che doveva rifornirci per la festa, e adesso manca anche l'agente della Smokywood Pastures che avevamo mandato a cercarlo! Ti prego: il carico è stato segnalato l'ultima volta nelle Alterac Mountains, ed è lì che il nostro uomo è andato a cercarlo.$B$BVedi se sono tutti e due là, sani e salvi!",
  obj = "Trova l'investigatore della Smokywood Pastures scomparso nelle regioni innevate delle Alterac Mountains.",
  reward = "M-m-mi senti! Sia r-r-ringraziato il b-b-bilancio!$B$BNon sono davvero un p-p-pupazzo di neve: mi ch-ch-chiamo Sacks e l-l-lavoro per la f-f-filiale di Ironforge della Smokywood Pastures... Mi hanno m-m-mandato qui a cercare un p-p-pacco scomparso, quando sono stato attaccato da una c-c-creatura che non avevo mai v-v-visto p-p-prima!$B$BChe f-f-freddo...",
  en_title = "Stolen Winter Veil Treats",
  en_obj = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.",
}
T[7043] = {
  title = "Che cattivone...",
  desc = "Una c-c-creatura chiamata \"The Abominable Greench\" è quella che ha r-r-rubato il nostro carico di l-l-leccornie, $N. Ma sta' $Gattento:attenta;! È l-l-lui che mi ha ridotto in questo p-p-pasticcio di neve!$B$BTi s-s-servirà un po' d'aiuto per a-a-affrontarlo. L'ho visto g-g-girare dappertutto dove ci sono gli y-y-yeti; di s-s-sicuro è qui da q-q-qualche parte! T-t-trova le leccornie, $N, riportale alla Smokywood Pastures a Ironforge e d-d-di' che bisogna s-s-scongelarmi!",
  obj = "Trova e riporta gli Stolen Treats a Wulmort Jinglepocket, a Ironforge. L'ultima volta si pensava che li avesse l'Abominable Greench, che si trova da qualche parte nelle regioni innevate delle Alterac Mountains.",
  progress = "$N, la nostra Vigilia di Grande Inverno sarà rovinata senza quelle leccornie per rifornirci! Lo stesso Graccu non potrà dividere i suoi deliziosi pasticci di carne con tutti i bambini e le bambine buoni, quest'anno...",
  reward = "L'hai trovato! Hai salvato la Vigilia di Grande Inverno della Smokywood Pasture!$B$BPovero Sacks... manderemo di sicuro una squadra laggiù per trovare un modo di scongelarlo. Speriamo che torni in tempo per il giorno della Vigilia; però dovrà recuperare le ore di lavoro perse. Comunque, niente di tutto questo sarebbe possibile senza di te!",
  en_title = "You're a Mean One...",
  en_obj = "Locate and return the Stolen Treats to Wulmort Jinglepocket in Ironforge.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.$B",
}
T[7045] = {
  title = "Un grazie dalla Smokywood Pastures!",
  desc = "Noi della Smokywood Pastures ti siamo grati per aver recuperato le leccornie rubate, $N. Per questo vorremmo offrirti un regalo speciale... consegnato nientemeno che da Greatfather Winter in persona!$B$BPer favore, parla con Greatfather Winter: ti darà il tuo regalo della Vigilia di Grande Inverno da parte di noi della Smokywood Pastures. Dalla nostra fattoria alla tua tavola, è sempre la bontà genuina della Smokywood Pastures... grazie a te, naturalmente!",
  obj = "Parla con Greatfather Winter, a Ironforge.",
  reward = "Oh, oh, salve, $Gavventuriero:avventuriera;!$B$BI goblin mi hanno detto che in queste feste ti sei $Gguadagnato:guadagnata; un regalo speciale, e sono lieto di dartelo. Eccolo qui: che la tua Vigilia di Grande Inverno sia meravigliosa, questa e tutte quelle che verranno.",
  en_title = "A Smokywood Pastures Thank You!",
  en_obj = "Speak with Greatfather Winter in Ironforge.",
}
T[7061] = {
  title = "The Feast of Winter Veil",
  desc = "Ecco: se vuoi saperne di più sulla Vigilia di Grande Inverno, leggi questo libro. Anche se credo che il nostro modo di intendere la leggenda sia quello giusto, sono abbastanza studioso di leggende da apprezzare che tutte le informazioni siano raccolte in un'unica fonte.$B$BQuando avrai finito, porta il libro a Cairne Bloodhoof, a Thunder Bluff. So per certo che gli farà piacere sapere che altri si sono interessati alla tradizione del nostro popolo.",
  obj = "Leggi pure il libro, \"The Feast of Winter Veil\", per saperne di più sulla festa. Quando avrai finito, consegnalo a Cairne Bloodhoof, a Thunder Bluff.",
  progress = "Ti do il benvenuto a Mulgore e nella nostra umile comunità di Thunder Bluff, $Gamico:amica;. Mi interesso sempre a chi sceglie di interessarsi al regno, alla sua gente e alla sua tradizione. È per questo che sei qui davanti a me?",
  reward = "Le leggende e la tradizione legate alla Vigilia di Grande Inverno sono sbiadite, nel corso degli anni, dal primo piano del pensiero comune. Sì, so che i goblin stanno aiutando a far rivivere la festa per i loro scopi, ma il fatto che il nostro popolo ci rifletta, almeno in qualche forma, aiuta a mantenere viva questa tradizione.$B$BIl tuo desiderio di andare oltre le cose materiali e di conoscere il nostro passato è una qualità ammirevole, giovane $C. Rendo omaggio alla tua saggezza.",
  en_title = "The Feast of Winter Veil",
  en_obj = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff.",
}
T[7062] = {
  title = "Il senso della festa",
  desc = "Doni, leccornie, regali... bah, dico io!$B$BQuei goblin inquinano il vero significato di questa ricorrenza: la Vigilia di Grande Inverno. È un tempo di rinascita; la terra dorme sotto una coltre di neve portata da Greatfather Winter, che NON è quello sciocco pasticcione vestito di rosso laggiù!$B$BSe vuoi scoprire da te che cos'è davvero la Vigilia, chiedi a Historian Karnik, alla Lega degli Esploratori. Sono sicuro che sarà sorpreso che a qualcuno importi della storia più che ricevere regali.",
  obj = "Parla della Vigilia di Grande Inverno con Historian Karnik, alla Lega degli Esploratori, a Ironforge.",
  reward = "La Vigilia di Grande Inverno, dici? Ahimè, un tempo per noi nani aveva un significato più profondo. Oggi sembra che altri abbiano trasformato la leggenda di Greatfather Winter in qualcosa che serve a vendere dolciumi e regali.$B$BNon c'è da stupirsi che Goli sia amareggiato per un cambiamento del genere. Lui e altri nani come lui si aggrappano al nostro passato come a uno stendardo di guerra. Anche se credo che un po' di festa faccia sempre bene, è importante ricordare le origini della Vigilia.",
  en_title = "The Reason for the Season",
  en_obj = "Speak with Historian Karnik at the Explorer's League in Ironforge about the Feast of Winter Veil.",
}
T[7063] = {
  title = "The Feast of Winter Veil",
  desc = "Ecco: se vuoi saperne di più sulla Vigilia di Grande Inverno, leggi questo libro. Anche se credo che il nostro modo di intendere la leggenda sia quello giusto, sono abbastanza studioso da apprezzare che tutte le informazioni siano raccolte in un'unica fonte.$B$BQuando avrai finito, porta il libro a King Magni Bronzebeard. So per certo che gli farà piacere sapere che altri si sono interessati alle leggende più antiche.",
  obj = "Leggi pure il libro, \"The Feast of Winter Veil\", per saperne di più sulla festa. Quando avrai finito, consegnalo a King Magni Bronzebeard, a Ironforge.",
  progress = "Ti do il benvenuto nel regno di Ironforge, $Gamico:amica;. Mi interesso sempre a chi sceglie di interessarsi al regno, alla sua gente e alla sua tradizione. È per questo che sei qui davanti a me?",
  reward = "Le leggende e la tradizione legate alla Vigilia di Grande Inverno sono sbiadite, nel corso degli anni, dal primo piano del pensiero comune. Riconosco che i goblin stanno aiutando a far rivivere la festa per i loro scopi, ma il fatto che i cittadini ci pensino, almeno in qualche forma, aiuta a mantenere viva questa tradizione.$B$BIl tuo desiderio di andare oltre le cose materiali e di conoscere il nostro passato è una qualità ammirevole, giovane $C. Rendo omaggio alla tua erudizione.",
  en_title = "The Feast of Winter Veil",
  en_obj = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge.",
}
T[7321] = {
  title = "Soothing Turtle Bisque",
  desc = "Chi dice che i non morti non sanno niente di cucina? Prendi la mia ricetta segreta della Turtle Bisque, per esempio. Ho conosciuto gente che tornerebbe dalla morte solo per gustarne una ciotola! Eh, eh...$B$BA proposito, ultimamente non ho potuto prepararne. Andavo di persona al Lake Lordamere a cacciare gli Snapjaw, quelle brutte bestie, ma non riesco a staccarmi dal mio lavoro qui.$B$BSe mi porti un po' di Turtle Meat dagli Snapjaw e delle Soothing Spices, ti mostrerò come si fa!",
  obj = "Porta 10 pezzi di Turtle Meat e delle Soothing Spices a Christoph Jeffcoat, a Tarren Mill.",
  progress = "Hai avuto fortuna con gli ingredienti? Te lo dico io, quei vermi dell'Alleanza sono fin troppi da queste parti ormai... Secondo me si sono già avvicinati fin troppo...",
  reward = "La mia Soothing Turtle Bisque ti terrà al caldo in una notte fredda... se ti importa di queste cose.",
  en_title = "Soothing Turtle Bisque",
  en_obj = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Christoph Jeffcoat in Tarren Mill.",
}
T[7383] = {
  title = "La corona della Terra",
  desc = "Non tutto andava bene a Teldrassil, tuttavia. I piani accuratamente elaborati di Staghelm per il nuovo Albero del Mondo avevano dato i frutti sperati, ma c'era un piccolo problema, un problema al quale si possono attribuire molti dei guai di Teldrassil.$B$BTuttavia, non ne parlerò ancora. Devi visitare l'ultimo pozzo lunare, a nordovest, nell'Oracle Glade. Sotto i rami dell'Oracle Tree si trova il primo e più potente dei nostri pozzi. Recupera una fiala della sua acqua e torna da me.",
  obj = "Riempi l'Amethyst Phial e riportala a Corithras Moonrage a Dolanaar.",
  progress = "Insieme ai druidi, l'Oracle Tree e l'Arch Druid hanno monitorato con cura la crescita di Teldrassil. Ma sebbene abbiamo una nuova casa, le nostre vite immortali non ci sono state restituite.",
  reward = "Trovarsi alla presenza dell'Oracle Tree... è quasi sentire la saggezza prendere forma. Lascia che continui il racconto...$B$BCresciuta Teldrassil, l'Arch Druid si rivolse ai draghi per ottenere la loro benedizione, come i draghi avevano concesso a Nordrassil nei tempi antichi. Ma Nozdormu, Signore del Tempo, rifiutò di benedire, rimproverando il druido per la sua arroganza. D'accordo con Nozdormu, anche Alexstrasza rifiutò Staghelm e, senza la sua benedizione, la crescita di Teldrassil è stata viziata e imprevedibile...",
  en_title = "Crown of the Earth",
  en_obj = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.",
}
T[7495] = {
  title = "Vittoria per l'Alleanza",
  desc = "Hai compiuto l'impossibile. La madre della covata del Black Dragonflight giace morta ai tuoi piedi. Prendi la sua testa e presentala al Gran Signore.",
  obj = "Porta la Head of Onyxia a Highlord Bolvar Fordragon, a Stormwind.",
  progress = "Per la barba di Uther!",
  reward = "Per tanti anni sono stato prigioniero del suo sguardo ammaliatore. Finalmente vedo fatta giustizia e restituito l'onore di Stormwind! Oggi celebriamo questa gloriosa vittoria!",
  en_title = "Victory for the Alliance",
  en_obj = "Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind.",
}
T[7496] = {
  title = "Tempi di festa",
  desc = "Cerca Major Mattingly nella Valley of Heroes, $N. Ti starà aspettando...",
  obj = "Cerca Major Mattingly nella Valley of Heroes.",
  reward = "A pochi è concessa una cerimonia simile, $N. Ti prego, scegli la tua ricompensa, così possiamo cominciare i festeggiamenti.",
  en_title = "Celebrating Good Times",
  en_obj = "Seek out Major Mattingly in the Valley of Heroes.",
}
T[7497] = {
  title = "Il viaggio è appena cominciato",
  reward = "$GUn ammazzadraghi e un esperto conciatore:Un'ammazzadraghi e un'esperta conciatrice;? Non smetti di stupire, $Geroe:eroina;. Sono lusingato.$B$BTi prego, accetta quello che sto per insegnarti. Questa conoscenza ti sarà preziosissima se vorrai distruggere ciò che resta del Black Dragonflight.$B$BCrea il mantello con le scaglie della madre della covata. Proteggerà te e i tuoi alleati dal soffio incendiario del Signore di Blackrock... Nefarian.",
  en_title = "The Journey Has Just Begun",
}
T[7541] = {
  title = "Al servizio dell'Orda",
  reward = "Ci vorrà tempo perché i nostri studiosi esaminino il ciondolo che ci hai portato. Ma per il tuo servizio all'Orda vorrei offrirti un piccolo segno di riconoscenza.$B$BGrazie, $N. Le tue azioni fanno onore a te, e a noi.",
  en_title = "Service to the Horde",
}
T[7662] = {
  title = "Nuovo kodo — verde acqua",
  reward = "Se mi porti il tuo vecchio kodo, te lo cambierò con uno della nuova mandria. Il nuovo kodo sarà veloce quanto il vecchio, ma avrà un aspetto diverso. Puoi guardare i grandi kodo che abbiamo già qui intorno al recinto per vedere tra quali potrai scegliere.",
  en_title = "New Kodo - Teal",
}
T[7663] = {
  title = "Nuovo kodo — verde",
  reward = "Se mi porti il tuo vecchio kodo, te lo cambierò con uno della nuova mandria. Il nuovo kodo sarà veloce quanto il vecchio, ma avrà un aspetto diverso. Puoi guardare i grandi kodo che abbiamo già qui intorno al recinto per vedere tra quali potrai scegliere.",
  en_title = "New Kodo - Green",
}
T[7664] = {
  title = "Sostituzione dell'Ivory Raptor",
  reward = "Tu mi porti il tuo vecchio raptor, io ti do uno nuovo con artigli appena affilati! Il nuovo raptor sarà veloce proprio come il tuo vecchio, ma con un aspetto nuovo. Puoi dare un'occhiata ai raptor veloci qui per vedere fra quali potrai scegliere.",
  en_title = "Ivory Raptor Replacement",
}
