T[7675] = {
  title = "Sostituzione dell'Icy Blue Mechanostrider",
  progress = "Se mi porti il tuo vecchio mechanostrider veloce, lo scambierò con uno del nuovo lotto. Il nuovo mechanostrider sarà veloce quanto il vecchio, ma avrà un aspetto diverso. Puoi guardare i mechanostrider veloci che abbiamo già qui nel cortile per vedere come sarà.",
  reward = "Se vai ancora in giro su quel vecchio Icy Blue Mechanostrider Mod A, vorrai di sicuro cambiarlo con un modello più nuovo. Il tuo nuovo mechanostrider veloce mantiene tutta la velocità del vecchio, con un aspetto nuovo di zecca. Puoi dare un'occhiata ai mechanostrider veloci qui per vedere fra quali splendidi modelli potrai scegliere.",
  en_title = "Icy Blue Mechanostrider Replacement",
}
T[7676] = {
  title = "Sostituzione del White Mechanostrider",
  progress = "Se mi porti il tuo vecchio mechanostrider veloce, lo scambierò con uno del nuovo lotto. Il nuovo mechanostrider sarà veloce quanto il vecchio, ma avrà un aspetto diverso. Puoi guardare i mechanostrider veloci che abbiamo già qui nel cortile per vedere come sarà.",
  reward = "Se vai ancora in giro su quel vecchio White Mechanostrider Mod A, vorrai di sicuro cambiarlo con un modello più nuovo. Il tuo nuovo mechanostrider veloce mantiene tutta la velocità del vecchio, con un aspetto nuovo di zecca. Puoi dare un'occhiata ai mechanostrider veloci qui per vedere fra quali splendidi modelli potrai scegliere.",
  en_title = "White Mechanostrider Replacement",
}
T[7781] = {
  title = "Il Signore di Blackrock",
  desc = "La vecchia sensazione ritorna. Il gradito fremito della vittoria ti risuona in tutto l'essere. Davanti a te giace la testa monolitica e segnata dalle battaglie di Nefarian. Riportala al tuo Gran Signore, $Gcampione:campionessa;.",
  obj = "Riporta la Head of Nefarian a Highlord Bolvar Fordragon, a Stormwind.",
  progress = "Inconcepibile!",
  reward = "Non c'è bisogno che ti si spieghi il significato di ciò che hai fatto, $N. Questo giorno sarà scritto negli annali della storia. Una vittoria come l'Alleanza non ne conosceva da anni, se mai ne ha conosciute!",
  en_title = "The Lord of Blackrock",
  en_obj = "Return the Head of Nefarian to Highlord Bolvar Fordragon in Stormwind.",
}
T[7782] = {
  title = "Il Signore di Blackrock",
  desc = "Va' nella Valley of Heroes e parla con Field Marshal Afrasiabi.",
  obj = "Raggiungi la Valley of Heroes, a Stormwind City, e parla con Field Marshal Afrasiabi.",
  reward = "<Field Marshal Afrasiabi si inchina.>$B$BScegli la tua ricompensa, e che i festeggiamenti abbiano inizio!",
  en_title = "The Lord of Blackrock",
  en_obj = "Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi.",
}
T[7788] = {
  title = "Sconfiggi gli invasori!",
  desc = "Oltre questo tunnel troverai un campo di lotta e tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.$B$BEntra in Warsong Gulch e difendi Silverwing Hold. Respingi le forze invasori dell'Orda!$B$BFa' questo e guadagna un Mark of Honor. Portamelo, $N, e ti ricompenserò.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong, al Silverwing Grove.",
  progress = "Hai combattuto in Warsong Gulch e difeso Silverwing Hold?",
  reward = "Hai dimostrato quanto vali per i nostri sforzi in Warsong Gulch. Continua ad aiutare la causa e portami altri Mark of Honor. Fa' questo, e ti guadagnerai ancora più fiducia da parte nostra.",
  en_title = "Vanquish the Invaders!",
  en_obj = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
}
T[7789] = {
  title = "Soffoca gli usurpatori Silverwing",
  desc = "Le terre selvagge dell'Ashenvale Forest cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro diritto sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!$B$BLascia che l'orgoglio ti gonfi il petto mentre abbatti i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinel e guadagna un Mark of Honor. Torna da me con un Mark simile, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  progress = "Il sangue dei nostri nemici è un marchio d'onore. Ce l'hai un marchio simile?",
  reward = "<Captain Shatterskull ruggisce in trionfo>$B$BQuanto ancora possono resistere? Quanta altra feccia dell'Alleanza deve perire per mano dell'Orda prima che si ritirino? Solo il tempo lo dirà, $R...",
  en_title = "Quell the Silverwing Usurpers",
  en_obj = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
}
T[7791] = {
  title = "Una donazione di lana",
  progress = "Al momento accettiamo donazioni di Wool Cloth. Una donazione di sessanta Wool Cloth ti farà guadagnare il pieno riconoscimento di Stormwind per il tuo gesto generoso. Con le scorte di lana che abbiamo, da te ci bastano sessanta pezzi in tutto: il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.$B$BSe hai con te i sessanta Wool Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Wool",
}
T[7792] = {
  title = "Una donazione di lana",
  progress = "Al momento accettiamo donazioni di Wool Cloth. Una donazione di sessanta Wool Cloth ti farà guadagnare il pieno riconoscimento di Darnassus per la tua generosità. Con le scorte di lana che abbiamo, da te ci bastano sessanta pezzi in tutto: il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.$B$BSe hai con te i sessanta Wool Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Wool",
}
T[7793] = {
  title = "Una donazione di seta",
  progress = "Come per quasi tutti gli altri tessuti, le nostre scorte di seta sono al minimo storico. Con le scorte che abbiamo, da te ci bastano sessanta Silk Cloth in tutto: con l'aiuto di altri dovremmo riuscire a raggiungere l'obiettivo.$B$BUn dono generoso come la seta, aggiungerei, farebbe di certo salire la tua considerazione qui nella comunità! Se hai con te i sessanta Silk Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Silk",
}
T[7794] = {
  title = "Una donazione di Mageweave",
  progress = "La Mageweave Cloth sta finendo, e il tuo aiuto ci farebbe comodo per rifornire le nostre scorte! Contando sulla comunità nel suo insieme, da te ci servirebbe solo una donazione di 60 pezzi di Mageweave Cloth per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a Stormwind, te lo assicuro!$B$BSe hai con te i sessanta pezzi di Mageweave Cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.",
  reward = "Meraviglioso! Ti ringraziamo per la tua generosa donazione, $N!",
  en_title = "A Donation of Mageweave",
}
T[7795] = {
  title = "Una donazione di Runecloth",
  progress = "$N, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre ci diamo da fare per ricostituire le nostre riserve, un tipo di stoffa resta scarsissimo: la Runecloth. Ne abbiamo un bisogno disperato, e speriamo che tu possa aiutarci come hai fatto in passato!$B$BSe vuoi, portami tutta la Runecloth di cui puoi fare a meno. Per cominciare accetteremo una sola donazione di sessanta pezzi, e poi vedremo.",
  reward = "Fantastico: la useremo subito, te lo assicuro. Grazie ancora per il tuo aiuto! Senza di te saremmo davvero persi.$B$BCon tutte le donazioni che hai fatto, accetterò volentieri qualsiasi altra donazione di Runecloth vorrai fare in futuro. Passa pure da me, e farò in modo di persona che le tue buone azioni non restino senza riconoscimento!",
  en_title = "A Donation of Runecloth",
}
T[7796] = {
  title = "Altra Runecloth",
  progress = "Quando sei $Gpronto:pronta; a consegnare la pila di Runecloth, la accetterò.",
  reward = "$N, senza eroi come te che lavorano per la tribù, soffriremmo di sicuro. Grazie per il tuo impegno costante!",
  en_title = "Additional Runecloth",
}
