T[7863] = {
  title = "Sentinel Basic Care Package",
  reward = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! Dentro trovi razioni e bende utilizzabili solo dentro Warsong Gulch.$B$BContinuando a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.",
  en_title = "Sentinel Basic Care Package",
}
