  en_title = "The Battle for Arathi Basin!",
  en_obj = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.",
}
T[8193] = {
  title = "Maestro pescatore",
  progress = "Oggi, tra le 2 e le 4 del pomeriggio, c'è una gara per stabilire chi è il più grande pescatore di tutti! Basta essere la PRIMA PERSONA a portarmi 40 Tastyfish pescati dai banchi di Tastyfish lungo la costa di Stranglethorn, prima di chiunque altro, e sarai $Gproclamato Maestro pescatore:proclamata Maestra pescatrice;!$B$BSe non sei la prima persona a portarmi 40 pesci, la mia apprendista qui ti ricompenserà comunque con del denaro per ogni 5 Tastyfish che le porterai.$B$BAh, e non perdere tempo, i Tastyfish vanno a male in fretta!",
  reward = "Sbrigati a consegnarli, se vuoi essere $Gproclamato Maestro pescatore:proclamata Maestra pescatrice;! Sono qui da ORE senza niente da mangiare! Dammi quei cosi!",
  en_title = "Master Angler",
}
T[8260] = {
  title = "Arathor Basic Care Package",
  reward = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! Dentro trovi razioni e bende utilizzabili solo dentro Arathi Basin.$B$BContinuando a dimostrare il tuo valore nel Basin, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.",
  en_title = "Arathor Basic Care Package",
}
T[8263] = {
  title = "Defiler's Basic Care Package",
  reward = "Hai di sicuro cominciato a dimostrare il tuo valore ai nostri occhi, $N. Come ricompensa, prendi questo pacco di rifornimenti! Dentro trovi razioni e bende utilizzabili solo dentro Arathi Basin.$B$BContinuando a dimostrare il tuo valore nel Basin, scoprirai che questi oggetti si potranno anche comprare. Le razioni diventano disponibili quando sei Friendly con noi, le bende quando sei Honored.",
  en_title = "Defiler's Basic Care Package",
}
T[8266] = {
  title = "Ribbons of Sacrifice",
  progress = "Capisco che a volte può essere difficile avere la meglio in Warsong Gulch. Eppure il tuo impegno per noi — anche quando la vittoria non arriva — è importante.$B$BSe porti a termine una delle prove dentro Warsong Gulch senza ottenere la vittoria, riceverai comunque una Ribbons of Sacrifice. Portamela, così le Sentinelle potranno ricompensarti per aver agito per noi... anche se questa volta non sei $Griuscito:riuscita; a vincere.",
  reward = "Be', non sei $Gfuggito:fuggita; di fronte alla sconfitta. Hai tenuto la posizione, $N, e alla fine è questo che fa un vero eroe. Di sicuro la prossima volta vincerai... ma intanto ti ringraziamo per il tuo impegno.",
  en_title = "Ribbons of Sacrifice",
  en_obj = "Bring the Ribbons of Sacrifice to Captain Shatterskull so that the Outriders may reward you for acting on our behalf.",
}
T[8268] = {
  title = "Ribbons of Sacrifice",
  progress = "Capisco che a volte può essere difficile avere la meglio in Warsong Gulch. Eppure il tuo impegno per noi — anche quando la vittoria non arriva — è importante.$B$BSe porti a termine una delle prove dentro Warsong Gulch senza ottenere la vittoria, riceverai comunque una Ribbons of Sacrifice. Portamela, così i Warsong Outrider potranno ricompensarti per aver agito per noi... anche se questa volta non sei $Griuscito:riuscita; a vincere.",
  reward = "Be', non sei $Gfuggito:fuggita; di fronte alla sconfitta. Hai tenuto la posizione, $N, e alla fine è questo che fa un vero eroe. Di sicuro la prossima volta vincerai... ma intanto ti ringraziamo per il tuo impegno.",
  en_title = "Ribbons of Sacrifice",
  en_obj = "Bring the Ribbons of Sacrifice to Sentinel Farsong so that the Sentinels may reward you for acting on our behalf.",
}
T[8290] = {
  title = "Sconfiggi gli invasori",
  desc = "Oltre questo tunnel troverai un campo di lotta e tumulto, giovane $C. L'Orda continua a decimare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.$B$BEntra in Warsong Gulch e difendi Silverwing Hold. Respingi le forze invasori dell'Orda!$B$BFa' questo e guadagna un talismano di merito. Portami un talismano simile, $N, e ti ricompenserò.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Orda, ottieni un Warsong Gulch Mark of Honor e torna da Sentinel Farsong, al Silverwing Grove.",
  en_title = "Vanquish the Invaders",
  en_obj = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
}
T[8295] = {
  title = "Soffoca gli usurpatori Silverwing",
  desc = "Le terre selvagge dell'Ashenvale Forest cederanno alla potenza dell'Orda, $R. Niente di quel che i Silverwing dicono o fanno può fermare il nostro diritto sovrano. Kalimdor appartiene all'Orda. Come osano cercare di impedirci di raccogliere quel che ci spetta!$B$BLascia che l'orgoglio ti gonfi il petto mentre abbatti i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le Silverwing Sentinel e guadagna un Warsong Mark of Honor. Torna da me con un marchio simile, $N, e sarai $Gricompensato:ricompensata;.",
  obj = "Entra in Warsong Gulch e sconfiggi l'Alleanza, ottieni un Warsong Gulch Mark of Honor e portalo a Captain Shatterskull, al Mor'shan Base Camp.",
  en_title = "Quell the Silverwing Usurpers",
  en_obj = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
}
T[8311] = {
  title = "Dolcetti della Veglia delle Ombre per Jesper!",
  desc = "Voglio andare a fare dolcetto o scherzetto, ma non posso perché sono malato. Se ci vai tu per me, ti darei in cambio delle caramelle che ho già! Credo che queste caramelle ti piacerebbero: ti trasformano in cose buffe e spaventose!$B$BOgnuno dei locandieri delle grandi città ha delle caramelle che regala per la Veglia delle Ombre: parla con loro e fai gli scherzetti che ti chiedono! Anche un piccolo gnomo di nome Talvash, a Ironforge, sta distribuendo caramelle. Quando avrai tutte le caramelle, riportamele qui!",
  obj = "Parla con i locandieri di Stormwind, Ironforge e Darnassus, e con Talvash del Kissel a Ironforge. Fai gli scherzetti che ti chiedono in cambio dei dolcetti che offrono.$B$BTorna da Jesper, allo Stormwind Orphanage, con un Darnassus Marzipan, una Gnomeregan Gumdrop, uno Stormwind Nougat e una Ironforge Mint.",
  progress = "Hai finito di fare dolcetto o scherzetto? Mi dispiace non poterci andare perché sono malato, ma il fatto che mi aiuti mi fa sentire un po' meglio...",
  reward = "Wow, le hai prese tutte! Sei $Gfantastico:fantastica;!$B$BGrazie di aver fatto dolcetto o scherzetto al posto mio. Ecco, prendi questi dolcetti alla zucca: credo che ti piaceranno un sacco!$B$BBuona Veglia delle Ombre, $N!",
  en_title = "Hallow's End Treats for Jesper!",
  en_obj = "Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge.  Perform the tricks they ask of you in exchange for the treats they offer.$B$BReturn to Jesper at the Stormwind Orphanage with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint.",
}
T[8312] = {
  title = "Dolcetti della Veglia delle Ombre per Spoops!",
  desc = "Voglio andare a fare dolcetto o scherzetto, ma non posso perché sono malata. Se ci vai tu per me, ti darei in cambio delle caramelle che ho già! Credo che queste caramelle ti piacerebbero: ti trasformano in cose buffe e spaventose!$B$BOgnuno dei locandieri delle grandi città ha delle caramelle che regala per la Veglia delle Ombre: parla con loro e fai gli scherzetti che ti chiedono! Anche un troll di nome Kali Remik, a Sen'jin Village, sta distribuendo caramelle. Quando avrai tutte le caramelle, riportamele qui!",
  obj = "Parla con i locandieri di Orgrimmar, dell'Undercity e di Thunder Bluff, e con Kali Remik a Sen'jin Village. Fai gli scherzetti che ti chiedono in cambio dei dolcetti che offrono.$B$BTorna da Spoops, all'Orgrimmar Orphanage, con un Thunder Bluff Marzipan, una Darkspear Gumdrop, un Orgrimmar Nougat e una Undercity Mint.",
  progress = "Hai finito di fare dolcetto o scherzetto? Mi dispiace non poterci andare perché sono malata, ma il fatto che mi aiuti mi fa sentire un po' meglio...",
  reward = "Wow, le hai prese tutte! Sei $Gfantastico:fantastica;!$B$BGrazie di aver fatto dolcetto o scherzetto al posto mio. Ecco, prendi questi dolcetti alla zucca: credo che ti piaceranno un sacco!$B$BBuona Veglia delle Ombre, $N!",
  en_title = "Hallow's End Treats for Spoops!",
  en_obj = "Speak with the innkeepers of Orgrimmar, Undercity, and Thunder Bluff, as well as Kali Remik in Sen'jin Village.  Perform the tricks they ask of you in exchange for the treats they offer.$B$BReturn to Spoops at the Orgrimmar Orphanage with a Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat, and Undercity Mint.",
}
T[8322] = {
  title = "Rotten Eggs",
  desc = "Gli umani di Southshore adorano la loro birra, e per questo tengono moltissimo alla birra servita al Southshore Inn. Ora che il caos della Veglia delle Ombre si è abbattuto su di loro, possiamo approfittarne per rovinare le loro prossime partite di birra per settimane, se non per mesi!$B$BPrendi queste uova marce e mettile nel barile principale della birra, dentro il Southshore Inn. La tua sola presenza scatenerà lo scompiglio, quindi preparati a difenderti!$B$BQuando avrai fatto assaggiare a Southshore un gusto che non dimenticherà presto, torna da me qui alla festa!",
  obj = "Metti le Rotten Eggs nel barile principale della birra, dentro il Southshore Inn.",
  progress = "Il barile è pieno di birra.",
  reward = "Dopo esserti $Gfatto:fatta; strada a forza dentro la locanda, metti le uova nel barile. Senti il fetore che impregna l'aria...",
  en_title = "Rotten Eggs",
  en_obj = "Place the Rotten Eggs in the main brew keg located inside the Southshore Inn.",
}
T[8353] = {
  title = "Chiocciare per una mentina",
  desc = "Ah, dolcetto o scherzetto per un bambino malato, eh? Stavo per dire che sei un po' $Gcresciutello:cresciutella; per andare a frugare in giro in cerca di caramelle...$B$BBe', per il mio dolcetto, una Ironforge Mint, dovrai... chiocciare come una gallina! Sì, alle galline piacciono le mentine... be', ok, forse non le ADORANO... ma non ti darò una mentina finché non chiocci come una gallina per me!$B$BAllora, $C, accetti la sfida o no?! È ora di guadagnarti il dolcetto!",
  obj = "Fai l'emote /chicken davanti a Innkeeper Firebrew, e in cambio riceverai una Ironforge Mint!",
  progress = "Sto aspettando...",
  reward = "Troppo divertente! Ben fatto, $N! Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre!",
  en_title = "Chicken Clucking for a Mint",
  en_obj = "Do a chicken emote at Innkeeper Firebrew, and in exchange you'll receive an Ironforge Mint!",
}
T[8354] = {
  title = "Chiocciare per una mentina",
  desc = "Ah, dolcetto o scherzetto per un bambino malato, eh? Stavo per dire che sei un po' $Gcresciutello:cresciutella; per andare a frugare in giro in cerca di caramelle...$B$BBe', per il mio dolcetto, una Undercity Mint, dovrai... chiocciare come una gallina! Sì, alle galline piacciono le mentine... be', ok, forse non le ADORANO... ma non ti darò una mentina finché non chiocci come una gallina per me!$B$BAllora, $C, accetti la sfida o no?! È ora di guadagnarti il dolcetto!",
  obj = "Fai l'emote /chicken davanti a Innkeeper Norman, e in cambio riceverai una Undercity Mint!",
  progress = "Sto aspettando...",
  reward = "Troppo divertente! Ben fatto, $N! Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre!",
  en_title = "Chicken Clucking for a Mint",
  en_obj = "Do a chicken emote at Innkeeper Norman, and in exchange you'll receive an Undercity Mint!",
}
T[8355] = {
  title = "Arriva la caramella gommosa",
  desc = "$GUno:Una; che fa dolcetto o scherzetto! Evviva!$B$BBe', anche se stai facendo una cosa nobile raccogliendo caramelle per un bambino malato, non posso lasciarti andare così facilmente. Ho una deliziosa Gnomeregan Gumdrop da dare al bambino malato... se fai il verso di un treno per me! Ahah, sì, sarà questo lo scherzetto! Il prezzo di questa caramella è un verso da treno!$B$BCiuf ciuf, $C!",
  obj = "Fai l'emote /train davanti a Talvash del Kissel, e in cambio riceverai una Gnomeregan Gumdrop!",
  progress = "Be', forza...",
  reward = "Tuu tuu! Ben fatto, $N! Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre!",
  en_title = "Incoming Gumdrop",
  en_obj = "Do a train emote at Talvash del Kissel, and in exchange you'll receive a Gnomeregan Gumdrop!",
}
T[8356] = {
  title = "Muscoli in cambio di torrone",
  desc = "È un costume... interessante, quello che indossi. Anche se sei gentile e quest'anno aiuti un bambino malato a fare dolcetto o scherzetto, temo che dovrò chiederti di fare uno scherzetto per me!$B$BVediamo... sembri così $Gforte e muscoloso:forte e muscolosa; con quel... costume... fammi vedere i muscoli! Sì, forza, mostrami i muscoli, $Guomo:donna; forte!$B$BQuando, e solo quando, mi mostrerai i muscoli, ti darò un po' di buonissimo Stormwind Nougat. È un ottimo dolcetto della Veglia delle Ombre.",
  obj = "Fai l'emote /flex davanti a Innkeeper Allison, e in cambio riceverai lo Stormwind Nougat!",
  progress = "Niente caramelle finché non mi mostri i muscoli, $N...",
  reward = "Sei davvero potente, ahah! Ben fatto, e grazie per essere $Gstato:stata; al gioco. Ecco la tua caramella.$B$BBuona Veglia delle Ombre, $N!",
  en_title = "Flexing for Nougat",
  en_obj = "Do a flex emote at Innkeeper Allison, and in exchange you'll receive Stormwind Nougat!$B",
}
T[8357] = {
  title = "Ballare per il marzapane",
  desc = "Anche se fai dolcetto o scherzetto per un bambino malato, per avere il dolcetto devi comunque fare uno scherzetto! Non possiamo certo cambiare la tradizione, no?...$B$BCredo che oggi il prezzo di un pezzo di marzapane sia scatenarsi e BALLARE! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del buonissimo marzapane!",
  obj = "Fai l'emote /dance davanti a Innkeeper Saelienne, e in cambio riceverai il Darnassus Marzipan!",
  progress = "Sai ballare, vero? Prova così: metti dentro il piede destro... poi fuori il piede destro... dentro il piede destro... e scuotilo tutto...",
  reward = "Sei proprio $Gun ballerino nato:una ballerina nata;, $N!$B$BEcco il tuo dolcetto, per essere $Gstato:stata; al gioco. Buona Veglia delle Ombre, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.",
  en_title = "Dancing for Marzipan",
  en_obj = "Do a dance emote at Innkeeper Saelienne, and in exchange you'll receive Darnassus Marzipan!",
}
T[8360] = {
  title = "Ballare per il marzapane",
  desc = "Anche se fai dolcetto o scherzetto per un bambino malato, per avere il dolcetto devi comunque fare uno scherzetto! Non possiamo certo cambiare la tradizione, no?...$B$BCredo che oggi il prezzo di un pezzo di marzapane sia scatenarsi e BALLARE! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del buonissimo marzapane!",
  obj = "Fai l'emote /dance davanti a Innkeeper Pala, e in cambio riceverai il Thunder Bluff Marzipan!",
  progress = "Sai ballare, vero? Prova così: metti dentro il piede destro... poi fuori il piede destro... dentro il piede destro... e scuotilo tutto...",
  reward = "Sei proprio $Gun ballerino nato:una ballerina nata;, $N!$B$BEcco il tuo dolcetto, per essere $Gstato:stata; al gioco. Buona Veglia delle Ombre, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.",
  en_title = "Dancing for Marzipan",
  en_obj = "Do a dance emote at Innkeeper Pala, and in exchange you'll receive Thunder Bluff Marzipan!",
}
T[8368] = {
  title = "La battaglia di Warsong Gulch",
  desc = "La battaglia in Warsong Gulch contro le Silverwing Sentinel è di grande importanza. Con la scusa di proteggere una foresta che non appartiene loro, l'Alleanza cerca di togliere all'Orda una delle nostre più grandi fonti di legname.$B$BNon permetterlo, $N! Torna da me con la prova di aver servito l'Orda in modo degno!",
  obj = "Porta 3 Warsong Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Porti notizie da Warsong Gulch, $N?",
  reward = "Ottimo! Hai dimostrato il tuo valore difendendo le nostre operazioni in Warsong Gulch! Che la voce del tuo onore si spanda in lungo e in largo per le nostre terre.",
  en_title = "Battle of Warsong Gulch",
  en_obj = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8370] = {
  title = "Conquistare Arathi Basin",
  desc = "Il nostro conflitto con l'Alleanza è degenerato in una vera guerra. A questo punto nessuna delle due parti usa più, né si aspetta, falsi pretesti per scendere in battaglia.$B$BLa battaglia per Arathi Basin è una battaglia per le risorse, punto e basta. O l'Alleanza si prende le risorse e le usa contro di noi, o le prendiamo noi e le usiamo per sostenere il nostro sforzo di guerra. Aiuta i Defilers a mantenere il flusso di risorse di cui abbiamo bisogno, $N!",
  obj = "Porta 3 Arathi Basin Mark of Honor a un Horde Warbringer fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; con notizie da Arathi, $C?",
  reward = "Mettere al sicuro le nostre risorse in Arathi è un compito importante! Hai fatto un buon lavoro, $N.",
  en_title = "Conquering Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8372] = {
  title = "Combatti per Warsong Gulch",
  desc = "Le Silverwing Sentinel sono in guerra con i Warsong Outrider per la distruzione che gli orchi stanno causando alla foresta. Ci sono però più ragioni per difendere questa foresta del semplice amore per la natura.$B$BLa foresta forma una barriera strategica che rende Ashenvale difendibile contro un attacco su larga scala. Senza, Astranaar resisterebbe un giorno o due prima di essere annessa alle Barrens.$B$BFa' la tua parte combattendo i Warsong Outrider, $N! Per l'Alleanza!",
  obj = "Porta 3 Warsong Gulch Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Sei $Gtornato:tornata; con notizie dal fronte, $N?",
  reward = "Ben fatto, $N! Hai servito bene l'Alleanza.",
  en_title = "Fight for Warsong Gulch",
  en_obj = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8373] = {
  title = "Il potere del pino",
  desc = "Quello che odio di più della Veglia delle Ombre sono le bombe puzzolenti che i Reietti usano su Southshore. Chi l'avrebbe mai detto che festeggiare la liberazione volesse dire fare un tale schifo puzzolente?$B$BDurante la Veglia delle Ombre, usa questo detergente per eliminare le schifose bombe puzzolenti che l'Orda lascia cadere qui al villaggio. Usa il potere del pino per combattere i cattivi odori.$B$BFai la tua parte per tenere pulita Southshore, e ti darò qualche dolcetto della Veglia delle Ombre che di sicuro ti piacerà. Affare fatto?",
  obj = "Usa uno Stink Bomb Cleaner per eliminare le Forsaken Stink Bomb lanciate su Southshore. Quando hai finito, torna da Sergeant Hartman a Southshore.",
  progress = "Quei maledetti Reietti... è già abbastanza brutto che siano non morti, ma poi si scatenano e cominciano a creare problemi nel MIO villaggio!",
  reward = "Ah, qui intorno si sente già un odore migliore. Quasi.$B$BGrazie a te, $N, Southshore potrebbe superare anche questa Veglia delle Ombre. Ecco i tuoi dolcetti, con i miei ringraziamenti! Se finisci le caramelle, credo che a Ironforge ci sia una gnoma di nome Katrina Shimmerstar che può vendertene altre; credo che ci sia solo durante la Veglia delle Ombre.",
  en_title = "The Power of Pine",
  en_obj = "Use a Stink Bomb Cleaner to remove any Forsaken Stink Bomb that's been dropped on Southshore.  Return to Sergeant Hartman in Southshore when you're done.",
}
T[8374] = {
  title = "Rivendicare Arathi Basin",
  desc = "Vincere una guerra non vuol dire solo superare l'avversario in astuzia e in combattimento. Spesso la vittoria si riduce semplicemente a produrre più del nemico.$B$BQuello che abbiamo in Arathi Basin è una notevole riserva di risorse per la parte che riuscirà a impadronirsene per prima.$B$BSe sarà l'Alleanza a vincere, vorrà dire più spade e picche per le nostre truppe. Se vincesse l'Orda, quelle spade e quelle picche verrebbero fabbricate lo stesso, solo che sarebbero puntate contro di noi! È il momento di aiutare l'Alleanza in Arathi Basin, $N.",
  obj = "Porta 3 Arathi Basin Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.",
  progress = "Dimmi, che notizie ci sono dal fronte?",
  reward = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8384] = {
  title = "Rivendicare Arathi Basin",
  progress = "La guerra contro l'Orda sta esaurendo in fretta le nostre provviste, $N. È vitale mantenere il controllo di Arathi Basin perché il flusso di risorse non si interrompa! Hai già dato una mano in Arathi?",
  reward = "Buon lavoro, $Gsoldato:soldatessa;! Continua così e faremo scappare l'Orda fino a Orgrimmar.",
  en_title = "Claiming Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8386] = {
  title = "Combatti per Warsong Gulch",
  progress = "Non dimenticare che la lotta per Warsong Gulch è molto più che proteggere degli alberi. Si tratta di mantenere una barriera naturale tra Ashenvale e le Barrens. Porti notizie dal campo di battaglia, $N?",
  reward = "Ben fatto, $N! Hai servito bene l'Alleanza.",
  en_title = "Fight for Warsong Gulch",
  en_obj = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.",
}
T[8389] = {
  title = "La battaglia di Warsong Gulch",
  progress = "La battaglia in Warsong Gulch infuria, $N. Fa' la tua parte per cacciare le Silverwing Sentinel dalle nostre terre!",
  reward = "Ottimo! Hai dimostrato il tuo valore difendendo le nostre operazioni in Warsong Gulch! Che la voce del tuo onore si spanda in lungo e in largo per le nostre terre.",
  en_title = "Battle of Warsong Gulch",
  en_obj = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8390] = {
  title = "Conquistare Arathi Basin",
  progress = "La guerra contro la feccia dell'Alleanza richiede risorse, $N! Non possiamo permettere che le nostre scorte si esauriscano nel bel mezzo di una battaglia. Continua a fare in modo che Arathi Basin resti nelle nostre mani!",
  reward = "Mettere al sicuro le nostre risorse in Arathi è un compito importante! Hai fatto un buon lavoro, $N.",
  en_title = "Conquering Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
}
