T[8409] = {
  title = "Barili rovinati",
  desc = "Le uova marce sono state messe nel barile. Le prossime partite di birra del Southshore Inn sono di sicuro rovinate!$B$BOra dovresti tornare da Darkcaller Yanka, al Wickerman Festival nelle Tirisfal Glade, per riferire il tuo successo.",
  obj = "Torna da Darkcaller Yanka, al Wickerman Festival nelle Tirisfal Glade.",
  reward = "Ah, un successo! Hai mostrato il vero spirito della Veglia delle Ombre: lo spirito dei REIETTI, dovrei dire!$B$B<Darkcaller Yanka ride e si sfrega le mani.>$B$BMi rallegra sapere che Southshore ora dovrà festeggiare con birra cattiva o farne a meno! Quanto a te, prendi questi dolcetti. Credo che ne farai buon uso!",
  en_title = "Ruined Kegs",
  en_obj = "Return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.",
}
