T[8440] = {
  title = "Conquistare Arathi Basin",
  progress = "La guerra contro la feccia dell'Alleanza richiede risorse, $N! Non possiamo permettere che le nostre scorte si esauriscano nel bel mezzo di una battaglia. Continua a fare in modo che Arathi Basin resti nelle nostre mani!",
  reward = "Ottimo lavoro, $N! Finché Arathi Basin resterà sotto il nostro controllo, le nostre provviste saranno ben fornite.",
  en_title = "Conquering Arathi Basin",
  en_obj = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",
}
T[8492] = {
  title = "L'Alleanza ha bisogno di Copper Bar!",
  desc = "Ehi, $C, mi sembri abbastanza in forma per contribuire allo sforzo bellico! Qui ci serve tutto l'aiuto possibile per mettere insieme il materiale bellico per la guerra di Ahn'Qiraj, ed è il tuo giorno fortunato.$B$BRaccolgo Copper Bar in pile da venti. È per una buona causa, che ne dici? Pensi di poter dare una mano all'Alleanza?",
  obj = "Porta 20 Copper Bar a Sergeant Stonebrow, nel Military Ward di Ironforge.",
  progress = "Hai già raccolto quelle venti Copper Bar, $Gsoldato:soldatessa;?",
  reward = "Ce l'hai fatta, $Gragazzo:ragazza;! Metteremo subito quelle Copper Bar sul mucchio e le useremo per fare il materiale bellico. Sono gli sforzi di gente come te che mi rendono orgoglioso di servire l'Alleanza. Bel lavoro, $Gsoldato:soldatessa;!$B$BE se ti capita di trovare altre Copper Bar, fa' in modo che arrivino a me.",
  en_title = "The Alliance Needs Copper Bars!",
  en_obj = "Bring 20 Copper Bars to Sergeant Stonebrow at the Military Ward in Ironforge.",
}
T[8493] = {
  title = "L'Alleanza ha bisogno di altre Copper Bar!",
  desc = "Di nuovo qui, $C? Magnifico! Ci servono ancora pile di Copper Bar, se riesci a procurarle per lo sforzo bellico di Ahn'Qiraj. Ci dai una mano?",
  obj = "Porta 20 Copper Bar a Sergeant Stonebrow, all'aerodromo di Dun Morogh.",
  progress = "Di nuovo qui, $C? Magnifico! Le barre che ci hai portato finora saranno davvero utili per fabbricare ogni genere di cose per la guerra. So, per esempio, che il rame servirà per i pezzi dei carri a vapore in costruzione, e per una piccola flotta di girocotteri che contiamo di schierare, se ci sarà tempo.$B$BMa non farti ingannare dalle pile che vedi qui: ci servono ancora Copper Bar, se riesci a procurarle per lo sforzo bellico di Ahn'Qiraj. Ci dai una mano?",
  reward = "Ottimo lavoro! Scavare per trovare quel rame e fonderlo dev'essere stata una bella avventura. A meno che tu non abbia comprato le barre alla casa d'aste. In ogni caso, a me va bene. Meriti un encomio per il tuo contributo allo sforzo bellico, $C. E non esitare a portarmi altre Copper Bar, se ne hai.",
  en_title = "The Alliance Needs More Copper Bars!",
  en_obj = "Bring 20 copper bars to Sergeant Stonebrow at the airfield in Dun Morogh.",
}
T[8494] = {
  title = "L'Alleanza ha bisogno di Iron Bar!",
  desc = "Ma guarda chi si vede, $Gsignor Elegantone:signorina Elegantona;, che piacere per gli occhi. Nel caso non l'avessi sentito dire mentre eri là fuori a \"fare avventure\", l'Alleanza si sta preparando a una guerra ad Ahn'Qiraj e ha bisogno di Iron Bar... un mucchio enorme. Portamele in pile da venti. Possiamo contare su di te, vero, $C?",
  obj = "Porta 20 Iron Bar a Corporal Carnes, nel Military Ward di Ironforge.",
  progress = "Se hai quelle venti Iron Bar, non voglio sapere dove le tieni nascoste!",
  reward = "Bene, bene, guarda chi c'è: $N. E ce l'hai fatta. Immagino che adesso dovrò tenerti d'occhio. Mi costa dirlo, ma grazie per i tuoi sforzi. L'Alleanza non lo dimenticherà, e nemmeno io. Ora torna là fuori e sgobba per raccogliere qualsiasi altra cosa serva.",
  en_title = "The Alliance Needs Iron Bars!",
  en_obj = "Bring 20 Iron Bars to Corporal Carnes at the Military Ward in Ironforge.",
}
T[8495] = {
  title = "L'Alleanza ha bisogno di altre Iron Bar!",
  desc = "Già di ritorno? Smettila di farmi rivedere la pessima opinione che ho di te, $C, mi stai facendo sentire tutto tenero dentro. Allora, come vedi non abbiamo ancora abbastanza Iron Bar per tutte le armi, le armature, i carri a vapore e compagnia bella che vanno costruiti per la caccia agli insetti. Pensi di farcela a portarmi un'altra pila di venti Iron Bar, tra un viaggio e l'altro a Zul'Gurub, o dovunque andiate a bighellonare voi ragazzi di oggi?",
  obj = "Porta 20 Iron Bar a Corporal Carnes, all'aerodromo di Dun Morogh.",
  progress = "Già di ritorno? Smettila di farmi rivedere la pessima opinione che ho di te, $C, mi stai facendo sentire tutto tenero dentro. Allora, come vedi non abbiamo ancora abbastanza Iron Bar per tutte le armi, le armature, i carri a vapore e compagnia bella che vanno costruiti per la caccia agli insetti. Pensi di farcela a portarmi un'altra pila di venti Iron Bar, tra un viaggio e l'altro a Zul'Gurub, o dovunque andiate a bighellonare voi ragazzi di oggi?",
  reward = "Dev'essere una giornata fredda nelle Burning Steppes. Guarda un po', c'è $N, ed è $Gvenuto:venuta; a portarmi un regalo. Venti Iron Bar! Proprio quello che ho sempre desiderato.$B$BMa scherzi a parte, grazie, $N. Fai onore a te $Gstesso:stessa; e all'Alleanza. Ora torna là fuori e porta altra roba per lo sforzo bellico!",
  en_title = "The Alliance Needs More Iron Bars!",
  en_obj = "Bring 20 iron bars to Corporal Carnes at the airfield in Dun Morogh.",
}
T[8499] = {
  title = "L'Alleanza ha bisogno di Thorium Bar!",
  desc = "È molto gentile da parte tua informarti su ciò di cui l'Alleanza ha bisogno. Oltre a tutte le altre raccolte in corso, ci serve una grande quantità di Thorium Bar, ed è questo il compito di cui sono responsabile. Il torio servirà a creare molte cose diverse per la guerra, prima fra tutte un battaglione di carri a vapore da trasportare per via aerea a Silithus appena saranno pronti. Puoi aiutarci in questa impresa, $C?",
  obj = "Porta 20 Thorium Bar a Dame Twinbraid, nel Military Ward di Ironforge.",
  progress = "Oh, un carico da parte di mio fratello? Splendido! Oggi la fortuna mi sorride davvero!",
  reward = "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...",
  en_title = "The Alliance Needs Thorium Bars!",
  en_obj = "Bring 20 Thorium Bars to Dame Twinbraid at the Military Ward in Ironforge.",
}
T[8500] = {
  title = "L'Alleanza ha bisogno di altre Thorium Bar!",
  desc = "Che bello rivederti, $N. Spero che tu stia bene. È vero, abbiamo ancora bisogno di Thorium Bar. Se ne hai da parte, le raccolgo per lo sforzo bellico di Ahn'Qiraj.",
  obj = "Porta 20 Thorium Bar a Dame Twinbraid, all'aerodromo di Dun Morogh.",
  progress = "Che bello rivederti, $N. Spero che tu stia bene. È vero, abbiamo ancora bisogno di Thorium Bar. Se ne hai da parte, le raccolgo per lo sforzo bellico di Ahn'Qiraj.",
  reward = "Eccellente, $C! Un lavoro ben fatto. Mi assicurerò che quelle barre finiscano sul bancale e nelle mani dei fabbri e degli ingegneri che lavorano sodo per preparare i rifornimenti del nostro esercito. Grazie ancora, e se trovi altre Thorium Bar, passa pure da me.",
  en_title = "The Alliance Needs More Thorium Bars!",
  en_obj = "Bring 20 thorium bars to Dame Twinbraid at the airfield in Dun Morogh.",
}
T[8503] = {
  title = "L'Alleanza ha bisogno di Stranglekelp!",
  desc = "Allora, $C, ti ho già parlato di tutti i favolosi usi della Stranglekelp? Sì? Be', pazienza... comunque ce ne serve tanta, e quando dico tanta intendo TANTISSIMA! Pensi di poterci dare una mano? So che significa rinunciare a tutte le cose meravigliose che ci puoi fare, ma è per una buona causa!",
  obj = "Porta 20 Stranglekelp a Private Draxlegauge, nel Military Ward di Ironforge.",
  progress = "Non è vero! Non prenderei mai di nascosto un po' di Stranglekelp dalle pile che ho qui. Anche se la tentazione ci sarebbe, visto che è praticamente una panacea di utilità pratica. *coff* Non è che per caso hai la Stranglekelp di cui parlavamo prima?",
  reward = "Evviva! Altre venti sistemate. Sei $Gil migliore:la migliore;. Immagino che dovrei impacchettarle tutte prima che appassiscano. Tanta Stranglekelp, così poco tempo!$B$BGrazie ancora, $C!",
  en_title = "The Alliance Needs Stranglekelp!",
  en_obj = "Bring 20 Stranglekelp to Private Draxlegauge at the Military Ward in Ironforge.",
}
T[8504] = {
  title = "L'Alleanza ha bisogno di altra Stranglekelp!",
  desc = "Ma guarda, ciao di nuovo... com'era? Ah sì, $N! Sei $Gvenuto:venuta; a vedere se mi serve ancora Stranglekelp, eh? Be', è il tuo giorno fortunato, perché la risposta a questa importantissima domanda è un SÌ convintissimo! Pensi di riuscire a raccoglierne altre venti?",
  obj = "Porta 20 Stranglekelp a Private Draxlegauge, all'aerodromo di Dun Morogh.",
  progress = "Ma guarda, ciao di nuovo... com'era? Ah sì, $N! Sei $Gvenuto:venuta; a vedere se mi serve ancora Stranglekelp, eh? Be', è il tuo giorno fortunato, perché la risposta a questa importantissima domanda è un SÌ convintissimo! Pensi di riuscire a raccoglierne altre venti?",
  reward = "Oh, santo cielo, che carico di Stranglekelp hai lì! Presto, mettiamola in una cassa per tenerla fresca. Portando questa partita hai fatto a me... cioè, a noi, all'Alleanza, un grande favore. Farò in modo che tutti sappiano che sei $Gstato:stata; tu, $Gil grande:la grande; $N, ad aiutare a far pendere la bilancia nello sforzo bellico di Ahn'Qiraj con il tuo contributo di Stranglekelp!",
  en_title = "The Alliance Needs More Stranglekelp!",
  en_obj = "Bring 20 stranglekelp to Private Draxlegauge at the airfield in Dun Morogh.",
}
T[8505] = {
  title = "L'Alleanza ha bisogno di Purple Lotus!",
  desc = "$C, il Purple Lotus è un fiore dai molteplici usi. Sono qui su richiesta dell'Alleanza come autorità in materia, per conservare le erbe raccolte e assicurarmi che il suo sforzo bellico ottenga abbastanza Purple Lotus per qualunque impiego abbia in mente.$B$BVorrei che tu viaggiassi per il mondo e tornassi da me con qualcuno di questi fiori. Puoi farlo?",
  obj = "Porta 20 Purple Lotus a Master Nightsong, nel Military Ward di Ironforge.",
  progress = "Hai le erbe di Purple Lotus che ti ho chiesto?",
  reward = "Il tuo contributo è molto apprezzato, $C. Solo con gli sforzi uniti di tutti potremo respingere l'avanzata spietata dei silitidi e di qualunque forza li stia spingendo avanti. Anche l'Orda sta ammassando la sua scorta di Purple Lotus. Se ne trovi altro, ti prego, torna da me.",
  en_title = "The Alliance Needs Purple Lotus!",
  en_obj = "Bring 20 Purple Lotus to Master Nightsong at the Military Ward in Ironforge.",
}
T[8506] = {
  title = "L'Alleanza ha bisogno di altro Purple Lotus!",
  desc = "$GBentornato:Bentornata;, $C. La nostra raccolta cresce, ma anche ora abbiamo bisogno di altro Purple Lotus. Se è ancora in tuo potere raccogliere altre di queste erbe, ti prego di farlo e di riportarmele qui.",
  obj = "Porta 20 Purple Lotus a Master Nightsong, all'aerodromo di Dun Morogh.",
  progress = "$GBentornato:Bentornata;, $C. La nostra raccolta cresce, ma anche ora abbiamo bisogno di altro Purple Lotus. Se è ancora in tuo potere raccogliere altre di queste erbe, ti prego di farlo e di riportarmele qui.",
  reward = "Accetto con piacere il tuo contributo a nome dell'Alleanza, $N. I tuoi sforzi porteranno direttamente alla creazione di varie pozioni e oli a sostegno dei nostri uomini e delle nostre donne sul campo. Grazie, e se ne trovassi altro, considera di tornare da me.",
  en_title = "The Alliance Needs More Purple Lotus!",
  en_obj = "Bring 20 purple lotus to Master Nightsong at the airfield in Dun Morogh.",
}
T[8509] = {
  title = "L'Alleanza ha bisogno di Arthas' Tears!",
  desc = "Sarò semplice e diretta, $C. L'Alleanza deve raccogliere una grande quantità di Arthas' Tears per lo sforzo bellico di Ahn'Qiraj. Non chiedermi a cosa servano: io eseguo solo gli ordini. Ma vorrei che tu raccogliessi quante più di queste erbe puoi e me le riportassi qui. Sei $Gdisposto:disposta; a farlo?",
  obj = "Porta 20 Arthas' Tears a Sergeant Major Germaine, nel Military Ward di Ironforge.",
  progress = "Come dici? Parla più forte, $C! Hai quel carico di Arthas' Tears che ti ho chiesto?",
  reward = "Bel lavoro, $C. Devo dire che sono piacevolmente sorpresa. Non crederesti a quanta gente è passata di qui offrendosi di aiutare, senza poi tornare mai. Lasciami mettere queste in una cassa e registrarle a tuo nome, poi potremo riparlarne, per vedere se mi servono altre di queste piante.",
  en_title = "The Alliance Needs Arthas' Tears!",
  en_obj = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the Military Ward in Ironforge.",
}
T[8510] = {
  title = "L'Alleanza ha bisogno di altre Arthas' Tears!",
  desc = "Ok, a quanto pare mi servono ancora Arthas' Tears. Immagino che potrai trovarle più o meno nella stessa zona in cui le hai raccolte per me l'ultima volta. Prima le avremo, prima potremo lanciare l'offensiva contro le forze di Ahn'Qiraj.$B$BCi dai di nuovo una mano, $C?",
  obj = "Porta 20 Arthas' Tears a Sergeant Major Germaine, all'aerodromo di Dun Morogh.",
  progress = "Ok, a quanto pare mi servono ancora Arthas' Tears, $C. Immagino che potrai trovarle più o meno nella stessa zona in cui le hai raccolte per me l'ultima volta. Lo sforzo bellico procede bene, ma prima le avremo, prima potremo lanciare l'offensiva contro le forze di Ahn'Qiraj.$B$BCi dai di nuovo una mano, $N?",
  reward = "Semplicemente eccezionale, $N! Fai davvero onore all'Alleanza. Metterò via queste erbe finché qualcuno non verrà a trasformarle in qualcosa di utile per la guerra. Torna pure quando vuoi, soprattutto se hai altre Arthas' Tears per me.",
  en_title = "The Alliance Needs More Arthas' Tears!",
  en_obj = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the airfield in Dun Morogh.",
}
T[8511] = {
  title = "L'Alleanza ha bisogno di Light Leather!",
  desc = "Noi Stoneflayer abbiamo una lunga tradizione di scuoiatori, $C. Per questo l'Alleanza ha chiesto alla mia famiglia di aiutare a raccogliere Light Leather per lo sforzo bellico di Ahn'Qiraj. Sono qui per assicurarmi che il cuoio venga conciato come si deve, qualunque sia l'uso che vogliono farne. Ma ci serve il tuo aiuto.$B$BVisto che devo restare qui a fare questo, ho bisogno che tu vada a raccogliere le pelli e me le riporti qui. Che ne dici, $Gragazzo:ragazza;, ci provi?",
  obj = "Porta 10 Light Leather a Bonnie Stoneflayer, nel Military Ward di Ironforge.",
  progress = "$C, spero proprio che quello sia il Light Leather che mi avevi promesso.",
  reward = "Direi che l'Alleanza sarà molto contenta di queste tue pelli, $C. Farò in modo che non se ne sprechi nemmeno una. Grazie, e ripassa da me quando le avrò contate, per vedere se ce ne servono altre.",
  en_title = "The Alliance Needs Light Leather!",
  en_obj = "Bring 10 Light Leather to Bonnie Stoneflayer at the Military Ward in Ironforge.",
}
T[8512] = {
  title = "L'Alleanza ha bisogno di altro Light Leather!",
  desc = "Che piacere rivederti, $N. Sembra proprio che ci serva altro Light Leather per fabbricare il materiale bellico. Se mi portassi una pila da dieci, sarebbe perfetto.",
  obj = "Porta 10 Light Leather a Bonnie Stoneflayer, all'aerodromo di Dun Morogh.",
  progress = "Che piacere rivederti, $N. Sembra proprio che ci serva altro Light Leather per fabbricare il materiale bellico. Se mi portassi una pila da dieci, sarebbe perfetto.",
  reward = "Grazie per la tua generosa donazione, $N. Le metto subito sul mucchio, e vedrai che in un attimo diventeranno una bella armatura, qualche toppa di cuoio o qualcos'altro per i nostri preparativi. Pare che il Light Leather non basti mai. Torna a trovarmi presto.",
  en_title = "The Alliance Needs Light Leather!",
  en_obj = "Bring 10 light leather to Bonnie Stoneflayer at the airfield in Dun Morogh.",
}
T[8513] = {
  title = "L'Alleanza ha bisogno di Medium Leather!",
  desc = "Sì, $Gsignore:signora;, mi hanno incaricato di raccogliere e registrare tutto il Medium Leather raccolto per lo sforzo bellico. Se hai modo di procurarti del Medium Leather, da qualunque fonte, per favore portalo qui da me. Mi farebbe davvero comodo una mano, se hai un po' di tempo.",
  obj = "Porta 10 Medium Leather a Private Porter, nel Military Ward di Ironforge.",
  progress = "Sì, $Gsignore:signora;, mi ricordo di te. È il Medium Leather quello che hai lì con te?",
  reward = "Caspita! Mi sembra che tu fossi qui proprio poco fa a offrirti di aiutare. Grazie mille per la donazione. Adesso le impacchetto e le conto tutte. Sai proprio come rallegrare la giornata a un povero soldato.",
  en_title = "The Alliance Needs Medium Leather!",
  en_obj = "Bring 10 Medium Leather to Private Porter at the Military Ward in Ironforge.",
}
T[8514] = {
  title = "L'Alleanza ha bisogno di altro Medium Leather!",
  desc = "Sì, $Gsignore:signora;, pare che finora abbiamo raccolto un sacco di pezzi di Medium Leather. So che è chiedere molto, ma se sei ancora $Gdisposto:disposta;, mi farebbe comodo il tuo aiuto per intaccare quello che resta della mia quota.",
  obj = "Porta 10 Medium Leather a Private Porter, all'aerodromo di Dun Morogh.",
  progress = "Sì, $Gsignore:signora;, pare che abbiamo raccolto un sacco di pezzi di Medium Leather, ma ce ne servono altri. Ti assicuro che sarà tutto usato bene: non se ne sprecherà nemmeno un pezzo. So che è chiedere molto, ma se sei ancora $Gdisposto:disposta;, mi farebbe comodo il tuo aiuto per intaccare quello che resta della mia quota.",
  reward = "Accidenti, che quantità di Medium Leather mi hai portato, $Gsignore:signora;! Farò in modo che venga usato tutto come si deve, sissignore. Con il tuo aiuto raggiungeremo la nostra stima di Medium Leather in un baleno!$B$BGrazie, $N!",
  en_title = "The Alliance Needs More Medium Leather!",
  en_obj = "Bring 10 medium leather to Private Porter at the airfield in Dun Morogh.",
}
T[8515] = {
  title = "L'Alleanza ha bisogno di Thick Leather!",
  desc = "Oh, che bello, sarà fantastico! $C, lo sforzo bellico di Ahn'Qiraj è in pieno svolgimento, e mi hanno incaricato di tenere il conto di tutto il Thick Leather che arriva. Ci faremo un sacco di cose, ma prima dobbiamo raccoglierne una tonnellata. E lo dico alla lettera! Ed è qui che entri in gioco tu.$B$BAllora, pensi di poter andare là fuori e riportarmi una bella pila grassa di Thick Leather? Eh? Eh?!",
  obj = "Porta 10 Thick Leather a Marta Finespindle, nel Military Ward di Ironforge.",
  progress = "È Thick Leather quello che hai lì nello zaino, $C? Lo è? Non vedo l'ora che me lo consegni! Saranno tutti così contenti di noi, non credi?",
  reward = "Oh, lo sapevo che ce l'avresti fatta, $C, lo sapevo! Lo metterò nelle mani giuste il prima possibile. Allora, vediamo un po'. Mmm, pare che il conto stia procedendo piuttosto bene. Ripassa da me tra un attimo, quando avrò finito di contare, per vedere se ce ne serve altro. Perché se è così, voglio che sia tu ad andare a raccoglierlo per me!",
  en_title = "The Alliance Needs Thick Leather!",
  en_obj = "Bring 10 Thick Leather to Marta Finespindle at the Military Ward in Ironforge.",
}
T[8516] = {
  title = "L'Alleanza ha bisogno di altro Thick Leather!",
  desc = "Già, la pila non è ancora abbastanza alta. $N, non abbiamo ancora raggiunto il nostro obiettivo di Thick Leather. Pensa a tutte le cose che possiamo fare con tutto quel cuoio! Armature e armi di ogni tipo. Roba per l'interno dei carri a vapore e per i mirini dei fucili! Occhiali d'ingegneria, e scommetto che se finiamo per raccoglierne troppo potremmo dare il resto all'Orda per i suoi zeppelin!$B$BMi riporti altro Thick Leather?",
  obj = "Porta 10 Thick Leather a Marta Finespindle, all'aerodromo di Dun Morogh.",
  progress = "Già, la pila non è ancora abbastanza alta. $N, non abbiamo ancora raggiunto il nostro obiettivo di Thick Leather. Pensa a tutte le cose che possiamo fare con tutto quel cuoio! Armature e armi di ogni tipo. Roba per l'interno dei carri a vapore e per i mirini dei fucili! E occhiali d'ingegneria, che sono sempre divertenti!$B$BMi riporti altro Thick Leather?",
  reward = "Ce l'hai fatta di nuovo! È semplicemente incredibile come tu vada là fuori, raccolga tutta questa roba e poi la riporti qui a consegnarla. Te lo dico io: quando scopriranno quanto hai aiutato qui, non potrai fare due passi per strada senza che la gente ti chieda l'autografo!$B$BGrazie ancora per la tua generosissima donazione di Thick Leather, $N.",
  en_title = "The Alliance Needs More Thick Leather!",
  en_obj = "Bring 10 thick leather to Marta Finespindle at the airfield in Dun Morogh.",
}
T[8517] = {
  title = "L'Alleanza ha bisogno di Linen Bandage!",
  desc = "La guerra ad Ahn'Qiraj sarà lunga e sanguinosa. L'Alleanza fa una cosa molto saggia a chiedere l'aiuto di te e di quelli come te per accumulare il materiale bellico necessario, prima di gettarsi a capofitto nel conflitto.$B$BMi è stato chiesto di dirigere la raccolta di Linen Bandage per la guerra, e spero che tu mi aiuterai a radunarne quante ne servono. Non è una questione da poco, ma almeno le Linen Bandage sono le meno difficili da preparare. Sei con noi, $C?",
  obj = "Porta 20 Linen Bandage a Sentinel Silversky, nel Military Ward di Ironforge.",
  progress = "Hai le venti Linen Bandage che mi servono, $C?",
  reward = "Molti sono i soldati che trarranno beneficio dal contributo che hai dato oggi, $C. Mi assicurerò di persona che l'Alleanza venga a sapere dei tuoi sforzi. Concedimi un momento per riporre come si deve queste bende e aggiornare il conto, poi ripassa da me per vedere se me ne servono altre.$B$BChe la Luce di Elune risplenda su di te, $R!",
  en_title = "The Alliance Needs Linen Bandages!",
  en_obj = "Bring 20 Linen Bandages to Sentinel Silversky at the Military Ward in Ironforge.",
}
T[8518] = {
  title = "L'Alleanza ha bisogno di altre Linen Bandage!",
  desc = "Sono sempre stupita dall'altruismo di alcuni, quando tanti altri si abbandonano invece all'egoismo. $C, mi serve ancora un certo numero di Linen Bandage prima che il mio incarico qui sia concluso. Mi aiuterai ancora una volta a raccoglierle?",
  obj = "Porta 20 Linen Bandage a Sentinel Silversky, all'aerodromo di Dun Morogh.",
  progress = "Sono sempre stupita dall'altruismo di alcuni, quando tanti altri si abbandonano invece all'egoismo. $C, mi serve ancora un certo numero di Linen Bandage prima che il mio incarico qui sia concluso. Mi aiuterai ancora una volta a raccoglierle?",
  reward = "Meriti un encomio, $N. Mentre c'è chi approfitta dell'economia di guerra per riempirsi le tasche in preda all'avidità, tu hai dimostrato più e più volte che la tua devozione all'Alleanza, e anzi a tutta Azeroth, viene prima di tutto.$B$BChe le benedizioni di Elune siano sempre con te!",
  en_title = "The Alliance Needs More Linen Bandages!",
  en_obj = "Bring 20 linen bandages to Sentinel Silversky at the airfield in Dun Morogh.",
}
T[8520] = {
  title = "L'Alleanza ha bisogno di Silk Bandage!",
  desc = "Con la guerra di Ahn'Qiraj alle porte, dobbiamo fare tutto il possibile perché i nostri soldati abbiano tutto ciò che serve. Ed è proprio quello che facciamo qui. Per quanto mi riguarda, mi hanno affidato il compito di raccogliere abbastanza Silk Bandage.$B$BPensi di potermi aiutare, $C?",
  obj = "Porta 20 Silk Bandage a Nurse Stonefield, nel Military Ward di Ironforge.",
  progress = "Ciao, $C, sei $Griuscito:riuscita; a procurarti quelle venti Silk Bandage?",
  reward = "$C, ce l'hai fatta! Grazie a te siamo un altro passo più vicini al nostro obiettivo di Silk Bandage. Le metto via, e poi, se vuoi, possiamo parlarne ancora.",
  en_title = "The Alliance Needs Silk Bandages!",
  en_obj = "Bring 20 Silk Bandages to Nurse Stonefield at the Military Ward in Ironforge.",
}
T[8521] = {
  title = "L'Alleanza ha bisogno di altre Silk Bandage!",
  desc = "È molto gentile da parte tua offrirti di nuovo di aiutarmi, $C. Pare che abbiamo raccolto un bel numero di Silk Bandage, ma ce ne serviranno altre.",
  obj = "Porta 20 Silk Bandage a Nurse Stonefield, all'aerodromo di Dun Morogh.",
  progress = "È molto gentile da parte tua offrirti di nuovo di aiutarmi, $C. Pare che abbiamo raccolto un bel numero delle Silk Bandage che ci hanno chiesto, ma ce ne servono ancora. $N, c'è modo che tu riesca a mettere insieme un altro fascio e a riportarmelo qui? L'Alleanza e io te ne saremo molto grate.",
  reward = "Sei una persona davvero altruista. Grazie mille per il tuo contributo allo sforzo bellico. Sono le persone come te che faranno la differenza tra il successo e la sconfitta ad Ahn'Qiraj. Spero solo che tutto questo basti.$B$BGrazie ancora, $N.",
  en_title = "The Alliance Needs More Silk Bandages!",
  en_obj = "Bring 20 silk bandages to Nurse Stonefield at the airfield in Dun Morogh.",
}
T[8522] = {
  title = "L'Alleanza ha bisogno di Runecloth Bandage!",
  desc = "Discuti pure sull'opportunità della guerra, se vuoi, $C, ma ormai è stata avviata. Guarda la tua famiglia e i tuoi amici, e poi chiediti che cosa puoi fare perché, se saranno coinvolti, abbiano ogni vantaggio per sopravvivere alla conflagrazione.$B$BPer questo raccolgo qui Runecloth Bandage, da qualunque fonte vengano. Vuoi fare una donazione?",
  obj = "Porta 20 Runecloth Bandage a Keeper Moonshade, nel Military Ward di Ironforge.",
  progress = "I giorni passano uno dopo l'altro, e noi andiamo avanti. $C, hai quelle Runecloth Bandage?",
  reward = "Meriti un encomio per la tua perseveranza in questo compito, $C. Metterò via queste bende, e poi vorrei parlarti di nuovo della possibilità che tu raccolga ancora altre Runecloth Bandage.",
  en_title = "The Alliance Needs Runecloth Bandages!",
  en_obj = "Bring 20 Runecloth Bandages to Keeper Moonshade at the Military Ward in Ironforge.",
}
T[8523] = {
  title = "L'Alleanza ha bisogno di altre Runecloth Bandage!",
  desc = "Eccoci di nuovo qui a discutere di questioni urgenti, $C. Ancora una volta ti ringrazio per i tuoi sforzi passati: non tutti darebbero con tanto altruismo. Ma c'è ancora del lavoro da fare.$B$B$N, raccoglierai ancora una volta Runecloth Bandage e me le riporterai qui?",
  obj = "Porta 20 Runecloth Bandage a Keeper Moonshade, all'aerodromo di Dun Morogh.",
  progress = "Eccoci di nuovo qui a discutere di questioni urgenti, $C. Ancora una volta ti ringrazio per i tuoi sforzi passati: non tutti darebbero con tanto altruismo. Ma c'è ancora del lavoro da fare.$B$B$N, raccoglierai ancora una volta Runecloth Bandage e me le riporterai qui?",
  reward = "È una bella strada quella che percorriamo insieme, $N. Sei $Gun ottimo compagno:un'ottima compagna; di lavoro. Ancora una volta ti ringrazio per i tuoi sforzi a nome di tutta l'Alleanza. Torna presto a parlare con me.",
  en_title = "The Alliance Needs More Runecloth Bandages!",
  en_obj = "Bring 20 runecloth bandages to Keeper Moonshade at the airfield in Dun Morogh.",
}
T[8524] = {
  title = "L'Alleanza ha bisogno di Rainbow Fin Albacore!",
  desc = "Ehi, $Gamico:amica;! Se ti chiedessi: \"Non pensi che i soldati debbano avere da mangiare come tutti gli altri?\", ovviamente risponderesti: \"Sì\". Sono d'accordo con te al 110%! Sono contento che la pensiamo allo stesso modo. Tutto quello che devi fare è andare là fuori, pescare un bel mucchio di Raw Rainbow Fin Albacore, cucinarlo tutto e riportarmelo proprio qui. Mmm, mmm, lo sento già in bocca.",
  obj = "Porta 20 Rainbow Fin Albacore a Slicky Gastronome, nel Military Ward di Ironforge.",
  progress = "Scommetto che sei $Gtornato:tornata; con tutto quel Rainbow Fin Albacore di cui parlavamo prima, vero, $C?",
  reward = "Due per l'Alleanza, uno per me, due per l'Alleanza, uno per me. Ehi, $Gpescivendolo:pescivendola;, ottimo lavoro. Vedo che farai onore al club. Mi sa però che ci serve altro albacore. Perché non vai là fuori a rimediarne ancora un po'? Sento già lo stomaco che brontola.",
  en_title = "The Alliance Needs Rainbow Fin Albacore!",
  en_obj = "Bring 20 Rainbow Fin Albacore to Slicky Gastronome at the Military Ward in Ironforge.",
}
T[8525] = {
  title = "L'Alleanza ha bisogno di altro Rainbow Fin Albacore!",
  desc = "Cosa! Ancora tu? Be', e io sono lo zio di una scimmia... anzi no, sono uno gnomo. Slicky Gastronome, per la precisione! Quindi sei $Gtornato:tornata; ad aiutare, eh? Be', non posso darti torto. Non adori anche tu il profumo di tutto quel cibo? <sbava>$B$BBasta perdere tempo! Va' là fuori e riportami altro Rainbow Fin Albacore!",
  obj = "Porta 20 Rainbow Fin Albacore a Slicky Gastronome, all'aerodromo di Dun Morogh.",
  progress = "Cosa! Ancora tu? Be', e io sono lo zio di una scimmia... anzi no, sono uno gnomo. Slicky Gastronome, per la precisione! Quindi sei $Gtornato:tornata; ad aiutare, eh? Be', non posso darti torto. Non adori anche tu il profumo di tutto quel cibo? <sbava>$B$BBasta perdere tempo! Va' là fuori e riportami altro Rainbow Fin Albacore!",
  reward = "Lo sapevo che ce l'avevi dentro, $Gragazzo:ragazza;. Hai l'aria di $Guno che sa cosa gli piace:una che sa cosa le piace;. In particolare, che ti piace fare contento me e chi comanda. E ci sei $Griuscito:riuscita;, te lo garantisco.$B$BAhah, ok, metto via questi pesci come si deve, e poi io e te facciamo due chiacchiere perché tu mi raccolga altri venti albacore.",
  en_title = "The Alliance Needs More Rainbow Fin Albacore!",
  en_obj = "Bring 20 rainbow fin albacore to Slicky Gastronome at the airfield in Dun Morogh.",
}
T[8526] = {
  title = "L'Alleanza ha bisogno di Roast Raptor!",
  desc = "Oh, come va, $C? Vedo che ti interessa magari raccogliere cibo per la guerra di Ahn'Qiraj in arrivo? Chissà perché mio padre ha pensato che sarebbe stata una bella esperienza per me offrirmi di aiutare qui. Grosso errore. A me la carne non piace nemmeno.$B$BComunque, se ti va, potresti riportarmi un sacco di Roast Raptor. A quanto pare è quello che vorranno tutti i soldati.",
  obj = "Porta 20 Roast Raptor a Sarah Sadwhistle, nel Military Ward di Ironforge.",
  progress = "Allora, ce l'hai tutto quel Roast Raptor?",
  reward = "Uh, fantastico. Grazie di avermi portato tutta questa carne di animale bruciata, $C. La metto sul mucchio laggiù. Qualcuno se ne occuperà di sicuro. Immagino che, se hai un po' di tempo libero, vorrai portarmene altra?",
  en_title = "The Alliance Needs Roast Raptor!",
  en_obj = "Bring 20 Roast Raptor to Sarah Sadwhistle at the Military Ward in Ironforge.",
}
T[8527] = {
  title = "L'Alleanza ha bisogno di altro Roast Raptor!",
  desc = "Ciao di nuovo, $C. Vedo che tutto questo ti entusiasma parecchio. Quindi immagino che tu voglia portarmi altri venti Roast Raptor. Fantastico. Be', fallo pure. Credo che ci vedremo quando torni.",
  obj = "Porta 20 Roast Raptor a Sarah Sadwhistle, all'aerodromo di Dun Morogh.",
  progress = "Ciao di nuovo, $C. Vedo che tutto questo ti entusiasma parecchio. Quindi immagino che tu voglia portarmi altri venti Roast Raptor? Fantastico. Be', fallo pure. Credo che ci vedremo quando torni.",
  reward = "Wow, hai proprio una marcia in più. Mi stanchi solo a guardarti. Comunque, grazie da parte dell'Alleanza e via dicendo. Farò in modo che tutta quella carne morta venga impacchettata. Immagino che potresti ripassare più tardi per vedere se ce ne serve ancora, anche se, se vuoi sapere come la penso, comincia a far puzzare tutto il posto.",
  en_title = "The Alliance Needs More Roast Raptor!",
  en_obj = "Bring 20 roast raptor to Sarah Sadwhistle at the airfield in Dun Morogh.",
}
T[8528] = {
  title = "L'Alleanza ha bisogno di Spotted Yellowtail!",
  desc = "Raccogliere pesce cotto può non sembrare eroico, ma non sottovalutare il valore della preparazione, giovane $C. I soldati devono mangiare come tutti gli altri, e noi siamo qui a fare la nostra parte perché abbiano ciò che serve quando comincerà la guerra ad Ahn'Qiraj.$B$BPer questo sto facendo scorta di Spotted Yellowtail, una fonte di nutrimento versatile che si conserva bene e si può usare in molti piatti diversi. E non ha nemmeno l'odore di certi altri pesci di mare. Sei $Gdisposto:disposta; ad aiutarmi in questa impresa?",
  obj = "Porta 20 Spotted Yellowtail a Huntress Swiftriver, nel Military Ward di Ironforge.",
  progress = "Sono sicura che torni così presto con lo Spotted Yellowtail di cui abbiamo parlato.",
  reward = "Grazie per questo dono, $C, e per giunta così tempestivo. Ai nostri soldati di certo non mancherà da mangiare. Lasciami riporre come si deve questi pesci, e poi, se sei $Gdisposto:disposta;, possiamo parlare di una seconda pescata.",
  en_title = "The Alliance Needs Spotted Yellowtail!",
  en_obj = "Bring 20 Spotted Yellowtail to Huntress Swiftriver at the Military Ward in Ironforge.",
}
T[8529] = {
  title = "L'Alleanza ha bisogno di altro Spotted Yellowtail!",
  desc = "Se sei ancora $Gdisposto:disposta;, vorrei rimandarti là fuori a portare un'altra pescata di Spotted Yellowtail, $N. Immagino che, con l'esperienza che ti sei $Gfatto:fatta; la prima volta, stavolta la pesca sarà molto più rapida e facile. Ci stai?",
  obj = "Porta 20 Spotted Yellowtail a Huntress Swiftriver, all'aerodromo di Dun Morogh.",
  progress = "Se sei ancora $Gdisposto:disposta;, vorrei rimandarti là fuori a portare un'altra pescata di Spotted Yellowtail, $N. Immagino che, con l'esperienza che ti sei $Gfatto:fatta; la prima volta, stavolta la pesca sarà molto più rapida e facile. Ci stai?",
  reward = "Sei un vero membro dell'Alleanza, $N. I tuoi sforzi non passeranno inosservati, né saranno dati per scontati. E grazie anche per aver cucinato il pesce. Farò in modo che venga riposto come si deve, e poi dovrò aggiornare il conto. Ogni pesce ci avvicina un po' di più alla nostra meta.",
  en_title = "The Alliance Needs More Spotted Yellowtail!",
  en_obj = "Bring 20 spotted yellowtail to Huntress Swiftriver at the airfield in Dun Morogh.",
}
T[8530] = {
  title = "L'Alleanza ha bisogno di Singed Corestone!",
  desc = "$C, ho bisogno del tuo aiuto. Nel Molten Core ci sono delle pietre, le Singed Corestone per la precisione, che dobbiamo raccogliere per lo sforzo bellico di Ahn'Qiraj. Mi dicono che i nostri fabbri e ingegneri sapranno farne buon uso, ed è qui che entri in gioco tu. Ho bisogno che tu vada nel Molten Core e raccolga quante più di queste pietre puoi. Naturalmente vorrai portarti dietro trentanove dei tuoi amici più cari.",
  obj = "Porta 50 Singed Corestone a Commander Stronghammer, all'aerodromo di Dun Morogh.",
}
T[8532] = {
  title = "L'Orda ha bisogno di Copper Bar!",
  desc = "Sono davvero contento che tu abbia deciso di dare una mano. Non tutti lo farebbero, quindi devo essere sicuro che tu abbia capito bene cosa mi serve. Copper Bar, non Copper Ore. Non abbiamo né il tempo né la gente per fondere tutto noi, quindi se fossi così gentile da occupartene tu, i tuoi sforzi verranno debitamente annotati. Pensi di farcela, $C?",
  obj = "Porta 20 Copper Bar a Miner Cromwell, nella Valley of Spirits di Orgrimmar.",
  progress = "Spero che quelle che hai con te siano le venti Copper Bar, $C.",
  reward = "Queste barre andranno bene, e grazie per non averle lucidate. Non ha senso farle belle, se poi verranno maltrattate per fabbricare il materiale bellico che serve per la guerra. Le metterò io sulle pile e farò in modo che vengano usate come si deve. Parlami di nuovo se ti interessa portarne altre venti.",
  en_title = "The Horde Needs Copper Bars!",
  en_obj = "Bring 20 Copper Bars to Miner Cromwell at the Valley of Spirits in Orgrimmar.",
}
T[8533] = {
  title = "L'Orda ha bisogno di altre Copper Bar!",
  desc = "Già di ritorno? Diventerai $Gun vero minatore:una vera minatrice; in un attimo, $C. Allora, sai già come funziona: ho bisogno che tu vada là fuori, estragga un bel mucchio di Copper Ore, lo fonda in barre e me le riporti qui. So che sei in grado di farlo; la domanda è: ne hai voglia?",
  obj = "Porta 20 Copper Bar a Miner Cromwell, a Durotar.",
  progress = "Già di ritorno? Diventerai $Gun vero minatore:una vera minatrice; in un attimo, $C. Allora, sai già come funziona: ho bisogno che tu vada là fuori, estragga un bel mucchio di Copper Ore, lo fonda in barre e me le riporti qui. So che sei in grado di farlo; la domanda è: ne hai voglia?",
  reward = "Mi hai dimostrato di nuovo il tuo valore, $C. Farò in modo che questo rame venga usato a suo tempo. Per ora, però, devo mettere queste Copper Bar sul bancale e contarle. Se te la senti ancora, probabilmente mi farebbe comodo il tuo aiuto per raccogliere altre Copper Bar.",
  en_title = "The Horde Needs More Copper Bars!",
  en_obj = "Bring 20 copper bars to Miner Cromwell in Durotar.",
}
T[8542] = {
  title = "L'Orda ha bisogno di Tin Bar!",
  desc = "Lok'tar, $R, sono sicuro che sai già che andremo in guerra ad Ahn'Qiraj contro gli insetti. Ma prima il Capoguerra ha deciso che faremo una cosa chiamata \"prepararsi\". Anche se preferirei affilare armi e martellare armature, sono fiero di essere stato scelto per occuparmi della raccolta di Tin Bar qui. Ma non posso farlo senza il tuo aiuto.$B$BQuindi ho bisogno che tu vada a fare delle Tin Bar e me le riporti qui. Credo che me ne serviranno più di quante ne so contare.",
  obj = "Porta 20 Tin Bar a Grunt Maug, nella Valley of Spirits di Orgrimmar.",
  progress = "Quante Tin Bar hai lì, $C? Dopo la guerra credo che mi servirà qualcuno che mi insegni a contare.",
  reward = "Be', mi pare che questo sia il numero giusto di Tin Bar. Non provare a imbrogliarmi, $C! Contare mi fa male al cranio. Ora io vado a mettere queste barre sulla pila e tu vai là fuori a riportarmene altre uguali.",
  en_title = "The Horde Needs Tin Bars!",
  en_obj = "Bring 20 Tin Bars to Grunt Maug at the Valley of Spirits in Orgrimmar.",
}
T[8543] = {
  title = "L'Orda ha bisogno di altre Tin Bar!",
  desc = "Molto bene, vedo che prendi sul serio la guerra. Però sono un po' nervoso nell'attesa che cominci, il che vuol dire che mi arrabbierò se non inizi a portare la roba più in fretta. Magari potrei esercitarmi su di te, invece.$B$BHar! Forse no, perché poi chi mi riporterebbe le Tin Bar?",
  obj = "Porta 20 Tin Bar a Grunt Maug, a Durotar.",
  progress = "Molto bene, vedo che prendi sul serio la guerra. Però sono un po' nervoso nell'attesa che cominci, e sono sicuro che lo sei anche tu, $C. Sarà gloriosa, quando comincerà. L'Orda che corre sulle sabbie del deserto di Silithus, armi in pugno, e si lancia a capofitto contro le masse di insetti. Quel giorno ci sarà grande onore per tutti!$B$BHar! Ma prima ci servono altre Tin Bar. Buffo come una cosa così piccola possa fare una differenza così grande, non trovi?",
  reward = "Throm'ka, $N. Onori me e l'Orda con le tue Tin Bar. Le metterò sulla pila, e poi verranno a farci delle cose. E quando sarà tutto fatto andremo in guerra e mostreremo a quella misera Alleanza come si combattono gli insetti.$B$BOra riportami altre Tin Bar!",
  en_title = "The Horde Needs More Tin Bars!",
  en_obj = "Bring 20 tin bars to Grunt Maug in Durotar.",
}
T[8545] = {
  title = "L'Orda ha bisogno di Mithril Bar!",
  desc = "$C, la guerra sta arrivando e l'unica cosa che possiamo fare è prepararci. È lì che tu e io possiamo aiutarci a vicenda, $Gamico:amica;. Vedi, mi hanno messo a capo della raccolta di tutte le Mithril Bar che ci servono per costruire tutte le cose di cui avremo bisogno. E me ne servono ancora!$B$BQuindi spero che tu possa andare là fuori a estrarci un po' di mithril e poi fonderlo in barre. Ti sembra una cosa che puoi fare per noi?",
  obj = "Porta 20 Mithril Bar a Senior Sergeant T'kelah, nella Valley of Spirits di Orgrimmar.",
  progress = "Sarebbe proprio bello avere tutte le Mithril Bar che ci servono per lo sforzo bellico di Ahn'Qiraj. È per questo che sei $Gtornato:tornata;, $Gamico:amica;? Hai le mie barre?",
  reward = "Questo è un buon inizio per te e per me, $C. Sono altre venti Mithril Bar che posso mettere sulle pile e spuntare dalla lista. Verrà tutto usato bene per fare il materiale bellico.$B$BAssicurati di ripassare da me, perché mi sa proprio che ci serviranno ancora più Mithril Bar.",
  en_title = "The Horde Needs Mithril Bars!",
  en_obj = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.",
}
T[8546] = {
  title = "L'Orda ha bisogno di altre Mithril Bar!",
  progress = "Già, sono contenta che tu sia qui, $Gamico:amica;. Mi hai aiutato prima, e ora ho di nuovo bisogno del tuo aiuto. Stiamo ancora cercando di raccogliere altre Mithril Bar per lo sforzo bellico; ci faremo un sacco di armature, armi e altre cose per andare a schiacciare quegli insetti ad Ahn'Qiraj.$B$BQuindi, se sei $Gun vero amico:una vera amica;, riportami altre pile di Mithril Bar. Prendo tutte quelle che hai finché non raggiungiamo la quota. Ne hai qualcuna per me adesso?",
  reward = "Bel lavoro, $N! Altre venti barre ci portano un po' più vicino all'obiettivo, e ci danno altro materiale bellico. Mi occupo io di metterle via. E se ti procuri un'altra pila di Mithril Bar, $Gamico:amica;, assicurati di portarla qui da me.",
  en_title = "The Horde Needs More Mithril Bars!",
  en_obj = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.",
}
T[8549] = {
  title = "L'Orda ha bisogno di Peacebloom!",
  desc = "Si dice che ogni generazione debba affrontare una prova decisiva. Temo che la guerra di Ahn'Qiraj sarà il crogiolo in cui verrà messa alla prova la nostra tempra. Così ci prepariamo, e nel farlo scopriamo di che pasta siamo fatti.$B$BMi sono offerta volontaria per aiutare l'Orda raccogliendo più Peacebloom possibile, perché se ne possano fare pozioni per la guerra. Spero che tu sia qui per darmi il tuo aiuto. Se è così, ho bisogno che tu mi riporti una buona quantità di quest'erba. Mi aiuterai, $C?",
  obj = "Porta 20 Peacebloom a Herbalist Proudfeather, nella Valley of Spirits di Orgrimmar.",
  progress = "Già di ritorno con la Peacebloom, $C?",
  reward = "E così i nostri sforzi ci spingono un po' più vicino alla guerra. Grazie per il duro lavoro che hai fatto per raccogliere questa Peacebloom, $C. Ti assicuro che verrà usata bene, e che il tuo contributo è stato annotato, $N. Se te la senti, torna da me con altri di questi fiori. Fino ad allora, che la Madre Terra ti guidi.",
  en_title = "The Horde Needs Peacebloom!",
  en_obj = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.",
}
T[8550] = {
  title = "L'Orda ha bisogno di altra Peacebloom!",
  progress = "Ciao di nuovo, Abyssmal. Sono contenta che tu voglia parlarmi ancora del nostro bisogno senza fine di Peacebloom. Lo sforzo bellico continua, e con esso la nostra produzione di pozioni ed elisir per le battaglie che verranno. Ci aiuterai di nuovo, $C? Mi serve la stessa quantità di Peacebloom di prima, quindi se puoi raccoglierla e riportarmela qui te ne sarò molto grata. Naturalmente, se ce l'hai già con te, sarò più che felice di prenderla subito.",
  reward = "Grazie per il tuo impegno costante, $N. Con la tua generosità disinteressata porti grande onore a te e ai tuoi antenati, e tutti lo sapranno! Metterò via queste erbe perché restino fresche finché non serviranno. Ancora una volta mostri il vero spirito dell'Orda: la lotta per superare le difficoltà e la promessa che possiamo farlo insieme.",
  en_title = "The Horde Needs Peacebloom!",
  en_obj = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.",
}
T[8551] = {
  title = "Il forziere del capitano",
  desc = "Un tempo navigavo da qui fino a Ratchet, in Kalimdor. Ero un capitano di successo, con una reputazione impeccabile.$B$BFinché...$B$BQuei maledetti giganti marini mi hanno rovinato! Mi hanno distrutto la nave, ucciso l'equipaggio e mi hanno messo su una scialuppa diretta a Booty Bay. E uno dei giganti, Gorlash, mi ha rubato il mio forziere del capitano. Ha detto che lo voleva come tabacchiera. Che faccia tosta!$B$BHo sentito che Gorlash si aggira lungo la costa a est di qui. Trovalo e riportami il mio forziere! Fallo, e ti sarai $Gguadagnato:guadagnata; la gratitudine di un capitano.",
  obj = "Porta Smotts' Chest a Hecklebury Smotts, a Booty Bay.",
  progress = "Ahoy, $N! Hai trovato Gorlash? Quel forziere era il mio preferito, e ha uno scomparto segreto dove tenevo i miei tesori più preziosi!",
  reward = "L'hai trovato! Oh, che giorno felice, questo! Grazie, $N. Riavere il mio forziere spegne un po' del fuoco che ho dentro.$B$BMa la mia vendetta non è completa...",
  en_title = "The Captain's Chest",
  en_obj = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.",
}
T[8552] = {
  title = "La Monogrammed Sash",
  desc = "Questa elegante fascia ha le lettere \"HS\" ricamate lungo l'orlo.",
  obj = "Riporta la Monogrammed Sash al suo proprietario.",
  progress = "Salve. Hai affari da trattare con me?",
  reward = "Hai recuperato la mia fascia? Allora... devi aver ucciso Mok'rash, il gigante marino! Evviva!$B$BSono contento che quel lurido farabutto sia morto: Mok'rash era uno dei tre giganti marini che mi hanno distrutto le navi e ucciso l'equipaggio.$B$BTre volte.$B$BSei $Gun:una; $C di valore, $N.",
  en_title = "The Monogrammed Sash",
  en_obj = "Return the Monogrammed Sash to its owner.",
}
T[8553] = {
  title = "La sciabola del capitano",
  desc = "Dopo aver perso la mia prima nave per colpa di quei giganti, ne ho comprata un'altra. L'ho chiamata Smotts' Revenge, l'ho riempita di provviste e di marinai e sono partito alla ricerca di quei farabutti. Li ho trovati, ma... mi hanno battuto. Hanno distrutto la Smotts' Revenge, ucciso il mio secondo equipaggio e mi hanno messo su un'altra scialuppa.$B$BStavolta un altro dei giganti, Negolash, mi ha rubato la sciabola.$B$BAffronta Negolash e riportami la mia sciabola!$B$BParla con Sprogger. Era il mio cuoco sulla Smotts' Revenge, ed è sopravvissuto all'ultimo attacco. Può aiutarti a trovare il gigante.",
  obj = "Parla con Sprogger.",
  reward = "Salve, salve, $N. Il capitano mi ha detto che vuoi dare la caccia a Negolash, eh?",
  en_title = "The Captain's Cutlass",
  en_obj = "Speak with Sprogger.",
}
T[8554] = {
  title = "Affrontare Negolash",
  desc = "Negolash è un gigante affamato.$B$BQuando i giganti hanno distrutto la nostra nave, Negolash è andato dritto nella mia cucina. Non aveva fame di marinai come gli altri giganti. Negolash voleva il vino... e le mie Barbecued Buzzard Wing. Sono la mia specialità, e sono dovuto andare fino alle Badlands per la ricetta!$B$BSe vuoi attirare il gigante, procurati del vino e un mucchio di Buzzard Wing. Mettili nella nostra vecchia scialuppa, a sud-est di qui lungo la costa. Quando Negolash sentirà l'odore di tutto quel cibo, verrà di sicuro!",
  obj = "Porta 10 Barbecued Buzzard Wing e 5 bottiglie di Junglevine Wine a Captain Smotts' Lifeboat.$B$BUccidi Negolash e porta Smotts' Cutlass a Captain Smotts, a Stranglethorn.",
  progress = "Hai recuperato la mia sciabola, $N?",
  reward = "Hai tolto la mia sciabola a Negolash! Non posso credere alla mia fortuna, $N! Incontrarti ha girato la mia sorte in meglio, puoi starne certo!$B$BGrazie! E se mai avrò una nuova nave e vorrai solcare i mari, sarai mio ospite d'onore.",
  en_title = "Facing Negolash",
  en_obj = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.$B$BKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.",
}
T[8580] = {
  title = "L'Orda ha bisogno di Firebloom!",
  desc = "Ehi, $C. Sì, proprio tu, $Gamico:amica;! L'Orda pensa che le serva un bel mucchio di Firebloom per questo sforzo bellico di Ahn'Qiraj. Magari la mettono in belle cose che fanno bum? Magari la danno all'Alleanza come combustibile per i suoi carri a vapore? Chi lo sa? Non Pele'keiki!$B$BPerò Pele'keiki sa questo... sa che tu lo aiuterai e gli riporterai tanta Firebloom, vero, $Gamico:amica;?",
  obj = "Porta 20 Firebloom a Batrider Pele'keiki, nella Valley of Spirits di Orgrimmar.",
  progress = "Non vuoi far arrabbiare Pele'keiki. Rendi felice Pele'keiki portandogli tanta Firebloom, e alla svelta.",
  reward = "$C! Pele'keiki è felice, per ora. Pele'keiki prende tutta questa Firebloom e la mette in una cassa, così resta fresca. Pele'keiki si assicura che tutta la Firebloom diventi roba buona per la guerra. E se ne trovi ancora, vieni subito da Pele'keiki. Probabilmente a Pele'keiki ne servirà altra.",
  en_title = "The Horde Needs Firebloom!",
  en_obj = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.",
}
T[8581] = {
  title = "L'Orda ha bisogno di altra Firebloom!",
  progress = "Pele'keiki sa che sei qui per aiutare. Porta tanta Firebloom e lo renderai molto felice. Pele'keiki potrebbe fare grosse bombe con la Firebloom. E sganciarle sugli insetti dal suo pipistrello sopra Ahn'Qiraj, quando arriverà la guerra. Ma a Pele'keiki serve altra Firebloom, $C!$B$BPorterai quella Firebloom a Pele'keiki, e alla svelta. Torna con almeno la stessa quantità dell'ultima volta, e Pele'keiki sarà contento.",
  reward = "Non è uno scherzo, $C? Porti a Pele'keiki la Firebloom così in fretta? Pele'keiki la conta subito, $Gamico:amica;! Stai rendendo Pele'keiki così felice che dirà a tutti che $N è $Gil miglior raccoglitore:la miglior raccoglitrice; di Firebloom di sempre! Pele'keiki non vede l'ora che cominci la guerra. Adesso sì che illumineremo il cielo sopra Silithus, vero, $Gfratello:sorella;?!",
  en_title = "The Horde Needs More Firebloom!",
  en_obj = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.",
}
T[8582] = {
  title = "L'Orda ha bisogno di Purple Lotus!",
  desc = "Il Purple Lotus, $C, è un reagente di moltissime pozioni, elisir e oli, alcuni dei quali ci saranno utili ad Ahn'Qiraj. Dovremo preparare un numero enorme di queste pozioni per lo sforzo bellico. E farò anche degli esperimenti per trovare altri usi per il loto. Ma per fare tutto questo mi servirà una grande quantità di questo fiore.$B$BEd è qui che entri in gioco tu. Va' sul campo e raccogli quanti più Purple Lotus puoi. È una cosa che sei $Gdisposto:disposta; a fare per noi?",
  obj = "Porta 20 Purple Lotus ad Apothecary Jezel, nella Valley of Spirits di Orgrimmar.",
  progress = "Già di ritorno con il Purple Lotus che ti ho chiesto, $C? È fondamentale che tu lo faccia il più tempestivamente possibile, se non vuoi che tutto ciò che sto tentando qui finisca nel nulla.",
  reward = "Uno sforzo encomiabile, $C. Misurerò questi campioni per stabilirne l'uso più adatto e annoterò il tuo contributo. Poi il Purple Lotus andrà conservato come si deve finché non sarò pronta a usarlo. Quanto a te, se sei ancora disponibile, immagino che mi servirà altro Purple Lotus. Ripassa da me tra un momento.",
  en_title = "The Horde Needs Purple Lotus!",
  en_obj = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.",
}
T[8583] = {
  title = "L'Orda ha bisogno di altro Purple Lotus!",
  progress = "In effetti pare proprio che ci serva ancora altro Purple Lotus, $C. Anche se i miei studi non hanno ancora individuato un nuovo impiego utile per quest'erba, ci sono metodi collaudati ancora da applicare.$B$BHo bisogno che tu vada di nuovo sul campo a raccogliere almeno venti campioni di Purple Lotus. Riportali qui da me.",
  reward = "Un lavoro eccellente e preciso, $N. La tua diligenza merita un encomio, e così la tua rapidità. Mi assicurerò di persona che nessuno di questi Purple Lotus vada sprecato.$B$BGrazie ancora, e se ti capita di trovare altro Purple Lotus, non esitare a portarmelo con la massima urgenza.",
  en_title = "The Horde Needs More Purple Lotus!",
  en_obj = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.",
}
T[8588] = {
  title = "L'Orda ha bisogno di Heavy Leather!",
  desc = "Visto che ci stiamo preparando alla guerra, forse è meglio procurarci prima tutta la roba che ci serve, non credi, $Gamico:amica;? Uno dei materiali base per il materiale bellico che produciamo è l'Heavy Leather. Lo useremo praticamente per tutto, dai rinforzi alle armature, fino ai buoni vecchi teloni.$B$BMa prima dobbiamo metterci le mani sopra. Questo è compito tuo, $C. Affila il coltello e riportamene un fascio. Poi ne parleremo ancora.",
  obj = "Porta 10 Heavy Leather a Skinner Jamani, nella Valley of Spirits di Orgrimmar.",
  progress = "Non ho tempo per i giochi, se sei qui solo per chiacchierare, $C. Ci sono troppe pile di Heavy Leather da conciare. Torna quando ne avrai almeno dieci per me.",
  reward = "Oh, allora ce l'hai davvero l'Heavy Leather che mi serviva. La tua lama è proprio affilata, $C: queste sono belle pelli! Ora che siamo partiti con il piede giusto, farò in modo che il tuo contributo venga usato bene. E se ti capita di trovare altro Heavy Leather, portalo da me.",
  en_title = "The Horde Needs Heavy Leather!",
  en_obj = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.",
}
T[8589] = {
  title = "L'Orda ha bisogno di altro Heavy Leather!",
  progress = "È vero, $C, mi serve ancora altro Heavy Leather. Le richieste dei generali e dei loro furieri sembrano non finire mai. E non è niente in confronto a quello che chiedono i maestri degli zeppelin!$B$BDevo raccogliere la mia quota al più presto. $N, portami altre pile di Heavy Leather il prima possibile!",
  reward = "Sei $Gil migliore:la migliore;, $Gamico:amica;! Grazie mille per l'Heavy Leather. Ogni piccola parte ci avvicina un po' di più. Lo metto subito in pila, così gli altri conciatori possono metterci mano.$B$BGrazie ancora, $N, e se trovi altre pile di Heavy Leather, sai dove trovarmi.",
  en_title = "The Horde Needs More Heavy Leather!",
  en_obj = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.",
}
T[8590] = {
  title = "L'Orda ha bisogno di Thick Leather!",
  desc = "Sono contenta che tu abbia deciso di parlarmi di questa faccenda, $C. Pare che i preparativi dell'Orda per la guerra di Ahn'Qiraj siano in pieno svolgimento. Ma tu e io dobbiamo ancora fare la nostra parte.$B$BMi hanno chiesto di raccogliere una gran quantità di pelli di Thick Leather da usare per ogni genere di materiale bellico, e ho bisogno che tu mi aiuti andando là fuori a raccoglierle. Se deciderai di aiutarmi, ne avrai onore e la gratitudine dell'Orda. Lo farai?",
  obj = "Porta 10 Thick Leather a Sergeant Umala, nella Valley of Spirits di Orgrimmar.",
  progress = "$C, sei già $Gtornato:tornata; con i dieci Thick Leather di cui avevamo parlato?",
  reward = "Bel lavoro, $C. Sono sicura che queste pelli di Thick Leather serviranno a rinforzare gli zeppelin e a fare ogni genere di armature e armi. Ti ringrazio, a nome mio e dell'Orda. Torna ancora se nei tuoi viaggi trovi altro Thick Leather, e che la fortuna sia con te.",
  en_title = "The Horde Needs Thick Leather!",
  en_obj = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.",
}
T[8591] = {
  title = "L'Orda ha bisogno di altro Thick Leather!",
  progress = "$C, come vedi devo ancora raccogliere altro Thick Leather. Ancora una volta ti chiedo aiuto in questo compito, e ti prometto che, se lo porterai a termine, i tuoi sforzi saranno riconosciuti.$B$BIl tempo stringe! Torna da me con il Thick Leather, così potremo finire i preparativi e andare in guerra, $Geroe:eroina;!",
  reward = "Ce l'hai fatta, $N, lo sapevo! Ancora una volta, grazie a nome di tutta l'Orda. I tuoi sforzi sono stati annotati e sono molto apprezzati. E se ti ritrovi con altro Thick Leather da donare, portalo qui da me.$B$BLok'tar Ogar, $C!",
  en_title = "The Horde Needs More Thick Leather!",
  en_obj = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.",
}
T[8600] = {
  title = "L'Orda ha bisogno di Rugged Leather!",
  desc = "Trovo che il modo in cui il coltello si adatta al palmo conti più del suo filo. Anche la lama più smussata può tagliare, se la pressione viene applicata nel modo giusto, non credi, $C? Ma tu e io non abbiamo di questi problemi, visto che teniamo le lame più affilate, vero?$B$BBe', non importa, ho un compito per te. Al servizio dell'Orda, e per fare la tua parte nello sforzo bellico di Ahn'Qiraj, voglio che tu torni da me con un certo numero di pelli di Rugged Leather. È una cosa che farai, no?",
  obj = "Porta 10 Rugged Leather a Doctor Serratus, nella Valley of Spirits di Orgrimmar.",
  progress = "Non è possibile che ti ci voglia tanto per tagliarmi dieci Rugged Leather! Forse dovresti affilare il coltello da scuoiatura? O forse mi sbaglio e ce le hai lì nello zaino?",
  reward = "Molto bene, pare che tu abbia fatto un lavoro abbastanza decente, anche se alcune di quelle pelli sono un po' sfilacciate ai bordi. Non importa, il compito è fatto, e ti sei $Gguadagnato:guadagnata; la ricompensa. Se ti capita di trovare un'altra pila di Rugged Leather, portamela senza indugio.",
  en_title = "The Horde Needs Rugged Leather!",
  en_obj = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.",
}
T[8601] = {
  title = "L'Orda ha bisogno di altro Rugged Leather!",
  progress = "I preparativi per l'imminente guerra ad Ahn'Qiraj procedono, $C. Tuttavia, per essere sicuri di non restare indietro, o almeno per non essere io quello che ci fa restare indietro, voglio che tu mi riporti un'altra pila di Rugged Leather. Apprezzerò molto la tua sollecitudine in questa faccenda, $N.",
  reward = "Esercizio, esercizio, esercizio. Un coltello ben affilato e l'abilità di usarlo ti porteranno lontano in questo mondo, $N. Mi sembra che i bordi di queste pelli siano migliori di quelle dell'ultima volta. Ti sei $Gcomprato:comprata; un coltello nuovo?$B$BIn ogni caso, ti ringraziamo per i tuoi sforzi. La tua donazione è stata annotata, e ti assicuro che verrà usata bene. Se ti ritrovi con altro Rugged Leather, torna pure a parlarmi, perché probabilmente mi servirà.",
  en_title = "The Horde Needs More Rugged Leather!",
  en_obj = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.",
}
T[8604] = {
  title = "L'Orda ha bisogno di Wool Bandage!",
  desc = "Salve, $C. In vista della guerra ad Ahn'Qiraj, sono qui a coordinare gli sforzi dell'Orda per raccogliere Wool Bandage. Purtroppo, sul campo, i nostri soldati non possono contare sulla presenza di un guaritore che li tenga in vita. Credimi, lo so per esperienza. Per questo stiamo preparando per loro tutte queste cassette di pronto soccorso.$B$BSe hai tempo, mi servono molte Wool Bandage. Riportamele qui e farò in modo che tu venga $Gricompensato:ricompensata; come si deve.",
  obj = "Porta 20 Wool Bandage a Healer Longrunner, nella Valley of Spirits di Orgrimmar.",
  progress = "Ah, $C, sei già $Gtornato:tornata; con le Wool Bandage?",
  reward = "Ti ringrazio, a nome mio e dell'Orda, $C. Se trovi altre Wool Bandage e vuoi contribuire ancora allo sforzo bellico, portamele qui. Fino ad allora, che i tuoi antenati veglino su di te!",
  en_title = "The Horde Needs Wool Bandages!",
  en_obj = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.",
}
T[8605] = {
  title = "L'Orda ha bisogno di altre Wool Bandage!",
  progress = "Che piacere rivederti, $C. Stiamo ancora lavorando ai preparativi per lo sforzo bellico, e mi fa ancora comodo tutto l'aiuto che puoi darmi per raccogliere bende di lana. Qualsiasi aiuto sarà molto apprezzato. Spero solo che i nostri sforzi bastino. Ho perso troppe anime nobili sui campi di battaglia del passato per non fare tutto quello che posso perché non succeda di nuovo.",
  reward = "Sei $Gun:una; $C d'onore, $N! Farò in modo che queste bende arrivino nelle mani giuste. Ti ringrazio, a nome mio e dell'Orda.$B$BVa' in pace, e torna da me se ti ritrovi con bende di lana in più. Qui ci serve tutto l'aiuto possibile.",
  en_title = "The Horde Needs More Wool Bandages!",
  en_obj = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.",
}
T[8607] = {
  title = "L'Orda ha bisogno di Mageweave Bandage!",
  desc = "Confido che tu mi stia parlando perché intendi aiutarmi con la raccolta che mi è stata affidata? Bene! Con qualunque mezzo, e intendo davvero qualunque, desidero che tu raccolga un buon numero di Mageweave Bandage. Fresche sarebbe meglio, ma non è indispensabile. Riportamele qui, $C, e mi assicurerò di persona che tu venga $Gricompensato:ricompensata; come si deve.",
  obj = "Porta 20 Mageweave Bandage a Lady Callow, nella Valley of Spirits di Orgrimmar.",
  progress = "Non fallire e non farmi fare brutta figura, $C! Torna qui il prima possibile con le Mageweave Bandage di cui abbiamo parlato.",
  reward = "Sorprendente, eppure accettabile. Forse ho sottovalutato le tue \"capacità\", $C. Forse. Hai portato a termine un compito molto semplice, e per questo verrai $Gricompensato:ricompensata; in modo sproporzionato. Ma non montarti la testa. Se vuoi davvero dimostrare il tuo valore, dovresti andare là fuori e portarmi un altro fascio di Mageweave Bandage.",
  en_title = "The Horde Needs Mageweave Bandages!",
  en_obj = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.",
}
T[8608] = {
  title = "L'Orda ha bisogno di altre Mageweave Bandage!",
  progress = "Sei $Gtornato:tornata;? Interessante. Come vedi, sto ancora raccogliendo per lo \"sforzo bellico\" di Ahn'Qiraj. Il che significa che ho bisogno che tu vada di nuovo a raccogliere una pila di Mageweave Bandage per me. Attendo il tuo ritorno, $C.",
  reward = "Stupefacente, $C, ce l'hai fatta davvero di nuovo! Be', dicono che ho buon gusto nello scegliere chi mettere al mio servizio. Molto bene, il tuo contributo è stato annotato e riceverai i vantaggi sociali che i tuoi sforzi ti hanno procurato. Ti suggerisco però di tornare là fuori a raccogliere un altro fascio ancora di Mageweave Bandage, se vuoi davvero dimostrare quanto vali.",
  en_title = "The Horde Needs More Mageweave Bandages!",
  en_obj = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.",
}
T[8609] = {
  title = "L'Orda ha bisogno di Runecloth Bandage!",
  desc = "Pare inevitabile che l'Orda e l'Alleanza siano in rotta verso la guerra ad Ahn'Qiraj. Sorprendentemente, non è una guerra tra loro, ma contro i silitidi e qualunque forza li controlli. E, sorprendentemente anche questo, entrambi gli schieramenti stanno facendo la loro parte per raccogliere le risorse necessarie a combattere una guerra vittoriosa.$B$BRaccolgo Runecloth Bandage da distribuire ai soldati, ma senza aiuto non ci riuscirò, e spero che sia il tuo. Puoi aiutarmi in questo, $C?",
  obj = "Porta 20 Runecloth Bandage a Stoneguard Clayhoof, nella Valley of Spirits di Orgrimmar.",
  progress = "La guerra arriverà presto, credo, $C. Ti ringrazio per il tempo e l'impegno che dedichi ad aiutarci nelle raccolte. Sei $Gtornato:tornata; perché hai trovato le Runecloth Bandage di cui abbiamo parlato?",
  reward = "Fai onore all'Orda, $C. Grazie per i tuoi sforzi: sono apprezzati! Dovrò mettere via queste bende fresche e rifare il conto per vedere quanto siamo vicini al nostro obiettivo. Se vuoi, puoi raccogliere altre Runecloth Bandage e riportarmele qui.",
  en_title = "The Horde Needs Runecloth Bandages!",
  en_obj = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.",
}
T[8610] = {
  title = "L'Orda ha bisogno di altre Runecloth Bandage!",
  progress = "Si avvicina sempre di più il momento in cui ci getteremo a capofitto nella conflagrazione di Ahn'Qiraj, $Gsacerdote:sacerdotessa;. Ma prima dobbiamo raccogliere le forze e prepararci, per poter sopravvivere all'assalto degli insetti e dei loro padroni.$B$BSe sei di nuovo qui, di certo vuoi fare un'altra donazione di Runecloth Bandage allo sforzo bellico? Ti prego, fallo appena puoi e torna ancora da me.",
  reward = "Il tuo è un gesto di generosità davvero disinteressato, $N. Un gesto che probabilmente salverà la vita a molti combattenti ad Ahn'Qiraj. Grazie, e sappi che l'Orda ti è grata per la tua donazione. Se prepari, o trovi, altre Runecloth Bandage, ti prego, pensa a portarmele qui.",
  en_title = "The Horde Needs More Runecloth Bandages!",
  en_obj = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.",
}
T[8611] = {
  title = "L'Orda ha bisogno di Lean Wolf Steak!",
  desc = "Non sto qui solo per prendere un po' di sole, $C. Ci sono dei preparativi di guerra da fare. Se vogliamo schiacciare quegli insetti ad Ahn'Qiraj, dobbiamo essere pronti, e questo vale anche per il cibo!$B$BMi hanno messo qui a raccogliere e salare Lean Wolf Steak per la guerra in arrivo. Ma visto che devo restare qui a occuparmi di tutto questo, ho bisogno che tu vada là fuori, uccida qualche lupo, cucini la carne per farne Lean Wolf Steak e me le riporti qui. Tutto chiaro?",
  obj = "Porta 20 Lean Wolf Steak a Bloodguard Rawtar, nella Valley of Spirits di Orgrimmar.",
  progress = "Già di ritorno con quelle Lean Wolf Steak, $C? Non m'importa se sono troppo cotte o crude, basta che siano saporite e che me le porti in fretta!",
  reward = "Ok, questa pila di carne mi sembra buona. Le salerò, poi le metterò via, e speriamo che restino abbastanza fresche da essere mangiabili quando sarà il momento.$B$BGrazie per il contributo, $C. Pensi di potermene portare un'altra infornata?",
  en_title = "The Horde Needs Lean Wolf Steaks!",
  en_obj = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.",
}
T[8612] = {
  title = "L'Orda ha bisogno di altre Lean Wolf Steak!",
  progress = "Come vedi, $C, dobbiamo ancora mettere via altro cibo per i soldati. Non so se tu sia mai $Gstato:stata; in guerra, ma una volta superato lo shock iniziale del campo di battaglia, può venire una gran fame. L'ultima volta hai fatto un buon lavoro, quindi mi aspetto che farai altrettanto bene, se non un po' più in fretta, portandomi un'altra pila di quelle Lean Wolf Steak.",
  reward = "Dall'odore, tu, o qualcuno che conosci, ci sai proprio fare ai fornelli, $N. Queste Lean Wolf Steak mi fanno venire l'acquolina in bocca; immagino che se ne sparisce qualcuna nessuno se ne accorgerà. Comunque, bel lavoro. Farò in modo che qualcuno le metta via come si deve, così non si guasteranno troppo.$B$BSe ne trovi altre, sai dove trovarmi.",
  en_title = "The Horde Needs More Lean Wolf Steaks!",
  en_obj = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.",
}
T[8613] = {
  title = "L'Orda ha bisogno di Spotted Yellowtail!",
  desc = "È una bella giornata per pescare, non credi, $Gamico:amica;? Meno male, perché pare che mi serva un sacco di pesce. L'Orda mi ha chiesto di occuparmi di raccogliere una montagna di Spotted Yellowtail. Dicono che gli serve per la guerra che stanno preparando ad Ahn'Qiraj. Io gli ho detto che faccio del mio meglio. Quindi mi serve un po' d'aiuto. Mi aiuti tu, $C?",
  obj = "Porta 20 Spotted Yellowtail a Fisherman Lin'do, nella Valley of Spirits di Orgrimmar.",
  progress = "Già di ritorno con lo Spotted Yellowtail, $C? Ti sei $Gricordato:ricordata; di cucinarlo per bene? Il pesce crudo ai soldati sotto il sole caldo del deserto non lo serviamo di sicuro.",
  reward = "Oh sì, questa è roba buona. Lo impacchetto per bene, così non va sprecato. Grazie a te per avermi aiutato così. Secondo me sei $Gun pescatore:una pescatrice; di prima classe, con tutto questo Spotted Yellowtail. E se ti capita di pescarne e cucinarne ancora, portalo qui da me: farò sapere a tutti che sei $Gstato:stata; tu!",
  en_title = "The Horde Needs Spotted Yellowtail!",
  en_obj = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.",
}
T[8614] = {
  title = "L'Orda ha bisogno di altro Spotted Yellowtail!",
  progress = "Come vedi, ci servono ancora un sacco di pescetti. I combattenti della guerra di Ahn'Qiraj in arrivo avranno bisogno di tanto da mangiare, quindi devo procurarmi tutto lo Spotted Yellowtail possibile. Tu li peschi, li cucini e me li riporti qui, e io ti ringrazio, e con me ti ringrazia l'Orda.",
  reward = "È la pescata migliore finora, $N! Un lavoro buono e onesto. E senza nemmeno una lisca! Grazie per questo Spotted Yellowtail, $Gamico:amica;. Torna presto, se ne cucini ancora!",
  en_title = "The Horde Needs More Spotted Yellowtail!",
  en_obj = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.",
}
T[8615] = {
  title = "L'Orda ha bisogno di Baked Salmon!",
  desc = "Lo sforzo bellico di Ahn'Qiraj è un'impresa immensa, $C. Tutti i materiali che si raccolgono qui, che siano metallo per le armi o cibo da mangiare, sono importanti allo stesso modo. Perché, se non mangi da giorni, non avrai la forza di sollevare l'ascia quando conta.$B$BPer questo raccogliamo tutto il cibo che possiamo. Io raccolgo Baked Salmon, un piatto scelto perché è nutriente e perché si conserva bene. Puoi aiutarmi in questo compito, $C?",
  obj = "Porta 20 Baked Salmon a Chief Sharpclaw, nella Valley of Spirits di Orgrimmar.",
  progress = "Gli Sprite Darter possono essere bestiole pericolose, se provocati. Sta' $Gattento:attenta; quando hai a che fare con loro, $C. E fa' ancora più attenzione agli elfi della notte della zona. Quegli sciocchi fastidiosi tendono a rintanarsi anche loro nelle foreste.$B$BQuando avrai abbastanza ali, fammelo sapere: ti ricompenserò bene, puoi starne certo!",
  reward = "Magnifico, $C! Queste andranno benissimo. Ce n'è abbastanza per fare un mantello per Korrin, e forse anche di più! Grazie.$B$BSpero che il viaggio non sia stato troppo pericoloso? La zona di Feralas non è nota per essere clemente, ma è chiaro che te la sei $Gcavato:cavata; bene.$B$BGrazie ancora, $C.",
  en_title = "The Horde Needs Baked Salmon!",
  en_obj = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.",
}
T[8616] = {
  title = "L'Orda ha bisogno di altro Baked Salmon!",
  progress = "L'ultima partita di Baked Salmon che hai donato allo sforzo bellico aveva un aspetto davvero delizioso, $C. Devo ammettere che sono stato tentato di prenderne un po' per me. Come vedi, non abbiamo ancora raggiunto la nostra quota. Spero che tu sia $Gtornato:tornata; perché hai con te un'altra pila di Baked Salmon.",
  reward = "Il tempo e l'energia che doni allo sforzo bellico vanno ben oltre il dovuto, $N. Ti assicuro che le tue fatiche non sono passate inosservate. Ti ringrazio, a nome mio e dell'Orda. Torna ancora da me se ne cucini un'altra partita.",
  en_title = "The Horde Needs More Baked Salmon!",
  en_obj = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.",
}
T[8617] = {
  title = "L'Orda ha bisogno di Singed Corestone!",
  desc = "È arrivato il momento che tu contribuisca allo sforzo bellico di Ahn'Qiraj, $C. Sono finiti i giorni sereni passati a oziare. Ora è il momento di servire me e l'Orda, e ti assicuro che non sono indulgente quanto il Capoguerra.$B$BRadunerai le tue forze, una gilda se ne hai una, e invaderai il Molten Core. Lì dentro scoprirai che chi lo abita ha delle Singed Corestone. Riportamele in grandi quantità.",
  obj = "Porta 50 Singed Corestone a General Zog, a Durotar.",
}
T[8619] = {
  title = "Morndeep the Elder",
  reward = "È bello sapere che la gente di queste terre rende ancora omaggio alle razze antiche. Ti auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Morndeep the Elder",
}
T[8635] = {
  title = "Splitrock the Elder",
  reward = "Le battaglie delle ere passate sono semi da cui crescono le leggende. La tua è un'epoca di eroi, giovane. Che la tua leggenda metta radici e prosperi.$B$BTi auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Splitrock the Elder",
}
T[8636] = {
  title = "Rumblerock the Elder",
  reward = "Ciò che appartiene alla vita è destinato a morire e a tornare alla terra, ma ciò che appartiene allo spirito vive in eterno. Ti auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Rumblerock the Elder",
}
