T[8734] = {
  title = "Tyrande e Remulos",
  desc = "Tyrande sarà avvisata, mortale. Shan'do Stormrage mi ha preparato per questa evenienza.$B$BOra devi andare nel Moonglade a parlare con Remulos. Ti darà altre istruzioni per l'evocazione di Eranikus.$B$BTi auguriamo tutti buona fortuna.",
  obj = "Raggiungi il Moonglade e parla con Keeper Remulos.",
  reward = "Sarebbe impossibile strappare Eranikus al Sogno, se si rifiutasse. Però le sue intenzioni lo obbligano a entrare nel nostro mondo. Cerca di distruggere la manifestazione vivente di Malfurion. Se ci riuscisse, sarebbe la fine di uno dei più potenti alleati del Sogno. Se Malfurion cadesse, l'Incubo consumerebbe completamente tutto ciò che resterebbe...",
  en_title = "Tyrande and Remulos",
  en_obj = "Travel to the Moonglade and speak to Keeper Remulos. ",
}
T[8744] = {
  title = "Un regalo incartato con cura",
  reward = "Sul biglietto di questo regalo c'è scritto:$B$BPer $N,$B$Bche la tua Vigilia di Grande Inverno sia allegra e luminosa!",
  en_title = "A Carefully Wrapped Present",
}
T[8767] = {
  title = "Un regalo scosso delicatamente",
  reward = "Sembra che questo regalo sia stato scosso un paio di volte. Sul biglietto c'è scritto:$B$BPer $Gun:una; $R $C davvero speciale.",
  en_title = "A Gently Shaken Gift",
}
T[8768] = {
  title = "Un regalo incartato allegramente",
  reward = "Questo regalo dalla carta festosa ha sopra il tuo nome.$B$BAspetta, si è appena mosso?",
  en_title = "A Gaily Wrapped Present",
}
T[8788] = {
  title = "Un regalo scosso delicatamente",
  reward = "Sembra che questo regalo sia stato scosso un paio di volte. Sul biglietto c'è scritto:$B$BPer $Gun:una; $R $C davvero speciale.",
  en_title = "A Gently Shaken Gift",
}
T[8792] = {
  title = "L'Orda ha bisogno del tuo aiuto!",
  desc = "Ciao, sono $Gcontento:contenta; che tu abbia deciso di ascoltarmi. L'Orda ha bisogno di tutto l'aiuto possibile per prepararsi alla guerra di Ahn'Qiraj, e questo vuol dire che abbiamo bisogno di te! Proprio mentre parliamo, i raccoglitori ufficiali stanno radunando il materiale necessario per la guerra in arrivo, ma senza il tuo aiuto non riusciremo a raggiungere i nostri obiettivi, $N!$B$BDovresti andare a parlare con chi comanda, Warlord Gorchuk. Che ne dici, $C? Darai una mano con i preparativi indispensabili?",
  obj = "Parla con Warlord Gorchuk nella Valley of Spirits di Orgrimmar.",
  reward = "Throm'ka, $C! È bello vedere così tanti membri dell'Orda, come te, $N, venire a dare il loro sostegno per gettare le basi della guerra di Ahn'Qiraj in arrivo. Lo sforzo che facciamo qui ci garantirà la vittoria contro i silitidi e i loro malvagi padroni nascosti dentro Ahn'Qiraj.$B$BAllora, ora che sei qui, assicurati di parlare con i vari raccoglitori e di offrire il tuo aiuto per raccogliere i materiali più adatti a te.",
  en_title = "The Horde Needs Your Help!",
  en_obj = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
}
T[8793] = {
  title = "L'Orda ha bisogno del tuo aiuto!",
  desc = "Ciao, sono $Gcontento:contenta; che tu abbia deciso di ascoltarmi. L'Orda ha bisogno di tutto l'aiuto possibile per prepararsi alla guerra di Ahn'Qiraj, e questo vuol dire che abbiamo bisogno di te! Proprio mentre parliamo, i raccoglitori ufficiali stanno radunando il materiale necessario per la guerra in arrivo, ma senza il tuo aiuto non riusciremo a raggiungere i nostri obiettivi, $N!$B$BDovresti andare a parlare con chi comanda, Warlord Gorchuk. Che ne dici, $C? Darai una mano con i preparativi indispensabili?",
