T[8803] = {
  title = "Un regalo di festa",
  reward = "Sul biglietto di questo regalo c'è scritto:$B$BPer $N,$B$Bcon la speranza che ti aiuti a portare calorosi auguri e allegria festiva a tutta Azeroth.$B$BDa Greatfather Winter",
  en_title = "A Festive Gift",
}
T[8811] = {
  title = "Un Commendation Signet",
  progress = "Se un avventuriero ha un solo Commendation Signet, glielo cambio con un piccolo riconoscimento da parte di Darnassus.$B$BTieni presente che è meglio consegnare una pila di dieci sigilli tutti insieme: così i tuoi sforzi riceveranno un riconoscimento maggiore. Offriamo il cambio di un singolo sigillo come servizio per chi non ne ha abbastanza per una pila completa da dieci.$B$BDetto questo, sono a tua disposizione se vuoi comunque consegnare un solo sigillo.",
  reward = "Molto bene: le tue gesta sono state messe agli atti, e i tuoi sforzi ti vengono debitamente riconosciuti. Continua così, $C.$B$BSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.",
  en_title = "One Commendation Signet",
}
