T[8827] = {
  title = "I regali dell'inverno",
  desc = "Ho sentito che Greatfather Winter, con il generoso sostegno della Smokeywood Pastures, ha messo dei regali per tutti sotto l'albero a Ironforge. Vorrei tanto andarci, ma devo tenere d'occhio il PX-238 Winter Wondervolt.$B$BMa tu dovresti proprio andare a vedere. Sono sicuro che Greatfather Winter ha dei regali con sopra il tuo nome.",
  obj = "Parla con Greatfather Winter. Si trova vicino ai banchi della Smokywood Pastures, a Ironforge.",
  reward = "Oh, oh, salve! Puoi essere qui per un solo motivo: aprire i tuoi regali della Vigilia di Grande Inverno.$B$BOra, non preoccuparti: Greatfather Winter non si è dimenticato $Gdel suo:della sua; $R $C $Gpreferito:preferita;. Guarda sotto l'albero e troverai i tuoi regali.$B$BIn questo periodo di doni, magari anche ai tuoi amici farebbe piacere ricevere qualcuno degli ottimi prodotti della Smokeywood Pasture?",
  en_title = "Winter's Presents",
  en_obj = "Speak with Greatfather Winter. He is located near the Smokywood Pastures vendor area in Ironforge.",
}
