T[8860] = {
  title = "Festeggiamenti per il New Year!",
  desc = "Stormwind organizza una festa per il nuovo anno! Per tutta la giornata di oggi puoi avere da bere gratis, e stanotte faranno uno spettacolo di fuochi d'artificio! Dovrebbe essere piuttosto bello... ma anche Booty Bay oggi fa una festa; scommetto che sarà ancora meglio!$B$BComunque, a Innkeeper Allison, a Stormwind, serve una scorta di cibo della Smoky Wood Pasture per sfamare tutti i festaioli. Mi fai il favore di consegnargliela?$B$BGrazie, $N! Innkeeper Allison è al Gilded Rose, nel Trade District di Stormwind.",
  obj = "Porta le Smokywood Supplies a Innkeeper Allison, a Stormwind.",
  progress = "Salve! Sei qui per la festa? O forse devi solo far riposare quei tuoi piedi stanchi...",
  reward = "Oh, le mie provviste della Smokywood! Splendido! Mi serviranno per sfamare tutta la gente in città per la festa!$B$BGrazie, $N. Prendi questo come pagamento, e non dimenticare di bere e ballare con i festaioli qui fuori!",
  en_title = "New Year Celebrations!",
  en_obj = "Bring the Smokywood Supplies to Innkeeper Allison in Stormwind.",
}
T[8861] = {
  title = "Festeggiamenti per il New Year!",
  desc = "Thunder Bluff organizza una festa per il nuovo anno! Per tutto il giorno lì troverai da bere gratis, e stanotte faranno uno spettacolo di fuochi d'artificio!$B$BDovrebbe essere piuttosto bello... ma anche Booty Bay oggi fa una festa; scommetto che sarà ancora meglio!$B$BComunque, a Innkeeper Pala, a Thunder Bluff, serve una scorta di cibo della Smoky Wood Pasture per sfamare tutti i festaioli. Mi fai il favore di consegnargliela?$B$BGrazie, $N! Innkeeper Pala è nella locanda vicino al ponte per l'Hunter's Rise.",
  obj = "Porta le Smokywood Supplies a Innkeeper Pala, a Thunder Bluff.",
  progress = "Buongiorno, $C! Sei $Gvenuto:venuta; a Thunder Bluff per i nostri festeggiamenti? O sei qui per far riposare uno zoccolo stanco tra una caccia e l'altra?",
  reward = "Oh, molto bene! Queste provviste aiuteranno a sfamare tutta la nostra gente, qui per festeggiare il nuovo anno!$B$BTi ringrazio, $N. Sei in debito con me. Ti prego, prendi queste monete... e segui il mio consiglio: bevi a volontà dai barili qui fuori, e unisciti ai festaioli in una danza di festa!",
  en_title = "New Year Celebrations!",
  en_obj = "Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff.",
}
T[8862] = {
  title = "Elune's Candle",
  progress = "Elune's Candle è un manufatto molto venerato dai discepoli della Celebrazione della Luna. Nella candela è racchiusa la vera luce lunare, pronta a essere liberata!$B$BQuesta luce è innocua per la maggior parte delle creature, ma scoprirai che Omen e i suoi servitori ne vengono bruciati e abbagliati.",
  reward = "Molto bene, allora: accetto questi Coin of Ancestry. Prendi Elune's Candle, con la mia benedizione. E goditi anche questi fuochi d'artificio in omaggio.$B$BChe la tua Celebrazione della Luna sia gioiosa e piena di allegria, $N.$B$BE se sceglierai di affrontare Omen e i suoi servitori, vedrai che Elune's Candle ti sarà molto utile...",
  en_title = "Elune's Candle",
}
T[8863] = {
  title = "Festival Dumplings",
  progress = "Se hai fame, sei $Gcapitato:capitata; nel posto giusto, $Gamico mio:amica mia;!$B$BI ravioli sono il cibo tradizionale della Celebrazione della Luna: si servono fin dai tempi della prima Celebrazione della Luna, e mi fa piacere poterli offrire anche in questa. In cambio di un solo Coin of Ancestry, ti farò assaggiare uno dei piatti più gustosi che ti capiterà mai di provare!",
  reward = "Eccellente: goditi questi ravioli, offerti da me. Sono solo un piccolo segno di apprezzamento per l'onore che ti sei $Gguadagnato:guadagnata; con le tue azioni, ma credo che ti piaceranno lo stesso.$B$BSe hai altri Coin of Ancestry, sono a tua disposizione con un'ampia scelta di oggetti in cambio.",
  en_title = "Festival Dumplings",
}
T[8864] = {
  title = "Abiti festivi lunari",
  progress = "Ho una selezione di abiti che potrebbe interessarti. Abiti come questi si indossavano un tempo durante la Celebrazione della Luna, e la selezione che ho oggi è forse la più bella che abbia mai visto. Ognuno è fatto a mano con i materiali più pregiati e morbidi.$B$BIn cambio di qualche Coin of Ancestry, ti lascerò scegliere uno dei tre modelli che ho, da tenere per te. Ti va bene?",
  reward = "Molto bene, allora: accetto questi Coin of Ancestry. Prendi il tuo abito, con la mia benedizione. E goditi anche questi fuochi d'artificio in omaggio.$B$BCome hai onorato i tuoi anziani, così onori me con la tua sola presenza. Grazie, e che la tua Celebrazione della Luna sia gioiosa.",
  en_title = "Festive Lunar Dresses",
}
T[8865] = {
  title = "Completi pantalone festivi lunari",
  progress = "Ho il piacere di informarti che ho una bella selezione di completi pantalone festivi che possono diventare tuoi... ma solo in cambio di Coin of Ancestry. Se tieni alla moda, è proprio quello che cerchi! Ti assicuro che completi come questi non li troverai da nessun'altra parte.$B$BIn cambio di qualche Coin of Ancestry, ti lascerò scegliere uno dei tre modelli che ho, da tenere per te. Ti va bene?",
  reward = "Molto bene, allora: accetto questi Coin of Ancestry. Prendi il tuo completo pantalone, con la mia benedizione. E goditi anche questi fuochi d'artificio in omaggio.$B$BSe hai altri Coin of Ancestry da scambiare, torna a parlarmi. Offrirò vari oggetti per tutta la durata della Celebrazione della Luna.",
  en_title = "Festive Lunar Pant Suits",
}
T[8866] = {
  title = "Bronzebeard the Elder",
  reward = "È bello sapere che la gente di queste terre rende ancora omaggio alle razze antiche. Ti auguro ogni bene, $N, e ti offro questo pegno...",
  en_title = "Bronzebeard the Elder",
}
T[8867] = {
  title = "Lunar Fireworks",
  desc = "Ogni anno i druidi di Moonglade celebrano il grande trionfo della nostra città su un antico male.$B$BCelebriamo la saggezza dei nostri anziani, partecipiamo a banchetti magnifici e, naturalmente... lanciamo fuochi d'artificio!$B$BCon una piccola offerta puoi comprare dei razzi colorati dal nostro venditore. Prova a usare qualcuno dei lanciarazzi qui intorno, $N.",
  obj = "Lancia 8 Lunar Fireworks e 2 Cluster Fireworks, poi torna da una Lunar Festival Harbinger in una qualsiasi capitale.",
  progress = "Hai trovato i lanciarazzi, $N?",
  reward = "Ben fatto, $N.$B$BOra che sei $Gentrato:entrata; nello spirito della festa, perché non prendi questo invito ai festeggiamenti di Moonglade?$B$BÈ una celebrazione davvero piacevole, se hai tempo. Condividiamo cibo, bevande, storie e, naturalmente... altri fuochi d'artificio!$B$BApri l'invito stando dentro il cerchio di luce lunare più intensa e verrai $Gtrasportato:trasportata; a Moonglade.",
  en_title = "Lunar Fireworks",
  en_obj = "Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city.",
}
T[8870] = {
  title = "La Celebrazione della Luna",
  desc = "È arrivato quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare ai nostri festeggiamenti per la Celebrazione della Luna. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Può dirti di più sulla festa.",
  obj = "Parla con la Lunar Festival Harbinger nel Mystic Ward di Ironforge. Puoi parlare anche con le Lunar Festival Harbinger delle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti ai festeggiamenti?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
T[8871] = {
  title = "La Celebrazione della Luna",
  desc = "È arrivato quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare ai nostri festeggiamenti per la Celebrazione della Luna. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Può dirti di più sulla festa.",
  obj = "Parla con la Lunar Festival Harbinger nel Park District di Stormwind. Puoi parlare anche con le Lunar Festival Harbinger delle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti ai festeggiamenti?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger in the Park District in Stormwind.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
