T[8875] = {
  title = "La Celebrazione della Luna",
  desc = "È arrivato quel periodo dell'anno, $N! Il Cenarion Circle invita tutti gli abitanti di Azeroth a partecipare ai nostri festeggiamenti per la Celebrazione della Luna. Troverai la Lunar Festival Harbinger proprio in questa città, in un punto segnato da un cerchio benedetto di luce lunare. Può dirti di più sulla festa.",
  obj = "Parla con la Lunar Festival Harbinger all'Elder Rise di Thunder Bluff. Puoi parlare anche con le Lunar Festival Harbinger delle altre capitali.",
  reward = "$GBenvenuto:Benvenuta;, $N. Sei qui per unirti ai festeggiamenti?",
  en_title = "The Lunar Festival",
  en_obj = "Talk to the Lunar Festival Harbinger at the Elder Rise in Thunder Bluff.  You can also talk to Lunar Festival Harbingers in other capital cities.",
}
T[8876] = {
  title = "Razzi piccoli",
  progress = "Custodisco i segreti per creare i razzi della Celebrazione della Luna, e mi fa piacere condividere il mio sapere con chi è degno di onore.$B$BIn cambio di qualche Coin of Ancestry, posso offrirti la ricetta per fare un razzo piccolo...",
  reward = "Ah, molto bene. Ecco le tue ricette, $N, e che Elune ti benedica.",
  en_title = "Small Rockets",
}
T[8883] = {
  title = "Valadar Starsong",
  desc = "Ora che hai la tua Lunar Festival Invitation, puoi raggiungere Moonglade! Lì troverai molti festeggianti, e nel villaggio di Nighthaven Valadar Starsong e sua sorella Fariel aspettano chi desidera partecipare alla celebrazione.$B$BRaggiungi Moonglade attraverso la luce lunare più intensa e parla con Valadar Starsong: scopri quali premi potresti vincere durante la festa!",
  obj = "Usa la tua Lunar Festival Invitation nella luce lunare per raggiungere Moonglade. Quando arrivi, parla con Valadar Starsong a Nighthaven.",
  reward = "$N, $Gbenvenuto:benvenuta; a Nighthaven, che ospita la Celebrazione della Luna! Anche se di solito il nostro villaggio è remoto e isolato dai popoli di Azeroth, in questo periodo di festa apriamo a tutti le braccia e il cuore.$B$BGoditi la visita, $N, e torna a parlare con me o con mia sorella quando sarai $Gpronto:pronta;.",
  en_title = "Valadar Starsong",
  en_obj = "Use your Lunar Festival Invitation in the moonlight to travel to Moonglade. Speak with Valadar Starsong in Nighthaven when you arrive.",
}
T[8897] = {
  title = "Carissima Colara,",
  desc = "Devo fare la guardia qui al cancello, ma sono sempre in pensiero per la mia amata, Colara. Riesco a vederla solo per qualche ora, se mi va bene, e poi... guardami. Ho la paga di un ufficiale di basso grado e potrei essere chiamato al fronte da un giorno all'altro.$B$BE se si dimenticasse di me? In città ci sono tanti uomini. Tanti uomini ricchi.$B$BComunque, ho buttato giù qualcosa... niente di che, ma se potessi portarglielo tu, sarebbe fantastico.",
  obj = "Consegna Lieutenant Heldric's Carefully Penned Note a Colara Dean, fuori dalla banca di Stormwind.",
  progress = "$GCiao, bel ragazzo. Posso aiutarti in qualcosa?:Oh, cielo! Posso aiutarti in qualcosa?;",
  reward = "Oh, che dolce! È la prima volta che mi manda qualcosa. Pensi che stia facendo sul serio?$B$BColara Heldric? Non suona male. Oh, ma sto correndo troppo. Grazie.",
  en_title = "Dearest Colara,",
  en_obj = "Deliver Lieutenant Heldric's Carefully Penned Note to Colara Dean outside the bank in Stormwind.",
}
T[8898] = {
  title = "Carissima Colara,",
  desc = "Ho conosciuto una ragazza a Stormwind, l'ultima volta che ci sono stato per affari della banca. Mi ha rubato il cuore. E adesso non riesco a smettere di pensare a lei! Vorrei mandarle questo messaggio: l'ho riscritto dodici volte!$B$BIn questo periodo la posta è così piena, e voglio essere sicuro che arrivi.$B$BSe vai da quelle parti, potresti aiutarmi?",
  obj = "Consegna la Creased Letter a Colara Dean, fuori dalla banca di Stormwind.",
  progress = "Ciao, bel ragazzo. Posso aiutarti in qualcosa?",
  reward = "Tormek? Oh sì, me lo ricordo. Aveva una gran bella barba, e sotto un bel sorriso.$B$BAh, non posso credere che si sia ricordato di me!",
  en_title = "Dearest Colara,",
  en_obj = "Deliver the Creased Letter to Colara Dean outside the bank in Stormwind.",
}
T[8899] = {
  title = "Carissima Colara,",
  desc = "Come descrivere la sua bellezza? Migliaia di anni di parole, e non trovo le mie.$B$BQuesti mortali confondono la mente e ci riducono a sciocchi balbettanti.$B$BHo fissato queste parole troppo a lungo. Non riesco a spremerne un significato più eloquente. No, deve riceverla adesso, o qualche altro corteggiatore le ruberà di sicuro lo sguardo.",
  obj = "Consegna l'Immaculate Letter a Colara Dean, fuori dalla banca di Stormwind.",
  progress = "Ciao, bel ragazzo. Posso aiutarti in qualcosa?",
  reward = "Non avevo mai ricevuto niente del genere. Che bello!",
  en_title = "Dearest Colara,",
  en_obj = "Deliver the Immaculate Letter to Colara Dean outside the bank in Stormwind.",
}
T[8900] = {
  title = "Carissima Elenia,",
  desc = "Era così triste. L'ho capito quando sono riuscito a guardare oltre la sua condizione. Voglio dire, sembrava triste... non lo saresti anche tu?$B$BMa dopo averle parlato, c'era un legame. Non pensavo che qualcuno potesse capire quello che pensavo, ma lei ci riusciva.$B$BQuando l'ho detto agli altri, mi hanno riso in faccia, e così non le ho più parlato. Ma mi manca. Puoi portarle questa lettera per me? Voglio essere sicuro che arrivi nelle sue mani.",
  obj = "Consegna la Slightly Creased Note a Elenia Haydon, vicino alla banca dell'Undercity.",
  progress = "Oh, e a cosa devo questo piacere?",
  reward = "Non ti aspetteresti tanta eloquenza da un orco. Certo, finora non abbiamo mai avuto davvero l'occasione di conoscerli. Grazie di avermela portata.",
  en_title = "Dearest Elenia,",
  en_obj = "Deliver the Slightly Creased Note to Elenia Haydon near the bank in the Undercity.",
}
T[8901] = {
  title = "Carissima Elenia,",
  desc = "Hai mai conosciuto l'amore, giovane? Per me era una cosa sconosciuta fino a poco tempo fa, quando ho incontrato una ragazza dell'Undercity, Elenia. È già raro che uno della mia specie guardi al di fuori della propria gente, figuriamoci a una Reietta.$B$BMa ora il pensiero di lei mi occupa la mente giorno e notte.$B$BSe puoi, potresti portarle questa lettera? Vorrei che venisse qui a Mulgore. Spero che dirà di sì.",
  obj = "Consegna la Carefully Written Letter a Elenia Haydon, vicino alla banca dell'Undercity.",
  progress = "Oh, e a cosa devo questo piacere?",
  reward = "Che parole gentili mi scrive Temma. Ma per quanto le sue parole mi commuovano, non posso prendere in considerazione l'amore di un tauren. Nei pensieri, nel corpo e nella mente siamo troppo diversi.$B$BMeno male che non devo ricevere di persona questi suoi pensieri. Non sopporterei di spezzargli il cuore.",
  en_title = "Dearest Elenia,",
  en_obj = "Deliver the Carefully Written Letter to Elenia Haydon near the bank in the Undercity.",
}
T[8902] = {
  title = "Carissima Elenia,",
  desc = "Una vita fa ero promesso sposo di Elenia, la mia fidanzatina d'infanzia. Erano anni che non pensavo a lei, ma ultimamente occupa spesso i miei pensieri.$B$BForse, nonostante tutto quello che è successo, nelle nostre vite può esserci ancora un po' di spazio per il nostro amore.$B$BSono sicuro che anche lei sarà cambiata. Puoi consegnarle questa lettera per me? Sono troppo nervoso per dargliela di persona.",
  obj = "Consegna la Lovingly Composed Letter a Elenia Haydon, vicino alla banca dell'Undercity.",
  progress = "Oh, e a cosa devo questo piacere?",
  reward = "Questo mi riporta alla mente ricordi di una vita fa, $N. Elenia Tor. Sarebbe stato il mio nome, sai. Avremmo fatto una bellissima cerimonia sulle rive del lago. Quando lui si fosse ritirato, avremmo trovato una fattoria dove passare la vecchiaia.$B$BSogni semplici, allora.$B$BMa se mi vedesse adesso, dubito che vedrebbe in me Elenia. Solo carne fredda e un cuore morto...",
  en_title = "Dearest Elenia,",
  en_obj = "Deliver the Lovingly Composed Letter to Elenia Haydon near the bank in the Undercity.",
}
T[8903] = {
  title = "Amore pericoloso",
  desc = "C'è qualcosa di innaturale in questa epidemia d'amore. Non è decoroso, è uno spettacolo indecente e, nel peggiore dei casi, potrebbe essere una minaccia per la sicurezza stessa dell'Alleanza.$B$BPensaci: e se anche le guardie fossero state colpite da questo strano male? Bisogna fare qualcosa.$B$BVa' da una delle guardie qui a Stormwind e vedi se anche loro sono state prese da questa follia.",
  obj = "Procurati una Stormwind Guard's Card e riportala ad Aristan Mottar, a Stormwind.",
  progress = "Avevo ragione a preoccuparmi? Le guardie sono state colpite da questo mal d'amore?",
  reward = "Allora è vero. È incredibile. Come può essere successo? Lasciami pensare un momento. Dev'esserci una ragione dietro tutto questo.",
  en_title = "Dangerous Love",
  en_obj = "Get a Stormwind Guard's Card and return it to Aristan Mottar in Stormwind.",
}
T[8904] = {
  title = "Amore pericoloso",
  desc = "C'è qualcosa di innaturale in questa epidemia d'amore. È disgustosa e, abbassando le nostre difese, potrebbe essere una minaccia per tutti noi.$B$BÈ già abbastanza grave che così tanti della nostra gente siano presi da questo comportamento ridicolo. Ma credo che si sia diffusa persino ai nostri guardiani, che dovrebbero essere immuni a cose del genere.$B$BTrova uno dei nostri guardiani e vedi se anche loro sono stati presi da questa follia.",
  obj = "Procurati una Guardian's Moldy Card e portala a Fenstad Argyle, nell'Undercity.",
  progress = "Avevo ragione a preoccuparmi? Quegli idioti dei nostri guardiani hanno ceduto?",
  reward = "Allora è vero. È incredibile. Come può essere successo? Lasciami pensare un momento. Dev'esserci una ragione dietro tutto questo.",
  en_title = "Dangerous Love",
  en_obj = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.",
}
T[8979] = {
  title = "L'intuizione di Fenstad",
  desc = "Credo di sapere la causa di questo comportamento recente. Hai sentito il nuovo profumo nell'aria, sopra la puzza dei canali? Le nuove acque di colonia e i profumi che sono diventati di moda?$B$BIl nostro modo di pensare è stato annebbiato da qualche alchimia immonda.$B$BC'è un solo modo per esserne sicuri: porta una bottiglia di acqua di colonia e una di profumo alla mia amica, Apothecary Zinge. La Royal Apothecary Society scoprirà la verità.$B$BTi rimborserò l'acquisto quando tornerai.",
  obj = "Porta 1 Cologne Bottle e 1 Perfume Bottle ad Apothecary Zinge, nell'Apothecarium dell'Undercity.",
  progress = "Come posso servirti?",
  reward = "Un'altra delle fissazioni di Fenstad, vedo. Crede forse che la Royal Apothecary Society non abbia niente di meglio da fare che portare avanti le sue piccole indagini?$B$BE va bene, lo accontenterò ancora una volta.",
  en_title = "Fenstad's Hunch",
  en_obj = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Apothecary Zinge in the Undercity's Apothecarium.",
}
T[8980] = {
  title = "La valutazione di Zinge",
  desc = "Questo non me l'aspettavo. Sembra che Fenstad, dopotutto, abbia visto giusto. Ho trovato tracce di sostanze usate nelle pozioni per il controllo della mente.$B$BNon è insolito che i profumi ne contengano un po', ma alcuni degli ingredienti che ho trovato... Questa è alchimia seria, all'altezza di un membro della Royal Apothecary Society.",
  obj = "Torna da Fenstad Argyle, fuori dalla banca dell'Undercity.",
  reward = "Allora avevo ragione. Non dobbiamo perdere tempo. Dobbiamo scoprire da dove vengono queste fragranze corrotte.$B$BEcco, per rimborsarti l'acquisto dell'acqua di colonia e del profumo.",
  en_title = "Zinge's Assessment",
  en_obj = "Return to Fenstad Argyle outside the bank in the Undercity.",
}
T[8981] = {
  title = "Fare regali",
  progress = "Sei $Gvenuto:venuta; a consegnare un regalo d'amore e d'affetto al tuo capo preferito?",
  reward = "Magnifico! Magnifico! Lo aggiungerò alla pila degli altri regali.$B$BNon me ne aspettavo così tanti! Devi proprio voler bene ai tuoi capi.$B$BOra, fammene aggiungere un altro al conteggio...",
  en_title = "Gift Giving",
}
T[8982] = {
  title = "Risalire alla fonte",
  desc = "Dobbiamo scoprire chi è il fornitore. Ho notato che Apothecary Katrina aveva una bottiglia di quel profumo infilata nella borsa. Mi ha detto di averla comprata da Norman, il locandiere.",
  obj = "Parla con Innkeeper Norman, nell'Undercity.",
  reward = "Ah sì, ho ricevuto da poco una fornitura di profumo e acqua di colonia. Non so quanto riuscirò a tenerla sugli scaffali: sembra che nessuno ne abbia mai abbastanza.$B$BSe vuoi il mio parere, non capisco tutto questo clamore.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Innkeeper Norman in the Undercity.",
}
T[8983] = {
  title = "Risalire alla fonte",
  desc = "C'è qualcosa che non va nella mia merce? Be', non ho mai visto così tanta gente volere qualcosa così disperatamente.$B$BHo comprato la mia scorta da una mercante di nome Mara Rennick. È nuova in città.$B$BHa detto che doveva consegnare della merce al sarto del Mage Quarter.",
  obj = "Parla con Mara Rennick, alla bottega del sarto nel Mage Quarter dell'Undercity.",
  reward = "Purtroppo ho venduto tutta la mia scorta di profumo e acqua di colonia a Norman, il locandiere. Se ne vuoi un po', dovresti parlare con lui, sempre che gliene sia rimasta.$B$BPerò non dovresti perdere tempo. Credo che troverai $Gl'acqua di colonia:il profumo; irresistibile.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Mara Rennick at the tailor's shop in the Undercity's Mage Quarter.",
}
T[8984] = {
  title = "La fonte svelata",
  desc = "Senti, le azioni di uno speziale rinnegato non mi riguardano. Se sta sabotando i nostri sforzi, lascia che sia io la prima a indicarti la strada giusta.$B$BSe è innocente, allora non ha niente da nascondere, giusto?$B$BHo comprato la merce da Apothecary Staffron Lerent. Lavora in un posto isolato oltre il Ravenholdt Manor, sulle colline sopra Hillsbrad. A dire il vero, mi è sembrato un po' strano.",
  obj = "Trova Apothecary Staffron Lerent nelle Hillsbrad Foothills, oltre il Ravenholdt Manor.",
  reward = "Sì, quelle fragranze le ho fatte io. Un profumo meraviglioso, non trovi? Irresistibile.$B$BUna volta che i guerrieri dell'Alleanza e dell'Orda saranno presi da questi sentimenti d'amore, non avranno la forza di fermare l'ascesa del Concilio dell'Ombra.$B$BSaranno indeboliti, impreparati. Preoccupandosi per i loro cari, perderanno la loro prontezza.$B$BLa soluzione era così semplice. Perché ci ho messo tanto a trovarla? Il punto debole di tutti è il cuore. E non c'è niente che tu possa fare per fermare l'inevitabile.",
  en_title = "The Source Revealed",
  en_obj = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills past Ravenholdt Manor.",
}
T[8993] = {
  title = "Fare regali",
  progress = "Sei $Gvenuto:venuta; a consegnare un regalo d'amore e d'affetto al tuo capo preferito?",
  reward = "Magnifico! Magnifico! Lo aggiungerò alla pila degli altri regali.$B$BNon me ne aspettavo così tanti! Devi proprio voler bene ai tuoi capi.$B$BOra, fammene aggiungere un altro al conteggio...",
  en_title = "Gift Giving",
}
T[9024] = {
  title = "L'intuizione di Aristan",
  desc = "Ci sono! Hai sentito il nuovo profumo nell'aria? Le nuove acque di colonia e i profumi che sono diventati di moda? Le nostre guardie non trascurerebbero i loro doveri così facilmente.$B$BA meno che il loro modo di pensare non sia stato annebbiato da qualche alchimia immonda.$B$BC'è un solo modo per esserne sicuri: porta una bottiglia di acqua di colonia e una di profumo a Morgan Pestle, e riferiscigli i miei sospetti. Ti rimborserò l'acquisto quando tornerai.",
  obj = "Porta 1 Cologne Bottle e 1 Perfume Bottle a Morgan Pestle, nel Trade District di Stormwind.",
  progress = "Posso aiutarti in qualcosa?",
  reward = "Capisco le preoccupazioni di Aristan, ma credo davvero che stia esagerando. Lascia che i giovani, uomini e donne, facciano come vogliono. Credo che Aristan abbia dimenticato cosa vuol dire essere giovani e innamorati.$B$BMa sarà meglio non dirglielo. Lo accontenteremo.",
  en_title = "Aristan's Hunch",
  en_obj = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Morgan Pestle in the Trade District of Stormwind.",
}
T[9025] = {
  title = "La scoperta di Morgan",
  desc = "Ma guarda un po'. Sembra che Aristan, dopotutto, abbia visto giusto. Ho trovato tracce di sostanze usate nei filtri d'amore e in subdole pozioni che alterano la mente.$B$BNon è insolito che i profumi ne contengano un po', ma alcuni degli ingredienti che ho trovato... Hanno un odore strano.",
  obj = "Torna da Aristan Mottar, fuori dalla banca nel Trade District di Stormwind.",
  reward = "Anche se pensavo che sarebbe andata così, scoprire che i miei sospetti erano fondati è comunque inquietante. Dobbiamo valutare con attenzione la nostra prossima mossa.$B$BEcco, per rimborsarti l'acquisto dell'acqua di colonia e del profumo.",
  en_title = "Morgan's Discovery",
  en_obj = "Return to Aristan Mottar outside the bank in Stormwind's Trade District.",
}
T[9026] = {
  title = "Risalire alla fonte",
  desc = "Dobbiamo trovare la fonte. Ho visto molta più gente del solito, guardie comprese, entrare e uscire dal Gilded Rose. Parla con Allison. Se è lei a venderli, può dirti da dove vengono.",
  obj = "Parla con Innkeeper Allison al Gilded Rose, nel Trade District di Stormwind.",
  reward = "Oh sì, ho ricevuto da poco il profumo e l'acqua di colonia. Si vendono così bene che non so quanto riuscirò a tenerli sugli scaffali.$B$BSe vuoi il mio parere, è un po' noioso. Tutti con lo stesso odore? Il profumo è ottimo, ma comunque.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Innkeeper Allison at The Gilded Rose in Stormwind's Trade District.",
}
T[9027] = {
  title = "Risalire alla fonte",
  desc = "C'è qualcosa di strano nell'acqua di colonia? È possibile. Non ho mai visto così tanta gente cercare un prodotto in questo modo.$B$BSenti, se c'è qualcosa che non va, voglio saperlo anch'io. Ho comprato la mia scorta da un mercante di nome Evert Sorisam. È nuovo in città.$B$BHa detto che aveva della merce da consegnare a The Finest Thread.",
  obj = "Parla con Evert Sorisam a The Finest Thread, lungo i Canals di Stormwind.",
  reward = "Sì, certo. Quelle fragranze sono gli articoli più richiesti della stagione. Sarai la quinta o sesta persona che me lo chiede nell'ultima ora.$B$BPurtroppo ho esaurito tutte le scorte. Se ne vuoi un po', dovresti parlare con Allison, la locandiera del Gilded Rose.$B$BPerò non dovresti perdere tempo. Credo che troverai $Gl'acqua di colonia:il profumo; irresistibile.",
  en_title = "Tracing the Source",
  en_obj = "Speak with Evert Sorisam at The Finest Thread along Stormwind's Canals.",
}
T[9028] = {
  title = "La fonte svelata",
  desc = "Cosa? Tradimento? No, no. Ti assicuro che le mie intenzioni sono del tutto innocue.$B$BÈ così sbagliato aiutare chi vuole alleviare il doloroso rituale del corteggiamento? Andiamo, non è un crimine.$B$BE per dimostrare che non ho cattive intenzioni, ti dirò persino il mio fornitore.$B$BMe li ha spediti un certo Staffron Lerent, uno speziale di qualche tipo. Non ci ho mai parlato.$B$BIl nostro intermediario goblin ha detto che lavorava sulle colline sopra Hillsbrad, oltre quel misterioso Ravenholdt Manor. Ti auguro buona fortuna nel trovarlo.",
  obj = "Trova Apothecary Staffron Lerent nelle Hillsbrad Foothills, dietro il Ravenholdt Manor.",
  reward = "Sì, quelle fragranze le ho fatte io. Un profumo meraviglioso, non trovi? Irresistibile.$B$BUna volta che i guerrieri dell'Alleanza e dell'Orda saranno presi da questi sentimenti d'amore, non avranno la forza di fermare l'ascesa del Concilio dell'Ombra.$B$BSaranno indeboliti, impreparati. Preoccupandosi per i loro cari, perderanno la loro prontezza.$B$BLa soluzione era così semplice. Perché ci ho messo tanto a trovarla? Il punto debole di tutti è il cuore. E non c'è niente che tu possa fare per fermare l'inevitabile.",
  en_title = "The Source Revealed",
  en_obj = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills behind Ravenholdt Manor.",
}
T[9029] = {
  title = "Un Bubbling Cauldron",
  reward = "Un profumo gradevole si leva dal calderone.",
  en_title = "A Bubbling Cauldron",
}
T[9247] = {
  title = "La chiamata del Keeper",
  desc = "$N,$B$BIn passato hai servito gli interessi dell'Argent Dawn, sempre al meglio delle tue capacità. Ora, ancora una volta, lanciamo la chiamata alle armi nel momento del bisogno più grande.$B$B$N, ti preghiamo di presentarti al Keeper of the Rolls, alla Light's Hope Chapel negli Eastern Plaguelands, se sei $Gdisposto:disposta; ad aiutarci ancora una volta.",
  obj = "Porta la Letter from the Keeper of the Rolls a lui, alla Light's Hope Chapel negli Eastern Plaguelands.",
  en_title = "The Keeper's Call",
  en_obj = "Take the Letter from the Keeper of the Rolls to him at Light's Hope Chapel in the Eastern Plaguelands.",
}
T[9259] = {
  title = "Traditore dei Bloodsail",
  progress = "Quel cane rognoso di Revilgaz ha offerto il perdono a tutti gli ex Bloodsail disposti a voltare le spalle al loro capitano! Quel succhiasentina mi ha chiesto di far fuori i miei vecchi compagni e di riportargli le loro bandane come prova.$B$BNon ho il cuore di farlo, e non lo chiederò nemmeno a te. Portami un po' di Silk Cloth e di Red Dye e farò delle copie credibili. Dirò al barone che hai cambiato bandiera, ma sappi che... ai Bloodsail non piacerà per niente!",
  reward = "Osserviamo un minuto di silenzio per i nostri compagni caduti, $N.$B$B<Bloodsail Traitor ti sorride e ti fa l'occhiolino.>$B$BEssere un traditore è una cosa, ma ammazzare i propri compari... quello sì che sarebbe davvero spregevole, eh!",
  en_title = "Traitor to the Bloodsail",
}
T[9260] = {
  title = "Indaga sul Flagello di Stormwind",
  desc = "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere Stormwind da questi invasori maledetti?$B $BFuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropolis là in alto. Hanno un significato, non ho dubbi, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai risultati delle tue indagini, e ti ricompenserò. Va'!",
  obj = "Raccogli tre Dim Necrotic Stone dal Flagello fuori da Stormwind e indaga sui cerchi runici luminosi vicino al suo accampamento.",
  progress = "Hai già indagato sull'invasione? Non c'è tempo da perdere!",
  reward = "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne $Guscito integro e sano:uscita integra e sana;. L'Argent Dawn apprezza i tuoi servigi.",
  en_title = "Investigate the Scourge of Stormwind",
  en_obj = "Collect three Dim Necrotic Stones from the Scourge outside Stormwind and investigate the glowing runic circles near their encampment.",
}
